window.HSC={"sections":[{"n":"1","title":{"uk":"Загальні положення","ru":"Общие положения"}},{"n":"2","title":{"uk":"Обов'язки і права водіїв механічних транспортних засобів","ru":"Обязанности и права водителей механических транспортных средств"}},{"n":"3","title":{"uk":"Рух транспортних засобів із спеціальними сигналами","ru":"Движение транспортных средств со специальными сигналами"}},{"n":"4","title":{"uk":"Обов'язки і права пішоходів","ru":"Обязанности и права пешеходов"}},{"n":"5","title":{"uk":"Обов'язки і права пасажирів","ru":"Обязанности и права пассажиров"}},{"n":"6","title":{"uk":"Вимоги до велосипедистів","ru":"Требования к велосипедистам"}},{"n":"7","title":{"uk":"Вимоги до осіб, які керують гужовим транспортом, і погоничів тварин","ru":"Требования к лицам, управляющим гужевым транспортом, и погонщикам животных"}},{"n":"8.1","title":{"uk":"Регулювання дорожнього руху (регульовані перехрестя)","ru":"Регулирование дорожного движения (регулируемые перекрёстки)"}},{"n":"8.2","title":{"uk":"Регулювання дорожнього руху (нерегульовані перехрестя)","ru":"Регулирование дорожного движения (нерегулируемые перекрёстки)"}},{"n":"9","title":{"uk":"Попереджувальні сигнали","ru":"Предупредительные сигналы"}},{"n":"10","title":{"uk":"Початок руху та зміна його напрямку","ru":"Начало движения и изменение его направления"}},{"n":"11","title":{"uk":"Розташування транспортних засобів на дорозі","ru":"Расположение транспортных средств на дороге"}},{"n":"12","title":{"uk":"Швидкість руху","ru":"Скорость движения"}},{"n":"13","title":{"uk":"Дистанція, інтервал, зустрічний роз'їзд","ru":"Дистанция, интервал, встречный разъезд"}},{"n":"14","title":{"uk":"Обгін","ru":"Обгон"}},{"n":"15","title":{"uk":"Зупинка і стоянка","ru":"Остановка и стоянка"}},{"n":"16.1","title":{"uk":"Проїзд перехресть (регульовані перехрестя)","ru":"Проезд перекрёстков (регулируемые перекрёстки)"}},{"n":"16.2","title":{"uk":"Проїзд перехресть (нерегульовані перехрестя)","ru":"Проезд перекрёстков (нерегулируемые перекрёстки)"}},{"n":"17","title":{"uk":"Переваги маршрутних транспортних засобів","ru":"Преимущества маршрутных транспортных средств"}},{"n":"18","title":{"uk":"Проїзд пішохідних переходів і зупинок транспортних засобів","ru":"Проезд пешеходных переходов и остановок транспортных средств"}},{"n":"19","title":{"uk":"Користування зовнішніми світловими приладами","ru":"Пользование внешними световыми приборами"}},{"n":"20","title":{"uk":"Рух через залізничні переїзди","ru":"Движение через железнодорожные переезды"}},{"n":"21","title":{"uk":"Перевезення пасажирів","ru":"Перевозка пассажиров"}},{"n":"22","title":{"uk":"Перевезення вантажу","ru":"Перевозка груза"}},{"n":"23","title":{"uk":"Буксирування та експлуатація транспортних составів","ru":"Буксировка и эксплуатация транспортных составов"}},{"n":"24","title":{"uk":"Навчальна їзда","ru":"Учебная езда"}},{"n":"25","title":{"uk":"Рух транспортних засобів у колонах","ru":"Движение транспортных средств в колоннах"}},{"n":"26","title":{"uk":"Рух у житловій та пішохідній зоні","ru":"Движение в жилой и пешеходной зоне"}},{"n":"27","title":{"uk":"Рух по автомагістралях і дорогах для автомобілів","ru":"Движение по автомагистралям и дорогам для автомобилей"}},{"n":"28","title":{"uk":"Рух по гірських дорогах і на крутих спусках","ru":"Движение по горным дорогам и на крутых спусках"}},{"n":"29","title":{"uk":"Міжнародний рух","ru":"Международное движение"}},{"n":"30","title":{"uk":"Номерні, розпізнавальні знаки, написи і позначення","ru":"Номерные, опознавательные знаки, надписи и обозначения"}},{"n":"31","title":{"uk":"Технічний стан транспортних засобів та їх обладнання","ru":"Техническое состояние транспортных средств и их оборудование"}},{"n":"32","title":{"uk":"Окремі питання дорожнього руху, що потребують узгодження","ru":"Отдельные вопросы дорожного движения, требующие согласования"}},{"n":"33","title":{"uk":"Дорожні знаки","ru":"Дорожные знаки"}},{"n":"34","title":{"uk":"Дорожня розмітка","ru":"Дорожная разметка"}},{"n":"35","title":{"uk":"Основи безпечного водіння","ru":"Основы безопасного вождения"}},{"n":"36","title":{"uk":"Основи права в галузі дорожнього руху","ru":"Основы права в области дорожного движения"}},{"n":"37","title":{"uk":"Надання домедичної допомоги","ru":"Оказание домедицинской помощи"}},{"n":"38","title":{"uk":"Етика водіння, культура та відпочинок водія","ru":"Этика вождения, культура и отдых водителя"}},{"n":"39","title":{"uk":"Європротокол","ru":"Европротокол"}},{"n":"44","title":{"uk":"Додатково для B1, B: загальні питання","ru":"Дополнительно для B1, B: общие вопросы"}},{"n":"45","title":{"uk":"Додатково для B1, B: будова і терміни","ru":"Дополнительно для B1, B: устройство и термины"}},{"n":"46","title":{"uk":"Додатково для B1, B: юридична відповідальність","ru":"Дополнительно для B1, B: юридическая ответственность"}},{"n":"47","title":{"uk":"Додатково для B1, B: безпека","ru":"Дополнительно для B1, B: безопасность"}}],"list":[{"id":"h1-1","t":"h1","num":"1.1","q":{"uk":"Трамвайна колія – елемент дороги, призначений для руху рейкових транспортних засобів, який обмежується по ширині:","ru":"Трамвайные пути — элемент дороги, предназначенный для движения рельсовых транспортных средств, который ограничивается по ширине:"},"a":[{"uk":"Спеціально виділеним вимощенням трамвайної лінії.","ru":"Специально выделенным мощением трамвайной линии.","w":{"uk":"Це лише одна з двох ознак: межу колії може задавати й дорожня розмітка.","ru":"Это лишь один из двух признаков: границу путей может задавать и дорожная разметка."}},{"uk":"Дорожньої розміткою.","ru":"Дорожной разметкой.","w":{"uk":"Це лише одна з двох ознак: колію може обмежувати й спеціально виділене вимощення.","ru":"Это лишь один из двух признаков: пути может ограничивать и специально выделенное мощение."}},{"uk":"Відповіді, зазначені в пунктах 1 та 2.","ru":"Ответы, указанные в пунктах 1 и 2."}],"c":2,"e":{"uk":"За визначенням у {p:1.10}, трамвайна колія обмежується по ширині спеціально виділеним вимощенням трамвайної лінії **або** дорожньою розміткою — тому правильні обидва варіанти.","ru":"По определению в {p:1.10}, трамвайные пути ограничиваются по ширине специально выделенным мощением трамвайной линии **или** дорожной разметкой — поэтому верны оба варианта."},"ref":["1.10"],"pic":["img/hsc/1-1-1.jpg"]},{"id":"h1-2","t":"h1","num":"1.2","q":{"uk":"Елемент дороги, призначений для руху рейкових транспортних засобів, який обмежується по ширині спеціально виділеним вимощенням трамвайної лінії або дорожньою розміткою це:","ru":"Элемент дороги, предназначенный для движения рельсовых транспортных средств, который ограничивается по ширине специально выделенным мощением трамвайной линии или дорожной разметкой, — это:"},"a":[{"uk":"Трамвайна колія.","ru":"Трамвайные пути."},{"uk":"Удосконалене покриття.","ru":"Усовершенствованное покрытие.","w":{"uk":"Удосконалене покриття — це вид покриття дороги (асфальтобетон, бруківка тощо), а не елемент дороги для руху трамваїв.","ru":"Усовершенствованное покрытие — это вид покрытия дороги (асфальтобетон, брусчатка и т. п.), а не элемент дороги для движения трамваев."}},{"uk":"Смуга руху.","ru":"Полоса движения.","w":{"uk":"Смуга руху призначена для нерейкових транспортних засобів і має ширину щонайменше 2,75 м.","ru":"Полоса движения предназначена для нерельсовых транспортных средств и имеет ширину не менее 2,75 м."}}],"c":0,"e":{"uk":"Це дослівне визначення **трамвайної колії** з {p:1.10}: елемент дороги для рейкових транспортних засобів, обмежений по ширині вимощенням трамвайної лінії або розміткою.","ru":"Это дословное определение **трамвайных путей** из {p:1.10}: элемент дороги для рельсовых транспортных средств, ограниченный по ширине мощением трамвайной линии или разметкой."},"ref":["1.10"]},{"id":"h1-3","t":"h1","num":"1.3","q":{"uk":"По якому з наведених елементів дороги дозволено рух нерейкових транспортних засобів?","ru":"По какому из перечисленных элементов дороги разрешено движение нерельсовых транспортных средств?"},"a":[{"uk":"По тротуару.","ru":"По тротуару.","w":{"uk":"Тротуар призначений для руху пішоходів, а не транспортних засобів.","ru":"Тротуар предназначен для движения пешеходов, а не транспортных средств."}},{"uk":"По трамвайній колії.","ru":"По трамвайным путям.","w":{"uk":"Неповна відповідь: нерейкові транспортні засоби рухаються насамперед проїзною частиною.","ru":"Неполный ответ: нерельсовые транспортные средства движутся прежде всего по проезжей части."}},{"uk":"По проїзній частині.","ru":"По проезжей части.","w":{"uk":"Неповна відповідь: на умовах {p:11.8} нерейкові транспортні засоби можуть рухатися й трамвайною колією.","ru":"Неполный ответ: на условиях {p:11.8} нерельсовые транспортные средства могут двигаться и по трамвайным путям."}},{"uk":"Відповіді 2 та 3.","ru":"Ответы 2 и 3."}],"c":3,"e":{"uk":"Проїзна частина призначена саме для нерейкових транспортних засобів, а по трамвайній колії їхній рух допускається за правилами розділу 11 ({p:11.8}) — тому правильні обидва варіанти.","ru":"Проезжая часть предназначена именно для нерельсовых транспортных средств, а по трамвайным путям их движение допускается по правилам раздела 11 ({p:11.8}) — поэтому верны оба варианта."},"ref":["1.10","11.8"]},{"id":"h1-4","t":"h1","num":"1.4","q":{"uk":"Чи належить до проїзної частини велосипедна смуга?","ru":"Относится ли к проезжей части велосипедная полоса?"},"a":[{"uk":"Так, належить.","ru":"Да, относится."},{"uk":"Ні, не належить.","ru":"Нет, не относится.","w":{"uk":"Поза проїзною частиною розташована велосипедна доріжка; велосипедна ж смуга виділена саме на проїзній частині.","ru":"За пределами проезжей части расположена велосипедная дорожка; велосипедная же полоса выделена именно на проезжей части."}}],"c":0,"e":{"uk":"За {p:1.10} велосипедна смуга — це смуга для руху на велосипедах **у межах проїзної частини**, позначена знаком {s:5.88} і розміткою.","ru":"Согласно {p:1.10} велосипедная полоса — это полоса для движения на велосипедах **в пределах проезжей части**, обозначенная знаком {s:5.88} и разметкой."},"ref":["1.10"]},{"id":"h1-5","t":"h1","num":"1.5","q":{"uk":"Для руху яких транспортних засобів призначена проїзна частина?","ru":"Для движения каких транспортных средств предназначена проезжая часть?"},"a":[{"uk":"Нерейкових транспортних засобів.","ru":"Нерельсовых транспортных средств."},{"uk":"Рейкових транспортних засобів.","ru":"Рельсовых транспортных средств.","w":{"uk":"Для рейкових транспортних засобів (трамваїв) призначена трамвайна колія, а не проїзна частина.","ru":"Для рельсовых транспортных средств (трамваев) предназначены трамвайные пути, а не проезжая часть."}},{"uk":"Нерейкових та рейкових транспортних засобів.","ru":"Нерельсовых и рельсовых транспортных средств.","w":{"uk":"Визначення проїзної частини згадує лише нерейкові транспортні засоби; рейкові рухаються трамвайною колією.","ru":"Определение проезжей части упоминает только нерельсовые транспортные средства; рельсовые движутся по трамвайным путям."}}],"c":0,"e":{"uk":"За {p:1.10} проїзна частина — елемент дороги, призначений для руху **нерейкових** транспортних засобів.","ru":"Согласно {p:1.10} проезжая часть — элемент дороги, предназначенный для движения **нерельсовых** транспортных средств."},"ref":["1.10"]},{"id":"h1-6","t":"h1","num":"1.6","q":{"uk":"Що означає вимога дати дорогу?","ru":"Что означает требование уступить дорогу?"},"a":[{"uk":"Вимога до учасника дорожнього руху не продовжувати або не відновлювати рух, якщо це може примусити інших учасників дорожнього руху, які мають перевагу, змінити напрямок руху або швидкість.","ru":"Требование к участнику дорожного движения не продолжать или не возобновлять движение, если это может вынудить других участников дорожного движения, имеющих преимущество, изменить направление движения или скорость.","w":{"uk":"Це лише частина визначення: вимога дати дорогу також забороняє маневри.","ru":"Это лишь часть определения: требование уступить дорогу также запрещает манёвры."}},{"uk":"Вимога до учасника дорожнього руху не здійснювати будь-яких маневрів (за винятком вимоги звільнити займану смугу руху), якщо це може примусити інших учасників дорожнього руху, які мають перевагу, змінити напрямок руху або швидкість.","ru":"Требование к участнику дорожного движения не осуществлять каких-либо манёвров (за исключением требования освободить занимаемую полосу движения), если это может вынудить других участников дорожного движения, имеющих преимущество, изменить направление движения или скорость.","w":{"uk":"Це лише частина визначення: вимога дати дорогу також забороняє продовжувати чи відновлювати рух.","ru":"Это лишь часть определения: требование уступить дорогу также запрещает продолжать или возобновлять движение."}},{"uk":"Відповідь 1 і 2.","ru":"Ответ 1 и 2."}],"c":2,"e":{"uk":"Визначення «дати дорогу» в {p:1.10} поєднує обидві частини: не продовжувати чи не відновлювати рух **і** не здійснювати маневрів, якщо це змусить учасника, який має перевагу, змінити напрямок чи швидкість.","ru":"Определение «уступить дорогу» в {p:1.10} объединяет обе части: не продолжать или не возобновлять движение **и** не осуществлять манёвров, если это вынудит участника, имеющего преимущество, изменить направление или скорость."},"ref":["1.10"]},{"id":"h1-7","t":"h1","num":"1.7","q":{"uk":"Поздовжня смуга на проїзній частині завширшки щонайменше 2,75 м, що позначена або не позначена дорожньою розміткою і призначена для руху нерейкових транспортних засобів це:","ru":"Продольная полоса на проезжей части шириной не менее 2,75 м, обозначенная или не обозначенная дорожной разметкой и предназначенная для движения нерельсовых транспортных средств, — это:"},"a":[{"uk":"Розділювальна смуга.","ru":"Разделительная полоса.","w":{"uk":"Розділювальна смуга розділяє суміжні проїзні частини і не призначена для руху транспортних засобів.","ru":"Разделительная полоса разделяет смежные проезжие части и не предназначена для движения транспортных средств."}},{"uk":"Смуга руху.","ru":"Полоса движения."},{"uk":"Трамвайна колія.","ru":"Трамвайные пути.","w":{"uk":"Трамвайна колія призначена для рейкових, а не нерейкових транспортних засобів.","ru":"Трамвайные пути предназначены для рельсовых, а не нерельсовых транспортных средств."}}],"c":1,"e":{"uk":"Це визначення **смуги руху** з {p:1.10}; на малюнку проїзну частину розміткою поділено на кілька таких смуг.","ru":"Это определение **полосы движения** из {p:1.10}; на рисунке проезжая часть разделена разметкой на несколько таких полос."},"ref":["1.10"],"pic":["img/hsc/1-7-1.jpg"]},{"id":"h1-8","t":"h1","num":"1.8","q":{"uk":"Які із наведених категорій осіб, належать до визначення «учасник дорожнього руху»?","ru":"Какие из перечисленных категорий лиц относятся к определению «участник дорожного движения»?"},"a":[{"uk":"Регулювальник, пішоходи, водії, пасажири, велосипедисти, а також особи, які рухаються в кріслі колісному.","ru":"Регулировщик, пешеходы, водители, пассажиры, велосипедисты, а также лица, передвигающиеся в кресле-коляске.","w":{"uk":"Регулювальник не є учасником дорожнього руху, а погоничів тварин у переліку бракує.","ru":"Регулировщик не является участником дорожного движения, а погонщиков животных в перечне не хватает."}},{"uk":"Пішоходи, водії, пасажири, погоничі тварин, велосипедисти, а також особи, які рухаються в кріслі колісному.","ru":"Пешеходы, водители, пассажиры, погонщики животных, велосипедисты, а также лица, передвигающиеся в кресле-коляске."},{"uk":"Пішоходи, водії, пасажири, погоничі тварин, велосипедисти та регулювальник.","ru":"Пешеходы, водители, пассажиры, погонщики животных, велосипедисты и регулировщик.","w":{"uk":"Регулювальник не належить до учасників дорожнього руху, а осіб у кріслах колісних у переліку бракує.","ru":"Регулировщик не относится к участникам дорожного движения, а лиц в креслах-колясках в перечне не хватает."}}],"c":1,"e":{"uk":"Перелік у {p:1.10} такий: пішохід, водій, пасажир, погонич тварин, велосипедист, а також особа, яка рухається в кріслі колісному. Регулювальника в ньому немає — він регулює рух, а не бере в ньому участь.","ru":"Перечень в {p:1.10} такой: пешеход, водитель, пассажир, погонщик животных, велосипедист, а также лицо, передвигающееся в кресле-коляске. Регулировщика в нём нет — он регулирует движение, а не участвует в нём."},"ref":["1.10"]},{"id":"h1-9","t":"h1","num":"1.9","q":{"uk":"Яка із наведених категорій осіб бере участь у дорожньому русі поза транспортними засобами та не виконує на дорозі будь-яку роботу:","ru":"Какая из перечисленных категорий лиц участвует в дорожном движении вне транспортных средств и не выполняет на дороге какую-либо работу:"},"a":[{"uk":"Пішохід.","ru":"Пешеход."},{"uk":"Пасажир.","ru":"Пассажир.","w":{"uk":"Пасажир перебуває в транспортному засобі, а не поза ним.","ru":"Пассажир находится в транспортном средстве, а не вне его."}},{"uk":"Регулювальник.","ru":"Регулировщик.","w":{"uk":"Регулювальник виконує на дорозі роботу — регулює рух.","ru":"Регулировщик выполняет на дороге работу — регулирует движение."}}],"c":0,"e":{"uk":"Саме так {p:1.10} визначає **пішохода**: особа, яка бере участь у дорожньому русі поза транспортними засобами та не виконує на дорозі будь-яку роботу.","ru":"Именно так {p:1.10} определяет **пешехода**: лицо, участвующее в дорожном движении вне транспортных средств и не выполняющее на дороге какую-либо работу."},"ref":["1.10"]},{"id":"h1-10","t":"h1","num":"1.10","q":{"uk":"Особа, яка користується транспортним засобом і перебуває в ньому, але не причетна до керування ним, це:","ru":"Лицо, которое пользуется транспортным средством и находится в нём, но не причастно к управлению им, — это:"},"a":[{"uk":"Пасажир.","ru":"Пассажир."},{"uk":"Пішохід.","ru":"Пешеход.","w":{"uk":"Пішохід бере участь у русі поза транспортними засобами.","ru":"Пешеход участвует в движении вне транспортных средств."}},{"uk":"Особа, яка рухається в кріслі колісному.","ru":"Лицо, передвигающееся в кресле-коляске.","w":{"uk":"Особа в кріслі колісному сама рухається на ньому, а не перебуває в транспортному засобі як пасажир.","ru":"Лицо в кресле-коляске само передвигается на нём, а не находится в транспортном средстве как пассажир."}}],"c":0,"e":{"uk":"Це визначення **пасажира** з {p:1.10}.","ru":"Это определение **пассажира** из {p:1.10}."},"ref":["1.10"]},{"id":"h1-11","t":"h1","num":"1.11","q":{"uk":"Колона пішоходів це:","ru":"Колонна пешеходов — это:"},"a":[{"uk":"Організована група людей, які рухаються по тротуару в одному напрямку.","ru":"Организованная группа людей, движущихся по тротуару в одном направлении.","w":{"uk":"Визначення колони пішоходів у {p:1.10} говорить про проїзну частину, а не про тротуар.","ru":"Определение колонны пешеходов в {p:1.10} говорит о проезжей части, а не о тротуаре."}},{"uk":"Організована група людей, які рухаються узбіччям в одному напрямку.","ru":"Организованная группа людей, движущихся по обочине в одном направлении.","w":{"uk":"Визначення колони пішоходів у {p:1.10} говорить про проїзну частину, а не про узбіччя.","ru":"Определение колонны пешеходов в {p:1.10} говорит о проезжей части, а не об обочине."}},{"uk":"Організована група людей, які рухаються по проїзній частині в одному напрямку.","ru":"Организованная группа людей, движущихся по проезжей части в одном направлении."}],"c":2,"e":{"uk":"За {p:1.10} колона пішоходів — організована група людей, які рухаються **по проїзній частині** в одному напрямку.","ru":"Согласно {p:1.10} колонна пешеходов — организованная группа людей, движущихся **по проезжей части** в одном направлении."},"ref":["1.10"]},{"id":"h1-12","t":"h1","num":"1.12","q":{"uk":"Регульованим пішохідним переходом вважається:","ru":"Регулируемым пешеходным переходом считается:"},"a":[{"uk":"Пішохідний перехід, рух по якому регулюється світлофором чи регулювальником.","ru":"Пешеходный переход, движение по которому регулируется светофором или регулировщиком."},{"uk":"Пішохідний перехід, рух по якому регулюється дорожніми знаками або дорожньою розміткою.","ru":"Пешеходный переход, движение по которому регулируется дорожными знаками или дорожной разметкой.","w":{"uk":"Знаки й розмітка лише позначають перехід; без світлофора чи регулювальника він нерегульований.","ru":"Знаки и разметка лишь обозначают переход; без светофора или регулировщика он нерегулируемый."}}],"c":0,"e":{"uk":"За {p:1.10} регульованим вважається пішохідний перехід, рух по якому регулюється **світлофором чи регулювальником**.","ru":"Согласно {p:1.10} регулируемым считается пешеходный переход, движение по которому регулируется **светофором или регулировщиком**."},"ref":["1.10"]},{"id":"h1-13","t":"h1","num":"1.13","q":{"uk":"Пішохідний перехід, на якому немає регулювальника, відсутні світлофори або вимкнені чи працюють у режимі миготіння жовтого сигналу вважається:","ru":"Пешеходный переход, на котором нет регулировщика, светофоры отсутствуют или выключены либо работают в режиме мигания жёлтого сигнала, считается:"},"a":[{"uk":"Регульованим.","ru":"Регулируемым.","w":{"uk":"Регульованим перехід є лише тоді, коли рух на ньому регулюють працюючий світлофор або регулювальник.","ru":"Регулируемым переход является лишь тогда, когда движение на нём регулируют работающий светофор или регулировщик."}},{"uk":"Нерегульованим.","ru":"Нерегулируемым."}],"c":1,"e":{"uk":"Саме так {p:1.10} визначає **нерегульований** пішохідний перехід: вимкнений світлофор чи миготливий жовтий сигнал рух не регулюють.","ru":"Именно так {p:1.10} определяет **нерегулируемый** пешеходный переход: выключенный светофор или мигающий жёлтый сигнал движение не регулируют."},"ref":["1.10"]},{"id":"h1-14","t":"h1","num":"1.14","q":{"uk":"Доріжка з покриттям, призначена для руху пішоходів, виконана в межах дороги чи поза нею і позначена наведеним дорожнім знаком це:","ru":"Дорожка с покрытием, предназначенная для движения пешеходов, выполненная в пределах дороги или вне её и обозначенная приведённым дорожным знаком, — это:"},"a":[{"uk":"Пішохідна доріжка.","ru":"Пешеходная дорожка."},{"uk":"Велосипедна доріжка.","ru":"Велосипедная дорожка.","w":{"uk":"Велосипедна доріжка призначена для руху на велосипедах і позначається знаком {s:4.14}.","ru":"Велосипедная дорожка предназначена для движения на велосипедах и обозначается знаком {s:4.14}."}},{"uk":"Пішохідна смуга.","ru":"Пешеходная полоса.","w":{"uk":"Терміна «пішохідна смуга» Правила не містять.","ru":"Термина «пешеходная полоса» Правила не содержат."}}],"c":0,"e":{"uk":"На малюнку знак {s:4.16} «Доріжка для пішоходів»; за {p:1.10} позначена ним доріжка з покриттям для руху пішоходів — це **пішохідна доріжка**.","ru":"На рисунке знак {s:4.16} «Дорожка для пешеходов»; согласно {p:1.10} обозначенная им дорожка с покрытием для движения пешеходов — это **пешеходная дорожка**."},"ref":["1.10"],"pic":["img/hsc/1-14-1.jpg"]},{"id":"h1-15","t":"h1","num":"1.15","q":{"uk":"Чи призначена пішохідна доріжка для руху велосипедистів?","ru":"Предназначена ли пешеходная дорожка для движения велосипедистов?"},"a":[{"uk":"Так, призначена.","ru":"Да, предназначена.","w":{"uk":"Велосипедист — не пішохід; рух по пішохідних доріжках йому прямо заборонено {p:6.6}.","ru":"Велосипедист — не пешеход; движение по пешеходным дорожкам ему прямо запрещено {p:6.6}."}},{"uk":"Ні, не призначена.","ru":"Нет, не предназначена."}],"c":1,"e":{"uk":"Пішохідна доріжка призначена для руху пішоходів ({p:1.10}), а велосипедистам рух по пішохідних доріжках заборонено (крім дітей до 7 років на дитячих велосипедах під наглядом дорослих) — {p:6.6}.","ru":"Пешеходная дорожка предназначена для движения пешеходов ({p:1.10}), а велосипедистам движение по пешеходным дорожкам запрещено (кроме детей до 7 лет на детских велосипедах под присмотром взрослых) — {p:6.6}."},"ref":["1.10","6.6"]},{"id":"h1-16","t":"h1","num":"1.16","q":{"uk":"Чи призначена пішохідна доріжка для руху осіб, які рухаються в кріслах колісних без двигуна?","ru":"Предназначена ли пешеходная дорожка для движения лиц, передвигающихся в креслах-колясках без двигателя?"},"a":[{"uk":"Так, призначена.","ru":"Да, предназначена."},{"uk":"Ні, не призначена.","ru":"Нет, не предназначена.","w":{"uk":"Ці особи прирівнюються до пішоходів, тож пішохідна доріжка призначена й для них.","ru":"Эти лица приравниваются к пешеходам, поэтому пешеходная дорожка предназначена и для них."}}],"c":0,"e":{"uk":"Особи в кріслах колісних без двигуна прирівнюються до пішоходів ({p:1.10}) і мають право рухатися пішохідними доріжками зі швидкістю пішохода ({p:4.17}).","ru":"Лица в креслах-колясках без двигателя приравниваются к пешеходам ({p:1.10}) и имеют право двигаться по пешеходным дорожкам со скоростью пешехода ({p:4.17})."},"ref":["1.10","4.17"]},{"id":"h1-17","t":"h1","num":"1.17","q":{"uk":"Чи призначена пішохідна доріжка для руху осіб, які ведуть мопед?","ru":"Предназначена ли пешеходная дорожка для движения лиц, ведущих мопед?"},"a":[{"uk":"Так, призначена.","ru":"Да, предназначена."},{"uk":"Ні, не призначена.","ru":"Нет, не предназначена.","w":{"uk":"Хто веде мопед поруч із собою, а не їде на ньому, той за Правилами — пішохід.","ru":"Кто ведёт мопед рядом с собой, а не едет на нём, тот по Правилам — пешеход."}}],"c":0,"e":{"uk":"Особа, яка **веде** мопед, прирівнюється до пішохода ({p:1.10}), тому може рухатися пішохідною доріжкою, як і інші пішоходи ({p:4.1}).","ru":"Лицо, которое **ведёт** мопед, приравнивается к пешеходу ({p:1.10}), поэтому может двигаться по пешеходной дорожке, как и другие пешеходы ({p:4.1})."},"ref":["1.10","4.1"]},{"id":"h1-18","t":"h1","num":"1.18","q":{"uk":"На якому з наведених малюнків зображено перехрестя:","ru":"На каком из приведённых рисунков изображён перекрёсток:"},"a":[{"uk":"На першому.","ru":"На первом.","w":{"uk":"Місце прилягання до дороги виїзду з прилеглої території (двору) за {p:1.10} перехрестям не вважається.","ru":"Место примыкания к дороге выезда с прилегающей территории (двора) согласно {p:1.10} перекрёстком не считается."}},{"uk":"На другому.","ru":"На втором."}],"c":1,"e":{"uk":"На другому малюнку дві дороги з'єднуються на одному рівні із заокругленими краями проїзної частини — це перехрестя ({p:1.10}). На першому — в'їзд у двір, позначений знаком {s:5.34} «Житлова зона», тобто на прилеглу територію.","ru":"На втором рисунке две дороги соединяются на одном уровне с закруглёнными краями проезжей части — это перекрёсток ({p:1.10}). На первом — въезд во двор, обозначенный знаком {s:5.34} «Жилая зона», то есть на прилегающую территорию."},"ref":["1.10"],"pic":["img/hsc/1-18-1.jpg"]},{"id":"h1-19","t":"h1","num":"1.19","q":{"uk":"На якому малюнку зображено в’їзд на прилеглу територію:","ru":"На каком рисунке изображён въезд на прилегающую территорию:"},"a":[{"uk":"На першому.","ru":"На первом.","w":{"uk":"На першому малюнку — перехрестя доріг із центральним острівцем, тобто місце перехрещення доріг, а не в'їзд на прилеглу територію.","ru":"На первом рисунке — перекрёсток дорог с центральным островком, то есть место пересечения дорог, а не въезд на прилегающую территорию."}},{"uk":"На другому.","ru":"На втором."}],"c":1,"e":{"uk":"На другому малюнку — в'їзд у двір, позначений знаком {s:5.34} «Житлова зона»: така територія не призначена для наскрізного проїзду, тобто є прилеглою ({p:1.10}).","ru":"На втором рисунке — въезд во двор, обозначенный знаком {s:5.34} «Жилая зона»: такая территория не предназначена для сквозного проезда, то есть является прилегающей ({p:1.10})."},"ref":["1.10"],"pic":["img/hsc/1-19-1.jpg"]},{"id":"h1-20","t":"h1","num":"1.20","q":{"uk":"Чи може автомагістраль перетинати на одному рівні інші дороги, залізничні і трамвайні колії, пішохідні та велосипедні доріжки, шляхи проходу тварин?","ru":"Может ли автомагистраль пересекать на одном уровне другие дороги, железнодорожные и трамвайные пути, пешеходные и велосипедные дорожки, пути прохода животных?"},"a":[{"uk":"Так, може.","ru":"Да, может.","w":{"uk":"Перетин на одному рівні суперечить визначенню автомагістралі: усі такі перетини на ній влаштовано на різних рівнях.","ru":"Пересечение на одном уровне противоречит определению автомагистрали: все такие пересечения на ней устроены в разных уровнях."}},{"uk":"Ні, не може.","ru":"Нет, не может."}],"c":1,"e":{"uk":"Одна з ознак автомагістралі за {p:1.10} — вона **не перетинає на одному рівні** інші дороги, залізничні й трамвайні колії, пішохідні й велосипедні доріжки, шляхи проходу тварин.","ru":"Один из признаков автомагистрали согласно {p:1.10} — она **не пересекает на одном уровне** другие дороги, железнодорожные и трамвайные пути, пешеходные и велосипедные дорожки, пути прохода животных."},"ref":["1.10"]},{"id":"h1-21","t":"h1","num":"1.21","q":{"uk":"Чи вважається перехрестям місце прилягання до дороги виїзду з прилеглої території (дворів)?","ru":"Считается ли перекрёстком место примыкания к дороге выезда с прилегающей территории (дворов)?"},"a":[{"uk":"Так, вважається.","ru":"Да, считается.","w":{"uk":"Перехрестя — це перехрещення, прилягання чи розгалуження саме доріг, а виїзд із двору дорогою не є.","ru":"Перекрёсток — это пересечение, примыкание или разветвление именно дорог, а выезд со двора дорогой не является."}},{"uk":"Ні, не вважається.","ru":"Нет, не считается."}],"c":1,"e":{"uk":"Визначення перехрестя в {p:1.10} прямо застерігає: місце прилягання до дороги виїзду з прилеглої території перехрестям **не вважається**.","ru":"Определение перекрёстка в {p:1.10} прямо оговаривает: место примыкания к дороге выезда с прилегающей территории перекрёстком **не считается**."},"ref":["1.10"]},{"id":"h1-22","t":"h1","num":"1.22","q":{"uk":"Показаний на малюнку поворот дороги відповідає терміну:","ru":"Показанный на рисунке поворот дороги соответствует термину:"},"a":[{"uk":"«Обмежена оглядовість дороги».","ru":"«Ограниченная обзорность дороги»."},{"uk":"«Недостатня видимість дороги».","ru":"«Недостаточная видимость дороги».","w":{"uk":"Недостатню видимість спричиняють сутінки чи погода (туман, дощ, снігопад), а на малюнку ясний день.","ru":"Недостаточную видимость вызывают сумерки или погода (туман, дождь, снегопад), а на рисунке ясный день."}}],"c":0,"e":{"uk":"Видимість дороги тут обмежують її геометрія (поворот) і насадження обабіч, тож це **обмежена оглядовість** ({p:1.10}).","ru":"Видимость дороги здесь ограничивают её геометрия (поворот) и насаждения по сторонам, поэтому это **ограниченная обзорность** ({p:1.10})."},"ref":["1.10"],"pic":["img/hsc/1-22-1.jpg"]},{"id":"h1-23","t":"h1","num":"1.23","q":{"uk":"Як називається даний маневр?","ru":"Как называется данный манёвр?"},"a":[{"uk":"Обгін.","ru":"Обгон.","w":{"uk":"Обгін пов'язаний із виїздом на смугу зустрічного руху, а тут обидва автомобілі на смугах одного напрямку.","ru":"Обгон связан с выездом на полосу встречного движения, а здесь оба автомобиля на полосах одного направления."}},{"uk":"Об’їзд.","ru":"Объезд.","w":{"uk":"Об'їжджають перешкоду, а перед жовтим автомобілем перешкоди немає — він просто рухається швидше за сусіда.","ru":"Объезжают препятствие, а перед жёлтым автомобилем препятствия нет — он просто движется быстрее соседа."}},{"uk":"Випередження.","ru":"Опережение."}],"c":2,"e":{"uk":"Жовтий автомобіль їде швидше (85 км/год) за попутний (70 км/год), що рухається поряд по суміжній смузі, і не виїжджає на смугу зустрічного руху — це **випередження** ({p:1.10}).","ru":"Жёлтый автомобиль едет быстрее (85 км/ч) попутного (70 км/ч), движущегося рядом по соседней полосе, и не выезжает на полосу встречного движения — это **опережение** ({p:1.10})."},"ref":["1.10"],"pic":["img/hsc/1-23-1.jpg"]},{"id":"h1-24","t":"h1","num":"1.24","q":{"uk":"Автомобільна дорога призначена для руху:","ru":"Автомобильная дорога предназначена для движения:"},"a":[{"uk":"Транспортних засобів.","ru":"Транспортных средств.","w":{"uk":"Неповна відповідь: дорогою рухаються також пішоходи — тротуари й узбіччя теж є її частинами.","ru":"Неполный ответ: по дороге движутся также пешеходы — тротуары и обочины тоже являются её частями."}},{"uk":"Пішоходів і тварин.","ru":"Пешеходов и животных.","w":{"uk":"Тварин визначення автомобільної дороги не згадує, а транспортні засоби тут пропущено.","ru":"Животных определение автомобильной дороги не упоминает, а транспортные средства здесь пропущены."}},{"uk":"Транспортних засобів і пішоходів.","ru":"Транспортных средств и пешеходов."},{"uk":"Варіант 1 та 2.","ru":"Вариант 1 и 2.","w":{"uk":"Варіант 2 хибний: про рух тварин у визначенні дороги не йдеться.","ru":"Вариант 2 ошибочен: о движении животных в определении дороги речи нет."}}],"c":2,"e":{"uk":"За {p:1.10} автомобільна дорога — частина території, призначена для руху **транспортних засобів і пішоходів**.","ru":"Согласно {p:1.10} автомобильная дорога — часть территории, предназначенная для движения **транспортных средств и пешеходов**."},"ref":["1.10"]},{"id":"h1-25","t":"h1","num":"1.25","q":{"uk":"Недостатньою видимістю вважається:","ru":"Недостаточной видимостью считается:"},"a":[{"uk":"Обмежена оглядовість менше 300 м.","ru":"Ограниченная обзорность менее 300 м.","w":{"uk":"Обмежена оглядовість — окремий термін: її спричиняють дорога й придорожні об'єкти, а не погода, і відстані її визначення не містить.","ru":"Ограниченная обзорность — отдельный термин: её вызывают дорога и придорожные объекты, а не погода, и расстояния её определение не содержит."}},{"uk":"Видимість дороги в напрямку руху менше 300 метрів, обмежена поворотом дороги.","ru":"Видимость дороги в направлении движения менее 300 метров, ограниченная поворотом дороги.","w":{"uk":"Видимість, обмежена поворотом дороги, — це обмежена оглядовість, а не недостатня видимість.","ru":"Видимость, ограниченная поворотом дороги, — это ограниченная обзорность, а не недостаточная видимость."}},{"uk":"Видимість дороги в напрямку руху менше 300 м у сутінках, в умовах туману, дощу, снігопаду тощо.","ru":"Видимость дороги в направлении движения менее 300 м в сумерках, в условиях тумана, дождя, снегопада и т. п."},{"uk":"Небезпечний поворот, небезпечний підйом, небезпечний спуск.","ru":"Опасный поворот, опасный подъём, опасный спуск.","w":{"uk":"Це назви небезпечних ділянок дороги (попереджувальних знаків), а не визначення недостатньої видимості.","ru":"Это названия опасных участков дороги (предупреждающих знаков), а не определение недостаточной видимости."}}],"c":2,"e":{"uk":"Це визначення з {p:1.10}: недостатня видимість — менше 300 м через сутінки чи погодні умови, як туман на малюнку.","ru":"Это определение из {p:1.10}: недостаточная видимость — менее 300 м из-за сумерек или погодных условий, как туман на рисунке."},"ref":["1.10"],"pic":["img/hsc/1-25-1.jpg"]},{"id":"h1-26","t":"h1","num":"1.26","q":{"uk":"Доріжка з покриттям поза межами проїзної частини вулиці та/або дороги, розташована окремо чи суміжно з тротуаром або пішохідною доріжкою, що призначена для руху на велосипедах, і позначена дорожнім знаком та горизонтальною розміткою, як показано на малюнку, це:","ru":"Дорожка с покрытием за пределами проезжей части улицы и/или дороги, расположенная отдельно или рядом с тротуаром либо пешеходной дорожкой, предназначенная для движения на велосипедах и обозначенная дорожным знаком и горизонтальной разметкой, как показано на рисунке, — это:"},"a":[{"uk":"Велосипедна доріжка.","ru":"Велосипедная дорожка."},{"uk":"Велосипедна смуга.","ru":"Велосипедная полоса.","w":{"uk":"Велосипедна смуга виділяється в межах проїзної частини і позначається знаком {s:5.88}.","ru":"Велосипедная полоса выделяется в пределах проезжей части и обозначается знаком {s:5.88}."}},{"uk":"Велосипедний переїзд.","ru":"Велосипедный переезд.","w":{"uk":"Велосипедний переїзд — місце перетину велосипедистами проїзної частини, позначене розміткою {m:1.15}.","ru":"Велосипедный переезд — место пересечения велосипедистами проезжей части, обозначенное разметкой {m:1.15}."}}],"c":0,"e":{"uk":"Це визначення **велосипедної доріжки** з {p:1.10}: вона розташована поза проїзною частиною і позначена знаком {s:4.14} та розміткою {m:1.36}, як на малюнку.","ru":"Это определение **велосипедной дорожки** из {p:1.10}: она расположена за пределами проезжей части и обозначена знаком {s:4.14} и разметкой {m:1.36}, как на рисунке."},"ref":["1.10"],"pic":["img/hsc/1-26-1.jpg"]},{"id":"h1-27","t":"h1","num":"1.27","q":{"uk":"Як називається доріжка зображена на наведеному малюнку?","ru":"Как называется дорожка, изображённая на приведённом рисунке?"},"a":[{"uk":"Велосипедна доріжка.","ru":"Велосипедная дорожка."},{"uk":"Велосипедна смуга.","ru":"Велосипедная полоса.","w":{"uk":"Велосипедна смуга виділяється на проїзній частині, а ця доріжка розташована поза нею.","ru":"Велосипедная полоса выделяется на проезжей части, а эта дорожка расположена за её пределами."}},{"uk":"Велосипедний переїзд.","ru":"Велосипедный переезд.","w":{"uk":"Велосипедний переїзд — це лише місце перетину проїзної частини, позначене розміткою {m:1.15}, а не доріжка вздовж неї.","ru":"Велосипедный переезд — это лишь место пересечения проезжей части, обозначенное разметкой {m:1.15}, а не дорожка вдоль неё."}}],"c":0,"e":{"uk":"Доріжка проходить окремо від проїзної частини (серед газону) і позначена знаком {s:4.14} та розміткою {m:1.36} — це **велосипедна доріжка** ({p:1.10}).","ru":"Дорожка проходит отдельно от проезжей части (среди газона) и обозначена знаком {s:4.14} и разметкой {m:1.36} — это **велосипедная дорожка** ({p:1.10})."},"ref":["1.10"],"pic":["img/hsc/1-27-1.jpg"]},{"id":"h1-28","t":"h1","num":"1.28","q":{"uk":"Доріжка з покриттям поза межами проїзної частини вулиці та/або дороги, розташована окремо чи суміжно з тротуаром або пішохідною доріжкою, і позначена дорожнім знаком та горизонтальною розміткою, як показано на малюнку, призначена для руху:","ru":"Дорожка с покрытием за пределами проезжей части улицы и/или дороги, расположенная отдельно или рядом с тротуаром либо пешеходной дорожкой и обозначенная дорожным знаком и горизонтальной разметкой, как показано на рисунке, предназначена для движения:"},"a":[{"uk":"Пішоходів.","ru":"Пешеходов.","w":{"uk":"Для пішоходів призначені тротуари й пішохідні доріжки; велосипедною доріжкою пішоходи можуть іти лише за їх відсутності ({p:4.1}).","ru":"Для пешеходов предназначены тротуары и пешеходные дорожки; по велосипедной дорожке пешеходы могут идти лишь при их отсутствии ({p:4.1})."}},{"uk":"На велосипедах.","ru":"На велосипедах."},{"uk":"Відповідь 1 та 2.","ru":"Ответ 1 и 2.","w":{"uk":"Пішоходів у призначенні велосипедної доріжки немає; спільну доріжку для пішоходів і велосипедистів позначають знаком {s:4.17}.","ru":"Пешеходов в назначении велосипедной дорожки нет; общую дорожку для пешеходов и велосипедистов обозначают знаком {s:4.17}."}}],"c":1,"e":{"uk":"Знак {s:4.14} і розмітка {m:1.36} позначають велосипедну доріжку, а вона за {p:1.10} призначена для руху **на велосипедах**.","ru":"Знак {s:4.14} и разметка {m:1.36} обозначают велосипедную дорожку, а она согласно {p:1.10} предназначена для движения **на велосипедах**."},"ref":["1.10"],"pic":["img/hsc/1-28-1.jpg"]},{"id":"h1-29","t":"h1","num":"1.29","q":{"uk":"Смуга, призначена для руху на велосипедах у межах проїзної частини вулиці та/або дороги, яка позначена дорожнім знаком 5.88 та відповідною горизонтальною дорожньою розміткою це:","ru":"Полоса, предназначенная для движения на велосипедах в пределах проезжей части улицы и/или дороги, обозначенная дорожным знаком 5.88 и соответствующей горизонтальной дорожной разметкой, — это:"},"a":[{"uk":"Велосипедна доріжка.","ru":"Велосипедная дорожка.","w":{"uk":"Велосипедна доріжка розташована поза проїзною частиною і позначається знаком {s:4.14}.","ru":"Велосипедная дорожка расположена за пределами проезжей части и обозначается знаком {s:4.14}."}},{"uk":"Велосипедна смуга.","ru":"Велосипедная полоса."},{"uk":"Велосипедний переїзд.","ru":"Велосипедный переезд.","w":{"uk":"Велосипедний переїзд — місце перетину проїзної частини велосипедистами, позначене розміткою {m:1.15}.","ru":"Велосипедный переезд — место пересечения проезжей части велосипедистами, обозначенное разметкой {m:1.15}."}}],"c":1,"e":{"uk":"Це визначення **велосипедної смуги** з {p:1.10}: вона виділена в межах проїзної частини та позначена знаком {s:5.88}.","ru":"Это определение **велосипедной полосы** из {p:1.10}: она выделена в пределах проезжей части и обозначена знаком {s:5.88}."},"ref":["1.10"],"pic":["img/hsc/1-29-1.jpg"]},{"id":"h1-30","t":"h1","num":"1.30","q":{"uk":"Велосипедною доріжкою дозволяється рух:","ru":"По велосипедной дорожке разрешается движение:"},"a":[{"uk":"Особам, які рухаються із швидкістю пішохода в кріслах колісних.","ru":"Лицам, передвигающимся со скоростью пешехода в креслах-колясках.","w":{"uk":"Неповна відповідь: право осіб у кріслах колісних ({p:4.17}) не виключає руху велосипедистів і пішоходів.","ru":"Неполный ответ: право лиц в креслах-колясках ({p:4.17}) не исключает движения велосипедистов и пешеходов."}},{"uk":"Особам, які везуть візок, якщо немає тротуару або пішохідної доріжки.","ru":"Лицам, везущим тележку, если нет тротуара или пешеходной дорожки.","w":{"uk":"Неповна відповідь: крім осіб із візком, велосипедною доріжкою можуть рухатися велосипедисти, інші пішоходи й особи в кріслах колісних.","ru":"Неполный ответ: кроме лиц с тележкой, по велосипедной дорожке могут двигаться велосипедисты, другие пешеходы и лица в креслах-колясках."}},{"uk":"Велосипедистам.","ru":"Велосипедистам.","w":{"uk":"Неповна відповідь: велосипедисти — основні, але не єдині, хто може рухатися велосипедною доріжкою ({p:4.1}, {p:4.17}).","ru":"Неполный ответ: велосипедисты — основные, но не единственные, кто может двигаться по велосипедной дорожке ({p:4.1}, {p:4.17})."}},{"uk":"Пішоходам.","ru":"Пешеходам.","w":{"uk":"Неповна відповідь: пішоходи можуть іти велосипедною доріжкою за відсутності тротуару, але нею рухаються й велосипедисти та особи в кріслах колісних.","ru":"Неполный ответ: пешеходы могут идти по велосипедной дорожке при отсутствии тротуара, но по ней движутся и велосипедисты, и лица в креслах-колясках."}},{"uk":"Усім переліченим учасникам дорожнього руху.","ru":"Всем перечисленным участникам дорожного движения."}],"c":4,"e":{"uk":"Велосипедна доріжка призначена для велосипедистів ({p:1.10}); особи в кріслах колісних мають право рухатися нею зі швидкістю пішохода ({p:4.17}), а пішоходи, зокрема ті, хто везе візок, — коли немає тротуару чи пішохідної доріжки ({p:4.1}).","ru":"Велосипедная дорожка предназначена для велосипедистов ({p:1.10}); лица в креслах-колясках имеют право двигаться по ней со скоростью пешехода ({p:4.17}), а пешеходы, в том числе везущие тележку, — когда нет тротуара или пешеходной дорожки ({p:4.1})."},"ref":["1.10","4.1","4.17"]},{"id":"h1-31","t":"h1","num":"1.31","q":{"uk":"Що з переліченого нижче відповідає терміну «небезпека для руху»?","ru":"Что из перечисленного ниже соответствует термину «опасность для движения»?"},"a":[{"uk":"Зміна дорожньої обстановки (у тому числі поява рухомого об’єкта, який наближається до смуги руху транспортного засобу чи перетинає її), яка загрожує безпеці дорожнього руху і змушує водія негайно зменшити швидкість або зупинитися.","ru":"Изменение дорожной обстановки (в том числе появление движущегося объекта, приближающегося к полосе движения транспортного средства или пересекающего её), которое угрожает безопасности дорожного движения и вынуждает водителя немедленно снизить скорость или остановиться.","w":{"uk":"Неповна відповідь: небезпекою для руху є також зміна технічного стану транспортного засобу.","ru":"Неполный ответ: опасностью для движения является также изменение технического состояния транспортного средства."}},{"uk":"Зміна технічного стану транспортного засобу, яка загрожує безпеці дорожнього руху і змушує водія негайно зменшити швидкість або зупинитися.","ru":"Изменение технического состояния транспортного средства, которое угрожает безопасности дорожного движения и вынуждает водителя немедленно снизить скорость или остановиться.","w":{"uk":"Неповна відповідь: небезпекою для руху є також зміна дорожньої обстановки, наприклад поява рухомого об'єкта.","ru":"Неполный ответ: опасностью для движения является также изменение дорожной обстановки, например появление движущегося объекта."}},{"uk":"Відповіді 1 та 2.","ru":"Ответы 1 и 2."}],"c":2,"e":{"uk":"Визначення небезпеки для руху в {p:1.10} охоплює **обидва** випадки: зміну дорожньої обстановки або технічного стану транспортного засобу, яка змушує водія негайно зменшити швидкість чи зупинитися.","ru":"Определение опасности для движения в {p:1.10} охватывает **оба** случая: изменение дорожной обстановки или технического состояния транспортного средства, которое вынуждает водителя немедленно снизить скорость или остановиться."},"ref":["1.10"]},{"id":"h1-32","t":"h1","num":"1.32","q":{"uk":"Елемент дороги, призначений для руху пішоходів, який прилягає до проїзної частини або відокремлений від неї газоном це:","ru":"Элемент дороги, предназначенный для движения пешеходов, который прилегает к проезжей части или отделён от неё газоном, — это:"},"a":[{"uk":"Тротуар.","ru":"Тротуар."},{"uk":"Узбіччя.","ru":"Обочина.","w":{"uk":"Узбіччя прилягає безпосередньо до краю проїзної частини на одному рівні з нею і використовується не лише пішоходами, а й для зупинки та стоянки.","ru":"Обочина прилегает непосредственно к краю проезжей части на одном уровне с ней и используется не только пешеходами, но и для остановки и стоянки."}},{"uk":"Розділювальна смуга.","ru":"Разделительная полоса.","w":{"uk":"Розділювальна смуга розділяє суміжні проїзні частини; пішоходи можуть рухатися нею лише тоді, коли на ній є тротуар.","ru":"Разделительная полоса разделяет смежные проезжие части; пешеходы могут двигаться по ней, только если на ней есть тротуар."}}],"c":0,"e":{"uk":"Це визначення **тротуару** з {p:1.10}.","ru":"Это определение **тротуара** из {p:1.10}."},"ref":["1.10"]},{"id":"h1-33","t":"h1","num":"1.33","q":{"uk":"Чи є тротуар елементом автомобільної дороги?","ru":"Является ли тротуар элементом автомобильной дороги?"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"Тротуар входить до складу дороги: її межа проходить саме по зовнішньому краю тротуарів.","ru":"Тротуар входит в состав дороги: её граница проходит именно по внешнему краю тротуаров."}}],"c":0,"e":{"uk":"За {p:1.10} тротуар — **елемент дороги**, а сама автомобільна дорога обмежена по ширині зовнішнім краєм тротуарів.","ru":"Согласно {p:1.10} тротуар — **элемент дороги**, а сама автомобильная дорога ограничена по ширине внешним краем тротуаров."},"ref":["1.10"]},{"id":"h1-34","t":"h1","num":"1.34","q":{"uk":"Чи вважається тротуар елементом проїзної частини?","ru":"Считается ли тротуар элементом проезжей части?"},"a":[{"uk":"Так, вважається.","ru":"Да, считается.","w":{"uk":"Тротуар — окремий елемент дороги; край проїзної частини проходить якраз там, де до неї прилягає тротуар.","ru":"Тротуар — отдельный элемент дороги; край проезжей части проходит как раз там, где к ней примыкает тротуар."}},{"uk":"Ні, не вважається.","ru":"Нет, не считается."}],"c":1,"e":{"uk":"Тротуар і проїзна частина — різні елементи дороги ({p:1.10}): тротуар призначений для пішоходів і лише прилягає до проїзної частини, яка призначена для нерейкових транспортних засобів.","ru":"Тротуар и проезжая часть — разные элементы дороги ({p:1.10}): тротуар предназначен для пешеходов и лишь прилегает к проезжей части, которая предназначена для нерельсовых транспортных средств."},"ref":["1.10"]},{"id":"h1-35","t":"h1","num":"1.35","q":{"uk":"Чи дозволено велосипедистам рухатись по тротуару?","ru":"Разрешено ли велосипедистам двигаться по тротуару?"},"a":[{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"Загалом рух велосипедистів по тротуару заборонено {p:6.6}.","ru":"В целом движение велосипедистов по тротуару запрещено {p:6.6}."}},{"uk":"Заборонено.","ru":"Запрещено.","w":{"uk":"Неповна відповідь: заборона не стосується дітей до 7 років на дитячих велосипедах під наглядом дорослих.","ru":"Неполный ответ: запрет не касается детей до 7 лет на детских велосипедах под присмотром взрослых."}},{"uk":"Заборонено, крім дітей до 7 років на дитячих велосипедах під наглядом дорослих.","ru":"Запрещено, кроме детей до 7 лет на детских велосипедах под присмотром взрослых."}],"c":2,"e":{"uk":"{p:6.6} забороняє велосипедистам рухатися по тротуарах і пішохідних доріжках, **крім** дітей до 7 років на дитячих велосипедах під наглядом дорослих.","ru":"{p:6.6} запрещает велосипедистам двигаться по тротуарам и пешеходным дорожкам, **кроме** детей до 7 лет на детских велосипедах под присмотром взрослых."},"ref":["6.6"]},{"id":"h1-36","t":"h1","num":"1.36","q":{"uk":"Що з переліченого нижче відповідає терміну «видимість у напрямку руху»?","ru":"Что из перечисленного ниже соответствует термину «видимость в направлении движения»?"},"a":[{"uk":"Мінімальна відстань, на якій з місця водія можна побачити «стоп-лінію».","ru":"Минимальное расстояние, на котором с места водителя можно увидеть «стоп-линию».","w":{"uk":"Йдеться про максимальну, а не мінімальну відстань, і не лише про стоп-лінію, а про всі елементи дороги та учасників руху.","ru":"Речь идёт о максимальном, а не минимальном расстоянии, и не только о стоп-линии, а обо всех элементах дороги и участниках движения."}},{"uk":"Максимальна відстань вправо від напрямку руху, на якій можна розпізнати транспортні засоби, що наближаються до перехрестя по головній дорозі.","ru":"Максимальное расстояние вправо от направления движения, на котором можно распознать транспортные средства, приближающиеся к перекрёстку по главной дороге.","w":{"uk":"Видимість оцінюють у напрямку руху, а не праворуч від нього, і стосується вона всіх елементів дороги, а не лише головної дороги.","ru":"Видимость оценивают в направлении движения, а не справа от него, и касается она всех элементов дороги, а не только главной дороги."}},{"uk":"Максимальна відстань, на якій з місця водія можна чітко розпізнати межі елементів дороги та розміщення учасників руху, що дає змогу водієві орієнтуватися під час керування транспортним засобом.","ru":"Максимальное расстояние, на котором с места водителя можно чётко распознать границы элементов дороги и расположение участников движения, что позволяет водителю ориентироваться при управлении транспортным средством."}],"c":2,"e":{"uk":"Це визначення з {p:1.10}: видимість у напрямку руху — **максимальна** відстань, на якій водій чітко розпізнає межі елементів дороги та розміщення учасників руху.","ru":"Это определение из {p:1.10}: видимость в направлении движения — **максимальное** расстояние, на котором водитель чётко распознаёт границы элементов дороги и расположение участников движения."},"ref":["1.10"]},{"id":"h1-37","t":"h1","num":"1.37","q":{"uk":"На якому з наведених малюнків зображена автомобільна дорога?","ru":"На каком из приведённых рисунков изображена автомобильная дорога?"},"a":[{"uk":"На малюнку 1.","ru":"На рисунке 1.","w":{"uk":"Неповна відповідь: дорога з асфальтовим покриттям на малюнку 2 — теж автомобільна дорога.","ru":"Неполный ответ: дорога с асфальтовым покрытием на рисунке 2 — тоже автомобильная дорога."}},{"uk":"На малюнку 2.","ru":"На рисунке 2.","w":{"uk":"Неповна відповідь: дорога без удосконаленого покриття на малюнку 1 також є автомобільною — визначення не вимагає певного покриття.","ru":"Неполный ответ: дорога без усовершенствованного покрытия на рисунке 1 также является автомобильной — определение не требует определённого покрытия."}},{"uk":"На обох малюнках.","ru":"На обоих рисунках."}],"c":2,"e":{"uk":"Автомобільна дорога за {p:1.10} — частина території, призначена для руху транспортних засобів і пішоходів; вид покриття значення не має, тож і ґрунтова (1), і асфальтова (2) дороги підпадають під це визначення.","ru":"Автомобильная дорога согласно {p:1.10} — часть территории, предназначенная для движения транспортных средств и пешеходов; вид покрытия значения не имеет, поэтому и грунтовая (1), и асфальтированная (2) дороги подпадают под это определение."},"ref":["1.10"],"pic":["img/hsc/1-37-1.jpg"]},{"id":"h1-38","t":"h1","num":"1.38","q":{"uk":"Для руху яких транспортних засобів призначена проїзна частина?","ru":"Для движения каких транспортных средств предназначена проезжая часть?"},"a":[{"uk":"Рейкових транспортних засобів.","ru":"Рельсовых транспортных средств.","w":{"uk":"Рейкові транспортні засоби рухаються трамвайною колією, а не проїзною частиною.","ru":"Рельсовые транспортные средства движутся по трамвайным путям, а не по проезжей части."}},{"uk":"Нерейкових транспортних засобів.","ru":"Нерельсовых транспортных средств."},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2.","w":{"uk":"Проїзна частина за визначенням призначена лише для нерейкових транспортних засобів.","ru":"Проезжая часть по определению предназначена только для нерельсовых транспортных средств."}}],"c":1,"e":{"uk":"За {p:1.10} проїзна частина — елемент дороги, призначений для руху **нерейкових** транспортних засобів.","ru":"Согласно {p:1.10} проезжая часть — элемент дороги, предназначенный для движения **нерельсовых** транспортных средств."},"ref":["1.10"]},{"id":"h1-39","t":"h1","num":"1.39","q":{"uk":"Чи може дорога мати декілька проїзних частин?","ru":"Может ли дорога иметь несколько проезжих частей?"},"a":[{"uk":"Так, може.","ru":"Да, может."},{"uk":"Ні, не може.","ru":"Нет, не может.","w":{"uk":"Визначення проїзної частини прямо допускає кілька проїзних частин на одній дорозі.","ru":"Определение проезжей части прямо допускает несколько проезжих частей на одной дороге."}}],"c":0,"e":{"uk":"За {p:1.10} дорога може мати декілька проїзних частин, межами яких є розділювальні смуги (наприклад, автомагістраль має окремі проїзні частини для кожного напрямку).","ru":"Согласно {p:1.10} дорога может иметь несколько проезжих частей, границами которых являются разделительные полосы (например, автомагистраль имеет отдельные проезжие части для каждого направления)."},"ref":["1.10"]},{"id":"h1-40","t":"h1","num":"1.40","q":{"uk":"Чи вважається довільно накатана колія автомобільною дорогою?","ru":"Считается ли произвольно накатанная колея автомобильной дорогой?"},"a":[{"uk":"Так, вважається.","ru":"Да, считается.","w":{"uk":"Визначення автомобільної дороги прямо виключає довільно накатані колії.","ru":"Определение автомобильной дороги прямо исключает произвольно накатанные колеи."}},{"uk":"Ні, не вважається.","ru":"Нет, не считается."}],"c":1,"e":{"uk":"Термін «автомобільна дорога» охоплює й спеціально побудовані тимчасові дороги, **крім** довільно накатаних доріг (колій) — {p:1.10}.","ru":"Термин «автомобильная дорога» охватывает и специально построенные временные дороги, **кроме** произвольно накатанных дорог (колей) — {p:1.10}."},"ref":["1.10"]},{"id":"h1-41","t":"h1","num":"1.41","q":{"uk":"Обмежена оглядовість – це:","ru":"Ограниченная обзорность — это:"},"a":[{"uk":"Видимість дороги в напрямку руху менше 300 м в умовах недостатньої видимості, яка обмежена геометричними параметрами дороги.","ru":"Видимость дороги в направлении движения менее 300 м в условиях недостаточной видимости, ограниченная геометрическими параметрами дороги.","w":{"uk":"Межа 300 м і погодні умови належать до визначення недостатньої видимості, а не обмеженої оглядовості.","ru":"Предел 300 м и погодные условия относятся к определению недостаточной видимости, а не ограниченной обзорности."}},{"uk":"Видимість дороги в напрямку руху, яка обмежена геометричними параметрами дороги, придорожніми інженерними спорудами, насадженнями та іншими об’єктами, а також транспортними засобами.","ru":"Видимость дороги в направлении движения, ограниченная геометрическими параметрами дороги, придорожными инженерными сооружениями, насаждениями и другими объектами, а также транспортными средствами."},{"uk":"Оглядовість дороги, обмежена умовами туману, дощу, снігопаду тощо.","ru":"Обзорность дороги, ограниченная условиями тумана, дождя, снегопада и т. п.","w":{"uk":"Туман, дощ і снігопад спричиняють недостатню видимість, а не обмежену оглядовість.","ru":"Туман, дождь и снегопад вызывают недостаточную видимость, а не ограниченную обзорность."}}],"c":1,"e":{"uk":"Це дослівне визначення з {p:1.10}: обмежену оглядовість спричиняють геометрія дороги, споруди, насадження, інші об'єкти й транспортні засоби, а жодної відстані воно не встановлює.","ru":"Это дословное определение из {p:1.10}: ограниченную обзорность вызывают геометрия дороги, сооружения, насаждения, другие объекты и транспортные средства, а никакого расстояния оно не устанавливает."},"ref":["1.10"]},{"id":"h1-42","t":"h1","num":"1.42","q":{"uk":"Що означає термін «перевага»?","ru":"Что означает термин «преимущество»?"},"a":[{"uk":"Право на першочерговий рух стосовно інших учасників дорожнього руху.","ru":"Право на первоочередное движение по отношению к другим участникам дорожного движения."},{"uk":"Вимога, що означає не відновлювати або не продовжувати рух або не здійснювати будь-яких маневрів, якщо це може змусити іншого учасника дорожнього руху змінити напрямок або швидкість руху.","ru":"Требование не возобновлять или не продолжать движение либо не осуществлять каких-либо манёвров, если это может вынудить другого участника дорожного движения изменить направление или скорость движения.","w":{"uk":"Це, по суті, вимога «дати дорогу» — обов'язок, протилежний перевазі.","ru":"Это, по сути, требование «уступить дорогу» — обязанность, противоположная преимуществу."}},{"uk":"Положення транспортного засобу на проїжджій частині дороги, призначеної для руху в даному напрямку, що не дає можливості руху навіть двоколісних транспортних засобів відповідно правіше (лівіше) в попутному напрямку.","ru":"Положение транспортного средства на проезжей части дороги, предназначенной для движения в данном направлении, которое не даёт возможности движения даже двухколёсных транспортных средств соответственно правее (левее) в попутном направлении.","w":{"uk":"Це опис крайнього положення на проїзній частині, а не переваги.","ru":"Это описание крайнего положения на проезжей части, а не преимущества."}}],"c":0,"e":{"uk":"За {p:1.10} перевага — **право на першочерговий рух** стосовно інших учасників дорожнього руху.","ru":"Согласно {p:1.10} преимущество — **право на первоочередное движение** по отношению к другим участникам дорожного движения."},"ref":["1.10"]},{"id":"h1-43","t":"h1","num":"1.43","q":{"uk":"Рейковим транспортом вважається:","ru":"Рельсовым транспортом считается:"},"a":[{"uk":"Трамвай або транспортний засіб, що рухається трамвайною колією.","ru":"Трамвай или транспортное средство, движущееся по трамвайным путям.","w":{"uk":"Не кожен транспортний засіб на трамвайній колії рейковий: автомобіль, що за {p:11.8} їде колією, залишається нерейковим.","ru":"Не каждое транспортное средство на трамвайных путях рельсовое: автомобиль, который согласно {p:11.8} едет по путям, остаётся нерельсовым."}},{"uk":"Платформа зі спеціальним обладнанням, що рухається по залізничній колії.","ru":"Платформа со специальным оборудованием, движущаяся по железнодорожному пути.","w":{"uk":"Визначення говорить про трамвайні, а не залізничні колії; до того ж тут пропущено трамвай.","ru":"Определение говорит о трамвайных, а не железнодорожных путях; к тому же здесь пропущен трамвай."}},{"uk":"Трамвай і платформа зі спеціальним обладнанням, що рухаються трамвайними коліями.","ru":"Трамвай и платформа со специальным оборудованием, движущиеся по трамвайным путям."}],"c":2,"e":{"uk":"За {p:1.10} рейкові транспортні засоби — **трамвай та платформи зі спеціальним обладнанням**, що рухаються трамвайними коліями.","ru":"Согласно {p:1.10} рельсовые транспортные средства — **трамвай и платформы со специальным оборудованием**, движущиеся по трамвайным путям."},"ref":["1.10"]},{"id":"h1-44","t":"h1","num":"1.44","q":{"uk":"Дозволеною максимальною масою вважається:","ru":"Разрешённой максимальной массой считается:"},"a":[{"uk":"Маса спорядженого транспортного засобу з вантажем, водієм і пасажирами, що встановлена технічною характеристикою транспортного засобу як максимально допустима.","ru":"Масса снаряжённого транспортного средства с грузом, водителем и пассажирами, установленная технической характеристикой транспортного средства как максимально допустимая."},{"uk":"Вага транспортного засобу з вантажем, водієм і пасажирами, встановлена технічною характеристикою на даний транспортний засіб підприємством-виробником, яка не повинна перевищувати 3500 кг.","ru":"Вес транспортного средства с грузом, водителем и пассажирами, установленный технической характеристикой на данное транспортное средство предприятием-изготовителем, который не должен превышать 3500 кг.","w":{"uk":"Визначення не прив'язане до межі 3500 кг — дозволена максимальна маса вантажівки чи автобуса може бути значно більшою.","ru":"Определение не привязано к пределу 3500 кг — разрешённая максимальная масса грузовика или автобуса может быть значительно больше."}}],"c":0,"e":{"uk":"Це визначення з {p:1.10}: маса спорядженого транспортного засобу з вантажем, водієм і пасажирами, встановлена його технічною характеристикою як **максимально допустима**.","ru":"Это определение из {p:1.10}: масса снаряжённого транспортного средства с грузом, водителем и пассажирами, установленная его технической характеристикой как **максимально допустимая**."},"ref":["1.10"]},{"id":"h1-45","t":"h1","num":"1.45","q":{"uk":"В якому з перелічених випадків водій здійснив вимушену зупинку?","ru":"В каком из перечисленных случаев водитель совершил вынужденную остановку?"},"a":[{"uk":"Зупинився на узбіччі через прокол колеса.","ru":"Остановился на обочине из-за прокола колеса.","w":{"uk":"Неповна відповідь: зупинки через засліплення й для допомоги пасажиру теж вимушені — їх спричинив стан учасника руху.","ru":"Неполный ответ: остановки из-за ослепления и для помощи пассажиру тоже вынужденные — их вызвало состояние участника движения."}},{"uk":"Зупинився на смузі руху через засліплення фарами зустрічного автомобіля.","ru":"Остановился на полосе движения из-за ослепления фарами встречного автомобиля.","w":{"uk":"Неповна відповідь: прокол колеса (технічна несправність) і допомога пасажиру теж зумовлюють вимушену зупинку.","ru":"Неполный ответ: прокол колеса (техническая неисправность) и помощь пассажиру тоже обусловливают вынужденную остановку."}},{"uk":"Зупинився, щоб надати допомогу пасажиру.","ru":"Остановился, чтобы оказать помощь пассажиру.","w":{"uk":"Неповна відповідь: прокол колеса й засліплення водія теж зумовлюють вимушену зупинку.","ru":"Неполный ответ: прокол колеса и ослепление водителя тоже обусловливают вынужденную остановку."}},{"uk":"Відповіді 1, 2, 3.","ru":"Ответы 1, 2, 3."}],"c":3,"e":{"uk":"Вимушена зупинка за {p:1.10} — припинення руху через технічну несправність (прокол колеса) або стан учасника дорожнього руху (засліплення водія — {p:19.3}, погане самопочуття пасажира); підходять усі три випадки.","ru":"Вынужденная остановка согласно {p:1.10} — прекращение движения из-за технической неисправности (прокол колеса) или состояния участника дорожного движения (ослепление водителя — {p:19.3}, плохое самочувствие пассажира); подходят все три случая."},"ref":["1.10","19.3"]},{"id":"h1-46","t":"h1","num":"1.46","q":{"uk":"До маршрутних транспортних засобів (транспортних засобів загального користування) належать:","ru":"К маршрутным транспортным средствам (транспортным средствам общего пользования) относятся:"},"a":[{"uk":"Трамваї, тролейбуси, автобуси, таксі.","ru":"Трамваи, троллейбусы, автобусы, такси.","w":{"uk":"Не будь-яке таксі чи автобус маршрутні — вирішальна ознака саме рух за встановленим маршрутом; до того ж тут пропущено мікроавтобуси.","ru":"Не всякое такси или автобус маршрутные — решающий признак именно движение по установленному маршруту; к тому же здесь пропущены микроавтобусы."}},{"uk":"Транспортні засоби з кількістю місць для сидіння не менш ніж сімнадцять з місцем водія включно, що рухаються за встановленими маршрутами та мають визначені місця на дорозі для посадки (висадки) пасажирів.","ru":"Транспортные средства с количеством мест для сидения не менее семнадцати, включая место водителя, движущиеся по установленным маршрутам и имеющие определённые места на дороге для посадки (высадки) пассажиров.","w":{"uk":"Кількість місць для сидіння не є ознакою маршрутного транспортного засобу: маршрутним може бути й таксі чи мікроавтобус.","ru":"Количество мест для сидения не является признаком маршрутного транспортного средства: маршрутным может быть и такси, и микроавтобус."}},{"uk":"Автобуси, мікроавтобуси, тролейбуси, трамваї і таксі, що рухаються за встановленими маршрутами та мають визначені місця на дорозі для посадки (висадки) пасажирів.","ru":"Автобусы, микроавтобусы, троллейбусы, трамваи и такси, движущиеся по установленным маршрутам и имеющие определённые места на дороге для посадки (высадки) пассажиров."}],"c":2,"e":{"uk":"Повне визначення з {p:1.10}: маршрутними є автобуси, мікроавтобуси, тролейбуси, трамваї й таксі, що **рухаються за встановленими маршрутами** і мають визначені місця для посадки (висадки) пасажирів.","ru":"Полное определение из {p:1.10}: маршрутными являются автобусы, микроавтобусы, троллейбусы, трамваи и такси, которые **движутся по установленным маршрутам** и имеют определённые места для посадки (высадки) пассажиров."},"ref":["1.10"]},{"id":"h1-47","t":"h1","num":"1.47","q":{"uk":"Оглядовістю вважається:","ru":"Обзорностью считается:"},"a":[{"uk":"Об’єктивна можливість бачити дорожню обстановку з місця водія.","ru":"Объективная возможность видеть дорожную обстановку с места водителя."},{"uk":"Видимість дороги в напрямку руху, яка обмежена геометричними параметрами дороги.","ru":"Видимость дороги в направлении движения, ограниченная геометрическими параметрами дороги.","w":{"uk":"Це частина визначення обмеженої оглядовості, а не оглядовості загалом.","ru":"Это часть определения ограниченной обзорности, а не обзорности вообще."}},{"uk":"Максимальна відстань, на якій з місця водія можна чітко розпізнати межі елементів дороги та розміщення учасників руху.","ru":"Максимальное расстояние, на котором с места водителя можно чётко распознать границы элементов дороги и расположение участников движения.","w":{"uk":"Це визначення видимості в напрямку руху.","ru":"Это определение видимости в направлении движения."}}],"c":0,"e":{"uk":"Це визначення **оглядовості** з {p:1.10}.","ru":"Это определение **обзорности** из {p:1.10}."},"ref":["1.10"]},{"id":"h1-48","t":"h1","num":"1.48","q":{"uk":"Обмежена оглядовість – це видимість дороги в напрямку руху, яка обмежена:","ru":"Ограниченная обзорность — это видимость дороги в направлении движения, ограниченная:"},"a":[{"uk":"Геометричними параметрами дороги.","ru":"Геометрическими параметрами дороги.","w":{"uk":"Неповна відповідь: оглядовість обмежують також придорожні споруди, насадження, інші об'єкти й транспортні засоби.","ru":"Неполный ответ: обзорность ограничивают также придорожные сооружения, насаждения, другие объекты и транспортные средства."}},{"uk":"Придорожніми інженерними спорудами, насадженнями та іншими об’єктами, а також транспортними засобами.","ru":"Придорожными инженерными сооружениями, насаждениями и другими объектами, а также транспортными средствами.","w":{"uk":"Неповна відповідь: оглядовість обмежують також геометричні параметри дороги — повороти, підйоми, спуски.","ru":"Неполный ответ: обзорность ограничивают также геометрические параметры дороги — повороты, подъёмы, спуски."}},{"uk":"Погодними явищами, такими як дощ, снігопад, туман і тощо","ru":"Погодными явлениями, такими как дождь, снегопад, туман и т. п.","w":{"uk":"Погодні явища спричиняють недостатню видимість, а не обмежену оглядовість.","ru":"Погодные явления вызывают недостаточную видимость, а не ограниченную обзорность."}},{"uk":"Відповіді 1, 2.","ru":"Ответы 1, 2."}],"c":3,"e":{"uk":"Визначення обмеженої оглядовості в {p:1.10} називає **обидві** групи причин: геометричні параметри дороги та придорожні споруди, насадження, інші об'єкти й транспортні засоби.","ru":"Определение ограниченной обзорности в {p:1.10} называет **обе** группы причин: геометрические параметры дороги и придорожные сооружения, насаждения, другие объекты и транспортные средства."},"ref":["1.10"]},{"id":"h1-49","t":"h1","num":"1.49","q":{"uk":"З якого боку дозволено виконати випередження на проїзній частині?","ru":"С какой стороны разрешено выполнить опережение на проезжей части?"},"a":[{"uk":"Тільки з лівого боку.","ru":"Только с левой стороны.","w":{"uk":"Лише ліворуч дозволено обгін нерейкових транспортних засобів ({p:14.1}), а для випередження такого обмеження немає.","ru":"Только слева разрешён обгон нерельсовых транспортных средств ({p:14.1}), а для опережения такого ограничения нет."}},{"uk":"Тільки з правого боку.","ru":"Только с правой стороны.","w":{"uk":"Правила не обмежують випередження правим боком: воно можливе по будь-якій суміжній смузі.","ru":"Правила не ограничивают опережение правой стороной: оно возможно по любой соседней полосе."}},{"uk":"З будь-якого боку по суміжній смузі з дотриманням безпечного інтервалу.","ru":"С любой стороны по соседней полосе с соблюдением безопасного интервала."}],"c":2,"e":{"uk":"Визначення випередження в {p:1.10} не обмежує бік — достатньо рухатися швидше за попутний транспортний засіб по суміжній смузі; при цьому треба дотримувати безпечного інтервалу ({p:13.3}).","ru":"Определение опережения в {p:1.10} не ограничивает сторону — достаточно двигаться быстрее попутного транспортного средства по соседней полосе; при этом нужно соблюдать безопасный интервал ({p:13.3})."},"ref":["1.10","13.3"]},{"id":"h1-50","t":"h1","num":"1.50","q":{"uk":"Що з переліченого є прилеглою територією?","ru":"Что из перечисленного является прилегающей территорией?"},"a":[{"uk":"Місце перехрещення, прилягання або розгалуження доріг на одному рівні.","ru":"Место пересечения, примыкания или разветвления дорог на одном уровне.","w":{"uk":"Це визначення перехрестя, а не прилеглої території.","ru":"Это определение перекрёстка, а не прилегающей территории."}},{"uk":"Територія, що прилягає до краю проїзної частини та не призначена для наскрізного проїзду, а лише для в’їзду до дворів, на стоянки, автозаправні станції, будівельні майданчики тощо або виїзду з них.","ru":"Территория, прилегающая к краю проезжей части и не предназначенная для сквозного проезда, а только для въезда во дворы, на стоянки, автозаправочные станции, строительные площадки и т. п. или выезда из них."},{"uk":"Місце для в’їзду до дворів, на стоянки, автозаправні станції, будівельні майданчики тощо або виїзду з них.","ru":"Место для въезда во дворы, на стоянки, автозаправочные станции, строительные площадки и т. п. или выезда из них.","w":{"uk":"Неповне визначення: бракує ключових ознак — прилягання до краю проїзної частини й непризначеності для наскрізного проїзду.","ru":"Неполное определение: не хватает ключевых признаков — примыкания к краю проезжей части и непредназначенности для сквозного проезда."}},{"uk":"Відповідь 1 та 3.","ru":"Ответ 1 и 3.","w":{"uk":"Варіант 1 описує перехрестя, а варіант 3 — неповне визначення.","ru":"Вариант 1 описывает перекрёсток, а вариант 3 — неполное определение."}}],"c":1,"e":{"uk":"Це повне визначення прилеглої території з {p:1.10}: вона прилягає до краю проїзної частини і **не призначена для наскрізного проїзду**.","ru":"Это полное определение прилегающей территории из {p:1.10}: она прилегает к краю проезжей части и **не предназначена для сквозного проезда**."},"ref":["1.10"]},{"id":"h1-51","t":"h1","num":"1.51","q":{"uk":"Розділювальна смуга призначена:","ru":"Разделительная полоса предназначена:"},"a":[{"uk":"Для зупинки та стоянки транспортних засобів.","ru":"Для остановки и стоянки транспортных средств.","w":{"uk":"Розділювальна смуга прямо не призначена для стоянки транспортних засобів ({p:1.10}).","ru":"Разделительная полоса прямо не предназначена для стоянки транспортных средств ({p:1.10})."}},{"uk":"Для руху велосипедистів за умови відсутності велосипедної доріжки.","ru":"Для движения велосипедистов при отсутствии велосипедной дорожки.","w":{"uk":"Велосипед — теж транспортний засіб, а розділювальна смуга для руху транспортних засобів не призначена.","ru":"Велосипед — тоже транспортное средство, а разделительная полоса для движения транспортных средств не предназначена."}},{"uk":"Для розділення суміжних проїзних частин та руху пішоходів за наявності на ній тротуару.","ru":"Для разделения смежных проезжих частей и движения пешеходов при наличии на ней тротуара."}],"c":2,"e":{"uk":"За {p:1.10} розділювальна смуга розділяє суміжні проїзні частини і не призначена для руху чи стоянки транспортних засобів; пішоходи можуть рухатися нею, лише якщо на ній є тротуар.","ru":"Согласно {p:1.10} разделительная полоса разделяет смежные проезжие части и не предназначена для движения или стоянки транспортных средств; пешеходы могут двигаться по ней, только если на ней есть тротуар."},"ref":["1.10"],"pic":["img/hsc/1-51-1.jpg"]},{"id":"h1-52","t":"h1","num":"1.52","q":{"uk":"Який елемент автомобільної дороги зображено на наведеному малюнку?","ru":"Какой элемент автомобильной дороги изображён на приведённом рисунке?"},"a":[{"uk":"Розділювальна смуга.","ru":"Разделительная полоса."},{"uk":"Тротуар.","ru":"Тротуар.","w":{"uk":"Тротуар призначений для пішоходів і проходить уздовж краю дороги, а не між зустрічними проїзними частинами.","ru":"Тротуар предназначен для пешеходов и проходит вдоль края дороги, а не между встречными проезжими частями."}},{"uk":"Узбіччя.","ru":"Обочина.","w":{"uk":"Узбіччя прилягає до зовнішнього краю проїзної частини, а не розділяє дві проїзні частини.","ru":"Обочина прилегает к внешнему краю проезжей части, а не разделяет две проезжие части."}},{"uk":"Газон.","ru":"Газон.","w":{"uk":"Покриття смуги може бути трав'яним, але як елемент дороги, що розділяє суміжні проїзні частини, вона називається розділювальною смугою.","ru":"Покрытие полосы может быть травяным, но как элемент дороги, разделяющий смежные проезжие части, она называется разделительной полосой."}}],"c":0,"e":{"uk":"Зелена смуга конструктивно відокремлює дві суміжні проїзні частини протилежних напрямків — це **розділювальна смуга** ({p:1.10}).","ru":"Зелёная полоса конструктивно отделяет две смежные проезжие части противоположных направлений — это **разделительная полоса** ({p:1.10})."},"ref":["1.10"],"pic":["img/hsc/1-52-1.jpg"]},{"id":"h1-53","t":"h1","num":"1.53","q":{"uk":"Чи призначена розділювальна смуга для руху або стоянки транспортних засобів?","ru":"Предназначена ли разделительная полоса для движения или стоянки транспортных средств?"},"a":[{"uk":"Так, призначена.","ru":"Да, предназначена.","w":{"uk":"Розділювальна смуга лише розділяє суміжні проїзні частини; рух і стоянка на ній не передбачені.","ru":"Разделительная полоса лишь разделяет смежные проезжие части; движение и стоянка на ней не предусмотрены."}},{"uk":"Ні, не призначена.","ru":"Нет, не предназначена."}],"c":1,"e":{"uk":"За {p:1.10} розділювальна смуга, виділена конструктивно або суцільними лініями розмітки {m:1.2} (як на малюнку), **не призначена** для руху або стоянки транспортних засобів.","ru":"Согласно {p:1.10} разделительная полоса, выделенная конструктивно или сплошными линиями разметки {m:1.2} (как на рисунке), **не предназначена** для движения или стоянки транспортных средств."},"ref":["1.10"],"pic":["img/hsc/1-53-1.jpg"]},{"id":"h1-54","t":"h1","num":"1.54","q":{"uk":"Засліплення це:","ru":"Ослепление — это:"},"a":[{"uk":"Фізіологічний стан водія внаслідок дії світла на його зір, коли водій об’єктивно не має можливості виявити перешкоди чи розпізнати межі елементів дороги на мінімальній відстані.","ru":"Физиологическое состояние водителя вследствие воздействия света на его зрение, когда водитель объективно не имеет возможности обнаружить препятствия или распознать границы элементов дороги на минимальном расстоянии."},{"uk":"Фізіологічний стан водія внаслідок дії світла на його зір, коли на деякий час видимість для водія стає поганою, але він має можливість виявити перешкоди чи розпізнати межі елементів дороги на мінімальній відстані.","ru":"Физиологическое состояние водителя вследствие воздействия света на его зрение, когда на некоторое время видимость для водителя становится плохой, но он имеет возможность обнаружить препятствия или распознать границы элементов дороги на минимальном расстоянии.","w":{"uk":"Якщо водій ще бачить перешкоди й межі дороги на мінімальній відстані, це погіршення видимості, а не засліплення в розумінні Правил.","ru":"Если водитель ещё видит препятствия и границы дороги на минимальном расстоянии, это ухудшение видимости, а не ослепление в понимании Правил."}}],"c":0,"e":{"uk":"Це визначення засліплення з {p:1.10}: ключова ознака — водій **об'єктивно не має можливості** виявити перешкоди чи розпізнати межі елементів дороги навіть на мінімальній відстані.","ru":"Это определение ослепления из {p:1.10}: ключевой признак — водитель **объективно не имеет возможности** обнаружить препятствия или распознать границы элементов дороги даже на минимальном расстоянии."},"ref":["1.10"]},{"id":"h1-55","t":"h1","num":"1.55","q":{"uk":"Чи зобов’язані водії бути особливо уважними до велосипедистів?","ru":"Обязаны ли водители быть особенно внимательными к велосипедистам?"},"a":[{"uk":"Так, зобов’язані.","ru":"Да, обязаны."},{"uk":"Ні, не зобов’язані.","ru":"Нет, не обязаны.","w":{"uk":"Велосипедисти названі в {p:1.7} серед учасників руху, до яких водії мають бути особливо уважними.","ru":"Велосипедисты названы в {p:1.7} среди участников движения, к которым водители должны быть особенно внимательны."}}],"c":0,"e":{"uk":"{p:1.7} прямо зобов'язує водіїв бути особливо уважними до велосипедистів, осіб у кріслах колісних і пішоходів.","ru":"{p:1.7} прямо обязывает водителей быть особенно внимательными к велосипедистам, лицам в креслах-колясках и пешеходам."},"ref":["1.7"],"pic":["img/hsc/1-55-1.jpg"]},{"id":"h1-56","t":"h1","num":"1.56","q":{"uk":"Особи, які ведуть мотоцикл прирівнюються до:","ru":"Лица, ведущие мотоцикл, приравниваются к:"},"a":[{"uk":"Водіїв.","ru":"Водителям.","w":{"uk":"Водій керує транспортним засобом під час руху, а особа, яка веде мотоцикл, іде пішки поруч із ним.","ru":"Водитель управляет транспортным средством во время движения, а лицо, ведущее мотоцикл, идёт пешком рядом с ним."}},{"uk":"Пішоходів.","ru":"Пешеходам."},{"uk":"Велосипедистів.","ru":"Велосипедистам.","w":{"uk":"Велосипедист — це особа, яка керує велосипедом; до того, хто веде мотоцикл, цей термін не стосується.","ru":"Велосипедист — это лицо, управляющее велосипедом; к тому, кто ведёт мотоцикл, этот термин не относится."}}],"c":1,"e":{"uk":"За {p:1.10} до пішоходів прирівнюються особи, які **ведуть** велосипед, мопед чи мотоцикл, — як чоловік на малюнку, що котить мотоцикл поруч із собою.","ru":"Согласно {p:1.10} к пешеходам приравниваются лица, которые **ведут** велосипед, мопед или мотоцикл, — как мужчина на рисунке, катящий мотоцикл рядом с собой."},"ref":["1.10"],"pic":["img/hsc/1-56-1.jpg"]},{"id":"h1-57","t":"h1","num":"1.57","q":{"uk":"Особи, які ведуть мотоцикл прирівнюються до пішоходів?","ru":"Приравниваются ли лица, ведущие мотоцикл, к пешеходам?"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"Особа не керує мотоциклом, а котить його поруч, тому за Правилами вона пішохід.","ru":"Лицо не управляет мотоциклом, а катит его рядом, поэтому по Правилам оно пешеход."}}],"c":0,"e":{"uk":"Визначення пішохода в {p:1.10} прямо включає осіб, які **ведуть** мотоцикл, як на малюнку.","ru":"Определение пешехода в {p:1.10} прямо включает лиц, которые **ведут** мотоцикл, как на рисунке."},"ref":["1.10"],"pic":["img/hsc/1-57-1.jpg"]},{"id":"h1-58","t":"h1","num":"1.58","q":{"uk":"Чи прирівнюються до пішоходів особи, які везуть дитячий візок?","ru":"Приравниваются ли к пешеходам лица, везущие детскую коляску?"},"a":[{"uk":"Так, прирівнюються.","ru":"Да, приравниваются."},{"uk":"Ні, не прирівнюються.","ru":"Нет, не приравниваются.","w":{"uk":"Особи з дитячою коляскою чи візком названі в {p:1.10} серед прирівняних до пішоходів.","ru":"Лица с детской коляской или тележкой названы в {p:1.10} среди приравненных к пешеходам."}}],"c":0,"e":{"uk":"Визначення пішохода в {p:1.10} прямо згадує осіб, які везуть дитячу коляску.","ru":"Определение пешехода в {p:1.10} прямо упоминает лиц, везущих детскую коляску."},"ref":["1.10"],"pic":["img/hsc/1-58-1.jpg"]},{"id":"h1-59","t":"h1","num":"1.59","q":{"uk":"Особи, які рухаються у кріслах колісних, є учасниками дорожнього руху?","ru":"Являются ли лица, передвигающиеся в креслах-колясках, участниками дорожного движения?"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"Особи в кріслах колісних прямо названі учасниками дорожнього руху, а Правила присвячують їм окремі пункти ({p:4.17}).","ru":"Лица в креслах-колясках прямо названы участниками дорожного движения, а Правила посвящают им отдельные пункты ({p:4.17})."}}],"c":0,"e":{"uk":"Визначення учасника дорожнього руху в {p:1.10} окремо називає особу, яка рухається в кріслі колісному.","ru":"Определение участника дорожного движения в {p:1.10} отдельно называет лицо, передвигающееся в кресле-коляске."},"ref":["1.10"],"pic":["img/hsc/1-59-1.jpg"]},{"id":"h1-60","t":"h1","num":"1.60","q":{"uk":"Чи відноситься штучна споруда (естакада, шляхопровід, міст тощо), яка призначена для руху транспортних засобів до елемента автомобільної дороги?","ru":"Относится ли искусственное сооружение (эстакада, путепровод, мост и т. п.), предназначенное для движения транспортных средств, к элементу автомобильной дороги?"},"a":[{"uk":"Так, відноситься.","ru":"Да, относится."},{"uk":"Ні, не відноситься.","ru":"Нет, не относится.","w":{"uk":"Визначення автомобільної дороги прямо охоплює мости, шляхопроводи й естакади.","ru":"Определение автомобильной дороги прямо охватывает мосты, путепроводы и эстакады."}}],"c":0,"e":{"uk":"За {p:1.10} автомобільна дорога включає всі розташовані на ній споруди — мости, шляхопроводи, естакади, надземні й підземні пішохідні переходи.","ru":"Согласно {p:1.10} автомобильная дорога включает все расположенные на ней сооружения — мосты, путепроводы, эстакады, надземные и подземные пешеходные переходы."},"ref":["1.10"]},{"id":"h1-61","t":"h1","num":"1.61","q":{"uk":"Інженерна споруда призначена для руху транспортних засобів та/або пішоходів, підняття однієї дороги над іншою у місці їх перетину та не має з’їздів на іншу дорогу це:","ru":"Инженерное сооружение, предназначенное для движения транспортных средств и/или пешеходов, подъёма одной дороги над другой в месте их пересечения и не имеющее съездов на другую дорогу, — это:"},"a":[{"uk":"Естакада.","ru":"Эстакада."},{"uk":"Міст.","ru":"Мост.","w":{"uk":"Міст споруджують для руху через річку, яр та інші перешкоди, а не для підняття однієї дороги над іншою.","ru":"Мост сооружают для движения через реку, овраг и другие препятствия, а не для подъёма одной дороги над другой."}},{"uk":"Шляхопровід.","ru":"Путепровод.","w":{"uk":"Шляхопровід, на відміну від естакади, дає можливість з'їзду на іншу дорогу.","ru":"Путепровод, в отличие от эстакады, даёт возможность съезда на другую дорогу."}}],"c":0,"e":{"uk":"Це визначення **естакади** з {p:1.10}; головна відмінність від шляхопроводу — естакада **не має з'їздів** на іншу дорогу.","ru":"Это определение **эстакады** из {p:1.10}; главное отличие от путепровода — эстакада **не имеет съездов** на другую дорогу."},"ref":["1.10"]},{"id":"h1-62","t":"h1","num":"1.62","q":{"uk":"Який транспортний засіб призначений для руху тільки в з’єднанні з іншим транспортним засобом?","ru":"Какое транспортное средство предназначено для движения только в соединении с другим транспортным средством?"},"a":[{"uk":"Причіп.","ru":"Прицеп."},{"uk":"Автопоїзд.","ru":"Автопоезд.","w":{"uk":"Автопоїзд — це вже з'єднані механічний транспортний засіб і причіп (причепи), який рухається сам, а не засіб, що потребує з'єднання.","ru":"Автопоезд — это уже соединённые механическое транспортное средство и прицеп (прицепы), который движется сам, а не средство, нуждающееся в соединении."}},{"uk":"Рейковий транспортний засіб.","ru":"Рельсовое транспортное средство.","w":{"uk":"Рейковий транспортний засіб (трамвай) рухається трамвайною колією самостійно.","ru":"Рельсовое транспортное средство (трамвай) движется по трамвайным путям самостоятельно."}}],"c":0,"e":{"uk":"Це визначення **причепа** з {p:1.10}; до причепів належать також напівпричепи й причепи-розпуски.","ru":"Это определение **прицепа** из {p:1.10}; к прицепам относятся также полуприцепы и прицепы-роспуски."},"ref":["1.10"]},{"id":"h1-63","t":"h1","num":"1.63","q":{"uk":"Чи дозволено пішоходам рухатись узбіччям?","ru":"Разрешено ли пешеходам двигаться по обочине?"},"a":[{"uk":"Дозволено, за відсутності тротуарів, пішохідних доріжок.","ru":"Разрешено при отсутствии тротуаров, пешеходных дорожек."},{"uk":"Дозволено за будь-яких умов.","ru":"Разрешено при любых условиях.","w":{"uk":"Узбіччям пішоходи йдуть лише тоді, коли немає тротуарів і пішохідних доріжок або рух ними неможливий.","ru":"По обочине пешеходы идут лишь тогда, когда нет тротуаров и пешеходных дорожек или движение по ним невозможно."}},{"uk":"Заборонено.","ru":"Запрещено.","w":{"uk":"Рух пішоходів узбіччям прямо передбачений {p:4.1} і визначенням узбіччя в {p:1.10}.","ru":"Движение пешеходов по обочине прямо предусмотрено {p:4.1} и определением обочины в {p:1.10}."}}],"c":0,"e":{"uk":"За {p:4.1} пішоходи рухаються тротуарами й пішохідними доріжками, а якщо їх немає або пересуватися ними неможливо, — зокрема в один ряд узбіччям.","ru":"Согласно {p:4.1} пешеходы движутся по тротуарам и пешеходным дорожкам, а если их нет или передвигаться по ним невозможно, — в частности, в один ряд по обочине."},"ref":["4.1","1.10"]},{"id":"h1-64","t":"h1","num":"1.64","q":{"uk":"Чи призначено узбіччя для руху транспортних засобів?","ru":"Предназначена ли обочина для движения транспортных средств?"},"a":[{"uk":"Так, призначено.","ru":"Да, предназначена.","w":{"uk":"Узбіччя не є проїзною частиною; рух ним дозволено лише у випадках, прямо передбачених Правилами.","ru":"Обочина не является проезжей частью; движение по ней разрешено лишь в случаях, прямо предусмотренных Правилами."}},{"uk":"Ні, не призначено, крім випадків, передбачених Правилами дорожнього руху.","ru":"Нет, не предназначена, кроме случаев, предусмотренных Правилами дорожного движения."}],"c":1,"e":{"uk":"За {p:1.10} узбіччя **не призначене** для руху транспортних засобів, крім випадків, передбачених Правилами (наприклад, рух мопедів і велосипедів за відсутності велосипедних доріжок).","ru":"Согласно {p:1.10} обочина **не предназначена** для движения транспортных средств, кроме случаев, предусмотренных Правилами (например, движения мопедов и велосипедов при отсутствии велосипедных дорожек)."},"ref":["1.10"]},{"id":"h1-65","t":"h1","num":"1.65","q":{"uk":"У наведеному випадку суцільна лінія дорожньої розмітки вважається межею проїзної частини та узбіччя?","ru":"В приведённом случае сплошная линия дорожной разметки считается границей проезжей части и обочины?"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"Лінія {m:1.2} якраз і позначає край проїзної частини, відокремлюючи її від узбіччя.","ru":"Линия {m:1.2} как раз и обозначает край проезжей части, отделяя её от обочины."}}],"c":0,"e":{"uk":"Суцільна лінія біля правого краю дороги — розмітка {m:1.2}, що позначає край проїзної частини ({p:34.1}); за {p:1.10} узбіччя може бути виділене саме суцільною лінією розмітки, тож праворуч від неї — узбіччя.","ru":"Сплошная линия у правого края дороги — разметка {m:1.2}, обозначающая край проезжей части ({p:34.1}); согласно {p:1.10} обочина может быть выделена именно сплошной линией разметки, поэтому справа от неё — обочина."},"ref":["1.10","34.1"],"pic":["img/hsc/1-65-1.jpg"]},{"id":"h1-66","t":"h1","num":"1.66","q":{"uk":"На наведеному малюнку зображено узбіччя?","ru":"На приведённом рисунке изображена обочина?"},"a":[{"uk":"Так.","ru":"Да.","w":{"uk":"Узбіччя розташоване на одному рівні з проїзною частиною, а цей елемент дороги піднятий і відокремлений бордюром — це тротуар.","ru":"Обочина расположена на одном уровне с проезжей частью, а этот элемент дороги поднят и отделён бордюром — это тротуар."}},{"uk":"Ні.","ru":"Нет."}],"c":1,"e":{"uk":"Стрілка вказує на піднятий бордюром тротуар, яким іде пішохід. Узбіччя ж за {p:1.10} розташоване **на одному рівні** з проїзною частиною, тож це не узбіччя.","ru":"Стрелка указывает на поднятый бордюром тротуар, по которому идёт пешеход. Обочина же согласно {p:1.10} расположена **на одном уровне** с проезжей частью, поэтому это не обочина."},"ref":["1.10"],"pic":["img/hsc/1-66-1.jpg"]},{"id":"h1-67","t":"h1","num":"1.67","q":{"uk":"Технічний засіб регулювання дорожнього руху на наземних пішохідних переходах, конструктивно виділений над проїзною частиною дороги та призначений як захисний елемент для зупинки пішоходів під час переходу проїзної частини дороги це:","ru":"Техническое средство регулирования дорожного движения на наземных пешеходных переходах, конструктивно выделенное над проезжей частью дороги и предназначенное как защитный элемент для остановки пешеходов во время перехода проезжей части дороги, — это:"},"a":[{"uk":"Острівець безпеки.","ru":"Островок безопасности."},{"uk":"Пішохідна доріжка.","ru":"Пешеходная дорожка.","w":{"uk":"Пішохідна доріжка призначена для руху пішоходів у межах дороги чи поза нею і позначається знаком {s:4.16}.","ru":"Пешеходная дорожка предназначена для движения пешеходов в пределах дороги или вне её и обозначается знаком {s:4.16}."}},{"uk":"Тротуар.","ru":"Тротуар.","w":{"uk":"Тротуар прилягає до проїзної частини збоку і призначений для руху пішоходів, а не для зупинки посеред переходу.","ru":"Тротуар прилегает к проезжей части сбоку и предназначен для движения пешеходов, а не для остановки посреди перехода."}}],"c":0,"e":{"uk":"Це визначення **острівця безпеки** з {p:1.10}.","ru":"Это определение **островка безопасности** из {p:1.10}."},"ref":["1.10"]},{"id":"h1-68","t":"h1","num":"1.68","q":{"uk":"Чи призначений острівець безпеки для посадки (висадки) пасажирів маршрутних транспортних засобів?","ru":"Предназначен ли островок безопасности для посадки (высадки) пассажиров маршрутных транспортных средств?"},"a":[{"uk":"Так, призначений.","ru":"Да, предназначен.","w":{"uk":"Призначення острівця безпеки — захищати пішоходів, які переходять дорогу; для посадки пасажирів існують посадкові майданчики.","ru":"Назначение островка безопасности — защищать пешеходов, переходящих дорогу; для посадки пассажиров существуют посадочные площадки."}},{"uk":"Ні, не призначений.","ru":"Нет, не предназначен."}],"c":1,"e":{"uk":"За {p:1.10} острівець безпеки — захисний елемент для зупинки **пішоходів під час переходу** проїзної частини; посадки й висадки пасажирів його призначення не передбачає.","ru":"Согласно {p:1.10} островок безопасности — защитный элемент для остановки **пешеходов во время перехода** проезжей части; посадку и высадку пассажиров его назначение не предусматривает."},"ref":["1.10"]},{"id":"h1-69","t":"h1","num":"1.69","q":{"uk":"Припинення руху транспортного засобу через його технічну несправність чи небезпеку, яка спричинена вантажем, який перевозиться, станом учасника дорожнього руху, появою перешкоди для руху відноситься до терміну:","ru":"Прекращение движения транспортного средства из-за его технической неисправности или опасности, вызванной перевозимым грузом, состоянием участника дорожного движения, появлением препятствия для движения, относится к термину:"},"a":[{"uk":"Дорожньо-транспортна пригода.","ru":"Дорожно-транспортное происшествие.","w":{"uk":"ДТП — подія, внаслідок якої загинули чи поранені люди або завдано матеріальних збитків; сама зупинка нею не є.","ru":"ДТП — событие, в результате которого погибли или ранены люди либо причинён материальный ущерб; сама остановка им не является."}},{"uk":"Вимушена зупинка.","ru":"Вынужденная остановка."},{"uk":"Стоянка.","ru":"Стоянка.","w":{"uk":"Стоянка — припинення руху понад 5 хвилин з власної волі водія, а не через несправність чи небезпеку.","ru":"Стоянка — прекращение движения более 5 минут по собственной воле водителя, а не из-за неисправности или опасности."}}],"c":1,"e":{"uk":"Це визначення **вимушеної зупинки** з {p:1.10}.","ru":"Это определение **вынужденной остановки** из {p:1.10}."},"ref":["1.10"]},{"id":"h1-70","t":"h1","num":"1.70","q":{"uk":"Перехрещення дороги із залізничними коліями на одному рівні вважається:","ru":"Пересечение дороги с железнодорожными путями на одном уровне считается:"},"a":[{"uk":"Регульованим перехрестям.","ru":"Регулируемым перекрёстком.","w":{"uk":"Перехрестя — місце перехрещення доріг, а не дороги із залізничними коліями.","ru":"Перекрёсток — место пересечения дорог, а не дороги с железнодорожными путями."}},{"uk":"Залізничним переїздом.","ru":"Железнодорожным переездом."},{"uk":"Шляхопроводом.","ru":"Путепроводом.","w":{"uk":"Шляхопровід забезпечує перетин на **різних** рівнях, а тут перехрещення на одному рівні.","ru":"Путепровод обеспечивает пересечение в **разных** уровнях, а здесь пересечение на одном уровне."}}],"c":1,"e":{"uk":"Це визначення **залізничного переїзду** з {p:1.10}.","ru":"Это определение **железнодорожного переезда** из {p:1.10}."},"ref":["1.10"]},{"id":"h1-71","t":"h1","num":"1.71","q":{"uk":"Частина території, зокрема, в населеному пункті, з усіма розташованими на ній спорудами та засобами організації дорожнього руху, призначена для руху транспортних засобів і пішоходів та обмежена по ширині зовнішнім краєм тротуарів чи краєм смуги відводу, вважається:","ru":"Часть территории, в том числе в населённом пункте, со всеми расположенными на ней сооружениями и средствами организации дорожного движения, предназначенная для движения транспортных средств и пешеходов и ограниченная по ширине внешним краем тротуаров или краем полосы отвода, считается:"},"a":[{"uk":"Автомагістраллю.","ru":"Автомагистралью.","w":{"uk":"Автомагістраль — особливий вид дороги з окремими проїзними частинами для кожного напрямку, без перетинів на одному рівні, позначений знаком {s:5.1}.","ru":"Автомагистраль — особый вид дороги с отдельными проезжими частями для каждого направления, без пересечений на одном уровне, обозначенный знаком {s:5.1}."}},{"uk":"Автомобільною дорогою, вулицею (дорогою).","ru":"Автомобильной дорогой, улицей (дорогой)."},{"uk":"Проїзною частиною.","ru":"Проезжей частью.","w":{"uk":"Проїзна частина — лише один елемент дороги для нерейкових транспортних засобів; тротуари й узбіччя до неї не входять.","ru":"Проезжая часть — лишь один элемент дороги для нерельсовых транспортных средств; тротуары и обочины в неё не входят."}}],"c":1,"e":{"uk":"Це визначення **автомобільної дороги, вулиці (дороги)** з {p:1.10}.","ru":"Это определение **автомобильной дороги, улицы (дороги)** из {p:1.10}."},"ref":["1.10"]},{"id":"h1-72","t":"h1","num":"1.72","q":{"uk":"Пішохідний перехід призначений для руху:","ru":"Пешеходный переход предназначен для движения:"},"a":[{"uk":"Пішоходів через дорогу.","ru":"Пешеходов через дорогу."},{"uk":"На велосипедах.","ru":"На велосипедах.","w":{"uk":"Для перетину проїзної частини на велосипедах призначений велосипедний переїзд, позначений розміткою {m:1.15}.","ru":"Для пересечения проезжей части на велосипедах предназначен велосипедный переезд, обозначенный разметкой {m:1.15}."}},{"uk":"Варіант 1 і 2.","ru":"Вариант 1 и 2.","w":{"uk":"Велосипедистам пішохідний перехід не призначений — вони переїжджають проїзну частину по велосипедному переїзду ({p:6.5}).","ru":"Велосипедистам пешеходный переход не предназначен — они пересекают проезжую часть по велосипедному переезду ({p:6.5})."}}],"c":0,"e":{"uk":"За {p:1.10} пішохідний перехід — ділянка проїзної частини або інженерна споруда, призначена для руху **пішоходів через дорогу**.","ru":"Согласно {p:1.10} пешеходный переход — участок проезжей части или инженерное сооружение, предназначенные для движения **пешеходов через дорогу**."},"ref":["1.10"]},{"id":"h1-73","t":"h1","num":"1.73","q":{"uk":"Зовнішні світлові прилади білого кольору, передбачені конструкцією транспортного засобу, установлені спереду транспортного засобу і призначені для покращення видимості транспортного засобу під час його руху у світлий час доби це:","ru":"Внешние световые приборы белого цвета, предусмотренные конструкцией транспортного средства, установленные спереди транспортного средства и предназначенные для улучшения видимости транспортного средства во время его движения в светлое время суток, — это:"},"a":[{"uk":"Габаритні ліхтарі.","ru":"Габаритные огни.","w":{"uk":"Габаритні ліхтарі позначають габарити транспортного засобу спереду й ззаду (ззаду — червоні) і не призначені саме для світлого часу доби.","ru":"Габаритные огни обозначают габариты транспортного средства спереди и сзади (сзади — красные) и не предназначены именно для светлого времени суток."}},{"uk":"Денні ходові вогні.","ru":"Дневные ходовые огни."},{"uk":"Ближнє світло фар.","ru":"Ближний свет фар.","w":{"uk":"Ближнє світло фар освітлює дорогу і використовується передусім у темну пору доби та в умовах недостатньої видимості; описані вогні — окремий прилад.","ru":"Ближний свет фар освещает дорогу и используется прежде всего в тёмное время суток и в условиях недостаточной видимости; описанные огни — отдельный прибор."}}],"c":1,"e":{"uk":"Це визначення **денних ходових вогнів** з {p:1.10}.","ru":"Это определение **дневных ходовых огней** из {p:1.10}."},"ref":["1.10"]},{"id":"h1-74","t":"h1","num":"1.74","q":{"uk":"Яка із наведених категорій осіб не прирівнюється до пішоходів?","ru":"Какая из перечисленных категорий лиц не приравнивается к пешеходам?"},"a":[{"uk":"Особи, які рухаються в кріслах колісних без двигуна.","ru":"Лица, передвигающиеся в креслах-колясках без двигателя.","w":{"uk":"Особи в кріслах колісних без двигуна прямо прирівнюються до пішоходів ({p:1.10}).","ru":"Лица в креслах-колясках без двигателя прямо приравниваются к пешеходам ({p:1.10})."}},{"uk":"Особи, які рухаються на велосипедах.","ru":"Лица, передвигающиеся на велосипедах."},{"uk":"Особи, які везуть візок.","ru":"Лица, везущие тележку.","w":{"uk":"Особи, які везуть візок, прямо прирівнюються до пішоходів ({p:1.10}).","ru":"Лица, везущие тележку, прямо приравниваются к пешеходам ({p:1.10})."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2.","w":{"uk":"Варіант 1 хибний: особи в кріслах колісних без двигуна прирівнюються до пішоходів.","ru":"Вариант 1 ошибочен: лица в креслах-колясках без двигателя приравниваются к пешеходам."}}],"c":1,"e":{"uk":"До пішоходів прирівнюються особи, які **ведуть** велосипед, а той, хто **їде** на велосипеді, — велосипедист ({p:1.10}).","ru":"К пешеходам приравниваются лица, которые **ведут** велосипед, а тот, кто **едет** на велосипеде, — велосипедист ({p:1.10})."},"ref":["1.10"]},{"id":"h1-75","t":"h1","num":"1.75","q":{"uk":"Яке із наведених визначень відповідає терміну колона транспортних засобів:","ru":"Какое из приведённых определений соответствует термину «колонна транспортных средств»:"},"a":[{"uk":"Організована група двох транспортних засобів, що разом рухаються в одному напрямку безпосередньо один за одним з постійно увімкненим ближнім світлом фар.","ru":"Организованная группа из двух транспортных средств, которые вместе движутся в одном направлении непосредственно одно за другим с постоянно включённым ближним светом фар.","w":{"uk":"Двох транспортних засобів для колони замало — потрібно щонайменше три.","ru":"Двух транспортных средств для колонны мало — нужно не менее трёх."}},{"uk":"Організована група з трьох і більше транспортних засобів, що разом рухаються в одному напрямку безпосередньо один за одним з постійно увімкненим ближнім світлом фар.","ru":"Организованная группа из трёх и более транспортных средств, которые вместе движутся в одном направлении непосредственно одно за другим с постоянно включённым ближним светом фар."},{"uk":"Організована група двох транспортних засобів, що разом рухаються в одному напрямку безпосередньо один за одним з постійно увімкненою аварійною сигналізацією.","ru":"Организованная группа из двух транспортных средств, которые вместе движутся в одном направлении непосредственно одно за другим с постоянно включённой аварийной сигнализацией.","w":{"uk":"Колону утворюють щонайменше три транспортні засоби, і в ній вмикають ближнє світло фар, а не аварійну сигналізацію.","ru":"Колонну образуют не менее трёх транспортных средств, и в ней включают ближний свет фар, а не аварийную сигнализацию."}},{"uk":"Організована група з трьох і більше транспортних засобів, що разом рухаються в одному напрямку безпосередньо один за одним з постійно увімкненою аварійною сигналізацією.","ru":"Организованная группа из трёх и более транспортных средств, которые вместе движутся в одном направлении непосредственно одно за другим с постоянно включённой аварийной сигнализацией.","w":{"uk":"Кількість правильна, але в колоні постійно вмикають ближнє світло фар, а не аварійну сигналізацію.","ru":"Количество правильное, но в колонне постоянно включают ближний свет фар, а не аварийную сигнализацию."}}],"c":1,"e":{"uk":"За {p:1.10} колона — організована група з **трьох і більше** транспортних засобів, що рухаються одне за одним з постійно увімкненим **ближнім світлом фар**.","ru":"Согласно {p:1.10} колонна — организованная группа из **трёх и более** транспортных средств, движущихся одно за другим с постоянно включённым **ближним светом фар**."},"ref":["1.10"]},{"id":"h1-76","t":"h1","num":"1.76","q":{"uk":"Якому терміну відповідає сукупність факторів, що характеризуються дорожніми умовами, наявністю перешкод на певній ділянці дороги, інтенсивністю і рівнем організації дорожнього руху (наявність та стан дорожньої розмітки, дорожніх знаків, дорожнього обладнання, світлофорів), які повинен ураховувати водій під час вибору швидкості, смуги руху та прийомів керування транспортним засобом?","ru":"Какому термину соответствует совокупность факторов, характеризующихся дорожными условиями, наличием препятствий на определённом участке дороги, интенсивностью и уровнем организации дорожного движения (наличие и состояние дорожной разметки, дорожных знаков, дорожного оборудования, светофоров), которые должен учитывать водитель при выборе скорости, полосы движения и приёмов управления транспортным средством?"},"a":[{"uk":"Дорожні роботи.","ru":"Дорожные работы.","w":{"uk":"Дорожні роботи — це будівництво, ремонт чи утримання дороги та засобів організації руху.","ru":"Дорожные работы — это строительство, ремонт или содержание дороги и средств организации движения."}},{"uk":"Дорожні умови.","ru":"Дорожные условия.","w":{"uk":"Дорожні умови — вужче поняття (видимість, стан і ширина проїзної частини, похили тощо), яке лише входить до складу дорожньої обстановки.","ru":"Дорожные условия — более узкое понятие (видимость, состояние и ширина проезжей части, уклоны и т. п.), которое лишь входит в состав дорожной обстановки."}},{"uk":"Дорожня обстановка.","ru":"Дорожная обстановка."}],"c":2,"e":{"uk":"Це визначення **дорожньої обстановки** з {p:1.10}; дорожні умови — лише одна з її складових.","ru":"Это определение **дорожной обстановки** из {p:1.10}; дорожные условия — лишь одна из её составляющих."},"ref":["1.10"]},{"id":"h1-77","t":"h1","num":"1.77","q":{"uk":"До терміну «оглядовість» належить:","ru":"К термину «обзорность» относится:"},"a":[{"uk":"Об’єктивна можливість бачити дорожню обстановку з місця водія.","ru":"Объективная возможность видеть дорожную обстановку с места водителя."},{"uk":"Видимість дороги в напрямку руху.","ru":"Видимость дороги в направлении движения.","w":{"uk":"Видимість у напрямку руху — окремий термін: максимальна відстань, на якій водій чітко розпізнає елементи дороги.","ru":"Видимость в направлении движения — отдельный термин: максимальное расстояние, на котором водитель чётко распознаёт элементы дороги."}},{"uk":"Об’єктивна можливість водія розпізнати межі елементів дороги та розміщення учасників дорожнього руху.","ru":"Объективная возможность водителя распознать границы элементов дороги и расположение участников дорожного движения.","w":{"uk":"Розпізнавання меж елементів дороги та розміщення учасників руху належить до визначення видимості в напрямку руху, а не оглядовості.","ru":"Распознавание границ элементов дороги и расположения участников движения относится к определению видимости в направлении движения, а не обзорности."}}],"c":0,"e":{"uk":"За {p:1.10} оглядовість — **об'єктивна можливість бачити дорожню обстановку з місця водія**.","ru":"Согласно {p:1.10} обзорность — **объективная возможность видеть дорожную обстановку с места водителя**."},"ref":["1.10"]},{"id":"h1-78","t":"h1","num":"1.78","q":{"uk":"До якого виду транспортних засобів відносяться трактори, самохідні шасі, дорожньо-будівельні, меліоративні машини та інші механізми?","ru":"К какому виду транспортных средств относятся тракторы, самоходные шасси, дорожно-строительные, мелиоративные машины и другие механизмы?"},"a":[{"uk":"Легкових автомобілів.","ru":"Легковых автомобилей.","w":{"uk":"Легковий автомобіль призначений для перевезення пасажирів і має не більше дев'яти місць для сидіння.","ru":"Легковой автомобиль предназначен для перевозки пассажиров и имеет не более девяти мест для сидения."}},{"uk":"Вантажних автомобілів.","ru":"Грузовых автомобилей.","w":{"uk":"Вантажний автомобіль призначений для перевезення вантажів, а перелічені машини виконують роботи.","ru":"Грузовой автомобиль предназначен для перевозки грузов, а перечисленные машины выполняют работы."}},{"uk":"Сільськогосподарської техніки.","ru":"Сельскохозяйственной техники."},{"uk":"Відповідь 2 і 3.","ru":"Ответ 2 и 3.","w":{"uk":"Варіант 2 хибний: перелічені машини не є вантажними автомобілями.","ru":"Вариант 2 ошибочен: перечисленные машины не являются грузовыми автомобилями."}}],"c":2,"e":{"uk":"За {p:1.10} трактори, самохідні шасі, самохідні сільськогосподарські, дорожньо-будівельні, меліоративні машини та інші механізми належать до **сільськогосподарської техніки**.","ru":"Согласно {p:1.10} тракторы, самоходные шасси, самоходные сельскохозяйственные, дорожно-строительные, мелиоративные машины и другие механизмы относятся к **сельскохозяйственной технике**."},"ref":["1.10"]},{"id":"h1-79","t":"h1","num":"1.79","q":{"uk":"Безпечною швидкістю руху вважається:","ru":"Безопасной скоростью движения считается:"},"a":[{"uk":"Мінімально допустима швидкість руху, за якою водій контролює дорожню обстановку та пам’ятає про небезпеку на дорозі.","ru":"Минимально допустимая скорость движения, при которой водитель контролирует дорожную обстановку и помнит об опасности на дороге.","w":{"uk":"Безпечна швидкість — не «мінімально допустима»: її визначає можливість безпечно керувати транспортним засобом у конкретних умовах.","ru":"Безопасная скорость — не «минимально допустимая»: её определяет возможность безопасно управлять транспортным средством в конкретных условиях."}},{"uk":"Швидкість, за якої водій має змогу безпечно керувати транспортним засобом та контролювати його рух у конкретних дорожніх умовах.","ru":"Скорость, при которой водитель имеет возможность безопасно управлять транспортным средством и контролировать его движение в конкретных дорожных условиях."}],"c":1,"e":{"uk":"Це визначення **безпечної швидкості** з {p:1.10}: вона залежить від конкретних дорожніх умов, а не є фіксованим мінімумом чи максимумом.","ru":"Это определение **безопасной скорости** из {p:1.10}: она зависит от конкретных дорожных условий, а не является фиксированным минимумом или максимумом."},"ref":["1.10"]},{"id":"h2-1","t":"h2","num":"2.1","q":{"uk":"У разі, якщо неможливо вжити заходи для надання домедичної допомоги потерпілому та викликати бригаду екстреної (швидкої) медичної допомоги, а також якщо з місця ДТП немає можливості відправити потерпілого до лікувального закладу за допомогою інших осіб, водій зобов'язаний:","ru":"Если невозможно принять меры для оказания домедицинской помощи пострадавшему и вызвать бригаду экстренной (скорой) медицинской помощи, а также если с места ДТП нет возможности отправить пострадавшего в лечебное учреждение с помощью других лиц, водитель обязан:"},"a":[{"uk":"Не залишати місце дорожньо-транспортної пригоди і чекати будь-який транспортний засіб, що рухається в попутному напрямку, для доставки потерпілого.","ru":"Не оставлять место дорожно-транспортного происшествия и ждать любое транспортное средство, движущееся в попутном направлении, для доставки пострадавшего.","w":{"uk":"Очікування попутного транспорту лише затримає допомогу; у цьому разі Правила зобов'язують водія відвезти потерпілого власним транспортним засобом.","ru":"Ожидание попутного транспорта лишь задержит помощь; в этом случае Правила обязывают водителя отвезти пострадавшего собственным транспортным средством."}},{"uk":"Відвезти потерпілого в найближчий лікувальний заклад своїм транспортним засобом, попередньо зафіксувавши розташування слідів пригоди, в лікувальному закладі повідомити своє прізвище та номерний знак транспортного засобу (з пред'явленням посвідчення водія або іншого документа, що посвідчує особу, реєстраційного документа на транспортний засіб) і повернутися на місце події.","ru":"Отвезти пострадавшего в ближайшее лечебное учреждение своим транспортным средством, предварительно зафиксировав расположение следов происшествия, в лечебном учреждении сообщить свою фамилию и номерной знак транспортного средства (с предъявлением удостоверения водителя или другого документа, удостоверяющего личность, регистрационного документа на транспортное средство) и вернуться на место происшествия."}],"c":1,"e":{"uk":"Саме цей порядок встановлює {p:2.10} (підпункт «ґ»): якщо допомогу на місці надати й відправити потерпілого іншими особами неможливо, водій **сам везе його** до найближчого лікувального закладу, попередньо зафіксувавши сліди пригоди, а потім повертається на місце.","ru":"Именно этот порядок устанавливает {p:2.10} (подпункт «ґ»): если оказать помощь на месте и отправить пострадавшего с помощью других лиц невозможно, водитель **сам везёт его** в ближайшее лечебное учреждение, предварительно зафиксировав следы происшествия, а затем возвращается на место."},"ref":["2.10"],"pic":["img/hsc/2-1-1.jpg"]},{"id":"h2-2","t":"h2","num":"2.2","q":{"uk":"Що з переліченого в першу чергу зобов’язаний зробити причетний до дорожньо-транспортної пригоди водій, якщо в результаті події є потерпілі особи?","ru":"Что из перечисленного в первую очередь обязан сделать причастный к дорожно-транспортному происшествию водитель, если в результате происшествия есть пострадавшие?"},"a":[{"uk":"Прибрати транспортний засіб за межі дороги.","ru":"Убрать транспортное средство за пределы дороги.","w":{"uk":"Переміщати транспортний засіб, причетний до пригоди, {p:2.10} забороняє (підпункт «в»).","ru":"Перемещать транспортное средство, причастное к происшествию, {p:2.10} запрещает (подпункт «в»)."}},{"uk":"Повідомити про дорожньо-транспортну пригоду орган чи уповноважений підрозділ Національної поліції і чекати прибуття поліцейських.","ru":"Сообщить о дорожно-транспортном происшествии в орган или уполномоченное подразделение Национальной полиции и ожидать прибытия полицейских.","w":{"uk":"Повідомити поліцію водій зобов'язаний, але не раніше, ніж подбає про допомогу потерпілим.","ru":"Сообщить в полицию водитель обязан, но не раньше, чем позаботится о помощи пострадавшим."}},{"uk":"Вжити можливих заходів для надання домедичної допомоги потерпілим, викликати бригаду екстреної (швидкої) медичної допомоги, а в разі відсутності можливості вжити зазначених заходів звернутися по допомогу до присутніх і відправити потерпілих до закладу охорони здоров’я.","ru":"Принять возможные меры для оказания домедицинской помощи пострадавшим, вызвать бригаду экстренной (скорой) медицинской помощи, а при отсутствии возможности принять указанные меры обратиться за помощью к присутствующим и отправить пострадавших в учреждение здравоохранения."},{"uk":"Вжити всіх можливих заходів для збереження слідів пригоди, огородження їх, організувати об’їзд місця пригоди.","ru":"Принять все возможные меры для сохранения следов происшествия, их ограждения, организовать объезд места происшествия.","w":{"uk":"Збереження слідів пригоди важливе, але допомога потерпілим має пріоритет.","ru":"Сохранение следов происшествия важно, но помощь пострадавшим имеет приоритет."}}],"c":2,"e":{"uk":"Коли є потерпілі, найважливіше — їхні життя і здоров'я: {p:2.10} (підпункт «г») зобов'язує надати домедичну допомогу, викликати швидку або відправити потерпілих до закладу охорони здоров'я. Інші обов'язки (повідомити поліцію, зберегти сліди) теж виконуються, але не замість допомоги.","ru":"При наличии пострадавших важнее всего их жизнь и здоровье: {p:2.10} (подпункт «г») обязывает оказать домедицинскую помощь, вызвать скорую или отправить пострадавших в учреждение здравоохранения. Другие обязанности (сообщить в полицию, сохранить следы) тоже выполняются, но не вместо помощи."},"ref":["2.10"]},{"id":"h2-3","t":"h2","num":"2.3","q":{"uk":"Що зобов'язаний зробити водій, який став учасником дорожньо-транспортної пригоди?","ru":"Что обязан сделать водитель, ставший участником дорожно-транспортного происшествия?"},"a":[{"uk":"Негайно зупинити транспортний засіб і залишатися на місці пригоди, увімкнути аварійну сигналізацію і встановити знак аварійної зупинки.","ru":"Немедленно остановить транспортное средство и оставаться на месте происшествия, включить аварийную сигнализацию и установить знак аварийной остановки.","w":{"uk":"Неповна відповідь: водій також мусить подбати про допомогу потерпілим і повідомити поліцію.","ru":"Неполный ответ: водитель также должен позаботиться о помощи пострадавшим и сообщить в полицию."}},{"uk":"Надати домедичну допомогу і викликати бригаду екстреної (швидкої) медичної допомоги.","ru":"Оказать домедицинскую помощь и вызвать бригаду экстренной (скорой) медицинской помощи.","w":{"uk":"Неповна відповідь: спершу треба зупинитися, позначити місце пригоди, а також повідомити поліцію.","ru":"Неполный ответ: сначала нужно остановиться, обозначить место происшествия, а также сообщить в полицию."}},{"uk":"Повідомити про те, що сталося, орган чи підрозділ поліції.","ru":"Сообщить о случившемся в орган или подразделение полиции.","w":{"uk":"Неповна відповідь: повідомлення поліції — лише один з обов'язків, перелічених у {p:2.10}.","ru":"Неполный ответ: сообщение в полицию — лишь одна из обязанностей, перечисленных в {p:2.10}."}},{"uk":"Усе перелічене вище.","ru":"Всё перечисленное выше."}],"c":3,"e":{"uk":"Усі три дії входять до обов'язків водія, причетного до ДТП, за {p:2.10}: зупинитися й залишатися на місці, увімкнути аварійну сигналізацію й виставити знак аварійної зупинки, подбати про допомогу потерпілим і повідомити поліцію — як і показано на малюнку.","ru":"Все три действия входят в обязанности водителя, причастного к ДТП, согласно {p:2.10}: остановиться и оставаться на месте, включить аварийную сигнализацию и выставить знак аварийной остановки, позаботиться о помощи пострадавшим и сообщить в полицию — как и показано на рисунке."},"ref":["2.10"],"pic":["img/hsc/2-3-1.jpg"]},{"id":"h2-4","t":"h2","num":"2.4","q":{"uk":"Водій, причетний до дорожньо-транспортної пригоди, що зупинив транспортний засіб на місці події, ввімкнув аварійну світлову сигналізацію і встановив знак аварійної зупинки, залишаючись на місці події, повинен:","ru":"Водитель, причастный к дорожно-транспортному происшествию, который остановил транспортное средство на месте происшествия, включил аварийную световую сигнализацию и установил знак аварийной остановки, оставаясь на месте происшествия, должен:"},"a":[{"uk":"Повідомити про дорожньо-транспортну пригоду страхову компанію.","ru":"Сообщить о дорожно-транспортном происшествии страховой компании.","w":{"uk":"Повідомлення страхової компанії не входить до обов'язків водія на місці ДТП за Правилами дорожнього руху.","ru":"Сообщение страховой компании не входит в обязанности водителя на месте ДТП по Правилам дорожного движения."}},{"uk":"Не переміщати транспортний засіб і предмети, що мають причетність до події, а також вжити можливих заходів для надання домедичної допомоги потерпілим, викликати бригаду екстреної (швидкої) медичної допомоги, а якщо це неможливо, звернутися за допомогою до присутніх і відправити потерпілих до лікувального закладу.","ru":"Не перемещать транспортное средство и предметы, имеющие отношение к происшествию, а также принять возможные меры для оказания домедицинской помощи пострадавшим, вызвать бригаду экстренной (скорой) медицинской помощи, а если это невозможно, обратиться за помощью к присутствующим и отправить пострадавших в лечебное учреждение."},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2.","w":{"uk":"Варіант 1 не передбачений {p:2.10}, тож це поєднання відповідей неправильне.","ru":"Вариант 1 не предусмотрен {p:2.10}, поэтому это сочетание ответов неверно."}}],"c":1,"e":{"uk":"Наступні обов'язки за {p:2.10} — не переміщати транспортний засіб і причетні до пригоди предмети (підпункт «в») та подбати про допомогу потерпілим (підпункт «г»).","ru":"Следующие обязанности согласно {p:2.10} — не перемещать транспортное средство и причастные к происшествию предметы (подпункт «в») и позаботиться о помощи пострадавшим (подпункт «г»)."},"ref":["2.10"],"pic":["img/hsc/2-4-1.jpg"]},{"id":"h2-5","t":"h2","num":"2.5","q":{"uk":"Кому дозволено зупинку і стоянку в зоні дії знака «Зупинку заборонено» за наявності під ним таблички «Крім осіб з інвалідністю»?","ru":"Кому разрешены остановка и стоянка в зоне действия знака «Остановка запрещена» при наличии под ним таблички «Кроме лиц с инвалидностью»?"},"a":[{"uk":"Мотоколяскам та автомобілям, на яких встановлено розпізнавальний знак «Водій з інвалідністю».","ru":"Мотоколяскам и автомобилям, на которых установлен опознавательный знак «Водитель с инвалидностью».","w":{"uk":"Неповна відповідь: зупинятися під цим знаком може й таксі для посадки чи висадки пасажирів ({p:33.3}).","ru":"Неполный ответ: останавливаться под этим знаком может и такси для посадки или высадки пассажиров ({p:33.3})."}},{"uk":"Таксі, що здійснюють посадку або висадку пасажирів (розвантаження чи завантаження вантажу).","ru":"Такси, осуществляющим посадку или высадку пассажиров (разгрузку или погрузку груза).","w":{"uk":"Неповна відповідь: табличка {s:7.18} дозволяє зупинку й стоянку також транспортним засобам зі знаком «Водій з інвалідністю».","ru":"Неполный ответ: табличка {s:7.18} разрешает остановку и стоянку также транспортным средствам со знаком «Водитель с инвалидностью»."}},{"uk":"Мотоциклам і мопедам.","ru":"Мотоциклам и мопедам.","w":{"uk":"Для мотоциклів і мопедів знак {s:3.34} жодних винятків не передбачає.","ru":"Для мотоциклов и мопедов знак {s:3.34} никаких исключений не предусматривает."}},{"uk":"Відповіді, зазначені в пунктах 1, 2.","ru":"Ответы, указанные в пунктах 1, 2."},{"uk":"Відповіді, зазначені в пунктах 1, 2, 3.","ru":"Ответы, указанные в пунктах 1, 2, 3.","w":{"uk":"Мотоцикли й мопеди права на зупинку в зоні дії знака {s:3.34} не мають.","ru":"Мотоциклы и мопеды права на остановку в зоне действия знака {s:3.34} не имеют."}}],"c":3,"e":{"uk":"На малюнку знак {s:3.34} з табличкою {s:7.18} (перекреслений символ крісла колісного). Табличка знімає дію знака для мотоколясок і автомобілів з розпізнавальним знаком «Водій з інвалідністю» ({p:2.8}, {p:33.7}), а на таксі під час посадки чи висадки пасажирів знак {s:3.34} не поширюється взагалі ({p:33.3}).","ru":"На рисунке знак {s:3.34} с табличкой {s:7.18} (перечёркнутый символ кресла-коляски). Табличка снимает действие знака для мотоколясок и автомобилей с опознавательным знаком «Водитель с инвалидностью» ({p:2.8}, {p:33.7}), а на такси во время посадки или высадки пассажиров знак {s:3.34} не распространяется вообще ({p:33.3})."},"ref":["2.8","33.3","33.7"],"pic":["img/hsc/2-5-1.jpg"]},{"id":"h2-6","t":"h2","num":"2.6","q":{"uk":"Хто може вимагати від водія проходження в установленому порядку медичного огляду для визначення стану алкогольного сп’яніння, впливу наркотичних чи токсичних речовин?","ru":"Кто может требовать от водителя прохождения в установленном порядке медицинского осмотра для определения состояния алкогольного опьянения, воздействия наркотических или токсических веществ?"},"a":[{"uk":"Лікар карети швидкої допомоги.","ru":"Врач кареты скорой помощи.","w":{"uk":"Лікар швидкої допомоги не має права вимагати від водія проходження огляду на стан сп'яніння.","ru":"Врач скорой помощи не имеет права требовать от водителя прохождения осмотра на состояние опьянения."}},{"uk":"Поліцейський і страховий агент.","ru":"Полицейский и страховой агент.","w":{"uk":"Страховий агент не має права вимагати від водія медичного огляду.","ru":"Страховой агент не имеет права требовать от водителя медицинского осмотра."}},{"uk":"Поліцейський.","ru":"Полицейский."},{"uk":"Відповіді 2 і 3.","ru":"Ответы 2 и 3.","w":{"uk":"Відповідь 2 хибна: страховий агент такого права не має.","ru":"Ответ 2 ошибочен: страховой агент такого права не имеет."}}],"c":2,"e":{"uk":"За {p:2.5} водій зобов'язаний пройти медичний огляд на стан сп'яніння саме **на вимогу поліцейського**.","ru":"Согласно {p:2.5} водитель обязан пройти медицинский осмотр на состояние опьянения именно **по требованию полицейского**."},"ref":["2.5"],"pic":["img/hsc/2-6-1.jpg"]},{"id":"h2-7","t":"h2","num":"2.7","q":{"uk":"З якого віку надається право на керування транспортними засобами категорії В?","ru":"С какого возраста предоставляется право на управление транспортными средствами категории В?"},"a":[{"uk":"З 16 років.","ru":"С 16 лет.","w":{"uk":"З 16 років можна отримати право лише на мототранспортні засоби категорій А1, А.","ru":"С 16 лет можно получить право только на мототранспортные средства категорий А1, А."}},{"uk":"З 18 років.","ru":"С 18 лет."},{"uk":"З 19 років.","ru":"С 19 лет.","w":{"uk":"З 19 років надається право на состави з причепами категорій ВЕ, С1Е, СЕ.","ru":"С 19 лет предоставляется право на составы с прицепами категорий ВЕ, С1Е, СЕ."}},{"uk":"З 21 року.","ru":"С 21 года.","w":{"uk":"З 21 року надається право на автобуси, трамваї й тролейбуси (категорії D1, D, D1Е, DE, Т).","ru":"С 21 года предоставляется право на автобусы, трамваи и троллейбусы (категории D1, D, D1Е, DE, Т)."}}],"c":1,"e":{"uk":"За {p:2.13} право керувати автомобілями категорій В1, В, С1, С (як легковий автомобіль на малюнку) надається **з 18-річного віку**.","ru":"Согласно {p:2.13} право управлять автомобилями категорий В1, В, С1, С (как легковой автомобиль на рисунке) предоставляется **с 18-летнего возраста**."},"ref":["2.13"],"pic":["img/hsc/2-7-1.jpg"]},{"id":"h2-8","t":"h2","num":"2.8","q":{"uk":"Якими засобами пасивної безпеки зобов'язані користуватися водії і пасажири автомобілів, обладнаних такими засобами?","ru":"Какими средствами пассивной безопасности обязаны пользоваться водители и пассажиры автомобилей, оборудованных такими средствами?"},"a":[{"uk":"Підголівниками.","ru":"Подголовниками.","w":{"uk":"Неповна відповідь: обов'язково користуватися й ременями безпеки.","ru":"Неполный ответ: обязательно пользоваться и ремнями безопасности."}},{"uk":"Ременями безпеки.","ru":"Ремнями безопасности.","w":{"uk":"Неповна відповідь: до засобів пасивної безпеки належать також підголовники.","ru":"Неполный ответ: к средствам пассивной безопасности относятся также подголовники."}},{"uk":"Підлокітниками.","ru":"Подлокотниками.","w":{"uk":"Підлокітник — елемент зручності, а не засіб пасивної безпеки.","ru":"Подлокотник — элемент удобства, а не средство пассивной безопасности."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2."},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3.","w":{"uk":"Підлокітники не є засобом пасивної безпеки, тож відповідь 3 тут зайва.","ru":"Подлокотники не являются средством пассивной безопасности, поэтому ответ 3 здесь лишний."}}],"c":3,"e":{"uk":"{p:2.3} (підпункт «в») називає засобами пасивної безпеки **підголовники та ремені безпеки** і зобов'язує ними користуватися.","ru":"{p:2.3} (подпункт «в») называет средствами пассивной безопасности **подголовники и ремни безопасности** и обязывает ими пользоваться."},"ref":["2.3"],"pic":["img/hsc/2-8-1.jpg"]},{"id":"h2-9","t":"h2","num":"2.9","q":{"uk":"Документи, які повинен пред’явити для перевірки водій на вимогу поліцейського:","ru":"Документы, которые должен предъявить для проверки водитель по требованию полицейского:"},"a":[{"uk":"Посвідчення водія на право керування транспортним засобом відповідної категорії, реєстраційний документ на транспортний засіб або пред’явити електронне посвідчення водія та електронне свідоцтво про реєстрацію транспортного засобу.","ru":"Удостоверение водителя на право управления транспортным средством соответствующей категории, регистрационный документ на транспортное средство либо предъявить электронное удостоверение водителя и электронное свидетельство о регистрации транспортного средства.","w":{"uk":"Неповна відповідь: водій має пред'явити й чинний поліс обов'язкового страхування цивільно-правової відповідальності.","ru":"Неполный ответ: водитель должен предъявить и действующий полис обязательного страхования гражданско-правовой ответственности."}},{"uk":"Чинний страховий поліс (страховий сертифікат «Зелена картка») про укладання договору обов’язкового страхування цивільно-правової відповідальності власників наземних транспортних засобів або чинний внутрішній електронний договір зазначеного виду обов’язкового страхування у візуальній формі страхового поліса (на паперовому чи електронному носії або відображення інформації про його наявність в електронному свідоцтві про реєстрацію транспортного засобу).","ru":"Действующий страховой полис (страховой сертификат «Зелёная карта») о заключении договора обязательного страхования гражданско-правовой ответственности владельцев наземных транспортных средств или действующий внутренний электронный договор указанного вида обязательного страхования в визуальной форме страхового полиса (на бумажном или электронном носителе либо отображение информации о его наличии в электронном свидетельстве о регистрации транспортного средства).","w":{"uk":"Неповна відповідь: основні документи — посвідчення водія й реєстраційний документ на транспортний засіб.","ru":"Неполный ответ: основные документы — удостоверение водителя и регистрационный документ на транспортное средство."}},{"uk":"Дійсну медичну довідку встановленого зразка.","ru":"Действительную медицинскую справку установленного образца.","w":{"uk":"Медичної довідки немає серед документів, які водій зобов'язаний мати при собі за {p:2.1}.","ru":"Медицинской справки нет среди документов, которые водитель обязан иметь при себе согласно {p:2.1}."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3.","w":{"uk":"Медична довідка не входить до переліку {p:2.1}, тож відповідь 3 зайва.","ru":"Медицинская справка не входит в перечень {p:2.1}, поэтому ответ 3 лишний."}},{"uk":"Відповіді, зазначені в пунктах 1 і 2.","ru":"Ответы, указанные в пунктах 1 и 2."}],"c":4,"e":{"uk":"На вимогу поліцейського водій пред'являє документи, перелічені в {p:2.1} ({p:2.4}): посвідчення водія, реєстраційний документ на транспортний засіб і чинний страховий поліс (у паперовій чи електронній формі). Медичної довідки в цьому переліку немає.","ru":"По требованию полицейского водитель предъявляет документы, перечисленные в {p:2.1} ({p:2.4}): удостоверение водителя, регистрационный документ на транспортное средство и действующий страховой полис (в бумажной или электронной форме). Медицинской справки в этом перечне нет."},"ref":["2.1","2.4"],"pic":["img/hsc/2-9-1.jpg"]},{"id":"h2-10","t":"h2","num":"2.10","q":{"uk":"Чи дозволено керувати транспортним засобом, якщо водій перебуває в хворобливому стані, який ставить під загрозу безпеку дорожнього руху?","ru":"Разрешено ли управлять транспортным средством, если водитель находится в болезненном состоянии, которое ставит под угрозу безопасность дорожного движения?"},"a":[{"uk":"Дозволено під впливом лікарських засобів, що підвищують увагу та швидкість реакції.","ru":"Разрешено под воздействием лекарственных средств, повышающих внимание и скорость реакции.","w":{"uk":"Прийом будь-яких ліків не скасовує заборони {p:2.9} керувати в хворобливому стані.","ru":"Приём каких-либо лекарств не отменяет запрета {p:2.9} управлять в болезненном состоянии."}},{"uk":"Дозволено в будь-якому випадку.","ru":"Разрешено в любом случае.","w":{"uk":"Керування в хворобливому стані прямо заборонене {p:2.9}.","ru":"Управление в болезненном состоянии прямо запрещено {p:2.9}."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":2,"e":{"uk":"{p:2.9} (підпункт «б») забороняє керувати транспортним засобом **у хворобливому стані**, у стані стомлення чи під впливом ліків, що знижують увагу та швидкість реакції.","ru":"{p:2.9} (подпункт «б») запрещает управлять транспортным средством **в болезненном состоянии**, в состоянии утомления или под воздействием лекарств, снижающих внимание и скорость реакции."},"ref":["2.9"]},{"id":"h2-11","t":"h2","num":"2.11","q":{"uk":"Водій має право:","ru":"Водитель имеет право:"},"a":[{"uk":"Керувати транспортним засобом і перевозити пасажирів або вантажі дорогами, вулицями чи іншими місцями, де рух не заборонено.","ru":"Управлять транспортным средством и перевозить пассажиров или грузы по дорогам, улицам или в других местах, где движение не запрещено.","w":{"uk":"Неповна відповідь: водій має також право знати причину зупинки й оскаржити дії поліцейського.","ru":"Неполный ответ: водитель имеет также право знать причину остановки и обжаловать действия полицейского."}},{"uk":"Знати причину зупинки, перевірки та огляду транспортного засобу посадовою особою державного органу, яка здійснює нагляд за дорожнім рухом, а також її прізвище і посаду.","ru":"Знать причину остановки, проверки и осмотра транспортного средства должностным лицом государственного органа, осуществляющим надзор за дорожным движением, а также его фамилию и должность.","w":{"uk":"Неповна відповідь: водій має також право керувати транспортним засобом там, де рух не заборонено, і оскаржити дії поліцейського.","ru":"Неполный ответ: водитель имеет также право управлять транспортным средством там, где движение не запрещено, и обжаловать действия полицейского."}},{"uk":"Оскаржити дії поліцейського в разі порушення ним законодавства.","ru":"Обжаловать действия полицейского в случае нарушения им законодательства.","w":{"uk":"Неповна відповідь: інші два варіанти теж є правами водія за {p:2.14}.","ru":"Неполный ответ: остальные два варианта тоже являются правами водителя согласно {p:2.14}."}},{"uk":"Усе перелічене вище.","ru":"Всё перечисленное выше."}],"c":3,"e":{"uk":"Усі три права прямо перелічені в {p:2.14} (підпункти «а», «в», «д»).","ru":"Все три права прямо перечислены в {p:2.14} (подпункты «а», «в», «д»)."},"ref":["2.14"]},{"id":"h2-12","t":"h2","num":"2.12","q":{"uk":"Що входить в обов'язки учасників дорожнього руху?","ru":"Что входит в обязанности участников дорожного движения?"},"a":[{"uk":"Тільки знати Правила дорожнього руху, що відносяться до них.","ru":"Только знать Правила дорожного движения, которые к ним относятся.","w":{"uk":"Знати Правила недостатньо — їх треба ще й неухильно виконувати.","ru":"Знать Правила недостаточно — их нужно ещё и неукоснительно выполнять."}},{"uk":"Знати і дотримуватися вимог Правил дорожнього руху і вимагати від інших учасників дорожнього руху виконання Правил.","ru":"Знать и соблюдать требования Правил дорожного движения и требовать от других участников дорожного движения выполнения Правил.","w":{"uk":"Права вимагати від інших виконання Правил учасники руху не мають, а обов'язок бути взаємно ввічливими тут пропущено.","ru":"Права требовать от других выполнения Правил участники движения не имеют, а обязанность быть взаимно вежливыми здесь пропущена."}},{"uk":"Знати і неухильно виконувати вимоги Правил дорожнього руху, бути взаємно ввічливими.","ru":"Знать и неукоснительно выполнять требования Правил дорожного движения, быть взаимно вежливыми."}],"c":2,"e":{"uk":"Це дослівно {p:1.3}: учасники дорожнього руху зобов'язані знати й неухильно виконувати вимоги Правил, а також бути взаємно ввічливими.","ru":"Это дословно {p:1.3}: участники дорожного движения обязаны знать и неукоснительно выполнять требования Правил, а также быть взаимно вежливыми."},"ref":["1.3"]},{"id":"h2-13","t":"h2","num":"2.13","q":{"uk":"Водій транспортного засобу, якого зупинила посадова особа державного органу, яка здійснює нагляд за дорожнім рухом, має право:","ru":"Водитель транспортного средства, которого остановило должностное лицо государственного органа, осуществляющее надзор за дорожным движением, имеет право:"},"a":[{"uk":"Знати причину зупинки, перевірки та огляду транспортного засобу посадовою особою державного органу, яка здійснює нагляд за дорожнім рухом, а також її прізвище і посаду.","ru":"Знать причину остановки, проверки и осмотра транспортного средства должностным лицом государственного органа, осуществляющим надзор за дорожным движением, а также его фамилию и должность.","w":{"uk":"Неповна відповідь: водій може також вимагати пред'явити посвідчення особи.","ru":"Неполный ответ: водитель может также требовать предъявить удостоверение личности."}},{"uk":"Вимагати від особи, яка здійснює нагляд за дорожнім рухом та зупинила транспортний засіб, пред’явлення посвідчення її особи.","ru":"Требовать от лица, осуществляющего надзор за дорожным движением и остановившего транспортное средство, предъявления удостоверения его личности.","w":{"uk":"Неповна відповідь: водій має також право знати причину зупинки, прізвище й посаду посадової особи.","ru":"Неполный ответ: водитель имеет также право знать причину остановки, фамилию и должность должностного лица."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2."}],"c":2,"e":{"uk":"Обидва права закріплені в {p:2.14} (підпункти «в» і «г»).","ru":"Оба права закреплены в {p:2.14} (подпункты «в» и «г»)."},"ref":["2.14"]},{"id":"h2-14","t":"h2","num":"2.14","q":{"uk":"Чи має право водій оскаржити дії поліцейського в разі порушення ним законодавства?","ru":"Имеет ли право водитель обжаловать действия полицейского в случае нарушения им законодательства?"},"a":[{"uk":"Має право.","ru":"Имеет право."},{"uk":"Не має право.","ru":"Не имеет права.","w":{"uk":"{p:2.14} прямо надає водієві таке право.","ru":"{p:2.14} прямо предоставляет водителю такое право."}}],"c":0,"e":{"uk":"Право оскаржити дії поліцейського в разі порушення ним законодавства прямо передбачене {p:2.14} (підпункт «д»).","ru":"Право обжаловать действия полицейского в случае нарушения им законодательства прямо предусмотрено {p:2.14} (подпункт «д»)."},"ref":["2.14"]},{"id":"h2-15","t":"h2","num":"2.15","q":{"uk":"Кому може передавати керування власник транспортного засобу, а також особа, яка використовує цей транспортний засіб на законних підставах?","ru":"Кому может передавать управление владелец транспортного средства, а также лицо, использующее это транспортное средство на законных основаниях?"},"a":[{"uk":"Будь-якій іншій особі.","ru":"Любому другому лицу.","w":{"uk":"Передавати керування особі без посвідчення водія забороняє {p:2.9} (підпункт «ґ»).","ru":"Передавать управление лицу без удостоверения водителя запрещает {p:2.9} (подпункт «ґ»)."}},{"uk":"Іншій особі, що має при собі посвідчення водія на право керування транспортним засобом відповідної категорії.","ru":"Другому лицу, имеющему при себе удостоверение водителя на право управления транспортным средством соответствующей категории."},{"uk":"Близькому родичу (чоловік або дружина, брат або сестра) під час його навчання водінню.","ru":"Близкому родственнику (муж или жена, брат или сестра) во время его обучения вождению.","w":{"uk":"Родинні зв'язки значення не мають: навчання водінню проводиться лише за вимогами розділу 24 Правил, а не будь-ким із рідних.","ru":"Родственные связи значения не имеют: обучение вождению проводится только по требованиям раздела 24 Правил, а не кем угодно из родных."}}],"c":1,"e":{"uk":"За {p:2.2} керування можна передати лише особі, яка **має при собі** посвідчення на право керування транспортним засобом **відповідної категорії**.","ru":"Согласно {p:2.2} управление можно передать только лицу, которое **имеет при себе** удостоверение на право управления транспортным средством **соответствующей категории**."},"ref":["2.2","2.9"]},{"id":"h2-16","t":"h2","num":"2.16","q":{"uk":"Чи зобов'язаний водій перевіряти технічний стан транспортного засобу перед виїздом?","ru":"Обязан ли водитель проверять техническое состояние транспортного средства перед выездом?"},"a":[{"uk":"Зобов'язаний тільки після тривалої стоянки.","ru":"Обязан только после длительной стоянки.","w":{"uk":"Обов'язок діє перед кожним виїздом, а не лише після тривалої стоянки.","ru":"Обязанность действует перед каждым выездом, а не только после длительной стоянки."}},{"uk":"Зобов'язаний тільки при наявності відповідних знань і рівня кваліфікації.","ru":"Обязан только при наличии соответствующих знаний и уровня квалификации.","w":{"uk":"Обов'язок не залежить від знань чи кваліфікації водія.","ru":"Обязанность не зависит от знаний или квалификации водителя."}},{"uk":"Зобов'язаний в будь-якому випадку.","ru":"Обязан в любом случае."}],"c":2,"e":{"uk":"{p:2.3} (підпункт «а») зобов'язує водія **перед виїздом** перевірити та забезпечити технічно справний стан і комплектність транспортного засобу — без жодних винятків.","ru":"{p:2.3} (подпункт «а») обязывает водителя **перед выездом** проверить и обеспечить технически исправное состояние и комплектность транспортного средства — без каких-либо исключений."},"ref":["2.3"]},{"id":"h2-17","t":"h2","num":"2.17","q":{"uk":"Що з переліченого нижче входить в обов'язки водіїв?","ru":"Что из перечисленного ниже входит в обязанности водителей?"},"a":[{"uk":"Бути уважним, стежити за дорожньою обстановкою.","ru":"Быть внимательным, следить за дорожной обстановкой.","w":{"uk":"Неповна відповідь: інші три варіанти теж є обов'язками водія за {p:2.3}.","ru":"Неполный ответ: остальные три варианта тоже являются обязанностями водителя согласно {p:2.3}."}},{"uk":"Не забруднювати проїзну частину та смугу відведення автомобільних доріг.","ru":"Не загрязнять проезжую часть и полосу отвода автомобильных дорог.","w":{"uk":"Неповна відповідь: водій також має бути уважним, не створювати загрози й повідомляти про перешкоди.","ru":"Неполный ответ: водитель также должен быть внимательным, не создавать угрозы и сообщать о помехах."}},{"uk":"Не створювати своїми діями загрози безпеці дорожнього руху.","ru":"Не создавать своими действиями угрозы безопасности дорожного движения.","w":{"uk":"Неповна відповідь: до обов'язків належать також уважність, чистота дороги й повідомлення про перешкоди.","ru":"Неполный ответ: к обязанностям относятся также внимательность, чистота дороги и сообщение о помехах."}},{"uk":"Повідомляти дорожньо-експлуатаційним організаціям про виявлені факти створення перешкод для дорожнього руху.","ru":"Сообщать дорожно-эксплуатационным организациям о выявленных фактах создания помех для дорожного движения.","w":{"uk":"Неповна відповідь: повідомлення про перешкоди — лише один з обов'язків, перелічених у {p:2.3}.","ru":"Неполный ответ: сообщение о помехах — лишь одна из обязанностей, перечисленных в {p:2.3}."}},{"uk":"Відповіді 1, 2, 3, 4 входять в обов’язки.","ru":"Ответы 1, 2, 3, 4 входят в обязанности."}],"c":4,"e":{"uk":"Усі чотири обов'язки перелічені в {p:2.3} (підпункти «б», «ґ», «д», «е»).","ru":"Все четыре обязанности перечислены в {p:2.3} (подпункты «б», «ґ», «д», «е»)."},"ref":["2.3"]},{"id":"h2-18","t":"h2","num":"2.18","q":{"uk":"Що зобов'язаний зробити водій перед виїздом?","ru":"Что обязан сделать водитель перед выездом?"},"a":[{"uk":"Перевірити й забезпечити технічно справний стан і комплектність транспортного засобу, правильність розміщення та кріплення вантажу.","ru":"Проверить и обеспечить технически исправное состояние и комплектность транспортного средства, правильность размещения и крепления груза."},{"uk":"Перевірити наявність насоса, а також буксирувального троса.","ru":"Проверить наличие насоса, а также буксировочного троса.","w":{"uk":"Насос і буксирувальний трос не входять до обов'язкового обладнання транспортного засобу (аптечка, знак аварійної зупинки тощо — {p:31.4}).","ru":"Насос и буксировочный трос не входят в обязательное оснащение транспортного средства (аптечка, знак аварийной остановки и т. п. — {p:31.4})."}},{"uk":"Усе перелічене вище.","ru":"Всё перечисленное выше.","w":{"uk":"Відповідь 2 зайва: насос і трос не є обов'язковими для перевірки перед виїздом.","ru":"Ответ 2 лишний: насос и трос не являются обязательными для проверки перед выездом."}}],"c":0,"e":{"uk":"Це дослівно {p:2.3} (підпункт «а»): перевірити та забезпечити технічну справність і комплектність транспортного засобу, правильність розміщення та кріплення вантажу.","ru":"Это дословно {p:2.3} (подпункт «а»): проверить и обеспечить техническую исправность и комплектность транспортного средства, правильность размещения и крепления груза."},"ref":["2.3"]},{"id":"h2-19","t":"h2","num":"2.19","q":{"uk":"Ви як власник легкового автомобіля, маєте право передати керування Вашим автомобілем особі, яка:","ru":"Вы как владелец легкового автомобиля имеете право передать управление вашим автомобилем лицу, которое:"},"a":[{"uk":"Має посвідчення водія на право керування транспортним засобом категорії «А» або «С» і поліс (сертифікат) обов'язкового страхування цивільно-правової відповідальності.","ru":"Имеет удостоверение водителя на право управления транспортным средством категории «А» или «С» и полис (сертификат) обязательного страхования гражданско-правовой ответственности.","w":{"uk":"Категорії «А» (мотоцикли) і «С» (вантажні автомобілі) не дають права керувати легковим автомобілем.","ru":"Категории «А» (мотоциклы) и «С» (грузовые автомобили) не дают права управлять легковым автомобилем."}},{"uk":"Має вік 18 років, медичну довідку і поліс (сертифікат) обов'язкового страхування цивільно-правової відповідальності.","ru":"Имеет возраст 18 лет, медицинскую справку и полис (сертификат) обязательного страхования гражданско-правовой ответственности.","w":{"uk":"Вік, медична довідка й поліс не замінюють посвідчення водія відповідної категорії.","ru":"Возраст, медицинская справка и полис не заменяют удостоверения водителя соответствующей категории."}},{"uk":"Має при собі посвідчення водія на право керування транспортним засобом категорії «В».","ru":"Имеет при себе удостоверение водителя на право управления транспортным средством категории «В»."}],"c":2,"e":{"uk":"За {p:2.2} керування передають особі, яка має при собі посвідчення водія **відповідної категорії**; для легкового автомобіля це категорія «В».","ru":"Согласно {p:2.2} управление передают лицу, которое имеет при себе удостоверение водителя **соответствующей категории**; для легкового автомобиля это категория «В»."},"ref":["2.2"]},{"id":"h2-20","t":"h2","num":"2.20","q":{"uk":"Які з перерахованих прав є у водія?","ru":"Какие из перечисленных прав есть у водителя?"},"a":[{"uk":"Знати причину зупинки, перевірки та огляду транспортного засобу посадовою особою державного органу, яка здійснює нагляд за дорожнім рухом, а також її прізвище і посаду.","ru":"Знать причину остановки, проверки и осмотра транспортного средства должностным лицом государственного органа, осуществляющим надзор за дорожным движением, а также его фамилию и должность.","w":{"uk":"Неповна відповідь: водій також може вимагати посвідчення особи й відступати від вимог законодавства в умовах непереборної сили.","ru":"Неполный ответ: водитель также может требовать удостоверение личности и отступать от требований законодательства в условиях непреодолимой силы."}},{"uk":"Вимагати від особи, яка здійснює нагляд за дорожнім рухом та зупинила транспортний засіб, пред'явлення посвідчення її особи.","ru":"Требовать от лица, осуществляющего надзор за дорожным движением и остановившего транспортное средство, предъявления удостоверения его личности.","w":{"uk":"Неповна відповідь: водій також має право знати причину зупинки й відступати від вимог законодавства в умовах непереборної сили.","ru":"Неполный ответ: водитель также имеет право знать причину остановки и отступать от требований законодательства в условиях непреодолимой силы."}},{"uk":"Відступати від вимог законодавства в умовах дії непереборної сили або коли іншими засобами неможливо запобігти власній загибелі чи каліцтву громадян.","ru":"Отступать от требований законодательства в условиях действия непреодолимой силы или когда иными средствами невозможно предотвратить собственную гибель или увечье граждан.","w":{"uk":"Неповна відповідь: права знати причину зупинки й вимагати посвідчення особи теж передбачені {p:2.14}.","ru":"Неполный ответ: права знать причину остановки и требовать удостоверение личности тоже предусмотрены {p:2.14}."}},{"uk":"Права, перераховані у відповідях 1, 2, 3.","ru":"Права, перечисленные в ответах 1, 2, 3."}],"c":3,"e":{"uk":"Усі три права перелічені в {p:2.14} (підпункти «в», «г», «е»).","ru":"Все три права перечислены в {p:2.14} (подпункты «в», «г», «е»)."},"ref":["2.14"]},{"id":"h2-21","t":"h2","num":"2.21","q":{"uk":"Що з переліченого нижче не входить в обов'язки водіїв?","ru":"Что из перечисленного ниже не входит в обязанности водителей?"},"a":[{"uk":"Вживати заходів по затриманню осіб, що забруднюють дороги.","ru":"Принимать меры по задержанию лиц, загрязняющих дороги."},{"uk":"Не забруднювати проїзну частину та смугу відведення автомобільних доріг.","ru":"Не загрязнять проезжую часть и полосу отвода автомобильных дорог.","w":{"uk":"Це обов'язок водія за {p:2.3} (підпункт «ґ»).","ru":"Это обязанность водителя согласно {p:2.3} (подпункт «ґ»)."}},{"uk":"На автомобілях, обладнаних засобами пасивної безпеки (підголівники, ремені безпеки), користуватися ними і не перевозити пасажирів, не пристебнутих ременями безпеки у випадках встановлених Правилами дорожнього руху.","ru":"На автомобилях, оборудованных средствами пассивной безопасности (подголовники, ремни безопасности), пользоваться ими и не перевозить пассажиров, не пристёгнутых ремнями безопасности, в случаях, установленных Правилами дорожного движения.","w":{"uk":"Це обов'язок водія за {p:2.3} (підпункт «в»).","ru":"Это обязанность водителя согласно {p:2.3} (подпункт «в»)."}}],"c":0,"e":{"uk":"Затримувати порушників водій не зобов'язаний: {p:2.3} вимагає лише самому не забруднювати дорогу (підпункт «ґ») і повідомляти про виявлені перешкоди для руху (підпункт «е»).","ru":"Задерживать нарушителей водитель не обязан: {p:2.3} требует лишь самому не загрязнять дорогу (подпункт «ґ») и сообщать о выявленных помехах для движения (подпункт «е»)."},"ref":["2.3"]},{"id":"h2-22","t":"h2","num":"2.22","q":{"uk":"Які транспортні засоби належать до категорії В?","ru":"Какие транспортные средства относятся к категории В?"},"a":[{"uk":"Тільки автомобілі, у яких дозволена максимальна маса не перевищує 3500 кг.","ru":"Только автомобили, у которых разрешённая максимальная масса не превышает 3500 кг.","w":{"uk":"Маса до 3500 кг — лише одна з ознак категорії В: важить і кількість місць, а ще до неї належать состави з легким причепом.","ru":"Масса до 3500 кг — лишь один из признаков категории В: важно и количество мест, а ещё к ней относятся составы с лёгким прицепом."}},{"uk":"Тільки автомобілі, у яких кількість сидячих місць, крім сидіння водія, не більш як вісім.","ru":"Только автомобили, у которых количество сидячих мест, кроме сиденья водителя, не более восьми.","w":{"uk":"Кількість місць — лише одна з ознак: має значення й маса до 3500 кг, а ще до категорії В належать состави з причепом до 750 кг.","ru":"Количество мест — лишь один из признаков: имеет значение и масса до 3500 кг, а ещё к категории В относятся составы с прицепом до 750 кг."}},{"uk":"Тільки состави транспортних засобів з тягачем категорії В і причепом, повна маса якого не перевищує 750 кілограмів.","ru":"Только составы транспортных средств с тягачом категории В и прицепом, полная масса которого не превышает 750 килограммов.","w":{"uk":"Состави з легким причепом — лише частина категорії В; передусім до неї належать самі автомобілі до 3500 кг.","ru":"Составы с лёгким прицепом — лишь часть категории В; прежде всего к ней относятся сами автомобили до 3500 кг."}},{"uk":"Усі перелічені вище.","ru":"Все перечисленные выше."}],"c":3,"e":{"uk":"За {p:2.13} до категорії В належать автомобілі з дозволеною максимальною масою до 3500 кг і не більш як вісьмома сидячими місцями, крім місця водія, а також состави з тягачем категорії В і причепом повною масою до 750 кг — тобто всі перелічені.","ru":"Согласно {p:2.13} к категории В относятся автомобили с разрешённой максимальной массой до 3500 кг и не более чем восемью сидячими местами, кроме места водителя, а также составы с тягачом категории В и прицепом полной массой до 750 кг — то есть все перечисленные."},"ref":["2.13"]},{"id":"h2-23","t":"h2","num":"2.23","q":{"uk":"Під час руху поза населеним пунктом ременями безпеки можуть не пристібатися:","ru":"При движении вне населённого пункта ремнями безопасности могут не пристёгиваться:"},"a":[{"uk":"Водії з інвалідністю.","ru":"Водители с инвалидностью.","w":{"uk":"Водії з інвалідністю, яким фізіологічні особливості не дають користуватися ременем, можуть не пристібатися лише в населених пунктах.","ru":"Водители с инвалидностью, которым физиологические особенности не позволяют пользоваться ремнём, могут не пристёгиваться только в населённых пунктах."}},{"uk":"Водії і пасажири оперативних та спеціальних транспортних засобів.","ru":"Водители и пассажиры оперативных и специальных транспортных средств.","w":{"uk":"Водії й пасажири оперативних і спеціальних транспортних засобів звільнені від цього лише в населених пунктах.","ru":"Водители и пассажиры оперативных и специальных транспортных средств освобождены от этого только в населённых пунктах."}},{"uk":"Водії і пасажири таксі.","ru":"Водители и пассажиры такси.","w":{"uk":"Для таксі Правила жодних винятків не передбачають.","ru":"Для такси Правила никаких исключений не предусматривают."}},{"uk":"Особи, що навчають водінню, якщо за кермом учень.","ru":"Лица, обучающие вождению, если за рулём ученик.","w":{"uk":"Для осіб, які навчають водінню, Правила винятків не передбачають.","ru":"Для лиц, обучающих вождению, Правила исключений не предусматривают."}},{"uk":"Усі зобов’язані пристібатися.","ru":"Все обязаны пристёгиваться."}],"c":4,"e":{"uk":"Винятки з {p:2.3} (підпункт «в») діють лише **в населених пунктах**; поза ними пристібатися зобов'язані всі.","ru":"Исключения из {p:2.3} (подпункт «в») действуют только **в населённых пунктах**; вне их пристёгиваться обязаны все."},"ref":["2.3"]},{"id":"h2-24","t":"h2","num":"2.24","q":{"uk":"Згідно з Правилами дорожнього руху на вимогу поліцейського водій повинен...","ru":"Согласно Правилам дорожного движения по требованию полицейского водитель должен..."},"a":[{"uk":"Дати можливість оглянути транспортний засіб, за будь-яких обставин.","ru":"Дать возможность осмотреть транспортное средство при любых обстоятельствах.","w":{"uk":"Огляд «за будь-яких обставин» суперечить {p:2.4}: для нього потрібні законні підстави.","ru":"Осмотр «при любых обстоятельствах» противоречит {p:2.4}: для него нужны законные основания."}},{"uk":"Дати можливість оглянути транспортний засіб тільки за наявності на те законних підстав відповідно до законодавства України.","ru":"Дать возможность осмотреть транспортное средство только при наличии на то законных оснований в соответствии с законодательством Украины."}],"c":1,"e":{"uk":"За {p:2.4} (підпункт «в») водій дає змогу оглянути транспортний засіб відповідно до законодавства **за наявності на те законних підстав**.","ru":"Согласно {p:2.4} (подпункт «в») водитель даёт возможность осмотреть транспортное средство в соответствии с законодательством **при наличии на то законных оснований**."},"ref":["2.4"]},{"id":"h2-25","t":"h2","num":"2.25","q":{"uk":"Водії яких транспортних засобів можуть не надавати свій транспортний засіб поліцейським та працівникам охорони здоров’я у встановлених Правилами дорожнього руху випадках?","ru":"Водители каких транспортных средств могут не предоставлять своё транспортное средство полицейским и работникам здравоохранения в установленных Правилами дорожного движения случаях?"},"a":[{"uk":"Водії транспортних засобів дипломатичних та інших представництв іноземних держав, міжнародних організацій.","ru":"Водители транспортных средств дипломатических и других представительств иностранных государств, международных организаций.","w":{"uk":"Неповна відповідь: від обов'язку звільнені також водії оперативних і спеціальних транспортних засобів.","ru":"Неполный ответ: от обязанности освобождены также водители оперативных и специальных транспортных средств."}},{"uk":"Водії оперативних і спеціальних транспортних засобів.","ru":"Водители оперативных и специальных транспортных средств.","w":{"uk":"Неповна відповідь: від обов'язку звільнені також водії транспортних засобів дипломатичних представництв і міжнародних організацій.","ru":"Неполный ответ: от обязанности освобождены также водители транспортных средств дипломатических представительств и международных организаций."}},{"uk":"Водії таксі.","ru":"Водители такси.","w":{"uk":"Таксі серед винятків {p:2.7} немає.","ru":"Такси среди исключений {p:2.7} нет."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3.","w":{"uk":"Таксі не звільнені від цього обов'язку, тож відповідь 3 зайва.","ru":"Такси не освобождены от этой обязанности, поэтому ответ 3 лишний."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2."}],"c":4,"e":{"uk":"{p:2.7} звільняє від цього обов'язку водіїв транспортних засобів дипломатичних та інших представництв іноземних держав, міжнародних організацій, а також оперативних і спеціальних транспортних засобів.","ru":"{p:2.7} освобождает от этой обязанности водителей транспортных средств дипломатических и других представительств иностранных государств, международных организаций, а также оперативных и специальных транспортных средств."},"ref":["2.7"]},{"id":"h2-26","t":"h2","num":"2.26","q":{"uk":"Водій повинен надавати свій транспортний засіб...","ru":"Водитель должен предоставлять своё транспортное средство..."},"a":[{"uk":"Працівникам дипломатичних та інших представництв іноземних держав, міжнародних організацій.","ru":"Работникам дипломатических и других представительств иностранных государств, международных организаций.","w":{"uk":"Працівникам дипломатичних представництв водій свій транспортний засіб надавати не зобов'язаний — їхні транспортні засоби самі звільнені від цього обов'язку.","ru":"Работникам дипломатических представительств водитель своё транспортное средство предоставлять не обязан — их транспортные средства сами освобождены от этой обязанности."}},{"uk":"Поліцейським та працівникам охорони здоров’я для доставки до найближчого закладу охорони здоров’я осіб, які потребують екстреної (швидкої) медичної допомоги.","ru":"Полицейским и работникам здравоохранения для доставки в ближайшее учреждение здравоохранения лиц, нуждающихся в экстренной (скорой) медицинской помощи.","w":{"uk":"Неповна відповідь: транспортний засіб надають також поліцейським для транспортування пошкоджених транспортних засобів.","ru":"Неполный ответ: транспортное средство предоставляют также полицейским для транспортировки повреждённых транспортных средств."}},{"uk":"Поліцейським для транспортування пошкоджених транспортних засобів (залучаються лише вантажні автомобілі).","ru":"Полицейским для транспортировки повреждённых транспортных средств (привлекаются только грузовые автомобили).","w":{"uk":"Неповна відповідь: транспортний засіб надають також для доставлення осіб, які потребують екстреної медичної допомоги.","ru":"Неполный ответ: транспортное средство предоставляют также для доставки лиц, нуждающихся в экстренной медицинской помощи."}},{"uk":"Відповіді 2 і 3.","ru":"Ответы 2 и 3."}],"c":3,"e":{"uk":"Обидва випадки прямо названі в {p:2.7}; для транспортування пошкоджених транспортних засобів залучаються лише вантажні автомобілі.","ru":"Оба случая прямо названы в {p:2.7}; для транспортировки повреждённых транспортных средств привлекаются только грузовые автомобили."},"ref":["2.7"]},{"id":"h2-27","t":"h2","num":"2.27","q":{"uk":"Кому і в яких випадках водій транспортного засобу повинен надати свій транспортний засіб?","ru":"Кому и в каких случаях водитель транспортного средства должен предоставить своё транспортное средство?"},"a":[{"uk":"Поліцейським та працівникам охорони здоров’я для доставки до найближчого лікувального закладу осіб, які потребують екстреної (швидкої) медичної допомоги.","ru":"Полицейским и работникам здравоохранения для доставки в ближайшее лечебное учреждение лиц, нуждающихся в экстренной (скорой) медицинской помощи.","w":{"uk":"Неповна відповідь: транспортний засіб надають також поліцейським для переслідування правопорушників.","ru":"Неполный ответ: транспортное средство предоставляют также полицейским для преследования правонарушителей."}},{"uk":"Поліцейським у випадках, пов'язаних із переслідуванням правопорушників, доставкою їх до органів Національної поліції.","ru":"Полицейским в случаях, связанных с преследованием правонарушителей, доставкой их в органы Национальной полиции.","w":{"uk":"Неповна відповідь: транспортний засіб надають також для доставлення осіб, які потребують екстреної медичної допомоги.","ru":"Неполный ответ: транспортное средство предоставляют также для доставки лиц, нуждающихся в экстренной медицинской помощи."}},{"uk":"Усі відповіді вірні.","ru":"Все ответы верны."}],"c":2,"e":{"uk":"Обидва випадки передбачені {p:2.7} (підпункти «а» і «б»).","ru":"Оба случая предусмотрены {p:2.7} (подпункты «а» и «б»)."},"ref":["2.7"]},{"id":"h2-28","t":"h2","num":"2.28","q":{"uk":"Що з переліченого водієві заборонено?","ru":"Что из перечисленного водителю запрещено?"},"a":[{"uk":"Керувати транспортним засобом у стані алкогольного сп'яніння або під впливом наркотичних чи токсичних речовин.","ru":"Управлять транспортным средством в состоянии алкогольного опьянения или под воздействием наркотических или токсических веществ.","w":{"uk":"Неповна відповідь: заборонено також керувати в хворобливому стані чи стомленим і передавати керування таким особам.","ru":"Неполный ответ: запрещено также управлять в болезненном состоянии или утомлённым и передавать управление таким лицам."}},{"uk":"Керувати транспортним засобом у хворобливому стані, у стані стомлення, а також перебуваючи під впливом лікарських препаратів, що знижують швидкість реакції й увагу.","ru":"Управлять транспортным средством в болезненном состоянии, в состоянии утомления, а также находясь под воздействием лекарственных препаратов, снижающих скорость реакции и внимание.","w":{"uk":"Неповна відповідь: заборонено також керувати в стані сп'яніння й передавати керування особам у такому стані.","ru":"Неполный ответ: запрещено также управлять в состоянии опьянения и передавать управление лицам в таком состоянии."}},{"uk":"Передавати керування транспортним засобом особам, які перебувають у стані алкогольного сп'яніння, під впливом наркотичних чи токсичних речовин, у хворобливому стані, у стані стомлення або під впливом лікарських препаратів, що знижують швидкість реакції й увагу.","ru":"Передавать управление транспортным средством лицам, находящимся в состоянии алкогольного опьянения, под воздействием наркотических или токсических веществ, в болезненном состоянии, в состоянии утомления или под воздействием лекарственных препаратов, снижающих скорость реакции и внимание.","w":{"uk":"Неповна відповідь: самому водієві теж заборонено керувати в такому стані.","ru":"Неполный ответ: самому водителю тоже запрещено управлять в таком состоянии."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3."},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2.","w":{"uk":"Неповна відповідь: передавати керування таким особам теж заборонено ({p:2.9}, підпункт «г»).","ru":"Неполный ответ: передавать управление таким лицам тоже запрещено ({p:2.9}, подпункт «г»)."}}],"c":3,"e":{"uk":"Усі три заборони містить {p:2.9} (підпункти «а», «б», «г»).","ru":"Все три запрета содержит {p:2.9} (подпункты «а», «б», «г»)."},"ref":["2.9"]},{"id":"h2-29","t":"h2","num":"2.29","q":{"uk":"Хто з водіїв не порушує вимог Правил дорожнього руху, користуючись засобами зв'язку під час руху транспортного засобу?","ru":"Кто из водителей не нарушает требований Правил дорожного движения, пользуясь средствами связи во время движения транспортного средства?"},"a":[{"uk":"Водії зі стажем керування не менш ніж два роки, які користуються засобами зв'язку, тримаючи їх в руці.","ru":"Водители со стажем управления не менее двух лет, пользующиеся средствами связи, держа их в руке.","w":{"uk":"Стаж водіння не скасовує заборони тримати засоби зв'язку в руці.","ru":"Стаж вождения не отменяет запрета держать средства связи в руке."}},{"uk":"Водії таксі.","ru":"Водители такси.","w":{"uk":"Для водіїв таксі винятку немає — він стосується лише водіїв оперативних транспортних засобів під час невідкладного службового завдання.","ru":"Для водителей такси исключения нет — оно касается только водителей оперативных транспортных средств во время неотложного служебного задания."}},{"uk":"Водії, які користуються засобами зв'язку, не тримаючи їх у руці.","ru":"Водители, пользующиеся средствами связи, не держа их в руке."},{"uk":"Усе перелічене вище.","ru":"Всё перечисленное выше.","w":{"uk":"Варіанти 1 і 2 порушують заборону {p:2.9}.","ru":"Варианты 1 и 2 нарушают запрет {p:2.9}."}}],"c":2,"e":{"uk":"{p:2.9} (підпункт «д») забороняє під час руху користуватися засобами зв'язку, **тримаючи їх у руці**; користуватися ними без рук (гарнітура, гучний зв'язок) не заборонено.","ru":"{p:2.9} (подпункт «д») запрещает во время движения пользоваться средствами связи, **держа их в руке**; пользоваться ими без рук (гарнитура, громкая связь) не запрещено."},"ref":["2.9"]},{"id":"h2-30","t":"h2","num":"2.30","q":{"uk":"Чи дозволено водієві – учаснику дорожньо-транспортної пригоди до проведення медичного огляду вживати алкоголь, наркотичні засоби, лікарські препарати, виготовлені на їх основі (крім тих, які входять до офіційно затвердженого складу аптечки)?","ru":"Разрешено ли водителю — участнику дорожно-транспортного происшествия до проведения медицинского осмотра употреблять алкоголь, наркотические средства, лекарственные препараты, изготовленные на их основе (кроме тех, которые входят в официально утверждённый состав аптечки)?"},"a":[{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"Таке вживання прямо заборонене {p:2.10}: воно унеможливить достовірний медичний огляд.","ru":"Такое употребление прямо запрещено {p:2.10}: оно сделает невозможным достоверный медицинский осмотр."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":1,"e":{"uk":"{p:2.10} (підпункт «є») забороняє причетному до ДТП водієві до медичного огляду вживати без призначення медичного працівника алкоголь, наркотики й ліки на їх основі, крім тих, що входять до складу аптечки.","ru":"{p:2.10} (подпункт «є») запрещает причастному к ДТП водителю до медицинского осмотра употреблять без назначения медицинского работника алкоголь, наркотики и лекарства на их основе, кроме входящих в состав аптечки."},"ref":["2.10"]},{"id":"h2-31","t":"h2","num":"2.31","q":{"uk":"Які документи повинен мати при собі водій механічного транспортного засобу?","ru":"Какие документы должен иметь при себе водитель механического транспортного средства?"},"a":[{"uk":"Реєстраційний документ на транспортний засіб.","ru":"Регистрационный документ на транспортное средство.","w":{"uk":"Неповна відповідь: водій має мати при собі також посвідчення водія і страховий поліс.","ru":"Неполный ответ: водитель должен иметь при себе также удостоверение водителя и страховой полис."}},{"uk":"Посвідчення водія на право керування транспортним засобом відповідної категорії і поліс (сертифікат) обов'язкового страхування цивільно-правової відповідальності власників наземних транспортних засобів.","ru":"Удостоверение водителя на право управления транспортным средством соответствующей категории и полис (сертификат) обязательного страхования гражданско-правовой ответственности владельцев наземных транспортных средств.","w":{"uk":"Неповна відповідь: водій має мати при собі також реєстраційний документ на транспортний засіб.","ru":"Неполный ответ: водитель должен иметь при себе также регистрационный документ на транспортное средство."}},{"uk":"Генеральну довіреність на транспортний засіб або тимчасовий реєстраційний талон.","ru":"Генеральную доверенность на транспортное средство или временный регистрационный талон.","w":{"uk":"Довіреності й тимчасового талона в переліку {p:2.1} немає: передаючи автомобіль у користування, власник передає реєстраційний документ ({p:2.2}).","ru":"Доверенности и временного талона в перечне {p:2.1} нет: передавая автомобиль в пользование, владелец передаёт регистрационный документ ({p:2.2})."}},{"uk":"Усе перелічене вище.","ru":"Всё перечисленное выше.","w":{"uk":"Відповідь 3 зайва: довіреність і тимчасовий талон Правила не вимагають.","ru":"Ответ 3 лишний: доверенность и временный талон Правила не требуют."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2."}],"c":4,"e":{"uk":"Перелік {p:2.1}: посвідчення водія відповідної категорії, реєстраційний документ на транспортний засіб і чинний страховий поліс (сертифікат). Довіреності чи тимчасового талона Правила не вимагають.","ru":"Перечень {p:2.1}: удостоверение водителя соответствующей категории, регистрационный документ на транспортное средство и действующий страховой полис (сертификат). Доверенности или временного талона Правила не требуют."},"ref":["2.1","2.2"]},{"id":"h2-32","t":"h2","num":"2.32","q":{"uk":"Власник транспортного засобу має право:","ru":"Владелец транспортного средства имеет право:"},"a":[{"uk":"На безпечні та зручні умови для руху, а також на запит оперативної інформації про дорожні умови та напрямки руху.","ru":"На безопасные и удобные условия для движения, а также на запрос оперативной информации о дорожных условиях и направлениях движения.","w":{"uk":"Неповна відповідь: власник має й інші права за {p:2.12} — довіряти розпорядження транспортним засобом, на відшкодування витрат і збитків.","ru":"Неполный ответ: владелец имеет и другие права согласно {p:2.12} — доверять распоряжение транспортным средством, на возмещение расходов и убытков."}},{"uk":"Тільки довіряти в установленому порядку розпорядження транспортним засобом іншій особі.","ru":"Только доверять в установленном порядке распоряжение транспортным средством другому лицу.","w":{"uk":"Слово «тільки» хибне: власник має й інші права за {p:2.12}.","ru":"Слово «только» ошибочно: владелец имеет и другие права согласно {p:2.12}."}},{"uk":"Тільки на відшкодування витрат у разі надання транспортного засобу поліцейським та працівникам органу охорони здоров'я.","ru":"Только на возмещение расходов в случае предоставления транспортного средства полицейским и работникам органа здравоохранения.","w":{"uk":"Слово «тільки» хибне: відшкодування витрат — лише одне з прав власника за {p:2.12}.","ru":"Слово «только» ошибочно: возмещение расходов — лишь одно из прав владельца согласно {p:2.12}."}},{"uk":"Тільки на відшкодування збитків, завданих внаслідок невідповідності стану автомобільних доріг, вулиць, залізничних переїздів вимогам безпеки дорожнього руху.","ru":"Только на возмещение убытков, причинённых вследствие несоответствия состояния автомобильных дорог, улиц, железнодорожных переездов требованиям безопасности дорожного движения.","w":{"uk":"Слово «тільки» хибне: відшкодування збитків — лише одне з прав власника за {p:2.12}.","ru":"Слово «только» ошибочно: возмещение убытков — лишь одно из прав владельца согласно {p:2.12}."}},{"uk":"Усе перелічене вище.","ru":"Всё перечисленное выше."}],"c":4,"e":{"uk":"Усі ці права перелічені в {p:2.12}.","ru":"Все эти права перечислены в {p:2.12}."},"ref":["2.12"]},{"id":"h2-33","t":"h2","num":"2.33","q":{"uk":"В якому випадку водієві дозволяється залишати транспортний засіб?","ru":"В каком случае водителю разрешается оставлять транспортное средство?"},"a":[{"uk":"Якщо вжиті заходи, що виключають самовільний рух транспортного засобу.","ru":"Если приняты меры, исключающие самопроизвольное движение транспортного средства.","w":{"uk":"Заходів лише проти самовільного руху недостатньо — треба ще вберегти транспортний засіб від проникнення й незаконного заволодіння.","ru":"Мер только против самопроизвольного движения недостаточно — нужно ещё уберечь транспортное средство от проникновения и незаконного завладения."}},{"uk":"Якщо вжиті заходи, щоб не допустити проникнення до автомобіля і (або) незаконне заволодіння ним.","ru":"Если приняты меры, чтобы не допустить проникновения в автомобиль и (или) незаконного завладения им.","w":{"uk":"Заходів лише проти проникнення недостатньо — треба ще виключити самовільний рух транспортного засобу.","ru":"Мер только против проникновения недостаточно — нужно ещё исключить самопроизвольное движение транспортного средства."}},{"uk":"У всіх перерахованих випадках.","ru":"Во всех перечисленных случаях."}],"c":2,"e":{"uk":"За {p:15.12} залишати транспортний засіб можна, лише вживши **всіх** заходів — і проти самовільного руху, і проти проникнення до нього та незаконного заволодіння ним; варіант 3 поєднує обидві умови.","ru":"Согласно {p:15.12} оставлять транспортное средство можно, только приняв **все** меры — и против самопроизвольного движения, и против проникновения в него и незаконного завладения им; вариант 3 объединяет оба условия."},"ref":["15.12"]},{"id":"h2-34","t":"h2","num":"2.34","q":{"uk":"Під час руху транспортного засобу в населеному пункті ременями безпеки можуть не пристібатися:","ru":"При движении транспортного средства в населённом пункте ремнями безопасности могут не пристёгиваться:"},"a":[{"uk":"Водії і пасажири з інвалідністю, фізіологічні особливості яких унеможливлюють користування ременями безпеки.","ru":"Водители и пассажиры с инвалидностью, физиологические особенности которых делают невозможным пользование ремнями безопасности.","w":{"uk":"Неповна відповідь: у населених пунктах можуть не пристібатися також водії й пасажири оперативних і спеціальних транспортних засобів.","ru":"Неполный ответ: в населённых пунктах могут не пристёгиваться также водители и пассажиры оперативных и специальных транспортных средств."}},{"uk":"Водії і пасажири оперативних та спеціальних транспортних засобів.","ru":"Водители и пассажиры оперативных и специальных транспортных средств.","w":{"uk":"Неповна відповідь: у населених пунктах можуть не пристібатися також особи з інвалідністю, яким ремінь не підходить фізіологічно.","ru":"Неполный ответ: в населённых пунктах могут не пристёгиваться также лица с инвалидностью, которым ремень не подходит физиологически."}},{"uk":"Водії таксі.","ru":"Водители такси.","w":{"uk":"Водіїв таксі серед винятків {p:2.3} немає.","ru":"Водителей такси среди исключений {p:2.3} нет."}},{"uk":"Особи, що навчають водінню, якщо за кермом учень.","ru":"Лица, обучающие вождению, если за рулём ученик.","w":{"uk":"Осіб, які навчають водінню, серед винятків {p:2.3} немає.","ru":"Лиц, обучающих вождению, среди исключений {p:2.3} нет."}},{"uk":"Відповіді 1 та 2.","ru":"Ответы 1 и 2."}],"c":4,"e":{"uk":"{p:2.3} (підпункт «в») дозволяє в населених пунктах не пристібатися саме цим двом категоріям: особам з інвалідністю, яким фізіологічні особливості не дають користуватися ременями, та водіям і пасажирам оперативних і спеціальних транспортних засобів.","ru":"{p:2.3} (подпункт «в») разрешает в населённых пунктах не пристёгиваться именно этим двум категориям: лицам с инвалидностью, которым физиологические особенности не позволяют пользоваться ремнями, и водителям и пассажирам оперативных и специальных транспортных средств."},"ref":["2.3"]},{"id":"h2-35","t":"h2","num":"2.35","q":{"uk":"Чи дозволено водію, який причетний до дорожньо-транспортної пригоди, переміщати транспортний засіб і предмети, що мають причетність до пригоди, якщо вони ускладнюють рух іншим учасникам дорожнього руху?","ru":"Разрешено ли водителю, причастному к дорожно-транспортному происшествию, перемещать транспортное средство и предметы, имеющие отношение к происшествию, если они затрудняют движение другим участникам дорожного движения?"},"a":[{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"Винятку для випадків, коли транспортний засіб заважає руху, Правила не роблять: розташування автомобілів і уламків, як на малюнку, — важливі сліди пригоди.","ru":"Исключения для случаев, когда транспортное средство мешает движению, Правила не делают: расположение автомобилей и обломков, как на рисунке, — важные следы происшествия."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":1,"e":{"uk":"{p:2.10} (підпункт «в») забороняє переміщати транспортний засіб і предмети, що мають причетність до пригоди, — навіть якщо вони заважають руху: водій позначає місце пригоди й організовує його об'їзд (підпункти «б», «е»).","ru":"{p:2.10} (подпункт «в») запрещает перемещать транспортное средство и предметы, имеющие отношение к происшествию, — даже если они мешают движению: водитель обозначает место происшествия и организует его объезд (подпункты «б», «е»)."},"ref":["2.10"],"pic":["img/hsc/2-35-1.jpg"]},{"id":"h2-36","t":"h2","num":"2.36","q":{"uk":"Чи дозволено Вам закріпити номерний знак так, як показано на малюнку?","ru":"Разрешено ли вам закрепить номерной знак так, как показано на рисунке?"},"a":[{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"Номерний знак має бути закріплений у встановленому місці — інакше це пряме порушення {p:2.9}.","ru":"Номерной знак должен быть закреплён в установленном месте — иначе это прямое нарушение {p:2.9}."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":1,"e":{"uk":"Номерний знак закріплено збоку бампера під фарою, а не в установленому для нього місці; {p:2.9} (підпункт «в») забороняє керувати транспортним засобом з так закріпленим знаком.","ru":"Номерной знак закреплён сбоку бампера под фарой, а не в установленном для него месте; {p:2.9} (подпункт «в») запрещает управлять транспортным средством с так закреплённым знаком."},"ref":["2.9"],"pic":["img/hsc/2-36-1.jpg"]},{"id":"h2-37","t":"h2","num":"2.37","q":{"uk":"Чи дозволено водієві керувати транспортним засобом, якщо номерний знак забруднений?","ru":"Разрешено ли водителю управлять транспортным средством, если номерной знак загрязнён?"},"a":[{"uk":"Дозволено лише за межами населених пунктів.","ru":"Разрешено только за пределами населённых пунктов.","w":{"uk":"Заборона діє незалежно від місця руху — і поза населеними пунктами теж.","ru":"Запрет действует независимо от места движения — и вне населённых пунктов тоже."}},{"uk":"Дозволено лише в населених пунктах.","ru":"Разрешено только в населённых пунктах.","w":{"uk":"Заборона діє незалежно від місця руху — і в населених пунктах теж.","ru":"Запрет действует независимо от места движения — и в населённых пунктах тоже."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":2,"e":{"uk":"{p:2.9} (підпункт «в») забороняє керувати транспортним засобом, номерний знак якого забруднений так, що символи не можна чітко розпізнати з відстані 20 м, — як на малюнку, де знака майже не видно.","ru":"{p:2.9} (подпункт «в») запрещает управлять транспортным средством, номерной знак которого загрязнён так, что символы нельзя чётко распознать с расстояния 20 м, — как на рисунке, где знак почти не виден."},"ref":["2.9"],"pic":["img/hsc/2-37-1.jpg"]},{"id":"h3-1","t":"h3","num":"3.1","q":{"uk":"Чи повинен водій автомобіля, рухаючись по головній дорозі, дати дорогу транспортному засобу з увімкненим синім проблисковим маячком?","ru":"Должен ли водитель автомобиля, двигаясь по главной дороге, уступить дорогу транспортному средству с включённым синим проблесковым маячком?"},"a":[{"uk":"Не повинен.","ru":"Не должен.","w":{"uk":"Перевага головної дороги не діє щодо транспортного засобу з увімкненим синім маячком: оперативний транспорт має пріоритет над усіма іншими учасниками руху.","ru":"Преимущество главной дороги не действует в отношении транспортного средства с включённым синим маячком: оперативный транспорт имеет приоритет над всеми остальными участниками движения."}},{"uk":"Повинен.","ru":"Должен."}],"c":1,"e":{"uk":"Справа до перехрестя наближається автомобіль швидкої допомоги з увімкненим синім маячком. За {p:3.2} йому зобов'язані дати дорогу всі водії, які можуть створити перешкоду, — і те, що ви їдете головною дорогою (знак {s:2.3}), цього обов'язку не скасовує.","ru":"Справа к перекрёстку приближается автомобиль скорой помощи с включённым синим маячком. Согласно {p:3.2} ему обязаны уступить дорогу все водители, которые могут создать помеху, — и то, что вы едете по главной дороге (знак {s:2.3}), этой обязанности не отменяет."},"ref":["3.2"],"pic":["img/hsc/3-1-1.jpg"]},{"id":"h3-2","t":"h3","num":"3.2","q":{"uk":"Чи повинен водій транспортного засобу з увімкненим проблисковим маячком синього кольору, що рухається на спуск, де зустрічний роз'їзд утруднено, дати дорогу транспортним засобам, які рухаються на підйом?","ru":"Должен ли водитель транспортного средства с включённым проблесковым маячком синего цвета, движущегося на спуск, где встречный разъезд затруднён, уступить дорогу транспортным средствам, движущимся на подъём?"},"a":[{"uk":"Повинен.","ru":"Должен.","w":{"uk":"Обов'язок дати дорогу на спуску ({p:28.1}) входить до переліку вимог, від яких оперативний транспорт з увімкненим маячком може відступати за {p:3.1}.","ru":"Обязанность уступить дорогу на спуске ({p:28.1}) входит в перечень требований, от которых оперативный транспорт с включённым маячком может отступать согласно {p:3.1}."}},{"uk":"Не повинен.","ru":"Не должен."}],"c":1,"e":{"uk":"Зазвичай на спуску, де зустрічний роз'їзд утруднено, дорогу дає той, хто їде вниз ({p:28.1}). Але {p:3.1} дозволяє водієві оперативного транспортного засобу з увімкненим синім або червоним маячком відступати саме від пункту 28.1, а інші водії самі мають дати йому дорогу ({p:3.2}).","ru":"Обычно на спуске, где встречный разъезд затруднён, дорогу уступает тот, кто едет вниз ({p:28.1}). Но {p:3.1} позволяет водителю оперативного транспортного средства с включённым синим или красным маячком отступать именно от пункта 28.1, а остальные водители сами должны уступить ему дорогу ({p:3.2})."},"ref":["3.1","3.2","28.1"],"pic":["img/hsc/3-2-1.jpg"]},{"id":"h3-3","t":"h3","num":"3.3","q":{"uk":"Наближаючись до нерухомого автомобіля з увімкненим проблисковим маячком синього кольору, що стоїть на узбіччі (біля проїзної частини) або на проїзній частині, водій повинен:","ru":"Приближаясь к неподвижному автомобилю с включённым проблесковым маячком синего цвета, стоящему на обочине (у проезжей части) или на проезжей части, водитель должен:"},"a":[{"uk":"Не знижуючи швидкості, продовжити рух по суміжній смузі попутного напрямку.","ru":"Не снижая скорости, продолжить движение по смежной полосе попутного направления.","w":{"uk":"Знизити швидкість до 40 км/год потрібно обов'язково, незалежно від того, якою смугою ви рухаєтеся.","ru":"Снизить скорость до 40 км/ч нужно обязательно, независимо от того, по какой полосе вы движетесь."}},{"uk":"Зупинитися біля правого краю проїзної частини (на узбіччі) й очікувати сигналу регулювальника.","ru":"Остановиться у правого края проезжей части (на обочине) и ожидать сигнала регулировщика.","w":{"uk":"Зупинятися завчасно Правила не вимагають — лише в разі відповідного сигналу регулювальника.","ru":"Останавливаться заранее Правила не требуют — только в случае соответствующего сигнала регулировщика."}},{"uk":"Знизити швидкість до 40 км/год. і в разі подання регулювальником відповідного сигналу зупинитися.","ru":"Снизить скорость до 40 км/ч и в случае подачи регулировщиком соответствующего сигнала остановиться."}],"c":2,"e":{"uk":"Це пряма вимога {p:3.5}: біля нерухомого автомобіля із синім маячком швидкість знижують до 40 км/год, а зупиняються, лише якщо регулювальник (на малюнку — поліцейський на проїзній частині) подасть відповідний сигнал.","ru":"Это прямое требование {p:3.5}: у неподвижного автомобиля с синим маячком скорость снижают до 40 км/ч, а останавливаются, только если регулировщик (на рисунке — полицейский на проезжей части) подаст соответствующий сигнал."},"ref":["3.5"],"pic":["img/hsc/3-3-1.jpg"]},{"id":"h3-4","t":"h3","num":"3.4","q":{"uk":"Чи дозволено водієві синього автомобіля зайняти місце в даній колоні?","ru":"Разрешено ли водителю синего автомобиля занять место в данной колонне?"},"a":[{"uk":"Так.","ru":"Да.","w":{"uk":"Займати місце в супроводжуваній колоні прямо заборонено ({p:3.4}).","ru":"Занимать место в сопровождаемой колонне прямо запрещено ({p:3.4})."}},{"uk":"Ні.","ru":"Нет."},{"uk":"Так, якщо швидкість руху колони менш ніж 30 км/год.","ru":"Да, если скорость движения колонны менее 30 км/ч.","w":{"uk":"Заборона {p:3.4} діє за будь-якої швидкості колони — жодного винятку для 30 км/год у ній немає.","ru":"Запрет {p:3.4} действует при любой скорости колонны — никакого исключения для 30 км/ч в нём нет."}}],"c":1,"e":{"uk":"Колону замикає автомобіль з увімкненим зеленим проблисковим маячком, а {p:3.4} забороняє займати місце в такій колоні, так само як обганяти, випереджати її чи рухатися суміжною смугою зі швидкістю колони.","ru":"Колонну замыкает автомобиль с включённым зелёным проблесковым маячком, а {p:3.4} запрещает занимать место в такой колонне, так же как обгонять, опережать её или двигаться по смежной полосе со скоростью колонны."},"ref":["3.4"],"pic":["img/hsc/3-4-1.jpg"]},{"id":"h3-5","t":"h3","num":"3.5","q":{"uk":"Чи дозволено водієві синього автомобіля виконати випередження автомобіля що супроводжує колону і рухається з увімкненим зеленим проблисковим маячком?","ru":"Разрешено ли водителю синего автомобиля выполнить опережение автомобиля, который сопровождает колонну и движется с включённым зелёным проблесковым маячком?"},"a":[{"uk":"Заборонено.","ru":"Запрещено."},{"uk":"Дозволено, якщо він рухається зі швидкістю менш ніж 30 км/год., дотримуючись заходів безпеки.","ru":"Разрешено, если он движется со скоростью менее 30 км/ч, соблюдая меры безопасности.","w":{"uk":"Швидкість колони на заборону не впливає: {p:3.4} не робить винятку для повільного руху.","ru":"Скорость колонны на запрет не влияет: {p:3.4} не делает исключения для медленного движения."}},{"uk":"Дозволено в будь-якому разі.","ru":"Разрешено в любом случае.","w":{"uk":"Випереджати транспортний засіб із зеленим маячком прямо заборонено ({p:3.4}).","ru":"Опережать транспортное средство с зелёным маячком прямо запрещено ({p:3.4})."}}],"c":0,"e":{"uk":"Автомобіль із зеленим маячком замикає супроводжувану колону, і обмеження для інших водіїв скасовуються лише після його проїзду ({p:3.3}). Тому {p:3.4} забороняє обгін і **випередження** таких транспортних засобів.","ru":"Автомобиль с зелёным маячком замыкает сопровождаемую колонну, и ограничения для других водителей отменяются только после его проезда ({p:3.3}). Поэтому {p:3.4} запрещает обгон и **опережение** таких транспортных средств."},"ref":["3.3","3.4"],"pic":["img/hsc/3-5-1.jpg"]},{"id":"h3-6","t":"h3","num":"3.6","q":{"uk":"Як вчинити водієві транспортного засобу, до якого ззаду наближається автомобіль з увімкненим проблисковим маячком синього кольору та (або) звуковим сигналом?","ru":"Как поступить водителю транспортного средства, к которому сзади приближается автомобиль с включённым проблесковым маячком синего цвета и (или) звуковым сигналом?"},"a":[{"uk":"Зупинитися біля правого краю проїзної частини (на правому узбіччі).","ru":"Остановиться у правого края проезжей части (на правой обочине).","w":{"uk":"Зупинятися біля правого краю обов'язково лише тоді, коли ввімкнено синій і червоний або лише червоний маячки ({p:3.2}).","ru":"Останавливаться у правого края обязательно только тогда, когда включены синий и красный или только красный маячки ({p:3.2})."}},{"uk":"Звільнити займану смугу руху.","ru":"Освободить занимаемую полосу движения.","w":{"uk":"Звільнити смугу — лише один із можливих способів поступитися; Правила вимагають саме дати дорогу й забезпечити безперешкодний проїзд.","ru":"Освободить полосу — лишь один из возможных способов уступить; Правила требуют именно уступить дорогу и обеспечить беспрепятственный проезд."}},{"uk":"Дати йому дорогу і забезпечити безперешкодний проїзд зазначеного транспортного засобу.","ru":"Уступить ему дорогу и обеспечить беспрепятственный проезд указанного транспортного средства."}],"c":2,"e":{"uk":"На поліцейському автомобілі ввімкнено лише синій маячок, тож за {p:3.2} водій, який може створити йому перешкоду, зобов'язаний дати дорогу й забезпечити безперешкодний проїзд; як саме — вирішує за обставинами.","ru":"На полицейском автомобиле включён только синий маячок, поэтому согласно {p:3.2} водитель, который может создать ему помеху, обязан уступить дорогу и обеспечить беспрепятственный проезд; как именно — решает по обстоятельствам."},"ref":["3.2"],"pic":["img/hsc/3-6-1.jpg"]},{"id":"h3-7","t":"h3","num":"3.7","q":{"uk":"Як повинен вчинити водій у даній ситуації в разі наближення оперативного транспортного засобу?","ru":"Как должен поступить водитель в данной ситуации при приближении оперативного транспортного средства?"},"a":[{"uk":"Зупинитися біля правого краю проїзної частини (на узбіччі).","ru":"Остановиться у правого края проезжей части (на обочине)."},{"uk":"Знизити швидкість до 40 км/год.","ru":"Снизить скорость до 40 км/ч.","w":{"uk":"Знизити швидкість до 40 км/год вимагає {p:3.5}, коли проїжджаєте повз нерухомий автомобіль із синім маячком, а тут оперативний автомобіль рухається із синім і червоним маячками.","ru":"Снизить скорость до 40 км/ч требует {p:3.5}, когда проезжаете мимо неподвижного автомобиля с синим маячком, а здесь оперативный автомобиль движется с синим и красным маячками."}},{"uk":"Продовжувати рух із дотриманням вимог цих Правил.","ru":"Продолжать движение с соблюдением требований настоящих Правил.","w":{"uk":"Продовжувати рух не можна: синій і червоний маячки зобов'язують зупинитися біля правого краю ({p:3.2}).","ru":"Продолжать движение нельзя: синий и красный маячки обязывают остановиться у правого края ({p:3.2})."}}],"c":0,"e":{"uk":"На поліцейському автомобілі ввімкнено проблискові маячки **синього і червоного** кольору, а в такому разі {p:3.2} зобов'язує водіїв інших транспортних засобів зупинитися біля правого краю проїзної частини (на правому узбіччі).","ru":"На полицейском автомобиле включены проблесковые маячки **синего и красного** цвета, а в таком случае {p:3.2} обязывает водителей других транспортных средств остановиться у правого края проезжей части (на правой обочине)."},"ref":["3.2"],"pic":["img/hsc/3-7-1.jpg"]},{"id":"h3-8","t":"h3","num":"3.8","q":{"uk":"Чи дозволено Вам виконати обгін одиночного транспортного засобу, що рухається з увімкненим синім проблисковим маячком?","ru":"Разрешено ли вам выполнить обгон одиночного транспортного средства, движущегося с включённым синим проблесковым маячком?"},"a":[{"uk":"Заборонено.","ru":"Запрещено.","w":{"uk":"Заборона обгону з {p:3.4} стосується лише сполучень синього з червоним, червоного, зеленого або синього з зеленим маячків, а не одного синього.","ru":"Запрет обгона из {p:3.4} касается только сочетаний синего с красным, красного, зелёного или синего с зелёным маячков, а не одного синего."}},{"uk":"Дозволено.","ru":"Разрешено."}],"c":1,"e":{"uk":"{p:3.4} забороняє обганяти транспортні засоби з маячками синього і червоного, лише червоного, зеленого або синього і зеленого кольору та супроводжувані ними колони. Одиночний автомобіль лише із синім маячком до цього переліку не входить, тож обгін можливий за загальними правилами ({p:14.2}), якщо ви не створюєте йому перешкоди ({p:3.2}).","ru":"{p:3.4} запрещает обгонять транспортные средства с маячками синего и красного, только красного, зелёного или синего и зелёного цвета и сопровождаемые ими колонны. Одиночный автомобиль только с синим маячком в этот перечень не входит, поэтому обгон возможен по общим правилам ({p:14.2}), если вы не создаёте ему помехи ({p:3.2})."},"ref":["3.4","14.2"]},{"id":"h3-9","t":"h3","num":"3.9","q":{"uk":"Який проблисковий маячок повинен бути увімкнений на транспортному засобі, що замикає колону, якщо на транспортному засобі, що рухається попереду колони, увімкнено проблискові маячки червоного та синього кольору?","ru":"Какой проблесковый маячок должен быть включён на транспортном средстве, замыкающем колонну, если на транспортном средстве, движущемся впереди колонны, включены проблесковые маячки красного и синего цвета?"},"a":[{"uk":"Синій проблисковий маячок.","ru":"Синий проблесковый маячок.","w":{"uk":"Лише синього маячка замикаючому транспортному засобу недостатньо: {p:3.3} вимагає зеленого маячка (окремо або разом із синім).","ru":"Только синего маячка замыкающему транспортному средству недостаточно: {p:3.3} требует зелёного маячка (отдельно или вместе с синим)."}},{"uk":"Синій і зелений проблискові маячки.","ru":"Синий и зелёный проблесковые маячки.","w":{"uk":"Неповна відповідь: колону може замикати й транспортний засіб лише із зеленим маячком.","ru":"Неполный ответ: колонну может замыкать и транспортное средство только с зелёным маячком."}},{"uk":"Зелений проблисковий маячок.","ru":"Зелёный проблесковый маячок.","w":{"uk":"Неповна відповідь: допускається й поєднання синього і зеленого маячків.","ru":"Неполный ответ: допускается и сочетание синего и зелёного маячков."}},{"uk":"Відповіді 2 і 3.","ru":"Ответы 2 и 3."},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3.","w":{"uk":"Варіант 1 (лише синій маячок) неправильний, тож неправильна й ця відповідь.","ru":"Вариант 1 (только синий маячок) неверен, поэтому неверен и этот ответ."}}],"c":3,"e":{"uk":"За {p:3.3} таку колону замикає транспортний засіб із зеленим **або** синім і зеленим проблисковими маячками — тому правильні обидва варіанти, 2 і 3.","ru":"Согласно {p:3.3} такую колонну замыкает транспортное средство с зелёным **или** синим и зелёным проблесковыми маячками — поэтому верны оба варианта, 2 и 3."},"ref":["3.3"]},{"id":"h3-10","t":"h3","num":"3.10","q":{"uk":"Чи зобов’язаний водій транспортного засобу надавати переважне право для проїзду транспортним засобам із включеними синіми або червоними проблисковими маячками та спеціальними звуковими сигналами?","ru":"Обязан ли водитель транспортного средства предоставлять преимущественное право на проезд транспортным средствам с включёнными синими или красными проблесковыми маячками и специальными звуковыми сигналами?"},"a":[{"uk":"Зобов’язаний.","ru":"Обязан."},{"uk":"Не зобов’язаний.","ru":"Не обязан.","w":{"uk":"Надати перевагу такому транспортному засобу — прямий обов'язок, а не право водія ({p:3.2}).","ru":"Предоставить преимущество такому транспортному средству — прямая обязанность, а не право водителя ({p:3.2})."}}],"c":0,"e":{"uk":"За {p:3.2} водії, які можуть створити перешкоду транспортному засобу з увімкненим синім маячком та (або) спеціальним звуковим сигналом, зобов'язані дати йому дорогу, а за червоного маячка — ще й зупинитися біля правого краю проїзної частини.","ru":"Согласно {p:3.2} водители, которые могут создать помеху транспортному средству с включённым синим маячком и (или) специальным звуковым сигналом, обязаны уступить ему дорогу, а при красном маячке — ещё и остановиться у правого края проезжей части."},"ref":["3.2"]},{"id":"h3-11","t":"h3","num":"3.11","q":{"uk":"Чи дозволено водієві транспортного засобу з увімкненим проблисковим маячком синього або червоного кольору рухатися на заборонний сигнал регулювальника?","ru":"Разрешено ли водителю транспортного средства с включённым проблесковым маячком синего или красного цвета двигаться на запрещающий сигнал регулировщика?"},"a":[{"uk":"Дозволено завжди.","ru":"Разрешено всегда.","w":{"uk":"Сигнали регулювальника прямо виключено з переліку вимог, від яких можна відступати ({p:3.1}).","ru":"Сигналы регулировщика прямо исключены из перечня требований, от которых можно отступать ({p:3.1})."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":1,"e":{"uk":"{p:3.1} дозволяє оперативному транспорту відступати від вимог розділу 8 про регулювання руху, **крім сигналів регулювальника** — їх зобов'язані виконувати й водії з увімкненими маячками.","ru":"{p:3.1} позволяет оперативному транспорту отступать от требований раздела 8 о регулировании движения, **кроме сигналов регулировщика** — их обязаны выполнять и водители с включёнными маячками."},"ref":["3.1"]},{"id":"h3-12","t":"h3","num":"3.12","q":{"uk":"Водії оперативних транспортних засобів, виконуючи невідкладне службове завдання, увімкнувши проблисковий маячок червоного або синього кольору, можуть відступати від:","ru":"Водители оперативных транспортных средств, выполняя неотложное служебное задание, включив проблесковый маячок красного или синего цвета, могут отступать от:"},"a":[{"uk":"Правил маневрування й обгону.","ru":"Правил маневрирования и обгона."},{"uk":"Правил проїзду залізничних переїздів.","ru":"Правил проезда железнодорожных переездов.","w":{"uk":"Розділу 20 про рух через залізничні переїзди в переліку {p:3.1} немає — ці правила обов'язкові й для оперативного транспорту.","ru":"Раздела 20 о движении через железнодорожные переезды в перечне {p:3.1} нет — эти правила обязательны и для оперативного транспорта."}},{"uk":"Вимог сигналів регулювальника.","ru":"Требований сигналов регулировщика.","w":{"uk":"{p:3.1} прямо робить виняток: від сигналів регулювальника відступати не можна.","ru":"{p:3.1} прямо делает исключение: от сигналов регулировщика отступать нельзя."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3.","w":{"uk":"Правильний лише варіант 1, тож поєднання 1, 2 і 3 неправильне.","ru":"Верен только вариант 1, поэтому сочетание 1, 2 и 3 неверно."}}],"c":0,"e":{"uk":"Перелік у {p:3.1} містить розділи 10 (початок руху та зміна його напрямку, тобто маневрування) і 14 (обгін), але не містить розділу 20 про залізничні переїзди й прямо виключає сигнали регулювальника.","ru":"Перечень в {p:3.1} содержит разделы 10 (начало движения и изменение его направления, то есть маневрирование) и 14 (обгон), но не содержит раздела 20 о железнодорожных переездах и прямо исключает сигналы регулировщика."},"ref":["3.1"]},{"id":"h3-13","t":"h3","num":"3.13","q":{"uk":"За яких умов водії оперативних транспортних засобів мають перевагу в русі перед іншими учасниками дорожнього руху?","ru":"При каких условиях водители оперативных транспортных средств имеют преимущество в движении перед другими участниками дорожного движения?"},"a":[{"uk":"З увімкненим проблисковим маячком оранжевого кольору разом зі спеціальним звуковим сигналом, за умови забезпечення безпеки дорожнього руху.","ru":"С включённым проблесковым маячком оранжевого цвета вместе со специальным звуковым сигналом, при условии обеспечения безопасности дорожного движения.","w":{"uk":"Оранжевий маячок, навіть разом зі звуковим сигналом, лише привертає увагу й попереджає про небезпеку, але переваги в русі не дає ({p:3.6}).","ru":"Оранжевый маячок, даже вместе со звуковым сигналом, лишь привлекает внимание и предупреждает об опасности, но преимущества в движении не даёт ({p:3.6})."}},{"uk":"За умови увімкнення проблискового маячка синього або червоного кольору та забезпечення безпеки дорожнього руху.","ru":"При условии включения проблескового маячка синего или красного цвета и обеспечения безопасности дорожного движения."}],"c":1,"e":{"uk":"Перевагу в русі дає лише ввімкнений синій або червоний проблисковий маячок ({p:3.1}, {p:3.2}) за умови забезпечення безпеки руху; оранжевий маячок переваги не дає ({p:3.6}).","ru":"Преимущество в движении даёт только включённый синий или красный проблесковый маячок ({p:3.1}, {p:3.2}) при условии обеспечения безопасности движения; оранжевый маячок преимущества не даёт ({p:3.6})."},"ref":["3.1","3.2","3.6"]},{"id":"h3-14","t":"h3","num":"3.14","q":{"uk":"Чи завжди на оперативному транспортному засобі, що виконує невідкладне службове завдання, поряд з увімкненими проблисковими маячками червоного або синього кольору необхідно вмикати спеціальний звуковий сигнал?","ru":"Всегда ли на оперативном транспортном средстве, выполняющем неотложное служебное задание, наряду с включёнными проблесковыми маячками красного или синего цвета необходимо включать специальный звуковой сигнал?"},"a":[{"uk":"Повинен бути обов'язково увімкнений на дорогах з інтенсивним рухом.","ru":"Должен быть обязательно включён на дорогах с интенсивным движением.","w":{"uk":"Правила не пов'язують звуковий сигнал з інтенсивністю руху — важить лише те, чи потрібно додатково привернути увагу.","ru":"Правила не связывают звуковой сигнал с интенсивностью движения — важно лишь то, нужно ли дополнительно привлечь внимание."}},{"uk":"Можна не вмикати за відсутності необхідності додаткового привертання уваги учасників дорожнього руху.","ru":"Можно не включать при отсутствии необходимости дополнительного привлечения внимания участников дорожного движения."}],"c":1,"e":{"uk":"Останнє речення {p:3.1}: за відсутності необхідності додатково привертати увагу учасників дорожнього руху спеціальний звуковий сигнал може бути вимкнений.","ru":"Последнее предложение {p:3.1}: при отсутствии необходимости дополнительно привлекать внимание участников дорожного движения специальный звуковой сигнал может быть выключен."},"ref":["3.1"]},{"id":"h3-15","t":"h3","num":"3.15","q":{"uk":"Чи повинен водій надавати перевагу в русі автомобілю екстреної (швидкої) медичної допомоги?","ru":"Должен ли водитель предоставлять преимущество в движении автомобилю экстренной (скорой) медицинской помощи?"},"a":[{"uk":"Повинен завжди.","ru":"Должен всегда.","w":{"uk":"Без увімкнених маячка чи звукового сигналу автомобіль швидкої допомоги переваги в русі не має.","ru":"Без включённых маячка или звукового сигнала автомобиль скорой помощи преимущества в движении не имеет."}},{"uk":"Не повинен.","ru":"Не должен.","w":{"uk":"Якщо ввімкнено маячок та (або) звуковий сигнал, дати дорогу обов'язково ({p:3.2}).","ru":"Если включены маячок и (или) звуковой сигнал, уступить дорогу обязательно ({p:3.2})."}},{"uk":"Повинен тільки у разі ввімкнення проблискових маячків та (або) спеціального звукового сигналу.","ru":"Должен только в случае включения проблесковых маячков и (или) специального звукового сигнала."}],"c":2,"e":{"uk":"Обов'язок дати дорогу за {p:3.2} виникає лише тоді, коли ввімкнено синій проблисковий маячок та (або) спеціальний звуковий сигнал. На малюнку маячки вимкнено, тож такий автомобіль — звичайний учасник руху.","ru":"Обязанность уступить дорогу согласно {p:3.2} возникает только тогда, когда включён синий проблесковый маячок и (или) специальный звуковой сигнал. На рисунке маячки выключены, поэтому такой автомобиль — обычный участник движения."},"ref":["3.1","3.2"],"pic":["img/hsc/3-15-1.jpg"]},{"id":"h3-16","t":"h3","num":"3.16","q":{"uk":"Чи надає перевагу в русі ввімкнення проблискового маячка оранжевого кольору на транспортних засобах дорожньо-експлуатаційної служби під час виконання роботи?","ru":"Даёт ли преимущество в движении включение проблескового маячка оранжевого цвета на транспортных средствах дорожно-эксплуатационной службы во время выполнения работы?"},"a":[{"uk":"Так.","ru":"Да.","w":{"uk":"Оранжевий маячок, на відміну від синього чи червоного, переваги не дає ({p:3.6}).","ru":"Оранжевый маячок, в отличие от синего или красного, преимущества не даёт ({p:3.6})."}},{"uk":"Ні.","ru":"Нет."}],"c":1,"e":{"uk":"За {p:3.6} оранжевий маячок на машинах дорожно-експлуатаційної служби переваги в русі не дає, а лише привертає увагу й попереджає про небезпеку; водії інших транспортних засобів при цьому не повинні перешкоджати їхній роботі.","ru":"Согласно {p:3.6} оранжевый маячок на машинах дорожно-эксплуатационной службы преимущества в движении не даёт, а лишь привлекает внимание и предупреждает об опасности; водители других транспортных средств при этом не должны мешать их работе."},"ref":["3.6"],"pic":["img/hsc/3-16-1.jpg"]},{"id":"h4-1","t":"h4","num":"4.1","q":{"uk":"З якого боку від трамвая пішоходам дозволяється виходити на проїзну частину під час посадки на трамвай, якщо трамвайна зупинка не обладнана посадковим майданчиком?","ru":"С какой стороны от трамвая пешеходам разрешается выходить на проезжую часть при посадке в трамвай, если трамвайная остановка не оборудована посадочной площадкой?"},"a":[{"uk":"Лише з боку дверей і тільки після зупинки трамвая.","ru":"Только со стороны дверей и только после остановки трамвая."},{"uk":"З будь-якого боку – пішоходи мають перевагу в русі.","ru":"С любой стороны — пешеходы имеют преимущество в движении.","w":{"uk":"Пішохід має перевагу лише на позначених пішохідних переходах ({p:4.16}), а виходити на проїзну частину з протилежного від дверей боку небезпечно й заборонено.","ru":"Пешеход имеет преимущество только на обозначенных пешеходных переходах ({p:4.16}), а выходить на проезжую часть с противоположной от дверей стороны опасно и запрещено."}},{"uk":"Лише з боку дверей, коли трамвай перебуває в зоні видимості.","ru":"Только со стороны дверей, когда трамвай находится в зоне видимости.","w":{"uk":"Трамвай, який лише видно, ще рухається: виходити на проїзну частину можна тільки після його зупинки.","ru":"Трамвай, который только виден, ещё движется: выходить на проезжую часть можно только после его остановки."}}],"c":0,"e":{"uk":"На малюнку зупинка трамвая (знак {s:5.46.1}) без посадкового майданчика. За {p:4.12} у такому разі виходити на проїзну частину дозволено лише з боку дверей і тільки після того, як трамвай зупиниться.","ru":"На рисунке остановка трамвая (знак {s:5.46.1}) без посадочной площадки. Согласно {p:4.12} в таком случае выходить на проезжую часть разрешено только со стороны дверей и только после того, как трамвай остановится."},"ref":["4.12"],"pic":["img/hsc/4-1-1.jpg"]},{"id":"h4-2","t":"h4","num":"4.2","q":{"uk":"За наявності підземних і надземних пішохідних переходів пішоходи повинні переходити проїзну частину:","ru":"При наличии подземных и надземных пешеходных переходов пешеходы должны переходить проезжую часть:"},"a":[{"uk":"По них або по лініях тротуарів чи узбіч на перехрестях.","ru":"По ним или по линиям тротуаров либо обочин на перекрёстках.","w":{"uk":"Перехід на перехресті по лініях тротуарів чи узбіч допускається лише тоді, коли пішохідного переходу немає ({p:4.7}).","ru":"Переход на перекрёстке по линиям тротуаров или обочин допускается только тогда, когда пешеходного перехода нет ({p:4.7})."}},{"uk":"За ними або під прямим кутом до краю проїзної частини в місцях, де дорогу добре видно в обидва боки, і лише після того, як переконаються у відсутності небезпеки.","ru":"За ними или под прямым углом к краю проезжей части в местах, где дорога хорошо просматривается в обе стороны, и лишь после того, как убедятся в отсутствии опасности.","w":{"uk":"Переходити під прямим кутом дозволено лише тоді, коли в зоні видимості немає ні переходу, ні перехрестя ({p:4.8}).","ru":"Переходить под прямым углом разрешено только тогда, когда в зоне видимости нет ни перехода, ни перекрёстка ({p:4.8})."}},{"uk":"Тільки по них.","ru":"Только по ним."}],"c":2,"e":{"uk":"{p:4.7} вимагає переходити проїзну частину по пішохідних переходах, у тому числі підземних і надземних (знаки {s:5.40.1}, {s:5.41.1}); перехрестя чи інші місця допускаються лише **за відсутності** переходу ({p:4.7}, {p:4.8}).","ru":"{p:4.7} требует переходить проезжую часть по пешеходным переходам, в том числе подземным и надземным (знаки {s:5.40.1}, {s:5.41.1}); перекрёстки или другие места допускаются только **при отсутствии** перехода ({p:4.7}, {p:4.8})."},"ref":["4.7","4.8"],"pic":["img/hsc/4-2-1.jpg"]},{"id":"h4-3","t":"h4","num":"4.3","q":{"uk":"Рухаючись тротуарами і пішохідними доріжками, пішоходи повинні дотримуватись:","ru":"Двигаясь по тротуарам и пешеходным дорожкам, пешеходы должны придерживаться:"},"a":[{"uk":"Правого боку.","ru":"Правой стороны."},{"uk":"Лівого боку.","ru":"Левой стороны.","w":{"uk":"Назустріч транспорту пішоходи йдуть лише узбіччям чи краєм проїзної частини ({p:4.1}, {p:4.3}), а тротуаром і пішохідною доріжкою — правим боком.","ru":"Навстречу транспорту пешеходы идут только по обочине или краю проезжей части ({p:4.1}, {p:4.3}), а по тротуару и пешеходной дорожке — по правой стороне."}},{"uk":"Будь-якого боку, як кому зручніше.","ru":"Любой стороны, как кому удобнее.","w":{"uk":"Правила встановлюють чіткий порядок — правий бік, щоб зустрічні потоки пішоходів не заважали один одному.","ru":"Правила устанавливают чёткий порядок — правая сторона, чтобы встречные потоки пешеходов не мешали друг другу."}}],"c":0,"e":{"uk":"{p:4.1}: пішоходи повинні рухатися по тротуарах і пішохідних доріжках (знак {s:4.16}), тримаючись **правого** боку.","ru":"{p:4.1}: пешеходы должны двигаться по тротуарам и пешеходным дорожкам (знак {s:4.16}), придерживаясь **правой** стороны."},"ref":["4.1"],"pic":["img/hsc/4-3-1.jpg"]},{"id":"h4-4","t":"h4","num":"4.4","q":{"uk":"В яких випадках пішоходу дозволено рух краєм проїзної частини?","ru":"В каких случаях пешеходу разрешено движение по краю проезжей части?"},"a":[{"uk":"Тільки в світлу пору доби, рухаючись назустріч руху транспортних засобів.","ru":"Только в светлое время суток, двигаясь навстречу движению транспортных средств.","w":{"uk":"Пора доби тут не є умовою: краєм проїзної частини можна йти й у темряві, якщо немає тротуару й узбіччя, використовуючи світлоповертальні елементи ({p:4.4}).","ru":"Время суток здесь не является условием: по краю проезжей части можно идти и в темноте, если нет тротуара и обочины, используя световозвращающие элементы ({p:4.4})."}},{"uk":"У темну пору доби або в умовах недостатньої видимості рухатися назустріч руху транспортних засобів, виділивши себе або маючи на зовнішньому одязі світловідбиваючі елементи.","ru":"В тёмное время суток или в условиях недостаточной видимости двигаться навстречу движению транспортных средств, выделив себя или имея на верхней одежде световозвращающие элементы.","w":{"uk":"Світлоповертальні елементи в темряві обов'язкові ({p:4.4}), але самі по собі не дають права йти краєм проїзної частини, коли є тротуар чи узбіччя.","ru":"Световозвращающие элементы в темноте обязательны ({p:4.4}), но сами по себе не дают права идти по краю проезжей части, когда есть тротуар или обочина."}},{"uk":"За відсутності тротуарів або пішохідних доріжок.","ru":"При отсутствии тротуаров или пешеходных дорожек.","w":{"uk":"Неповна відповідь: якщо тротуару немає, а узбіччя є, іти треба узбіччям ({p:4.1}).","ru":"Неполный ответ: если тротуара нет, а обочина есть, идти нужно по обочине ({p:4.1})."}},{"uk":"За відсутності узбіччя або неможливості рухатися ним.","ru":"При отсутствии обочины или невозможности двигаться по ней.","w":{"uk":"Неповна відповідь: якщо є тротуар чи пішохідна доріжка, рухатися треба ними, навіть коли узбіччя немає.","ru":"Неполный ответ: если есть тротуар или пешеходная дорожка, двигаться нужно по ним, даже когда обочины нет."}},{"uk":"Відповіді 3 і 4.","ru":"Ответы 3 и 4."}],"c":4,"e":{"uk":"За {p:4.1} край проїзної частини — крайній варіант: коли немає тротуарів і пішохідних доріжок (або ними неможливо рухатися) **і** немає узбіччя чи ним неможливо йти. Тому правильне поєднання умов 3 і 4.","ru":"Согласно {p:4.1} край проезжей части — крайний вариант: когда нет тротуаров и пешеходных дорожек (или по ним невозможно двигаться) **и** нет обочины или по ней невозможно идти. Поэтому верно сочетание условий 3 и 4."},"ref":["4.1"]},{"id":"h4-5","t":"h4","num":"4.5","q":{"uk":"Чи має право пішохід вимагати від органів виконавчої влади, власників автомобільних доріг, вулиць та залізничних переїздів створення умов для забезпечення безпеки дорожнього руху?","ru":"Имеет ли право пешеход требовать от органов исполнительной власти, владельцев автомобильных дорог, улиц и железнодорожных переездов создания условий для обеспечения безопасности дорожного движения?"},"a":[{"uk":"Не має.","ru":"Не имеет.","w":{"uk":"Правила прямо надають пішоходові право вимагати створення безпечних умов руху ({p:4.16}).","ru":"Правила прямо предоставляют пешеходу право требовать создания безопасных условий движения ({p:4.16})."}},{"uk":"Має.","ru":"Имеет."}],"c":1,"e":{"uk":"Це право пішохода прямо закріплене в підпункті «б» {p:4.16}.","ru":"Это право пешехода прямо закреплено в подпункте «б» {p:4.16}."},"ref":["4.16"]},{"id":"h4-6","t":"h4","num":"4.6","q":{"uk":"Чи має перевагу пішохід, якщо переходить дорогу на регульованому пішохідному переході?","ru":"Имеет ли преимущество пешеход, если переходит дорогу по регулируемому пешеходному переходу?"},"a":[{"uk":"Має завжди.","ru":"Имеет всегда.","w":{"uk":"Перевагу без додаткових умов пішохід має лише на позначених **нерегульованих** переходах; на регульованому переході на заборонний сигнал іти не можна.","ru":"Преимущество без дополнительных условий пешеход имеет только на обозначенных **нерегулируемых** переходах; на регулируемом переходе на запрещающий сигнал идти нельзя."}},{"uk":"Має за наявності на те відповідного сигналу регулювальника чи світлофора.","ru":"Имеет при наличии соответствующего сигнала регулировщика или светофора."}],"c":1,"e":{"uk":"За підпунктом «а» {p:4.16} на регульованому переході пішохід має перевагу лише за відповідного сигналу регулювальника чи світлофора, адже в таких місцях він керується саме цими сигналами ({p:4.9}).","ru":"Согласно подпункту «а» {p:4.16} на регулируемом переходе пешеход имеет преимущество только при соответствующем сигнале регулировщика или светофора, ведь в таких местах он руководствуется именно этими сигналами ({p:4.9})."},"ref":["4.9","4.16"]},{"id":"h4-7","t":"h4","num":"4.7","q":{"uk":"Коли пішоходу дозволяється затримуватися і зупинятися на проїзній частині?","ru":"Когда пешеходу разрешается задерживаться и останавливаться на проезжей части?"},"a":[{"uk":"Коли це пов'язано із забезпеченням безпеки дорожнього руху.","ru":"Когда это связано с обеспечением безопасности дорожного движения.","w":{"uk":"Неповна відповідь: зупинитися посеред дороги дозволено й тоді, коли пішохід не встиг закінчити перехід ({p:4.9}).","ru":"Неполный ответ: остановиться посреди дороги разрешено и тогда, когда пешеход не успел закончить переход ({p:4.9})."}},{"uk":"У разі наближення транспортного засобу з увімкненими проблисковими маячками червоного або синього кольору.","ru":"При приближении транспортного средства с включёнными проблесковыми маячками красного или синего цвета.","w":{"uk":"За наближення транспорту з маячками пішохід повинен утриматися від переходу або **негайно залишити** проїзну частину ({p:4.13}), а не зупинятися на ній.","ru":"При приближении транспорта с маячками пешеход должен воздержаться от перехода или **немедленно покинуть** проезжую часть ({p:4.13}), а не останавливаться на ней."}},{"uk":"Коли пішохід не встиг завершити перехід проїзної частини дороги одного напрямку під час сигналу світлофора, що дозволяє перехід і перебуває на острівці безпеки або лінії, що розділяє транспортні потоки протилежних напрямків, а у разі їх відсутності - на середині проїзної частини.","ru":"Когда пешеход не успел завершить переход проезжей части дороги одного направления во время сигнала светофора, разрешающего переход, и находится на островке безопасности или линии, разделяющей транспортные потоки противоположных направлений, а при их отсутствии — на середине проезжей части.","w":{"uk":"Неповна відповідь: зупинка можлива й тоді, коли цього вимагає безпека руху ({p:4.14}).","ru":"Неполный ответ: остановка возможна и тогда, когда этого требует безопасность движения ({p:4.14})."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3.","w":{"uk":"Варіант 2 неправильний: наближення транспорту з маячками вимагає залишити проїзну частину ({p:4.13}).","ru":"Вариант 2 неверен: приближение транспорта с маячками требует покинуть проезжую часть ({p:4.13})."}},{"uk":"Відповіді 1 і 3.","ru":"Ответы 1 и 3."}],"c":4,"e":{"uk":"{p:4.14} забороняє затримуватися на проїзній частині, якщо це **не** пов'язано із забезпеченням безпеки руху (варіант 1), а {p:4.9} прямо велить пішоходові, який не встиг перейти, чекати на острівці безпеки, лінії між зустрічними потоками чи посередині проїзної частини (варіант 3).","ru":"{p:4.14} запрещает задерживаться на проезжей части, если это **не** связано с обеспечением безопасности движения (вариант 1), а {p:4.9} прямо велит пешеходу, который не успел перейти, ждать на островке безопасности, линии между встречными потоками или посередине проезжей части (вариант 3)."},"ref":["4.9","4.14"]},{"id":"h4-8","t":"h4","num":"4.8","q":{"uk":"Де пішоходам дозволено переходити дорогу, якщо є розділювальна смуга або дорога має чотири і більше смуг для руху в обох напрямках, а також у місцях, де встановлено огородження:","ru":"Где пешеходам разрешено переходить дорогу, если есть разделительная полоса или дорога имеет четыре и более полос для движения в обоих направлениях, а также в местах, где установлено ограждение:"},"a":[{"uk":"У будь-якому місці, якщо в зоні видимості немає переходу або перехрестя.","ru":"В любом месте, если в зоне видимости нет перехода или перекрёстка.","w":{"uk":"Перехід у довільному місці допускається лише на дорогах, що мають не більше трьох смуг і без розділювальної смуги ({p:4.8}).","ru":"Переход в произвольном месте допускается только на дорогах, имеющих не более трёх полос и без разделительной полосы ({p:4.8})."}},{"uk":"На пішохідних переходах, у тому числі підземних і надземних.","ru":"На пешеходных переходах, в том числе подземных и надземных."},{"uk":"У разі відсутності пішохідних переходів – на перехрестях рухаючись лініями тротуарів або узбіч.","ru":"При отсутствии пешеходных переходов — на перекрёстках, двигаясь по линиям тротуаров или обочин.","w":{"uk":"Варіант описує перехід там, де пішохідних переходів немає, а на таких дорогах переходити поза пішохідним переходом заборонено ({p:4.14}).","ru":"Вариант описывает переход там, где пешеходных переходов нет, а на таких дорогах переходить вне пешеходного перехода запрещено ({p:4.14})."}},{"uk":"Відповіді 2 і 3","ru":"Ответы 2 и 3.","w":{"uk":"Варіант 3 неправильний, тож неправильне й це поєднання.","ru":"Вариант 3 неверен, поэтому неверно и это сочетание."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3.","w":{"uk":"Варіанти 1 і 3 неправильні: на таких дорогах переходити можна лише пішохідними переходами.","ru":"Варианты 1 и 3 неверны: на таких дорогах переходить можно только по пешеходным переходам."}}],"c":1,"e":{"uk":"На таких дорогах підпункт «г» {p:4.14} забороняє переходити проїзну частину поза пішохідним переходом, тож лишаються тільки пішохідні переходи, у тому числі підземні й надземні ({p:4.7}).","ru":"На таких дорогах подпункт «г» {p:4.14} запрещает переходить проезжую часть вне пешеходного перехода, поэтому остаются только пешеходные переходы, в том числе подземные и надземные ({p:4.7})."},"ref":["4.7","4.14"]},{"id":"h4-9","t":"h4","num":"4.9","q":{"uk":"Що заборонено пішоходам під час переходу проїзної частини навіть на пішохідному переході?","ru":"Что запрещено пешеходам при переходе проезжей части даже на пешеходном переходе?"},"a":[{"uk":"Виходити на проїзну частину, не впевнившись у відсутності небезпеки для себе та інших учасників руху.","ru":"Выходить на проезжую часть, не убедившись в отсутствии опасности для себя и других участников движения.","w":{"uk":"Неповна відповідь: раптово виходити чи вибігати на перехід теж заборонено ({p:4.14}).","ru":"Неполный ответ: внезапно выходить или выбегать на переход тоже запрещено ({p:4.14})."}},{"uk":"Раптово виходити чи вибігати на проїзну частину, в тому числі на пішохідний перехід.","ru":"Внезапно выходить или выбегать на проезжую часть, в том числе на пешеходный переход.","w":{"uk":"Неповна відповідь: виходити на проїзну частину, не впевнившись у відсутності небезпеки, теж заборонено ({p:4.14}).","ru":"Неполный ответ: выходить на проезжую часть, не убедившись в отсутствии опасности, тоже запрещено ({p:4.14})."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2."}],"c":2,"e":{"uk":"Обидві заборони містить {p:4.14} (підпункти «а» і «б»), і вони діють також на пішохідному переході: перевага не звільняє пішохода від обов'язку переконатися в безпеці й не вибігати раптово.","ru":"Оба запрета содержит {p:4.14} (подпункты «а» и «б»), и они действуют также на пешеходном переходе: преимущество не освобождает пешехода от обязанности убедиться в безопасности и не выбегать внезапно."},"ref":["4.14"]},{"id":"h4-10","t":"h4","num":"4.10","q":{"uk":"Де пішоходи повинні чекати на транспортний засіб?","ru":"Где пешеходы должны ожидать транспортное средство?"},"a":[{"uk":"На тротуарах та на посадкових майданчиках.","ru":"На тротуарах и на посадочных площадках.","w":{"uk":"Неповна відповідь: за відсутності тротуару й посадкового майданчика чекають на узбіччі.","ru":"Неполный ответ: при отсутствии тротуара и посадочной площадки ожидают на обочине."}},{"uk":"В заїзних кишенях для маршрутних транспортних засобів.","ru":"В заездных карманах для маршрутных транспортных средств.","w":{"uk":"Заїзна кишеня — це місце для заїзду маршрутного транспорту, а не для пішоходів; стояти там небезпечно, і Правила цього не передбачають.","ru":"Заездной карман — это место для заезда маршрутного транспорта, а не для пешеходов; стоять там опасно, и Правила этого не предусматривают."}},{"uk":"На узбіччі, у разі відсутності тротуарів та посадкових майданчиків.","ru":"На обочине, при отсутствии тротуаров и посадочных площадок.","w":{"uk":"Неповна відповідь: узбіччя — лише запасний варіант, основне місце очікування — тротуар чи посадковий майданчик.","ru":"Неполный ответ: обочина — лишь запасной вариант, основное место ожидания — тротуар или посадочная площадка."}},{"uk":"Відповіді 1 і 3.","ru":"Ответы 1 и 3."}],"c":3,"e":{"uk":"За {p:4.11} чекати на транспортний засіб треба на тротуарах і посадкових майданчиках, а якщо їх немає — на узбіччі, не створюючи перешкод для дорожнього руху.","ru":"Согласно {p:4.11} ожидать транспортное средство нужно на тротуарах и посадочных площадках, а если их нет — на обочине, не создавая помех для дорожного движения."},"ref":["4.11"]},{"id":"h4-11","t":"h4","num":"4.11","q":{"uk":"Як повинні вчинити пішоходи, що переходять дорогу з розділювальною смугою на регульованому пішохідному переході, яким при переході проїзної частини одного напрямку (коли вони ще не дійшли до розділювальної смуги) загорівся сигнал світлофора, що забороняє рух?","ru":"Как должны поступить пешеходы, переходящие дорогу с разделительной полосой по регулируемому пешеходному переходу, если при переходе проезжей части одного направления (когда они ещё не дошли до разделительной полосы) загорелся сигнал светофора, запрещающий движение?"},"a":[{"uk":"Повинні завершити перехід дороги, на будь-якому сигналі світлофора.","ru":"Должны завершить переход дороги при любом сигнале светофора.","w":{"uk":"Переходити другу половину дороги на заборонний сигнал не можна ({p:4.9}): транспорт там уже отримав дозвіл на рух.","ru":"Переходить вторую половину дороги на запрещающий сигнал нельзя ({p:4.9}): транспорт там уже получил разрешение на движение."}},{"uk":"Повинні очікувати на розділювальній смузі і можуть продовжити перехід лише тоді, коли це буде дозволено відповідним сигналом світлофора.","ru":"Должны ожидать на разделительной полосе и могут продолжить переход лишь тогда, когда это будет разрешено соответствующим сигналом светофора."}],"c":1,"e":{"uk":"За {p:4.9} пішохід, який не встиг перейти проїзну частину одного напрямку, має дійти до розділювальної смуги й чекати там, доки світлофор знову дозволить рух і він переконається в безпеці.","ru":"Согласно {p:4.9} пешеход, который не успел перейти проезжую часть одного направления, должен дойти до разделительной полосы и ждать там, пока светофор снова разрешит движение и он убедится в безопасности."},"ref":["4.9"]},{"id":"h4-12","t":"h4","num":"4.12","q":{"uk":"На регульованому пішохідному переході пішохід, який не встиг перейти проїзну частину дороги одного напрямку руху (для нього загорівся сигнал світлофора, що забороняє рух) повинен:","ru":"На регулируемом пешеходном переходе пешеход, который не успел перейти проезжую часть дороги одного направления движения (для него загорелся сигнал светофора, запрещающий движение), должен:"},"a":[{"uk":"Закінчити перехід дороги не залежно від сигналів світлофора.","ru":"Закончить переход дороги независимо от сигналов светофора.","w":{"uk":"Ігнорувати сигнали світлофора пішохід не має права ({p:4.9}).","ru":"Игнорировать сигналы светофора пешеход не имеет права ({p:4.9})."}},{"uk":"Перебувати на острівці безпеки або лінії, що розділяє транспортні потоки протилежних напрямків, або на середині проїзної частини, і може продовжити перехід лише тоді, коли це буде дозволено відповідним сигналом світлофора, переконавшись у безпеці подальшого руху.","ru":"Находиться на островке безопасности или линии, разделяющей транспортные потоки противоположных направлений, или на середине проезжей части, и может продолжить переход лишь тогда, когда это будет разрешено соответствующим сигналом светофора, убедившись в безопасности дальнейшего движения."},{"uk":"Повернутися назад на тротуар, щоб дочекатися сигналу регулювальника чи світлофора, який дозволяє рух.","ru":"Вернуться назад на тротуар, чтобы дождаться сигнала регулировщика или светофора, разрешающего движение.","w":{"uk":"Повертатися назад Правила не вимагають: це довше й небезпечніше, бо транспорт уже може рушити; пішохід чекає посередині дороги ({p:4.9}).","ru":"Возвращаться назад Правила не требуют: это дольше и опаснее, ведь транспорт уже может тронуться; пешеход ждёт посередине дороги ({p:4.9})."}}],"c":1,"e":{"uk":"Це майже дослівний текст {p:4.9}: пішохід чекає на острівці безпеки, лінії між зустрічними потоками або посередині проїзної частини й рушає далі лише на дозвільний сигнал, переконавшись у безпеці.","ru":"Это почти дословный текст {p:4.9}: пешеход ждёт на островке безопасности, линии между встречными потоками или посередине проезжей части и идёт дальше только на разрешающий сигнал, убедившись в безопасности."},"ref":["4.9"]},{"id":"h4-13","t":"h4","num":"4.13","q":{"uk":"За яких умов пішоходам дозволяється переходити дорогу поза межами пішохідного переходу або поза перехрестям?","ru":"При каких условиях пешеходам разрешается переходить дорогу вне пешеходного перехода или вне перекрёстка?"},"a":[{"uk":"На будь-яких дорогах, переконавшись у відсутності небезпеки.","ru":"На любых дорогах, убедившись в отсутствии опасности.","w":{"uk":"На дорогах із розділювальною смугою, чотирма й більше смугами або огородженням переходити поза пішохідним переходом заборонено ({p:4.14}).","ru":"На дорогах с разделительной полосой, четырьмя и более полосами или ограждением переходить вне пешеходного перехода запрещено ({p:4.14})."}},{"uk":"Якщо в зоні видимості немає переходу або перехрестя, а дорога має не більш як три смуги для руху в обох напрямках, при цьому пішохід повинен переконатися у відсутності небезпеки.","ru":"Если в зоне видимости нет перехода или перекрёстка, а дорога имеет не более трёх полос для движения в обоих направлениях, при этом пешеход должен убедиться в отсутствии опасности."},{"uk":"Якщо в зоні видимості немає переходу або перехрестя, а дорога має розділювальну смугу, при цьому пішохід повинен переконатися у відсутності небезпеки.","ru":"Если в зоне видимости нет перехода или перекрёстка, а дорога имеет разделительную полосу, при этом пешеход должен убедиться в отсутствии опасности.","w":{"uk":"Наявність розділювальної смуги якраз забороняє переходити поза пішохідним переходом ({p:4.14}).","ru":"Наличие разделительной полосы как раз запрещает переходить вне пешеходного перехода ({p:4.14})."}}],"c":1,"e":{"uk":"Саме ці умови називає {p:4.8}: у зоні видимості немає переходу чи перехрестя, дорога має не більше трьох смуг в обох напрямках, а переходять під прямим кутом там, де дорогу добре видно, упевнившись у безпеці.","ru":"Именно эти условия называет {p:4.8}: в зоне видимости нет перехода или перекрёстка, дорога имеет не более трёх полос в обоих направлениях, а переходят под прямым углом там, где дорога хорошо просматривается, убедившись в безопасности."},"ref":["4.8","4.14"]},{"id":"h4-14","t":"h4","num":"4.14","q":{"uk":"Чи має перевагу пішохід, якщо переходить дорогу на позначеному нерегульованому пішохідному переході?","ru":"Имеет ли преимущество пешеход, если переходит дорогу по обозначенному нерегулируемому пешеходному переходу?"},"a":[{"uk":"Має завжди.","ru":"Имеет всегда."},{"uk":"Не має.","ru":"Не имеет.","w":{"uk":"Перевага на позначеному нерегульованому переході прямо закріплена за пішоходом ({p:4.16}).","ru":"Преимущество на обозначенном нерегулируемом переходе прямо закреплено за пешеходом ({p:4.16})."}},{"uk":"Має, якщо пішохідний перехід знаходиться на перехресті.","ru":"Имеет, если пешеходный переход находится на перекрёстке.","w":{"uk":"Розташування переходу значення не має: перевага діє на будь-якому позначеному нерегульованому переході.","ru":"Расположение перехода значения не имеет: преимущество действует на любом обозначенном нерегулируемом переходе."}}],"c":0,"e":{"uk":"За підпунктом «а» {p:4.16} на позначених нерегульованих пішохідних переходах пішохід має перевагу, а водії зобов'язані дати йому дорогу ({p:18.1}).","ru":"Согласно подпункту «а» {p:4.16} на обозначенных нерегулируемых пешеходных переходах пешеход имеет преимущество, а водители обязаны уступить ему дорогу ({p:18.1})."},"ref":["4.16","18.1"]},{"id":"h4-15","t":"h4","num":"4.15","q":{"uk":"Де дозволяється водити організовані групи дітей за відсутності тротуарів і пішохідних доріжок?","ru":"Где разрешается водить организованные группы детей при отсутствии тротуаров и пешеходных дорожек?"},"a":[{"uk":"Тільки узбіччям дороги в напрямку руху транспортних засобів колоною, але тільки у світлу пору доби і лише в супроводі дорослих.","ru":"Только по обочине дороги в направлении движения транспортных средств колонной, но только в светлое время суток и лишь в сопровождении взрослых."},{"uk":"Проїзною частиною або узбіччям назустріч руху транспортних засобів, один за одним і тільки у світлу пору доби.","ru":"По проезжей части или обочине навстречу движению транспортных средств, друг за другом и только в светлое время суток.","w":{"uk":"Проїзною частиною водити дітей заборонено, а узбіччям — лише в напрямку руху транспорту й у супроводі дорослих ({p:4.6}).","ru":"По проезжей части водить детей запрещено, а по обочине — только в направлении движения транспорта и в сопровождении взрослых ({p:4.6})."}}],"c":0,"e":{"uk":"За {p:4.6} організовані групи дітей водять тротуарами й пішохідними доріжками, а за їх відсутності — узбіччям у напрямку руху транспорту колоною, лише у світлу пору доби й у супроводі дорослих.","ru":"Согласно {p:4.6} организованные группы детей водят по тротуарам и пешеходным дорожкам, а при их отсутствии — по обочине в направлении движения транспорта колонной, только в светлое время суток и в сопровождении взрослых."},"ref":["4.6"]},{"id":"h4-16","t":"h4","num":"4.16","q":{"uk":"Чи дозволено водити організовані групи дітей проїзною частиною?","ru":"Разрешено ли водить организованные группы детей по проезжей части?"},"a":[{"uk":"Дозволено рухатися один за одним, тільки назустріч руху транспортних засобів.","ru":"Разрешено двигаться друг за другом, только навстречу движению транспортных средств.","w":{"uk":"Проїзною частиною водити дітей заборонено в будь-якому напрямку ({p:4.6}).","ru":"По проезжей части водить детей запрещено в любом направлении ({p:4.6})."}},{"uk":"Заборонено.","ru":"Запрещено."},{"uk":"Дозволяється тільки в напрямку руху транспортних засобів колоною не більш як по чотири дитини в ряд за умови, що колона не займає більше половини ширини проїзної частини одного напрямку руху, у супроводі дорослих.","ru":"Разрешается только в направлении движения транспортных средств колонной не более чем по четыре ребёнка в ряд при условии, что колонна не занимает более половины ширины проезжей части одного направления движения, в сопровождении взрослых.","w":{"uk":"Такі умови {p:4.5} встановлює для організованих груп **дорослих**; для дітей {p:4.6} дозволяє лише тротуар, пішохідну доріжку чи узбіччя.","ru":"Такие условия {p:4.5} устанавливает для организованных групп **взрослых**; для детей {p:4.6} разрешает только тротуар, пешеходную дорожку или обочину."}}],"c":1,"e":{"uk":"{p:4.6} дозволяє водити організовані групи дітей лише тротуарами й пішохідними доріжками, а за їх відсутності — узбіччям; проїзної частини в цьому переліку немає.","ru":"{p:4.6} разрешает водить организованные группы детей только по тротуарам и пешеходным дорожкам, а при их отсутствии — по обочине; проезжей части в этом перечне нет."},"ref":["4.6"]},{"id":"h4-17","t":"h4","num":"4.17","q":{"uk":"При дотриманні яких умов дозволяється рух організованих груп людей проїзною частиною?","ru":"При соблюдении каких условий разрешается движение организованных групп людей по проезжей части?"},"a":[{"uk":"Тільки у напрямку руху транспортних засобів колоною не більш як по чотири особи в ряд за умови, що колона не займає більше половини ширини проїзної частини одного напрямку руху.","ru":"Только в направлении движения транспортных средств колонной не более чем по четыре человека в ряд при условии, что колонна не занимает более половины ширины проезжей части одного направления движения.","w":{"uk":"Неповна відповідь: колону ще повинні супроводжувати люди з червоними прапорцями, а в темряві — з ліхтарями ({p:4.5}).","ru":"Неполный ответ: колонну ещё должны сопровождать люди с красными флажками, а в темноте — с фонарями ({p:4.5})."}},{"uk":"Попереду і позаду колони на відстані 10-15 м з лівого боку повинні бути супровідники з червоними прапорцями, а в темну пору доби та в умовах недостатньої видимості - із засвіченими ліхтарями: попереду - білого кольору, позаду - червоного.","ru":"Впереди и позади колонны на расстоянии 10–15 м с левой стороны должны быть сопровождающие с красными флажками, а в тёмное время суток и в условиях недостаточной видимости — с зажжёнными фонарями: впереди — белого цвета, позади — красного.","w":{"uk":"Неповна відповідь: колона також має рухатися лише в напрямку руху транспорту, не більше ніж по чотири особи в ряд і займати не більше половини ширини проїзної частини.","ru":"Неполный ответ: колонна также должна двигаться только в направлении движения транспорта, не более чем по четыре человека в ряд и занимать не более половины ширины проезжей части."}},{"uk":"Колону пішоходів обов'язково повинні супроводжувати автомобілі з увімкненим ближнім світлом фар і проблисковими маячками червоного кольору або червоного та синього кольорів.","ru":"Колонну пешеходов обязательно должны сопровождать автомобили с включённым ближним светом фар и проблесковыми маячками красного цвета или красного и синего цветов.","w":{"uk":"{p:4.5} не вимагає супроводу автомобілями з маячками: досить супровідників із червоними прапорцями чи ліхтарями.","ru":"{p:4.5} не требует сопровождения автомобилями с маячками: достаточно сопровождающих с красными флажками или фонарями."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3.","w":{"uk":"Варіант 3 неправильний, тож неправильне й поєднання 1, 2 і 3.","ru":"Вариант 3 неверен, поэтому неверно и сочетание 1, 2 и 3."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2."}],"c":4,"e":{"uk":"Обидві умови — напрямок і ширину колони та супровідників із червоними прапорцями (ліхтарями) — встановлює {p:4.5}. Супроводу автомобілями з маячками Правила для колони пішоходів не вимагають.","ru":"Оба условия — направление и ширину колонны и сопровождающих с красными флажками (фонарями) — устанавливает {p:4.5}. Сопровождения автомобилями с маячками Правила для колонны пешеходов не требуют."},"ref":["4.5"]},{"id":"h4-18","t":"h4","num":"4.18","q":{"uk":"В якому напрямку дозволено рухатися організованим групам людей проїзною частиною?","ru":"В каком направлении разрешено двигаться организованным группам людей по проезжей части?"},"a":[{"uk":"Тільки назустріч руху, один за одним.","ru":"Только навстречу движению, друг за другом.","w":{"uk":"Назустріч транспорту краєм проїзної частини ходять окремі пішоходи ({p:4.1}), а не організовані групи.","ru":"Навстречу транспорту по краю проезжей части ходят отдельные пешеходы ({p:4.1}), а не организованные группы."}},{"uk":"У будь-який зручний бік, в залежності від інтенсивності руху, колоною по чотири особи в ряд.","ru":"В любую удобную сторону, в зависимости от интенсивности движения, колонной по четыре человека в ряд.","w":{"uk":"Напрямок руху колони не довільний: лише в напрямку руху транспортних засобів ({p:4.5}).","ru":"Направление движения колонны не произвольное: только в направлении движения транспортных средств ({p:4.5})."}},{"uk":"Тільки у напрямку руху транспортних засобів колоною не більш як по чотири особи в ряд.","ru":"Только в направлении движения транспортных средств колонной не более чем по четыре человека в ряд."}],"c":2,"e":{"uk":"За {p:4.5} організовані групи людей рухаються дорогою лише в напрямку руху транспортних засобів колоною не більш як по чотири особи в ряду.","ru":"Согласно {p:4.5} организованные группы людей движутся по дороге только в направлении движения транспортных средств колонной не более чем по четыре человека в ряду."},"ref":["4.5"]},{"id":"h4-19","t":"h4","num":"4.19","q":{"uk":"Пішоходи, які рухаються проїзною частиною чи узбіччям у темну пору доби або в умовах недостатньої видимості, для своєчасного виявлення їх іншими учасниками дорожнього руху повинні:","ru":"Пешеходы, движущиеся по проезжей части или обочине в тёмное время суток или в условиях недостаточной видимости, для своевременного обнаружения их другими участниками дорожного движения должны:"},"a":[{"uk":"Пересуватися тільки групами, по чотири особи в ряд.","ru":"Передвигаться только группами, по четыре человека в ряд.","w":{"uk":"Рух по чотири особи в ряд стосується організованих колон ({p:4.5}), а окремих пішоходів у темряві робить помітними лише світлоповертальні елементи.","ru":"Движение по четыре человека в ряд касается организованных колонн ({p:4.5}), а отдельных пешеходов в темноте делают заметными только световозвращающие элементы."}},{"uk":"Використовувати світлоповертальні елементи (стрічку, наклейку, жилет тощо) або бути в одязі, який має світлоповертальні елементи, для своєчасного їх виявлення іншими учасниками дорожнього руху.","ru":"Использовать световозвращающие элементы (ленту, наклейку, жилет и т. п.) или быть в одежде, имеющей световозвращающие элементы, для своевременного их обнаружения другими участниками дорожного движения."},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2.","w":{"uk":"Варіант 1 неправильний, тож неправильне й це поєднання.","ru":"Вариант 1 неверен, поэтому неверно и это сочетание."}}],"c":1,"e":{"uk":"Це пряма вимога {p:4.4}: у темряві та за недостатньої видимості пішохід на проїзній частині чи узбіччі повинен мати світлоповертальні елементи.","ru":"Это прямое требование {p:4.4}: в темноте и при недостаточной видимости пешеход на проезжей части или обочине должен иметь световозвращающие элементы."},"ref":["4.4"]},{"id":"h4-20","t":"h4","num":"4.20","q":{"uk":"В якому напрямку узбіччям чи краєм проїзної частини повинні рухатися особи, які пересуваються в кріслах колісних без двигуна, які ведуть в руках мотоцикл, мопед або велосипед, за межами населених пунктів?","ru":"В каком направлении по обочине или краю проезжей части должны двигаться лица, передвигающиеся в креслах-колясках без двигателя, ведущие в руках мотоцикл, мопед или велосипед, вне населённых пунктов?"},"a":[{"uk":"Назустріч руху транспортних засобів. При цьому треба бути обережним і не заважати іншим учасникам дорожнього руху.","ru":"Навстречу движению транспортных средств. При этом нужно быть осторожным и не мешать другим участникам дорожного движения.","w":{"uk":"Назустріч транспорту йдуть звичайні пішоходи, а для крісел колісних і тих, хто веде двоколісний транспорт, {p:4.3} встановлює рух у напрямку транспорту.","ru":"Навстречу транспорту идут обычные пешеходы, а для кресел-колясок и тех, кто ведёт двухколёсный транспорт, {p:4.3} устанавливает движение в направлении транспорта."}},{"uk":"На свій розсуд, в залежності від інтенсивності руху.","ru":"По своему усмотрению, в зависимости от интенсивности движения.","w":{"uk":"Напрямок руху прямо визначено в {p:4.3} і від інтенсивності руху не залежить.","ru":"Направление движения прямо определено в {p:4.3} и от интенсивности движения не зависит."}},{"uk":"Повинні пересуватися в напрямку руху транспортних засобів.","ru":"Должны передвигаться в направлении движения транспортных средств."}],"c":2,"e":{"uk":"Другий абзац {p:4.3}: особи в кріслах колісних без двигуна та ті, хто веде мотоцикл, мопед або велосипед, рухаються узбіччям чи краєм проїзної частини **в напрямку** руху транспортних засобів — на відміну від звичайних пішоходів, які йдуть назустріч.","ru":"Второй абзац {p:4.3}: лица в креслах-колясках без двигателя и те, кто ведёт мотоцикл, мопед или велосипед, движутся по обочине или краю проезжей части **в направлении** движения транспортных средств — в отличие от обычных пешеходов, которые идут навстречу."},"ref":["4.3"]},{"id":"h4-21","t":"h4","num":"4.21","q":{"uk":"Які дії зобов’язаний вжити пішохід у разі його причетності до дорожньо-транспортної пригоди?","ru":"Какие действия обязан предпринять пешеход в случае его причастности к дорожно-транспортному происшествию?"},"a":[{"uk":"Пішохід не зобов’язаний нічого робити.","ru":"Пешеход ничего не обязан делать.","w":{"uk":"Обов'язки учасника ДТП стосуються й пішохода — їх прямо перелічує {p:4.15}.","ru":"Обязанности участника ДТП касаются и пешехода — их прямо перечисляет {p:4.15}."}},{"uk":"Записати прізвища і адреси очевидців.","ru":"Записать фамилии и адреса очевидцев.","w":{"uk":"Неповна відповідь: пішохід ще має надати допомогу потерпілим і повідомити поліцію ({p:4.15}).","ru":"Неполный ответ: пешеход ещё должен оказать помощь пострадавшим и сообщить в полицию ({p:4.15})."}},{"uk":"Повідомити орган чи уповноважений підрозділ Національної поліції про пригоду, надати необхідні дані про себе і перебувати на місці до прибуття поліцейських.","ru":"Сообщить в орган или уполномоченное подразделение Национальной полиции о происшествии, предоставить необходимые данные о себе и находиться на месте до прибытия полицейских.","w":{"uk":"Неповна відповідь: пішохід ще має надати допомогу потерпілим і записати очевидців ({p:4.15}).","ru":"Неполный ответ: пешеход ещё должен оказать помощь пострадавшим и записать очевидцев ({p:4.15})."}},{"uk":"Надати можливу допомогу потерпілим.","ru":"Оказать возможную помощь пострадавшим.","w":{"uk":"Неповна відповідь: пішохід ще має записати очевидців і повідомити поліцію ({p:4.15}).","ru":"Неполный ответ: пешеход ещё должен записать очевидцев и сообщить в полицию ({p:4.15})."}},{"uk":"Відповіді 2, 3 і 4.","ru":"Ответы 2, 3 и 4."}],"c":4,"e":{"uk":"{p:4.15} покладає на пішохода, причетного до ДТП, усі три обов'язки: надати допомогу потерпілим, записати прізвища й адреси очевидців, повідомити поліцію та залишатися на місці до її прибуття.","ru":"{p:4.15} возлагает на пешехода, причастного к ДТП, все три обязанности: оказать помощь пострадавшим, записать фамилии и адреса очевидцев, сообщить в полицию и оставаться на месте до её прибытия."},"ref":["4.15"]},{"id":"h4-22","t":"h4","num":"4.22","q":{"uk":"На нерегульованих перехрестях пішоходи мають право переходити дорогу, якщо не має позначеного пішохідного переходу?","ru":"Имеют ли пешеходы право переходить дорогу на нерегулируемых перекрёстках, если нет обозначенного пешеходного перехода?"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"Перехрестя по лініях тротуарів чи узбіч — саме те місце, де Правила дозволяють переходити за відсутності позначеного переходу ({p:4.7}).","ru":"Перекрёсток по линиям тротуаров или обочин — именно то место, где Правила разрешают переходить при отсутствии обозначенного перехода ({p:4.7})."}}],"c":0,"e":{"uk":"За {p:4.7} за відсутності пішохідних переходів проїзну частину переходять на перехрестях по лініях тротуарів або узбіч — так визначаються й межі непозначеного переходу на перехресті ({p:1.10}).","ru":"Согласно {p:4.7} при отсутствии пешеходных переходов проезжую часть переходят на перекрёстках по линиям тротуаров или обочин — так определяются и границы необозначенного перехода на перекрёстке ({p:1.10})."},"ref":["4.7","1.10"]},{"id":"h4-23","t":"h4","num":"4.23","q":{"uk":"Чи дозволено пішоходам переходити проїзну частину на цій ділянці дороги?","ru":"Разрешено ли пешеходам переходить проезжую часть на этом участке дороги?"},"a":[{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"Тут немає пішохідного переходу, а дорогу розділяє огородження — перехід заборонений ({p:4.14}).","ru":"Здесь нет пешеходного перехода, а дорогу разделяет ограждение — переход запрещён ({p:4.14})."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":1,"e":{"uk":"На малюнку автомагістраль — по дві смуги в кожному напрямку, розділені огородженням. Підпункти «г» і «д» {p:4.14} забороняють переходити дорогу з розділювальною смугою чи огородженням поза пішохідним переходом і взагалі виходити на автомагістраль.","ru":"На рисунке автомагистраль — по две полосы в каждом направлении, разделённые ограждением. Подпункты «г» и «д» {p:4.14} запрещают переходить дорогу с разделительной полосой или ограждением вне пешеходного перехода и вообще выходить на автомагистраль."},"ref":["4.14"],"pic":["img/hsc/4-23-1.jpg"]},{"id":"h4-24","t":"h4","num":"4.24","q":{"uk":"Чи правильно в даному випадку рухається пішохід по краю проїзної частини?","ru":"Правильно ли в данном случае движется пешеход по краю проезжей части?"},"a":[{"uk":"Так.","ru":"Да.","w":{"uk":"Ідучи в напрямку руху транспорту, пішохід не бачить автомобілів, що наближаються ззаду, тому так рухатися не можна ({p:4.1}).","ru":"Идя в направлении движения транспорта, пешеход не видит автомобилей, приближающихся сзади, поэтому так двигаться нельзя ({p:4.1})."}},{"uk":"Ні.","ru":"Нет."}],"c":1,"e":{"uk":"Жінка йде краєм проїзної частини в тому ж напрямку, що й транспорт (червоний автомобіль віддаляється разом із нею), тобто спиною до автомобілів, які її наздоганяють. {p:4.1} вимагає йти краєм проїзної частини **назустріч** руху транспортних засобів.","ru":"Женщина идёт по краю проезжей части в том же направлении, что и транспорт (красный автомобиль удаляется вместе с ней), то есть спиной к автомобилям, которые её догоняют. {p:4.1} требует идти по краю проезжей части **навстречу** движению транспортных средств."},"ref":["4.1"],"pic":["img/hsc/4-24-1.jpg"]},{"id":"h4-25","t":"h4","num":"4.25","q":{"uk":"Чи правильно в даному випадку рухається пішохід по краю проїзної частини?","ru":"Правильно ли в данном случае движется пешеход по краю проезжей части?"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"Пішохід якраз виконує вимогу {p:4.1}: іде краєм проїзної частини назустріч транспорту.","ru":"Пешеход как раз выполняет требование {p:4.1}: идёт по краю проезжей части навстречу транспорту."}}],"c":0,"e":{"uk":"Тротуару немає, і пішохід іде краєм проїзної частини **назустріч** руху транспортних засобів своєї смуги, як вимагає {p:4.1}: він бачить автомобілі, що наближаються, і може вчасно відійти.","ru":"Тротуара нет, и пешеход идёт по краю проезжей части **навстречу** движению транспортных средств своей полосы, как требует {p:4.1}: он видит приближающиеся автомобили и может вовремя отойти."},"ref":["4.1"],"pic":["img/hsc/4-25-1.jpg"]},{"id":"h4-26","t":"h4","num":"4.26","q":{"uk":"Пішоходи, у визначених Правилами дорожнього руху випадках, мають право рухатись велосипедними доріжками?","ru":"Имеют ли пешеходы право в определённых Правилами дорожного движения случаях двигаться по велосипедным дорожкам?"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"{p:4.1} прямо дозволяє пішоходам рухатися велосипедною доріжкою, коли тротуару чи пішохідної доріжки немає.","ru":"{p:4.1} прямо разрешает пешеходам двигаться по велосипедной дорожке, когда тротуара или пешеходной дорожки нет."}}],"c":0,"e":{"uk":"За {p:4.1}, якщо немає тротуарів і пішохідних доріжок або рухатися ними неможливо, пішоходи можуть іти велосипедними доріжками, тримаючись правого боку й не утруднюючи рух на велосипедах.","ru":"Согласно {p:4.1}, если нет тротуаров и пешеходных дорожек или двигаться по ним невозможно, пешеходы могут идти по велосипедным дорожкам, придерживаясь правой стороны и не затрудняя движение на велосипедах."},"ref":["4.1"]},{"id":"h5-1","t":"h5","num":"5.1","q":{"uk":"Чи дозволено пасажирам виконувати посадку (висадку) з боку суміжної смуги руху?","ru":"Разрешено ли пассажирам осуществлять посадку (высадку) со стороны смежной полосы движения?"},"a":[{"uk":"Заборонено.","ru":"Запрещено."},{"uk":"Дозволено, якщо при цьому не буде створено перешкод для руху транспортних засобів.","ru":"Разрешено, если при этом не будут созданы помехи для движения транспортных средств.","w":{"uk":"Заборона посадки з боку суміжної смуги безумовна: застереження «не створюючи перешкод» у {p:5.1} стосується лише посадки з крайньої смуги з безпечного боку.","ru":"Запрет посадки со стороны смежной полосы безусловен: оговорка «не создавая помех» в {p:5.1} касается только посадки с крайней полосы с безопасной стороны."}}],"c":0,"e":{"uk":"{p:5.1} дозволяє посадку (висадку) з крайньої смуги проїзної частини лише «не з боку суміжної смуги для руху»: з того боку рухаються інші транспортні засоби.","ru":"{p:5.1} разрешает посадку (высадку) с крайней полосы проезжей части только «не со стороны смежной полосы для движения»: с той стороны движутся другие транспортные средства."},"ref":["5.1"]},{"id":"h5-2","t":"h5","num":"5.2","q":{"uk":"Під час користування транспортним засобом пасажир автобуса має право на:","ru":"Во время пользования транспортным средством пассажир автобуса имеет право на:"},"a":[{"uk":"Отримання своєчасної і точної інформації про умови і порядок руху.","ru":"Получение своевременной и точной информации об условиях и порядке движения.","w":{"uk":"Неповна відповідь: пасажир має ще право на безпечне перевезення й відшкодування збитків ({p:5.5}).","ru":"Неполный ответ: пассажир имеет ещё право на безопасную перевозку и возмещение ущерба ({p:5.5})."}},{"uk":"Відшкодування заподіяної шкоди.","ru":"Возмещение причинённого вреда.","w":{"uk":"Неповна відповідь: пасажир має ще право на безпечне перевезення й своєчасну інформацію ({p:5.5}).","ru":"Неполный ответ: пассажир имеет ещё право на безопасную перевозку и своевременную информацию ({p:5.5})."}},{"uk":"Безпечне перевезення себе і багажу.","ru":"Безопасную перевозку себя и багажа.","w":{"uk":"Неповна відповідь: пасажир має ще право на відшкодування збитків і своєчасну інформацію ({p:5.5}).","ru":"Неполный ответ: пассажир имеет ещё право на возмещение ущерба и своевременную информацию ({p:5.5})."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3."}],"c":3,"e":{"uk":"Усі три права пасажира перелічено в {p:5.5}: безпечне перевезення себе й багажу, відшкодування завданих збитків і своєчасна та точна інформація про умови й порядок руху.","ru":"Все три права пассажира перечислены в {p:5.5}: безопасная перевозка себя и багажа, возмещение причинённого ущерба и своевременная и точная информация об условиях и порядке движения."},"ref":["5.5"]},{"id":"h5-3","t":"h5","num":"5.3","q":{"uk":"Що повинен зробити пасажир транспортного засобу, який причетний до дорожньо-транспортної пригоди?","ru":"Что должен сделать пассажир транспортного средства, причастного к дорожно-транспортному происшествию?"},"a":[{"uk":"Надати можливу допомогу потерпілим.","ru":"Оказать возможную помощь пострадавшим.","w":{"uk":"Неповна відповідь: пасажир ще має повідомити поліцію й дочекатися її на місці ({p:5.4}).","ru":"Неполный ответ: пассажир ещё должен сообщить в полицию и дождаться её на месте ({p:5.4})."}},{"uk":"Повідомити про пригоду орган чи уповноважений підрозділ Національної поліції і перебувати на місці до прибуття поліцейських.","ru":"Сообщить о происшествии в орган или уполномоченное подразделение Национальной полиции и находиться на месте до прибытия полицейских.","w":{"uk":"Неповна відповідь: пасажир також зобов'язаний надати можливу допомогу потерпілим ({p:5.4}).","ru":"Неполный ответ: пассажир также обязан оказать возможную помощь пострадавшим ({p:5.4})."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2."}],"c":2,"e":{"uk":"{p:5.4} зобов'язує пасажира причетного до ДТП транспортного засобу і надати можливу допомогу потерпілим, і повідомити поліцію та залишатися на місці до прибуття поліцейських.","ru":"{p:5.4} обязывает пассажира причастного к ДТП транспортного средства и оказать возможную помощь пострадавшим, и сообщить в полицию и оставаться на месте до прибытия полицейских."},"ref":["5.4"]},{"id":"h5-4","t":"h5","num":"5.4","q":{"uk":"Чи дозволено пасажирам під час руху на транспортному засобі використовувати для їзди підніжки і виступи транспортного засобу?","ru":"Разрешено ли пассажирам во время движения на транспортном средстве использовать для езды подножки и выступы транспортного средства?"},"a":[{"uk":"Дозволено у разі супроводу вантажів.","ru":"Разрешено в случае сопровождения грузов.","w":{"uk":"Супровід вантажу не робить їзду на підніжці безпечною — заборона {p:5.3} безумовна.","ru":"Сопровождение груза не делает езду на подножке безопасной — запрет {p:5.3} безусловен."}},{"uk":"Заборонено.","ru":"Запрещено."},{"uk":"Дозволено з дозволу водія.","ru":"Разрешено с разрешения водителя.","w":{"uk":"Водій не може скасувати заборону Правил: їздити на підніжках і виступах заборонено ({p:5.3}).","ru":"Водитель не может отменить запрет Правил: ездить на подножках и выступах запрещено ({p:5.3})."}}],"c":1,"e":{"uk":"Підпункт «в» {p:5.3} прямо забороняє пасажирам використовувати для їзди підніжки й виступи транспортних засобів — без жодних винятків.","ru":"Подпункт «в» {p:5.3} прямо запрещает пассажирам использовать для езды подножки и выступы транспортных средств — без каких-либо исключений."},"ref":["5.3"]},{"id":"h5-5","t":"h5","num":"5.5","q":{"uk":"Чи дозволено пасажирам відкривати двері транспортного засобу з боку тротуару, посадкового майданчика, краю проїзної частини чи узбіччя?","ru":"Разрешено ли пассажирам открывать двери транспортного средства со стороны тротуара, посадочной площадки, края проезжей части или обочины?"},"a":[{"uk":"Дозволено лише з дозволу водія.","ru":"Разрешено только с разрешения водителя.","w":{"uk":"Дозвіл водія Правила не вимагають: пасажир сам має переконатися, що транспортний засіб зупинився у відповідному місці ({p:5.3}).","ru":"Разрешения водителя Правила не требуют: пассажир сам должен убедиться, что транспортное средство остановилось в соответствующем месте ({p:5.3})."}},{"uk":"Дозволено, переконавшись, що транспортний засіб зупинився біля тротуару, посадкового майданчика, краю проїзної частини чи на узбіччі.","ru":"Разрешено, убедившись, что транспортное средство остановилось у тротуара, посадочной площадки, края проезжей части или на обочине."},{"uk":"Заборонено з лівого боку.","ru":"Запрещено с левой стороны.","w":{"uk":"Правила не прив'язують заборону до лівого чи правого боку: вирішальне те, чи зупинився транспортний засіб біля тротуару, посадкового майданчика, краю проїзної частини чи на узбіччі ({p:5.3}).","ru":"Правила не привязывают запрет к левой или правой стороне: решающее то, остановилось ли транспортное средство у тротуара, посадочной площадки, края проезжей части или на обочине ({p:5.3})."}}],"c":1,"e":{"uk":"Підпункт «б» {p:5.3} забороняє відчиняти двері, **не переконавшись**, що транспортний засіб зупинився біля тротуару, посадкового майданчика, краю проїзної частини чи на узбіччі; отже, переконавшись у цьому, відчиняти їх можна.","ru":"Подпункт «б» {p:5.3} запрещает открывать двери, **не убедившись**, что транспортное средство остановилось у тротуара, посадочной площадки, края проезжей части или на обочине; значит, убедившись в этом, открывать их можно."},"ref":["5.3"]},{"id":"h5-6","t":"h5","num":"5.6","q":{"uk":"Чи дозволяється пасажиру відволікати водія під час руху?","ru":"Разрешается ли пассажиру отвлекать водителя во время движения?"},"a":[{"uk":"Забороняється під час руху відволікати водія від керування транспортним засобом та заважати йому в цьому.","ru":"Запрещается во время движения отвлекать водителя от управления транспортным средством и мешать ему в этом."},{"uk":"Дозволяється для уточнення маршруту.","ru":"Разрешается для уточнения маршрута.","w":{"uk":"Винятку для уточнення маршруту Правила не роблять: це можна зробити до початку руху чи на зупинці ({p:5.3}).","ru":"Исключения для уточнения маршрута Правила не делают: это можно сделать до начала движения или на остановке ({p:5.3})."}}],"c":0,"e":{"uk":"Це дослівно підпункт «а» {p:5.3}: під час руху пасажирам заборонено відвертати увагу водія від керування й заважати йому.","ru":"Это дословно подпункт «а» {p:5.3}: во время движения пассажирам запрещено отвлекать внимание водителя от управления и мешать ему."},"ref":["5.3"]},{"id":"h5-7","t":"h5","num":"5.7","q":{"uk":"Чи повинні пасажири бути в застебнутих мотошоломах під час пересування на мотоциклах і мопедах?","ru":"Должны ли пассажиры быть в застёгнутых мотошлемах во время передвижения на мотоциклах и мопедах?"},"a":[{"uk":"Повинні під час руху автомагістралями.","ru":"Должны во время движения по автомагистралям.","w":{"uk":"Вимога щодо мотошолома не залежить від типу дороги — вона діє завжди ({p:5.2}).","ru":"Требование о мотошлеме не зависит от типа дороги — оно действует всегда ({p:5.2})."}},{"uk":"Повинні у будь-якому разі.","ru":"Должны в любом случае."},{"uk":"Не повинні.","ru":"Не должны.","w":{"uk":"Застебнутий мотошолом для пасажира мотоцикла й мопеда обов'язковий ({p:5.2}).","ru":"Застёгнутый мотошлем для пассажира мотоцикла и мопеда обязателен ({p:5.2})."}}],"c":1,"e":{"uk":"Підпункт «б» {p:5.2} зобов'язує пасажира мотоцикла чи мопеда бути в застебнутому мотошоломі без будь-яких винятків, а водій не має права перевозити пасажира без шолома ({p:2.3}).","ru":"Подпункт «б» {p:5.2} обязывает пассажира мотоцикла или мопеда быть в застёгнутом мотошлеме без каких-либо исключений, а водитель не имеет права перевозить пассажира без шлема ({p:2.3})."},"ref":["5.2","2.3"]},{"id":"h5-8","t":"h5","num":"5.8","q":{"uk":"Чи повинні пасажири пристібатися ременями безпеки під час пересування на транспортному засобі, який ними обладнаний?","ru":"Должны ли пассажиры пристёгиваться ремнями безопасности во время передвижения на транспортном средстве, которое ими оборудовано?"},"a":[{"uk":"Не повинні в населених пунктах.","ru":"Не должны в населённых пунктах.","w":{"uk":"Для пасажирів Правила не роблять винятку в населених пунктах: пристібатися треба й там ({p:5.2}).","ru":"Для пассажиров Правила не делают исключения в населённых пунктах: пристёгиваться нужно и там ({p:5.2})."}},{"uk":"Повинні обов'язково.","ru":"Должны обязательно."},{"uk":"Повинні обов'язково за межами населених пунктів.","ru":"Должны обязательно вне населённых пунктов.","w":{"uk":"Обов'язок пристібатися діє не лише за межами населених пунктів, а під час будь-якої поїздки ({p:5.2}).","ru":"Обязанность пристёгиваться действует не только вне населённых пунктов, а во время любой поездки ({p:5.2})."}}],"c":1,"e":{"uk":"Підпункт «б» {p:5.2} зобов'язує пасажирів користуватися ременями безпеки, якщо їх установку передбачено конструкцією, — незалежно від того, де відбувається рух (виняток — лише пасажири з інвалідністю, яким ремені протипоказані).","ru":"Подпункт «б» {p:5.2} обязывает пассажиров пользоваться ремнями безопасности, если их установка предусмотрена конструкцией, — независимо от того, где происходит движение (исключение — только пассажиры с инвалидностью, которым ремни противопоказаны)."},"ref":["5.2"]},{"id":"h5-9","t":"h5","num":"5.9","q":{"uk":"Чи може пасажир їхати стоячи, користуючись транспортним засобом, що обладнаний поручнями?","ru":"Может ли пассажир ехать стоя, пользуясь транспортным средством, которое оборудовано поручнями?"},"a":[{"uk":"Може, якщо немає сидячих місць.","ru":"Может, если нет сидячих мест.","w":{"uk":"Відсутність сидячих місць не дає права їхати стоячи, якщо конструкція транспортного засобу цього не передбачає ({p:5.2}).","ru":"Отсутствие сидячих мест не даёт права ехать стоя, если конструкция транспортного средства этого не предусматривает ({p:5.2})."}},{"uk":"Може, якщо це передбачено конструкцією транспортного засобу.","ru":"Может, если это предусмотрено конструкцией транспортного средства."}],"c":1,"e":{"uk":"За підпунктом «а» {p:5.2} пасажир може стояти лише тоді, коли це передбачено конструкцією транспортного засобу (як в автобусі чи трамваї), у призначених для цього місцях, тримаючись за поручень.","ru":"Согласно подпункту «а» {p:5.2} пассажир может стоять только тогда, когда это предусмотрено конструкцией транспортного средства (как в автобусе или трамвае), в предназначенных для этого местах, держась за поручень."},"ref":["5.2"]},{"id":"h5-10","t":"h5","num":"5.10","q":{"uk":"Де повинні перебувати пасажири, користуючись транспортним засобом?","ru":"Где должны находиться пассажиры, пользуясь транспортным средством?"},"a":[{"uk":"Сидіти на призначених для цього місцях.","ru":"Сидеть на предназначенных для этого местах.","w":{"uk":"Неповна відповідь: якщо це передбачено конструкцією, пасажир може й стояти ({p:5.2}).","ru":"Неполный ответ: если это предусмотрено конструкцией, пассажир может и стоять ({p:5.2})."}},{"uk":"Стояти (якщо це передбачено конструкцією транспортного засобу) в призначених для цього місцях, тримаючись за поручень або інше пристосування.","ru":"Стоять (если это предусмотрено конструкцией транспортного средства) в предназначенных для этого местах, держась за поручень или другое приспособление.","w":{"uk":"Неповна відповідь: основний спосіб перевезення — сидячи на призначених місцях ({p:5.2}).","ru":"Неполный ответ: основной способ перевозки — сидя на предназначенных местах ({p:5.2})."}},{"uk":"Перебувати в будь-якому зручному місці.","ru":"Находиться в любом удобном месте.","w":{"uk":"Пасажир не може перебувати де завгодно: заборонено, зокрема, сидіти на бортах чи в необладнаному для сидіння місці ({p:5.3}).","ru":"Пассажир не может находиться где угодно: запрещено, в частности, сидеть на бортах или в необорудованном для сидения месте ({p:5.3})."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3.","w":{"uk":"Варіант 3 неправильний, тож неправильне й поєднання 1, 2 і 3.","ru":"Вариант 3 неверен, поэтому неверно и сочетание 1, 2 и 3."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2."}],"c":4,"e":{"uk":"Підпункт «а» {p:5.2}: пасажири сидять або стоять (якщо це передбачено конструкцією) у призначених для цього місцях, тримаючись за поручень чи інше пристосування.","ru":"Подпункт «а» {p:5.2}: пассажиры сидят или стоят (если это предусмотрено конструкцией) в предназначенных для этого местах, держась за поручень или другое приспособление."},"ref":["5.2"]},{"id":"h5-11","t":"h5","num":"5.11","q":{"uk":"Яких умов повинні дотримуватися пасажири при посадці (висадці) з крайньої смуги проїзної частини?","ru":"Каких условий должны придерживаться пассажиры при посадке (высадке) с крайней полосы проезжей части?"},"a":[{"uk":"Виділити себе або мати на зовнішньому одязі світловідбиваючі елементи.","ru":"Выделить себя или иметь на верхней одежде световозвращающие элементы.","w":{"uk":"Світлоповертальні елементи Правила вимагають від пішоходів у темряві ({p:4.4}), а для посадки пасажирів таких умов немає.","ru":"Световозвращающие элементы Правила требуют от пешеходов в темноте ({p:4.4}), а для посадки пассажиров таких условий нет."}},{"uk":"Переконатися, що це буде безпечно та не створить перешкод іншим учасникам руху.","ru":"Убедиться, что это будет безопасно и не создаст помех другим участникам движения."},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2.","w":{"uk":"Варіант 1 неправильний, тож неправильне й це поєднання.","ru":"Вариант 1 неверен, поэтому неверно и это сочетание."}}],"c":1,"e":{"uk":"{p:5.1} дозволяє посадку (висадку) з крайньої смуги (не з боку суміжної смуги) за умови, що це буде безпечно й не створить перешкод іншим учасникам руху.","ru":"{p:5.1} разрешает посадку (высадку) с крайней полосы (не со стороны смежной полосы) при условии, что это будет безопасно и не создаст помех другим участникам движения."},"ref":["5.1"]},{"id":"h5-12","t":"h5","num":"5.12","q":{"uk":"Звідки пасажирам дозволено здійснювати посадку (висадку) за відсутності посадкового майданчика, тротуару та узбіччя?","ru":"Откуда пассажирам разрешено осуществлять посадку (высадку) при отсутствии посадочной площадки, тротуара и обочины?"},"a":[{"uk":"З крайньої смуги проїзної частини з будь-якої сторони транспортного засобу, за умови, що це буде безпечно та не створить перешкод іншим учасникам руху.","ru":"С крайней полосы проезжей части с любой стороны транспортного средства при условии, что это будет безопасно и не создаст помех другим участникам движения.","w":{"uk":"З боку суміжної смуги рухаються інші транспортні засоби, тому посадка «з будь-якої сторони» заборонена ({p:5.1}).","ru":"Со стороны смежной полосы движутся другие транспортные средства, поэтому посадка «с любой стороны» запрещена ({p:5.1})."}},{"uk":"З крайньої смуги проїзної частини, але не з боку суміжної смуги для руху, за умови, що це буде безпечно та не створить перешкод іншим учасникам руху.","ru":"С крайней полосы проезжей части, но не со стороны смежной полосы для движения, при условии, что это будет безопасно и не создаст помех другим участникам движения."}],"c":1,"e":{"uk":"Це дослівно {p:5.1}: з крайньої смуги проїзної частини, але **не з боку суміжної смуги** для руху, і лише якщо це безпечно.","ru":"Это дословно {p:5.1}: с крайней полосы проезжей части, но **не со стороны смежной полосы** для движения, и только если это безопасно."},"ref":["5.1"]},{"id":"h5-13","t":"h5","num":"5.13","q":{"uk":"В якому випадку пасажирам дозволено здійснювати посадку (висадку) з узбіч або тротуарів?","ru":"В каком случае пассажирам разрешено осуществлять посадку (высадку) с обочин или тротуаров?"},"a":[{"uk":"На розсуд водія за умови забезпечення їх безпеки.","ru":"По усмотрению водителя при условии обеспечения их безопасности.","w":{"uk":"Порядок посадки визначають Правила, а не водій: тротуар чи узбіччя використовують лише тоді, коли немає посадкового майданчика ({p:5.1}).","ru":"Порядок посадки определяют Правила, а не водитель: тротуар или обочину используют только тогда, когда нет посадочной площадки ({p:5.1})."}},{"uk":"Тільки в світлу пору доби.","ru":"Только в светлое время суток.","w":{"uk":"Обмежень за порою доби для посадки з тротуару чи узбіччя {p:5.1} не встановлює.","ru":"Ограничений по времени суток для посадки с тротуара или обочины {p:5.1} не устанавливает."}},{"uk":"У разі відсутності посадкового майданчика.","ru":"При отсутствии посадочной площадки."}],"c":2,"e":{"uk":"За {p:5.1} посадка (висадка) відбувається насамперед із посадкового майданчика, а **за його відсутності** — з тротуару чи узбіччя.","ru":"Согласно {p:5.1} посадка (высадка) происходит прежде всего с посадочной площадки, а **при её отсутствии** — с тротуара или обочины."},"ref":["5.1"]},{"id":"h5-14","t":"h5","num":"5.14","q":{"uk":"Посадку (висадку) пасажирам дозволено здійснювати:","ru":"Посадку (высадку) пассажирам разрешено осуществлять:"},"a":[{"uk":"Лише з посадкового майданчика.","ru":"Только с посадочной площадки.","w":{"uk":"Неповна відповідь: за відсутності посадкового майданчика дозволено посадку з тротуару, узбіччя або крайньої смуги ({p:5.1}).","ru":"Неполный ответ: при отсутствии посадочной площадки разрешена посадка с тротуара, обочины или крайней полосы ({p:5.1})."}},{"uk":"За умови відсутності посадкового майданчика, з узбіччя чи тротуару, а якщо це неможливо, то з крайньої смуги.","ru":"При отсутствии посадочной площадки — с обочины или тротуара, а если это невозможно, то с крайней полосы.","w":{"uk":"Неповна відповідь: основне місце посадки — посадковий майданчик ({p:5.1}).","ru":"Неполный ответ: основное место посадки — посадочная площадка ({p:5.1})."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2."}],"c":2,"e":{"uk":"{p:5.1} встановлює черговість: посадковий майданчик, за його відсутності — тротуар чи узбіччя, а якщо й це неможливо — крайня смуга проїзної частини. Варіанти 1 і 2 разом описують увесь цей порядок.","ru":"{p:5.1} устанавливает очерёдность: посадочная площадка, при её отсутствии — тротуар или обочина, а если и это невозможно — крайняя полоса проезжей части. Варианты 1 и 2 вместе описывают весь этот порядок."},"ref":["5.1"]},{"id":"h5-15","t":"h5","num":"5.15","q":{"uk":"В якому випадку пасажири при русі механічного транспортного засобу, обладнаного ременями безпеки, повинні бути пристебнутими згідно Правил дорожнього руху?","ru":"В каком случае пассажиры при движении механического транспортного средства, оборудованного ремнями безопасности, должны быть пристёгнутыми согласно Правилам дорожного движения?"},"a":[{"uk":"Тільки при знаходженні на передньому сидінні.","ru":"Только при нахождении на переднем сиденье.","w":{"uk":"Обов'язок пристібатися не обмежується переднім сидінням: на задньому сидінні непристебнутий пасажир так само травмується сам і травмує інших ({p:5.2}).","ru":"Обязанность пристёгиваться не ограничивается передним сиденьем: на заднем сиденье непристёгнутый пассажир так же травмируется сам и травмирует других ({p:5.2})."}},{"uk":"На всіх сидіннях, обладнаних ременями безпеки.","ru":"На всех сиденьях, оборудованных ремнями безопасности."}],"c":1,"e":{"uk":"Підпункт «б» {p:5.2} зобов'язує пасажирів користуватися ременями безпеки всюди, де їх установку передбачено конструкцією, — отже, і на задніх сидіннях.","ru":"Подпункт «б» {p:5.2} обязывает пассажиров пользоваться ремнями безопасности везде, где их установка предусмотрена конструкцией, — значит, и на задних сиденьях."},"ref":["5.2"]},{"id":"h5-16","t":"h5","num":"5.16","q":{"uk":"Чи правильно здійснюють посадку пасажири в наведеній ситуації?","ru":"Правильно ли осуществляют посадку пассажиры в приведённой ситуации?"},"a":[{"uk":"Так, посадку (висадку) дозволяється здійснювати пасажирам з будь-якої сторони проїзної частини за умови, що це буде безпечно та не створить перешкод іншим учасникам руху.","ru":"Да, посадку (высадку) разрешается осуществлять пассажирам с любой стороны проезжей части при условии, что это будет безопасно и не создаст помех другим участникам движения.","w":{"uk":"Посадка «з будь-якої сторони» суперечить {p:5.1}: з боку суміжної смуги вона заборонена.","ru":"Посадка «с любой стороны» противоречит {p:5.1}: со стороны смежной полосы она запрещена."}},{"uk":"Ні, посадку (висадку) дозволяється здійснювати пасажирам з крайньої смуги проїзної частини (але не з боку суміжної смуги для руху), за умови, що це буде безпечно та не створить перешкод іншим учасникам руху.","ru":"Нет, посадку (высадку) разрешается осуществлять пассажирам с крайней полосы проезжей части (но не со стороны смежной полосы для движения) при условии, что это будет безопасно и не создаст помех другим участникам движения."}],"c":1,"e":{"uk":"Жінка з дитиною сідають у автомобіль через ліві двері — з боку суміжної смуги, якою рухаються інші транспортні засоби. {p:5.1} дозволяє посадку з крайньої смуги лише **не з боку суміжної смуги**.","ru":"Женщина с ребёнком садятся в автомобиль через левые двери — со стороны смежной полосы, по которой движутся другие транспортные средства. {p:5.1} разрешает посадку с крайней полосы только **не со стороны смежной полосы**."},"ref":["5.1"],"pic":["img/hsc/5-16-1.jpg"]},{"id":"h6-1","t":"h6","num":"6.1","q":{"uk":"Чи має перевагу в русі велосипедист, якщо велосипедна доріжка перетинає дорогу поза перехрестям?","ru":"Имеет ли преимущество в движении велосипедист, если велосипедная дорожка пересекает дорогу вне перекрёстка?"},"a":[{"uk":"Не має.","ru":"Не имеет."},{"uk":"Має.","ru":"Имеет.","w":{"uk":"Поза перехрестям перевагу мають транспортні засоби на дорозі, а не велосипедист, що виїжджає з доріжки ({p:6.5}).","ru":"Вне перекрёстка преимущество имеют транспортные средства на дороге, а не велосипедист, выезжающий с дорожки ({p:6.5})."}},{"uk":"Має перевагу, якщо автомобіль наближається зліва.","ru":"Имеет преимущество, если автомобиль приближается слева.","w":{"uk":"Правило «перешкоди праворуч» діє на перехрестях рівнозначних доріг ({p:16.12}); тут велосипедист поступається всім, хто їде дорогою, з будь-якого боку ({p:6.5}).","ru":"Правило «помехи справа» действует на перекрёстках равнозначных дорог ({p:16.12}); здесь велосипедист уступает всем, кто едет по дороге, с любой стороны ({p:6.5})."}}],"c":0,"e":{"uk":"Велосипедна доріжка (знак {s:4.14}) перетинає дорогу поза перехрестям, а в такому разі {p:6.5} зобов'язує велосипедистів дати дорогу транспортним засобам, що рухаються дорогою. Знак {s:1.34} лише попереджає водіїв про можливу появу велосипедистів.","ru":"Велосипедная дорожка (знак {s:4.14}) пересекает дорогу вне перекрёстка, а в таком случае {p:6.5} обязывает велосипедистов уступить дорогу транспортным средствам, движущимся по дороге. Знак {s:1.34} лишь предупреждает водителей о возможном появлении велосипедистов."},"ref":["6.5"],"pic":["img/hsc/6-1-1.jpg"]},{"id":"h6-2","t":"h6","num":"6.2","q":{"uk":"Чи дозволено перевезення пасажирів на велосипеді?","ru":"Разрешена ли перевозка пассажиров на велосипеде?"},"a":[{"uk":"Дозволено на багажнику.","ru":"Разрешена на багажнике.","w":{"uk":"Багажник не є обладнаним сидінням: возити на ньому пасажира заборонено ({p:6.6}).","ru":"Багажник не является оборудованным сиденьем: возить на нём пассажира запрещено ({p:6.6})."}},{"uk":"Дозволено на рамі велосипеда.","ru":"Разрешена на раме велосипеда.","w":{"uk":"Пасажир на рамі заважає керуванню й не має опори для ніг — це заборонено ({p:6.6}).","ru":"Пассажир на раме мешает управлению и не имеет опоры для ног — это запрещено ({p:6.6})."}},{"uk":"Заборонено перевезення пасажирів на велосипеді (за винятком дітей до 7 років, які перевозяться на додатковому сидінні, обладнаному надійно закріпленими підніжками).","ru":"Запрещена перевозка пассажиров на велосипеде (за исключением детей до 7 лет, перевозимых на дополнительном сиденье, оборудованном надёжно закреплёнными подножками)."}],"c":2,"e":{"uk":"Це дослівно підпункт «д» {p:6.6}: возити пасажирів на велосипеді заборонено, крім дітей до 7 років на додатковому сидінні з надійно закріпленими підніжками.","ru":"Это дословно подпункт «д» {p:6.6}: возить пассажиров на велосипеде запрещено, кроме детей до 7 лет на дополнительном сиденье с надёжно закреплёнными подножками."},"ref":["6.6"]},{"id":"h6-3","t":"h6","num":"6.3","q":{"uk":"Велосипедисту під час руху на велосипеді забороняється:","ru":"Велосипедисту во время движения на велосипеде запрещается:"},"a":[{"uk":"Триматися за інший транспортний засіб.","ru":"Держаться за другое транспортное средство.","w":{"uk":"Неповна відповідь: їздити без рук і знімати ноги з педалей теж заборонено ({p:6.6}).","ru":"Неполный ответ: ездить без рук и снимать ноги с педалей тоже запрещено ({p:6.6})."}},{"uk":"Їздити, не тримаючись за кермо, та знімати ноги з педалей (підніжок).","ru":"Ездить, не держась за руль, и снимать ноги с педалей (подножек).","w":{"uk":"Неповна відповідь: триматися за інший транспортний засіб теж заборонено ({p:6.6}).","ru":"Неполный ответ: держаться за другое транспортное средство тоже запрещено ({p:6.6})."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2."}],"c":2,"e":{"uk":"Обидві заборони містить {p:6.6}: підпункт «г» — триматися за інший транспортний засіб, підпункт «ґ» — їздити, не тримаючись за кермо, і знімати ноги з педалей.","ru":"Оба запрета содержит {p:6.6}: подпункт «г» — держаться за другое транспортное средство, подпункт «ґ» — ездить, не держась за руль, и снимать ноги с педалей."},"ref":["6.6"]},{"id":"h6-4","t":"h6","num":"6.4","q":{"uk":"У якому випадку велосипедистам дозволено рухатись тротуарами і пішохідними доріжками?","ru":"В каком случае велосипедистам разрешено двигаться по тротуарам и пешеходным дорожкам?"},"a":[{"uk":"Дозволено за відсутності велосипедної доріжки.","ru":"Разрешено при отсутствии велосипедной дорожки.","w":{"uk":"Відсутність велосипедної доріжки не дає права їхати тротуаром: тоді велосипедист рухається проїзною частиною чи узбіччям ({p:6.6}).","ru":"Отсутствие велосипедной дорожки не даёт права ехать по тротуару: тогда велосипедист движется по проезжей части или обочине ({p:6.6})."}},{"uk":"Дозволено тільки дітям до 7 років на дитячих велосипедах під наглядом дорослих.","ru":"Разрешено только детям до 7 лет на детских велосипедах под присмотром взрослых."},{"uk":"Дозволено в будь-якому випадку.","ru":"Разрешено в любом случае.","w":{"uk":"Тротуари й пішохідні доріжки призначені для пішоходів, і рух велосипедистів ними заборонено ({p:6.6}).","ru":"Тротуары и пешеходные дорожки предназначены для пешеходов, и движение велосипедистов по ним запрещено ({p:6.6})."}}],"c":1,"e":{"uk":"Підпункт «в» {p:6.6} забороняє велосипедистам рухатися тротуарами й пішохідними доріжками; виняток — лише діти до 7 років на дитячих велосипедах під наглядом дорослих.","ru":"Подпункт «в» {p:6.6} запрещает велосипедистам двигаться по тротуарам и пешеходным дорожкам; исключение — только дети до 7 лет на детских велосипедах под присмотром взрослых."},"ref":["6.6"]},{"id":"h6-5","t":"h6","num":"6.5","q":{"uk":"У якому випадку велосипедисту заборонено рухатися проїзною частиною?","ru":"В каком случае велосипедисту запрещено двигаться по проезжей части?"},"a":[{"uk":"Якщо поряд облаштовано велосипедну доріжку.","ru":"Если рядом обустроена велосипедная дорожка."},{"uk":"Якщо проїзна частина звужена.","ru":"Если проезжая часть сужена.","w":{"uk":"Звуження проїзної частини не забороняє рух велосипедиста — Правила такої заборони не містять.","ru":"Сужение проезжей части не запрещает движение велосипедиста — Правила такого запрета не содержат."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2.","w":{"uk":"Варіант 2 неправильний, тож неправильне й це поєднання.","ru":"Вариант 2 неверен, поэтому неверно и это сочетание."}}],"c":0,"e":{"uk":"Підпункт «б» {p:6.6} забороняє велосипедистові рухатися проїзною частиною, коли поряд облаштовано велосипедну доріжку.","ru":"Подпункт «б» {p:6.6} запрещает велосипедисту двигаться по проезжей части, когда рядом обустроена велосипедная дорожка."},"ref":["6.6"]},{"id":"h6-6","t":"h6","num":"6.6","q":{"uk":"За яких умов велосипедисту заборонено керувати велосипедом?","ru":"При каких условиях велосипедисту запрещено управлять велосипедом?"},"a":[{"uk":"На велосипеді несправні гальма і звуковий сигнал.","ru":"На велосипеде неисправны тормоза и звуковой сигнал.","w":{"uk":"Неповна відповідь: у темряві заборонено ще й їздити без увімкненого ліхтаря чи світлоповертачів ({p:6.6}).","ru":"Неполный ответ: в темноте запрещено ещё и ездить без включённого фонаря или световозвращателей ({p:6.6})."}},{"uk":"Рухатися у темну пору доби та в умовах недостатньої видимості — з вимкненим ліхтарем (фарою) чи без світлоповертачів.","ru":"Двигаться в тёмное время суток и в условиях недостаточной видимости — с выключенным фонарём (фарой) или без световозвращателей.","w":{"uk":"Неповна відповідь: несправні гальма чи звуковий сигнал теж забороняють керувати велосипедом ({p:6.6}).","ru":"Неполный ответ: неисправные тормоза или звуковой сигнал тоже запрещают управлять велосипедом ({p:6.6})."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2."}],"c":2,"e":{"uk":"Підпункт «а» {p:6.6} забороняє і керувати велосипедом з несправним гальмом чи звуковим сигналом, і їздити в темряві чи за недостатньої видимості з вимкненим ліхтарем (фарою) або без світлоповертачів.","ru":"Подпункт «а» {p:6.6} запрещает и управлять велосипедом с неисправным тормозом или звуковым сигналом, и ездить в темноте или при недостаточной видимости с выключенным фонарём (фарой) или без световозвращателей."},"ref":["6.6"]},{"id":"h6-7","t":"h6","num":"6.7","q":{"uk":"Які вантажі може перевозити велосипедист?","ru":"Какие грузы может перевозить велосипедист?"},"a":[{"uk":"Такі, які можна закріпити на його рамі або багажнику.","ru":"Такие, которые можно закрепить на его раме или багажнике.","w":{"uk":"Важить не спосіб закріплення, а вплив на керування: закріплений на рамі великий вантаж усе одно може заважати й виступати за габарити ({p:6.4}).","ru":"Важен не способ крепления, а влияние на управление: закреплённый на раме большой груз всё равно может мешать и выступать за габариты ({p:6.4})."}},{"uk":"Такі, які не заважають керувати велосипедом і не створюють перешкод іншим учасникам дорожнього руху.","ru":"Такие, которые не мешают управлять велосипедом и не создают помех другим участникам дорожного движения."}],"c":1,"e":{"uk":"{p:6.4} дозволяє перевозити лише такі вантажі, які не заважають керувати велосипедом і не створюють перешкод іншим учасникам руху.","ru":"{p:6.4} разрешает перевозить только такие грузы, которые не мешают управлять велосипедом и не создают помех другим участникам движения."},"ref":["6.4"]},{"id":"h6-8","t":"h6","num":"6.8","q":{"uk":"Яка дистанція має бути між рухомими колонами велосипедистів?","ru":"Какая дистанция должна быть между движущимися колоннами велосипедистов?"},"a":[{"uk":"10 – 30 м.","ru":"10–30 м.","w":{"uk":"10–30 м замало: між групами велосипедистів {p:6.3} вимагає 80–100 м.","ru":"10–30 м слишком мало: между группами велосипедистов {p:6.3} требует 80–100 м."}},{"uk":"80 – 100 м.","ru":"80–100 м."},{"uk":"150 – 200 м.","ru":"150–200 м.","w":{"uk":"150–200 м — завелика дистанція; {p:6.3} встановлює 80–100 м.","ru":"150–200 м — слишком большая дистанция; {p:6.3} устанавливает 80–100 м."}}],"c":1,"e":{"uk":"За {p:6.3} колону велосипедистів на проїзній частині ділять на групи до 10 велосипедистів із дистанцією між групами 80–100 м, щоб інші транспортні засоби могли їх безпечно обганяти.","ru":"Согласно {p:6.3} колонну велосипедистов на проезжей части делят на группы до 10 велосипедистов с дистанцией между группами 80–100 м, чтобы другие транспортные средства могли их безопасно обгонять."},"ref":["6.3"]},{"id":"h6-9","t":"h6","num":"6.9","q":{"uk":"Рухаючись групами, велосипедисти мають їхати по дорозі...","ru":"Двигаясь группами, велосипедисты должны ехать по дороге…"},"a":[{"uk":"Один за одним або один біля одного, щоб не заважати іншим учасникам дорожнього руху.","ru":"Друг за другом или рядом друг с другом, чтобы не мешать другим участникам дорожного движения.","w":{"uk":"Їхати поруч Правила групам велосипедистів не дозволяють: так група займає більше місця на дорозі й заважає іншим ({p:6.3}).","ru":"Ехать рядом Правила группам велосипедистов не разрешают: так группа занимает больше места на дороге и мешает другим ({p:6.3})."}},{"uk":"Один за одним, щоб не заважати іншим учасникам дорожнього руху.","ru":"Друг за другом, чтобы не мешать другим участникам дорожного движения."}],"c":1,"e":{"uk":"{p:6.3}: велосипедисти, рухаючись групами, повинні їхати **один за одним**, щоб не заважати іншим учасникам руху.","ru":"{p:6.3}: велосипедисты, двигаясь группами, должны ехать **друг за другом**, чтобы не мешать другим участникам движения."},"ref":["6.3"]},{"id":"h6-10","t":"h6","num":"6.10","q":{"uk":"Що встановлюється на велосипедах для руху в темну пору доби та в умовах недостатньої видимості?","ru":"Что устанавливается на велосипедах для движения в тёмное время суток и в условиях недостаточной видимости?"},"a":[{"uk":"Звуковий сигнал.","ru":"Звуковой сигнал.","w":{"uk":"Звуковий сигнал обов'язковий на велосипеді завжди, а не лише для руху в темряві; освітлює ж дорогу й робить велосипедиста помітним саме ліхтар ({p:6.2}).","ru":"Звуковой сигнал обязателен на велосипеде всегда, а не только для движения в темноте; освещает же дорогу и делает велосипедиста заметным именно фонарь ({p:6.2})."}},{"uk":"Ліхтарі (фари).","ru":"Фонари (фары)."}],"c":1,"e":{"uk":"За {p:6.2} для руху в темну пору доби та за недостатньої видимості на велосипеді повинен бути встановлений і ввімкнений ліхтар (фара).","ru":"Согласно {p:6.2} для движения в тёмное время суток и при недостаточной видимости на велосипеде должен быть установлен и включён фонарь (фара)."},"ref":["6.2"]},{"id":"h6-11","t":"h6","num":"6.11","q":{"uk":"Чим має бути обладнаний велосипед?","ru":"Чем должен быть оборудован велосипед?"},"a":[{"uk":"Звуковим сигналом.","ru":"Звуковым сигналом.","w":{"uk":"Неповна відповідь: потрібні ще світлоповертачі й ліхтар для руху в темряві ({p:6.2}).","ru":"Неполный ответ: нужны ещё световозвращатели и фонарь для движения в темноте ({p:6.2})."}},{"uk":"Світлоповертачами: спереду – білого кольору, по боках – оранжевого, ззаду – червоного.","ru":"Световозвращателями: спереди — белого цвета, по бокам — оранжевого, сзади — красного.","w":{"uk":"Неповна відповідь: потрібні ще звуковий сигнал і ліхтар для руху в темряві ({p:6.2}).","ru":"Неполный ответ: нужны ещё звуковой сигнал и фонарь для движения в темноте ({p:6.2})."}},{"uk":"Під час руху в темний час доби і в умовах недостатньої видимості має бути встановлений і увімкнений ліхтар (фара).","ru":"Во время движения в тёмное время суток и в условиях недостаточной видимости должен быть установлен и включён фонарь (фара).","w":{"uk":"Неповна відповідь: велосипед також має бути обладнаний звуковим сигналом і світлоповертачами ({p:6.2}).","ru":"Неполный ответ: велосипед также должен быть оборудован звуковым сигналом и световозвращателями ({p:6.2})."}},{"uk":"Відповіді 1, 2, 3.","ru":"Ответы 1, 2, 3."}],"c":3,"e":{"uk":"Усі три вимоги містить {p:6.2}: звуковий сигнал, світлоповертачі (спереду білі, по боках оранжеві, позаду червоні), а для руху в темряві — увімкнений ліхтар (фара).","ru":"Все три требования содержит {p:6.2}: звуковой сигнал, световозвращатели (спереди белые, по бокам оранжевые, сзади красные), а для движения в темноте — включённый фонарь (фара)."},"ref":["6.2"]},{"id":"h6-12","t":"h6","num":"6.12","q":{"uk":"З якого віку дозволено рухатися по дорогах на велосипеді?","ru":"С какого возраста разрешено двигаться по дорогам на велосипеде?"},"a":[{"uk":"З 10 років.","ru":"С 10 лет.","w":{"uk":"10 років замало: самостійно їздити дорогою на велосипеді можна лише з 14 років ({p:6.1}).","ru":"10 лет слишком мало: самостоятельно ездить по дороге на велосипеде можно только с 14 лет ({p:6.1})."}},{"uk":"З 12 років.","ru":"С 12 лет.","w":{"uk":"12 років замало: Правила встановлюють вік 14 років ({p:6.1}).","ru":"12 лет слишком мало: Правила устанавливают возраст 14 лет ({p:6.1})."}},{"uk":"З 14 років.","ru":"С 14 лет."},{"uk":"З 16 років.","ru":"С 16 лет.","w":{"uk":"16 років — завищений вік; велосипедом дорогою можна їздити вже з 14 років ({p:6.1}).","ru":"16 лет — завышенный возраст; на велосипеде по дороге можно ездить уже с 14 лет ({p:6.1})."}}],"c":2,"e":{"uk":"{p:6.1}: рухатися по дорозі на велосипедах дозволяється особам, які досягли **14-річного** віку.","ru":"{p:6.1}: двигаться по дороге на велосипедах разрешается лицам, достигшим **14-летнего** возраста."},"ref":["6.1"]},{"id":"h6-13","t":"h6","num":"6.13","q":{"uk":"Чи дозволено велосипедистам рухатися автомагістралями, дорогами для автомобілів і проїзною частиною за наявності поруч велосипедної доріжки?","ru":"Разрешено ли велосипедистам двигаться по автомагистралям, дорогам для автомобилей и по проезжей части при наличии рядом велосипедной дорожки?"},"a":[{"uk":"Заборонено.","ru":"Запрещено."},{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"Усі три випадки прямо перелічено в забороні підпункту «б» {p:6.6}.","ru":"Все три случая прямо перечислены в запрете подпункта «б» {p:6.6}."}}],"c":0,"e":{"uk":"Підпункт «б» {p:6.6} прямо забороняє велосипедистам рухатися автомагістралями й дорогами для автомобілів, а також проїзною частиною, коли поряд облаштовано велосипедну доріжку.","ru":"Подпункт «б» {p:6.6} прямо запрещает велосипедистам двигаться по автомагистралям и дорогам для автомобилей, а также по проезжей части, когда рядом обустроена велосипедная дорожка."},"ref":["6.6"]},{"id":"h6-14","t":"h6","num":"6.14","q":{"uk":"Чи дозволено буксирування велосипеда?","ru":"Разрешена ли буксировка велосипеда?"},"a":[{"uk":"Дозволено.","ru":"Разрешена.","w":{"uk":"Буксирування велосипедів прямо заборонено ({p:6.6}): велосипед не має гальм і світлових приладів, достатніх для безпечного буксирування.","ru":"Буксировка велосипедов прямо запрещена ({p:6.6}): велосипед не имеет тормозов и световых приборов, достаточных для безопасной буксировки."}},{"uk":"Заборонено.","ru":"Запрещена."}],"c":1,"e":{"uk":"Підпункт «е» {p:6.6} забороняє буксирувати велосипеди.","ru":"Подпункт «е» {p:6.6} запрещает буксировать велосипеды."},"ref":["6.6"]},{"id":"h6-15","t":"h6","num":"6.15","q":{"uk":"У місцях, де рух регулюється, велосипедисти повинні керуватися:","ru":"В местах, где движение регулируется, велосипедисты должны руководствоваться:"},"a":[{"uk":"Сигналами регулювальника.","ru":"Сигналами регулировщика.","w":{"uk":"Неповна відповідь: якщо регулювальника немає, велосипедист керується сигналами світлофора ({p:6.5}).","ru":"Неполный ответ: если регулировщика нет, велосипедист руководствуется сигналами светофора ({p:6.5})."}},{"uk":"Сигналами світлофора.","ru":"Сигналами светофора.","w":{"uk":"Неповна відповідь: якщо рух регулює регулювальник, діють його сигнали, і вони мають перевагу над світлофором ({p:8.3}).","ru":"Неполный ответ: если движение регулирует регулировщик, действуют его сигналы, и они имеют преимущество над светофором ({p:8.3})."}},{"uk":"Дорожніми знаками.","ru":"Дорожными знаками.","w":{"uk":"Регульованим місце роблять саме регулювальник чи світлофор, і їхні сигнали мають перевагу над знаками пріоритету ({p:8.3}).","ru":"Регулируемым место делают именно регулировщик или светофор, и их сигналы имеют преимущество над знаками приоритета ({p:8.3})."}},{"uk":"Відповіді 1 або 2.","ru":"Ответы 1 или 2."}],"c":3,"e":{"uk":"Третій абзац {p:6.5}: у місцях, де рух регулюється, велосипедисти керуються сигналами регулювальника **або** світлофора — залежно від того, чим регулюється рух.","ru":"Третий абзац {p:6.5}: в местах, где движение регулируется, велосипедисты руководствуются сигналами регулировщика **или** светофора — в зависимости от того, чем регулируется движение."},"ref":["6.5","8.3"],"pic":["img/hsc/6-15-1.jpg"]},{"id":"h6-16","t":"h6","num":"6.16","q":{"uk":"Що позначає вказаний дорожній знак?","ru":"Что обозначает указанный дорожный знак?"},"a":[{"uk":"Суміжні пішохідний перехід та велосипедний переїзд.","ru":"Смежные пешеходный переход и велосипедный переезд.","w":{"uk":"На знаку {s:5.93.1} «Суміжні пішохідний перехід та велосипедний переїзд» зображено і пішохода, і велосипедиста, а тут лише велосипедист.","ru":"На знаке {s:5.93.1} «Смежные пешеходный переход и велосипедный переезд» изображены и пешеход, и велосипедист, а здесь только велосипедист."}},{"uk":"Велосипедний переїзд.","ru":"Велосипедный переезд."}],"c":1,"e":{"uk":"На знаку — велосипедист над розміткою переїзду, без пішохода: це знак {s:5.92.1} «Велосипедний переїзд», що позначає організований переїзд велосипедистів через проїзну частину ({p:33.5}).","ru":"На знаке — велосипедист над разметкой переезда, без пешехода: это знак {s:5.92.1} «Велосипедный переезд», обозначающий организованный переезд велосипедистов через проезжую часть ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/6-16-1.jpg"]},{"id":"h6-17","t":"h6","num":"6.17","q":{"uk":"Що в даному випадку позначає ця горизонтальна розмітка?","ru":"Что в данном случае обозначает эта горизонтальная разметка?"},"a":[{"uk":"Велосипедний переїзд.","ru":"Велосипедный переезд."},{"uk":"Пішохідний перехід.","ru":"Пешеходный переход.","w":{"uk":"Пішохідний перехід позначають «зеброю» — широкими смугами, паралельними осі дороги ({m:1.14.1}), а не двома рядами прямокутників.","ru":"Пешеходный переход обозначают «зеброй» — широкими полосами, параллельными оси дороги ({m:1.14.1}), а не двумя рядами прямоугольников."}},{"uk":"Велосипедну смугу.","ru":"Велосипедную полосу.","w":{"uk":"Велосипедна смуга тягнеться вздовж проїзної частини, а ця розмітка перетинає її поперек.","ru":"Велосипедная полоса тянется вдоль проезжей части, а эта разметка пересекает её поперёк."}}],"c":0,"e":{"uk":"Поперек проїзної частини нанесено дві лінії білих прямокутників (тут — на червоному покритті): це розмітка {m:1.15}, що позначає місце, де велосипедна доріжка перетинає проїзну частину ({p:34.1}, {p:1.10}).","ru":"Поперёк проезжей части нанесены две линии белых прямоугольников (здесь — на красном покрытии): это разметка {m:1.15}, обозначающая место, где велосипедная дорожка пересекает проезжую часть ({p:34.1}, {p:1.10})."},"ref":["1.10","34.1"],"pic":["img/hsc/6-17-1.jpg"]},{"id":"h6-18","t":"h6","num":"6.18","q":{"uk":"Яке з наведених тверджень про велосипедистів є невірним?","ru":"Какое из приведённых утверждений о велосипедистах является неверным?"},"a":[{"uk":"У місцях, де рух регулюється, велосипедисти повинні керуватися сигналами регулювальника або світлофора.","ru":"В местах, где движение регулируется, велосипедисты должны руководствоваться сигналами регулировщика или светофора.","w":{"uk":"Це твердження правильне — його містить {p:6.5}, тож воно не є відповіддю на питання про невірне.","ru":"Это утверждение верно — его содержит {p:6.5}, поэтому оно не является ответом на вопрос о неверном."}},{"uk":"Рухатися по дорозі на велосипедах дозволяється особам, які досягли 14-річного віку.","ru":"Двигаться по дороге на велосипедах разрешается лицам, достигшим 14-летнего возраста.","w":{"uk":"Це твердження правильне — вік 14 років встановлює {p:6.1}.","ru":"Это утверждение верно — возраст 14 лет устанавливает {p:6.1}."}},{"uk":"Велосипедистам дозволено рухатися по тротуарах і пішохідних доріжках (крім дітей до 7 років на дитячих велосипедах під наглядом дорослих).","ru":"Велосипедистам разрешено двигаться по тротуарам и пешеходным дорожкам (кроме детей до 7 лет на детских велосипедах под присмотром взрослых)."}],"c":2,"e":{"uk":"Неправильне твердження 3: підпункт «в» {p:6.6} якраз **забороняє** велосипедистам рухатися тротуарами й пішохідними доріжками, а виняток зроблено лише для дітей до 7 років. Твердження 1 і 2 дослівно повторюють {p:6.5} і {p:6.1}.","ru":"Неверно утверждение 3: подпункт «в» {p:6.6} как раз **запрещает** велосипедистам двигаться по тротуарам и пешеходным дорожкам, а исключение сделано только для детей до 7 лет. Утверждения 1 и 2 дословно повторяют {p:6.5} и {p:6.1}."},"ref":["6.1","6.5","6.6"]},{"id":"h6-19","t":"h6","num":"6.19","q":{"uk":"Велосипедна смуга дозволяє також рух мопедів по ній?","ru":"Разрешает ли велосипедная полоса также движение мопедов по ней?"},"a":[{"uk":"Так.","ru":"Да.","w":{"uk":"Велосипедна смуга призначена лише для велосипедів ({p:1.10}), а мопед має двигун і велосипедом не є.","ru":"Велосипедная полоса предназначена только для велосипедов ({p:1.10}), а мопед имеет двигатель и велосипедом не является."}},{"uk":"Ні.","ru":"Нет."}],"c":1,"e":{"uk":"Знак {s:5.88} позначає велосипедну смугу, а за {p:1.10} вона призначена саме для руху на велосипедах. Мопед — механічний транспортний засіб із двигуном, а не велосипед, тож рухатися нею не може.","ru":"Знак {s:5.88} обозначает велосипедную полосу, а согласно {p:1.10} она предназначена именно для движения на велосипедах. Мопед — механическое транспортное средство с двигателем, а не велосипед, поэтому двигаться по ней не может."},"ref":["1.10","33.5"],"pic":["img/hsc/6-19-1.jpg"]},{"id":"h6-20","t":"h6","num":"6.20","q":{"uk":"Велосипедна смуга дозволяє також рух мотоциклів по ній?","ru":"Разрешает ли велосипедная полоса также движение мотоциклов по ней?"},"a":[{"uk":"Так.","ru":"Да.","w":{"uk":"Мотоцикл — механічний транспортний засіб, а велосипедна смуга призначена тільки для велосипедів ({p:1.10}).","ru":"Мотоцикл — механическое транспортное средство, а велосипедная полоса предназначена только для велосипедов ({p:1.10})."}},{"uk":"Ні.","ru":"Нет."}],"c":1,"e":{"uk":"Велосипедна смуга (знак {s:5.88}) за {p:1.10} призначена лише для руху на велосипедах, тож мотоциклам рухатися нею не можна.","ru":"Велосипедная полоса (знак {s:5.88}) согласно {p:1.10} предназначена только для движения на велосипедах, поэтому мотоциклам двигаться по ней нельзя."},"ref":["1.10","33.5"],"pic":["img/hsc/6-20-1.jpg"]},{"id":"h6-21","t":"h6","num":"6.21","q":{"uk":"Крім велосипедів, по велосипедній смузі можуть рухатись:","ru":"Кроме велосипедов, по велосипедной полосе могут двигаться:"},"a":[{"uk":"Водії мотоциклів.","ru":"Водители мотоциклов.","w":{"uk":"Мотоцикли рухаються проїзною частиною, а не велосипедною смугою ({p:1.10}).","ru":"Мотоциклы движутся по проезжей части, а не по велосипедной полосе ({p:1.10})."}},{"uk":"Водії мопедів.","ru":"Водители мопедов.","w":{"uk":"Мопед має двигун і велосипедом не є, тому велосипедною смугою рухатися не може ({p:1.10}).","ru":"Мопед имеет двигатель и велосипедом не является, поэтому по велосипедной полосе двигаться не может ({p:1.10})."}},{"uk":"Ніхто з вищеперерахованих.","ru":"Никто из вышеперечисленных."}],"c":2,"e":{"uk":"За {p:1.10} велосипедна смуга (знак {s:5.88}) призначена для руху на велосипедах; ні мотоциклам, ні мопедам Правила рух нею не дозволяють.","ru":"Согласно {p:1.10} велосипедная полоса (знак {s:5.88}) предназначена для движения на велосипедах; ни мотоциклам, ни мопедам Правила движение по ней не разрешают."},"ref":["1.10","33.5"],"pic":["img/hsc/6-21-1.jpg"]},{"id":"h6-22","t":"h6","num":"6.22","q":{"uk":"Чи дозволено велосипедистам рухатися в два ряди, якщо зустрічні транспортні засоби відсутні?","ru":"Разрешено ли велосипедистам двигаться в два ряда, если встречные транспортные средства отсутствуют?"},"a":[{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"Рух у два ряди Правила велосипедистам не дозволяють за жодних умов ({p:6.3}, {p:11.14}).","ru":"Движение в два ряда Правила велосипедистам не разрешают ни при каких условиях ({p:6.3}, {p:11.14})."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":1,"e":{"uk":"Велосипедисти, рухаючись групою, повинні їхати один за одним ({p:6.3}), а проїзною частиною — лише в один ряд якомога правіше ({p:11.14}). Відсутність зустрічного транспорту цього не змінює: їх можуть наздоганяти попутні автомобілі.","ru":"Велосипедисты, двигаясь группой, должны ехать друг за другом ({p:6.3}), а по проезжей части — только в один ряд как можно правее ({p:11.14}). Отсутствие встречного транспорта этого не меняет: их могут догонять попутные автомобили."},"ref":["6.3","11.14"],"pic":["img/hsc/6-22-1.jpg"]},{"id":"h7-1","t":"h7","num":"7.1","q":{"uk":"У разі виїзду з прилеглої території в місцях з обмеженою оглядовістю дороги, водій гужового воза повинен...","ru":"При выезде с прилегающей территории в местах с ограниченной обзорностью дороги водитель гужевой повозки должен…"},"a":[{"uk":"Виїхати швидше, не заважаючи транспортним засобам, які рухаються по дорозі.","ru":"Выехать быстрее, не мешая транспортным средствам, движущимся по дороге.","w":{"uk":"Поспіх в умовах обмеженої оглядовості небезпечний; Правила вимагають не швидкості, а контролю над твариною — вести її за вуздечку ({p:7.4}).","ru":"Спешка в условиях ограниченной обзорности опасна; Правила требуют не скорости, а контроля над животным — вести его под уздцы ({p:7.4})."}},{"uk":"Вести тварину за вуздечку, повід.","ru":"Вести животное под уздцы, за повод."}],"c":1,"e":{"uk":"Повіз виїжджає на дорогу з ґрунтового виїзду, звідки дорогу погано видно. За {p:7.4} у такому місці водій воза повинен вести тварину за вуздечку (повід), щоб вона не рвонула на проїзну частину.","ru":"Повозка выезжает на дорогу с грунтового выезда, откуда дорога плохо просматривается. Согласно {p:7.4} в таком месте водитель повозки должен вести животное под уздцы (за повод), чтобы оно не рвануло на проезжую часть."},"ref":["7.4"],"pic":["img/hsc/7-1-1.jpg"]},{"id":"h7-2","t":"h7","num":"7.2","q":{"uk":"Чим повинен бути обладнаний гужовий віз (сани)?","ru":"Чем должна быть оборудована гужевая повозка (сани)?"},"a":[{"uk":"Звуковим сигналом і світлоповертачами.","ru":"Звуковым сигналом и световозвращателями.","w":{"uk":"Звукового сигналу для гужового воза Правила не вимагають — його вимагають, наприклад, для велосипеда ({p:6.2}).","ru":"Звукового сигнала для гужевой повозки Правила не требуют — его требуют, например, для велосипеда ({p:6.2})."}},{"uk":"Світлоповертачами: спереду – білого кольору, ззаду – червоного.","ru":"Световозвращателями: спереди — белого цвета, сзади — красного."}],"c":1,"e":{"uk":"{p:7.2}: гужовий віз (сани) повинен бути обладнаний світлоповертачами — спереду білого кольору, ззаду червоного.","ru":"{p:7.2}: гужевая повозка (сани) должна быть оборудована световозвращателями — спереди белого цвета, сзади красного."},"ref":["7.2"]},{"id":"h7-3","t":"h7","num":"7.3","q":{"uk":"З якого боку гужового воза (саней) повинні бути встановлені ліхтарі для руху в темну пору доби?","ru":"С какой стороны гужевой повозки (саней) должны быть установлены фонари для движения в тёмное время суток?"},"a":[{"uk":"З правого і лівого.","ru":"С правой и левой.","w":{"uk":"Встановлювати ліхтарі з обох боків Правила не вимагають — лише з лівого ({p:7.3}).","ru":"Устанавливать фонари с обеих сторон Правила не требуют — только с левой ({p:7.3})."}},{"uk":"З лівого.","ru":"С левой."}],"c":1,"e":{"uk":"За {p:7.3} ліхтарі (спереду білий, ззаду червоний) встановлюють з **лівого** боку воза (саней) — з боку зустрічного та обганяючого транспорту, щоб віз було видно здалеку.","ru":"Согласно {p:7.3} фонари (спереди белый, сзади красный) устанавливают с **левой** стороны повозки (саней) — со стороны встречного и обгоняющего транспорта, чтобы повозку было видно издалека."},"ref":["7.3"]},{"id":"h7-4","t":"h7","num":"7.4","q":{"uk":"Які освітлювальні прилади повинні бути ввімкнені на гужовому возі (санях) під час руху в темну пору доби, а також в умовах недостатньої видимості?","ru":"Какие осветительные приборы должны быть включены на гужевой повозке (санях) во время движения в тёмное время суток, а также в условиях недостаточной видимости?"},"a":[{"uk":"Фари і габаритні ліхтарі.","ru":"Фары и габаритные огни.","w":{"uk":"Фари й габаритні ліхтарі — прилади механічних транспортних засобів; на гужовому возі потрібні ліхтарі білого й червоного кольору ({p:7.3}).","ru":"Фары и габаритные огни — приборы механических транспортных средств; на гужевой повозке нужны фонари белого и красного цвета ({p:7.3})."}},{"uk":"Ліхтарі: спереду – білого кольору, ззаду – червоного кольору, що встановлюються з обох боків воза (саней).","ru":"Фонари: спереди — белого цвета, сзади — красного цвета, устанавливаемые с обеих сторон повозки (саней).","w":{"uk":"Ліхтарі встановлюють лише з лівого боку воза, а не з обох ({p:7.3}).","ru":"Фонари устанавливают только с левой стороны повозки, а не с обеих ({p:7.3})."}},{"uk":"Ліхтарі: спереду – білого кольору, ззаду – червоного кольору, що встановлюються з лівого боку воза (саней).","ru":"Фонари: спереди — белого цвета, сзади — красного цвета, устанавливаемые с левой стороны повозки (саней)."}],"c":2,"e":{"uk":"Це дослівно {p:7.3}: ліхтарі спереду білого, ззаду червоного кольору, встановлені з лівого боку воза (саней).","ru":"Это дословно {p:7.3}: фонари спереди белого, сзади красного цвета, установленные с левой стороны повозки (саней)."},"ref":["7.3"]},{"id":"h7-5","t":"h7","num":"7.5","q":{"uk":"За яких умов дозволено перевозити людей гужовим транспортом?","ru":"При каких условиях разрешено перевозить людей гужевым транспортом?"},"a":[{"uk":"За наявності умови, яка виключає можливість перебування пасажирів за боковими габаритами транспортного засобу.","ru":"При наличии условия, исключающего возможность нахождения пассажиров за боковыми габаритами транспортного средства.","w":{"uk":"Неповна відповідь: пасажири не повинні виступати й за задній габарит воза ({p:7.5}).","ru":"Неполный ответ: пассажиры не должны выступать и за задний габарит повозки ({p:7.5})."}},{"uk":"За наявності умови, яка виключає можливість перебування пасажирів за заднім габаритом транспортного засобу.","ru":"При наличии условия, исключающего возможность нахождения пассажиров за задним габаритом транспортного средства.","w":{"uk":"Неповна відповідь: пасажири не повинні виступати й за бокові габарити воза ({p:7.5}).","ru":"Неполный ответ: пассажиры не должны выступать и за боковые габариты повозки ({p:7.5})."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2."}],"c":2,"e":{"uk":"{p:7.5} дозволяє перевозити людей гужовим транспортом, лише коли пасажири не можуть опинитися ні за **боковими**, ні за **заднім** габаритами воза — тому потрібні обидві умови.","ru":"{p:7.5} разрешает перевозить людей гужевым транспортом, только когда пассажиры не могут оказаться ни за **боковыми**, ни за **задним** габаритами повозки — поэтому нужны оба условия."},"ref":["7.5"]},{"id":"h7-6","t":"h7","num":"7.6","q":{"uk":"Чи дозволено переганяти стадо тварин по дорозі в темну пору доби?","ru":"Разрешено ли перегонять стадо животных по дороге в тёмное время суток?"},"a":[{"uk":"Дозволено в разі достатньої кількості погоничів, але не менш ніж трьох.","ru":"Разрешено при достаточном количестве погонщиков, но не менее трёх.","w":{"uk":"Кількість погоничів визначає безпеку вдень, але не знімає заборони переганяти тварин у темряві ({p:7.7}).","ru":"Количество погонщиков определяет безопасность днём, но не снимает запрета перегонять животных в темноте ({p:7.7})."}},{"uk":"Заборонено.","ru":"Запрещено."},{"uk":"Дозволено по дорогах без покриття.","ru":"Разрешено по дорогам без покрытия.","w":{"uk":"Заборона діє на будь-яких дорогах, незалежно від покриття ({p:7.7}).","ru":"Запрет действует на любых дорогах, независимо от покрытия ({p:7.7})."}}],"c":1,"e":{"uk":"Переганяти стадо дорогою дозволено лише у світлу пору доби ({p:7.6}), а в темряві та за недостатньої видимості це прямо заборонено (підпункт «ґ» {p:7.7}).","ru":"Перегонять стадо по дороге разрешено только в светлое время суток ({p:7.6}), а в темноте и при недостаточной видимости это прямо запрещено (подпункт «ґ» {p:7.7})."},"ref":["7.6","7.7"]},{"id":"h7-7","t":"h7","num":"7.7","q":{"uk":"Чи дозволено особам, які керують гужовим транспортом, і погоничам тварин пересуватися автомобільними дорогами державного значення?","ru":"Разрешено ли лицам, управляющим гужевым транспортом, и погонщикам животных передвигаться по автомобильным дорогам государственного значения?"},"a":[{"uk":"Дозволено тільки у світлу пору доби.","ru":"Разрешено только в светлое время суток.","w":{"uk":"Заборона щодо доріг державного значення від пори доби не залежить ({p:7.7}).","ru":"Запрет в отношении дорог государственного значения от времени суток не зависит ({p:7.7})."}},{"uk":"Заборонено (по змозі слід пересуватися автомобільними дорогами місцевого значення).","ru":"Запрещено (по возможности следует передвигаться по автомобильным дорогам местного значения)."},{"uk":"Дозволено, якщо віз обладнаний світлоповертачами.","ru":"Разрешено, если повозка оборудована световозвращателями.","w":{"uk":"Світлоповертачі — обов'язкове обладнання воза ({p:7.2}), але вони не дають права рухатися дорогами державного значення ({p:7.7}).","ru":"Световозвращатели — обязательное оборудование повозки ({p:7.2}), но они не дают права двигаться по дорогам государственного значения ({p:7.7})."}}],"c":1,"e":{"uk":"Підпункт «а» {p:7.7} забороняє їм рухатися автомобільними дорогами державного значення, якщо є можливість рухатися дорогами місцевого значення.","ru":"Подпункт «а» {p:7.7} запрещает им двигаться по автомобильным дорогам государственного значения, если есть возможность двигаться по дорогам местного значения."},"ref":["7.7"]},{"id":"h7-8","t":"h7","num":"7.8","q":{"uk":"Що заборонено погоничам тварин?","ru":"Что запрещено погонщикам животных?"},"a":[{"uk":"Вести тварин по дорогах з удосконаленим покриттям, якщо поряд є інші дороги.","ru":"Вести животных по дорогам с усовершенствованным покрытием, если рядом есть другие дороги.","w":{"uk":"Неповна відповідь: {p:7.7} містить ще три заборони для погоничів.","ru":"Неполный ответ: {p:7.7} содержит ещё три запрета для погонщиков."}},{"uk":"Переганяти тварин по дорогах у темну пору доби та в умовах недостатньої видимості.","ru":"Перегонять животных по дорогам в тёмное время суток и в условиях недостаточной видимости.","w":{"uk":"Неповна відповідь: {p:7.7} містить ще три заборони для погоничів.","ru":"Неполный ответ: {p:7.7} содержит ещё три запрета для погонщиков."}},{"uk":"Переганяти тварин через залізничні колії і дороги з удосконаленим покриттям поза спеціально відведеними місцями.","ru":"Перегонять животных через железнодорожные пути и дороги с усовершенствованным покрытием вне специально отведённых мест.","w":{"uk":"Неповна відповідь: {p:7.7} містить ще три заборони для погоничів.","ru":"Неполный ответ: {p:7.7} содержит ещё три запрета для погонщиков."}},{"uk":"Залишати на смузі відведення дороги тварин без нагляду та пасти їх.","ru":"Оставлять на полосе отвода дороги животных без присмотра и выпасать их.","w":{"uk":"Неповна відповідь: {p:7.7} містить ще три заборони для погоничів.","ru":"Неполный ответ: {p:7.7} содержит ещё три запрета для погонщиков."}},{"uk":"Відповіді 1, 2, 3 і 4.","ru":"Ответы 1, 2, 3 и 4."}],"c":4,"e":{"uk":"Усі чотири заборони прямо перелічено в {p:7.7} (підпункти «в», «г», «ґ», «д»), тому правильна відповідь — усі варіанти разом.","ru":"Все четыре запрета прямо перечислены в {p:7.7} (подпункты «в», «г», «ґ», «д»), поэтому верный ответ — все варианты вместе."},"ref":["7.7"]},{"id":"h8.1-1","t":"h8.1","num":"8.1.1","q":{"uk":"Водіям яких транспортних засобів дозволено рух у даній ситуації?","ru":"Водителям каких транспортных средств разрешено движение в данной ситуации?"},"a":[{"uk":"Синього – ліворуч, жовтого – прямо, червоного – праворуч.","ru":"Синего — налево, жёлтого — прямо, красного — направо.","w":{"uk":"Жовтий (прямо) і червоний (праворуч) автомобілі рухаються на червоний сигнал, а стрілки праворуч у світлофора немає — їм рух заборонено.","ru":"Жёлтый (прямо) и красный (направо) автомобили движутся на красный сигнал, а стрелки направо у светофора нет — им движение запрещено."}},{"uk":"Синього – ліворуч або розворот.","ru":"Синего — налево или разворот."},{"uk":"Синього – ліворуч, жовтого – прямо.","ru":"Синего — налево, жёлтого — прямо.","w":{"uk":"Жовтому автомобілю, що їде прямо, червоний сигнал забороняє рух, а синьому, крім повороту ліворуч, дозволено й розворот.","ru":"Жёлтому автомобилю, едущему прямо, красный сигнал запрещает движение, а синему, кроме поворота налево, разрешён и разворот."}},{"uk":"Синього – ліворуч, червоного – праворуч.","ru":"Синего — налево, красного — направо.","w":{"uk":"Повороту праворуч на червоний сигнал жодна стрілка тут не дозволяє, тож червоний автомобіль повинен стояти.","ru":"Поворот направо на красный сигнал здесь никакая стрелка не разрешает, поэтому красный автомобиль должен стоять."}}],"c":1,"e":{"uk":"Основний сигнал світлофора червоний, а в додатковій секції горить зелена стрілка ліворуч: рух дозволено лише в напрямку стрілки, причому стрілка ліворуч дозволяє й розворот ({p:8.7}). Тож рушити може тільки синій — ліворуч або на розворот, пропустивши транспортні засоби з інших напрямків ({p:16.9}).","ru":"Основной сигнал светофора красный, а в дополнительной секции горит зелёная стрелка налево: движение разрешено только в направлении стрелки, причём стрелка налево разрешает и разворот ({p:8.7}). Поэтому тронуться может только синий — налево или на разворот, пропустив транспортные средства с других направлений ({p:16.9})."},"ref":["8.7","16.9"],"pic":["img/hsc/8.1-1-1.jpg"]},{"id":"h8.1-2","t":"h8.1","num":"8.1.2","q":{"uk":"Ви правильно виконали поворот праворуч у цій ситуації, якщо:","ru":"Вы правильно выполнили поворот направо в этой ситуации, если:"},"a":[{"uk":"Зупинилися перед стоп-лінією і, дочекавшись дозвільного сигналу регулювальника, продовжили рух.","ru":"Остановились перед стоп-линией и, дождавшись разрешающего сигнала регулировщика, продолжили движение.","w":{"uk":"Показаний сигнал уже дозволяє поворот праворуч, тож чекати іншого сигналу не потрібно.","ru":"Показанный сигнал уже разрешает поворот направо, поэтому ждать другого сигнала не нужно."}},{"uk":"Повернули на зображений на малюнку сигнал регулювальника, давши дорогу пішоходам.","ru":"Повернули на изображённый на рисунке сигнал регулировщика, уступив дорогу пешеходам."},{"uk":"Повернули на зображений на малюнку сигнал регулювальника, не даючи дороги пішоходам.","ru":"Повернули на изображённый на рисунке сигнал регулировщика, не уступая дорогу пешеходам.","w":{"uk":"Пішоходам за цього сигналу дозволено переходити проїзну частину, на яку Ви повертаєте, і за {p:16.2} Ви зобов'язані дати їм дорогу.","ru":"Пешеходам при этом сигнале разрешено переходить проезжую часть, на которую Вы поворачиваете, и по {p:16.2} Вы обязаны уступить им дорогу."}}],"c":1,"e":{"uk":"Регулювальник стоїть до Вас боком з опущеними руками — з цього боку нерейковим транспортним засобам дозволено рух прямо і праворуч, а пішоходам — перехід за спиною й перед грудьми регулювальника ({p:8.8}). Тому повертати можна одразу (сигнал регулювальника має перевагу над знаком {s:2.2} — {p:8.3}), але слід дати дорогу пішоходам на проїзній частині, на яку Ви повертаєте ({p:16.2}).","ru":"Регулировщик стоит к Вам боком с опущенными руками — с этой стороны нерельсовым транспортным средствам разрешено движение прямо и направо, а пешеходам — переход за спиной и перед грудью регулировщика ({p:8.8}). Поэтому поворачивать можно сразу (сигнал регулировщика имеет преимущество перед знаком {s:2.2} — {p:8.3}), но следует уступить дорогу пешеходам на проезжей части, на которую Вы поворачиваете ({p:16.2})."},"ref":["8.8","8.3","16.2"],"pic":["img/hsc/8.1-2-1.jpg"]},{"id":"h8.1-3","t":"h8.1","num":"8.1.3","q":{"uk":"Чи дозволено Вам повернути праворуч у даній ситуації?","ru":"Разрешено ли Вам повернуть направо в данной ситуации?"},"a":[{"uk":"Заборонено.","ru":"Запрещено."},{"uk":"Дозволено, даючи дорогу пішоходам.","ru":"Разрешено, уступая дорогу пешеходам.","w":{"uk":"Поворот заборонений, бо Ви з боку грудей регулювальника; пропуск пішоходів тут ні до чого.","ru":"Поворот запрещён, так как Вы со стороны груди регулировщика; пропуск пешеходов здесь ни при чём."}}],"c":0,"e":{"uk":"Регулювальник повернутий до Вас грудьми з руками, витягнутими в сторони, — з боку грудей і спини рух усіх транспортних засобів заборонено ({p:8.8}). Зелений сигнал світлофора не діє, бо сигнали регулювальника мають перевагу ({p:8.3}).","ru":"Регулировщик повёрнут к Вам грудью с вытянутыми в стороны руками — со стороны груди и спины движение всех транспортных средств запрещено ({p:8.8}). Зелёный сигнал светофора не действует, так как сигналы регулировщика имеют преимущество ({p:8.3})."},"ref":["8.8","8.3"],"pic":["img/hsc/8.1-3-1.jpg"]},{"id":"h8.1-4","t":"h8.1","num":"8.1.4","q":{"uk":"Кому дозволено рух у даній ситуації?","ru":"Кому разрешено движение в данной ситуации?"},"a":[{"uk":"Тільки трамваю.","ru":"Только трамваю.","w":{"uk":"Автомобілю, що стоїть збоку від регулювальника, теж дозволено рух — прямо і праворуч.","ru":"Автомобилю, стоящему сбоку от регулировщика, тоже разрешено движение — прямо и направо."}},{"uk":"Тільки автомобілю.","ru":"Только автомобилю.","w":{"uk":"Трамваю, що стоїть збоку від регулювальника, теж дозволено рух — прямо.","ru":"Трамваю, стоящему сбоку от регулировщика, тоже разрешено движение — прямо."}},{"uk":"Обом транспортним засобам.","ru":"Обоим транспортным средствам."}],"c":2,"e":{"uk":"Регулювальник стоїть до трамвая й автомобіля боком з опущеними руками: з цього боку трамваю дозволено рух прямо, а нерейковим транспортним засобам — прямо і праворуч ({p:8.8}). Отже, рушити можуть обидва.","ru":"Регулировщик стоит к трамваю и автомобилю боком с опущенными руками: с этой стороны трамваю разрешено движение прямо, а нерельсовым транспортным средствам — прямо и направо ({p:8.8}). Значит, тронуться могут оба."},"ref":["8.8"],"pic":["img/hsc/8.1-4-1.jpg"]},{"id":"h8.1-5","t":"h8.1","num":"8.1.5","q":{"uk":"Чи дозволено Вам рух у даній ситуації?","ru":"Разрешено ли Вам движение в данной ситуации?"},"a":[{"uk":"Заборонено.","ru":"Запрещено.","w":{"uk":"Збоку від регулювальника рух дозволено, а червоний сигнал світлофора не діє, бо сигнали регулювальника мають перевагу ({p:8.3}).","ru":"Сбоку от регулировщика движение разрешено, а красный сигнал светофора не действует, так как сигналы регулировщика имеют преимущество ({p:8.3})."}},{"uk":"Дозволено, але треба дати дорогу трамваю.","ru":"Разрешено, но нужно уступить дорогу трамваю.","w":{"uk":"Трамвай, що повертає, за цього жесту рушати не може (йому дозволено лише прямо), тож давати йому дорогу не потрібно.","ru":"Трамвай, который поворачивает, при этом жесте трогаться не может (ему разрешено только прямо), поэтому уступать ему дорогу не нужно."}},{"uk":"Дозволено тільки Вам.","ru":"Разрешено только Вам."}],"c":2,"e":{"uk":"Регулювальник стоїть боком до Вас і до трамвая, що їде поруч, руки витягнуті в сторони: з цього боку нерейковим транспортним засобам дозволено рух прямо і праворуч, а трамваю — **тільки прямо** ({p:8.8}). Трамвай показує поворот, тож йому рух заборонено, а Вам дозволено, і поступатися трамваю не потрібно.","ru":"Регулировщик стоит боком к Вам и к трамваю, едущему рядом, руки вытянуты в стороны: с этой стороны нерельсовым транспортным средствам разрешено движение прямо и направо, а трамваю — **только прямо** ({p:8.8}). Трамвай показывает поворот, поэтому ему движение запрещено, а Вам разрешено, и уступать трамваю не нужно."},"ref":["8.8","8.3"],"pic":["img/hsc/8.1-5-1.jpg"]},{"id":"h8.1-6","t":"h8.1","num":"8.1.6","q":{"uk":"Чи повинен водій синього автомобіля, повертаючи праворуч, дати дорогу пішоходам?","ru":"Должен ли водитель синего автомобиля, поворачивая направо, уступить дорогу пешеходам?"},"a":[{"uk":"Повинен.","ru":"Должен."},{"uk":"Не повинен.","ru":"Не должен.","w":{"uk":"Обов'язок дати дорогу пішоходам на проїзній частині, на яку повертають, діє і на регульованих перехрестях ({p:16.2}), а пішоходам тут рух дозволено.","ru":"Обязанность уступить дорогу пешеходам на проезжей части, на которую поворачивают, действует и на регулируемых перекрёстках ({p:16.2}), а пешеходам здесь движение разрешено."}}],"c":0,"e":{"uk":"Регулювальник стоїть до синього автомобіля боком (права рука зігнута перед грудьми): йому дозволено рух прямо і праворуч, а пішоходам — перехід перед грудьми й за спиною регулювальника ({p:8.8}). Повертаючи праворуч, водій повинен дати дорогу пішоходам, які переходять проїзну частину, на яку він повертає ({p:16.2}).","ru":"Регулировщик стоит к синему автомобилю боком (правая рука согнута перед грудью): ему разрешено движение прямо и направо, а пешеходам — переход перед грудью и за спиной регулировщика ({p:8.8}). Поворачивая направо, водитель должен уступить дорогу пешеходам, переходящим проезжую часть, на которую он поворачивает ({p:16.2})."},"ref":["16.2","8.8"],"pic":["img/hsc/8.1-6-1.jpg"]},{"id":"h8.1-7","t":"h8.1","num":"8.1.7","q":{"uk":"Чи дозволено Вам рух у даній ситуації?","ru":"Разрешено ли Вам движение в данной ситуации?"},"a":[{"uk":"Дозволено праворуч.","ru":"Разрешено направо.","w":{"uk":"З боку грудей праворуч можна рухатися лише тоді, коли регулювальник витягнув праву руку вперед; за цього жесту рух заборонено.","ru":"Со стороны груди направо можно двигаться только когда регулировщик вытянул правую руку вперёд; при этом жесте движение запрещено."}},{"uk":"Дозволено прямо і праворуч.","ru":"Разрешено прямо и направо.","w":{"uk":"Прямо і праворуч можна рухатися лише збоку від регулювальника, а Ви перебуваєте з боку його грудей.","ru":"Прямо и направо можно двигаться только сбоку от регулировщика, а Вы находитесь со стороны его груди."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":2,"e":{"uk":"Регулювальник стоїть до Вас грудьми з руками, витягнутими в сторони: з боку грудей рух усіх транспортних засобів заборонено ({p:8.8}). Сигнал світлофора тут не враховується, бо сигнали регулювальника мають перевагу ({p:8.3}).","ru":"Регулировщик стоит к Вам грудью с вытянутыми в стороны руками: со стороны груди движение всех транспортных средств запрещено ({p:8.8}). Сигнал светофора здесь не учитывается, так как сигналы регулировщика имеют преимущество ({p:8.3})."},"ref":["8.8","8.3"],"pic":["img/hsc/8.1-7-1.jpg"]},{"id":"h8.1-8","t":"h8.1","num":"8.1.8","q":{"uk":"Чи дозволено Вам повернути ліворуч у даній ситуації?","ru":"Разрешено ли Вам повернуть налево в данной ситуации?"},"a":[{"uk":"Заборонено.","ru":"Запрещено."},{"uk":"Дозволено, давши дорогу зустрічному автомобілю.","ru":"Разрешено, уступив дорогу встречному автомобилю.","w":{"uk":"Поворот ліворуч за цього жесту регулювальника заборонений взагалі, незалежно від зустрічного автомобіля.","ru":"Поворот налево при этом жесте регулировщика запрещён вообще, независимо от встречного автомобиля."}},{"uk":"Дозволено, не даючи дорогу зустрічному автомобілю.","ru":"Разрешено, не уступая дорогу встречному автомобилю.","w":{"uk":"Поворот ліворуч заборонений; орієнтуватися на стрілку світлофора не можна, коли перехрестя регулює регулювальник.","ru":"Поворот налево запрещён; ориентироваться на стрелку светофора нельзя, когда перекрёсток регулирует регулировщик."}}],"c":0,"e":{"uk":"Регулювальник стоїть до Вас правим боком, права рука зігнута перед грудьми — з цього боку нерейковим транспортним засобам дозволено рух лише прямо і праворуч ({p:8.8}). Зелена стрілка ліворуч у додатковій секції не діє, бо сигнали регулювальника мають перевагу над сигналами світлофора ({p:8.3}).","ru":"Регулировщик стоит к Вам правым боком, правая рука согнута перед грудью — с этой стороны нерельсовым транспортным средствам разрешено движение только прямо и направо ({p:8.8}). Зелёная стрелка налево в дополнительной секции не действует, так как сигналы регулировщика имеют преимущество перед сигналами светофора ({p:8.3})."},"ref":["8.8","8.3"],"pic":["img/hsc/8.1-8-1.jpg"]},{"id":"h8.1-9","t":"h8.1","num":"8.1.9","q":{"uk":"У яких напрямках дозволено рух у даній ситуації?","ru":"В каких направлениях разрешено движение в данной ситуации?"},"a":[{"uk":"Прямо.","ru":"Прямо.","w":{"uk":"Крім руху прямо, збоку від регулювальника дозволено й поворот праворуч.","ru":"Кроме движения прямо, сбоку от регулировщика разрешён и поворот направо."}},{"uk":"Прямо або ліворуч.","ru":"Прямо или налево.","w":{"uk":"Поворот ліворуч за цього жесту заборонений — дозволено лише прямо і праворуч.","ru":"Поворот налево при этом жесте запрещён — разрешено только прямо и направо."}},{"uk":"Прямо або праворуч.","ru":"Прямо или направо."},{"uk":"Праворуч.","ru":"Направо.","w":{"uk":"Крім повороту праворуч, збоку від регулювальника дозволено й рух прямо.","ru":"Кроме поворота направо, сбоку от регулировщика разрешено и движение прямо."}}],"c":2,"e":{"uk":"Регулювальник стоїть до Вас боком із руками, витягнутими в сторони: з лівого і правого боку нерейковим транспортним засобам дозволено рух прямо і праворуч ({p:8.8}). Червоний сигнал світлофора до уваги не береться — сигнали регулювальника мають перевагу ({p:8.3}).","ru":"Регулировщик стоит к Вам боком с вытянутыми в стороны руками: с левой и правой стороны нерельсовым транспортным средствам разрешено движение прямо и направо ({p:8.8}). Красный сигнал светофора во внимание не принимается — сигналы регулировщика имеют преимущество ({p:8.3})."},"ref":["8.8","8.3"],"pic":["img/hsc/8.1-9-1.jpg"]},{"id":"h8.1-10","t":"h8.1","num":"8.1.10","q":{"uk":"Чи дозволено Вам повернути праворуч у даній ситуації?","ru":"Разрешено ли Вам повернуть направо в данной ситуации?"},"a":[{"uk":"Заборонено.","ru":"Запрещено.","w":{"uk":"Збоку від регулювальника поворот праворуч дозволено; червоний сигнал світлофора не діє, бо сигнали регулювальника мають перевагу ({p:8.3}).","ru":"Сбоку от регулировщика поворот направо разрешён; красный сигнал светофора не действует, так как сигналы регулировщика имеют преимущество ({p:8.3})."}},{"uk":"Дозволено, не даючи дорогу пішоходам.","ru":"Разрешено, не уступая дорогу пешеходам.","w":{"uk":"Пішоходам на проїзній частині, на яку Ви повертаєте, рух дозволено, і за {p:16.2} їм треба дати дорогу.","ru":"Пешеходам на проезжей части, на которую Вы поворачиваете, движение разрешено, и по {p:16.2} им нужно уступить дорогу."}},{"uk":"Дозволено, даючи дорогу пішоходам.","ru":"Разрешено, уступая дорогу пешеходам."}],"c":2,"e":{"uk":"Регулювальник стоїть до Вас боком з руками, витягнутими в сторони: Вам дозволено рух прямо і праворуч, а пішоходам — перехід перед грудьми й за спиною регулювальника ({p:8.8}), тобто й через проїзну частину, на яку Ви повертаєте. Тому, повертаючи праворуч, треба дати їм дорогу ({p:16.2}).","ru":"Регулировщик стоит к Вам боком с вытянутыми в стороны руками: Вам разрешено движение прямо и направо, а пешеходам — переход перед грудью и за спиной регулировщика ({p:8.8}), то есть и через проезжую часть, на которую Вы поворачиваете. Поэтому, поворачивая направо, нужно уступить им дорогу ({p:16.2})."},"ref":["8.8","16.2"],"pic":["img/hsc/8.1-10-1.jpg"]},{"id":"h8.1-11","t":"h8.1","num":"8.1.11","q":{"uk":"Чи дозволено Вам рух у напрямку, вказаному стрілкою в додатковій секції світлофора?","ru":"Разрешено ли Вам движение в направлении, указанном стрелкой в дополнительной секции светофора?"},"a":[{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"Стрілка світлофора не діє, коли сигнали подає регулювальник, а його жест не дозволяє поворот ліворуч.","ru":"Стрелка светофора не действует, когда сигналы подаёт регулировщик, а его жест не разрешает поворот налево."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":1,"e":{"uk":"Стрілка в додатковій секції показує ліворуч, але перехрестя регулює регулювальник, а його сигнали мають перевагу над сигналами світлофора ({p:8.3}). Він стоїть до Вас правим боком із зігнутою перед грудьми правою рукою — з цього боку дозволено лише прямо і праворуч ({p:8.8}), тож поворот ліворуч заборонений.","ru":"Стрелка в дополнительной секции показывает налево, но перекрёсток регулирует регулировщик, а его сигналы имеют преимущество перед сигналами светофора ({p:8.3}). Он стоит к Вам правым боком с согнутой перед грудью правой рукой — с этой стороны разрешено только прямо и направо ({p:8.8}), поэтому поворот налево запрещён."},"ref":["8.3","8.8"],"pic":["img/hsc/8.1-11-1.jpg"]},{"id":"h8.1-12","t":"h8.1","num":"8.1.12","q":{"uk":"Звуковий сигнал, який додатково увімкнений до сигналу світлофора, що регулює рух пішоходів:","ru":"Звуковой сигнал, дополнительно включённый к сигналу светофора, регулирующего движение пешеходов:"},"a":[{"uk":"Призначений для пішоходів з порушенням зору – забороняє їм рух через дорогу.","ru":"Предназначен для пешеходов с нарушением зрения — запрещает им движение через дорогу.","w":{"uk":"Звуковий сигнал пішохідного світлофора навпаки дозволяє рух, а не забороняє його.","ru":"Звуковой сигнал пешеходного светофора, наоборот, разрешает движение, а не запрещает его."}},{"uk":"Призначений для пішоходів з порушенням зору – дозволяє їм рух.","ru":"Предназначен для пешеходов с нарушением зрения — разрешает им движение."},{"uk":"Призначений для привернення уваги пішоходів.","ru":"Предназначен для привлечения внимания пешеходов.","w":{"uk":"Сигнал призначений саме для пішоходів з порушенням зору і дозволяє їм рух, а не просто привертає увагу.","ru":"Сигнал предназначен именно для пешеходов с нарушением зрения и разрешает им движение, а не просто привлекает внимание."}}],"c":1,"e":{"uk":"За {p:8.7} для пішоходів з порушенням зору може бути ввімкнений звуковий сигнал, який **дозволяє** рух пішоходів.","ru":"По {p:8.7} для пешеходов с нарушением зрения может быть включён звуковой сигнал, который **разрешает** движение пешеходов."},"ref":["8.7"],"pic":["img/hsc/8.1-12-1.jpg"]},{"id":"h8.1-13","t":"h8.1","num":"8.1.13","q":{"uk":"На яких учасників дорожнього руху поширює свою дію даний світлофор?","ru":"На каких участников дорожного движения распространяет своё действие данный светофор?"},"a":[{"uk":"На пішоходів.","ru":"На пешеходов."},{"uk":"На транспортні засоби.","ru":"На транспортные средства.","w":{"uk":"Світлофор із силуетом пішохода транспортними засобами не керує.","ru":"Светофор с силуэтом пешехода транспортными средствами не управляет."}},{"uk":"На транспортні засоби та пішоходів.","ru":"На транспортные средства и пешеходов.","w":{"uk":"Дія світлофора з силуетом пішохода поширюється тільки на пішоходів.","ru":"Действие светофора с силуэтом пешехода распространяется только на пешеходов."}}],"c":0,"e":{"uk":"Сигнали цього світлофора мають вигляд силуету пішохода, а такий світлофор поширює свою дію тільки на пішоходів ({p:8.7}).","ru":"Сигналы этого светофора имеют вид силуэта пешехода, а такой светофор распространяет своё действие только на пешеходов ({p:8.7})."},"ref":["8.7"],"pic":["img/hsc/8.1-13-1.jpg"]},{"id":"h8.1-14","t":"h8.1","num":"8.1.14","q":{"uk":"Який світлофор застосовується для регулювання руху через залізничні переїзди?","ru":"Какой светофор применяется для регулирования движения через железнодорожные переезды?"},"a":[{"uk":"Світлофор 1.","ru":"Светофор 1.","w":{"uk":"Світлофор 1 застосовують на переїздах, але так само і світлофор 2 з біло-місячним сигналом.","ru":"Светофор 1 применяется на переездах, но точно так же и светофор 2 с бело-лунным сигналом."}},{"uk":"Світлофор 2.","ru":"Светофор 2.","w":{"uk":"Світлофор 2 застосовують на переїздах, але так само і світлофор 1 з двома червоними сигналами.","ru":"Светофор 2 применяется на переездах, но точно так же и светофор 1 с двумя красными сигналами."}},{"uk":"Світлофор 3.","ru":"Светофор 3.","w":{"uk":"Світлофор 3 із чотирма біло-місячними сигналами у вигляді літери «Т» — трамвайний, він регулює рух трамваїв.","ru":"Светофор 3 с четырьмя бело-лунными сигналами в виде буквы «Т» — трамвайный, он регулирует движение трамваев."}},{"uk":"Світлофори 1 і 2.","ru":"Светофоры 1 и 2."},{"uk":"Світлофори 1, 2 і 3.","ru":"Светофоры 1, 2 и 3.","w":{"uk":"Світлофор 3 — трамвайний, для залізничних переїздів його не застосовують.","ru":"Светофор 3 — трамвайный, для железнодорожных переездов он не применяется."}}],"c":3,"e":{"uk":"На залізничних переїздах застосовують світлофори з двома червоними сигналами (світлофор 1) або з одним біло-місячним і двома червоними (світлофор 2) — {p:8.7}.","ru":"На железнодорожных переездах применяются светофоры с двумя красными сигналами (светофор 1) или с одним бело-лунным и двумя красными (светофор 2) — {p:8.7}."},"ref":["8.7"],"pic":["img/hsc/8.1-14-1.jpg"]},{"id":"h8.1-15","t":"h8.1","num":"8.1.15","q":{"uk":"На якому світлофорі горить сигнал, що дозволяє трамваю повернути праворуч?","ru":"На каком светофоре горит сигнал, разрешающий трамваю повернуть направо?"},"a":[{"uk":"На третьому і четвертому.","ru":"На третьем и четвёртом.","w":{"uk":"На третьому світлофорі горять лише середній і нижній сигнали (тільки прямо), а на четвертому правий верхній вимкнений (прямо і ліворуч).","ru":"На третьем светофоре горят только средний и нижний сигналы (только прямо), а на четвёртом правый верхний выключен (прямо и налево)."}},{"uk":"Тільки на четвертому.","ru":"Только на четвёртом.","w":{"uk":"На четвертому світлофорі правий верхній сигнал вимкнений — він дозволяє рух прямо і ліворуч, а не праворуч.","ru":"На четвёртом светофоре правый верхний сигнал выключен — он разрешает движение прямо и налево, а не направо."}},{"uk":"На другому світлофорі.","ru":"На втором светофоре."},{"uk":"На другому і четвертому.","ru":"На втором и четвёртом.","w":{"uk":"Четвертий світлофор дозволяє прямо і ліворуч, а не праворуч.","ru":"Четвёртый светофор разрешает прямо и налево, а не направо."}},{"uk":"На першому і другому.","ru":"На первом и втором.","w":{"uk":"На першому світлофорі горять тільки три верхні сигнали без нижнього — це заборона руху.","ru":"На первом светофоре горят только три верхних сигнала без нижнего — это запрет движения."}}],"c":2,"e":{"uk":"Трамвайний світлофор дозволяє рух лише тоді, коли горить нижній сигнал разом з одним чи кількома верхніми; правий верхній дозволяє рух праворуч ({p:8.7}). Нижній і правий верхній сигнали горять тільки на другому світлофорі (він дозволяє прямо і праворуч).","ru":"Трамвайный светофор разрешает движение только тогда, когда горит нижний сигнал вместе с одним или несколькими верхними; правый верхний разрешает движение направо ({p:8.7}). Нижний и правый верхний сигналы горят только на втором светофоре (он разрешает прямо и направо)."},"ref":["8.7"],"pic":["img/hsc/8.1-15-1.jpg"]},{"id":"h8.1-16","t":"h8.1","num":"8.1.16","q":{"uk":"У цій ситуації рух дозволено:","ru":"В этой ситуации движение разрешено:"},"a":[{"uk":"Трамваю й автомобілю.","ru":"Трамваю и автомобилю.","w":{"uk":"Трамваю рух заборонено: без нижнього сигналу три верхні сигнали трамвайного світлофора означають заборону, а мотоциклу зелений дозволяє рух.","ru":"Трамваю движение запрещено: без нижнего сигнала три верхних сигнала трамвайного светофора означают запрет, а мотоциклу зелёный разрешает движение."}},{"uk":"Трамваю і мотоциклу.","ru":"Трамваю и мотоциклу.","w":{"uk":"Трамвай повинен стояти, бо на його світлофорі горять тільки три верхні сигнали; автомобілю ж зелений дозволяє рух.","ru":"Трамвай должен стоять, так как на его светофоре горят только три верхних сигнала; автомобилю же зелёный разрешает движение."}},{"uk":"Автомобілю і мотоциклу.","ru":"Автомобилю и мотоциклу."},{"uk":"Тільки трамваю.","ru":"Только трамваю.","w":{"uk":"Навпаки, трамваю рух заборонено, а автомобіль і мотоцикл можуть рухатися на зелений сигнал.","ru":"Наоборот, трамваю движение запрещено, а автомобиль и мотоцикл могут двигаться на зелёный сигнал."}},{"uk":"Усім переліченим вище транспортним засобам.","ru":"Всем перечисленным выше транспортным средствам.","w":{"uk":"Трамваю рух заборонено, бо нижній сигнал трамвайного світлофора не горить.","ru":"Трамваю движение запрещено, так как нижний сигнал трамвайного светофора не горит."}}],"c":2,"e":{"uk":"На трамвайному світлофорі горять тільки три верхні сигнали, а нижній вимкнений — трамваю рух заборонено ({p:8.7}). Автомобіль і мотоцикл керуються звичайним світлофором, на якому горить зелений, тож їм рух дозволено.","ru":"На трамвайном светофоре горят только три верхних сигнала, а нижний выключен — трамваю движение запрещено ({p:8.7}). Автомобиль и мотоцикл руководствуются обычным светофором, на котором горит зелёный, поэтому им движение разрешено."},"ref":["8.7"],"pic":["img/hsc/8.1-16-1.jpg"]},{"id":"h8.1-17","t":"h8.1","num":"8.1.17","q":{"uk":"Чи дозволено рух трамвая в цій ситуації?","ru":"Разрешено ли движение трамвая в этой ситуации?"},"a":[{"uk":"Заборонено.","ru":"Запрещено.","w":{"uk":"Трамваї керуються своїм світлофором, а на ньому разом із верхніми горить нижній сигнал, тобто рух дозволено.","ru":"Трамваи руководствуются своим светофором, а на нём вместе с верхними горит нижний сигнал, то есть движение разрешено."}},{"uk":"Дозволено прямо, праворуч або ліворуч.","ru":"Разрешено прямо, направо или налево.","w":{"uk":"Правий верхній сигнал трамвайного світлофора вимкнений, тож праворуч рух не дозволено.","ru":"Правый верхний сигнал трамвайного светофора выключен, поэтому направо движение не разрешено."}},{"uk":"Дозволено прямо або ліворуч.","ru":"Разрешено прямо или налево."}],"c":2,"e":{"uk":"На трамвайному світлофорі горять нижній сигнал, а також лівий і середній верхні — це дозвіл руху ліворуч і прямо; правий верхній вимкнений ({p:8.7}). Червоний сигнал звичайного світлофора для трамвая значення не має, поки працює трамвайний.","ru":"На трамвайном светофоре горят нижний сигнал, а также левый и средний верхние — это разрешение движения налево и прямо; правый верхний выключен ({p:8.7}). Красный сигнал обычного светофора для трамвая значения не имеет, пока работает трамвайный."},"ref":["8.7"],"pic":["img/hsc/8.1-17-1.jpg"]},{"id":"h8.1-18","t":"h8.1","num":"8.1.18","q":{"uk":"Яким автомобілям дозволено рух у даній ситуації?","ru":"Каким автомобилям разрешено движение в данной ситуации?"},"a":[{"uk":"Білому і синьому.","ru":"Белому и синему.","w":{"uk":"Білий автомобіль стоїть за спиною регулювальника — йому рух заборонено.","ru":"Белый автомобиль стоит за спиной регулировщика — ему движение запрещено."}},{"uk":"Синьому і сірому.","ru":"Синему и серому.","w":{"uk":"Сірий автомобіль перебуває з боку грудей регулювальника — йому рух заборонено.","ru":"Серый автомобиль находится со стороны груди регулировщика — ему движение запрещено."}},{"uk":"Жовтому і синьому.","ru":"Жёлтому и синему."},{"uk":"Синьому і білому.","ru":"Синему и белому.","w":{"uk":"Білий автомобіль за спиною регулювальника повинен стояти; рух дозволено жовтому і синьому.","ru":"Белый автомобиль за спиной регулировщика должен стоять; движение разрешено жёлтому и синему."}}],"c":2,"e":{"uk":"Регулювальник з опущеними руками стоїть грудьми до сірого і спиною до білого автомобіля — з цих боків рух заборонено ({p:8.8}). Жовтий і синій під'їжджають з лівого і правого боку регулювальника, звідки нерейковим транспортним засобам дозволено рух прямо і праворуч.","ru":"Регулировщик с опущенными руками стоит грудью к серому и спиной к белому автомобилю — с этих сторон движение запрещено ({p:8.8}). Жёлтый и синий подъезжают с левой и правой стороны регулировщика, откуда нерельсовым транспортным средствам разрешено движение прямо и направо."},"ref":["8.8"],"pic":["img/hsc/8.1-18-1.jpg"]},{"id":"h8.1-19","t":"h8.1","num":"8.1.19","q":{"uk":"У яких напрямках Вам дозволено рух?","ru":"В каких направлениях Вам разрешено движение?"},"a":[{"uk":"Праворуч.","ru":"Направо.","w":{"uk":"Крім повороту праворуч, цей жест дозволяє й рух прямо.","ru":"Кроме поворота направо, этот жест разрешает и движение прямо."}},{"uk":"Прямо.","ru":"Прямо.","w":{"uk":"Крім руху прямо, цей жест дозволяє й поворот праворуч.","ru":"Кроме движения прямо, этот жест разрешает и поворот направо."}},{"uk":"Ліворуч.","ru":"Налево.","w":{"uk":"Поворот ліворуч за цього жесту заборонений, хоч би куди вказувала табличка напрямку головної дороги.","ru":"Поворот налево при этом жесте запрещён, куда бы ни указывала табличка направления главной дороги."}},{"uk":"Прямо або праворуч.","ru":"Прямо или направо."},{"uk":"Ліворуч або праворуч.","ru":"Налево или направо.","w":{"uk":"Ліворуч за цього жесту повертати не можна — дозволено тільки прямо і праворуч.","ru":"Налево при этом жесте поворачивать нельзя — разрешено только прямо и направо."}}],"c":3,"e":{"uk":"Регулювальник стоїть до Вас боком із руками, витягнутими в сторони, — з лівого і правого боку нерейковим транспортним засобам дозволено рух прямо і праворуч ({p:8.8}). Знаки пріоритету тут не діють, бо перехрестя регульоване ({p:16.1}), а сигнали регулювальника мають перевагу над знаками ({p:8.3}).","ru":"Регулировщик стоит к Вам боком с вытянутыми в стороны руками — с левой и правой стороны нерельсовым транспортным средствам разрешено движение прямо и направо ({p:8.8}). Знаки приоритета здесь не действуют, так как перекрёсток регулируемый ({p:16.1}), а сигналы регулировщика имеют преимущество перед знаками ({p:8.3})."},"ref":["8.8","8.3","16.1"],"pic":["img/hsc/8.1-19-1.jpg"]},{"id":"h8.1-20","t":"h8.1","num":"8.1.20","q":{"uk":"Яким транспортним засобам дозволено рух на даний жест регулювальника?","ru":"Каким транспортным средствам разрешено движение при данном жесте регулировщика?"},"a":[{"uk":"Усім транспортним засобам.","ru":"Всем транспортным средствам.","w":{"uk":"Трамваю з лівого боку регулювальника дозволено лише поворот ліворуч, а він рухається прямо.","ru":"Трамваю с левой стороны регулировщика разрешён только поворот налево, а он движется прямо."}},{"uk":"Трамваю і білому автомобілю.","ru":"Трамваю и белому автомобилю.","w":{"uk":"Трамваю рух прямо за цього жесту заборонений, а синьому автомобілю, навпаки, дозволений.","ru":"Трамваю движение прямо при этом жесте запрещено, а синему автомобилю, наоборот, разрешено."}},{"uk":"Трамваю і синьому автомобілю.","ru":"Трамваю и синему автомобилю.","w":{"uk":"Трамвай прямо рухатися не може, а білому автомобілю з лівого боку регулювальника рух дозволено.","ru":"Трамвай прямо двигаться не может, а белому автомобилю с левой стороны регулировщика движение разрешено."}},{"uk":"Білому і синьому автомобілям.","ru":"Белому и синему автомобилям."}],"c":3,"e":{"uk":"Регулювальник витягнув праву руку вперед, і трамвай та обидва автомобілі опинилися з його лівого боку: звідси нерейковим транспортним засобам дозволено рух у всіх напрямках, а трамваю — **тільки ліворуч** ({p:8.8}). Трамвай рухається прямо, тож йому рух заборонено, а білий і синій автомобілі можуть їхати (сигнали світлофора не діють — {p:8.3}).","ru":"Регулировщик вытянул правую руку вперёд, и трамвай и оба автомобиля оказались с его левой стороны: отсюда нерельсовым транспортным средствам разрешено движение во всех направлениях, а трамваю — **только налево** ({p:8.8}). Трамвай движется прямо, поэтому ему движение запрещено, а белый и синий автомобили могут ехать (сигналы светофора не действуют — {p:8.3})."},"ref":["8.8","8.3"],"pic":["img/hsc/8.1-20-1.jpg"]},{"id":"h8.1-21","t":"h8.1","num":"8.1.21","q":{"uk":"У якому напрямку Вам дозволено рух в показаній ситуації?","ru":"В каком направлении Вам разрешено движение в показанной ситуации?"},"a":[{"uk":"Прямо.","ru":"Прямо.","w":{"uk":"Зелений сигнал без стрілок не обмежує напрямок руху лише прямо.","ru":"Зелёный сигнал без стрелок не ограничивает направление движения только прямо."}},{"uk":"Прямо, праворуч, ліворуч або розворот.","ru":"Прямо, направо, налево или разворот."},{"uk":"Прямо, праворуч і ліворуч.","ru":"Прямо, направо и налево.","w":{"uk":"Зелений сигнал дозволяє й розворот, якщо його не заборонено знаками чи розміткою.","ru":"Зелёный сигнал разрешает и разворот, если он не запрещён знаками или разметкой."}},{"uk":"Прямо і праворуч.","ru":"Прямо и направо.","w":{"uk":"Повороти ліворуч і розворот на зелений сигнал теж дозволені — за умови пропуску зустрічних транспортних засобів.","ru":"Поворот налево и разворот на зелёный сигнал тоже разрешены — при условии пропуска встречных транспортных средств."}}],"c":1,"e":{"uk":"Горить зелений сигнал основного світлофора без додаткових секцій, а знаків, що обмежують напрямки руху, немає — зелений дозволяє рух в усіх напрямках, зокрема й розворот ({p:8.7}). Повертаючи ліворуч чи розвертаючись, треба лише пропустити зустрічних ({p:16.6}).","ru":"Горит зелёный сигнал основного светофора без дополнительных секций, а знаков, ограничивающих направления движения, нет — зелёный разрешает движение во всех направлениях, в том числе и разворот ({p:8.7}). Поворачивая налево или разворачиваясь, нужно лишь пропустить встречных ({p:16.6})."},"ref":["8.7","16.6"],"pic":["img/hsc/8.1-21-1.jpg"]},{"id":"h8.1-22","t":"h8.1","num":"8.1.22","q":{"uk":"Як Ви повинні вчинити в даній ситуації?","ru":"Как Вы должны поступить в данной ситуации?"},"a":[{"uk":"Зупинитися в місці, на яке вкаже поліцейський, з дотриманням правил зупинки.","ru":"Остановиться в месте, на которое укажет полицейский, с соблюдением правил остановки."},{"uk":"Зупинитися біля правого або лівого краю проїзної частини.","ru":"Остановиться у правого или левого края проезжей части.","w":{"uk":"Місце зупинки визначає поліцейський, а не водій на власний розсуд.","ru":"Место остановки определяет полицейский, а не водитель по своему усмотрению."}},{"uk":"Зупинитися, не змінюючи смуги руху.","ru":"Остановиться, не меняя полосы движения.","w":{"uk":"Зупинятися просто на смузі руху не можна: треба стати там, де вказав поліцейський, дотримуючись правил зупинки.","ru":"Останавливаться прямо на полосе движения нельзя: нужно встать там, где указал полицейский, соблюдая правила остановки."}}],"c":0,"e":{"uk":"Поліцейський рукою з жезлом вимагає зупинитися. За {p:8.9} водій повинен зупинити транспортний засіб у місці, на яке вказує поліцейський, з дотриманням правил зупинки.","ru":"Полицейский рукой с жезлом требует остановиться. По {p:8.9} водитель должен остановить транспортное средство в месте, на которое указывает полицейский, с соблюдением правил остановки."},"ref":["8.9"],"pic":["img/hsc/8.1-22-1.jpg"]},{"id":"h8.1-23","t":"h8.1","num":"8.1.23","q":{"uk":"Як Ви повинні діяти в цій ситуації, якщо співробітник поліції подає Вам сигнал про зупинку?","ru":"Как Вы должны действовать в этой ситуации, если сотрудник полиции подаёт Вам сигнал об остановке?"},"a":[{"uk":"Зупинити свій транспортний засіб у місці, на яке Вам буде вказано, з дотриманням правил зупинки.","ru":"Остановить своё транспортное средство в месте, которое Вам укажут, с соблюдением правил остановки."},{"uk":"Зупинитися, але тільки з лівого боку проїжджої частини.","ru":"Остановиться, но только с левой стороны проезжей части.","w":{"uk":"Правила не вимагають зупинятися саме зліва — місце вказує поліцейський, а зупинка має відповідати правилам.","ru":"Правила не требуют останавливаться именно слева — место указывает полицейский, а остановка должна соответствовать правилам."}},{"uk":"Зупинитися безпосередньо біля поліцейського.","ru":"Остановиться непосредственно возле полицейского.","w":{"uk":"Тут зупинку заборонено знаком {s:3.34} і розміткою {m:1.4}, а вимога поліцейського не звільняє від дотримання правил зупинки.","ru":"Здесь остановка запрещена знаком {s:3.34} и разметкой {m:1.4}, а требование полицейского не освобождает от соблюдения правил остановки."}}],"c":0,"e":{"uk":"За {p:8.9} на вимогу поліцейського водій зупиняється в указаному місці з дотриманням правил зупинки. Біля поліцейського зупинку заборонено знаком {s:3.34} із табличкою {s:7.2.1} та жовтою розміткою {m:1.4}, тож стати треба там, куди він вкаже.","ru":"По {p:8.9} по требованию полицейского водитель останавливается в указанном месте с соблюдением правил остановки. Возле полицейского остановка запрещена знаком {s:3.34} с табличкой {s:7.2.1} и жёлтой разметкой {m:1.4}, поэтому остановиться нужно там, куда он укажет."},"ref":["8.9"],"pic":["img/hsc/8.1-23-1.jpg"]},{"id":"h8.1-24","t":"h8.1","num":"8.1.24","q":{"uk":"Яким учасникам дорожнього руху дозволено рух у даній ситуації?","ru":"Каким участникам дорожного движения разрешено движение в данной ситуации?"},"a":[{"uk":"Транспортним засобам.","ru":"Транспортным средствам.","w":{"uk":"Піднята вгору рука забороняє рух і транспортним засобам.","ru":"Поднятая вверх рука запрещает движение и транспортным средствам."}},{"uk":"Пішоходам.","ru":"Пешеходам.","w":{"uk":"Піднята вгору рука забороняє рух і пішоходам.","ru":"Поднятая вверх рука запрещает движение и пешеходам."}},{"uk":"Транспортним засобам і пішоходам.","ru":"Транспортным средствам и пешеходам.","w":{"uk":"За піднятої вгору руки рух заборонено всім учасникам.","ru":"При поднятой вверх руке движение запрещено всем участникам."}},{"uk":"Нікому.","ru":"Никому."}],"c":3,"e":{"uk":"Регулювальник підняв руку вгору — цей сигнал забороняє рух усіх транспортних засобів і пішоходів у всіх напрямках ({p:8.8}).","ru":"Регулировщик поднял руку вверх — этот сигнал запрещает движение всех транспортных средств и пешеходов во всех направлениях ({p:8.8})."},"ref":["8.8"],"pic":["img/hsc/8.1-24-1.jpg"]},{"id":"h8.1-25","t":"h8.1","num":"8.1.25","q":{"uk":"На даний сигнал регулювальника рух дозволено:","ru":"При данном сигнале регулировщика движение разрешено:"},"a":[{"uk":"Жовтому автомобілю.","ru":"Жёлтому автомобилю."},{"uk":"Чорному і білому автомобілям.","ru":"Чёрному и белому автомобилям.","w":{"uk":"Чорний автомобіль за спиною регулювальника повинен стояти, а білий з боку грудей може лише повернути праворуч.","ru":"Чёрный автомобиль за спиной регулировщика должен стоять, а белый со стороны груди может только повернуть направо."}},{"uk":"Червоному, білому і жовтому автомобілям.","ru":"Красному, белому и жёлтому автомобилям.","w":{"uk":"Червоний автомобіль перебуває з правого боку регулювальника, звідки рух заборонено.","ru":"Красный автомобиль находится с правой стороны регулировщика, откуда движение запрещено."}},{"uk":"Червоному і білому автомобілям.","ru":"Красному и белому автомобилям.","w":{"uk":"З правого боку регулювальника (червоний) рух заборонено, а білому дозволено лише праворуч.","ru":"С правой стороны регулировщика (красный) движение запрещено, а белому разрешён только поворот направо."}}],"c":0,"e":{"uk":"Регулювальник стоїть грудьми до білого автомобіля, права рука витягнута вперед. Жовтий автомобіль — з лівого боку регулювальника, звідки нерейковим транспортним засобам дозволено рух у всіх напрямках ({p:8.8}). Червоному (з правого боку) і чорному (з боку спини) рух заборонено, а білому з боку грудей дозволено лише поворот праворуч, якого він не показує.","ru":"Регулировщик стоит грудью к белому автомобилю, правая рука вытянута вперёд. Жёлтый автомобиль — с левой стороны регулировщика, откуда нерельсовым транспортным средствам разрешено движение во всех направлениях ({p:8.8}). Красному (с правой стороны) и чёрному (со стороны спины) движение запрещено, а белому со стороны груди разрешён только поворот направо, которого он не показывает."},"ref":["8.8"],"pic":["img/hsc/8.1-25-1.jpg"]},{"id":"h8.1-26","t":"h8.1","num":"8.1.26","q":{"uk":"Чи дозволено Вам рух у даній ситуації?","ru":"Разрешено ли Вам движение в данной ситуации?"},"a":[{"uk":"Заборонено.","ru":"Запрещено.","w":{"uk":"Цей жест не забороняє рух з боку грудей повністю — праворуч повертати можна.","ru":"Этот жест не запрещает движение со стороны груди полностью — направо поворачивать можно."}},{"uk":"Дозволено прямо.","ru":"Разрешено прямо.","w":{"uk":"Прямо з боку грудей за цього жесту рухатися заборонено.","ru":"Прямо со стороны груди при этом жесте двигаться запрещено."}},{"uk":"Дозволено праворуч.","ru":"Разрешено направо."},{"uk":"Дозволено праворуч і прямо.","ru":"Разрешено направо и прямо.","w":{"uk":"З боку грудей дозволено тільки праворуч; прямо і праворуч можна рухатися лише збоку від регулювальника, коли руки витягнуті в сторони чи опущені.","ru":"Со стороны груди разрешено только направо; прямо и направо можно двигаться лишь сбоку от регулировщика, когда руки вытянуты в стороны или опущены."}}],"c":2,"e":{"uk":"Регулювальник стоїть до Вас грудьми з витягнутою вперед правою рукою — з боку грудей усім транспортним засобам дозволено рух **тільки праворуч** ({p:8.8}).","ru":"Регулировщик стоит к Вам грудью с вытянутой вперёд правой рукой — со стороны груди всем транспортным средствам разрешено движение **только направо** ({p:8.8})."},"ref":["8.8"],"pic":["img/hsc/8.1-26-1.jpg"]},{"id":"h8.1-27","t":"h8.1","num":"8.1.27","q":{"uk":"На даний сигнал регулювальника рух дозволено:","ru":"При данном сигнале регулировщика движение разрешено:"},"a":[{"uk":"Зеленому, синьому і жовтому автомобілям.","ru":"Зелёному, синему и жёлтому автомобилям.","w":{"uk":"Синій автомобіль перебуває з правого боку регулювальника, звідки рух усіх транспортних засобів заборонено.","ru":"Синий автомобиль находится с правой стороны регулировщика, откуда движение всех транспортных средств запрещено."}},{"uk":"Жовтому і зеленому автомобілям.","ru":"Жёлтому и зелёному автомобилям."},{"uk":"Чорному і зеленому автомобілям.","ru":"Чёрному и зелёному автомобилям.","w":{"uk":"Чорний автомобіль стоїть за спиною регулювальника — йому рух заборонено, а жовтому дозволено.","ru":"Чёрный автомобиль стоит за спиной регулировщика — ему движение запрещено, а жёлтому разрешено."}},{"uk":"Жовтому автомобілю.","ru":"Жёлтому автомобилю.","w":{"uk":"Крім жовтого, рух дозволено й зеленому: з боку грудей можна повернути праворуч.","ru":"Кроме жёлтого, движение разрешено и зелёному: со стороны груди можно повернуть направо."}}],"c":1,"e":{"uk":"Регулювальник стоїть грудьми до зеленого автомобіля з витягнутою вперед правою рукою. Жовтий під'їжджає з лівого боку регулювальника — йому дозволено рух у всіх напрямках, зеленому з боку грудей — тільки праворуч, і він якраз повертає праворуч ({p:8.8}). Синьому (з правого боку) і чорному (з боку спини) рух заборонено.","ru":"Регулировщик стоит грудью к зелёному автомобилю с вытянутой вперёд правой рукой. Жёлтый подъезжает с левой стороны регулировщика — ему разрешено движение во всех направлениях, зелёному со стороны груди — только направо, и он как раз поворачивает направо ({p:8.8}). Синему (с правой стороны) и чёрному (со стороны спины) движение запрещено."},"ref":["8.8"],"pic":["img/hsc/8.1-27-1.jpg"]},{"id":"h8.1-28","t":"h8.1","num":"8.1.28","q":{"uk":"Чи дозволено Вам рух у даній ситуації?","ru":"Разрешено ли Вам движение в данной ситуации?"},"a":[{"uk":"Рух заборонено.","ru":"Движение запрещено."},{"uk":"Дозволено праворуч.","ru":"Разрешено направо.","w":{"uk":"Праворуч за цього жесту можна повертати лише з боку грудей регулювальника, а Ви — з його правого боку.","ru":"Направо при этом жесте можно поворачивать только со стороны груди регулировщика, а Вы — с его правой стороны."}},{"uk":"Дозволено ліворуч або на розворот.","ru":"Разрешено налево или на разворот.","w":{"uk":"Ліворуч і на розворот можна рухатися з лівого боку регулювальника, а не з правого.","ru":"Налево и на разворот можно двигаться с левой стороны регулировщика, а не с правой."}}],"c":0,"e":{"uk":"Регулювальник витягнув праву руку вперед і стоїть до Вас правим боком — з правого боку і спини рух усіх транспортних засобів заборонено ({p:8.8}).","ru":"Регулировщик вытянул правую руку вперёд и стоит к Вам правым боком — с правой стороны и со стороны спины движение всех транспортных средств запрещено ({p:8.8})."},"ref":["8.8"],"pic":["img/hsc/8.1-28-1.jpg"]},{"id":"h8.1-29","t":"h8.1","num":"8.1.29","q":{"uk":"Чи дозволено Вам рух у даній ситуації?","ru":"Разрешено ли Вам движение в данной ситуации?"},"a":[{"uk":"Дозволено праворуч.","ru":"Разрешено направо.","w":{"uk":"З боку спини регулювальника повертати праворуч заборонено.","ru":"Со стороны спины регулировщика поворачивать направо запрещено."}},{"uk":"Дозволено праворуч і ліворуч.","ru":"Разрешено направо и налево.","w":{"uk":"З боку спини регулювальника рух заборонено в усіх напрямках.","ru":"Со стороны спины регулировщика движение запрещено во всех направлениях."}},{"uk":"Рух заборонено.","ru":"Движение запрещено."}],"c":2,"e":{"uk":"Регулювальник стоїть до Вас спиною, а зі сторони спини рух усіх транспортних засобів заборонено за будь-якого з його основних жестів ({p:8.8}).","ru":"Регулировщик стоит к Вам спиной, а со стороны спины движение всех транспортных средств запрещено при любом из его основных жестов ({p:8.8})."},"ref":["8.8"],"pic":["img/hsc/8.1-29-1.jpg"]},{"id":"h8.1-30","t":"h8.1","num":"8.1.30","q":{"uk":"У якому з місць пішоходам дозволено перехід проїзної частини в даній ситуації?","ru":"В каком из мест пешеходам разрешено переходить проезжую часть в данной ситуации?"},"a":[{"uk":"У місці Г.","ru":"В месте Г."},{"uk":"У місцях Б і Г.","ru":"В местах Б и Г.","w":{"uk":"Перехід Б розташований перед грудьми регулювальника, а за цього жесту там переходити не можна.","ru":"Переход Б расположен перед грудью регулировщика, а при этом жесте там переходить нельзя."}},{"uk":"У місці Б.","ru":"В месте Б.","w":{"uk":"Перехід Б — перед грудьми регулювальника; пішоходам дозволено переходити лише за його спиною.","ru":"Переход Б — перед грудью регулировщика; пешеходам разрешено переходить только за его спиной."}},{"uk":"У всіх місцях.","ru":"Во всех местах.","w":{"uk":"За витягнутої вперед правої руки пішоходи можуть переходити лише за спиною регулювальника, тобто тільки в місці Г.","ru":"При вытянутой вперёд правой руке пешеходы могут переходить только за спиной регулировщика, то есть только в месте Г."}}],"c":0,"e":{"uk":"Регулювальник витягнув праву руку вперед — за такого жесту пішоходам дозволено переходити проїзну частину **тільки за спиною** регулювальника ({p:8.8}). За його спиною розташований перехід Г.","ru":"Регулировщик вытянул правую руку вперёд — при таком жесте пешеходам разрешено переходить проезжую часть **только за спиной** регулировщика ({p:8.8}). За его спиной расположен переход Г."},"ref":["8.8"],"pic":["img/hsc/8.1-30-1.jpg"]},{"id":"h8.1-31","t":"h8.1","num":"8.1.31","q":{"uk":"На даний сигнал регулювальника рух дозволено:","ru":"При данном сигнале регулировщика движение разрешено:"},"a":[{"uk":"Трамваям 1 і 2, а також білому автомобілю.","ru":"Трамваям 1 и 2, а также белому автомобилю.","w":{"uk":"Сірий автомобіль з боку грудей теж може рухатися, бо повертає праворуч.","ru":"Серый автомобиль со стороны груди тоже может двигаться, так как поворачивает направо."}},{"uk":"Трамваям 1 і 2, сірому і білому автомобілям.","ru":"Трамваям 1 и 2, серому и белому автомобилям."},{"uk":"Трамваю 1, білому і сірому автомобілям.","ru":"Трамваю 1, белому и серому автомобилям.","w":{"uk":"Трамвай 2 з лівого боку регулювальника повертає ліворуч, а це дозволено.","ru":"Трамвай 2 с левой стороны регулировщика поворачивает налево, а это разрешено."}},{"uk":"Трамваю 2 і білому автомобілю.","ru":"Трамваю 2 и белому автомобилю.","w":{"uk":"Трамвай 1 і сірий автомобіль повертають праворуч з боку грудей регулювальника — їм рух теж дозволено.","ru":"Трамвай 1 и серый автомобиль поворачивают направо со стороны груди регулировщика — им движение тоже разрешено."}}],"c":1,"e":{"uk":"Регулювальник витягнув праву руку вперед. Трамвай 1 і сірий автомобіль — з боку його грудей, звідки всім дозволено рух тільки праворуч, і обидва повертають праворуч. Трамвай 2 і білий автомобіль — з лівого боку: трамваю звідси дозволено ліворуч (він туди й повертає), нерейковим транспортним засобам — у всіх напрямках ({p:8.8}).","ru":"Регулировщик вытянул правую руку вперёд. Трамвай 1 и серый автомобиль — со стороны его груди, откуда всем разрешено движение только направо, и оба поворачивают направо. Трамвай 2 и белый автомобиль — с левой стороны: трамваю отсюда разрешено налево (он туда и поворачивает), нерельсовым транспортным средствам — во всех направлениях ({p:8.8})."},"ref":["8.8"],"pic":["img/hsc/8.1-31-1.jpg"]},{"id":"h8.1-32","t":"h8.1","num":"8.1.32","q":{"uk":"На даний сигнал регулювальника трамваю дозволено рух:","ru":"При данном сигнале регулировщика трамваю разрешено движение:"},"a":[{"uk":"Прямо або праворуч.","ru":"Прямо или направо.","w":{"uk":"Прямо і праворуч трамваю з лівого боку регулювальника за цього жесту рухатися заборонено.","ru":"Прямо и направо трамваю с левой стороны регулировщика при этом жесте двигаться запрещено."}},{"uk":"Прямо або ліворуч.","ru":"Прямо или налево.","w":{"uk":"Рух прямо трамваю за цього жесту заборонений — дозволено тільки ліворуч.","ru":"Движение прямо трамваю при этом жесте запрещено — разрешено только налево."}},{"uk":"Ліворуч або праворуч.","ru":"Налево или направо.","w":{"uk":"Праворуч трамваю з лівого боку регулювальника рухатися заборонено.","ru":"Направо трамваю с левой стороны регулировщика двигаться запрещено."}},{"uk":"Ліворуч.","ru":"Налево."}],"c":3,"e":{"uk":"Трамвай під'їжджає з лівого боку регулювальника, який витягнув праву руку вперед: з лівого боку трамваю дозволено рух **тільки ліворуч** ({p:8.8}).","ru":"Трамвай подъезжает с левой стороны регулировщика, который вытянул правую руку вперёд: с левой стороны трамваю разрешено движение **только налево** ({p:8.8})."},"ref":["8.8"],"pic":["img/hsc/8.1-32-1.jpg"]},{"id":"h8.1-33","t":"h8.1","num":"8.1.33","q":{"uk":"У якому напрямку Ви можете продовжити рух у даній ситуації?","ru":"В каком направлении Вы можете продолжить движение в данной ситуации?"},"a":[{"uk":"Ліворуч.","ru":"Налево.","w":{"uk":"Крім повороту ліворуч, з лівого боку регулювальника дозволено й розворот.","ru":"Кроме поворота налево, с левой стороны регулировщика разрешён и разворот."}},{"uk":"У зворотному напрямку.","ru":"В обратном направлении.","w":{"uk":"Крім розвороту, з лівого боку регулювальника дозволено й поворот ліворуч.","ru":"Кроме разворота, с левой стороны регулировщика разрешён и поворот налево."}},{"uk":"Ліворуч або у зворотному напрямку.","ru":"Налево или в обратном направлении."}],"c":2,"e":{"uk":"Регулювальник стоїть до Вас лівим боком із витягнутою вперед правою рукою — з лівого боку нерейковим транспортним засобам дозволено рух у всіх напрямках ({p:8.8}). Ви ввімкнули лівий покажчик повороту, тож можете повернути ліворуч або розвернутися.","ru":"Регулировщик стоит к Вам левым боком с вытянутой вперёд правой рукой — с левой стороны нерельсовым транспортным средствам разрешено движение во всех направлениях ({p:8.8}). Вы включили левый указатель поворота, поэтому можете повернуть налево или развернуться."},"ref":["8.8"],"pic":["img/hsc/8.1-33-1.jpg"]},{"id":"h8.1-34","t":"h8.1","num":"8.1.34","q":{"uk":"У якому напрямку Ви можете продовжити рух на даний сигнал регулювальника?","ru":"В каком направлении Вы можете продолжить движение при данном сигнале регулировщика?"},"a":[{"uk":"Ліворуч.","ru":"Налево.","w":{"uk":"З лівого боку регулювальника дозволено не лише ліворуч, а й в усіх інших напрямках.","ru":"С левой стороны регулировщика разрешено не только налево, но и во всех остальных направлениях."}},{"uk":"Прямо або праворуч.","ru":"Прямо или направо.","w":{"uk":"Прямо і праворуч — це дозвіл для того, хто стоїть збоку від регулювальника з витягнутими в сторони руками; тут дозволено ще й ліворуч і розворот.","ru":"Прямо и направо — это разрешение для того, кто стоит сбоку от регулировщика с вытянутыми в стороны руками; здесь разрешены ещё и налево, и разворот."}},{"uk":"Прямо або ліворуч.","ru":"Прямо или налево.","w":{"uk":"З лівого боку регулювальника можна також повернути праворуч і розвернутися.","ru":"С левой стороны регулировщика можно также повернуть направо и развернуться."}},{"uk":"Прямо, праворуч або ліворуч.","ru":"Прямо, направо или налево.","w":{"uk":"Дозволено й розворот — з лівого боку регулювальника рух не обмежений жодним напрямком.","ru":"Разрешён и разворот — с левой стороны регулировщика движение не ограничено ни одним направлением."}},{"uk":"Прямо, праворуч, ліворуч або у зворотному напрямку.","ru":"Прямо, направо, налево или в обратном направлении."}],"c":4,"e":{"uk":"Регулювальник стоїть до Вас лівим боком із витягнутою вперед правою рукою — з лівого боку нерейковим транспортним засобам дозволено рух **у всіх напрямках**, зокрема й розворот ({p:8.8}).","ru":"Регулировщик стоит к Вам левым боком с вытянутой вперёд правой рукой — с левой стороны нерельсовым транспортным средствам разрешено движение **во всех направлениях**, в том числе и разворот ({p:8.8})."},"ref":["8.8"],"pic":["img/hsc/8.1-34-1.jpg"]},{"id":"h8.1-35","t":"h8.1","num":"8.1.35","q":{"uk":"Чи дозволено Вам рух прямо в даній ситуації?","ru":"Разрешено ли Вам движение прямо в данной ситуации?"},"a":[{"uk":"Заборонено.","ru":"Запрещено.","w":{"uk":"З лівого боку регулювальника нерейковим транспортним засобам дозволено рух у всіх напрямках, зокрема прямо; червоний сигнал світлофора тут не діє.","ru":"С левой стороны регулировщика нерельсовым транспортным средствам разрешено движение во всех направлениях, в том числе прямо; красный сигнал светофора здесь не действует."}},{"uk":"Дозволено за умови, що Ви дасте дорогу трамваю.","ru":"Разрешено при условии, что Вы уступите дорогу трамваю.","w":{"uk":"Трамваю за цього жесту дозволено лише ліворуч, а він туди не повертає — рушати йому не можна, тож і поступатися не потрібно.","ru":"Трамваю при этом жесте разрешено только налево, а он туда не поворачивает — трогаться ему нельзя, поэтому и уступать не нужно."}},{"uk":"Дозволено тільки Вам, рух трамваю заборонено.","ru":"Разрешено только Вам, движение трамвая запрещено."}],"c":2,"e":{"uk":"Регулювальник витягнув праву руку вперед, і Ви, як і трамвай, перебуваєте з його лівого боку: нерейковим транспортним засобам звідси дозволено рух у всіх напрямках, а трамваю — **тільки ліворуч** ({p:8.8}). Трамвай ліворуч не повертає, тож йому рух заборонено, а Ви можете їхати прямо; сигнали світлофора не діють ({p:8.3}).","ru":"Регулировщик вытянул правую руку вперёд, и Вы, как и трамвай, находитесь с его левой стороны: нерельсовым транспортным средствам отсюда разрешено движение во всех направлениях, а трамваю — **только налево** ({p:8.8}). Трамвай налево не поворачивает, поэтому ему движение запрещено, а Вы можете ехать прямо; сигналы светофора не действуют ({p:8.3})."},"ref":["8.8","8.3"],"pic":["img/hsc/8.1-35-1.jpg"]},{"id":"h8.1-36","t":"h8.1","num":"8.1.36","q":{"uk":"Яким автомобілям дозволено рух на даний жест регулювальника?","ru":"Каким автомобилям разрешено движение при данном жесте регулировщика?"},"a":[{"uk":"Усім.","ru":"Всем."},{"uk":"Червоному і жовтому.","ru":"Красному и жёлтому.","w":{"uk":"Сірому, що повертає праворуч, з лівого боку регулювальника рух теж дозволено.","ru":"Серому, поворачивающему направо, с левой стороны регулировщика движение тоже разрешено."}},{"uk":"Червоному.","ru":"Красному.","w":{"uk":"Не лише червоному: з лівого боку регулювальника рух дозволено в усіх напрямках, тож і жовтому, і сірому.","ru":"Не только красному: с левой стороны регулировщика движение разрешено во всех направлениях, значит, и жёлтому, и серому."}},{"uk":"Жовтому і сірому.","ru":"Жёлтому и серому.","w":{"uk":"Червоному теж дозволено: зелена стрілка тут ні до чого, бо діє сигнал регулювальника, а він дозволяє й поворот ліворуч.","ru":"Красному тоже разрешено: зелёная стрелка здесь ни при чём, так как действует сигнал регулировщика, а он разрешает и поворот налево."}},{"uk":"Сірому і червоному.","ru":"Серому и красному.","w":{"uk":"Жовтому, що їде прямо, з лівого боку регулювальника рух теж дозволено.","ru":"Жёлтому, едущему прямо, с левой стороны регулировщика движение тоже разрешено."}}],"c":0,"e":{"uk":"Усі три автомобілі під'їжджають з лівого боку регулювальника, який витягнув праву руку вперед, — звідси нерейковим транспортним засобам дозволено рух у всіх напрямках ({p:8.8}). Тож рушити можуть і червоний (ліворуч), і жовтий (прямо), і сірий (праворуч); сигнали світлофора не діють ({p:8.3}).","ru":"Все три автомобиля подъезжают с левой стороны регулировщика, который вытянул правую руку вперёд, — отсюда нерельсовым транспортным средствам разрешено движение во всех направлениях ({p:8.8}). Поэтому тронуться могут и красный (налево), и жёлтый (прямо), и серый (направо); сигналы светофора не действуют ({p:8.3})."},"ref":["8.8","8.3"],"pic":["img/hsc/8.1-36-1.jpg"]},{"id":"h8.1-37","t":"h8.1","num":"8.1.37","q":{"uk":"Для регулювання руху яких транспортних засобів застосовується даний світлофор?","ru":"Для регулирования движения каких транспортных средств применяется данный светофор?"},"a":[{"uk":"Маршрутних транспортних засобів.","ru":"Маршрутных транспортных средств.","w":{"uk":"Маршрутні транспортні засоби (крім трамваїв) керуються звичайними світлофорами; Т-подібний призначений саме для трамваїв.","ru":"Маршрутные транспортные средства (кроме трамваев) руководствуются обычными светофорами; Т-образный предназначен именно для трамваев."}},{"uk":"Трамваїв.","ru":"Трамваев."},{"uk":"Тролейбусів.","ru":"Троллейбусов.","w":{"uk":"Тролейбуси — нерейкові транспортні засоби і рухаються за звичайними світлофорами, а не за трамвайними.","ru":"Троллейбусы — нерельсовые транспортные средства и движутся по обычным светофорам, а не по трамвайным."}}],"c":1,"e":{"uk":"Світлофор із чотирма біло-місячними сигналами, розташованими у вигляді літери «Т», застосовується для регулювання руху трамваїв ({p:8.7}).","ru":"Светофор с четырьмя бело-лунными сигналами, расположенными в виде буквы «Т», применяется для регулирования движения трамваев ({p:8.7})."},"ref":["8.7"],"pic":["img/hsc/8.1-37-1.jpg"]},{"id":"h8.1-38","t":"h8.1","num":"8.1.38","q":{"uk":"Чи дозволено водієві червоного автомобіля в даній ситуації виконати випередження вантажного автомобіля з лівого боку?","ru":"Разрешено ли водителю красного автомобиля в данной ситуации выполнить опережение грузового автомобиля с левой стороны?"},"a":[{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"Щоб випередити вантажівку зліва, треба заїхати на реверсивну смугу, а при вимкнених реверсивних світлофорах це заборонено, і лінію {m:1.9} ліворуч перетинати не можна.","ru":"Чтобы опередить грузовик слева, нужно заехать на реверсивную полосу, а при выключенных реверсивных светофорах это запрещено, и линию {m:1.9} слева пересекать нельзя."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":1,"e":{"uk":"Ліворуч від червоного автомобіля — реверсивна смуга, позначена з обох боків розміткою {m:1.9}, а реверсивні світлофори над нею вимкнені. За вимкнених сигналів реверсивного світлофора в'їзд на таку смугу заборонено ({p:8.7}), тож для випередження виїхати на неї не можна.","ru":"Слева от красного автомобиля — реверсивная полоса, обозначенная с обеих сторон разметкой {m:1.9}, а реверсивные светофоры над ней выключены. При выключенных сигналах реверсивного светофора въезд на такую полосу запрещён ({p:8.7}), поэтому для опережения выезжать на неё нельзя."},"ref":["8.7","34.1"],"pic":["img/hsc/8.1-38-1.jpg"]},{"id":"h8.1-39","t":"h8.1","num":"8.1.39","q":{"uk":"Проїжджаючи дане перехрестя, водії повинні керуватися:","ru":"Проезжая данный перекрёсток, водители должны руководствоваться:"},"a":[{"uk":"Знаками пріоритету.","ru":"Знаками приоритета.","w":{"uk":"Знаки пріоритету діють лише тоді, коли світлофор вимкнений або блимає жовтим, а тут він працює.","ru":"Знаки приоритета действуют только когда светофор выключен или мигает жёлтым, а здесь он работает."}},{"uk":"Сигналами світлофора.","ru":"Сигналами светофора."},{"uk":"Вірні обидва варіанти.","ru":"Верны оба варианта.","w":{"uk":"Поки світлофор працює, знаки пріоритету не діють, тож керуватися обома не можна.","ru":"Пока светофор работает, знаки приоритета не действуют, поэтому руководствоваться обоими нельзя."}}],"c":1,"e":{"uk":"Світлофори працюють у звичайному режимі, тож перехрестя регульоване, а на ньому знаки пріоритету не діють ({p:16.1}). Крім того, сигнали світлофора мають перевагу перед знаками пріоритету ({p:8.3}).","ru":"Светофоры работают в обычном режиме, поэтому перекрёсток регулируемый, а на нём знаки приоритета не действуют ({p:16.1}). Кроме того, сигналы светофора имеют преимущество перед знаками приоритета ({p:8.3})."},"ref":["16.1","8.3"],"pic":["img/hsc/8.1-39-1.jpg"]},{"id":"h8.1-40","t":"h8.1","num":"8.1.40","q":{"uk":"У яких напрямках Вам дозволено рух в даній ситуації?","ru":"В каких направлениях Вам разрешено движение в данной ситуации?"},"a":[{"uk":"Прямо, праворуч, ліворуч і розворот.","ru":"Прямо, направо, налево и разворот.","w":{"uk":"Контурні стрілки на зеленому не показують руху праворуч — цей напрямок регулює додаткова секція.","ru":"Контурные стрелки на зелёном не показывают движения направо — это направление регулирует дополнительная секция."}},{"uk":"Ліворуч.","ru":"Налево.","w":{"uk":"Контурні стрілки дозволяють і рух прямо, а стрілка ліворуч — ще й розворот.","ru":"Контурные стрелки разрешают и движение прямо, а стрелка налево — ещё и разворот."}},{"uk":"Ліворуч і розворот.","ru":"Налево и разворот.","w":{"uk":"Крім повороту ліворуч і розвороту, контурна стрілка дозволяє й рух прямо.","ru":"Кроме поворота налево и разворота, контурная стрелка разрешает и движение прямо."}},{"uk":"Прямо, ліворуч і розворот.","ru":"Прямо, налево и разворот."}],"c":3,"e":{"uk":"На зеленому сигналі нанесені чорні контурні стрілки прямо і ліворуч — вони вказують дозволені за цього сигналу напрямки ({p:8.7}). Стрілка ліворуч дозволяє й розворот, а праворуч рух можливий лише за сигналом додаткової секції, коли вона ввімкнеться.","ru":"На зелёном сигнале нанесены чёрные контурные стрелки прямо и налево — они указывают разрешённые при этом сигнале направления ({p:8.7}). Стрелка налево разрешает и разворот, а направо движение возможно только по сигналу дополнительной секции, когда она включится."},"ref":["8.7"],"pic":["img/hsc/8.1-40-1.jpg"]},{"id":"h8.1-41","t":"h8.1","num":"8.1.41","q":{"uk":"Як Ви повинні вчинити в цій ситуації, якщо поліцейський подає Вам сигнал про зупинку?","ru":"Как Вы должны поступить в этой ситуации, если полицейский подаёт Вам сигнал об остановке?"},"a":[{"uk":"Виконати вимогу поліцейського, зупинивши свій транспортний засіб у місці, на яке Вам буде вказано, з дотриманням правил зупинки.","ru":"Выполнить требование полицейского, остановив своё транспортное средство в месте, которое Вам укажут, с соблюдением правил остановки."},{"uk":"Виконати вимогу поліцейського, зупинивши свій транспортний засіб тільки з лівого боку дороги.","ru":"Выполнить требование полицейского, остановив своё транспортное средство только с левой стороны дороги.","w":{"uk":"Правила не вимагають зупинятися тільки з лівого боку — місце вказує поліцейський з урахуванням правил зупинки.","ru":"Правила не требуют останавливаться только с левой стороны — место указывает полицейский с учётом правил остановки."}}],"c":0,"e":{"uk":"На вимогу поліцейського водій повинен зупинитися в місці, на яке йому вкажуть, з дотриманням правил зупинки ({p:8.9}). Тут біля поліцейського діє знак {s:3.34} з табличкою {s:7.2.1}, тому стати треба там, де зупинка дозволена й куди вкаже поліцейський.","ru":"По требованию полицейского водитель должен остановиться в месте, которое ему укажут, с соблюдением правил остановки ({p:8.9}). Здесь возле полицейского действует знак {s:3.34} с табличкой {s:7.2.1}, поэтому встать нужно там, где остановка разрешена и куда укажет полицейский."},"ref":["8.9"],"pic":["img/hsc/8.1-41-1.jpg"]},{"id":"h8.1-42","t":"h8.1","num":"8.1.42","q":{"uk":"Як повинні вчинити водії транспортних засобів у даній ситуації?","ru":"Как должны поступить водители транспортных средств в данной ситуации?"},"a":[{"uk":"Керуючись сигналом регулювальника, продовжити рух.","ru":"Руководствуясь сигналом регулировщика, продолжить движение."},{"uk":"Дочекавшись дозвільного сигналу світлофора, розпочати рух.","ru":"Дождавшись разрешающего сигнала светофора, начать движение.","w":{"uk":"Чекати на сигнал світлофора не потрібно: коли перехрестя регулює регулювальник, діють його сигнали.","ru":"Ждать сигнала светофора не нужно: когда перекрёсток регулирует регулировщик, действуют его сигналы."}},{"uk":"Керуючись сигналом регулювальника, рух повинен продовжити тільки білий автомобіль.","ru":"Руководствуясь сигналом регулировщика, движение должен продолжить только белый автомобиль.","w":{"uk":"Темному автомобілю, що повертає ліворуч, з лівого боку регулювальника рух теж дозволено.","ru":"Тёмному автомобилю, поворачивающему налево, с левой стороны регулировщика движение тоже разрешено."}}],"c":0,"e":{"uk":"Обидва автомобілі під'їжджають з лівого боку регулювальника, який витягнув праву руку вперед, — звідси нерейковим транспортним засобам дозволено рух у всіх напрямках ({p:8.8}). Червоний сигнал світлофора не діє, бо сигнали регулювальника мають перевагу ({p:8.3}).","ru":"Оба автомобиля подъезжают с левой стороны регулировщика, который вытянул правую руку вперёд, — отсюда нерельсовым транспортным средствам разрешено движение во всех направлениях ({p:8.8}). Красный сигнал светофора не действует, так как сигналы регулировщика имеют преимущество ({p:8.3})."},"ref":["8.8","8.3"],"pic":["img/hsc/8.1-42-1.jpg"]},{"id":"h8.1-43","t":"h8.1","num":"8.1.43","q":{"uk":"Як Ви повинні вчинити в даній ситуації?","ru":"Как Вы должны поступить в данной ситуации?"},"a":[{"uk":"Керуючись зеленим сигналом світлофора, продовжити рух через перехрестя.","ru":"Руководствуясь зелёным сигналом светофора, продолжить движение через перекрёсток.","w":{"uk":"Коли сигнали регулювальника і світлофора суперечать одне одному, виконувати треба сигнали регулювальника.","ru":"Когда сигналы регулировщика и светофора противоречат друг другу, выполнять нужно сигналы регулировщика."}},{"uk":"Керуючись сигналом регулювальника, зупинитися.","ru":"Руководствуясь сигналом регулировщика, остановиться."},{"uk":"Керуючись сигналом регулювальника і світлофора, продовжити рух.","ru":"Руководствуясь сигналами регулировщика и светофора, продолжить движение.","w":{"uk":"Сигнал регулювальника (рука вгору) забороняє рух, тож продовжувати його не можна, хоч на світлофорі й зелений.","ru":"Сигнал регулировщика (рука вверх) запрещает движение, поэтому продолжать его нельзя, хотя на светофоре и зелёный."}}],"c":1,"e":{"uk":"Регулювальник підняв руку вгору — рух усіх транспортних засобів заборонено ({p:8.8}), і цей сигнал має перевагу над зеленим сигналом світлофора ({p:8.3}). Тож треба зупинитися перед стоп-лінією ({p:8.10}).","ru":"Регулировщик поднял руку вверх — движение всех транспортных средств запрещено ({p:8.8}), и этот сигнал имеет преимущество перед зелёным сигналом светофора ({p:8.3}). Поэтому нужно остановиться перед стоп-линией ({p:8.10})."},"ref":["8.8","8.3","8.10"],"pic":["img/hsc/8.1-43-1.jpg"]},{"id":"h8.1-44","t":"h8.1","num":"8.1.44","q":{"uk":"На даному перехресті водії та пішоходи повинні керуватися:","ru":"На данном перекрёстке водители и пешеходы должны руководствоваться:"},"a":[{"uk":"Сигналами світлофора.","ru":"Сигналами светофора.","w":{"uk":"За наявності регулювальника світлофори втрачають пріоритет — діють сигнали регулювальника.","ru":"При наличии регулировщика светофоры теряют приоритет — действуют сигналы регулировщика."}},{"uk":"Сигналами регулювальника.","ru":"Сигналами регулировщика."},{"uk":"Сигналами світлофора, якщо не зрозумілі сигнали регулювальника.","ru":"Сигналами светофора, если непонятны сигналы регулировщика.","w":{"uk":"Правила не дозволяють переходити на сигнали світлофора: регулювальник може подавати й інші сигнали, зрозумілі водіям і пішоходам ({p:8.8}), і їх треба виконувати.","ru":"Правила не разрешают переходить на сигналы светофора: регулировщик может подавать и иные сигналы, понятные водителям и пешеходам ({p:8.8}), и их нужно выполнять."}}],"c":1,"e":{"uk":"На перехресті працює регулювальник, а його сигнали мають перевагу над сигналами світлофорів і вимогами знаків та обов'язкові для виконання ({p:8.3}).","ru":"На перекрёстке работает регулировщик, а его сигналы имеют преимущество перед сигналами светофоров и требованиями знаков и обязательны для выполнения ({p:8.3})."},"ref":["8.3","8.8"],"pic":["img/hsc/8.1-44-1.jpg"]},{"id":"h8.1-45","t":"h8.1","num":"8.1.45","q":{"uk":"Чи дозволено в даній ситуації рух водієві автомобіля?","ru":"Разрешено ли в данной ситуации движение водителю автомобиля?"},"a":[{"uk":"Дозволено тільки праворуч.","ru":"Разрешено только направо.","w":{"uk":"Праворуч з боку грудей можна повертати лише тоді, коли регулювальник витягнув праву руку вперед, а тут руки витягнуті в сторони.","ru":"Направо со стороны груди можно поворачивать лишь тогда, когда регулировщик вытянул правую руку вперёд, а здесь руки вытянуты в стороны."}},{"uk":"Дозволено праворуч або ліворуч.","ru":"Разрешено направо или налево.","w":{"uk":"З боку грудей за цього жесту рух заборонено в усіх напрямках.","ru":"Со стороны груди при этом жесте движение запрещено во всех направлениях."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":2,"e":{"uk":"Регулювальник стоїть до автомобіля грудьми з руками, витягнутими в сторони, — з боку грудей і спини рух усіх транспортних засобів заборонено ({p:8.8}).","ru":"Регулировщик стоит к автомобилю грудью с вытянутыми в стороны руками — со стороны груди и спины движение всех транспортных средств запрещено ({p:8.8})."},"ref":["8.8"],"pic":["img/hsc/8.1-45-1.jpg"]},{"id":"h8.1-46","t":"h8.1","num":"8.1.46","q":{"uk":"Яким автомобілям дозволено рух у даній ситуації?","ru":"Каким автомобилям разрешено движение в данной ситуации?"},"a":[{"uk":"Синьому.","ru":"Синему.","w":{"uk":"Білому автомобілю з лівого боку регулювальника рух теж дозволено.","ru":"Белому автомобилю с левой стороны регулировщика движение тоже разрешено."}},{"uk":"Білому.","ru":"Белому.","w":{"uk":"Синьому (темному) автомобілю, що повертає ліворуч, з лівого боку регулювальника рух теж дозволено.","ru":"Синему (тёмному) автомобилю, поворачивающему налево, с левой стороны регулировщика движение тоже разрешено."}},{"uk":"Обом автомобілям.","ru":"Обоим автомобилям."},{"uk":"Рух заборонено.","ru":"Движение запрещено.","w":{"uk":"Жовтий сигнал світлофора тут не діє — сигнал регулювальника дозволяє рух.","ru":"Жёлтый сигнал светофора здесь не действует — сигнал регулировщика разрешает движение."}}],"c":2,"e":{"uk":"Обидва автомобілі під'їжджають з лівого боку регулювальника, який витягнув праву руку вперед, — звідси нерейковим транспортним засобам дозволено рух у всіх напрямках ({p:8.8}). Жовтий сигнал світлофора значення не має, бо сигнали регулювальника мають перевагу ({p:8.3}).","ru":"Оба автомобиля подъезжают с левой стороны регулировщика, который вытянул правую руку вперёд, — отсюда нерельсовым транспортным средствам разрешено движение во всех направлениях ({p:8.8}). Жёлтый сигнал светофора значения не имеет, так как сигналы регулировщика имеют преимущество ({p:8.3})."},"ref":["8.8","8.3"],"pic":["img/hsc/8.1-46-1.jpg"]},{"id":"h8.1-47","t":"h8.1","num":"8.1.47","q":{"uk":"Чим повинні керуватися водії під час проїзду даного перехрестя?","ru":"Чем должны руководствоваться водители при проезде данного перекрёстка?"},"a":[{"uk":"Сигналами світлофора.","ru":"Сигналами светофора.","w":{"uk":"Сигнали регулювальника мають перевагу над сигналами світлофора.","ru":"Сигналы регулировщика имеют преимущество перед сигналами светофора."}},{"uk":"Знаками пріоритету.","ru":"Знаками приоритета.","w":{"uk":"На регульованому перехресті знаки пріоритету не діють.","ru":"На регулируемом перекрёстке знаки приоритета не действуют."}},{"uk":"Сигналами регулювальника.","ru":"Сигналами регулировщика."}],"c":2,"e":{"uk":"Перехрестя регулює регулювальник, а його сигнали мають перевагу і над сигналами світлофорів, і над вимогами знаків ({p:8.3}). На регульованому перехресті знаки пріоритету не діють ({p:16.1}).","ru":"Перекрёсток регулирует регулировщик, а его сигналы имеют преимущество и перед сигналами светофоров, и перед требованиями знаков ({p:8.3}). На регулируемом перекрёстке знаки приоритета не действуют ({p:16.1})."},"ref":["8.3","16.1"],"pic":["img/hsc/8.1-47-1.jpg"]},{"id":"h8.1-48","t":"h8.1","num":"8.1.48","q":{"uk":"Що означає даний сигнал регулювальника?","ru":"Что означает данный сигнал регулировщика?"},"a":[{"uk":"Рух заборонено транспортним засобам.","ru":"Движение запрещено транспортным средствам.","w":{"uk":"Піднята вгору рука забороняє рух не лише транспортним засобам, а й пішоходам.","ru":"Поднятая вверх рука запрещает движение не только транспортным средствам, но и пешеходам."}},{"uk":"Рух заборонено пішоходам.","ru":"Движение запрещено пешеходам.","w":{"uk":"Піднята вгору рука забороняє рух не лише пішоходам, а й транспортним засобам.","ru":"Поднятая вверх рука запрещает движение не только пешеходам, но и транспортным средствам."}},{"uk":"Рух заборонено транспортним засобам і пішоходам.","ru":"Движение запрещено транспортным средствам и пешеходам."}],"c":2,"e":{"uk":"Рука регулювальника піднята вгору — це заборона руху всіх транспортних засобів і пішоходів у всіх напрямках ({p:8.8}).","ru":"Рука регулировщика поднята вверх — это запрет движения всех транспортных средств и пешеходов во всех направлениях ({p:8.8})."},"ref":["8.8"],"pic":["img/hsc/8.1-48-1.jpg"]},{"id":"h8.1-49","t":"h8.1","num":"8.1.49","q":{"uk":"Хто з водіїв порушив Правила дорожнього руху, зупинившись на заборонний сигнал світлофора?","ru":"Кто из водителей нарушил Правила дорожного движения, остановившись на запрещающий сигнал светофора?"},"a":[{"uk":"Водій легкового автомобіля.","ru":"Водитель легкового автомобиля."},{"uk":"Водій вантажного автомобіля.","ru":"Водитель грузового автомобиля.","w":{"uk":"Вантажівка зупинилася перед стоп-лінією, як і вимагає {p:8.10}.","ru":"Грузовик остановился перед стоп-линией, как и требует {p:8.10}."}}],"c":0,"e":{"uk":"На заборонний сигнал світлофора водії мають зупинятися перед стоп-лінією {m:1.12} ({p:8.10}). Легковий автомобіль зупинився, переїхавши стоп-лінію, — це порушення.","ru":"При запрещающем сигнале светофора водители должны останавливаться перед стоп-линией {m:1.12} ({p:8.10}). Легковой автомобиль остановился, переехав стоп-линию, — это нарушение."},"ref":["8.10"],"pic":["img/hsc/8.1-49-1.jpg"]},{"id":"h8.1-50","t":"h8.1","num":"8.1.50","q":{"uk":"Чи дозволено водієві сірого автомобіля в'їхати на реверсивну смугу так, як показано на малюнку?","ru":"Разрешено ли водителю серого автомобиля въехать на реверсивную полосу так, как показано на рисунке?"},"a":[{"uk":"Заборонено.","ru":"Запрещено."},{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"Займати реверсивну смугу можна тільки після реверсивного світлофора з дозвільним сигналом; до нього на цій смузі діє червоний Х-подібний сигнал.","ru":"Занимать реверсивную полосу можно только после реверсивного светофора с разрешающим сигналом; до него на этой полосе действует красный Х-образный сигнал."}}],"c":0,"e":{"uk":"Над реверсивною смугою перед перехрестям горить червоний Х-подібний сигнал — рух нею для Вашого напрямку заборонено ({p:8.7}). Перестроюватися на реверсивну смугу можна лише після проїзду реверсивного світлофора з дозвільним сигналом ({p:11.12}), а сірий автомобіль займає її раніше — ще до світлофора із зеленою стрілкою.","ru":"Над реверсивной полосой перед перекрёстком горит красный Х-образный сигнал — движение по ней для Вашего направления запрещено ({p:8.7}). Перестраиваться на реверсивную полосу можно только после проезда реверсивного светофора с разрешающим сигналом ({p:11.12}), а серый автомобиль занимает её раньше — ещё до светофора с зелёной стрелкой."},"ref":["8.7","11.12"],"pic":["img/hsc/8.1-50-1.jpg"]},{"id":"h8.1-51","t":"h8.1","num":"8.1.51","q":{"uk":"Чи дозволено Вам рух у цій ситуації?","ru":"Разрешено ли Вам движение в этой ситуации?"},"a":[{"uk":"Дозволено, але необхідно дати дорогу транспортним засобам і пішоходам.","ru":"Разрешено, но необходимо уступить дорогу транспортным средствам и пешеходам.","w":{"uk":"Поєднання червоного і жовтого сигналів рух забороняє, а не дозволяє з умовою пропустити інших.","ru":"Сочетание красного и жёлтого сигналов движение запрещает, а не разрешает с условием пропустить других."}},{"uk":"Заборонено, необхідно дочекатися ввімкнення зеленого сигналу та завершення переходу пішоходами проїзної частини.","ru":"Запрещено, необходимо дождаться включения зелёного сигнала и завершения перехода проезжей части пешеходами."}],"c":1,"e":{"uk":"Одночасно горять червоний і жовтий сигнали — це заборона руху й попередження про ввімкнення зеленого ({p:8.7}). Після ввімкнення зеленого треба ще дати змогу пішоходам, які переходять проїзну частину, завершити перехід ({p:16.5}).","ru":"Одновременно горят красный и жёлтый сигналы — это запрет движения и предупреждение о включении зелёного ({p:8.7}). После включения зелёного нужно ещё дать пешеходам, переходящим проезжую часть, завершить переход ({p:16.5})."},"ref":["8.7","16.5"],"pic":["img/hsc/8.1-51-1.jpg"]},{"id":"h8.1-52","t":"h8.1","num":"8.1.52","q":{"uk":"Чи дозволено водієві автомобіля рух у напрямку стрілки, ввімкненої в додатковій секції світлофора?","ru":"Разрешено ли водителю автомобиля движение в направлении стрелки, включённой в дополнительной секции светофора?"},"a":[{"uk":"Заборонено.","ru":"Запрещено.","w":{"uk":"Увімкнена зелена стрілка дозволяє рух у її напрямку навіть за червоного основного сигналу.","ru":"Включённая зелёная стрелка разрешает движение в её направлении даже при красном основном сигнале."}},{"uk":"Дозволено за умови, що він дасть дорогу транспортним засобам.","ru":"Разрешено при условии, что он уступит дорогу транспортным средствам.","w":{"uk":"Пропустити треба не лише транспортні засоби, а й пішоходів на переході, через який проходить поворот.","ru":"Пропустить нужно не только транспортные средства, но и пешеходов на переходе, через который проходит поворот."}},{"uk":"Дозволено за умови безперешкодного пропуску транспортних засобів, що рухаються з інших напрямків, а також пішоходів.","ru":"Разрешено при условии беспрепятственного пропуска транспортных средств, движущихся с других направлений, а также пешеходов."}],"c":2,"e":{"uk":"Зелена стрілка в додатковій секції разом із червоним сигналом дозволяє поворот праворуч за умови безперешкодного пропуску транспортних засобів з інших напрямків ({p:8.7}, {p:16.9}). Крім того, повертаючи, треба дати дорогу пішоходам, які переходять проїзну частину, на яку повертають ({p:16.2}).","ru":"Зелёная стрелка в дополнительной секции вместе с красным сигналом разрешает поворот направо при условии беспрепятственного пропуска транспортных средств с других направлений ({p:8.7}, {p:16.9}). Кроме того, при повороте нужно уступить дорогу пешеходам, переходящим проезжую часть, на которую поворачивают ({p:16.2})."},"ref":["8.7","16.9","16.2"],"pic":["img/hsc/8.1-52-1.jpg"]},{"id":"h8.1-53","t":"h8.1","num":"8.1.53","q":{"uk":"Водіям яких транспортних засобів дозволено рух у даній ситуації?","ru":"Водителям каких транспортных средств разрешено движение в данной ситуации?"},"a":[{"uk":"Водієві трамвая і червоного автомобіля.","ru":"Водителю трамвая и красного автомобиля."},{"uk":"Водіям усіх транспортних засобів.","ru":"Водителям всех транспортных средств.","w":{"uk":"Білому автомобілю поворот ліворуч заборонено, поки вимкнена додаткова секція зі стрілкою ліворуч.","ru":"Белому автомобилю поворот налево запрещён, пока выключена дополнительная секция со стрелкой налево."}},{"uk":"Водіям білого і червоного автомобілів.","ru":"Водителям белого и красного автомобилей.","w":{"uk":"Білий автомобіль повертає ліворуч, а цей напрямок поки що закритий вимкненою додатковою секцією; трамваю ж прямо рух дозволено.","ru":"Белый автомобиль поворачивает налево, а это направление пока закрыто выключенной дополнительной секцией; трамваю же прямо движение разрешено."}},{"uk":"Водіям трамвая і білого автомобіля.","ru":"Водителям трамвая и белого автомобиля.","w":{"uk":"Рушити може трамвай, але не білий автомобіль: його поворот ліворуч заборонений вимкненою додатковою секцією.","ru":"Тронуться может трамвай, но не белый автомобиль: его поворот налево запрещён выключенной дополнительной секцией."}}],"c":0,"e":{"uk":"Основний зелений сигнал має контурні стрілки прямо і праворуч, а додаткова секція зі стрілкою ліворуч вимкнена — вимкнений сигнал додаткової секції забороняє рух у напрямку її стрілки ({p:8.7}). Тому трамвай (прямо) і червоний автомобіль (праворуч) їхати можуть, а білий, що повертає ліворуч, — ні.","ru":"Основной зелёный сигнал имеет контурные стрелки прямо и направо, а дополнительная секция со стрелкой налево выключена — выключенный сигнал дополнительной секции запрещает движение в направлении её стрелки ({p:8.7}). Поэтому трамвай (прямо) и красный автомобиль (направо) ехать могут, а белый, поворачивающий налево, — нет."},"ref":["8.7"],"pic":["img/hsc/8.1-53-1.jpg"]},{"id":"h8.1-54","t":"h8.1","num":"8.1.54","q":{"uk":"У якому напрямку Вам дозволено рух в зображеній ситуації?","ru":"В каком направлении Вам разрешено движение в изображённой ситуации?"},"a":[{"uk":"Прямо, праворуч, ліворуч і розворот.","ru":"Прямо, направо, налево и разворот.","w":{"uk":"Сигнал-стрілка дозволяє рух лише в указаному напрямку, а не в усіх.","ru":"Сигнал-стрелка разрешает движение только в указанном направлении, а не во всех."}},{"uk":"Ліворуч.","ru":"Налево.","w":{"uk":"Стрілка ліворуч дозволяє також розворот.","ru":"Стрелка налево разрешает также разворот."}},{"uk":"Ліворуч і розворот.","ru":"Налево и разворот."},{"uk":"Прямо, ліворуч і розворот.","ru":"Прямо, налево и разворот.","w":{"uk":"Рух прямо цей сигнал не дозволяє — стрілка показує тільки ліворуч.","ru":"Движение прямо этот сигнал не разрешает — стрелка показывает только налево."}}],"c":2,"e":{"uk":"Горить зелений сигнал у вигляді стрілки ліворуч на чорному тлі — він дозволяє рух лише в напрямку стрілки, а стрілка ліворуч дозволяє й розворот, якщо його не заборонено знаками ({p:8.7}).","ru":"Горит зелёный сигнал в виде стрелки налево на чёрном фоне — он разрешает движение только в направлении стрелки, а стрелка налево разрешает и разворот, если он не запрещён знаками ({p:8.7})."},"ref":["8.7"],"pic":["img/hsc/8.1-54-1.jpg"]},{"id":"h8.1-55","t":"h8.1","num":"8.1.55","q":{"uk":"Водіям яких транспортних засобів дозволено рух у даній ситуації?","ru":"Водителям каких транспортных средств разрешено движение в данной ситуации?"},"a":[{"uk":"Водіям усіх транспортних засобів.","ru":"Водителям всех транспортных средств.","w":{"uk":"Червоний (ліворуч) і сірий (прямо) рухаються на червоний сигнал, і стрілка праворуч їм не допомагає.","ru":"Красный (налево) и серый (прямо) движутся на красный сигнал, и стрелка направо им не помогает."}},{"uk":"Водіям червоного і сірого автомобілів.","ru":"Водителям красного и серого автомобилей.","w":{"uk":"Ні червоному, що повертає ліворуч, ні сірому, що їде прямо, червоний сигнал рушати не дозволяє.","ru":"Ни красному, поворачивающему налево, ни серому, едущему прямо, красный сигнал трогаться не разрешает."}},{"uk":"Водіям сірого та синього автомобілів.","ru":"Водителям серого и синего автомобилей.","w":{"uk":"Сірий їде прямо, а для цього напрямку горить червоний сигнал.","ru":"Серый едет прямо, а для этого направления горит красный сигнал."}},{"uk":"Водієві синього автомобіля.","ru":"Водителю синего автомобиля."}],"c":3,"e":{"uk":"Основний сигнал червоний, а в додатковій секції горить зелена стрілка праворуч — рух дозволено лише праворуч, з пропуском транспортних засобів з інших напрямків ({p:8.7}, {p:16.9}). Праворуч повертає тільки синій автомобіль.","ru":"Основной сигнал красный, а в дополнительной секции горит зелёная стрелка направо — движение разрешено только направо, с пропуском транспортных средств с других направлений ({p:8.7}, {p:16.9}). Направо поворачивает только синий автомобиль."},"ref":["8.7","16.9"],"pic":["img/hsc/8.1-55-1.jpg"]},{"id":"h8.1-56","t":"h8.1","num":"8.1.56","q":{"uk":"У якому напрямку Вам дозволено рух у даній ситуації?","ru":"В каком направлении Вам разрешено движение в данной ситуации?"},"a":[{"uk":"Ліворуч.","ru":"Налево.","w":{"uk":"Стрілка ліворуч дозволяє також розворот.","ru":"Стрелка налево разрешает также разворот."}},{"uk":"Ліворуч або розворот.","ru":"Налево или разворот."},{"uk":"Прямо, ліворуч або розворот.","ru":"Прямо, налево или разворот.","w":{"uk":"Для руху прямо горить червоний сигнал — він рух забороняє.","ru":"Для движения прямо горит красный сигнал — он движение запрещает."}}],"c":1,"e":{"uk":"Основний сигнал червоний, а в додатковій секції горить зелена стрілка ліворуч. Вона дозволяє рух ліворуч, а стрілка ліворуч дозволяє й розворот ({p:8.7}); при цьому треба пропустити транспортні засоби з інших напрямків ({p:16.9}).","ru":"Основной сигнал красный, а в дополнительной секции горит зелёная стрелка налево. Она разрешает движение налево, а стрелка налево разрешает и разворот ({p:8.7}); при этом нужно пропустить транспортные средства с других направлений ({p:16.9})."},"ref":["8.7","16.9"],"pic":["img/hsc/8.1-56-1.jpg"]},{"id":"h8.1-57","t":"h8.1","num":"8.1.57","q":{"uk":"Чи може водій автомобіля в даній ситуації розпочати рух?","ru":"Может ли водитель автомобиля в данной ситуации начать движение?"},"a":[{"uk":"Може.","ru":"Может.","w":{"uk":"Червоний разом із жовтим — це ще заборона руху; почати рух можна лише після ввімкнення зеленого.","ru":"Красный вместе с жёлтым — это ещё запрет движения; начать движение можно только после включения зелёного."}},{"uk":"Не може, оскільки повинен дочекатися ввімкнення зеленого сигналу.","ru":"Не может, так как должен дождаться включения зелёного сигнала."}],"c":1,"e":{"uk":"Одночасно ввімкнені червоний і жовтий сигнали забороняють рух і лише попереджають про ввімкнення зеленого ({p:8.7}). Рушати можна тільки на зелений.","ru":"Одновременно включённые красный и жёлтый сигналы запрещают движение и лишь предупреждают о включении зелёного ({p:8.7}). Трогаться можно только на зелёный."},"ref":["8.7"],"pic":["img/hsc/8.1-57-1.jpg"]},{"id":"h8.1-58","t":"h8.1","num":"8.1.58","q":{"uk":"Яке значення мають одночасно ввімкнені червоний і жовтий сигнали світлофора?","ru":"Какое значение имеют одновременно включённые красный и жёлтый сигналы светофора?"},"a":[{"uk":"Дозволяють рух, якщо перехрестя вільне.","ru":"Разрешают движение, если перекрёсток свободен.","w":{"uk":"Червоний із жовтим — це заборона руху незалежно від того, вільне перехрестя чи ні.","ru":"Красный с жёлтым — это запрет движения независимо от того, свободен перекрёсток или нет."}},{"uk":"Забороняють рух.","ru":"Запрещают движение."}],"c":1,"e":{"uk":"За {p:8.7} поєднання червоного і жовтого сигналів забороняє рух та інформує про найближче ввімкнення зеленого сигналу.","ru":"По {p:8.7} сочетание красного и жёлтого сигналов запрещает движение и информирует о скором включении зелёного сигнала."},"ref":["8.7"],"pic":["img/hsc/8.1-58-1.jpg"]},{"id":"h8.1-59","t":"h8.1","num":"8.1.59","q":{"uk":"Чорні контурні стрілки на червоному і жовтому сигналах не змінюють значення цих сигналів та інформують:","ru":"Чёрные контурные стрелки на красном и жёлтом сигналах не меняют значения этих сигналов и информируют:"},"a":[{"uk":"Про наявність у світлофора додаткової секції.","ru":"О наличии у светофора дополнительной секции.","w":{"uk":"Про наявність додаткової секції інформують контурні стрілки на основному **зеленому** сигналі, а не на червоному і жовтому.","ru":"О наличии дополнительной секции информируют контурные стрелки на основном **зелёном** сигнале, а не на красном и жёлтом."}},{"uk":"Про дозволені напрямки руху при зеленому сигналі.","ru":"О разрешённых направлениях движения при зелёном сигнале."}],"c":1,"e":{"uk":"За {p:8.7} чорні контурні стрілки на червоному і жовтому сигналах не змінюють значення цих сигналів і інформують про дозволені напрямки руху при зеленому сигналі.","ru":"По {p:8.7} чёрные контурные стрелки на красном и жёлтом сигналах не меняют значения этих сигналов и информируют о разрешённых направлениях движения при зелёном сигнале."},"ref":["8.7"],"pic":["img/hsc/8.1-59-1.jpg"]},{"id":"h8.1-60","t":"h8.1","num":"8.1.60","q":{"uk":"Чи дозволено водієві автомобіля поворот ліворуч на даному перехресті в разі ввімкнення зеленого сигналу світлофора?","ru":"Разрешён ли водителю автомобиля поворот налево на данном перекрёстке при включении зелёного сигнала светофора?"},"a":[{"uk":"Дозволено тільки в разі ввімкнення зеленого сигналу.","ru":"Разрешён только при включении зелёного сигнала.","w":{"uk":"Зелений сигнал із контурними стрілками дозволяє рух лише в напрямках стрілок, а ліворуч стрілки немає.","ru":"Зелёный сигнал с контурными стрелками разрешает движение только в направлениях стрелок, а налево стрелки нет."}},{"uk":"Заборонено.","ru":"Запрещён."}],"c":1,"e":{"uk":"На сигналах світлофора нанесені чорні контурні стрілки прямо і праворуч — вони показують напрямки, дозволені при зеленому сигналі ({p:8.7}). Стрілки ліворуч немає, тож поворот ліворуч заборонений і на зелений.","ru":"На сигналах светофора нанесены чёрные контурные стрелки прямо и направо — они показывают направления, разрешённые при зелёном сигнале ({p:8.7}). Стрелки налево нет, поэтому поворот налево запрещён и на зелёный."},"ref":["8.7"],"pic":["img/hsc/8.1-60-1.jpg"]},{"id":"h8.1-61","t":"h8.1","num":"8.1.61","q":{"uk":"Чорні контурні стрілки на ввімкненому червоному сигналі світлофора інформують:","ru":"Чёрные контурные стрелки на включённом красном сигнале светофора информируют:"},"a":[{"uk":"Про наявність у світлофора кількох додаткових секцій.","ru":"О наличии у светофора нескольких дополнительных секций.","w":{"uk":"Про наявність додаткової секції повідомляють контурні стрілки на зеленому сигналі, а не на червоному.","ru":"О наличии дополнительной секции сообщают контурные стрелки на зелёном сигнале, а не на красном."}},{"uk":"Про те, що рух дозволено в інших напрямках.","ru":"О том, что движение разрешено в других направлениях.","w":{"uk":"Червоний сигнал з контурними стрілками рух забороняє в усіх напрямках — стрілки не дають дозволу.","ru":"Красный сигнал с контурными стрелками запрещает движение во всех направлениях — стрелки не дают разрешения."}},{"uk":"Про дозволені напрямки руху при зеленому сигналі.","ru":"О разрешённых направлениях движения при зелёном сигнале."}],"c":2,"e":{"uk":"Контурні стрілки на червоному (і жовтому) сигналі не змінюють його значення й лише інформують про напрямки руху, дозволені при зеленому сигналі ({p:8.7}).","ru":"Контурные стрелки на красном (и жёлтом) сигнале не меняют его значения и лишь информируют о направлениях движения, разрешённых при зелёном сигнале ({p:8.7})."},"ref":["8.7"],"pic":["img/hsc/8.1-61-1.jpg"]},{"id":"h8.1-62","t":"h8.1","num":"8.1.62","q":{"uk":"Як Вам виконати поворот ліворуч у даній ситуації?","ru":"Как Вам выполнить поворот налево в данной ситуации?"},"a":[{"uk":"Повернути без зупинки, давши дорогу зустрічним автомобілям.","ru":"Повернуть без остановки, уступив дорогу встречным автомобилям.","w":{"uk":"Вимкнена додаткова секція зі стрілкою ліворуч забороняє поворот ліворуч, навіть якщо пропустити зустрічних.","ru":"Выключенная дополнительная секция со стрелкой налево запрещает поворот налево, даже если пропустить встречных."}},{"uk":"Зупинитися перед стоп-лінією і повернути, коли ввімкнеться додаткова секція.","ru":"Остановиться перед стоп-линией и повернуть, когда включится дополнительная секция."}],"c":1,"e":{"uk":"На зеленому сигналі нанесені контурні стрілки прямо і праворуч — отже, є додаткова секція, яка регулює поворот ліворуч, а поки вона вимкнена, рух ліворуч заборонено ({p:8.7}). Треба зупинитися перед стоп-лінією ({p:8.10}) і повертати після ввімкнення стрілки ліворуч.","ru":"На зелёном сигнале нанесены контурные стрелки прямо и направо — значит, есть дополнительная секция, регулирующая поворот налево, а пока она выключена, движение налево запрещено ({p:8.7}). Нужно остановиться перед стоп-линией ({p:8.10}) и поворачивать после включения стрелки налево."},"ref":["8.7","8.10"],"pic":["img/hsc/8.1-62-1.jpg"]},{"id":"h8.1-63","t":"h8.1","num":"8.1.63","q":{"uk":"Який зі світлофорів застосовується для регулювання руху транспортних засобів на вулицях, дорогах або смугах проїзної частини, напрямок руху на яких може змінюватися на протилежний?","ru":"Какой из светофоров применяется для регулирования движения транспортных средств на улицах, дорогах или полосах проезжей части, направление движения по которым может меняться на противоположное?"},"a":[{"uk":"Світлофор 1.","ru":"Светофор 1."},{"uk":"Світлофор 2.","ru":"Светофор 2.","w":{"uk":"Світлофор із двома червоними сигналами застосовують на залізничних переїздах.","ru":"Светофор с двумя красными сигналами применяется на железнодорожных переездах."}},{"uk":"Світлофор 3.","ru":"Светофор 3.","w":{"uk":"Світлофор із червоним і зеленим сигналами не має Х-подібного сигналу та стрілки вниз, тож реверсивним не є.","ru":"Светофор с красным и зелёным сигналами не имеет Х-образного сигнала и стрелки вниз, поэтому реверсивным не является."}},{"uk":"Світлофор 4.","ru":"Светофор 4.","w":{"uk":"Це звичайний транспортний світлофор із контурними стрілками, а не реверсивний.","ru":"Это обычный транспортный светофор с контурными стрелками, а не реверсивный."}}],"c":0,"e":{"uk":"На смугах із реверсивним рухом застосовують реверсивні світлофори з червоним Х-подібним сигналом і зеленим сигналом у вигляді стрілки, спрямованої вниз ({p:8.7}) — це світлофор 1.","ru":"На полосах с реверсивным движением применяются реверсивные светофоры с красным Х-образным сигналом и зелёным сигналом в виде стрелки, направленной вниз ({p:8.7}), — это светофор 1."},"ref":["8.7"],"pic":["img/hsc/8.1-63-1.jpg"]},{"id":"h8.1-64","t":"h8.1","num":"8.1.64","q":{"uk":"Чи дозволено водієві червоного автомобіля в даній ситуації виконати випередження вантажного автомобіля з лівого боку?","ru":"Разрешено ли водителю красного автомобиля в данной ситуации выполнить опережение грузового автомобиля с левой стороны?"},"a":[{"uk":"Дозволено, але після випередження необхідно повернутися на смугу, яку він займав раніше.","ru":"Разрешено, но после опережения необходимо вернуться на полосу, которую он занимал ранее.","w":{"uk":"Червоний Х-подібний сигнал забороняє будь-який рух реверсивною смугою, навіть короткочасний для випередження.","ru":"Красный Х-образный сигнал запрещает любое движение по реверсивной полосе, даже кратковременное для опережения."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":1,"e":{"uk":"Ліворуч від червоного автомобіля — реверсивна смуга, а реверсивні світлофори над нею показують червоний Х-подібний сигнал, який забороняє рух по цій смузі ({p:8.7}). Виїжджати на неї для випередження не можна.","ru":"Слева от красного автомобиля — реверсивная полоса, а реверсивные светофоры над ней показывают красный Х-образный сигнал, запрещающий движение по этой полосе ({p:8.7}). Выезжать на неё для опережения нельзя."},"ref":["8.7"],"pic":["img/hsc/8.1-64-1.jpg"]},{"id":"h8.1-65","t":"h8.1","num":"8.1.65","q":{"uk":"За якої умови водій автомобіля може виконати поворот праворуч у даній ситуації?","ru":"При каком условии водитель автомобиля может выполнить поворот направо в данной ситуации?"},"a":[{"uk":"Тільки в разі ввімкнення зеленого сигналу світлофора.","ru":"Только при включении зелёного сигнала светофора.","w":{"uk":"Табличка із зеленою стрілкою дозволяє повертати праворуч і на червоний сигнал, пропустивши інших учасників руху.","ru":"Табличка с зелёной стрелкой разрешает поворачивать направо и на красный сигнал, пропустив других участников движения."}},{"uk":"У разі ввімкнення зеленого сигналу світлофора, а також при ввімкненому червоному сигналі, але за умови надання переваги в русі іншим учасникам.","ru":"При включении зелёного сигнала светофора, а также при включённом красном сигнале, но при условии предоставления преимущества в движении другим участникам."}],"c":1,"e":{"uk":"На рівні червоного сигналу встановлено табличку із зеленою стрілкою праворуч: вона дозволяє поворот праворуч і при червоному сигналі з крайньої правої смуги за умови надання переваги іншим учасникам руху, що рухаються на дозвільний сигнал ({p:8.7}, {p:16.9}). На зелений же поворот дозволено звичайним порядком.","ru":"На уровне красного сигнала установлена табличка с зелёной стрелкой направо: она разрешает поворот направо и при красном сигнале из крайней правой полосы при условии предоставления преимущества другим участникам движения, движущимся на разрешающий сигнал ({p:8.7}, {p:16.9}). На зелёный же поворот разрешён в обычном порядке."},"ref":["8.7","16.9"],"pic":["img/hsc/8.1-65-1.jpg"]},{"id":"h8.1-66","t":"h8.1","num":"8.1.66","q":{"uk":"У якому напрямку водієві автомобіля дозволено рух у даній ситуації?","ru":"В каком направлении водителю автомобиля разрешено движение в данной ситуации?"},"a":[{"uk":"Рух заборонено.","ru":"Движение запрещено.","w":{"uk":"Табличка із зеленою стрілкою на рівні червоного сигналу дозволяє поворот праворуч.","ru":"Табличка с зелёной стрелкой на уровне красного сигнала разрешает поворот направо."}},{"uk":"Праворуч, ввімкнувши покажчик правого повороту (за умови надання переваги в русі іншим учасникам).","ru":"Направо, включив указатель правого поворота (при условии предоставления преимущества в движении другим участникам)."},{"uk":"Ліворуч.","ru":"Налево.","w":{"uk":"Червоний сигнал забороняє рух ліворуч, а табличка дозволяє лише праворуч.","ru":"Красный сигнал запрещает движение налево, а табличка разрешает только направо."}}],"c":1,"e":{"uk":"Горить червоний сигнал, але на його рівні встановлено табличку із зеленою стрілкою праворуч — з крайньої правої смуги можна повернути праворуч, надавши перевагу учасникам, які рухаються з інших напрямків ({p:8.7}, {p:16.9}). Перед поворотом треба ввімкнути покажчик правого повороту ({p:9.2}).","ru":"Горит красный сигнал, но на его уровне установлена табличка с зелёной стрелкой направо — из крайней правой полосы можно повернуть направо, предоставив преимущество участникам, движущимся с других направлений ({p:8.7}, {p:16.9}). Перед поворотом нужно включить указатель правого поворота ({p:9.2})."},"ref":["8.7","16.9","9.2"],"pic":["img/hsc/8.1-66-1.jpg"]},{"id":"h8.1-67","t":"h8.1","num":"8.1.67","q":{"uk":"Що означають два червоні поперемінно миготливі сигнали даного світлофора?","ru":"Что означают два красных попеременно мигающих сигнала данного светофора?"},"a":[{"uk":"Рух заборонено.","ru":"Движение запрещено."},{"uk":"Рух не заборонено, але наближається поїзд, якому необхідно дати дорогу.","ru":"Движение не запрещено, но приближается поезд, которому необходимо уступить дорогу.","w":{"uk":"Миготливі червоні сигнали не просто попереджають про поїзд — вони прямо забороняють в'їзд на переїзд.","ru":"Мигающие красные сигналы не просто предупреждают о поезде — они прямо запрещают въезд на переезд."}},{"uk":"Слід бути особливо уважним на даній ділянці дороги.","ru":"Следует быть особенно внимательным на данном участке дороги.","w":{"uk":"Підвищену увагу означає жовтий миготливий сигнал; червоні миготливі — це заборона руху.","ru":"Повышенное внимание означает жёлтый мигающий сигнал; красные мигающие — это запрет движения."}}],"c":0,"e":{"uk":"Це світлофор залізничного переїзду з одним біло-місячним і двома червоними сигналами: миготливі червоні сигнали забороняють рух транспортних засобів через переїзд ({p:8.7}).","ru":"Это светофор железнодорожного переезда с одним бело-лунным и двумя красными сигналами: мигающие красные сигналы запрещают движение транспортных средств через переезд ({p:8.7})."},"ref":["8.7","20.5"],"pic":["img/hsc/8.1-67-1.jpg"]},{"id":"h8.1-68","t":"h8.1","num":"8.1.68","q":{"uk":"Увімкнений червоний сигнал світлофора означає, що:","ru":"Включённый красный сигнал светофора означает, что:"},"a":[{"uk":"Рух дозволено тільки праворуч за умови надання переваги в русі іншим учасникам.","ru":"Движение разрешено только направо при условии предоставления преимущества в движении другим участникам.","w":{"uk":"Поворот праворуч на червоний можливий лише тоді, коли є зелена стрілка в додатковій секції чи на табличці; сам червоний сигнал рух забороняє.","ru":"Поворот направо на красный возможен только при наличии зелёной стрелки в дополнительной секции или на табличке; сам красный сигнал движение запрещает."}},{"uk":"Рух заборонено.","ru":"Движение запрещено."},{"uk":"Рух заборонено тільки нерейковим транспортним засобам.","ru":"Движение запрещено только нерельсовым транспортным средствам.","w":{"uk":"Червоний сигнал забороняє рух усім транспортним засобам, які ним керуються, зокрема й трамваям (якщо немає окремого трамвайного світлофора).","ru":"Красный сигнал запрещает движение всем транспортным средствам, которые им руководствуются, в том числе и трамваям (если нет отдельного трамвайного светофора)."}}],"c":1,"e":{"uk":"У світлофорі з горизонтальним розташуванням сигналів червоний — крайній лівий, і саме він горить. За {p:8.7} червоний сигнал (зокрема й миготливий) забороняє рух.","ru":"В светофоре с горизонтальным расположением сигналов красный — крайний левый, и именно он горит. По {p:8.7} красный сигнал (в том числе и мигающий) запрещает движение."},"ref":["8.7"],"pic":["img/hsc/8.1-68-1.jpg"]},{"id":"h8.1-69","t":"h8.1","num":"8.1.69","q":{"uk":"У якому випадку заборонено в'їжджати на реверсивну смугу?","ru":"В каком случае запрещено въезжать на реверсивную полосу?"},"a":[{"uk":"Коли на реверсивному світлофорі горить червоний сигнал.","ru":"Когда на реверсивном светофоре горит красный сигнал.","w":{"uk":"Це лише один випадок: в'їзд заборонено й тоді, коли реверсивний світлофор вимкнений.","ru":"Это лишь один случай: въезд запрещён и тогда, когда реверсивный светофор выключен."}},{"uk":"Коли реверсивний світлофор вимкнений.","ru":"Когда реверсивный светофор выключен.","w":{"uk":"Це лише один випадок: в'їзд заборонено й при червоному сигналі реверсивного світлофора.","ru":"Это лишь один случай: въезд запрещён и при красном сигнале реверсивного светофора."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2."}],"c":2,"e":{"uk":"Червоний Х-подібний сигнал реверсивного світлофора забороняє рух по смузі, над якою він розташований, а при вимкнених сигналах реверсивного світлофора над смугою, позначеною розміткою {m:1.9}, в'їзд на неї теж заборонено ({p:8.7}).","ru":"Красный Х-образный сигнал реверсивного светофора запрещает движение по полосе, над которой он расположен, а при выключенных сигналах реверсивного светофора над полосой, обозначенной разметкой {m:1.9}, въезд на неё тоже запрещён ({p:8.7})."},"ref":["8.7"]},{"id":"h8.1-70","t":"h8.1","num":"8.1.70","q":{"uk":"Знаки якої групи інформують учасників дорожнього руху про розташування населених пунктів, різних об'єктів, територій, де діють спеціальні правила?","ru":"Знаки какой группы информируют участников дорожного движения о расположении населённых пунктов, различных объектов, территорий, где действуют специальные правила?"},"a":[{"uk":"Попереджувальні знаки.","ru":"Предупреждающие знаки.","w":{"uk":"Попереджувальні знаки інформують про наближення до небезпечної ділянки дороги та характер небезпеки.","ru":"Предупреждающие знаки информируют о приближении к опасному участку дороги и характере опасности."}},{"uk":"Знаки пріоритету.","ru":"Знаки приоритета.","w":{"uk":"Знаки пріоритету встановлюють черговість проїзду перехресть, перехрещень проїзних частин або вузьких ділянок дороги.","ru":"Знаки приоритета устанавливают очерёдность проезда перекрёстков, пересечений проезжих частей или узких участков дороги."}},{"uk":"Заборонні знаки.","ru":"Запрещающие знаки.","w":{"uk":"Заборонні знаки запроваджують або скасовують певні обмеження в русі.","ru":"Запрещающие знаки вводят или отменяют определённые ограничения движения."}},{"uk":"Наказові знаки.","ru":"Предписывающие знаки.","w":{"uk":"Наказові знаки показують обов'язкові напрямки руху або дозволяють окремим учасникам рух певними ділянками.","ru":"Предписывающие знаки показывают обязательные направления движения или разрешают отдельным участникам движение по определённым участкам."}},{"uk":"Інформаційно-вказівні знаки.","ru":"Информационно-указательные знаки."}],"c":4,"e":{"uk":"За {p:8.4} саме інформаційно-вказівні знаки запроваджують або скасовують певний режим руху, а також інформують про розташування населених пунктів, різних об'єктів і територій, де діють спеціальні правила.","ru":"По {p:8.4} именно информационно-указательные знаки вводят или отменяют определённый режим движения, а также информируют о расположении населённых пунктов, различных объектов и территорий, где действуют специальные правила."},"ref":["8.4"]},{"id":"h8.1-71","t":"h8.1","num":"8.1.71","q":{"uk":"Згідно з Правилами дорожнього руху регулювальником вважається...","ru":"Согласно Правилам дорожного движения регулировщиком считается..."},"a":[{"uk":"Працівник дорожньо-експлуатаційної служби, який має відповідне посвідчення і нарукавну пов’язку, жезл, диск з червоним сигналом чи світлоповертачем, червоний ліхтар або прапорець і виконує регулювання у форменому одязі.","ru":"Работник дорожно-эксплуатационной службы, имеющий соответствующее удостоверение и нарукавную повязку, жезл, диск с красным сигналом или световозвращателем, красный фонарь или флажок и осуществляющий регулирование в форменной одежде.","w":{"uk":"Працівник дорожньо-експлуатаційної служби — лише одна з категорій, прирівняних до регулювальника.","ru":"Работник дорожно-эксплуатационной службы — лишь одна из категорий, приравненных к регулировщику."}},{"uk":"Працівник військової інспекції безпеки дорожнього руху, який має відповідне посвідчення і нарукавну пов’язку, жезл, диск з червоним сигналом чи світлоповертачем, червоний ліхтар або прапорець і виконує регулювання у форменому одязі.","ru":"Работник военной инспекции безопасности дорожного движения, имеющий соответствующее удостоверение и нарукавную повязку, жезл, диск с красным сигналом или световозвращателем, красный фонарь или флажок и осуществляющий регулирование в форменной одежде.","w":{"uk":"Працівник військової інспекції — лише одна з категорій, прирівняних до регулювальника.","ru":"Работник военной инспекции — лишь одна из категорий, приравненных к регулировщику."}},{"uk":"Поліцейський, що виконує регулювання дорожнього руху у форменому одязі підвищеної видимості з елементами із світлоповертального матеріалу за допомогою жезлу, свистка.","ru":"Полицейский, осуществляющий регулирование дорожного движения в форменной одежде повышенной видимости с элементами из световозвращающего материала с помощью жезла, свистка.","w":{"uk":"Поліцейський — основний, але не єдиний регулювальник: до нього прирівнюються й інші особи.","ru":"Полицейский — основной, но не единственный регулировщик: к нему приравниваются и другие лица."}},{"uk":"Черговий на залізничному переїзді і поромній переправі, який має відповідне посвідчення і нарукавну пов’язку, жезл, диск з червоним сигналом чи світлоповертачем, червоний ліхтар або прапорець і виконує регулювання у форменому одязі.","ru":"Дежурный на железнодорожном переезде и паромной переправе, имеющий соответствующее удостоверение и нарукавную повязку, жезл, диск с красным сигналом или световозвращателем, красный фонарь или флажок и осуществляющий регулирование в форменной одежде.","w":{"uk":"Черговий на переїзді чи поромній переправі — лише одна з категорій, прирівняних до регулювальника.","ru":"Дежурный на переезде или паромной переправе — лишь одна из категорий, приравненных к регулировщику."}},{"uk":"Відповіді 1, 2, 3 і 4.","ru":"Ответы 1, 2, 3 и 4."}],"c":4,"e":{"uk":"За визначенням у {p:1.10} регулювальник — це поліцейський, що регулює рух у форменому одязі підвищеної видимості, а до регулювальника прирівнюються працівники військової інспекції безпеки дорожнього руху, дорожньо-експлуатаційної служби, чергові на залізничному переїзді й поромній переправі з відповідним посвідченням і атрибутами. Тож правильні всі чотири варіанти.","ru":"По определению в {p:1.10} регулировщик — это полицейский, регулирующий движение в форменной одежде повышенной видимости, а к регулировщику приравниваются работники военной инспекции безопасности дорожного движения, дорожно-эксплуатационной службы, дежурные на железнодорожном переезде и паромной переправе с соответствующим удостоверением и атрибутами. Поэтому верны все четыре варианта."},"ref":["1.10"]},{"id":"h8.1-72","t":"h8.1","num":"8.1.72","q":{"uk":"Яких видів буває дорожня розмітка?","ru":"Какой бывает дорожная разметка?"},"a":[{"uk":"Горизонтальна.","ru":"Горизонтальная.","w":{"uk":"Крім горизонтальної, є ще вертикальна розмітка.","ru":"Кроме горизонтальной, есть ещё вертикальная разметка."}},{"uk":"Вертикальна.","ru":"Вертикальная.","w":{"uk":"Крім вертикальної, є ще горизонтальна розмітка.","ru":"Кроме вертикальной, есть ещё горизонтальная разметка."}},{"uk":"Діагональна.","ru":"Диагональная.","w":{"uk":"Діагональної розмітки як окремого виду Правила не передбачають.","ru":"Диагональной разметки как отдельного вида Правила не предусматривают."}},{"uk":"Горизонтальна і вертикальна.","ru":"Горизонтальная и вертикальная."}],"c":3,"e":{"uk":"За {p:8.5} дорожня розмітка поділяється на горизонтальну і вертикальну.","ru":"По {p:8.5} дорожная разметка делится на горизонтальную и вертикальную."},"ref":["8.5"]},{"id":"h8.1-73","t":"h8.1","num":"8.1.73","q":{"uk":"У якому місці водій повинен зупинити свій транспортний засіб у разі ввімкнення заборонного сигналу світлофора або підняття регулювальником руки вгору?","ru":"В каком месте водитель должен остановить своё транспортное средство при включении запрещающего сигнала светофора или поднятии регулировщиком руки вверх?"},"a":[{"uk":"Перед дорожньою розміткою «Стоп-лінія».","ru":"Перед дорожной разметкой «Стоп-линия».","w":{"uk":"Стоп-лінія — лише одне з місць зупинки, названих у {p:8.10}.","ru":"Стоп-линия — лишь одно из мест остановки, названных в {p:8.10}."}},{"uk":"Перед дорожнім знаком «Місце зупинки».","ru":"Перед дорожным знаком «Место остановки».","w":{"uk":"Знак «Місце зупинки» — лише одне з місць зупинки, названих у {p:8.10}.","ru":"Знак «Место остановки» — лишь одно из мест остановки, названных в {p:8.10}."}},{"uk":"Перед світлофором або пішохідним переходом за відсутності розмітки «Стоп-лінія» і знака «Місце зупинки».","ru":"Перед светофором или пешеходным переходом при отсутствии разметки «Стоп-линия» и знака «Место остановки».","w":{"uk":"Це місце зупинки застосовується лише за відсутності стоп-лінії та знака; правильна відповідь охоплює всі три випадки.","ru":"Это место остановки применяется лишь при отсутствии стоп-линии и знака; правильный ответ охватывает все три случая."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3."}],"c":3,"e":{"uk":"{p:8.10} визначає всі ці місця: перед стоп-лінією {m:1.12}, знаком {s:5.69}, а якщо їх немає — перед світлофором чи пішохідним переходом (а в інших випадках — перед перехрещуваною проїзною частиною).","ru":"{p:8.10} определяет все эти места: перед стоп-линией {m:1.12}, знаком {s:5.69}, а если их нет — перед светофором или пешеходным переходом (а в остальных случаях — перед пересекаемой проезжей частью)."},"ref":["8.10"]},{"id":"h8.1-74","t":"h8.1","num":"8.1.74","q":{"uk":"Знаки якої групи вказують обов'язкові напрямки руху або дозволяють деяким учасникам рух по проїзній частині чи на окремих її ділянках, а також запроваджують або скасовують деякі обмеження?","ru":"Знаки какой группы указывают обязательные направления движения или разрешают некоторым участникам движение по проезжей части или отдельным её участкам, а также вводят или отменяют некоторые ограничения?"},"a":[{"uk":"Попереджувальні знаки.","ru":"Предупреждающие знаки.","w":{"uk":"Попереджувальні знаки лише інформують про небезпечну ділянку і характер небезпеки.","ru":"Предупреждающие знаки лишь информируют об опасном участке и характере опасности."}},{"uk":"Знаки пріоритету.","ru":"Знаки приоритета.","w":{"uk":"Знаки пріоритету встановлюють черговість проїзду, а не обов'язкові напрямки руху.","ru":"Знаки приоритета устанавливают очерёдность проезда, а не обязательные направления движения."}},{"uk":"Наказові знаки.","ru":"Предписывающие знаки."},{"uk":"Інформаційно-вказівні знаки.","ru":"Информационно-указательные знаки.","w":{"uk":"Інформаційно-вказівні знаки запроваджують чи скасовують режим руху й інформують про об'єкти, але не вказують обов'язкових напрямків.","ru":"Информационно-указательные знаки вводят или отменяют режим движения и информируют об объектах, но не указывают обязательных направлений."}}],"c":2,"e":{"uk":"Це дослівний опис наказових знаків з {p:8.4}.","ru":"Это дословное описание предписывающих знаков из {p:8.4}."},"ref":["8.4"]},{"id":"h8.1-75","t":"h8.1","num":"8.1.75","q":{"uk":"Як повинен вчинити водій транспортного засобу, якщо від поліцейського надійшла вимога про зупинку?","ru":"Как должен поступить водитель транспортного средства, если от полицейского поступило требование об остановке?"},"a":[{"uk":"Зупинити свій транспортний засіб у будь-якому місці.","ru":"Остановить своё транспортное средство в любом месте.","w":{"uk":"Зупинятися будь-де не можна: місце вказує поліцейський, і зупинка має відповідати правилам.","ru":"Останавливаться где угодно нельзя: место указывает полицейский, и остановка должна соответствовать правилам."}},{"uk":"Зупинити свій транспортний засіб у місці, на яке йому буде вказано, з дотриманням правил зупинки.","ru":"Остановить своё транспортное средство в месте, которое ему укажут, с соблюдением правил остановки."}],"c":1,"e":{"uk":"За {p:8.9} водій повинен зупинити транспортний засіб у вказаному місці з дотриманням правил зупинки.","ru":"По {p:8.9} водитель должен остановить транспортное средство в указанном месте с соблюдением правил остановки."},"ref":["8.9"]},{"id":"h8.1-76","t":"h8.1","num":"8.1.76","q":{"uk":"За допомогою чого поліцейські можуть подавати вимогу про зупинку транспортного засобу?","ru":"С помощью чего полицейские могут подавать требование об остановке транспортного средства?"},"a":[{"uk":"Сигнального диска з червоним сигналом чи світлоповертачем або руки, що вказують на відповідний транспортний засіб та подальше місце його зупинки.","ru":"Сигнального диска с красным сигналом или световозвращателем или руки, указывающих на соответствующее транспортное средство и дальнейшее место его остановки.","w":{"uk":"Диск чи рука — лише один із чотирьох способів, названих у {p:8.9}.","ru":"Диск или рука — лишь один из четырёх способов, названных в {p:8.9}."}},{"uk":"Увімкненого проблискового маячка синього і червоного або лише червоного кольору та (або) спеціального звукового сигналу.","ru":"Включённого проблескового маячка синего и красного или только красного цвета и (или) специального звукового сигнала.","w":{"uk":"Проблисковий маячок — лише один із чотирьох способів, названих у {p:8.9}.","ru":"Проблесковый маячок — лишь один из четырёх способов, названных в {p:8.9}."}},{"uk":"Гучномовного пристрою.","ru":"Громкоговорящего устройства.","w":{"uk":"Гучномовний пристрій — лише один із чотирьох способів, названих у {p:8.9}.","ru":"Громкоговорящее устройство — лишь один из четырёх способов, названных в {p:8.9}."}},{"uk":"Спеціального табло, на якому зазначається вимога про зупинку транспортного засобу.","ru":"Специального табло, на котором указывается требование об остановке транспортного средства.","w":{"uk":"Спеціальне табло — лише один із чотирьох способів, названих у {p:8.9}.","ru":"Специальное табло — лишь один из четырёх способов, названных в {p:8.9}."}},{"uk":"Будь-якого з перелічених вище засобів.","ru":"Любого из перечисленных выше средств."}],"c":4,"e":{"uk":"{p:8.9} перелічує всі чотири способи: сигнальний диск або рука, проблисковий маячок і (або) спеціальний звуковий сигнал, гучномовний пристрій і спеціальне табло.","ru":"{p:8.9} перечисляет все четыре способа: сигнальный диск или рука, проблесковый маячок и (или) специальный звуковой сигнал, громкоговорящее устройство и специальное табло."},"ref":["8.9"]},{"id":"h8.1-77","t":"h8.1","num":"8.1.77","q":{"uk":"Знаки якої групи запроваджують або скасовують обмеження в русі на проїзній частині?","ru":"Знаки какой группы вводят или отменяют ограничения движения на проезжей части?"},"a":[{"uk":"Попереджувальні знаки.","ru":"Предупреждающие знаки.","w":{"uk":"Попереджувальні знаки обмежень не вводять — вони попереджають про небезпеку.","ru":"Предупреждающие знаки ограничений не вводят — они предупреждают об опасности."}},{"uk":"Знаки пріоритету.","ru":"Знаки приоритета.","w":{"uk":"Знаки пріоритету встановлюють черговість проїзду, а не обмеження руху.","ru":"Знаки приоритета устанавливают очерёдность проезда, а не ограничения движения."}},{"uk":"Заборонні знаки.","ru":"Запрещающие знаки."},{"uk":"Інформаційно-вказівні знаки.","ru":"Информационно-указательные знаки.","w":{"uk":"Інформаційно-вказівні знаки запроваджують чи скасовують режим руху й інформують, але обмеження вводять саме заборонні знаки.","ru":"Информационно-указательные знаки вводят или отменяют режим движения и информируют, но ограничения вводят именно запрещающие знаки."}}],"c":2,"e":{"uk":"За {p:8.4} заборонні знаки запроваджують або скасовують певні обмеження в русі.","ru":"По {p:8.4} запрещающие знаки вводят или отменяют определённые ограничения движения."},"ref":["8.4"]},{"id":"h8.1-78","t":"h8.1","num":"8.1.78","q":{"uk":"Зелений миготливий сигнал світлофора означає, що:","ru":"Зелёный мигающий сигнал светофора означает, что:"},"a":[{"uk":"Рух заборонено.","ru":"Движение запрещено.","w":{"uk":"Зелений миготливий ще дозволяє рух; забороняють жовтий і червоний.","ru":"Зелёный мигающий ещё разрешает движение; запрещают жёлтый и красный."}},{"uk":"Рух заборонено, крім випадків, коли для зупинки потрібно вдатися до екстреного гальмування.","ru":"Движение запрещено, кроме случаев, когда для остановки нужно прибегнуть к экстренному торможению.","w":{"uk":"Таке значення має жовтий сигнал (з винятком {p:8.11}), а не зелений миготливий.","ru":"Такое значение имеет жёлтый сигнал (с исключением {p:8.11}), а не зелёный мигающий."}},{"uk":"Рух дозволено, але незабаром буде ввімкнено сигнал, що забороняє рух.","ru":"Движение разрешено, но вскоре будет включён сигнал, запрещающий движение."}],"c":2,"e":{"uk":"За {p:8.7} зелений миготливий сигнал дозволяє рух, але інформує, що незабаром буде ввімкнено сигнал, який забороняє рух.","ru":"По {p:8.7} зелёный мигающий сигнал разрешает движение, но информирует, что вскоре будет включён сигнал, запрещающий движение."},"ref":["8.7"]},{"id":"h8.1-79","t":"h8.1","num":"8.1.79","q":{"uk":"Яким способом водій може бути проінформований про перемикання зеленого сигналу світлофора?","ru":"Каким способом водитель может быть проинформирован о переключении зелёного сигнала светофора?"},"a":[{"uk":"Миготінням зеленого сигналу світлофора.","ru":"Миганием зелёного сигнала светофора.","w":{"uk":"Миготіння — лише один зі способів; Правила передбачають і цифрові табло.","ru":"Мигание — лишь один из способов; Правила предусматривают и цифровые табло."}},{"uk":"Цифровими табло.","ru":"Цифровыми табло.","w":{"uk":"Цифрові табло — лише один зі способів; про зміну сигналу інформує й миготіння зеленого.","ru":"Цифровые табло — лишь один из способов; о смене сигнала информирует и мигание зелёного."}},{"uk":"Будь-яким з перелічених вище способів.","ru":"Любым из перечисленных выше способов."}],"c":2,"e":{"uk":"За {p:8.7} про швидке ввімкнення заборонного сигналу інформує зелений миготливий сигнал, а для інформування про час (у секундах), що залишився до кінця горіння зеленого, можуть застосовуватися цифрові табло.","ru":"По {p:8.7} о скором включении запрещающего сигнала информирует зелёный мигающий сигнал, а для информирования о времени (в секундах), оставшемся до окончания горения зелёного, могут применяться цифровые табло."},"ref":["8.7"]},{"id":"h8.1-80","t":"h8.1","num":"8.1.80","q":{"uk":"Чим Ви як водій повинні керуватися, якщо сигнали, які подає регулювальник, суперечать сигналам світлофора?","ru":"Чем Вы как водитель должны руководствоваться, если сигналы, подаваемые регулировщиком, противоречат сигналам светофора?"},"a":[{"uk":"Сигналами світлофора.","ru":"Сигналами светофора.","w":{"uk":"Сигнали світлофора поступаються сигналам регулювальника.","ru":"Сигналы светофора уступают сигналам регулировщика."}},{"uk":"Сигналами регулювальника.","ru":"Сигналами регулировщика."},{"uk":"Вимогами дорожніх знаків пріоритету.","ru":"Требованиями дорожных знаков приоритета.","w":{"uk":"Знаки пріоритету поступаються і сигналам світлофора, і тим паче сигналам регулювальника.","ru":"Знаки приоритета уступают и сигналам светофора, и тем более сигналам регулировщика."}},{"uk":"Правилами проїзду нерегульованих перехресть.","ru":"Правилами проезда нерегулируемых перекрёстков.","w":{"uk":"Перехрестя, де працює регулювальник, є регульованим ({p:16.1}), тож правила нерегульованих перехресть тут не застосовуються.","ru":"Перекрёсток, где работает регулировщик, является регулируемым ({p:16.1}), поэтому правила нерегулируемых перекрёстков здесь не применяются."}}],"c":1,"e":{"uk":"Сигнали регулювальника мають перевагу перед сигналами світлофорів і вимогами дорожніх знаків та є обов'язковими для виконання ({p:8.3}).","ru":"Сигналы регулировщика имеют преимущество перед сигналами светофоров и требованиями дорожных знаков и являются обязательными для выполнения ({p:8.3})."},"ref":["8.3"]},{"id":"h8.1-81","t":"h8.1","num":"8.1.81","q":{"uk":"Для чого служить сигнал регулювальника, що подається свистком?","ru":"Для чего служит сигнал регулировщика, подаваемый свистком?"},"a":[{"uk":"Для привернення уваги водіїв транспортних засобів.","ru":"Для привлечения внимания водителей транспортных средств.","w":{"uk":"Свисток привертає увагу не лише водіїв, а всіх учасників дорожнього руху.","ru":"Свисток привлекает внимание не только водителей, а всех участников дорожного движения."}},{"uk":"Для привернення уваги пішоходів.","ru":"Для привлечения внимания пешеходов.","w":{"uk":"Свисток привертає увагу не лише пішоходів, а всіх учасників дорожнього руху.","ru":"Свисток привлекает внимание не только пешеходов, а всех участников дорожного движения."}},{"uk":"Для попередження про зміну положення корпуса.","ru":"Для предупреждения об изменении положения корпуса.","w":{"uk":"Правила не пов'язують свисток зі зміною положення корпуса — він служить для привернення уваги.","ru":"Правила не связывают свисток с изменением положения корпуса — он служит для привлечения внимания."}},{"uk":"Для привернення уваги учасників дорожнього руху.","ru":"Для привлечения внимания участников дорожного движения."}],"c":3,"e":{"uk":"За {p:8.8} сигнал, що подається свистком, використовують для привернення уваги **учасників дорожнього руху** — і водіїв, і пішоходів.","ru":"По {p:8.8} сигнал, подаваемый свистком, используется для привлечения внимания **участников дорожного движения** — и водителей, и пешеходов."},"ref":["8.8"]},{"id":"h8.1-82","t":"h8.1","num":"8.1.82","q":{"uk":"Якщо сигнал регулювальника відрізняється від сигналу світлофора, Ви будете керуватись сигналами регулювальника:","ru":"Если сигнал регулировщика отличается от сигнала светофора, Вы будете руководствоваться сигналами регулировщика:"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"За розбіжності сигналів пріоритет має регулювальник, а не світлофор.","ru":"При расхождении сигналов приоритет имеет регулировщик, а не светофор."}}],"c":0,"e":{"uk":"Сигнали регулювальника мають перевагу перед сигналами світлофора ({p:8.3}), тож виконувати треба саме їх.","ru":"Сигналы регулировщика имеют преимущество перед сигналами светофора ({p:8.3}), поэтому выполнять нужно именно их."},"ref":["8.3"]},{"id":"h8.1-83","t":"h8.1","num":"8.1.83","q":{"uk":"Сигнал світлофора відрізняється від сигналу регулювальника. Ви будете користуватись сигналом світлофора:","ru":"Сигнал светофора отличается от сигнала регулировщика. Вы будете руководствоваться сигналом светофора:"},"a":[{"uk":"Так.","ru":"Да.","w":{"uk":"Світлофор поступається регулювальнику: якщо їхні сигнали різні, діє сигнал регулювальника.","ru":"Светофор уступает регулировщику: если их сигналы различаются, действует сигнал регулировщика."}},{"uk":"Ні.","ru":"Нет."}],"c":1,"e":{"uk":"Сигнали регулювальника мають перевагу перед сигналами світлофора ({p:8.3}), тому за розбіжності керуватися треба регулювальником, а не світлофором.","ru":"Сигналы регулировщика имеют преимущество перед сигналами светофора ({p:8.3}), поэтому при расхождении руководствоваться нужно регулировщиком, а не светофором."},"ref":["8.3"]},{"id":"h8.1-84","t":"h8.1","num":"8.1.84","q":{"uk":"Сигнал, який показує регулювальник відрізняється від вимог дорожніх знаків. Дорожні знаки є пріоритетними в цьому випадку:","ru":"Сигнал, который показывает регулировщик, отличается от требований дорожных знаков. Дорожные знаки в этом случае являются приоритетными:"},"a":[{"uk":"Так.","ru":"Да.","w":{"uk":"Дорожні знаки поступаються сигналам регулювальника, а не навпаки.","ru":"Дорожные знаки уступают сигналам регулировщика, а не наоборот."}},{"uk":"Ні.","ru":"Нет."}],"c":1,"e":{"uk":"Сигнали регулювальника мають перевагу і над вимогами дорожніх знаків ({p:8.3}), тож пріоритет за регулювальником.","ru":"Сигналы регулировщика имеют преимущество и перед требованиями дорожных знаков ({p:8.3}), поэтому приоритет за регулировщиком."},"ref":["8.3"]},{"id":"h8.2-1","t":"h8.2","num":"8.2.1","q":{"uk":"У якому напрямку Вам дозволено рух?","ru":"В каком направлении вам разрешено движение?"},"a":[{"uk":"У напрямку А.","ru":"В направлении А."},{"uk":"У напрямках А і В.","ru":"В направлениях А и В.","w":{"uk":"Розворот (В) дозволяв би постійний знак {s:5.29}, але його скасовує тимчасовий знак {s:4.1}, що має перевагу ({p:8.2}).","ru":"Разворот (В) разрешал бы постоянный знак {s:5.29}, но его отменяет временный знак {s:4.1}, имеющий преимущество ({p:8.2})."}},{"uk":"У напрямках Б і В.","ru":"В направлениях Б и В.","w":{"uk":"Знак {s:4.1} дозволяє рух лише прямо, тож ні поворот ліворуч (Б), ні розворот (В) тут не дозволені ({p:33.4}).","ru":"Знак {s:4.1} разрешает движение только прямо, поэтому ни поворот налево (Б), ни разворот (В) здесь не разрешены ({p:33.4})."}},{"uk":"У напрямках А, Б і В.","ru":"В направлениях А, Б и В.","w":{"uk":"Знак {s:4.1} дозволяє рух лише прямо, тож напрямки Б і В заборонені ({p:33.4}).","ru":"Знак {s:4.1} разрешает движение только прямо, поэтому направления Б и В запрещены ({p:33.4})."}},{"uk":"У напрямку В.","ru":"В направлении В.","w":{"uk":"Розворот (В) заборонено тимчасовим знаком {s:4.1}, який має перевагу перед постійним {s:5.29} ({p:8.2}).","ru":"Разворот (В) запрещён временным знаком {s:4.1}, который имеет преимущество перед постоянным {s:5.29} ({p:8.2})."}}],"c":0,"e":{"uk":"У розриві розділювальної смуги стоїть постійний знак {s:5.29} «Місце для розвороту», але перед ним — тимчасовий знак {s:4.1} «Рух прямо» на жовтому щиті. Тимчасові знаки мають перевагу перед постійними ({p:8.2}), тож дозволено лише рух прямо — у напрямку А.","ru":"В разрыве разделительной полосы стоит постоянный знак {s:5.29} «Место для разворота», но перед ним — временный знак {s:4.1} «Движение прямо» на жёлтом щите. Временные знаки имеют преимущество перед постоянными ({p:8.2}), поэтому разрешено только движение прямо — в направлении А."},"ref":["8.2","33.4"],"pic":["img/hsc/8.2-1-1.jpg"]},{"id":"h8.2-2","t":"h8.2","num":"8.2.2","q":{"uk":"На якому малюнку зображено тимчасовий дорожній знак?","ru":"На каком рисунке изображён временный дорожный знак?"},"a":[{"uk":"На малюнку 1.","ru":"На рисунке 1."},{"uk":"На малюнку 2.","ru":"На рисунке 2.","w":{"uk":"Знак {s:5.29} «Місце для розвороту» на малюнку 2 — звичайний постійний знак без жовтого щита.","ru":"Знак {s:5.29} «Место для разворота» на рисунке 2 — обычный постоянный знак без жёлтого щита."}},{"uk":"На малюнку 3.","ru":"На рисунке 3.","w":{"uk":"Знак {s:3.23} «Поворот ліворуч заборонено» на малюнку 3 — постійний, без жовтого щита; регулювальник поруч не робить знак тимчасовим.","ru":"Знак {s:3.23} «Поворот налево запрещён» на рисунке 3 — постоянный, без жёлтого щита; регулировщик рядом не делает знак временным."}}],"c":0,"e":{"uk":"За {p:8.2} тимчасові знаки розміщують на переносних пристроях, дорожньому обладнанні або закріплюють на щиті з **жовтим фоном**. Саме так встановлено знак {s:4.2} «Рух праворуч» на малюнку 1.","ru":"Согласно {p:8.2} временные знаки размещают на переносных устройствах, дорожном оборудовании или закрепляют на щите с **жёлтым фоном**. Именно так установлен знак {s:4.2} «Движение направо» на рисунке 1."},"ref":["8.2"],"pic":["img/hsc/8.2-2-1.jpg"]},{"id":"h8.2-3","t":"h8.2","num":"8.2.3","q":{"uk":"Яке значення має жовтий миготливий сигнал світлофора в даній ситуації?","ru":"Какое значение имеет жёлтый мигающий сигнал светофора в данной ситуации?"},"a":[{"uk":"Забороняє рух транспортних засобів.","ru":"Запрещает движение транспортных средств.","w":{"uk":"Рух забороняють червоний і немиготливий жовтий сигнали, а жовтий миготливий рух дозволяє ({p:8.7}).","ru":"Движение запрещают красный и немигающий жёлтый сигналы, а жёлтый мигающий движение разрешает ({p:8.7})."}},{"uk":"Дозволяє рух й інформує про наявність небезпечного нерегульованого перехрестя.","ru":"Разрешает движение и информирует о наличии опасного нерегулируемого перекрёстка."},{"uk":"Вимагає від водіїв обов'язкової зупинки.","ru":"Требует от водителей обязательной остановки.","w":{"uk":"Обов'язкову зупинку вимагає знак {s:2.2} «Проїзд без зупинки заборонено», а тут встановлено {s:2.1}: зупинятися треба лише тоді, коли потрібно дати дорогу.","ru":"Обязательную остановку требует знак {s:2.2} «Проезд без остановки запрещён», а здесь установлен {s:2.1}: останавливаться нужно только тогда, когда нужно уступить дорогу."}}],"c":1,"e":{"uk":"Жовтий миготливий сигнал дозволяє рух і інформує про небезпечне нерегульоване перехрестя ({p:8.7}). Переваги над знаками пріоритету він не має ({p:8.3}), тож черговість проїзду тут визначає знак {s:2.1} «Дати дорогу».","ru":"Жёлтый мигающий сигнал разрешает движение и информирует об опасном нерегулируемом перекрёстке ({p:8.7}). Преимущества над знаками приоритета он не имеет ({p:8.3}), поэтому очерёдность проезда здесь определяет знак {s:2.1} «Уступить дорогу»."},"ref":["8.3","8.7"],"pic":["img/hsc/8.2-3-1.jpg"]},{"id":"h8.2-4","t":"h8.2","num":"8.2.4","q":{"uk":"Чим Ви як водій повинні керуватися, якщо вимоги дорожніх знаків суперечать вимогам дорожньої розмітки?","ru":"Чем вы как водитель должны руководствоваться, если требования дорожных знаков противоречат требованиям дорожной разметки?"},"a":[{"uk":"Вимогами дорожньої розмітки.","ru":"Требованиями дорожной разметки.","w":{"uk":"Розмітка лише підкреслює чи уточнює вимоги знаків, а в разі суперечності поступається їм ({p:8.2}).","ru":"Разметка лишь подчёркивает или уточняет требования знаков, а при противоречии уступает им ({p:8.2})."}},{"uk":"Вимогами дорожніх знаків.","ru":"Требованиями дорожных знаков."},{"uk":"На розсуд водія.","ru":"На усмотрение водителя.","w":{"uk":"Черговість вимог встановлюють Правила, а не водій: знаки мають перевагу перед розміткою ({p:8.2}).","ru":"Очерёдность требований устанавливают Правила, а не водитель: знаки имеют преимущество перед разметкой ({p:8.2})."}}],"c":1,"e":{"uk":"{p:8.2}: дорожні знаки мають перевагу перед дорожньою розміткою — тож у разі суперечності керуються знаками.","ru":"{p:8.2}: дорожные знаки имеют преимущество перед дорожной разметкой — поэтому при противоречии руководствуются знаками."},"ref":["8.2"]},{"id":"h8.2-5","t":"h8.2","num":"8.2.5","q":{"uk":"Чим Ви як водій повинні керуватися, якщо вимоги тимчасових дорожніх знаків суперечать вимогам постійних дорожніх знаків?","ru":"Чем вы как водитель должны руководствоваться, если требования временных дорожных знаков противоречат требованиям постоянных дорожных знаков?"},"a":[{"uk":"Тимчасовими дорожніми знаками.","ru":"Временными дорожными знаками."},{"uk":"Постійними дорожніми знаками.","ru":"Постоянными дорожными знаками.","w":{"uk":"Постійні знаки поступаються тимчасовим, які встановлюють на час робіт чи зміни організації руху ({p:8.2}).","ru":"Постоянные знаки уступают временным, которые устанавливают на время работ или изменения организации движения ({p:8.2})."}},{"uk":"Вимогами дорожньої розмітки.","ru":"Требованиями дорожной разметки.","w":{"uk":"Розмітка має найнижчий пріоритет: знаки, і постійні, і тимчасові, мають перевагу перед нею ({p:8.2}).","ru":"Разметка имеет самый низкий приоритет: знаки, и постоянные, и временные, имеют преимущество перед ней ({p:8.2})."}}],"c":0,"e":{"uk":"За {p:8.2} тимчасові дорожні знаки мають перевагу перед постійними: вони відображають поточну ситуацію — ремонт, об'їзд тощо.","ru":"Согласно {p:8.2} временные дорожные знаки имеют преимущество перед постоянными: они отражают текущую ситуацию — ремонт, объезд и т. п."},"ref":["8.2"]},{"id":"h8.2-6","t":"h8.2","num":"8.2.6","q":{"uk":"Як розміщуються тимчасові дорожні знаки?","ru":"Как размещаются временные дорожные знаки?"},"a":[{"uk":"На переносних пристроях і дорожньому обладнанні.","ru":"На переносных устройствах и дорожном оборудовании.","w":{"uk":"Неповна відповідь: тимчасовий знак можна також закріпити на щиті з жовтим фоном ({p:8.2}).","ru":"Неполный ответ: временный знак можно также закрепить на щите с жёлтым фоном ({p:8.2})."}},{"uk":"Закріплюються на щиті з фоном жовтого кольору.","ru":"Закрепляются на щите с фоном жёлтого цвета.","w":{"uk":"Неповна відповідь: тимчасові знаки розміщують також на переносних пристроях і дорожньому обладнанні ({p:8.2}).","ru":"Неполный ответ: временные знаки размещают также на переносных устройствах и дорожном оборудовании ({p:8.2})."}},{"uk":"Встановлюються над постійними дорожніми знаками.","ru":"Устанавливаются над постоянными дорожными знаками.","w":{"uk":"Правила не вимагають розміщувати тимчасові знаки над постійними — їх перевага над постійними не залежить від місця встановлення ({p:8.2}).","ru":"Правила не требуют размещать временные знаки над постоянными — их преимущество перед постоянными не зависит от места установки ({p:8.2})."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3.","w":{"uk":"Варіант 3 неправильний, тож неправильне й поєднання 1, 2 і 3.","ru":"Вариант 3 неверен, поэтому неверно и сочетание 1, 2 и 3."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2."}],"c":4,"e":{"uk":"{p:8.2}: тимчасові знаки розміщуються на переносних пристроях, дорожньому обладнанні або закріплюються на щиті з фоном жовтого кольору — це варіанти 1 і 2.","ru":"{p:8.2}: временные знаки размещаются на переносных устройствах, дорожном оборудовании или закрепляются на щите с фоном жёлтого цвета — это варианты 1 и 2."},"ref":["8.2"]},{"id":"h8.2-7","t":"h8.2","num":"8.2.7","q":{"uk":"Знаки якої групи заздалегідь зобов'язують вжити заходів для безпечного проїзду при наближенні до небезпечної ділянки дороги або іншої небезпеки?","ru":"Знаки какой группы заранее обязывают принять меры для безопасного проезда при приближении к опасному участку дороги или иной опасности?"},"a":[{"uk":"Попереджувальні знаки.","ru":"Предупреждающие знаки."},{"uk":"Знаки сервісу.","ru":"Знаки сервиса.","w":{"uk":"Знаки сервісу інформують про розташування об'єктів обслуговування, а не про небезпеку ({p:8.4}).","ru":"Знаки сервиса информируют о расположении объектов обслуживания, а не об опасности ({p:8.4})."}},{"uk":"Заборонні знаки.","ru":"Запрещающие знаки.","w":{"uk":"Заборонні знаки запроваджують або скасовують обмеження руху, а не попереджають про небезпечну ділянку ({p:8.4}).","ru":"Запрещающие знаки вводят или отменяют ограничения движения, а не предупреждают об опасном участке ({p:8.4})."}},{"uk":"Наказові знаки.","ru":"Предписывающие знаки.","w":{"uk":"Наказові знаки показують обов'язкові напрямки руху чи дозволяють рух окремим категоріям учасників ({p:8.4}).","ru":"Предписывающие знаки показывают обязательные направления движения или разрешают движение отдельным категориям участников ({p:8.4})."}},{"uk":"Інформаційно-вказівні знаки.","ru":"Информационно-указательные знаки.","w":{"uk":"Інформаційно-вказівні знаки запроваджують чи скасовують режим руху й інформують про об'єкти, а не про небезпеку ({p:8.4}).","ru":"Информационно-указательные знаки вводят или отменяют режим движения и информируют об объектах, а не об опасности ({p:8.4})."}}],"c":0,"e":{"uk":"За {p:8.4} саме **попереджувальні** знаки інформують водіїв про наближення до небезпечної ділянки дороги й характер небезпеки, а на цій ділянці треба вжити заходів для безпечного проїзду.","ru":"Согласно {p:8.4} именно **предупреждающие** знаки информируют водителей о приближении к опасному участку дороги и характере опасности, а на этом участке нужно принять меры для безопасного проезда."},"ref":["8.4"]},{"id":"h9-1","t":"h9","num":"9.1","q":{"uk":"Який попереджувальний сигнал вмикається під час руху на всіх транспортних засобах колони у світлий час доби?","ru":"Какой предупредительный сигнал включается во время движения на всех транспортных средствах колонны в светлое время суток?"},"a":[{"uk":"Проблискові маячки оранжевого кольору.","ru":"Проблесковые маячки оранжевого цвета.","w":{"uk":"Проблисковий маячок оранжевого кольору — окремий попереджувальний сигнал ({p:9.1}), а не позначення транспортних засобів колони.","ru":"Проблесковый маячок оранжевого цвета — отдельный предупредительный сигнал ({p:9.1}), а не обозначение транспортных средств колонны."}},{"uk":"Протитуманні фари.","ru":"Противотуманные фары.","w":{"uk":"Протитуманні фари можна вмикати лише додатково в умовах недостатньої видимості; для позначення колони вони не передбачені.","ru":"Противотуманные фары можно включать лишь дополнительно в условиях недостаточной видимости; для обозначения колонны они не предусмотрены."}},{"uk":"Денні ходові вогні.","ru":"Дневные ходовые огни.","w":{"uk":"Денні ходові вогні — загальна вимога для руху поза населеними пунктами, а для колони {p:9.8} прямо вимагає ближнього світла фар.","ru":"Дневные ходовые огни — общее требование для движения вне населённых пунктов, а для колонны {p:9.8} прямо требует ближнего света фар."}},{"uk":"Ближнє світло фар.","ru":"Ближний свет фар."},{"uk":"Ближнє світло фар або денні ходові вогні.","ru":"Ближний свет фар или дневные ходовые огни.","w":{"uk":"Вибору тут немає: на транспортних засобах колони має бути ввімкнене саме ближнє світло, денні ходові вогні його не замінюють.","ru":"Выбора здесь нет: на транспортных средствах колонны должен быть включён именно ближний свет, дневные ходовые огни его не заменяют."}}],"c":3,"e":{"uk":"На малюнку — розпізнавальний знак «Колона» ({p:30.3}). За {p:9.8} (підпункт «а») і {p:25.1} на кожному транспортному засобі колони для позначення під час руху вмикається саме **ближнє світло фар** — денні ходові вогні його тут не замінюють.","ru":"На рисунке — опознавательный знак «Колонна» ({p:30.3}). Согласно {p:9.8} (подпункт «а») и {p:25.1} на каждом транспортном средстве колонны для обозначения во время движения включается именно **ближний свет фар** — дневные ходовые огни его здесь не заменяют."},"ref":["9.8","25.1"],"pic":["img/hsc/9-1-1.jpg"]},{"id":"h9-2","t":"h9","num":"9.2","q":{"uk":"Про що свідчить (може попереджати) знак аварійної зупинки, встановлений ззаду на автомобілі, що рухається?","ru":"О чём свидетельствует (о чём может предупреждать) знак аварийной остановки, установленный сзади на движущемся автомобиле?"},"a":[{"uk":"Транспортний засіб рухається з технічними несправностями (з якими не заборонений подальший рух) до місця ремонту або стоянки.","ru":"Транспортное средство движется с техническими неисправностями (с которыми дальнейшее движение не запрещено) к месту ремонта или стоянки.","w":{"uk":"Це лише один із можливих випадків: так само позначають і транспортний засіб, що буксирується.","ru":"Это лишь один из возможных случаев: так же обозначают и буксируемое транспортное средство."}},{"uk":"Це транспортний засіб, що буксирується.","ru":"Это буксируемое транспортное средство.","w":{"uk":"Це лише один із можливих випадків: так само позначають і транспортний засіб, що рухається з технічними несправностями.","ru":"Это лишь один из возможных случаев: так же обозначают и транспортное средство, движущееся с техническими неисправностями."}},{"uk":"Може попереджати про випадок, указаний у відповіді 1 або у відповіді 2.","ru":"Может предупреждать о случае, указанном в ответе 1 или в ответе 2."}],"c":2,"e":{"uk":"Якщо аварійна сигналізація відсутня або несправна, за {p:9.11} знак аварійної зупинки встановлюють ззаду і на транспортному засобі, що рухається з технічними несправностями, і на транспортному засобі, що буксирується ({p:9.9}, підпункти «в», «г»). Тож знак на вантажівці на малюнку може означати **будь-який** із цих випадків.","ru":"Если аварийная сигнализация отсутствует или неисправна, согласно {p:9.11} знак аварийной остановки устанавливают сзади и на транспортном средстве, движущемся с техническими неисправностями, и на буксируемом транспортном средстве ({p:9.9}, подпункты «в», «г»). Поэтому знак на грузовике на рисунке может означать **любой** из этих случаев."},"ref":["9.9","9.11"],"pic":["img/hsc/9-2-1.jpg"]},{"id":"h9-3","t":"h9","num":"9.3","q":{"uk":"Як позначити транспортний засіб, що буксирується, якщо у нього несправна або відсутня аварійна світлова сигналізація?","ru":"Как обозначить буксируемое транспортное средство, если у него неисправна или отсутствует аварийная световая сигнализация?"},"a":[{"uk":"Установити ззаду на транспортному засобі щитки розміром 40х40 см з нанесеними по діагоналі червоними і білими смугами, що чергуються.","ru":"Установить сзади на транспортном средстве щитки размером 40х40 см с нанесёнными по диагонали чередующимися красными и белыми полосами.","w":{"uk":"Щиток із червоними й білими смугами (перший на малюнку) — це розпізнавальний знак «Негабаритний вантаж» ({p:30.3}), а не заміна аварійної сигналізації.","ru":"Щиток с красными и белыми полосами (первый на рисунке) — это опознавательный знак «Негабаритный груз» ({p:30.3}), а не замена аварийной сигнализации."}},{"uk":"Встановити ззаду на транспортному засобі знак аварійної зупинки, а в умовах недостатньої видимості – миготливий червоний ліхтар.","ru":"Установить сзади на транспортном средстве знак аварийной остановки, а в условиях недостаточной видимости — мигающий красный фонарь.","w":{"uk":"Правила не прив'язують вибір до видимості: ставлять або знак, або ліхтар; до того ж світло ліхтаря має бути добре видно і вдень ({p:9.12}).","ru":"Правила не привязывают выбор к видимости: ставят либо знак, либо фонарь; к тому же свет фонаря должен быть хорошо виден и днём ({p:9.12})."}},{"uk":"Установити ззаду на транспортному засобі знак аварійної зупинки або миготливий червоний ліхтар.","ru":"Установить сзади на транспортном средстве знак аварийной остановки или мигающий красный фонарь."},{"uk":"Виконати вимогу, вказану у відповіді 1 або відповіді 2.","ru":"Выполнить требование, указанное в ответе 1 или в ответе 2.","w":{"uk":"Щитки з варіанта 1 для цього не застосовують, а варіант 2 додає умову щодо видимості, якої в Правилах немає.","ru":"Щитки из варианта 1 для этого не применяют, а вариант 2 добавляет условие о видимости, которого в Правилах нет."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3.","w":{"uk":"Правильний лише варіант 3: щитки з варіанта 1 для позначення транспортного засобу, що буксирується, не застосовують.","ru":"Верен только вариант 3: щитки из варианта 1 для обозначения буксируемого транспортного средства не применяют."}}],"c":2,"e":{"uk":"Транспортний засіб, що буксирується, позначають аварійною сигналізацією ({p:9.9}, «г»), а якщо вона відсутня чи несправна — знаком аварійної зупинки **або** миготливим червоним ліхтарем, установленим ззаду ({p:9.11}, «а»), — це другий і третій предмети на малюнку.","ru":"Буксируемое транспортное средство обозначают аварийной сигнализацией ({p:9.9}, «г»), а если она отсутствует или неисправна — знаком аварийной остановки **или** мигающим красным фонарём, установленным сзади ({p:9.11}, «а»), — это второй и третий предметы на рисунке."},"ref":["9.9","9.11"],"pic":["img/hsc/9-3-1.jpg"]},{"id":"h9-4","t":"h9","num":"9.4","q":{"uk":"Який попереджувальний сигнал вмикається на транспортних засобах колони під час зупинки на дорозі?","ru":"Какой предупредительный сигнал включается на транспортных средствах колонны во время остановки на дороге?"},"a":[{"uk":"Ближнє світло фар.","ru":"Ближний свет фар.","w":{"uk":"Ближнє світло фар позначає транспортні засоби колони під час руху ({p:9.8}), а не під час зупинки.","ru":"Ближний свет фар обозначает транспортные средства колонны во время движения ({p:9.8}), а не во время остановки."}},{"uk":"Габаритні ліхтарі.","ru":"Габаритные огни.","w":{"uk":"Габаритні ліхтарі не є попереджувальним сигналом про зупинку колони; Правила вимагають саме аварійної сигналізації.","ru":"Габаритные огни не являются предупредительным сигналом об остановке колонны; Правила требуют именно аварийной сигнализации."}},{"uk":"Аварійна сигналізація.","ru":"Аварийная сигнализация."}],"c":2,"e":{"uk":"За {p:9.9} (підпункт «д») під час зупинки на дорозі аварійна світлова сигналізація має бути ввімкнена на **всіх** механічних транспортних засобах колони — як на автобусах зі знаком «Колона» на малюнку.","ru":"Согласно {p:9.9} (подпункт «д») во время остановки на дороге аварийная световая сигнализация должна быть включена на **всех** механических транспортных средствах колонны — как на автобусах со знаком «Колонна» на рисунке."},"ref":["9.9"],"pic":["img/hsc/9-4-1.jpg"]},{"id":"h9-5","t":"h9","num":"9.5","q":{"uk":"На якій відстані від транспортного засобу необхідно встановити знак аварійної зупинки або миготливий червоний ліхтар у випадках, передбачених Правилами дорожнього руху, на дорогах у населених пунктах?","ru":"На каком расстоянии от транспортного средства необходимо установить знак аварийной остановки или мигающий красный фонарь в случаях, предусмотренных Правилами дорожного движения, на дорогах в населённых пунктах?"},"a":[{"uk":"На відстані, що забезпечує безпеку дорожнього руху, але не менше ніж 20 м.","ru":"На расстоянии, обеспечивающем безопасность дорожного движения, но не менее 20 м."},{"uk":"На відстані, що забезпечує безпеку дорожнього руху, але не менше ніж 40 м.","ru":"На расстоянии, обеспечивающем безопасность дорожного движения, но не менее 40 м.","w":{"uk":"40 м — мінімальна відстань поза населеними пунктами, а не в них.","ru":"40 м — минимальное расстояние вне населённых пунктов, а не в них."}},{"uk":"На відстані, що забезпечує безпеку дорожнього руху, але не менше ніж 50 м.","ru":"На расстоянии, обеспечивающем безопасность дорожного движения, но не менее 50 м.","w":{"uk":"Відстані 50 м Правила не встановлюють: у населених пунктах мінімум — 20 м.","ru":"Расстояния 50 м Правила не устанавливают: в населённых пунктах минимум — 20 м."}},{"uk":"На відстані, що забезпечує безпеку дорожнього руху, але не менше ніж 100 м.","ru":"На расстоянии, обеспечивающем безопасность дорожного движения, но не менее 100 м.","w":{"uk":"100 м — це межа обмеженої оглядовості з {p:9.10}, а не відстань до знака.","ru":"100 м — это порог ограниченной обзорности из {p:9.10}, а не расстояние до знака."}}],"c":0,"e":{"uk":"За {p:9.10} знак аварійної зупинки чи миготливий червоний ліхтар ставлять на відстані, що забезпечує безпеку руху, але **не ближче 20 м** до транспортного засобу в населених пунктах (поза ними — 40 м).","ru":"Согласно {p:9.10} знак аварийной остановки или мигающий красный фонарь устанавливают на расстоянии, обеспечивающем безопасность движения, но **не ближе 20 м** от транспортного средства в населённых пунктах (вне их — 40 м)."},"ref":["9.10"],"pic":["img/hsc/9-5-1.jpg"]},{"id":"h9-6","t":"h9","num":"9.6","q":{"uk":"У яких випадках для позначення транспортного засобу потрібно увімкнути аварійну сигналізацію і встановити знак аварійної зупинки або миготливий червоний ліхтар на відстані від транспортного засобу?","ru":"В каких случаях для обозначения транспортного средства нужно включить аварийную сигнализацию и установить знак аварийной остановки или мигающий красный фонарь на расстоянии от транспортного средства?"},"a":[{"uk":"У випадку виникнення дорожньо-транспортної пригоди.","ru":"При дорожно-транспортном происшествии.","w":{"uk":"Неповна відповідь: знак виставляють і під час вимушеної зупинки в місці з обмеженою оглядовістю.","ru":"Неполный ответ: знак выставляют и при вынужденной остановке в месте с ограниченной обзорностью."}},{"uk":"Під час посадки і висадки організованих груп дітей із транспортного засобу, позначеного розпізнавальним знаком «Діти».","ru":"Во время посадки и высадки организованных групп детей из транспортного средства, обозначенного опознавательным знаком «Дети».","w":{"uk":"Під час посадки й висадки дітей вмикають лише аварійну сигналізацію ({p:9.9}, «ґ»); знак аварійної зупинки на відстані не виставляють.","ru":"Во время посадки и высадки детей включают только аварийную сигнализацию ({p:9.9}, «ґ»); знак аварийной остановки на расстоянии не выставляют."}},{"uk":"Під час вимушеної зупинки в місцях з обмеженою оглядовістю дороги (хоча б в одному напрямку менше ніж 100 м).","ru":"При вынужденной остановке в местах с ограниченной обзорностью дороги (хотя бы в одном направлении менее 100 м).","w":{"uk":"Неповна відповідь: знак виставляють також у разі ДТП.","ru":"Неполный ответ: знак выставляют также при ДТП."}},{"uk":"Відповіді 1 і 3.","ru":"Ответы 1 и 3."},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3.","w":{"uk":"Посадка й висадка дітей до випадків із {p:9.10} не належить — там достатньо аварійної сигналізації.","ru":"Посадка и высадка детей к случаям из {p:9.10} не относится — там достаточно аварийной сигнализации."}}],"c":3,"e":{"uk":"{p:9.10} вимагає разом з аварійною сигналізацією виставляти знак аварійної зупинки або миготливий червоний ліхтар (як на малюнку) лише у двох випадках: у разі ДТП і під час вимушеної зупинки там, де оглядовість дороги хоча б в одному напрямку менше 100 м.","ru":"{p:9.10} требует вместе с аварийной сигнализацией выставлять знак аварийной остановки или мигающий красный фонарь (как на рисунке) только в двух случаях: при ДТП и при вынужденной остановке там, где обзорность дороги хотя бы в одном направлении менее 100 м."},"ref":["9.9","9.10"],"pic":["img/hsc/9-6-1.jpg"]},{"id":"h9-7","t":"h9","num":"9.7","q":{"uk":"Як повинен водій позначити місце дорожньо-транспортної пригоди?","ru":"Как должен водитель обозначить место дорожно-транспортного происшествия?"},"a":[{"uk":"Ввімкнути габаритні ліхтарі, а також встановити знак аварійної зупинки.","ru":"Включить габаритные огни, а также установить знак аварийной остановки.","w":{"uk":"Габаритні ліхтарі не замінюють аварійної сигналізації: у разі ДТП вмикають саме її.","ru":"Габаритные огни не заменяют аварийную сигнализацию: при ДТП включают именно её."}},{"uk":"Ввімкнути тільки аварійну сигналізацію","ru":"Включить только аварийную сигнализацию.","w":{"uk":"Однієї аварійної сигналізації недостатньо: у разі ДТП додатково виставляють знак аварійної зупинки чи миготливий червоний ліхтар.","ru":"Одной аварийной сигнализации недостаточно: при ДТП дополнительно выставляют знак аварийной остановки или мигающий красный фонарь."}},{"uk":"Ввімкнути аварійну сигналізацію, а також установити знак аварійної зупинки чи миготливий червоний ліхтар.","ru":"Включить аварийную сигнализацию, а также установить знак аварийной остановки или мигающий красный фонарь."}],"c":2,"e":{"uk":"У разі ДТП водій вмикає аварійну сигналізацію ({p:9.9}, «е») і разом з нею встановлює знак аварійної зупинки або миготливий червоний ліхтар ({p:9.10}, «а»; {p:2.10}).","ru":"При ДТП водитель включает аварийную сигнализацию ({p:9.9}, «е») и вместе с ней устанавливает знак аварийной остановки или мигающий красный фонарь ({p:9.10}, «а»; {p:2.10})."},"ref":["2.10","9.9","9.10"],"pic":["img/hsc/9-7-1.jpg"]},{"id":"h9-8","t":"h9","num":"9.8","q":{"uk":"На якому малюнку водій правильно подав сигнал про початок руху?","ru":"На каком рисунке водитель правильно подал сигнал о начале движения?"},"a":[{"uk":"На першому.","ru":"На первом."},{"uk":"На другому.","ru":"На втором.","w":{"uk":"Покажчики повороту справні, тож сигнал треба подавати ними; рукою сигналізують лише в разі їх відсутності або несправності ({p:9.3}).","ru":"Указатели поворота исправны, поэтому сигнал нужно подавать ими; рукой сигнализируют только при их отсутствии или неисправности ({p:9.3})."}},{"uk":"На третьому.","ru":"На третьем.","w":{"uk":"Дублювати сигнал рукою не потрібно: коли покажчики повороту справні, сигнал подають лише ними ({p:9.2}, {p:9.3}).","ru":"Дублировать сигнал рукой не нужно: когда указатели поворота исправны, сигнал подают только ими ({p:9.2}, {p:9.3})."}}],"c":0,"e":{"uk":"Перед початком руху сигнал подають **світловими покажчиками повороту** ({p:9.2}, «а»), а рукою — лише в разі їх відсутності чи несправності ({p:9.3}). На першому малюнку водій, рушаючи від правого краю, увімкнув лівий покажчик повороту — це правильно.","ru":"Перед началом движения сигнал подают **световыми указателями поворота** ({p:9.2}, «а»), а рукой — только при их отсутствии или неисправности ({p:9.3}). На первом рисунке водитель, трогаясь от правого края, включил левый указатель поворота — это правильно."},"ref":["9.2","9.3"],"pic":["img/hsc/9-8-1.jpg"]},{"id":"h9-9","t":"h9","num":"9.9","q":{"uk":"Ви водій, рухаючись на сірому автомобілі вирішили повернути праворуч на другому перехресті. Ви:","ru":"Вы водитель; двигаясь на сером автомобиле, вы решили повернуть направо на втором перекрёстке. Вы:"},"a":[{"uk":"Включите покажчик повороту як показано на малюнку.","ru":"Включите указатель поворота, как показано на рисунке.","w":{"uk":"Покажчик, увімкнений до першого перехрестя, введе в оману водія білого автомобіля, який чекає перед знаком {s:2.1}.","ru":"Указатель, включённый до первого перекрёстка, введёт в заблуждение водителя белого автомобиля, ожидающего перед знаком {s:2.1}."}},{"uk":"Проїдете перше перехрестя і включите покажчик повороту, щоб не вводити в оману водія білого автомобіля.","ru":"Проедете первый перекрёсток и включите указатель поворота, чтобы не вводить в заблуждение водителя белого автомобиля."},{"uk":"Включите покажчик повороту, як показано на малюнку, і для запобігання дорожньо-транспортної пригоди з білим автомобілем, попередити його звуковим сигналом.","ru":"Включите указатель поворота, как показано на рисунке, и, чтобы предотвратить дорожно-транспортное происшествие с белым автомобилем, предупредите его звуковым сигналом.","w":{"uk":"Звуковий сигнал не усуває двозначності сигналу повороту, а в населеному пункті він узагалі заборонений, крім випадків, коли без нього не уникнути ДТП ({p:9.5}).","ru":"Звуковой сигнал не устраняет двусмысленности сигнала поворота, а в населённом пункте он вообще запрещён, кроме случаев, когда без него не избежать ДТП ({p:9.5})."}}],"c":1,"e":{"uk":"Правий покажчик повороту, увімкнений перед першим перехрестям, водій білого автомобіля сприйме як намір повернути на його дорогу й може почати рух. За {p:9.4} сигнал забороняється подавати, якщо він може бути незрозумілим, тому покажчик слід увімкнути **після** першого перехрестя, але завчасно до другого.","ru":"Правый указатель поворота, включённый перед первым перекрёстком, водитель белого автомобиля воспримет как намерение повернуть на его дорогу и может начать движение. Согласно {p:9.4} сигнал запрещается подавать, если он может быть непонятен, поэтому указатель следует включить **после** первого перекрёстка, но заблаговременно до второго."},"ref":["9.4"],"pic":["img/hsc/9-9-1.jpg"]},{"id":"h9-10","t":"h9","num":"9.10","q":{"uk":"Які попереджувальні сигнали вмикаються на транспортному засобі, що буксирується?","ru":"Какие предупредительные сигналы включаются на буксируемом транспортном средстве?"},"a":[{"uk":"Ближнє світло фар і аварійна сигналізація.","ru":"Ближний свет фар и аварийная сигнализация.","w":{"uk":"Ближнє світло фар потрібне на транспортному засобі, що буксирує, а не на тому, що буксирується.","ru":"Ближний свет фар нужен на буксирующем транспортном средстве, а не на буксируемом."}},{"uk":"Тільки ближнє світло фар.","ru":"Только ближний свет фар.","w":{"uk":"Ближнє світло — сигнал для транспортного засобу, що буксирує; на тому, що буксирується, потрібна аварійна сигналізація.","ru":"Ближний свет — сигнал для буксирующего транспортного средства; на буксируемом нужна аварийная сигнализация."}},{"uk":"Тільки аварійна сигналізація.","ru":"Только аварийная сигнализация."}],"c":2,"e":{"uk":"На механічному транспортному засобі, що буксирується, вмикають аварійну сигналізацію ({p:9.9}, «г»); ближнє світло фар у світлу пору доби вмикає транспортний засіб, що **буксирує** ({p:9.8}, «ґ»), — як передня вантажівка на малюнку.","ru":"На буксируемом механическом транспортном средстве включают аварийную сигнализацию ({p:9.9}, «г»); ближний свет фар в светлое время суток включает **буксирующее** транспортное средство ({p:9.8}, «ґ»), — как передний грузовик на рисунке."},"ref":["9.8","9.9"],"pic":["img/hsc/9-10-1.jpg"]},{"id":"h9-11","t":"h9","num":"9.11","q":{"uk":"На якому малюнку водій правильно подав сигнал перед поворотом праворуч у разі несправності світлових покажчиків повороту?","ru":"На каком рисунке водитель правильно подал сигнал перед поворотом направо при неисправности световых указателей поворота?"},"a":[{"uk":"На першому.","ru":"На первом."},{"uk":"На другому.","ru":"На втором.","w":{"uk":"Ліва рука, витягнута вбік, — це сигнал повороту ліворуч (розвороту, перестроювання ліворуч).","ru":"Левая рука, вытянутая в сторону, — это сигнал поворота налево (разворота, перестроения влево)."}},{"uk":"На третьому.","ru":"На третьем.","w":{"uk":"Рука, піднята вгору, — це сигнал гальмування, а не повороту.","ru":"Рука, поднятая вверх, — это сигнал торможения, а не поворота."}}],"c":0,"e":{"uk":"За {p:9.3} сигнал повороту праворуч подають правою рукою, витягнутою вбік, або **лівою рукою, витягнутою вбік і зігнутою в лікті під прямим кутом угору** — саме так показує водій на першому малюнку.","ru":"Согласно {p:9.3} сигнал поворота направо подают правой рукой, вытянутой в сторону, или **левой рукой, вытянутой в сторону и согнутой в локте под прямым углом вверх** — именно так показывает водитель на первом рисунке."},"ref":["9.3"],"pic":["img/hsc/9-11-1.jpg"]},{"id":"h9-12","t":"h9","num":"9.12","q":{"uk":"Які попереджувальні сигнали повинні бути увімкнені на механічному транспортному засобі, що рухається з технічними несправностями, якщо такий рух не заборонено Правилами дорожнього руху?","ru":"Какие предупредительные сигналы должны быть включены на механическом транспортном средстве, движущемся с техническими неисправностями, если такое движение не запрещено Правилами дорожного движения?"},"a":[{"uk":"Ближнє світло фар.","ru":"Ближний свет фар.","w":{"uk":"Ближнє світло не попереджає про несправність; для цього випадку Правила вимагають аварійної сигналізації.","ru":"Ближний свет не предупреждает о неисправности; для этого случая Правила требуют аварийной сигнализации."}},{"uk":"Аварійна сигналізація разом із ближнім світлом фар.","ru":"Аварийная сигнализация вместе с ближним светом фар.","w":{"uk":"Ближнього світла для цього випадку Правила окремо не вимагають — несправний транспортний засіб позначають саме аварійною сигналізацією.","ru":"Ближнего света для этого случая Правила отдельно не требуют — неисправное транспортное средство обозначают именно аварийной сигнализацией."}},{"uk":"Аварійна сигналізація.","ru":"Аварийная сигнализация."}],"c":2,"e":{"uk":"{p:9.9} (підпункт «в») прямо вимагає вмикати аварійну світлову сигналізацію на механічному транспортному засобі, що рухається з технічними несправностями, з якими рух не заборонено.","ru":"{p:9.9} (подпункт «в») прямо требует включать аварийную световую сигнализацию на механическом транспортном средстве, движущемся с техническими неисправностями, с которыми движение не запрещено."},"ref":["9.9"]},{"id":"h9-13","t":"h9","num":"9.13","q":{"uk":"Як позначити транспортний засіб, що рухається до місця ремонту з технічними несправностями, рух із якими не заборонений Правилами дорожнього руху, якщо на транспортному засобі відсутня або несправна аварійна світлова сигналізація?","ru":"Как обозначить транспортное средство, движущееся к месту ремонта с техническими неисправностями, с которыми движение не запрещено Правилами дорожного движения, если на транспортном средстве отсутствует или неисправна аварийная световая сигнализация?"},"a":[{"uk":"Потрібно ввімкнути ближнє світло фар.","ru":"Нужно включить ближний свет фар.","w":{"uk":"Ближнє світло фар не замінює аварійної сигналізації.","ru":"Ближний свет фар не заменяет аварийную сигнализацию."}},{"uk":"Необхідно встановити ззаду на транспортному засобі знак аварійної зупинки.","ru":"Необходимо установить сзади на транспортном средстве знак аварийной остановки.","w":{"uk":"Неповна відповідь: замість знака можна встановити й миготливий червоний ліхтар.","ru":"Неполный ответ: вместо знака можно установить и мигающий красный фонарь."}},{"uk":"Необхідно встановити ззаду на транспортному засобі миготливий червоний ліхтар.","ru":"Необходимо установить сзади на транспортном средстве мигающий красный фонарь.","w":{"uk":"Неповна відповідь: замість ліхтаря можна встановити й знак аварійної зупинки.","ru":"Неполный ответ: вместо фонаря можно установить и знак аварийной остановки."}},{"uk":"Виконати вимогу, вказану у відповіді 2 або у відповіді 3.","ru":"Выполнить требование, указанное в ответе 2 или в ответе 3."},{"uk":"Виконати вимогу, вказану у відповідях 1 і 2.","ru":"Выполнить требование, указанное в ответах 1 и 2.","w":{"uk":"Ближнє світло фар у {p:9.11} не згадується, тож поєднання варіантів 1 і 2 не відповідає Правилам.","ru":"Ближний свет фар в {p:9.11} не упоминается, поэтому сочетание вариантов 1 и 2 не соответствует Правилам."}}],"c":3,"e":{"uk":"За {p:9.11} (підпункт «а») у разі відсутності чи несправності аварійної сигналізації транспортний засіб із {p:9.9} «в» позначають знаком аварійної зупинки **або** миготливим червоним ліхтарем, установленим ззаду, — достатньо одного з двох.","ru":"Согласно {p:9.11} (подпункт «а») при отсутствии или неисправности аварийной сигнализации транспортное средство из {p:9.9} «в» обозначают знаком аварийной остановки **или** мигающим красным фонарём, установленным сзади, — достаточно одного из двух."},"ref":["9.9","9.11"]},{"id":"h9-14","t":"h9","num":"9.14","q":{"uk":"Який попереджувальний сигнал повинен бути ввімкнений на транспортному засобі під час руху в тунелі?","ru":"Какой предупредительный сигнал должен быть включён на транспортном средстве во время движения в тоннеле?"},"a":[{"uk":"Денні ходові вогні.","ru":"Дневные ходовые огни.","w":{"uk":"Денні ходові вогні в тунелі не замінюють ближнього світла: {p:9.8} вимагає саме його.","ru":"Дневные ходовые огни в тоннеле не заменяют ближний свет: {p:9.8} требует именно его."}},{"uk":"Протитуманні фари без ближнього світла.","ru":"Противотуманные фары без ближнего света.","w":{"uk":"Протитуманні фари можна вмикати лише **додатково** в умовах недостатньої видимості, а не замість ближнього світла.","ru":"Противотуманные фары можно включать только **дополнительно** в условиях недостаточной видимости, а не вместо ближнего света."}},{"uk":"Ближнє світло фар.","ru":"Ближний свет фар."}],"c":2,"e":{"uk":"За {p:9.8} (підпункт «д») у тунелях для позначення транспортного засобу, що рухається, ближнє світло фар має бути ввімкнене навіть у світлу пору доби.","ru":"Согласно {p:9.8} (подпункт «д») в тоннелях для обозначения движущегося транспортного средства ближний свет фар должен быть включён даже в светлое время суток."},"ref":["9.8"]},{"id":"h9-15","t":"h9","num":"9.15","q":{"uk":"У яких випадках на транспортному засобі повинна бути ввімкнена аварійна сигналізація?","ru":"В каких случаях на транспортном средстве должна быть включена аварийная сигнализация?"},"a":[{"uk":"На транспортному засобі, що буксирує.","ru":"На буксирующем транспортном средстве.","w":{"uk":"Аварійну сигналізацію вмикають на транспортному засобі, що буксирується; на тому, що буксирує, вмикають ближнє світло фар ({p:9.8}, «ґ»).","ru":"Аварийную сигнализацию включают на буксируемом транспортном средстве; на буксирующем включают ближний свет фар ({p:9.8}, «ґ»)."}},{"uk":"На механічному транспортному засобі, позначеному розпізнавальним знаком «Діти», що перевозить організовану групу дітей, під час посадки або висадки дітей.","ru":"На механическом транспортном средстве, обозначенном опознавательным знаком «Дети», перевозящем организованную группу детей, во время посадки или высадки детей.","w":{"uk":"Неповна відповідь: аварійну сигналізацію вмикають і на транспортних засобах колони під час зупинки на дорозі.","ru":"Неполный ответ: аварийную сигнализацию включают и на транспортных средствах колонны во время остановки на дороге."}},{"uk":"На всіх механічних транспортних засобах колони під час їхньої зупинки на дорозі.","ru":"На всех механических транспортных средствах колонны во время их остановки на дороге.","w":{"uk":"Неповна відповідь: аварійну сигналізацію вмикають і під час посадки чи висадки дітей.","ru":"Неполный ответ: аварийную сигнализацию включают и во время посадки или высадки детей."}},{"uk":"Відповіді 2 і 3.","ru":"Ответы 2 и 3."},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3.","w":{"uk":"Варіант 1 помилковий: транспортний засіб, що буксирує, позначають ближнім світлом фар, а не аварійною сигналізацією.","ru":"Вариант 1 ошибочен: буксирующее транспортное средство обозначают ближним светом фар, а не аварийной сигнализацией."}}],"c":3,"e":{"uk":"Обидва випадки прямо названі в {p:9.9}: посадка чи висадка дітей із транспортного засобу зі знаком «Діти» (підпункт «ґ») і зупинка колони на дорозі (підпункт «д»).","ru":"Оба случая прямо названы в {p:9.9}: посадка или высадка детей из транспортного средства со знаком «Дети» (подпункт «ґ») и остановка колонны на дороге (подпункт «д»)."},"ref":["9.9"]},{"id":"h9-16","t":"h9","num":"9.16","q":{"uk":"Як водій повинен позначити транспортний засіб під час вимушеної зупинки в місці з обмеженою оглядовістю (менше ніж 100 м в одному напрямку)?","ru":"Как водитель должен обозначить транспортное средство при вынужденной остановке в месте с ограниченной обзорностью (менее 100 м в одном направлении)?"},"a":[{"uk":"Встановити знак аварійної зупинки або миготливий червоний ліхтар на відстані від транспортного засобу, встановленій Правилами дорожнього руху.","ru":"Установить знак аварийной остановки или мигающий красный фонарь на расстоянии от транспортного средства, установленном Правилами дорожного движения.","w":{"uk":"Неповна відповідь: знак виставляють **разом** з увімкненням аварійної сигналізації.","ru":"Неполный ответ: знак выставляют **вместе** с включением аварийной сигнализации."}},{"uk":"Увімкнути габаритні ліхтарі разом з аварійною сигналізацією.","ru":"Включить габаритные огни вместе с аварийной сигнализацией.","w":{"uk":"Габаритні ліхтарі серед вимог {p:9.10} не названі, а без знака аварійної зупинки позначення неповне.","ru":"Габаритные огни среди требований {p:9.10} не названы, а без знака аварийной остановки обозначение неполное."}},{"uk":"Увімкнути аварійну сигналізацію.","ru":"Включить аварийную сигнализацию.","w":{"uk":"Неповна відповідь: у місці з обмеженою оглядовістю, крім аварійної сигналізації, виставляють ще й знак аварійної зупинки чи ліхтар.","ru":"Неполный ответ: в месте с ограниченной обзорностью, кроме аварийной сигнализации, выставляют ещё и знак аварийной остановки или фонарь."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2.","w":{"uk":"Габаритних ліхтарів {p:9.10} не вимагає: разом зі знаком потрібна саме аварійна сигналізація.","ru":"Габаритных огней {p:9.10} не требует: вместе со знаком нужна именно аварийная сигнализация."}},{"uk":"Відповіді 1 і 3.","ru":"Ответы 1 и 3."}],"c":4,"e":{"uk":"Під час вимушеної зупинки вмикають аварійну сигналізацію ({p:9.9}, «а»), а коли оглядовість хоча б в одному напрямку менше 100 м — ще й виставляють знак аварійної зупинки чи миготливий червоний ліхтар не ближче 20 м у населеному пункті й 40 м поза ним ({p:9.10}, «б»).","ru":"При вынужденной остановке включают аварийную сигнализацию ({p:9.9}, «а»), а когда обзорность хотя бы в одном направлении менее 100 м — ещё и выставляют знак аварийной остановки или мигающий красный фонарь не ближе 20 м в населённом пункте и 40 м вне его ({p:9.10}, «б»)."},"ref":["9.9","9.10"]},{"id":"h9-17","t":"h9","num":"9.17","q":{"uk":"Який попереджувальний сигнал Ви як водій повинні вмикати на транспортному засобі перед початком руху і зупинкою?","ru":"Какой предупредительный сигнал вы как водитель должны включать на транспортном средстве перед началом движения и остановкой?"},"a":[{"uk":"Покажчик повороту.","ru":"Указатель поворота."},{"uk":"Аварійну сигналізацію.","ru":"Аварийную сигнализацию.","w":{"uk":"Аварійну сигналізацію вмикають у випадках, перелічених у {p:9.9} (вимушена зупинка, ДТП тощо), а не перед звичайним рушанням чи зупинкою.","ru":"Аварийную сигнализацию включают в случаях, перечисленных в {p:9.9} (вынужденная остановка, ДТП и т. п.), а не перед обычным началом движения или остановкой."}},{"uk":"Стоянкові вогні.","ru":"Стояночные огни.","w":{"uk":"Стоянкові вогні позначають транспортний засіб на стоянці і не попереджають про початок руху чи зупинку.","ru":"Стояночные огни обозначают транспортное средство на стоянке и не предупреждают о начале движения или остановке."}}],"c":0,"e":{"uk":"За {p:9.2} (підпункт «а») перед початком руху і зупинкою водій подає сигнали світловими покажчиками повороту відповідного напрямку.","ru":"Согласно {p:9.2} (подпункт «а») перед началом движения и остановкой водитель подаёт сигналы световыми указателями поворота соответствующего направления."},"ref":["9.2"]},{"id":"h9-18","t":"h9","num":"9.18","q":{"uk":"Що необхідно виконати під час вимушеної зупинки, якщо аварійна світлова сигналізація відсутня або несправна?","ru":"Что необходимо сделать при вынужденной остановке, если аварийная световая сигнализация отсутствует или неисправна?"},"a":[{"uk":"Встановити знак аварійної зупинки.","ru":"Установить знак аварийной остановки.","w":{"uk":"Неповна відповідь: замість знака можна встановити й миготливий червоний ліхтар.","ru":"Неполный ответ: вместо знака можно установить и мигающий красный фонарь."}},{"uk":"Встановити миготливий червоний ліхтар.","ru":"Установить мигающий красный фонарь.","w":{"uk":"Неповна відповідь: замість ліхтаря можна встановити й знак аварійної зупинки.","ru":"Неполный ответ: вместо фонаря можно установить и знак аварийной остановки."}},{"uk":"Виконати одну з дій, указаних у відповідях 1 і 2.","ru":"Выполнить одно из действий, указанных в ответах 1 и 2."}],"c":2,"e":{"uk":"Якщо транспортний засіб не обладнаний аварійною сигналізацією або вона несправна, {p:9.11} вимагає встановити знак аварійної зупинки **або** миготливий червоний ліхтар — тобто будь-що одне з двох.","ru":"Если транспортное средство не оборудовано аварийной сигнализацией или она неисправна, {p:9.11} требует установить знак аварийной остановки **или** мигающий красный фонарь — то есть что-то одно из двух."},"ref":["9.9","9.11"]},{"id":"h9-19","t":"h9","num":"9.19","q":{"uk":"Як позначити транспортний засіб, що вимушено стоїть у місці з обмеженою оглядовістю дороги (менш ніж 100 м в одному напрямку), якщо на ньому відсутня або несправна аварійна світлова сигналізація?","ru":"Как обозначить транспортное средство, вынужденно стоящее в месте с ограниченной обзорностью дороги (менее 100 м в одном направлении), если на нём отсутствует или неисправна аварийная световая сигнализация?"},"a":[{"uk":"Встановити знак аварійної зупинки по одну сторону від транспортного засобу, миготливий червоний ліхтар – по іншу сторону від транспортного засобу.","ru":"Установить знак аварийной остановки с одной стороны от транспортного средства, а мигающий красный фонарь — с другой стороны.","w":{"uk":"Правила не вимагають позначати транспортний засіб з обох боків: знак або ліхтар ставлять один — з боку гіршої видимості.","ru":"Правила не требуют обозначать транспортное средство с обеих сторон: знак или фонарь ставят один — со стороны худшей видимости."}},{"uk":"Установити знак аварійної зупинки або миготливий червоний ліхтар з боку гіршої видимості для інших учасників дорожнього руху.","ru":"Установить знак аварийной остановки или мигающий красный фонарь со стороны худшей видимости для других участников дорожного движения."}],"c":1,"e":{"uk":"Для цього випадку {p:9.11} (підпункт «б») вимагає встановити знак аварійної зупинки або миготливий червоний ліхтар **з боку гіршої видимості** для інших учасників руху — там, звідки транспортний засіб помітити найважче.","ru":"Для этого случая {p:9.11} (подпункт «б») требует установить знак аварийной остановки или мигающий красный фонарь **со стороны худшей видимости** для других участников движения — там, откуда транспортное средство заметить труднее всего."},"ref":["9.10","9.11"]},{"id":"h9-20","t":"h9","num":"9.20","q":{"uk":"Водій, який рухається по перехрестю, де організовано круговий рух, не маючи наміру змінювати своєї смуги, зобов'язаний:","ru":"Водитель, который движется по перекрёстку с круговым движением, не намереваясь менять свою полосу, обязан:"},"a":[{"uk":"Включити лівий поворот, щоб показати всім свій рух по колу.","ru":"Включить левый указатель поворота, чтобы показать всем своё движение по кругу.","w":{"uk":"Лівий покажчик на кільці інші водії сприймуть як намір перестроїтися ліворуч, тож такий сигнал вводить в оману ({p:9.4}).","ru":"Левый указатель на кольце другие водители воспримут как намерение перестроиться влево, поэтому такой сигнал вводит в заблуждение ({p:9.4})."}},{"uk":"Включити правий поворот, щоб попередити всіх, що він скоро поїде праворуч.","ru":"Включить правый указатель поворота, чтобы предупредить всех, что он скоро поедет направо.","w":{"uk":"Правий покажчик вмикають перед з'їздом з кільця чи перестроюванням праворуч, а не заздалегідь «на майбутнє» — інакше водії, що чекають на в'їзд, можуть помилково виїхати на перехрестя.","ru":"Правый указатель включают перед съездом с кольца или перестроением вправо, а не заранее «на будущее» — иначе водители, ожидающие въезда, могут ошибочно выехать на перекрёсток."}},{"uk":"Не вмикати покажчики поворотів, поки він рухається по одній смузі.","ru":"Не включать указатели поворота, пока он движется по одной полосе."}],"c":2,"e":{"uk":"Покажчики повороту вмикають перед початком руху, зупинкою, перестроюванням, поворотом або розворотом ({p:9.2}); рух по колу в межах своєї смуги жодним із цих маневрів не є. Зайвий сигнал може бути незрозумілим для інших водіїв, а такий сигнал подавати заборонено ({p:9.4}).","ru":"Указатели поворота включают перед началом движения, остановкой, перестроением, поворотом или разворотом ({p:9.2}); движение по кругу в пределах своей полосы ни одним из этих манёвров не является. Лишний сигнал может быть непонятен другим водителям, а такой сигнал подавать запрещено ({p:9.4})."},"ref":["9.2","9.4"]},{"id":"h9-21","t":"h9","num":"9.21","q":{"uk":"Ви водій, рухаючись в населеному пункті вирішили здійснити розворот. Ви:","ru":"Вы водитель; двигаясь в населённом пункте, вы решили выполнить разворот. Вы:"},"a":[{"uk":"Зобов’язаний подати сигнал покажчиками повороту або рукою за 200 метрів до розвороту.","ru":"Обязаны подать сигнал указателями поворота или рукой за 200 метров до разворота.","w":{"uk":"200 м — верхня межа відстані для доріг поза населеними пунктами; у населеному пункті Правила вимагають не менш як 50–100 м.","ru":"200 м — верхняя граница расстояния для дорог вне населённых пунктов; в населённом пункте Правила требуют не менее 50–100 м."}},{"uk":"Зобов’язаний подати сигнал покажчиками повороту або рукою за 100 метрів до розвороту за наявності інших учасників дорожнього руху.","ru":"Обязаны подать сигнал указателями поворота или рукой за 100 метров до разворота при наличии других участников дорожного движения.","w":{"uk":"Сигнал подають завжди, незалежно від наявності інших учасників руху, а відстань у населеному пункті — не менш як 50–100 м.","ru":"Сигнал подают всегда, независимо от наличия других участников движения, а расстояние в населённом пункте — не менее 50–100 м."}},{"uk":"Зобов’язаний подати сигнал покажчиками повороту або рукою не менш як за 50 - 100 метрів до маневру.","ru":"Обязаны подать сигнал указателями поворота или рукой не менее чем за 50–100 метров до манёвра."}],"c":2,"e":{"uk":"За {p:9.4} сигнал подають завчасно, з урахуванням швидкості, але **не менш як за 50–100 м** у населених пунктах (поза ними — за 150–200 м).","ru":"Согласно {p:9.4} сигнал подают заблаговременно, с учётом скорости, но **не менее чем за 50–100 м** в населённых пунктах (вне их — за 150–200 м)."},"ref":["9.2","9.4"]},{"id":"h9-22","t":"h9","num":"9.22","q":{"uk":"Ви водій, рухаючись в населеному пункті вирішили змінити смугу руху. Ви:","ru":"Вы водитель; двигаясь в населённом пункте, вы решили сменить полосу движения. Вы:"},"a":[{"uk":"Зобов’язаний подати сигнал покажчиками повороту або рукою за 30 метрів до початку виконання маневру.","ru":"Обязаны подать сигнал указателями поворота или рукой за 30 метров до начала выполнения манёвра.","w":{"uk":"30 м — замало: у населеному пункті сигнал подають не менш як за 50–100 м.","ru":"30 м — слишком мало: в населённом пункте сигнал подают не менее чем за 50–100 м."}},{"uk":"Зобов’язаний подати сигнал покажчиками повороту або рукою за 100 метрів до початку виконання маневру за наявності інших учасників дорожнього руху.","ru":"Обязаны подать сигнал указателями поворота или рукой за 100 метров до начала выполнения манёвра при наличии других участников дорожного движения.","w":{"uk":"Сигнал подають завжди, а не лише за наявності інших учасників руху; мінімальна відстань у населеному пункті — 50–100 м.","ru":"Сигнал подают всегда, а не только при наличии других участников движения; минимальное расстояние в населённом пункте — 50–100 м."}},{"uk":"Зобов’язаний подати сигнал покажчиками повороту або рукою не менш як за 50 - 100 метрів до початку виконання маневру.","ru":"Обязаны подать сигнал указателями поворота или рукой не менее чем за 50–100 метров до начала выполнения манёвра."}],"c":2,"e":{"uk":"Перестроювання — один із маневрів, перед якими подають сигнал ({p:9.2}, «б»). За {p:9.4} у населеному пункті це роблять завчасно, але **не менш як за 50–100 м** до початку маневру.","ru":"Перестроение — один из манёвров, перед которыми подают сигнал ({p:9.2}, «б»). Согласно {p:9.4} в населённом пункте это делают заблаговременно, но **не менее чем за 50–100 м** до начала манёвра."},"ref":["9.2","9.4"]},{"id":"h9-23","t":"h9","num":"9.23","q":{"uk":"Ви водій, рухаючись в населеному пункті вирішили повернути праворуч на перехресті. Ви:","ru":"Вы водитель; двигаясь в населённом пункте, вы решили повернуть направо на перекрёстке. Вы:"},"a":[{"uk":"Зобов’язаний подати сигнал покажчиками повороту або рукою за 200 метрів до повороту.","ru":"Обязаны подать сигнал указателями поворота или рукой за 200 метров до поворота.","w":{"uk":"200 м — верхня межа відстані для доріг поза населеними пунктами; до того ж сигнал, поданий так рано в місті, може ввести в оману на попередніх перехрестях.","ru":"200 м — верхняя граница расстояния для дорог вне населённых пунктов; к тому же сигнал, поданный так рано в городе, может ввести в заблуждение на предыдущих перекрёстках."}},{"uk":"Зобов’язаний подати сигнал покажчиками повороту або рукою за 100 метрів до повороту за наявності інших учасників дорожнього руху.","ru":"Обязаны подать сигнал указателями поворота или рукой за 100 метров до поворота при наличии других участников дорожного движения.","w":{"uk":"Сигнал подають незалежно від наявності інших учасників руху, а в населеному пункті — не менш як за 50–100 м.","ru":"Сигнал подают независимо от наличия других участников движения, а в населённом пункте — не менее чем за 50–100 м."}},{"uk":"Зобов’язаний подати сигнал покажчиками повороту або рукою не менш як за 50 - 100 метрів до повороту.","ru":"Обязаны подать сигнал указателями поворота или рукой не менее чем за 50–100 метров до поворота."}],"c":2,"e":{"uk":"За {p:9.4} сигнал повороту в населеному пункті подають завчасно, з урахуванням швидкості, але **не менш як за 50–100 м** до маневру.","ru":"Согласно {p:9.4} сигнал поворота в населённом пункте подают заблаговременно, с учётом скорости, но **не менее чем за 50–100 м** до манёвра."},"ref":["9.2","9.4"]},{"id":"h9-24","t":"h9","num":"9.24","q":{"uk":"Ви рухаєтесь на велосипеді і Вам необхідно зупинитися. Ваші дії:","ru":"Вы движетесь на велосипеде, и вам необходимо остановиться. Ваши действия:"},"a":[{"uk":"Витягнете праву руку вбік і зігнете під прямим кутом вгору.","ru":"Вытянете правую руку в сторону и согнёте под прямым углом вверх.","w":{"uk":"Права рука, зігнута в лікті вгору, — це сигнал лівого напрямку (поворот, розворот, перестроювання ліворуч чи зупинка зліва), а не сигнал гальмування.","ru":"Правая рука, согнутая в локте вверх, — это сигнал левого направления (поворот, разворот, перестроение налево или остановка слева), а не сигнал торможения."}},{"uk":"Витягнете ліву руку в бік або праву руку вбік і зігнете у лікті під прямим кутом вгору.","ru":"Вытянете левую руку в сторону или правую руку в сторону и согнёте в локте под прямым углом вверх.","w":{"uk":"Обидва описані жести — сигнали лівого напрямку (поворот, розворот, перестроювання ліворуч чи зупинка зліва), а не сигнал гальмування.","ru":"Оба описанных жеста — сигналы левого направления (поворот, разворот, перестроение налево или остановка слева), а не сигнал торможения."}},{"uk":"Піднімаєте ліву або праву руку вгору.","ru":"Поднимете левую или правую руку вверх."},{"uk":"Варіанти 1 та 2 вірні.","ru":"Варианты 1 и 2 верны.","w":{"uk":"Варіанти 1 і 2 описують сигнали лівого напрямку, тож сигналом гальмування жоден із них не є.","ru":"Варианты 1 и 2 описывают сигналы левого направления, поэтому сигналом торможения ни один из них не является."}}],"c":2,"e":{"uk":"Сигнал гальмування рукою за {p:9.3} подають лівою або правою рукою, **піднятою вгору**. Велосипед зазвичай не має сигналів гальмування, тому, зупиняючись, велосипедист подає саме такий сигнал.","ru":"Сигнал торможения рукой согласно {p:9.3} подают левой или правой рукой, **поднятой вверх**. У велосипеда обычно нет сигналов торможения, поэтому, останавливаясь, велосипедист подаёт именно такой сигнал."},"ref":["9.3"]},{"id":"h9-25","t":"h9","num":"9.25","q":{"uk":"Ви рухаєтесь на велосипеді і Вам необхідно повернути праворуч. Ваші дії:","ru":"Вы движетесь на велосипеде, и вам необходимо повернуть направо. Ваши действия:"},"a":[{"uk":"Витягнете праву руку вбік і зігнете під прямим кутом вгору.","ru":"Вытянете правую руку в сторону и согнёте под прямым углом вверх.","w":{"uk":"Права рука, зігнута в лікті вгору, означає поворот ліворуч, а не праворуч.","ru":"Правая рука, согнутая в локте вверх, означает поворот налево, а не направо."}},{"uk":"Витягнете ліву руку в бік або праву руку вбік і зігнете її у лікті під прямим кутом вгору.","ru":"Вытянете левую руку в сторону или правую руку в сторону и согнёте её в локте под прямым углом вверх.","w":{"uk":"Тут описано обидва способи подати сигнал повороту ліворуч.","ru":"Здесь описаны оба способа подать сигнал поворота налево."}},{"uk":"Витягнете праву руку в бік або ліву руку вбік і зігнете у лікті під прямим кутом вгору.","ru":"Вытянете правую руку в сторону или левую руку в сторону и согнёте в локте под прямым углом вверх."},{"uk":"Варіанти 1 та 2 вірні.","ru":"Варианты 1 и 2 верны.","w":{"uk":"Варіанти 1 і 2 описують сигнали повороту ліворуч, тож для повороту праворуч вони не підходять.","ru":"Варианты 1 и 2 описывают сигналы поворота налево, поэтому для поворота направо они не подходят."}}],"c":2,"e":{"uk":"За {p:9.3} сигнал повороту праворуч подають **правою рукою, витягнутою вбік**, або **лівою рукою, витягнутою вбік і зігнутою в лікті під прямим кутом угору** — саме це описано у варіанті 3.","ru":"Согласно {p:9.3} сигнал поворота направо подают **правой рукой, вытянутой в сторону**, или **левой рукой, вытянутой в сторону и согнутой в локте под прямым углом вверх** — именно это описано в варианте 3."},"ref":["9.3"]},{"id":"h9-26","t":"h9","num":"9.26","q":{"uk":"Ви рухаєтесь на велосипеді і Вам необхідно повернути ліворуч. Ваші дії:","ru":"Вы движетесь на велосипеде, и вам необходимо повернуть налево. Ваши действия:"},"a":[{"uk":"Витягнете праву руку вбік і зігнете під прямим кутом вгору.","ru":"Вытянете правую руку в сторону и согнёте под прямым углом вверх.","w":{"uk":"Це лише один із двох дозволених способів; повну відповідь дає варіант 2.","ru":"Это лишь один из двух разрешённых способов; полный ответ даёт вариант 2."}},{"uk":"Витягнете ліву руку в бік або праву руку вбік і зігнете у лікті під прямим кутом вгору.","ru":"Вытянете левую руку в сторону или правую руку в сторону и согнёте в локте под прямым углом вверх."},{"uk":"Витягнете ліву руку і зігнете у лікті під прямим кутом вгору.","ru":"Вытянете левую руку и согнёте в локте под прямым углом вверх.","w":{"uk":"Ліва рука, зігнута в лікті вгору, — це сигнал повороту праворуч.","ru":"Левая рука, согнутая в локте вверх, — это сигнал поворота направо."}}],"c":1,"e":{"uk":"За {p:9.3} сигнал повороту ліворуч подають **лівою рукою, витягнутою вбік**, або **правою рукою, витягнутою вбік і зігнутою в лікті під прямим кутом угору**; варіант 2 називає обидва дозволені способи.","ru":"Согласно {p:9.3} сигнал поворота налево подают **левой рукой, вытянутой в сторону**, или **правой рукой, вытянутой в сторону и согнутой в локте под прямым углом вверх**; вариант 2 называет оба разрешённых способа."},"ref":["9.3"]},{"id":"h9-27","t":"h9","num":"9.27","q":{"uk":"Ви рухаєтесь на автомобілі, у якого несправні світлові покажчики поворотів, але Вам необхідно повернути ліворуч. Ваші дії:","ru":"Вы движетесь на автомобиле, у которого неисправны световые указатели поворота, но вам необходимо повернуть налево. Ваши действия:"},"a":[{"uk":"Витягнете праву руку вбік.","ru":"Вытянете правую руку в сторону.","w":{"uk":"Права рука, витягнута вбік, — це сигнал повороту праворуч; до того ж з місця водія його не видно іншим учасникам руху.","ru":"Правая рука, вытянутая в сторону, — это сигнал поворота направо; к тому же с места водителя его не видно другим участникам движения."}},{"uk":"Витягнете ліву руку у вікно в бік.","ru":"Вытянете левую руку в окно в сторону."},{"uk":"Витягнете ліву руку у вікно і зігнете у лікті під прямим кутом вгору.","ru":"Вытянете левую руку в окно и согнёте в локте под прямым углом вверх.","w":{"uk":"Ліва рука, зігнута в лікті вгору, — це сигнал повороту праворуч.","ru":"Левая рука, согнутая в локте вверх, — это сигнал поворота направо."}}],"c":1,"e":{"uk":"Сигнал повороту ліворуч за {p:9.3} — ліва рука, витягнута вбік. Водій автомобіля з лівим кермом подає його, витягнувши ліву руку у вікно.","ru":"Сигнал поворота налево согласно {p:9.3} — левая рука, вытянутая в сторону. Водитель автомобиля с левым рулём подаёт его, вытянув левую руку в окно."},"ref":["9.3"]},{"id":"h9-28","t":"h9","num":"9.28","q":{"uk":"Ви рухаєтесь на автомобілі, у якого несправні світлові покажчики поворотів, але Вам необхідно повернути праворуч. Ваші дії:","ru":"Вы движетесь на автомобиле, у которого неисправны световые указатели поворота, но вам необходимо повернуть направо. Ваши действия:"},"a":[{"uk":"Витягнете праву руку в праву сторону і зігнете під прямим кутом вгору.","ru":"Вытянете правую руку в правую сторону и согнёте под прямым углом вверх.","w":{"uk":"Права рука, зігнута в лікті вгору, означає поворот ліворуч; крім того, з місця водія такий сигнал майже не видно.","ru":"Правая рука, согнутая в локте вверх, означает поворот налево; кроме того, с места водителя такой сигнал почти не виден."}},{"uk":"Витягнете ліву руку в ліву сторону.","ru":"Вытянете левую руку в левую сторону.","w":{"uk":"Ліва рука, витягнута вбік, — це сигнал повороту ліворуч.","ru":"Левая рука, вытянутая в сторону, — это сигнал поворота налево."}},{"uk":"Витягнете ліву руку в ліву сторону у вікно і зігнете під прямим кутом вгору.","ru":"Вытянете левую руку в левую сторону в окно и согнёте под прямым углом вверх."}],"c":2,"e":{"uk":"Сигнал повороту праворуч за {p:9.3} можна подати лівою рукою, витягнутою вбік і зігнутою в лікті під прямим кутом угору. Водій автомобіля з лівим кермом робить це через ліве вікно — так його сигнал бачать інші учасники руху.","ru":"Сигнал поворота направо согласно {p:9.3} можно подать левой рукой, вытянутой в сторону и согнутой в локте под прямым углом вверх. Водитель автомобиля с левым рулём делает это через левое окно — так его сигнал видят другие участники движения."},"ref":["9.3"]},{"id":"h9-29","t":"h9","num":"9.29","q":{"uk":"Ви розпочинаєте рух на автомобілі, який попереджувальний сигнал повинні подати:","ru":"Вы начинаете движение на автомобиле. Какой предупредительный сигнал вы должны подать?"},"a":[{"uk":"Включити аварійну сигналізацію.","ru":"Включить аварийную сигнализацию.","w":{"uk":"Аварійну сигналізацію вмикають лише у випадках із {p:9.9}; про початок руху вона не попереджає.","ru":"Аварийную сигнализацию включают только в случаях из {p:9.9}; о начале движения она не предупреждает."}},{"uk":"Ввімкнути габаритні ліхтарі.","ru":"Включить габаритные огни.","w":{"uk":"Габаритні ліхтарі позначають габарити транспортного засобу, а не намір рушити.","ru":"Габаритные огни обозначают габариты транспортного средства, а не намерение тронуться."}},{"uk":"Подати сигнал світловим покажчиком повороту.","ru":"Подать сигнал световым указателем поворота."}],"c":2,"e":{"uk":"За {p:9.2} (підпункт «а») перед початком руху водій подає сигнал світловим покажчиком повороту відповідного напрямку.","ru":"Согласно {p:9.2} (подпункт «а») перед началом движения водитель подаёт сигнал световым указателем поворота соответствующего направления."},"ref":["9.2"]},{"id":"h9-30","t":"h9","num":"9.30","q":{"uk":"Ви водій автомобіля вирішили зупинитися з правої сторони дороги:","ru":"Вы, водитель автомобиля, решили остановиться у правой стороны дороги:"},"a":[{"uk":"Тільки у населеному пункті зобов’язані вмикати покажчик повороту.","ru":"Только в населённом пункте обязаны включать указатель поворота.","w":{"uk":"Обов'язок подавати сигнал перед зупинкою не залежить від того, у населеному пункті чи поза ним рухається транспортний засіб.","ru":"Обязанность подавать сигнал перед остановкой не зависит от того, в населённом пункте или вне его движется транспортное средство."}},{"uk":"Зобов’язані подивитися в праве дзеркало і якщо є інші учасники дорожнього руху тільки тоді ввімкнути покажчик повороту.","ru":"Обязаны посмотреть в правое зеркало и, только если есть другие участники дорожного движения, включить указатель поворота.","w":{"uk":"Сигнал подають незалежно від наявності інших учасників руху — когось можна й не помітити в дзеркалі.","ru":"Сигнал подают независимо от наличия других участников движения — кого-то можно и не заметить в зеркале."}},{"uk":"В будь-якому випадку включити правий покажчик повороту.","ru":"В любом случае включить правый указатель поворота."}],"c":2,"e":{"uk":"{p:9.2} вимагає подавати сигнал покажчиком повороту перед зупинкою **завжди** — і в населеному пункті, і поза ним, незалежно від того, чи є поруч інші учасники руху.","ru":"{p:9.2} требует подавать сигнал указателем поворота перед остановкой **всегда** — и в населённом пункте, и вне его, независимо от того, есть ли рядом другие участники движения."},"ref":["9.2"]},{"id":"h9-31","t":"h9","num":"9.31","q":{"uk":"За яких умов миготливий червоний ліхтар може використовуватися замість знака аварійної зупинки, згідно з Правилами дорожнього руху?","ru":"При каких условиях мигающий красный фонарь может использоваться вместо знака аварийной остановки согласно Правилам дорожного движения?"},"a":[{"uk":"Світло, випромінюване ліхтарем, має бути добре видно тільки вдень за сонячної погоди.","ru":"Свет, излучаемый фонарём, должен быть хорошо виден только днём в солнечную погоду.","w":{"uk":"Цього замало: світло ліхтаря має бути добре видно й в умовах недостатньої видимості.","ru":"Этого мало: свет фонаря должен быть хорошо виден и в условиях недостаточной видимости."}},{"uk":"Світло, випромінюване ліхтарем, повинно бути добре видно тільки в умовах недостатньої видимості.","ru":"Свет, излучаемый фонарём, должен быть хорошо виден только в условиях недостаточной видимости.","w":{"uk":"Цього замало: світло ліхтаря має бути добре видно й удень за сонячної погоди.","ru":"Этого мало: свет фонаря должен быть хорошо виден и днём в солнечную погоду."}},{"uk":"Світло, випромінюване ліхтарем, повинно бути добре видно як удень за сонячної погоди, так і в умовах недостатньої видимості.","ru":"Свет, излучаемый фонарём, должен быть хорошо виден как днём в солнечную погоду, так и в условиях недостаточной видимости."}],"c":2,"e":{"uk":"{p:9.12} вимагає, щоб миготливе червоне світло ліхтаря було добре видно **і** вдень за сонячної погоди, **і** в умовах недостатньої видимості.","ru":"{p:9.12} требует, чтобы мигающий красный свет фонаря был хорошо виден **и** днём в солнечную погоду, **и** в условиях недостаточной видимости."},"ref":["9.12"]},{"id":"h9-32","t":"h9","num":"9.32","q":{"uk":"Які зовнішні світлові прилади необхідно ввімкнути у разі зупинення транспортного засобу поліцейським?","ru":"Какие внешние световые приборы необходимо включить при остановке транспортного средства полицейским?"},"a":[{"uk":"Не потрібно вмикати жодних зовнішніх світлових приладів.","ru":"Не нужно включать никаких внешних световых приборов.","w":{"uk":"Правила прямо вимагають у цьому випадку ввімкнути аварійну сигналізацію ({p:9.9}).","ru":"Правила прямо требуют в этом случае включить аварийную сигнализацию ({p:9.9})."}},{"uk":"Аварійну світлову сигналізацію.","ru":"Аварийную световую сигнализацию."},{"uk":"Денні ходові вогні або протитуманні фари.","ru":"Дневные ходовые огни или противотуманные фары.","w":{"uk":"Денні ходові вогні й протитуманні фари позначають транспортний засіб під час руху, а не під час зупинки.","ru":"Дневные ходовые огни и противотуманные фары обозначают транспортное средство во время движения, а не во время остановки."}},{"uk":"Стоянкові ліхтарі.","ru":"Стояночные огни.","w":{"uk":"Стоянкові вогні не замінюють аварійної сигналізації, якої вимагає {p:9.9}.","ru":"Стояночные огни не заменяют аварийную сигнализацию, которой требует {p:9.9}."}}],"c":1,"e":{"uk":"За {p:9.9} (підпункт «б») у разі зупинки на вимогу поліцейського має бути ввімкнена аварійна світлова сигналізація.","ru":"Согласно {p:9.9} (подпункт «б») при остановке по требованию полицейского должна быть включена аварийная световая сигнализация."},"ref":["9.9"]},{"id":"h9-33","t":"h9","num":"9.33","q":{"uk":"У яких із перерахованих випадків потрібно ввімкнути аварійну світлову сигналізацію?","ru":"В каких из перечисленных случаев нужно включить аварийную световую сигнализацию?"},"a":[{"uk":"У випадку будь-якої зупинки на дорозі.","ru":"При любой остановке на дороге.","w":{"uk":"Аварійну сигналізацію вмикають під час **вимушеної** зупинки та в інших випадках із {p:9.9}, а не під час будь-якої зупинки.","ru":"Аварийную сигнализацию включают при **вынужденной** остановке и в других случаях из {p:9.9}, а не при любой остановке."}},{"uk":"У випадку зупинки на вимогу поліцейського.","ru":"При остановке по требованию полицейского.","w":{"uk":"Неповна відповідь: аварійну сигналізацію вмикають і в разі зупинки через засліплення світлом фар.","ru":"Неполный ответ: аварийную сигнализацию включают и при остановке из-за ослепления светом фар."}},{"uk":"У випадку зупинки внаслідок засліплення водія світлом фар.","ru":"При остановке вследствие ослепления водителя светом фар.","w":{"uk":"Неповна відповідь: аварійну сигналізацію вмикають і в разі зупинки на вимогу поліцейського.","ru":"Неполный ответ: аварийную сигнализацию включают и при остановке по требованию полицейского."}},{"uk":"Відповіді 2 і 3.","ru":"Ответы 2 и 3."},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3.","w":{"uk":"Варіант 1 помилковий: перед звичайною зупинкою вмикають покажчик повороту ({p:9.2}), а не аварійну сигналізацію.","ru":"Вариант 1 ошибочен: перед обычной остановкой включают указатель поворота ({p:9.2}), а не аварийную сигнализацию."}}],"c":3,"e":{"uk":"Обидва випадки прямо названі в {p:9.9} (підпункт «б»): зупинка на вимогу поліцейського і зупинка внаслідок засліплення водія світлом фар.","ru":"Оба случая прямо названы в {p:9.9} (подпункт «б»): остановка по требованию полицейского и остановка вследствие ослепления водителя светом фар."},"ref":["9.9"]},{"id":"h9-34","t":"h9","num":"9.34","q":{"uk":"У яких випадках дозволене подавання звукового сигналу?","ru":"В каких случаях разрешена подача звукового сигнала?"},"a":[{"uk":"Для привертання уваги водія під час обгону транспортного засобу на дорогах поза населеними пунктами.","ru":"Для привлечения внимания водителя при обгоне транспортного средства на дорогах вне населённых пунктов.","w":{"uk":"Неповна відповідь: звуковий сигнал дозволений і тоді, коли без нього неможливо запобігти ДТП.","ru":"Неполный ответ: звуковой сигнал разрешён и тогда, когда без него невозможно предотвратить ДТП."}},{"uk":"У випадках, коли без цього неможливо запобігти дорожньо-транспортній пригоді.","ru":"В случаях, когда без этого невозможно предотвратить дорожно-транспортное происшествие.","w":{"uk":"Неповна відповідь: поза населеними пунктами звуковим сигналом можна привернути й увагу водія, якого обганяють.","ru":"Неполный ответ: вне населённых пунктов звуковым сигналом можно привлечь и внимание водителя обгоняемого транспортного средства."}},{"uk":"Для привертання уваги водія під час обгону транспортного засобу на дорогах у населених пунктах.","ru":"Для привлечения внимания водителя при обгоне транспортного средства на дорогах в населённых пунктах.","w":{"uk":"У населених пунктах для цього можна застосовувати лише перемикання світла фар, а звуковий сигнал там заборонений ({p:9.5}, {p:9.6}).","ru":"В населённых пунктах для этого можно применять только переключение света фар, а звуковой сигнал там запрещён ({p:9.5}, {p:9.6})."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3.","w":{"uk":"Варіант 3 помилковий: у населеному пункті звуковий сигнал для привертання уваги під час обгону заборонений.","ru":"Вариант 3 ошибочен: в населённом пункте звуковой сигнал для привлечения внимания при обгоне запрещён."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2."}],"c":4,"e":{"uk":"Звуковий сигнал дозволений, коли без нього неможливо запобігти ДТП ({p:9.5}), а для привертання уваги водія, якого обганяють, — лише поза населеними пунктами ({p:9.6}).","ru":"Звуковой сигнал разрешён, когда без него невозможно предотвратить ДТП ({p:9.5}), а для привлечения внимания водителя обгоняемого транспортного средства — только вне населённых пунктов ({p:9.6})."},"ref":["9.5","9.6"]},{"id":"h9-35","t":"h9","num":"9.35","q":{"uk":"Де заборонене подавання звукового сигналу?","ru":"Где запрещена подача звукового сигнала?"},"a":[{"uk":"У населених пунктах, окрім випадків, коли без цього неможливо запобігти дорожньо-транспортній пригоді.","ru":"В населённых пунктах, кроме случаев, когда без этого невозможно предотвратить дорожно-транспортное происшествие.","w":{"uk":"Неповна відповідь: поза населеними пунктами звуковий сигнал забороняє знак {s:3.33}.","ru":"Неполный ответ: вне населённых пунктов звуковой сигнал запрещает знак {s:3.33}."}},{"uk":"Поза населеними пунктами, в місцях, де встановлений знак «Подавання звукового сигналу заборонено», крім випадків, коли без цього неможливо запобігти дорожньо-транспортній пригоді.","ru":"Вне населённых пунктов, в местах, где установлен знак «Подача звукового сигнала запрещена», кроме случаев, когда без этого невозможно предотвратить дорожно-транспортное происшествие.","w":{"uk":"Неповна відповідь: у населених пунктах звуковий сигнал заборонений і без знака ({p:9.5}).","ru":"Неполный ответ: в населённых пунктах звуковой сигнал запрещён и без знака ({p:9.5})."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2."}],"c":2,"e":{"uk":"У населених пунктах звуковий сигнал заборонений за {p:9.5}, а поза ними — у зоні дії знака {s:3.33} ({p:33.3}); в обох випадках виняток — коли без сигналу неможливо запобігти ДТП.","ru":"В населённых пунктах звуковой сигнал запрещён согласно {p:9.5}, а вне их — в зоне действия знака {s:3.33} ({p:33.3}); в обоих случаях исключение — когда без сигнала невозможно предотвратить ДТП."},"ref":["9.5","33.3"]},{"id":"h9-36","t":"h9","num":"9.36","q":{"uk":"Чи дозволене водіям подавання звукового сигналу?","ru":"Разрешена ли водителям подача звукового сигнала?"},"a":[{"uk":"Дозволено завжди.","ru":"Разрешена всегда.","w":{"uk":"У населених пунктах звуковий сигнал заборонений, крім випадків, коли без нього не уникнути ДТП ({p:9.5}).","ru":"В населённых пунктах звуковой сигнал запрещён, кроме случаев, когда без него не избежать ДТП ({p:9.5})."}},{"uk":"Заборонено у населених пунктах, окрім випадків, коли без цього неможливо запобігти дорожньо-транспортній пригоді.","ru":"Запрещена в населённых пунктах, кроме случаев, когда без этого невозможно предотвратить дорожно-транспортное происшествие."},{"uk":"Заборонено у населених пунктах і поза населеними пунктами, крім випадків, коли без цього неможливо запобігти дорожньо-транспортній пригоді.","ru":"Запрещена в населённых пунктах и вне населённых пунктов, кроме случаев, когда без этого невозможно предотвратить дорожно-транспортное происшествие.","w":{"uk":"Поза населеними пунктами загальної заборони немає: там звуковий сигнал можна подати, наприклад, водієві, якого обганяють ({p:9.6}), якщо не встановлено знак {s:3.33}.","ru":"Вне населённых пунктов общего запрета нет: там звуковой сигнал можно подать, например, водителю обгоняемого транспортного средства ({p:9.6}), если не установлен знак {s:3.33}."}}],"c":1,"e":{"uk":"{p:9.5} забороняє звукові сигнали саме **в населених пунктах**, крім випадків, коли без них неможливо запобігти ДТП. Поза населеними пунктами звуковий сигнал загалом дозволений — зокрема, щоб привернути увагу водія, якого обганяють ({p:9.6}).","ru":"{p:9.5} запрещает звуковые сигналы именно **в населённых пунктах**, кроме случаев, когда без них невозможно предотвратить ДТП. Вне населённых пунктов звуковой сигнал в целом разрешён — в частности, чтобы привлечь внимание водителя обгоняемого транспортного средства ({p:9.6})."},"ref":["9.5","9.6"]},{"id":"h9-37","t":"h9","num":"9.37","q":{"uk":"Чи дає водієві перевагу в русі ввімкнення покажчика повороту?","ru":"Даёт ли водителю преимущество в движении включение указателя поворота?"},"a":[{"uk":"Завжди надає перевагу","ru":"Всегда даёт преимущество.","w":{"uk":"Сигнал лише попереджає про намір водія, а переваги в русі не дає ({p:9.4}).","ru":"Сигнал лишь предупреждает о намерении водителя, а преимущества в движении не даёт ({p:9.4})."}},{"uk":"Надає перевагу тільки під час перестроювання.","ru":"Даёт преимущество только при перестроении.","w":{"uk":"Під час перестроювання водій, навпаки, повинен дати дорогу тим, хто рухається по смузі, на яку він перестроюється ({p:10.3}).","ru":"При перестроении водитель, наоборот, должен уступить дорогу тем, кто движется по полосе, на которую он перестраивается ({p:10.3})."}},{"uk":"Не дає водієві переваги і не звільняє його від прийняття запобіжних заходів.","ru":"Не даёт водителю преимущества и не освобождает его от принятия мер предосторожности."}],"c":2,"e":{"uk":"За {p:9.4} подавання попереджувального сигналу не дає водієві переваги і не звільняє його від вжиття запобіжних заходів.","ru":"Согласно {p:9.4} подача предупредительного сигнала не даёт водителю преимущества и не освобождает его от принятия мер предосторожности."},"ref":["9.4","10.3"]},{"id":"h9-38","t":"h9","num":"9.38","q":{"uk":"Водій автомобіля, що рухається, перед перестроюванням увімкнув покажчик повороту. Чи повинен він дати дорогу транспортним засобам, на смугу яких він зібрався перестроюватися?","ru":"Водитель движущегося автомобиля перед перестроением включил указатель поворота. Должен ли он уступить дорогу транспортным средствам, на полосу которых он собрался перестроиться?"},"a":[{"uk":"Не повинен поступатися, оскільки був увімкнений покажчик повороту.","ru":"Не должен уступать, поскольку был включён указатель поворота.","w":{"uk":"Покажчик повороту лише попереджає про намір і не дає переваги в русі ({p:9.4}).","ru":"Указатель поворота лишь предупреждает о намерении и не даёт преимущества в движении ({p:9.4})."}},{"uk":"Повинен дати дорогу, оскільки подавання попереджувального сигналу покажчиками повороту не дає водієві переваги і не звільняє його від вжиття запобіжних заходів.","ru":"Должен уступить дорогу, поскольку подача предупредительного сигнала указателями поворота не даёт водителю преимущества и не освобождает его от принятия мер предосторожности."},{"uk":"Не повинен поступатися дорогою у разі, якщо він уже почав перестроювання.","ru":"Не должен уступать дорогу, если он уже начал перестроение.","w":{"uk":"Обов'язок дати дорогу діє протягом усього перестроювання: розпочатий маневр переваги не дає.","ru":"Обязанность уступить дорогу действует в течение всего перестроения: начатый манёвр преимущества не даёт."}}],"c":1,"e":{"uk":"Під час перестроювання водій повинен дати дорогу транспортним засобам, що рухаються в попутному напрямку по смузі, на яку він перестроюється ({p:10.3}), а ввімкнений покажчик повороту переваги не дає ({p:9.4}).","ru":"При перестроении водитель должен уступить дорогу транспортным средствам, движущимся в попутном направлении по полосе, на которую он перестраивается ({p:10.3}), а включённый указатель поворота преимущества не даёт ({p:9.4})."},"ref":["9.4","10.3"]},{"id":"h9-39","t":"h9","num":"9.39","q":{"uk":"Коли водієві необхідно припинити подавання сигналу рукою?","ru":"Когда водителю необходимо прекратить подачу сигнала рукой?"},"a":[{"uk":"Безпосередньо перед початком виконання маневру.","ru":"Непосредственно перед началом выполнения манёвра."},{"uk":"Відразу після завершення маневру.","ru":"Сразу после завершения манёвра.","w":{"uk":"Так припиняють сигнал покажчиками повороту, а сигнал рукою закінчують ще до початку маневру.","ru":"Так прекращают сигнал указателями поворота, а сигнал рукой заканчивают ещё до начала манёвра."}},{"uk":"Під час виконання маневру.","ru":"Во время выполнения манёвра.","w":{"uk":"Під час маневру водій має керувати обома руками, тому сигнал рукою закінчують до його початку.","ru":"Во время манёвра водитель должен управлять обеими руками, поэтому сигнал рукой заканчивают до его начала."}}],"c":0,"e":{"uk":"За {p:9.4} подавання сигналу рукою слід закінчити **безпосередньо перед початком** виконання маневру — щоб маневр водій виконував, тримаючи кермо обома руками.","ru":"Согласно {p:9.4} подачу сигнала рукой следует закончить **непосредственно перед началом** выполнения манёвра — чтобы манёвр водитель выполнял, держа руль обеими руками."},"ref":["9.4"]},{"id":"h9-40","t":"h9","num":"9.40","q":{"uk":"Коли водієві необхідно припинити подавання сигналу світловим покажчиком повороту, виконуючи маневр?","ru":"Когда водителю необходимо прекратить подачу сигнала световым указателем поворота, выполняя манёвр?"},"a":[{"uk":"Безпосередньо перед початком виконання маневру.","ru":"Непосредственно перед началом выполнения манёвра.","w":{"uk":"Так закінчують сигнал рукою; покажчик повороту має працювати до кінця маневру.","ru":"Так заканчивают сигнал рукой; указатель поворота должен работать до конца манёвра."}},{"uk":"Відразу після завершення маневру.","ru":"Сразу после завершения манёвра."},{"uk":"Під час виконання маневру.","ru":"Во время выполнения манёвра.","w":{"uk":"Вимкнений посеред маневру покажчик перестає попереджати інших учасників руху; його вимикають лише після завершення маневру.","ru":"Выключенный посреди манёвра указатель перестаёт предупреждать других участников движения; его выключают только после завершения манёвра."}}],"c":1,"e":{"uk":"За {p:9.4} сигнал покажчиками повороту припиняють **негайно після закінчення** маневру — протягом усього маневру він попереджає інших учасників руху.","ru":"Согласно {p:9.4} сигнал указателями поворота прекращают **немедленно после окончания** манёвра — в течение всего манёвра он предупреждает других участников движения."},"ref":["9.4"]},{"id":"h9-41","t":"h9","num":"9.41","q":{"uk":"На якій відстані до початку маневру подається сигнал покажчиками повороту або рукою поза населеним пунктом?","ru":"На каком расстоянии до начала манёвра подаётся сигнал указателями поворота или рукой вне населённого пункта?"},"a":[{"uk":"Не менше ніж за 150–300 м.","ru":"Не менее чем за 150–300 м.","w":{"uk":"Такої відстані Правила не встановлюють: поза населеними пунктами — не менш як 150–200 м.","ru":"Такого расстояния Правила не устанавливают: вне населённых пунктов — не менее 150–200 м."}},{"uk":"Не менше ніж за 50–100 м.","ru":"Не менее чем за 50–100 м.","w":{"uk":"50–100 м — мінімальна відстань для населених пунктів, а не для доріг поза ними.","ru":"50–100 м — минимальное расстояние для населённых пунктов, а не для дорог вне их."}},{"uk":"Не менше ніж за 150–200 м.","ru":"Не менее чем за 150–200 м."}],"c":2,"e":{"uk":"За {p:9.4} сигнал подають завчасно, але не менш як за 50–100 м у населених пунктах і **за 150–200 м поза ними**.","ru":"Согласно {p:9.4} сигнал подают заблаговременно, но не менее чем за 50–100 м в населённых пунктах и **за 150–200 м вне их**."},"ref":["9.4"]},{"id":"h9-42","t":"h9","num":"9.42","q":{"uk":"Які сигнали повинен подавати водій у разі відсутності або несправності сигналів гальмування?","ru":"Какие сигналы должен подавать водитель при отсутствии или неисправности сигналов торможения?"},"a":[{"uk":"Сигнал подається круговим обертанням правої або лівої руки, витягнутої вбік.","ru":"Сигнал подаётся круговым вращением правой или левой руки, вытянутой в сторону.","w":{"uk":"Кругових рухів рукою Правила для сигналу гальмування не передбачають, а рука, витягнута вбік, означає поворот.","ru":"Круговых движений рукой Правила для сигнала торможения не предусматривают, а рука, вытянутая в сторону, означает поворот."}},{"uk":"Сигнал подається лівою або правою рукою, піднятою вгору.","ru":"Сигнал подаётся левой или правой рукой, поднятой вверх."},{"uk":"Сигнал подається круговим обертанням правої або лівої руки, піднятою вгору.","ru":"Сигнал подаётся круговым вращением правой или левой руки, поднятой вверх.","w":{"uk":"Руку просто піднімають угору — обертати нею Правила не передбачають.","ru":"Руку просто поднимают вверх — вращать ею Правила не предусматривают."}}],"c":1,"e":{"uk":"За {p:9.3} у разі відсутності або несправності сигналів гальмування такий сигнал подають лівою або правою рукою, **піднятою вгору**.","ru":"Согласно {p:9.3} при отсутствии или неисправности сигналов торможения такой сигнал подают левой или правой рукой, **поднятой вверх**."},"ref":["9.3"]},{"id":"h9-43","t":"h9","num":"9.43","q":{"uk":"Який попереджувальний сигнал вмикається на транспортному засобі перед початком руху і зупинкою?","ru":"Какой предупредительный сигнал включается на транспортном средстве перед началом движения и остановкой?"},"a":[{"uk":"Світловий покажчик повороту.","ru":"Световой указатель поворота."},{"uk":"Аварійна сигналізація.","ru":"Аварийная сигнализация.","w":{"uk":"Аварійну сигналізацію вмикають у випадках, перелічених у {p:9.9}, а не перед звичайним рушанням чи зупинкою.","ru":"Аварийную сигнализацию включают в случаях, перечисленных в {p:9.9}, а не перед обычным началом движения или остановкой."}},{"uk":"Стоянкові вогні.","ru":"Стояночные огни.","w":{"uk":"Стоянкові вогні позначають транспортний засіб на стоянці і не попереджають про початок руху чи зупинку.","ru":"Стояночные огни обозначают транспортное средство на стоянке и не предупреждают о начале движения или остановке."}}],"c":0,"e":{"uk":"За {p:9.2} (підпункт «а») перед початком руху і зупинкою водій подає сигнали світловими покажчиками повороту відповідного напрямку.","ru":"Согласно {p:9.2} (подпункт «а») перед началом движения и остановкой водитель подаёт сигналы световыми указателями поворота соответствующего направления."},"ref":["9.2"]},{"id":"h9-44","t":"h9","num":"9.44","q":{"uk":"Чи повинні Ви як водій подавати сигнали світловим покажчиком повороту перед перестроюванням?","ru":"Должны ли вы как водитель подавать сигналы световым указателем поворота перед перестроением?"},"a":[{"uk":"Повинен тільки за наявності інших учасників дорожнього руху.","ru":"Должен только при наличии других участников дорожного движения.","w":{"uk":"Наявність інших учасників руху не впливає на обов'язок подати сигнал — когось можна й не помітити.","ru":"Наличие других участников движения не влияет на обязанность подать сигнал — кого-то можно и не заметить."}},{"uk":"Повинен завжди.","ru":"Должен всегда."},{"uk":"Зобов'язаний, якщо встигає їх ввімкнути.","ru":"Обязан, если успевает их включить.","w":{"uk":"Сигнал подають завчасно до маневру ({p:9.4}); якщо водій «не встигає», він має відкласти маневр, а не виконувати його без сигналу.","ru":"Сигнал подают заблаговременно до манёвра ({p:9.4}); если водитель «не успевает», он должен отложить манёвр, а не выполнять его без сигнала."}}],"c":1,"e":{"uk":"{p:9.2} (підпункт «б») вимагає подавати сигнал покажчиком повороту перед перестроюванням без жодних винятків, а {p:9.4} — робити це завчасно.","ru":"{p:9.2} (подпункт «б») требует подавать сигнал указателем поворота перед перестроением без каких-либо исключений, а {p:9.4} — делать это заблаговременно."},"ref":["9.2","9.4"]},{"id":"h9-45","t":"h9","num":"9.45","q":{"uk":"Чи завжди для привертання уваги водія транспортного засобу, якого обганяють, дозволене подавання звукового сигналу на дорогах за межами населеного пункту?","ru":"Всегда ли на дорогах вне населённого пункта разрешена подача звукового сигнала для привлечения внимания водителя обгоняемого транспортного средства?"},"a":[{"uk":"Дозволено завжди.","ru":"Разрешена всегда.","w":{"uk":"Дозвіл із {p:9.6} не діє в зоні знака {s:3.33}: там звуковий сигнал заборонений.","ru":"Разрешение из {p:9.6} не действует в зоне знака {s:3.33}: там звуковой сигнал запрещён."}},{"uk":"Заборонено, якщо встановлений знак «Подачу звукового сигналу заборонено».","ru":"Запрещена, если установлен знак «Подача звукового сигнала запрещена»."}],"c":1,"e":{"uk":"Поза населеними пунктами {p:9.6} дозволяє привертати увагу водія, якого обганяють, звуковим сигналом, але в зоні дії знака {s:3.33} користуватися звуковими сигналами заборонено, крім випадків, коли без цього неможливо запобігти ДТП ({p:33.3}).","ru":"Вне населённых пунктов {p:9.6} разрешает привлекать внимание водителя обгоняемого транспортного средства звуковым сигналом, но в зоне действия знака {s:3.33} пользоваться звуковыми сигналами запрещено, кроме случаев, когда без этого невозможно предотвратить ДТП ({p:33.3})."},"ref":["9.6","33.3"]},{"id":"h9-46","t":"h9","num":"9.46","q":{"uk":"Чи дозволено використовувати звуковий сигнал для привернення уваги водія транспортного засобу, якого обганяють, у населеному пункті?","ru":"Разрешено ли использовать звуковой сигнал для привлечения внимания водителя обгоняемого транспортного средства в населённом пункте?"},"a":[{"uk":"Заборонено, необхідно застосовувати лише перемикання світла фар.","ru":"Запрещено, необходимо применять только переключение света фар."},{"uk":"Дозволено за відсутності знака «Подачу звукового сигналу заборонено».","ru":"Разрешено при отсутствии знака «Подача звукового сигнала запрещена».","w":{"uk":"Знак тут ні до чого: у населеному пункті звуковий сигнал заборонений і без нього ({p:9.5}).","ru":"Знак здесь ни при чём: в населённом пункте звуковой сигнал запрещён и без него ({p:9.5})."}},{"uk":"Дозволено в будь-якому випадку.","ru":"Разрешено в любом случае.","w":{"uk":"У населеному пункті звуковий сигнал дозволений лише тоді, коли без нього неможливо запобігти ДТП ({p:9.5}).","ru":"В населённом пункте звуковой сигнал разрешён только тогда, когда без него невозможно предотвратить ДТП ({p:9.5})."}}],"c":0,"e":{"uk":"За {p:9.6} у населеному пункті увагу водія, якого обганяють, можна привертати лише перемиканням світла фар — звуковий сигнал для цього дозволений тільки поза населеними пунктами; до того ж {p:9.5} забороняє звукові сигнали в населених пунктах.","ru":"Согласно {p:9.6} в населённом пункте внимание водителя обгоняемого транспортного средства можно привлекать только переключением света фар — звуковой сигнал для этого разрешён лишь вне населённых пунктов; к тому же {p:9.5} запрещает звуковые сигналы в населённых пунктах."},"ref":["9.5","9.6"]},{"id":"h9-47","t":"h9","num":"9.47","q":{"uk":"Який попереджувальний сигнал дозволено використовувати для привернення уваги водія транспортного засобу, якого обганяють?","ru":"Какой предупредительный сигнал разрешено использовать для привлечения внимания водителя обгоняемого транспортного средства?"},"a":[{"uk":"Перемикання світла фар.","ru":"Переключение света фар.","w":{"uk":"Неповна відповідь: поза населеними пунктами можна застосовувати й звуковий сигнал.","ru":"Неполный ответ: вне населённых пунктов можно применять и звуковой сигнал."}},{"uk":"Звуковий сигнал (тільки поза населеними пунктами).","ru":"Звуковой сигнал (только вне населённых пунктов).","w":{"uk":"Неповна відповідь: перемикання світла фар дозволене і в населених пунктах, і поза ними.","ru":"Неполный ответ: переключение света фар разрешено и в населённых пунктах, и вне их."}},{"uk":"Звуковий сигнал.","ru":"Звуковой сигнал.","w":{"uk":"Звуковий сигнал для цього дозволений лише поза населеними пунктами, а не будь-де.","ru":"Звуковой сигнал для этого разрешён только вне населённых пунктов, а не где угодно."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2."},{"uk":"Відповіді 1 і 3.","ru":"Ответы 1 и 3.","w":{"uk":"Варіант 3 не враховує заборони звукових сигналів у населених пунктах ({p:9.5}).","ru":"Вариант 3 не учитывает запрета звуковых сигналов в населённых пунктах ({p:9.5})."}}],"c":3,"e":{"uk":"За {p:9.6} для привертання уваги водія, якого обганяють, можна застосовувати перемикання світла фар, а поза населеними пунктами — і звуковий сигнал.","ru":"Согласно {p:9.6} для привлечения внимания водителя обгоняемого транспортного средства можно применять переключение света фар, а вне населённых пунктов — и звуковой сигнал."},"ref":["9.6"]},{"id":"h9-48","t":"h9","num":"9.48","q":{"uk":"Що вмикається у разі вимушеної зупинки на дорозі?","ru":"Что включается при вынужденной остановке на дороге?"},"a":[{"uk":"Стоянкові вогні.","ru":"Стояночные огни.","w":{"uk":"Стоянкові вогні не замінюють аварійної сигналізації, якої вимагає {p:9.9}.","ru":"Стояночные огни не заменяют аварийную сигнализацию, которой требует {p:9.9}."}},{"uk":"Аварійна світлова сигналізація.","ru":"Аварийная световая сигнализация."},{"uk":"Габаритні ліхтарі.","ru":"Габаритные огни.","w":{"uk":"Габаритні ліхтарі не попереджають про вимушену зупинку; для цього вмикають аварійну сигналізацію.","ru":"Габаритные огни не предупреждают о вынужденной остановке; для этого включают аварийную сигнализацию."}}],"c":1,"e":{"uk":"За {p:9.9} (підпункт «а») у разі вимушеної зупинки на дорозі має бути ввімкнена аварійна світлова сигналізація.","ru":"Согласно {p:9.9} (подпункт «а») при вынужденной остановке на дороге должна быть включена аварийная световая сигнализация."},"ref":["9.9"]},{"id":"h9-49","t":"h9","num":"9.49","q":{"uk":"Які попереджувальні сигнали вмикаються на транспортних засобах під час буксирування у світлий час доби?","ru":"Какие предупредительные сигналы включаются на транспортных средствах при буксировке в светлое время суток?"},"a":[{"uk":"На обох транспортних засобах вмикаються аварійна сигналізація і ближнє світло фар.","ru":"На обоих транспортных средствах включаются аварийная сигнализация и ближний свет фар.","w":{"uk":"Правила розподіляють сигнали між транспортними засобами: аварійна сигналізація — на тому, що буксирується, ближнє світло — на тому, що буксирує.","ru":"Правила распределяют сигналы между транспортными средствами: аварийная сигнализация — на буксируемом, ближний свет — на буксирующем."}},{"uk":"На обох транспортних засобах вмикається лише аварійна сигналізація.","ru":"На обоих транспортных средствах включается только аварийная сигнализация.","w":{"uk":"На транспортному засобі, що буксирує, вмикають не аварійну сигналізацію, а ближнє світло фар ({p:9.8}).","ru":"На буксирующем транспортном средстве включают не аварийную сигнализацию, а ближний свет фар ({p:9.8})."}},{"uk":"На транспортному засобі, що буксирує, вмикається ближнє світло, а на тому, що буксирується, – аварійна сигналізація.","ru":"На буксирующем транспортном средстве включается ближний свет, а на буксируемом — аварийная сигнализация."}],"c":2,"e":{"uk":"На транспортному засобі, що буксирує, у світлу пору доби вмикають ближнє світло фар ({p:9.8}, «ґ»), а на механічному транспортному засобі, що буксирується, — аварійну сигналізацію ({p:9.9}, «г»).","ru":"На буксирующем транспортном средстве в светлое время суток включают ближний свет фар ({p:9.8}, «ґ»), а на буксируемом механическом транспортном средстве — аварийную сигнализацию ({p:9.9}, «г»)."},"ref":["9.8","9.9"]},{"id":"h9-50","t":"h9","num":"9.50","q":{"uk":"Де саме необхідно вмикати денні ходові вогні, а в разі їх відсутності в конструкції транспортного засобу – ближнє світло фар на всіх механічних транспортних засобах під час руху в світлу пору доби?","ru":"Где именно необходимо включать дневные ходовые огни, а при их отсутствии в конструкции транспортного средства — ближний свет фар на всех механических транспортных средствах во время движения в светлое время суток?"},"a":[{"uk":"На автомагістралях і дорогах для автомобілів.","ru":"На автомагистралях и дорогах для автомобилей.","w":{"uk":"Вимога не обмежується автомагістралями й дорогами для автомобілів — вона діє на всіх дорогах поза населеними пунктами.","ru":"Требование не ограничивается автомагистралями и дорогами для автомобилей — оно действует на всех дорогах вне населённых пунктов."}},{"uk":"На всіх дорогах у населених пунктах і поза населеними пунктами.","ru":"На всех дорогах в населённых пунктах и вне населённых пунктов.","w":{"uk":"У населених пунктах такої загальної вимоги немає: ближнє світло там потрібне лише в окремих випадках із {p:9.8} (колона, тунель тощо).","ru":"В населённых пунктах такого общего требования нет: ближний свет там нужен лишь в отдельных случаях из {p:9.8} (колонна, тоннель и т. п.)."}},{"uk":"На всіх дорогах поза населеними пунктами.","ru":"На всех дорогах вне населённых пунктов."}],"c":2,"e":{"uk":"За {p:9.8} на всіх механічних транспортних засобах **поза населеними пунктами** мають бути ввімкнені денні ходові вогні, а в разі їх відсутності — ближнє світло фар.","ru":"Согласно {p:9.8} на всех механических транспортных средствах **вне населённых пунктов** должны быть включены дневные ходовые огни, а при их отсутствии — ближний свет фар."},"ref":["9.8"]},{"id":"h9-51","t":"h9","num":"9.51","q":{"uk":"За яких умов на механічному транспортному засобі у світлу пору доби мають бути ввімкнені денні ходові вогні, а в разі їх відсутності в конструкції транспортного засобу – ближнє світло фар?","ru":"При каких условиях на механическом транспортном средстве в светлое время суток должны быть включены дневные ходовые огни, а при их отсутствии в конструкции транспортного средства — ближний свет фар?"},"a":[{"uk":"Під час руху на автомагістралях.","ru":"Во время движения по автомагистралям.","w":{"uk":"Вимога діє на всіх дорогах поза населеними пунктами, а не лише на автомагістралях.","ru":"Требование действует на всех дорогах вне населённых пунктов, а не только на автомагистралях."}},{"uk":"Під час руху на дорогах поза населеними пунктами з 1 жовтня до 1 травня.","ru":"Во время движения по дорогам вне населённых пунктов с 1 октября по 1 мая.","w":{"uk":"Чинні Правила не прив'язують цю вимогу до сезону: вона діє цілий рік.","ru":"Действующие Правила не привязывают это требование к сезону: оно действует круглый год."}},{"uk":"Під час руху на дорогах поза населеними пунктами.","ru":"Во время движения по дорогам вне населённых пунктов."},{"uk":"Завжди під час руху транспортного засобу.","ru":"Всегда во время движения транспортного средства.","w":{"uk":"У населених пунктах такої загальної вимоги немає — лише окремі випадки з {p:9.8} (колона, тунель тощо).","ru":"В населённых пунктах такого общего требования нет — только отдельные случаи из {p:9.8} (колонна, тоннель и т. п.)."}}],"c":2,"e":{"uk":"{p:9.8} вимагає денних ходових вогнів (а за їх відсутності — ближнього світла фар) на всіх механічних транспортних засобах під час руху **поза населеними пунктами** — цілий рік, без сезонних обмежень.","ru":"{p:9.8} требует дневных ходовых огней (а при их отсутствии — ближнего света фар) на всех механических транспортных средствах во время движения **вне населённых пунктов** — круглый год, без сезонных ограничений."},"ref":["9.8"]},{"id":"h9-52","t":"h9","num":"9.52","q":{"uk":"Під час руху у світлу пору доби на дорогах поза населеними пунктами мають бути ввімкнені денні ходові вогні, а в разі їх відсутності в конструкції транспортного засобу – ближнє світло фар:","ru":"При движении в светлое время суток по дорогам вне населённых пунктов дневные ходовые огни, а при их отсутствии в конструкции транспортного средства — ближний свет фар должны быть включены:"},"a":[{"uk":"Тільки на великовагових, великогабаритних транспортних засобах, сільськогосподарській техніці, ширина якої перевищує 2,6 м, та на транспортних засобах, що здійснюють дорожнє перевезення небезпечних вантажів.","ru":"Только на тяжеловесных, крупногабаритных транспортных средствах, сельскохозяйственной технике, ширина которой превышает 2,6 м, и на транспортных средствах, осуществляющих дорожную перевозку опасных грузов.","w":{"uk":"Для цих транспортних засобів {p:9.8} окремо вимагає ближнього світла будь-де, але поза населеними пунктами денні ходові вогні чи ближнє світло потрібні на всіх механічних транспортних засобах.","ru":"Для этих транспортных средств {p:9.8} отдельно требует ближнего света где угодно, но вне населённых пунктов дневные ходовые огни или ближний свет нужны на всех механических транспортных средствах."}},{"uk":"Тільки на маршрутних транспортних засобах, що рухаються по смузі, позначеній дорожнім знаком 5.8, назустріч загальному потоку транспортних засобів.","ru":"Только на маршрутных транспортных средствах, движущихся по полосе, обозначенной дорожным знаком 5.8, навстречу общему потоку транспортных средств.","w":{"uk":"Маршрутні транспортні засоби на смузі зі знаком {s:5.8} — окремий випадок увімкнення ближнього світла, а поза населеними пунктами вимога стосується всіх механічних транспортних засобів.","ru":"Маршрутные транспортные средства на полосе со знаком {s:5.8} — отдельный случай включения ближнего света, а вне населённых пунктов требование касается всех механических транспортных средств."}},{"uk":"На всіх механічних транспортних засобах.","ru":"На всех механических транспортных средствах."}],"c":2,"e":{"uk":"За {p:9.8} на **всіх** механічних транспортних засобах поза населеними пунктами повинні бути ввімкнені денні ходові вогні, а в разі їх відсутності — ближнє світло фар.","ru":"Согласно {p:9.8} на **всех** механических транспортных средствах вне населённых пунктов должны быть включены дневные ходовые огни, а при их отсутствии — ближний свет фар."},"ref":["9.8"]},{"id":"h9-53","t":"h9","num":"9.53","q":{"uk":"Що слід умикати під час руху на дорогах поза населеними пунктами у світлу пору доби на механічному транспортному засобі за відсутності в його конструкції денних ходових вогнів?","ru":"Что следует включать во время движения по дорогам вне населённых пунктов в светлое время суток на механическом транспортном средстве при отсутствии в его конструкции дневных ходовых огней?"},"a":[{"uk":"Аварійну світлову сигналізацію.","ru":"Аварийную световую сигнализацию.","w":{"uk":"Аварійну сигналізацію вмикають лише у випадках із {p:9.9}; денних ходових вогнів вона не замінює.","ru":"Аварийную сигнализацию включают только в случаях из {p:9.9}; дневные ходовые огни она не заменяет."}},{"uk":"Ближнє світло фар.","ru":"Ближний свет фар."},{"uk":"Габаритні ліхтарі.","ru":"Габаритные огни.","w":{"uk":"Габаритні ліхтарі вдень погано помітні й не замінюють денних ходових вогнів — Правила вимагають саме ближнього світла фар.","ru":"Габаритные огни днём плохо заметны и не заменяют дневные ходовые огни — Правила требуют именно ближнего света фар."}}],"c":1,"e":{"uk":"За {p:9.8} поза населеними пунктами вмикають денні ходові вогні, а якщо їх немає в конструкції транспортного засобу — **ближнє світло фар**.","ru":"Согласно {p:9.8} вне населённых пунктов включают дневные ходовые огни, а если их нет в конструкции транспортного средства — **ближний свет фар**."},"ref":["9.8"]},{"id":"h9-54","t":"h9","num":"9.54","q":{"uk":"Що саме слід умикати на механічних транспортних засобах поза населеними пунктами в світлий час доби?","ru":"Что именно следует включать на механических транспортных средствах вне населённых пунктов в светлое время суток?"},"a":[{"uk":"Денні ходові вогні.","ru":"Дневные ходовые огни.","w":{"uk":"Неповна відповідь: не всі транспортні засоби мають денні ходові вогні, і тоді вмикають ближнє світло фар.","ru":"Неполный ответ: не у всех транспортных средств есть дневные ходовые огни, и тогда включают ближний свет фар."}},{"uk":"Дальнє світло фар.","ru":"Дальний свет фар.","w":{"uk":"Дальнє світло можна вмикати лише в умовах недостатньої видимості й тоді, коли воно не засліплює інших водіїв ({p:9.7}, {p:9.8}).","ru":"Дальний свет можно включать только в условиях недостаточной видимости и тогда, когда он не ослепляет других водителей ({p:9.7}, {p:9.8})."}},{"uk":"Аварійну світлову сигналізацію.","ru":"Аварийную световую сигнализацию.","w":{"uk":"Аварійна сигналізація — для випадків із {p:9.9}, а не для позначення транспортного засобу під час звичайного руху.","ru":"Аварийная сигнализация — для случаев из {p:9.9}, а не для обозначения транспортного средства при обычном движении."}},{"uk":"Денні ходові вогні, а в разі їх відсутності у конструкції транспортного засобу – ближнє світло фар.","ru":"Дневные ходовые огни, а при их отсутствии в конструкции транспортного средства — ближний свет фар."}],"c":3,"e":{"uk":"За {p:9.8} поза населеними пунктами на всіх механічних транспортних засобах повинні бути ввімкнені денні ходові вогні, а в разі їх відсутності в конструкції — ближнє світло фар.","ru":"Согласно {p:9.8} вне населённых пунктов на всех механических транспортных средствах должны быть включены дневные ходовые огни, а при их отсутствии в конструкции — ближний свет фар."},"ref":["9.8"]},{"id":"h9-55","t":"h9","num":"9.55","q":{"uk":"Чи завжди під час руху в тунелі потрібно вмикати ближнє світло фар?","ru":"Всегда ли во время движения в тоннеле нужно включать ближний свет фар?"},"a":[{"uk":"Можна не вмикати, якщо тунель має штучне освітлення.","ru":"Можно не включать, если тоннель имеет искусственное освещение.","w":{"uk":"Штучне освітлення не звільняє від вимоги {p:9.8}: у тунелі ближнє світло вмикають завжди.","ru":"Искусственное освещение не освобождает от требования {p:9.8}: в тоннеле ближний свет включают всегда."}},{"uk":"Світло вмикається завжди.","ru":"Свет включается всегда."}],"c":1,"e":{"uk":"{p:9.8} (підпункт «д») вимагає вмикати ближнє світло фар у тунелях без жодних винятків — штучне освітлення тунелю цього обов'язку не скасовує.","ru":"{p:9.8} (подпункт «д») требует включать ближний свет фар в тоннелях без каких-либо исключений — искусственное освещение тоннеля эту обязанность не отменяет."},"ref":["9.8"]},{"id":"h9-56","t":"h9","num":"9.56","q":{"uk":"Які попереджувальні сигнали вмикаються у світлий час доби на транспортному засобі, що буксирує?","ru":"Какие предупредительные сигналы включаются в светлое время суток на буксирующем транспортном средстве?"},"a":[{"uk":"Аварійна сигналізація разом із ближнім світлом фар.","ru":"Аварийная сигнализация вместе с ближним светом фар.","w":{"uk":"Аварійну сигналізацію вмикають на транспортному засобі, що буксирується ({p:9.9}, «г»), а не на тому, що буксирує.","ru":"Аварийную сигнализацию включают на буксируемом транспортном средстве ({p:9.9}, «г»), а не на буксирующем."}},{"uk":"Ближнє світло фар.","ru":"Ближний свет фар."},{"uk":"Аварійна сигналізація.","ru":"Аварийная сигнализация.","w":{"uk":"Аварійна сигналізація потрібна на транспортному засобі, що буксирується; той, що буксирує, позначають ближнім світлом фар.","ru":"Аварийная сигнализация нужна на буксируемом транспортном средстве; буксирующее обозначают ближним светом фар."}}],"c":1,"e":{"uk":"За {p:9.8} (підпункт «ґ») на транспортному засобі, що буксирує, у світлу пору доби має бути ввімкнене ближнє світло фар.","ru":"Согласно {p:9.8} (подпункт «ґ») на буксирующем транспортном средстве в светлое время суток должен быть включён ближний свет фар."},"ref":["9.8","9.9"]},{"id":"h9-57","t":"h9","num":"9.57","q":{"uk":"У якому випадку на транспортних засобах колони не вмикається ближнє світло фар у світлу пору доби?","ru":"В каком случае на транспортных средствах колонны не включается ближний свет фар в светлое время суток?"},"a":[{"uk":"При супроводі транспортними засобами з увімкненими проблисковими маячками червоного та синього кольорів.","ru":"При сопровождении транспортными средствами с включёнными проблесковыми маячками красного и синего цветов.","w":{"uk":"За такого супроводу можна не встановлювати розпізнавальний знак «Колона» ({p:25.1}), але ближнє світло фар однаково вмикають ({p:9.8}).","ru":"При таком сопровождении можно не устанавливать опознавательный знак «Колонна» ({p:25.1}), но ближний свет фар всё равно включают ({p:9.8})."}},{"uk":"При ввімкненні на транспортних засобах денних ходових вогнів.","ru":"При включении на транспортных средствах дневных ходовых огней.","w":{"uk":"Денні ходові вогні не замінюють ближнього світла фар, якого {p:9.8} вимагає для колони.","ru":"Дневные ходовые огни не заменяют ближний свет фар, которого {p:9.8} требует для колонны."}},{"uk":"Завжди на транспортних засобах колони вмикається ближнє світло фар.","ru":"На транспортных средствах колонны ближний свет фар включается всегда."}],"c":2,"e":{"uk":"{p:9.8} (підпункт «а») вимагає ближнього світла фар на транспортних засобах колони без винятків — ні супровід, ні денні ходові вогні цього обов'язку не скасовують.","ru":"{p:9.8} (подпункт «а») требует ближнего света фар на транспортных средствах колонны без исключений — ни сопровождение, ни дневные ходовые огни эту обязанность не отменяют."},"ref":["9.8","25.1"]},{"id":"h9-58","t":"h9","num":"9.58","q":{"uk":"Ближнє світло фар у світлу пору доби як попереджувальний сигнал вмикається:","ru":"Ближний свет фар в светлое время суток как предупредительный сигнал включается:"},"a":[{"uk":"На механічному транспортному засобі, що буксирується.","ru":"На буксируемом механическом транспортном средстве.","w":{"uk":"Транспортний засіб, що буксирується, позначають аварійною сигналізацією ({p:9.9}, «г»), а не ближнім світлом.","ru":"Буксируемое транспортное средство обозначают аварийной сигнализацией ({p:9.9}, «г»), а не ближним светом."}},{"uk":"На механічному транспортному засобі, що буксирується і що буксирує.","ru":"На буксируемом и буксирующем механических транспортных средствах.","w":{"uk":"Ближнє світло вмикають лише на транспортному засобі, що буксирує; на тому, що буксирується, — аварійну сигналізацію.","ru":"Ближний свет включают только на буксирующем транспортном средстве; на буксируемом — аварийную сигнализацию."}},{"uk":"На механічному транспортному засобі, що буксирує.","ru":"На буксирующем механическом транспортном средстве.","w":{"uk":"Неповна відповідь: ближнє світло вмикають і на транспортних засобах колони.","ru":"Неполный ответ: ближний свет включают и на транспортных средствах колонны."}},{"uk":"На транспортних засобах колони.","ru":"На транспортных средствах колонны.","w":{"uk":"Неповна відповідь: ближнє світло вмикають і на транспортному засобі, що буксирує.","ru":"Неполный ответ: ближний свет включают и на буксирующем транспортном средстве."}},{"uk":"Відповіді 3 і 4.","ru":"Ответы 3 и 4."}],"c":4,"e":{"uk":"За {p:9.8} ближнє світло фар у світлу пору доби вмикають, зокрема, у колоні (підпункт «а») і на транспортному засобі, що буксирує (підпункт «ґ»).","ru":"Согласно {p:9.8} ближний свет фар в светлое время суток включают, в частности, в колонне (подпункт «а») и на буксирующем транспортном средстве (подпункт «ґ»)."},"ref":["9.8","9.9"]},{"id":"h9-59","t":"h9","num":"9.59","q":{"uk":"У яких випадках Ви як водій повинні подавати сигнали покажчиками повороту?","ru":"В каких случаях вы как водитель должны подавать сигналы указателями поворота?"},"a":[{"uk":"У населених пунктах перед початком руху і зупинкою.","ru":"В населённых пунктах перед началом движения и остановкой.","w":{"uk":"Обов'язок не обмежується населеними пунктами і стосується не лише рушання та зупинки, а й перестроювання, повороту й розвороту.","ru":"Обязанность не ограничивается населёнными пунктами и касается не только начала движения и остановки, но и перестроения, поворота и разворота."}},{"uk":"Перед початком руху, зупинкою, перестроюванням, поворотом або розворотом, якщо є інші учасники дорожнього руху, а також при інтенсивному русі.","ru":"Перед началом движения, остановкой, перестроением, поворотом или разворотом, если есть другие участники дорожного движения, а также при интенсивном движении.","w":{"uk":"Сигнал подають незалежно від наявності інших учасників руху та інтенсивності руху.","ru":"Сигнал подают независимо от наличия других участников движения и интенсивности движения."}},{"uk":"Завжди перед початком руху, зупинкою, перестроюванням, поворотом або розворотом.","ru":"Всегда перед началом движения, остановкой, перестроением, поворотом или разворотом."}],"c":2,"e":{"uk":"{p:9.2} зобов'язує подавати сигнали покажчиками повороту перед початком руху і зупинкою, а також перед перестроюванням, поворотом або розворотом — завжди, незалежно від місця й дорожньої обстановки.","ru":"{p:9.2} обязывает подавать сигналы указателями поворота перед началом движения и остановкой, а также перед перестроением, поворотом или разворотом — всегда, независимо от места и дорожной обстановки."},"ref":["9.2"]},{"id":"h9-60","t":"h9","num":"9.60","q":{"uk":"Для того, щоб припаркувати Ваш транспортний засіб праворуч, Ви повинні увімкнути:","ru":"Для того чтобы припарковать ваше транспортное средство справа, вы должны включить:"},"a":[{"uk":"Світловий покажчик повороту.","ru":"Световой указатель поворота."},{"uk":"Аварійну сигналізацію.","ru":"Аварийную сигнализацию.","w":{"uk":"Аварійну сигналізацію вмикають у випадках із {p:9.9}, а не перед звичайною зупинкою для паркування.","ru":"Аварийную сигнализацию включают в случаях из {p:9.9}, а не перед обычной остановкой для парковки."}},{"uk":"Стоянкові вогні.","ru":"Стояночные огни.","w":{"uk":"Стоянкові вогні позначають транспортний засіб, що вже стоїть, і не попереджають про намір зупинитися.","ru":"Стояночные огни обозначают уже стоящее транспортное средство и не предупреждают о намерении остановиться."}}],"c":0,"e":{"uk":"Перед зупинкою водій вмикає покажчик повороту відповідного (тут — правого) напрямку ({p:9.2}, «а») — так водії позаду, як-от автомобіль у дзеркалі на малюнку, розуміють його намір.","ru":"Перед остановкой водитель включает указатель поворота соответствующего (здесь — правого) направления ({p:9.2}, «а») — так водители сзади, как автомобиль в зеркале на рисунке, понимают его намерение."},"ref":["9.2"],"pic":["img/hsc/9-60-1.jpg"]},{"id":"h10-1","t":"h10","num":"10.1","q":{"uk":"Ви водій синього автомобіля, виконаєте розворот:","ru":"Вы водитель синего автомобиля, выполните разворот:"},"a":[{"uk":"По траєкторії А.","ru":"По траектории А.","w":{"uk":"Неповна відповідь: розворот за траєкторією В після переїзду теж дозволений.","ru":"Неполный ответ: разворот по траектории В после переезда тоже разрешён."}},{"uk":"По траєкторії Б.","ru":"По траектории Б.","w":{"uk":"Траєкторія Б — це розворот на залізничному переїзді, а його прямо заборонено {p:10.7}.","ru":"Траектория Б — это разворот на железнодорожном переезде, а он прямо запрещён {p:10.7}."}},{"uk":"По траєкторії В.","ru":"По траектории В.","w":{"uk":"Неповна відповідь: розворот за траєкторією А перед переїздом теж дозволений.","ru":"Неполный ответ: разворот по траектории А перед переездом тоже разрешён."}},{"uk":"По траєкторіях А і В.","ru":"По траекториям А и В."},{"uk":"По траєкторіях А, Б і В.","ru":"По траекториям А, Б и В.","w":{"uk":"Сюди входить траєкторія Б — розворот на переїзді, заборонений {p:10.7}.","ru":"Сюда входит траектория Б — разворот на переезде, запрещённый {p:10.7}."}}],"c":3,"e":{"uk":"Траєкторія Б проходить по залізничному переїзду, де розворот заборонено {p:10.7}, а розвороти А (перед переїздом) і В (після нього) виконуються поза переїздом, тож дозволені.","ru":"Траектория Б проходит по железнодорожному переезду, где разворот запрещён {p:10.7}, а развороты А (перед переездом) и В (после него) выполняются вне переезда, поэтому разрешены."},"ref":["10.7"],"pic":["img/hsc/10-1-1.jpg"]},{"id":"h10-2","t":"h10","num":"10.2","q":{"uk":"В'їжджаючи на дорогу по смузі розгону, водій повинен:","ru":"Въезжая на дорогу по полосе разгона, водитель должен:"},"a":[{"uk":"Вливатися в транспортний потік, даючи дорогу транспортним засобам, що рухаються по цій дорозі.","ru":"Вливаться в транспортный поток, уступая дорогу транспортным средствам, движущимся по этой дороге."},{"uk":"Вливатися в транспортний потік, інші водії, побачивши його, повинні обов'язково дати йому дорогу.","ru":"Вливаться в транспортный поток, а другие водители, увидев его, обязательно должны уступить ему дорогу.","w":{"uk":"Перевагу мають ті, хто вже рухається дорогою: водій зі смуги розгону перестроюється і сам повинен дати їм дорогу {p:10.3}.","ru":"Преимущество имеют те, кто уже движется по дороге: водитель с полосы разгона перестраивается и сам должен уступить им дорогу {p:10.3}."}}],"c":0,"e":{"uk":"За {p:10.8} водій, що в'їжджає на дорогу смугою розгону, рухається нею і вливається в потік, **даючи дорогу** транспортним засобам, які вже рухаються цією дорогою.","ru":"По {p:10.8} водитель, въезжающий на дорогу по полосе разгона, движется по ней и вливается в поток, **уступая дорогу** транспортным средствам, которые уже движутся по этой дороге."},"ref":["10.8"],"pic":["img/hsc/10-2-1.jpg"]},{"id":"h10-3","t":"h10","num":"10.3","q":{"uk":"Чи дозволено рух заднім ходом на автомагістралях і дорогах для автомобілів?","ru":"Разрешено ли движение задним ходом на автомагистралях и дорогах для автомобилей?"},"a":[{"uk":"Дозволено, якщо неможливо під'їхати до об'єкта іншим способом, забезпечивши безпеку руху.","ru":"Разрешено, если невозможно подъехать к объекту иным способом, обеспечив безопасность движения.","w":{"uk":"Виняток «неможливо під'їхати до об'єкта іншим чином» стосується лише доріг з одностороннім рухом, а не автомагістралей і доріг для автомобілів.","ru":"Исключение «невозможно подъехать к объекту иным способом» касается только дорог с односторонним движением, а не автомагистралей и дорог для автомобилей."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":1,"e":{"uk":"{p:10.10} прямо забороняє рух заднім ходом на автомагістралях ({s:5.1}) і дорогах для автомобілів ({s:5.3}) — без жодних винятків.","ru":"{p:10.10} прямо запрещает движение задним ходом на автомагистралях ({s:5.1}) и дорогах для автомобилей ({s:5.3}) — без каких-либо исключений."},"ref":["10.10"],"pic":["img/hsc/10-3-1.jpg"]},{"id":"h10-4","t":"h10","num":"10.4","q":{"uk":"Чи дозволено рух заднім ходом у тунелях, якщо неможливо під'їхати до об'єкта іншим способом?","ru":"Разрешено ли движение задним ходом в тоннелях, если невозможно подъехать к объекту иным способом?"},"a":[{"uk":"Заборонено.","ru":"Запрещено."},{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"Заборона в тунелях (а також на в'їздах і виїздах з них) безумовна, і неможливість під'їхати інакше її не скасовує.","ru":"Запрет в тоннелях (а также на въездах и выездах из них) безусловный, и невозможность подъехать иначе его не отменяет."}}],"c":0,"e":{"uk":"Тунелі входять до переліку місць, де рух заднім ходом заборонено {p:10.10}; умова «неможливо під'їхати іншим чином» дозволяє його лише на дорогах з одностороннім рухом.","ru":"Тоннели входят в перечень мест, где движение задним ходом запрещено {p:10.10}; условие «невозможно подъехать иным способом» разрешает его только на дорогах с односторонним движением."},"ref":["10.10"],"pic":["img/hsc/10-4-1.jpg"]},{"id":"h10-5","t":"h10","num":"10.5","q":{"uk":"Чи дозволено в даному місці небезпечного повороту рух заднім ходом?","ru":"Разрешено ли в данном месте опасного поворота движение задним ходом?"},"a":[{"uk":"Дозволено за умови забезпечення безпеки дорожнього руху.","ru":"Разрешено при условии обеспечения безопасности дорожного движения.","w":{"uk":"Заборона на ділянках з обмеженою оглядовістю безумовна: водій не бачить, що за поворотом, тож забезпечити безпеку він не може.","ru":"Запрет на участках с ограниченной обзорностью безусловный: водитель не видит, что за поворотом, поэтому обеспечить безопасность он не может."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":1,"e":{"uk":"На небезпечному повороті ({s:1.1}) закруглення дороги й дерева обмежують оглядовість {p:1.10}, а на ділянках з обмеженою оглядовістю рух заднім ходом заборонено {p:10.10}.","ru":"На опасном повороте ({s:1.1}) закругление дороги и деревья ограничивают обзорность {p:1.10}, а на участках с ограниченной обзорностью движение задним ходом запрещено {p:10.10}."},"ref":["10.10","1.10"],"pic":["img/hsc/10-5-1.jpg"]},{"id":"h10-6","t":"h10","num":"10.6","q":{"uk":"Чи дозволено автомобілю рух заднім ходом у даному місці в умовах недостатньої видимості?","ru":"Разрешено ли автомобилю движение задним ходом в данном месте в условиях недостаточной видимости?"},"a":[{"uk":"Заборонено.","ru":"Запрещено."},{"uk":"Дозволено за умови забезпечення безпеки руху.","ru":"Разрешено при условии обеспечения безопасности движения.","w":{"uk":"Заборона в умовах недостатньої видимості та на перехрестях безумовна, її не знімає обіцянка «забезпечити безпеку».","ru":"Запрет в условиях недостаточной видимости и на перекрёстках безусловный, его не снимает обещание «обеспечить безопасность»."}}],"c":0,"e":{"uk":"На малюнку туман, тобто недостатня видимість {p:1.10}, а маневр виконується ще й на перехресті — в обох випадках рух заднім ходом заборонено {p:10.10}.","ru":"На рисунке туман, то есть недостаточная видимость {p:1.10}, а манёвр выполняется ещё и на перекрёстке — в обоих случаях движение задним ходом запрещено {p:10.10}."},"ref":["10.10","1.10"],"pic":["img/hsc/10-6-1.jpg"]},{"id":"h10-7","t":"h10","num":"10.7","q":{"uk":"Як роз'їдуться транспортні засоби на лісовій дорозі?","ru":"Как разъедутся транспортные средства на лесной дороге?"},"a":[{"uk":"Білий автомобіль проїде першим, синій – другим.","ru":"Белый автомобиль проедет первым, синий — вторым."},{"uk":"Синій автомобіль проїде першим, білий – другим.","ru":"Синий автомобиль проедет первым, белый — вторым.","w":{"uk":"Синій мав би перевагу, лише якби наближався до білого справа, а тут навпаки: білий у синього справа.","ru":"Синий имел бы преимущество, только если бы приближался к белому справа, а здесь наоборот: белый у синего справа."}}],"c":0,"e":{"uk":"Знаків пріоритету немає, траєкторії перетинаються, тож діє {p:10.11}: дорогу дає той, до кого інший наближається справа. Білий автомобіль у синього справа, тому синій поступається, і білий проїжджає першим.","ru":"Знаков приоритета нет, траектории пересекаются, поэтому действует {p:10.11}: уступает тот, к кому другой приближается справа. Белый автомобиль у синего справа, поэтому синий уступает, и белый проезжает первым."},"ref":["10.11"],"pic":["img/hsc/10-7-1.jpg"]},{"id":"h10-8","t":"h10","num":"10.8","q":{"uk":"Як роз'їдуться транспортні засоби в житловій зоні?","ru":"Как разъедутся транспортные средства в жилой зоне?"},"a":[{"uk":"Жовтий автомобіль проїде першим, сірий – другим.","ru":"Жёлтый автомобиль проедет первым, серый — вторым.","w":{"uk":"Жовтий не має переваги: сірий наближається до нього справа, тож саме жовтий повинен дати дорогу {p:10.11}.","ru":"Жёлтый не имеет преимущества: серый приближается к нему справа, поэтому именно жёлтый должен уступить дорогу {p:10.11}."}},{"uk":"Сірий автомобіль проїде першим, жовтий – другим.","ru":"Серый автомобиль проедет первым, жёлтый — вторым."}],"c":1,"e":{"uk":"У житловій зоні знаків пріоритету немає, траєкторії перетинаються, тож діє {p:10.11}: сірий автомобіль наближається до жовтого з правого боку, тому жовтий дає дорогу, і сірий проїжджає першим.","ru":"В жилой зоне знаков приоритета нет, траектории пересекаются, поэтому действует {p:10.11}: серый автомобиль приближается к жёлтому справа, поэтому жёлтый уступает дорогу, и серый проезжает первым."},"ref":["10.11"],"pic":["img/hsc/10-8-1.jpg"]},{"id":"h10-9","t":"h10","num":"10.9","q":{"uk":"Ви, водій автомобіля, виїжджаючи з житлової зони, повинні дати дорогу:","ru":"Вы, водитель автомобиля, выезжая из жилой зоны, должны уступить дорогу:"},"a":[{"uk":"Тільки автомобілю.","ru":"Только автомобилю.","w":{"uk":"Неповна відповідь: пішохода, який перетинає шлях Вашого руху, теж треба пропустити {p:10.2}.","ru":"Неполный ответ: пешехода, который пересекает путь вашего движения, тоже нужно пропустить {p:10.2}."}},{"uk":"Тільки пішоходу.","ru":"Только пешеходу.","w":{"uk":"Неповна відповідь: жовтий автомобіль рухається дорогою, тож йому теж треба дати дорогу {p:10.2}.","ru":"Неполный ответ: жёлтый автомобиль движется по дороге, поэтому ему тоже нужно уступить дорогу {p:10.2}."}},{"uk":"Автомобілю і пішоходу.","ru":"Автомобилю и пешеходу."}],"c":2,"e":{"uk":"Знак {s:5.35} показує, що Ви виїжджаєте з житлової зони, а за {p:10.2} при цьому треба дати дорогу і пішоходам, і транспортним засобам, що рухаються дорогою.","ru":"Знак {s:5.35} показывает, что вы выезжаете из жилой зоны, а по {p:10.2} при этом нужно уступить дорогу и пешеходам, и транспортным средствам, движущимся по дороге."},"ref":["10.2"],"pic":["img/hsc/10-9-1.jpg"]},{"id":"h10-10","t":"h10","num":"10.10","q":{"uk":"Ви, як водій автомобіля, повертаючи праворуч в показаній ситуації повинні:","ru":"Вы как водитель автомобиля, поворачивая направо в показанной ситуации, должны:"},"a":[{"uk":"Дати дорогу велосипедисту в будь – якому випадку.","ru":"Уступить дорогу велосипедисту в любом случае."},{"uk":"Не повинні давати дорогу велосипедисту, так як велосипедист рухається велосипедною смугою.","ru":"Не должны уступать дорогу велосипедисту, так как велосипедист движется по велосипедной полосе.","w":{"uk":"Саме тому, що велосипедист їде прямо своєю смугою, він має перевагу перед тим, хто повертає і перетинає цю смугу.","ru":"Именно потому, что велосипедист едет прямо по своей полосе, он имеет преимущество перед тем, кто поворачивает и пересекает эту полосу."}},{"uk":"Посигналити велосипедисту і повернути першим.","ru":"Подать звуковой сигнал велосипедисту и повернуть первым.","w":{"uk":"Звуковий сигнал не дає переваги в русі; повернувши першим, Ви створите велосипедисту перешкоду {p:10.1}.","ru":"Звуковой сигнал не даёт преимущества в движении; повернув первым, вы создадите велосипедисту помеху {p:10.1}."}}],"c":0,"e":{"uk":"Велосипедист рухається прямо велосипедною смугою ({s:5.88}), яку Ви перетинаєте, повертаючи праворуч. Маневр не повинен створювати йому перешкод {p:10.1}, а при повороті треба дати дорогу велосипедистам, які рухаються прямо в попутному напрямку {p:16.2}.","ru":"Велосипедист движется прямо по велосипедной полосе ({s:5.88}), которую вы пересекаете, поворачивая направо. Манёвр не должен создавать ему помех {p:10.1}, а при повороте нужно уступить дорогу велосипедистам, движущимся прямо в попутном направлении {p:16.2}."},"ref":["10.1","16.2"],"pic":["img/hsc/10-10-1.jpg"]},{"id":"h10-11","t":"h10","num":"10.11","q":{"uk":"Ви водій сірого автомобіля, вирішили перестроїтись праворуч. Ваші дії:","ru":"Вы водитель серого автомобиля, решили перестроиться направо. Ваши действия:"},"a":[{"uk":"Почнете перестроюватися, бо знаходитись ліворуч від водія білого автомобіля на дорозі з одностороннім рухом і тому маєте перевагу.","ru":"Начнёте перестраиваться, так как находитесь слева от водителя белого автомобиля на дороге с односторонним движением и поэтому имеете преимущество.","w":{"uk":"Правило про розташування стосується лише одночасного перестроювання, і перевагу там має правий, а не лівий; односторонній рух нічого не змінює.","ru":"Правило о расположении касается только одновременного перестроения, и преимущество там имеет правый, а не левый; одностороннее движение ничего не меняет."}},{"uk":"Почнете перестроюватися, бо маєте перевагу відносно водія білого автомобіля.","ru":"Начнёте перестраиваться, так как имеете преимущество перед водителем белого автомобиля.","w":{"uk":"Переваги немає: той, хто перестроюється, поступається транспортним засобам, які вже рухаються смугою, на яку він перестроюється {p:10.3}.","ru":"Преимущества нет: перестраивающийся уступает транспортным средствам, которые уже движутся по полосе, на которую он перестраивается {p:10.3}."}},{"uk":"Дасте дорогу водію білого автомобіля і переконавшись, що це буде безпечно і не створить перешкод або небезпеки іншим учасникам руху, виконаєте маневр.","ru":"Уступите дорогу водителю белого автомобиля и, убедившись, что это будет безопасно и не создаст помех или опасности другим участникам движения, выполните манёвр."}],"c":2,"e":{"uk":"Білий автомобіль їде прямо смугою, на яку Ви хочете перестроїтися, тому за {p:10.3} Ви повинні дати йому дорогу, а перед маневром переконатися, що він безпечний {p:10.1}.","ru":"Белый автомобиль едет прямо по полосе, на которую вы хотите перестроиться, поэтому по {p:10.3} вы должны уступить ему дорогу, а перед манёвром убедиться, что он безопасен {p:10.1}."},"ref":["10.1","10.3"],"pic":["img/hsc/10-11-1.jpg"]},{"id":"h10-12","t":"h10","num":"10.12","q":{"uk":"Ви водій білого автомобіля, вирішили перестроїтись ліворуч. Ваші дії:","ru":"Вы водитель белого автомобиля, решили перестроиться налево. Ваши действия:"},"a":[{"uk":"Почнете перестроюватися, бо знаходитись праворуч від водія сірого автомобіля на дорозі з одностороннім рухом і тому маєте перевагу.","ru":"Начнёте перестраиваться, так как находитесь справа от водителя серого автомобиля на дороге с односторонним движением и поэтому имеете преимущество.","w":{"uk":"Перевага правого діє лише за **одночасного** перестроювання, а сірий автомобіль не перестроюється, а їде прямо.","ru":"Преимущество правого действует только при **одновременном** перестроении, а серый автомобиль не перестраивается, а едет прямо."}},{"uk":"Почнете перестроюватися, бо маєте перевагу відносно водія сірого автомобіля.","ru":"Начнёте перестраиваться, так как имеете преимущество перед водителем серого автомобиля.","w":{"uk":"Той, хто перестроюється, не має переваги перед тим, хто вже рухається смугою, на яку він перестроюється {p:10.3}.","ru":"Перестраивающийся не имеет преимущества перед тем, кто уже движется по полосе, на которую он перестраивается {p:10.3}."}},{"uk":"Дасте дорогу водію сірого автомобіля і переконавшись, що це буде безпечно і не створить перешкод або небезпеки іншим учасникам руху, виконаєте маневр.","ru":"Уступите дорогу водителю серого автомобиля и, убедившись, что это будет безопасно и не создаст помех или опасности другим участникам движения, выполните манёвр."}],"c":2,"e":{"uk":"Сірий автомобіль їде прямо лівою смугою, на яку Ви хочете перестроїтися, тож за {p:10.3} Ви повинні дати йому дорогу, а перед маневром переконатися, що він безпечний {p:10.1}.","ru":"Серый автомобиль едет прямо по левой полосе, на которую вы хотите перестроиться, поэтому по {p:10.3} вы должны уступить ему дорогу, а перед манёвром убедиться, что он безопасен {p:10.1}."},"ref":["10.1","10.3"],"pic":["img/hsc/10-12-1.jpg"]},{"id":"h10-13","t":"h10","num":"10.13","q":{"uk":"Ви водій білого автомобіля, вирішили перестроїтись ліворуч, а водій сірого автомобіля одночасно з Вами вирішив перестроїтись праворуч. Ви:","ru":"Вы водитель белого автомобиля, решили перестроиться налево, а водитель серого автомобиля одновременно с вами решил перестроиться направо. Вы:"},"a":[{"uk":"Маєте перевагу за одночасного перестроювання, бо знаходитись праворуч від водія сірого автомобіля.","ru":"Имеете преимущество при одновременном перестроении, так как находитесь справа от водителя серого автомобиля."},{"uk":"Не маєте переваги перед водієм сірого автомобіля.","ru":"Не имеете преимущества перед водителем серого автомобиля.","w":{"uk":"За одночасного перестроювання перевага є — у того, хто праворуч, тобто у Вас {p:10.3}.","ru":"При одновременном перестроении преимущество есть — у того, кто справа, то есть у вас {p:10.3}."}},{"uk":"Повинні дати дорогу згідно правил дорожнього руху в такій ситуації, бо рухаєтеся на дорозі з одностороннім рухом.","ru":"Должны уступить дорогу согласно правилам дорожного движения в такой ситуации, так как движетесь по дороге с односторонним движением.","w":{"uk":"Односторонній рух не змінює правила одночасного перестроювання: поступається лівий, а не правий.","ru":"Одностороннее движение не меняет правила одновременного перестроения: уступает левый, а не правый."}}],"c":0,"e":{"uk":"За одночасного перестроювання водій, який знаходиться ліворуч, повинен дати дорогу тому, хто праворуч {p:10.3}; білий автомобіль — праворуч від сірого, тож перевага у Вас.","ru":"При одновременном перестроении водитель, находящийся слева, должен уступить дорогу тому, кто справа {p:10.3}; белый автомобиль — справа от серого, поэтому преимущество у вас."},"ref":["10.3"],"pic":["img/hsc/10-13-1.jpg"]},{"id":"h10-14","t":"h10","num":"10.14","q":{"uk":"Ви водій сірого автомобіля, вирішили перестроїтись праворуч, а водій білого автомобіля одночасно з Вами вирішив перестроїтись ліворуч. Ви:","ru":"Вы водитель серого автомобиля, решили перестроиться направо, а водитель белого автомобиля одновременно с вами решил перестроиться налево. Вы:"},"a":[{"uk":"Маєте перевагу за одночасного перестроювання, бо знаходитись ліворуч від водія білого автомобіля.","ru":"Имеете преимущество при одновременном перестроении, так как находитесь слева от водителя белого автомобиля.","w":{"uk":"Навпаки: розташування ліворуч зобов'язує дати дорогу, а перевагу має той, хто праворуч {p:10.3}.","ru":"Наоборот: положение слева обязывает уступить дорогу, а преимущество имеет тот, кто справа {p:10.3}."}},{"uk":"Повинні дати дорогу водію білого автомобіля бо за одночасного перестроювання білий автомобіль має перевагу.","ru":"Должны уступить дорогу водителю белого автомобиля, так как при одновременном перестроении белый автомобиль имеет преимущество."},{"uk":"Не повинні давати дорогу згідно правил дорожнього руху в такій ситуації, бо рухаєтеся на дорозі з одностороннім рухом.","ru":"Не должны уступать дорогу согласно правилам дорожного движения в такой ситуации, так как движетесь по дороге с односторонним движением.","w":{"uk":"Правило одночасного перестроювання діє на будь-якій дорозі, зокрема з одностороннім рухом ({s:5.5}).","ru":"Правило одновременного перестроения действует на любой дороге, в том числе с односторонним движением ({s:5.5})."}}],"c":1,"e":{"uk":"За одночасного перестроювання водій, що ліворуч, дає дорогу тому, хто праворуч {p:10.3}; сірий автомобіль — ліворуч від білого, тож Ви повинні його пропустити.","ru":"При одновременном перестроении водитель, находящийся слева, уступает дорогу тому, кто справа {p:10.3}; серый автомобиль — слева от белого, поэтому вы должны его пропустить."},"ref":["10.3"],"pic":["img/hsc/10-14-1.jpg"]},{"id":"h10-15","t":"h10","num":"10.15","q":{"uk":"Ви водій синього автомобіля:","ru":"Вы водитель синего автомобиля:"},"a":[{"uk":"Виконаєте розворот перед залізничним переїздом.","ru":"Выполните разворот перед железнодорожным переездом.","w":{"uk":"Неповна відповідь: розворот після переїзду теж дозволений.","ru":"Неполный ответ: разворот после переезда тоже разрешён."}},{"uk":"Виконаєте розворот після залізничного переїзду.","ru":"Выполните разворот после железнодорожного переезда.","w":{"uk":"Неповна відповідь: розворот перед переїздом теж дозволений.","ru":"Неполный ответ: разворот перед переездом тоже разрешён."}},{"uk":"Виконаєте розворот на залізничному переїзді.","ru":"Выполните разворот на железнодорожном переезде.","w":{"uk":"Розворот на залізничному переїзді прямо заборонено {p:10.7}.","ru":"Разворот на железнодорожном переезде прямо запрещён {p:10.7}."}},{"uk":"Виконаєте умови пунктів 1 або 2.","ru":"Выполните условия пунктов 1 или 2."}],"c":3,"e":{"uk":"Розворот заборонено лише на самому залізничному переїзді {p:10.7}, тож розвернутися можна або перед ним (траєкторія 1), або після нього (траєкторія 2).","ru":"Разворот запрещён только на самом железнодорожном переезде {p:10.7}, поэтому развернуться можно либо перед ним (траектория 1), либо после него (траектория 2)."},"ref":["10.7"],"pic":["img/hsc/10-15-1.jpg"]},{"id":"h10-16","t":"h10","num":"10.16","q":{"uk":"Яким шляхом водій правильно виконує поворот на дорогу зі смугою для розгону?","ru":"Каким путём водитель правильно выполняет поворот на дорогу с полосой для разгона?"},"a":[{"uk":"Шляхом А.","ru":"Путём А.","w":{"uk":"Шлях А веде одразу в основну смугу повз смугу розгону — це суперечить {p:10.8} і створює перешкоди транспорту, що рухається дорогою.","ru":"Путь А ведёт сразу в основную полосу мимо полосы разгона — это противоречит {p:10.8} и создаёт помехи транспорту, движущемуся по дороге."}},{"uk":"Шляхом Б.","ru":"Путём Б."},{"uk":"Обидва варіанти правильні.","ru":"Оба варианта правильные.","w":{"uk":"Правильний лише шлях Б: якщо є смуга розгону, рухатися треба саме по ній {p:10.8}.","ru":"Правильный только путь Б: если есть полоса разгона, двигаться нужно именно по ней {p:10.8}."}}],"c":1,"e":{"uk":"Знак {s:5.22} показує, що в місці в'їзду є смуга розгону, а за {p:10.8} водій має рухатися саме нею (шлях Б) і вливатися в потік, даючи дорогу транспортним засобам, які рухаються дорогою.","ru":"Знак {s:5.22} показывает, что в месте въезда есть полоса разгона, а по {p:10.8} водитель должен двигаться именно по ней (путь Б) и вливаться в поток, уступая дорогу транспортным средствам, движущимся по дороге."},"ref":["10.8"],"pic":["img/hsc/10-16-1.jpg"]},{"id":"h10-17","t":"h10","num":"10.17","q":{"uk":"Чи дозволено виконати розворот у технологічному розриві цьому транспортному засобу?","ru":"Разрешено ли этому транспортному средству выполнить разворот в технологическом разрыве?"},"a":[{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"Технологічний розрив не є ні перехрестям, ні місцем для розвороту ({s:5.29}, {s:5.30}), тож на автомагістралі розвертатися в ньому не можна {p:10.7}.","ru":"Технологический разрыв не является ни перекрёстком, ни местом для разворота ({s:5.29}, {s:5.30}), поэтому на автомагистрали разворачиваться в нём нельзя {p:10.7}."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":1,"e":{"uk":"Знак {s:5.1} позначає автомагістраль, де розворот заборонено, крім перехресть і місць, позначених знаками {s:5.29} та {s:5.30} {p:10.7}; технологічний розрив розділювальної смуги таким місцем не є.","ru":"Знак {s:5.1} обозначает автомагистраль, где разворот запрещён, кроме перекрёстков и мест, обозначенных знаками {s:5.29} и {s:5.30} {p:10.7}; технологический разрыв разделительной полосы таким местом не является."},"ref":["10.7"],"pic":["img/hsc/10-17-1.jpg"]},{"id":"h10-18","t":"h10","num":"10.18","q":{"uk":"Хто з водіїв порушив Правила дорожнього руху, виконавши розворот?","ru":"Кто из водителей нарушил Правила дорожного движения, выполнив разворот?"},"a":[{"uk":"Водій синього автомобіля.","ru":"Водитель синего автомобиля."},{"uk":"Водій зеленого автомобіля.","ru":"Водитель зелёного автомобиля.","w":{"uk":"Зелений автомобіль розвертається до шляхопроводу, а не під ним, де діє заборона {p:10.7}.","ru":"Зелёный автомобиль разворачивается до путепровода, а не под ним, где действует запрет {p:10.7}."}},{"uk":"Обидва водії.","ru":"Оба водителя.","w":{"uk":"Порушив лише водій синього автомобіля: зелений розвернувся не під шляхопроводом, а перед ним.","ru":"Нарушил только водитель синего автомобиля: зелёный развернулся не под путепроводом, а перед ним."}}],"c":0,"e":{"uk":"Синій автомобіль розвертається на шляхопроводі, а там розворот заборонено {p:10.7}. Зелений розвертається перед шляхопроводом, а не під ним, тож Правил не порушує.","ru":"Синий автомобиль разворачивается на путепроводе, а там разворот запрещён {p:10.7}. Зелёный разворачивается перед путепроводом, а не под ним, поэтому Правил не нарушает."},"ref":["10.7"],"pic":["img/hsc/10-18-1.jpg"]},{"id":"h10-19","t":"h10","num":"10.19","q":{"uk":"Чи дозволено буде водієві білого автомобіля виконати поворот праворуч?","ru":"Будет ли разрешено водителю белого автомобиля выполнить поворот направо?"},"a":[{"uk":"Заборонено.","ru":"Запрещено.","w":{"uk":"Займати крайнє праве положення тут не потрібно: з обох смуг рух можливий лише праворуч ({s:4.2}), а це прямий виняток із {p:10.4}.","ru":"Занимать крайнее правое положение здесь не нужно: из обеих полос движение возможно только направо ({s:4.2}), а это прямое исключение из {p:10.4}."}},{"uk":"Дозволено.","ru":"Разрешено."}],"c":1,"e":{"uk":"Знаки {s:4.2} над обома смугами дозволяють рух лише праворуч ({s:5.6} — кінець дороги з одностороннім рухом). Коли рух можливий лише в одному напрямку, встановленому знаками, повертати можна не тільки з крайнього правого положення {p:10.4}, тож білий повертає праворуч зі своєї смуги.","ru":"Знаки {s:4.2} над обеими полосами разрешают движение только направо ({s:5.6} — конец дороги с односторонним движением). Когда движение возможно только в одном направлении, установленном знаками, поворачивать можно не только из крайнего правого положения {p:10.4}, поэтому белый поворачивает направо из своей полосы."},"ref":["10.4"],"pic":["img/hsc/10-19-1.jpg"]},{"id":"h10-20","t":"h10","num":"10.20","q":{"uk":"Чи дозволено водієві виконати розворот у даному місці?","ru":"Разрешено ли водителю выполнить разворот в данном месте?"},"a":[{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"Водій не бачить транспорту, що виїжджає з-за повороту: видимість менше 100 м, а за неї розворот заборонено {p:10.7}.","ru":"Водитель не видит транспорт, выезжающий из-за поворота: видимость менее 100 м, а при ней разворот запрещён {p:10.7}."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":1,"e":{"uk":"На небезпечному повороті ({s:1.1}) закруглення й дерева закривають огляд, тож видимість дороги менше 100 м, а за такої видимості хоча б в одному напрямку розворот заборонено {p:10.7}.","ru":"На опасном повороте ({s:1.1}) закругление и деревья закрывают обзор, поэтому видимость дороги менее 100 м, а при такой видимости хотя бы в одном направлении разворот запрещён {p:10.7}."},"ref":["10.7"],"pic":["img/hsc/10-20-1.jpg"]},{"id":"h10-21","t":"h10","num":"10.21","q":{"uk":"Чи правильно водій, який знаходиться ліворуч, виконує поворот праворуч?","ru":"Правильно ли водитель, находящийся слева, выполняет поворот направо?"},"a":[{"uk":"Правильно.","ru":"Правильно."},{"uk":"Неправильно.","ru":"Неправильно.","w":{"uk":"Вимога повертати з крайнього правого положення тут не діє, бо обидві смуги ведуть лише праворуч ({s:4.2}) — виняток із {p:10.4}.","ru":"Требование поворачивать из крайнего правого положения здесь не действует, так как обе полосы ведут только направо ({s:4.2}) — исключение из {p:10.4}."}}],"c":0,"e":{"uk":"Знаки {s:4.2} дозволяють рух з обох смуг лише праворуч, а коли рух можливий лише в одному напрямку, встановленому знаками, повертати можна не тільки з крайнього правого положення {p:10.4}. Лівий автомобіль повертає паралельно з правим, не заважаючи йому.","ru":"Знаки {s:4.2} разрешают движение из обеих полос только направо, а когда движение возможно только в одном направлении, установленном знаками, поворачивать можно не только из крайнего правого положения {p:10.4}. Левый автомобиль поворачивает параллельно с правым, не мешая ему."},"ref":["10.4"],"pic":["img/hsc/10-21-1.jpg"]},{"id":"h10-22","t":"h10","num":"10.22","q":{"uk":"Чи правильно водій білого автомобіля виконав з'їзд із перехрестя з круговим рухом одночасно з водієм синього автомобіля?","ru":"Правильно ли водитель белого автомобиля выполнил съезд с перекрёстка с круговым движением одновременно с водителем синего автомобиля?"},"a":[{"uk":"Правильно.","ru":"Правильно."},{"uk":"Неправильно.","ru":"Неправильно.","w":{"uk":"Виїзд не з крайньої правої смуги дозволений {p:10.5}, а синьому автомобілю, що рухається праворуч, білий не заважає.","ru":"Выезд не из крайней правой полосы разрешён {p:10.5}, а синему автомобилю, движущемуся справа, белый не мешает."}}],"c":0,"e":{"uk":"Виїзд з перехрестя з круговим рухом ({s:4.10}) можна здійснювати з будь-якої смуги, якщо напрямок не визначено знаками чи розміткою і це не створює перешкод попутним транспортним засобам праворуч {p:10.5}. Білий автомобіль виїжджає паралельно із синім у свою смугу, не перетинаючи його траєкторії.","ru":"Выезд с перекрёстка с круговым движением ({s:4.10}) можно осуществлять с любой полосы, если направление не определено знаками или разметкой и это не создаёт помех попутным транспортным средствам справа {p:10.5}. Белый автомобиль выезжает параллельно с синим в свою полосу, не пересекая его траекторию."},"ref":["10.5"],"pic":["img/hsc/10-22-1.jpg"]},{"id":"h10-23","t":"h10","num":"10.23","q":{"uk":"Хто з водіїв правильно зайняв смугу для повороту у разі в’їзду на перехрестя, де організовано круговий рух?","ru":"Кто из водителей правильно занял полосу для поворота при въезде на перекрёсток, где организовано круговое движение?"},"a":[{"uk":"Водій червоного автомобіля.","ru":"Водитель красного автомобиля.","w":{"uk":"Неповна відповідь: білий автомобіль у лівій смузі теж має право в'їжджати на перехрестя з круговим рухом {p:10.4}.","ru":"Неполный ответ: белый автомобиль в левой полосе тоже имеет право въезжать на перекрёсток с круговым движением {p:10.4}."}},{"uk":"Водій білого автомобіля.","ru":"Водитель белого автомобиля.","w":{"uk":"Неповна відповідь: червоний автомобіль у правій смузі теж розташований правильно.","ru":"Неполный ответ: красный автомобиль в правой полосе тоже расположен правильно."}},{"uk":"Водії обох автомобілів.","ru":"Водители обоих автомобилей."}],"c":2,"e":{"uk":"Під час в'їзду на перехрестя з круговим рухом ({s:4.10}) не обов'язково займати крайнє праве положення — це прямий виняток із {p:10.4}, тож правильно розташовані обидва автомобілі.","ru":"При въезде на перекрёсток с круговым движением ({s:4.10}) не обязательно занимать крайнее правое положение — это прямое исключение из {p:10.4}, поэтому правильно расположены оба автомобиля."},"ref":["10.4"],"pic":["img/hsc/10-23-1.jpg"]},{"id":"h10-24","t":"h10","num":"10.24","q":{"uk":"Чи правильно автомобіль, що знаходиться ліворуч, виконує поворот праворуч у другу смугу для руху?","ru":"Правильно ли автомобиль, находящийся слева, выполняет поворот направо во вторую полосу для движения?"},"a":[{"uk":"Неправильно: у разі повороту праворуч слід рухатися ближче до правого краю проїзної частини.","ru":"Неправильно: при повороте направо следует двигаться ближе к правому краю проезжей части.","w":{"uk":"Вимога триматися ближче до правого краю стосується звичайного повороту; тут знак {s:5.16} дозволяє поворот із двох смуг, і кожен автомобіль повертає у «свою» смугу.","ru":"Требование держаться ближе к правому краю относится к обычному повороту; здесь знак {s:5.16} разрешает поворот из двух полос, и каждый автомобиль поворачивает в «свою» полосу."}},{"uk":"Правильно.","ru":"Правильно."}],"c":1,"e":{"uk":"Знак {s:5.16} дозволяє поворот праворуч не лише з правої, а й із середньої смуги, а коли напрямок руху визначено знаками, повертати можна не тільки з крайнього положення {p:10.4}. Тому автомобіль із середньої смуги повертає у другу смугу, паралельно із сусідом праворуч.","ru":"Знак {s:5.16} разрешает поворот направо не только из правой, но и из средней полосы, а когда направление движения определено знаками, поворачивать можно не только из крайнего положения {p:10.4}. Поэтому автомобиль из средней полосы поворачивает во вторую полосу, параллельно с соседом справа."},"ref":["10.4","10.5"],"pic":["img/hsc/10-24-1.jpg"]},{"id":"h10-25","t":"h10","num":"10.25","q":{"uk":"Чи дозволено водієві виконати розворот на перехресті так, як показано на малюнку?","ru":"Разрешено ли водителю выполнить разворот на перекрёстке так, как показано на рисунке?"},"a":[{"uk":"Заборонено, тому що відстань до пішохідного переходу менш ніж 10 м.","ru":"Запрещено, так как расстояние до пешеходного перехода менее 10 м.","w":{"uk":"Обмеження «ближче 10 м від переходу» має прямий виняток — дозволений розворот на перехресті {p:10.7}.","ru":"Ограничение «ближе 10 м от перехода» имеет прямое исключение — разрешённый разворот на перекрёстке {p:10.7}."}},{"uk":"Дозволено.","ru":"Разрешено."}],"c":1,"e":{"uk":"Заборона розвороту ближче 10 м від пішохідного переходу не поширюється на дозволений розворот на перехресті {p:10.7}, а на малюнку розворот виконується саме в межах перехрестя.","ru":"Запрет разворота ближе 10 м от пешеходного перехода не распространяется на разрешённый разворот на перекрёстке {p:10.7}, а на рисунке разворот выполняется именно в пределах перекрёстка."},"ref":["10.7"],"pic":["img/hsc/10-25-1.jpg"]},{"id":"h10-26","t":"h10","num":"10.26","q":{"uk":"У якому місці водій правильно виконав розворот?","ru":"В каком месте водитель правильно выполнил разворот?"},"a":[{"uk":"У місці А.","ru":"В месте А."},{"uk":"У місцях А, Б і В.","ru":"В местах А, Б и В.","w":{"uk":"Розвороти Б (на переході) і В (ближче 10 м за ним) заборонені {p:10.7}.","ru":"Развороты Б (на переходе) и В (ближе 10 м за ним) запрещены {p:10.7}."}},{"uk":"У місцях А і В.","ru":"В местах А и В.","w":{"uk":"Розворот В виконано ближче 10 м від пішохідного переходу, а це заборонено {p:10.7}.","ru":"Разворот В выполнен ближе 10 м от пешеходного перехода, а это запрещено {p:10.7}."}},{"uk":"У місці В.","ru":"В месте В.","w":{"uk":"Місце В — у межах 10 м від пішохідного переходу, де розворот заборонено {p:10.7}.","ru":"Место В — в пределах 10 м от пешеходного перехода, где разворот запрещён {p:10.7}."}}],"c":0,"e":{"uk":"Розворот заборонено на пішохідному переході та ближче 10 м від нього з обох боків {p:10.7}. Місце Б — на самому переході, В — у межах 10 м за ним, і лише А розташоване далі ніж 10 м від переходу.","ru":"Разворот запрещён на пешеходном переходе и ближе 10 м от него с обеих сторон {p:10.7}. Место Б — на самом переходе, В — в пределах 10 м за ним, и только А расположено дальше 10 м от перехода."},"ref":["10.7"],"pic":["img/hsc/10-26-1.jpg"]},{"id":"h10-27","t":"h10","num":"10.27","q":{"uk":"Ви керуєте автомобілем і під час руху вирішили перестроїтись ліворуч. Виконуючи такий маневр Ви повинні:","ru":"Вы управляете автомобилем и во время движения решили перестроиться налево. Выполняя такой манёвр, вы должны:"},"a":[{"uk":"Ввімкнути лівий покажчик повороту.","ru":"Включить левый указатель поворота.","w":{"uk":"Неповна відповідь: крім сигналу, треба переконатися в безпечності маневру і дати дорогу транспорту на сусідній смузі.","ru":"Неполный ответ: кроме сигнала, нужно убедиться в безопасности манёвра и уступить дорогу транспорту на соседней полосе."}},{"uk":"Подивитися в ліве дзеркало заднього виду і переконатися, що це буде безпечно і не створить перешкод або небезпеки іншим учасникам руху, контролюючи «сліпу зону» автомобіля.","ru":"Посмотреть в левое зеркало заднего вида и убедиться, что это будет безопасно и не создаст помех или опасности другим участникам движения, контролируя «слепую зону» автомобиля.","w":{"uk":"Неповна відповідь: треба ще ввімкнути покажчик повороту {p:9.2} і дати дорогу транспорту на сусідній смузі {p:10.3}.","ru":"Неполный ответ: нужно ещё включить указатель поворота {p:9.2} и уступить дорогу транспорту на соседней полосе {p:10.3}."}},{"uk":"Дати дорогу транспортним засобам, що рухаються в попутному напрямку по тій смузі, на яку Ви маєте намір перестроїтися.","ru":"Уступить дорогу транспортным средствам, движущимся в попутном направлении по той полосе, на которую вы намерены перестроиться.","w":{"uk":"Неповна відповідь: перед маневром треба ще подати сигнал {p:9.2} і переконатися в його безпечності {p:10.1}.","ru":"Неполный ответ: перед манёвром нужно ещё подать сигнал {p:9.2} и убедиться в его безопасности {p:10.1}."}},{"uk":"Виконати усі дії зазначені у відповідях 1, 2 і 3.","ru":"Выполнить все действия, указанные в ответах 1, 2 и 3."},{"uk":"Виконати тільки дії зазначені у відповідях 1 і 3.","ru":"Выполнить только действия, указанные в ответах 1 и 3.","w":{"uk":"Пропущено обов'язкову перевірку безпечності маневру — дзеркало і «сліпу зону» {p:10.1}.","ru":"Пропущена обязательная проверка безопасности манёвра — зеркало и «слепая зона» {p:10.1}."}}],"c":3,"e":{"uk":"Перед перестроюванням треба подати сигнал покажчиком повороту {p:9.2}, переконатися, що маневр безпечний {p:10.1} (дзеркало і «сліпа зона»), і дати дорогу тим, хто рухається смугою, на яку Ви перестроюєтеся {p:10.3}. Обов'язкові всі три дії.","ru":"Перед перестроением нужно подать сигнал указателем поворота {p:9.2}, убедиться, что манёвр безопасен {p:10.1} (зеркало и «слепая зона»), и уступить дорогу тем, кто движется по полосе, на которую вы перестраиваетесь {p:10.3}. Обязательны все три действия."},"ref":["9.2","10.1","10.3"]},{"id":"h10-28","t":"h10","num":"10.28","q":{"uk":"Ви керуєте автомобілем і під час руху вирішили перестроїтись ліворуч. Виконуючи такий маневр Ви повинні дати дорогу:","ru":"Вы управляете автомобилем и во время движения решили перестроиться налево. Выполняя такой манёвр, вы должны уступить дорогу:"},"a":[{"uk":"Тільки механічним транспортним засобам, що рухаються в попутному напрямку по тій смузі, на яку Ви маєте намір перестроїтися.","ru":"Только механическим транспортным средствам, движущимся в попутном направлении по той полосе, на которую вы намерены перестроиться.","w":{"uk":"Велосипед — теж транспортний засіб {p:1.10}, хоч і не механічний, тож велосипедиста на сусідній смузі теж треба пропустити.","ru":"Велосипед — тоже транспортное средство {p:1.10}, хотя и не механическое, поэтому велосипедиста на соседней полосе тоже нужно пропустить."}},{"uk":"Тільки автомобілям, автобусам і велосипедистам, що рухаються в попутному напрямку по тій смузі, на яку Ви маєте намір перестроїтися.","ru":"Только автомобилям, автобусам и велосипедистам, движущимся в попутном направлении по той полосе, на которую вы намерены перестроиться.","w":{"uk":"Перелік неповний: дорогу треба дати будь-якому транспортному засобу на цій смузі, зокрема мотоциклу чи мопеду {p:10.3}.","ru":"Перечень неполный: дорогу нужно уступить любому транспортному средству на этой полосе, в том числе мотоциклу или мопеду {p:10.3}."}},{"uk":"Транспортним засобам, що рухаються в попутному напрямку по тій смузі, на яку Ви маєте намір перестроїтися.","ru":"Транспортным средствам, движущимся в попутном направлении по той полосе, на которую вы намерены перестроиться."}],"c":2,"e":{"uk":"{p:10.3} вимагає дати дорогу **всім** транспортним засобам, що рухаються в попутному напрямку смугою, на яку Ви перестроюєтеся, а не лише окремим їх видам.","ru":"{p:10.3} требует уступить дорогу **всем** транспортным средствам, движущимся в попутном направлении по полосе, на которую вы перестраиваетесь, а не только отдельным их видам."},"ref":["10.3","1.10"]},{"id":"h10-29","t":"h10","num":"10.29","q":{"uk":"Як повинен вчинити водій, що повертає ліворуч на перехресті, якщо автомобіль, який рухається попереду нього, почав виконувати розворот?","ru":"Как должен поступить водитель, поворачивающий налево на перекрёстке, если автомобиль, движущийся впереди него, начал выполнять разворот?"},"a":[{"uk":"Подати звуковий сигнал для запобігання дорожньо-транспортній пригоді.","ru":"Подать звуковой сигнал для предотвращения дорожно-транспортного происшествия.","w":{"uk":"Звуковий сигнал не дає переваги {p:9.4}; Правила прямо зобов'язують того, хто повертає ліворуч, пропустити попутний автомобіль, що розвертається {p:10.4}.","ru":"Звуковой сигнал не даёт преимущества {p:9.4}; Правила прямо обязывают поворачивающего налево пропустить попутный автомобиль, выполняющий разворот {p:10.4}."}},{"uk":"Дати йому дорогу.","ru":"Уступить ему дорогу."}],"c":1,"e":{"uk":"За {p:10.4} водій, що повертає ліворуч, повинен дати дорогу попутним транспортним засобам, які рухаються попереду нього і виконують розворот.","ru":"По {p:10.4} водитель, поворачивающий налево, должен уступить дорогу попутным транспортным средствам, которые движутся впереди него и выполняют разворот."},"ref":["10.4"]},{"id":"h10-30","t":"h10","num":"10.30","q":{"uk":"Ви керуєте автомобілем і під час руху вирішили перестроїтись праворуч. Виконуючи такий маневр Ви повинні:","ru":"Вы управляете автомобилем и во время движения решили перестроиться направо. Выполняя такой манёвр, вы должны:"},"a":[{"uk":"Ввімкнути правий покажчик повороту.","ru":"Включить правый указатель поворота.","w":{"uk":"Неповна відповідь: крім сигналу, треба переконатися в безпечності маневру і дати дорогу транспорту на сусідній смузі.","ru":"Неполный ответ: кроме сигнала, нужно убедиться в безопасности манёвра и уступить дорогу транспорту на соседней полосе."}},{"uk":"Подивитися в праве дзеркало заднього виду і переконатися, що це буде безпечно і не створить перешкод або небезпеки іншим учасникам руху, контролюючи «сліпу зону» автомобіля.","ru":"Посмотреть в правое зеркало заднего вида и убедиться, что это будет безопасно и не создаст помех или опасности другим участникам движения, контролируя «слепую зону» автомобиля.","w":{"uk":"Неповна відповідь: треба ще ввімкнути покажчик повороту {p:9.2} і дати дорогу транспорту на сусідній смузі {p:10.3}.","ru":"Неполный ответ: нужно ещё включить указатель поворота {p:9.2} и уступить дорогу транспорту на соседней полосе {p:10.3}."}},{"uk":"Дати дорогу транспортним засобам, що рухаються в попутному напрямку по тій смузі, на яку Ви маєте намір перестроїтися.","ru":"Уступить дорогу транспортным средствам, движущимся в попутном направлении по той полосе, на которую вы намерены перестроиться.","w":{"uk":"Неповна відповідь: перед маневром треба ще подати сигнал {p:9.2} і переконатися в його безпечності {p:10.1}.","ru":"Неполный ответ: перед манёвром нужно ещё подать сигнал {p:9.2} и убедиться в его безопасности {p:10.1}."}},{"uk":"Виконати усі дії зазначені у відповідях 1, 2 і 3.","ru":"Выполнить все действия, указанные в ответах 1, 2 и 3."},{"uk":"Виконати тільки дії зазначені у відповідях 1 і 3.","ru":"Выполнить только действия, указанные в ответах 1 и 3.","w":{"uk":"Пропущено обов'язкову перевірку безпечності маневру — дзеркало і «сліпу зону» {p:10.1}.","ru":"Пропущена обязательная проверка безопасности манёвра — зеркало и «слепая зона» {p:10.1}."}}],"c":3,"e":{"uk":"Перед перестроюванням треба подати сигнал правим покажчиком повороту {p:9.2}, переконатися, що маневр безпечний {p:10.1} (дзеркало і «сліпа зона»), і дати дорогу тим, хто рухається смугою, на яку Ви перестроюєтеся {p:10.3}. Обов'язкові всі три дії.","ru":"Перед перестроением нужно подать сигнал правым указателем поворота {p:9.2}, убедиться, что манёвр безопасен {p:10.1} (зеркало и «слепая зона»), и уступить дорогу тем, кто движется по полосе, на которую вы перестраиваетесь {p:10.3}. Обязательны все три действия."},"ref":["9.2","10.1","10.3"]},{"id":"h10-31","t":"h10","num":"10.31","q":{"uk":"Ви, як водій, повертаючи праворуч повинні:","ru":"Вы как водитель, поворачивая направо, должны:"},"a":[{"uk":"Рухатися ближче до правого краю проїзної частини.","ru":"Двигаться ближе к правому краю проезжей части."},{"uk":"Триматися середини смуги.","ru":"Держаться середины полосы.","w":{"uk":"Середина смуги — не крайнє праве положення; Правила вимагають триматися ближче до правого краю {p:10.5}.","ru":"Середина полосы — не крайнее правое положение; Правила требуют держаться ближе к правому краю {p:10.5}."}},{"uk":"Рухатися так, щоб між Вами і бордюром помістився велосипед.","ru":"Двигаться так, чтобы между вами и бордюром поместился велосипед.","w":{"uk":"Залишений праворуч проміжок суперечить {p:10.5} і провокує велосипедиста проїхати справа, під траєкторію повороту.","ru":"Оставленный справа промежуток противоречит {p:10.5} и провоцирует велосипедиста проехать справа, под траекторию поворота."}}],"c":0,"e":{"uk":"За {p:10.5} у разі повороту праворуч слід рухатися **ближче до правого краю** проїзної частини — так поворот виконується з крайнього правого положення і не залишає справа місця для інших.","ru":"По {p:10.5} при повороте направо следует двигаться **ближе к правому краю** проезжей части — так поворот выполняется из крайнего правого положения и не оставляет справа места для других."},"ref":["10.5","10.4"]},{"id":"h10-32","t":"h10","num":"10.32","q":{"uk":"Ви, як водій, повертаючи ліворуч поза перехрестям повинні:","ru":"Вы как водитель, поворачивая налево вне перекрёстка, должны:"},"a":[{"uk":"Включити покажчик лівого повороту.","ru":"Включить указатель левого поворота.","w":{"uk":"Неповна відповідь: треба ще зайняти крайнє положення і пропустити зустрічний транспорт {p:10.4}.","ru":"Неполный ответ: нужно ещё занять крайнее положение и пропустить встречный транспорт {p:10.4}."}},{"uk":"Зайняти відповідне крайнє положення на проїзній частині.","ru":"Занять соответствующее крайнее положение на проезжей части.","w":{"uk":"Неповна відповідь: треба ще подати сигнал {p:9.2} і пропустити зустрічний транспорт {p:10.4}.","ru":"Неполный ответ: нужно ещё подать сигнал {p:9.2} и пропустить встречный транспорт {p:10.4}."}},{"uk":"Дати дорогу зустрічним транспортним засобам.","ru":"Уступить дорогу встречным транспортным средствам.","w":{"uk":"Неповна відповідь: треба ще подати сигнал {p:9.2} і заздалегідь зайняти крайнє ліве положення {p:10.4}.","ru":"Неполный ответ: нужно ещё подать сигнал {p:9.2} и заранее занять крайнее левое положение {p:10.4}."}},{"uk":"Виконати дії зазначені у відповідях 1,2,3.","ru":"Выполнить действия, указанные в ответах 1, 2, 3."}],"c":3,"e":{"uk":"Перед поворотом треба подати сигнал лівим покажчиком {p:9.2}, завчасно зайняти крайнє ліве положення і, повертаючи поза перехрестям, дати дорогу зустрічним транспортним засобам {p:10.4}. Обов'язкові всі три дії.","ru":"Перед поворотом нужно подать сигнал левым указателем {p:9.2}, заблаговременно занять крайнее левое положение и, поворачивая вне перекрёстка, уступить дорогу встречным транспортным средствам {p:10.4}. Обязательны все три действия."},"ref":["9.2","10.4"]},{"id":"h10-33","t":"h10","num":"10.33","q":{"uk":"Ви, як водій автомобіля, маєте право розвернутися:","ru":"Вы как водитель автомобиля имеете право развернуться:"},"a":[{"uk":"У тунелях.","ru":"В тоннелях.","w":{"uk":"Розворот у тунелях заборонено {p:10.7}.","ru":"Разворот в тоннелях запрещён {p:10.7}."}},{"uk":"На мостах, шляхопроводах, естакадах.","ru":"На мостах, путепроводах, эстакадах.","w":{"uk":"Розворот на мостах, шляхопроводах і естакадах заборонено {p:10.7}.","ru":"Разворот на мостах, путепроводах и эстакадах запрещён {p:10.7}."}},{"uk":"Під мостами, шляхопроводами та естакадами.","ru":"Под мостами, путепроводами и эстакадами.","w":{"uk":"Розворот під мостами, шляхопроводами й естакадами теж заборонено {p:10.7}.","ru":"Разворот под мостами, путепроводами и эстакадами тоже запрещён {p:10.7}."}},{"uk":"На дорозі по одній смузі в кожному напрямку і при відсутності заборонних знаків та суцільної лінії розмітки.","ru":"На дороге с одной полосой в каждом направлении и при отсутствии запрещающих знаков и сплошной линии разметки."},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3.","w":{"uk":"Усі три перелічені місця — тунелі, мости та простір під ними — є місцями, де розворот заборонено {p:10.7}.","ru":"Все три перечисленных места — тоннели, мосты и пространство под ними — являются местами, где разворот запрещён {p:10.7}."}}],"c":3,"e":{"uk":"Тунелі, мости, шляхопроводи, естакади й місця під ними входять до переліку, де розворот заборонено {p:10.7}. На звичайній дорозі з однією смугою в кожному напрямку розворот дозволений, якщо його не забороняє знак {s:3.24} і не треба перетинати суцільну лінію {m:1.1} {p:34.1}.","ru":"Тоннели, мосты, путепроводы, эстакады и места под ними входят в перечень, где разворот запрещён {p:10.7}. На обычной дороге с одной полосой в каждом направлении разворот разрешён, если его не запрещает знак {s:3.24} и не нужно пересекать сплошную линию {m:1.1} {p:34.1}."},"ref":["10.7","34.1"]},{"id":"h10-34","t":"h10","num":"10.34","q":{"uk":"З якої смуги дозволено виконати поворот при в'їзді на перехрестя, де організовано круговий рух?","ru":"С какой полосы разрешено выполнять поворот при въезде на перекрёсток, где организовано круговое движение?"},"a":[{"uk":"З крайньої правої.","ru":"С крайней правой.","w":{"uk":"Займати крайню праву смугу тут не обов'язково — це прямий виняток із {p:10.4}.","ru":"Занимать крайнюю правую полосу здесь не обязательно — это прямое исключение из {p:10.4}."}},{"uk":"Тільки з крайньої правої і з сусідньої смуги.","ru":"Только с крайней правой и с соседней полосы.","w":{"uk":"Правила не обмежують в'їзд двома смугами: дозволено з будь-якої смуги цього напрямку {p:10.4}.","ru":"Правила не ограничивают въезд двумя полосами: разрешено с любой полосы этого направления {p:10.4}."}},{"uk":"З будь-якої смуги для руху в цьому ж напрямку.","ru":"С любой полосы для движения в этом же направлении."}],"c":2,"e":{"uk":"Вимога завчасно займати крайнє положення не діє в разі повороту під час в'їзду на перехрестя з круговим рухом {p:10.4}, тож в'їжджати на коло можна з будь-якої смуги цього напрямку.","ru":"Требование заблаговременно занимать крайнее положение не действует при повороте во время въезда на перекрёсток с круговым движением {p:10.4}, поэтому въезжать на круг можно с любой полосы этого направления."},"ref":["10.4"]},{"id":"h10-35","t":"h10","num":"10.35","q":{"uk":"Ви водій автомобіля, рухаючись по мосту, зрозуміли, що обрали не вірний напрямок. Ваші дії:","ru":"Вы водитель автомобиля и, двигаясь по мосту, поняли, что выбрали неверное направление. Ваши действия:"},"a":[{"uk":"Виконаєте розворот в зворотному напрямку.","ru":"Выполните разворот в обратном направлении.","w":{"uk":"Розворот на мосту заборонено {p:10.7}, незалежно від того, чи вдасться його виконати.","ru":"Разворот на мосту запрещён {p:10.7}, независимо от того, удастся ли его выполнить."}},{"uk":"Включити лівий покажчик повороту, пропустите зустрічні транспортні засоби і після цього виконаєте розворот.","ru":"Включите левый указатель поворота, пропустите встречные транспортные средства и после этого выполните разворот.","w":{"uk":"Сигнал і пропуск зустрічних не роблять розворот на мосту дозволеним — заборона безумовна {p:10.7}.","ru":"Сигнал и пропуск встречных не делают разворот на мосту разрешённым — запрет безусловный {p:10.7}."}},{"uk":"Проїдете міст і після цього виконаєте розворот в дозволеному місці.","ru":"Проедете мост и после этого выполните разворот в разрешённом месте."}],"c":2,"e":{"uk":"Розворот на мостах заборонено {p:10.7}, тож треба проїхати міст і розвернутися там, де це дозволено.","ru":"Разворот на мостах запрещён {p:10.7}, поэтому нужно проехать мост и развернуться там, где это разрешено."},"ref":["10.7"]},{"id":"h10-36","t":"h10","num":"10.36","q":{"uk":"Ви, як водій, вирішили повернути праворуч на перехресті. Ви зобов’язані:","ru":"Вы как водитель решили повернуть направо на перекрёстке. Вы обязаны:"},"a":[{"uk":"Виконуючи поворот праворуч рухатися ближче до правого краю проїзної частини.","ru":"Выполняя поворот направо, двигаться ближе к правому краю проезжей части."},{"uk":"Зайняти середину смуги під час повороту праворуч.","ru":"Занять середину полосы во время поворота направо.","w":{"uk":"Середина смуги — не крайнє праве положення, а Правила вимагають триматися ближче до правого краю {p:10.5}.","ru":"Середина полосы — не крайнее правое положение, а Правила требуют держаться ближе к правому краю {p:10.5}."}},{"uk":"Залежно від швидкості руху, або 1, або 2 варіант.","ru":"В зависимости от скорости движения либо вариант 1, либо вариант 2.","w":{"uk":"Вимога {p:10.5} не залежить від швидкості: поворот праворуч завжди виконують ближче до правого краю.","ru":"Требование {p:10.5} не зависит от скорости: поворот направо всегда выполняют ближе к правому краю."}}],"c":0,"e":{"uk":"За {p:10.5} у разі повороту праворуч слід рухатися ближче до правого краю проїзної частини — незалежно від швидкості.","ru":"По {p:10.5} при повороте направо следует двигаться ближе к правому краю проезжей части — независимо от скорости."},"ref":["10.5"]},{"id":"h10-37","t":"h10","num":"10.37","q":{"uk":"Ви, як водій, вирішили повернути ліворуч на перехресті. Вам необхідно:","ru":"Вы как водитель решили повернуть налево на перекрёстке. Вам необходимо:"},"a":[{"uk":"Включити лівий покажчик повороту і виконати поворот.","ru":"Включить левый указатель поворота и выполнить поворот.","w":{"uk":"Самого сигналу замало: треба ще завчасно зайняти крайнє ліве положення {p:10.4} і не виїхати на зустрічну смугу {p:10.5}.","ru":"Одного сигнала мало: нужно ещё заблаговременно занять крайнее левое положение {p:10.4} и не выехать на встречную полосу {p:10.5}."}},{"uk":"Завчасно включити покажчик повороту і зайняти крайнє ліве положення.","ru":"Заблаговременно включить указатель поворота и занять крайнее левое положение.","w":{"uk":"Неповна відповідь: треба ще виконати поворот так, щоб не опинитися на смузі зустрічного руху {p:10.5}.","ru":"Неполный ответ: нужно ещё выполнить поворот так, чтобы не оказаться на полосе встречного движения {p:10.5}."}},{"uk":"Виконати поворот так, щоб при виїзді з перехрещення проїзних частин транспортний засіб не опинився на смузі зустрічного руху.","ru":"Выполнить поворот так, чтобы при выезде с пересечения проезжих частей транспортное средство не оказалось на полосе встречного движения.","w":{"uk":"Неповна відповідь: до повороту треба ще завчасно подати сигнал і зайняти крайнє ліве положення {p:10.4}.","ru":"Неполный ответ: до поворота нужно ещё заблаговременно подать сигнал и занять крайнее левое положение {p:10.4}."}},{"uk":"Виконати обов’язково дії 2 та 3.","ru":"Обязательно выполнить действия 2 и 3."}],"c":3,"e":{"uk":"Перед поворотом ліворуч треба завчасно подати сигнал {p:9.2} і зайняти крайнє ліве положення {p:10.4}, а сам поворот виконати так, щоб після перехрещення не опинитися на зустрічній смузі {p:10.5}. Тож обов'язкові дії 2 і 3.","ru":"Перед поворотом налево нужно заблаговременно подать сигнал {p:9.2} и занять крайнее левое положение {p:10.4}, а сам поворот выполнить так, чтобы после пересечения не оказаться на встречной полосе {p:10.5}. Поэтому обязательны действия 2 и 3."},"ref":["9.2","10.4","10.5"]},{"id":"h10-38","t":"h10","num":"10.38","q":{"uk":"Ви, як водій, повертаючи ліворуч, побачили що автомобіль, який рухається попереду Вас почав виконувати розворот, Ваші дії:","ru":"Вы как водитель, поворачивая налево, увидели, что автомобиль, движущийся впереди вас, начал выполнять разворот. Ваши действия:"},"a":[{"uk":"Повернете ліворуч першим.","ru":"Повернёте налево первым.","w":{"uk":"Перевагу має автомобіль, що розвертається попереду, тож повертати першим не можна {p:10.4}.","ru":"Преимущество имеет автомобиль, разворачивающийся впереди, поэтому поворачивать первым нельзя {p:10.4}."}},{"uk":"Ви зобов’язані дати дорогу автомобілю, який попереду Вас почав виконувати розворот.","ru":"Вы обязаны уступить дорогу автомобилю, который впереди вас начал выполнять разворот."},{"uk":"Виконаєте звуковий сигнал для привертання його уваги і повернете ліворуч першим.","ru":"Подадите звуковой сигнал, чтобы привлечь его внимание, и повернёте налево первым.","w":{"uk":"Звуковий сигнал не дає переваги {p:9.4}, а дорогу автомобілю, що розвертається попереду, треба дати {p:10.4}.","ru":"Звуковой сигнал не даёт преимущества {p:9.4}, а дорогу автомобилю, разворачивающемуся впереди, нужно уступить {p:10.4}."}}],"c":1,"e":{"uk":"За {p:10.4} водій, що повертає ліворуч, повинен дати дорогу попутним транспортним засобам, які рухаються попереду нього і виконують розворот.","ru":"По {p:10.4} водитель, поворачивающий налево, должен уступить дорогу попутным транспортным средствам, которые движутся впереди него и выполняют разворот."},"ref":["10.4"]},{"id":"h10-39","t":"h10","num":"10.39","q":{"uk":"Ви, як водій, вирішили розвернутись на дорозі поза перехрестям. Що Ви обов’язково повинні зробити:","ru":"Вы как водитель решили развернуться на дороге вне перекрёстка. Что вы обязательно должны сделать:"},"a":[{"uk":"Зайняти відповідне крайнє положення на проїзній частині.","ru":"Занять соответствующее крайнее положение на проезжей части.","w":{"uk":"Неповна відповідь: крім крайнього положення, треба пропустити зустрічних, переконатися в безпечності маневру й відсутності заборони.","ru":"Неполный ответ: кроме крайнего положения, нужно пропустить встречных, убедиться в безопасности манёвра и в отсутствии запрета."}},{"uk":"Дати дорогу зустрічним транспортним засобам.","ru":"Уступить дорогу встречным транспортным средствам.","w":{"uk":"Неповна відповідь: треба ще зайняти крайнє положення, переконатися в безпечності й відсутності заборони знаками чи розміткою.","ru":"Неполный ответ: нужно ещё занять крайнее положение, убедиться в безопасности и в отсутствии запрета знаками или разметкой."}},{"uk":"Упевнитись, що це не створить небезпеки чи перешкод іншим учасникам руху.","ru":"Убедиться, что это не создаст опасности или помех другим участникам движения.","w":{"uk":"Неповна відповідь: треба ще зайняти крайнє положення, пропустити зустрічних і перевірити, чи не заборонено розворот.","ru":"Неполный ответ: нужно ещё занять крайнее положение, пропустить встречных и проверить, не запрещён ли разворот."}},{"uk":"Упевнитись, що це не заборонено дорожніми знаками або розміткою.","ru":"Убедиться, что это не запрещено дорожными знаками или разметкой.","w":{"uk":"Неповна відповідь: треба ще зайняти крайнє положення, пропустити зустрічних і переконатися в безпечності маневру.","ru":"Неполный ответ: нужно ещё занять крайнее положение, пропустить встречных и убедиться в безопасности манёвра."}},{"uk":"Виконати дії зазначені у відповідях 1,2,3,4.","ru":"Выполнить действия, указанные в ответах 1, 2, 3, 4."}],"c":4,"e":{"uk":"Розворот поза перехрестям виконують з крайнього лівого положення, даючи дорогу зустрічним {p:10.4}, переконавшись у його безпечності {p:10.1} і в тому, що його не забороняють знак {s:3.24} чи розмітка {m:1.1}. Обов'язкові всі чотири дії.","ru":"Разворот вне перекрёстка выполняют из крайнего левого положения, уступая дорогу встречным {p:10.4}, убедившись в его безопасности {p:10.1} и в том, что его не запрещают знак {s:3.24} или разметка {m:1.1}. Обязательны все четыре действия."},"ref":["10.1","10.4","34.1"]},{"id":"h10-40","t":"h10","num":"10.40","q":{"uk":"Ви, як водій, вирішили розвернутись на дорозі поза перехрестям. Що Ви обов’язково повинні зробити:","ru":"Вы как водитель решили развернуться на дороге вне перекрёстка. Что вы обязательно должны сделать:"},"a":[{"uk":"Включити покажчик лівого повороту.","ru":"Включить указатель левого поворота.","w":{"uk":"Неповна відповідь: треба ще зайняти крайнє ліве положення і пропустити зустрічних {p:10.4}.","ru":"Неполный ответ: нужно ещё занять крайнее левое положение и пропустить встречных {p:10.4}."}},{"uk":"Зайняти відповідне крайнє положення на проїзній частині.","ru":"Занять соответствующее крайнее положение на проезжей части.","w":{"uk":"Неповна відповідь: треба ще подати сигнал {p:9.2} і пропустити зустрічних {p:10.4}.","ru":"Неполный ответ: нужно ещё подать сигнал {p:9.2} и пропустить встречных {p:10.4}."}},{"uk":"Дати дорогу зустрічним транспортним засобам.","ru":"Уступить дорогу встречным транспортным средствам.","w":{"uk":"Неповна відповідь: треба ще подати сигнал {p:9.2} і зайняти крайнє ліве положення {p:10.4}.","ru":"Неполный ответ: нужно ещё подать сигнал {p:9.2} и занять крайнее левое положение {p:10.4}."}},{"uk":"Виконати дії зазначені у відповідях 1,2,3.","ru":"Выполнить действия, указанные в ответах 1, 2, 3."}],"c":3,"e":{"uk":"Перед розворотом треба подати сигнал лівим покажчиком {p:9.2}, зайняти крайнє ліве положення і, розвертаючись поза перехрестям, дати дорогу зустрічним транспортним засобам {p:10.4}. Обов'язкові всі три дії.","ru":"Перед разворотом нужно подать сигнал левым указателем {p:9.2}, занять крайнее левое положение и, разворачиваясь вне перекрёстка, уступить дорогу встречным транспортным средствам {p:10.4}. Обязательны все три действия."},"ref":["9.2","10.4"]},{"id":"h10-41","t":"h10","num":"10.41","q":{"uk":"Ви керуєте автомобілем і під час руху вирішили перестроїтись праворуч. Виконуючи такий маневр Ви повинні дати дорогу:","ru":"Вы управляете автомобилем и во время движения решили перестроиться направо. Выполняя такой манёвр, вы должны уступить дорогу:"},"a":[{"uk":"Тільки механічним транспортним засобам, що рухаються в попутному напрямку по тій смузі, на яку Ви маєте намір перестроїтися.","ru":"Только механическим транспортным средствам, движущимся в попутном направлении по той полосе, на которую вы намерены перестроиться.","w":{"uk":"Велосипед — теж транспортний засіб {p:1.10}, хоч і не механічний, тож велосипедиста на правій смузі теж треба пропустити.","ru":"Велосипед — тоже транспортное средство {p:1.10}, хотя и не механическое, поэтому велосипедиста на правой полосе тоже нужно пропустить."}},{"uk":"Тільки автомобілям, автобусам і велосипедистам, що рухаються в попутному напрямку по тій смузі, на яку Ви маєте намір перестроїтися.","ru":"Только автомобилям, автобусам и велосипедистам, движущимся в попутном направлении по той полосе, на которую вы намерены перестроиться.","w":{"uk":"Перелік неповний: дорогу треба дати будь-якому транспортному засобу на цій смузі, зокрема мотоциклу чи мопеду {p:10.3}.","ru":"Перечень неполный: дорогу нужно уступить любому транспортному средству на этой полосе, в том числе мотоциклу или мопеду {p:10.3}."}},{"uk":"Всім транспортним засобам, що рухаються в попутному напрямку по тій смузі, на яку Ви маєте намір перестроїтися.","ru":"Всем транспортным средствам, движущимся в попутном направлении по той полосе, на которую вы намерены перестроиться."}],"c":2,"e":{"uk":"{p:10.3} вимагає дати дорогу **всім** транспортним засобам, що рухаються в попутному напрямку смугою, на яку Ви перестроюєтеся, а не лише окремим їх видам.","ru":"{p:10.3} требует уступить дорогу **всем** транспортным средствам, движущимся в попутном направлении по полосе, на которую вы перестраиваетесь, а не только отдельным их видам."},"ref":["10.3","1.10"]},{"id":"h10-42","t":"h10","num":"10.42","q":{"uk":"Ви водій, заправили автомобіль паливом і виїжджаючи на дорогу з місця заправки, повинні:","ru":"Вы водитель, заправили автомобиль топливом и, выезжая на дорогу с места заправки, должны:"},"a":[{"uk":"Перед проїзною частиною чи тротуаром дати дорогу тільки автомобілям і велосипедистам.","ru":"Перед проезжей частью или тротуаром уступить дорогу только автомобилям и велосипедистам.","w":{"uk":"Пропущено пішоходів, а також інші транспортні засоби, крім автомобілів і велосипедів, — дорогу треба дати всім {p:10.2}.","ru":"Пропущены пешеходы, а также другие транспортные средства, кроме автомобилей и велосипедов, — дорогу нужно уступить всем {p:10.2}."}},{"uk":"Перед тротуаром дати дорогу пішоходам, що рухаються по ній, а перед проїзною частиною тільки велосипедистам і мотоциклістам.","ru":"Перед тротуаром уступить дорогу пешеходам, движущимся по нему, а перед проезжей частью — только велосипедистам и мотоциклистам.","w":{"uk":"На проїзній частині треба пропустити всі транспортні засоби, а не лише велосипедистів і мотоциклістів {p:10.2}.","ru":"На проезжей части нужно пропустить все транспортные средства, а не только велосипедистов и мотоциклистов {p:10.2}."}},{"uk":"Перед проїзною частиною чи тротуаром дати дорогу пішоходам і транспортним засобам, що рухаються по ній.","ru":"Перед проезжей частью или тротуаром уступить дорогу пешеходам и транспортным средствам, движущимся по ней."}],"c":2,"e":{"uk":"Автозаправна станція — прилегла територія, і за {p:10.2} при виїзді з неї треба перед проїзною частиною чи тротуаром дати дорогу **і пішоходам, і всім транспортним засобам**, що рухаються дорогою.","ru":"Автозаправочная станция — прилегающая территория, и по {p:10.2} при выезде с неё нужно перед проезжей частью или тротуаром уступить дорогу **и пешеходам, и всем транспортным средствам**, движущимся по дороге."},"ref":["10.2"]},{"id":"h10-43","t":"h10","num":"10.43","q":{"uk":"Ви водій, виїжджаючи на дорогу з місця стоянки, повинні:","ru":"Вы водитель и, выезжая на дорогу с места стоянки, должны:"},"a":[{"uk":"Перед проїзною частиною чи тротуаром дати дорогу пішоходам і транспортним засобам, що рухаються по ній.","ru":"Перед проезжей частью или тротуаром уступить дорогу пешеходам и транспортным средствам, движущимся по ней."},{"uk":"Перед проїзною частиною чи тротуаром дати дорогу тільки автомобілям і велосипедистам.","ru":"Перед проезжей частью или тротуаром уступить дорогу только автомобилям и велосипедистам.","w":{"uk":"Пропущено пішоходів, а також інші транспортні засоби, крім автомобілів і велосипедів, — дорогу треба дати всім {p:10.2}.","ru":"Пропущены пешеходы, а также другие транспортные средства, кроме автомобилей и велосипедов, — дорогу нужно уступить всем {p:10.2}."}},{"uk":"Перед тротуаром дати дорогу пішоходам, що рухаються по ній, а перед проїзною частиною тільки велосипедистам і мотоциклістам.","ru":"Перед тротуаром уступить дорогу пешеходам, движущимся по нему, а перед проезжей частью — только велосипедистам и мотоциклистам.","w":{"uk":"На проїзній частині треба пропустити всі транспортні засоби, а не лише велосипедистів і мотоциклістів {p:10.2}.","ru":"На проезжей части нужно пропустить все транспортные средства, а не только велосипедистов и мотоциклистов {p:10.2}."}}],"c":0,"e":{"uk":"Місце стоянки належить до прилеглих територій, і за {p:10.2} при виїзді з нього треба перед проїзною частиною чи тротуаром дати дорогу і пішоходам, і транспортним засобам, що рухаються дорогою.","ru":"Место стоянки относится к прилегающим территориям, и по {p:10.2} при выезде с него нужно перед проезжей частью или тротуаром уступить дорогу и пешеходам, и транспортным средствам, движущимся по дороге."},"ref":["10.2"]},{"id":"h10-44","t":"h10","num":"10.44","q":{"uk":"Яких вимог повинен дотримуватися водій під час руху автомобіля заднім ходом?","ru":"Каких требований должен придерживаться водитель во время движения автомобиля задним ходом?"},"a":[{"uk":"Повинен увімкнути аварійну сигналізацію.","ru":"Должен включить аварийную сигнализацию.","w":{"uk":"Аварійну сигналізацію вмикають у випадках, перелічених у {p:9.9}, а рух заднім ходом серед них не названо.","ru":"Аварийную сигнализацию включают в случаях, перечисленных в {p:9.9}, а движение задним ходом среди них не названо."}},{"uk":"Використовувати звуковий сигнал для привернення уваги.","ru":"Использовать звуковой сигнал для привлечения внимания.","w":{"uk":"Звуковий сигнал не дає переваги і в населених пунктах узагалі заборонений, крім випадків запобігання ДТП {p:9.5}.","ru":"Звуковой сигнал не даёт преимущества и в населённых пунктах вообще запрещён, кроме случаев предотвращения ДТП {p:9.5}."}},{"uk":"Не повинен створювати небезпеки чи перешкод іншим учасникам руху.","ru":"Не должен создавать опасности или помех другим участникам движения."},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3.","w":{"uk":"Варіанти 1 і 2 Правилами не передбачені; обов'язкова лише вимога не створювати небезпеки чи перешкод {p:10.9}.","ru":"Варианты 1 и 2 Правилами не предусмотрены; обязательно лишь требование не создавать опасности или помех {p:10.9}."}}],"c":2,"e":{"uk":"Головна вимога {p:10.9}: під час руху заднім ходом водій не повинен створювати небезпеки чи перешкод іншим учасникам руху. Аварійної сигналізації чи звукового сигналу Правила для цього маневру не вимагають.","ru":"Главное требование {p:10.9}: при движении задним ходом водитель не должен создавать опасности или помех другим участникам движения. Аварийной сигнализации или звукового сигнала Правила для этого манёвра не требуют."},"ref":["10.9"]},{"id":"h10-45","t":"h10","num":"10.45","q":{"uk":"Що в разі потреби повинен зробити водій для забезпечення безпеки дорожнього руху під час руху заднім ходом на транспортному засобі?","ru":"Что в случае необходимости должен сделать водитель для обеспечения безопасности дорожного движения во время движения задним ходом на транспортном средстве?"},"a":[{"uk":"Увімкнути аварійну сигналізацію.","ru":"Включить аварийную сигнализацию.","w":{"uk":"Аварійна сигналізація не передбачена для руху заднім ходом {p:9.9} і не допоможе водієві побачити, що позаду.","ru":"Аварийная сигнализация не предусмотрена для движения задним ходом {p:9.9} и не поможет водителю увидеть, что сзади."}},{"uk":"Звернутися за допомогою до інших осіб.","ru":"Обратиться за помощью к другим лицам."},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2.","w":{"uk":"Варіант 1 Правилами не передбачений, тому поєднання 1 і 2 неправильне.","ru":"Вариант 1 Правилами не предусмотрен, поэтому сочетание 1 и 2 неверно."}}],"c":1,"e":{"uk":"За {p:10.9} для забезпечення безпеки під час руху заднім ходом водій у разі потреби повинен звернутися за допомогою до інших осіб — наприклад, щоб хтось підказував йому ззовні.","ru":"По {p:10.9} для обеспечения безопасности при движении задним ходом водитель при необходимости должен обратиться за помощью к другим лицам — например, чтобы кто-то подсказывал ему снаружи."},"ref":["10.9"]},{"id":"h10-46","t":"h10","num":"10.46","q":{"uk":"У якому випадку дозволено рух заднім ходом на дорогах з одностороннім рухом?","ru":"В каком случае разрешено движение задним ходом на дорогах с односторонним движением?"},"a":[{"uk":"Рух заднім ходом на дорогах з одностороннім рухом заборонено.","ru":"Движение задним ходом на дорогах с односторонним движением запрещено.","w":{"uk":"Повної заборони немає: Правила допускають рух заднім ходом на такій дорозі, якщо інакше під'їхати неможливо і це безпечно {p:10.10}.","ru":"Полного запрета нет: Правила допускают движение задним ходом на такой дороге, если иначе подъехать невозможно и это безопасно {p:10.10}."}},{"uk":"Дозволяється рух заднім ходом на дорогах з одностороннім рухом за умови забезпечення безпеки руху та неможливості під'їхати до об'єкта іншим способом.","ru":"Разрешается движение задним ходом на дорогах с односторонним движением при условии обеспечения безопасности движения и невозможности подъехать к объекту иным способом."}],"c":1,"e":{"uk":"{p:10.10} прямо дозволяє рух заднім ходом на дорогах з одностороннім рухом за двох умов: дотримано вимог безпеки {p:10.9} і до об'єкта неможливо під'їхати іншим чином.","ru":"{p:10.10} прямо разрешает движение задним ходом на дорогах с односторонним движением при двух условиях: соблюдены требования безопасности {p:10.9} и к объекту невозможно подъехать иным способом."},"ref":["10.10","10.9"]},{"id":"h10-47","t":"h10","num":"10.47","q":{"uk":"На якій відстані від пішохідних переходів заборонений розворот?","ru":"На каком расстоянии от пешеходных переходов запрещён разворот?"},"a":[{"uk":"Ближче 10 м перед пішохідними переходами.","ru":"Ближе 10 м перед пешеходными переходами.","w":{"uk":"Неповна відповідь: заборона діє й у межах 10 м за переходом {p:10.7}.","ru":"Неполный ответ: запрет действует и в пределах 10 м за переходом {p:10.7}."}},{"uk":"Ближче 10 м від пішохідного переходу з обох боків.","ru":"Ближе 10 м от пешеходного перехода с обеих сторон."},{"uk":"Ближче 10 м за пішохідними переходами.","ru":"Ближе 10 м за пешеходными переходами.","w":{"uk":"Неповна відповідь: заборона діє й у межах 10 м перед переходом {p:10.7}.","ru":"Неполный ответ: запрет действует и в пределах 10 м перед переходом {p:10.7}."}}],"c":1,"e":{"uk":"За {p:10.7} розворот заборонено на пішохідних переходах і ближче 10 м від них **з обох боків** — і перед переходом, і за ним.","ru":"По {p:10.7} разворот запрещён на пешеходных переходах и ближе 10 м от них **с обеих сторон** — и перед переходом, и за ним."},"ref":["10.7"]},{"id":"h10-48","t":"h10","num":"10.48","q":{"uk":"Де заборонено рух заднім ходом?","ru":"Где запрещено движение задним ходом?"},"a":[{"uk":"На пішохідних переходах.","ru":"На пешеходных переходах.","w":{"uk":"Неповна відповідь: рух заднім ходом заборонено й на залізничних переїздах {p:10.10}.","ru":"Неполный ответ: движение задним ходом запрещено и на железнодорожных переездах {p:10.10}."}},{"uk":"На залізничних переїздах.","ru":"На железнодорожных переездах.","w":{"uk":"Неповна відповідь: рух заднім ходом заборонено й на пішохідних переходах {p:10.10}.","ru":"Неполный ответ: движение задним ходом запрещено и на пешеходных переходах {p:10.10}."}},{"uk":"За 10 м від пішохідного переходу.","ru":"В 10 м от пешеходного перехода.","w":{"uk":"Відстань 10 м від переходу Правила встановлюють для розвороту {p:10.7}, а не для руху заднім ходом.","ru":"Расстояние 10 м от перехода Правила устанавливают для разворота {p:10.7}, а не для движения задним ходом."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3.","w":{"uk":"Варіант 3 зайвий: заборона в межах 10 м від переходу стосується розвороту, а не руху заднім ходом.","ru":"Вариант 3 лишний: запрет в пределах 10 м от перехода касается разворота, а не движения задним ходом."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2."}],"c":4,"e":{"uk":"Пішохідні та залізничні переїзди прямо названі в переліку місць, де рух заднім ходом заборонено {p:10.10}. Обмеження «10 м від переходу» стосується розвороту {p:10.7}, а не руху заднім ходом.","ru":"Пешеходные переходы и железнодорожные переезды прямо названы в перечне мест, где движение задним ходом запрещено {p:10.10}. Ограничение «10 м от перехода» касается разворота {p:10.7}, а не движения задним ходом."},"ref":["10.10"]},{"id":"h10-49","t":"h10","num":"10.49","q":{"uk":"У яких місцях заборонено рух заднім ходом?","ru":"В каких местах запрещено движение задним ходом?"},"a":[{"uk":"На перехрестях.","ru":"На перекрёстках.","w":{"uk":"Неповна відповідь: рух заднім ходом заборонено й на ділянках з обмеженою оглядовістю чи недостатньою видимістю {p:10.10}.","ru":"Неполный ответ: движение задним ходом запрещено и на участках с ограниченной обзорностью или недостаточной видимостью {p:10.10}."}},{"uk":"На ділянках доріг з обмеженою оглядовістю чи недостатньою видимістю.","ru":"На участках дорог с ограниченной обзорностью или недостаточной видимостью.","w":{"uk":"Неповна відповідь: рух заднім ходом заборонено й на перехрестях {p:10.10}.","ru":"Неполный ответ: движение задним ходом запрещено и на перекрёстках {p:10.10}."}},{"uk":"Під шляхопроводами та естакадами.","ru":"Под путепроводами и эстакадами.","w":{"uk":"{p:10.10} забороняє рух заднім ходом на шляхопроводах і естакадах, а не під ними; «під ними» — це заборона для розвороту.","ru":"{p:10.10} запрещает движение задним ходом на путепроводах и эстакадах, а не под ними; «под ними» — это запрет для разворота."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3.","w":{"uk":"Варіант 3 зайвий: місць під шляхопроводами та естакадами в переліку {p:10.10} немає.","ru":"Вариант 3 лишний: мест под путепроводами и эстакадами в перечне {p:10.10} нет."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2."}],"c":4,"e":{"uk":"Перехрестя та ділянки з обмеженою оглядовістю чи недостатньою видимістю прямо названі в {p:10.10}. Простору **під** шляхопроводами й естакадами в цьому переліку немає (заборона «під ними» є лише для розвороту {p:10.7}).","ru":"Перекрёстки и участки с ограниченной обзорностью или недостаточной видимостью прямо названы в {p:10.10}. Пространства **под** путепроводами и эстакадами в этом перечне нет (запрет «под ними» есть только для разворота {p:10.7})."},"ref":["10.10"]},{"id":"h10-50","t":"h10","num":"10.50","q":{"uk":"Якщо в місці з'їзду з дороги є смуга гальмування, чи завжди водій перед поворотом на іншу дорогу повинен знижувати швидкість на ній?","ru":"Если в месте съезда с дороги есть полоса торможения, всегда ли водитель перед поворотом на другую дорогу должен снижать скорость на ней?"},"a":[{"uk":"Може знижувати швидкість не на смузі гальмування, якщо швидкість невелика.","ru":"Может снижать скорость не на полосе торможения, если скорость невелика.","w":{"uk":"Винятків для невеликої швидкості Правила не передбачають: гальмувати треба лише на смузі гальмування {p:10.8}.","ru":"Исключений для небольшой скорости Правила не предусматривают: тормозить нужно только на полосе торможения {p:10.8}."}},{"uk":"Знижувати швидкість і повертати можна з будь-якої смуги.","ru":"Снижать скорость и поворачивать можно с любой полосы.","w":{"uk":"Повертати з будь-якої смуги не можна: треба заздалегідь перестроїтися на смугу гальмування {p:10.8}.","ru":"Поворачивать с любой полосы нельзя: нужно заранее перестроиться на полосу торможения {p:10.8}."}},{"uk":"Повинен своєчасно перестроїтися на цю смугу і знижувати швидкість тільки на ній.","ru":"Должен своевременно перестроиться на эту полосу и снижать скорость только на ней."}],"c":2,"e":{"uk":"За {p:10.8} за наявності смуги гальмування водій повинен своєчасно перестроїтися на неї і знижувати швидкість **тільки на ній**, щоб не гальмувати в основному потоці.","ru":"По {p:10.8} при наличии полосы торможения водитель должен своевременно перестроиться на неё и снижать скорость **только на ней**, чтобы не тормозить в основном потоке."},"ref":["10.8"]},{"id":"h10-51","t":"h10","num":"10.51","q":{"uk":"У якому з перелічених місць заборонено розворот?","ru":"В каком из перечисленных мест запрещён разворот?"},"a":[{"uk":"У тунелях.","ru":"В тоннелях.","w":{"uk":"Неповна відповідь: розворот заборонено також на мостах, шляхопроводах, естакадах і під ними {p:10.7}.","ru":"Неполный ответ: разворот запрещён также на мостах, путепроводах, эстакадах и под ними {p:10.7}."}},{"uk":"На мостах, шляхопроводах, естакадах.","ru":"На мостах, путепроводах, эстакадах.","w":{"uk":"Неповна відповідь: розворот заборонено також у тунелях і під мостами, шляхопроводами, естакадами {p:10.7}.","ru":"Неполный ответ: разворот запрещён также в тоннелях и под мостами, путепроводами, эстакадами {p:10.7}."}},{"uk":"Під мостами, шляхопроводами та естакадами.","ru":"Под мостами, путепроводами и эстакадами.","w":{"uk":"Неповна відповідь: розворот заборонено також у тунелях і на самих мостах, шляхопроводах, естакадах {p:10.7}.","ru":"Неполный ответ: разворот запрещён также в тоннелях и на самих мостах, путепроводах, эстакадах {p:10.7}."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2.","w":{"uk":"Неповна відповідь: розворот заборонено й під мостами, шляхопроводами та естакадами {p:10.7}.","ru":"Неполный ответ: разворот запрещён и под мостами, путепроводами и эстакадами {p:10.7}."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3."}],"c":4,"e":{"uk":"{p:10.7} забороняє розворот і в тунелях, і на мостах, шляхопроводах, естакадах, і під ними — тож правильні всі три варіанти.","ru":"{p:10.7} запрещает разворот и в тоннелях, и на мостах, путепроводах, эстакадах, и под ними — поэтому верны все три варианта."},"ref":["10.7"]},{"id":"h10-52","t":"h10","num":"10.52","q":{"uk":"Яких заходів повинен вжити водій, якщо габарити його транспортного засобу не дозволяють виконати поворот з крайнього положення на проїзній частині?","ru":"Какие меры должен принять водитель, если габариты его транспортного средства не позволяют выполнить поворот из крайнего положения на проезжей части?"},"a":[{"uk":"Повертати тільки з крайніх смуг для руху.","ru":"Поворачивать только с крайних полос для движения.","w":{"uk":"Якраз навпаки: великому транспортному засобу дозволено повертати не з крайньої смуги, бо з неї він не впишеться в поворот {p:10.6}.","ru":"Как раз наоборот: большому транспортному средству разрешено поворачивать не из крайней полосы, так как из неё он не впишется в поворот {p:10.6}."}},{"uk":"Не створювати небезпеки чи перешкод іншим учасникам руху.","ru":"Не создавать опасности или помех другим участникам движения.","w":{"uk":"Неповна відповідь: у разі потреби слід ще звернутися за допомогою до інших осіб {p:10.6}.","ru":"Неполный ответ: при необходимости следует ещё обратиться за помощью к другим лицам {p:10.6}."}},{"uk":"У разі потреби для забезпечення безпеки дорожнього руху слід звернутися за допомогою до інших осіб.","ru":"При необходимости для обеспечения безопасности дорожного движения следует обратиться за помощью к другим лицам.","w":{"uk":"Неповна відповідь: головна умова — не створювати небезпеки чи перешкод іншим учасникам руху {p:10.6}.","ru":"Неполный ответ: главное условие — не создавать опасности или помех другим участникам движения {p:10.6}."}},{"uk":"Відповіді 2 і 3.","ru":"Ответы 2 и 3."}],"c":3,"e":{"uk":"{p:10.6} дозволяє такому транспортному засобу відступити від вимоги крайнього положення, якщо це не створить небезпеки чи перешкод іншим, а в разі потреби — звернутися за допомогою до інших осіб.","ru":"{p:10.6} разрешает такому транспортному средству отступить от требования крайнего положения, если это не создаст опасности или помех другим, а при необходимости — обратиться за помощью к другим лицам."},"ref":["10.6"]},{"id":"h10-53","t":"h10","num":"10.53","q":{"uk":"У якому випадку водій може виконати поворот на перехресті не з крайнього положення?","ru":"В каком случае водитель может выполнить поворот на перекрёстке не из крайнего положения?"},"a":[{"uk":"Якщо транспортний засіб через свої габарити не може виконати поворот чи розворот з відповідного крайнього положення.","ru":"Если транспортное средство из-за своих габаритов не может выполнить поворот или разворот из соответствующего крайнего положения.","w":{"uk":"Неповна відповідь: габаритів замало, маневр ще не повинен суперечити знакам, розмітці й створювати небезпеку {p:10.6}.","ru":"Неполный ответ: габаритов недостаточно, манёвр ещё не должен противоречить знакам, разметке и создавать опасность {p:10.6}."}},{"uk":"Якщо це не суперечить вимогам заборонних чи наказових дорожніх знаків, дорожньої розмітки та не створить небезпеки чи перешкод для інших учасників дорожнього руху.","ru":"Если это не противоречит требованиям запрещающих или предписывающих дорожных знаков, дорожной разметки и не создаст опасности или помех для других участников дорожного движения.","w":{"uk":"Неповна відповідь: без поважної причини (габарити тощо) повертати не з крайнього положення не можна {p:10.4}.","ru":"Неполный ответ: без уважительной причины (габариты и т. п.) поворачивать не из крайнего положения нельзя {p:10.4}."}},{"uk":"Правильні відповіді 1 і 2.","ru":"Правильные ответы 1 и 2."}],"c":2,"e":{"uk":"{p:10.6} дозволяє відступити від вимоги крайнього положення, коли транспортний засіб через габарити не може повернути з нього **і** коли це не суперечить знакам, розмітці та не створює небезпеки чи перешкод. Потрібні обидві умови.","ru":"{p:10.6} разрешает отступить от требования крайнего положения, когда транспортное средство из-за габаритов не может повернуть из него, **и** когда это не противоречит знакам, разметке и не создаёт опасности или помех. Нужны оба условия."},"ref":["10.6"]},{"id":"h10-54","t":"h10","num":"10.54","q":{"uk":"Яким правилом повинні керуватися водії транспортних засобів, якщо траєкторії їхнього руху перетинаються, а черговість проїзду не обумовлена Правилами?","ru":"Каким правилом должны руководствоваться водители транспортных средств, если траектории их движения пересекаются, а очерёдность проезда не оговорена Правилами?"},"a":[{"uk":"Перевагу має той водій, який їде прямо.","ru":"Преимущество имеет тот водитель, который едет прямо.","w":{"uk":"Напрямок руху (прямо чи з поворотом) у цьому випадку переваги не дає — вирішує лише, хто з правого боку {p:10.11}.","ru":"Направление движения (прямо или с поворотом) в этом случае преимущества не даёт — решает только, кто справа {p:10.11}."}},{"uk":"Водій, до якого транспортний засіб наближається з правого боку, повинен дати дорогу.","ru":"Водитель, к которому транспортное средство приближается справа, должен уступить дорогу."},{"uk":"Перевагу має той водій, який їде прямо або повертає праворуч.","ru":"Преимущество имеет тот водитель, который едет прямо или поворачивает направо.","w":{"uk":"Такого правила немає: черговість визначається тим, хто наближається справа {p:10.11}.","ru":"Такого правила нет: очерёдность определяется тем, кто приближается справа {p:10.11}."}}],"c":1,"e":{"uk":"Це дослівно {p:10.11}: якщо траєкторії перетинаються, а черговість не обумовлена Правилами, дає дорогу водій, до якого транспортний засіб наближається з правого боку.","ru":"Это дословно {p:10.11}: если траектории пересекаются, а очерёдность не оговорена Правилами, уступает дорогу водитель, к которому транспортное средство приближается справа."},"ref":["10.11"]},{"id":"h10-55","t":"h10","num":"10.55","q":{"uk":"Ви, як водій, перед початком руху повинні:","ru":"Вы как водитель перед началом движения должны:"},"a":[{"uk":"Переконатися у тому, що це буде безпечно.","ru":"Убедиться в том, что это будет безопасно.","w":{"uk":"Неповна відповідь: треба ще переконатися, що рух не створить перешкод іншим учасникам {p:10.1}.","ru":"Неполный ответ: нужно ещё убедиться, что движение не создаст помех другим участникам {p:10.1}."}},{"uk":"Переконатися у тому що це не створить перешкод або небезпеки іншим учасникам руху.","ru":"Убедиться в том, что это не создаст помех или опасности другим участникам движения.","w":{"uk":"Неповна відповідь: треба ще переконатися, що рух безпечний {p:10.1}.","ru":"Неполный ответ: нужно ещё убедиться, что движение безопасно {p:10.1}."}},{"uk":"Виконати дії зазначені у 1 та 2 відповідях.","ru":"Выполнить действия, указанные в ответах 1 и 2."}],"c":2,"e":{"uk":"За {p:10.1} перед початком руху водій повинен переконатися і в тому, що це **безпечно**, і в тому, що це **не створить перешкод або небезпеки** іншим учасникам руху.","ru":"По {p:10.1} перед началом движения водитель должен убедиться и в том, что это **безопасно**, и в том, что это **не создаст помех или опасности** другим участникам движения."},"ref":["10.1"]},{"id":"h10-56","t":"h10","num":"10.56","q":{"uk":"Ви, як водій, перед поворотом праворуч повинні:","ru":"Вы как водитель перед поворотом направо должны:"},"a":[{"uk":"Переконатися у тому, що це буде безпечно.","ru":"Убедиться в том, что это будет безопасно.","w":{"uk":"Неповна відповідь: треба ще переконатися, що поворот не створить перешкод, і зайняти крайнє праве положення.","ru":"Неполный ответ: нужно ещё убедиться, что поворот не создаст помех, и занять крайнее правое положение."}},{"uk":"Переконатися у тому що це не створить перешкод або небезпеки іншим учасникам руху.","ru":"Убедиться в том, что это не создаст помех или опасности другим участникам движения.","w":{"uk":"Неповна відповідь: треба ще переконатися в безпечності й зайняти крайнє праве положення {p:10.4}.","ru":"Неполный ответ: нужно ещё убедиться в безопасности и занять крайнее правое положение {p:10.4}."}},{"uk":"Зайняти відповідне крайнє праве положення.","ru":"Занять соответствующее крайнее правое положение.","w":{"uk":"Неповна відповідь: перед поворотом треба ще переконатися, що він безпечний і не заважає іншим {p:10.1}.","ru":"Неполный ответ: перед поворотом нужно ещё убедиться, что он безопасен и не мешает другим {p:10.1}."}},{"uk":"Виконати усі вищеперераховані дії.","ru":"Выполнить все вышеперечисленные действия."}],"c":3,"e":{"uk":"Перед поворотом треба переконатися в його безпечності й відсутності перешкод для інших {p:10.1} і завчасно зайняти крайнє праве положення {p:10.4}. Обов'язкові всі три дії.","ru":"Перед поворотом нужно убедиться в его безопасности и отсутствии помех для других {p:10.1} и заблаговременно занять крайнее правое положение {p:10.4}. Обязательны все три действия."},"ref":["10.1","10.4"]},{"id":"h10-57","t":"h10","num":"10.57","q":{"uk":"Ви водій автомобіля, виїжджаючи з прилеглої до дороги території повинні перед проїзною частиною чи тротуаром дати дорогу:","ru":"Вы водитель автомобиля и, выезжая с прилегающей к дороге территории, должны перед проезжей частью или тротуаром уступить дорогу:"},"a":[{"uk":"Тільки пішоходам.","ru":"Только пешеходам.","w":{"uk":"Неповна відповідь: дорогу треба дати й транспортним засобам, що рухаються дорогою {p:10.2}.","ru":"Неполный ответ: дорогу нужно уступить и транспортным средствам, движущимся по дороге {p:10.2}."}},{"uk":"Тільки транспортним засобам.","ru":"Только транспортным средствам.","w":{"uk":"Неповна відповідь: дорогу треба дати й пішоходам {p:10.2}.","ru":"Неполный ответ: дорогу нужно уступить и пешеходам {p:10.2}."}},{"uk":"Пішоходам і транспортним засобам.","ru":"Пешеходам и транспортным средствам."}],"c":2,"e":{"uk":"За {p:10.2} при виїзді на дорогу з прилеглої території водій повинен перед проїзною частиною чи тротуаром дати дорогу і пішоходам, і транспортним засобам, що рухаються дорогою.","ru":"По {p:10.2} при выезде на дорогу с прилегающей территории водитель должен перед проезжей частью или тротуаром уступить дорогу и пешеходам, и транспортным средствам, движущимся по дороге."},"ref":["10.2"]},{"id":"h10-58","t":"h10","num":"10.58","q":{"uk":"Ви велосипедист, виїжджаючи з прилеглої до дороги території повинні перед проїзною частиною чи тротуаром дати дорогу:","ru":"Вы велосипедист и, выезжая с прилегающей к дороге территории, должны перед проезжей частью или тротуаром уступить дорогу:"},"a":[{"uk":"Тільки пішоходам.","ru":"Только пешеходам.","w":{"uk":"Неповна відповідь: велосипедист повинен пропустити й транспортні засоби, що рухаються дорогою {p:10.2}.","ru":"Неполный ответ: велосипедист должен пропустить и транспортные средства, движущиеся по дороге {p:10.2}."}},{"uk":"Тільки транспортним засобам.","ru":"Только транспортным средствам.","w":{"uk":"Неповна відповідь: велосипедист повинен пропустити й пішоходів {p:10.2}.","ru":"Неполный ответ: велосипедист должен пропустить и пешеходов {p:10.2}."}},{"uk":"Пішоходам і транспортним засобам.","ru":"Пешеходам и транспортным средствам."}],"c":2,"e":{"uk":"Велосипед — теж транспортний засіб {p:1.10}, тож, виїжджаючи з прилеглої території, велосипедист, як і водій, перед проїзною частиною чи тротуаром дає дорогу пішоходам і транспортним засобам {p:10.2}.","ru":"Велосипед — тоже транспортное средство {p:1.10}, поэтому, выезжая с прилегающей территории, велосипедист, как и водитель, перед проезжей частью или тротуаром уступает дорогу пешеходам и транспортным средствам {p:10.2}."},"ref":["10.2","1.10"]},{"id":"h10-59","t":"h10","num":"10.59","q":{"uk":"Ви, як водій автомобіля, повертаючи з дороги на прилеглу територію, повинні:","ru":"Вы как водитель автомобиля, поворачивая с дороги на прилегающую территорию, должны:"},"a":[{"uk":"Дати дорогу тільки пішоходам.","ru":"Уступить дорогу только пешеходам.","w":{"uk":"Неповна відповідь: треба пропустити й велосипедистів, чий шлях Ви перетинаєте {p:10.2}.","ru":"Неполный ответ: нужно пропустить и велосипедистов, чей путь вы пересекаете {p:10.2}."}},{"uk":"Дати дорогу тільки велосипедистам.","ru":"Уступить дорогу только велосипедистам.","w":{"uk":"Неповна відповідь: треба пропустити й пішоходів, чий шлях Ви перетинаєте {p:10.2}.","ru":"Неполный ответ: нужно пропустить и пешеходов, чей путь вы пересекаете {p:10.2}."}},{"uk":"Дати дорогу велосипедистам і пішоходам, напрямок руху яких ви перетинаєте.","ru":"Уступить дорогу велосипедистам и пешеходам, направление движения которых вы пересекаете."}],"c":2,"e":{"uk":"За {p:10.2}, з'їжджаючи з дороги, водій повинен дати дорогу велосипедистам і пішоходам, напрямок руху яких він перетинає.","ru":"По {p:10.2}, съезжая с дороги, водитель должен уступить дорогу велосипедистам и пешеходам, направление движения которых он пересекает."},"ref":["10.2"]},{"id":"h10-60","t":"h10","num":"10.60","q":{"uk":"Ви, як велосипедист, перед поворотом праворуч повинні:","ru":"Вы как велосипедист перед поворотом направо должны:"},"a":[{"uk":"Переконатися у тому, що це буде безпечно.","ru":"Убедиться в том, что это будет безопасно.","w":{"uk":"Неповна відповідь: треба ще переконатися, що поворот не заважає іншим, і зайняти крайнє праве положення.","ru":"Неполный ответ: нужно ещё убедиться, что поворот не мешает другим, и занять крайнее правое положение."}},{"uk":"Переконатися у тому що це не створить перешкод або небезпеки іншим учасникам руху.","ru":"Убедиться в том, что это не создаст помех или опасности другим участникам движения.","w":{"uk":"Неповна відповідь: треба ще переконатися в безпечності й зайняти крайнє праве положення {p:10.4}.","ru":"Неполный ответ: нужно ещё убедиться в безопасности и занять крайнее правое положение {p:10.4}."}},{"uk":"Зайняти відповідне крайнє праве положення.","ru":"Занять соответствующее крайнее правое положение.","w":{"uk":"Неповна відповідь: перед поворотом треба ще переконатися, що він безпечний і не заважає іншим {p:10.1}.","ru":"Неполный ответ: перед поворотом нужно ещё убедиться, что он безопасен и не мешает другим {p:10.1}."}},{"uk":"Виконати усі вищеперераховані дії.","ru":"Выполнить все вышеперечисленные действия."}],"c":3,"e":{"uk":"Велосипедист керує транспортним засобом {p:1.10}, тож перед поворотом теж повинен переконатися в безпечності маневру й відсутності перешкод для інших {p:10.1} і зайняти крайнє праве положення {p:10.4}.","ru":"Велосипедист управляет транспортным средством {p:1.10}, поэтому перед поворотом тоже должен убедиться в безопасности манёвра и отсутствии помех для других {p:10.1} и занять крайнее правое положение {p:10.4}."},"ref":["10.1","10.4","1.10"]},{"id":"h10-61","t":"h10","num":"10.61","q":{"uk":"Яку смугу повинен зайняти водій перед поворотом ліворуч на перехресті згідно з Правилами дорожнього руху?","ru":"Какую полосу должен занять водитель перед поворотом налево на перекрёстке согласно Правилам дорожного движения?"},"a":[{"uk":"Крайню ліву смугу.","ru":"Крайнюю левую полосу.","w":{"uk":"Неповна відповідь: знаки чи розмітка можуть дозволяти поворот ліворуч і не з крайньої лівої смуги {p:10.4}.","ru":"Неполный ответ: знаки или разметка могут разрешать поворот налево и не из крайней левой полосы {p:10.4}."}},{"uk":"Будь-яку смугу, з якої дозволено поворот ліворуч дорожніми знаками або дорожньою розміткою.","ru":"Любую полосу, с которой поворот налево разрешён дорожными знаками или дорожной разметкой.","w":{"uk":"Неповна відповідь: якщо знаків і розмітки немає, повертати ліворуч треба з крайнього лівого положення {p:10.4}.","ru":"Неполный ответ: если знаков и разметки нет, поворачивать налево нужно из крайнего левого положения {p:10.4}."}},{"uk":"Відповіді 1 або 2 (залежно від дорожньої обстановки).","ru":"Ответы 1 или 2 (в зависимости от дорожной обстановки)."}],"c":2,"e":{"uk":"Загальне правило — завчасно зайняти крайнє ліве положення {p:10.4}; але якщо знаки (наприклад, {s:5.16}) чи розмітка {m:1.18} дозволяють поворот ліворуч і з інших смуг, повертати можна з будь-якої з них — це виняток із того самого пункту.","ru":"Общее правило — заблаговременно занять крайнее левое положение {p:10.4}; но если знаки (например, {s:5.16}) или разметка {m:1.18} разрешают поворот налево и из других полос, поворачивать можно из любой из них — это исключение из того же пункта."},"ref":["10.4"]},{"id":"h10-62","t":"h10","num":"10.62","q":{"uk":"Чи дозволено Вам виконати розворот на перехресті в зоні 10 метрів від переходу?","ru":"Разрешено ли вам выполнить разворот на перекрёстке в зоне 10 метров от перехода?"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"На перехресті 10-метрова заборона не діє, якщо сам розворот там дозволений {p:10.7}.","ru":"На перекрёстке 10-метровый запрет не действует, если сам разворот там разрешён {p:10.7}."}}],"c":0,"e":{"uk":"Заборона розвороту ближче 10 м від пішохідного переходу має прямий виняток: вона не поширюється на дозволений розворот на перехресті {p:10.7}.","ru":"Запрет разворота ближе 10 м от пешеходного перехода имеет прямое исключение: он не распространяется на разрешённый разворот на перекрёстке {p:10.7}."},"ref":["10.7"]},{"id":"h10-63","t":"h10","num":"10.63","q":{"uk":"Чи дозволено Вам виконати розворот одразу після проїзду зустрічного автомобіля в наведеній ситуації?","ru":"Разрешено ли вам выполнить разворот сразу после проезда встречного автомобиля в приведённой ситуации?"},"a":[{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"Те, що один зустрічний автомобіль проїхав, не робить маневр безпечним: за поворотом у тумані може бути наступний, а видимість менше 100 м {p:10.7}.","ru":"То, что один встречный автомобиль проехал, не делает манёвр безопасным: за поворотом в тумане может быть следующий, а видимость менее 100 м {p:10.7}."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":1,"e":{"uk":"Туман і крутий поворот, позначений знаками «Напрямок повороту», обмежують видимість дороги менше ніж до 100 м, а за такої видимості хоча б в одному напрямку розворот заборонено {p:10.7}.","ru":"Туман и крутой поворот, обозначенный знаками «Направление поворота», ограничивают видимость дороги менее чем до 100 м, а при такой видимости хотя бы в одном направлении разворот запрещён {p:10.7}."},"ref":["10.7"],"pic":["img/hsc/10-63-1.jpg"]},{"id":"h10-64","t":"h10","num":"10.64","q":{"uk":"Чи дозволено Вам виконати розворот, якщо видимість дороги менше 100 м в обох напрямках?","ru":"Разрешено ли вам выполнить разворот, если видимость дороги менее 100 м в обоих направлениях?"},"a":[{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"За видимості менше 100 м водій не встигне побачити транспорт, що наближається, тому розворот заборонено {p:10.7}.","ru":"При видимости менее 100 м водитель не успеет увидеть приближающийся транспорт, поэтому разворот запрещён {p:10.7}."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":1,"e":{"uk":"{p:10.7} забороняє розворот, якщо видимість дороги менше 100 м **хоча б в одному** напрямку, а тут туман обмежує її в обох.","ru":"{p:10.7} запрещает разворот, если видимость дороги менее 100 м **хотя бы в одном** направлении, а здесь туман ограничивает её в обоих."},"ref":["10.7"],"pic":["img/hsc/10-64-1.jpg"]},{"id":"h10-65","t":"h10","num":"10.65","q":{"uk":"Водій сірого автомобіля здійснює в’їзд на перехрестя з круговим рухом. Чи потрібно в такому випадку вмикати лівий покажчик повороту?","ru":"Водитель серого автомобиля осуществляет въезд на перекрёсток с круговым движением. Нужно ли в таком случае включать левый указатель поворота?"},"a":[{"uk":"Так.","ru":"Да.","w":{"uk":"Лівий покажчик сповіщає про поворот ліворуч, якого під час в'їзду на коло немає, і лише заплутає інших учасників руху {p:9.2}.","ru":"Левый указатель сообщает о повороте налево, которого при въезде на круг нет, и лишь запутает других участников движения {p:9.2}."}},{"uk":"Ні.","ru":"Нет."}],"c":1,"e":{"uk":"В'їжджаючи на перехрестя з круговим рухом, автомобіль не повертає ліворуч, а відхиляється праворуч і далі рухається по колу в напрямку, показаному стрілками знака {s:4.10}. Покажчики вмикають відповідно до напрямку маневру {p:9.2}, тож лівий вводив би інших в оману.","ru":"Въезжая на перекрёсток с круговым движением, автомобиль не поворачивает налево, а отклоняется направо и далее движется по кругу в направлении, указанном стрелками знака {s:4.10}. Указатели включают в соответствии с направлением манёвра {p:9.2}, поэтому левый вводил бы других в заблуждение."},"ref":["9.2"],"pic":["img/hsc/10-65-1.jpg"]},{"id":"h10-66","t":"h10","num":"10.66","q":{"uk":"Чи дозволено водієві червоного автомобіля рухатись прямо у даному випадку?","ru":"Разрешено ли водителю красного автомобиля двигаться прямо в данном случае?"},"a":[{"uk":"Дозволено.","ru":"Разрешено."},{"uk":"Заборонено.","ru":"Запрещено.","w":{"uk":"Червоний автомобіль не в крайній лівій смузі, призначеній лише для повороту ліворуч, а в другій, з якої знак {s:5.16} дозволяє рух прямо.","ru":"Красный автомобиль не в крайней левой полосе, предназначенной только для поворота налево, а во второй, из которой знак {s:5.16} разрешает движение прямо."}}],"c":0,"e":{"uk":"Знак {s:5.16} показує, що з крайньої лівої смуги можна лише повертати ліворуч, а з другої — рухатися прямо або ліворуч. Червоний автомобіль займає другу смугу (ліворуч від нього є ще ряд автомобілів), тож рух прямо для нього дозволений {p:33.5}.","ru":"Знак {s:5.16} показывает, что из крайней левой полосы можно только поворачивать налево, а из второй — двигаться прямо или налево. Красный автомобиль занимает вторую полосу (слева от него есть ещё ряд автомобилей), поэтому движение прямо для него разрешено {p:33.5}."},"ref":["33.5"],"pic":["img/hsc/10-66-1.jpg"]},{"id":"h10-67","t":"h10","num":"10.67","q":{"uk":"Чи дозволено Вам повернути ліворуч у даному випадку?","ru":"Разрешено ли вам повернуть налево в данном случае?"},"a":[{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"Дорога, на яку Ви виїжджаєте, одностороння ({s:5.7.1}), і рух нею можливий лише праворуч {p:33.5}.","ru":"Дорога, на которую вы выезжаете, односторонняя ({s:5.7.1}), и движение по ней возможно только направо {p:33.5}."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":1,"e":{"uk":"Знак {s:5.7.1} над знаком {s:2.1} показує, що на перехрещуваній дорозі організовано односторонній рух праворуч, а рух нею дозволено лише в напрямку стрілки {p:33.5}. Поворот ліворуч означав би виїзд назустріч потоку.","ru":"Знак {s:5.7.1} над знаком {s:2.1} показывает, что на пересекаемой дороге организовано одностороннее движение направо, а движение по ней разрешено только в направлении стрелки {p:33.5}. Поворот налево означал бы выезд навстречу потоку."},"ref":["33.5"],"pic":["img/hsc/10-67-1.jpg"]},{"id":"h10-68","t":"h10","num":"10.68","q":{"uk":"У яких випадках дозволено виконати розворот на пішохідному переході?","ru":"В каких случаях разрешено выполнить разворот на пешеходном переходе?"},"a":[{"uk":"Якщо поруч немає транспортних засобів.","ru":"Если рядом нет транспортных средств.","w":{"uk":"Відсутність транспорту поруч не скасовує заборони розвороту на пішохідному переході {p:10.7}.","ru":"Отсутствие транспорта рядом не отменяет запрета разворота на пешеходном переходе {p:10.7}."}},{"uk":"Якщо на переході немає пішоходів.","ru":"Если на переходе нет пешеходов.","w":{"uk":"Заборона діє й тоді, коли пішоходів на переході немає: вони можуть з'явитися в будь-який момент {p:10.7}.","ru":"Запрет действует и тогда, когда пешеходов на переходе нет: они могут появиться в любой момент {p:10.7}."}},{"uk":"Заборонено, крім випадку дозволеного розвороту на перехресті.","ru":"Запрещено, кроме случая разрешённого разворота на перекрёстке."}],"c":2,"e":{"uk":"{p:10.7} забороняє розворот на пішохідних переходах і ближче 10 м від них; єдиний виняток — дозволений розворот на перехресті.","ru":"{p:10.7} запрещает разворот на пешеходных переходах и ближе 10 м от них; единственное исключение — разрешённый разворот на перекрёстке."},"ref":["10.7"]},{"id":"h10-69","t":"h10","num":"10.69","q":{"uk":"Якщо пішохідний перехід розділений острівцем безпеки, на такому переході дозволено виконати розворот?","ru":"Если пешеходный переход разделён островком безопасности, разрешено ли на таком переходе выполнить разворот?"},"a":[{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"Острівець не дає права розвертатися: це частина пішохідного переходу, де розворот заборонено {p:10.7}.","ru":"Островок не даёт права разворачиваться: это часть пешеходного перехода, где разворот запрещён {p:10.7}."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":1,"e":{"uk":"Острівець безпеки — елемент самого пішохідного переходу {p:1.10}, тож перехід лишається переходом, а розворот на ньому та ближче 10 м від нього заборонено {p:10.7}.","ru":"Островок безопасности — элемент самого пешеходного перехода {p:1.10}, поэтому переход остаётся переходом, а разворот на нём и ближе 10 м от него запрещён {p:10.7}."},"ref":["10.7","1.10"],"pic":["img/hsc/10-69-1.jpg"]},{"id":"h10-70","t":"h10","num":"10.70","q":{"uk":"У якому випадку дозволено виконати розворот під час руху тунелем?","ru":"В каком случае разрешено выполнить разворот во время движения по тоннелю?"},"a":[{"uk":"Якщо поруч немає транспортних засобів.","ru":"Если рядом нет транспортных средств.","w":{"uk":"Відсутність транспорту поруч не скасовує безумовної заборони розвороту в тунелі {p:10.7}.","ru":"Отсутствие транспорта рядом не отменяет безусловного запрета разворота в тоннеле {p:10.7}."}},{"uk":"Якщо тунель добре освітлений, а його ширина дозволяє розвернутись швидко та безпечно.","ru":"Если тоннель хорошо освещён, а его ширина позволяет развернуться быстро и безопасно.","w":{"uk":"Освітлення й ширина тунелю не мають значення: розворот у тунелях заборонено завжди {p:10.7}.","ru":"Освещение и ширина тоннеля не имеют значения: разворот в тоннелях запрещён всегда {p:10.7}."}},{"uk":"Розворот у тунелі заборонений.","ru":"Разворот в тоннеле запрещён."}],"c":2,"e":{"uk":"{p:10.7} забороняє розворот у тунелях без будь-яких винятків.","ru":"{p:10.7} запрещает разворот в тоннелях без каких-либо исключений."},"ref":["10.7"],"pic":["img/hsc/10-70-1.jpg"]},{"id":"h10-71","t":"h10","num":"10.71","q":{"uk":"Під час руху транспортного засобу заднім ходом водій для забезпечення безпеки руху, у разі потреби повинен звернутися за допомогою до інших осіб:","ru":"Во время движения транспортного средства задним ходом водитель для обеспечения безопасности движения при необходимости должен обратиться за помощью к другим лицам:"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"{p:10.9} прямо зобов'язує водія в разі потреби звернутися за допомогою до інших осіб.","ru":"{p:10.9} прямо обязывает водителя при необходимости обратиться за помощью к другим лицам."}}],"c":0,"e":{"uk":"Це пряма вимога {p:10.9}: якщо огляду назад недостатньо, водій повинен звернутися за допомогою до інших осіб.","ru":"Это прямое требование {p:10.9}: если обзора назад недостаточно, водитель должен обратиться за помощью к другим лицам."},"ref":["10.9"]},{"id":"h10-72","t":"h10","num":"10.72","q":{"uk":"Чи можете Ви, виїжджаючи з місця паркування заднім ходом, для забезпечення безпеки руху звернутися за допомогою до інших осіб:","ru":"Можете ли вы, выезжая с места парковки задним ходом, для обеспечения безопасности движения обратиться за помощью к другим лицам:"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"Звернутися по допомогу не лише можна, а в разі потреби й треба {p:10.9}.","ru":"Обратиться за помощью не только можно, а при необходимости и нужно {p:10.9}."}}],"c":0,"e":{"uk":"Так: якщо огляду назад недостатньо, {p:10.9} навіть зобов'язує водія звернутися за допомогою до інших осіб — наприклад, попросити когось підказувати ззовні.","ru":"Да: если обзора назад недостаточно, {p:10.9} даже обязывает водителя обратиться за помощью к другим лицам — например, попросить кого-то подсказывать снаружи."},"ref":["10.9"],"pic":["img/hsc/10-72-1.jpg"]},{"id":"h10-73","t":"h10","num":"10.73","q":{"uk":"Під час руху на автомагістралі водій червоного автомобіля пропустив поворот праворуч. Чи дозволено йому рухатись заднім ходом, якщо позаду немає транспортних засобів?","ru":"Во время движения по автомагистрали водитель красного автомобиля пропустил поворот направо. Разрешено ли ему двигаться задним ходом, если сзади нет транспортных средств?"},"a":[{"uk":"Так, попередньо увімкнувши аварійну світлову сигналізацію.","ru":"Да, предварительно включив аварийную световую сигнализацию.","w":{"uk":"Аварійна сигналізація не скасовує заборони {p:10.10}, а на автомагістралі транспорт ззаду наближається дуже швидко.","ru":"Аварийная сигнализация не отменяет запрета {p:10.10}, а на автомагистрали транспорт сзади приближается очень быстро."}},{"uk":"Ні.","ru":"Нет."}],"c":1,"e":{"uk":"Знак {s:5.1} позначає автомагістраль, а на ній рух заднім ходом заборонено {p:10.10} без винятків — навіть якщо позаду порожньо. Пропущений з'їзд доведеться проїхати до наступного.","ru":"Знак {s:5.1} обозначает автомагистраль, а на ней движение задним ходом запрещено {p:10.10} без исключений — даже если сзади пусто. Пропущенный съезд придётся проехать до следующего."},"ref":["10.10"],"pic":["img/hsc/10-73-1.jpg"]},{"id":"h10-74","t":"h10","num":"10.74","q":{"uk":"Рухатись заднім ходом на автомагістралі у разі відсутності позаду транспортних засобів:","ru":"Двигаться задним ходом на автомагистрали при отсутствии сзади транспортных средств:"},"a":[{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"Виняток «неможливо під'їхати інакше» діє лише на дорогах з одностороннім рухом, а не на автомагістралях {p:10.10}.","ru":"Исключение «невозможно подъехать иначе» действует только на дорогах с односторонним движением, а не на автомагистралях {p:10.10}."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":1,"e":{"uk":"{p:10.10} забороняє рух заднім ходом на автомагістралях безумовно — відсутність транспорту позаду нічого не змінює.","ru":"{p:10.10} запрещает движение задним ходом на автомагистралях безусловно — отсутствие транспорта сзади ничего не меняет."},"ref":["10.10"]},{"id":"h10-75","t":"h10","num":"10.75","q":{"uk":"Ви рухаєтесь на спуск з гірської дороги. З метою економії палива можна під час руху по цій дорозі вимкнути передачу?","ru":"Вы движетесь на спуск по горной дороге. Можно ли с целью экономии топлива во время движения по этой дороге выключить передачу?"},"a":[{"uk":"Так.","ru":"Да.","w":{"uk":"Економія палива не виправдовує ризику: без передачі автомобіль втрачає гальмування двигуном, і Правила такий рух на гірських дорогах забороняють {p:28.3}.","ru":"Экономия топлива не оправдывает риска: без передачи автомобиль теряет торможение двигателем, и Правила такое движение на горных дорогах запрещают {p:28.3}."}},{"uk":"Ні.","ru":"Нет."}],"c":1,"e":{"uk":"На гірських дорогах заборонено рухатися з непрацюючим двигуном та вимкненими зчепленням або передачею {p:28.3}: на спуску увімкнена передача гальмує двигуном, а без неї гальма перегріваються й можуть відмовити.","ru":"На горных дорогах запрещено двигаться с неработающим двигателем и выключенным сцеплением или передачей {p:28.3}: на спуске включённая передача тормозит двигателем, а без неё тормоза перегреваются и могут отказать."},"ref":["28.3"]},{"id":"h10-76","t":"h10","num":"10.76","q":{"uk":"Чи дозволений розворот у технологічних розривах розділювальної смуги на автомагістралі?","ru":"Разрешён ли разворот в технологических разрывах разделительной полосы на автомагистрали?"},"a":[{"uk":"Дозволений.","ru":"Разрешён.","w":{"uk":"Технологічний розрив не є ні перехрестям, ні позначеним місцем для розвороту, тож розворот у ньому заборонено {p:10.7}.","ru":"Технологический разрыв не является ни перекрёстком, ни обозначенным местом для разворота, поэтому разворот в нём запрещён {p:10.7}."}},{"uk":"Дозволений, якщо дорога добре проглядається в обидві сторони.","ru":"Разрешён, если дорога хорошо просматривается в обе стороны.","w":{"uk":"Гарна видимість не створює винятку: на автомагістралі розвертатися можна лише в місцях, позначених {s:5.29} чи {s:5.30}, і на перехрестях {p:10.7}.","ru":"Хорошая видимость не создаёт исключения: на автомагистрали разворачиваться можно только в местах, обозначенных {s:5.29} или {s:5.30}, и на перекрёстках {p:10.7}."}},{"uk":"Заборонений.","ru":"Запрещён."}],"c":2,"e":{"uk":"На автомагістралі розворот дозволено лише на перехрестях і в місцях, позначених знаками {s:5.29} та {s:5.30} {p:10.7}; технологічний розрив розділювальної смуги (як на фото) до них не належить.","ru":"На автомагистрали разворот разрешён только на перекрёстках и в местах, обозначенных знаками {s:5.29} и {s:5.30} {p:10.7}; технологический разрыв разделительной полосы (как на фото) к ним не относится."},"ref":["10.7"],"pic":["img/hsc/10-76-1.jpg"]},{"id":"h11-1","t":"h11","num":"11.1","q":{"uk":"Вам дозволений розворот по траєкторії Б, тому що:","ru":"Вам разрешён разворот по траектории Б, потому что:"},"a":[{"uk":"Траєкторія А допустима тільки для вантажних автомобілів.","ru":"Траектория А допустима только для грузовых автомобилей.","w":{"uk":"Правила не встановлюють окремої траєкторії розвороту для вантажних автомобілів: вимога {p:11.8} стосується всіх нерейкових транспортних засобів.","ru":"Правила не устанавливают отдельной траектории разворота для грузовых автомобилей: требование {p:11.8} касается всех нерельсовых транспортных средств."}},{"uk":"Траєкторія Б коротша, ніж траєкторія А.","ru":"Траектория Б короче, чем траектория А.","w":{"uk":"Довжина траєкторії значення не має — вирішує вимога розвертатися з трамвайної колії попутного напрямку.","ru":"Длина траектории значения не имеет — решает требование разворачиваться с трамвайных путей попутного направления."}},{"uk":"Розворот повинен виконуватися з трамвайних колій попутного напрямку.","ru":"Разворот должен выполняться с трамвайных путей попутного направления."}],"c":2,"e":{"uk":"За {p:11.8} поворот ліворуч або розворот повинні виконуватися **з трамвайної колії попутного напрямку**, розташованої на одному рівні з проїзною частиною, якщо інший порядок не встановлено знаками чи розміткою. Розворот по траєкторії Б виконується саме з трамвайної колії, а по траєкторії А — ні.","ru":"Согласно {p:11.8} поворот налево или разворот должны выполняться **с трамвайных путей попутного направления**, расположенных на одном уровне с проезжей частью, если иной порядок не установлен знаками или разметкой. Разворот по траектории Б выполняется именно с трамвайных путей, а по траектории А — нет."},"ref":["11.8"],"pic":["img/hsc/11-1-1.jpg"]},{"id":"h11-2","t":"h11","num":"11.2","q":{"uk":"Чи дозволено автомобілю виконати виїзд на трамвайну колію попутного напрямку?","ru":"Разрешено ли автомобилю выехать на трамвайные пути попутного направления?"},"a":[{"uk":"Дозволено.","ru":"Разрешено."},{"uk":"Заборонено.","ru":"Запрещено.","w":{"uk":"Знаків чи розмітки, що забороняють рух по колії, на малюнку немає, а для об'їзду перешкоди {p:11.8} прямо дозволяє виїзд на трамвайну колію попутного напрямку.","ru":"Знаков или разметки, запрещающих движение по путям, на рисунке нет, а для объезда препятствия {p:11.8} прямо разрешает выезд на трамвайные пути попутного направления."}}],"c":0,"e":{"uk":"Попереду на єдиній смузі стоїть автомобіль з увімкненою аварійною сигналізацією, і ширина проїзної частини не дає об'їхати його, не заїжджаючи на колію. {p:11.8} у такому разі дозволяє об'їзд по трамвайній колії попутного напрямку, якщо це не створює перешкод для руху трамвая.","ru":"Впереди на единственной полосе стоит автомобиль с включённой аварийной сигнализацией, и ширина проезжей части не позволяет объехать его, не заезжая на пути. {p:11.8} в таком случае разрешает объезд по трамвайным путям попутного направления, если это не создаёт помех для движения трамвая."},"ref":["11.8"],"pic":["img/hsc/11-2-1.jpg"]},{"id":"h11-3","t":"h11","num":"11.3","q":{"uk":"По якій траєкторії водієві дозволено виконати поворот ліворуч?","ru":"По какой траектории водителю разрешено выполнить поворот налево?"},"a":[{"uk":"По траєкторії А.","ru":"По траектории А.","w":{"uk":"Траєкторія А веде на дальню колію — трамвайну колію зустрічного напрямку, виїжджати на яку заборонено ({p:11.9}).","ru":"Траектория А ведёт на дальние пути — трамвайные пути встречного направления, выезжать на которые запрещено ({p:11.9})."}},{"uk":"По траєкторії Б.","ru":"По траектории Б."},{"uk":"По траєкторії В.","ru":"По траектории В.","w":{"uk":"Траєкторія В — поворот із проїзної частини праворуч від колії, хоча знаків чи розмітки, що встановлюють такий порядок, немає; Правила вимагають повертати з колії попутного напрямку.","ru":"Траектория В — поворот с проезжей части справа от путей, хотя знаков или разметки, устанавливающих такой порядок, нет; Правила требуют поворачивать с путей попутного направления."}}],"c":1,"e":{"uk":"Поворот ліворуч виконують із трамвайної колії попутного напрямку, розташованої на одному рівні з проїзною частиною ({p:11.8}). Траєкторія Б проходить саме по ближній (попутній) колії.","ru":"Поворот налево выполняют с трамвайных путей попутного направления, расположенных на одном уровне с проезжей частью ({p:11.8}). Траектория Б проходит именно по ближним (попутным) путям."},"ref":["11.8","11.9"],"pic":["img/hsc/11-3-1.jpg"]},{"id":"h11-4","t":"h11","num":"11.4","q":{"uk":"Чи дозволено водію у даній ситуації виконати поворот ліворуч із трамвайної колії попутного напрямку?","ru":"Разрешено ли водителю в данной ситуации выполнить поворот налево с трамвайных путей попутного направления?"},"a":[{"uk":"Дозволено, оскільки поворот ліворуч він повинен виконувати з трамвайної колії попутного напрямку.","ru":"Разрешено, поскольку поворот налево он должен выполнять с трамвайных путей попутного направления.","w":{"uk":"Загальне правило з {p:11.8} діє, лише якщо інший порядок не передбачено знаками {s:5.16}, {s:5.18} або розміткою {m:1.18}; тут розмітка визначає поворот із лівої смуги.","ru":"Общее правило из {p:11.8} действует, только если иной порядок не предусмотрен знаками {s:5.16}, {s:5.18} или разметкой {m:1.18}; здесь разметка определяет поворот с левой полосы."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":1,"e":{"uk":"Розмітка {m:1.18} на малюнку показує, що поворот ліворуч дозволений із лівої смуги проїзної частини. Коли інший порядок руху передбачено розміткою {m:1.18}, правило повертати з трамвайної колії не діє ({p:11.8}), тож повертати з колії заборонено.","ru":"Разметка {m:1.18} на рисунке показывает, что поворот налево разрешён с левой полосы проезжей части. Когда иной порядок движения предусмотрен разметкой {m:1.18}, правило поворачивать с трамвайных путей не действует ({p:11.8}), поэтому поворачивать с путей запрещено."},"ref":["11.8"],"pic":["img/hsc/11-4-1.jpg"]},{"id":"h11-5","t":"h11","num":"11.5","q":{"uk":"Чи має право водій у даній ситуації виконати поворот ліворуч із трамвайної колії попутного напрямку?","ru":"Имеет ли право водитель в данной ситуации выполнить поворот налево с трамвайных путей попутного направления?"},"a":[{"uk":"Має, оскільки поворот ліворуч він повинен виконувати з трамвайної колії попутного напрямку.","ru":"Имеет, поскольку поворот налево он должен выполнять с трамвайных путей попутного направления.","w":{"uk":"Знак {s:5.16} встановлює інший порядок руху, тому загальне правило повороту з трамвайної колії тут не застосовується ({p:11.8}).","ru":"Знак {s:5.16} устанавливает иной порядок движения, поэтому общее правило поворота с трамвайных путей здесь не применяется ({p:11.8})."}},{"uk":"Не має права.","ru":"Не имеет права."}],"c":1,"e":{"uk":"Перед перехрестям установлено знак {s:5.16}: поворот ліворуч дозволений лише з лівої смуги проїзної частини, а трамвайна колія на знаку не позначена. За {p:11.8} за наявності цього знака виїжджати на колію перед перехрестям і повертати з неї не можна.","ru":"Перед перекрёстком установлен знак {s:5.16}: поворот налево разрешён только с левой полосы проезжей части, а трамвайные пути на знаке не обозначены. Согласно {p:11.8} при наличии этого знака выезжать на пути перед перекрёстком и поворачивать с них нельзя."},"ref":["11.8"],"pic":["img/hsc/11-5-1.jpg"]},{"id":"h11-6","t":"h11","num":"11.6","q":{"uk":"Чи дозволено водієві рух по трамвайній колії попутного напрямку в даній ситуації?","ru":"Разрешено ли водителю движение по трамвайным путям попутного направления в данной ситуации?"},"a":[{"uk":"Дозволено тільки по попутній трамвайній колії.","ru":"Разрешено только по попутным трамвайным путям.","w":{"uk":"Рух по попутній колії дозволений лише тоді, коли вона розташована на одному рівні з проїзною частиною ({p:11.8}); відокремлена колія для нерейкових транспортних засобів закрита в обох напрямках.","ru":"Движение по попутным путям разрешено только тогда, когда они расположены на одном уровне с проезжей частью ({p:11.8}); обособленные пути для нерельсовых транспортных средств закрыты в обоих направлениях."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":1,"e":{"uk":"Трамвайна колія на малюнку прокладена окремо від проїзної частини — за газонами й тротуаром. За {p:11.9} виїжджати на відокремлені від проїзної частини трамвайні колії заборонено, навіть щоб об'їхати затор, про який попереджає знак {s:1.38}.","ru":"Трамвайные пути на рисунке проложены отдельно от проезжей части — за газонами и тротуаром. Согласно {p:11.9} выезжать на обособленные от проезжей части трамвайные пути запрещено, даже чтобы объехать затор, о котором предупреждает знак {s:1.38}."},"ref":["11.8","11.9"],"pic":["img/hsc/11-6-1.jpg"]},{"id":"h11-7","t":"h11","num":"11.7","q":{"uk":"Чи правильно водій автомобіля рухається по дорозі, яка поділена на смуги лініями дорожньої розмітки?","ru":"Правильно ли водитель автомобиля движется по дороге, которая разделена на полосы линиями дорожной разметки?"},"a":[{"uk":"Правильно, якщо відсутні інші учасники, для руху яких може бути створено перешкоду.","ru":"Правильно, если отсутствуют другие участники, для движения которых может быть создана помеха.","w":{"uk":"Заборона з {p:11.10} не залежить від наявності інших учасників руху.","ru":"Запрет из {p:11.10} не зависит от наличия других участников движения."}},{"uk":"Неправильно: наїжджати на переривчасті лінії розмітки дозволяється лише під час перестроювання.","ru":"Неправильно: наезжать на прерывистые линии разметки разрешается только при перестроении."}],"c":1,"e":{"uk":"Автомобіль на малюнку їде по переривчастій лінії, займаючи одночасно дві смуги. {p:11.10} це забороняє: наїжджати на переривчасті лінії розмітки можна лише під час перестроювання.","ru":"Автомобиль на рисунке едет по прерывистой линии, занимая одновременно две полосы. {p:11.10} это запрещает: наезжать на прерывистые линии разметки можно только при перестроении."},"ref":["11.10"],"pic":["img/hsc/11-7-1.jpg"]},{"id":"h11-8","t":"h11","num":"11.8","q":{"uk":"Як повинен вчинити водій у даній ситуації в разі руху прямо?","ru":"Как должен поступить водитель в данной ситуации при движении прямо?"},"a":[{"uk":"Перестроїтися ліворуч або праворуч.","ru":"Перестроиться влево или вправо.","w":{"uk":"Ліва смуга без потреби (випередження, об'їзду, повороту ліворуч чи розвороту) не відповідає {p:11.2}, тож вибору «ліворуч або праворуч» немає.","ru":"Левая полоса без необходимости (опережения, объезда, поворота налево или разворота) не соответствует {p:11.2}, поэтому выбора «влево или вправо» нет."}},{"uk":"Перестроїтися на праву смугу.","ru":"Перестроиться на правую полосу."},{"uk":"Залишатися там само, якщо не створено перешкоди для інших водіїв.","ru":"Оставаться на месте, если не создана помеха другим водителям.","w":{"uk":"Рух із зайняттям двох смуг заборонений за будь-яких умов ({p:11.10}).","ru":"Движение с занятием двух полос запрещено при любых условиях ({p:11.10})."}},{"uk":"Перестроїтися на ліву смугу.","ru":"Перестроиться на левую полосу.","w":{"uk":"Рухаючись прямо без випередження чи об'їзду, водій має триматися правого краю ({p:11.2}), а не лівої смуги.","ru":"Двигаясь прямо без опережения или объезда, водитель должен держаться правого края ({p:11.2}), а не левой полосы."}}],"c":1,"e":{"uk":"Автомобіль займає одразу дві смуги, що заборонено ({p:11.10}). Оскільки маневрів водій не виконує, за {p:11.2} він повинен рухатися якнайближче до правого краю проїзної частини, тобто перестроїтися на праву смугу.","ru":"Автомобиль занимает сразу две полосы, что запрещено ({p:11.10}). Поскольку манёвров водитель не выполняет, согласно {p:11.2} он должен двигаться как можно ближе к правому краю проезжей части, то есть перестроиться на правую полосу."},"ref":["11.2","11.10"],"pic":["img/hsc/11-8-1.jpg"]},{"id":"h11-9","t":"h11","num":"11.9","q":{"uk":"Чи дозволено водієві білого автомобіля при інтенсивному русі виконати перестроювання?","ru":"Разрешено ли водителю белого автомобиля при интенсивном движении выполнить перестроение?"},"a":[{"uk":"Заборонено змінювати смугу при інтенсивному русі.","ru":"Запрещено менять полосу при интенсивном движении.","w":{"uk":"Повної заборони немає: {p:11.11} дозволяє змінювати смугу для об'їзду перешкоди, повороту, розвороту або зупинки.","ru":"Полного запрета нет: {p:11.11} разрешает менять полосу для объезда препятствия, поворота, разворота или остановки."}},{"uk":"Дозволено для об'їзду перешкоди, повороту або розвороту.","ru":"Разрешено для объезда препятствия, поворота или разворота."}],"c":1,"e":{"uk":"За {p:11.11} при інтенсивному русі змінювати смугу дозволяється лише для об'їзду перешкоди, повороту, розвороту або зупинки. Тож білий автомобіль з увімкненим покажчиком може перестроїтися, якщо робить це з однієї з цих причин.","ru":"Согласно {p:11.11} при интенсивном движении менять полосу разрешается только для объезда препятствия, поворота, разворота или остановки. Поэтому белый автомобиль с включённым указателем может перестроиться, если делает это по одной из этих причин."},"ref":["11.11"],"pic":["img/hsc/11-9-1.jpg"]},{"id":"h11-10","t":"h11","num":"11.10","q":{"uk":"По якій траєкторії водій білого автомобіля може виїжджати на смугу з реверсивним рухом при повороті?","ru":"По какой траектории водитель белого автомобиля может выезжать на полосу с реверсивным движением при повороте?"},"a":[{"uk":"По будь-якій.","ru":"По любой.","w":{"uk":"Траєкторія А не відповідає {p:11.12}: на реверсивну смугу виїжджають лише після реверсивного світлофора.","ru":"Траектория А не соответствует {p:11.12}: на реверсивную полосу выезжают только после реверсивного светофора."}},{"uk":"По А.","ru":"По А.","w":{"uk":"За траєкторією А водій потрапляє на реверсивну смугу, не проїхавши реверсивного світлофора, що заборонено ({p:11.12}).","ru":"По траектории А водитель попадает на реверсивную полосу, не проехав реверсивного светофора, что запрещено ({p:11.12})."}},{"uk":"По Б.","ru":"По Б."}],"c":2,"e":{"uk":"За {p:11.12} водій, який повертає на дорогу зі смугою для реверсивного руху, може перестроїтися на неї лише **після проїзду реверсивного світлофора** з дозвільним сигналом. Траєкторія Б виходить на реверсивну смугу вже за світлофором, а траєкторія А — одразу після повороту, ще до нього.","ru":"Согласно {p:11.12} водитель, поворачивающий на дорогу с полосой для реверсивного движения, может перестроиться на неё только **после проезда реверсивного светофора** с разрешающим сигналом. Траектория Б выходит на реверсивную полосу уже за светофором, а траектория А — сразу после поворота, ещё до него."},"ref":["11.12"],"pic":["img/hsc/11-10-1.jpg"]},{"id":"h11-11","t":"h11","num":"11.11","q":{"uk":"По якій траєкторії велосипедистові дозволено подальший рух?","ru":"По какой траектории велосипедисту разрешено дальнейшее движение?"},"a":[{"uk":"По будь-якій траєкторії.","ru":"По любой траектории.","w":{"uk":"Траєкторія А заборонена: на дорозі з двома смугами в кожному напрямку велосипедист не може перестроюватися для повороту ліворуч чи розвороту.","ru":"Траектория А запрещена: на дороге с двумя полосами в каждом направлении велосипедист не может перестраиваться для поворота налево или разворота."}},{"uk":"По траєкторії А, для повороту ліворуч або для розвороту.","ru":"По траектории А, для поворота налево или для разворота.","w":{"uk":"Поворот ліворуч і розворот велосипедистам дозволені лише на дорогах з однією смугою в кожному напрямку, а тут їх по дві ({p:11.14}).","ru":"Поворот налево и разворот велосипедистам разрешены только на дорогах с одной полосой в каждом направлении, а здесь их по две ({p:11.14})."}},{"uk":"Тільки по траєкторії Б.","ru":"Только по траектории Б."}],"c":2,"e":{"uk":"Велосипедист рухається лише по правій крайній смузі якомога правіше, а повертати ліворуч чи розвертатися може тільки на дорогах з однією смугою для руху в кожному напрямку без трамвайної колії посередині ({p:11.14}). Тут у кожному напрямку по дві смуги, тож дозволена лише траєкторія Б.","ru":"Велосипедист движется только по правой крайней полосе как можно правее, а поворачивать налево или разворачиваться может только на дорогах с одной полосой для движения в каждом направлении без трамвайных путей посередине ({p:11.14}). Здесь в каждом направлении по две полосы, поэтому разрешена только траектория Б."},"ref":["11.14"],"pic":["img/hsc/11-11-1.jpg"]},{"id":"h11-12","t":"h11","num":"11.12","q":{"uk":"На якій із доріг велосипедистам, водіям мопедів, особам, які керують гужовим транспортом, а також вершникам дозволено поворот ліворуч або розворот?","ru":"На какой из дорог велосипедистам, водителям мопедов, лицам, управляющим гужевым транспортом, а также всадникам разрешён поворот налево или разворот?"},"a":[{"uk":"На всіх дорогах.","ru":"На всех дорогах.","w":{"uk":"На дорозі 2 посередині трамвайна колія, а на дорозі 3 по дві смуги в кожному напрямку — там поворот ліворуч і розворот заборонені.","ru":"На дороге 2 посередине трамвайные пути, а на дороге 3 по две полосы в каждом направлении — там поворот налево и разворот запрещены."}},{"uk":"На дорогах 1 і 2.","ru":"На дорогах 1 и 2.","w":{"uk":"На дорозі 2 посередині проходить трамвайна колія, тож поворот ліворуч і розворот там заборонені.","ru":"На дороге 2 посередине проходят трамвайные пути, поэтому поворот налево и разворот там запрещены."}},{"uk":"Тільки на дорозі 1.","ru":"Только на дороге 1."},{"uk":"Тільки на дорозі 3.","ru":"Только на дороге 3.","w":{"uk":"Дорога 3 має по дві смуги в кожному напрямку, а {p:11.14} дозволяє поворот ліворуч лише на дорогах з однією смугою.","ru":"Дорога 3 имеет по две полосы в каждом направлении, а {p:11.14} разрешает поворот налево только на дорогах с одной полосой."}}],"c":2,"e":{"uk":"За {p:11.14} поворот ліворуч і розворот для цих учасників руху дозволені на дорогах з **однією смугою** для руху в кожному напрямку і **без трамвайної колії посередині**. Цим умовам відповідає лише дорога 1.","ru":"Согласно {p:11.14} поворот налево и разворот для этих участников движения разрешены на дорогах с **одной полосой** для движения в каждом направлении и **без трамвайных путей посередине**. Этим условиям соответствует только дорога 1."},"ref":["11.14"],"pic":["img/hsc/11-12-1.jpg"]},{"id":"h11-13","t":"h11","num":"11.13","q":{"uk":"Чи може даний транспортний засіб рухатися по крайній лівій смузі?","ru":"Может ли данное транспортное средство двигаться по крайней левой полосе?"},"a":[{"uk":"Може завжди.","ru":"Может всегда.","w":{"uk":"Транспортний засіб зі швидкістю до 40 км/год повинен триматися правого краю; ліва смуга для нього — лише виняток ({p:11.7}).","ru":"Транспортное средство со скоростью до 40 км/ч должно держаться правого края; левая полоса для него — лишь исключение ({p:11.7})."}},{"uk":"Не може, тому що завжди повинен рухатися якнайближче до правого краю проїзної частини.","ru":"Не может, потому что всегда должно двигаться как можно ближе к правому краю проезжей части.","w":{"uk":"{p:11.7} має винятки: обгін, об'їзд і перестроювання перед поворотом ліворуч чи розворотом.","ru":"{p:11.7} имеет исключения: обгон, объезд и перестроение перед поворотом налево или разворотом."}},{"uk":"Може рухатися у разі перестроювання перед поворотом ліворуч або розворотом.","ru":"Может двигаться в случае перестроения перед поворотом налево или разворотом."}],"c":2,"e":{"uk":"Розпізнавальний знак «40» на тракторі означає, що його швидкість обмежена 40 км/год ({p:30.3}). Такі транспортні засоби за {p:11.7} рухаються якнайближче до правого краю, а ліву смугу можуть зайняти, зокрема, для перестроювання перед поворотом ліворуч чи розворотом — як перед перехрестям на малюнку.","ru":"Опознавательный знак «40» на тракторе означает, что его скорость ограничена 40 км/ч ({p:30.3}). Такие транспортные средства согласно {p:11.7} движутся как можно ближе к правому краю, а левую полосу могут занять, в частности, для перестроения перед поворотом налево или разворотом — как перед перекрёстком на рисунке."},"ref":["11.7"],"pic":["img/hsc/11-13-1.jpg"]},{"id":"h11-14","t":"h11","num":"11.14","q":{"uk":"Який з водіїв правильно зайняв смугу перед зупинкою?","ru":"Какой из водителей правильно занял полосу перед остановкой?"},"a":[{"uk":"Водій, що знаходиться праворуч.","ru":"Водитель, который находится справа.","w":{"uk":"Неповна відповідь: на дорозі з одностороннім рухом у населеному пункті правильно діє й водій, який готується зупинитися біля лівого краю.","ru":"Неполный ответ: на дороге с односторонним движением в населённом пункте правильно действует и водитель, который готовится остановиться у левого края."}},{"uk":"Водій, що знаходиться ліворуч.","ru":"Водитель, который находится слева.","w":{"uk":"Неповна відповідь: водій праворуч, який зупиняється біля правого краю, теж діє правильно.","ru":"Неполный ответ: водитель справа, который останавливается у правого края, тоже действует правильно."}},{"uk":"Обидва водії.","ru":"Оба водителя."}],"c":2,"e":{"uk":"Знаки {s:5.5} позначають дорогу з одностороннім рухом у населеному пункті. На ній можна зупинятися і біля правого, і біля лівого краю ({p:15.3}), а для зупинки зліва {p:11.5} дозволяє виїжджати на крайню ліву смугу. Тож і білий автомобіль ліворуч, і синій праворуч зайняли смуги правильно.","ru":"Знаки {s:5.5} обозначают дорогу с односторонним движением в населённом пункте. На ней можно останавливаться и у правого, и у левого края ({p:15.3}), а для остановки слева {p:11.5} разрешает выезжать на крайнюю левую полосу. Поэтому и белый автомобиль слева, и синий справа заняли полосы правильно."},"ref":["11.5","15.3"],"pic":["img/hsc/11-14-1.jpg"]},{"id":"h11-15","t":"h11","num":"11.15","q":{"uk":"На якому з малюнків показана дорога, на якій дозволено виїжджати на призначений для зустрічного руху бік дороги?","ru":"На каком из рисунков показана дорога, на которой разрешено выезжать на предназначенную для встречного движения сторону дороги?"},"a":[{"uk":"На малюнку 1.","ru":"На рисунке 1."},{"uk":"На малюнку 2.","ru":"На рисунке 2.","w":{"uk":"На малюнку 2 в попутному напрямку дві смуги, а зустрічний бік відокремлено суцільною лінією, — виїзд заборонено ({p:11.4}).","ru":"На рисунке 2 в попутном направлении две полосы, а встречная сторона отделена сплошной линией, — выезд запрещён ({p:11.4})."}},{"uk":"На малюнку 3.","ru":"На рисунке 3.","w":{"uk":"На малюнку 3 по дві смуги в кожному напрямку, розділені подвійною суцільною лінією {m:1.3}, — виїзд на зустрічний бік заборонено ({p:11.4}).","ru":"На рисунке 3 по две полосы в каждом направлении, разделённые двойной сплошной линией {m:1.3}, — выезд на встречную сторону запрещён ({p:11.4})."}},{"uk":"На малюнках 1, 2 і 3.","ru":"На рисунках 1, 2 и 3.","w":{"uk":"Лише дорога на малюнку 1 має по одній смузі в кожному напрямку без суцільної лінії; на двох інших виїзд заборонено.","ru":"Только дорога на рисунке 1 имеет по одной полосе в каждом направлении без сплошной линии; на двух других выезд запрещён."}}],"c":0,"e":{"uk":"На малюнку 1 — дорога з однією смугою в кожному напрямку, розділена переривчастою лінією: за {p:11.3} виїзд на зустрічну смугу тут можливий (для обгону, об'їзду перешкоди тощо). На дорогах із двома й більше смугами в одному напрямку виїжджати на зустрічний бік заборонено ({p:11.4}).","ru":"На рисунке 1 — дорога с одной полосой в каждом направлении, разделённая прерывистой линией: согласно {p:11.3} выезд на встречную полосу здесь возможен (для обгона, объезда препятствия и т. п.). На дорогах с двумя и более полосами в одном направлении выезжать на встречную сторону запрещено ({p:11.4})."},"ref":["11.3","11.4"],"pic":["img/hsc/11-15-1.jpg"]},{"id":"h11-16","t":"h11","num":"11.16","q":{"uk":"Чи дозволено водієві жовтого автомобіля виїхати на смугу зустрічного руху?","ru":"Разрешено ли водителю жёлтого автомобиля выехать на полосу встречного движения?"},"a":[{"uk":"Дозволено для виконання обгону, в разі якщо транспортний засіб рухається зі швидкістю менш ніж 30 км/год.","ru":"Разрешено для выполнения обгона, если транспортное средство движется со скоростью менее 30 км/ч.","w":{"uk":"Виняток для транспортних засобів, що рухаються зі швидкістю менше 30 км/год, стосується знака {s:3.25}, а не заборони з {p:11.4}: тут виїзд на зустрічний бік заборонений незалежно від швидкості.","ru":"Исключение для транспортных средств, движущихся со скоростью менее 30 км/ч, относится к знаку {s:3.25}, а не к запрету из {p:11.4}: здесь выезд на встречную сторону запрещён независимо от скорости."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":1,"e":{"uk":"У напрямку руху жовтого автомобіля дві смуги, а зустрічну смугу відокремлює суцільна лінія {m:1.1}. На дорогах із щонайменше двома смугами в одному напрямку виїжджати на зустрічний бік заборонено ({p:11.4}).","ru":"В направлении движения жёлтого автомобиля две полосы, а встречную полосу отделяет сплошная линия {m:1.1}. На дорогах с не менее чем двумя полосами в одном направлении выезжать на встречную сторону запрещено ({p:11.4})."},"ref":["11.4"],"pic":["img/hsc/11-16-1.jpg"]},{"id":"h11-17","t":"h11","num":"11.17","q":{"uk":"За яких умов водієві легкового автомобіля дозволено рух по крайній лівій смузі на дорозі з розділювальною смугою?","ru":"При каких условиях водителю легкового автомобиля разрешено движение по крайней левой полосе на дороге с разделительной полосой?"},"a":[{"uk":"Для повороту ліворуч або розвороту.","ru":"Для поворота налево или разворота."},{"uk":"Для зупинки біля розділювальної смуги тільки в населеному пункті.","ru":"Для остановки у разделительной полосы только в населённом пункте.","w":{"uk":"Якщо дорога має розділювальну смугу, зупинка і стоянка біля неї заборонені ({p:15.3}) — і в населеному пункті теж.","ru":"Если дорога имеет разделительную полосу, остановка и стоянка у неё запрещены ({p:15.3}) — и в населённом пункте тоже."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2.","w":{"uk":"Варіант 2 помилковий: зупинятися біля розділювальної смуги заборонено ({p:15.3}).","ru":"Вариант 2 ошибочен: останавливаться у разделительной полосы запрещено ({p:15.3})."}}],"c":0,"e":{"uk":"За {p:11.5} на дорогах із двома й більше смугами в одному напрямку виїзд на крайню ліву смугу дозволений для повороту ліворуч або розвороту (а також коли праві смуги зайняті). Із запропонованих варіантів правильний лише перший.","ru":"Согласно {p:11.5} на дорогах с двумя и более полосами в одном направлении выезд на крайнюю левую полосу разрешён для поворота налево или разворота (а также когда правые полосы заняты). Из предложенных вариантов верен только первый."},"ref":["11.5","15.3"],"pic":["img/hsc/11-17-1.jpg"]},{"id":"h11-18","t":"h11","num":"11.18","q":{"uk":"Чи дозволено транспортному засобу, швидкість руху якого з технічних причин не перевищує 40 км/год., рухатися по крайній лівій смузі?","ru":"Разрешено ли транспортному средству, скорость движения которого по техническим причинам не превышает 40 км/ч, двигаться по крайней левой полосе?"},"a":[{"uk":"Заборонено, транспортний засіб завжди має рухатися якнайближче до правого краю проїзної частини.","ru":"Запрещено, транспортное средство всегда должно двигаться как можно ближе к правому краю проезжей части.","w":{"uk":"Абсолютної заборони немає: {p:11.7} допускає обгін, об'їзд і перестроювання перед поворотом ліворуч чи розворотом.","ru":"Абсолютного запрета нет: {p:11.7} допускает обгон, объезд и перестроение перед поворотом налево или разворотом."}},{"uk":"Дозволено для виконання об'їзду або перестроювання перед поворотом ліворуч чи розворотом.","ru":"Разрешено для выполнения объезда или перестроения перед поворотом налево или разворотом."},{"uk":"Дозволено, якщо інші смуги зайняті.","ru":"Разрешено, если другие полосы заняты.","w":{"uk":"Дозвіл виїжджати ліворуч, коли праві смуги зайняті, стосується інших транспортних засобів ({p:11.5}); для тихохідних {p:11.7} такого винятку не містить.","ru":"Разрешение выезжать влево, когда правые полосы заняты, касается других транспортных средств ({p:11.5}); для тихоходных {p:11.7} такого исключения не содержит."}}],"c":1,"e":{"uk":"{p:11.7} зобов'язує такі транспортні засоби рухатися якнайближче до правого краю, крім випадків обгону, об'їзду або перестроювання перед поворотом ліворуч чи розворотом.","ru":"{p:11.7} обязывает такие транспортные средства двигаться как можно ближе к правому краю, кроме случаев обгона, объезда или перестроения перед поворотом налево или разворотом."},"ref":["11.7"]},{"id":"h11-19","t":"h11","num":"11.19","q":{"uk":"Чи може водій транспортного засобу в'їжджати на смугу, призначену для зустрічного руху, для зупинки або стоянки біля лівого краю проїзної частини?","ru":"Может ли водитель транспортного средства выезжать на полосу, предназначенную для встречного движения, для остановки или стоянки у левого края проезжей части?"},"a":[{"uk":"Не може, тому що зупинка і стоянка дозволені тільки біля правого краю проїзної частини.","ru":"Не может, потому что остановка и стоянка разрешены только у правого края проезжей части.","w":{"uk":"У населених пунктах {p:15.3} за певних умов дозволяє зупинку й стоянку і на лівому боці дороги.","ru":"В населённых пунктах {p:15.3} при определённых условиях разрешает остановку и стоянку и на левой стороне дороги."}},{"uk":"Може виїжджати на всіх дорогах із двостороннім рухом, які мають по одній смузі для руху в кожному напрямку, за відсутності суцільної лінії дорожньої розмітки чи відповідних дорожніх знаків.","ru":"Может выезжать на всех дорогах с двусторонним движением, имеющих по одной полосе для движения в каждом направлении, при отсутствии сплошной линии дорожной разметки или соответствующих дорожных знаков.","w":{"uk":"Поза населеними пунктами зупинятися біля лівого краю не можна: {p:11.3} дозволяє такий виїзд лише в населених пунктах.","ru":"Вне населённых пунктов останавливаться у левого края нельзя: {p:11.3} разрешает такой выезд только в населённых пунктах."}},{"uk":"Може виїжджати тільки в населених пунктах, на дорогах із двостороннім рухом, які мають по одній смузі для руху в кожному напрямку, за відсутності суцільної лінії дорожньої розмітки чи відповідних дорожніх знаків, та трамвайних колій.","ru":"Может выезжать только в населённых пунктах, на дорогах с двусторонним движением, имеющих по одной полосе для движения в каждом направлении, при отсутствии сплошной линии дорожной разметки или соответствующих дорожных знаков, а также трамвайных путей."}],"c":2,"e":{"uk":"{p:11.3} допускає виїзд на зустрічну смугу для зупинки чи стоянки біля лівого краю лише **в населених пунктах** у дозволених випадках, а {p:15.3} уточнює: на дорозі з однією смугою в кожному напрямку, без трамвайної колії посередині й без суцільної лінії {m:1.1}.","ru":"{p:11.3} допускает выезд на встречную полосу для остановки или стоянки у левого края только **в населённых пунктах** в разрешённых случаях, а {p:15.3} уточняет: на дороге с одной полосой в каждом направлении, без трамвайных путей посередине и без сплошной линии {m:1.1}."},"ref":["11.3","15.3"]},{"id":"h11-20","t":"h11","num":"11.20","q":{"uk":"У яких випадках водієві при інтенсивному русі дозволено змінювати смугу?","ru":"В каких случаях водителю при интенсивном движении разрешено менять полосу?"},"a":[{"uk":"Для об'їзду перешкоди.","ru":"Для объезда препятствия.","w":{"uk":"Неповна відповідь: смугу можна змінити також для повороту, розвороту або зупинки.","ru":"Неполный ответ: полосу можно сменить также для поворота, разворота или остановки."}},{"uk":"Для повороту або розвороту.","ru":"Для поворота или разворота.","w":{"uk":"Неповна відповідь: смугу можна змінити також для об'їзду перешкоди або зупинки.","ru":"Неполный ответ: полосу можно сменить также для объезда препятствия или остановки."}},{"uk":"Для зупинки.","ru":"Для остановки.","w":{"uk":"Неповна відповідь: смугу можна змінити також для об'їзду перешкоди, повороту або розвороту.","ru":"Неполный ответ: полосу можно сменить также для объезда препятствия, поворота или разворота."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2.","w":{"uk":"Неповна відповідь: зміна смуги дозволена й для зупинки.","ru":"Неполный ответ: смена полосы разрешена и для остановки."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3."}],"c":4,"e":{"uk":"За {p:11.11} при інтенсивному русі змінювати смугу дозволяється лише для об'їзду перешкоди, повороту, розвороту **або зупинки** — тож правильні всі три варіанти.","ru":"Согласно {p:11.11} при интенсивном движении менять полосу разрешается только для объезда препятствия, поворота, разворота **или остановки** — поэтому верны все три варианта."},"ref":["11.11"]},{"id":"h11-21","t":"h11","num":"11.21","q":{"uk":"Як повинні рухатися водії нерейкових транспортних засобів на дорогах із двома смугами й більше для руху в кожному напрямку?","ru":"Как должны двигаться водители нерельсовых транспортных средств на дорогах с двумя и более полосами для движения в каждом направлении?"},"a":[{"uk":"Повинні рухатися в будь-якій смузі незалежно від інтенсивності руху.","ru":"Должны двигаться по любой полосе независимо от интенсивности движения.","w":{"uk":"Довільний вибір смуги суперечить {p:11.2}: без потреби треба триматися правого краю.","ru":"Произвольный выбор полосы противоречит {p:11.2}: без необходимости нужно держаться правого края."}},{"uk":"Повинні вибирати смугу для руху залежно від інтенсивності руху.","ru":"Должны выбирать полосу для движения в зависимости от интенсивности движения.","w":{"uk":"Правила прив'язують вибір смуги не до інтенсивності руху, а до маневру, який виконує водій ({p:11.2}, {p:11.5}).","ru":"Правила привязывают выбор полосы не к интенсивности движения, а к манёвру, который выполняет водитель ({p:11.2}, {p:11.5})."}},{"uk":"Повинні рухатися якнайближче до правого краю проїзної частини.","ru":"Должны двигаться как можно ближе к правому краю проезжей части.","w":{"uk":"Неповна відповідь: {p:11.2} має винятки — випередження, об'їзд, перестроювання перед поворотом ліворуч чи розворотом.","ru":"Неполный ответ: {p:11.2} имеет исключения — опережение, объезд, перестроение перед поворотом налево или разворотом."}},{"uk":"Повинні рухатися якнайближче до правого краю проїзної частини, крім випадків, коли виконуються випередження, об'їзд або перестроювання перед поворотом ліворуч чи розворотом.","ru":"Должны двигаться как можно ближе к правому краю проезжей части, кроме случаев, когда выполняются опережение, объезд или перестроение перед поворотом налево или разворотом."}],"c":3,"e":{"uk":"Це вимога {p:11.2}: рухатися якнайближче до правого краю проїзної частини, крім випередження, об'їзду або перестроювання перед поворотом ліворуч чи розворотом.","ru":"Это требование {p:11.2}: двигаться как можно ближе к правому краю проезжей части, кроме опережения, объезда или перестроения перед поворотом налево или разворотом."},"ref":["11.2"]},{"id":"h11-22","t":"h11","num":"11.22","q":{"uk":"У яких випадках водій нерейкового транспортного засобу може рухатися, не тримаючись ближче до правого краю проїзної частини на дорогах, що мають по дві й більше смуг для руху в кожному напрямку?","ru":"В каких случаях водитель нерельсового транспортного средства может двигаться, не держась ближе к правому краю проезжей части, на дорогах, имеющих по две и более полосы для движения в каждом направлении?"},"a":[{"uk":"У разі виконання об'їзду.","ru":"При выполнении объезда.","w":{"uk":"Неповна відповідь: виняток діє також для випередження і перестроювання перед поворотом ліворуч чи розворотом.","ru":"Неполный ответ: исключение действует также для опережения и перестроения перед поворотом налево или разворотом."}},{"uk":"У разі виконання випередження.","ru":"При выполнении опережения.","w":{"uk":"Неповна відповідь: виняток діє також для об'їзду і перестроювання перед поворотом ліворуч чи розворотом.","ru":"Неполный ответ: исключение действует также для объезда и перестроения перед поворотом налево или разворотом."}},{"uk":"У разі перестроювання перед поворотом ліворуч чи розворотом.","ru":"При перестроении перед поворотом налево или разворотом.","w":{"uk":"Неповна відповідь: виняток діє також для випередження й об'їзду.","ru":"Неполный ответ: исключение действует также для опережения и объезда."}},{"uk":"Відповіді 2 і 3.","ru":"Ответы 2 и 3.","w":{"uk":"Неповна відповідь: пропущено об'їзд, який {p:11.2} теж називає.","ru":"Неполный ответ: пропущен объезд, который {p:11.2} тоже называет."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3."}],"c":4,"e":{"uk":"{p:11.2} називає саме три винятки з обов'язку триматися правого краю: випередження, об'їзд і перестроювання перед поворотом ліворуч чи розворотом.","ru":"{p:11.2} называет именно три исключения из обязанности держаться правого края: опережение, объезд и перестроение перед поворотом налево или разворотом."},"ref":["11.2"]},{"id":"h11-23","t":"h11","num":"11.23","q":{"uk":"У яких випадках транспортним засобам дозволено рух по тротуарах і пішохідних доріжках?","ru":"В каких случаях транспортным средствам разрешено движение по тротуарам и пешеходным дорожкам?"},"a":[{"uk":"Завжди для виконання робіт або обслуговування торговельних та інших підприємств, розташованих безпосередньо біля цих тротуарів або доріжок, і за умови надання переваги пішоходам.","ru":"Всегда для выполнения работ или обслуживания торговых и других предприятий, расположенных непосредственно у этих тротуаров или дорожек, и при условии предоставления преимущества пешеходам.","w":{"uk":"Слово «завжди» тут хибне: такий рух можливий лише тоді, коли інших під'їздів немає.","ru":"Слово «всегда» здесь неверно: такое движение возможно только тогда, когда других подъездов нет."}},{"uk":"Для виконання робіт або обслуговування торговельних та інших підприємств, розташованих безпосередньо біля цих тротуарів або доріжок, за відсутності інших під'їздів і за умови надання переваги пішоходам.","ru":"Для выполнения работ или обслуживания торговых и других предприятий, расположенных непосредственно у этих тротуаров или дорожек, при отсутствии других подъездов и при условии предоставления преимущества пешеходам."},{"uk":"Рух транспортних засобів по тротуарах і пішохідних доріжках заборонено в будь-якому разі.","ru":"Движение транспортных средств по тротуарам и пешеходным дорожкам запрещено в любом случае.","w":{"uk":"Повної заборони немає: {p:11.13} передбачає винятки для виконання робіт і обслуговування підприємств.","ru":"Полного запрета нет: {p:11.13} предусматривает исключения для выполнения работ и обслуживания предприятий."}}],"c":1,"e":{"uk":"{p:11.13} забороняє рух тротуарами й пішохідними доріжками, крім випадків, коли транспортні засоби виконують роботи або обслуговують підприємства біля них **за відсутності інших під'їздів** і з дотриманням вимог {p:26.1}–{p:26.3} (зокрема, пішоходи мають перевагу).","ru":"{p:11.13} запрещает движение по тротуарам и пешеходным дорожкам, кроме случаев, когда транспортные средства выполняют работы или обслуживают предприятия у них **при отсутствии других подъездов** и с соблюдением требований {p:26.1}–{p:26.3} (в частности, пешеходы имеют преимущество)."},"ref":["11.13","26.1"]},{"id":"h11-24","t":"h11","num":"11.24","q":{"uk":"За яких умов транспортним засобам дозволено рух по тротуарах і пішохідних доріжках для виконання робіт або обслуговування торговельних та інших підприємств, розташованих безпосередньо біля цих тротуарів або доріжок?","ru":"При каких условиях транспортным средствам разрешено движение по тротуарам и пешеходным дорожкам для выполнения работ или обслуживания торговых и других предприятий, расположенных непосредственно у этих тротуаров или дорожек?"},"a":[{"uk":"Завжди.","ru":"Всегда.","w":{"uk":"Такий рух дозволений не завжди, а лише за відсутності інших під'їздів і з наданням переваги пішоходам.","ru":"Такое движение разрешено не всегда, а только при отсутствии других подъездов и с предоставлением преимущества пешеходам."}},{"uk":"У разі надання пішоходам переваги в русі.","ru":"При предоставлении пешеходам преимущества в движении.","w":{"uk":"Неповна відповідь: потрібна ще й відсутність інших під'їздів.","ru":"Неполный ответ: нужно ещё и отсутствие других подъездов."}},{"uk":"За відсутності інших під'їздів і за умови надання переваги пішоходам.","ru":"При отсутствии других подъездов и при условии предоставления преимущества пешеходам."}],"c":2,"e":{"uk":"{p:11.13} ставить дві умови: інших під'їздів немає, і виконуються вимоги {p:26.1}–{p:26.3}, тобто пішоходи мають перевагу.","ru":"{p:11.13} ставит два условия: других подъездов нет, и выполняются требования {p:26.1}–{p:26.3}, то есть пешеходы имеют преимущество."},"ref":["11.13","26.1"]},{"id":"h11-25","t":"h11","num":"11.25","q":{"uk":"Як повинні рухатися по проїзній частині велосипедисти, водії мопедів, особи, які керують гужовим транспортом, а також вершники?","ru":"Как должны двигаться по проезжей части велосипедисты, водители мопедов, лица, управляющие гужевым транспортом, а также всадники?"},"a":[{"uk":"По будь-якій смузі.","ru":"По любой полосе.","w":{"uk":"Ці учасники руху повинні триматися правої крайньої смуги якомога правіше ({p:11.14}).","ru":"Эти участники движения должны держаться правой крайней полосы как можно правее ({p:11.14})."}},{"uk":"Тільки в один ряд по правій крайній смузі, якомога правіше, за винятком випадків, коли виконується об'їзд.","ru":"Только в один ряд по правой крайней полосе, как можно правее, за исключением случаев, когда выполняется объезд.","w":{"uk":"Неповна відповідь: не враховано дозволу повертати ліворуч і розвертатися на дорогах з однією смугою в кожному напрямку.","ru":"Неполный ответ: не учтено разрешение поворачивать налево и разворачиваться на дорогах с одной полосой в каждом направлении."}},{"uk":"Тільки в один ряд по правій крайній смузі, якомога правіше, за винятком випадків повороту ліворуч і розвороту.","ru":"Только в один ряд по правой крайней полосе, как можно правее, за исключением случаев поворота налево и разворота.","w":{"uk":"Поворот ліворуч і розворот дозволені не скрізь, а лише на дорогах з однією смугою в кожному напрямку без трамвайної колії посередині.","ru":"Поворот налево и разворот разрешены не везде, а только на дорогах с одной полосой в каждом направлении без трамвайных путей посередине."}},{"uk":"Тільки в один ряд по правій крайній смузі, якомога правіше, за винятком випадків повороту ліворуч і розвороту на дорогах з однією смугою для руху в кожному напрямку і без трамвайної колії посередині.","ru":"Только в один ряд по правой крайней полосе, как можно правее, за исключением случаев поворота налево и разворота на дорогах с одной полосой для движения в каждом направлении и без трамвайных путей посередине.","w":{"uk":"Неповна відповідь: від руху по правій крайній смузі можна відступити й для об'їзду.","ru":"Неполный ответ: от движения по правой крайней полосе можно отступить и для объезда."}},{"uk":"Відповіді 2 і 4.","ru":"Ответы 2 и 4."}],"c":4,"e":{"uk":"{p:11.14} містить обидва положення: рух в один ряд по правій крайній смузі якомога правіше (крім об'їзду) і дозвіл повертати ліворуч та розвертатися лише на дорогах з однією смугою в кожному напрямку без трамвайної колії посередині.","ru":"{p:11.14} содержит оба положения: движение в один ряд по правой крайней полосе как можно правее (кроме объезда) и разрешение поворачивать налево и разворачиваться только на дорогах с одной полосой в каждом направлении без трамвайных путей посередине."},"ref":["11.14"]},{"id":"h11-26","t":"h11","num":"11.26","q":{"uk":"Як має рухатися нерейковий транспортний засіб на дорозі, яка має по дві й більше смуг для руху в кожному напрямку, вільній від інших транспортних засобів, якщо немає необхідності виконувати маневри?","ru":"Как должно двигаться нерельсовое транспортное средство на дороге, имеющей по две и более полосы для движения в каждом направлении, свободной от других транспортных средств, если нет необходимости выполнять манёвры?"},"a":[{"uk":"Якнайближче до правого краю проїзної частини.","ru":"Как можно ближе к правому краю проезжей части."},{"uk":"У будь-якій смузі – на розсуд водія.","ru":"По любой полосе — на усмотрение водителя.","w":{"uk":"Вибір смуги «на розсуд» суперечить {p:11.2}: вільна дорога не скасовує вимоги триматися правого краю.","ru":"Выбор полосы «на усмотрение» противоречит {p:11.2}: свободная дорога не отменяет требования держаться правого края."}}],"c":0,"e":{"uk":"За {p:11.2} без випередження, об'їзду чи перестроювання перед поворотом ліворуч або розворотом треба рухатися якнайближче до правого краю проїзної частини — навіть на вільній дорозі.","ru":"Согласно {p:11.2} без опережения, объезда или перестроения перед поворотом налево или разворотом нужно двигаться как можно ближе к правому краю проезжей части — даже на свободной дороге."},"ref":["11.2"]},{"id":"h11-27","t":"h11","num":"11.27","q":{"uk":"Що повинен враховувати водій нерейкового транспортного засобу для визначення кількості смуг за відсутності дорожньої розмітки та дорожніх знаків «Напрямки руху по смугах» і «Напрямки руху по смузі»?","ru":"Что должен учитывать водитель нерельсового транспортного средства для определения количества полос при отсутствии дорожной разметки и дорожных знаков «Направления движения по полосам» и «Направления движения по полосе»?"},"a":[{"uk":"Повинен враховувати ширину проїзної частини відповідного напрямку руху, габарити транспортного засобу, дотримуючись при цьому безпечних інтервалів.","ru":"Должен учитывать ширину проезжей части соответствующего направления движения, габариты транспортного средства, соблюдая при этом безопасные интервалы."},{"uk":"Тільки ширину проїзної частини.","ru":"Только ширину проезжей части.","w":{"uk":"Неповна відповідь: ураховують також габарити транспортних засобів і безпечні інтервали між ними.","ru":"Неполный ответ: учитывают также габариты транспортных средств и безопасные интервалы между ними."}},{"uk":"Тільки габарити транспортних засобів.","ru":"Только габариты транспортных средств.","w":{"uk":"Неповна відповідь: ураховують також ширину проїзної частини й безпечні інтервали.","ru":"Неполный ответ: учитывают также ширину проезжей части и безопасные интервалы."}}],"c":0,"e":{"uk":"За {p:11.1} за відсутності розмітки і знаків {s:5.16}, {s:5.17.1}, {s:5.17.2} кількість смуг визначають самі водії з урахуванням ширини проїзної частини відповідного напрямку, габаритів транспортних засобів і безпечних інтервалів між ними.","ru":"Согласно {p:11.1} при отсутствии разметки и знаков {s:5.16}, {s:5.17.1}, {s:5.17.2} количество полос определяют сами водители с учётом ширины проезжей части соответствующего направления, габаритов транспортных средств и безопасных интервалов между ними."},"ref":["11.1"]},{"id":"h11-28","t":"h11","num":"11.28","q":{"uk":"Якщо дорога поділена на смуги руху лініями дорожньої розмітки, чи завжди водій повинен рухатися точно по смузі для руху?","ru":"Если дорога разделена на полосы движения линиями дорожной разметки, всегда ли водитель должен двигаться точно по полосе?"},"a":[{"uk":"Повинен завжди.","ru":"Должен всегда.","w":{"uk":"Під час перестроювання водій неминуче перетинає переривчасту лінію — {p:11.10} це прямо дозволяє.","ru":"При перестроении водитель неизбежно пересекает прерывистую линию — {p:11.10} это прямо разрешает."}},{"uk":"Повинен, крім випадків перестроювання.","ru":"Должен, кроме случаев перестроения."}],"c":1,"e":{"uk":"За {p:11.10} рухатися, займаючи одночасно дві смуги, заборонено, а наїжджати на переривчасті лінії розмітки можна лише під час перестроювання.","ru":"Согласно {p:11.10} двигаться, занимая одновременно две полосы, запрещено, а наезжать на прерывистые линии разметки можно только при перестроении."},"ref":["11.10"]},{"id":"h11-29","t":"h11","num":"11.29","q":{"uk":"У яких випадках заборонено виїжджати на призначений для зустрічного руху бік дороги?","ru":"В каких случаях запрещено выезжать на предназначенную для встречного движения сторону дороги?"},"a":[{"uk":"Якщо дорога має щонайменше дві смуги для руху в одному напрямку.","ru":"Если дорога имеет не менее двух полос для движения в одном направлении."},{"uk":"Якщо дорога з двостороннім рухом розділена переривчастою лінією дорожньої розмітки.","ru":"Если дорога с двусторонним движением разделена прерывистой линией дорожной разметки.","w":{"uk":"Переривчаста лінія сама по собі виїзду не забороняє: на дорозі з однією смугою в кожному напрямку його допускає {p:11.3} (для обгону, об'їзду тощо).","ru":"Прерывистая линия сама по себе выезд не запрещает: на дороге с одной полосой в каждом направлении его допускает {p:11.3} (для обгона, объезда и т. п.)."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2.","w":{"uk":"Варіант 2 помилковий: через переривчасту лінію можна виїхати на зустрічну смугу у випадках, передбачених {p:11.3}.","ru":"Вариант 2 ошибочен: через прерывистую линию можно выехать на встречную полосу в случаях, предусмотренных {p:11.3}."}}],"c":0,"e":{"uk":"За {p:11.4} на дорогах із двостороннім рухом, які мають щонайменше дві смуги для руху в одному напрямку, виїжджати на зустрічний бік заборонено.","ru":"Согласно {p:11.4} на дорогах с двусторонним движением, имеющих не менее двух полос для движения в одном направлении, выезжать на встречную сторону запрещено."},"ref":["11.3","11.4"]},{"id":"h11-30","t":"h11","num":"11.30","q":{"uk":"Чи дозволено водієві виконати випередження, виїхавши на розділювальну смугу, яка відокремлена суцільними лініями дорожньої розмітки?","ru":"Разрешено ли водителю выполнить опережение, выехав на разделительную полосу, отделённую сплошными линиями дорожной разметки?"},"a":[{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"Розділювальна смуга не призначена для руху, і {p:11.9} прямо забороняє на неї виїжджати — для випередження теж.","ru":"Разделительная полоса не предназначена для движения, и {p:11.9} прямо запрещает на неё выезжать — для опережения тоже."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":1,"e":{"uk":"{p:11.9} забороняє виїжджати на розділювальну смугу, а суцільні лінії, що її відокремлюють, перетинати теж не можна. Тож випереджати по ній заборонено.","ru":"{p:11.9} запрещает выезжать на разделительную полосу, а сплошные линии, которые её отделяют, пересекать тоже нельзя. Поэтому опережать по ней запрещено."},"ref":["1.10","11.9"]},{"id":"h11-31","t":"h11","num":"11.31","q":{"uk":"Як повинен рухатися транспортний засіб, швидкість руху якого не повинна перевищувати 40 км/год. або який з технічних причин не може розвивати таку швидкість?","ru":"Как должно двигаться транспортное средство, скорость движения которого не должна превышать 40 км/ч или которое по техническим причинам не может развивать такую скорость?"},"a":[{"uk":"Повинен рухатися якнайближче до правого краю проїзної частини, крім випадків, коли виконується об'їзд або обгін.","ru":"Должно двигаться как можно ближе к правому краю проезжей части, кроме случаев, когда выполняется объезд или обгон.","w":{"uk":"Неповна відповідь: виняток діє й для перестроювання перед поворотом ліворуч чи розворотом.","ru":"Неполный ответ: исключение действует и для перестроения перед поворотом налево или разворотом."}},{"uk":"Повинен рухатися якнайближче до правого краю проїзної частини, крім випадків, коли виконується перестроювання перед поворотом ліворуч чи розворотом.","ru":"Должно двигаться как можно ближе к правому краю проезжей части, кроме случаев, когда выполняется перестроение перед поворотом налево или разворотом.","w":{"uk":"Неповна відповідь: виняток діє й для обгону та об'їзду.","ru":"Неполный ответ: исключение действует и для обгона и объезда."}},{"uk":"Може рухатися в будь-якій смузі.","ru":"Может двигаться по любой полосе.","w":{"uk":"Довільний вибір смуги суперечить {p:11.7}: тихохідний транспортний засіб повинен триматися правого краю.","ru":"Произвольный выбор полосы противоречит {p:11.7}: тихоходное транспортное средство должно держаться правого края."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2."}],"c":3,"e":{"uk":"За {p:11.7} такі транспортні засоби рухаються якнайближче до правого краю, крім обгону, об'їзду або перестроювання перед поворотом ліворуч чи розворотом, — тобто варіанти 1 і 2 разом передають цей пункт.","ru":"Согласно {p:11.7} такие транспортные средства движутся как можно ближе к правому краю, кроме обгона, объезда или перестроения перед поворотом налево или разворотом, — то есть варианты 1 и 2 вместе передают этот пункт."},"ref":["11.7"]},{"id":"h11-32","t":"h11","num":"11.32","q":{"uk":"За яких умов водієві легкового автомобіля дозволено виїжджати на крайню ліву смугу на дорозі з розділювальною смугою?","ru":"При каких условиях водителю легкового автомобиля разрешено выезжать на крайнюю левую полосу на дороге с разделительной полосой?"},"a":[{"uk":"Якщо праві смуги зайняті.","ru":"Если правые полосы заняты.","w":{"uk":"Неповна відповідь: на ліву смугу можна виїхати також для повороту ліворуч або розвороту.","ru":"Неполный ответ: на левую полосу можно выехать также для поворота налево или разворота."}},{"uk":"Для повороту ліворуч або розвороту.","ru":"Для поворота налево или разворота.","w":{"uk":"Неповна відповідь: на ліву смугу можна виїхати також тоді, коли праві смуги зайняті.","ru":"Неполный ответ: на левую полосу можно выехать также тогда, когда правые полосы заняты."}},{"uk":"Для зупинки або стоянки з лівого боку в населених пунктах.","ru":"Для остановки или стоянки с левой стороны в населённых пунктах.","w":{"uk":"Дорога з розділювальною смугою не є дорогою з одностороннім рухом, а зупинка й стоянка біля розділювальної смуги заборонені ({p:15.3}).","ru":"Дорога с разделительной полосой не является дорогой с односторонним движением, а остановка и стоянка у разделительной полосы запрещены ({p:15.3})."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3.","w":{"uk":"Варіант 3 помилковий: зупинятися біля розділювальної смуги заборонено.","ru":"Вариант 3 ошибочен: останавливаться у разделительной полосы запрещено."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2."}],"c":4,"e":{"uk":"{p:11.5} дозволяє виїзд на крайню ліву смугу, якщо праві зайняті, а також для повороту ліворуч чи розвороту. Зупинятися ліворуч можна лише на дорогах з одностороннім рухом, а біля розділювальної смуги зупинка заборонена ({p:15.3}).","ru":"{p:11.5} разрешает выезд на крайнюю левую полосу, если правые заняты, а также для поворота налево или разворота. Останавливаться слева можно только на дорогах с односторонним движением, а у разделительной полосы остановка запрещена ({p:15.3})."},"ref":["11.5","15.3"]},{"id":"h11-33","t":"h11","num":"11.33","q":{"uk":"Коли нерейковим транспортним засобам дозволено рух по трамвайній колії попутного напрямку, розташованій на одному рівні з проїзною частиною?","ru":"Когда нерельсовым транспортным средствам разрешено движение по трамвайным путям попутного направления, расположенным на одном уровне с проезжей частью?"},"a":[{"uk":"Завжди під час випередження або перед поворотом ліворуч, а також перед розворотом.","ru":"Всегда при опережении или перед поворотом налево, а также перед разворотом.","w":{"uk":"Слово «завжди» хибне: знаки чи розмітка можуть забороняти виїзд на колію, а за знаків {s:5.16}, {s:5.18} чи розмітки {m:1.18} поворот виконують не з колії ({p:11.8}).","ru":"Слово «всегда» неверно: знаки или разметка могут запрещать выезд на пути, а при знаках {s:5.16}, {s:5.18} или разметке {m:1.18} поворот выполняют не с путей ({p:11.8})."}},{"uk":"Завжди для виконання об'їзду.","ru":"Всегда для выполнения объезда.","w":{"uk":"Для об'їзду на колію виїжджають не завжди, а лише тоді, коли ширина проїзної частини недостатня, щоб об'їхати перешкоду без виїзду на колію.","ru":"Для объезда на пути выезжают не всегда, а только тогда, когда ширина проезжей части недостаточна, чтобы объехать препятствие без выезда на пути."}},{"uk":"За умови, що рух не заборонено дорожніми знаками чи дорожньою розміткою, а також під час випередження, об'їзду, коли ширина проїзної частини недостатня для виконання об'їзду без виїзду на трамвайну колію.","ru":"При условии, что движение не запрещено дорожными знаками или дорожной разметкой, а также при опережении, объезде, когда ширина проезжей части недостаточна для выполнения объезда без выезда на трамвайные пути."},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2.","w":{"uk":"Обидва варіанти містять хибне «завжди»: дозвіл з {p:11.8} діє лише за певних умов.","ru":"Оба варианта содержат неверное «всегда»: разрешение из {p:11.8} действует только при определённых условиях."}}],"c":2,"e":{"uk":"Варіант 3 відтворює {p:11.8}: рух по попутній колії на одному рівні з проїзною частиною дозволений, якщо його не заборонено знаками чи розміткою, а для об'їзду — коли ширини проїзної частини не вистачає; при цьому не можна створювати перешкод трамваю.","ru":"Вариант 3 воспроизводит {p:11.8}: движение по попутным путям на одном уровне с проезжей частью разрешено, если его не запрещают знаки или разметка, а для объезда — когда ширины проезжей части не хватает; при этом нельзя создавать помех трамваю."},"ref":["11.8"]},{"id":"h11-34","t":"h11","num":"11.34","q":{"uk":"У якому випадку заборонено в'їжджати на попутні трамвайні колії, розташовані на одному рівні з проїзною частиною?","ru":"В каком случае запрещено въезжать на попутные трамвайные пути, расположенные на одном уровне с проезжей частью?"},"a":[{"uk":"Коли рух по ній заборонено дорожніми знаками чи дорожньою розміткою.","ru":"Когда движение по ним запрещено дорожными знаками или дорожной разметкой.","w":{"uk":"Неповна відповідь: виїзд заборонений також для об'їзду, коли ширини проїзної частини достатньо, і тоді, коли він заважає трамваю.","ru":"Неполный ответ: выезд запрещён также для объезда, когда ширины проезжей части достаточно, и тогда, когда он мешает трамваю."}},{"uk":"Коли ширина проїзної частини достатня для виконання об'їзду без виїзду на трамвайну колію.","ru":"Когда ширина проезжей части достаточна для выполнения объезда без выезда на трамвайные пути.","w":{"uk":"Неповна відповідь: виїзд заборонений також знаками чи розміткою і тоді, коли він заважає трамваю.","ru":"Неполный ответ: выезд запрещён также знаками или разметкой и тогда, когда он мешает трамваю."}},{"uk":"Якщо в разі виїзду на трамвайну колію створюється перешкода для руху трамвая.","ru":"Если при выезде на трамвайные пути создаётся помеха для движения трамвая.","w":{"uk":"Неповна відповідь: виїзд може бути заборонений також знаками чи розміткою або недоречний для об'їзду, коли ширини проїзної частини достатньо.","ru":"Неполный ответ: выезд может быть запрещён также знаками или разметкой либо неуместен для объезда, когда ширины проезжей части достаточно."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2.","w":{"uk":"Неповна відповідь: пропущено головну вимогу — не створювати перешкод для руху трамвая.","ru":"Неполный ответ: пропущено главное требование — не создавать помех для движения трамвая."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3."}],"c":4,"e":{"uk":"Усі три обмеження випливають з {p:11.8}: рух по колії можливий, лише якщо його не заборонено знаками чи розміткою; для об'їзду — лише коли ширини проїзної частини не вистачає; і в усіх випадках не можна створювати перешкод для руху трамвая.","ru":"Все три ограничения следуют из {p:11.8}: движение по путям возможно, только если его не запрещают знаки или разметка; для объезда — только когда ширины проезжей части не хватает; и во всех случаях нельзя создавать помех для движения трамвая."},"ref":["11.8"]},{"id":"h11-35","t":"h11","num":"11.35","q":{"uk":"У якому випадку дозволено виїжджати на трамвайну колію попутного напрямку на перехрестях?","ru":"В каком случае разрешено выезжать на трамвайные пути попутного направления на перекрёстках?"},"a":[{"uk":"У тих самих випадках, що й поза перехрестями, якщо кількість смуг для руху і дозволені напрямки руху по смугах не визначені дорожніми знаками.","ru":"В тех же случаях, что и вне перекрёстков, если количество полос для движения и разрешённые направления движения по полосам не определены дорожными знаками."},{"uk":"Виїжджати на трамвайну колію попутного напрямку на перехрестях заборонено.","ru":"Выезжать на трамвайные пути попутного направления на перекрёстках запрещено.","w":{"uk":"Повної заборони немає: {p:11.8} дозволяє виїзд на колію на перехресті, якщо перед ним немає знаків, що визначають рух по смугах.","ru":"Полного запрета нет: {p:11.8} разрешает выезд на пути на перекрёстке, если перед ним нет знаков, определяющих движение по полосам."}},{"uk":"Тільки для об'їзду, повороту ліворуч і розвороту. При цьому не повинні створюватися перешкоди для руху трамвая.","ru":"Только для объезда, поворота налево и разворота. При этом не должны создаваться помехи для движения трамвая.","w":{"uk":"Варіант пропускає головну умову з {p:11.8} — відсутність перед перехрестям знаків, що визначають смуги й напрямки руху, — і безпідставно звужує випадки виїзду на колію.","ru":"Вариант пропускает главное условие из {p:11.8} — отсутствие перед перекрёстком знаков, определяющих полосы и направления движения, — и необоснованно сужает случаи выезда на пути."}}],"c":0,"e":{"uk":"За {p:11.8} на перехресті на трамвайну колію попутного напрямку можна виїжджати в тих самих випадках, що й поза ним, якщо перед перехрестям немає знаків {s:5.16}, {s:5.17.1}, {s:5.17.2}, {s:5.18}, {s:5.19.1}, {s:5.19.2}, {s:5.19.3}, які визначають смуги й напрямки руху по них.","ru":"Согласно {p:11.8} на перекрёстке на трамвайные пути попутного направления можно выезжать в тех же случаях, что и вне его, если перед перекрёстком нет знаков {s:5.16}, {s:5.17.1}, {s:5.17.2}, {s:5.18}, {s:5.19.1}, {s:5.19.2}, {s:5.19.3}, которые определяют полосы и направления движения по ним."},"ref":["11.8"]},{"id":"h11-36","t":"h11","num":"11.36","q":{"uk":"Коли дозволено виїжджати на крайню ліву смугу на дорогах, що мають дві смуги і більше для руху в одному напрямку?","ru":"Когда разрешено выезжать на крайнюю левую полосу на дорогах, имеющих две полосы и более для движения в одном направлении?"},"a":[{"uk":"Для повороту ліворуч або розвороту.","ru":"Для поворота налево или разворота.","w":{"uk":"Неповна відповідь: на ліву смугу можна виїхати також, коли праві зайняті, і для зупинки зліва на дорозі з одностороннім рухом у населеному пункті.","ru":"Неполный ответ: на левую полосу можно выехать также, когда правые заняты, и для остановки слева на дороге с односторонним движением в населённом пункте."}},{"uk":"Якщо праві смуги зайняті, а також для зупинки або стоянки на лівому боці дороги з одностороннім рухом поза населеними пунктами, якщо це не суперечить правилам зупинки (стоянки).","ru":"Если правые полосы заняты, а также для остановки или стоянки на левой стороне дороги с односторонним движением вне населённых пунктов, если это не противоречит правилам остановки (стоянки).","w":{"uk":"Зупинка й стоянка на лівому боці дороги з одностороннім рухом дозволені лише в населених пунктах, а не поза ними ({p:11.5}, {p:15.3}).","ru":"Остановка и стоянка на левой стороне дороги с односторонним движением разрешены только в населённых пунктах, а не вне их ({p:11.5}, {p:15.3})."}},{"uk":"Якщо праві смуги зайняті, а також для зупинки або стоянки на лівому боці дороги з одностороннім рухом у населених пунктах, якщо це не суперечить правилам зупинки (стоянки).","ru":"Если правые полосы заняты, а также для остановки или стоянки на левой стороне дороги с односторонним движением в населённых пунктах, если это не противоречит правилам остановки (стоянки).","w":{"uk":"Неповна відповідь: на ліву смугу можна виїхати також для повороту ліворуч або розвороту.","ru":"Неполный ответ: на левую полосу можно выехать также для поворота налево или разворота."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2.","w":{"uk":"Варіант 2 помилковий: поза населеними пунктами зупинятися на лівому боці дороги не дозволено.","ru":"Вариант 2 ошибочен: вне населённых пунктов останавливаться на левой стороне дороги не разрешено."}},{"uk":"Відповіді 1 і 3.","ru":"Ответы 1 и 3."}],"c":4,"e":{"uk":"{p:11.5} дозволяє виїзд на крайню ліву смугу, якщо праві зайняті, для повороту ліворуч, розвороту, а також для зупинки чи стоянки на лівому боці дороги з одностороннім рухом **у населених пунктах**. Варіанти 1 і 3 разом відтворюють цей пункт.","ru":"{p:11.5} разрешает выезд на крайнюю левую полосу, если правые заняты, для поворота налево, разворота, а также для остановки или стоянки на левой стороне дороги с односторонним движением **в населённых пунктах**. Варианты 1 и 3 вместе воспроизводят этот пункт."},"ref":["11.5","15.3"]},{"id":"h11-37","t":"h11","num":"11.37","q":{"uk":"Чи має право водій транспортного засобу виїжджати на трамвайну колію зустрічного напрямку?","ru":"Имеет ли право водитель транспортного средства выезжать на трамвайные пути встречного направления?"},"a":[{"uk":"Має право в будь-якому разі для виконання об'їзду.","ru":"Имеет право в любом случае для выполнения объезда.","w":{"uk":"Для об'їзду можна використовувати лише колію попутного напрямку ({p:11.8}); на зустрічну колію виїжджати заборонено.","ru":"Для объезда можно использовать только пути попутного направления ({p:11.8}); на встречные пути выезжать запрещено."}},{"uk":"Не має права: виїзд на зустрічну трамвайну колію заборонено.","ru":"Не имеет права: выезд на встречные трамвайные пути запрещён."}],"c":1,"e":{"uk":"{p:11.9} без винятків забороняє виїжджати на трамвайну колію зустрічного напрямку.","ru":"{p:11.9} без исключений запрещает выезжать на трамвайные пути встречного направления."},"ref":["11.9"]},{"id":"h11-38","t":"h11","num":"11.38","q":{"uk":"На дорогах з якою мінімальною кількістю смуг для руху в одному напрямку заборонено виїжджати на бік, призначений для зустрічного руху?","ru":"На дорогах с каким минимальным количеством полос для движения в одном направлении запрещено выезжать на сторону, предназначенную для встречного движения?"},"a":[{"uk":"Три і більше.","ru":"Три и более.","w":{"uk":"Заборона діє вже з двох смуг в одному напрямку, а не з трьох.","ru":"Запрет действует уже с двух полос в одном направлении, а не с трёх."}},{"uk":"Дві і більше.","ru":"Две и более."},{"uk":"Чотири і більше.","ru":"Четыре и более.","w":{"uk":"Заборона діє вже з двох смуг в одному напрямку, а не з чотирьох.","ru":"Запрет действует уже с двух полос в одном направлении, а не с четырёх."}}],"c":1,"e":{"uk":"За {p:11.4} заборона діє на дорогах із двостороннім рухом, які мають **щонайменше дві** смуги для руху в одному напрямку.","ru":"Согласно {p:11.4} запрет действует на дорогах с двусторонним движением, имеющих **не менее двух** полос для движения в одном направлении."},"ref":["11.4"]},{"id":"h11-39","t":"h11","num":"11.39","q":{"uk":"Чим у першу чергу повинен керуватися водій нерейкового транспортного засобу для визначення кількості смуг на проїзній частині?","ru":"Чем в первую очередь должен руководствоваться водитель нерельсового транспортного средства для определения количества полос на проезжей части?"},"a":[{"uk":"Лініями горизонтальної і вертикальної дорожньої розмітки.","ru":"Линиями горизонтальной и вертикальной дорожной разметки.","w":{"uk":"Вертикальна розмітка позначає елементи дорожніх споруд і смуг не визначає; для цього слугують горизонтальна розмітка або знаки.","ru":"Вертикальная разметка обозначает элементы дорожных сооружений и полос не определяет; для этого служат горизонтальная разметка или знаки."}},{"uk":"Тільки лініями горизонтальної дорожньої розмітки.","ru":"Только линиями горизонтальной дорожной разметки.","w":{"uk":"Неповна відповідь: кількість смуг можуть визначати й дорожні знаки.","ru":"Неполный ответ: количество полос могут определять и дорожные знаки."}},{"uk":"Тільки дорожніми знаками «Напрямок руху по смугах» і «Напрямок руху по смузі».","ru":"Только дорожными знаками «Направление движения по полосам» и «Направление движения по полосе».","w":{"uk":"Неповна відповідь: кількість смуг визначає й дорожня розмітка.","ru":"Неполный ответ: количество полос определяет и дорожная разметка."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3.","w":{"uk":"Варіанти суперечать один одному («тільки розмітка» і «тільки знаки»), а вертикальна розмітка смуг не визначає.","ru":"Варианты противоречат друг другу («только разметка» и «только знаки»), а вертикальная разметка полос не определяет."}},{"uk":"Дорожньою розміткою або дорожніми знаками «Напрямок руху по смугах» і «Напрямок руху по смузі».","ru":"Дорожной разметкой или дорожными знаками «Направление движения по полосам» и «Направление движения по полосе»."}],"c":4,"e":{"uk":"За {p:11.1} кількість смуг визначається дорожньою розміткою **або** знаками {s:5.16}, {s:5.17.1}, {s:5.17.2}, а за їх відсутності — самими водіями.","ru":"Согласно {p:11.1} количество полос определяется дорожной разметкой **или** знаками {s:5.16}, {s:5.17.1}, {s:5.17.2}, а при их отсутствии — самими водителями."},"ref":["11.1"]},{"id":"h12-1","t":"h12","num":"12.1","q":{"uk":"У яких випадках за допомогою дорожніх знаків вводяться постійні обмеження швидкості руху?","ru":"В каких случаях с помощью дорожных знаков вводятся постоянные ограничения скорости движения?"},"a":[{"uk":"На небезпечних ділянках доріг і вулиць та в місцях розміщення наземних нерегульованих пішохідних переходів.","ru":"На опасных участках дорог и улиц и в местах размещения наземных нерегулируемых пешеходных переходов.","w":{"uk":"Неповна відповідь: постійні обмеження вводять також біля дитячих садків, шкіл і дитячих оздоровчих таборів.","ru":"Неполный ответ: постоянные ограничения вводят также возле детских садов, школ и детских оздоровительных лагерей."}},{"uk":"На ділянках доріг (вулиць), що прилягають до території дошкільних та загальноосвітніх навчальних закладів, дитячих оздоровчих таборів.","ru":"На участках дорог (улиц), прилегающих к территории дошкольных и общеобразовательных учебных заведений, детских оздоровительных лагерей.","w":{"uk":"Неповна відповідь: постійні обмеження вводять також на небезпечних ділянках доріг і біля нерегульованих пішохідних переходів.","ru":"Неполный ответ: постоянные ограничения вводят также на опасных участках дорог и у нерегулируемых пешеходных переходов."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2."}],"c":2,"e":{"uk":"За {p:12.10} постійні обмеження швидкості вводяться виключно на небезпечних ділянках доріг і вулиць, у місцях наземних нерегульованих пішохідних переходів, біля дорожніх станцій патрульної поліції та на ділянках, прилеглих до дошкільних і загальноосвітніх навчальних закладів, дитячих оздоровчих таборів — тож правильні **обидва** варіанти.","ru":"Согласно {p:12.10} постоянные ограничения скорости вводятся исключительно на опасных участках дорог и улиц, в местах наземных нерегулируемых пешеходных переходов, у дорожных станций патрульной полиции и на участках, прилегающих к дошкольным и общеобразовательным учебным заведениям, детским оздоровительным лагерям, — поэтому верны **оба** варианта."},"ref":["12.10"],"pic":["img/hsc/12-1-1.jpg"]},{"id":"h12-2","t":"h12","num":"12.2","q":{"uk":"З якою максимальною швидкістю дозволено рух водієві зі стажем менш ніж два роки?","ru":"С какой максимальной скоростью разрешено движение водителю со стажем менее двух лет?"},"a":[{"uk":"60 км/год.","ru":"60 км/ч.","w":{"uk":"60 км/год — обмеження для вантажних автомобілів, що перевозять людей у кузові, і мопедів, а не для водіїв-початківців.","ru":"60 км/ч — ограничение для грузовых автомобилей, перевозящих людей в кузове, и мопедов, а не для начинающих водителей."}},{"uk":"70 км/год.","ru":"70 км/ч."},{"uk":"80 км/год.","ru":"80 км/ч.","w":{"uk":"80 км/год дозволено легковим автомобілям з причепом, мотоциклам і автобусам з організованими групами дітей; водієві зі стажем до 2 років — лише 70 км/год.","ru":"80 км/ч разрешено легковым автомобилям с прицепом, мотоциклам и автобусам с организованными группами детей; водителю со стажем до 2 лет — только 70 км/ч."}},{"uk":"90 км/год.","ru":"90 км/ч.","w":{"uk":"90 км/год — загальне обмеження для звичайних доріг поза населеними пунктами, але для водія зі стажем до 2 років воно нижче — 70 км/год.","ru":"90 км/ч — общее ограничение для обычных дорог вне населённых пунктов, но для водителя со стажем до 2 лет оно ниже — 70 км/ч."}},{"uk":"50 км/год.","ru":"50 км/ч.","w":{"uk":"50 км/год діє в населених пунктах, позначених білим знаком {s:5.49}, а тут знак синій — {s:5.51}.","ru":"50 км/ч действует в населённых пунктах, обозначенных белым знаком {s:5.49}, а здесь знак синий — {s:5.51}."}}],"c":1,"e":{"uk":"Автомобіль в'їжджає в населений пункт, позначений синім знаком {s:5.51}: на цій дорозі вимоги для населених пунктів не діють, тож застосовується {p:12.6}, а для водія зі стажем до 2 років він встановлює не більше **70 км/год**.","ru":"Автомобиль въезжает в населённый пункт, обозначенный синим знаком {s:5.51}: на этой дороге требования для населённых пунктов не действуют, поэтому применяется {p:12.6}, а для водителя со стажем до 2 лет он устанавливает не более **70 км/ч**."},"ref":["12.6"],"pic":["img/hsc/12-2-1.jpg"]},{"id":"h12-3","t":"h12","num":"12.3","q":{"uk":"Яка максимальна швидкість встановлена для руху легкових автомобілів на автомагістралі (крім транспортних засобів, якими керують водії зі стажем до 2-х років)?","ru":"Какая максимальная скорость установлена для движения легковых автомобилей на автомагистрали (кроме транспортных средств, которыми управляют водители со стажем до 2 лет)?"},"a":[{"uk":"80 км/год.","ru":"80 км/ч.","w":{"uk":"80 км/год — обмеження для легкових автомобілів з причепом, мотоциклів і автобусів з організованими групами дітей.","ru":"80 км/ч — ограничение для легковых автомобилей с прицепом, мотоциклов и автобусов с организованными группами детей."}},{"uk":"90 км/год.","ru":"90 км/ч.","w":{"uk":"90 км/год — обмеження для звичайних доріг поза населеними пунктами, а не для автомагістралі.","ru":"90 км/ч — ограничение для обычных дорог вне населённых пунктов, а не для автомагистрали."}},{"uk":"110 км/год.","ru":"110 км/ч.","w":{"uk":"110 км/год дозволено на дорогах з окремими проїзними частинами, розділеними розділювальною смугою; на автомагістралі межа вища.","ru":"110 км/ч разрешено на дорогах с отдельными проезжими частями, разделёнными разделительной полосой; на автомагистрали предел выше."}},{"uk":"130 км/год.","ru":"130 км/ч."}],"c":3,"e":{"uk":"За {p:12.6} (підпункт «ґ») на дорозі, позначеній знаком {s:5.1} «Автомагістраль», легковим автомобілям дозволено рух зі швидкістю не більше **130 км/год**.","ru":"Согласно {p:12.6} (подпункт «ґ») на дороге, обозначенной знаком {s:5.1} «Автомагистраль», легковым автомобилям разрешено движение со скоростью не более **130 км/ч**."},"ref":["12.6"]},{"id":"h12-4","t":"h12","num":"12.4","q":{"uk":"З якою максимальною швидкістю можуть рухатися легкові автомобілі по дорогах для автомобілів (крім транспортних засобів, якими керують водії зі стажем до 2-х років)?","ru":"С какой максимальной скоростью могут двигаться легковые автомобили по дорогам для автомобилей (кроме транспортных средств, которыми управляют водители со стажем до 2 лет)?"},"a":[{"uk":"80 км/год.","ru":"80 км/ч.","w":{"uk":"80 км/год — обмеження для легкових автомобілів з причепом, мотоциклів і автобусів з організованими групами дітей.","ru":"80 км/ч — ограничение для легковых автомобилей с прицепом, мотоциклов и автобусов с организованными группами детей."}},{"uk":"90 км/год.","ru":"90 км/ч.","w":{"uk":"90 км/год — обмеження для звичайних доріг без розділювальної смуги.","ru":"90 км/ч — ограничение для обычных дорог без разделительной полосы."}},{"uk":"110 км/год.","ru":"110 км/ч."},{"uk":"130 км/год.","ru":"130 км/ч.","w":{"uk":"130 км/год дозволено лише на автомагістралі, позначеній знаком {s:5.1}, а не на дорозі для автомобілів.","ru":"130 км/ч разрешено только на автомагистрали, обозначенной знаком {s:5.1}, а не на дороге для автомобилей."}}],"c":2,"e":{"uk":"Знак {s:5.3} «Дорога для автомобілів» — це не автомагістраль, тож 130 км/год тут не дозволено. Така дорога, як правило, має окремі проїзні частини з розділювальною смугою, для яких {p:12.6} (підпункт «ґ») дозволяє легковим автомобілям не більше **110 км/год**.","ru":"Знак {s:5.3} «Дорога для автомобилей» — это не автомагистраль, поэтому 130 км/ч здесь не разрешено. Такая дорога, как правило, имеет отдельные проезжие части с разделительной полосой, для которых {p:12.6} (подпункт «ґ») разрешает легковым автомобилям не более **110 км/ч**."},"ref":["12.6"],"pic":["img/hsc/12-4-1.jpg"]},{"id":"h12-5","t":"h12","num":"12.5","q":{"uk":"З якою максимальною швидкістю допускається рух легкових автомобілів на дорогах з окремими проїзними частинами, що відокремлені одна від одної розділювальною смугою (крім транспортних засобів, якими керують водії зі стажем до 2-х років)?","ru":"С какой максимальной скоростью допускается движение легковых автомобилей на дорогах с отдельными проезжими частями, отделёнными одна от другой разделительной полосой (кроме транспортных средств, которыми управляют водители со стажем до 2 лет)?"},"a":[{"uk":"80 км/год.","ru":"80 км/ч.","w":{"uk":"80 км/год — обмеження для легкових автомобілів з причепом, мотоциклів і автобусів з організованими групами дітей.","ru":"80 км/ч — ограничение для легковых автомобилей с прицепом, мотоциклов и автобусов с организованными группами детей."}},{"uk":"90 км/год.","ru":"90 км/ч.","w":{"uk":"90 км/год — обмеження для доріг без розділювальної смуги між зустрічними проїзними частинами.","ru":"90 км/ч — ограничение для дорог без разделительной полосы между встречными проезжими частями."}},{"uk":"110 км/год.","ru":"110 км/ч."},{"uk":"130 км/год.","ru":"130 км/ч.","w":{"uk":"130 км/год дозволено лише на автомагістралі, позначеній знаком {s:5.1}.","ru":"130 км/ч разрешено только на автомагистрали, обозначенной знаком {s:5.1}."}}],"c":2,"e":{"uk":"На малюнку зустрічні проїзні частини відокремлені зеленою розділювальною смугою; для таких доріг {p:12.6} (підпункт «ґ») встановлює для легкових автомобілів не більше **110 км/год**.","ru":"На рисунке встречные проезжие части отделены зелёной разделительной полосой; для таких дорог {p:12.6} (подпункт «ґ») устанавливает для легковых автомобилей не более **110 км/ч**."},"ref":["12.6"],"pic":["img/hsc/12-5-1.jpg"]},{"id":"h12-6","t":"h12","num":"12.6","q":{"uk":"З якою максимальною швидкістю допускається рух на цій дорозі легкового автомобіля, якщо він рухається за межами населеного пункту (крім транспортних засобів, якими керують водії зі стажем до 2-х років)?","ru":"С какой максимальной скоростью допускается движение легкового автомобиля по этой дороге, если он движется вне населённого пункта (кроме транспортных средств, которыми управляют водители со стажем до 2 лет)?"},"a":[{"uk":"70 км/год.","ru":"70 км/ч.","w":{"uk":"70 км/год — обмеження для водіїв зі стажем до 2 років, яких питання прямо виключає.","ru":"70 км/ч — ограничение для водителей со стажем до 2 лет, которых вопрос прямо исключает."}},{"uk":"80 км/год.","ru":"80 км/ч.","w":{"uk":"80 км/год — обмеження для легкових автомобілів з причепом, мотоциклів і автобусів з організованими групами дітей.","ru":"80 км/ч — ограничение для легковых автомобилей с прицепом, мотоциклов и автобусов с организованными группами детей."}},{"uk":"90 км/год.","ru":"90 км/ч."},{"uk":"100 км/год.","ru":"100 км/ч.","w":{"uk":"Такого обмеження {p:12.6} не встановлює: на звичайній дорозі поза населеним пунктом — 90 км/год.","ru":"Такого ограничения {p:12.6} не устанавливает: на обычной дороге вне населённого пункта — 90 км/ч."}},{"uk":"110 км/год.","ru":"110 км/ч.","w":{"uk":"110 км/год дозволено лише на дорогах, де зустрічні проїзні частини відокремлені розділювальною смугою.","ru":"110 км/ч разрешено только на дорогах, где встречные проезжие части отделены разделительной полосой."}}],"c":2,"e":{"uk":"Це звичайна дорога поза населеним пунктом — по одній смузі в кожному напрямку, без розділювальної смуги, тож за {p:12.6} (підпункт «ґ») легковому автомобілю дозволено не більше **90 км/год**.","ru":"Это обычная дорога вне населённого пункта — по одной полосе в каждом направлении, без разделительной полосы, поэтому согласно {p:12.6} (подпункт «ґ») легковому автомобилю разрешено не более **90 км/ч**."},"ref":["12.6"],"pic":["img/hsc/12-6-1.jpg"]},{"id":"h12-7","t":"h12","num":"12.7","q":{"uk":"Яка максимальна швидкість встановлена для автомобіля в цьому місці (крім транспортних засобів, якими керують водії зі стажем до 2-х років)?","ru":"Какая максимальная скорость установлена для автомобиля в этом месте (кроме транспортных средств, которыми управляют водители со стажем до 2 лет)?"},"a":[{"uk":"50 км/год. до кінця всього населеного пункту.","ru":"50 км/ч до конца всего населённого пункта.","w":{"uk":"50 км/год діяло б на всій дорозі після білого знака {s:5.49}; синій знак {s:5.51} на цій дорозі обмеження для населених пунктів не вводить.","ru":"50 км/ч действовало бы на всей дороге после белого знака {s:5.49}; синий знак {s:5.51} на этой дороге ограничение для населённых пунктов не вводит."}},{"uk":"80 км/год. до кінця всього населеного пункту.","ru":"80 км/ч до конца всего населённого пункта.","w":{"uk":"80 км/год — обмеження для легкових автомобілів з причепом і мотоциклів; до того ж на вулицях забудованої території дозволено лише 50 км/год.","ru":"80 км/ч — ограничение для легковых автомобилей с прицепом и мотоциклов; к тому же на улицах застроенной территории разрешено лишь 50 км/ч."}},{"uk":"90 км/год. під час руху прямо, у разі повороту праворуч, на забудовану територію – 50 км/год.","ru":"90 км/ч при движении прямо, при повороте направо, на застроенную территорию, — 50 км/ч."}],"c":2,"e":{"uk":"Синій знак {s:5.51} означає, що **на цій дорозі** вимоги для населених пунктів не діють, тож прямо можна їхати як поза населеним пунктом — до 90 км/год ({p:12.6}). Повернувши праворуч на вулиці забудованої території, водій рухається вже населеним пунктом, де діє обмеження 50 км/год ({p:12.4}).","ru":"Синий знак {s:5.51} означает, что **на этой дороге** требования для населённых пунктов не действуют, поэтому прямо можно ехать как вне населённого пункта — до 90 км/ч ({p:12.6}). Повернув направо на улицы застроенной территории, водитель движется уже по населённому пункту, где действует ограничение 50 км/ч ({p:12.4})."},"ref":["12.4","12.6","33.5"],"pic":["img/hsc/12-7-1.jpg"]},{"id":"h12-8","t":"h12","num":"12.8","q":{"uk":"Яка максимальна швидкість встановлена для легкових автомобілів на цій дорозі за межами населених пунктів (крім транспортних засобів, якими керують водії зі стажем до 2-х років)?","ru":"Какая максимальная скорость установлена для легковых автомобилей на этой дороге вне населённых пунктов (кроме транспортных средств, которыми управляют водители со стажем до 2 лет)?"},"a":[{"uk":"70 км/год.","ru":"70 км/ч.","w":{"uk":"70 км/год — обмеження для водіїв зі стажем до 2 років, яких питання прямо виключає.","ru":"70 км/ч — ограничение для водителей со стажем до 2 лет, которых вопрос прямо исключает."}},{"uk":"80 км/год.","ru":"80 км/ч.","w":{"uk":"80 км/год — обмеження для легкових автомобілів з причепом, мотоциклів і автобусів з організованими групами дітей.","ru":"80 км/ч — ограничение для легковых автомобилей с прицепом, мотоциклов и автобусов с организованными группами детей."}},{"uk":"90 км/год.","ru":"90 км/ч."},{"uk":"100 км/год.","ru":"100 км/ч.","w":{"uk":"Такого обмеження {p:12.6} не встановлює: на звичайній дорозі поза населеним пунктом — 90 км/год.","ru":"Такого ограничения {p:12.6} не устанавливает: на обычной дороге вне населённого пункта — 90 км/ч."}},{"uk":"110 км/год.","ru":"110 км/ч.","w":{"uk":"110 км/год дозволено лише на дорогах, де зустрічні проїзні частини відокремлені розділювальною смугою.","ru":"110 км/ч разрешено только на дорогах, где встречные проезжие части отделены разделительной полосой."}}],"c":2,"e":{"uk":"Дорога на малюнку має по одній смузі в кожному напрямку й не розділена розділювальною смугою — це «інша автомобільна дорога», де за {p:12.6} (підпункт «ґ») легковим автомобілям дозволено не більше **90 км/год**.","ru":"Дорога на рисунке имеет по одной полосе в каждом направлении и не разделена разделительной полосой — это «другая автомобильная дорога», где согласно {p:12.6} (подпункт «ґ») легковым автомобилям разрешено не более **90 км/ч**."},"ref":["12.6"],"pic":["img/hsc/12-8-1.jpg"]},{"id":"h12-9","t":"h12","num":"12.9","q":{"uk":"З якою максимальною швидкістю дозволено рух білому автомобілю на дорозі за межами населених пунктів?","ru":"С какой максимальной скоростью разрешено движение белому автомобилю на дороге вне населённых пунктов?"},"a":[{"uk":"40 км/год.","ru":"40 км/ч.","w":{"uk":"Обмеження для буксирування — 50 км/год, а не 40 км/год.","ru":"Ограничение при буксировке — 50 км/ч, а не 40 км/ч."}},{"uk":"50 км/год.","ru":"50 км/ч."},{"uk":"60 км/год.","ru":"60 км/ч.","w":{"uk":"60 км/год перевищує граничну швидкість буксирування — 50 км/год.","ru":"60 км/ч превышает предельную скорость буксировки — 50 км/ч."}},{"uk":"70 км/год.","ru":"70 км/ч.","w":{"uk":"70 км/год перевищує граничну швидкість буксирування — 50 км/год.","ru":"70 км/ч превышает предельную скорость буксировки — 50 км/ч."}}],"c":1,"e":{"uk":"Білий пікап буксирує синій автомобіль на гнучкому зчепленні, а під час буксирування швидкість не повинна перевищувати **50 км/год** незалежно від дороги ({p:12.7}).","ru":"Белый пикап буксирует синий автомобиль на гибкой сцепке, а при буксировке скорость не должна превышать **50 км/ч** независимо от дороги ({p:12.7})."},"ref":["12.7"],"pic":["img/hsc/12-9-1.jpg"]},{"id":"h12-10","t":"h12","num":"12.10","q":{"uk":"З якою максимальною швидкістю дозволено буксирування транспортним засобам на автомагістралях?","ru":"С какой максимальной скоростью разрешена буксировка транспортных средств на автомагистралях?"},"a":[{"uk":"40 км/год.","ru":"40 км/ч.","w":{"uk":"Обмеження для буксирування — 50 км/год, а не 40 км/год.","ru":"Ограничение при буксировке — 50 км/ч, а не 40 км/ч."}},{"uk":"50 км/год.","ru":"50 км/ч."},{"uk":"60 км/год.","ru":"60 км/ч.","w":{"uk":"60 км/год перевищує граничну швидкість буксирування — 50 км/год, і на автомагістралі виняток не передбачено.","ru":"60 км/ч превышает предельную скорость буксировки — 50 км/ч, и для автомагистрали исключение не предусмотрено."}},{"uk":"70 км/год.","ru":"70 км/ч.","w":{"uk":"70 км/год перевищує граничну швидкість буксирування — 50 км/год.","ru":"70 км/ч превышает предельную скорость буксировки — 50 км/ч."}}],"c":1,"e":{"uk":"Обмеження {p:12.7} — під час буксирування не більше **50 км/год** — діє на будь-якій дорозі, зокрема й на автомагістралі (знак {s:5.1}), хоч звичайним легковим автомобілям там дозволено 130 км/год.","ru":"Ограничение {p:12.7} — при буксировке не более **50 км/ч** — действует на любой дороге, в том числе и на автомагистрали (знак {s:5.1}), хотя обычным легковым автомобилям там разрешено 130 км/ч."},"ref":["12.7"],"pic":["img/hsc/12-10-1.jpg"]},{"id":"h12-11","t":"h12","num":"12.11","q":{"uk":"З якою максимальною швидкістю дозволено рух червоного автомобіля?","ru":"С какой максимальной скоростью разрешено движение красного автомобиля?"},"a":[{"uk":"60 км/год.","ru":"60 км/ч.","w":{"uk":"Знак на автомобілі дозволяє до 70 км/год, тож обмеження 60 км/год для нього не встановлено.","ru":"Знак на автомобиле разрешает до 70 км/ч, так что ограничение 60 км/ч для него не установлено."}},{"uk":"70 км/год.","ru":"70 км/ч."},{"uk":"90 км/год.","ru":"90 км/ч.","w":{"uk":"90 км/год перевищує швидкість, зазначену на розпізнавальному знаку автомобіля.","ru":"90 км/ч превышает скорость, указанную на опознавательном знаке автомобиля."}},{"uk":"110 км/год.","ru":"110 км/ч.","w":{"uk":"Навіть якщо дорога дозволяє 110 км/год іншим, цьому автомобілю розпізнавальний знак обмежує швидкість до 70 км/год.","ru":"Даже если дорога разрешает 110 км/ч другим, этому автомобилю опознавательный знак ограничивает скорость до 70 км/ч."}},{"uk":"50 км/год.","ru":"50 км/ч.","w":{"uk":"50 км/год — обмеження для населених пунктів, а не швидкість, зазначена на знаку автомобіля.","ru":"50 км/ч — ограничение для населённых пунктов, а не скорость, указанная на знаке автомобиля."}}],"c":1,"e":{"uk":"Ззаду на червоному автомобілі розміщено розпізнавальний знак «Обмеження максимальної швидкості» з числом 70 ({p:30.3}, підпункт «и»), а перевищувати швидкість, зазначену на такому знаку, водієві забороняється ({p:12.9}) — отже, не більше **70 км/год**.","ru":"Сзади на красном автомобиле размещён опознавательный знак «Ограничение максимальной скорости» с числом 70 ({p:30.3}, подпункт «и»), а превышать скорость, указанную на таком знаке, водителю запрещается ({p:12.9}), — значит, не более **70 км/ч**."},"ref":["12.9","30.3"],"pic":["img/hsc/12-11-1.jpg"]},{"id":"h12-12","t":"h12","num":"12.12","q":{"uk":"У яких випадках за допомогою дорожніх знаків вводяться тимчасові обмеження швидкості руху?","ru":"В каких случаях с помощью дорожных знаков вводятся временные ограничения скорости движения?"},"a":[{"uk":"У місцях виконання дорожніх робіт і місцях проведення масових або спеціальних заходів.","ru":"В местах выполнения дорожных работ и местах проведения массовых или специальных мероприятий.","w":{"uk":"Неповна відповідь: тимчасові обмеження вводять також у випадках, пов'язаних зі стихійними (погодними) явищами.","ru":"Неполный ответ: временные ограничения вводят также в случаях, связанных со стихийными (погодными) явлениями."}},{"uk":"У випадках, пов’язаних зі стихійними (погодними) явищами.","ru":"В случаях, связанных со стихийными (погодными) явлениями.","w":{"uk":"Неповна відповідь: тимчасові обмеження вводять також у місцях дорожніх робіт і масових або спеціальних заходів.","ru":"Неполный ответ: временные ограничения вводят также в местах дорожных работ и массовых или специальных мероприятий."}},{"uk":"У місцях патрулювання поліцейськими.","ru":"В местах патрулирования полицейскими.","w":{"uk":"Патрулювання поліцейськими не є підставою для обмеження швидкості; лише біля дорожніх станцій патрульної поліції вводять постійне, а не тимчасове обмеження.","ru":"Патрулирование полицейскими не является основанием для ограничения скорости; лишь у дорожных станций патрульной полиции вводят постоянное, а не временное ограничение."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2."},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3.","w":{"uk":"Перелік у {p:12.10} вичерпний, і місць патрулювання поліцейськими в ньому немає.","ru":"Перечень в {p:12.10} исчерпывающий, и мест патрулирования полицейскими в нём нет."}}],"c":3,"e":{"uk":"За {p:12.10} тимчасові обмеження швидкості (знаки {s:3.29} і {s:3.31} на жовтому фоні, як на малюнку) вводяться **виключно** в місцях дорожніх робіт, масових або спеціальних заходів і у випадках, пов'язаних зі стихійними (погодними) явищами.","ru":"Согласно {p:12.10} временные ограничения скорости (знаки {s:3.29} и {s:3.31} на жёлтом фоне, как на рисунке) вводятся **исключительно** в местах дорожных работ, массовых или специальных мероприятий и в случаях, связанных со стихийными (погодными) явлениями."},"ref":["12.10"],"pic":["img/hsc/12-12-1.jpg"]},{"id":"h12-13","t":"h12","num":"12.13","q":{"uk":"Кому з водіїв дозволено рух з більш високою швидкістю?","ru":"Кому из водителей разрешено движение с более высокой скоростью?"},"a":[{"uk":"Водієві мотоцикла.","ru":"Водителю мотоцикла.","w":{"uk":"У житловій зоні обмеження 20 км/год однакове для всіх транспортних засобів, і мотоцикл переваги не має.","ru":"В жилой зоне ограничение 20 км/ч одинаково для всех транспортных средств, и мотоцикл преимущества не имеет."}},{"uk":"Водієві автомобіля.","ru":"Водителю автомобиля.","w":{"uk":"У житловій зоні обмеження 20 км/год однакове для всіх транспортних засобів, і автомобіль переваги не має.","ru":"В жилой зоне ограничение 20 км/ч одинаково для всех транспортных средств, и автомобиль преимущества не имеет."}},{"uk":"Швидкість обох не повинна перевищувати 20 км/год.","ru":"Скорость обоих не должна превышать 20 км/ч."}],"c":2,"e":{"uk":"Обидва транспортні засоби перебувають у житловій зоні, позначеній знаком {s:5.34}, а там швидкість не повинна перевищувати **20 км/год** для всіх ({p:12.5}).","ru":"Оба транспортных средства находятся в жилой зоне, обозначенной знаком {s:5.34}, а там скорость не должна превышать **20 км/ч** для всех ({p:12.5})."},"ref":["12.5"],"pic":["img/hsc/12-13-1.jpg"]},{"id":"h12-14","t":"h12","num":"12.14","q":{"uk":"З якою максимальною швидкістю дозволено рух у житлових і пішохідних зонах?","ru":"С какой максимальной скоростью разрешено движение в жилых и пешеходных зонах?"},"a":[{"uk":"20 км/год.","ru":"20 км/ч."},{"uk":"40 км/год.","ru":"40 км/ч.","w":{"uk":"40 км/год удвічі перевищує дозволені в житловій і пішохідній зоні 20 км/год.","ru":"40 км/ч вдвое превышает разрешённые в жилой и пешеходной зоне 20 км/ч."}},{"uk":"60 км/год.","ru":"60 км/ч.","w":{"uk":"60 км/год значно перевищує дозволені в житловій і пішохідній зоні 20 км/год.","ru":"60 км/ч значительно превышает разрешённые в жилой и пешеходной зоне 20 км/ч."}},{"uk":"50 км/год.","ru":"50 км/ч.","w":{"uk":"50 км/год — загальне обмеження в населених пунктах; у житлових і пішохідних зонах воно суворіше — 20 км/год.","ru":"50 км/ч — общее ограничение в населённых пунктах; в жилых и пешеходных зонах оно строже — 20 км/ч."}}],"c":0,"e":{"uk":"За {p:12.5} у житлових (знак {s:5.34}) і пішохідних (знак {s:5.36}) зонах швидкість руху не повинна перевищувати **20 км/год**.","ru":"Согласно {p:12.5} в жилых (знак {s:5.34}) и пешеходных (знак {s:5.36}) зонах скорость движения не должна превышать **20 км/ч**."},"ref":["12.5"],"pic":["img/hsc/12-14-1.jpg"]},{"id":"h12-15","t":"h12","num":"12.15","q":{"uk":"Швидкість руху в темну пору доби та в умовах недостатньої видимості повинна бути такою, щоб водій:","ru":"Скорость движения в тёмное время суток и в условиях недостаточной видимости должна быть такой, чтобы водитель:"},"a":[{"uk":"Мав можливість оцінити дорожню обстановку на відстані 50-100 м попереду.","ru":"Имел возможность оценить дорожную обстановку на расстоянии 50–100 м впереди.","w":{"uk":"Правила не прив'язують швидкість до фіксованої відстані 50–100 м: видимість буває й меншою, а вирішальне — встигнути зупинитися в її межах.","ru":"Правила не привязывают скорость к фиксированному расстоянию 50–100 м: видимость бывает и меньше, а решающее — успеть остановиться в её пределах."}},{"uk":"Мав можливість зупинити транспортний засіб у межах видимості дороги.","ru":"Имел возможность остановить транспортное средство в пределах видимости дороги."},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2.","w":{"uk":"Варіант 1 неправильний: фіксованої відстані 50–100 м у {p:12.2} немає.","ru":"Вариант 1 неверен: фиксированного расстояния 50–100 м в {p:12.2} нет."}}],"c":1,"e":{"uk":"Вимога {p:12.2} одна: у темну пору доби та в умовах недостатньої видимості швидкість має бути такою, щоб водій міг **зупинити транспортний засіб у межах видимості дороги** — тобто в межах ділянки, яку освітлюють фари.","ru":"Требование {p:12.2} одно: в тёмное время суток и в условиях недостаточной видимости скорость должна быть такой, чтобы водитель мог **остановить транспортное средство в пределах видимости дороги** — то есть в пределах участка, освещаемого фарами."},"ref":["12.2"],"pic":["img/hsc/12-15-1.jpg"]},{"id":"h12-16","t":"h12","num":"12.16","q":{"uk":"Рухаючись по дорозі, водій виявив перешкоду для руху. Як він повинен вчинити в такій ситуації?","ru":"Двигаясь по дороге, водитель обнаружил препятствие для движения. Как он должен поступить в такой ситуации?"},"a":[{"uk":"Знизити швидкість на 10 км/год., об'їхати небезпеку, що виникла, а в разі потреби зупинитися.","ru":"Снизить скорость на 10 км/ч, объехать возникшую опасность, а при необходимости остановиться.","w":{"uk":"Правила не встановлюють зниження швидкості саме на 10 км/год: її треба зменшити настільки, наскільки потрібно, аж до зупинки.","ru":"Правила не устанавливают снижение скорости именно на 10 км/ч: её нужно уменьшить настолько, насколько требуется, вплоть до остановки."}},{"uk":"Знизити швидкість (аж до зупинки транспортного засобу) або, забезпечивши безпеку для інших учасників руху, об'їхати перешкоду.","ru":"Снизить скорость (вплоть до остановки транспортного средства) или, обеспечив безопасность для других участников движения, объехать препятствие."},{"uk":"Об'їхати перешкоду, не знижуючи швидкості.","ru":"Объехать препятствие, не снижая скорости.","w":{"uk":"Об'їзд допускається лише безпечний для інших учасників руху, а рух без зниження швидкості цієї умови не враховує і суперечить {p:12.3}.","ru":"Объезд допускается только безопасный для других участников движения, а движение без снижения скорости этого условия не учитывает и противоречит {p:12.3}."}}],"c":1,"e":{"uk":"Побачивши на своїй смузі перешкоду (купу каміння), водій за {p:12.3} повинен негайно вжити заходів для зменшення швидкості **аж до зупинки** або безпечно для інших учасників руху об'їхати перешкоду.","ru":"Увидев на своей полосе препятствие (кучу камней), водитель согласно {p:12.3} должен немедленно принять меры для снижения скорости **вплоть до остановки** или безопасно для других участников движения объехать препятствие."},"ref":["12.3"],"pic":["img/hsc/12-16-1.jpg"]},{"id":"h12-17","t":"h12","num":"12.17","q":{"uk":"Яку максимальну швидкість руху встановлено в населених пунктах, позначених даним дорожнім знаком?","ru":"Какая максимальная скорость движения установлена в населённых пунктах, обозначенных данным дорожным знаком?"},"a":[{"uk":"50 км/год.","ru":"50 км/ч."},{"uk":"60 км/год.","ru":"60 км/ч.","w":{"uk":"У населеному пункті, позначеному білим знаком {s:5.49}, дозволено не більше 50 км/год, а не 60 км/год.","ru":"В населённом пункте, обозначенном белым знаком {s:5.49}, разрешено не более 50 км/ч, а не 60 км/ч."}},{"uk":"70 км/год.","ru":"70 км/ч.","w":{"uk":"70 км/год — обмеження поза населеними пунктами для водіїв зі стажем до 2 років, а не для населеного пункту.","ru":"70 км/ч — ограничение вне населённых пунктов для водителей со стажем до 2 лет, а не для населённого пункта."}},{"uk":"80 км/год.","ru":"80 км/ч.","w":{"uk":"80 км/год — обмеження поза населеними пунктами для легкових автомобілів з причепом і мотоциклів.","ru":"80 км/ч — ограничение вне населённых пунктов для легковых автомобилей с прицепом и мотоциклов."}}],"c":0,"e":{"uk":"Білий знак з назвою міста — {s:5.49} «Початок населеного пункту»: після нього діють правила руху в населених пунктах, зокрема обмеження **50 км/год** ({p:12.4}).","ru":"Белый знак с названием города — {s:5.49} «Начало населённого пункта»: после него действуют правила движения в населённых пунктах, в частности ограничение **50 км/ч** ({p:12.4})."},"ref":["12.4","33.5"],"pic":["img/hsc/12-17-1.jpg"]},{"id":"h12-18","t":"h12","num":"12.18","q":{"uk":"З якою максимальною швидкістю дозволено рух після проїзду цього знака?","ru":"С какой максимальной скоростью разрешено движение после проезда этого знака?"},"a":[{"uk":"50 км/год.","ru":"50 км/ч."},{"uk":"60 км/год.","ru":"60 км/ч.","w":{"uk":"Після білого знака {s:5.49} дозволено не більше 50 км/год, а не 60 км/год.","ru":"После белого знака {s:5.49} разрешено не более 50 км/ч, а не 60 км/ч."}},{"uk":"70 км/год.","ru":"70 км/ч.","w":{"uk":"70 км/год — обмеження поза населеними пунктами для водіїв зі стажем до 2 років.","ru":"70 км/ч — ограничение вне населённых пунктов для водителей со стажем до 2 лет."}},{"uk":"80 км/год.","ru":"80 км/ч.","w":{"uk":"80 км/год — обмеження поза населеними пунктами для легкових автомобілів з причепом і мотоциклів.","ru":"80 км/ч — ограничение вне населённых пунктов для легковых автомобилей с прицепом и мотоциклов."}}],"c":0,"e":{"uk":"Знак {s:5.49} на білому фоні позначає початок населеного пункту, у якому діють правила руху в населених пунктах, тож після нього швидкість не повинна перевищувати **50 км/год** ({p:12.4}).","ru":"Знак {s:5.49} на белом фоне обозначает начало населённого пункта, в котором действуют правила движения в населённых пунктах, поэтому после него скорость не должна превышать **50 км/ч** ({p:12.4})."},"ref":["12.4","33.5"],"pic":["img/hsc/12-18-1.jpg"]},{"id":"h12-19","t":"h12","num":"12.19","q":{"uk":"З якою максимальною швидкістю дозволено рух на дорогах з розділювальною смугою в населених пунктах?","ru":"С какой максимальной скоростью разрешено движение на дорогах с разделительной полосой в населённых пунктах?"},"a":[{"uk":"60 км/год.","ru":"60 км/ч.","w":{"uk":"Наявність розділювальної смуги в населеному пункті не підвищує межу 50 км/год.","ru":"Наличие разделительной полосы в населённом пункте не повышает предел 50 км/ч."}},{"uk":"70 км/год.","ru":"70 км/ч.","w":{"uk":"70 км/год — обмеження поза населеними пунктами для водіїв зі стажем до 2 років; у населеному пункті — 50 км/год.","ru":"70 км/ч — ограничение вне населённых пунктов для водителей со стажем до 2 лет; в населённом пункте — 50 км/ч."}},{"uk":"80 км/год.","ru":"80 км/ч.","w":{"uk":"80 км/год — обмеження поза населеними пунктами для легкових автомобілів з причепом і мотоциклів; у населеному пункті — 50 км/год.","ru":"80 км/ч — ограничение вне населённых пунктов для легковых автомобилей с прицепом и мотоциклов; в населённом пункте — 50 км/ч."}},{"uk":"90 км/год.","ru":"90 км/ч.","w":{"uk":"90 км/год дозволено на звичайних дорогах поза населеними пунктами, а не в населеному пункті.","ru":"90 км/ч разрешено на обычных дорогах вне населённых пунктов, а не в населённом пункте."}},{"uk":"50 км/год.","ru":"50 км/ч."}],"c":4,"e":{"uk":"Розділювальна смуга підвищує дозволену швидкість лише поза населеними пунктами ({p:12.6}); у населеному пункті на будь-якій дорозі діє обмеження **50 км/год** ({p:12.4}), якщо знаками не встановлено інше.","ru":"Разделительная полоса повышает разрешённую скорость только вне населённых пунктов ({p:12.6}); в населённом пункте на любой дороге действует ограничение **50 км/ч** ({p:12.4}), если знаками не установлено иное."},"ref":["12.4"],"pic":["img/hsc/12-19-1.jpg"]},{"id":"h12-20","t":"h12","num":"12.20","q":{"uk":"З якою максимальною швидкістю дозволено рух автомобіля в зображеній ситуації?","ru":"С какой максимальной скоростью разрешено движение автомобиля в изображённой ситуации?"},"a":[{"uk":"20 км/год.","ru":"20 км/ч."},{"uk":"40 км/год.","ru":"40 км/ч.","w":{"uk":"40 км/год удвічі перевищує дозволені в житловій зоні 20 км/год.","ru":"40 км/ч вдвое превышает разрешённые в жилой зоне 20 км/ч."}},{"uk":"60 км/год.","ru":"60 км/ч.","w":{"uk":"60 км/год значно перевищує дозволені в житловій зоні 20 км/год.","ru":"60 км/ч значительно превышает разрешённые в жилой зоне 20 км/ч."}},{"uk":"50 км/год.","ru":"50 км/ч.","w":{"uk":"50 км/год — загальне обмеження в населеному пункті, а знак {s:5.34} вводить суворіше — 20 км/год.","ru":"50 км/ч — общее ограничение в населённом пункте, а знак {s:5.34} вводит более строгое — 20 км/ч."}}],"c":0,"e":{"uk":"Автомобіль рухається територією, позначеною знаком {s:5.34} «Житлова зона», а в житловій зоні швидкість не повинна перевищувати **20 км/год** ({p:12.5}).","ru":"Автомобиль движется по территории, обозначенной знаком {s:5.34} «Жилая зона», а в жилой зоне скорость не должна превышать **20 км/ч** ({p:12.5})."},"ref":["12.5"],"pic":["img/hsc/12-20-1.jpg"]},{"id":"h12-21","t":"h12","num":"12.21","q":{"uk":"Чи завжди водій під час вибору безпечної швидкості руху повинен враховувати особливості вантажу, що перевозиться?","ru":"Всегда ли водитель при выборе безопасной скорости движения должен учитывать особенности перевозимого груза?"},"a":[{"uk":"Не повинен, якщо вантаж добре закріплений.","ru":"Не должен, если груз хорошо закреплён.","w":{"uk":"Навіть надійно закріплений вантаж змінює масу, центр ваги й гальмівний шлях автомобіля, тож його особливості треба враховувати.","ru":"Даже надёжно закреплённый груз меняет массу, центр тяжести и тормозной путь автомобиля, поэтому его особенности нужно учитывать."}},{"uk":"Повинен завжди.","ru":"Должен всегда."}],"c":1,"e":{"uk":"За {p:12.1}, вибираючи безпечну швидкість, водій **завжди** враховує дорожню обстановку, особливості вантажу і стан транспортного засобу — жодних винятків для закріпленого вантажу немає.","ru":"Согласно {p:12.1}, выбирая безопасную скорость, водитель **всегда** учитывает дорожную обстановку, особенности груза и состояние транспортного средства — никаких исключений для закреплённого груза нет."},"ref":["12.1"]},{"id":"h12-22","t":"h12","num":"12.22","q":{"uk":"У яких випадках, відповідно до Правил дорожнього руху, водій не може бути притягнений до відповідальності за порушення встановлених обмежень швидкості?","ru":"В каких случаях, согласно Правилам дорожного движения, водитель не может быть привлечён к ответственности за нарушение установленных ограничений скорости?"},"a":[{"uk":"Якщо знаки обмеження швидкості руху встановлені з порушенням правил їх введення.","ru":"Если знаки ограничения скорости движения установлены с нарушением правил их введения.","w":{"uk":"Неповна відповідь: {p:12.10} називає ще два випадки — порушення національних стандартів і знаки, залишені після усунення обставин.","ru":"Неполный ответ: {p:12.10} называет ещё два случая — нарушение национальных стандартов и знаки, оставленные после устранения обстоятельств."}},{"uk":"Якщо знаки обмеження швидкості руху встановлені з порушенням вимог національних стандартів.","ru":"Если знаки ограничения скорости движения установлены с нарушением требований национальных стандартов.","w":{"uk":"Неповна відповідь: {p:12.10} називає ще два випадки — порушення порядку введення знаків і знаки, залишені після усунення обставин.","ru":"Неполный ответ: {p:12.10} называет ещё два случая — нарушение порядка введения знаков и знаки, оставленные после устранения обстоятельств."}},{"uk":"Якщо знаки обмеження швидкості руху залишені після усунення обставин, за яких їх було встановлено.","ru":"Если знаки ограничения скорости движения оставлены после устранения обстоятельств, при которых их установили.","w":{"uk":"Неповна відповідь: так само звільняють від відповідальності знаки, встановлені з порушенням порядку їх введення чи національних стандартів.","ru":"Неполный ответ: так же освобождают от ответственности знаки, установленные с нарушением порядка их введения или национальных стандартов."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2.","w":{"uk":"Бракує третього випадку — знаків, залишених після усунення обставин, за яких їх було встановлено.","ru":"Не хватает третьего случая — знаков, оставленных после устранения обстоятельств, при которых их установили."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3."}],"c":4,"e":{"uk":"{p:12.10} називає всі три випадки: знаки {s:3.29} чи {s:3.31} встановлені з порушенням вимог Правил щодо їх введення, з порушенням національних стандартів або залишені після усунення обставин, за яких їх установили.","ru":"{p:12.10} называет все три случая: знаки {s:3.29} или {s:3.31} установлены с нарушением требований Правил к их введению, с нарушением национальных стандартов или оставлены после устранения обстоятельств, при которых их установили."},"ref":["12.10"]},{"id":"h12-23","t":"h12","num":"12.23","q":{"uk":"Чи завжди, вибираючи безпечну швидкість під час руху взимку, водій повинен враховувати стан дорожнього покриття?","ru":"Всегда ли, выбирая безопасную скорость при движении зимой, водитель должен учитывать состояние дорожного покрытия?"},"a":[{"uk":"Повинен враховувати завжди.","ru":"Должен учитывать всегда."},{"uk":"Не повинен, якщо на транспортному засобі встановлено зимові шини.","ru":"Не должен, если на транспортном средстве установлены зимние шины.","w":{"uk":"Зимові шини лише поліпшують зчеплення, але на ожеледі гальмівний шлях однаково зростає в рази, а {p:12.1} винятків не передбачає.","ru":"Зимние шины лишь улучшают сцепление, но на гололёде тормозной путь всё равно возрастает в разы, а {p:12.1} исключений не предусматривает."}}],"c":0,"e":{"uk":"Стан покриття (сніг, ожеледь, сльота) — частина дорожньої обстановки, яку за {p:12.1} треба враховувати **завжди**, щоб постійно контролювати рух транспортного засобу.","ru":"Состояние покрытия (снег, гололёд, слякоть) — часть дорожной обстановки, которую согласно {p:12.1} нужно учитывать **всегда**, чтобы постоянно контролировать движение транспортного средства."},"ref":["12.1"]},{"id":"h12-24","t":"h12","num":"12.24","q":{"uk":"Чи дозволено водієві різко гальмувати?","ru":"Разрешено ли водителю резко тормозить?"},"a":[{"uk":"Заборонено завжди.","ru":"Запрещено всегда.","w":{"uk":"Заборона не абсолютна: щоб запобігти ДТП, різке гальмування дозволене.","ru":"Запрет не абсолютный: чтобы предотвратить ДТП, резкое торможение разрешено."}},{"uk":"Заборонено, крім випадків запобігання дорожньо-транспортній пригоді.","ru":"Запрещено, кроме случаев предотвращения дорожно-транспортного происшествия."},{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"Без потреби різко гальмувати заборонено — це може спричинити наїзд транспортного засобу, що рухається позаду.","ru":"Без необходимости резко тормозить запрещено — это может привести к наезду движущегося сзади транспортного средства."}}],"c":1,"e":{"uk":"За {p:12.9} (підпункт «г») різко гальмувати заборонено, **крім випадків**, коли без цього неможливо запобігти дорожньо-транспортній пригоді.","ru":"Согласно {p:12.9} (подпункт «г») резко тормозить запрещено, **кроме случаев**, когда без этого невозможно предотвратить дорожно-транспортное происшествие."},"ref":["12.9"]},{"id":"h12-25","t":"h12","num":"12.25","q":{"uk":"Чи можна водієві без потреби рухатися з дуже малою швидкістю?","ru":"Можно ли водителю без необходимости двигаться с очень малой скоростью?"},"a":[{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"Якщо повільний рух без потреби заважає іншим транспортним засобам, він прямо заборонений {p:12.9}.","ru":"Если медленное движение без необходимости мешает другим транспортным средствам, оно прямо запрещено {p:12.9}."}},{"uk":"Заборонено в умовах, коли це перешкоджає іншим транспортним засобам.","ru":"Запрещено в условиях, когда это мешает другим транспортным средствам."}],"c":1,"e":{"uk":"{p:12.9} (підпункт «в») забороняє перешкоджати іншим транспортним засобам, рухаючись **без потреби** з дуже малою швидкістю.","ru":"{p:12.9} (подпункт «в») запрещает мешать другим транспортным средствам, двигаясь **без необходимости** с очень малой скоростью."},"ref":["12.9"]},{"id":"h12-26","t":"h12","num":"12.26","q":{"uk":"Що враховується під час вибору безпечної швидкості руху?","ru":"Что учитывается при выборе безопасной скорости движения?"},"a":[{"uk":"Дорожня обстановка.","ru":"Дорожная обстановка.","w":{"uk":"Неповна відповідь: треба враховувати ще особливості вантажу і стан транспортного засобу.","ru":"Неполный ответ: нужно учитывать ещё особенности груза и состояние транспортного средства."}},{"uk":"Особливості вантажу, що перевозиться.","ru":"Особенности перевозимого груза.","w":{"uk":"Неповна відповідь: треба враховувати ще дорожню обстановку і стан транспортного засобу.","ru":"Неполный ответ: нужно учитывать ещё дорожную обстановку и состояние транспортного средства."}},{"uk":"Стан транспортного засобу.","ru":"Состояние транспортного средства.","w":{"uk":"Неповна відповідь: треба враховувати ще дорожню обстановку й особливості вантажу.","ru":"Неполный ответ: нужно учитывать ещё дорожную обстановку и особенности груза."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3."}],"c":3,"e":{"uk":"{p:12.1} перелічує всі три чинники: дорожню обстановку, особливості вантажу, що перевозиться, і стан транспортного засобу.","ru":"{p:12.1} перечисляет все три фактора: дорожную обстановку, особенности перевозимого груза и состояние транспортного средства."},"ref":["12.1"]},{"id":"h12-27","t":"h12","num":"12.27","q":{"uk":"Чи дозволено водієві перевищувати максимальну дозволену швидкість під час буксирування?","ru":"Разрешено ли водителю превышать максимальную разрешённую скорость при буксировке?"},"a":[{"uk":"Заборонено.","ru":"Запрещено."},{"uk":"Дозволено, якщо довжина гнучкого зчеплення достатня.","ru":"Разрешено, если длина гибкой сцепки достаточна.","w":{"uk":"Довжина гнучкого зчеплення на дозволену швидкість не впливає: обмеження {p:12.7} діє за будь-якого способу буксирування.","ru":"Длина гибкой сцепки на разрешённую скорость не влияет: ограничение {p:12.7} действует при любом способе буксировки."}}],"c":0,"e":{"uk":"Під час буксирування швидкість не повинна перевищувати 50 км/год ({p:12.7}), а перевищувати її {p:12.9} забороняє без жодних винятків.","ru":"При буксировке скорость не должна превышать 50 км/ч ({p:12.7}), а превышать её {p:12.9} запрещает без каких-либо исключений."},"ref":["12.7","12.9"]},{"id":"h12-28","t":"h12","num":"12.28","q":{"uk":"Чи можуть водії транспортних засобів рухатися в житлових і пішохідних зонах зі швидкістю, що перевищує встановлену для таких місць?","ru":"Могут ли водители транспортных средств двигаться в жилых и пешеходных зонах со скоростью, превышающей установленную для таких мест?"},"a":[{"uk":"Дозволено тим, хто там працює або проживає в цих зонах.","ru":"Разрешено тем, кто там работает или проживает в этих зонах.","w":{"uk":"Жителі й працівники можуть в'їжджати до зони, але обмеження 20 км/год стосується і їх.","ru":"Жители и работники могут въезжать в зону, но ограничение 20 км/ч касается и их."}},{"uk":"Дозволено тим, хто обслуговує підприємства.","ru":"Разрешено тем, кто обслуживает предприятия.","w":{"uk":"Транспорт, що обслуговує підприємства, може лише в'їжджати до зони, а швидкість для нього — ті самі 20 км/год.","ru":"Транспорт, обслуживающий предприятия, может лишь въезжать в зону, а скорость для него — те же 20 км/ч."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2.","w":{"uk":"Жодна категорія водіїв не має права перевищувати 20 км/год у житлових і пішохідних зонах.","ru":"Ни одна категория водителей не имеет права превышать 20 км/ч в жилых и пешеходных зонах."}},{"uk":"Заборонено перевищувати встановлену швидкість.","ru":"Запрещено превышать установленную скорость."}],"c":3,"e":{"uk":"Обмеження {p:12.5} — не більше 20 км/год у житлових і пішохідних зонах — стосується **всіх** водіїв; право в'їзду до пішохідної зони ({p:26.3}) не дає права перевищувати цю швидкість.","ru":"Ограничение {p:12.5} — не более 20 км/ч в жилых и пешеходных зонах — касается **всех** водителей; право въезда в пешеходную зону ({p:26.3}) не даёт права превышать эту скорость."},"ref":["12.5"]},{"id":"h12-29","t":"h12","num":"12.29","q":{"uk":"У якому випадку максимальна дозволена швидкість руху на дорозі в населеному пункті може бути збільшена?","ru":"В каком случае максимальная разрешённая скорость движения на дороге в населённом пункте может быть увеличена?"},"a":[{"uk":"У разі створення умов, що дають можливість рухатися з більш високою швидкістю, за узгодженим рішенням уповноваженого підрозділу Національної поліції та власників доріг або органів, яким передано право на утримання таких доріг.","ru":"При создании условий, позволяющих двигаться с более высокой скоростью, по согласованному решению уполномоченного подразделения Национальной полиции и владельцев дорог или органов, которым передано право на содержание таких дорог.","w":{"uk":"Самого рішення недостатньо: для водія нова швидкість починає діяти лише після встановлення відповідних знаків.","ru":"Одного решения недостаточно: для водителя новая скорость начинает действовать только после установки соответствующих знаков."}},{"uk":"У разі встановлення відповідних дорожніх знаків.","ru":"При установке соответствующих дорожных знаков.","w":{"uk":"Знаки, що збільшують швидкість, встановлюють лише там, де створено належні дорожні умови, і за погодженим з поліцією рішенням власників доріг.","ru":"Знаки, увеличивающие скорость, устанавливают только там, где созданы надлежащие дорожные условия, и по согласованному с полицией решению владельцев дорог."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2."}],"c":2,"e":{"uk":"За {p:12.8} дозволену швидкість можна збільшити там, де створено відповідні дорожні умови, за погодженим з уповноваженим підрозділом Національної поліції рішенням власників доріг — **і** шляхом встановлення відповідних дорожніх знаків; потрібні обидві умови.","ru":"Согласно {p:12.8} разрешённую скорость можно увеличить там, где созданы соответствующие дорожные условия, по согласованному с уполномоченным подразделением Национальной полиции решению владельцев дорог — **и** путём установки соответствующих дорожных знаков; нужны оба условия."},"ref":["12.8"]},{"id":"h12-30","t":"h12","num":"12.30","q":{"uk":"За яких умов дозволена максимальна швидкість руху на дорозі може бути збільшена?","ru":"При каких условиях разрешённая максимальная скорость движения на дороге может быть увеличена?"},"a":[{"uk":"За умови встановлення відповідних дорожніх знаків.","ru":"При условии установки соответствующих дорожных знаков."},{"uk":"За узгодженим рішенням власників доріг або органів, яким передано право на утримання таких доріг, у разі створення умов, що дають можливість рухатися з більш високою швидкістю.","ru":"По согласованному решению владельцев дорог или органов, которым передано право на содержание таких дорог, при создании условий, позволяющих двигаться с более высокой скоростью.","w":{"uk":"Процедуру описано неточно: за {p:12.8} рішення власників доріг має бути погоджене з уповноваженим підрозділом Національної поліції, і навіть таке рішення без знаків швидкості не змінює.","ru":"Процедура описана неточно: согласно {p:12.8} решение владельцев дорог должно быть согласовано с уполномоченным подразделением Национальной полиции, и даже такое решение без знаков скорость не меняет."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2.","w":{"uk":"Варіант 2 неточний (у ньому немає погодження з Національною поліцією), тому поєднання варіантів 1 і 2 неправильне.","ru":"Вариант 2 неточен (в нём нет согласования с Национальной полицией), поэтому сочетание вариантов 1 и 2 неверно."}}],"c":0,"e":{"uk":"Для водія дозволена швидкість збільшується лише тоді, коли встановлено **відповідні дорожні знаки** ({p:12.8}): саме вони вводять нову межу, а без них діють загальні обмеження.","ru":"Для водителя разрешённая скорость увеличивается только тогда, когда установлены **соответствующие дорожные знаки** ({p:12.8}): именно они вводят новый предел, а без них действуют общие ограничения."},"ref":["12.8"]},{"id":"h12-31","t":"h12","num":"12.31","q":{"uk":"Яка швидкість обрана правильно під час руху в темну пору доби або в умовах недостатньої видимості?","ru":"Какая скорость выбрана правильно при движении в тёмное время суток или в условиях недостаточной видимости?"},"a":[{"uk":"При якій водій мав змогу зупинити транспортний засіб у межах видимості дороги.","ru":"При которой водитель имел возможность остановить транспортное средство в пределах видимости дороги."},{"uk":"При якій гальмівний шлях дорівнює або не перевищує видимості в напрямку руху.","ru":"При которой тормозной путь равен видимости в направлении движения или не превышает её.","w":{"uk":"Гальмівний шлях не враховує відстані, пройденої за час реакції водія; якщо він дорівнює видимості, зупинитися в її межах не вдасться.","ru":"Тормозной путь не учитывает расстояния, пройденного за время реакции водителя; если он равен видимости, остановиться в её пределах не удастся."}},{"uk":"При якій гальмівний шлях перевищує видимість за напрямком руху.","ru":"При которой тормозной путь превышает видимость по направлению движения.","w":{"uk":"Якщо гальмівний шлях більший за видимість, водій свідомо не встигне зупинитися перед перешкодою, що з'явилася на межі видимості.","ru":"Если тормозной путь больше видимости, водитель заведомо не успеет остановиться перед препятствием, появившимся на границе видимости."}}],"c":0,"e":{"uk":"{p:12.2} вимагає такої швидкості, за якої водій може **зупинити** транспортний засіб у межах видимості дороги. Зупинний шлях — це не лише гальмівний шлях, а й відстань, яку автомобіль проїжджає, поки водій реагує на небезпеку.","ru":"{p:12.2} требует такой скорости, при которой водитель может **остановить** транспортное средство в пределах видимости дороги. Остановочный путь — это не только тормозной путь, но и расстояние, которое автомобиль проезжает, пока водитель реагирует на опасность."},"ref":["12.2"]},{"id":"h12-32","t":"h12","num":"12.32","q":{"uk":"Якою має бути швидкість під час руху в темну пору доби або в умовах недостатньої видимості?","ru":"Какой должна быть скорость при движении в тёмное время суток или в условиях недостаточной видимости?"},"a":[{"uk":"На 10 км/год. нижчою, ніж швидкість, яка встановлена для ділянки дороги, по якій рухається транспортний засіб.","ru":"На 10 км/ч ниже скорости, установленной для участка дороги, по которому движется транспортное средство.","w":{"uk":"Правила не вимагають знижувати швидкість на фіксовані 10 км/год: за поганої видимості часто треба їхати значно повільніше.","ru":"Правила не требуют снижать скорость на фиксированные 10 км/ч: при плохой видимости часто нужно ехать значительно медленнее."}},{"uk":"Такою, щоб водій мав змогу зупинити транспортний засіб у межах видимості дороги.","ru":"Такой, чтобы водитель имел возможность остановить транспортное средство в пределах видимости дороги."},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2.","w":{"uk":"Варіант 1 неправильний: фіксованого зниження на 10 км/год у {p:12.2} немає.","ru":"Вариант 1 неверен: фиксированного снижения на 10 км/ч в {p:12.2} нет."}}],"c":1,"e":{"uk":"За {p:12.2} у темну пору доби та в умовах недостатньої видимості швидкість має бути такою, щоб водій міг **зупинити транспортний засіб у межах видимості дороги**.","ru":"Согласно {p:12.2} в тёмное время суток и в условиях недостаточной видимости скорость должна быть такой, чтобы водитель мог **остановить транспортное средство в пределах видимости дороги**."},"ref":["12.2"]},{"id":"h12-33","t":"h12","num":"12.33","q":{"uk":"З якою максимальною швидкістю дозволено буксирування транспортних засобів?","ru":"С какой максимальной скоростью разрешена буксировка транспортных средств?"},"a":[{"uk":"40 км/год.","ru":"40 км/ч.","w":{"uk":"Обмеження для буксирування — 50 км/год, а не 40 км/год.","ru":"Ограничение при буксировке — 50 км/ч, а не 40 км/ч."}},{"uk":"50 км/год.","ru":"50 км/ч."},{"uk":"60 км/год.","ru":"60 км/ч.","w":{"uk":"60 км/год перевищує граничну швидкість буксирування — 50 км/год.","ru":"60 км/ч превышает предельную скорость буксировки — 50 км/ч."}},{"uk":"70 км/год.","ru":"70 км/ч.","w":{"uk":"70 км/год перевищує граничну швидкість буксирування — 50 км/год.","ru":"70 км/ч превышает предельную скорость буксировки — 50 км/ч."}}],"c":1,"e":{"uk":"За {p:12.7} під час буксирування швидкість не повинна перевищувати **50 км/год** — на будь-якій дорозі й за будь-якого способу буксирування.","ru":"Согласно {p:12.7} при буксировке скорость не должна превышать **50 км/ч** — на любой дороге и при любом способе буксировки."},"ref":["12.7"]},{"id":"h12-34","t":"h12","num":"12.34","q":{"uk":"Як повинен вчинити водій у разі виникнення небезпеки для руху або перешкоди, яку він виявив під час руху?","ru":"Как должен поступить водитель в случае возникновения опасности для движения или препятствия, которое он обнаружил во время движения?"},"a":[{"uk":"Рухатися далі, не змінюючи швидкості, і бути готовим негайно зупинити транспортний засіб.","ru":"Двигаться дальше, не меняя скорости, и быть готовым немедленно остановить транспортное средство.","w":{"uk":"{p:12.3} вимагає діяти негайно, а не продовжувати рух з тією самою швидкістю.","ru":"{p:12.3} требует действовать немедленно, а не продолжать движение с той же скоростью."}},{"uk":"Вжити заходів для зменшення швидкості аж до зупинки транспортного засобу або безпечного для інших учасників руху об'їзду перешкоди.","ru":"Принять меры для снижения скорости вплоть до остановки транспортного средства или безопасного для других участников движения объезда препятствия."},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2.","w":{"uk":"Варіант 1 суперечить {p:12.3}, тому поєднання неправильне.","ru":"Вариант 1 противоречит {p:12.3}, поэтому сочетание неверно."}}],"c":1,"e":{"uk":"Це вимога {p:12.3}: виявивши небезпеку чи перешкоду, водій повинен **негайно** вжити заходів для зменшення швидкості аж до зупинки або безпечно для інших учасників руху об'їхати перешкоду.","ru":"Это требование {p:12.3}: обнаружив опасность или препятствие, водитель должен **немедленно** принять меры для снижения скорости вплоть до остановки или безопасно для других участников движения объехать препятствие."},"ref":["12.3"]},{"id":"h12-35","t":"h12","num":"12.35","q":{"uk":"З якою максимальною швидкістю дозволено рух транспортних засобів, якими керують водії зі стажем до двох років, на всіх дорогах за межами населених пунктів?","ru":"С какой максимальной скоростью разрешено движение транспортных средств, которыми управляют водители со стажем до двух лет, на всех дорогах вне населённых пунктов?"},"a":[{"uk":"60 км/год.","ru":"60 км/ч.","w":{"uk":"60 км/год — обмеження для вантажних автомобілів, що перевозять людей у кузові, і мопедів.","ru":"60 км/ч — ограничение для грузовых автомобилей, перевозящих людей в кузове, и мопедов."}},{"uk":"70 км/год.","ru":"70 км/ч."},{"uk":"80 км/год.","ru":"80 км/ч.","w":{"uk":"80 км/год дозволено легковим автомобілям з причепом, мотоциклам і автобусам з організованими групами дітей, а не водіям-початківцям.","ru":"80 км/ч разрешено легковым автомобилям с прицепом, мотоциклам и автобусам с организованными группами детей, а не начинающим водителям."}},{"uk":"90 км/год.","ru":"90 км/ч.","w":{"uk":"90 км/год — загальне обмеження для звичайних доріг, але для водіїв зі стажем до 2 років воно нижче.","ru":"90 км/ч — общее ограничение для обычных дорог, но для водителей со стажем до 2 лет оно ниже."}},{"uk":"50 км/год.","ru":"50 км/ч.","w":{"uk":"50 км/год — обмеження в населених пунктах, а питання стосується доріг поза ними.","ru":"50 км/ч — ограничение в населённых пунктах, а вопрос касается дорог вне их."}}],"c":1,"e":{"uk":"За {p:12.6} (підпункт «б») транспортним засобам, якими керують водії зі стажем до 2 років, поза населеними пунктами дозволено рух зі швидкістю не більше **70 км/год** — на будь-якій дорозі, зокрема й на автомагістралі.","ru":"Согласно {p:12.6} (подпункт «б») транспортным средствам, которыми управляют водители со стажем до 2 лет, вне населённых пунктов разрешено движение со скоростью не более **70 км/ч** — на любой дороге, в том числе и на автомагистрали."},"ref":["12.6"]},{"id":"h12-36","t":"h12","num":"12.36","q":{"uk":"З якою максимальною швидкістю дозволено рух на дворових територіях?","ru":"С какой максимальной скоростью разрешено движение на дворовых территориях?"},"a":[{"uk":"20 км/год.","ru":"20 км/ч."},{"uk":"40 км/год.","ru":"40 км/ч.","w":{"uk":"40 км/год удвічі перевищує дозволені у дворі 20 км/год.","ru":"40 км/ч вдвое превышает разрешённые во дворе 20 км/ч."}},{"uk":"60 км/год.","ru":"60 км/ч.","w":{"uk":"60 км/год значно перевищує дозволені у дворі 20 км/год.","ru":"60 км/ч значительно превышает разрешённые во дворе 20 км/ч."}},{"uk":"50 км/год.","ru":"50 км/ч.","w":{"uk":"50 км/год — загальне обмеження в населеному пункті, а двір є житловою зоною з межею 20 км/год.","ru":"50 км/ч — общее ограничение в населённом пункте, а двор является жилой зоной с пределом 20 км/ч."}}],"c":0,"e":{"uk":"За {p:1.10} дворові території належать до **житлової зони**, а в житловій зоні швидкість не повинна перевищувати **20 км/год** ({p:12.5}).","ru":"Согласно {p:1.10} дворовые территории относятся к **жилой зоне**, а в жилой зоне скорость не должна превышать **20 км/ч** ({p:12.5})."},"ref":["1.10","12.5"]},{"id":"h12-37","t":"h12","num":"12.37","q":{"uk":"Що для Вас вважається безпечною швидкістю?","ru":"Что для Вас считается безопасной скоростью?"},"a":[{"uk":"Швидкість яка визначена дорожніми знаками для руху в населених пунктах.","ru":"Скорость, которая определена дорожными знаками для движения в населённых пунктах.","w":{"uk":"Знаки задають лише верхню межу; безпечна швидкість може бути значно нижчою — наприклад, на ожеледі чи в тумані.","ru":"Знаки задают лишь верхний предел; безопасная скорость может быть значительно ниже — например, в гололёд или в тумане."}},{"uk":"Швидкість при якій Ви маєте змогу безпечно керувати транспортним засобом та контролювати його рух у конкретних дорожніх умовах.","ru":"Скорость, при которой Вы имеете возможность безопасно управлять транспортным средством и контролировать его движение в конкретных дорожных условиях."},{"uk":"Швидкість яка визначена технічною характеристикою даного транспортного засобу.","ru":"Скорость, которая определена технической характеристикой данного транспортного средства.","w":{"uk":"Технічна максимальна швидкість — межа, яку перевищувати заборонено ({p:12.9}), але вона ніяк не враховує дорожніх умов.","ru":"Техническая максимальная скорость — предел, превышать который запрещено ({p:12.9}), но она никак не учитывает дорожных условий."}}],"c":1,"e":{"uk":"За {p:12.1} безпечну швидкість водій вибирає **в установлених межах**, враховуючи дорожню обстановку, вантаж і стан транспортного засобу, щоб постійно контролювати його рух і безпечно ним керувати.","ru":"Согласно {p:12.1} безопасную скорость водитель выбирает **в установленных пределах**, учитывая дорожную обстановку, груз и состояние транспортного средства, чтобы постоянно контролировать его движение и безопасно им управлять."},"ref":["12.1"]},{"id":"h12-38","t":"h12","num":"12.38","q":{"uk":"Чи дозволено водіям із досвідом водіння понад 5 років перевищувати максимально допустиме обмеження швидкості поза межами населених пунктів?","ru":"Разрешено ли водителям с опытом вождения более 5 лет превышать максимально допустимое ограничение скорости вне населённых пунктов?"},"a":[{"uk":"Так.","ru":"Да.","w":{"uk":"Великий стаж не дає жодних пільг щодо швидкості: обмеження однакові для всіх водіїв зі стажем від 2 років.","ru":"Большой стаж не даёт никаких льгот по скорости: ограничения одинаковы для всех водителей со стажем от 2 лет."}},{"uk":"Ні.","ru":"Нет."}],"c":1,"e":{"uk":"Обмеження {p:12.6} поширюються на всіх водіїв, і перевищувати їх забороняє {p:12.9}. Стаж має значення лише для водіїв зі стажем до 2 років — їм дозволено **менше**, а не досвідченим більше.","ru":"Ограничения {p:12.6} распространяются на всех водителей, и превышать их запрещает {p:12.9}. Стаж имеет значение лишь для водителей со стажем до 2 лет — им разрешено **меньше**, а не опытным больше."},"ref":["12.6","12.9"]},{"id":"h12-39","t":"h12","num":"12.39","q":{"uk":"Максимальна швидкість під час руху у житловій зоні становить 30 км/год?","ru":"Максимальная скорость при движении в жилой зоне составляет 30 км/ч?"},"a":[{"uk":"Так.","ru":"Да.","w":{"uk":"30 км/год Правила для житлової зони не встановлюють — межа становить 20 км/год.","ru":"30 км/ч Правила для жилой зоны не устанавливают — предел составляет 20 км/ч."}},{"uk":"Ні.","ru":"Нет."}],"c":1,"e":{"uk":"На фото знак {s:5.34} «Житлова зона», а в житловій зоні швидкість не повинна перевищувати **20 км/год**, а не 30 ({p:12.5}).","ru":"На фото знак {s:5.34} «Жилая зона», а в жилой зоне скорость не должна превышать **20 км/ч**, а не 30 ({p:12.5})."},"ref":["12.5"],"pic":["img/hsc/12-39-1.jpg"]},{"id":"h12-40","t":"h12","num":"12.40","q":{"uk":"Безпечна швидкість руху – це виключно встановлене обмеження швидкості:","ru":"Безопасная скорость движения — это исключительно установленное ограничение скорости:"},"a":[{"uk":"Так.","ru":"Да.","w":{"uk":"У тумані, на ожеледі чи з важким вантажем безпечна швидкість може бути значно нижчою за встановлене обмеження.","ru":"В тумане, в гололёд или с тяжёлым грузом безопасная скорость может быть значительно ниже установленного ограничения."}},{"uk":"Ні.","ru":"Нет."}],"c":1,"e":{"uk":"Встановлене обмеження — лише верхня межа. За {p:12.1} безпечну швидкість водій вибирає в цих межах з урахуванням дорожньої обстановки, вантажу і стану транспортного засобу, тож вона може бути й нижчою.","ru":"Установленное ограничение — лишь верхний предел. Согласно {p:12.1} безопасную скорость водитель выбирает в этих пределах с учётом дорожной обстановки, груза и состояния транспортного средства, поэтому она может быть и ниже."},"ref":["12.1"]},{"id":"h12-41","t":"h12","num":"12.41","q":{"uk":"Водій транспортного засобу, що рухається зі швидкістю 68 км/год, наближаючись до наведеного дорожнього знака повинен:","ru":"Водитель транспортного средства, движущегося со скоростью 68 км/ч, приближаясь к приведённому дорожному знаку, должен:"},"a":[{"uk":"Зобов'язаний збільшити швидкість, щоб швидкість транспортного засобу становила більше 70 км/год.","ru":"Обязан увеличить скорость, чтобы скорость транспортного средства составляла более 70 км/ч.","w":{"uk":"Знак {s:3.29} встановлює максимальну, а не мінімальну швидкість: рух понад 70 км/год після нього якраз заборонений.","ru":"Знак {s:3.29} устанавливает максимальную, а не минимальную скорость: движение быстрее 70 км/ч после него как раз запрещено."}},{"uk":"Зобов’язаний продовжувати рух з цією ж швидкістю або меншою, але не більшою 70 км/год.","ru":"Обязан продолжать движение с этой же скоростью или меньшей, но не более 70 км/ч."}],"c":1,"e":{"uk":"Знак {s:3.29} «Обмеження максимальної швидкості» з числом 70 лише забороняє рух зі швидкістю понад 70 км/год ({p:12.9}). 68 км/год у межах обмеження, тож водій може їхати так само чи повільніше, не перевищуючи 70 км/год.","ru":"Знак {s:3.29} «Ограничение максимальной скорости» с числом 70 лишь запрещает движение со скоростью более 70 км/ч ({p:12.9}). 68 км/ч — в пределах ограничения, поэтому водитель может ехать так же или медленнее, не превышая 70 км/ч."},"ref":["12.9","33.3"],"pic":["img/hsc/12-41-1.jpg"]},{"id":"h13-1","t":"h13","num":"13.1","q":{"uk":"Що вважається безпечною дистанцією?","ru":"Что считается безопасной дистанцией?"},"a":[{"uk":"Відстань між транспортними засобами, що рухаються по суміжних смугах в попутному напрямку.","ru":"Расстояние между транспортными средствами, движущимися по смежным полосам в попутном направлении.","w":{"uk":"Відстань між автомобілями на суміжних смугах — це інтервал, а не дистанція.","ru":"Расстояние между автомобилями на соседних полосах — это интервал, а не дистанция."}},{"uk":"Відстань до транспортного засобу, що рухається тією ж самою смугою, яка складає 30 м.","ru":"Расстояние до транспортного средства, движущегося по той же полосе, составляющее 30 м.","w":{"uk":"Правила не встановлюють фіксованої безпечної дистанції: вона залежить від швидкості, дорожньої обстановки, вантажу і стану транспортного засобу ({p:13.1}).","ru":"Правила не устанавливают фиксированной безопасной дистанции: она зависит от скорости, дорожной обстановки, груза и состояния транспортного средства ({p:13.1})."}},{"uk":"Відстань до транспортного засобу, що рухається попереду тією ж смугою, яка у разі його раптового гальмування або зупинки дасть можливість водієві транспортного засобу, що рухається позаду, запобігти зіткненню без здійснення будь-якого маневру.","ru":"Расстояние до транспортного средства, движущегося впереди по той же полосе, которое при его внезапном торможении или остановке позволит водителю транспортного средства, движущегося сзади, предотвратить столкновение без выполнения какого-либо манёвра."}],"c":2,"e":{"uk":"Це дослівне визначення **безпечної дистанції** з {p:1.10}: її вимірюють до транспортного засобу попереду на тій самій смузі, і вона має дозволити уникнути зіткнення без маневру, якщо той раптово загальмує.","ru":"Это дословное определение **безопасной дистанции** из {p:1.10}: её измеряют до транспортного средства впереди на той же полосе, и она должна позволить избежать столкновения без манёвра, если оно внезапно затормозит."},"ref":["1.10","13.1"],"pic":["img/hsc/13-1-1.jpg"]},{"id":"h13-2","t":"h13","num":"13.2","q":{"uk":"Водій якого автомобіля має перевагу на цій ділянці дороги?","ru":"Водитель какого автомобиля имеет преимущество на этом участке дороги?"},"a":[{"uk":"Червоного автомобіля.","ru":"Красного автомобиля.","w":{"uk":"Перешкода на смузі червоного автомобіля, тому саме він повинен дати дорогу зустрічному синьому.","ru":"Препятствие на полосе красного автомобиля, поэтому именно он должен уступить дорогу встречному синему."}},{"uk":"Синього автомобіля.","ru":"Синего автомобиля."}],"c":1,"e":{"uk":"Яма знаходиться на смузі червоного автомобіля, тож зустрічний роз'їзд утруднений саме для нього — за {p:13.4} дорогу дає водій, на смузі якого перешкода, отже перевагу має синій.","ru":"Яма находится на полосе красного автомобиля, поэтому встречный разъезд затруднён именно для него — по {p:13.4} уступает дорогу водитель, на полосе которого препятствие, значит преимущество у синего."},"ref":["13.4"],"pic":["img/hsc/13-2-1.jpg"]},{"id":"h13-3","t":"h13","num":"13.3","q":{"uk":"Водій якого транспортного засобу повинен дати дорогу під час зустрічного роз'їзду на цій ділянці?","ru":"Водитель какого транспортного средства должен уступить дорогу при встречном разъезде на этом участке?"},"a":[{"uk":"Водій синього автомобіля, тому що на його боці є перешкода.","ru":"Водитель синего автомобиля, потому что на его стороне есть препятствие.","w":{"uk":"Загальне правило «дає дорогу той, на чиїй смузі перешкода» на крутому підйомі/спуску не діє: тут поступається той, хто їде на спуск.","ru":"Общее правило «уступает тот, на чьей полосе препятствие» на крутом подъёме/спуске не действует: здесь уступает тот, кто едет на спуск."}},{"uk":"Водій білого, тому що він рухається на спуск.","ru":"Водитель белого, потому что он движется на спуск."}],"c":1,"e":{"uk":"Ділянку позначено знаками {s:1.6} і {s:1.7}: синій їде на підйом, білий — на спуск. На таких ділянках за наявності перешкоди дорогу дає водій, що рухається **на спуск**, незалежно від того, на чиїй смузі перешкода ({p:13.4}).","ru":"Участок обозначен знаками {s:1.6} и {s:1.7}: синий едет на подъём, белый — на спуск. На таких участках при наличии препятствия уступает дорогу водитель, движущийся **на спуск**, независимо от того, на чьей полосе препятствие ({p:13.4})."},"ref":["13.4"],"pic":["img/hsc/13-3-1.jpg"]},{"id":"h13-4","t":"h13","num":"13.4","q":{"uk":"Чи може водій синього автомобіля продовжити рух, не чекаючи проїзду червоного автомобіля, якщо перешкода на його боці?","ru":"Может ли водитель синего автомобиля продолжить движение, не дожидаясь проезда красного автомобиля, если препятствие на его стороне?"},"a":[{"uk":"Може.","ru":"Может.","w":{"uk":"Об'їжджаючи перешкоду на своїй смузі, синій виїде на смугу зустрічного червоного, якому за {p:13.4} зобов'язаний дати дорогу.","ru":"Объезжая препятствие на своей полосе, синий выедет на полосу встречного красного, которому по {p:13.4} обязан уступить дорогу."}},{"uk":"Не може, синій автомобіль повинен дати дорогу.","ru":"Не может, синий автомобиль должен уступить дорогу."}],"c":1,"e":{"uk":"Перешкода (огороджена яма) на смузі синього автомобіля, тому зустрічний роз'їзд утруднений для нього, і за {p:13.4} він повинен дати дорогу червоному, а вже потім об'їжджати перешкоду.","ru":"Препятствие (огороженная яма) на полосе синего автомобиля, поэтому встречный разъезд затруднён для него, и по {p:13.4} он должен уступить дорогу красному, а уже потом объезжать препятствие."},"ref":["13.4"],"pic":["img/hsc/13-4-1.jpg"]},{"id":"h13-5","t":"h13","num":"13.5","q":{"uk":"Хто з водіїв повинен дати дорогу?","ru":"Кто из водителей должен уступить дорогу?"},"a":[{"uk":"Водій, який рухається з меншою швидкістю.","ru":"Водитель, движущийся с меньшей скоростью.","w":{"uk":"Швидкість руху не визначає черговості зустрічного роз'їзду — вирішує, на чиїй смузі перешкода.","ru":"Скорость движения не определяет очерёдность встречного разъезда — решает, на чьей полосе препятствие."}},{"uk":"Водій, на смузі якого є перешкода.","ru":"Водитель, на полосе которого есть препятствие."},{"uk":"Водій, на смузі якого немає перешкод.","ru":"Водитель, на полосе которого нет препятствий.","w":{"uk":"Водій, на смузі якого немає перешкоди, навпаки має перевагу, і йому повинні дати дорогу.","ru":"Водитель, на полосе которого нет препятствия, наоборот, имеет преимущество, и ему должны уступить дорогу."}}],"c":1,"e":{"uk":"Якщо зустрічний роз'їзд утруднений, дорогу дає водій, на смузі руху якого є перешкода ({p:13.4}) — тут це синій автомобіль, бо огороджена яма на його смузі.","ru":"Если встречный разъезд затруднён, уступает дорогу водитель, на полосе движения которого есть препятствие ({p:13.4}) — здесь это синий автомобиль, так как огороженная яма на его полосе."},"ref":["13.4"],"pic":["img/hsc/13-5-1.jpg"]},{"id":"h13-6","t":"h13","num":"13.6","q":{"uk":"Яка дистанція повинна бути між тракторами, що рухаються за межами населених пунктів, якщо їх швидкість не перевищує 40 км/год.?","ru":"Какой должна быть дистанция между тракторами, движущимися за пределами населённых пунктов, если их скорость не превышает 40 км/ч?"},"a":[{"uk":"Дистанція повинна бути 2 – 3 м.","ru":"Дистанция должна быть 2–3 м.","w":{"uk":"Дистанція 2–3 м не дасть транспортному засобу, що обганяє, повернутися між тракторами на свою смугу, до того ж Правила не встановлюють таких цифр.","ru":"Дистанция 2–3 м не позволит обгоняющему транспортному средству вернуться между тракторами на свою полосу, к тому же Правила не устанавливают таких цифр."}},{"uk":"Дистанція повинна бути обрана залежно від дорожньої обстановки.","ru":"Дистанция должна выбираться в зависимости от дорожной обстановки.","w":{"uk":"Для тихохідних транспортних засобів поза населеними пунктами {p:13.2} встановлює конкретну вимогу — дистанцію, достатню для повернення після обгону.","ru":"Для тихоходных транспортных средств вне населённых пунктов {p:13.2} устанавливает конкретное требование — дистанцию, достаточную для возвращения после обгона."}},{"uk":"Дистанція повинна бути такою, щоб транспортні засоби, які виконують обгін, мали змогу безперешкодно повернутися на раніше займану смугу руху.","ru":"Дистанция должна быть такой, чтобы транспортные средства, выполняющие обгон, имели возможность беспрепятственно вернуться на ранее занимаемую полосу движения."}],"c":2,"e":{"uk":"Для транспортних засобів, швидкість яких не перевищує 40 км/год, поза населеними пунктами {p:13.2} вимагає такої дистанції, щоб ті, хто їх обганяє, могли безперешкодно повернутися на раніше займану смугу — тобто між тракторами має залишатися «вікно» для обгону.","ru":"Для транспортных средств, скорость которых не превышает 40 км/ч, вне населённых пунктов {p:13.2} требует такой дистанции, чтобы обгоняющие могли беспрепятственно вернуться на ранее занимаемую полосу — то есть между тракторами должно оставаться «окно» для обгона."},"ref":["13.2"],"pic":["img/hsc/13-6-1.jpg"]},{"id":"h13-7","t":"h13","num":"13.7","q":{"uk":"Що вважається безпечним інтервалом?","ru":"Что считается безопасным интервалом?"},"a":[{"uk":"Відстань між боковими частинами транспортних засобів, що рухаються назустріч крайніми лівими смугами.","ru":"Расстояние между боковыми частями транспортных средств, движущихся навстречу друг другу по крайним левым полосам.","w":{"uk":"Інтервал стосується не лише зустрічних автомобілів у лівих смугах, а будь-яких транспортних засобів та інших об'єктів поруч, і має гарантувати безпеку руху.","ru":"Интервал касается не только встречных автомобилей в левых полосах, а любых транспортных средств и других объектов рядом, и должен гарантировать безопасность движения."}},{"uk":"Відстань між боковими частинами транспортних засобів, що рухаються в попутному напрямку.","ru":"Расстояние между боковыми частями транспортных средств, движущихся в попутном направлении.","w":{"uk":"Інтервал потрібен і до зустрічних транспортних засобів та інших об'єктів, а головне — він має бути таким, щоб гарантувати безпеку руху.","ru":"Интервал нужен и до встречных транспортных средств и других объектов, а главное — он должен быть таким, чтобы гарантировать безопасность движения."}},{"uk":"Відстань між боковими частинами транспортних засобів, що рухаються, або між ними та іншими об'єктами, за якої гарантована безпека дорожнього руху.","ru":"Расстояние между боковыми частями движущихся транспортных средств или между ними и другими объектами, при котором гарантирована безопасность дорожного движения."}],"c":2,"e":{"uk":"Це визначення **безпечного інтервалу** з {p:1.10}: бічна відстань до будь-якого транспортного засобу (попутного чи зустрічного) або іншого об'єкта, за якої гарантована безпека руху.","ru":"Это определение **безопасного интервала** из {p:1.10}: боковое расстояние до любого транспортного средства (попутного или встречного) или другого объекта, при котором гарантирована безопасность движения."},"ref":["1.10","13.3"],"pic":["img/hsc/13-7-1.jpg"]},{"id":"h13-8","t":"h13","num":"13.8","q":{"uk":"Яким правилом повинні керуватися водії в разі обмеженого зустрічного роз'їзду на ділянках доріг, позначених знаками «Крутий підйом» і «Крутий спуск»?","ru":"Каким правилом должны руководствоваться водители при затруднённом встречном разъезде на участках дорог, обозначенных знаками «Крутой подъём» и «Крутой спуск»?"},"a":[{"uk":"Водій, на смузі руху якого є перешкода, повинен дати дорогу.","ru":"Водитель, на полосе движения которого есть препятствие, должен уступить дорогу.","w":{"uk":"Це загальне правило зустрічного роз'їзду, але на крутому підйомі/спуску діє спеціальне: поступається той, хто їде на спуск.","ru":"Это общее правило встречного разъезда, но на крутом подъёме/спуске действует специальное: уступает тот, кто едет на спуск."}},{"uk":"Водій транспортного засобу, габарити якого заважають зустрічному роз'їзду, повинен дати дорогу.","ru":"Водитель транспортного средства, габариты которого мешают встречному разъезду, должен уступить дорогу.","w":{"uk":"Це також загальне правило; на ділянках зі знаками {s:1.6} і {s:1.7} черговість визначає напрямок руху — на спуск чи на підйом.","ru":"Это тоже общее правило; на участках со знаками {s:1.6} и {s:1.7} очерёдность определяет направление движения — на спуск или на подъём."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2.","w":{"uk":"Обидва загальні правила на крутому підйомі/спуску поступаються спеціальному: дорогу дає водій, що рухається на спуск.","ru":"Оба общих правила на крутом подъёме/спуске уступают специальному: дорогу уступает водитель, движущийся на спуск."}},{"uk":"Водій транспортного засобу, що рухається на спуск, повинен дати дорогу.","ru":"Водитель транспортного средства, движущегося на спуск, должен уступить дорогу."}],"c":3,"e":{"uk":"На ділянках, позначених знаками {s:1.6} і {s:1.7}, за наявності перешкоди дорогу дає водій, що рухається **на спуск** ({p:13.4}) — тому, хто їде на підйом, важче зупинитися і знову рушити.","ru":"На участках, обозначенных знаками {s:1.6} и {s:1.7}, при наличии препятствия уступает дорогу водитель, движущийся **на спуск** ({p:13.4}) — тому, кто едет на подъём, труднее остановиться и снова тронуться."},"ref":["13.4"],"pic":["img/hsc/13-8-1.jpg"]},{"id":"h13-9","t":"h13","num":"13.9","q":{"uk":"Під час виконання яких маневрів водій повинен дотримуватися безпечного інтервалу?","ru":"При выполнении каких манёвров водитель должен соблюдать безопасный интервал?"},"a":[{"uk":"Під час обгону.","ru":"При обгоне.","w":{"uk":"Обгін — лише один із чотирьох маневрів, названих у {p:13.3}.","ru":"Обгон — лишь один из четырёх манёвров, названных в {p:13.3}."}},{"uk":"Під час випередження.","ru":"При опережении.","w":{"uk":"Випередження — лише один із чотирьох маневрів, названих у {p:13.3}.","ru":"Опережение — лишь один из четырёх манёвров, названных в {p:13.3}."}},{"uk":"Під час об'їзду перешкоди.","ru":"При объезде препятствия.","w":{"uk":"Об'їзд перешкоди — лише один із чотирьох маневрів, названих у {p:13.3}.","ru":"Объезд препятствия — лишь один из четырёх манёвров, названных в {p:13.3}."}},{"uk":"Під час зустрічного роз'їзду.","ru":"При встречном разъезде.","w":{"uk":"Зустрічний роз'їзд — лише один із чотирьох маневрів, названих у {p:13.3}.","ru":"Встречный разъезд — лишь один из четырёх манёвров, названных в {p:13.3}."}},{"uk":"Відповіді 1, 2, 3 і 4.","ru":"Ответы 1, 2, 3 и 4."}],"c":4,"e":{"uk":"{p:13.3} прямо перелічує всі чотири випадки: під час обгону, випередження, об'їзду перешкоди чи зустрічного роз'їзду необхідно дотримувати безпечного інтервалу.","ru":"{p:13.3} прямо перечисляет все четыре случая: во время обгона, опережения, объезда препятствия или встречного разъезда необходимо соблюдать безопасный интервал."},"ref":["13.3"]},{"id":"h13-10","t":"h13","num":"13.10","q":{"uk":"Якої дистанції повинні дотримуватися водії транспортних засобів, швидкість яких не перевищує 40 км/год. поза населеними пунктами?","ru":"Какую дистанцию должны соблюдать вне населённых пунктов водители транспортных средств, скорость которых не превышает 40 км/ч?"},"a":[{"uk":"З такою, за якої неможливий наїзд ззаду.","ru":"Такую, при которой невозможен наезд сзади.","w":{"uk":"Дистанція, що лише виключає наїзд ззаду, — це звичайна безпечна дистанція; для тихохідних транспортних засобів поза населеними пунктами вимога інша і більша.","ru":"Дистанция, лишь исключающая наезд сзади, — это обычная безопасная дистанция; для тихоходных транспортных средств вне населённых пунктов требование другое и бóльшее."}},{"uk":"З будь-якою, на розсуд водія.","ru":"Любую, на усмотрение водителя.","w":{"uk":"Дистанцію не можна обирати довільно: {p:13.2} встановлює для цього випадку конкретну вимогу.","ru":"Дистанцию нельзя выбирать произвольно: {p:13.2} устанавливает для этого случая конкретное требование."}},{"uk":"Такої дистанції, щоб транспортні засоби, які виконують обгін, мали змогу безперешкодно повернутися на раніше займану смугу руху.","ru":"Такую дистанцию, чтобы транспортные средства, выполняющие обгон, имели возможность беспрепятственно вернуться на ранее занимаемую полосу движения."}],"c":2,"e":{"uk":"Саме цього вимагає {p:13.2}: поза населеними пунктами тихохідні транспортні засоби (до 40 км/год) мають тримати дистанцію, достатню, щоб ті, хто їх обганяє, могли безперешкодно повернутися на свою смугу.","ru":"Именно этого требует {p:13.2}: вне населённых пунктов тихоходные транспортные средства (до 40 км/ч) должны держать дистанцию, достаточную, чтобы обгоняющие могли беспрепятственно вернуться на свою полосу."},"ref":["13.2"]},{"id":"h13-11","t":"h13","num":"13.11","q":{"uk":"Що повинен враховувати водій під час вибору безпечної дистанції та інтервалу?","ru":"Что должен учитывать водитель при выборе безопасной дистанции и интервала?"},"a":[{"uk":"Швидкість руху.","ru":"Скорость движения.","w":{"uk":"Швидкість — лише один із чотирьох чинників, названих у {p:13.1}.","ru":"Скорость — лишь один из четырёх факторов, названных в {p:13.1}."}},{"uk":"Дорожню обстановку.","ru":"Дорожную обстановку.","w":{"uk":"Дорожня обстановка — лише один із чотирьох чинників, названих у {p:13.1}.","ru":"Дорожная обстановка — лишь один из четырёх факторов, названных в {p:13.1}."}},{"uk":"Особливості вантажу, що перевозиться.","ru":"Особенности перевозимого груза.","w":{"uk":"Особливості вантажу — лише один із чотирьох чинників, названих у {p:13.1}.","ru":"Особенности груза — лишь один из четырёх факторов, названных в {p:13.1}."}},{"uk":"Стан транспортного засобу.","ru":"Состояние транспортного средства.","w":{"uk":"Стан транспортного засобу — лише один із чотирьох чинників, названих у {p:13.1}.","ru":"Состояние транспортного средства — лишь один из четырёх факторов, названных в {p:13.1}."}},{"uk":"Відповіді 1, 2, 3 і 4.","ru":"Ответы 1, 2, 3 и 4."}],"c":4,"e":{"uk":"За {p:13.1} водій обирає безпечну дистанцію та інтервал залежно від швидкості руху, дорожньої обстановки, особливостей вантажу і стану транспортного засобу — тобто враховує всі чотири чинники.","ru":"По {p:13.1} водитель выбирает безопасную дистанцию и интервал в зависимости от скорости движения, дорожной обстановки, особенностей груза и состояния транспортного средства — то есть учитывает все четыре фактора."},"ref":["13.1"]},{"id":"h13-12","t":"h13","num":"13.12","q":{"uk":"Ви на ділянці дороги, позначеній знаком «Крутий підйом», на Вашій смузі нерухома перешкода, що утруднює зустрічний роз'їзд. Як Вам виконати роз'їзд із зустрічним автомобілем, що рухається на спуск?","ru":"Вы на участке дороги, обозначенном знаком «Крутой подъём», на Вашей полосе неподвижное препятствие, затрудняющее встречный разъезд. Как Вам выполнить разъезд со встречным автомобилем, движущимся на спуск?"},"a":[{"uk":"Дати дорогу зустрічному автомобілю, який рухається на спуск.","ru":"Уступить дорогу встречному автомобилю, движущемуся на спуск.","w":{"uk":"Навпаки, водій, що рухається на спуск, повинен дати дорогу Вам, бо Ви їдете на підйом.","ru":"Наоборот, водитель, движущийся на спуск, должен уступить дорогу Вам, так как Вы едете на подъём."}},{"uk":"Дати дорогу зустрічному автомобілю, так як перешкода на Вашій смузі","ru":"Уступить дорогу встречному автомобилю, так как препятствие на Вашей полосе.","w":{"uk":"Правило «дає дорогу той, на чиїй смузі перешкода» тут не застосовується: на крутому підйомі/спуску поступається той, хто їде на спуск.","ru":"Правило «уступает тот, на чьей полосе препятствие» здесь не применяется: на крутом подъёме/спуске уступает тот, кто едет на спуск."}},{"uk":"Проїхати першим, оскільки Ви маєте перевагу перед автомобілем, що їде на спуск.","ru":"Проехать первым, так как Вы имеете преимущество перед автомобилем, движущимся на спуск."}],"c":2,"e":{"uk":"На ділянках зі знаками {s:1.6} і {s:1.7} за наявності перешкоди дорогу дає водій, що рухається **на спуск** ({p:13.4}). Ви їдете на підйом, тож проїжджаєте першим, хоча перешкода на Вашій смузі.","ru":"На участках со знаками {s:1.6} и {s:1.7} при наличии препятствия уступает дорогу водитель, движущийся **на спуск** ({p:13.4}). Вы едете на подъём, поэтому проезжаете первым, хотя препятствие на Вашей полосе."},"ref":["13.4"]},{"id":"h13-13","t":"h13","num":"13.13","q":{"uk":"Яким правилом повинні керуватися водії під час зустрічного роз'їзду в місцях, де він утруднений?","ru":"Каким правилом должны руководствоваться водители при встречном разъезде в местах, где он затруднён?"},"a":[{"uk":"Водій, на смузі руху якого є перешкода, повинен дати дорогу.","ru":"Водитель, на полосе движения которого есть препятствие, должен уступить дорогу."},{"uk":"Водій, який під'їхав першим, має перевагу.","ru":"Водитель, подъехавший первым, имеет преимущество.","w":{"uk":"Правила не дають переваги тому, хто під'їхав першим: черговість визначає, на чиїй смузі перешкода.","ru":"Правила не дают преимущества тому, кто подъехал первым: очерёдность определяется тем, на чьей полосе препятствие."}},{"uk":"Правильні відповіді 1 і 2.","ru":"Правильные ответы 1 и 2.","w":{"uk":"Варіант 2 неправильний — моменту під'їзду Правила значення не надають, тож комбінація теж хибна.","ru":"Вариант 2 неверен — моменту подъезда Правила значения не придают, поэтому и комбинация неверна."}}],"c":0,"e":{"uk":"Якщо зустрічний роз'їзд утруднений, дорогу дає водій, на смузі руху якого є перешкода (або габарити транспортного засобу якого заважають зустрічному руху) — {p:13.4}.","ru":"Если встречный разъезд затруднён, уступает дорогу водитель, на полосе движения которого есть препятствие (или габариты транспортного средства которого мешают встречному движению) — {p:13.4}."},"ref":["13.4"]},{"id":"h14-1","t":"h14","num":"14.1","q":{"uk":"На якому з малюнків показаний обгін?","ru":"На каком из рисунков показан обгон?"},"a":[{"uk":"На першому.","ru":"На первом."},{"uk":"На другому.","ru":"На втором.","w":{"uk":"На другому малюнку червоний автомобіль не виїжджає на зустрічну смугу, а рухається суміжною смугою попутного напрямку, тож це випередження, а не обгін.","ru":"На втором рисунке красный автомобиль не выезжает на встречную полосу, а движется по соседней полосе попутного направления, поэтому это опережение, а не обгон."}},{"uk":"На обох.","ru":"На обоих.","w":{"uk":"Обгін показано лише на першому малюнку; на другому — випередження без виїзду на зустрічну смугу.","ru":"Обгон показан только на первом рисунке; на втором — опережение без выезда на встречную полосу."}}],"c":0,"e":{"uk":"Обгін за {p:1.10} — випередження, пов'язане з **виїздом на смугу зустрічного руху**. На першому малюнку червоний автомобіль виїжджає на зустрічну смугу, щоб випередити синій, — це обгін. На другому він випереджає синій суміжною смугою свого напрямку (зустрічна проїзна частина відокремлена розділювальною смугою) — це лише випередження.","ru":"Обгон согласно {p:1.10} — опережение, связанное с **выездом на полосу встречного движения**. На первом рисунке красный автомобиль выезжает на встречную полосу, чтобы опередить синий, — это обгон. На втором он опережает синий по соседней полосе своего направления (встречная проезжая часть отделена разделительной полосой) — это лишь опережение."},"ref":["1.10"],"pic":["img/hsc/14-1-1.jpg"]},{"id":"h14-2","t":"h14","num":"14.2","q":{"uk":"У якому випадку водій білого автомобіля правильно виконав обгін перед залізничним переїздом?","ru":"В каком случае водитель белого автомобиля правильно выполнил обгон перед железнодорожным переездом?"},"a":[{"uk":"Якщо завершив обгін до залізничного переїзду.","ru":"Если завершил обгон до железнодорожного переезда.","w":{"uk":"Завершивши обгін безпосередньо перед переїздом, водій виконував його в 100-метровій зоні, де обгін заборонено.","ru":"Завершив обгон непосредственно перед переездом, водитель выполнял его в 100-метровой зоне, где обгон запрещён."}},{"uk":"Якщо завершив обгін за 50 м до переїзду.","ru":"Если завершил обгон за 50 м до переезда.","w":{"uk":"50 м стосуються пішохідних переходів у населеному пункті; перед залізничним переїздом заборонена зона становить 100 м.","ru":"50 м относятся к пешеходным переходам в населённом пункте; перед железнодорожным переездом запрещённая зона составляет 100 м."}},{"uk":"Якщо завершив обгін за 100 м до переїзду.","ru":"Если завершил обгон за 100 м до переезда."}],"c":2,"e":{"uk":"{p:14.6} (підпункт «б») забороняє обгін на залізничних переїздах і **ближче ніж за 100 м** перед ними, тож обгін треба завершити не пізніше ніж за 100 м до переїзду.","ru":"{p:14.6} (подпункт «б») запрещает обгон на железнодорожных переездах и **ближе чем за 100 м** перед ними, поэтому обгон нужно завершить не позднее чем за 100 м до переезда."},"ref":["14.6"],"pic":["img/hsc/14-2-1.jpg"]},{"id":"h14-3","t":"h14","num":"14.3","q":{"uk":"Як в цій ситуації вчинити водієві червоного автомобіля, для того щоб обігнати великогабаритний вантажний автомобіль?","ru":"Как в этой ситуации поступить водителю красного автомобиля, для того чтобы обогнать крупногабаритный грузовой автомобиль?"},"a":[{"uk":"Виконати обгін в цьому місці, якщо вантажівка рухається зі швидкістю менше ніж 30 км/год.","ru":"Выполнить обгон в этом месте, если грузовик движется со скоростью менее 30 км/ч.","w":{"uk":"Виняток для транспортних засобів, що рухаються повільніше ніж 30 км/год, стосується знака {s:3.25}, а не заборони обгону перед залізничним переїздом.","ru":"Исключение для транспортных средств, движущихся медленнее 30 км/ч, относится к знаку {s:3.25}, а не к запрету обгона перед железнодорожным переездом."}},{"uk":"Виконати обгін в цьому місці, дотримуючись особливої обережності.","ru":"Выполнить обгон в этом месте, соблюдая особую осторожность.","w":{"uk":"Заборона {p:14.6} безумовна: особлива обережність не робить обгін перед переїздом дозволеним.","ru":"Запрет {p:14.6} безусловный: особая осторожность не делает обгон перед переездом разрешённым."}},{"uk":"Виконати обгін за залізничним переїздом.","ru":"Выполнить обгон за железнодорожным переездом."}],"c":2,"e":{"uk":"Червоний автомобіль уже проїхав знаки, що попереджають про залізничний переїзд, і перебуває безпосередньо перед ним. Обгін на переїзді та ближче ніж за 100 м перед ним заборонено ({p:14.6}), тому обганяти вантажівку можна лише після переїзду.","ru":"Красный автомобиль уже проехал знаки, предупреждающие о железнодорожном переезде, и находится непосредственно перед ним. Обгон на переезде и ближе чем за 100 м перед ним запрещён ({p:14.6}), поэтому обгонять грузовик можно только после переезда."},"ref":["14.6"],"pic":["img/hsc/14-3-1.jpg"]},{"id":"h14-4","t":"h14","num":"14.4","q":{"uk":"Чи може водій виконати обгін після проїзду цих знаків?","ru":"Может ли водитель выполнить обгон после проезда этих знаков?"},"a":[{"uk":"Не може.","ru":"Не может.","w":{"uk":"Самі знаки обгону не забороняють; заборонена лише ділянка ближче ніж за 100 м до переїзду.","ru":"Сами знаки обгон не запрещают; запрещён лишь участок ближе чем за 100 м до переезда."}},{"uk":"Може за умови, що обгін буде завершено за 100 м до переїзду.","ru":"Может при условии, что обгон будет завершён за 100 м до переезда."},{"uk":"Може в будь-якому випадку.","ru":"Может в любом случае.","w":{"uk":"Ближче ніж за 100 м до переїзду обгін заборонено, тож дозволити його «в будь-якому випадку» не можна.","ru":"Ближе чем за 100 м до переезда обгон запрещён, поэтому разрешить его «в любом случае» нельзя."}}],"c":1,"e":{"uk":"Це перші знаки про наближення до залізничного переїзду з табличками {s:1.31.1} і {s:1.31.4}; поза населеним пунктом їх встановлюють за 150–300 м до переїзду. Обгін заборонено лише на переїзді та ближче ніж за 100 м перед ним ({p:14.6}), тож після цих знаків його можна виконати, якщо завершити не пізніше ніж за 100 м до переїзду.","ru":"Это первые знаки о приближении к железнодорожному переезду с табличками {s:1.31.1} и {s:1.31.4}; вне населённого пункта их устанавливают за 150–300 м до переезда. Обгон запрещён только на переезде и ближе чем за 100 м перед ним ({p:14.6}), поэтому после этих знаков его можно выполнить, если завершить не позднее чем за 100 м до переезда."},"ref":["14.6","33.1"],"pic":["img/hsc/14-4-1.jpg"]},{"id":"h14-5","t":"h14","num":"14.5","q":{"uk":"Чи дозволено в цій ситуації водієві синього автомобіля виконати обгін білого автомобіля?","ru":"Разрешено ли в этой ситуации водителю синего автомобиля выполнить обгон белого автомобиля?"},"a":[{"uk":"Заборонено, якщо швидкість білого автомобіля вище 30 км/год.","ru":"Запрещено, если скорость белого автомобиля выше 30 км/ч.","w":{"uk":"Виняток «менше 30 км/год» стосується знака {s:3.25}; тут обгін дозволено за будь-якої швидкості білого автомобіля.","ru":"Исключение «менее 30 км/ч» относится к знаку {s:3.25}; здесь обгон разрешён при любой скорости белого автомобиля."}},{"uk":"Заборонено в будь-якому випадку.","ru":"Запрещено в любом случае.","w":{"uk":"Заборонна зона розташована лише перед переїздом; після нього обгін дозволено.","ru":"Запрещённая зона расположена только перед переездом; после него обгон разрешён."}},{"uk":"Дозволено.","ru":"Разрешено."},{"uk":"Дозволено через 100 м.","ru":"Разрешено через 100 м.","w":{"uk":"100 м відлічують перед переїздом, а не після нього; одразу за переїздом обгін уже дозволено.","ru":"100 м отсчитывают перед переездом, а не после него; сразу за переездом обгон уже разрешён."}}],"c":2,"e":{"uk":"Автомобілі вже проїхали залізничний переїзд. {p:14.6} забороняє обгін на переїзді та ближче ніж за 100 м **перед** ним, а після переїзду такої заборони немає, тож синій може обганяти, дотримавшись умов {p:14.2}.","ru":"Автомобили уже проехали железнодорожный переезд. {p:14.6} запрещает обгон на переезде и ближе чем за 100 м **перед** ним, а после переезда такого запрета нет, поэтому синий может обгонять, соблюдая условия {p:14.2}."},"ref":["14.2","14.6"],"pic":["img/hsc/14-5-1.jpg"]},{"id":"h14-6","t":"h14","num":"14.6","q":{"uk":"Чи дозволено обгін у даній ситуації?","ru":"Разрешён ли обгон в данной ситуации?"},"a":[{"uk":"Дозволено.","ru":"Разрешён.","w":{"uk":"У населеному пункті обгін у межах 50 м перед пішохідним переходом заборонено.","ru":"В населённом пункте обгон в пределах 50 м перед пешеходным переходом запрещён."}},{"uk":"Дозволено за умови, що швидкість автомобіля, який рухається попереду, менше 30 км/год.","ru":"Разрешён при условии, что скорость автомобиля, движущегося впереди, менее 30 км/ч.","w":{"uk":"Виняток для повільних (до 30 км/год) транспортних засобів передбачено лише для знака {s:3.25}, а не для заборони перед пішохідним переходом.","ru":"Исключение для медленных (до 30 км/ч) транспортных средств предусмотрено только для знака {s:3.25}, а не для запрета перед пешеходным переходом."}},{"uk":"Заборонено.","ru":"Запрещён."}],"c":2,"e":{"uk":"У населеному пункті обгін заборонено ближче ніж за 50 м перед пішохідним переходом ({p:14.6}, підпункт «в»). Червоний автомобіль уже на межі цієї ділянки, тож обгін довелося б виконувати в забороненій зоні.","ru":"В населённом пункте обгон запрещён ближе чем за 50 м перед пешеходным переходом ({p:14.6}, подпункт «в»). Красный автомобиль уже на границе этого участка, поэтому обгон пришлось бы выполнять в запрещённой зоне."},"ref":["14.6"],"pic":["img/hsc/14-6-1.jpg"]},{"id":"h14-7","t":"h14","num":"14.7","q":{"uk":"Чи дозволено обгін у даній дорожній ситуації?","ru":"Разрешён ли обгон в данной дорожной ситуации?"},"a":[{"uk":"Дозволено.","ru":"Разрешён.","w":{"uk":"Поза населеним пунктом обгін у межах 100 м перед пішохідним переходом заборонено.","ru":"Вне населённого пункта обгон в пределах 100 м перед пешеходным переходом запрещён."}},{"uk":"Дозволено за умови, що швидкість автомобіля, який рухається попереду, менше 30 км/год.","ru":"Разрешён при условии, что скорость автомобиля, движущегося впереди, менее 30 км/ч.","w":{"uk":"Виняток для повільних (до 30 км/год) транспортних засобів передбачено лише для знака {s:3.25}, а не для заборони перед пішохідним переходом.","ru":"Исключение для медленных (до 30 км/ч) транспортных средств предусмотрено только для знака {s:3.25}, а не для запрета перед пешеходным переходом."}},{"uk":"Заборонено.","ru":"Запрещён."}],"c":2,"e":{"uk":"Поза населеним пунктом обгін заборонено ближче ніж за **100 м** перед пішохідним переходом ({p:14.6}, підпункт «в»), а червоний автомобіль уже на межі цієї зони.","ru":"Вне населённого пункта обгон запрещён ближе чем за **100 м** перед пешеходным переходом ({p:14.6}, подпункт «в»), а красный автомобиль уже на границе этой зоны."},"ref":["14.6"],"pic":["img/hsc/14-7-1.jpg"]},{"id":"h14-8","t":"h14","num":"14.8","q":{"uk":"Чи дозволяється водієві синього автомобіля почати обгін у цій ситуації?","ru":"Разрешается ли водителю синего автомобиля начать обгон в этой ситуации?"},"a":[{"uk":"Дозволяється.","ru":"Разрешается.","w":{"uk":"У кінці підйому зустрічного транспорту не видно, і {p:14.6} прямо забороняє там обгін.","ru":"В конце подъёма встречного транспорта не видно, и {p:14.6} прямо запрещает там обгон."}},{"uk":"Забороняється.","ru":"Запрещается."},{"uk":"Дозволяється, якщо водій білого автомобіля включив аварійну сигналізацію.","ru":"Разрешается, если водитель белого автомобиля включил аварийную сигнализацию.","w":{"uk":"Увімкнена аварійна сигналізація білого автомобіля не поліпшує оглядовості на вершині підйому, тож заборона {p:14.6} діє й тоді.","ru":"Включённая аварийная сигнализация белого автомобиля не улучшает обзорности на вершине подъёма, поэтому запрет {p:14.6} действует и тогда."}}],"c":1,"e":{"uk":"Знак {s:1.6} «Крутий підйом» і сам малюнок показують, що автомобілі наближаються до вершини підйому, з-за якої не видно зустрічних транспортних засобів. Обгін у кінці підйому заборонено ({p:14.6}, підпункт «г»).","ru":"Знак {s:1.6} «Крутой подъём» и сам рисунок показывают, что автомобили приближаются к вершине подъёма, из-за которой не видно встречных транспортных средств. Обгон в конце подъёма запрещён ({p:14.6}, подпункт «г»)."},"ref":["14.6"],"pic":["img/hsc/14-8-1.jpg"]},{"id":"h14-9","t":"h14","num":"14.9","q":{"uk":"Чи дозволено водієві обгін у цьому місці?","ru":"Разрешён ли водителю обгон в этом месте?"},"a":[{"uk":"Дозволено, якщо не буде створено перешкоди зустрічним транспортним засобам.","ru":"Разрешён, если не будет создано помех встречным транспортным средствам.","w":{"uk":"Відсутність перешкод зустрічним — лише одна з умов {p:14.2}; на мосту обгін заборонено навіть за її дотримання.","ru":"Отсутствие помех встречным — лишь одно из условий {p:14.2}; на мосту обгон запрещён даже при его соблюдении."}},{"uk":"Дозволено за умови, що водій автомобіля, який їде попереду, не почав обгін або перестроювання.","ru":"Разрешён при условии, что водитель автомобиля, едущего впереди, не начал обгон или перестроение.","w":{"uk":"Ця умова {p:14.2} потрібна для будь-якого обгону, але на мосту обгін заборонено в будь-якому разі.","ru":"Это условие {p:14.2} нужно для любого обгона, но на мосту обгон запрещён в любом случае."}},{"uk":"Дозволено у випадках, зазначених у відповідях 1 і 2.","ru":"Разрешён в случаях, указанных в ответах 1 и 2.","w":{"uk":"Навіть за дотримання обох умов {p:14.6} забороняє обгін на мосту.","ru":"Даже при соблюдении обоих условий {p:14.6} запрещает обгон на мосту."}},{"uk":"Заборонено.","ru":"Запрещён."}],"c":3,"e":{"uk":"Автомобіль рухається мостом через Дніпро, а на мостах обгін заборонено ({p:14.6}, підпункт «г») незалежно від інших умов.","ru":"Автомобиль движется по мосту через Днепр, а на мостах обгон запрещён ({p:14.6}, подпункт «г») независимо от других условий."},"ref":["14.6"],"pic":["img/hsc/14-9-1.jpg"]},{"id":"h14-10","t":"h14","num":"14.10","q":{"uk":"Чи дозволено водієві чорного автомобіля виконати обгін у цій ситуації?","ru":"Разрешено ли водителю чёрного автомобиля выполнить обгон в этой ситуации?"},"a":[{"uk":"Дозволено, переконавшись у відсутності зустрічних автомобілів.","ru":"Разрешено, убедившись в отсутствии встречных автомобилей.","w":{"uk":"На повороті з обмеженою оглядовістю неможливо переконатися, що зустрічна смуга вільна на достатній відстані, тому обгін тут заборонено.","ru":"На повороте с ограниченной обзорностью невозможно убедиться, что встречная полоса свободна на достаточном расстоянии, поэтому обгон здесь запрещён."}},{"uk":"Дозволено, якщо швидкість автомобіля, що обганяється, менше ніж 30 км/год.","ru":"Разрешено, если скорость обгоняемого автомобиля менее 30 км/ч.","w":{"uk":"Виняток «менше 30 км/год» стосується лише знака {s:3.25}, а не заборони обгону на поворотах.","ru":"Исключение «менее 30 км/ч» относится только к знаку {s:3.25}, а не к запрету обгона на поворотах."}},{"uk":"Заборонено.","ru":"Запрещено."},{"uk":"Дозволено за умови виконання вимог з відповідей 1 і 2.","ru":"Разрешено при условии выполнения требований из ответов 1 и 2.","w":{"uk":"Жодна з цих умов не знімає заборони обгону на крутих поворотах з обмеженою оглядовістю.","ru":"Ни одно из этих условий не снимает запрета обгона на крутых поворотах с ограниченной обзорностью."}}],"c":2,"e":{"uk":"Знак {s:1.3.1} «Декілька поворотів» попереджає про небезпечні повороти, і за вантажівкою на повороті зустрічних не видно. На крутих поворотах і ділянках з обмеженою оглядовістю обгін заборонено ({p:14.6}, підпункт «г»).","ru":"Знак {s:1.3.1} «Несколько поворотов» предупреждает об опасных поворотах, и за грузовиком на повороте встречных не видно. На крутых поворотах и участках с ограниченной обзорностью обгон запрещён ({p:14.6}, подпункт «г»)."},"ref":["14.6"],"pic":["img/hsc/14-10-1.jpg"]},{"id":"h14-11","t":"h14","num":"14.11","q":{"uk":"Чи дозволено водієві сірого автомобіля виконати обгін білого?","ru":"Разрешено ли водителю серого автомобиля выполнить обгон белого?"},"a":[{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"Білий автомобіль уже подав сигнал ліворуч і починає обгін трактора, тож обганяти його заборонено.","ru":"Белый автомобиль уже подал сигнал налево и начинает обгон трактора, поэтому обгонять его запрещено."}},{"uk":"Заборонено.","ru":"Запрещено."},{"uk":"Дозволено тільки в населеному пункті.","ru":"Разрешено только в населённом пункте.","w":{"uk":"Ці заборони діють однаково і в населених пунктах, і поза ними.","ru":"Эти запреты действуют одинаково и в населённых пунктах, и вне их."}}],"c":1,"e":{"uk":"Білий автомобіль увімкнув лівий покажчик повороту, щоб обігнати трактор. Перед обгоном водій має переконатися, що транспортний засіб попереду не подав сигналу повороту (перестроювання) ліворуч ({p:14.2}, підпункт «б»), а обганяти транспортний засіб, який сам здійснює обгін, заборонено ({p:14.6}, підпункт «ґ»).","ru":"Белый автомобиль включил левый указатель поворота, чтобы обогнать трактор. Перед обгоном водитель должен убедиться, что транспортное средство впереди не подало сигнала поворота (перестроения) налево ({p:14.2}, подпункт «б»), а обгонять транспортное средство, которое само выполняет обгон, запрещено ({p:14.6}, подпункт «ґ»)."},"ref":["14.2","14.6"],"pic":["img/hsc/14-11-1.jpg"]},{"id":"h14-12","t":"h14","num":"14.12","q":{"uk":"Чи дозволено обгін водієві зеленого автомобіля в цій ситуації?","ru":"Разрешён ли обгон водителю зелёного автомобиля в этой ситуации?"},"a":[{"uk":"Заборонено.","ru":"Запрещён."},{"uk":"Дозволено.","ru":"Разрешён.","w":{"uk":"Червоний автомобіль подав сигнал ліворуч і об'їжджає перешкоду, а обганяти транспортний засіб, що здійснює об'їзд, заборонено.","ru":"Красный автомобиль подал сигнал налево и объезжает препятствие, а обгонять транспортное средство, выполняющее объезд, запрещено."}}],"c":0,"e":{"uk":"Попереду стоїть сірий автомобіль з увімкненою аварійною сигналізацією, і червоний, увімкнувши лівий покажчик, починає його об'їжджати. Обганяти транспортний засіб, що здійснює об'їзд, заборонено ({p:14.6}, підпункт «ґ»); до того ж водій попереду подав сигнал повороту ліворуч ({p:14.2}, підпункт «б»).","ru":"Впереди стоит серый автомобиль с включённой аварийной сигнализацией, и красный, включив левый указатель, начинает его объезжать. Обгонять транспортное средство, выполняющее объезд, запрещено ({p:14.6}, подпункт «ґ»); к тому же водитель впереди подал сигнал поворота налево ({p:14.2}, подпункт «б»)."},"ref":["14.2","14.6"],"pic":["img/hsc/14-12-1.jpg"]},{"id":"h14-13","t":"h14","num":"14.13","q":{"uk":"Чи дозволено водієві білого автомобіля виконати обгін у цій ситуації?","ru":"Разрешено ли водителю белого автомобиля выполнить обгон в этой ситуации?"},"a":[{"uk":"Заборонено.","ru":"Запрещено."},{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"{p:14.6} забороняє обганяти колону, позаду якої рухається транспортний засіб з увімкненим проблисковим маячком (крім оранжевого), — саме такий випадок на малюнку.","ru":"{p:14.6} запрещает обгонять колонну, позади которой движется транспортное средство с включённым проблесковым маячком (кроме оранжевого), — именно такой случай на рисунке."}}],"c":0,"e":{"uk":"Колону супроводжують поліцейські автомобілі: попереду — з увімкненими синім і червоним проблисковими маячками, позаду — із синім і зеленим. Обганяти таку колону заборонено ({p:3.4}, а також {p:14.6}, підпункт «є»).","ru":"Колонну сопровождают полицейские автомобили: впереди — с включёнными синим и красным проблесковыми маячками, сзади — с синим и зелёным. Обгонять такую колонну запрещено ({p:3.4}, а также {p:14.6}, подпункт «є»)."},"ref":["3.4","14.6"],"pic":["img/hsc/14-13-1.jpg"]},{"id":"h14-14","t":"h14","num":"14.14","q":{"uk":"Чи дозволено виконати обгін у даній дорожній ситуації?","ru":"Разрешено ли выполнить обгон в данной дорожной ситуации?"},"a":[{"uk":"Заборонено.","ru":"Запрещено."},{"uk":"Дозволено, якщо швидкість автомобіля, що обганяється, менше 30 км/год.","ru":"Разрешено, если скорость обгоняемого автомобиля менее 30 км/ч.","w":{"uk":"Виняток «менше 30 км/год» стосується лише знака {s:3.25} і на тунель не поширюється.","ru":"Исключение «менее 30 км/ч» относится только к знаку {s:3.25} и на тоннель не распространяется."}},{"uk":"Дозволено, якщо смуга зустрічного руху вільна.","ru":"Разрешено, если полоса встречного движения свободна.","w":{"uk":"Вільна зустрічна смуга не знімає заборони обгону в тунелі.","ru":"Свободная встречная полоса не снимает запрета обгона в тоннеле."}},{"uk":"Дозволено при дотриманні умов, зазначених у відповідях 2 і 3.","ru":"Разрешено при соблюдении условий, указанных в ответах 2 и 3.","w":{"uk":"Навіть за дотримання обох умов обгін у тунелі заборонено.","ru":"Даже при соблюдении обоих условий обгон в тоннеле запрещён."}}],"c":0,"e":{"uk":"Автомобілі рухаються в тунелі, а в тунелях обгін заборонено ({p:14.6}, підпункт «д») незалежно від швидкості попереднього автомобіля та наявності зустрічних.","ru":"Автомобили движутся в тоннеле, а в тоннелях обгон запрещён ({p:14.6}, подпункт «д») независимо от скорости впереди идущего автомобиля и наличия встречных."},"ref":["14.6"],"pic":["img/hsc/14-14-1.jpg"]},{"id":"h14-15","t":"h14","num":"14.15","q":{"uk":"Чи дозволено водієві жовтого автомобіля виконати обгін у цій ситуації?","ru":"Разрешено ли водителю жёлтого автомобиля выполнить обгон в этой ситуации?"},"a":[{"uk":"Дозволено в будь-якому випадку.","ru":"Разрешено в любом случае.","w":{"uk":"На дорозі з двома смугами в одному напрямку обгін заборонено за будь-яких умов.","ru":"На дороге с двумя полосами в одном направлении обгон запрещён при любых условиях."}},{"uk":"Заборонено.","ru":"Запрещено."},{"uk":"Дозволено, якщо швидкість автомобіля, що обганяється, менше 30 км/год.","ru":"Разрешено, если скорость обгоняемого автомобиля менее 30 км/ч.","w":{"uk":"Виняток «менше 30 км/год» стосується лише знака {s:3.25}; заборона обгону на дорогах з двома смугами в одному напрямку безумовна.","ru":"Исключение «менее 30 км/ч» относится только к знаку {s:3.25}; запрет обгона на дорогах с двумя полосами в одном направлении безусловный."}}],"c":1,"e":{"uk":"Дорога має дві смуги для руху в напрямку жовтого автомобіля, а зустрічну смугу відокремлює суцільна лінія {m:1.1}. На таких дорогах обгін заборонено ({p:14.6}, підпункт «е»), а виїжджати на зустрічний бік забороняє {p:11.4}; випереджати можна лише смугами свого напрямку.","ru":"Дорога имеет две полосы для движения в направлении жёлтого автомобиля, а встречную полосу отделяет сплошная линия {m:1.1}. На таких дорогах обгон запрещён ({p:14.6}, подпункт «е»), а выезжать на встречную сторону запрещает {p:11.4}; опережать можно только по полосам своего направления."},"ref":["11.4","14.6"],"pic":["img/hsc/14-15-1.jpg"]},{"id":"h14-16","t":"h14","num":"14.16","q":{"uk":"Чи дозволено виконати обгін у цій ситуації?","ru":"Разрешено ли выполнить обгон в этой ситуации?"},"a":[{"uk":"Дозволено в будь-якому випадку.","ru":"Разрешено в любом случае.","w":{"uk":"Обгін вимагав би перетнути суцільну лінію {m:1.1}, що заборонено.","ru":"Обгон потребовал бы пересечь сплошную линию {m:1.1}, что запрещено."}},{"uk":"Заборонено.","ru":"Запрещено."},{"uk":"Дозволено, якщо швидкість автомобіля, що обганяється, менше 30 км/год.","ru":"Разрешено, если скорость обгоняемого автомобиля менее 30 км/ч.","w":{"uk":"Виняток «менше 30 км/год» стосується знака {s:3.25}, а не суцільної лінії розмітки: перетинати {m:1.1} заборонено за будь-якої швидкості.","ru":"Исключение «менее 30 км/ч» относится к знаку {s:3.25}, а не к сплошной линии разметки: пересекать {m:1.1} запрещено при любой скорости."}}],"c":1,"e":{"uk":"Смугу, якою рухаються сірий і синій автомобілі, відокремлює від лівої частини дороги суцільна лінія {m:1.1}. Щоб обігнати, синьому довелося б її перетнути, а лінію {m:1.1} перетинати забороняється ({p:34.1}).","ru":"Полосу, по которой движутся серый и синий автомобили, отделяет от левой части дороги сплошная линия {m:1.1}. Чтобы обогнать, синему пришлось бы её пересечь, а линию {m:1.1} пересекать запрещается ({p:34.1})."},"ref":["34.1"],"pic":["img/hsc/14-16-1.jpg"]},{"id":"h14-17","t":"h14","num":"14.17","q":{"uk":"Чи дозволено водієві виконати обгін транспортних засобів, що рухаються з увімкненими проблисковими маячками оранжевого кольору?","ru":"Разрешено ли водителю выполнить обгон транспортных средств, движущихся с включёнными проблесковыми маячками оранжевого цвета?"},"a":[{"uk":"Заборонено.","ru":"Запрещено.","w":{"uk":"Оранжевий маячок прямо виключено із заборони {p:14.6}; обганяти не можна лише колони із синіми, червоними чи зеленими маячками.","ru":"Оранжевый маячок прямо исключён из запрета {p:14.6}; нельзя обгонять лишь колонны с синими, красными или зелёными маячками."}},{"uk":"Дозволено.","ru":"Разрешено."}],"c":1,"e":{"uk":"{p:14.6} (підпункт «є») забороняє обганяти колону, позаду якої рухається транспортний засіб з увімкненим проблисковим маячком, **крім оранжевого**. Оранжеві маячки мають, зокрема, автомобілі супроводу великогабаритних вантажів, як на малюнку, тож обгін дозволено з дотриманням вимог {p:14.2}.","ru":"{p:14.6} (подпункт «є») запрещает обгонять колонну, позади которой движется транспортное средство с включённым проблесковым маячком, **кроме оранжевого**. Оранжевые маячки имеют, в частности, автомобили сопровождения крупногабаритных грузов, как на рисунке, поэтому обгон разрешён с соблюдением требований {p:14.2}."},"ref":["14.2","14.6"],"pic":["img/hsc/14-17-1.jpg"]},{"id":"h14-18","t":"h14","num":"14.18","q":{"uk":"Чи правильно водій зеленого автомобіля виконав обгін синього автомобіля?","ru":"Правильно ли водитель зелёного автомобиля выполнил обгон синего автомобиля?"},"a":[{"uk":"Неправильно: обгін перед залізничним переїздом заборонений.","ru":"Неправильно: обгон перед железнодорожным переездом запрещён.","w":{"uk":"Обгін перед переїздом заборонено не взагалі, а лише ближче ніж за 100 м до нього; зелений автомобіль завершив маневр раніше.","ru":"Обгон перед переездом запрещён не вообще, а только ближе чем за 100 м до него; зелёный автомобиль завершил манёвр раньше."}},{"uk":"Правильно, оскільки обгін був завершений за 100 м до залізничного переїзду.","ru":"Правильно, поскольку обгон был завершён за 100 м до железнодорожного переезда."}],"c":1,"e":{"uk":"Зелений автомобіль завершив обгін і повернувся на свою смугу ще далеко від переїзду. {p:14.6} (підпункт «б») забороняє обгін лише на переїзді та ближче ніж за 100 м перед ним, тож обгін виконано правильно.","ru":"Зелёный автомобиль завершил обгон и вернулся на свою полосу ещё далеко от переезда. {p:14.6} (подпункт «б») запрещает обгон только на переезде и ближе чем за 100 м перед ним, поэтому обгон выполнен правильно."},"ref":["14.6"],"pic":["img/hsc/14-18-1.jpg"]},{"id":"h14-19","t":"h14","num":"14.19","q":{"uk":"Чи дозволено водієві жовтого автомобіля виконати обгін синього так, як показано на малюнку?","ru":"Разрешено ли водителю жёлтого автомобиля выполнить обгон синего так, как показано на рисунке?"},"a":[{"uk":"Заборонено.","ru":"Запрещено."},{"uk":"Дозволено в будь-якому випадку.","ru":"Разрешено в любом случае.","w":{"uk":"Ближче ніж за 100 м до залізничного переїзду обгін заборонено, тож «в будь-якому випадку» — неправильно.","ru":"Ближе чем за 100 м до железнодорожного переезда обгон запрещён, поэтому «в любом случае» — неверно."}},{"uk":"Дозволено за умови, що синій автомобіль рухається повільно.","ru":"Разрешено при условии, что синий автомобиль движется медленно.","w":{"uk":"Мала швидкість синього автомобіля не знімає заборони обгону перед залізничним переїздом.","ru":"Малая скорость синего автомобиля не снимает запрета обгона перед железнодорожным переездом."}}],"c":0,"e":{"uk":"Жовтий автомобіль починає обгін уже біля других знаків про залізничний переїзд, безпосередньо перед ним, тобто ближче ніж за 100 м до переїзду, де обгін заборонено ({p:14.6}, підпункт «б»).","ru":"Жёлтый автомобиль начинает обгон уже у вторых знаков о железнодорожном переезде, непосредственно перед ним, то есть ближе чем за 100 м до переезда, где обгон запрещён ({p:14.6}, подпункт «б»)."},"ref":["14.6"],"pic":["img/hsc/14-19-1.jpg"]},{"id":"h14-20","t":"h14","num":"14.20","q":{"uk":"Чи дозволено водієві синього автомобіля обігнати мопед?","ru":"Разрешено ли водителю синего автомобиля обогнать мопед?"},"a":[{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"Головна дорога не дає права обганяти на перехресті: заборона {p:14.6} діє на будь-якому перехресті.","ru":"Главная дорога не даёт права обгонять на перекрёстке: запрет {p:14.6} действует на любом перекрёстке."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":1,"e":{"uk":"Мопед і синій автомобіль уже на перехресті, а обгін на перехресті заборонено ({p:14.6}, підпункт «а») — навіть якщо рух відбувається головною дорогою (знак {s:2.3}).","ru":"Мопед и синий автомобиль уже на перекрёстке, а обгон на перекрёстке запрещён ({p:14.6}, подпункт «а») — даже если движение происходит по главной дороге (знак {s:2.3})."},"ref":["14.6"],"pic":["img/hsc/14-20-1.jpg"]},{"id":"h14-21","t":"h14","num":"14.21","q":{"uk":"У чому повинен переконатися водій перед початком обгону за відсутності зустрічних транспортних засобів і транспортних засобів, що рухаються позаду?","ru":"В чём должен убедиться водитель перед началом обгона при отсутствии встречных транспортных средств и транспортных средств, движущихся сзади?"},"a":[{"uk":"У тому, що на проїзній частині рівна дорога.","ru":"В том, что на проезжей части ровная дорога.","w":{"uk":"Рівність дороги не входить до умов, які {p:14.2} вимагає перевірити перед обгоном.","ru":"Ровность дороги не входит в условия, которые {p:14.2} требует проверить перед обгоном."}},{"uk":"У тому, що після обгону зможе, не створюючи перешкоди транспортному засобу, якого він обганяє, повернутися на займану смугу.","ru":"В том, что после обгона сможет, не создавая помехи обгоняемому транспортному средству, вернуться на занимаемую полосу."},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2.","w":{"uk":"Варіант 1 до умов обгону не належить, тож поєднання неправильне.","ru":"Вариант 1 к условиям обгона не относится, поэтому сочетание неверно."}}],"c":1,"e":{"uk":"Коли зустрічних і попутних позаду немає, умови {p:14.2} щодо них уже виконано; лишається, зокрема, переконатися, що після обгону можна буде повернутися на свою смугу, **не створюючи перешкоди** транспортному засобу, якого обганяють ({p:14.2}, підпункт «г»).","ru":"Когда встречных и попутных сзади нет, условия {p:14.2} относительно них уже выполнены; остаётся, в частности, убедиться, что после обгона можно будет вернуться на свою полосу, **не создавая помехи** обгоняемому транспортному средству ({p:14.2}, подпункт «г»)."},"ref":["14.2"],"pic":["img/hsc/14-21-1.jpg"]},{"id":"h14-22","t":"h14","num":"14.22","q":{"uk":"Чи має право водій чорного автомобіля розпочати обгін синього автомобіля?","ru":"Имеет ли право водитель чёрного автомобиля начать обгон синего автомобиля?"},"a":[{"uk":"Не має права - повинен дати дорогу зустрічному автомобілю.","ru":"Не имеет права — должен уступить дорогу встречному автомобилю."},{"uk":"Має право.","ru":"Имеет право.","w":{"uk":"Зустрічна смуга зайнята автомобілем, що наближається, тож умову {p:14.2} не виконано.","ru":"Встречная полоса занята приближающимся автомобилем, поэтому условие {p:14.2} не выполнено."}}],"c":0,"e":{"uk":"Назустріч зустрічною смугою наближається автомобіль. Перед обгоном водій повинен переконатися, що смуга зустрічного руху вільна на достатній для обгону відстані ({p:14.2}, підпункт «в»), а водії зустрічного напрямку мають перевагу ({p:11.3}).","ru":"Навстречу по встречной полосе приближается автомобиль. Перед обгоном водитель должен убедиться, что полоса встречного движения свободна на достаточном для обгона расстоянии ({p:14.2}, подпункт «в»), а водители встречного направления имеют преимущество ({p:11.3})."},"ref":["11.3","14.2"],"pic":["img/hsc/14-22-1.jpg"]},{"id":"h14-23","t":"h14","num":"14.23","q":{"uk":"Чи може водій зеленого автомобіля почати обгін сірого автомобіля?","ru":"Может ли водитель зелёного автомобиля начать обгон серого автомобиля?"},"a":[{"uk":"Може, увімкнувши звуковий сигнал.","ru":"Может, включив звуковой сигнал.","w":{"uk":"Звуковий сигнал не дає переваги ({p:9.4}) і не скасовує заборони обганяти транспортний засіб, що вже виконує обгін.","ru":"Звуковой сигнал не даёт преимущества ({p:9.4}) и не отменяет запрета обгонять транспортное средство, которое уже выполняет обгон."}},{"uk":"Не може – повинен дочекатися, поки сірий автомобіль завершить обгін.","ru":"Не может — должен дождаться, пока серый автомобиль завершит обгон."}],"c":1,"e":{"uk":"Сірий автомобіль увімкнув лівий покажчик і починає обгін чорного. Обганяти транспортний засіб, який сам здійснює обгін, заборонено ({p:14.6}, підпункт «ґ»), і водій попереду вже подав сигнал ліворуч ({p:14.2}, підпункт «б»).","ru":"Серый автомобиль включил левый указатель и начинает обгон чёрного. Обгонять транспортное средство, которое само выполняет обгон, запрещено ({p:14.6}, подпункт «ґ»), и водитель впереди уже подал сигнал налево ({p:14.2}, подпункт «б»)."},"ref":["14.2","14.6"],"pic":["img/hsc/14-23-1.jpg"]},{"id":"h14-24","t":"h14","num":"14.24","q":{"uk":"Чи дозволяється водієві автомобіля виконати обгін мотоцикліста на цьому перехресті?","ru":"Разрешается ли водителю автомобиля выполнить обгон мотоциклиста на этом перекрёстке?"},"a":[{"uk":"Дозволяється при дотриманні заходів безпеки.","ru":"Разрешается при соблюдении мер безопасности.","w":{"uk":"Заборона обгону на перехресті безумовна, обережність її не скасовує.","ru":"Запрет обгона на перекрёстке безусловный, осторожность его не отменяет."}},{"uk":"Забороняється.","ru":"Запрещается."},{"uk":"Дозволяється за умови, що швидкість мотоцикліста менше ніж 30 км/год.","ru":"Разрешается при условии, что скорость мотоциклиста менее 30 км/ч.","w":{"uk":"Виняток «менше 30 км/год» стосується знака {s:3.25}, а не заборони обгону на перехресті.","ru":"Исключение «менее 30 км/ч» относится к знаку {s:3.25}, а не к запрету обгона на перекрёстке."}}],"c":1,"e":{"uk":"Обгін на перехресті заборонено ({p:14.6}, підпункт «а»), і рух головною дорогою (знак {s:2.3}) винятку не дає.","ru":"Обгон на перекрёстке запрещён ({p:14.6}, подпункт «а»), и движение по главной дороге (знак {s:2.3}) исключения не даёт."},"ref":["14.6"],"pic":["img/hsc/14-24-1.jpg"]},{"id":"h14-25","t":"h14","num":"14.25","q":{"uk":"Як повинен діяти водій чорного автомобіля, що збирається виконувати обгін, в даній ситуації?","ru":"Как должен действовать водитель чёрного автомобиля, собирающийся выполнить обгон, в данной ситуации?"},"a":[{"uk":"Дати можливість обігнати себе і після цього почати обгін.","ru":"Дать возможность обогнать себя и после этого начать обгон.","w":{"uk":"Неповна відповідь: водієві, якого обганяють, також заборонено перешкоджати обгону підвищенням швидкості ({p:14.3}).","ru":"Неполный ответ: водителю, которого обгоняют, также запрещено препятствовать обгону повышением скорости ({p:14.3})."}},{"uk":"Не перешкоджати обгону, підвищуючи швидкість.","ru":"Не препятствовать обгону, повышая скорость.","w":{"uk":"Неповна відповідь: крім того, не можна починати власний обгін, доки білий автомобіль не завершить свій ({p:14.2}).","ru":"Неполный ответ: кроме того, нельзя начинать собственный обгон, пока белый автомобиль не завершит свой ({p:14.2})."}},{"uk":"Виконати обидві дії.","ru":"Выполнить оба действия."}],"c":2,"e":{"uk":"Білий автомобіль позаду вже розпочав обгін чорного (виїхав ліворуч з увімкненим покажчиком). Водій чорного не може починати обгін, поки його обганяють ({p:14.2}, підпункт «а»), і не повинен перешкоджати обгону, підвищуючи швидкість ({p:14.3}); тож він пропускає білий автомобіль і лише потім обганяє жовтий.","ru":"Белый автомобиль сзади уже начал обгон чёрного (выехал влево с включённым указателем). Водитель чёрного не может начинать обгон, пока его обгоняют ({p:14.2}, подпункт «а»), и не должен препятствовать обгону, повышая скорость ({p:14.3}); поэтому он пропускает белый автомобиль и лишь потом обгоняет жёлтый."},"ref":["14.2","14.3"],"pic":["img/hsc/14-25-1.jpg"]},{"id":"h14-26","t":"h14","num":"14.26","q":{"uk":"Що в даній ситуації повинен зробити водій зеленого автомобіля перед тим, як почати обгін?","ru":"Что в данной ситуации должен сделать водитель зелёного автомобиля перед тем, как начать обгон?"},"a":[{"uk":"Переконатися, що водій сірого автомобіля не подав сигнал про намір повороту (перестроювання) ліворуч, і почати обгін.","ru":"Убедиться, что водитель серого автомобиля не подал сигнал о намерении поворота (перестроения) налево, и начать обгон."},{"uk":"Подати звуковий сигнал для привернення уваги водія транспортного засобу, що рухається попереду, й обов'язково (негайно) почати обгін.","ru":"Подать звуковой сигнал для привлечения внимания водителя транспортного средства, движущегося впереди, и обязательно (немедленно) начать обгон.","w":{"uk":"Звуковий сигнал поза населеним пунктом лише дозволений ({p:9.6}), а не обов'язковий, і він не звільняє від перевірки умов {p:14.2} перед тим, як «негайно» починати обгін.","ru":"Звуковой сигнал вне населённого пункта лишь разрешён ({p:9.6}), а не обязателен, и он не освобождает от проверки условий {p:14.2} перед тем, как «немедленно» начинать обгон."}},{"uk":"Виконати всі вище перелічені дії.","ru":"Выполнить все вышеперечисленные действия.","w":{"uk":"Варіант 2 неправильний, тож виконувати «всі дії» не потрібно.","ru":"Вариант 2 неверен, поэтому выполнять «все действия» не нужно."}}],"c":0,"e":{"uk":"Перед обгоном водій повинен переконатися, що транспортний засіб попереду на тій самій смузі не подав сигналу повороту (перестроювання) ліворуч ({p:14.2}, підпункт «б»). Сірий автомобіль сигналу не подає, тож після такої перевірки зелений може обганяти.","ru":"Перед обгоном водитель должен убедиться, что транспортное средство впереди на той же полосе не подало сигнала поворота (перестроения) налево ({p:14.2}, подпункт «б»). Серый автомобиль сигнала не подаёт, поэтому после такой проверки зелёный может обгонять."},"ref":["14.2"],"pic":["img/hsc/14-26-1.jpg"]},{"id":"h14-27","t":"h14","num":"14.27","q":{"uk":"Як повинен діяти в даній ситуації водій сірого автомобіля, який збирається виконати обгін?","ru":"Как должен действовать в данной ситуации водитель серого автомобиля, который собирается выполнить обгон?"},"a":[{"uk":"Збільшити швидкість і, виїхавши перед зеленим автомобілем, виконати обгін.","ru":"Увеличить скорость и, выехав перед зелёным автомобилем, выполнить обгон.","w":{"uk":"Збільшувати швидкість і виїжджати перед зеленим автомобілем — означає перешкоджати його обгону, що заборонено {p:14.3}.","ru":"Увеличивать скорость и выезжать перед зелёным автомобилем — значит препятствовать его обгону, что запрещено {p:14.3}."}},{"uk":"Дочекатися, поки його обжене зелений автомобіль, і тільки потім виконати обгін.","ru":"Дождаться, пока его обгонит зелёный автомобиль, и только потом выполнить обгон."}],"c":1,"e":{"uk":"Зелений автомобіль позаду вже розпочав обгін (увімкнув лівий покажчик). Сірий не може починати обгін, якщо водій позаду вже розпочав обгін ({p:14.2}, підпункт «а»), і не повинен заважати обгону підвищенням швидкості ({p:14.3}).","ru":"Зелёный автомобиль сзади уже начал обгон (включил левый указатель). Серый не может начинать обгон, если водитель сзади уже начал обгон ({p:14.2}, подпункт «а»), и не должен мешать обгону повышением скорости ({p:14.3})."},"ref":["14.2","14.3"],"pic":["img/hsc/14-27-1.jpg"]},{"id":"h14-28","t":"h14","num":"14.28","q":{"uk":"Чи дозволено водієві білого автомобіля виконати обгін трактора в даній ситуації?","ru":"Разрешено ли водителю белого автомобиля выполнить обгон трактора в данной ситуации?"},"a":[{"uk":"Заборонено.","ru":"Запрещено."},{"uk":"Дозволено, якщо трактор рухається зі швидкістю менше ніж 30 км/год.","ru":"Разрешено, если трактор движется со скоростью менее 30 км/ч.","w":{"uk":"Виняток «менше 30 км/год» стосується знака {s:3.25}, а не заборони обгону на перехресті.","ru":"Исключение «менее 30 км/ч» относится к знаку {s:3.25}, а не к запрету обгона на перекрёстке."}},{"uk":"Дозволено, при цьому він повинен переконатися в безпеці маневру.","ru":"Разрешено, при этом он должен убедиться в безопасности манёвра.","w":{"uk":"Заборона обгону на перехресті безумовна, переконання в безпеці її не знімає.","ru":"Запрет обгона на перекрёстке безусловный, уверенность в безопасности его не снимает."}}],"c":0,"e":{"uk":"Трактор уже в'їжджає на перехрестя, тож обганяти його довелося б на перехресті, де обгін заборонено ({p:14.6}, підпункт «а»), хоч би й по головній дорозі (знак {s:2.3}). До того ж перед перехрестям нанесено суцільну лінію {m:1.1}.","ru":"Трактор уже въезжает на перекрёсток, поэтому обгонять его пришлось бы на перекрёстке, где обгон запрещён ({p:14.6}, подпункт «а»), хотя бы и по главной дороге (знак {s:2.3}). К тому же перед перекрёстком нанесена сплошная линия {m:1.1}."},"ref":["14.6"],"pic":["img/hsc/14-28-1.jpg"]},{"id":"h14-29","t":"h14","num":"14.29","q":{"uk":"Як повинен вчинити водій синього автомобіля, що рухається прямо, у даній ситуації?","ru":"Как должен поступить водитель синего автомобиля, движущегося прямо, в данной ситуации?"},"a":[{"uk":"Зупинитися перед перехрестям і дочекатися, поки фіолетовий автомобіль поверне ліворуч.","ru":"Остановиться перед перекрёстком и дождаться, пока фиолетовый автомобиль повернёт налево.","w":{"uk":"Чекати не обов'язково: праворуч від фіолетового автомобіля достатньо місця, а проїзд праворуч не є обгоном.","ru":"Ждать не обязательно: справа от фиолетового автомобиля достаточно места, а проезд справа не является обгоном."}},{"uk":"Об'їхати фіолетовий автомобіль праворуч, забезпечивши безпеку руху.","ru":"Объехать фиолетовый автомобиль справа, обеспечив безопасность движения."}],"c":1,"e":{"uk":"Фіолетовий автомобіль з лівим покажчиком чекає на перехресті, щоб повернути ліворуч. Обганяти його ліворуч не можна ({p:14.2}, підпункт «б»), а проїзд праворуч своєю смугою — це випередження без виїзду на зустрічну смугу, яке Правила не забороняють; треба лише дотримати безпечного інтервалу ({p:13.3}).","ru":"Фиолетовый автомобиль с левым указателем ждёт на перекрёстке, чтобы повернуть налево. Обгонять его слева нельзя ({p:14.2}, подпункт «б»), а проезд справа по своей полосе — это опережение без выезда на встречную полосу, которое Правила не запрещают; нужно лишь соблюсти безопасный интервал ({p:13.3})."},"ref":["1.10","13.3","14.2"],"pic":["img/hsc/14-29-1.jpg"]},{"id":"h14-30","t":"h14","num":"14.30","q":{"uk":"Чи дозволено у цьому місці водієві білого автомобіля виконати обгін?","ru":"Разрешено ли в этом месте водителю белого автомобиля выполнить обгон?"},"a":[{"uk":"Дозволено за умови, що обгін завершиться до перехрестя.","ru":"Разрешено при условии, что обгон завершится до перекрёстка."},{"uk":"Дозволено, якщо швидкість транспортного засобу, що обганяється, менше ніж 30 км/год.","ru":"Разрешено, если скорость обгоняемого транспортного средства менее 30 км/ч.","w":{"uk":"Швидкість обганяного автомобіля тут не має значення: виняток «менше 30 км/год» стосується лише знака {s:3.25}, а обмежує обгін тільки перехрестя попереду.","ru":"Скорость обгоняемого автомобиля здесь значения не имеет: исключение «менее 30 км/ч» относится только к знаку {s:3.25}, а ограничивает обгон лишь перекрёсток впереди."}},{"uk":"Заборонено.","ru":"Запрещено.","w":{"uk":"Знаки {s:2.1} і {s:2.2} обгону не забороняють; заборона діє лише на самому перехресті.","ru":"Знаки {s:2.1} и {s:2.2} обгон не запрещают; запрет действует только на самом перекрёстке."}}],"c":0,"e":{"uk":"Знак {s:2.1} з табличкою {s:7.1.2} «STOP 250 м» лише попереджає, що за 250 м попереду перехрестя зі знаком {s:2.2}. Обгін заборонено на самому перехресті ({p:14.6}, підпункт «а»), тож тут він дозволений, якщо завершити його до перехрестя.","ru":"Знак {s:2.1} с табличкой {s:7.1.2} «STOP 250 м» лишь предупреждает, что в 250 м впереди перекрёсток со знаком {s:2.2}. Обгон запрещён на самом перекрёстке ({p:14.6}, подпункт «а»), поэтому здесь он разрешён, если завершить его до перекрёстка."},"ref":["14.6"],"pic":["img/hsc/14-30-1.jpg"]},{"id":"h14-31","t":"h14","num":"14.31","q":{"uk":"Чи дозволено водію червоного автомобіля виконати обгін в даному місці дороги?","ru":"Разрешено ли водителю красного автомобиля выполнить обгон в данном месте дороги?"},"a":[{"uk":"Дозволено обгін на перехресті, за умови, що швидкість транспортного засобу, що обганяється, менше ніж 30 км/год.","ru":"Разрешён обгон на перекрёстке при условии, что скорость обгоняемого транспортного средства менее 30 км/ч.","w":{"uk":"Заборона обгону на перехресті не має винятку щодо швидкості; правило «менше 30 км/год» стосується лише знака {s:3.25}.","ru":"Запрет обгона на перекрёстке не имеет исключения по скорости; правило «менее 30 км/ч» относится только к знаку {s:3.25}."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":1,"e":{"uk":"Синій автомобіль уже під'їжджає до перехрестя рівнозначних доріг (знак {s:1.21}), тож обгін довелося б виконувати на перехресті, де він заборонений ({p:14.6}, підпункт «а»); перед перехрестям до того ж нанесено суцільну лінію {m:1.1}.","ru":"Синий автомобиль уже подъезжает к перекрёстку равнозначных дорог (знак {s:1.21}), поэтому обгон пришлось бы выполнять на перекрёстке, где он запрещён ({p:14.6}, подпункт «а»); перед перекрёстком к тому же нанесена сплошная линия {m:1.1}."},"ref":["14.6"],"pic":["img/hsc/14-31-1.jpg"]},{"id":"h14-32","t":"h14","num":"14.32","q":{"uk":"Чи дозволено обгін транспортного засобу, який виконує об'їзд або обгін?","ru":"Разрешён ли обгон транспортного средства, которое выполняет объезд или обгон?"},"a":[{"uk":"Заборонено.","ru":"Запрещён."},{"uk":"Дозволено за умови, що одиночний транспортний засіб рухається зі швидкістю менше ніж 30 км/год.","ru":"Разрешён при условии, что одиночное транспортное средство движется со скоростью менее 30 км/ч.","w":{"uk":"Виняток для поодиноких транспортних засобів, що рухаються повільніше ніж 30 км/год, стосується лише знака {s:3.25}; заборона обганяти того, хто сам обганяє чи об'їжджає, безумовна.","ru":"Исключение для одиночных транспортных средств, движущихся медленнее 30 км/ч, относится только к знаку {s:3.25}; запрет обгонять того, кто сам обгоняет или объезжает, безусловный."}},{"uk":"Дозволено.","ru":"Разрешён.","w":{"uk":"Обгін транспортного засобу, що сам виконує обгін або об'їзд, прямо заборонений {p:14.6}.","ru":"Обгон транспортного средства, которое само выполняет обгон или объезд, прямо запрещён {p:14.6}."}}],"c":0,"e":{"uk":"{p:14.6} (підпункт «ґ») забороняє обганяти транспортний засіб, який сам здійснює обгін або об'їзд: він уже займає зустрічну смугу чи виїжджає на неї.","ru":"{p:14.6} (подпункт «ґ») запрещает обгонять транспортное средство, которое само выполняет обгон или объезд: оно уже занимает встречную полосу или выезжает на неё."},"ref":["14.6"]},{"id":"h14-33","t":"h14","num":"14.33","q":{"uk":"На дорогах з якою мінімальною кількістю смуг для руху в одному напрямку заборонений обгін?","ru":"На дорогах с каким минимальным количеством полос для движения в одном направлении запрещён обгон?"},"a":[{"uk":"Одна і більше.","ru":"Одна и более.","w":{"uk":"На дорозі з однією смугою в кожному напрямку обгін дозволений (якщо немає інших заборон) — саме для нього й виїжджають на зустрічну смугу ({p:11.3}).","ru":"На дороге с одной полосой в каждом направлении обгон разрешён (если нет других запретов) — именно для него и выезжают на встречную полосу ({p:11.3})."}},{"uk":"Дві та більше.","ru":"Две и более."},{"uk":"Три і більше.","ru":"Три и более.","w":{"uk":"Заборона діє вже з двох смуг в одному напрямку, а не з трьох.","ru":"Запрет действует уже с двух полос в одном направлении, а не с трёх."}},{"uk":"Чотири і більше.","ru":"Четыре и более.","w":{"uk":"Заборона діє вже з двох смуг в одному напрямку, а не з чотирьох.","ru":"Запрет действует уже с двух полос в одном направлении, а не с четырёх."}}],"c":1,"e":{"uk":"{p:14.6} (підпункт «е») забороняє обгін на дорогах, що мають **дві та більше** смуги для руху в одному напрямку: там випереджають смугами свого напрямку, а виїжджати на зустрічний бік заборонено ({p:11.4}).","ru":"{p:14.6} (подпункт «е») запрещает обгон на дорогах, имеющих **две и более** полосы для движения в одном направлении: там опережают по полосам своего направления, а выезжать на встречную сторону запрещено ({p:11.4})."},"ref":["11.4","14.6"]},{"id":"h14-34","t":"h14","num":"14.34","q":{"uk":"Обгоном вважається:","ru":"Обгоном считается:"},"a":[{"uk":"Рух по крайній лівій смузі з більш високою швидкістю, ніж швидкість руху в крайній правій смузі.","ru":"Движение по крайней левой полосе с более высокой скоростью, чем скорость движения в крайней правой полосе.","w":{"uk":"Швидший рух лівою смугою свого напрямку — це випередження, а не обгін: на зустрічну смугу ніхто не виїжджає.","ru":"Более быстрое движение по левой полосе своего направления — это опережение, а не обгон: на встречную полосу никто не выезжает."}},{"uk":"Рух по правому узбіччі, оскільки швидкість руху транспортного засобу, який обганяють, менш ніж 30 км/год.","ru":"Движение по правой обочине, поскольку скорость движения обгоняемого транспортного средства менее 30 км/ч.","w":{"uk":"Рух узбіччям не є обгоном: обгін завжди пов'язаний з виїздом на смугу зустрічного руху.","ru":"Движение по обочине не является обгоном: обгон всегда связан с выездом на полосу встречного движения."}},{"uk":"Випередження одного або кількох транспортних засобів, пов'язане з виїздом на смугу зустрічного руху.","ru":"Опережение одного или нескольких транспортных средств, связанное с выездом на полосу встречного движения."},{"uk":"Відповіді, зазначені в пунктах 1, 2.","ru":"Ответы, указанные в пунктах 1, 2.","w":{"uk":"Обидва варіанти неправильні: жоден із них не передбачає виїзду на смугу зустрічного руху.","ru":"Оба варианта неверны: ни один из них не предусматривает выезда на полосу встречного движения."}}],"c":2,"e":{"uk":"Це дослівне визначення **обгону** з {p:1.10}: випередження одного або кількох транспортних засобів, пов'язане з виїздом на смугу зустрічного руху.","ru":"Это дословное определение **обгона** из {p:1.10}: опережение одного или нескольких транспортных средств, связанное с выездом на полосу встречного движения."},"ref":["1.10"]},{"id":"h14-35","t":"h14","num":"14.35","q":{"uk":"Чи дозволено водієві обігнати транспортний засіб, що рухається тільки з проблисковим маячком зеленого кольору, і супроводжувані ним транспортні засоби?","ru":"Разрешено ли водителю обогнать транспортное средство, движущееся только с проблесковым маячком зелёного цвета, и сопровождаемые им транспортные средства?"},"a":[{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"Зелений маячок не належить до винятків: обганяти колону можна лише тоді, коли позаду неї рухається транспортний засіб з оранжевим маячком.","ru":"Зелёный маячок не относится к исключениям: обгонять колонну можно лишь тогда, когда позади неё движется транспортное средство с оранжевым маячком."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":1,"e":{"uk":"{p:3.4} забороняє обгін і випередження транспортних засобів із зеленим (або синім і зеленим) проблисковим маячком і супроводжуваної ними колони; до того ж {p:14.6} (підпункт «є») забороняє обганяти колону, позаду якої рухається транспортний засіб з маячком будь-якого кольору, крім оранжевого.","ru":"{p:3.4} запрещает обгон и опережение транспортных средств с зелёным (или синим и зелёным) проблесковым маячком и сопровождаемой ими колонны; к тому же {p:14.6} (подпункт «є») запрещает обгонять колонну, позади которой движется транспортное средство с маячком любого цвета, кроме оранжевого."},"ref":["3.4","14.6"]},{"id":"h14-36","t":"h14","num":"14.36","q":{"uk":"Які дії заборонені водієві транспортного засобу, якого обганяють?","ru":"Какие действия запрещены водителю обгоняемого транспортного средства?"},"a":[{"uk":"Перешкоджати обгону шляхом підвищення швидкості руху.","ru":"Препятствовать обгону путём повышения скорости движения."},{"uk":"Повертати праворуч або зупинятися.","ru":"Поворачивать направо или останавливаться.","w":{"uk":"Поворот праворуч чи зупинку {p:14.3} не забороняє — їх виконують за загальними правилами, не створюючи перешкод тому, хто обганяє.","ru":"Поворот направо или остановку {p:14.3} не запрещает — их выполняют по общим правилам, не создавая помех обгоняющему."}}],"c":0,"e":{"uk":"За {p:14.3} водієві транспортного засобу, якого обганяють, забороняється перешкоджати обгону **підвищенням швидкості** або іншими діями.","ru":"Согласно {p:14.3} водителю обгоняемого транспортного средства запрещается препятствовать обгону **повышением скорости** или иными действиями."},"ref":["14.3"]},{"id":"h14-37","t":"h14","num":"14.37","q":{"uk":"Чи дозволяється обгін на залізничних переїздах?","ru":"Разрешается ли обгон на железнодорожных переездах?"},"a":[{"uk":"Дозволяється.","ru":"Разрешается.","w":{"uk":"Обгін на залізничному переїзді прямо заборонений {p:14.6}.","ru":"Обгон на железнодорожном переезде прямо запрещён {p:14.6}."}},{"uk":"Забороняється.","ru":"Запрещается."},{"uk":"Дозволяється тільки на регульованих залізничних переїздах.","ru":"Разрешается только на регулируемых железнодорожных переездах.","w":{"uk":"Заборона поширюється на всі залізничні переїзди, незалежно від того, регульовані вони чи ні.","ru":"Запрет распространяется на все железнодорожные переезды, независимо от того, регулируемые они или нет."}}],"c":1,"e":{"uk":"{p:14.6} (підпункт «б») забороняє обгін на залізничних переїздах і ближче ніж за 100 м перед ними.","ru":"{p:14.6} (подпункт «б») запрещает обгон на железнодорожных переездах и ближе чем за 100 м перед ними."},"ref":["14.6"]},{"id":"h14-38","t":"h14","num":"14.38","q":{"uk":"У яких випадках Вам дозволено обгін на перехресті?","ru":"В каких случаях Вам разрешён обгон на перекрёстке?"},"a":[{"uk":"Дозволено, якщо перехрестя регульоване.","ru":"Разрешён, если перекрёсток регулируемый.","w":{"uk":"Регульоване перехрестя теж є перехрестям, і обгін на ньому заборонено.","ru":"Регулируемый перекрёсток тоже является перекрёстком, и обгон на нём запрещён."}},{"uk":"Дозволено, якщо Ви знаходитесь на головній дорозі.","ru":"Разрешён, если Вы находитесь на главной дороге.","w":{"uk":"Рух головною дорогою не дає права обганяти на перехресті.","ru":"Движение по главной дороге не даёт права обгонять на перекрёстке."}},{"uk":"Дозволено, якщо перехрестя розташоване поза населеним пунктом.","ru":"Разрешён, если перекрёсток расположен вне населённого пункта.","w":{"uk":"Заборона діє на перехрестях і в населених пунктах, і поза ними.","ru":"Запрет действует на перекрёстках и в населённых пунктах, и вне их."}},{"uk":"У всіх зазначених випадках.","ru":"Во всех указанных случаях.","w":{"uk":"Жоден із перелічених випадків не є винятком із заборони {p:14.6}.","ru":"Ни один из перечисленных случаев не является исключением из запрета {p:14.6}."}},{"uk":"Обгін на будь-якому перехресті заборонено.","ru":"Обгон на любом перекрёстке запрещён."}],"c":4,"e":{"uk":"{p:14.6} (підпункт «а») забороняє обгін на перехресті без жодних винятків — щодо регулювання, головної дороги чи розташування перехрестя.","ru":"{p:14.6} (подпункт «а») запрещает обгон на перекрёстке без каких-либо исключений — по регулированию, главной дороге или расположению перекрёстка."},"ref":["14.6"]},{"id":"h14-39","t":"h14","num":"14.39","q":{"uk":"На якій відстані від пішохідного переходу заборонений обгін?","ru":"На каком расстоянии от пешеходного перехода запрещён обгон?"},"a":[{"uk":"Ближче ніж за 50 м до і після пішохідного переходу в населеному пункті і 100 м - поза населеним пунктом.","ru":"Ближе чем за 50 м до и после пешеходного перехода в населённом пункте и 100 м — вне населённого пункта.","w":{"uk":"Заборонна зона розташована лише перед переходом; після нього {p:14.6} обгону не забороняє.","ru":"Запрещённая зона расположена только перед переходом; после него {p:14.6} обгон не запрещает."}},{"uk":"Ближче ніж за 50 м перед пішохідним переходом у населеному пункті і 100 м - поза населеним пунктом.","ru":"Ближе чем за 50 м перед пешеходным переходом в населённом пункте и 100 м — вне населённого пункта."},{"uk":"Ближче ніж за 100 м перед пішохідним переходом у населеному пункті і 150 м - поза населеним пунктом.","ru":"Ближе чем за 100 м перед пешеходным переходом в населённом пункте и 150 м — вне населённого пункта.","w":{"uk":"Відстані завищено: у населеному пункті — 50 м, поза ним — 100 м.","ru":"Расстояния завышены: в населённом пункте — 50 м, вне его — 100 м."}}],"c":1,"e":{"uk":"{p:14.6} (підпункт «в») забороняє обгін ближче ніж за **50 м перед** пішохідним переходом у населеному пункті та **100 м** — поза населеним пунктом.","ru":"{p:14.6} (подпункт «в») запрещает обгон ближе чем за **50 м перед** пешеходным переходом в населённом пункте и **100 м** — вне населённого пункта."},"ref":["14.6"]},{"id":"h14-40","t":"h14","num":"14.40","q":{"uk":"Обгін заборонено:","ru":"Обгон запрещён:"},"a":[{"uk":"Ближче ніж за 50 м перед пішохідним переходом у населеному пункті.","ru":"Ближе чем за 50 м перед пешеходным переходом в населённом пункте.","w":{"uk":"Неповна відповідь: поза населеним пунктом обгін заборонено ближче ніж за 100 м перед переходом.","ru":"Неполный ответ: вне населённого пункта обгон запрещён ближе чем за 100 м перед переходом."}},{"uk":"Ближче ніж за 100 м перед пішохідним переходом поза населеним пунктом.","ru":"Ближе чем за 100 м перед пешеходным переходом вне населённого пункта.","w":{"uk":"Неповна відповідь: у населеному пункті обгін заборонено ближче ніж за 50 м перед переходом.","ru":"Неполный ответ: в населённом пункте обгон запрещён ближе чем за 50 м перед переходом."}},{"uk":"На дорогах, що мають одну смугу для руху в кожному напрямку.","ru":"На дорогах, имеющих одну полосу для движения в каждом направлении.","w":{"uk":"На дорогах з однією смугою в кожному напрямку обгін якраз дозволений; заборонено його там, де смуг в одному напрямку дві або більше.","ru":"На дорогах с одной полосой в каждом направлении обгон как раз разрешён; запрещён он там, где полос в одном направлении две или больше."}},{"uk":"У місцях, зазначених у відповідях 1 і 2.","ru":"В местах, указанных в ответах 1 и 2."},{"uk":"У місцях, зазначених у відповідях 1, 2, 3.","ru":"В местах, указанных в ответах 1, 2, 3.","w":{"uk":"Варіант 3 неправильний, тож поєднання 1, 2 і 3 — теж.","ru":"Вариант 3 неверен, поэтому сочетание 1, 2 и 3 — тоже."}}],"c":3,"e":{"uk":"Обидва місця з варіантів 1 і 2 названо в {p:14.6} (підпункт «в»). Заборона щодо кількості смуг стосується доріг з **двома та більше** смугами в одному напрямку, а не з однією.","ru":"Оба места из вариантов 1 и 2 названы в {p:14.6} (подпункт «в»). Запрет по количеству полос касается дорог с **двумя и более** полосами в одном направлении, а не с одной."},"ref":["14.6"]},{"id":"h14-41","t":"h14","num":"14.41","q":{"uk":"У чому з переліченого повинен переконатися водій перед тим, як почати обгін:","ru":"В чём из перечисленного должен убедиться водитель перед тем, как начать обгон:"},"a":[{"uk":"У тому, щоб водій транспортного засобу, якого обганяють, зрозумів Ваші дії.","ru":"В том, чтобы водитель обгоняемого транспортного средства понял Ваши действия.","w":{"uk":"Такої умови в {p:14.2} немає: привернути увагу водія можна сигналами ({p:9.6}), але переконуватися, що він «зрозумів дії», Правила не вимагають.","ru":"Такого условия в {p:14.2} нет: привлечь внимание водителя можно сигналами ({p:9.6}), но убеждаться, что он «понял действия», Правила не требуют."}},{"uk":"У тому, що після обгону зможе, не створюючи перешкоди транспортному засобу, якого обігнав, повернутися на раніше займану смугу.","ru":"В том, что после обгона сможет, не создавая помехи обгоняемому транспортному средству, вернуться на ранее занимаемую полосу."},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2.","w":{"uk":"Варіант 1 до умов {p:14.2} не належить, тож поєднання неправильне.","ru":"Вариант 1 к условиям {p:14.2} не относится, поэтому сочетание неверно."}}],"c":1,"e":{"uk":"Це одна з умов {p:14.2} (підпункт «г»): після обгону водій має змогу повернутися на займану смугу, не створюючи перешкоди транспортному засобу, якого обігнав.","ru":"Это одно из условий {p:14.2} (подпункт «г»): после обгона водитель может вернуться на занимаемую полосу, не создавая помехи транспортному средству, которое обогнал."},"ref":["14.2"]},{"id":"h14-42","t":"h14","num":"14.42","q":{"uk":"Чи дозволено на перехресті обгін поодиноких транспортних засобів, що рухаються із швидкістю менше 30 км/год.?","ru":"Разрешён ли на перекрёстке обгон одиночных транспортных средств, движущихся со скоростью менее 30 км/ч?"},"a":[{"uk":"Дозволено обгін тільки мопедів і гужових возів.","ru":"Разрешён обгон только мопедов и гужевых повозок.","w":{"uk":"Для мопедів і гужових возів винятку із заборони обгону на перехресті немає.","ru":"Для мопедов и гужевых повозок исключения из запрета обгона на перекрёстке нет."}},{"uk":"Заборонено.","ru":"Запрещён."}],"c":1,"e":{"uk":"Обгін на перехресті заборонено без винятків ({p:14.6}, підпункт «а»). Обганяти поодинокі транспортні засоби, що рухаються повільніше ніж 30 км/год, дозволяє лише знак {s:3.25}, а на заборону обгону на перехресті цей виняток не поширюється.","ru":"Обгон на перекрёстке запрещён без исключений ({p:14.6}, подпункт «а»). Обгонять одиночные транспортные средства, движущиеся медленнее 30 км/ч, разрешает только знак {s:3.25}, а на запрет обгона на перекрёстке это исключение не распространяется."},"ref":["14.6"]},{"id":"h14-43","t":"h14","num":"14.43","q":{"uk":"У яких з перелічених місць заборонений обгін?","ru":"В каких из перечисленных мест запрещён обгон?"},"a":[{"uk":"На мостах, естакадах і шляхопроводах.","ru":"На мостах, эстакадах и путепроводах.","w":{"uk":"Неповна відповідь: обгін заборонено також у тунелях.","ru":"Неполный ответ: обгон запрещён также в тоннелях."}},{"uk":"Під шляхопроводами та естакадами.","ru":"Под путепроводами и эстакадами.","w":{"uk":"Місць під шляхопроводами та естакадами {p:14.6} не згадує: заборона діє на самих спорудах.","ru":"Мест под путепроводами и эстакадами {p:14.6} не упоминает: запрет действует на самих сооружениях."}},{"uk":"У тунелях.","ru":"В тоннелях.","w":{"uk":"Неповна відповідь: обгін заборонено також на мостах, естакадах і шляхопроводах.","ru":"Неполный ответ: обгон запрещён также на мостах, эстакадах и путепроводах."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3.","w":{"uk":"Варіант 2 зайвий: під шляхопроводами й естакадами обгін не заборонено.","ru":"Вариант 2 лишний: под путепроводами и эстакадами обгон не запрещён."}},{"uk":"Відповіді 1 і 3.","ru":"Ответы 1 и 3."}],"c":4,"e":{"uk":"{p:14.6} забороняє обгін на мостах, естакадах, шляхопроводах (підпункт «г») і в тунелях (підпункт «д»). Окремої заборони обгону **під** шляхопроводами та естакадами Правила не містять.","ru":"{p:14.6} запрещает обгон на мостах, эстакадах, путепроводах (подпункт «г») и в тоннелях (подпункт «д»). Отдельного запрета обгона **под** путепроводами и эстакадами Правила не содержат."},"ref":["14.6"]},{"id":"h14-44","t":"h14","num":"14.44","q":{"uk":"Чи дозволено водієві виконати обгін під час руху в умовах недостатньої видимості?","ru":"Разрешено ли водителю выполнить обгон во время движения в условиях недостаточной видимости?"},"a":[{"uk":"Заборонено.","ru":"Запрещено."},{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"За недостатньої видимості неможливо переконатися, що зустрічна смуга вільна на достатній відстані, тому {p:14.6} обгін забороняє.","ru":"При недостаточной видимости невозможно убедиться, что встречная полоса свободна на достаточном расстоянии, поэтому {p:14.6} обгон запрещает."}}],"c":0,"e":{"uk":"{p:14.6} (підпункт «г») забороняє обгін в умовах недостатньої видимості, тобто коли видимість дороги менше ніж 300 м ({p:1.10}).","ru":"{p:14.6} (подпункт «г») запрещает обгон в условиях недостаточной видимости, то есть когда видимость дороги менее 300 м ({p:1.10})."},"ref":["1.10","14.6"]},{"id":"h14-45","t":"h14","num":"14.45","q":{"uk":"Чи дозволено водієві виконати обгін під час руху в умовах туману?","ru":"Разрешено ли водителю выполнить обгон во время движения в условиях тумана?"},"a":[{"uk":"Дозволено, якщо видимість у напрямку руху понад 300 м.","ru":"Разрешено, если видимость в направлении движения более 300 м."},{"uk":"Заборонено.","ru":"Запрещено.","w":{"uk":"Сам туман обгону не забороняє: заборона діє лише тоді, коли видимість менша за 300 м.","ru":"Сам туман обгон не запрещает: запрет действует лишь тогда, когда видимость меньше 300 м."}}],"c":0,"e":{"uk":"Обгін заборонено в умовах **недостатньої видимості** ({p:14.6}, підпункт «г»), а нею {p:1.10} вважає видимість дороги менше ніж 300 м. Якщо в тумані видно далі ніж на 300 м, видимість не є недостатньою, і обгін дозволено з дотриманням {p:14.2}.","ru":"Обгон запрещён в условиях **недостаточной видимости** ({p:14.6}, подпункт «г»), а ею {p:1.10} считает видимость дороги менее 300 м. Если в тумане видно дальше чем на 300 м, видимость не является недостаточной, и обгон разрешён с соблюдением {p:14.2}."},"ref":["1.10","14.2","14.6"]},{"id":"h14-46","t":"h14","num":"14.46","q":{"uk":"Яка з перерахованих дій відповідає терміну «обгін»?","ru":"Какое из перечисленных действий соответствует термину «обгон»?"},"a":[{"uk":"Випередження одного або кількох транспортних засобів, пов'язане з виїздом на смугу зустрічного руху.","ru":"Опережение одного или нескольких транспортных средств, связанное с выездом на полосу встречного движения."},{"uk":"Випередження рухомого транспортного засобу, пов'язане з перестроюванням на праву смугу руху.","ru":"Опережение движущегося транспортного средства, связанное с перестроением на правую полосу движения.","w":{"uk":"Випередження з перестроюванням на праву смугу не пов'язане з виїздом на зустрічну смугу, тож обгоном не є.","ru":"Опережение с перестроением на правую полосу не связано с выездом на встречную полосу, поэтому обгоном не является."}},{"uk":"Випередження рухомого транспортного засобу, пов'язане з перестроюванням на ліву смугу руху попутного напрямку.","ru":"Опережение движущегося транспортного средства, связанное с перестроением на левую полосу движения попутного направления.","w":{"uk":"Ліва смуга попутного напрямку — не зустрічна, тож таке випередження обгоном не є.","ru":"Левая полоса попутного направления — не встречная, поэтому такое опережение обгоном не является."}}],"c":0,"e":{"uk":"Це дослівне визначення **обгону** з {p:1.10}: його ознака — виїзд на смугу зустрічного руху.","ru":"Это дословное определение **обгона** из {p:1.10}: его признак — выезд на полосу встречного движения."},"ref":["1.10"]},{"id":"h14-47","t":"h14","num":"14.47","q":{"uk":"Чи дозволено Вам розпочати обгін у цій ситуації?","ru":"Разрешено ли Вам начать обгон в этой ситуации?"},"a":[{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"На крутому повороті з обмеженою оглядовістю неможливо переконатися, що зустрічна смуга вільна, і {p:14.6} обгін забороняє.","ru":"На крутом повороте с ограниченной обзорностью невозможно убедиться, что встречная полоса свободна, и {p:14.6} обгон запрещает."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":1,"e":{"uk":"Автомобіль іде гірською дорогою на крутому повороті, за яким скеля закриває огляд, тож зустрічних не видно. На крутих поворотах і ділянках з обмеженою оглядовістю обгін заборонено ({p:14.6}, підпункт «г»).","ru":"Автомобиль едет по горной дороге на крутом повороте, за которым скала закрывает обзор, поэтому встречных не видно. На крутых поворотах и участках с ограниченной обзорностью обгон запрещён ({p:14.6}, подпункт «г»)."},"ref":["14.6"],"pic":["img/hsc/14-47-1.jpg"]},{"id":"h14-48","t":"h14","num":"14.48","q":{"uk":"Чи дозволено Вам виконати обгін автомобіля в даному випадку, якщо Ви рухаєтесь на мосту?","ru":"Разрешено ли Вам выполнить обгон автомобиля в данном случае, если Вы движетесь по мосту?"},"a":[{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"Навіть за вільної зустрічної смуги обганяти на мосту заборонено.","ru":"Даже при свободной встречной полосе обгонять на мосту запрещено."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":1,"e":{"uk":"На мостах обгін заборонено ({p:14.6}, підпункт «г») незалежно від того, чи є зустрічні транспортні засоби.","ru":"На мостах обгон запрещён ({p:14.6}, подпункт «г») независимо от того, есть ли встречные транспортные средства."},"ref":["14.6"],"pic":["img/hsc/14-48-1.jpg"]},{"id":"h14-49","t":"h14","num":"14.49","q":{"uk":"Чи дозволено водієві жовтого автомобіля виконати обгін у даному випадку?","ru":"Разрешено ли водителю жёлтого автомобиля выполнить обгон в данном случае?"},"a":[{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"На повороті з обмеженою оглядовістю неможливо переконатися, що зустрічна смуга вільна на достатній відстані, тому обгін заборонено.","ru":"На повороте с ограниченной обзорностью невозможно убедиться, что встречная полоса свободна на достаточном расстоянии, поэтому обгон запрещён."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":1,"e":{"uk":"Дорога звивиста: попереду крутий поворот, за яким зустрічних не видно, і розмітка там переходить у суцільну лінію. На крутих поворотах і ділянках з обмеженою оглядовістю обгін заборонено ({p:14.6}, підпункт «г»).","ru":"Дорога извилистая: впереди крутой поворот, за которым встречных не видно, и разметка там переходит в сплошную линию. На крутых поворотах и участках с ограниченной обзорностью обгон запрещён ({p:14.6}, подпункт «г»)."},"ref":["14.6"],"pic":["img/hsc/14-49-1.jpg"]},{"id":"h14-50","t":"h14","num":"14.50","q":{"uk":"Під час обгону інших транспортних засобів вночі необхідно вмикати аварійну світлову сигналізацію:","ru":"Во время обгона других транспортных средств ночью необходимо включать аварийную световую сигнализацию:"},"a":[{"uk":"Так.","ru":"Да.","w":{"uk":"{p:9.9} такого випадку не передбачає, а аварійна сигналізація під час обгону лише дезорієнтує інших водіїв.","ru":"{p:9.9} такого случая не предусматривает, а аварийная сигнализация во время обгона лишь дезориентирует других водителей."}},{"uk":"Ні.","ru":"Нет."}],"c":1,"e":{"uk":"Перелік випадків, коли вмикають аварійну світлову сигналізацію ({p:9.9}), обгону не містить. Про обгін попереджають лівим покажчиком повороту, а привернути увагу водія, якого обганяють, можна перемиканням світла фар ({p:9.6}).","ru":"Перечень случаев, когда включают аварийную световую сигнализацию ({p:9.9}), обгона не содержит. Об обгоне предупреждают левым указателем поворота, а привлечь внимание водителя обгоняемого транспортного средства можно переключением света фар ({p:9.6})."},"ref":["9.6","9.9"]},{"id":"h14-51","t":"h14","num":"14.51","q":{"uk":"Під час руху тунелем у світлу пору доби водій транспортного засобу має право виконувати обгін:","ru":"При движении по тоннелю в светлое время суток водитель транспортного средства имеет право выполнять обгон:"},"a":[{"uk":"Так.","ru":"Да.","w":{"uk":"Світла пора доби заборони не скасовує: у тунелі обгін заборонено завжди.","ru":"Светлое время суток запрета не отменяет: в тоннеле обгон запрещён всегда."}},{"uk":"Ні.","ru":"Нет."}],"c":1,"e":{"uk":"Заборона обгону в тунелях ({p:14.6}, підпункт «д») діє в будь-яку пору доби.","ru":"Запрет обгона в тоннелях ({p:14.6}, подпункт «д») действует в любое время суток."},"ref":["14.6"],"pic":["img/hsc/14-51-1.jpg"]},{"id":"h14-52","t":"h14","num":"14.52","q":{"uk":"Чи дозволено Вам здійснити обгін в наведеній ситуації?","ru":"Разрешено ли Вам выполнить обгон в приведённой ситуации?"},"a":[{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"На дорогах з двома та більше смугами в одному напрямку обгін заборонено; дозволено лише випередження.","ru":"На дорогах с двумя и более полосами в одном направлении обгон запрещён; разрешено лишь опережение."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":1,"e":{"uk":"Дорога має щонайменше дві смуги для руху в одному напрямку (їх розділяє переривчаста розмітка), а на таких дорогах обгін заборонено ({p:14.6}, підпункт «е»); випереджати можна лише смугами свого напрямку.","ru":"Дорога имеет не менее двух полос для движения в одном направлении (их разделяет прерывистая разметка), а на таких дорогах обгон запрещён ({p:14.6}, подпункт «е»); опережать можно только по полосам своего направления."},"ref":["14.6"],"pic":["img/hsc/14-52-1.jpg"]},{"id":"h14-53","t":"h14","num":"14.53","q":{"uk":"У якому випадку дозволено виконати обгін на перехресті?","ru":"В каком случае разрешено выполнить обгон на перекрёстке?"},"a":[{"uk":"Якщо перехрестя регульоване, і горить зелений сигнал світлофора.","ru":"Если перекрёсток регулируемый и горит зелёный сигнал светофора.","w":{"uk":"Зелений сигнал дозволяє проїзд перехрестя, але не обгін на ньому.","ru":"Зелёный сигнал разрешает проезд перекрёстка, но не обгон на нём."}},{"uk":"Якщо на зустрічній смузі немає транспортних засобів.","ru":"Если на встречной полосе нет транспортных средств.","w":{"uk":"Вільна зустрічна смуга не знімає заборони обгону на перехресті.","ru":"Свободная встречная полоса не снимает запрета обгона на перекрёстке."}},{"uk":"Обгін на перехресті заборонено.","ru":"Обгон на перекрёстке запрещён."}],"c":2,"e":{"uk":"{p:14.6} (підпункт «а») забороняє обгін на перехресті без винятків.","ru":"{p:14.6} (подпункт «а») запрещает обгон на перекрёстке без исключений."},"ref":["14.6"]},{"id":"h14-54","t":"h14","num":"14.54","q":{"uk":"Виконати обгін в тунелі дозволено у випадку:","ru":"Выполнить обгон в тоннеле разрешено в случае:"},"a":[{"uk":"Відсутності транспортних засобів на смузі зустрічного руху.","ru":"Отсутствия транспортных средств на полосе встречного движения.","w":{"uk":"Вільна зустрічна смуга не знімає заборони обгону в тунелі.","ru":"Свободная встречная полоса не снимает запрета обгона в тоннеле."}},{"uk":"Можливості виконати обгін безпечно.","ru":"Возможности выполнить обгон безопасно.","w":{"uk":"Заборона {p:14.6} не залежить від того, чи вважає водій обгін безпечним.","ru":"Запрет {p:14.6} не зависит от того, считает ли водитель обгон безопасным."}},{"uk":"У жодному з випадків.","ru":"Ни в одном из случаев."}],"c":2,"e":{"uk":"Обгін у тунелях заборонено безумовно ({p:14.6}, підпункт «д»); на малюнку до того ж назустріч рухається автомобіль.","ru":"Обгон в тоннелях запрещён безусловно ({p:14.6}, подпункт «д»); на рисунке к тому же навстречу движется автомобиль."},"ref":["14.6"],"pic":["img/hsc/14-54-1.jpg"]},{"id":"h14-55","t":"h14","num":"14.55","q":{"uk":"Чи має право водій виконати обгін у даній дорожній ситуації?","ru":"Имеет ли право водитель выполнить обгон в данной дорожной ситуации?"},"a":[{"uk":"Не має права.","ru":"Не имеет права."},{"uk":"Має право, якщо швидкість автомобіля, що обганяється, менше 30 км/год.","ru":"Имеет право, если скорость обгоняемого автомобиля менее 30 км/ч.","w":{"uk":"Виняток «менше 30 км/год» стосується лише знака {s:3.25} і на тунель не поширюється.","ru":"Исключение «менее 30 км/ч» относится только к знаку {s:3.25} и на тоннель не распространяется."}},{"uk":"Має право, якщо смуга зустрічного руху вільна.","ru":"Имеет право, если полоса встречного движения свободна.","w":{"uk":"Вільна зустрічна смуга не знімає заборони обгону в тунелі.","ru":"Свободная встречная полоса не снимает запрета обгона в тоннеле."}},{"uk":"Має право при дотриманні умов, зазначених у відповідях 2 і 3.","ru":"Имеет право при соблюдении условий, указанных в ответах 2 и 3.","w":{"uk":"Навіть за обох умов обгін у тунелі заборонено.","ru":"Даже при обоих условиях обгон в тоннеле запрещён."}}],"c":0,"e":{"uk":"Автомобілі рухаються в тунелі, де обгін заборонено ({p:14.6}, підпункт «д»); до того ж зустрічною смугою наближається автомобіль.","ru":"Автомобили движутся в тоннеле, где обгон запрещён ({p:14.6}, подпункт «д»); к тому же по встречной полосе приближается автомобиль."},"ref":["14.6"],"pic":["img/hsc/14-55-1.jpg"]},{"id":"h14-56","t":"h14","num":"14.56","q":{"uk":"Чи дозволено поза населеним пунктом для привертання уваги водія транспортного засобу, що обганяється, подати звуковий сигнал?","ru":"Разрешено ли вне населённого пункта для привлечения внимания водителя обгоняемого транспортного средства подать звуковой сигнал?"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"Заборона звукових сигналів ({p:9.5}) діє лише в населених пунктах; поза ними {p:9.6} прямо дозволяє звуковий сигнал перед обгоном.","ru":"Запрет звуковых сигналов ({p:9.5}) действует только в населённых пунктах; вне их {p:9.6} прямо разрешает звуковой сигнал перед обгоном."}}],"c":0,"e":{"uk":"{p:9.6}: щоб привернути увагу водія, якого обганяють, можна перемикати світло фар, а **поза населеними пунктами** — і подавати звуковий сигнал.","ru":"{p:9.6}: чтобы привлечь внимание водителя обгоняемого транспортного средства, можно переключать свет фар, а **вне населённых пунктов** — и подавать звуковой сигнал."},"ref":["9.6"],"pic":["img/hsc/14-56-1.jpg"]},{"id":"h15-1","t":"h15","num":"15.1","q":{"uk":"У якому місці водієві дозволено зупинку?","ru":"В каком месте водителю разрешена остановка?"},"a":[{"uk":"У місці А.","ru":"В месте А.","w":{"uk":"Неповна відповідь: місце В теж розташоване поза шляхопроводом, тож зупинка там дозволена.","ru":"Неполный ответ: место В тоже расположено вне путепровода, поэтому остановка там разрешена."}},{"uk":"У місцях А і Б.","ru":"В местах А и Б.","w":{"uk":"У місці Б автомобіль стоїть під шляхопроводом, а там зупинку заборонено.","ru":"В месте Б автомобиль стоит под путепроводом, а там остановка запрещена."}},{"uk":"У місцях А, Б і В.","ru":"В местах А, Б и В.","w":{"uk":"Місце Б зайве: під шляхопроводом зупинятися заборонено.","ru":"Место Б лишнее: под путепроводом останавливаться запрещено."}},{"uk":"У місцях А і В.","ru":"В местах А и В."}],"c":3,"e":{"uk":"Зупинка забороняється на естакадах, мостах, шляхопроводах **і під ними** ({p:15.9}), тому місце Б під шляхопроводом виключене. Місця А і В розташовані поза шляхопроводом, і зупинка там дозволена.","ru":"Остановка запрещается на эстакадах, мостах, путепроводах **и под ними** ({p:15.9}), поэтому место Б под путепроводом исключено. Места А и В расположены вне путепровода, и остановка там разрешена."},"ref":["15.9"],"pic":["img/hsc/15-1-1.jpg"]},{"id":"h15-2","t":"h15","num":"15.2","q":{"uk":"Чи має право водій зупинитися в цьому місці?","ru":"Имеет ли право водитель остановиться в этом месте?"},"a":[{"uk":"Має право в будь-якому випадку.","ru":"Имеет право в любом случае.","w":{"uk":"Заборона діє: відстань від автомобіля до суцільної лінії буде меншою за 3 м.","ru":"Запрет действует: расстояние от автомобиля до сплошной линии будет меньше 3 м."}},{"uk":"Не має права.","ru":"Не имеет права."},{"uk":"Має право тільки для посадки (висадки) пасажирів.","ru":"Имеет право только для посадки (высадки) пассажиров.","w":{"uk":"Заборона зупинки там, де до суцільної лінії менше ніж 3 м, не має винятку для посадки (висадки) пасажирів.","ru":"Запрет остановки там, где до сплошной линии менее 3 м, не имеет исключения для посадки (высадки) пассажиров."}}],"c":1,"e":{"uk":"Між суцільною лінією розмітки і краєм проїзної частини лише 3 м, тож після зупинки між автомобілем і суцільною лінією залишиться **менше ніж 3 м** — у такому місці зупинку заборонено ({p:15.9}), навіть навпроти бокового проїзду.","ru":"Между сплошной линией разметки и краем проезжей части всего 3 м, поэтому после остановки между автомобилем и сплошной линией останется **менее 3 м** — в таком месте остановка запрещена ({p:15.9}), даже напротив бокового проезда."},"ref":["15.9"],"pic":["img/hsc/15-2-1.jpg"]},{"id":"h15-3","t":"h15","num":"15.3","q":{"uk":"На якому з місць водієві синього автомобіля дозволено виконати зупинку?","ru":"На каком из мест водителю синего автомобиля разрешено выполнить остановку?"},"a":[{"uk":"На місці А.","ru":"На месте А.","w":{"uk":"Місце А розташоване ближче 10 м перед пішохідним переходом, а там зупинятися заборонено.","ru":"Место А расположено ближе 10 м перед пешеходным переходом, а там останавливаться запрещено."}},{"uk":"На місці Б.","ru":"На месте Б.","w":{"uk":"Місце Б ще в межах перехрестя: межею перехрестя є початок заокруглення краю проїзної частини, а на перехрестях зупинку заборонено.","ru":"Место Б ещё в пределах перекрёстка: границей перекрёстка является начало закругления края проезжей части, а на перекрёстках остановка запрещена."}},{"uk":"На місці В.","ru":"На месте В."},{"uk":"На місцях А та В.","ru":"На местах А и В.","w":{"uk":"Місце А ближче 10 м до пішохідного переходу, тому зупинка там заборонена.","ru":"Место А ближе 10 м к пешеходному переходу, поэтому остановка там запрещена."}},{"uk":"На місцях Б і В.","ru":"На местах Б и В.","w":{"uk":"Місце Б розташоване в межах перехрестя, де зупинку заборонено.","ru":"Место Б расположено в пределах перекрёстка, где остановка запрещена."}}],"c":2,"e":{"uk":"Місце А ближче 10 м перед пішохідним переходом, а місце Б ще в межах перехрестя (у зоні заокруглення краю проїзної частини) — там зупинку заборонено ({p:15.9}). Дозволене лише місце В, далі від перехрестя.","ru":"Место А ближе 10 м перед пешеходным переходом, а место Б ещё в пределах перекрёстка (в зоне закругления края проезжей части) — там остановка запрещена ({p:15.9}). Разрешено только место В, дальше от перекрёстка."},"ref":["15.9","1.10"],"pic":["img/hsc/15-3-1.jpg"]},{"id":"h15-4","t":"h15","num":"15.4","q":{"uk":"Хто з водіїв, виконуючи зупинку, порушив Правила дорожнього руху?","ru":"Кто из водителей, выполняя остановку, нарушил Правила дорожного движения?"},"a":[{"uk":"Усі водії.","ru":"Все водители."},{"uk":"Тільки водій мотоцикла.","ru":"Только водитель мотоцикла.","w":{"uk":"Не лише мотоцикл: синій і фіолетовий автомобілі теж стоять ближче 10 м від переходу.","ru":"Не только мотоцикл: синий и фиолетовый автомобили тоже стоят ближе 10 м от перехода."}},{"uk":"Водії синього автомобіля і мотоцикла.","ru":"Водители синего автомобиля и мотоцикла.","w":{"uk":"Фіолетовий автомобіль також порушує: він зупинився ближче 10 м перед переходом.","ru":"Фиолетовый автомобиль тоже нарушает: он остановился ближе 10 м перед переходом."}},{"uk":"Водії фіолетового автомобіля і мотоцикла.","ru":"Водители фиолетового автомобиля и мотоцикла.","w":{"uk":"Синій автомобіль також порушує: він зупинився ближче 10 м за переходом.","ru":"Синий автомобиль тоже нарушает: он остановился ближе 10 м за переходом."}}],"c":0,"e":{"uk":"Зупинка заборонена на пішохідних переходах і ближче 10 м від них з обох боків ({p:15.9}). Мотоцикл стоїть просто на переході, синій автомобіль — одразу за ним, фіолетовий — одразу перед ним, тож порушують усі.","ru":"Остановка запрещена на пешеходных переходах и ближе 10 м от них с обеих сторон ({p:15.9}). Мотоцикл стоит прямо на переходе, синий автомобиль — сразу за ним, фиолетовый — сразу перед ним, поэтому нарушают все."},"ref":["15.9"],"pic":["img/hsc/15-4-1.jpg"]},{"id":"h15-5","t":"h15","num":"15.5","q":{"uk":"На якому з місць водієві легкового автомобіля дозволено зупинитися?","ru":"На каком из мест водителю легкового автомобиля разрешено остановиться?"},"a":[{"uk":"На місцях В і Д.","ru":"На местах В и Д.","w":{"uk":"Неповна відповідь: місце А теж за 10 м від переходу, тож там зупинитися можна.","ru":"Неполный ответ: место А тоже в 10 м от перехода, поэтому там остановиться можно."}},{"uk":"На місцях В, Г і Д.","ru":"На местах В, Г и Д.","w":{"uk":"Місце Г — на пішохідному переході, де зупинку заборонено.","ru":"Место Г — на пешеходном переходе, где остановка запрещена."}},{"uk":"На місцях А і Б.","ru":"На местах А и Б.","w":{"uk":"Місце Б ближче 10 м за переходом, тому там зупинятися не можна.","ru":"Место Б ближе 10 м за переходом, поэтому там останавливаться нельзя."}},{"uk":"На місцях А, В і Д.","ru":"На местах А, В и Д."}],"c":3,"e":{"uk":"Це дорога з одностороннім рухом у населеному пункті ({s:5.5}), тому зупинка дозволена і праворуч, і ліворуч ({p:15.3}), але не на пішохідному переході і не ближче 10 м від нього ({p:15.9}). Місця А, В і Д віддалені від переходу щонайменше на 10 м, а Б — ближче, Г — на самому переході.","ru":"Это дорога с односторонним движением в населённом пункте ({s:5.5}), поэтому остановка разрешена и справа, и слева ({p:15.3}), но не на пешеходном переходе и не ближе 10 м от него ({p:15.9}). Места А, В и Д удалены от перехода не менее чем на 10 м, а Б — ближе, Г — на самом переходе."},"ref":["15.3","15.9"],"pic":["img/hsc/15-5-1.jpg"]},{"id":"h15-6","t":"h15","num":"15.6","q":{"uk":"Хто з водіїв порушує правила зупинки?","ru":"Кто из водителей нарушает правила остановки?"},"a":[{"uk":"Усі водії.","ru":"Все водители.","w":{"uk":"Білий автомобіль не порушує: між ним і переходом 10 м.","ru":"Белый автомобиль не нарушает: между ним и переходом 10 м."}},{"uk":"Водії білого автомобіля і мотоцикла.","ru":"Водители белого автомобиля и мотоцикла.","w":{"uk":"Білий автомобіль зупинився за 10 м від переходу правильно, а зелений і синій, навпаки, порушують.","ru":"Белый автомобиль остановился в 10 м от перехода правильно, а зелёный и синий, наоборот, нарушают."}},{"uk":"Водії зеленого і синього автомобілів.","ru":"Водители зелёного и синего автомобилей.","w":{"uk":"Мотоцикл теж порушує: він стоїть ближче 10 м від переходу.","ru":"Мотоцикл тоже нарушает: он стоит ближе 10 м от перехода."}},{"uk":"Водії зеленого, синього автомобілів і мотоцикла.","ru":"Водители зелёного, синего автомобилей и мотоцикла."},{"uk":"Ніхто не порушує.","ru":"Никто не нарушает.","w":{"uk":"Зелений, синій автомобілі й мотоцикл стоять ближче 10 м від пішохідного переходу.","ru":"Зелёный, синий автомобили и мотоцикл стоят ближе 10 м от пешеходного перехода."}}],"c":3,"e":{"uk":"Зупинка заборонена на пішохідних переходах і ближче 10 м від них з обох боків ({p:15.9}). Зелений автомобіль і мотоцикл стоять ближче 10 м перед переходом, синій — ближче 10 м за ним; лише білий зупинився за 10 м від переходу.","ru":"Остановка запрещена на пешеходных переходах и ближе 10 м от них с обеих сторон ({p:15.9}). Зелёный автомобиль и мотоцикл стоят ближе 10 м перед переходом, синий — ближе 10 м за ним; только белый остановился в 10 м от перехода."},"ref":["15.9"],"pic":["img/hsc/15-6-1.jpg"]},{"id":"h15-7","t":"h15","num":"15.7","q":{"uk":"Який автомобіль зупинився з порушенням Правил дорожнього руху на дорозі з одностороннім рухом?","ru":"Какой автомобиль остановился с нарушением Правил дорожного движения на дороге с односторонним движением?"},"a":[{"uk":"Зелений і жовтий.","ru":"Зелёный и жёлтый.","w":{"uk":"Жовтий автомобіль стоїть за 10 м від переходу на лівому боці дороги з одностороннім рухом — це дозволено.","ru":"Жёлтый автомобиль стоит в 10 м от перехода на левой стороне дороги с односторонним движением — это разрешено."}},{"uk":"Жовтий, синій і білий.","ru":"Жёлтый, синий и белый.","w":{"uk":"Жовтий не порушує (до переходу 10 м), а зелений, навпаки, стоїть лише за 5 м від переходу.","ru":"Жёлтый не нарушает (до перехода 10 м), а зелёный, наоборот, стоит всего в 5 м от перехода."}},{"uk":"Синій і білий.","ru":"Синий и белый.","w":{"uk":"Неповна відповідь: зелений автомобіль теж порушує — до переходу лише 5 м.","ru":"Неполный ответ: зелёный автомобиль тоже нарушает — до перехода всего 5 м."}},{"uk":"Синій, білий і зелений.","ru":"Синий, белый и зелёный."},{"uk":"Усі транспортні засоби порушують.","ru":"Все транспортные средства нарушают.","w":{"uk":"Жовтий автомобіль зупинився правильно — за 10 м від переходу.","ru":"Жёлтый автомобиль остановился правильно — в 10 м от перехода."}}],"c":3,"e":{"uk":"На дорозі з одностороннім рухом зупинятися можна з обох боків ({p:15.3}), але не ближче 10 м від пішохідного переходу ({p:15.9}). Зелений (5 м за переходом), синій і білий стоять ближче 10 м від нього; жовтий зупинився за 10 м — правильно.","ru":"На дороге с односторонним движением останавливаться можно с обеих сторон ({p:15.3}), но не ближе 10 м от пешеходного перехода ({p:15.9}). Зелёный (в 5 м за переходом), синий и белый стоят ближе 10 м от него; жёлтый остановился в 10 м — правильно."},"ref":["15.3","15.9"],"pic":["img/hsc/15-7-1.jpg"]},{"id":"h15-8","t":"h15","num":"15.8","q":{"uk":"Хто з водіїв порушив Правила дорожнього руху, виконуючи зупинку?","ru":"Кто из водителей нарушил Правила дорожного движения, выполняя остановку?"},"a":[{"uk":"Тільки водій білого автомобіля.","ru":"Только водитель белого автомобиля.","w":{"uk":"Червоний автомобіль теж порушує: він стоїть ближче 10 м за переходом.","ru":"Красный автомобиль тоже нарушает: он стоит ближе 10 м за переходом."}},{"uk":"Тільки водій червоного автомобіля.","ru":"Только водитель красного автомобиля.","w":{"uk":"Білий автомобіль теж порушує: він стоїть ближче 10 м перед переходом.","ru":"Белый автомобиль тоже нарушает: он стоит ближе 10 м перед переходом."}},{"uk":"Обидва порушують.","ru":"Оба нарушают."},{"uk":"Ніхто не порушує.","ru":"Никто не нарушает.","w":{"uk":"Обидва автомобілі стоять ближче 10 м від пішохідного переходу.","ru":"Оба автомобиля стоят ближе 10 м от пешеходного перехода."}}],"c":2,"e":{"uk":"Червоний автомобіль зупинився одразу за пішохідним переходом, білий — одразу перед ним; обидва ближче 10 м від переходу, де зупинку заборонено ({p:15.9}).","ru":"Красный автомобиль остановился сразу за пешеходным переходом, белый — сразу перед ним; оба ближе 10 м от перехода, где остановка запрещена ({p:15.9})."},"ref":["15.9"],"pic":["img/hsc/15-8-1.jpg"]},{"id":"h15-9","t":"h15","num":"15.9","q":{"uk":"У якому з місць водієві дозволено виконати зупинку?","ru":"В каком из мест водителю разрешено выполнить остановку?"},"a":[{"uk":"У місці А.","ru":"В месте А."},{"uk":"У місці Б.","ru":"В месте Б.","w":{"uk":"У місці Б автомобіль стоїть на мосту, де зупинка заборонена.","ru":"В месте Б автомобиль стоит на мосту, где остановка запрещена."}},{"uk":"У місцях А і Б.","ru":"В местах А и Б.","w":{"uk":"Місце Б розташоване на мосту, тому зупинятися там не можна.","ru":"Место Б расположено на мосту, поэтому останавливаться там нельзя."}}],"c":0,"e":{"uk":"Місце А — на узбіччі перед мостом, де зупинятися дозволено ({p:15.1}). Місце Б уже на мосту, а на мостах зупинку заборонено ({p:15.9}).","ru":"Место А — на обочине перед мостом, где останавливаться разрешено ({p:15.1}). Место Б уже на мосту, а на мостах остановка запрещена ({p:15.9})."},"ref":["15.1","15.9"],"pic":["img/hsc/15-9-1.jpg"]},{"id":"h15-10","t":"h15","num":"15.10","q":{"uk":"Чи дозволено водієві жовтого автомобіля зупинитися в цьому місці?","ru":"Разрешено ли водителю жёлтого автомобиля остановиться в этом месте?"},"a":[{"uk":"Дозволено тільки для посадки (висадки) пасажирів.","ru":"Разрешено только для посадки (высадки) пассажиров.","w":{"uk":"Перед тунелем зупинку не обмежено лише посадкою (висадкою) пасажирів — вона дозволена з будь-якою метою.","ru":"Перед тоннелем остановка не ограничена только посадкой (высадкой) пассажиров — она разрешена с любой целью."}},{"uk":"Дозволено.","ru":"Разрешено."},{"uk":"Заборонено.","ru":"Запрещено.","w":{"uk":"Зупинку заборонено в самому тунелі, а не перед ним.","ru":"Остановка запрещена в самом тоннеле, а не перед ним."}}],"c":1,"e":{"uk":"Заборона {p:15.9} стосується зупинки **в тунелі**, а жовтий автомобіль стоїть ще перед в'їздом у нього. Інших заборон тут немає, тому зупинка дозволена.","ru":"Запрет {p:15.9} касается остановки **в тоннеле**, а жёлтый автомобиль стоит ещё перед въездом в него. Других запретов здесь нет, поэтому остановка разрешена."},"ref":["15.9"],"pic":["img/hsc/15-10-1.jpg"]},{"id":"h15-11","t":"h15","num":"15.11","q":{"uk":"Чи дозволено зупинитися в цьому місці для посадки пасажирів?","ru":"Разрешено ли остановиться в этом месте для посадки пассажиров?"},"a":[{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"У тунелі зупинятися заборонено, навіть щоб узяти пасажира.","ru":"В тоннеле останавливаться запрещено, даже чтобы взять пассажира."}},{"uk":"Заборонено.","ru":"Запрещено."},{"uk":"Дозволено тільки в світлий час доби.","ru":"Разрешено только в светлое время суток.","w":{"uk":"Заборона зупинки в тунелі не залежить від пори доби.","ru":"Запрет остановки в тоннеле не зависит от времени суток."}}],"c":1,"e":{"uk":"Автомобіль рухається тунелем, а в тунелях зупинку заборонено ({p:15.9}) — без винятку для посадки пасажирів.","ru":"Автомобиль движется по тоннелю, а в тоннелях остановка запрещена ({p:15.9}) — без исключения для посадки пассажиров."},"ref":["15.9"],"pic":["img/hsc/15-11-1.jpg"]},{"id":"h15-12","t":"h15","num":"15.12","q":{"uk":"Чи дозволено водієві зупинитися на мості в цьому місці?","ru":"Разрешено ли водителю остановиться на мосту в этом месте?"},"a":[{"uk":"Заборонено.","ru":"Запрещено."},{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"Автомобіль на мосту, а там зупинка заборонена.","ru":"Автомобиль на мосту, а там остановка запрещена."}},{"uk":"Дозволено тільки для посадки (висадки) пасажирів.","ru":"Разрешено только для посадки (высадки) пассажиров.","w":{"uk":"Заборона зупинки на мосту не має винятку для посадки (висадки) пасажирів.","ru":"Запрет остановки на мосту не имеет исключения для посадки (высадки) пассажиров."}}],"c":0,"e":{"uk":"На мостах зупинку заборонено ({p:15.9}), тож узяти пасажира посередині мосту не можна.","ru":"На мостах остановка запрещена ({p:15.9}), поэтому взять пассажира посередине моста нельзя."},"ref":["15.9"],"pic":["img/hsc/15-12-1.jpg"]},{"id":"h15-13","t":"h15","num":"15.13","q":{"uk":"Чи дозволено водієві білого автомобіля зупинитися для посадки пасажира в цьому місці?","ru":"Разрешено ли водителю белого автомобиля остановиться для посадки пассажира в этом месте?"},"a":[{"uk":"Заборонено.","ru":"Запрещено."},{"uk":"Дозволено на час до 5 хвилин.","ru":"Разрешено на время до 5 минут.","w":{"uk":"Заборона зупинки на шляхопроводі не залежить від її тривалості — навіть короткочасна зупинка тут не дозволена.","ru":"Запрет остановки на путепроводе не зависит от её продолжительности — даже кратковременная остановка здесь не разрешена."}},{"uk":"Дозволено в будь-якому випадку.","ru":"Разрешено в любом случае.","w":{"uk":"На шляхопроводі зупинятися заборонено, тож дозволу «в будь-якому випадку» немає.","ru":"На путепроводе останавливаться запрещено, поэтому разрешения «в любом случае» нет."}}],"c":0,"e":{"uk":"Білий автомобіль перебуває на шляхопроводі над іншою дорогою, а на мостах і шляхопроводах зупинку заборонено ({p:15.9}) — навіть для посадки пасажира.","ru":"Белый автомобиль находится на путепроводе над другой дорогой, а на мостах и путепроводах остановка запрещена ({p:15.9}) — даже для посадки пассажира."},"ref":["15.9"],"pic":["img/hsc/15-13-1.jpg"]},{"id":"h15-14","t":"h15","num":"15.14","q":{"uk":"Хто з водіїв порушив Правила дорожнього руху, виконавши зупинку?","ru":"Кто из водителей нарушил Правила дорожного движения, выполнив остановку?"},"a":[{"uk":"Тільки водії чорного автомобіля й автобуса.","ru":"Только водители чёрного автомобиля и автобуса.","w":{"uk":"Сірий автомобіль теж порушує: під шляхопроводом зупинка заборонена так само, як і на ньому.","ru":"Серый автомобиль тоже нарушает: под путепроводом остановка запрещена так же, как и на нём."}},{"uk":"Тільки водії автобуса і сірого автомобіля.","ru":"Только водители автобуса и серого автомобиля.","w":{"uk":"Чорний автомобіль теж порушує: він зупинився на шляхопроводі.","ru":"Чёрный автомобиль тоже нарушает: он остановился на путепроводе."}},{"uk":"Водії всіх транспортних засобів порушують.","ru":"Водители всех транспортных средств нарушают."}],"c":2,"e":{"uk":"Зупинку заборонено на шляхопроводах **і під ними** ({p:15.9}). Чорний автомобіль і автобус стоять на шляхопроводі, а сірий автомобіль — під ним, тож порушують усі.","ru":"Остановка запрещена на путепроводах **и под ними** ({p:15.9}). Чёрный автомобиль и автобус стоят на путепроводе, а серый автомобиль — под ним, поэтому нарушают все."},"ref":["15.9"],"pic":["img/hsc/15-14-1.jpg"]},{"id":"h15-15","t":"h15","num":"15.15","q":{"uk":"У якому місці водієві легкового автомобіля дозволено зупинитися?","ru":"В каком месте водителю легкового автомобиля разрешено остановиться?"},"a":[{"uk":"У місцях А та Д.","ru":"В местах А и Д."},{"uk":"У місцях А, В і Д.","ru":"В местах А, В и Д.","w":{"uk":"Місце В — біля посадкового майданчика, де зупинятися легковому автомобілю заборонено.","ru":"Место В — у посадочной площадки, где останавливаться легковому автомобилю запрещено."}},{"uk":"У місці В.","ru":"В месте В.","w":{"uk":"Біля посадкового майданчика маршрутних транспортних засобів легковому автомобілю зупинятися заборонено.","ru":"У посадочной площадки маршрутных транспортных средств легковому автомобилю останавливаться запрещено."}},{"uk":"У місцях Г і Д.","ru":"В местах Г и Д.","w":{"uk":"Місце Г — ближче 30 м за посадковим майданчиком, тому там зупинятися не можна.","ru":"Место Г — ближе 30 м за посадочной площадкой, поэтому там останавливаться нельзя."}},{"uk":"У всіх місцях.","ru":"Во всех местах.","w":{"uk":"Місця Б, В і Г розташовані ближче 30 м від посадкового майданчика, де зупинку заборонено.","ru":"Места Б, В и Г расположены ближе 30 м от посадочной площадки, где остановка запрещена."}}],"c":0,"e":{"uk":"Зупинка заборонена ближче 30 м від посадкового майданчика для зупинки маршрутних транспортних засобів з обох боків ({p:15.9}). Місце В — біля самого майданчика, Б і Г — у межах 30 м від нього; лише А і Д розташовані далі.","ru":"Остановка запрещена ближе 30 м от посадочной площадки для остановки маршрутных транспортных средств с обеих сторон ({p:15.9}). Место В — у самой площадки, Б и Г — в пределах 30 м от неё; только А и Д расположены дальше."},"ref":["15.9"],"pic":["img/hsc/15-15-1.jpg"]},{"id":"h15-16","t":"h15","num":"15.16","q":{"uk":"За яких умов водієві дозволено зупинитися в цьому місці?","ru":"При каких условиях водителю разрешено остановиться в этом месте?"},"a":[{"uk":"Якщо відстань між транспортним засобом і суцільною розміткою становить не менше 2 м.","ru":"Если расстояние между транспортным средством и сплошной разметкой составляет не менее 2 м.","w":{"uk":"Правила вимагають щонайменше 3 м до суцільної лінії, а не 2 м.","ru":"Правила требуют не менее 3 м до сплошной линии, а не 2 м."}},{"uk":"Якщо відстань між транспортним засобом і суцільною розміткою становить не менше 3 м.","ru":"Если расстояние между транспортным средством и сплошной разметкой составляет не менее 3 м."},{"uk":"Зупинка в цьому місці дозволена в будь-якому випадку","ru":"Остановка в этом месте разрешена в любом случае.","w":{"uk":"Безумовного дозволу немає: якщо до суцільної лінії залишиться менше ніж 3 м, зупинку заборонено.","ru":"Безусловного разрешения нет: если до сплошной линии останется менее 3 м, остановка запрещена."}}],"c":1,"e":{"uk":"Зупинка заборонена там, де між транспортним засобом, що зупинився, і суцільною лінією розмітки залишається **менше ніж 3 м** ({p:15.9}). Отже, зупинитися тут можна лише тоді, коли ця відстань становить не менше 3 м.","ru":"Остановка запрещена там, где между остановившимся транспортным средством и сплошной линией разметки остаётся **менее 3 м** ({p:15.9}). Следовательно, остановиться здесь можно, только если это расстояние составляет не менее 3 м."},"ref":["15.9"],"pic":["img/hsc/15-16-1.jpg"]},{"id":"h15-17","t":"h15","num":"15.17","q":{"uk":"Чи дозволено водієві зупинитися в цьому місці?","ru":"Разрешено ли водителю остановиться в этом месте?"},"a":[{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"Автомобіль сам займає частину цих 3 м, тож до суцільної лінії залишиться менше 3 м, а це заборонено.","ru":"Автомобиль сам занимает часть этих 3 м, поэтому до сплошной линии останется менее 3 м, а это запрещено."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":1,"e":{"uk":"Між суцільною лінією розмітки і краєм проїзної частини лише 3 м, тож після зупинки до суцільної лінії залишиться менше ніж 3 м — у такому місці зупинку заборонено ({p:15.9}).","ru":"Между сплошной линией разметки и краем проезжей части всего 3 м, поэтому после остановки до сплошной линии останется менее 3 м — в таком месте остановка запрещена ({p:15.9})."},"ref":["15.9"],"pic":["img/hsc/15-17-1.jpg"]},{"id":"h15-18","t":"h15","num":"15.18","q":{"uk":"Яка мінімальна відстань має бути між транспортним засобом, що зупинився, і протилежним краєм проїзної частини, щоб зупинка була виконана без порушень Правил дорожнього руху?","ru":"Каким должно быть минимальное расстояние между остановившимся транспортным средством и противоположным краем проезжей части, чтобы остановка была выполнена без нарушения Правил дорожного движения?"},"a":[{"uk":"1,5 м.","ru":"1,5 м.","w":{"uk":"1,5 м замало: Правила вимагають залишати щонайменше 3 м.","ru":"1,5 м недостаточно: Правила требуют оставлять не менее 3 м."}},{"uk":"2 м.","ru":"2 м.","w":{"uk":"2 м замало: Правила вимагають залишати щонайменше 3 м.","ru":"2 м недостаточно: Правила требуют оставлять не менее 3 м."}},{"uk":"2,75 м.","ru":"2,75 м.","w":{"uk":"2,75 м — це мінімальна ширина смуги руху, а для зупинки потрібно залишити щонайменше 3 м.","ru":"2,75 м — это минимальная ширина полосы движения, а для остановки нужно оставить не менее 3 м."}},{"uk":"3 м.","ru":"3 м."},{"uk":"4 м.","ru":"4 м.","w":{"uk":"Правила не вимагають 4 м: достатньо 3 м.","ru":"Правила не требуют 4 м: достаточно 3 м."}}],"c":3,"e":{"uk":"Зупинку заборонено в місцях, де відстань між протилежним краєм проїзної частини і транспортним засобом, що зупинився, **менше ніж 3 м** ({p:15.9}), тож мінімально допустима відстань — 3 м.","ru":"Остановка запрещена в местах, где расстояние между противоположным краем проезжей части и остановившимся транспортным средством **менее 3 м** ({p:15.9}), поэтому минимально допустимое расстояние — 3 м."},"ref":["15.9"],"pic":["img/hsc/15-18-1.jpg"]},{"id":"h15-19","t":"h15","num":"15.19","q":{"uk":"У яких випадках, згідно з Правилами дорожнього руху, на проїзній частині дозволяється установка предметів, що перешкоджають проїзду або паркуванню транспортних засобів?","ru":"В каких случаях, согласно Правилам дорожного движения, на проезжей части разрешается установка предметов, препятствующих проезду или парковке транспортных средств?"},"a":[{"uk":"У разі оформлення дорожньо-транспортної пригоди.","ru":"При оформлении дорожно-транспортного происшествия.","w":{"uk":"Неповна відповідь: таких винятків три, оформлення ДТП — лише один із них.","ru":"Неполный ответ: таких исключений три, оформление ДТП — лишь одно из них."}},{"uk":"У разі виконання дорожніх робіт або робіт, пов'язаних із зайняттям проїзної частини.","ru":"При выполнении дорожных работ или работ, связанных с занятием проезжей части.","w":{"uk":"Неповна відповідь: крім дорожніх робіт, винятками є також оформлення ДТП і обмеження руху за законом.","ru":"Неполный ответ: кроме дорожных работ, исключениями являются также оформление ДТП и ограничение движения по закону."}},{"uk":"У разі обмеження або заборони руху транспортних засобів та пішоходів у випадках, передбачених законодавством.","ru":"При ограничении или запрете движения транспортных средств и пешеходов в случаях, предусмотренных законодательством.","w":{"uk":"Неповна відповідь: винятками є також оформлення ДТП і дорожні роботи.","ru":"Неполный ответ: исключениями являются также оформление ДТП и дорожные работы."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3."}],"c":3,"e":{"uk":"{p:15.15} забороняє ставити на проїзній частині предмети, що перешкоджають проїзду чи паркуванню, але робить три винятки: оформлення ДТП, дорожні роботи (або роботи із зайняттям проїзної частини) та обмеження чи заборона руху у випадках, передбачених законодавством.","ru":"{p:15.15} запрещает устанавливать на проезжей части предметы, препятствующие проезду или парковке, но делает три исключения: оформление ДТП, дорожные работы (или работы с занятием проезжей части) и ограничение или запрет движения в случаях, предусмотренных законодательством."},"ref":["15.15"],"pic":["img/hsc/15-19-1.jpg"]},{"id":"h15-20","t":"h15","num":"15.20","q":{"uk":"Чи дозволена стоянка білого автомобіля в цьому місці?","ru":"Разрешена ли стоянка белого автомобиля в этом месте?"},"a":[{"uk":"Дозволена.","ru":"Разрешена.","w":{"uk":"До контейнерів лише 3 м, а стоянка дозволена не ближче ніж за 5 м від них.","ru":"До контейнеров всего 3 м, а стоянка разрешена не ближе чем в 5 м от них."}},{"uk":"Заборонена.","ru":"Запрещена."}],"c":1,"e":{"uk":"Стоянку заборонено ближче 5 м від контейнерів для збирання побутових відходів ({p:15.10}), а білий автомобіль стоїть лише за 3 м від них.","ru":"Стоянка запрещена ближе 5 м от контейнеров для сбора бытовых отходов ({p:15.10}), а белый автомобиль стоит всего в 3 м от них."},"ref":["15.10"],"pic":["img/hsc/15-20-1.jpg"]},{"id":"h15-21","t":"h15","num":"15.21","q":{"uk":"Чи дозволена стоянка автомобіля в цьому місці?","ru":"Разрешена ли стоянка автомобиля в этом месте?"},"a":[{"uk":"Заборонена в будь-якому випадку.","ru":"Запрещена в любом случае.","w":{"uk":"Безумовної заборони стоянки в такому місці немає — вона залежить від того, чи заважатиме автомобіль іншим.","ru":"Безусловного запрета стоянки в таком месте нет — он зависит от того, будет ли автомобиль мешать другим."}},{"uk":"Дозволена.","ru":"Разрешена.","w":{"uk":"Дозвіл не безумовний: якщо автомобіль заблокує проїзд чи прохід пішоходів, стоянка заборонена.","ru":"Разрешение не безусловно: если автомобиль заблокирует проезд или проход пешеходов, стоянка запрещена."}},{"uk":"Заборонена, якщо транспортний засіб унеможливить рух інших транспортних засобів або створить перешкоду для руху пішоходів.","ru":"Запрещена, если транспортное средство сделает невозможным движение других транспортных средств или создаст помеху для движения пешеходов."}],"c":2,"e":{"uk":"Окремої заборони стоянки у дворі немає, але {p:15.10} забороняє її там, де транспортний засіб, що стоїть, **унеможливить рух** інших транспортних засобів або створить перешкоду для руху пішоходів. У вузькому проїзді між будинками саме від цього залежить, чи можна тут стояти.","ru":"Отдельного запрета стоянки во дворе нет, но {p:15.10} запрещает её там, где стоящее транспортное средство **сделает невозможным движение** других транспортных средств или создаст помеху для движения пешеходов. В узком проезде между домами именно от этого зависит, можно ли здесь стоять."},"ref":["15.10"],"pic":["img/hsc/15-21-1.jpg"]},{"id":"h15-22","t":"h15","num":"15.22","q":{"uk":"Чи дозволено водієві чорного автомобіля виконати стоянку в цьому місці дороги, що знаходиться за межами населених пунктів, якщо оглядовість в одному з напрямків менше 100 м?","ru":"Разрешено ли водителю чёрного автомобиля выполнить стоянку в этом месте дороги, находящемся за пределами населённых пунктов, если обзорность в одном из направлений менее 100 м?"},"a":[{"uk":"Заборонено.","ru":"Запрещено."},{"uk":"Дозволено в будь-якому випадку.","ru":"Разрешено в любом случае.","w":{"uk":"Небезпечний поворот з оглядовістю менше 100 м — саме те місце, де стоянку заборонено.","ru":"Опасный поворот с обзорностью менее 100 м — именно то место, где стоянка запрещена."}},{"uk":"Дозволено, якщо включені денні ходові вогні.","ru":"Разрешено, если включены дневные ходовые огни.","w":{"uk":"Денні ходові вогні не скасовують заборони стоянки на небезпечному повороті з поганою оглядовістю.","ru":"Дневные ходовые огни не отменяют запрета стоянки на опасном повороте с плохой обзорностью."}}],"c":0,"e":{"uk":"Поза населеними пунктами стоянку заборонено в зоні небезпечних поворотів (тут — знак {s:1.1}) з видимістю або оглядовістю **менше ніж 100 м** хоча б в одному напрямку руху ({p:15.10}).","ru":"Вне населённых пунктов стоянка запрещена в зоне опасных поворотов (здесь — знак {s:1.1}) с видимостью или обзорностью **менее 100 м** хотя бы в одном направлении движения ({p:15.10})."},"ref":["15.10"],"pic":["img/hsc/15-22-1.jpg"]},{"id":"h15-23","t":"h15","num":"15.23","q":{"uk":"У якому місці водієві легкового автомобіля дозволено виконати стоянку?","ru":"В каком месте водителю легкового автомобиля разрешено выполнить стоянку?"},"a":[{"uk":"У місцях А та Б.","ru":"В местах А и Б.","w":{"uk":"Місце Б розташоване біля самого переїзду, ближче 50 м від нього.","ru":"Место Б расположено у самого переезда, ближе 50 м от него."}},{"uk":"У місцях В і Г.","ru":"В местах В и Г.","w":{"uk":"Місце В розташоване одразу за переїздом, ближче 50 м від нього.","ru":"Место В расположено сразу за переездом, ближе 50 м от него."}},{"uk":"У місцях А та Г.","ru":"В местах А и Г."},{"uk":"У місцях А, В і Г.","ru":"В местах А, В и Г.","w":{"uk":"Місце В зайве: воно ближче 50 м від залізничного переїзду.","ru":"Место В лишнее: оно ближе 50 м от железнодорожного переезда."}}],"c":2,"e":{"uk":"Стоянку заборонено ближче 50 м від залізничних переїздів ({p:15.10}). Місця Б і В розташовані безпосередньо біля переїзду, а А і Г — далі від нього, тому стоянка дозволена лише в місцях А і Г.","ru":"Стоянка запрещена ближе 50 м от железнодорожных переездов ({p:15.10}). Места Б и В расположены непосредственно у переезда, а А и Г — дальше от него, поэтому стоянка разрешена только в местах А и Г."},"ref":["15.10"],"pic":["img/hsc/15-23-1.jpg"]},{"id":"h15-24","t":"h15","num":"15.24","q":{"uk":"Хто з водіїв правильно виконує стоянку?","ru":"Кто из водителей правильно выполняет стоянку?"},"a":[{"uk":"Усі водії.","ru":"Все водители.","w":{"uk":"Фіолетовий і червоний автомобілі стоять ближче 50 м від переїзду, а це заборонено.","ru":"Фиолетовый и красный автомобили стоят ближе 50 м от переезда, а это запрещено."}},{"uk":"Водії фіолетового, білого і синього автомобілів.","ru":"Водители фиолетового, белого и синего автомобилей.","w":{"uk":"Фіолетовий автомобіль стоїть біля самого переїзду, ближче 50 м від нього.","ru":"Фиолетовый автомобиль стоит у самого переезда, ближе 50 м от него."}},{"uk":"Водії червоного і синього автомобілів.","ru":"Водители красного и синего автомобилей.","w":{"uk":"Червоний автомобіль стоїть біля самого переїзду, ближче 50 м від нього.","ru":"Красный автомобиль стоит у самого переезда, ближе 50 м от него."}},{"uk":"Водії білого і синього автомобілів.","ru":"Водители белого и синего автомобилей."},{"uk":"Водії фіолетового і білого автомобілів.","ru":"Водители фиолетового и белого автомобилей.","w":{"uk":"Фіолетовий автомобіль стоїть ближче 50 м від переїзду, а синій, навпаки, поставлено правильно.","ru":"Фиолетовый автомобиль стоит ближе 50 м от переезда, а синий, наоборот, поставлен правильно."}}],"c":3,"e":{"uk":"Стоянку заборонено ближче 50 м від залізничного переїзду ({p:15.10}). Фіолетовий і червоний автомобілі стоять біля самого переїзду, а білий і синій — далі, за попереджувальними знаками, тому правильно поставлені лише вони.","ru":"Стоянка запрещена ближе 50 м от железнодорожного переезда ({p:15.10}). Фиолетовый и красный автомобили стоят у самого переезда, а белый и синий — дальше, за предупреждающими знаками, поэтому правильно поставлены только они."},"ref":["15.10"],"pic":["img/hsc/15-24-1.jpg"]},{"id":"h15-25","t":"h15","num":"15.25","q":{"uk":"Чим може бути зумовлена зупинка, щоб вона вважалася вимушеною?","ru":"Чем может быть обусловлена остановка, чтобы она считалась вынужденной?"},"a":[{"uk":"Технічною несправністю автомобіля або небезпекою, спричиненою вантажем, який перевозиться.","ru":"Технической неисправностью автомобиля или опасностью, вызванной перевозимым грузом.","w":{"uk":"Неповна відповідь: вимушеною зупинка буває також через стан учасника руху чи появу перешкоди.","ru":"Неполный ответ: вынужденной остановка бывает также из-за состояния участника движения или появления препятствия."}},{"uk":"Станом учасника дорожнього руху.","ru":"Состоянием участника дорожного движения.","w":{"uk":"Неповна відповідь: вимушену зупинку може зумовити й несправність, небезпека від вантажу чи перешкода.","ru":"Неполный ответ: вынужденную остановку может вызвать и неисправность, опасность от груза или препятствие."}},{"uk":"Появою перешкоди для руху.","ru":"Появлением препятствия для движения.","w":{"uk":"Неповна відповідь: поява перешкоди — лише одна з причин вимушеної зупинки.","ru":"Неполный ответ: появление препятствия — лишь одна из причин вынужденной остановки."}},{"uk":"Усім переліченим вище.","ru":"Всем перечисленным выше."},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2.","w":{"uk":"Неповна відповідь: бракує появи перешкоди для руху, яка теж є підставою для вимушеної зупинки.","ru":"Неполный ответ: не хватает появления препятствия для движения, которое тоже является основанием для вынужденной остановки."}}],"c":3,"e":{"uk":"За {p:1.10} вимушена зупинка — припинення руху через технічну несправність транспортного засобу чи небезпеку від вантажу, **стан учасника дорожнього руху** або **появу перешкоди для руху**, тобто через будь-яку з перелічених причин.","ru":"Согласно {p:1.10} вынужденная остановка — прекращение движения из-за технической неисправности транспортного средства или опасности от груза, **состояния участника дорожного движения** или **появления препятствия для движения**, то есть по любой из перечисленных причин."},"ref":["1.10"],"pic":["img/hsc/15-25-1.jpg"]},{"id":"h15-26","t":"h15","num":"15.26","q":{"uk":"Хто з водіїв порушив правила зупинки в місці виїзду з двору?","ru":"Кто из водителей нарушил правила остановки в месте выезда со двора?"},"a":[{"uk":"Тільки водій жовтого автомобіля.","ru":"Только водитель жёлтого автомобиля.","w":{"uk":"Синій автомобіль теж порушує: він стоїть ближче 10 м від виїзду з двору.","ru":"Синий автомобиль тоже нарушает: он стоит ближе 10 м от выезда со двора."}},{"uk":"Тільки водій синього автомобіля.","ru":"Только водитель синего автомобиля.","w":{"uk":"Жовтий автомобіль теж порушує: він зупинився просто в місці виїзду.","ru":"Жёлтый автомобиль тоже нарушает: он остановился прямо в месте выезда."}},{"uk":"Усі порушують.","ru":"Все нарушают.","w":{"uk":"Сірий автомобіль зупинився за 10 м від виїзду — це дозволено.","ru":"Серый автомобиль остановился в 10 м от выезда — это разрешено."}},{"uk":"Водії синього і жовтого автомобілів.","ru":"Водители синего и жёлтого автомобилей."},{"uk":"Водії сірого і жовтого автомобілів.","ru":"Водители серого и жёлтого автомобилей.","w":{"uk":"Сірий автомобіль не порушує (до виїзду 10 м), а синій, навпаки, стоїть ближче 10 м від нього.","ru":"Серый автомобиль не нарушает (до выезда 10 м), а синий, наоборот, стоит ближе 10 м от него."}}],"c":3,"e":{"uk":"Зупинку заборонено безпосередньо в місці виїзду з прилеглої території і ближче 10 м від нього ({p:15.9}). Жовтий автомобіль загородив виїзд з двору, синій стоїть у межах 10 м від нього, а сірий — за 10 м, тож він не порушує.","ru":"Остановка запрещена непосредственно в месте выезда с прилегающей территории и ближе 10 м от него ({p:15.9}). Жёлтый автомобиль загородил выезд со двора, синий стоит в пределах 10 м от него, а серый — в 10 м, поэтому он не нарушает."},"ref":["15.9","1.10"],"pic":["img/hsc/15-26-1.jpg"]},{"id":"h15-27","t":"h15","num":"15.27","q":{"uk":"Чи дозволена зупинка транспортних засобів один навпроти одного, як показано на малюнку?","ru":"Разрешена ли остановка транспортных средств друг напротив друга, как показано на рисунке?"},"a":[{"uk":"Заборонено в будь-якому випадку.","ru":"Запрещено в любом случае.","w":{"uk":"Безумовної заборони немає: якщо інші транспортні засоби можуть роз'їхатися й об'їхати ті, що зупинилися, зупинка дозволена.","ru":"Безусловного запрета нет: если другие транспортные средства могут разъехаться и объехать остановившиеся, остановка разрешена."}},{"uk":"Дозволено, якщо буде можливий зустрічний роз'їзд або об'їзд транспортних засобів, що зупинилися.","ru":"Разрешено, если будет возможен встречный разъезд или объезд остановившихся транспортных средств."}],"c":1,"e":{"uk":"Окремої заборони зупинятися навпроти іншого транспортного засобу немає; {p:15.9} забороняє зупинку лише там, де стане **неможливим зустрічний роз'їзд або об'їзд** транспортного засобу, що зупинився.","ru":"Отдельного запрета останавливаться напротив другого транспортного средства нет; {p:15.9} запрещает остановку только там, где станет **невозможен встречный разъезд или объезд** остановившегося транспортного средства."},"ref":["15.9"],"pic":["img/hsc/15-27-1.jpg"]},{"id":"h15-28","t":"h15","num":"15.28","q":{"uk":"Чи може водій виконати посадку (висадку) пасажирів у зоні виконання дорожніх робіт?","ru":"Может ли водитель выполнить посадку (высадку) пассажиров в зоне выполнения дорожных работ?"},"a":[{"uk":"Може.","ru":"Может.","w":{"uk":"Посадка (висадка) пасажирів — теж зупинка, а в зоні дорожніх робіт її заборонено.","ru":"Посадка (высадка) пассажиров — тоже остановка, а в зоне дорожных работ она запрещена."}},{"uk":"Не може.","ru":"Не может."}],"c":1,"e":{"uk":"Знак {s:1.37} попереджає про дорожні роботи. Зупинку заборонено ближче 10 м від позначеного місця їх виконання і в зоні робіт, де вона створить перешкоди технологічним транспортним засобам ({p:15.9}); виняток для посадки (висадки) пасажирів не передбачено.","ru":"Знак {s:1.37} предупреждает о дорожных работах. Остановка запрещена ближе 10 м от обозначенного места их выполнения и в зоне работ, где она создаст помехи технологическим транспортным средствам ({p:15.9}); исключения для посадки (высадки) пассажиров не предусмотрено."},"ref":["15.9"],"pic":["img/hsc/15-28-1.jpg"]},{"id":"h15-29","t":"h15","num":"15.29","q":{"uk":"На якій відстані до позначеного місця виконання дорожніх робіт заборонено зупинку транспортних засобів?","ru":"На каком расстоянии от обозначенного места выполнения дорожных работ запрещена остановка транспортных средств?"},"a":[{"uk":"Ближче 10 м.","ru":"Ближе 10 м."},{"uk":"Ближче 15 м.","ru":"Ближе 15 м.","w":{"uk":"Такої відстані Правила не встановлюють: для місця дорожніх робіт це 10 м.","ru":"Такого расстояния Правила не устанавливают: для места дорожных работ это 10 м."}},{"uk":"Ближче 30 м.","ru":"Ближе 30 м.","w":{"uk":"30 м стосується посадкових майданчиків маршрутних транспортних засобів, а не дорожніх робіт.","ru":"30 м касается посадочных площадок маршрутных транспортных средств, а не дорожных работ."}}],"c":0,"e":{"uk":"За {p:15.9} зупинку заборонено **ближче 10 м** від позначеного місця виконання дорожніх робіт (тут його позначено знаками {s:1.37} і {s:4.8}).","ru":"Согласно {p:15.9} остановка запрещена **ближе 10 м** от обозначенного места выполнения дорожных работ (здесь оно обозначено знаками {s:1.37} и {s:4.8})."},"ref":["15.9"],"pic":["img/hsc/15-29-1.jpg"]},{"id":"h15-30","t":"h15","num":"15.30","q":{"uk":"Чи дозволено водієві зупинитися в цьому місці?","ru":"Разрешено ли водителю остановиться в этом месте?"},"a":[{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"Відстань 30 м до зупинки автобуса дотримано, проте до пішохідного переходу менше 10 м.","ru":"Расстояние 30 м до остановки автобуса соблюдено, однако до пешеходного перехода менее 10 м."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":1,"e":{"uk":"До посадкового майданчика тут 30 м, тож ця вимога виконана, але автомобіль зупиняється безпосередньо перед пішохідним переходом, а зупинка ближче 10 м від переходу заборонена ({p:15.9}).","ru":"До посадочной площадки здесь 30 м, так что это требование выполнено, но автомобиль останавливается непосредственно перед пешеходным переходом, а остановка ближе 10 м от перехода запрещена ({p:15.9})."},"ref":["15.9"],"pic":["img/hsc/15-30-1.jpg"]},{"id":"h15-31","t":"h15","num":"15.31","q":{"uk":"Хто з водіїв, виконуючи зупинку, порушує Правила дорожнього руху?","ru":"Кто из водителей, выполняя остановку, нарушает Правила дорожного движения?"},"a":[{"uk":"Обидва водії","ru":"Оба водителя.","w":{"uk":"Жовтий автомобіль не порушує: він стоїть на протилежному боці, а не біля посадкового майданчика.","ru":"Жёлтый автомобиль не нарушает: он стоит на противоположной стороне, а не у посадочной площадки."}},{"uk":"Водій жовтого автомобіля.","ru":"Водитель жёлтого автомобиля.","w":{"uk":"Жовтий автомобіль зупинився на своєму боці дороги навпроти майданчика — заборона на нього не поширюється.","ru":"Жёлтый автомобиль остановился на своей стороне дороги напротив площадки — запрет на него не распространяется."}},{"uk":"Водій червоного автомобіля.","ru":"Водитель красного автомобиля."}],"c":2,"e":{"uk":"Червоний автомобіль зупинився біля посадкового майданчика маршрутних транспортних засобів, а ближче 30 м від нього зупинку заборонено ({p:15.9}). Жовтий автомобіль стоїть на протилежному боці дороги, де ця заборона не діє.","ru":"Красный автомобиль остановился у посадочной площадки маршрутных транспортных средств, а ближе 30 м от неё остановка запрещена ({p:15.9}). Жёлтый автомобиль стоит на противоположной стороне дороги, где этот запрет не действует."},"ref":["15.9"],"pic":["img/hsc/15-31-1.jpg"]},{"id":"h15-32","t":"h15","num":"15.32","q":{"uk":"Чи має право водій легкового автомобіля виконати зупинку в цьому місці?","ru":"Имеет ли право водитель легкового автомобиля выполнить остановку в этом месте?"},"a":[{"uk":"Має право в будь-якому випадку.","ru":"Имеет право в любом случае.","w":{"uk":"Відстань від переходу дотримано, але до суцільної лінії залишиться менше ніж 3 м, а це заборонено.","ru":"Расстояние от перехода соблюдено, но до сплошной линии останется менее 3 м, а это запрещено."}},{"uk":"Не має права.","ru":"Не имеет права."}],"c":1,"e":{"uk":"До пішохідного переходу 10 м, але між суцільною лінією розмітки і краєм проїзної частини лише 3 м, тож до суцільної лінії залишиться менше ніж 3 м — тут зупинку заборонено ({p:15.9}).","ru":"До пешеходного перехода 10 м, но между сплошной линией разметки и краем проезжей части всего 3 м, поэтому до сплошной линии останется менее 3 м — здесь остановка запрещена ({p:15.9})."},"ref":["15.9"],"pic":["img/hsc/15-32-1.jpg"]},{"id":"h15-33","t":"h15","num":"15.33","q":{"uk":"Чи дозволяється водієві зеленого автомобіля зупинитися в цьому місці без необхідності посадки (висадки) пасажирів, якщо це не вимагається Правилами дорожнього руху?","ru":"Разрешается ли водителю зелёного автомобиля остановиться в этом месте без необходимости посадки (высадки) пассажиров, если это не требуется Правилами дорожного движения?"},"a":[{"uk":"Дозволяється.","ru":"Разрешается.","w":{"uk":"На трамвайній колії біля правого краю зупинятися без потреби посадки (висадки) пасажирів чи виконання вимог Правил не можна.","ru":"На трамвайных путях у правого края останавливаться без необходимости посадки (высадки) пассажиров или выполнения требований Правил нельзя."}},{"uk":"Забороняється.","ru":"Запрещается."}],"c":1,"e":{"uk":"Зелений автомобіль стоїть на трамвайній колії попутного напрямку біля правого краю проїзної частини. Там зупинка дозволена лише для посадки (висадки) пасажирів чи виконання вимог Правил ({p:15.8}), інакше — заборонена ({p:15.9}).","ru":"Зелёный автомобиль стоит на трамвайных путях попутного направления у правого края проезжей части. Там остановка разрешена только для посадки (высадки) пассажиров или выполнения требований Правил ({p:15.8}), иначе — запрещена ({p:15.9})."},"ref":["15.8","15.9"],"pic":["img/hsc/15-33-1.jpg"]},{"id":"h15-34","t":"h15","num":"15.34","q":{"uk":"Який транспортний засіб поставлено на стоянку неправильно?","ru":"Какое транспортное средство поставлено на стоянку неправильно?"},"a":[{"uk":"Усі поставлені правильно.","ru":"Все поставлены правильно.","w":{"uk":"Вантажний автомобіль поставлено неправильно: табличка дозволяє такий спосіб лише легковим автомобілям і мотоциклам.","ru":"Грузовой автомобиль поставлен неправильно: табличка разрешает такой способ только легковым автомобилям и мотоциклам."}},{"uk":"Вантажний автомобіль.","ru":"Грузовой автомобиль."},{"uk":"Мотоцикл із боковим причепом.","ru":"Мотоцикл с боковым прицепом.","w":{"uk":"Мотоцикл, зокрема з боковим причепом, може стояти так, як показано на табличці, — дозвіл поширюється на мотоцикли.","ru":"Мотоцикл, в том числе с боковым прицепом, может стоять так, как показано на табличке, — разрешение распространяется на мотоциклы."}}],"c":1,"e":{"uk":"Знак {s:5.43} з табличкою, що показує поставлення частково на тротуарі, дозволяє так ставити **лише легкові автомобілі й мотоцикли** ({p:15.6}). Вантажний автомобіль, поставлений частково на тротуар, цю вимогу порушує.","ru":"Знак {s:5.43} с табличкой, показывающей постановку частично на тротуаре, разрешает так ставить **только легковые автомобили и мотоциклы** ({p:15.6}). Грузовой автомобиль, поставленный частично на тротуар, нарушает это требование."},"ref":["15.6","15.10"],"pic":["img/hsc/15-34-1.jpg"]},{"id":"h15-35","t":"h15","num":"15.35","q":{"uk":"Чи правильно водій червоного автомобіля виконує посадку (висадку) пасажирів?","ru":"Правильно ли водитель красного автомобиля выполняет посадку (высадку) пассажиров?"},"a":[{"uk":"Правильно.","ru":"Правильно.","w":{"uk":"Зупинка в другому ряду заборонена, і посадка (висадка) пасажирів її не виправдовує.","ru":"Остановка во втором ряду запрещена, и посадка (высадка) пассажиров её не оправдывает."}},{"uk":"Неправильно.","ru":"Неправильно."}],"c":1,"e":{"uk":"Червоний автомобіль зупинився в другому ряду, поруч із транспортними засобами, що стоять біля краю проїзної частини, а ставити транспортні засоби на проїзній частині у два і більше ряди заборонено ({p:15.4}) — навіть для посадки (висадки) пасажирів.","ru":"Красный автомобиль остановился во втором ряду, рядом с транспортными средствами, стоящими у края проезжей части, а ставить транспортные средства на проезжей части в два и более ряда запрещено ({p:15.4}) — даже для посадки (высадки) пассажиров."},"ref":["15.4","15.2"],"pic":["img/hsc/15-35-1.jpg"]},{"id":"h15-36","t":"h15","num":"15.36","q":{"uk":"У якому місці цієї дороги з одностороннім рухом водієві легкового автомобіля дозволено виконати зупинку?","ru":"В каком месте этой дороги с односторонним движением водителю легкового автомобиля разрешено выполнить остановку?"},"a":[{"uk":"Тільки в місці Б.","ru":"Только в месте Б.","w":{"uk":"Неповна відповідь: на дорозі з одностороннім рухом можна зупинитися й біля лівого краю — у місцях В і Г.","ru":"Неполный ответ: на дороге с односторонним движением можно остановиться и у левого края — в местах В и Г."}},{"uk":"У місцях Б, В і Г.","ru":"В местах Б, В и Г."},{"uk":"У місцях Б і В.","ru":"В местах Б и В.","w":{"uk":"Неповна відповідь: місце Г на лівому боці дороги з одностороннім рухом теж дозволене.","ru":"Неполный ответ: место Г на левой стороне дороги с односторонним движением тоже разрешено."}},{"uk":"У місцях А, Б, В і Г.","ru":"В местах А, Б, В и Г.","w":{"uk":"Місце А розташоване перед знаком {s:3.34}, у зоні його дії, тому там зупинятися не можна.","ru":"Место А расположено перед знаком {s:3.34}, в зоне его действия, поэтому там останавливаться нельзя."}},{"uk":"У місці В.","ru":"В месте В.","w":{"uk":"Неповна відповідь: місця Б і Г теж поза зоною дії знака {s:3.34}.","ru":"Неполный ответ: места Б и Г тоже вне зоны действия знака {s:3.34}."}}],"c":1,"e":{"uk":"Знак {s:3.34} установлено з табличкою {s:7.2.3} — це кінець зони його дії, тож зупинку заборонено лише перед знаком, у місці А. На дорозі з одностороннім рухом ({s:5.5}) у населеному пункті зупинятися можна й ліворуч ({p:15.3}), тому дозволені місця Б, В і Г.","ru":"Знак {s:3.34} установлен с табличкой {s:7.2.3} — это конец зоны его действия, поэтому остановка запрещена только перед знаком, в месте А. На дороге с односторонним движением ({s:5.5}) в населённом пункте останавливаться можно и слева ({p:15.3}), поэтому разрешены места Б, В и Г."},"ref":["15.3","33.7"],"pic":["img/hsc/15-36-1.jpg"]},{"id":"h15-37","t":"h15","num":"15.37","q":{"uk":"Який з водіїв правильно зупинив свій транспортний засіб на дорозі з двостороннім рухом за межами населеного пункту?","ru":"Какой из водителей правильно остановил своё транспортное средство на дороге с двусторонним движением за пределами населённого пункта?"},"a":[{"uk":"Водій червоного автомобіля.","ru":"Водитель красного автомобиля.","w":{"uk":"Червоний автомобіль зупинився на лівому узбіччі, а поза населеним пунктом це заборонено.","ru":"Красный автомобиль остановился на левой обочине, а вне населённого пункта это запрещено."}},{"uk":"Водій синього автомобіля.","ru":"Водитель синего автомобиля."},{"uk":"Обидва водії.","ru":"Оба водителя.","w":{"uk":"Червоний автомобіль стоїть ліворуч за напрямком руху, а поза населеним пунктом так зупинятися не можна.","ru":"Красный автомобиль стоит слева по направлению движения, а вне населённого пункта так останавливаться нельзя."}}],"c":1,"e":{"uk":"Поза населеними пунктами зупинятися можна лише на правому узбіччі ({p:15.1}): дозвіл зупинки ліворуч ({p:15.3}) діє тільки в населених пунктах. Синій автомобіль стоїть на узбіччі праворуч за напрямком свого руху, а червоний — ліворуч.","ru":"Вне населённых пунктов останавливаться можно только на правой обочине ({p:15.1}): разрешение остановки слева ({p:15.3}) действует только в населённых пунктах. Синий автомобиль стоит на обочине справа по направлению своего движения, а красный — слева."},"ref":["15.1","15.3"],"pic":["img/hsc/15-37-1.jpg"]},{"id":"h15-38","t":"h15","num":"15.38","q":{"uk":"На якому з малюнків транспортні засоби поставлені правильно на дорогах у населених пунктах?","ru":"На каком из рисунков транспортные средства поставлены правильно на дорогах в населённых пунктах?"},"a":[{"uk":"На першому.","ru":"На первом.","w":{"uk":"На першому малюнку автомобілі стоять біля розділювальної смуги, де зупинку і стоянку заборонено.","ru":"На первом рисунке автомобили стоят у разделительной полосы, где остановка и стоянка запрещены."}},{"uk":"На другому.","ru":"На втором."},{"uk":"На обох.","ru":"На обоих.","w":{"uk":"Правильно поставлено лише на другому малюнку: на першому автомобілі стоять біля розділювальної смуги.","ru":"Правильно поставлены только на втором рисунке: на первом автомобили стоят у разделительной полосы."}}],"c":1,"e":{"uk":"На другому малюнку — дорога з одностороннім рухом ({s:5.5}), де в населеному пункті ставити транспортні засоби ліворуч дозволено ({p:15.3}). На першому автомобілі стоять ліворуч біля розділювальної смуги, а біля бульвару чи розділювальної смуги зупинку і стоянку заборонено.","ru":"На втором рисунке — дорога с односторонним движением ({s:5.5}), где в населённом пункте ставить транспортные средства слева разрешено ({p:15.3}). На первом автомобили стоят слева у разделительной полосы, а у бульвара или разделительной полосы остановка и стоянка запрещены."},"ref":["15.3"],"pic":["img/hsc/15-38-1.jpg"]},{"id":"h15-39","t":"h15","num":"15.39","q":{"uk":"На якому з малюнків показана дорога з двостороннім рухом у населеному пункті, на якій водій може поставити транспортний засіб на стоянку або зупинку на лівому боці?","ru":"На каком из рисунков показана дорога с двусторонним движением в населённом пункте, на которой водитель может поставить транспортное средство на стоянку или остановку на левой стороне?"},"a":[{"uk":"На малюнках 1 і 2.","ru":"На рисунках 1 и 2.","w":{"uk":"Дорогу на малюнку 2 розділено суцільною лінією {m:1.1}, тому ліворуч на ній ставати не можна.","ru":"Дорога на рисунке 2 разделена сплошной линией {m:1.1}, поэтому слева на ней становиться нельзя."}},{"uk":"На малюнку 1.","ru":"На рисунке 1."},{"uk":"На малюнку 2.","ru":"На рисунке 2.","w":{"uk":"На малюнку 2 зустрічні потоки розділяє суцільна лінія {m:1.1}, а це виключає зупинку ліворуч.","ru":"На рисунке 2 встречные потоки разделяет сплошная линия {m:1.1}, а это исключает остановку слева."}},{"uk":"На малюнку 3.","ru":"На рисунке 3.","w":{"uk":"На малюнку 3 посередині дороги трамвайні колії, тож ставити транспортний засіб ліворуч заборонено.","ru":"На рисунке 3 посередине дороги трамвайные пути, поэтому ставить транспортное средство слева запрещено."}}],"c":1,"e":{"uk":"Ліворуч зупинка і стоянка дозволені на дорозі з однією смугою в кожному напрямку, без трамвайних колій посередині і не розділеній розміткою {m:1.1} ({p:15.3}). Цим умовам відповідає лише дорога на малюнку 1 з переривчастою осьовою лінією.","ru":"Слева остановка и стоянка разрешены на дороге с одной полосой в каждом направлении, без трамвайных путей посередине и не разделённой разметкой {m:1.1} ({p:15.3}). Этим условиям соответствует только дорога на рисунке 1 с прерывистой осевой линией."},"ref":["15.3"],"pic":["img/hsc/15-39-1.jpg"]},{"id":"h15-40","t":"h15","num":"15.40","q":{"uk":"Кому з водіїв дозволено поставити свій транспортний засіб на лівому боці дороги, після проїзду цих дорожніх знаків?","ru":"Кому из водителей разрешено поставить своё транспортное средство на левой стороне дороги после проезда этих дорожных знаков?"},"a":[{"uk":"Водієві синього автомобіля.","ru":"Водителю синего автомобиля.","w":{"uk":"Синій автомобіль виїжджає з населеного пункту, а поза ним ставити транспортний засіб ліворуч не можна.","ru":"Синий автомобиль выезжает из населённого пункта, а вне его ставить транспортное средство слева нельзя."}},{"uk":"Водієві зеленого автомобіля.","ru":"Водителю зелёного автомобиля."},{"uk":"Обом водіям.","ru":"Обоим водителям.","w":{"uk":"Дозвіл ставати ліворуч діє лише в населеному пункті, тобто тільки для зеленого автомобіля.","ru":"Разрешение становиться слева действует только в населённом пункте, то есть только для зелёного автомобиля."}}],"c":1,"e":{"uk":"Зелений автомобіль проїжджає знаки {s:5.49} і в'їжджає в населений пункт, де на дорозі з однією смугою в кожному напрямку можна ставати й ліворуч ({p:15.3}). Синій автомобіль, навпаки, виїжджає з населеного пункту, а поза ним зупинка ліворуч не дозволена.","ru":"Зелёный автомобиль проезжает знаки {s:5.49} и въезжает в населённый пункт, где на дороге с одной полосой в каждом направлении можно становиться и слева ({p:15.3}). Синий автомобиль, наоборот, выезжает из населённого пункта, а вне его остановка слева не разрешена."},"ref":["15.3","15.1"],"pic":["img/hsc/15-40-1.jpg"]},{"id":"h15-41","t":"h15","num":"15.41","q":{"uk":"У якому місці повинен зупинитися водій червоного автомобіля?","ru":"В каком месте должен остановиться водитель красного автомобиля?"},"a":[{"uk":"У місці А.","ru":"В месте А."},{"uk":"У місці Б.","ru":"В месте Б.","w":{"uk":"У місці Б автомобіль стояв би далеко від краю проїзної частини й заважав би іншим.","ru":"В месте Б автомобиль стоял бы далеко от края проезжей части и мешал бы другим."}},{"uk":"У місці А чи Б.","ru":"В месте А или Б.","w":{"uk":"Правила вимагають ставати якомога правіше, тож підходить лише місце А біля самого краю.","ru":"Правила требуют становиться как можно правее, поэтому подходит только место А у самого края."}}],"c":0,"e":{"uk":"Коли узбіччя немає, зупинятися треба біля правого краю проїзної частини **якомога правіше**, щоб не заважати іншим ({p:15.2}). Місце А прилягає до бордюру, а в місці Б автомобіль стояв би на відстані від краю.","ru":"Когда обочины нет, останавливаться нужно у правого края проезжей части **как можно правее**, чтобы не мешать другим ({p:15.2}). Место А прилегает к бордюру, а в месте Б автомобиль стоял бы на расстоянии от края."},"ref":["15.2"],"pic":["img/hsc/15-41-1.jpg"]},{"id":"h15-42","t":"h15","num":"15.42","q":{"uk":"У якому місці водію червоного автомобіля дозволено зупинити транспортний засіб на дорозі в населеному пункті?","ru":"В каком месте водителю красного автомобиля разрешено остановить транспортное средство на дороге в населённом пункте?"},"a":[{"uk":"Біля правого краю проїзної частини.","ru":"У правого края проезжей части.","w":{"uk":"Неповна відповідь: на такій дорозі в населеному пункті можна зупинитися й ліворуч.","ru":"Неполный ответ: на такой дороге в населённом пункте можно остановиться и слева."}},{"uk":"Біля лівого краю проїзної частини.","ru":"У левого края проезжей части.","w":{"uk":"Неповна відповідь: основним місцем зупинки залишається правий край проїзної частини.","ru":"Неполный ответ: основным местом остановки остаётся правый край проезжей части."}},{"uk":"Біля правого або лівого краю проїзної частини.","ru":"У правого или левого края проезжей части."}],"c":2,"e":{"uk":"У населеному пункті на дорозі з однією смугою в кожному напрямку, без трамвайних колій посередині і без розмітки {m:1.1}, зупинка дозволена і біля правого краю ({p:15.2}), і біля лівого ({p:15.3}).","ru":"В населённом пункте на дороге с одной полосой в каждом направлении, без трамвайных путей посередине и без разметки {m:1.1}, остановка разрешена и у правого края ({p:15.2}), и у левого ({p:15.3})."},"ref":["15.2","15.3"],"pic":["img/hsc/15-42-1.jpg"]},{"id":"h15-43","t":"h15","num":"15.43","q":{"uk":"У якому місці водій червоного автомобіля повинен зупинити транспортний засіб на дорозі за межами населених пунктів?","ru":"В каком месте водитель красного автомобиля должен остановить транспортное средство на дороге за пределами населённых пунктов?"},"a":[{"uk":"На правому або лівому узбіччі.","ru":"На правой или левой обочине.","w":{"uk":"Поза населеними пунктами зупинятися на лівому узбіччі не можна.","ru":"Вне населённых пунктов останавливаться на левой обочине нельзя."}},{"uk":"Тільки на правому узбіччі.","ru":"Только на правой обочине."},{"uk":"Біля правого краю проїзної частини, якомога правіше.","ru":"У правого края проезжей части, как можно правее.","w":{"uk":"Біля краю проїзної частини зупиняються лише тоді, коли узбіччя немає, а тут воно є.","ru":"У края проезжей части останавливаются только при отсутствии обочины, а здесь она есть."}},{"uk":"Відповіді 1 і 3.","ru":"Ответы 1 и 3.","w":{"uk":"І ліве узбіччя, і край проїзної частини тут не підходять: є праве узбіччя, а дорога — поза населеним пунктом.","ru":"И левая обочина, и край проезжей части здесь не подходят: есть правая обочина, а дорога — вне населённого пункта."}}],"c":1,"e":{"uk":"Зупинка має відбуватися на узбіччі ({p:15.1}), причому поза населеними пунктами — лише праворуч: дозвіл зупинки ліворуч ({p:15.3}) діє тільки в населених пунктах. На проїзну частину ставати можна лише тоді, коли узбіччя немає ({p:15.2}).","ru":"Остановка должна осуществляться на обочине ({p:15.1}), причём вне населённых пунктов — только справа: разрешение остановки слева ({p:15.3}) действует только в населённых пунктах. На проезжую часть становиться можно только при отсутствии обочины ({p:15.2})."},"ref":["15.1","15.2","15.3"],"pic":["img/hsc/15-43-1.jpg"]},{"id":"h15-44","t":"h15","num":"15.44","q":{"uk":"Хто з водіїв зупинився неправильно?","ru":"Кто из водителей остановился неправильно?"},"a":[{"uk":"Водій сірого автомобіля.","ru":"Водитель серого автомобиля."},{"uk":"Водій червоного автомобіля.","ru":"Водитель красного автомобиля.","w":{"uk":"Червоний автомобіль зупинився правильно — на правому узбіччі.","ru":"Красный автомобиль остановился правильно — на правой обочине."}},{"uk":"Обидва водії.","ru":"Оба водителя.","w":{"uk":"Порушує лише водій сірого автомобіля; червоний стоїть на узбіччі, як і належить.","ru":"Нарушает только водитель серого автомобиля; красный стоит на обочине, как и положено."}}],"c":0,"e":{"uk":"Зупинятися треба на узбіччі ({p:15.1}), а на проїзній частині — лише тоді, коли узбіччя немає або зупинка на ньому неможлива ({p:15.2}). Червоний автомобіль стоїть на узбіччі, а сірий — на проїзній частині, хоча вільне узбіччя поруч.","ru":"Останавливаться нужно на обочине ({p:15.1}), а на проезжей части — только когда обочины нет или остановка на ней невозможна ({p:15.2}). Красный автомобиль стоит на обочине, а серый — на проезжей части, хотя свободная обочина рядом."},"ref":["15.1","15.2"],"pic":["img/hsc/15-44-1.jpg"]},{"id":"h15-45","t":"h15","num":"15.45","q":{"uk":"Які транспортні засоби поставлені з порушенням Правил дорожнього руху?","ru":"Какие транспортные средства поставлены с нарушением Правил дорожного движения?"},"a":[{"uk":"Велосипеди.","ru":"Велосипеды.","w":{"uk":"Велосипеди можна ставити у два ряди, як на малюнку.","ru":"Велосипеды можно ставить в два ряда, как на рисунке."}},{"uk":"Мопеди.","ru":"Мопеды.","w":{"uk":"Мопеди можна ставити у два ряди, як на малюнку.","ru":"Мопеды можно ставить в два ряда, как на рисунке."}},{"uk":"Зелений мотоцикл із боковим причепом.","ru":"Зелёный мотоцикл с боковым прицепом.","w":{"uk":"Зелений мотоцикл із боковим причепом стоїть в одному ряду біля краю проїзної частини — це дозволено.","ru":"Зелёный мотоцикл с боковым прицепом стоит в один ряд у края проезжей части — это разрешено."}},{"uk":"Коричневий мотоцикл із боковим причепом.","ru":"Коричневый мотоцикл с боковым прицепом."}],"c":3,"e":{"uk":"Велосипеди, мопеди й мотоцикли **без бокового причепа** можна ставити не більше ніж у два ряди, а решту транспортних засобів — лише в один ({p:15.4}). Коричневий мотоцикл із боковим причепом стоїть у другому ряду поруч із червоним мотоциклом, тож він і порушує.","ru":"Велосипеды, мопеды и мотоциклы **без бокового прицепа** можно ставить не более чем в два ряда, а остальные транспортные средства — только в один ({p:15.4}). Коричневый мотоцикл с боковым прицепом стоит во втором ряду рядом с красным мотоциклом, поэтому он и нарушает."},"ref":["15.4"],"pic":["img/hsc/15-45-1.jpg"]},{"id":"h15-46","t":"h15","num":"15.46","q":{"uk":"У якому місці дороги водій може зупинити свій транспортний засіб, якщо на узбіччях зупинка і стоянка неможливі, а спеціально відведені місця відсутні?","ru":"В каком месте дороги водитель может остановить своё транспортное средство, если на обочинах остановка и стоянка невозможны, а специально отведённые места отсутствуют?"},"a":[{"uk":"Біля лівого краю проїзної частини.","ru":"У левого края проезжей части.","w":{"uk":"Біля лівого краю зупинятися можна лише в населених пунктах на дорогах, описаних у {p:15.3}, а тут дорога поза населеним пунктом.","ru":"У левого края останавливаться можно только в населённых пунктах на дорогах, описанных в {p:15.3}, а здесь дорога вне населённого пункта."}},{"uk":"Біля правого краю проїзної частини, як можна правіше, щоб не перешкоджати іншим учасникам дорожнього руху.","ru":"У правого края проезжей части, как можно правее, чтобы не мешать другим участникам дорожного движения."},{"uk":"На тротуарах або на пішохідних доріжках, щоб не перешкоджати іншим учасникам дорожнього руху.","ru":"На тротуарах или на пешеходных дорожках, чтобы не мешать другим участникам дорожного движения.","w":{"uk":"Тротуари й пішохідні доріжки призначені для пішоходів; ставити туди транспортні засоби можна лише там, де це дозволяють знаки з табличками.","ru":"Тротуары и пешеходные дорожки предназначены для пешеходов; ставить туда транспортные средства можно только там, где это разрешают знаки с табличками."}}],"c":1,"e":{"uk":"Узбіччя тут непридатне (знак {s:1.15}, вибоїни), а спеціально відведених місць немає, тому, за {p:15.2}, зупинятися слід біля правого краю проїзної частини — **якомога правіше**, щоб не заважати іншим.","ru":"Обочина здесь непригодна (знак {s:1.15}, выбоины), а специально отведённых мест нет, поэтому, согласно {p:15.2}, останавливаться следует у правого края проезжей части — **как можно правее**, чтобы не мешать другим."},"ref":["15.2"],"pic":["img/hsc/15-46-1.jpg"]},{"id":"h15-47","t":"h15","num":"15.47","q":{"uk":"У якому місці водій може виконати зупинку?","ru":"В каком месте водитель может выполнить остановку?"},"a":[{"uk":"У місці А.","ru":"В месте А.","w":{"uk":"Неповна відповідь: за переїздом, у місці В, зупинитися теж можна.","ru":"Неполный ответ: за переездом, в месте В, остановиться тоже можно."}},{"uk":"У місці Б.","ru":"В месте Б.","w":{"uk":"Місце Б — на залізничному переїзді, де зупинку заборонено.","ru":"Место Б — на железнодорожном переезде, где остановка запрещена."}},{"uk":"У місці В.","ru":"В месте В.","w":{"uk":"Неповна відповідь: перед переїздом, у місці А, зупинитися теж можна.","ru":"Неполный ответ: перед переездом, в месте А, остановиться тоже можно."}},{"uk":"У місці А, Б і В.","ru":"В местах А, Б и В.","w":{"uk":"Місце Б зайве: на переїзді зупинятися заборонено.","ru":"Место Б лишнее: на переезде останавливаться запрещено."}},{"uk":"У місці А і В.","ru":"В местах А и В."}],"c":4,"e":{"uk":"Зупинку заборонено **на самому** залізничному переїзді ({p:15.9}), тому місце Б на коліях виключене. Перед переїздом (А) і за ним (В) зупинятися можна; обмеження 50 м від переїзду стосується лише стоянки ({p:15.10}).","ru":"Остановка запрещена **на самом** железнодорожном переезде ({p:15.9}), поэтому место Б на путях исключено. Перед переездом (А) и за ним (В) останавливаться можно; ограничение 50 м от переезда касается только стоянки ({p:15.10})."},"ref":["15.9","15.10"],"pic":["img/hsc/15-47-1.jpg"]},{"id":"h15-48","t":"h15","num":"15.48","q":{"uk":"Чи дозволено водієві синього автомобіля зупинитися в цьому місці?","ru":"Разрешено ли водителю синего автомобиля остановиться в этом месте?"},"a":[{"uk":"Заборонено.","ru":"Запрещено.","w":{"uk":"Біля переїзду заборонено стоянку, а не зупинку; зупинку заборонено лише на самому переїзді.","ru":"У переезда запрещена стоянка, а не остановка; остановка запрещена только на самом переезде."}},{"uk":"Дозволено.","ru":"Разрешено."}],"c":1,"e":{"uk":"Синій автомобіль зупинився перед залізничним переїздом, а не на ньому. Зупинку заборонено лише на самому переїзді ({p:15.9}), а заборона ближче 50 м стосується стоянки ({p:15.10}), тож узяти пасажира тут можна.","ru":"Синий автомобиль остановился перед железнодорожным переездом, а не на нём. Остановка запрещена только на самом переезде ({p:15.9}), а запрет ближе 50 м касается стоянки ({p:15.10}), поэтому взять пассажира здесь можно."},"ref":["15.9","15.10"],"pic":["img/hsc/15-48-1.jpg"]},{"id":"h15-49","t":"h15","num":"15.49","q":{"uk":"Який транспортний засіб поставлено на стоянку з порушенням Правил дорожнього руху в цьому місці?","ru":"Какое транспортное средство поставлено на стоянку с нарушением Правил дорожного движения в этом месте?"},"a":[{"uk":"Усі стоять правильно.","ru":"Все стоят правильно.","w":{"uk":"Табличка дозволяє стоянку лише легковим автомобілям і мотоциклам, тож вантажний автомобіль і мікроавтобус порушують.","ru":"Табличка разрешает стоянку только легковым автомобилям и мотоциклам, поэтому грузовой автомобиль и микроавтобус нарушают."}},{"uk":"Вантажний автомобіль та мікроавтобус.","ru":"Грузовой автомобиль и микроавтобус."},{"uk":"Тільки вантажний автомобіль.","ru":"Только грузовой автомобиль.","w":{"uk":"Мікроавтобус теж порушує: він не є легковим автомобілем.","ru":"Микроавтобус тоже нарушает: он не является легковым автомобилем."}},{"uk":"Тільки мікроавтобус.","ru":"Только микроавтобус.","w":{"uk":"Вантажний автомобіль теж порушує: табличка дозволяє стоянку лише легковим автомобілям і мотоциклам.","ru":"Грузовой автомобиль тоже нарушает: табличка разрешает стоянку только легковым автомобилям и мотоциклам."}},{"uk":"Вантажний автомобіль, мікроавтобус і мотоцикл.","ru":"Грузовой автомобиль, микроавтобус и мотоцикл.","w":{"uk":"Мотоцикл (і з боковим причепом) тут стояти може — дозвіл поширюється на мотоцикли.","ru":"Мотоцикл (и с боковым прицепом) здесь стоять может — разрешение распространяется на мотоциклы."}}],"c":1,"e":{"uk":"Знак «Місце для стоянки» установлено з табличкою, що показує спосіб поставлення легкового автомобіля, а з такими табличками стоянка дозволена **лише легковим автомобілям і мотоциклам** ({p:15.6}). Вантажний автомобіль і мікроавтобус тут стояти не можуть.","ru":"Знак «Место стоянки» установлен с табличкой, показывающей способ постановки легкового автомобиля, а с такими табличками стоянка разрешена **только легковым автомобилям и мотоциклам** ({p:15.6}). Грузовой автомобиль и микроавтобус здесь стоять не могут."},"ref":["15.6"],"pic":["img/hsc/15-49-1.jpg"]},{"id":"h15-50","t":"h15","num":"15.50","q":{"uk":"Які транспортні засоби дозволено ставити в місцях, позначених дорожніми знаками «Місце для стоянки» або «Зона стоянки», встановленими з такими табличками?","ru":"Какие транспортные средства разрешено ставить в местах, обозначенных дорожными знаками «Место стоянки» или «Зона стоянки», установленными с такими табличками?"},"a":[{"uk":"Усі транспортні засоби.","ru":"Все транспортные средства.","w":{"uk":"Усім транспортним засобам дозволено лише стоянку вздовж тротуару на проїзній частині, а не так, як на цих табличках.","ru":"Всем транспортным средствам разрешена только стоянка вдоль тротуара на проезжей части, а не так, как на этих табличках."}},{"uk":"Вантажні автомобілі з дозволеною максимальною масою менше 3,5 т.","ru":"Грузовые автомобили с разрешённой максимальной массой менее 3,5 т.","w":{"uk":"Вантажні автомобілі, незалежно від маси, під дію цих табличок не підпадають.","ru":"Грузовые автомобили, независимо от массы, под действие этих табличек не подпадают."}},{"uk":"Тільки легкові автомобілі.","ru":"Только легковые автомобили.","w":{"uk":"Неповна відповідь: так ставити можна й мотоцикли.","ru":"Неполный ответ: так ставить можно и мотоциклы."}},{"uk":"Тільки мотоцикли.","ru":"Только мотоциклы.","w":{"uk":"Неповна відповідь: так ставити можна й легкові автомобілі.","ru":"Неполный ответ: так ставить можно и легковые автомобили."}},{"uk":"Транспортні засоби, зазначені у відповідях 3 і 4.","ru":"Транспортные средства, указанные в ответах 3 и 4."}],"c":4,"e":{"uk":"Таблички на малюнку показують поставлення на тротуарі або частково на ньому. Зі знаками «Місце для стоянки» чи «Зона стоянки» і такими табличками {p:15.6} дозволяє стоянку **легкових автомобілів і мотоциклів** — тільки так, як показано на табличці.","ru":"Таблички на рисунке показывают постановку на тротуаре или частично на нём. Со знаками «Место стоянки» или «Зона стоянки» и такими табличками {p:15.6} разрешает стоянку **легковых автомобилей и мотоциклов** — только так, как показано на табличке."},"ref":["15.6"],"pic":["img/hsc/15-50-1.jpg"]},{"id":"h15-51","t":"h15","num":"15.51","q":{"uk":"У якому місці водієві легкового автомобіля дозволено виконати зупинку або стоянку в цій ситуації?","ru":"В каком месте водителю легкового автомобиля разрешено выполнить остановку или стоянку в этой ситуации?"},"a":[{"uk":"У місці А.","ru":"В месте А."},{"uk":"У місці Б.","ru":"В месте Б.","w":{"uk":"Місце Б — на проїзній частині, хоча поруч є придатне узбіччя.","ru":"Место Б — на проезжей части, хотя рядом есть пригодная обочина."}},{"uk":"У місцях А чи Б.","ru":"В местах А или Б.","w":{"uk":"За наявності придатного узбіччя ставати на проїзній частині (місце Б) не можна.","ru":"При наличии пригодной обочины становиться на проезжей части (место Б) нельзя."}}],"c":0,"e":{"uk":"Місце А — на узбіччі за лінією {m:1.2}, що позначає край проїзної частини. Якщо узбіччя придатне, зупинка і стоянка мають бути саме на ньому ({p:15.1}); біля краю проїзної частини (місце Б) — лише коли узбіччя немає або там зупинитися неможливо ({p:15.2}).","ru":"Место А — на обочине за линией {m:1.2}, обозначающей край проезжей части. Если обочина пригодна, остановка и стоянка должны быть именно на ней ({p:15.1}); у края проезжей части (место Б) — только когда обочины нет или там остановиться невозможно ({p:15.2})."},"ref":["15.1","15.2"],"pic":["img/hsc/15-51-1.jpg"]},{"id":"h15-52","t":"h15","num":"15.52","q":{"uk":"Чи правильно на підйомі поставлений білий автомобіль, якщо оглядовість в напрямку руху менше 100 м?","ru":"Правильно ли на подъёме поставлен белый автомобиль, если обзорность в направлении движения менее 100 м?"},"a":[{"uk":"Правильно, якщо він не перешкоджає руху інших транспортних засобів.","ru":"Правильно, если он не мешает движению других транспортных средств.","w":{"uk":"Заборона стоянки на випуклому переломі з оглядовістю менше 100 м безумовна і не залежить від того, чи заважає автомобіль.","ru":"Запрет стоянки на выпуклом переломе с обзорностью менее 100 м безусловен и не зависит от того, мешает ли автомобиль."}},{"uk":"Неправильно.","ru":"Неправильно."},{"uk":"Правильно в будь-якому випадку.","ru":"Правильно в любом случае.","w":{"uk":"Через оглядовість менше 100 м стоянка тут заборонена.","ru":"Из-за обзорности менее 100 м стоянка здесь запрещена."}}],"c":1,"e":{"uk":"Білий автомобіль стоїть поза населеним пунктом на підйомі (знак {s:1.6}) перед вершиною — випуклим переломом поздовжнього профілю дороги, де оглядовість менше 100 м. У такому місці стоянку заборонено ({p:15.10}) незалежно від того, чи заважає він іншим.","ru":"Белый автомобиль стоит вне населённого пункта на подъёме (знак {s:1.6}) перед вершиной — выпуклым переломом продольного профиля дороги, где обзорность менее 100 м. В таком месте стоянка запрещена ({p:15.10}) независимо от того, мешает ли он другим."},"ref":["15.10"],"pic":["img/hsc/15-52-1.jpg"]},{"id":"h15-53","t":"h15","num":"15.53","q":{"uk":"Чи правильно водій фіолетового автомобіля поставив транспортний засіб?","ru":"Правильно ли водитель фиолетового автомобиля поставил транспортное средство?"},"a":[{"uk":"Правильно, якщо це не перешкоджає руху інших транспортних засобів.","ru":"Правильно, если это не мешает движению других транспортных средств.","w":{"uk":"Вимога ставити транспортний засіб якомога правіше не має застережень: проміжок від краю — уже порушення.","ru":"Требование ставить транспортное средство как можно правее не имеет оговорок: промежуток от края — уже нарушение."}},{"uk":"Неправильно.","ru":"Неправильно."},{"uk":"Правильно.","ru":"Правильно.","w":{"uk":"Автомобіль поставлено не якомога правіше, як вимагають Правила.","ru":"Автомобиль поставлен не как можно правее, как требуют Правила."}}],"c":1,"e":{"uk":"Фіолетовий автомобіль стоїть не впритул до правого краю проїзної частини, а з проміжком від нього. Біля краю проїзної частини транспортний засіб треба ставити **якомога правіше** ({p:15.2}), тож поставлено неправильно.","ru":"Фиолетовый автомобиль стоит не вплотную к правому краю проезжей части, а с промежутком от него. У края проезжей части транспортное средство нужно ставить **как можно правее** ({p:15.2}), поэтому поставлено неправильно."},"ref":["15.2"],"pic":["img/hsc/15-53-1.jpg"]},{"id":"h15-54","t":"h15","num":"15.54","q":{"uk":"Який транспортний засіб правильно поставлено на дорозі з одностороннім рухом, якщо відомо, що обидва автомобілі не перешкоджають руху інших транспортних засобів?","ru":"Какое транспортное средство правильно поставлено на дороге с односторонним движением, если известно, что оба автомобиля не мешают движению других транспортных средств?"},"a":[{"uk":"Червоний автомобіль.","ru":"Красный автомобиль.","w":{"uk":"Червоний автомобіль стоїть під кутом задньою частиною до тротуару, а так можна ставати лише на підйомах.","ru":"Красный автомобиль стоит под углом задней частью к тротуару, а так можно становиться только на подъёмах."}},{"uk":"Білий автомобіль.","ru":"Белый автомобиль."},{"uk":"Обидва автомобілі.","ru":"Оба автомобиля.","w":{"uk":"Червоний автомобіль поставлено неправильно: під кутом біля тротуару — лише передньою частиною.","ru":"Красный автомобиль поставлен неправильно: под углом у тротуара — только передней частью."}}],"c":1,"e":{"uk":"Білий автомобіль стоїть уздовж краю проїзної частини — правильно. Червоний поставлено під кутом **задньою частиною** до тротуару, а біля тротуарів під кутом можна ставати лише передньою частиною; задньою — тільки на підйомах ({p:15.5}).","ru":"Белый автомобиль стоит вдоль края проезжей части — правильно. Красный поставлен под углом **задней частью** к тротуару, а у тротуаров под углом можно становиться только передней частью; задней — только на подъёмах ({p:15.5})."},"ref":["15.5"],"pic":["img/hsc/15-54-1.jpg"]},{"id":"h15-55","t":"h15","num":"15.55","q":{"uk":"За яких умов водієві та пасажирам транспортного засобу заборонено відчиняти двері транспортного засобу, залишати їх відчиненими і виходити з транспортного засобу?","ru":"При каких условиях водителю и пассажирам транспортного средства запрещено открывать двери транспортного средства, оставлять их открытыми и выходить из транспортного средства?"},"a":[{"uk":"Якщо проїзна частина дороги невеликої ширини.","ru":"Если проезжая часть дороги небольшой ширины.","w":{"uk":"Ширина проїзної частини сама по собі не є умовою заборони — важливо, чи це загрожує безпеці й заважає іншим.","ru":"Ширина проезжей части сама по себе не является условием запрета — важно, угрожает ли это безопасности и мешает ли другим."}},{"uk":"Якщо це загрожує безпеці дорожнього руху.","ru":"Если это угрожает безопасности дорожного движения.","w":{"uk":"Неповна відповідь: Правила називають також створення перешкод іншим учасникам руху.","ru":"Неполный ответ: Правила называют также создание помех другим участникам движения."}},{"uk":"Якщо це створює перешкоди іншим учасникам дорожнього руху.","ru":"Если это создаёт помехи другим участникам дорожного движения.","w":{"uk":"Неповна відповідь: Правила називають також загрозу безпеці дорожнього руху.","ru":"Неполный ответ: Правила называют также угрозу безопасности дорожного движения."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3.","w":{"uk":"Невелика ширина проїзної частини не є умовою заборони, тож варіант 1 зайвий.","ru":"Небольшая ширина проезжей части не является условием запрета, поэтому вариант 1 лишний."}},{"uk":"Відповіді 2 і 3.","ru":"Ответы 2 и 3."}],"c":4,"e":{"uk":"{p:15.13} забороняє відчиняти двері, залишати їх відчиненими й виходити з транспортного засобу, якщо це **загрожує безпеці** та **створює перешкоди** іншим учасникам дорожнього руху.","ru":"{p:15.13} запрещает открывать двери, оставлять их открытыми и выходить из транспортного средства, если это **угрожает безопасности** и **создаёт помехи** другим участникам дорожного движения."},"ref":["15.13"]},{"id":"h15-56","t":"h15","num":"15.56","q":{"uk":"Ближче якої відстані від залізничного переїзду водієві транспортного засобу заборонена стоянка?","ru":"Ближе какого расстояния от железнодорожного переезда водителю транспортного средства запрещена стоянка?"},"a":[{"uk":"50 м.","ru":"50 м."},{"uk":"100 м.","ru":"100 м.","w":{"uk":"100 м — це відстань, на якій перед переїздами заборонено обгін, а не стоянку.","ru":"100 м — это расстояние, на котором перед переездами запрещён обгон, а не стоянка."}},{"uk":"150 м.","ru":"150 м.","w":{"uk":"Такої відстані для стоянки біля переїзду Правила не встановлюють — лише 50 м.","ru":"Такого расстояния для стоянки у переезда Правила не устанавливают — только 50 м."}}],"c":0,"e":{"uk":"За {p:15.10} стоянку заборонено **ближче 50 м** від залізничних переїздів.","ru":"Согласно {p:15.10} стоянка запрещена **ближе 50 м** от железнодорожных переездов."},"ref":["15.10"]},{"id":"h15-57","t":"h15","num":"15.57","q":{"uk":"Що забороняється водієві, а також пасажирам транспортного засобу під час відчинення дверей?","ru":"Что запрещается водителю, а также пассажирам транспортного средства при открывании дверей?"},"a":[{"uk":"Тільки відчиняти двері транспортного засобу, якщо це загрожує безпеці і створює перешкоди іншим учасникам дорожнього руху.","ru":"Только открывать двери транспортного средства, если это угрожает безопасности и создаёт помехи другим участникам дорожного движения.","w":{"uk":"Заборона не обмежується відчиненням дверей: не можна також залишати їх відчиненими й виходити.","ru":"Запрет не ограничивается открыванием дверей: нельзя также оставлять их открытыми и выходить."}},{"uk":"Тільки залишати відчиненими двері транспортного засобу, якщо це загрожує безпеці і створює перешкоди іншим учасникам дорожнього руху.","ru":"Только оставлять открытыми двери транспортного средства, если это угрожает безопасности и создаёт помехи другим участникам дорожного движения.","w":{"uk":"Заборона не обмежується відчиненими дверима: не можна також відчиняти їх і виходити.","ru":"Запрет не ограничивается открытыми дверями: нельзя также открывать их и выходить."}},{"uk":"Тільки виходити з транспортного засобу, якщо це загрожує безпеці і створює перешкоди іншим учасникам дорожнього руху.","ru":"Только выходить из транспортного средства, если это угрожает безопасности и создаёт помехи другим участникам дорожного движения.","w":{"uk":"Заборона не обмежується виходом: не можна також відчиняти двері й залишати їх відчиненими.","ru":"Запрет не ограничивается выходом: нельзя также открывать двери и оставлять их открытыми."}},{"uk":"Відчиняти двері транспортного засобу, залишати їх відчиненими і виходити з транспортного засобу, якщо це загрожує безпеці і створює перешкоди іншим учасникам дорожнього руху.","ru":"Открывать двери транспортного средства, оставлять их открытыми и выходить из транспортного средства, если это угрожает безопасности и создаёт помехи другим участникам дорожного движения."}],"c":3,"e":{"uk":"{p:15.13} забороняє одразу три дії — **відчиняти** двері, **залишати їх відчиненими** і **виходити** з транспортного засобу, — якщо це загрожує безпеці та створює перешкоди іншим.","ru":"{p:15.13} запрещает сразу три действия — **открывать** двери, **оставлять их открытыми** и **выходить** из транспортного средства, — если это угрожает безопасности и создаёт помехи другим."},"ref":["15.13"]},{"id":"h15-58","t":"h15","num":"15.58","q":{"uk":"Як повинен водій ставити свій транспортний засіб біля правого краю проїзної частини?","ru":"Как должен водитель ставить своё транспортное средство у правого края проезжей части?"},"a":[{"uk":"Ставити якомога правіше, щоб не перешкоджати іншим учасникам дорожнього руху.","ru":"Ставить как можно правее, чтобы не мешать другим участникам дорожного движения."},{"uk":"Ставити на будь-якій відстані від краю проїзної частини.","ru":"Ставить на любом расстоянии от края проезжей части.","w":{"uk":"Відстань від краю не довільна: транспортний засіб треба ставити якомога правіше.","ru":"Расстояние от края не произвольно: транспортное средство нужно ставить как можно правее."}},{"uk":"Так, щоб не перешкоджати лише транспортним засобам.","ru":"Так, чтобы не мешать только транспортным средствам.","w":{"uk":"Не можна заважати всім учасникам дорожнього руху, зокрема пішоходам і велосипедистам, а не лише транспортним засобам.","ru":"Нельзя мешать всем участникам дорожного движения, в том числе пешеходам и велосипедистам, а не только транспортным средствам."}}],"c":0,"e":{"uk":"{p:15.2} вимагає ставити транспортний засіб біля правого краю проїзної частини **якомога правіше**, щоб не перешкоджати іншим учасникам дорожнього руху.","ru":"{p:15.2} требует ставить транспортное средство у правого края проезжей части **как можно правее**, чтобы не мешать другим участникам дорожного движения."},"ref":["15.2"]},{"id":"h15-59","t":"h15","num":"15.59","q":{"uk":"У якому з місць заборонена стоянка транспортних засобів?","ru":"В каком из мест запрещена стоянка транспортных средств?"},"a":[{"uk":"У зоні небезпечних поворотів і випуклих переломів поздовжнього профілю дороги з видимістю або оглядовістю менше 100 м хоча б в одному напрямку руху за межами населених пунктів.","ru":"В зоне опасных поворотов и выпуклых переломов продольного профиля дороги с видимостью или обзорностью менее 100 м хотя бы в одном направлении движения за пределами населённых пунктов.","w":{"uk":"Неповна відповідь: стоянку заборонено також ближче 50 м від залізничних переїздів.","ru":"Неполный ответ: стоянка запрещена также ближе 50 м от железнодорожных переездов."}},{"uk":"Ближче ніж за 50 м до залізничних переїздів.","ru":"Ближе 50 м от железнодорожных переездов.","w":{"uk":"Неповна відповідь: стоянку заборонено також на небезпечних поворотах і випуклих переломах з видимістю менше 100 м.","ru":"Неполный ответ: стоянка запрещена также на опасных поворотах и выпуклых переломах с видимостью менее 100 м."}},{"uk":"Більше ніж за 100 м до залізничних переїздів за межами населених пунктів.","ru":"Дальше 100 м от железнодорожных переездов за пределами населённых пунктов.","w":{"uk":"Далі ніж за 50 м від переїзду стоянка дозволена, тож за 100 м вона тим паче не заборонена.","ru":"Дальше 50 м от переезда стоянка разрешена, поэтому в 100 м она тем более не запрещена."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3.","w":{"uk":"Варіант 3 зайвий: на відстані понад 100 м від переїзду стоянку не заборонено.","ru":"Вариант 3 лишний: на расстоянии более 100 м от переезда стоянка не запрещена."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2."}],"c":4,"e":{"uk":"Обидва місця названо в {p:15.10}: стоянку заборонено ближче 50 м від залізничних переїздів і поза населеними пунктами в зоні небезпечних поворотів та випуклих переломів профілю з видимістю менше 100 м.","ru":"Оба места названы в {p:15.10}: стоянка запрещена ближе 50 м от железнодорожных переездов и вне населённых пунктов в зоне опасных поворотов и выпуклых переломов профиля с видимостью менее 100 м."},"ref":["15.10"]},{"id":"h15-60","t":"h15","num":"15.60","q":{"uk":"У якому місці дороги водій повинен поставити транспортний засіб на зупинку або стоянку за наявності узбіччя, придатного для зупинки або стоянки?","ru":"В каком месте дороги водитель должен поставить транспортное средство на остановку или стоянку при наличии обочины, пригодной для остановки или стоянки?"},"a":[{"uk":"Біля правого краю проїзної частини чи на узбіччі.","ru":"У правого края проезжей части или на обочине.","w":{"uk":"Якщо узбіччя придатне, ставати біля краю проїзної частини не можна — цей варіант лише для випадків, коли узбіччя немає.","ru":"Если обочина пригодна, становиться у края проезжей части нельзя — этот вариант только для случаев, когда обочины нет."}},{"uk":"Тільки на узбіччі.","ru":"Только на обочине."}],"c":1,"e":{"uk":"Зупинка і стоянка мають здійснюватися в спеціально відведених місцях чи на узбіччі ({p:15.1}); біля краю проїзної частини — лише коли узбіччя немає або зупинка на ньому неможлива ({p:15.2}).","ru":"Остановка и стоянка должны осуществляться в специально отведённых местах или на обочине ({p:15.1}); у края проезжей части — только когда обочины нет или остановка на ней невозможна ({p:15.2})."},"ref":["15.1","15.2"]},{"id":"h15-61","t":"h15","num":"15.61","q":{"uk":"У яких місцях заборонено стоянку транспортних засобів?","ru":"В каких местах запрещена стоянка транспортных средств?"},"a":[{"uk":"У місцях, де транспортний засіб, що стоїть, унеможливить рух інших транспортних засобів.","ru":"В местах, где стоящее транспортное средство сделает невозможным движение других транспортных средств.","w":{"uk":"Неповна відповідь: стоянку заборонено також там, де вона заважає пішоходам, і на газонах.","ru":"Неполный ответ: стоянка запрещена также там, где она мешает пешеходам, и на газонах."}},{"uk":"У місцях, де транспортний засіб, що стоїть, створить перешкоду для руху пішоходів.","ru":"В местах, где стоящее транспортное средство создаст помеху для движения пешеходов.","w":{"uk":"Неповна відповідь: стоянку заборонено також там, де вона унеможливить рух транспорту, і на газонах.","ru":"Неполный ответ: стоянка запрещена также там, где она сделает невозможным движение транспорта, и на газонах."}},{"uk":"На газонах.","ru":"На газонах.","w":{"uk":"Неповна відповідь: стоянку заборонено також там, де вона унеможливить рух транспорту чи заважатиме пішоходам.","ru":"Неполный ответ: стоянка запрещена также там, где она сделает невозможным движение транспорта или будет мешать пешеходам."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2.","w":{"uk":"Неповна відповідь: стоянку на газонах {p:15.10} теж забороняє.","ru":"Неполный ответ: стоянку на газонах {p:15.10} тоже запрещает."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3."}],"c":4,"e":{"uk":"Усі три місця є в переліку {p:15.10}: там, де транспортний засіб унеможливить рух інших транспортних засобів, де створить перешкоду для руху пішоходів, і на газонах.","ru":"Все три места есть в перечне {p:15.10}: там, где транспортное средство сделает невозможным движение других транспортных средств, где создаст помеху для движения пешеходов, и на газонах."},"ref":["15.10"]},{"id":"h15-62","t":"h15","num":"15.62","q":{"uk":"Яким транспортним засобам дозволяється стоянка на тротуарах?","ru":"Каким транспортным средствам разрешается стоянка на тротуарах?"},"a":[{"uk":"Тільки легковим автомобілям.","ru":"Только легковым автомобилям.","w":{"uk":"Неповна відповідь: на краю тротуару можна ставити й мотоцикли.","ru":"Неполный ответ: на краю тротуара можно ставить и мотоциклы."}},{"uk":"Тільки мотоциклам.","ru":"Только мотоциклам.","w":{"uk":"Неповна відповідь: на краю тротуару можна ставити й легкові автомобілі.","ru":"Неполный ответ: на краю тротуара можно ставить и легковые автомобили."}},{"uk":"Легковим автомобілям та мотоциклам.","ru":"Легковым автомобилям и мотоциклам."}],"c":2,"e":{"uk":"За {p:15.10} на краю тротуару, де для пішоходів залишається щонайменше 2 м, можна ставити **легкові автомобілі та мотоцикли**; так само лише їм дозволяє стоянку на тротуарі знак із табличкою ({p:15.6}).","ru":"Согласно {p:15.10} на краю тротуара, где для пешеходов остаётся не менее 2 м, можно ставить **легковые автомобили и мотоциклы**; так же только им разрешает стоянку на тротуаре знак с табличкой ({p:15.6})."},"ref":["15.10","15.6"]},{"id":"h15-63","t":"h15","num":"15.63","q":{"uk":"На якій відстані від контейнерів для збору побутових відходів, місце розміщення або облаштування яких відповідає вимогам законодавства, заборонена стоянка транспортних засобів?","ru":"На каком расстоянии от контейнеров для сбора бытовых отходов, место размещения или обустройства которых соответствует требованиям законодательства, запрещена стоянка транспортных средств?"},"a":[{"uk":"Ближче 5 м.","ru":"Ближе 5 м."},{"uk":"Ближче 10 м.","ru":"Ближе 10 м.","w":{"uk":"10 м — відстань для пішохідних переходів і перехресть, а від контейнерів — 5 м.","ru":"10 м — расстояние для пешеходных переходов и перекрёстков, а от контейнеров — 5 м."}},{"uk":"Ближче 15 м.","ru":"Ближе 15 м.","w":{"uk":"Такої відстані Правила для контейнерів не встановлюють — лише 5 м.","ru":"Такого расстояния Правила для контейнеров не устанавливают — только 5 м."}}],"c":0,"e":{"uk":"За {p:15.10} стоянку заборонено **ближче 5 м** від контейнерних майданчиків та/або контейнерів для збирання побутових відходів.","ru":"Согласно {p:15.10} стоянка запрещена **ближе 5 м** от контейнерных площадок и/или контейнеров для сбора бытовых отходов."},"ref":["15.10"]},{"id":"h15-64","t":"h15","num":"15.64","q":{"uk":"Чи дозволена стоянка транспортних засобів на газонах?","ru":"Разрешена ли стоянка транспортных средств на газонах?"},"a":[{"uk":"Дозволена.","ru":"Разрешена.","w":{"uk":"Газони є в переліку місць, де стоянку заборонено.","ru":"Газоны есть в перечне мест, где стоянка запрещена."}},{"uk":"Заборонена.","ru":"Запрещена."}],"c":1,"e":{"uk":"Стоянку на газонах прямо заборонено {p:15.10}.","ru":"Стоянка на газонах прямо запрещена {p:15.10}."},"ref":["15.10"]},{"id":"h15-65","t":"h15","num":"15.65","q":{"uk":"Де на дорогах за межами населених пунктів дозволяється стоянка транспортних засобів у темну пору доби або в умовах недостатньої видимості?","ru":"Где на дорогах за пределами населённых пунктов разрешается стоянка транспортных средств в тёмное время суток или в условиях недостаточной видимости?"},"a":[{"uk":"На узбіччі.","ru":"На обочине.","w":{"uk":"Узбіччя є частиною дороги, а вночі поза населеними пунктами стояти можна лише за межами дороги чи на майданчиках.","ru":"Обочина является частью дороги, а ночью вне населённых пунктов стоять можно только за пределами дороги или на площадках."}},{"uk":"На майданчиках для стоянки.","ru":"На площадках для стоянки.","w":{"uk":"Неповна відповідь: стоянка дозволена також за межами дороги.","ru":"Неполный ответ: стоянка разрешена также за пределами дороги."}},{"uk":"За межами дороги.","ru":"За пределами дороги.","w":{"uk":"Неповна відповідь: стоянка дозволена також на майданчиках для стоянки.","ru":"Неполный ответ: стоянка разрешена также на площадках для стоянки."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3.","w":{"uk":"Узбіччя зайве: у таких умовах стоянка на ньому поза населеними пунктами заборонена.","ru":"Обочина лишняя: в таких условиях стоянка на ней вне населённых пунктов запрещена."}},{"uk":"Відповіді 2 і 3.","ru":"Ответы 2 и 3."}],"c":4,"e":{"uk":"За {p:15.11} у темну пору доби й в умовах недостатньої видимості стоянка поза населеними пунктами дозволена **лише** на майданчиках для стоянки або за межами дороги.","ru":"Согласно {p:15.11} в тёмное время суток и в условиях недостаточной видимости стоянка вне населённых пунктов разрешена **только** на площадках для стоянки или за пределами дороги."},"ref":["15.11"]},{"id":"h15-66","t":"h15","num":"15.66","q":{"uk":"Яких заходів повинен вжити водій транспортного засобу в разі вимушеної зупинки на місці, де зупинка заборонена, при відсутності можливості прибрати транспортний засіб?","ru":"Какие меры должен принять водитель транспортного средства в случае вынужденной остановки в месте, где остановка запрещена, при отсутствии возможности убрать транспортное средство?"},"a":[{"uk":"Тільки увімкнути аварійну сигналізацію.","ru":"Только включить аварийную сигнализацию.","w":{"uk":"Не завжди достатньо: у випадках з {p:9.10} треба ще й виставити знак аварійної зупинки, а без справної сигналізації — лише знак.","ru":"Не всегда достаточно: в случаях из {p:9.10} нужно ещё и выставить знак аварийной остановки, а без исправной сигнализации — только знак."}},{"uk":"Тільки встановити знак аварійної зупинки або миготливий червоний ліхтар.","ru":"Только установить знак аварийной остановки или мигающий красный фонарь.","w":{"uk":"Не завжди достатньо: основним заходом є аварійна сигналізація, а у випадках з {p:9.10} потрібні обидва заходи.","ru":"Не всегда достаточно: основной мерой является аварийная сигнализация, а в случаях из {p:9.10} нужны обе меры."}},{"uk":"Виконати дію з відповіді 1 або 2, а в установлених Правилами дорожнього руху випадках - й обидва дії одночасно.","ru":"Выполнить действие из ответа 1 или 2, а в установленных Правилами дорожного движения случаях — и оба действия одновременно."}],"c":2,"e":{"uk":"Якщо прибрати транспортний засіб неможливо, {p:15.14} відсилає до {p:9.9}–{p:9.11}: вмикають аварійну сигналізацію, а якщо її немає чи вона несправна — ставлять знак аварійної зупинки; у випадках, названих у {p:9.10}, потрібні обидва заходи одночасно.","ru":"Если убрать транспортное средство невозможно, {p:15.14} отсылает к {p:9.9}–{p:9.11}: включают аварийную сигнализацию, а если её нет или она неисправна — выставляют знак аварийной остановки; в случаях, названных в {p:9.10}, нужны обе меры одновременно."},"ref":["15.14","9.9","9.10","9.11"]},{"id":"h15-67","t":"h15","num":"15.67","q":{"uk":"У якому місці водій повинен виконати стоянку за межами населеного пункту в темний час доби або в умовах недостатньої видимості?","ru":"В каком месте водитель должен выполнить стоянку за пределами населённого пункта в тёмное время суток или в условиях недостаточной видимости?"},"a":[{"uk":"Виконати стоянку тільки за межами дороги.","ru":"Выполнить стоянку только за пределами дороги.","w":{"uk":"Неповна відповідь: стоянка дозволена й на майданчиках для стоянки.","ru":"Неполный ответ: стоянка разрешена и на площадках для стоянки."}},{"uk":"Виконати стоянку тільки на майданчиках для стоянки.","ru":"Выполнить стоянку только на площадках для стоянки.","w":{"uk":"Неповна відповідь: стоянка дозволена й за межами дороги.","ru":"Неполный ответ: стоянка разрешена и за пределами дороги."}},{"uk":"Виконати стоянку тільки на майданчиках для стоянки або за межами дороги.","ru":"Выполнить стоянку только на площадках для стоянки или за пределами дороги."},{"uk":"Виконати стоянку на узбіччі, включивши тільки стоянкові ліхтарі.","ru":"Выполнить стоянку на обочине, включив только стояночные огни.","w":{"uk":"Стоянкові вогні не роблять стоянку на узбіччі дозволеною: у таких умовах поза населеними пунктами вона заборонена.","ru":"Стояночные огни не делают стоянку на обочине разрешённой: в таких условиях вне населённых пунктов она запрещена."}}],"c":2,"e":{"uk":"{p:15.11} допускає в цих умовах поза населеними пунктами два варіанти: **майданчики для стоянки** або **місця за межами дороги**.","ru":"{p:15.11} допускает в этих условиях вне населённых пунктов два варианта: **площадки для стоянки** или **места за пределами дороги**."},"ref":["15.11"]},{"id":"h15-68","t":"h15","num":"15.68","q":{"uk":"За яких умов водій має право ставити транспортний засіб біля правого краю проїзної частини?","ru":"При каких условиях водитель имеет право ставить транспортное средство у правого края проезжей части?"},"a":[{"uk":"При відсутності спеціально відведених місць чи узбіччя.","ru":"При отсутствии специально отведённых мест или обочины.","w":{"uk":"Неповна відповідь: біля краю можна ставати й тоді, коли узбіччя є, але зупинитися на ньому неможливо.","ru":"Неполный ответ: у края можно становиться и тогда, когда обочина есть, но остановиться на ней невозможно."}},{"uk":"Коли зупинка або стоянка неможлива на узбіччях або в спеціально відведених місцях.","ru":"Когда остановка или стоянка невозможна на обочинах или в специально отведённых местах.","w":{"uk":"Неповна відповідь: біля краю можна ставати й тоді, коли узбіччя чи спеціальних місць просто немає.","ru":"Неполный ответ: у края можно становиться и тогда, когда обочины или специальных мест просто нет."}},{"uk":"Завжди, якщо водій зупинився для посадки або висадки пасажирів.","ru":"Всегда, если водитель остановился для посадки или высадки пассажиров.","w":{"uk":"Мета зупинки нічого не змінює: за наявності придатного узбіччя зупинятися слід на ньому.","ru":"Цель остановки ничего не меняет: при наличии пригодной обочины останавливаться следует на ней."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2."},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3.","w":{"uk":"Посадка (висадка) пасажирів не дає права ставати на проїзній частині, якщо є придатне узбіччя чи спеціально відведене місце.","ru":"Посадка (высадка) пассажиров не даёт права становиться на проезжей части, если есть пригодная обочина или специально отведённое место."}}],"c":3,"e":{"uk":"{p:15.2} дозволяє ставати біля правого краю проїзної частини у двох випадках: коли немає спеціально відведених місць чи узбіччя **або** коли зупинка чи стоянка там неможливі.","ru":"{p:15.2} разрешает становиться у правого края проезжей части в двух случаях: когда нет специально отведённых мест или обочины **либо** когда остановка или стоянка там невозможны."},"ref":["15.1","15.2"]},{"id":"h15-69","t":"h15","num":"15.69","q":{"uk":"Яких заходів повинен вжити водій, перед тим як залишити свій транспортний засіб?","ru":"Какие меры должен принять водитель, перед тем как оставить своё транспортное средство?"},"a":[{"uk":"Заходи щодо запобігання самовільного руху автомобіля.","ru":"Меры по предотвращению самопроизвольного движения автомобиля.","w":{"uk":"Неповна відповідь: треба також запобігти проникненню до транспортного засобу та його викраденню.","ru":"Неполный ответ: нужно также предотвратить проникновение в транспортное средство и его угон."}},{"uk":"Заходи щодо запобігання проникнення до нього і (або) незаконного заволодіння ним.","ru":"Меры по предотвращению проникновения в него и (или) незаконного завладения им.","w":{"uk":"Неповна відповідь: треба також запобігти самовільному руху транспортного засобу.","ru":"Неполный ответ: нужно также предотвратить самопроизвольное движение транспортного средства."}},{"uk":"Заходи щодо забезпечення цілісності вантажу, що перевозиться.","ru":"Меры по обеспечению сохранности перевозимого груза.","w":{"uk":"Збереження вантажу {p:15.12} не згадує — це не вимога Правил під час залишення транспортного засобу.","ru":"Сохранность груза {p:15.12} не упоминает — это не требование Правил при оставлении транспортного средства."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3.","w":{"uk":"Варіант 3 зайвий: заходів щодо цілісності вантажу {p:15.12} не вимагає.","ru":"Вариант 3 лишний: мер по сохранности груза {p:15.12} не требует."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2."}],"c":4,"e":{"uk":"{p:15.12} вимагає, залишаючи транспортний засіб, вжити заходів проти його **самовільного руху**, **проникнення** до нього і (або) **незаконного заволодіння** ним.","ru":"{p:15.12} требует, оставляя транспортное средство, принять меры против его **самопроизвольного движения**, **проникновения** в него и (или) **незаконного завладения** им."},"ref":["15.12"]},{"id":"h15-70","t":"h15","num":"15.70","q":{"uk":"У чому повинен переконатися водій перед тим, як відчинити двері транспортного засобу?","ru":"В чём должен убедиться водитель перед тем, как открыть дверь транспортного средства?"},"a":[{"uk":"У тому, що проїзна частина вільна від інших транспортних засобів.","ru":"В том, что проезжая часть свободна от других транспортных средств.","w":{"uk":"Проїзна частина не мусить бути зовсім вільною: важливо, щоб відчинені двері не загрожували безпеці й не заважали іншим.","ru":"Проезжая часть не обязана быть полностью свободной: важно, чтобы открытые двери не угрожали безопасности и не мешали другим."}},{"uk":"У тому, що це не загрожує безпеці дорожнього руху.","ru":"В том, что это не угрожает безопасности дорожного движения.","w":{"uk":"Неповна відповідь: треба також переконатися, що це не створить перешкод іншим.","ru":"Неполный ответ: нужно также убедиться, что это не создаст помех другим."}},{"uk":"У тому, що це не створює перешкод іншим учасникам дорожнього руху.","ru":"В том, что это не создаёт помех другим участникам дорожного движения.","w":{"uk":"Неповна відповідь: треба також переконатися, що це не загрожує безпеці руху.","ru":"Неполный ответ: нужно также убедиться, что это не угрожает безопасности движения."}},{"uk":"Відповіді 2 і 3.","ru":"Ответы 2 и 3."}],"c":3,"e":{"uk":"За {p:15.13} відчиняти двері можна, лише коли це не загрожує безпеці та не створює перешкод іншим учасникам дорожнього руху.","ru":"Согласно {p:15.13} открывать двери можно, только если это не угрожает безопасности и не создаёт помех другим участникам дорожного движения."},"ref":["15.13"]},{"id":"h15-71","t":"h15","num":"15.71","q":{"uk":"На якій відстані від залізничного переїзду водієві автомобіля дозволено виконати стоянку?","ru":"На каком расстоянии от железнодорожного переезда водителю автомобиля разрешено выполнить стоянку?"},"a":[{"uk":"На відстані не ближче 50 м від переїзду.","ru":"На расстоянии не ближе 50 м от переезда."},{"uk":"На відстані не ближче 100 м від переїзду.","ru":"На расстоянии не ближе 100 м от переезда.","w":{"uk":"Правила не вимагають відступати 100 м: стояти можна вже за 50 м від переїзду.","ru":"Правила не требуют отступать 100 м: стоять можно уже в 50 м от переезда."}},{"uk":"У всіх перерахованих випадках.","ru":"Во всех перечисленных случаях.","w":{"uk":"Мінімальна відстань одна — 50 м; вимоги про 100 м немає.","ru":"Минимальное расстояние одно — 50 м; требования о 100 м нет."}}],"c":0,"e":{"uk":"Стоянку заборонено ближче 50 м від залізничних переїздів ({p:15.10}), отже, дозволено — **не ближче 50 м**.","ru":"Стоянка запрещена ближе 50 м от железнодорожных переездов ({p:15.10}), следовательно, разрешена — **не ближе 50 м**."},"ref":["15.10"]},{"id":"h15-72","t":"h15","num":"15.72","q":{"uk":"Яких заходів, згідно з Правилами дорожнього руху, повинен вжити водій легкового автомобіля, поставленого на підйомі або спуску вздовж краю проїзної частини?","ru":"Какие меры, согласно Правилам дорожного движения, должен принять водитель легкового автомобиля, поставленного на подъёме или спуске вдоль края проезжей части?"},"a":[{"uk":"Повернути керовані колеса, щоб виключити можливість самовільного руху транспортного засобу.","ru":"Повернуть управляемые колёса, чтобы исключить возможность самопроизвольного движения транспортного средства."},{"uk":"Обов'язково скористатися противідкатними упорами.","ru":"Обязательно воспользоваться противооткатными упорами.","w":{"uk":"{p:15.7} не вимагає обов'язкових противідкотних упорів для легкового автомобіля — потрібно повернути колеса.","ru":"{p:15.7} не требует обязательных противооткатных упоров для легкового автомобиля — нужно повернуть колёса."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2.","w":{"uk":"Противідкотні упори в цьому пункті не згадано, тож обов'язковий лише поворот коліс.","ru":"Противооткатные упоры в этом пункте не упомянуты, поэтому обязателен только поворот колёс."}}],"c":0,"e":{"uk":"{p:15.7} дозволяє на спусках і підйомах ставити транспортний засіб уздовж краю проїзної частини, **повернувши керовані колеса** так, щоб виключити його самовільний рух.","ru":"{p:15.7} разрешает на спусках и подъёмах ставить транспортное средство вдоль края проезжей части, **повернув управляемые колёса** так, чтобы исключить его самопроизвольное движение."},"ref":["15.7"]},{"id":"h15-73","t":"h15","num":"15.73","q":{"uk":"Згідно з Правилами дорожнього руху, зупинка заборонена:","ru":"Согласно Правилам дорожного движения, остановка запрещена:"},"a":[{"uk":"Тільки перед залізничними переїздами.","ru":"Только перед железнодорожными переездами.","w":{"uk":"Перед переїздом зупинятися можна; ближче 50 м від нього заборонено лише стоянку.","ru":"Перед переездом останавливаться можно; ближе 50 м от него запрещена только стоянка."}},{"uk":"Тільки за залізничними переїздами.","ru":"Только за железнодорожными переездами.","w":{"uk":"За переїздом зупинятися можна; ближче 50 м від нього заборонено лише стоянку.","ru":"За переездом останавливаться можно; ближе 50 м от него запрещена только стоянка."}},{"uk":"Тільки на самих залізничних переїздах.","ru":"Только на самих железнодорожных переездах."},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3.","w":{"uk":"Заборона зупинки стосується лише самого переїзду, а не місць перед ним і за ним.","ru":"Запрет остановки касается только самого переезда, а не мест перед ним и за ним."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2.","w":{"uk":"Перед переїздом і за ним зупинка не заборонена — лише стоянка ближче 50 м.","ru":"Перед переездом и за ним остановка не запрещена — только стоянка ближе 50 м."}}],"c":2,"e":{"uk":"{p:15.9} забороняє зупинку **на** залізничних переїздах; перед ними й за ними обмеження 50 м стосується лише стоянки ({p:15.10}).","ru":"{p:15.9} запрещает остановку **на** железнодорожных переездах; перед ними и за ними ограничение 50 м касается только стоянки ({p:15.10})."},"ref":["15.9","15.10"]},{"id":"h15-74","t":"h15","num":"15.74","q":{"uk":"Ставити транспортний засіб під кутом до краю проїзної частини дозволяється:","ru":"Ставить транспортное средство под углом к краю проезжей части разрешается:"},"a":[{"uk":"В місцях, де це не буде перешкоджати руху інших транспортних засобів.","ru":"В местах, где это не будет мешать движению других транспортных средств.","w":{"uk":"Неповна відповідь: біля тротуарів діє ще й обмеження щодо того, якою частиною ставити транспортний засіб.","ru":"Неполный ответ: у тротуаров действует ещё и ограничение, какой частью ставить транспортное средство."}},{"uk":"Біля тротуарів або інших місць із пішохідним рухом лише передньою частиною, а на підйомах – тільки задньою частиною.","ru":"У тротуаров или других мест с пешеходным движением только передней частью, а на подъёмах — только задней частью.","w":{"uk":"Неповна відповідь: ставати під кутом можна лише там, де це не заважатиме руху інших транспортних засобів.","ru":"Неполный ответ: становиться под углом можно только там, где это не будет мешать движению других транспортных средств."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2."}],"c":2,"e":{"uk":"{p:15.5} містить обидві умови: під кутом ставати можна там, де це не заважає іншим транспортним засобам, а біля тротуарів — лише передньою частиною (на підйомах — задньою).","ru":"{p:15.5} содержит оба условия: под углом становиться можно там, где это не мешает другим транспортным средствам, а у тротуаров — только передней частью (на подъёмах — задней)."},"ref":["15.5"]},{"id":"h15-75","t":"h15","num":"15.75","q":{"uk":"На якій відстані від пішохідного переходу дозволена зупинка транспортних засобів?","ru":"На каком расстоянии от пешеходного перехода разрешена остановка транспортных средств?"},"a":[{"uk":"На відстані не менше 10 м з обох боків від переходу.","ru":"На расстоянии не менее 10 м с обеих сторон от перехода."},{"uk":"На відстані не менше 10 м до переходу.","ru":"На расстоянии не менее 10 м до перехода.","w":{"uk":"Вимога 10 м діє з обох боків переходу, а не лише перед ним.","ru":"Требование 10 м действует с обеих сторон перехода, а не только перед ним."}},{"uk":"На відстані не менше 20 м з обох боків від переходу.","ru":"На расстоянии не менее 20 м с обеих сторон от перехода.","w":{"uk":"Правила вимагають 10 м, а не 20 м.","ru":"Правила требуют 10 м, а не 20 м."}},{"uk":"На відстані не менше 30 м з обох боків від переходу.","ru":"На расстоянии не менее 30 м с обеих сторон от перехода.","w":{"uk":"30 м стосується посадкових майданчиків маршрутних транспортних засобів, а не пішохідних переходів.","ru":"30 м касается посадочных площадок маршрутных транспортных средств, а не пешеходных переходов."}}],"c":0,"e":{"uk":"Зупинку заборонено на пішохідних переходах і **ближче 10 м від них з обох боків** ({p:15.9}), тож дозволено — не ближче 10 м і перед переходом, і за ним.","ru":"Остановка запрещена на пешеходных переходах и **ближе 10 м от них с обеих сторон** ({p:15.9}), поэтому разрешена — не ближе 10 м и перед переходом, и за ним."},"ref":["15.9"]},{"id":"h15-76","t":"h15","num":"15.76","q":{"uk":"За якої умови дозволено ставити транспортні засоби під кутом до краю проїзної частини, якщо інший спосіб не визначений дорожніми знаками чи розміткою?"},"a":[{"uk":"При відсутності тротуарів або інших місць із пішохідним рухом."},{"uk":"Якщо це не буде перешкоджати руху інших транспортних засобів."}],"c":1},{"id":"h15-77","t":"h15","num":"15.77","q":{"uk":"Чи дозволено ставити транспортні засоби в два ряди на проїзній частині?"},"a":[{"uk":"Дозволено ставити тільки велосипеди і мопеди."},{"uk":"Заборонено ставити всі транспортні засоби."},{"uk":"Дозволено ставити тільки велосипеди, мопеди і мотоцикли без бокового причепа."}],"c":2},{"id":"h15-78","t":"h15","num":"15.78","q":{"uk":"У якому з перелічених місць заборонено зупинку транспортних засобів?"},"a":[{"uk":"У місцях, де відстань між суцільною лінією розмітки, розділювальною смугою чи протилежним краєм проїзної частини і транспортним засобом, що зупинився, менше 3 м."},{"uk":"На перехрестях та ближче 10 м від краю перехрещуваної проїзної частини за відсутності на них пішохідного переходу, за винятком зупинки для надання переваги в русі та зупинки проти бокового проїзду на Т-подібних перехрестях, де є суцільна лінія розмітки або розділювальна смуга."},{"uk":"На пішохідних переходах і ближче ніж за 10 м до них з обох боків."},{"uk":"Відповіді 1 і 3."},{"uk":"Відповіді 1, 2 і 3."}],"c":4},{"id":"h15-79","t":"h15","num":"15.79","q":{"uk":"Чи дозволені зупинка і стоянка біля розділювальних смуг або бульварів?"},"a":[{"uk":"Дозволені."},{"uk":"Заборонені."},{"uk":"Дозволені для посадки або висадки людей."}],"c":1},{"id":"h15-80","t":"h15","num":"15.80","q":{"uk":"У якому з місць забороняється зупинка?"},"a":[{"uk":"На мостах."},{"uk":"На шляхопроводах й естакадах."},{"uk":"Під мостами, шляхопроводами та естакадами."},{"uk":"Відповіді 1 і 2."},{"uk":"Відповіді 1, 2 і 3."}],"c":4},{"id":"h15-81","t":"h15","num":"15.81","q":{"uk":"Чи дозволено водіям легкових автомобілів виконувати зупинку або стоянку на лівому боці дороги, яка має по одній смузі для руху в кожному напрямку, без трамвайних колій посередині і не розділена суцільною розміткою, а також на лівому боці дороги з одностороннім рухом у населеному пункті?"},"a":[{"uk":"Дозволено."},{"uk":"Заборонено."}],"c":0},{"id":"h15-82","t":"h15","num":"15.82","q":{"uk":"На яких дорогах населених пунктів водієві легкового автомобіля дозволено поставити свій транспортний засіб біля лівого краю проїзної частини?"},"a":[{"uk":"На дорогах, що мають по одній смузі для руху в кожному напрямку, без трамвайних колій посередині і не розділених суцільною розміткою."},{"uk":"На дорозі з одностороннім рухом."},{"uk":"На всіх дорогах, що мають по одній смузі для руху в кожному напрямку."},{"uk":"Відповіді 1 і 2."},{"uk":"Відповіді 1, 2 і 3."}],"c":3},{"id":"h15-83","t":"h15","num":"15.83","q":{"uk":"У яких місцях заборонено зупинку транспортних засобів?"},"a":[{"uk":"У місцях, де буде неможливим зустрічний роз'їзд."},{"uk":"У місцях, де буде неможливим об'їзд транспортного засобу, що зупинився."},{"uk":"У місцях, де транспортний засіб закриває від інших водіїв сигнали світлофора або дорожні знаки."},{"uk":"Відповіді 1 і 2."},{"uk":"Відповіді 1, 2 і 3."}],"c":4},{"id":"h15-84","t":"h15","num":"15.84","q":{"uk":"На якій відстані від виїздів з прилеглих територій водіям дозволяється виконати зупинку?"},"a":[{"uk":"Не ближче 10 м."},{"uk":"Не ближче 15 м."},{"uk":"Не ближче 20 м."}],"c":0},{"id":"h15-85","t":"h15","num":"15.85","q":{"uk":"Чи дозволена стоянка в місцях, де Правилами дорожнього руху забороняється зупинка транспортних засобів?"},"a":[{"uk":"Заборонено."},{"uk":"Дозволено на час до 20 хвилин."},{"uk":"Дозволено."}],"c":0},{"id":"h15-86","t":"h15","num":"15.86","q":{"uk":"У якому з місць заборонена стоянка транспортних засобів?"},"a":[{"uk":"На тротуарах у будь-якому випадку."},{"uk":"На тротуарах, крім місць, позначених відповідними дорожніми знаками, встановленими з табличками."},{"uk":"На тротуарах, за винятком легкових автомобілів та мотоциклів, які можуть бути поставлені на краю тротуарів, де для руху пішоходів залишається щонайменше 2 м."},{"uk":"Більше 100 м від залізничного переїзду."},{"uk":"Відповіді 2 і 3."}],"c":4},{"id":"h15-87","t":"h15","num":"15.87","q":{"uk":"У яких випадках транспортним засобам дозволяється стоянка на тротуарі?"},"a":[{"uk":"На тротуарах тільки легковим автомобілям і мотоциклам, у місцях, позначених знаками, встановленими з табличками."},{"uk":"На краю тротуарів, де для руху пішоходів залишається щонайменше 2 м, - тільки легковим автомобілям і мотоциклам."},{"uk":"На всіх тротуарах, де не створюються перешкоди для руху пішоходів."},{"uk":"Відповіді 1, 2 і 3."},{"uk":"Відповіді 1 і 2."}],"c":4},{"id":"h15-88","t":"h15","num":"15.88","q":{"uk":"Яка ширина повинна бути залишена для руху пішоходів, якщо легковий автомобіль або мотоцикл поставлені на краю тротуару відповідно до Правил дорожнього руху?"},"a":[{"uk":"Не менше 1 м."},{"uk":"Не менше 1,5 м."},{"uk":"Не менше 2 м."},{"uk":"Не менше 3 м."}],"c":2},{"id":"h15-89","t":"h15","num":"15.89","q":{"uk":"Де водієві заборонено зупинку?"},"a":[{"uk":"На набережних."},{"uk":"На мостах, шляхопроводах й естакадах."},{"uk":"У тунелях."},{"uk":"Відповіді 1, 2 і 3."},{"uk":"Відповіді 2 і 3."}],"c":4},{"id":"h15-90","t":"h15","num":"15.90","q":{"uk":"Чи дозволена стоянка чорного автомобіля в цьому місці?"},"a":[{"uk":"Дозволена."},{"uk":"Заборонена."}],"c":1,"pic":["img/hsc/15-90-1.jpg"]},{"id":"h15-91","t":"h15","num":"15.91","q":{"uk":"Чи дозволено водієві сірого автомобіля зупинитись у цьому місці?"},"a":[{"uk":"Дозволено."},{"uk":"Заборонено."}],"c":1,"pic":["img/hsc/15-91-1.jpg"]},{"id":"h15-92","t":"h15","num":"15.92","q":{"uk":"Хто з водіїв, виконуючи зупинку, порушив Правила дорожнього руху?"},"a":[{"uk":"Обидва водії."},{"uk":"Тільки водій жовтого автомобіля."},{"uk":"Водій білого автомобіля."}],"c":0,"pic":["img/hsc/15-92-1.jpg"]},{"id":"h15-93","t":"h15","num":"15.93","q":{"uk":"Чи має право водій білого автомобіля виконати зупинку у цьому місці?"},"a":[{"uk":"Так."},{"uk":"Ні."}],"c":1,"pic":["img/hsc/15-93-1.jpg"]},{"id":"h15-94","t":"h15","num":"15.94","q":{"uk":"Чи дозволено водієві сірого автомобіля зупинитись у цьому місці?"},"a":[{"uk":"Дозволено."},{"uk":"Заборонено."}],"c":1,"pic":["img/hsc/15-94-1.jpg"]},{"id":"h15-95","t":"h15","num":"15.95","q":{"uk":"Чи порушив водій чорного автомобіля правила зупинки?"},"a":[{"uk":"Так."},{"uk":"Ні."}],"c":0,"pic":["img/hsc/15-95-1.jpg"]},{"id":"h15-96","t":"h15","num":"15.96","q":{"uk":"Чи дозволена стоянка автомобіля в цьому місці?"},"a":[{"uk":"Заборонена."},{"uk":"Дозволена, за умови, що є 2 метри для руху пішоходів."},{"uk":"Дозволена, за умови, що поруч немає інших місць для паркування."}],"c":0,"pic":["img/hsc/15-96-1.jpg"]},{"id":"h15-97","t":"h15","num":"15.97","q":{"uk":"Чи дозволено водієві чорного автомобіля зупинитись так як показано на малюнку?"},"a":[{"uk":"Дозволено."},{"uk":"Заборонено."}],"c":1,"pic":["img/hsc/15-97-1.jpg"]},{"id":"h16.1-1","t":"h16.1","num":"16.1.1","q":{"uk":"Як повинен у даній ситуації вчинити водій білого автомобіля, який очікує ввімкнення сигналу світлофора, що дозволяє рух, щоб їхати прямо?","ru":"Как должен в данной ситуации поступить водитель белого автомобиля, который ожидает включения разрешающего движение сигнала светофора, чтобы ехать прямо?"},"a":[{"uk":"Продовжити рух у наміченому напрямку, тільки коли буде увімкнено зелений сигнал світлофора.","ru":"Продолжить движение в намеченном направлении только тогда, когда будет включён зелёный сигнал светофора.","w":{"uk":"Чекаючи зеленого сигналу, білий автомобіль створить перешкоду зеленому автомобілю, який стоїть за ним у тій самій смузі й повертає ліворуч, а {p:16.10} саме цього не допускає.","ru":"Ожидая зелёного сигнала, белый автомобиль создаст помеху зелёному автомобилю, который стоит за ним в той же полосе и поворачивает налево, а {p:16.10} именно этого не допускает."}},{"uk":"Увімкнути лівий покажчик повороту, продовжити рух у напрямку, вказаному стрілкою, увімкненою в додатковій секції.","ru":"Включить левый указатель поворота и продолжить движение в направлении, указанном стрелкой, включённой в дополнительной секции."},{"uk":"Перестроїтися в правий ряд.","ru":"Перестроиться в правый ряд.","w":{"uk":"Права смуга зайнята сірим і оранжевим автомобілями, тож безпечно перестроїтися неможливо; до того ж {p:16.10} прямо вимагає продовжити рух за стрілкою.","ru":"Правая полоса занята серым и оранжевым автомобилями, поэтому безопасно перестроиться невозможно; к тому же {p:16.10} прямо требует продолжить движение по стрелке."}}],"c":1,"e":{"uk":"Білий автомобіль стоїть у лівій смузі, з якої виконують поворот ліворуч, у додатковій секції горить стрілка ліворуч, а за ним стоїть зелений автомобіль з увімкненим лівим покажчиком повороту. Якщо білий чекатиме зеленого сигналу, він заблокує зелений автомобіль, тому за {p:16.10} повинен рухатися в напрямку стрілки, попередньо подавши сигнал лівим покажчиком повороту ({p:9.2}).","ru":"Белый автомобиль стоит в левой полосе, из которой выполняется поворот налево, в дополнительной секции горит стрелка налево, а за ним стоит зелёный автомобиль с включённым левым указателем поворота. Если белый будет ждать зелёного сигнала, он заблокирует зелёный автомобиль, поэтому по {p:16.10} должен двигаться в направлении стрелки, предварительно подав сигнал левым указателем поворота ({p:9.2})."},"ref":["16.10","8.7","9.2"],"pic":["img/hsc/16.1-1-1.jpg"]},{"id":"h16.1-2","t":"h16.1","num":"16.1.2","q":{"uk":"Повертаючи праворуч, водій синього автомобіля повинен:","ru":"Поворачивая направо, водитель синего автомобиля должен:"},"a":[{"uk":"Проїхати перехрестя першим.","ru":"Проехать перекрёсток первым.","w":{"uk":"Коли зелений сигнал дозволяє рух одночасно трамваям і нерейковим транспортним засобам, перевага за {p:16.7} у трамваїв, тож першим синій автомобіль не проїде.","ru":"Когда зелёный сигнал разрешает движение одновременно трамваям и нерельсовым транспортным средствам, преимущество по {p:16.7} у трамваев, поэтому первым синий автомобиль не проедет."}},{"uk":"Дати дорогу тільки зустрічному трамваю.","ru":"Уступить дорогу только встречному трамваю.","w":{"uk":"Попутний трамвай теж має перевагу за {p:16.7}, а синій автомобіль, повертаючи праворуч, перетинатиме його колію.","ru":"Попутный трамвай тоже имеет преимущество по {p:16.7}, а синий автомобиль, поворачивая направо, будет пересекать его путь."}},{"uk":"Дати дорогу обом трамваям.","ru":"Уступить дорогу обоим трамваям."},{"uk":"Дати дорогу тільки попутному трамваю.","ru":"Уступить дорогу только попутному трамваю.","w":{"uk":"Зустрічний трамвай так само користується перевагою, адже {p:16.7} діє незалежно від напрямку руху трамвая.","ru":"Встречный трамвай так же пользуется преимуществом, ведь {p:16.7} действует независимо от направления движения трамвая."}}],"c":2,"e":{"uk":"Зелений сигнал світлофора дозволяє рух одночасно трамваям і синьому автомобілю, тому за {p:16.7} трамваї мають перевагу незалежно від напрямку свого руху. Повертаючи праворуч, синій автомобіль перетинає трамвайну колію, тож мусить пропустити і попутний, і зустрічний трамваї.","ru":"Зелёный сигнал светофора разрешает движение одновременно трамваям и синему автомобилю, поэтому по {p:16.7} трамваи имеют преимущество независимо от направления своего движения. Поворачивая направо, синий автомобиль пересекает трамвайные пути, поэтому должен пропустить и попутный, и встречный трамваи."},"ref":["16.7"],"pic":["img/hsc/16.1-2-1.jpg"]},{"id":"h16.1-3","t":"h16.1","num":"16.1.3","q":{"uk":"Який транспортний засіб у даній ситуації має перевагу в русі?","ru":"Какое транспортное средство в данной ситуации имеет преимущество в движении?"},"a":[{"uk":"Трамвай.","ru":"Трамвай."},{"uk":"Автомобіль.","ru":"Автомобиль.","w":{"uk":"Те, що трамвай повертає ліворуч, не дає переваги зустрічному автомобілю: між трамваєм і нерейковим транспортом при спільному зеленому сигналі діє {p:16.7}.","ru":"То, что трамвай поворачивает налево, не даёт преимущества встречному автомобилю: между трамваем и нерельсовым транспортом при общем зелёном сигнале действует {p:16.7}."}}],"c":0,"e":{"uk":"І трамваю, і автомобілю горить зелений сигнал, тобто рух дозволено їм одночасно. У такому разі за {p:16.7} трамвай має перевагу незалежно від напрямку свого руху — навіть повертаючи ліворуч перед зустрічним автомобілем.","ru":"И трамваю, и автомобилю горит зелёный сигнал, то есть движение разрешено им одновременно. В таком случае по {p:16.7} трамвай имеет преимущество независимо от направления своего движения — даже поворачивая налево перед встречным автомобилем."},"ref":["16.7"],"pic":["img/hsc/16.1-3-1.jpg"]},{"id":"h16.1-4","t":"h16.1","num":"16.1.4","q":{"uk":"Як повинен вчинити водій білого автомобіля, якщо він виїхав на перехрещення проїзних частин на сигнал світлофора, що дозволяє рух?","ru":"Как должен поступить водитель белого автомобиля, если он выехал на пересечение проезжих частей по разрешающему движение сигналу светофора?"},"a":[{"uk":"Зупинитися перед світлофором на шляху руху і, дочекавшись ввімкнення зеленого сигналу, продовжити рух.","ru":"Остановиться перед светофором на пути движения и, дождавшись включения зелёного сигнала, продолжить движение.","w":{"uk":"Зупинятися перед світлофором усередині перехрестя потрібно лише тоді, коли перед ним є стоп-лінія або знак {s:5.69}; тут їх немає, а зупинка лише заблокувала б перехрестя.","ru":"Останавливаться перед светофором внутри перекрёстка нужно только тогда, когда перед ним есть стоп-линия или знак {s:5.69}; здесь их нет, а остановка лишь заблокировала бы перекрёсток."}},{"uk":"Закінчити поворот ліворуч незалежно від сигналу світлофора на шляху свого руху.","ru":"Завершить поворот налево независимо от сигнала светофора на пути своего движения."}],"c":1,"e":{"uk":"Білий автомобіль виїхав на перехрещення проїзних частин на дозвільний сигнал, а перед світлофором на його шляху немає ні стоп-лінії {m:1.12}, ні знака {s:5.69}. Тому за {p:16.8} він має виїхати в наміченому напрямку незалежно від червоного сигналу цього світлофора.","ru":"Белый автомобиль выехал на пересечение проезжих частей по разрешающему сигналу, а перед светофором на его пути нет ни стоп-линии {m:1.12}, ни знака {s:5.69}. Поэтому по {p:16.8} он должен выехать в намеченном направлении независимо от красного сигнала этого светофора."},"ref":["16.8"],"pic":["img/hsc/16.1-4-1.jpg"]},{"id":"h16.1-5","t":"h16.1","num":"16.1.5","q":{"uk":"Як повинен вчинити водій білого автомобіля, що виїхав на перехрещення проїзних частин на зелений сигнал світлофора?","ru":"Как должен поступить водитель белого автомобиля, выехавший на пересечение проезжих частей на зелёный сигнал светофора?"},"a":[{"uk":"Повинен продовжувати рух у наміченому напрямку, незважаючи на ввімкнений заборонний сигнал світлофора.","ru":"Должен продолжать движение в намеченном направлении, несмотря на включённый запрещающий сигнал светофора.","w":{"uk":"Виїжджати незалежно від сигналів світлофора на виїзді можна лише тоді, коли перед ним немає стоп-лінії чи знака {s:5.69}; тут вони є, тому червоний сигнал обов'язковий для виконання.","ru":"Выезжать независимо от сигналов светофора на выезде можно, только если перед ним нет стоп-линии или знака {s:5.69}; здесь они есть, поэтому красный сигнал обязателен для выполнения."}},{"uk":"Повинен зупинитися перед дорожньою розміткою «Стоп-лінія» і продовжити рух, коли ввімкнеться зелений сигнал світлофора.","ru":"Должен остановиться перед дорожной разметкой «Стоп-линия» и продолжить движение, когда включится зелёный сигнал светофора."}],"c":1,"e":{"uk":"Перед наступним світлофором на шляху білого автомобіля нанесено стоп-лінію {m:1.12} і встановлено знак {s:5.69} (табличка «STOP»). У такому разі за {p:16.8} водій повинен керуватися сигналами кожного світлофора, тож на червоний сигнал зупиняється перед стоп-лінією ({p:8.10}) і рушає, коли ввімкнеться зелений.","ru":"Перед следующим светофором на пути белого автомобиля нанесена стоп-линия {m:1.12} и установлен знак {s:5.69} (табличка «STOP»). В таком случае по {p:16.8} водитель должен руководствоваться сигналами каждого светофора, поэтому на красный сигнал останавливается перед стоп-линией ({p:8.10}) и трогается, когда включится зелёный."},"ref":["16.8","8.10"],"pic":["img/hsc/16.1-5-1.jpg"]},{"id":"h16.1-6","t":"h16.1","num":"16.1.6","q":{"uk":"Як повинен діяти водій зеленого автомобіля, що повертає ліворуч, у даній ситуації?","ru":"Как должен действовать водитель зелёного автомобиля, поворачивающего налево, в данной ситуации?"},"a":[{"uk":"Виїхати в наміченому напрямку незалежно від сигналу світлофора на шляху свого руху.","ru":"Выехать в намеченном направлении независимо от сигнала светофора на пути своего движения.","w":{"uk":"Правило «виїхати незалежно від сигналу на виїзді» не діє, якщо перед світлофором на шляху руху є стоп-лінія або знак {s:5.69}, а тут є і те, і інше.","ru":"Правило «выехать независимо от сигнала на выезде» не действует, если перед светофором на пути движения есть стоп-линия или знак {s:5.69}, а здесь есть и то, и другое."}},{"uk":"Зупинитися перед дорожньою розміткою «Стоп-лінія» і продовжити рух, коли ввімкнеться зелений сигнал світлофора.","ru":"Остановиться перед дорожной разметкой «Стоп-линия» и продолжить движение, когда включится зелёный сигнал светофора."}],"c":1,"e":{"uk":"Після повороту ліворуч на шляху зеленого автомобіля є стоп-лінія {m:1.12} і світлофор зі знаком {s:5.69}, на якому горить червоний сигнал. За {p:16.8} у такому разі треба керуватися сигналами кожного світлофора, тому водій зупиняється перед стоп-лінією ({p:8.10}) і чекає зеленого сигналу.","ru":"После поворота налево на пути зелёного автомобиля есть стоп-линия {m:1.12} и светофор со знаком {s:5.69}, на котором горит красный сигнал. По {p:16.8} в таком случае нужно руководствоваться сигналами каждого светофора, поэтому водитель останавливается перед стоп-линией ({p:8.10}) и ждёт зелёного сигнала."},"ref":["16.8","8.10"],"pic":["img/hsc/16.1-6-1.jpg"]},{"id":"h16.1-7","t":"h16.1","num":"16.1.7","q":{"uk":"Хто в даній ситуації повинен дати дорогу?","ru":"Кто в данной ситуации должен уступить дорогу?"},"a":[{"uk":"Водій автомобіля.","ru":"Водитель автомобиля.","w":{"uk":"Автомобіль рухається на основний зелений сигнал, а трамвай — за додатковою стрілкою при червоному; перевага трамвая за {p:16.7} діє лише тоді, коли зелений сигнал дозволяє рух обом.","ru":"Автомобиль движется на основной зелёный сигнал, а трамвай — по дополнительной стрелке при красном; преимущество трамвая по {p:16.7} действует, только когда зелёный сигнал разрешает движение обоим."}},{"uk":"Водій трамвая.","ru":"Водитель трамвая."}],"c":1,"e":{"uk":"Трамвай їде прямо за стрілкою в додатковій секції, увімкненою разом із червоним сигналом, а синьому автомобілю горить зелений. За {p:16.9} той, хто рухається за такою стрілкою, повинен дати дорогу транспортним засобам з інших напрямків, тож поступається водій трамвая.","ru":"Трамвай едет прямо по стрелке в дополнительной секции, включённой вместе с красным сигналом, а синему автомобилю горит зелёный. По {p:16.9} тот, кто движется по такой стрелке, должен уступить дорогу транспортным средствам с других направлений, поэтому уступает водитель трамвая."},"ref":["16.9","8.7"],"pic":["img/hsc/16.1-7-1.jpg"]},{"id":"h16.1-8","t":"h16.1","num":"16.1.8","q":{"uk":"Який транспортний засіб першим проїде дане перехрестя?","ru":"Какое транспортное средство первым проедет данный перекрёсток?"},"a":[{"uk":"Червоний автомобіль.","ru":"Красный автомобиль."},{"uk":"Синій автомобіль.","ru":"Синий автомобиль.","w":{"uk":"Рух за стрілкою додаткової секції при червоному сигналі дозволено лише за умови безперешкодного пропуску транспорту з інших напрямків, тож синій автомобіль переваги не має.","ru":"Движение по стрелке дополнительной секции при красном сигнале разрешено лишь при условии беспрепятственного пропуска транспорта с других направлений, поэтому синий автомобиль преимущества не имеет."}}],"c":0,"e":{"uk":"Синій автомобіль їде прямо за стрілкою додаткової секції при червоному сигналі, а червоному автомобілю, який повертає ліворуч, горить зелений. За {p:16.9} синій повинен дати дорогу транспортним засобам, що рухаються з інших напрямків, тому першим проїжджає червоний.","ru":"Синий автомобиль едет прямо по стрелке дополнительной секции при красном сигнале, а красному автомобилю, который поворачивает налево, горит зелёный. По {p:16.9} синий должен уступить дорогу транспортным средствам, движущимся с других направлений, поэтому первым проезжает красный."},"ref":["16.9","8.7"],"pic":["img/hsc/16.1-8-1.jpg"]},{"id":"h16.1-9","t":"h16.1","num":"16.1.9","q":{"uk":"Як велосипедист проїде перехрестя в даному випадку?","ru":"Как велосипедист проедет перекрёсток в данном случае?"},"a":[{"uk":"Дасть дорогу трамваю.","ru":"Уступит дорогу трамваю.","w":{"uk":"Перевага трамвая за {p:16.7} діє лише тоді, коли зелений сигнал дозволяє рух одночасно трамваю і нерейковим транспортним засобам; тут трамвай рухається за додатковою стрілкою при червоному.","ru":"Преимущество трамвая по {p:16.7} действует, только когда зелёный сигнал разрешает движение одновременно трамваю и нерельсовым транспортным средствам; здесь трамвай движется по дополнительной стрелке при красном."}},{"uk":"Проїде першим, маючи перевагу.","ru":"Проедет первым, имея преимущество."}],"c":1,"e":{"uk":"Велосипедисту горить зелений сигнал, а трамвай повертає праворуч за стрілкою додаткової секції при червоному сигналі. За {p:16.9} трамвай повинен дати дорогу транспортним засобам з інших напрямків, зокрема й велосипеду, тож велосипедист проїжджає першим.","ru":"Велосипедисту горит зелёный сигнал, а трамвай поворачивает направо по стрелке дополнительной секции при красном сигнале. По {p:16.9} трамвай должен уступить дорогу транспортным средствам с других направлений, в том числе и велосипеду, поэтому велосипедист проезжает первым."},"ref":["16.9","8.7"],"pic":["img/hsc/16.1-9-1.jpg"]},{"id":"h16.1-10","t":"h16.1","num":"16.1.10","q":{"uk":"Як повинен вчинити водій червоного автомобіля, що збирається повертати праворуч, у даній ситуації?","ru":"Как должен поступить в данной ситуации водитель красного автомобиля, который собирается поворачивать направо?"},"a":[{"uk":"Продовжити рух тільки після ввімкнення зеленого сигналу світлофора.","ru":"Продолжить движение только после включения зелёного сигнала светофора.","w":{"uk":"Табличка зі стрілкою якраз дозволяє повернути праворуч при червоному сигналі, тож чекати зеленого не обов'язково.","ru":"Табличка со стрелкой как раз разрешает повернуть направо при красном сигнале, поэтому ждать зелёного не обязательно."}},{"uk":"Повернути праворуч, давши дорогу пішоходам і транспортним засобам, які рухаються з інших напрямків.","ru":"Повернуть направо, уступив дорогу пешеходам и транспортным средствам, движущимся с других направлений."},{"uk":"Повернути праворуч, давши дорогу лише транспортним засобам, що рухаються з інших напрямків.","ru":"Повернуть направо, уступив дорогу только транспортным средствам, движущимся с других направлений.","w":{"uk":"Рухаючись за стрілкою на табличці, за {p:16.9} треба пропустити не лише транспорт, а й пішоходів, що рухаються з інших напрямків.","ru":"Двигаясь по стрелке на табличке, по {p:16.9} нужно пропустить не только транспорт, но и пешеходов, движущихся с других направлений."}}],"c":1,"e":{"uk":"На рівні червоного сигналу встановлено білу табличку із зеленою стрілкою праворуч: вона дозволяє поворот праворуч із крайньої правої смуги при червоному сигналі ({p:8.7}). Але за {p:16.9} водій повинен дати дорогу і транспортним засобам, і пішоходам, що рухаються з інших напрямків, — зокрема пішоходу на переході.","ru":"На уровне красного сигнала установлена белая табличка с зелёной стрелкой направо: она разрешает поворот направо из крайней правой полосы при красном сигнале ({p:8.7}). Но по {p:16.9} водитель должен уступить дорогу и транспортным средствам, и пешеходам, движущимся с других направлений, — в том числе пешеходу на переходе."},"ref":["16.9","8.7"],"pic":["img/hsc/16.1-10-1.jpg"]},{"id":"h16.1-11","t":"h16.1","num":"16.1.11","q":{"uk":"Чи дозволено Вам повернути праворуч у даній ситуації при ввімкненому червоному сигналі світлофора?","ru":"Разрешено ли Вам повернуть направо в данной ситуации при включённом красном сигнале светофора?"},"a":[{"uk":"Заборонено.","ru":"Запрещено.","w":{"uk":"Зелена стрілка на табличці поруч із червоним сигналом якраз дозволяє поворот праворуч при червоному сигналі.","ru":"Зелёная стрелка на табличке рядом с красным сигналом как раз разрешает поворот направо при красном сигнале."}},{"uk":"Дозволено, давши дорогу пішоходам.","ru":"Разрешено, уступив дорогу пешеходам.","w":{"uk":"Пропустити треба не лише пішоходів, а й транспортні засоби з інших напрямків, які рухаються на свій зелений сигнал ({p:16.9}).","ru":"Пропустить нужно не только пешеходов, но и транспортные средства с других направлений, которые движутся на свой зелёный сигнал ({p:16.9})."}},{"uk":"Дозволено, давши дорогу транспортним засобам і пішоходам, що рухаються з інших напрямків.","ru":"Разрешено, уступив дорогу транспортным средствам и пешеходам, движущимся с других направлений."}],"c":2,"e":{"uk":"На рівні червоного сигналу встановлено білу табличку із зеленою стрілкою праворуч. Вона дозволяє поворот праворуч при червоному сигналі з крайньої правої смуги ({p:8.7}), але за {p:16.9} водій повинен дати дорогу транспортним засобам і пішоходам, що рухаються з інших напрямків.","ru":"На уровне красного сигнала установлена белая табличка с зелёной стрелкой направо. Она разрешает поворот направо при красном сигнале из крайней правой полосы ({p:8.7}), но по {p:16.9} водитель должен уступить дорогу транспортным средствам и пешеходам, движущимся с других направлений."},"ref":["16.9","8.7"],"pic":["img/hsc/16.1-11-1.jpg"]},{"id":"h16.1-12","t":"h16.1","num":"16.1.12","q":{"uk":"На якому малюнку водій чорного автомобіля, який зупинився на заборонний сигнал світлофора, щоб потім їхати в прямому напрямку, обов'язково повинен продовжити рух праворуч (у напрямку стрілки), коли транспортний засіб, що наближається ззаду, подав сигнал повороту праворуч?","ru":"На каком рисунке водитель чёрного автомобиля, который остановился на запрещающий сигнал светофора, чтобы потом ехать в прямом направлении, обязательно должен продолжить движение направо (в направлении стрелки), когда транспортное средство, приближающееся сзади, подало сигнал поворота направо?"},"a":[{"uk":"На обох.","ru":"На обоих.","w":{"uk":"На другому малюнку не додаткова секція, а табличка зі стрілкою, тоді як {p:16.10} говорить лише про світлофор з додатковою секцією.","ru":"На втором рисунке не дополнительная секция, а табличка со стрелкой, тогда как {p:16.10} говорит только о светофоре с дополнительной секцией."}},{"uk":"На першому.","ru":"На первом."},{"uk":"На другому.","ru":"На втором.","w":{"uk":"Саме на другому малюнку (табличка зі стрілкою) обов'язку повертати немає; він є лише на першому — з додатковою секцією.","ru":"Именно на втором рисунке (табличка со стрелкой) обязанности поворачивать нет; она есть только на первом — с дополнительной секцией."}}],"c":1,"e":{"uk":"Обов'язок за {p:16.10} — продовжити рух за стрілкою, щоб не заважати транспорту позаду в тій самій смузі, — стосується лише світлофора з додатковою секцією, як на першому малюнку. На другому малюнку стрілку нанесено на табличці на рівні червоного сигналу: вона лише дозволяє поворот ({p:16.9}), але не зобов'язує його виконувати.","ru":"Обязанность по {p:16.10} — продолжить движение по стрелке, чтобы не мешать транспорту сзади в той же полосе, — касается только светофора с дополнительной секцией, как на первом рисунке. На втором рисунке стрелка нанесена на табличке на уровне красного сигнала: она лишь разрешает поворот ({p:16.9}), но не обязывает его выполнять."},"ref":["16.10","16.9","8.7"],"pic":["img/hsc/16.1-12-1.jpg"]},{"id":"h16.1-13","t":"h16.1","num":"16.1.13","q":{"uk":"Що повинен зробити водій чорного автомобіля, який має намір їхати прямо, якщо в дзеркалі заднього виду він побачив транспортний засіб з увімкненим правим поворотом?","ru":"Что должен сделать водитель чёрного автомобиля, который намерен ехать прямо, если в зеркале заднего вида он увидел транспортное средство с включённым правым поворотом?"},"a":[{"uk":"Продовжити рух у наміченому напрямку, тільки коли буде увімкнено зелений сигнал світлофора.","ru":"Продолжить движение в намеченном направлении только тогда, когда будет включён зелёный сигнал светофора.","w":{"uk":"Чекаючи зеленого сигналу, чорний автомобіль створить перешкоду білому автомобілю, що повертає праворуч, а {p:16.10} цього не допускає.","ru":"Ожидая зелёного сигнала, чёрный автомобиль создаст помеху белому автомобилю, поворачивающему направо, а {p:16.10} этого не допускает."}},{"uk":"Продовжувати рух у напрямку, вказаному стрілкою, увімкненою в додатковій секції.","ru":"Продолжать движение в направлении, указанном стрелкой, включённой в дополнительной секции."},{"uk":"Перестроїтися в лівий ряд.","ru":"Перестроиться в левый ряд.","w":{"uk":"Перестроюватися з місця перед стоп-лінією небезпечно й не передбачено: {p:16.10} прямо вимагає продовжити рух у напрямку стрілки.","ru":"Перестраиваться с места перед стоп-линией опасно и не предусмотрено: {p:16.10} прямо требует продолжить движение в направлении стрелки."}}],"c":1,"e":{"uk":"Чорний автомобіль стоїть у правій смузі, з якої виконують поворот праворуч, а в додатковій секції горить стрілка праворуч. Якщо він чекатиме зеленого сигналу, то заблокує білий автомобіль позаду, який повертає праворуч, тож за {p:16.10} повинен продовжити рух у напрямку стрілки.","ru":"Чёрный автомобиль стоит в правой полосе, из которой выполняется поворот направо, а в дополнительной секции горит стрелка направо. Если он будет ждать зелёного сигнала, то заблокирует белый автомобиль сзади, который поворачивает направо, поэтому по {p:16.10} должен продолжить движение в направлении стрелки."},"ref":["16.10","8.7"],"pic":["img/hsc/16.1-13-1.jpg"]},{"id":"h16.1-14","t":"h16.1","num":"16.1.14","q":{"uk":"Чи повинен водій синього автомобіля дати дорогу велосипедистові в даній ситуації?","ru":"Должен ли водитель синего автомобиля уступить дорогу велосипедисту в данной ситуации?"},"a":[{"uk":"Повинен.","ru":"Должен."},{"uk":"Не повинен.","ru":"Не должен.","w":{"uk":"Велосипедист — водій транспортного засобу, що рухається назустріч прямо, тож за {p:16.6} синій автомобіль, повертаючи ліворуч, мусить його пропустити.","ru":"Велосипедист — водитель транспортного средства, движущегося навстречу прямо, поэтому по {p:16.6} синий автомобиль, поворачивая налево, обязан его пропустить."}}],"c":0,"e":{"uk":"Синій автомобіль повертає ліворуч на зелений сигнал, а велосипедист їде назустріч прямо. За {p:16.6} водій, який повертає ліворуч, повинен дати дорогу зустрічним транспортним засобам, що рухаються прямо або праворуч, а велосипед теж є транспортним засобом.","ru":"Синий автомобиль поворачивает налево на зелёный сигнал, а велосипедист едет навстречу прямо. По {p:16.6} водитель, поворачивающий налево, должен уступить дорогу встречным транспортным средствам, движущимся прямо или направо, а велосипед тоже является транспортным средством."},"ref":["16.6"],"pic":["img/hsc/16.1-14-1.jpg"]},{"id":"h16.1-15","t":"h16.1","num":"16.1.15","q":{"uk":"Яка черговість проїзду автомобілів на даному перехресті?","ru":"Какова очерёдность проезда автомобилей на данном перекрёстке?"},"a":[{"uk":"Білий, фіолетовий.","ru":"Белый, фиолетовый.","w":{"uk":"Білий автомобіль повертає ліворуч, тож за {p:16.6} поступається зустрічному фіолетовому, що їде прямо.","ru":"Белый автомобиль поворачивает налево, поэтому по {p:16.6} уступает встречному фиолетовому, едущему прямо."}},{"uk":"Фіолетовий, білий.","ru":"Фиолетовый, белый."}],"c":1,"e":{"uk":"Обом автомобілям горить зелений сигнал; білий повертає ліворуч, а фіолетовий їде назустріч прямо. За {p:16.6} білий повинен дати дорогу зустрічному фіолетовому, тому першим проїжджає фіолетовий.","ru":"Обоим автомобилям горит зелёный сигнал; белый поворачивает налево, а фиолетовый едет навстречу прямо. По {p:16.6} белый должен уступить дорогу встречному фиолетовому, поэтому первым проезжает фиолетовый."},"ref":["16.6"],"pic":["img/hsc/16.1-15-1.jpg"]},{"id":"h16.1-16","t":"h16.1","num":"16.1.16","q":{"uk":"Повертаючи ліворуч на перехресті, водій білого автомобіля повинен:","ru":"Поворачивая налево на перекрёстке, водитель белого автомобиля должен:"},"a":[{"uk":"Дати дорогу тільки сірому автомобілю.","ru":"Уступить дорогу только серому автомобилю.","w":{"uk":"Зелений автомобіль повертає праворуч, а таким зустрічним за {p:16.6} теж треба дати дорогу.","ru":"Зелёный автомобиль поворачивает направо, а таким встречным по {p:16.6} тоже нужно уступить дорогу."}},{"uk":"Дати дорогу тільки зеленому автомобілю.","ru":"Уступить дорогу только зелёному автомобилю.","w":{"uk":"Сірий автомобіль їде прямо, і його {p:16.6} також вимагає пропустити.","ru":"Серый автомобиль едет прямо, и его {p:16.6} также требует пропустить."}},{"uk":"Дати дорогу сірому і зеленому автомобілям.","ru":"Уступить дорогу серому и зелёному автомобилям."}],"c":2,"e":{"uk":"Білий автомобіль повертає ліворуч на зелений сигнал, а назустріч рухаються сірий автомобіль (прямо) і зелений (повертає праворуч). За {p:16.6} він повинен дати дорогу зустрічним транспортним засобам, що рухаються прямо або повертають праворуч, тобто обом.","ru":"Белый автомобиль поворачивает налево на зелёный сигнал, а навстречу движутся серый автомобиль (прямо) и зелёный (поворачивает направо). По {p:16.6} он должен уступить дорогу встречным транспортным средствам, движущимся прямо или поворачивающим направо, то есть обоим."},"ref":["16.6"],"pic":["img/hsc/16.1-16-1.jpg"]},{"id":"h16.1-17","t":"h16.1","num":"16.1.17","q":{"uk":"Як водій білого автомобіля, що наближається до перехрестя, повинен проїхати дане перехрестя?","ru":"Как водитель белого автомобиля, приближающегося к перекрёстку, должен проехать данный перекрёсток?"},"a":[{"uk":"Зупинитися перед розміткою «Стоп-лінія» і далі продовжити рух.","ru":"Остановиться перед разметкой «Стоп-линия» и далее продолжить движение.","w":{"uk":"Знак {s:2.2} — знак пріоритету, а на регульованому перехресті він не діє, тож зупинятися при зеленому сигналі не потрібно.","ru":"Знак {s:2.2} — знак приоритета, а на регулируемом перекрёстке он не действует, поэтому останавливаться при зелёном сигнале не нужно."}},{"uk":"Зупинитися перед розміткою «Стоп-лінія» і, давши дорогу іншим транспортним засобам, продовжити рух.","ru":"Остановиться перед разметкой «Стоп-линия» и, уступив дорогу другим транспортным средствам, продолжить движение.","w":{"uk":"І зупинка, і обов'язок поступитися випливали б лише зі знака {s:2.2}, який при працюючому світлофорі не діє; черговість визначає зелений сигнал.","ru":"И остановка, и обязанность уступить следовали бы лишь из знака {s:2.2}, который при работающем светофоре не действует; очерёдность определяет зелёный сигнал."}},{"uk":"Проїхати перехрестя без зупинки.","ru":"Проехать перекрёсток без остановки."}],"c":2,"e":{"uk":"Над світлофором встановлено знак {s:2.2} «Проїзд без зупинки заборонено», але світлофор працює і горить зелений. Перехрестя регульоване, тому знаки пріоритету на ньому не діють ({p:16.1}, {p:8.3}), і водій проїжджає без зупинки.","ru":"Над светофором установлен знак {s:2.2} «Проезд без остановки запрещён», но светофор работает и горит зелёный. Перекрёсток регулируемый, поэтому знаки приоритета на нём не действуют ({p:16.1}, {p:8.3}), и водитель проезжает без остановки."},"ref":["16.1","8.3"],"pic":["img/hsc/16.1-17-1.jpg"]},{"id":"h16.1-18","t":"h16.1","num":"16.1.18","q":{"uk":"Чи повинен водій автомобіля дати дорогу велосипедисту в даній ситуації?","ru":"Должен ли водитель автомобиля уступить дорогу велосипедисту в данной ситуации?"},"a":[{"uk":"Повинен.","ru":"Должен."},{"uk":"Не повинен, оскільки велосипедист рухається по велосипедній доріжці.","ru":"Не должен, так как велосипедист движется по велосипедной дорожке.","w":{"uk":"Обов'язок пропустити велосипедиста, що їде прямо в попутному напрямку, за {p:16.2} не залежить від того, де він рухається — велосипедною доріжкою чи проїзною частиною.","ru":"Обязанность пропустить велосипедиста, едущего прямо в попутном направлении, по {p:16.2} не зависит от того, где он движется — по велосипедной дорожке или по проезжей части."}},{"uk":"Не повинен, оскільки рухається на сигнал світлофора, що дозволяє рух.","ru":"Не должен, так как он движется на разрешающий движение сигнал светофора.","w":{"uk":"Велосипедисту теж горить зелений сигнал, а {p:16.2} зобов'язує поступатися йому якраз під час руху на дозвільний сигнал.","ru":"Велосипедисту тоже горит зелёный сигнал, а {p:16.2} обязывает уступать ему как раз при движении на разрешающий сигнал."}}],"c":0,"e":{"uk":"Автомобіль повертає праворуч, а велосипедист праворуч від нього їде прямо в попутному напрямку через велосипедний переїзд. За {p:16.2} на будь-якому перехресті водій, повертаючи праворуч чи ліворуч, повинен дати дорогу велосипедистам, що рухаються прямо в попутному напрямку; знаки пріоритету тут не діють ({p:16.1}).","ru":"Автомобиль поворачивает направо, а велосипедист справа от него едет прямо в попутном направлении через велосипедный переезд. По {p:16.2} на любом перекрёстке водитель, поворачивая направо или налево, должен уступить дорогу велосипедистам, движущимся прямо в попутном направлении; знаки приоритета здесь не действуют ({p:16.1})."},"ref":["16.2","16.1"],"pic":["img/hsc/16.1-18-1.jpg"]},{"id":"h16.1-19","t":"h16.1","num":"16.1.19","q":{"uk":"Чи повинен водій автомобіля, повертаючи праворуч на перехресті, дати дорогу велосипедистові, який рухається прямо в попутному напрямку?","ru":"Должен ли водитель автомобиля, поворачивая направо на перекрёстке, уступить дорогу велосипедисту, который движется прямо в попутном направлении?"},"a":[{"uk":"Повинен, якщо велосипедист рухається по велосипедній доріжці.","ru":"Должен, если велосипедист движется по велосипедной дорожке.","w":{"uk":"{p:16.2} не пов'язує обов'язок поступитися з наявністю велосипедної доріжки: велосипедиста, що їде прямо в попутному напрямку, пропускають у будь-якому разі.","ru":"{p:16.2} не связывает обязанность уступить с наличием велосипедной дорожки: велосипедиста, едущего прямо в попутном направлении, пропускают в любом случае."}},{"uk":"Не повинен.","ru":"Не должен.","w":{"uk":"Велосипедист, що рухається прямо в попутному напрямку, за {p:16.2} має перевагу перед транспортом, який повертає.","ru":"Велосипедист, движущийся прямо в попутном направлении, по {p:16.2} имеет преимущество перед поворачивающим транспортом."}},{"uk":"Повинен завжди.","ru":"Должен всегда."}],"c":2,"e":{"uk":"За {p:16.2} на регульованих і нерегульованих перехрестях водій, повертаючи праворуч чи ліворуч, повинен дати дорогу велосипедистам, які рухаються прямо в попутному напрямку, незалежно від того, їдуть вони велосипедною доріжкою чи проїзною частиною.","ru":"По {p:16.2} на регулируемых и нерегулируемых перекрёстках водитель, поворачивая направо или налево, должен уступить дорогу велосипедистам, движущимся прямо в попутном направлении, независимо от того, едут они по велосипедной дорожке или по проезжей части."},"ref":["16.2"],"pic":["img/hsc/16.1-19-1.jpg"]},{"id":"h16.1-20","t":"h16.1","num":"16.1.20","q":{"uk":"Чи повинен водій синього автомобіля дати дорогу пішоходам, повертаючи праворуч або ліворуч на даному перехресті?","ru":"Должен ли водитель синего автомобиля уступить дорогу пешеходам, поворачивая направо или налево на данном перекрёстке?"},"a":[{"uk":"Повинен дати дорогу, повертаючи в будь-якому напрямку.","ru":"Должен уступить дорогу, поворачивая в любом направлении."},{"uk":"Не повинен давати дорогу.","ru":"Не должен уступать дорогу.","w":{"uk":"Пішоходи переходять проїзні частини, на які повертає синій автомобіль, тож {p:16.2} зобов'язує їх пропустити.","ru":"Пешеходы переходят проезжие части, на которые поворачивает синий автомобиль, поэтому {p:16.2} обязывает их пропустить."}},{"uk":"Повинен дати дорогу, тільки повертаючи праворуч.","ru":"Должен уступить дорогу, только поворачивая направо.","w":{"uk":"Ліворуч теж є пішохід на переході через проїзну частину, на яку можна повернути, — йому також треба дати дорогу.","ru":"Слева тоже есть пешеход на переходе через проезжую часть, на которую можно повернуть, — ему также нужно уступить дорогу."}},{"uk":"Повинен дати дорогу, тільки повертаючи ліворуч.","ru":"Должен уступить дорогу, только поворачивая налево.","w":{"uk":"Праворуч пішохід переходить проїзну частину, на яку повертатиме автомобіль, тож і при повороті праворуч обов'язок за {p:16.2} зберігається.","ru":"Справа пешеход переходит проезжую часть, на которую будет поворачивать автомобиль, поэтому и при повороте направо обязанность по {p:16.2} сохраняется."}}],"c":0,"e":{"uk":"Синьому автомобілю горить зелений, а пішоходи переходять і ліву, і праву проїзні частини, на які він може повернути. За {p:16.2} водій, повертаючи праворуч або ліворуч, повинен дати дорогу пішоходам, що переходять проїзну частину, на яку він повертає, тож поступитися доведеться за будь-якого повороту.","ru":"Синему автомобилю горит зелёный, а пешеходы переходят и левую, и правую проезжие части, на которые он может повернуть. По {p:16.2} водитель, поворачивая направо или налево, должен уступить дорогу пешеходам, переходящим проезжую часть, на которую он поворачивает, поэтому уступить придётся при любом повороте."},"ref":["16.2"],"pic":["img/hsc/16.1-20-1.jpg"]},{"id":"h16.1-21","t":"h16.1","num":"16.1.21","q":{"uk":"Чи дозволено водієві червоного автомобіля виїхати на перехрестя на зелений миготливий сигнал світлофора, якщо за перехрестям утворився затор і йому буде потрібно зупинитися на перехресті?","ru":"Разрешено ли водителю красного автомобиля выехать на перекрёсток на зелёный мигающий сигнал светофора, если за перекрёстком образовался затор и ему придётся остановиться на перекрёстке?"},"a":[{"uk":"Виїжджати на перехрестя заборонено.","ru":"Выезжать на перекрёсток запрещено."},{"uk":"Виїжджати на перехрестя дозволено, оскільки зелений миготливий сигнал світлофора не забороняє рух.","ru":"Выезжать на перекрёсток разрешено, так как зелёный мигающий сигнал светофора не запрещает движение.","w":{"uk":"Зелений миготливий сигнал справді дозволяє рух, але {p:16.4} забороняє виїзд на перехрестя при заторі навіть за дозвільного сигналу.","ru":"Зелёный мигающий сигнал действительно разрешает движение, но {p:16.4} запрещает выезд на перекрёсток при заторе даже при разрешающем сигнале."}}],"c":0,"e":{"uk":"За перехрестям стоїть колона автомобілів, тож червоний автомобіль буде змушений зупинитися на перехресті й заважатиме транспорту, якому ввімкнеться зелений. {p:16.4} забороняє виїжджати на будь-яке перехрестя при такому заторі, навіть на дозвільний сигнал світлофора.","ru":"За перекрёстком стоит колонна автомобилей, поэтому красный автомобиль будет вынужден остановиться на перекрёстке и будет мешать транспорту, которому включится зелёный. {p:16.4} запрещает выезжать на любой перекрёсток при таком заторе, даже на разрешающий сигнал светофора."},"ref":["16.4"],"pic":["img/hsc/16.1-21-1.jpg"]},{"id":"h16.1-22","t":"h16.1","num":"16.1.22","q":{"uk":"Як зобов'язаний вчинити водій чорного автомобіля, для якого ввімкнувся зелений сигнал світлофора?","ru":"Как обязан поступить водитель чёрного автомобиля, для которого включился зелёный сигнал светофора?"},"a":[{"uk":"Дати дорогу тільки фіолетовому автомобілю, що завершує рух через перехрестя.","ru":"Уступить дорогу только фиолетовому автомобилю, завершающему движение через перекрёсток.","w":{"uk":"{p:16.5} вимагає пропустити також пішохода, який закінчує перехід, а не лише автомобіль.","ru":"{p:16.5} требует пропустить также пешехода, заканчивающего переход, а не только автомобиль."}},{"uk":"Дати дорогу тільки пішоходу, що завершує рух через проїзну частину.","ru":"Уступить дорогу только пешеходу, завершающему движение через проезжую часть.","w":{"uk":"Фіолетовий автомобіль завершує рух через перехрестя, і за {p:16.5} йому теж треба дати дорогу.","ru":"Фиолетовый автомобиль завершает движение через перекрёсток, и по {p:16.5} ему тоже нужно уступить дорогу."}},{"uk":"Дати дорогу фіолетовому автомобілю і пішоходу, що завершують рух через перехрестя.","ru":"Уступить дорогу фиолетовому автомобилю и пешеходу, завершающим движение через перекрёсток."}],"c":2,"e":{"uk":"Після ввімкнення зеленого сигналу на перехресті ще перебувають фіолетовий автомобіль, що завершує поворот, і пішохід, що закінчує перехід. За {p:16.5} водій зобов'язаний дати дорогу і транспортним засобам, що завершують рух через перехрестя, і пішоходам, які закінчують перехід.","ru":"После включения зелёного сигнала на перекрёстке ещё находятся фиолетовый автомобиль, завершающий поворот, и пешеход, заканчивающий переход. По {p:16.5} водитель обязан уступить дорогу и транспортным средствам, завершающим движение через перекрёсток, и пешеходам, заканчивающим переход."},"ref":["16.5","18.2"],"pic":["img/hsc/16.1-22-1.jpg"]},{"id":"h16.1-23","t":"h16.1","num":"16.1.23","q":{"uk":"Як повинен вчинити водій автомобіля в даній ситуації, коли йому ввімкнувся сигнал світлофора, що дозволяє рух?","ru":"Как должен поступить водитель автомобиля в данной ситуации, когда ему включился разрешающий движение сигнал светофора?"},"a":[{"uk":"Посигналити пішоходу і розпочати рух, змусивши пішохода повернутися на середину проїзної частини.","ru":"Посигналить пешеходу и начать движение, вынудив пешехода вернуться на середину проезжей части.","w":{"uk":"Змушувати пішохода повертатися не можна — йому треба дати закінчити перехід ({p:18.2}); до того ж звуковий сигнал у населеному пункті дозволено лише для запобігання ДТП ({p:9.5}).","ru":"Вынуждать пешехода возвращаться нельзя — ему нужно дать закончить переход ({p:18.2}); к тому же звуковой сигнал в населённом пункте разрешён только для предотвращения ДТП ({p:9.5})."}},{"uk":"Розпочати рух, безпечно об'їхавши пішохода.","ru":"Начать движение, безопасно объехав пешехода.","w":{"uk":"Об'їжджати пішохода, який закінчує перехід, не можна: {p:18.2} вимагає дати йому дорогу, а не маневрувати навколо нього.","ru":"Объезжать пешехода, заканчивающего переход, нельзя: {p:18.2} требует уступить ему дорогу, а не маневрировать вокруг него."}},{"uk":"Дати дорогу пішоходу, щоб він мав можливість закінчити перехід.","ru":"Уступить дорогу пешеходу, чтобы он имел возможность закончить переход."}],"c":2,"e":{"uk":"Пішохід уже на переході й закінчує його, хоча для нього ввімкнувся червоний сигнал. За {p:18.2} (і {p:16.5} на перехрестях) водій, рушаючи на дозвільний сигнал, повинен дати дорогу пішоходам, які закінчують перехід проїзної частини.","ru":"Пешеход уже на переходе и заканчивает его, хотя для него включился красный сигнал. По {p:18.2} (и {p:16.5} на перекрёстках) водитель, трогаясь на разрешающий сигнал, должен уступить дорогу пешеходам, заканчивающим переход проезжей части."},"ref":["18.2","16.5"],"pic":["img/hsc/16.1-23-1.jpg"]},{"id":"h16.1-24","t":"h16.1","num":"16.1.24","q":{"uk":"Як повинен вчинити водій синього автомобіля у разі ввімкнення зеленого сигналу світлофора?","ru":"Как должен поступить водитель синего автомобиля при включении зелёного сигнала светофора?"},"a":[{"uk":"Розпочати рух, не даючи дорогу зеленому автомобілю.","ru":"Начать движение, не уступая дорогу зелёному автомобилю.","w":{"uk":"Зелений сигнал не дає права рушати раніше за транспорт, що завершує рух через перехрестя: {p:16.5} вимагає його пропустити.","ru":"Зелёный сигнал не даёт права трогаться раньше транспорта, завершающего движение через перекрёсток: {p:16.5} требует его пропустить."}},{"uk":"Дати дорогу зеленому автомобілю, що завершує рух через перехрестя.","ru":"Уступить дорогу зелёному автомобилю, завершающему движение через перекрёсток."}],"c":1,"e":{"uk":"Зелений автомобіль ще перебуває на перехресті й завершує поворот ліворуч. За {p:16.5} у разі ввімкнення дозвільного сигналу водій зобов'язаний дати дорогу транспортним засобам, що завершують рух через перехрестя.","ru":"Зелёный автомобиль ещё находится на перекрёстке и завершает поворот налево. По {p:16.5} при включении разрешающего сигнала водитель обязан уступить дорогу транспортным средствам, завершающим движение через перекрёсток."},"ref":["16.5"],"pic":["img/hsc/16.1-24-1.jpg"]},{"id":"h16.1-25","t":"h16.1","num":"16.1.25","q":{"uk":"Хто проїде дане перехрестя першим?","ru":"Кто проедет данный перекрёсток первым?"},"a":[{"uk":"Червоний автомобіль.","ru":"Красный автомобиль.","w":{"uk":"Знак {s:2.3} на регульованому перехресті не діє, а повертаючи ліворуч, червоний автомобіль за {p:16.6} поступається зустрічним білому й синьому.","ru":"Знак {s:2.3} на регулируемом перекрёстке не действует, а поворачивая налево, красный автомобиль по {p:16.6} уступает встречным белому и синему."}},{"uk":"Білий і синій автомобілі.","ru":"Белый и синий автомобили."}],"c":1,"e":{"uk":"Хоча для червоного автомобіля встановлено знак {s:2.3}, а для білого й синього — {s:2.1}, світлофор працює, тож знаки пріоритету не діють ({p:16.1}, {p:8.3}). Усім горить зелений, червоний повертає ліворуч і за {p:16.6} має дати дорогу зустрічним: білому, що їде прямо, і синьому, що повертає праворуч.","ru":"Хотя для красного автомобиля установлен знак {s:2.3}, а для белого и синего — {s:2.1}, светофор работает, поэтому знаки приоритета не действуют ({p:16.1}, {p:8.3}). Всем горит зелёный, красный поворачивает налево и по {p:16.6} должен уступить дорогу встречным: белому, едущему прямо, и синему, поворачивающему направо."},"ref":["16.6","16.1","8.3"],"pic":["img/hsc/16.1-25-1.jpg"]},{"id":"h16.1-26","t":"h16.1","num":"16.1.26","q":{"uk":"Як Ви повинні вчинити, повертаючи ліворуч у даній ситуації?","ru":"Как Вы должны поступить, поворачивая налево в данной ситуации?"},"a":[{"uk":"Проїхати першим.","ru":"Проехать первым.","w":{"uk":"Знак головної дороги на регульованому перехресті переваги не дає, а той, хто повертає ліворуч, поступається зустрічним ({p:16.6}).","ru":"Знак главной дороги на регулируемом перекрёстке преимущества не даёт, а поворачивающий налево уступает встречным ({p:16.6})."}},{"uk":"Дати дорогу зустрічному автомобілю.","ru":"Уступить дорогу встречному автомобилю."}],"c":1,"e":{"uk":"Над світлофором встановлено знак {s:2.3} з табличкою, але при працюючому світлофорі знаки пріоритету не діють ({p:16.1}). Повертаючи ліворуч на зелений сигнал, Ви за {p:16.6} повинні дати дорогу зустрічному автомобілю, що їде прямо.","ru":"Над светофором установлен знак {s:2.3} с табличкой, но при работающем светофоре знаки приоритета не действуют ({p:16.1}). Поворачивая налево на зелёный сигнал, Вы по {p:16.6} должны уступить дорогу встречному автомобилю, едущему прямо."},"ref":["16.6","16.1"],"pic":["img/hsc/16.1-26-1.jpg"]},{"id":"h16.1-27","t":"h16.1","num":"16.1.27","q":{"uk":"Як Ви повинні вчинити в даній ситуації, рухаючись прямо?","ru":"Как Вы должны поступить в данной ситуации, двигаясь прямо?"},"a":[{"uk":"Дати дорогу зустрічному автомобілю і після цього проїхати перехрестя.","ru":"Уступить дорогу встречному автомобилю и после этого проехать перекрёсток.","w":{"uk":"Знак {s:2.1} на регульованому перехресті не діє, а зустрічний автомобіль, що повертає ліворуч, сам поступається Вам за {p:16.6}.","ru":"Знак {s:2.1} на регулируемом перекрёстке не действует, а встречный автомобиль, поворачивающий налево, сам уступает Вам по {p:16.6}."}},{"uk":"Проїхати перехрестя першим.","ru":"Проехать перекрёсток первым."}],"c":1,"e":{"uk":"Знак {s:2.1} над працюючим світлофором не діє ({p:16.1}), черговість визначає зелений сигнал. Ви їдете прямо, а зустрічний автомобіль повертає ліворуч, тож за {p:16.6} він повинен дати дорогу Вам.","ru":"Знак {s:2.1} над работающим светофором не действует ({p:16.1}), очерёдность определяет зелёный сигнал. Вы едете прямо, а встречный автомобиль поворачивает налево, поэтому по {p:16.6} он должен уступить дорогу Вам."},"ref":["16.6","16.1"],"pic":["img/hsc/16.1-27-1.jpg"]},{"id":"h16.1-28","t":"h16.1","num":"16.1.28","q":{"uk":"За яких умов водієві заборонено виїжджати на перехрестя?","ru":"При каких условиях водителю запрещено выезжать на перекрёсток?"},"a":[{"uk":"Якщо транспортний засіб, що їде попереду, рухається зі швидкістю менше ніж 30 км/год.","ru":"Если транспортное средство, едущее впереди, движется со скоростью менее 30 км/ч.","w":{"uk":"Повільний рух попереду сам по собі не забороняє виїзд на перехрестя — важливо лише, чи не доведеться на ньому зупинитися.","ru":"Медленное движение впереди само по себе не запрещает выезд на перекрёсток — важно лишь, не придётся ли на нём остановиться."}},{"uk":"Якщо наближається транспортний засіб з оранжевим проблисковим маячком.","ru":"Если приближается транспортное средство с оранжевым проблесковым маячком.","w":{"uk":"Оранжевий проблисковий маячок за {p:3.6} не дає переваги в русі, а лише привертає увагу й попереджає про небезпеку.","ru":"Оранжевый проблесковый маячок по {p:3.6} не даёт преимущества в движении, а лишь привлекает внимание и предупреждает об опасности."}},{"uk":"Якщо за перехрестям утворився затор, який змусить водія зупинитися на перехресті, і це створить перешкоду для руху інших транспортних засобів і пішоходів.","ru":"Если за перекрёстком образовался затор, который вынудит водителя остановиться на перекрёстке, и это создаст помеху для движения других транспортных средств и пешеходов."},{"uk":"Відповіді 2 і 3.","ru":"Ответы 2 и 3.","w":{"uk":"Варіант 2 неправильний: оранжевий маячок переваги в русі не дає ({p:3.6}).","ru":"Вариант 2 неверен: оранжевый маячок преимущества в движении не даёт ({p:3.6})."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3.","w":{"uk":"Варіанти 1 і 2 неправильні: ні повільний рух попереду, ні оранжевий маячок не забороняють виїзд на перехрестя.","ru":"Варианты 1 и 2 неверны: ни медленное движение впереди, ни оранжевый маячок не запрещают выезд на перекрёсток."}}],"c":2,"e":{"uk":"{p:16.4} забороняє виїжджати на будь-яке перехрестя, навіть на дозвільний сигнал світлофора, якщо через затор водій буде змушений зупинитися на перехресті й створить перешкоду іншим транспортним засобам і пішоходам.","ru":"{p:16.4} запрещает выезжать на любой перекрёсток, даже на разрешающий сигнал светофора, если из-за затора водитель будет вынужден остановиться на перекрёстке и создаст помеху другим транспортным средствам и пешеходам."},"ref":["16.4"]},{"id":"h16.1-29","t":"h16.1","num":"16.1.29","q":{"uk":"Як повинен вчинити водій у разі ввімкнення сигналу світлофора, що дозволяє рух?","ru":"Как должен поступить водитель при включении разрешающего движение сигнала светофора?"},"a":[{"uk":"Відразу розпочати рух, керуючись сигналом світлофора, що дозволяє рух.","ru":"Сразу начать движение, руководствуясь разрешающим движение сигналом светофора.","w":{"uk":"Дозвільний сигнал не скасовує обов'язку спершу пропустити тих, хто завершує рух через перехрестя ({p:16.5}).","ru":"Разрешающий сигнал не отменяет обязанности сначала пропустить тех, кто завершает движение через перекрёсток ({p:16.5})."}},{"uk":"Дати дорогу лише транспортним засобам, що завершують рух через перехрестя.","ru":"Уступить дорогу только транспортным средствам, завершающим движение через перекрёсток.","w":{"uk":"{p:16.5} вимагає пропустити також пішоходів, які закінчують перехід.","ru":"{p:16.5} требует пропустить также пешеходов, заканчивающих переход."}},{"uk":"Дати дорогу тільки пішоходам, що завершують рух через перехрестя.","ru":"Уступить дорогу только пешеходам, завершающим движение через перекрёсток.","w":{"uk":"{p:16.5} вимагає пропустити також транспортні засоби, що завершують рух через перехрестя.","ru":"{p:16.5} требует пропустить также транспортные средства, завершающие движение через перекрёсток."}},{"uk":"Дати дорогу всім транспортним засобам і пішоходам, що завершують рух через перехрестя.","ru":"Уступить дорогу всем транспортным средствам и пешеходам, завершающим движение через перекрёсток."}],"c":3,"e":{"uk":"За {p:16.5} у разі ввімкнення дозвільного сигналу світлофора водій зобов'язаний дати дорогу і транспортним засобам, що завершують рух через перехрестя, і пішоходам, які закінчують перехід.","ru":"По {p:16.5} при включении разрешающего сигнала светофора водитель обязан уступить дорогу и транспортным средствам, завершающим движение через перекрёсток, и пешеходам, заканчивающим переход."},"ref":["16.5"]},{"id":"h16.1-30","t":"h16.1","num":"16.1.30","q":{"uk":"Якому транспортному засобу надається перевага в русі, якщо сигнал регулювальника або зелений сигнал світлофора дозволяє одночасно рух трамвая і нерейкових транспортних засобів?","ru":"Какому транспортному средству предоставляется преимущество в движении, если сигнал регулировщика или зелёный сигнал светофора разрешает одновременно движение трамвая и нерельсовых транспортных средств?"},"a":[{"uk":"Трамваю.","ru":"Трамваю."},{"uk":"Нерейковим транспортним засобам.","ru":"Нерельсовым транспортным средствам.","w":{"uk":"{p:16.7} прямо надає перевагу трамваю, а не нерейковим транспортним засобам.","ru":"{p:16.7} прямо предоставляет преимущество трамваю, а не нерельсовым транспортным средствам."}}],"c":0,"e":{"uk":"За {p:16.7} у такому разі трамваю надається перевага незалежно від напрямку його руху.","ru":"По {p:16.7} в таком случае трамваю предоставляется преимущество независимо от направления его движения."},"ref":["16.7"]},{"id":"h16.1-31","t":"h16.1","num":"16.1.31","q":{"uk":"Яке перехрестя вважається регульованим?","ru":"Какой перекрёсток считается регулируемым?"},"a":[{"uk":"Перехрестя, де черговість проїзду регулюється тільки дорожніми знаками.","ru":"Перекрёсток, где очерёдность проезда регулируется только дорожными знаками.","w":{"uk":"Перехрестя, де черговість визначають лише знаки пріоритету, є нерегульованим.","ru":"Перекрёсток, где очерёдность определяют только знаки приоритета, является нерегулируемым."}},{"uk":"Перехрестя, де черговість проїзду регулюється тільки сигналами світлофора.","ru":"Перекрёсток, где очерёдность проезда регулируется только сигналами светофора.","w":{"uk":"Регульованим є й перехрестя, де рухом керує регулювальник, тож «тільки світлофор» — неповне визначення.","ru":"Регулируемым является и перекрёсток, где движением управляет регулировщик, поэтому «только светофор» — неполное определение."}},{"uk":"Перехрестя, де черговість проїзду регулюється тільки сигналами регулювальника.","ru":"Перекрёсток, где очерёдность проезда регулируется только сигналами регулировщика.","w":{"uk":"Регульованим є й перехрестя з працюючим світлофором без регулювальника, тож «тільки регулювальник» — неповне визначення.","ru":"Регулируемым является и перекрёсток с работающим светофором без регулировщика, поэтому «только регулировщик» — неполное определение."}},{"uk":"Перехрестя, де черговість проїзду регулюється дорожніми знаками, сигналами світлофора або сигналами регулювальника.","ru":"Перекрёсток, где очерёдность проезда регулируется дорожными знаками, сигналами светофора или сигналами регулировщика.","w":{"uk":"Дорожні знаки не роблять перехрестя регульованим; за {p:16.1} на регульованому перехресті знаки пріоритету навіть не діють.","ru":"Дорожные знаки не делают перекрёсток регулируемым; по {p:16.1} на регулируемом перекрёстке знаки приоритета даже не действуют."}},{"uk":"Перехрестя, де черговість проїзду регулюється сигналами світлофора або регулювальника.","ru":"Перекрёсток, где очерёдность проезда регулируется сигналами светофора или регулировщика."}],"c":4,"e":{"uk":"За {p:16.1} регульованим вважається перехрестя, де черговість проїзду визначається сигналами світлофора чи регулювальника; знаки пріоритету на ньому не діють.","ru":"По {p:16.1} регулируемым считается перекрёсток, где очерёдность проезда определяется сигналами светофора или регулировщика; знаки приоритета на нём не действуют."},"ref":["16.1"]},{"id":"h16.1-32","t":"h16.1","num":"16.1.32","q":{"uk":"Ви плануєте проїхати прямо на перехресті, при цьому сигнал регулювальника дозволяє Вам рух прямо, а сигнал світлофора забороняє. Ви:","ru":"Вы планируете проехать прямо на перекрёстке, при этом сигнал регулировщика разрешает Вам движение прямо, а сигнал светофора запрещает. Вы:"},"a":[{"uk":"Проїдете прямо.","ru":"Проедете прямо."},{"uk":"Зупинитесь і зачекаєте сигналу світлофора, що дозволяє рух.","ru":"Остановитесь и подождёте разрешающего движение сигнала светофора.","w":{"uk":"Коли рухом керує регулювальник, сигнали світлофора поступаються його сигналам ({p:8.3}), тож чекати зеленого не потрібно.","ru":"Когда движением управляет регулировщик, сигналы светофора уступают его сигналам ({p:8.3}), поэтому ждать зелёного не нужно."}}],"c":0,"e":{"uk":"За {p:8.3} сигнали регулювальника мають перевагу перед сигналами світлофорів і є обов'язковими для виконання, тож Ви проїжджаєте прямо за сигналом регулювальника.","ru":"По {p:8.3} сигналы регулировщика имеют преимущество перед сигналами светофоров и являются обязательными для выполнения, поэтому Вы проезжаете прямо по сигналу регулировщика."},"ref":["8.3"]},{"id":"h16.1-33","t":"h16.1","num":"16.1.33","q":{"uk":"Під’їжджаючи до перехрестя, де крім працюючого світлофора ви бачите регулювальника, сигнали якого відрізняються від сигналів світлофора. Ви будете керуватись:","ru":"Подъезжая к перекрёстку, где кроме работающего светофора Вы видите регулировщика, сигналы которого отличаются от сигналов светофора, Вы будете руководствоваться:"},"a":[{"uk":"Сигналом регулювальника.","ru":"Сигналом регулировщика."},{"uk":"Сигналом світлофора.","ru":"Сигналом светофора.","w":{"uk":"Сигнал світлофора поступається сигналу регулювальника ({p:8.3}), тож за розбіжності виконують вказівку регулювальника.","ru":"Сигнал светофора уступает сигналу регулировщика ({p:8.3}), поэтому при расхождении выполняют указание регулировщика."}}],"c":0,"e":{"uk":"За {p:8.3} сигнали регулювальника мають перевагу перед сигналами світлофорів і вимогами дорожніх знаків, тож за розбіжності керуються саме ними.","ru":"По {p:8.3} сигналы регулировщика имеют преимущество перед сигналами светофоров и требованиями дорожных знаков, поэтому при расхождении руководствуются именно ими."},"ref":["8.3"]},{"id":"h16.1-34","t":"h16.1","num":"16.1.34","q":{"uk":"Чи дозволено водію чорного автомобіля повернути праворуч у даному випадку?","ru":"Разрешено ли водителю чёрного автомобиля повернуть направо в данном случае?"},"a":[{"uk":"Дозволено.","ru":"Разрешено."},{"uk":"Заборонено.","ru":"Запрещено.","w":{"uk":"Табличка зі стрілкою не забороняє поворот, а лише додатково дозволяє його при червоному сигналі; зараз же горить зелений, який дозволяє рух.","ru":"Табличка со стрелкой не запрещает поворот, а лишь дополнительно разрешает его при красном сигнале; сейчас же горит зелёный, разрешающий движение."}}],"c":0,"e":{"uk":"На світлофорі горить основний зелений сигнал, який дозволяє рух ({p:8.7}), тож повернути праворуч можна. Табличка із зеленою стрілкою на рівні червоного сигналу має значення лише тоді, коли горить червоний, і рух на зелений не обмежує.","ru":"На светофоре горит основной зелёный сигнал, разрешающий движение ({p:8.7}), поэтому повернуть направо можно. Табличка с зелёной стрелкой на уровне красного сигнала имеет значение только тогда, когда горит красный, и движение на зелёный не ограничивает."},"ref":["8.7"],"pic":["img/hsc/16.1-34-1.jpg"]},{"id":"h16.2-1","t":"h16.2","num":"16.2.1","q":{"uk":"Проїжджаючи дане перехрестя, Ви повинні:","ru":"Проезжая данный перекрёсток, Вы должны:"},"a":[{"uk":"Дати дорогу тільки червоному і сірому автомобілям.","ru":"Уступить дорогу только красному и серому автомобилям."},{"uk":"Дати дорогу всім транспортним засобам.","ru":"Уступить дорогу всем транспортным средствам.","w":{"uk":"Білий автомобіль ліворуч, як і Ви, рухається другорядною дорогою; між собою ви роз'їжджаєтеся як на рівнозначних дорогах, тож поступається він Вам.","ru":"Белый автомобиль слева, как и Вы, движется по второстепенной дороге; между собой вы разъезжаетесь как на равнозначных дорогах, поэтому уступает он Вам."}},{"uk":"Дати дорогу тільки сірому автомобілю.","ru":"Уступить дорогу только серому автомобилю.","w":{"uk":"Червоний автомобіль теж рухається головною дорогою (вона йде прямо перед Вами і праворуч), тому йому також потрібно дати дорогу.","ru":"Красный автомобиль тоже движется по главной дороге (она идёт прямо перед Вами и направо), поэтому ему также нужно уступить дорогу."}}],"c":0,"e":{"uk":"Знак {s:2.1} з табличкою {s:7.8} показує, що головна дорога йде з зустрічного напрямку праворуч, а Ви на другорядній, тому за {p:16.11} поступаєтеся червоному (зустрічному) і сірому (праворуч) автомобілям. Білий автомобіль ліворуч теж їде другорядною дорогою, і за {p:16.14} він сам має дати дорогу Вам, бо Ви для нього праворуч.","ru":"Знак {s:2.1} с табличкой {s:7.8} показывает, что главная дорога идёт со встречного направления направо, а Вы на второстепенной, поэтому по {p:16.11} уступаете красному (встречному) и серому (справа) автомобилям. Белый автомобиль слева тоже едет по второстепенной дороге, и по {p:16.14} он сам должен уступить дорогу Вам, так как Вы для него справа."},"ref":["16.11","16.14","33.2","33.7"],"pic":["img/hsc/16.2-1-1.jpg"]},{"id":"h16.2-2","t":"h16.2","num":"16.2.2","q":{"uk":"Ви повинні проїхати дане перехрестя:","ru":"Вы должны проехать данный перекрёсток:"},"a":[{"uk":"Першим.","ru":"Первым."},{"uk":"Давши дорогу синьому автомобілю.","ru":"Уступив дорогу синему автомобилю.","w":{"uk":"На перехресті рівнозначних доріг дають дорогу тим, хто праворуч; синій автомобіль ліворуч, тому поступається він, а не Ви.","ru":"На перекрёстке равнозначных дорог уступают тем, кто справа; синий автомобиль слева, поэтому уступает он, а не Вы."}}],"c":0,"e":{"uk":"Знаків пріоритету немає, дороги рівнозначні, а синій автомобіль наближається ліворуч — за {p:16.12} саме він має дати дорогу Вам, тож Ви проїжджаєте першим.","ru":"Знаков приоритета нет, дороги равнозначные, а синий автомобиль приближается слева — по {p:16.12} именно он должен уступить дорогу Вам, поэтому Вы проезжаете первым."},"ref":["16.12"],"pic":["img/hsc/16.2-2-1.jpg"]},{"id":"h16.2-3","t":"h16.2","num":"16.2.3","q":{"uk":"Проїжджаючи дане перехрестя, Ви повинні:","ru":"Проезжая данный перекрёсток, Вы должны:"},"a":[{"uk":"Проїхати перехрестя першим.","ru":"Проехать перекрёсток первым.","w":{"uk":"Першим Ви могли б проїхати лише тоді, якби праворуч нікого не було; червоний автомобіль праворуч має перевагу.","ru":"Первым Вы могли бы проехать, только если бы справа никого не было; красный автомобиль справа имеет преимущество."}},{"uk":"Дати дорогу червоному автомобілю.","ru":"Уступить дорогу красному автомобилю."}],"c":1,"e":{"uk":"Знаків пріоритету немає, отже дороги рівнозначні, а червоний автомобіль наближається праворуч — за {p:16.12} Ви повинні дати йому дорогу.","ru":"Знаков приоритета нет, значит, дороги равнозначные, а красный автомобиль приближается справа — по {p:16.12} Вы должны уступить ему дорогу."},"ref":["16.12"],"pic":["img/hsc/16.2-3-1.jpg"]},{"id":"h16.2-4","t":"h16.2","num":"16.2.4","q":{"uk":"Яка черговість проїзду транспортних засобів на даному перехресті?","ru":"Какова очерёдность проезда транспортных средств на данном перекрёстке?"},"a":[{"uk":"Ви, а потім білий автомобіль.","ru":"Вы, а затем белый автомобиль.","w":{"uk":"Білий автомобіль для Вас праворуч, тож перевага в нього, а не у Вас.","ru":"Белый автомобиль для Вас справа, поэтому преимущество у него, а не у Вас."}},{"uk":"Білий автомобіль, а потім Ви.","ru":"Белый автомобиль, а затем Вы."}],"c":1,"e":{"uk":"Перехрестя рівнозначних доріг без знаків пріоритету, білий автомобіль наближається праворуч, тому за {p:16.12} він проїжджає першим, а Ви — після нього.","ru":"Перекрёсток равнозначных дорог без знаков приоритета, белый автомобиль приближается справа, поэтому по {p:16.12} он проезжает первым, а Вы — после него."},"ref":["16.12"],"pic":["img/hsc/16.2-4-1.jpg"]},{"id":"h16.2-5","t":"h16.2","num":"16.2.5","q":{"uk":"Проїжджаючи дане перехрестя, Ви повинні:","ru":"Проезжая данный перекрёсток, Вы должны:"},"a":[{"uk":"Проїхати перехрестя першим.","ru":"Проехать перекрёсток первым."},{"uk":"Дати дорогу синьому автомобілю.","ru":"Уступить дорогу синему автомобилю.","w":{"uk":"Поступатися треба транспорту праворуч, а синій автомобіль ліворуч — це він має пропустити Вас.","ru":"Уступать нужно транспорту справа, а синий автомобиль слева — это он должен пропустить Вас."}}],"c":0,"e":{"uk":"Дороги рівнозначні, синій автомобіль наближається ліворуч, тож за {p:16.12} він повинен дати дорогу Вам, і Ви проїжджаєте першим.","ru":"Дороги равнозначные, синий автомобиль приближается слева, поэтому по {p:16.12} он должен уступить дорогу Вам, и Вы проезжаете первым."},"ref":["16.12"],"pic":["img/hsc/16.2-5-1.jpg"]},{"id":"h16.2-6","t":"h16.2","num":"16.2.6","q":{"uk":"Яка черговість проїзду транспортних засобів на даному перехресті?","ru":"Какова очерёдность проезда транспортных средств на данном перекрёстке?"},"a":[{"uk":"Зелений автомобіль, а потім Ви.","ru":"Зелёный автомобиль, а затем Вы."},{"uk":"Ви, а потім зелений автомобіль.","ru":"Вы, а затем зелёный автомобиль.","w":{"uk":"Зелений автомобіль для Вас праворуч, тому на рівнозначних дорогах перевагу має він, незалежно від напрямку свого подальшого руху.","ru":"Зелёный автомобиль для Вас справа, поэтому на равнозначных дорогах преимущество у него, независимо от направления его дальнейшего движения."}}],"c":0,"e":{"uk":"Знаків пріоритету немає, дороги рівнозначні, а зелений автомобіль наближається праворуч, тому за {p:16.12} він проїжджає першим, а Ви — після нього.","ru":"Знаков приоритета нет, дороги равнозначные, а зелёный автомобиль приближается справа, поэтому по {p:16.12} он проезжает первым, а Вы — после него."},"ref":["16.12"],"pic":["img/hsc/16.2-6-1.jpg"]},{"id":"h16.2-7","t":"h16.2","num":"16.2.7","q":{"uk":"Проїжджаючи дане перехрестя, Ви повинні:","ru":"Проезжая данный перекрёсток, Вы должны:"},"a":[{"uk":"Проїхати перехрестя першим.","ru":"Проехать перекрёсток первым."},{"uk":"Дати дорогу жовтому автомобілю.","ru":"Уступить дорогу жёлтому автомобилю.","w":{"uk":"Жовтий автомобіль ліворуч, тому на рівнозначних дорогах він поступається Вам, а не навпаки.","ru":"Жёлтый автомобиль слева, поэтому на равнозначных дорогах он уступает Вам, а не наоборот."}}],"c":0,"e":{"uk":"Ви повертаєте праворуч на перехресті рівнозначних доріг, а жовтий автомобіль наближається ліворуч — за {p:16.12} він має дати дорогу Вам, тож Ви проїжджаєте першим.","ru":"Вы поворачиваете направо на перекрёстке равнозначных дорог, а жёлтый автомобиль приближается слева — по {p:16.12} он должен уступить дорогу Вам, поэтому Вы проезжаете первым."},"ref":["16.12"],"pic":["img/hsc/16.2-7-1.jpg"]},{"id":"h16.2-8","t":"h16.2","num":"16.2.8","q":{"uk":"Проїжджаючи дане перехрестя, Ви повинні:","ru":"Проезжая данный перекрёсток, Вы должны:"},"a":[{"uk":"Проїхати перехрестя першим.","ru":"Проехать перекрёсток первым.","w":{"uk":"Білий автомобіль праворуч має перевагу, тому проїхати першим Ви не можете.","ru":"Белый автомобиль справа имеет преимущество, поэтому проехать первым Вы не можете."}},{"uk":"Дати дорогу білому автомобілю.","ru":"Уступить дорогу белому автомобилю."}],"c":1,"e":{"uk":"Ви повертаєте ліворуч на перехресті рівнозначних доріг, а білий автомобіль наближається праворуч — за {p:16.12} Ви повинні дати йому дорогу.","ru":"Вы поворачиваете налево на перекрёстке равнозначных дорог, а белый автомобиль приближается справа — по {p:16.12} Вы должны уступить ему дорогу."},"ref":["16.12"],"pic":["img/hsc/16.2-8-1.jpg"]},{"id":"h16.2-9","t":"h16.2","num":"16.2.9","q":{"uk":"Проїжджаючи дане перехрестя, Ви повинні:","ru":"Проезжая данный перекрёсток, Вы должны:"},"a":[{"uk":"Проїхати перехрестя першим.","ru":"Проехать перекрёсток первым."},{"uk":"Дати дорогу сірому автомобілю.","ru":"Уступить дорогу серому автомобилю.","w":{"uk":"Сірий автомобіль ліворуч, тому на рівнозначних дорогах поступається він, а поворот ліворуч не позбавляє Вас переваги перед ним.","ru":"Серый автомобиль слева, поэтому на равнозначных дорогах уступает он, а поворот налево не лишает Вас преимущества перед ним."}}],"c":0,"e":{"uk":"Ви повертаєте ліворуч на перехресті рівнозначних доріг, а сірий автомобіль наближається ліворуч — за {p:16.12} він має дати дорогу Вам, бо Ви для нього праворуч.","ru":"Вы поворачиваете налево на перекрёстке равнозначных дорог, а серый автомобиль приближается слева — по {p:16.12} он должен уступить дорогу Вам, так как Вы для него справа."},"ref":["16.12"],"pic":["img/hsc/16.2-9-1.jpg"]},{"id":"h16.2-10","t":"h16.2","num":"16.2.10","q":{"uk":"Проїжджаючи дане перехрестя, Ви повинні:","ru":"Проезжая данный перекрёсток, Вы должны:"},"a":[{"uk":"Проїхати першим.","ru":"Проехать первым.","w":{"uk":"Фіолетовий автомобіль праворуч має перевагу, тому першим проїжджає він.","ru":"Фиолетовый автомобиль справа имеет преимущество, поэтому первым проезжает он."}},{"uk":"Дати дорогу фіолетовому автомобілю.","ru":"Уступить дорогу фиолетовому автомобилю."}],"c":1,"e":{"uk":"Знаків пріоритету немає, дороги рівнозначні, а фіолетовий автомобіль наближається праворуч — за {p:16.12} Ви повинні дати йому дорогу.","ru":"Знаков приоритета нет, дороги равнозначные, а фиолетовый автомобиль приближается справа — по {p:16.12} Вы должны уступить ему дорогу."},"ref":["16.12"],"pic":["img/hsc/16.2-10-1.jpg"]},{"id":"h16.2-11","t":"h16.2","num":"16.2.11","q":{"uk":"Яка черговість проїзду транспортних засобів на даному перехресті?","ru":"Какова очерёдность проезда транспортных средств на данном перекрёстке?"},"a":[{"uk":"Ви, а потім білий автомобіль.","ru":"Вы, а затем белый автомобиль."},{"uk":"Білий автомобіль, а потім Ви.","ru":"Белый автомобиль, а затем Вы.","w":{"uk":"Білий автомобіль ліворуч, тому на рівнозначних дорогах він поступається Вам.","ru":"Белый автомобиль слева, поэтому на равнозначных дорогах он уступает Вам."}}],"c":0,"e":{"uk":"Ви повертаєте праворуч на перехресті рівнозначних доріг, а білий автомобіль наближається ліворуч — за {p:16.12} він має дати дорогу Вам, тож першим проїжджаєте Ви.","ru":"Вы поворачиваете направо на перекрёстке равнозначных дорог, а белый автомобиль приближается слева — по {p:16.12} он должен уступить дорогу Вам, поэтому первым проезжаете Вы."},"ref":["16.12"],"pic":["img/hsc/16.2-11-1.jpg"]},{"id":"h16.2-12","t":"h16.2","num":"16.2.12","q":{"uk":"Яка черговість проїзду транспортних засобів на даному перехресті?","ru":"Какова очерёдность проезда транспортных средств на данном перекрёстке?"},"a":[{"uk":"Синій автомобіль, а потім Ви.","ru":"Синий автомобиль, а затем Вы."},{"uk":"Ви, а потім синій автомобіль.","ru":"Вы, а затем синий автомобиль.","w":{"uk":"Синій автомобіль для Вас праворуч, тож перевага в нього.","ru":"Синий автомобиль для Вас справа, поэтому преимущество у него."}}],"c":0,"e":{"uk":"Перехрестя рівнозначних доріг без знаків пріоритету, синій автомобіль наближається праворуч, тому за {p:16.12} першим проїжджає він, а Ви — після нього.","ru":"Перекрёсток равнозначных дорог без знаков приоритета, синий автомобиль приближается справа, поэтому по {p:16.12} первым проезжает он, а Вы — после него."},"ref":["16.12"],"pic":["img/hsc/16.2-12-1.jpg"]},{"id":"h16.2-13","t":"h16.2","num":"16.2.13","q":{"uk":"Ви проїдете дане перехрестя:","ru":"Вы проедете данный перекрёсток:"},"a":[{"uk":"Давши дорогу чорному автомобілю.","ru":"Уступив дорогу чёрному автомобилю.","w":{"uk":"Чорний автомобіль ліворуч, тому поступатися йому не потрібно — це він пропускає Вас.","ru":"Чёрный автомобиль слева, поэтому уступать ему не нужно — это он пропускает Вас."}},{"uk":"Першим.","ru":"Первым."}],"c":1,"e":{"uk":"Ви повертаєте праворуч на перехресті рівнозначних доріг, а чорний автомобіль наближається ліворуч — за {p:16.12} він має дати дорогу Вам.","ru":"Вы поворачиваете направо на перекрёстке равнозначных дорог, а чёрный автомобиль приближается слева — по {p:16.12} он должен уступить дорогу Вам."},"ref":["16.12"],"pic":["img/hsc/16.2-13-1.jpg"]},{"id":"h16.2-14","t":"h16.2","num":"16.2.14","q":{"uk":"Яка черговість проїзду транспортних засобів на даному перехресті?","ru":"Какова очерёдность проезда транспортных средств на данном перекрёстке?"},"a":[{"uk":"Сірий автомобіль, а потім Ви.","ru":"Серый автомобиль, а затем Вы.","w":{"uk":"Сірий автомобіль ліворуч, а на рівнозначних дорогах перевагу має той, хто праворуч, тобто Ви.","ru":"Серый автомобиль слева, а на равнозначных дорогах преимущество у того, кто справа, то есть у Вас."}},{"uk":"Ви, а потім сірий автомобіль.","ru":"Вы, а затем серый автомобиль."}],"c":1,"e":{"uk":"Дороги рівнозначні, сірий автомобіль наближається ліворуч, тому за {p:16.12} він поступається Вам: першим проїжджаєте Ви, потім він.","ru":"Дороги равнозначные, серый автомобиль приближается слева, поэтому по {p:16.12} он уступает Вам: первым проезжаете Вы, затем он."},"ref":["16.12"],"pic":["img/hsc/16.2-14-1.jpg"]},{"id":"h16.2-15","t":"h16.2","num":"16.2.15","q":{"uk":"Проїжджаючи дане перехрестя, Ви повинні:","ru":"Проезжая данный перекрёсток, Вы должны:"},"a":[{"uk":"Дати дорогу тільки транспортному засобу з увімкненим проблисковим маячком синього кольору.","ru":"Уступить дорогу только транспортному средству с включённым проблесковым маячком синего цвета.","w":{"uk":"Крім швидкої, головною дорогою рухаються синій і червоний автомобілі, і їм теж треба дати дорогу.","ru":"Кроме скорой, по главной дороге движутся синий и красный автомобили, и им тоже нужно уступить дорогу."}},{"uk":"Дати дорогу тільки транспортному засобу з увімкненим проблисковим маячком синього кольору і червоному автомобілю.","ru":"Уступить дорогу только транспортному средству с включённым проблесковым маячком синего цвета и красному автомобилю.","w":{"uk":"Синій зустрічний автомобіль теж їде головною дорогою (вона йде прямо перед Вами і праворуч), тому його також треба пропустити.","ru":"Синий встречный автомобиль тоже едет по главной дороге (она идёт прямо перед Вами и направо), поэтому его также нужно пропустить."}},{"uk":"Дати дорогу всім транспортним засобам.","ru":"Уступить дорогу всем транспортным средствам."}],"c":2,"e":{"uk":"Знак {s:2.1} з табличкою {s:7.8} показує, що головна дорога йде з зустрічного напрямку праворуч, тому за {p:16.11} Ви поступаєтеся синьому (зустрічному) і червоному (праворуч) автомобілям. Автомобілю швидкої допомоги з увімкненими синім маячком і спеціальним звуковим сигналом за {p:3.2} треба дати дорогу, хоч він і на другорядній дорозі ліворуч.","ru":"Знак {s:2.1} с табличкой {s:7.8} показывает, что главная дорога идёт со встречного направления направо, поэтому по {p:16.11} Вы уступаете синему (встречному) и красному (справа) автомобилям. Автомобилю скорой помощи с включёнными синим маячком и специальным звуковым сигналом по {p:3.2} нужно уступить дорогу, хотя он и на второстепенной дороге слева."},"ref":["3.2","16.11","33.2","33.7"],"pic":["img/hsc/16.2-15-1.jpg"]},{"id":"h16.2-16","t":"h16.2","num":"16.2.16","q":{"uk":"Повертаючи ліворуч на цьому перехресті, Ви повинні:","ru":"Поворачивая налево на этом перекрёстке, Вы должны:"},"a":[{"uk":"Проїхати перехрестя першим.","ru":"Проехать перекрёсток первым."},{"uk":"Дати дорогу тільки білому автомобілю.","ru":"Уступить дорогу только белому автомобилю.","w":{"uk":"Білий автомобіль рухається другорядною дорогою, тому він має пропустити Вас, хоч Ви й повертаєте ліворуч: правило {p:16.13} стосується лише рівнозначних доріг.","ru":"Белый автомобиль движется по второстепенной дороге, поэтому он должен пропустить Вас, хотя Вы и поворачиваете налево: правило {p:16.13} касается только равнозначных дорог."}},{"uk":"Дати дорогу білому і жовтому автомобілям.","ru":"Уступить дорогу белому и жёлтому автомобилям.","w":{"uk":"Білий автомобіль на другорядній дорозі, а жовтий — ліворуч від Вас на головній, яка змінює напрямок; обидва поступаються Вам.","ru":"Белый автомобиль на второстепенной дороге, а жёлтый — слева от Вас на главной, меняющей направление; оба уступают Вам."}}],"c":0,"e":{"uk":"Знак {s:2.3} з табличкою {s:7.8} показує, що головна дорога повертає ліворуч, і Ви рухаєтеся саме нею, тож білий зустрічний автомобіль на другорядній дорозі за {p:16.11} поступається Вам. Жовтий автомобіль ліворуч теж на головній дорозі, але між собою ви за {p:16.14} роз'їжджаєтеся як на рівнозначних дорогах, і Ви для нього праворуч.","ru":"Знак {s:2.3} с табличкой {s:7.8} показывает, что главная дорога поворачивает налево, и Вы движетесь именно по ней, поэтому белый встречный автомобиль на второстепенной дороге по {p:16.11} уступает Вам. Жёлтый автомобиль слева тоже на главной дороге, но между собой вы по {p:16.14} разъезжаетесь как на равнозначных дорогах, и Вы для него справа."},"ref":["16.11","16.14","33.2","33.7"],"pic":["img/hsc/16.2-16-1.jpg"]},{"id":"h16.2-17","t":"h16.2","num":"16.2.17","q":{"uk":"Проїжджаючи дане перехрестя, Ви повинні:","ru":"Проезжая данный перекрёсток, Вы должны:"},"a":[{"uk":"Дати дорогу тільки трамваю.","ru":"Уступить дорогу только трамваю.","w":{"uk":"Синій автомобіль теж рухається головною дорогою і наближається праворуч, тому йому також треба дати дорогу.","ru":"Синий автомобиль тоже движется по главной дороге и приближается справа, поэтому ему также нужно уступить дорогу."}},{"uk":"Проїхати перехрестя першим.","ru":"Проехать перекрёсток первым.","w":{"uk":"Ви їдете прямо, а головна дорога повертає праворуч, тож перевага між вами визначається правилами рівнозначних доріг — і трамвай, і синій автомобіль мають її перед Вами.","ru":"Вы едете прямо, а главная дорога поворачивает направо, поэтому преимущество между вами определяется правилами равнозначных дорог — и трамвай, и синий автомобиль имеют его перед Вами."}},{"uk":"Проїхати перехрестя після трамвая і синього автомобіля.","ru":"Проехать перекрёсток после трамвая и синего автомобиля."}],"c":2,"e":{"uk":"За знаком {s:2.3} з табличкою {s:7.8} головна дорога повертає праворуч, тож між Вами, трамваєм і синім автомобілем, які всі на головній дорозі, діють правила рівнозначних доріг ({p:16.14}). Трамвай має перевагу перед нерейковими транспортними засобами незалежно від напрямку руху, а синій автомобіль наближається праворуч ({p:16.12}), тому Ви проїжджаєте після них обох.","ru":"По знаку {s:2.3} с табличкой {s:7.8} главная дорога поворачивает направо, поэтому между Вами, трамваем и синим автомобилем, которые все на главной дороге, действуют правила равнозначных дорог ({p:16.14}). Трамвай имеет преимущество перед нерельсовыми транспортными средствами независимо от направления движения, а синий автомобиль приближается справа ({p:16.12}), поэтому Вы проезжаете после них обоих."},"ref":["16.12","16.14","33.2","33.7"],"pic":["img/hsc/16.2-17-1.jpg"]},{"id":"h16.2-18","t":"h16.2","num":"16.2.18","q":{"uk":"Яка черговість проїзду транспортних засобів на даному перехресті?","ru":"Какова очерёдность проезда транспортных средств на данном перекрёстке?"},"a":[{"uk":"Трамвай 2 і трамвай 1, червоний, жовтий, синій автомобілі.","ru":"Трамвай 2 и трамвай 1, красный, жёлтый, синий автомобили.","w":{"uk":"Трамвай 1 рухається другорядною дорогою, тому має пропустити транспортні засоби на головній — червоний і жовтий автомобілі.","ru":"Трамвай 1 движется по второстепенной дороге, поэтому должен пропустить транспортные средства на главной — красный и жёлтый автомобили."}},{"uk":"Трамвай 2, жовтий, червоний автомобілі, трамвай 1, синій автомобіль.","ru":"Трамвай 2, жёлтый, красный автомобили, трамвай 1, синий автомобиль.","w":{"uk":"Жовтий автомобіль наближається головною дорогою ліворуч від червоного, тому за {p:16.14} поступається йому, а червоний їде одночасно з трамваєм 2.","ru":"Жёлтый автомобиль приближается по главной дороге слева от красного, поэтому по {p:16.14} уступает ему, а красный едет одновременно с трамваем 2."}},{"uk":"Трамвай 2 одночасно з червоним автомобілем, жовтий автомобіль, трамвай 1, синій автомобіль.","ru":"Трамвай 2 одновременно с красным автомобилем, жёлтый автомобиль, трамвай 1, синий автомобиль."}],"c":2,"e":{"uk":"Головна дорога (знак {s:2.3} з табличкою {s:7.8}) йде знизу ліворуч, тож спершу рухаються трамвай 2, червоний і жовтий; між собою вони за {p:16.14} керуються правилами рівнозначних доріг, і жовтий поступається трамваю 2 та червоному, які для нього праворуч, а ті їдуть одночасно, не перетинаючи шляхів. Далі другорядною дорогою: трамвай 1 має перевагу перед синім автомобілем ({p:16.12}).","ru":"Главная дорога (знак {s:2.3} с табличкой {s:7.8}) идёт снизу налево, поэтому сначала движутся трамвай 2, красный и жёлтый; между собой они по {p:16.14} руководствуются правилами равнозначных дорог, и жёлтый уступает трамваю 2 и красному, которые для него справа, а те едут одновременно, не пересекая путей. Далее по второстепенной дороге: трамвай 1 имеет преимущество перед синим автомобилем ({p:16.12})."},"ref":["16.11","16.12","16.14","33.2","33.7"],"pic":["img/hsc/16.2-18-1.jpg"]},{"id":"h16.2-19","t":"h16.2","num":"16.2.19","q":{"uk":"Ви проїдете дане перехрестя:","ru":"Вы проедете данный перекрёсток:"},"a":[{"uk":"Першим.","ru":"Первым.","w":{"uk":"Ви на другорядній дорозі, тому мусите пропустити чорний і білий автомобілі, які рухаються головною.","ru":"Вы на второстепенной дороге, поэтому обязаны пропустить чёрный и белый автомобили, движущиеся по главной."}},{"uk":"Після чорного і білого автомобілів.","ru":"После чёрного и белого автомобилей."},{"uk":"Після чорного, білого і синього автомобілів.","ru":"После чёрного, белого и синего автомобилей.","w":{"uk":"Синій автомобіль ліворуч теж на другорядній дорозі; між собою ви роз'їжджаєтеся як на рівнозначних дорогах, тож він пропускає Вас.","ru":"Синий автомобиль слева тоже на второстепенной дороге; между собой вы разъезжаетесь как на равнозначных дорогах, поэтому он пропускает Вас."}}],"c":1,"e":{"uk":"За знаком {s:2.1} з табличкою {s:7.8} головна дорога йде із зустрічного напрямку праворуч, тож чорний (зустрічний) і білий (праворуч) автомобілі мають перевагу ({p:16.11}). Синій автомобіль ліворуч, як і Ви, на другорядній дорозі і за {p:16.14} поступається Вам, бо Ви для нього праворуч.","ru":"По знаку {s:2.1} с табличкой {s:7.8} главная дорога идёт со встречного направления направо, поэтому чёрный (встречный) и белый (справа) автомобили имеют преимущество ({p:16.11}). Синий автомобиль слева, как и Вы, на второстепенной дороге и по {p:16.14} уступает Вам, так как Вы для него справа."},"ref":["16.11","16.14","33.2","33.7"],"pic":["img/hsc/16.2-19-1.jpg"]},{"id":"h16.2-20","t":"h16.2","num":"16.2.20","q":{"uk":"Ви проїдете дане перехрестя:","ru":"Вы проедете данный перекрёсток:"},"a":[{"uk":"Останнім.","ru":"Последним.","w":{"uk":"Білий автомобіль ліворуч рухається другорядною дорогою, і Ви для нього праворуч, тому він проїде після Вас.","ru":"Белый автомобиль слева движется по второстепенной дороге, и Вы для него справа, поэтому он проедет после Вас."}},{"uk":"Після жовтого і фіолетового автомобілів, трамвая.","ru":"После жёлтого и фиолетового автомобилей, трамвая."},{"uk":"Першим.","ru":"Первым.","w":{"uk":"Ви на другорядній дорозі й мусите пропустити жовтий і фіолетовий автомобілі на головній, а також трамвай, що має перевагу перед нерейковими транспортними засобами.","ru":"Вы на второстепенной дороге и обязаны пропустить жёлтый и фиолетовый автомобили на главной, а также трамвай, имеющий преимущество перед нерельсовыми транспортными средствами."}}],"c":1,"e":{"uk":"Головна дорога (знак {s:2.1} з табличкою {s:7.8}) йде із зустрічного напрямку праворуч, тож жовтий і фіолетовий автомобілі мають перевагу ({p:16.11}). Трамвай на Вашій, другорядній дорозі має перевагу перед нерейковими транспортними засобами ({p:16.12}), а білий автомобіль ліворуч, теж на другорядній, поступається Вам ({p:16.14}).","ru":"Главная дорога (знак {s:2.1} с табличкой {s:7.8}) идёт со встречного направления направо, поэтому жёлтый и фиолетовый автомобили имеют преимущество ({p:16.11}). Трамвай на Вашей, второстепенной дороге имеет преимущество перед нерельсовыми транспортными средствами ({p:16.12}), а белый автомобиль слева, тоже на второстепенной, уступает Вам ({p:16.14})."},"ref":["16.11","16.12","16.14","33.2","33.7"],"pic":["img/hsc/16.2-20-1.jpg"]},{"id":"h16.2-21","t":"h16.2","num":"16.2.21","q":{"uk":"Ви проїдете дане перехрестя:","ru":"Вы проедете данный перекрёсток:"},"a":[{"uk":"Після трамвая.","ru":"После трамвая.","w":{"uk":"Білий зустрічний автомобіль теж їде головною дорогою, а чорний наближається праворуч по другорядній — обом також треба дати дорогу.","ru":"Белый встречный автомобиль тоже едет по главной дороге, а чёрный приближается справа по второстепенной — обоим также нужно уступить дорогу."}},{"uk":"Після трамвая, білого і чорного автомобілів.","ru":"После трамвая, белого и чёрного автомобилей."},{"uk":"Першим.","ru":"Первым.","w":{"uk":"Ви на другорядній дорозі, тому першим проїхати не можете: перевагу мають трамвай і білий автомобіль на головній, а також чорний автомобіль праворуч.","ru":"Вы на второстепенной дороге, поэтому первым проехать не можете: преимущество у трамвая и белого автомобиля на главной, а также у чёрного автомобиля справа."}}],"c":1,"e":{"uk":"За знаком {s:2.1} з табличкою {s:7.8} головна дорога йде із зустрічного напрямку ліворуч, тож трамвай ліворуч і білий зустрічний автомобіль мають перевагу ({p:16.11}). Чорний автомобіль праворуч, як і Ви, на другорядній дорозі, і за {p:16.14} Ви повинні дати йому дорогу як транспортному засобу, що наближається праворуч.","ru":"По знаку {s:2.1} с табличкой {s:7.8} главная дорога идёт со встречного направления налево, поэтому трамвай слева и белый встречный автомобиль имеют преимущество ({p:16.11}). Чёрный автомобиль справа, как и Вы, на второстепенной дороге, и по {p:16.14} Вы должны уступить ему дорогу как транспортному средству, приближающемуся справа."},"ref":["16.11","16.14","33.2","33.7"],"pic":["img/hsc/16.2-21-1.jpg"]},{"id":"h16.2-22","t":"h16.2","num":"16.2.22","q":{"uk":"Яка черговість проїзду транспортних засобів на даному перехресті?","ru":"Какова очерёдность проезда транспортных средств на данном перекрёстке?"},"a":[{"uk":"Ви, а потім сірий автомобіль.","ru":"Вы, а затем серый автомобиль.","w":{"uk":"Сірий автомобіль для Вас праворуч, тож на рівнозначних дорогах перевага в нього.","ru":"Серый автомобиль для Вас справа, поэтому на равнозначных дорогах преимущество у него."}},{"uk":"Сірий автомобіль, а потім Ви.","ru":"Серый автомобиль, а затем Вы."}],"c":1,"e":{"uk":"Знаків пріоритету немає, дороги рівнозначні, а сірий автомобіль наближається праворуч, тому за {p:16.12} першим проїжджає він, а Ви — після нього.","ru":"Знаков приоритета нет, дороги равнозначные, а серый автомобиль приближается справа, поэтому по {p:16.12} первым проезжает он, а Вы — после него."},"ref":["16.12"],"pic":["img/hsc/16.2-22-1.jpg"]},{"id":"h16.2-23","t":"h16.2","num":"16.2.23","q":{"uk":"Ви проїдете дане перехрестя:","ru":"Вы проедете данный перекрёсток:"},"a":[{"uk":"Першим.","ru":"Первым.","w":{"uk":"Білий автомобіль праворуч має перевагу, тож першим проїжджає він.","ru":"Белый автомобиль справа имеет преимущество, поэтому первым проезжает он."}},{"uk":"Давши дорогу білому автомобілю.","ru":"Уступив дорогу белому автомобилю."}],"c":1,"e":{"uk":"Дороги рівнозначні, білий автомобіль наближається праворуч, тож за {p:16.12} Ви повинні дати йому дорогу незалежно від того, куди він повертає.","ru":"Дороги равнозначные, белый автомобиль приближается справа, поэтому по {p:16.12} Вы должны уступить ему дорогу независимо от того, куда он поворачивает."},"ref":["16.12"],"pic":["img/hsc/16.2-23-1.jpg"]},{"id":"h16.2-24","t":"h16.2","num":"16.2.24","q":{"uk":"Ви проїдете дане перехрестя:","ru":"Вы проедете данный перекрёсток:"},"a":[{"uk":"Першим.","ru":"Первым.","w":{"uk":"Правило «перешкоди праворуч» стосується і велосипедистів, тож велосипедист праворуч має перевагу.","ru":"Правило «помехи справа» касается и велосипедистов, поэтому велосипедист справа имеет преимущество."}},{"uk":"Давши дорогу велосипедистові.","ru":"Уступив дорогу велосипедисту."}],"c":1,"e":{"uk":"Велосипед — теж транспортний засіб ({p:1.10}), а велосипедист наближається праворуч рівнозначною дорогою, тому за {p:16.12} Ви повинні дати йому дорогу.","ru":"Велосипед — тоже транспортное средство ({p:1.10}), а велосипедист приближается справа по равнозначной дороге, поэтому по {p:16.12} Вы должны уступить ему дорогу."},"ref":["1.10","16.12"],"pic":["img/hsc/16.2-24-1.jpg"]},{"id":"h16.2-25","t":"h16.2","num":"16.2.25","q":{"uk":"Рухаючись прямо на даному перехресті, Ви повинні:","ru":"Двигаясь прямо на данном перекрёстке, Вы должны:"},"a":[{"uk":"Проїхати, не даючи дорогу велосипедистові.","ru":"Проехать, не уступая дорогу велосипедисту.","w":{"uk":"Велосипед — транспортний засіб, і велосипедист праворуч має перевагу так само, як автомобіль.","ru":"Велосипед — транспортное средство, и велосипедист справа имеет преимущество так же, как автомобиль."}},{"uk":"Проїхати, давши дорогу велосипедистові.","ru":"Проехать, уступив дорогу велосипедисту."}],"c":1,"e":{"uk":"Це перехрестя рівнозначних доріг, а велосипедист, який керує транспортним засобом ({p:1.10}), наближається праворуч — за {p:16.12} Ви повинні дати йому дорогу.","ru":"Это перекрёсток равнозначных дорог, а велосипедист, управляющий транспортным средством ({p:1.10}), приближается справа — по {p:16.12} Вы должны уступить ему дорогу."},"ref":["1.10","16.12"],"pic":["img/hsc/16.2-25-1.jpg"]},{"id":"h16.2-26","t":"h16.2","num":"16.2.26","q":{"uk":"Виїжджаючи на дане перехрестя, Ви повинні:","ru":"Въезжая на данный перекрёсток, Вы должны:"},"a":[{"uk":"Виїхати на перехрестя, де організовано круговий рух, водій фіолетового автомобіля повинен дати Вам дорогу.","ru":"Въехать на перекрёсток, где организовано круговое движение, водитель фиолетового автомобиля должен уступить Вам дорогу.","w":{"uk":"На перехресті з круговим рухом, позначеному знаком {s:4.10}, правило «перешкоди праворуч» не діє: перевагу має той, хто вже рухається по колу.","ru":"На перекрёстке с круговым движением, обозначенном знаком {s:4.10}, правило «помехи справа» не действует: преимущество у того, кто уже движется по кругу."}},{"uk":"Надати перевагу у русі фіолетовому автомобілю, який вже рухається по колу, і після цього виїхати на перехрестя.","ru":"Предоставить преимущество в движении фиолетовому автомобилю, который уже движется по кругу, и после этого въехать на перекрёсток."}],"c":1,"e":{"uk":"Перехрестя позначене знаком {s:4.10}, тож за {p:16.12} перевага належить транспортним засобам, які **вже рухаються по колу**. Фіолетовий автомобіль уже на колі, тому Ви виїжджаєте на перехрестя тільки після нього.","ru":"Перекрёсток обозначен знаком {s:4.10}, поэтому по {p:16.12} преимущество принадлежит транспортным средствам, которые **уже движутся по кругу**. Фиолетовый автомобиль уже на кругу, поэтому Вы въезжаете на перекрёсток только после него."},"ref":["16.12"],"pic":["img/hsc/16.2-26-1.jpg"]},{"id":"h16.2-27","t":"h16.2","num":"16.2.27","q":{"uk":"Повертаючи ліворуч у даній ситуації, Ви повинні:","ru":"Поворачивая налево в данной ситуации, Вы должны:"},"a":[{"uk":"Проїхати першим, не даючи дорогу.","ru":"Проехать первым, не уступая дорогу.","w":{"uk":"Зустрічний велосипедист їде прямо, а Ви, повертаючи ліворуч, перетинаєте його шлях, тому зобов'язані його пропустити.","ru":"Встречный велосипедист едет прямо, а Вы, поворачивая налево, пересекаете его путь, поэтому обязаны его пропустить."}},{"uk":"Дати дорогу велосипедистові.","ru":"Уступить дорогу велосипедисту."}],"c":1,"e":{"uk":"Перед поворотом ліворуч за {p:16.13} Ви повинні дати дорогу транспортним засобам, що рухаються рівнозначною дорогою в зустрічному напрямку прямо, — зокрема й зустрічному велосипедистові.","ru":"Перед поворотом налево по {p:16.13} Вы должны уступить дорогу транспортным средствам, движущимся по равнозначной дороге во встречном направлении прямо, — в том числе и встречному велосипедисту."},"ref":["1.10","16.13"],"pic":["img/hsc/16.2-27-1.jpg"]},{"id":"h16.2-28","t":"h16.2","num":"16.2.28","q":{"uk":"Проїжджаючи дане перехрестя, Ви повинні:","ru":"Проезжая данный перекрёсток, Вы должны:"},"a":[{"uk":"Проїхати перехрестя першим, не даючи дорогу.","ru":"Проехать перекрёсток первым, не уступая дорогу.","w":{"uk":"Повертаючи ліворуч, Ви перетинаєте шлях зустрічного білого автомобіля, тому маєте його пропустити.","ru":"Поворачивая налево, Вы пересекаете путь встречного белого автомобиля, поэтому должны его пропустить."}},{"uk":"Дати дорогу білому автомобілю.","ru":"Уступить дорогу белому автомобилю."}],"c":1,"e":{"uk":"Ви повертаєте ліворуч на перехресті рівнозначних доріг, а білий автомобіль рухається назустріч прямо — за {p:16.13} Ви повинні дати йому дорогу.","ru":"Вы поворачиваете налево на перекрёстке равнозначных дорог, а белый автомобиль движется навстречу прямо — по {p:16.13} Вы должны уступить ему дорогу."},"ref":["16.13"],"pic":["img/hsc/16.2-28-1.jpg"]},{"id":"h16.2-29","t":"h16.2","num":"16.2.29","q":{"uk":"Повертаючи ліворуч у даній ситуації, Ви повинні:","ru":"Поворачивая налево в данной ситуации, Вы должны:"},"a":[{"uk":"Проїхати перехрестя першим.","ru":"Проехать перекрёсток первым.","w":{"uk":"Першим Ви проїхати не можете: мотоцикл їде назустріч прямо, а червоний автомобіль наближається праворуч.","ru":"Первым Вы проехать не можете: мотоцикл едет навстречу прямо, а красный автомобиль приближается справа."}},{"uk":"Проїхати перехрестя другим, давши дорогу тільки мотоциклу.","ru":"Проехать перекрёсток вторым, уступив дорогу только мотоциклу.","w":{"uk":"Червоний автомобіль праворуч від Вас, тож йому теж треба дати дорогу.","ru":"Красный автомобиль справа от Вас, поэтому ему тоже нужно уступить дорогу."}},{"uk":"Проїхати перехрестя останнім – після мотоцикла й автомобіля.","ru":"Проехать перекрёсток последним — после мотоцикла и автомобиля."}],"c":2,"e":{"uk":"Зустрічному мотоциклу, що їде прямо, Ви поступаєтеся під час повороту ліворуч ({p:16.13}), а червоний автомобіль наближається праворуч ({p:16.12}). Мотоцикл для червоного автомобіля теж праворуч, тому черговість така: мотоцикл, червоний автомобіль, Ви.","ru":"Встречному мотоциклу, едущему прямо, Вы уступаете при повороте налево ({p:16.13}), а красный автомобиль приближается справа ({p:16.12}). Мотоцикл для красного автомобиля тоже справа, поэтому очерёдность такая: мотоцикл, красный автомобиль, Вы."},"ref":["16.12","16.13"],"pic":["img/hsc/16.2-29-1.jpg"]},{"id":"h16.2-30","t":"h16.2","num":"16.2.30","q":{"uk":"Повертаючи ліворуч на даному перехресті, Ви повинні:","ru":"Поворачивая налево на данном перекрёстке, Вы должны:"},"a":[{"uk":"Проїхати перехрестя першим.","ru":"Проехать перекрёсток первым.","w":{"uk":"Повертаючи ліворуч, Ви поступаєтеся зустрічному білому автомобілю, а трамвай має перевагу перед нерейковими транспортними засобами.","ru":"Поворачивая налево, Вы уступаете встречному белому автомобилю, а трамвай имеет преимущество перед нерельсовыми транспортными средствами."}},{"uk":"Проїхати перехрестя другим, давши дорогу тільки білому автомобілю.","ru":"Проехать перекрёсток вторым, уступив дорогу только белому автомобилю.","w":{"uk":"Трамвай хоч і ліворуч, але має перевагу перед нерейковими транспортними засобами, тож його теж треба пропустити.","ru":"Трамвай хоть и слева, но имеет преимущество перед нерельсовыми транспортными средствами, поэтому его тоже нужно пропустить."}},{"uk":"Проїхати перехрестя останнім – після трамвая і білого автомобіля.","ru":"Проехать перекрёсток последним — после трамвая и белого автомобиля."}],"c":2,"e":{"uk":"Зустрічному білому автомобілю, що їде прямо, Ви поступаєтеся під час повороту ліворуч ({p:16.13}), а трамвай на нерегульованому перехресті має перевагу перед нерейковими транспортними засобами на рівнозначній дорозі незалежно від того, з якого боку він наближається ({p:16.12}). Тому Ви проїжджаєте останнім.","ru":"Встречному белому автомобилю, едущему прямо, Вы уступаете при повороте налево ({p:16.13}), а трамвай на нерегулируемом перекрёстке имеет преимущество перед нерельсовыми транспортными средствами на равнозначной дороге независимо от того, с какой стороны он приближается ({p:16.12}). Поэтому Вы проезжаете последним."},"ref":["16.12","16.13"],"pic":["img/hsc/16.2-30-1.jpg"]},{"id":"h16.2-31","t":"h16.2","num":"16.2.31","q":{"uk":"Проїжджаючи дане перехрестя, Ви повинні:","ru":"Проезжая данный перекрёсток, Вы должны:"},"a":[{"uk":"Проїхати перехрестя першим.","ru":"Проехать перекрёсток первым.","w":{"uk":"Трамвай праворуч має перевагу, тож першим Ви проїхати не можете.","ru":"Трамвай справа имеет преимущество, поэтому первым Вы проехать не можете."}},{"uk":"Дати дорогу тільки трамваю.","ru":"Уступить дорогу только трамваю."},{"uk":"Проїхати перехрестя після трамвая і сірого автомобіля.","ru":"Проехать перекрёсток после трамвая и серого автомобиля.","w":{"uk":"Сірий автомобіль повертає ліворуч, тому за {p:16.13} він поступається Вам як зустрічному транспортному засобу, що їде прямо.","ru":"Серый автомобиль поворачивает налево, поэтому по {p:16.13} он уступает Вам как встречному транспортному средству, едущему прямо."}}],"c":1,"e":{"uk":"Трамвай наближається праворуч і до того ж на нерегульованому перехресті має перевагу перед нерейковими транспортними засобами на рівнозначній дорозі ({p:16.12}), тому його треба пропустити. Сірий зустрічний автомобіль повертає ліворуч і за {p:16.13} сам має дати дорогу Вам, бо Ви їдете прямо.","ru":"Трамвай приближается справа и к тому же на нерегулируемом перекрёстке имеет преимущество перед нерельсовыми транспортными средствами на равнозначной дороге ({p:16.12}), поэтому его нужно пропустить. Серый встречный автомобиль поворачивает налево и по {p:16.13} сам должен уступить дорогу Вам, так как Вы едете прямо."},"ref":["16.12","16.13"],"pic":["img/hsc/16.2-31-1.jpg"]},{"id":"h16.2-32","t":"h16.2","num":"16.2.32","q":{"uk":"Ви повернете ліворуч на даному перехресті:","ru":"Вы повернёте налево на данном перекрёстке:"},"a":[{"uk":"Першим.","ru":"Первым.","w":{"uk":"Першим Ви не проїдете: синій автомобіль їде назустріч прямо, а зелений наближається праворуч.","ru":"Первым Вы не проедете: синий автомобиль едет навстречу прямо, а зелёный приближается справа."}},{"uk":"Другим.","ru":"Вторым.","w":{"uk":"Другим Ви не будете: поступитися треба обом — і зустрічному синьому, і зеленому праворуч.","ru":"Вторым Вы не будете: уступить нужно обоим — и встречному синему, и зелёному справа."}},{"uk":"Третім.","ru":"Третьим."}],"c":2,"e":{"uk":"Повертаючи ліворуч, Ви поступаєтеся зустрічному синьому автомобілю ({p:16.13}) і зеленому, що наближається праворуч ({p:16.12}). Зелений, своєю чергою, пропускає синій, бо той для нього праворуч, тож порядок такий: синій, зелений, Ви — третім.","ru":"Поворачивая налево, Вы уступаете встречному синему автомобилю ({p:16.13}) и зелёному, приближающемуся справа ({p:16.12}). Зелёный, в свою очередь, пропускает синий, так как тот для него справа, поэтому порядок такой: синий, зелёный, Вы — третьим."},"ref":["16.12","16.13"],"pic":["img/hsc/16.2-32-1.jpg"]},{"id":"h16.2-33","t":"h16.2","num":"16.2.33","q":{"uk":"Яка черговість проїзду транспортних засобів на даному перехресті?","ru":"Какова очерёдность проезда транспортных средств на данном перекрёстке?"},"a":[{"uk":"Синій, ваш, білий автомобілі.","ru":"Синий, ваш, белый автомобили.","w":{"uk":"Синій автомобіль ліворуч від Вас і мусить пропустити і Вас, і білий автомобіль.","ru":"Синий автомобиль слева от Вас и обязан пропустить и Вас, и белый автомобиль."}},{"uk":"Ваш, білий, синій автомобілі.","ru":"Ваш, белый, синий автомобили.","w":{"uk":"Білий автомобіль праворуч від Вас, тому Ви повинні пропустити його.","ru":"Белый автомобиль справа от Вас, поэтому Вы должны пропустить его."}},{"uk":"Білий, ваш, синій автомобілі.","ru":"Белый, ваш, синий автомобили."}],"c":2,"e":{"uk":"Дороги рівнозначні ({p:16.12}): білий автомобіль праворуч від Вас, тому проїжджає першим, а для синього, що ліворуч, праворуч уже Ви, отже він пропускає Вас. Черговість: білий, Ваш, синій.","ru":"Дороги равнозначные ({p:16.12}): белый автомобиль справа от Вас, поэтому проезжает первым, а для синего, который слева, справа уже Вы, значит, он пропускает Вас. Очерёдность: белый, Ваш, синий."},"ref":["16.12"],"pic":["img/hsc/16.2-33-1.jpg"]},{"id":"h16.2-34","t":"h16.2","num":"16.2.34","q":{"uk":"Ви проїдете дане перехрестя:","ru":"Вы проедете данный перекрёсток:"},"a":[{"uk":"Першим.","ru":"Первым.","w":{"uk":"Зелений автомобіль праворуч має перевагу, тож першим Ви не проїдете.","ru":"Зелёный автомобиль справа имеет преимущество, поэтому первым Вы не проедете."}},{"uk":"Після зеленого автомобіля.","ru":"После зелёного автомобиля."},{"uk":"Після сірого автомобіля.","ru":"После серого автомобиля.","w":{"uk":"Сірий автомобіль ліворуч від Вас, тому на рівнозначних дорогах поступається він.","ru":"Серый автомобиль слева от Вас, поэтому на равнозначных дорогах уступает он."}}],"c":1,"e":{"uk":"Ви повертаєте ліворуч на перехресті рівнозначних доріг: зелений автомобіль наближається праворуч, тож йому Ви поступаєтеся ({p:16.12}), а сірий автомобіль ліворуч сам має дати дорогу Вам.","ru":"Вы поворачиваете налево на перекрёстке равнозначных дорог: зелёный автомобиль приближается справа, поэтому ему Вы уступаете ({p:16.12}), а серый автомобиль слева сам должен уступить дорогу Вам."},"ref":["16.12"],"pic":["img/hsc/16.2-34-1.jpg"]},{"id":"h16.2-35","t":"h16.2","num":"16.2.35","q":{"uk":"Як повинен чинити водій транспортного засобу, що наближається до перехрестя, на якому немає знаків пріоритету, а наявність покриття на дорозі неможливо визначити у зв'язку з погодними або іншими умовами?","ru":"Как должен действовать водитель транспортного средства, приближающегося к перекрёстку, на котором нет знаков приоритета, а наличие покрытия на дороге невозможно определить в связи с погодными или иными условиями?"},"a":[{"uk":"Вважати, що він перебуває на головній дорозі.","ru":"Считать, что он находится на главной дороге.","w":{"uk":"Правила вимагають протилежного: у такій ситуації водій має вважати свою дорогу другорядною, щоб не створити небезпеки.","ru":"Правила требуют обратного: в такой ситуации водитель должен считать свою дорогу второстепенной, чтобы не создать опасности."}},{"uk":"Вважати, що він перебуває на другорядній дорозі.","ru":"Считать, что он находится на второстепенной дороге."},{"uk":"Давати дорогу, тільки повертаючи ліворуч.","ru":"Уступать дорогу, только поворачивая налево.","w":{"uk":"Водій, який вважає себе на другорядній дорозі, поступається транспорту на перехрещуваній дорозі за будь-якого напрямку руху, а не лише повертаючи ліворуч.","ru":"Водитель, считающий себя на второстепенной дороге, уступает транспорту на пересекаемой дороге при любом направлении движения, а не только поворачивая налево."}}],"c":1,"e":{"uk":"За {p:16.15}, якщо неможливо визначити наявність покриття (темна пора доби, бруд, сніг тощо), а знаків пріоритету немає, водій повинен вважати, що перебуває на **другорядній** дорозі, і пропускати транспорт на перехрещуваній дорозі.","ru":"По {p:16.15}, если невозможно определить наличие покрытия (тёмное время суток, грязь, снег и т. п.), а знаков приоритета нет, водитель должен считать, что находится на **второстепенной** дороге, и пропускать транспорт на пересекаемой дороге."},"ref":["16.15"],"pic":["img/hsc/16.2-35-1.jpg"]},{"id":"h16.2-36","t":"h16.2","num":"16.2.36","q":{"uk":"Як повинен поводитися водій у ситуації, коли неможливо визначити наявність покриття на дорозі, за відсутності знаків пріоритету?","ru":"Как должен вести себя водитель в ситуации, когда невозможно определить наличие покрытия на дороге, при отсутствии знаков приоритета?"},"a":[{"uk":"Проїхати перехрестя першим, оскільки він їде прямо.","ru":"Проехать перекрёсток первым, так как он едет прямо.","w":{"uk":"Рух прямо не дає переваги: коли покриття визначити неможливо, водій має вважати свою дорогу другорядною.","ru":"Движение прямо не даёт преимущества: когда покрытие определить невозможно, водитель должен считать свою дорогу второстепенной."}},{"uk":"Вважати, що він перебуває на другорядній дорозі.","ru":"Считать, что он находится на второстепенной дороге."}],"c":1,"e":{"uk":"Під снігом не видно, чи мають дороги покриття, а знаків пріоритету немає, тому за {p:16.15} водій повинен вважати, що перебуває на другорядній дорозі, і пропустити автомобілі на перехрещуваній дорозі.","ru":"Под снегом не видно, есть ли на дорогах покрытие, а знаков приоритета нет, поэтому по {p:16.15} водитель должен считать, что находится на второстепенной дороге, и пропустить автомобили на пересекаемой дороге."},"ref":["16.15"],"pic":["img/hsc/16.2-36-1.jpg"]},{"id":"h16.2-37","t":"h16.2","num":"16.2.37","q":{"uk":"Повертаючи ліворуч у даній ситуації, Ви повинні:","ru":"Поворачивая налево в данной ситуации, Вы должны:"},"a":[{"uk":"Проїхати першим, не даючи дорогу.","ru":"Проехать первым, не уступая дорогу.","w":{"uk":"Повертаючи ліворуч, Ви перетинаєте шлях зустрічного синього автомобіля, тому маєте його пропустити.","ru":"Поворачивая налево, Вы пересекаете путь встречного синего автомобиля, поэтому должны его пропустить."}},{"uk":"Дати дорогу синьому автомобілю.","ru":"Уступить дорогу синему автомобилю."}],"c":1,"e":{"uk":"Перед поворотом ліворуч за {p:16.13} Ви повинні дати дорогу зустрічному синьому автомобілю, який рухається рівнозначною дорогою прямо.","ru":"Перед поворотом налево по {p:16.13} Вы должны уступить дорогу встречному синему автомобилю, движущемуся по равнозначной дороге прямо."},"ref":["16.13"],"pic":["img/hsc/16.2-37-1.jpg"]},{"id":"h16.2-38","t":"h16.2","num":"16.2.38","q":{"uk":"Ви проїдете дане перехрестя:","ru":"Вы проедете данный перекрёсток:"},"a":[{"uk":"Першим.","ru":"Первым."},{"uk":"Після червоного автомобіля.","ru":"После красного автомобиля.","w":{"uk":"Червоний автомобіль повертає ліворуч, тому він сам зобов'язаний пропустити Вас як зустрічний транспортний засіб, що рухається прямо.","ru":"Красный автомобиль поворачивает налево, поэтому он сам обязан пропустить Вас как встречное транспортное средство, движущееся прямо."}},{"uk":"Останнім.","ru":"Последним.","w":{"uk":"Ні жовтий автомобіль (ліворуч), ні червоний (повертає ліворуч назустріч Вам) не мають переваги перед Вами.","ru":"Ни жёлтый автомобиль (слева), ни красный (поворачивает налево навстречу Вам) не имеют преимущества перед Вами."}}],"c":0,"e":{"uk":"Ви їдете прямо: червоний зустрічний автомобіль повертає ліворуч і за {p:16.13} має поступитися Вам, а жовтий наближається ліворуч і за {p:16.12} теж пропускає Вас. Отже, Ви проїжджаєте першим.","ru":"Вы едете прямо: красный встречный автомобиль поворачивает налево и по {p:16.13} должен уступить Вам, а жёлтый приближается слева и по {p:16.12} тоже пропускает Вас. Следовательно, Вы проезжаете первым."},"ref":["16.12","16.13"],"pic":["img/hsc/16.2-38-1.jpg"]},{"id":"h16.2-39","t":"h16.2","num":"16.2.39","q":{"uk":"Як повинен вчинити водій жовтого автомобіля в даній ситуації?","ru":"Как должен поступить водитель жёлтого автомобиля в данной ситуации?"},"a":[{"uk":"Повинен проїхати першим, оскільки має перевагу в русі, тому що перебуває на перехресті з круговим рухом.","ru":"Должен проехать первым, так как имеет преимущество в движении, поскольку находится на перекрёстке с круговым движением."},{"uk":"Повинен дати Вам дорогу.","ru":"Должен уступить Вам дорогу.","w":{"uk":"На перехресті з круговим рухом, позначеному знаком {s:4.10}, перевагу має той, хто вже рухається по колу, тобто жовтий автомобіль, а не Ви.","ru":"На перекрёстке с круговым движением, обозначенном знаком {s:4.10}, преимущество у того, кто уже движется по кругу, то есть у жёлтого автомобиля, а не у Вас."}}],"c":0,"e":{"uk":"Перехрестя позначене знаком {s:4.10}, а жовтий автомобіль уже рухається по колу, тож за {p:16.12} перевага в нього, і Ви, в'їжджаючи на коло, повинні його пропустити.","ru":"Перекрёсток обозначен знаком {s:4.10}, а жёлтый автомобиль уже движется по кругу, поэтому по {p:16.12} преимущество у него, и Вы, въезжая на круг, должны его пропустить."},"ref":["16.12"],"pic":["img/hsc/16.2-39-1.jpg"]},{"id":"h16.2-40","t":"h16.2","num":"16.2.40","q":{"uk":"Яка черговість проїзду транспортних засобів на даному перехресті?","ru":"Какова очерёдность проезда транспортных средств на данном перекрёстке?"},"a":[{"uk":"Синій, ваш автомобілі.","ru":"Синий, ваш автомобили."},{"uk":"Ваш, синій автомобілі.","ru":"Ваш, синий автомобили.","w":{"uk":"Ви лише в'їжджаєте на коло, а синій автомобіль уже рухається по ньому, тому перевага в нього.","ru":"Вы только въезжаете на круг, а синий автомобиль уже движется по нему, поэтому преимущество у него."}}],"c":0,"e":{"uk":"Перехрестя з круговим рухом позначене знаком {s:4.10}; синій автомобіль уже рухається по колу, тож за {p:16.12} він проїжджає першим, а Ви в'їжджаєте після нього.","ru":"Перекрёсток с круговым движением обозначен знаком {s:4.10}; синий автомобиль уже движется по кругу, поэтому по {p:16.12} он проезжает первым, а Вы въезжаете после него."},"ref":["16.12"],"pic":["img/hsc/16.2-40-1.jpg"]},{"id":"h16.2-41","t":"h16.2","num":"16.2.41","q":{"uk":"Яка черговість проїзду транспортних засобів на даному перехресті?","ru":"Какова очерёдность проезда транспортных средств на данном перекрёстке?"},"a":[{"uk":"Ваш, синій, білий автомобілі.","ru":"Ваш, синий, белый автомобили.","w":{"uk":"Білий автомобіль праворуч від Вас, тож Ви не можете проїхати раніше за нього.","ru":"Белый автомобиль справа от Вас, поэтому Вы не можете проехать раньше него."}},{"uk":"Синій, білий, ваш автомобілі.","ru":"Синий, белый, ваш автомобили."},{"uk":"Білий, синій, ваш автомобілі.","ru":"Белый, синий, ваш автомобили.","w":{"uk":"Синій автомобіль для білого розташований праворуч, тому білий має пропустити його й рушити лише після нього.","ru":"Синий автомобиль для белого находится справа, поэтому белый должен пропустить его и тронуться только после него."}}],"c":1,"e":{"uk":"На перехресті рівнозначних доріг ({p:16.12}) Ви поступаєтеся білому автомобілю, що праворуч, а білий — синьому зустрічному, бо той для нього праворуч. Синьому праворуч ніхто не заважає, тому черговість: синій, білий, Ваш.","ru":"На перекрёстке равнозначных дорог ({p:16.12}) Вы уступаете белому автомобилю, который справа, а белый — синему встречному, так как тот для него справа. Синему справа никто не мешает, поэтому очерёдность: синий, белый, Ваш."},"ref":["16.12"],"pic":["img/hsc/16.2-41-1.jpg"]},{"id":"h16.2-42","t":"h16.2","num":"16.2.42","q":{"uk":"Проїжджаючи дане перехрестя, Ви повинні:","ru":"Проезжая данный перекрёсток, Вы должны:"},"a":[{"uk":"Проїхати перехрестя першим.","ru":"Проехать перекрёсток первым.","w":{"uk":"Червоний автомобіль праворуч має перевагу, тож першим Ви не проїдете.","ru":"Красный автомобиль справа имеет преимущество, поэтому первым Вы не проедете."}},{"uk":"Проїхати, давши дорогу тільки білому автомобілю.","ru":"Проехать, уступив дорогу только белому автомобилю.","w":{"uk":"Білий автомобіль ліворуч, тому він поступається Вам, а от червоному праворуч дорогу дати треба.","ru":"Белый автомобиль слева, поэтому он уступает Вам, а вот красному справа уступить дорогу нужно."}},{"uk":"Проїхати, давши дорогу обом автомобілям.","ru":"Проехать, уступив дорогу обоим автомобилям.","w":{"uk":"Білому автомобілю ліворуч поступатися не потрібно: це він має пропустити Вас.","ru":"Белому автомобилю слева уступать не нужно: это он должен пропустить Вас."}},{"uk":"Проїхати, давши дорогу тільки червоному автомобілю.","ru":"Проехать, уступив дорогу только красному автомобилю."}],"c":3,"e":{"uk":"Дороги рівнозначні: червоний автомобіль наближається праворуч, тож йому Ви поступаєтеся, а білий ліворуч сам має пропустити Вас ({p:16.12}).","ru":"Дороги равнозначные: красный автомобиль приближается справа, поэтому ему Вы уступаете, а белый слева сам должен пропустить Вас ({p:16.12})."},"ref":["16.12"],"pic":["img/hsc/16.2-42-1.jpg"]},{"id":"h16.2-43","t":"h16.2","num":"16.2.43","q":{"uk":"Проїжджаючи дане перехрестя, Ви повинні:","ru":"Проезжая данный перекрёсток, Вы должны:"},"a":[{"uk":"Проїхати перехрестя першим.","ru":"Проехать перекрёсток первым.","w":{"uk":"Велосипедист праворуч керує транспортним засобом і має перевагу, тож першим Ви не проїдете.","ru":"Велосипедист справа управляет транспортным средством и имеет преимущество, поэтому первым Вы не проедете."}},{"uk":"Проїхати, давши дорогу тільки синьому автомобілю.","ru":"Проехать, уступив дорогу только синему автомобилю.","w":{"uk":"Синій автомобіль ліворуч від Вас, тому поступається він; пропустити треба велосипедиста праворуч.","ru":"Синий автомобиль слева от Вас, поэтому уступает он; пропустить нужно велосипедиста справа."}},{"uk":"Проїхати, давши дорогу синьому автомобілю і велосипедистові.","ru":"Проехать, уступив дорогу синему автомобилю и велосипедисту.","w":{"uk":"Синій автомобіль ліворуч поступається Вам, тож йому дорогу давати не потрібно.","ru":"Синий автомобиль слева уступает Вам, поэтому ему уступать дорогу не нужно."}},{"uk":"Проїхати, давши дорогу тільки велосипедистові.","ru":"Проехать, уступив дорогу только велосипедисту."}],"c":3,"e":{"uk":"Велосипедист наближається праворуч рівнозначною дорогою, і за {p:16.12} Ви повинні його пропустити, а синій автомобіль ліворуч сам поступається Вам.","ru":"Велосипедист приближается справа по равнозначной дороге, и по {p:16.12} Вы должны его пропустить, а синий автомобиль слева сам уступает Вам."},"ref":["1.10","16.12"],"pic":["img/hsc/16.2-43-1.jpg"]},{"id":"h16.2-44","t":"h16.2","num":"16.2.44","q":{"uk":"Ви проїдете дане перехрестя:","ru":"Вы проедете данный перекрёсток:"},"a":[{"uk":"Першим.","ru":"Первым.","w":{"uk":"Трамвай і жовтий автомобіль праворуч мають перевагу перед Вами, тож першим Ви не проїдете.","ru":"Трамвай и жёлтый автомобиль справа имеют преимущество перед Вами, поэтому первым Вы не проедете."}},{"uk":"Другим – після трамвая.","ru":"Вторым — после трамвая.","w":{"uk":"Крім трамвая, Ви повинні пропустити жовтий автомобіль праворуч, а він, своєю чергою, чекає на білий.","ru":"Кроме трамвая, Вы должны пропустить жёлтый автомобиль справа, а он, в свою очередь, ждёт белый."}},{"uk":"Третім, давши дорогу тільки трамваю і жовтому автомобілю.","ru":"Третьим, уступив дорогу только трамваю и жёлтому автомобилю.","w":{"uk":"Жовтий автомобіль не рушить, доки не проїде білий зустрічний, який для нього праворуч, тож Ви будете не третім, а останнім.","ru":"Жёлтый автомобиль не тронется, пока не проедет белый встречный, который для него справа, поэтому Вы будете не третьим, а последним."}},{"uk":"Останнім – після трамвая, білого і жовтого автомобілів.","ru":"Последним — после трамвая, белого и жёлтого автомобилей."}],"c":3,"e":{"uk":"Трамвай має перевагу перед нерейковими транспортними засобами на рівнозначній дорозі ({p:16.12}); жовтому автомобілю праворуч Ви поступаєтеся, а жовтий, своєю чергою, пропускає білий зустрічний, бо той для нього праворуч. Тому черговість: трамвай, білий, жовтий, Ви — останнім.","ru":"Трамвай имеет преимущество перед нерельсовыми транспортными средствами на равнозначной дороге ({p:16.12}); жёлтому автомобилю справа Вы уступаете, а жёлтый, в свою очередь, пропускает белый встречный, так как тот для него справа. Поэтому очерёдность: трамвай, белый, жёлтый, Вы — последним."},"ref":["16.12"],"pic":["img/hsc/16.2-44-1.jpg"]},{"id":"h16.2-45","t":"h16.2","num":"16.2.45","q":{"uk":"Яка черговість проїзду транспортних засобів на даному перехресті?","ru":"Какова очерёдность проезда транспортных средств на данном перекрёстке?"},"a":[{"uk":"Червоний, чорний, ваш автомобілі.","ru":"Красный, чёрный, ваш автомобили.","w":{"uk":"Чорний автомобіль для червоного праворуч, тож червоний має пропустити його.","ru":"Чёрный автомобиль для красного справа, поэтому красный должен пропустить его."}},{"uk":"Чорний, червоний, ваш автомобілі.","ru":"Чёрный, красный, ваш автомобили."},{"uk":"Ваш, червоний, чорний автомобілі.","ru":"Ваш, красный, чёрный автомобили.","w":{"uk":"Червоний автомобіль праворуч від Вас, тому Ви проїжджаєте після нього.","ru":"Красный автомобиль справа от Вас, поэтому Вы проезжаете после него."}}],"c":1,"e":{"uk":"Червоний автомобіль праворуч від Вас, тож Ви його пропускаєте ({p:16.12}); червоний, своєю чергою, має дати дорогу чорному, який для нього праворуч. Тому черговість: чорний, червоний, Ваш.","ru":"Красный автомобиль справа от Вас, поэтому Вы его пропускаете ({p:16.12}); красный, в свою очередь, должен уступить дорогу чёрному, который для него справа. Поэтому очерёдность: чёрный, красный, Ваш."},"ref":["16.12"],"pic":["img/hsc/16.2-45-1.jpg"]},{"id":"h16.2-46","t":"h16.2","num":"16.2.46","q":{"uk":"Ви проїдете дане перехрестя:","ru":"Вы проедете данный перекрёсток:"},"a":[{"uk":"Першим.","ru":"Первым.","w":{"uk":"Першим Ви не проїдете: перевагу мають трамвай (незалежно від напрямку руху) і велосипедист праворуч.","ru":"Первым Вы не проедете: преимущество имеют трамвай (независимо от направления движения) и велосипедист справа."}},{"uk":"Другим – після проїзду трамвая.","ru":"Вторым — после проезда трамвая.","w":{"uk":"Крім трамвая, Ви повинні пропустити й велосипедиста, який наближається праворуч.","ru":"Кроме трамвая, Вы должны пропустить и велосипедиста, приближающегося справа."}},{"uk":"Останнім – після трамвая і велосипедиста.","ru":"Последним — после трамвая и велосипедиста."}],"c":2,"e":{"uk":"Трамвай на нерегульованому перехресті має перевагу перед нерейковими транспортними засобами на рівнозначній дорозі незалежно від напрямку руху, тож він проїжджає першим, хоч і повертає ліворуч ({p:16.12}). Велосипедист наближається праворуч, тому Ви поступаєтеся і йому та проїжджаєте останнім.","ru":"Трамвай на нерегулируемом перекрёстке имеет преимущество перед нерельсовыми транспортными средствами на равнозначной дороге независимо от направления движения, поэтому он проезжает первым, хотя и поворачивает налево ({p:16.12}). Велосипедист приближается справа, поэтому Вы уступаете и ему и проезжаете последним."},"ref":["1.10","16.12"],"pic":["img/hsc/16.2-46-1.jpg"]},{"id":"h16.2-47","t":"h16.2","num":"16.2.47","q":{"uk":"Ви проїдете дане перехрестя:","ru":"Вы проедете данный перекрёсток:"},"a":[{"uk":"Першим.","ru":"Первым.","w":{"uk":"Першим Ви не проїдете: трамвай має перевагу незалежно від напрямку руху, а білий автомобіль — праворуч від Вас.","ru":"Первым Вы не проедете: трамвай имеет преимущество независимо от направления движения, а белый автомобиль — справа от Вас."}},{"uk":"Після трамвая.","ru":"После трамвая.","w":{"uk":"Білий автомобіль праворуч теж має перевагу перед Вами, тож його також треба пропустити.","ru":"Белый автомобиль справа тоже имеет преимущество перед Вами, поэтому его также нужно пропустить."}},{"uk":"Після трамвая і білого автомобіля.","ru":"После трамвая и белого автомобиля."}],"c":2,"e":{"uk":"Трамвай, хоч і наближається ліворуч, має перевагу перед нерейковими транспортними засобами на рівнозначній дорозі ({p:16.12}), а білий автомобіль наближається праворуч. Тому Ви проїжджаєте після обох.","ru":"Трамвай, хотя и приближается слева, имеет преимущество перед нерельсовыми транспортными средствами на равнозначной дороге ({p:16.12}), а белый автомобиль приближается справа. Поэтому Вы проезжаете после обоих."},"ref":["16.12"],"pic":["img/hsc/16.2-47-1.jpg"]},{"id":"h16.2-48","t":"h16.2","num":"16.2.48","q":{"uk":"Яка черговість проїзду транспортних засобів на даному перехресті?","ru":"Какова очерёдность проезда транспортных средств на данном перекрёстке?"},"a":[{"uk":"Трамвай, синій, жовтий, ваш автомобілі.","ru":"Трамвай, синий, жёлтый, ваш автомобили.","w":{"uk":"Синій автомобіль ліворуч від Вас, тому має пропустити Вас, а жовтому не потрібно чекати ні синього, ні Вас.","ru":"Синий автомобиль слева от Вас, поэтому должен пропустить Вас, а жёлтому не нужно ждать ни синего, ни Вас."}},{"uk":"Жовтий, ваш автомобіль, трамвай, синій автомобілі.","ru":"Жёлтый, ваш автомобиль, трамвай, синий автомобили.","w":{"uk":"Трамвай має перевагу перед усіма нерейковими транспортними засобами, тож не може проїжджати після Вас.","ru":"Трамвай имеет преимущество перед всеми нерельсовыми транспортными средствами, поэтому не может проезжать после Вас."}},{"uk":"Трамвай одночасно з жовтим, ваш, синій автомобілі.","ru":"Трамвай одновременно с жёлтым, ваш, синий автомобили."}],"c":2,"e":{"uk":"Трамвай має перевагу перед нерейковими транспортними засобами ({p:16.12}), а жовтому автомобілю праворуч ніхто не заважає; їхні шляхи не перетинаються, тож вони проїжджають одночасно. Потім їдете Ви, а синій автомобіль ліворуч від Вас поступається Вам і рушає останнім.","ru":"Трамвай имеет преимущество перед нерельсовыми транспортными средствами ({p:16.12}), а жёлтому автомобилю справа никто не мешает; их пути не пересекаются, поэтому они проезжают одновременно. Затем едете Вы, а синий автомобиль слева от Вас уступает Вам и трогается последним."},"ref":["16.12"],"pic":["img/hsc/16.2-48-1.jpg"]},{"id":"h16.2-49","t":"h16.2","num":"16.2.49","q":{"uk":"Рухаючись прямо на даному перехресті, Ви повинні:","ru":"Двигаясь прямо на данном перекрёстке, Вы должны:"},"a":[{"uk":"Проїхати перехрестя першим, не даючи нікому дорогу.","ru":"Проехать перекрёсток первым, никому не уступая дорогу.","w":{"uk":"Трамвай має перевагу незалежно від того, куди він повертає, тож проїхати першим Ви не можете.","ru":"Трамвай имеет преимущество независимо от того, куда он поворачивает, поэтому проехать первым Вы не можете."}},{"uk":"Дати дорогу тільки трамваю.","ru":"Уступить дорогу только трамваю."},{"uk":"Проїхати перехрестя після трамвая і синього автомобіля.","ru":"Проехать перекрёсток после трамвая и синего автомобиля.","w":{"uk":"Синій автомобіль ліворуч від Вас, тому на рівнозначних дорогах поступається він.","ru":"Синий автомобиль слева от Вас, поэтому на равнозначных дорогах уступает он."}}],"c":1,"e":{"uk":"Зустрічний трамвай має перевагу перед нерейковими транспортними засобами на рівнозначній дорозі незалежно від напрямку руху, тож, хоч він і повертає ліворуч, Ви повинні його пропустити ({p:16.12}). Синій автомобіль наближається ліворуч і сам поступається Вам.","ru":"Встречный трамвай имеет преимущество перед нерельсовыми транспортными средствами на равнозначной дороге независимо от направления движения, поэтому, хотя он и поворачивает налево, Вы должны его пропустить ({p:16.12}). Синий автомобиль приближается слева и сам уступает Вам."},"ref":["16.12"],"pic":["img/hsc/16.2-49-1.jpg"]},{"id":"h16.2-50","t":"h16.2","num":"16.2.50","q":{"uk":"Проїжджаючи дане перехрестя, Ви повинні:","ru":"Проезжая данный перекрёсток, Вы должны:"},"a":[{"uk":"Проїхати перехрестя першим.","ru":"Проехать перекрёсток первым.","w":{"uk":"Червоний автомобіль праворуч має перевагу, тому першим проїжджає він.","ru":"Красный автомобиль справа имеет преимущество, поэтому первым проезжает он."}},{"uk":"Дати дорогу червоному автомобілю.","ru":"Уступить дорогу красному автомобилю."}],"c":1,"e":{"uk":"Знаків пріоритету немає, отже дороги рівнозначні, а червоний автомобіль наближається праворуч — за {p:16.12} Ви повинні дати йому дорогу.","ru":"Знаков приоритета нет, значит, дороги равнозначные, а красный автомобиль приближается справа — по {p:16.12} Вы должны уступить ему дорогу."},"ref":["16.12"],"pic":["img/hsc/16.2-50-1.jpg"]},{"id":"h16.2-51","t":"h16.2","num":"16.2.51","q":{"uk":"Яка черговість проїзду транспортних засобів на даному перехресті:","ru":"Какова очерёдность проезда транспортных средств на данном перекрёстке:"},"a":[{"uk":"Чорний, фіолетовий, білий, зелений автомобілі.","ru":"Чёрный, фиолетовый, белый, зелёный автомобили.","w":{"uk":"Чорний автомобіль рухається другорядною дорогою, тому має пропустити зелений і фіолетовий, що на головній.","ru":"Чёрный автомобиль движется по второстепенной дороге, поэтому должен пропустить зелёный и фиолетовый, которые на главной."}},{"uk":"Фіолетовий, чорний, білий, зелений автомобілі.","ru":"Фиолетовый, чёрный, белый, зелёный автомобили.","w":{"uk":"Фіолетовий автомобіль має пропустити зелений, який для нього праворуч на головній дорозі, а чорний на другорядній — обидва автомобілі на головній.","ru":"Фиолетовый автомобиль должен пропустить зелёный, который для него справа на главной дороге, а чёрный на второстепенной — оба автомобиля на главной."}},{"uk":"Зелений, фіолетовий, чорний, білий автомобілі.","ru":"Зелёный, фиолетовый, чёрный, белый автомобили."},{"uk":"Білий, зелений, фіолетовий, чорний автомобілі.","ru":"Белый, зелёный, фиолетовый, чёрный автомобили.","w":{"uk":"Білий автомобіль стоїть перед знаком {s:2.1} на другорядній дорозі і, крім автомобілів на головній, має пропустити чорний, що праворуч від нього.","ru":"Белый автомобиль стоит перед знаком {s:2.1} на второстепенной дороге и, кроме автомобилей на главной, должен пропустить чёрный, который справа от него."}}],"c":2,"e":{"uk":"Табличка {s:7.8} під знаком {s:2.1} показує, що головна дорога йде згори ліворуч, тож першими їдуть зелений і фіолетовий; між собою вони за {p:16.14} керуються правилами рівнозначних доріг, і фіолетовий пропускає зелений, бо той для нього праворуч. Потім другорядною дорогою: білий поступається чорному, який для нього праворуч.","ru":"Табличка {s:7.8} под знаком {s:2.1} показывает, что главная дорога идёт сверху налево, поэтому первыми едут зелёный и фиолетовый; между собой они по {p:16.14} руководствуются правилами равнозначных дорог, и фиолетовый пропускает зелёный, так как тот для него справа. Затем по второстепенной дороге: белый уступает чёрному, который для него справа."},"ref":["16.11","16.14","33.2","33.7"],"pic":["img/hsc/16.2-51-1.jpg"]},{"id":"h16.2-52","t":"h16.2","num":"16.2.52","q":{"uk":"Який транспортний засіб проїде перехрестя третім?","ru":"Какое транспортное средство проедет перекрёсток третьим?"},"a":[{"uk":"Трамвай.","ru":"Трамвай.","w":{"uk":"Трамвай рухається головною дорогою і має перевагу навіть перед синім автомобілем, тому проїжджає першим.","ru":"Трамвай движется по главной дороге и имеет преимущество даже перед синим автомобилем, поэтому проезжает первым."}},{"uk":"Синій автомобіль.","ru":"Синий автомобиль.","w":{"uk":"Синій автомобіль на головній дорозі поступається лише трамваю, тож проїжджає другим.","ru":"Синий автомобиль на главной дороге уступает только трамваю, поэтому проезжает вторым."}},{"uk":"Чорний автомобіль.","ru":"Чёрный автомобиль.","w":{"uk":"Чорний автомобіль на другорядній дорозі повертає ліворуч і мусить пропустити зустрічний білий, тому проїжджає останнім.","ru":"Чёрный автомобиль на второстепенной дороге поворачивает налево и обязан пропустить встречный белый, поэтому проезжает последним."}},{"uk":"Білий автомобіль.","ru":"Белый автомобиль."}],"c":3,"e":{"uk":"Головна дорога (знак {s:2.3}) йде знизу вгору, тому першими проїжджають трамвай і синій автомобіль: трамвай має перевагу перед нерейковими транспортними засобами на рівнозначній дорозі навіть під час повороту ліворуч ({p:16.12}), отже синій — другий. Далі другорядною дорогою: чорний повертає ліворуч і за {p:16.13} пропускає зустрічний білий, тож білий проїжджає третім.","ru":"Главная дорога (знак {s:2.3}) идёт снизу вверх, поэтому первыми проезжают трамвай и синий автомобиль: трамвай имеет преимущество перед нерельсовыми транспортными средствами на равнозначной дороге даже при повороте налево ({p:16.12}), значит, синий — второй. Далее по второстепенной дороге: чёрный поворачивает налево и по {p:16.13} пропускает встречный белый, поэтому белый проезжает третьим."},"ref":["16.11","16.12","16.13","33.2"],"pic":["img/hsc/16.2-52-1.jpg"]},{"id":"h16.2-53","t":"h16.2","num":"16.2.53","q":{"uk":"Який транспортний засіб проїде дане перехрестя другим?","ru":"Какое транспортное средство проедет данный перекрёсток вторым?"},"a":[{"uk":"Червоний автомобіль.","ru":"Красный автомобиль."},{"uk":"Білий автомобіль.","ru":"Белый автомобиль.","w":{"uk":"Білий автомобіль рухається головною дорогою, яка повертає ліворуч, тому проїжджає першим, а не другим.","ru":"Белый автомобиль движется по главной дороге, которая поворачивает налево, поэтому проезжает первым, а не вторым."}}],"c":0,"e":{"uk":"За табличками {s:7.8} головна дорога йде знизу ліворуч, і білий автомобіль, повертаючи ліворуч, рухається саме нею, тож проїжджає першим ({p:16.11}). Червоний автомобіль перед знаком {s:2.1} на другорядній дорозі і проїжджає другим.","ru":"По табличкам {s:7.8} главная дорога идёт снизу налево, и белый автомобиль, поворачивая налево, движется именно по ней, поэтому проезжает первым ({p:16.11}). Красный автомобиль перед знаком {s:2.1} на второстепенной дороге и проезжает вторым."},"ref":["16.11","33.2","33.7"],"pic":["img/hsc/16.2-53-1.jpg"]},{"id":"h16.2-54","t":"h16.2","num":"16.2.54","q":{"uk":"Як Ви повинні проїхати дане перехрестя?","ru":"Как Вы должны проехать данный перекрёсток?"},"a":[{"uk":"Дати дорогу фіолетовому автомобілю.","ru":"Уступить дорогу фиолетовому автомобилю."},{"uk":"Проїхати першим, не даючи дорогу фіолетовому автомобілю.","ru":"Проехать первым, не уступая дорогу фиолетовому автомобилю.","w":{"uk":"На перехресті з круговим рухом, позначеному знаком {s:4.10}, перевагу має той, хто вже рухається по колу, а не той, хто в'їжджає.","ru":"На перекрёстке с круговым движением, обозначенном знаком {s:4.10}, преимущество у того, кто уже движется по кругу, а не у въезжающего."}}],"c":0,"e":{"uk":"Перехрестя позначене знаком {s:4.10}, тож за {p:16.12} перевага належить транспортним засобам, які вже рухаються по колу. Фіолетовий автомобіль уже на колі, тому Ви повинні його пропустити.","ru":"Перекрёсток обозначен знаком {s:4.10}, поэтому по {p:16.12} преимущество принадлежит транспортным средствам, которые уже движутся по кругу. Фиолетовый автомобиль уже на кругу, поэтому Вы должны его пропустить."},"ref":["16.12"],"pic":["img/hsc/16.2-54-1.jpg"]},{"id":"h16.2-55","t":"h16.2","num":"16.2.55","q":{"uk":"Ви проїдете перехрестя:","ru":"Вы проедете перекрёсток:"},"a":[{"uk":"Першим.","ru":"Первым.","w":{"uk":"Перевага головної дороги не звільняє від обов'язку пропустити транспортний засіб з увімкненими синім маячком і спеціальним звуковим сигналом.","ru":"Преимущество главной дороги не освобождает от обязанности пропустить транспортное средство с включёнными синим маячком и специальным звуковым сигналом."}},{"uk":"Другим.","ru":"Вторым."},{"uk":"Третім.","ru":"Третьим.","w":{"uk":"Білий автомобіль на другорядній дорозі має пропустити Вас, тож Ви поступаєтеся лише поліцейському автомобілю.","ru":"Белый автомобиль на второстепенной дороге должен пропустить Вас, поэтому Вы уступаете только полицейскому автомобилю."}}],"c":1,"e":{"uk":"Ви на головній дорозі (знак {s:2.3}), тож білий автомобіль праворуч, що на другорядній, поступається Вам ({p:16.11}). Проте поліцейському автомобілю з увімкненими проблисковими маячками і спеціальним звуковим сигналом за {p:3.2} треба дати дорогу, тому Ви проїжджаєте другим.","ru":"Вы на главной дороге (знак {s:2.3}), поэтому белый автомобиль справа, находящийся на второстепенной, уступает Вам ({p:16.11}). Однако полицейскому автомобилю с включёнными проблесковыми маячками и специальным звуковым сигналом по {p:3.2} нужно уступить дорогу, поэтому Вы проезжаете вторым."},"ref":["3.2","16.11","33.2"],"pic":["img/hsc/16.2-55-1.jpg"]},{"id":"h16.2-56","t":"h16.2","num":"16.2.56","q":{"uk":"На даному перехресті водій коричневого автомобіля повинен:","ru":"На данном перекрёстке водитель коричневого автомобиля должен:"},"a":[{"uk":"Проїхати перехрестя першим.","ru":"Проехать перекрёсток первым.","w":{"uk":"Водій виїжджає з ґрунтової, тобто другорядної, дороги, тому права проїхати першим не має.","ru":"Водитель выезжает с грунтовой, то есть второстепенной, дороги, поэтому права проехать первым не имеет."}},{"uk":"Дати дорогу всім транспортним засобам, що рухаються по дорозі, на яку він в'їжджає.","ru":"Уступить дорогу всем транспортным средствам, движущимся по дороге, на которую он въезжает."}],"c":1,"e":{"uk":"Коричневий автомобіль виїжджає з ґрунтової дороги на дорогу з асфальтовим покриттям, а дорога з покриттям відносно ґрунтової є головною ({p:1.10}). Тому за {p:16.11} його водій повинен дати дорогу всім транспортним засобам на цій дорозі незалежно від напрямку їхнього руху.","ru":"Коричневый автомобиль выезжает с грунтовой дороги на дорогу с асфальтовым покрытием, а дорога с покрытием по отношению к грунтовой является главной ({p:1.10}). Поэтому по {p:16.11} его водитель должен уступить дорогу всем транспортным средствам на этой дороге независимо от направления их движения."},"ref":["1.10","16.11"],"pic":["img/hsc/16.2-56-1.jpg"]},{"id":"h16.2-57","t":"h16.2","num":"16.2.57","q":{"uk":"Як повинен вчинити водій синього автомобіля в даній ситуації?","ru":"Как должен поступить водитель синего автомобиля в данной ситуации?"},"a":[{"uk":"Не даючи дорогу трактору, проїхати першим.","ru":"Не уступая дорогу трактору, проехать первым."},{"uk":"Дати дорогу трактору і проїхати другим.","ru":"Уступить дорогу трактору и проехать вторым.","w":{"uk":"Трактор виїжджає з ґрунтової, тобто другорядної, дороги, тож поступатися має він, а не водій синього автомобіля.","ru":"Трактор выезжает с грунтовой, то есть второстепенной, дороги, поэтому уступать должен он, а не водитель синего автомобиля."}}],"c":0,"e":{"uk":"Синій автомобіль рухається дорогою з покриттям, а трактор — ґрунтовою; дорога з покриттям відносно ґрунтової є головною ({p:1.10}), тому за {p:16.11} трактор повинен дати дорогу синьому автомобілю.","ru":"Синий автомобиль движется по дороге с покрытием, а трактор — по грунтовой; дорога с покрытием по отношению к грунтовой является главной ({p:1.10}), поэтому по {p:16.11} трактор должен уступить дорогу синему автомобилю."},"ref":["1.10","16.11"],"pic":["img/hsc/16.2-57-1.jpg"]},{"id":"h16.2-58","t":"h16.2","num":"16.2.58","q":{"uk":"Під час руху прямо на даному перехресті Ви повинні:","ru":"Во время движения прямо на данном перекрёстке Вы должны:"},"a":[{"uk":"Проїхати перехрестя першим, не даючи дорогу трамваю.","ru":"Проехать перекрёсток первым, не уступая дорогу трамваю.","w":{"uk":"Трамвай має перевагу перед нерейковими транспортними засобами на рівнозначній дорозі незалежно від того, куди він повертає, тож першим проїжджає він.","ru":"Трамвай имеет преимущество перед нерельсовыми транспортными средствами на равнозначной дороге независимо от того, куда он поворачивает, поэтому первым проезжает он."}},{"uk":"Проїхати другим, давши дорогу трамваю.","ru":"Проехать вторым, уступив дорогу трамваю."}],"c":1,"e":{"uk":"Ви й зустрічний трамвай рухаєтеся однією головною дорогою (знак {s:2.3}), тобто рівнозначною одна для одного, а за {p:16.12} трамвай на нерегульованому перехресті має перевагу перед нерейковими транспортними засобами незалежно від напрямку руху. Тому, хоч трамвай і повертає ліворуч, Ви пропускаєте його.","ru":"Вы и встречный трамвай движетесь по одной главной дороге (знак {s:2.3}), то есть равнозначной друг для друга, а по {p:16.12} трамвай на нерегулируемом перекрёстке имеет преимущество перед нерельсовыми транспортными средствами независимо от направления движения. Поэтому, хотя трамвай и поворачивает налево, Вы пропускаете его."},"ref":["16.12","33.2"],"pic":["img/hsc/16.2-58-1.jpg"]},{"id":"h16.2-59","t":"h16.2","num":"16.2.59","q":{"uk":"На даному перехресті Ви повинні:","ru":"На данном перекрёстке Вы должны:"},"a":[{"uk":"Дати дорогу трамваю.","ru":"Уступить дорогу трамваю."},{"uk":"Проїхати першим, оскільки маєте перевагу в русі.","ru":"Проехать первым, так как имеете преимущество в движении.","w":{"uk":"Знак {s:2.3} дає перевагу лише перед транспортом на другорядних дорогах; трамвай рухається тією самою головною дорогою і має перевагу перед Вами.","ru":"Знак {s:2.3} даёт преимущество только перед транспортом на второстепенных дорогах; трамвай движется по той же главной дороге и имеет преимущество перед Вами."}}],"c":0,"e":{"uk":"Ви й трамвай ліворуч рухаєтеся однією головною дорогою (знак {s:2.3}), тож між собою ви рівнозначні, а трамвай за {p:16.12} має перевагу перед нерейковими транспортними засобами незалежно від напрямку руху. Він повертає праворуч, перетинаючи Ваш шлях, тому Ви повинні його пропустити.","ru":"Вы и трамвай слева движетесь по одной главной дороге (знак {s:2.3}), поэтому между собой вы равнозначны, а трамвай по {p:16.12} имеет преимущество перед нерельсовыми транспортными средствами независимо от направления движения. Он поворачивает направо, пересекая Ваш путь, поэтому Вы должны его пропустить."},"ref":["16.12","33.2"],"pic":["img/hsc/16.2-59-1.jpg"]},{"id":"h16.2-60","t":"h16.2","num":"16.2.60","q":{"uk":"Який транспортний засіб проїде перехрестя останнім?","ru":"Какое транспортное средство проедет перекрёсток последним?"},"a":[{"uk":"Трамвай.","ru":"Трамвай.","w":{"uk":"Трамвай на другорядній дорозі поступається лише автомобілям на головній, а перед жовтим і чорним має перевагу.","ru":"Трамвай на второстепенной дороге уступает только автомобилям на главной, а перед жёлтым и чёрным имеет преимущество."}},{"uk":"Жовтий автомобіль.","ru":"Жёлтый автомобиль."},{"uk":"Синій автомобіль.","ru":"Синий автомобиль.","w":{"uk":"Синій автомобіль рухається головною дорогою (знак {s:2.3}), тому проїжджає одним із перших.","ru":"Синий автомобиль движется по главной дороге (знак {s:2.3}), поэтому проезжает одним из первых."}},{"uk":"Чорний автомобіль.","ru":"Чёрный автомобиль.","w":{"uk":"Чорний автомобіль їде прямо, тому жовтий, повертаючи ліворуч йому назустріч, має його пропустити.","ru":"Чёрный автомобиль едет прямо, поэтому жёлтый, поворачивая налево ему навстречу, должен его пропустить."}},{"uk":"Білий автомобіль.","ru":"Белый автомобиль.","w":{"uk":"Білий автомобіль рухається головною дорогою, тож проїжджає одним із перших.","ru":"Белый автомобиль движется по главной дороге, поэтому проезжает одним из первых."}}],"c":1,"e":{"uk":"Головною дорогою (знак {s:2.3}) рухаються синій і білий автомобілі — вони проїжджають першими ({p:16.11}). Серед транспортних засобів на другорядній дорозі трамвай має перевагу перед нерейковими ({p:16.12}), а жовтий, повертаючи ліворуч, за {p:16.13} пропускає зустрічний чорний автомобіль, тому проїжджає останнім.","ru":"По главной дороге (знак {s:2.3}) движутся синий и белый автомобили — они проезжают первыми ({p:16.11}). Среди транспортных средств на второстепенной дороге трамвай имеет преимущество перед нерельсовыми ({p:16.12}), а жёлтый, поворачивая налево, по {p:16.13} пропускает встречный чёрный автомобиль, поэтому проезжает последним."},"ref":["16.11","16.12","16.13","33.2"],"pic":["img/hsc/16.2-60-1.jpg"]},{"id":"h16.2-61","t":"h16.2","num":"16.2.61","q":{"uk":"Яка черговість проїзду даного перехрестя?","ru":"Какова очерёдность проезда данного перекрёстка?"},"a":[{"uk":"Трамвай 1, трамвай 2, червоний, фіолетовий, зелений автомобілі.","ru":"Трамвай 1, трамвай 2, красный, фиолетовый, зелёный автомобили.","w":{"uk":"Трамвай 1 повертає ліворуч і за {p:16.13}, яким між собою керуються й водії трамваїв, має пропустити зустрічний трамвай 2.","ru":"Трамвай 1 поворачивает налево и по {p:16.13}, которым между собой руководствуются и водители трамваев, должен пропустить встречный трамвай 2."}},{"uk":"Трамвай 2, трамвай 1, червоний, зелений, фіолетовий автомобілі.","ru":"Трамвай 2, трамвай 1, красный, зелёный, фиолетовый автомобили."},{"uk":"Трамвай 2, трамвай 1, фіолетовий, червоний, зелений автомобілі.","ru":"Трамвай 2, трамвай 1, фиолетовый, красный, зелёный автомобили.","w":{"uk":"Фіолетовий автомобіль на другорядній дорозі (знак {s:2.1}) має пропустити всі транспортні засоби на головній, зокрема червоний автомобіль.","ru":"Фиолетовый автомобиль на второстепенной дороге (знак {s:2.1}) должен пропустить все транспортные средства на главной, в том числе красный автомобиль."}},{"uk":"Трамвай 2, червоний автомобіль, трамвай 1, фіолетовий, зелений автомобілі.","ru":"Трамвай 2, красный автомобиль, трамвай 1, фиолетовый, зелёный автомобили.","w":{"uk":"Трамвай 1 має перевагу перед нерейковим червоним автомобілем на тій самій головній дорозі, тож червоний проїжджає після обох трамваїв.","ru":"Трамвай 1 имеет преимущество перед нерельсовым красным автомобилем на той же главной дороге, поэтому красный проезжает после обоих трамваев."}}],"c":1,"e":{"uk":"Головна дорога (знаки {s:2.3}) йде згори вниз: на ній трамвай 1, повертаючи ліворуч, за {p:16.13} пропускає зустрічний трамвай 2, а червоний автомобіль поступається обом трамваям, які мають перевагу перед нерейковими транспортними засобами ({p:16.12}). Потім другорядною дорогою: фіолетовий, повертаючи ліворуч, пропускає зустрічний зелений, що повертає праворуч ({p:16.13}).","ru":"Главная дорога (знаки {s:2.3}) идёт сверху вниз: на ней трамвай 1, поворачивая налево, по {p:16.13} пропускает встречный трамвай 2, а красный автомобиль уступает обоим трамваям, которые имеют преимущество перед нерельсовыми транспортными средствами ({p:16.12}). Затем по второстепенной дороге: фиолетовый, поворачивая налево, пропускает встречный зелёный, поворачивающий направо ({p:16.13})."},"ref":["16.11","16.12","16.13","33.2"],"pic":["img/hsc/16.2-61-1.jpg"]},{"id":"h16.2-62","t":"h16.2","num":"16.2.62","q":{"uk":"Який транспортний засіб проїде перехрестя останнім?","ru":"Какое транспортное средство проедет перекрёсток последним?"},"a":[{"uk":"Жовтий автомобіль.","ru":"Жёлтый автомобиль.","w":{"uk":"Жовтий автомобіль, хоч і на другорядній дорозі, має перевагу перед сірим, який повертає ліворуч йому назустріч.","ru":"Жёлтый автомобиль, хотя и на второстепенной дороге, имеет преимущество перед серым, который поворачивает налево ему навстречу."}},{"uk":"Сірий автомобіль.","ru":"Серый автомобиль."},{"uk":"Зелений автомобіль.","ru":"Зелёный автомобиль.","w":{"uk":"Зелений автомобіль рухається головною дорогою (знак {s:2.3}), тож проїжджає раніше за автомобілі з другорядної.","ru":"Зелёный автомобиль движется по главной дороге (знак {s:2.3}), поэтому проезжает раньше автомобилей со второстепенной."}},{"uk":"Білий автомобіль.","ru":"Белый автомобиль.","w":{"uk":"Білий автомобіль рухається головною дорогою, тому має перевагу перед автомобілями на другорядній.","ru":"Белый автомобиль движется по главной дороге, поэтому имеет преимущество перед автомобилями на второстепенной."}}],"c":1,"e":{"uk":"Сірий автомобіль стоїть перед знаком {s:2.1}, тобто на другорядній дорозі, і мусить пропустити всіх на головній ({p:16.11}). До того ж він повертає ліворуч і за {p:16.13} поступається зустрічному жовтому автомобілю, що теж на другорядній дорозі, тому проїжджає останнім.","ru":"Серый автомобиль стоит перед знаком {s:2.1}, то есть на второстепенной дороге, и обязан пропустить всех на главной ({p:16.11}). К тому же он поворачивает налево и по {p:16.13} уступает встречному жёлтому автомобилю, который тоже на второстепенной дороге, поэтому проезжает последним."},"ref":["16.11","16.13","33.2"],"pic":["img/hsc/16.2-62-1.jpg"]},{"id":"h16.2-63","t":"h16.2","num":"16.2.63","q":{"uk":"Яка черговість проїзду даного перехрестя?","ru":"Какова очерёдность проезда данного перекрёстка?"},"a":[{"uk":"Зелений, сірий автомобіль.","ru":"Зелёный, серый автомобиль.","w":{"uk":"Зелений автомобіль лише в'їжджає на коло, тому має пропустити сірий, що вже рухається по ньому.","ru":"Зелёный автомобиль только въезжает на круг, поэтому должен пропустить серый, который уже движется по нему."}},{"uk":"Сірий, зелений автомобіль.","ru":"Серый, зелёный автомобиль."}],"c":1,"e":{"uk":"На перехресті з круговим рухом, позначеному знаком {s:4.10}, перевага належить тим, хто вже рухається по колу ({p:16.12}). Сірий автомобіль уже на колі, тому проїжджає першим, а зелений в'їжджає після нього.","ru":"На перекрёстке с круговым движением, обозначенном знаком {s:4.10}, преимущество принадлежит тем, кто уже движется по кругу ({p:16.12}). Серый автомобиль уже на кругу, поэтому проезжает первым, а зелёный въезжает после него."},"ref":["16.12"],"pic":["img/hsc/16.2-63-1.jpg"]},{"id":"h16.2-64","t":"h16.2","num":"16.2.64","q":{"uk":"Білий автомобіль проїде дане перехрестя:","ru":"Белый автомобиль проедет данный перекрёсток:"},"a":[{"uk":"Першим.","ru":"Первым."},{"uk":"Другим.","ru":"Вторым.","w":{"uk":"Ні сірий, ні синій автомобіль не мають переваги перед білим: обидва на другорядній дорозі.","ru":"Ни серый, ни синий автомобиль не имеют преимущества перед белым: оба на второстепенной дороге."}},{"uk":"Третім.","ru":"Третьим.","w":{"uk":"Білому автомобілю на головній дорозі нікого пропускати не треба, бо зустрічних транспортних засобів на ній немає.","ru":"Белому автомобилю на главной дороге никого пропускать не нужно, так как встречных транспортных средств на ней нет."}}],"c":0,"e":{"uk":"Білий автомобіль рухається головною дорогою (знак {s:2.3}), а сірий і синій стоять перед знаками {s:2.1} на другорядній. За {p:16.11} вони мусять пропустити білий автомобіль незалежно від напрямку його руху, тож він проїжджає першим, навіть повертаючи ліворуч.","ru":"Белый автомобиль движется по главной дороге (знак {s:2.3}), а серый и синий стоят перед знаками {s:2.1} на второстепенной. По {p:16.11} они обязаны пропустить белый автомобиль независимо от направления его движения, поэтому он проезжает первым, даже поворачивая налево."},"ref":["16.11","33.2"],"pic":["img/hsc/16.2-64-1.jpg"]},{"id":"h16.2-65","t":"h16.2","num":"16.2.65","q":{"uk":"На якому малюнку показано нерегульоване перехрестя (на малюнках 2 і 3 миготливий жовтий)?","ru":"На каком рисунке показан нерегулируемый перекрёсток (на рисунках 2 и 3 мигающий жёлтый)?"},"a":[{"uk":"На першому.","ru":"На первом.","w":{"uk":"На першому малюнку світлофор працює у звичайному режимі (горить зелений), тож перехрестя регульоване, і знаки пріоритету на ньому не діють.","ru":"На первом рисунке светофор работает в обычном режиме (горит зелёный), поэтому перекрёсток регулируемый, и знаки приоритета на нём не действуют."}},{"uk":"На другому.","ru":"На втором."},{"uk":"На третьому.","ru":"На третьем.","w":{"uk":"На третьому малюнку є регулювальник, а перехрестя, де черговість визначає регулювальник, є регульованим, навіть якщо світлофор мигає жовтим.","ru":"На третьем рисунке есть регулировщик, а перекрёсток, где очерёдность определяет регулировщик, является регулируемым, даже если светофор мигает жёлтым."}},{"uk":"На всіх малюнках.","ru":"На всех рисунках.","w":{"uk":"Лише на другому малюнку немає ні робочого світлофора, ні регулювальника.","ru":"Только на втором рисунке нет ни работающего светофора, ни регулировщика."}}],"c":1,"e":{"uk":"За {p:16.1} перехрестя вважається нерегульованим, коли світлофор вимкнений або працює в режимі миготливого жовтого сигналу і **немає регулювальника**. Так є лише на другому малюнку: на першому рух регулює зелений сигнал світлофора, а на третьому — регулювальник.","ru":"По {p:16.1} перекрёсток считается нерегулируемым, когда светофор выключен или работает в режиме мигающего жёлтого сигнала и **нет регулировщика**. Так только на втором рисунке: на первом движение регулирует зелёный сигнал светофора, а на третьем — регулировщик."},"ref":["16.1"],"pic":["img/hsc/16.2-65-1.jpg"]},{"id":"h16.2-66","t":"h16.2","num":"16.2.66","q":{"uk":"Як водій білого автомобіля, що наближається до перехрестя, повинен проїхати дане перехрестя?","ru":"Как водитель белого автомобиля, приближающегося к перекрёстку, должен проехать данный перекрёсток?"},"a":[{"uk":"Зупинитися перед дорожньою розміткою «Стоп-лінія» і далі продовжити рух, не даючи нікому дорогу.","ru":"Остановиться перед дорожной разметкой «Стоп-линия» и далее продолжить движение, никому не уступая дорогу.","w":{"uk":"Знак {s:2.2} вимагає не лише зупинитися, а й дати дорогу транспортним засобам на перехрещуваній дорозі.","ru":"Знак {s:2.2} требует не только остановиться, но и уступить дорогу транспортным средствам на пересекаемой дороге."}},{"uk":"Зупинитися перед дорожньою розміткою «Стоп-лінія», виконавши вимогу знака «Проїзд без зупинки заборонено».","ru":"Остановиться перед дорожной разметкой «Стоп-линия», выполнив требование знака «Проезд без остановки запрещён»."},{"uk":"Проїхати перехрестя без зупинки.","ru":"Проехать перекрёсток без остановки.","w":{"uk":"Знак {s:2.2} забороняє проїзд без зупинки перед стоп-лінією, а вимкнений світлофор не скасовує його дії.","ru":"Знак {s:2.2} запрещает проезд без остановки перед стоп-линией, а выключенный светофор не отменяет его действия."}}],"c":1,"e":{"uk":"Світлофор вимкнений, тож за {p:16.1} перехрестя нерегульоване і діє знак {s:2.2}: водій повинен зупинитися перед стоп-лінією {m:1.12} і дати дорогу транспортним засобам, що рухаються перехрещуваною дорогою ({p:33.2}).","ru":"Светофор выключен, поэтому по {p:16.1} перекрёсток нерегулируемый и действует знак {s:2.2}: водитель должен остановиться перед стоп-линией {m:1.12} и уступить дорогу транспортным средствам, движущимся по пересекаемой дороге ({p:33.2})."},"ref":["16.1","16.3","33.2"],"pic":["img/hsc/16.2-66-1.jpg"]},{"id":"h16.2-67","t":"h16.2","num":"16.2.67","q":{"uk":"Чи повинен водій автомобіля дати дорогу велосипедисту в даній ситуації?","ru":"Должен ли водитель автомобиля уступить дорогу велосипедисту в данной ситуации?"},"a":[{"uk":"Не повинен, оскільки їде по головній дорозі.","ru":"Не должен, так как едет по главной дороге.","w":{"uk":"Вимога {p:16.2} діє на будь-якому перехресті, зокрема й для водія, що рухається головною дорогою.","ru":"Требование {p:16.2} действует на любом перекрёстке, в том числе и для водителя, движущегося по главной дороге."}},{"uk":"Не повинен, тому що велосипедист рухається по велосипедній доріжці.","ru":"Не должен, потому что велосипедист движется по велосипедной дорожке.","w":{"uk":"Велосипедна доріжка не позбавляє велосипедиста переваги: він рухається прямо в попутному напрямку і перетинає проїзну частину, на яку повертає автомобіль.","ru":"Велосипедная дорожка не лишает велосипедиста преимущества: он движется прямо в попутном направлении и пересекает проезжую часть, на которую поворачивает автомобиль."}},{"uk":"Повинен дати дорогу.","ru":"Должен уступить дорогу."}],"c":2,"e":{"uk":"За {p:16.2} водій, повертаючи праворуч або ліворуч, повинен дати дорогу велосипедистам, які рухаються прямо в попутному напрямку. Велосипедист їде прямо й велосипедним переїздом перетинає дорогу, на яку повертає автомобіль, тому його треба пропустити.","ru":"По {p:16.2} водитель, поворачивая направо или налево, должен уступить дорогу велосипедистам, движущимся прямо в попутном направлении. Велосипедист едет прямо и по велосипедному переезду пересекает дорогу, на которую поворачивает автомобиль, поэтому его нужно пропустить."},"ref":["16.2"],"pic":["img/hsc/16.2-67-1.jpg"]},{"id":"h16.2-68","t":"h16.2","num":"16.2.68","q":{"uk":"Чи повинен водій білого автомобіля дати дорогу пішоходам, які переходять проїзну частину на перехресті по лінії продовження тротуару?","ru":"Должен ли водитель белого автомобиля уступить дорогу пешеходам, переходящим проезжую часть на перекрёстке по линии продолжения тротуара?"},"a":[{"uk":"Не повинен.","ru":"Не должен.","w":{"uk":"Головна дорога дає перевагу лише перед транспортними засобами, а пішоходам на проїзній частині, на яку повертає водій, він зобов'язаний поступитися.","ru":"Главная дорога даёт преимущество только перед транспортными средствами, а пешеходам на проезжей части, на которую поворачивает водитель, он обязан уступить."}},{"uk":"Повинен завжди.","ru":"Должен всегда."}],"c":1,"e":{"uk":"За {p:16.2} на будь-якому перехресті водій, повертаючи праворуч або ліворуч, повинен дати дорогу пішоходам, які переходять проїзну частину, на яку він повертає, — і те, що він рухається головною дорогою, цього не скасовує.","ru":"По {p:16.2} на любом перекрёстке водитель, поворачивая направо или налево, должен уступить дорогу пешеходам, переходящим проезжую часть, на которую он поворачивает, — и то, что он движется по главной дороге, этого не отменяет."},"ref":["16.2"],"pic":["img/hsc/16.2-68-1.jpg"]},{"id":"h16.2-69","t":"h16.2","num":"16.2.69","q":{"uk":"Хто з водіїв повинен дати дорогу пішоходам?","ru":"Кто из водителей должен уступить дорогу пешеходам?"},"a":[{"uk":"Обидва водії.","ru":"Оба водителя."},{"uk":"Тільки водій білого автомобіля.","ru":"Только водитель белого автомобиля.","w":{"uk":"Синій автомобіль повертає праворуч, а проїзну частину, на яку він в'їжджає, теж переходять пішоходи — він також мусить їх пропустити.","ru":"Синий автомобиль поворачивает направо, а проезжую часть, на которую он въезжает, тоже переходят пешеходы — он также обязан их пропустить."}},{"uk":"Тільки водій синього автомобіля.","ru":"Только водитель синего автомобиля.","w":{"uk":"Білий автомобіль повертає ліворуч на проїзну частину, яку переходять пішоходи, тож і він має дати їм дорогу.","ru":"Белый автомобиль поворачивает налево на проезжую часть, которую переходят пешеходы, поэтому и он должен уступить им дорогу."}}],"c":0,"e":{"uk":"Білий автомобіль повертає ліворуч, синій — праворуч, і проїзні частини, на які вони повертають, переходять пішоходи. За {p:16.2} (а на пішохідних переходах ще й за {p:18.1}) обидва водії повинні дати їм дорогу.","ru":"Белый автомобиль поворачивает налево, синий — направо, и проезжие части, на которые они поворачивают, переходят пешеходы. По {p:16.2} (а на пешеходных переходах ещё и по {p:18.1}) оба водителя должны уступить им дорогу."},"ref":["16.2","18.1"],"pic":["img/hsc/16.2-69-1.jpg"]},{"id":"h16.2-70","t":"h16.2","num":"16.2.70","q":{"uk":"Чи повинен водій білого автомобіля дати дорогу пішоходам, які переходять проїзну частину на перехресті по лінії продовження тротуару?","ru":"Должен ли водитель белого автомобиля уступить дорогу пешеходам, переходящим проезжую часть на перекрёстке по линии продолжения тротуара?"},"a":[{"uk":"Не повинен.","ru":"Не должен.","w":{"uk":"Знак {s:2.3} дає перевагу лише перед транспортними засобами на другорядній дорозі і не звільняє від обов'язку пропустити пішоходів під час повороту.","ru":"Знак {s:2.3} даёт преимущество только перед транспортными средствами на второстепенной дороге и не освобождает от обязанности пропустить пешеходов при повороте."}},{"uk":"Повинен завжди.","ru":"Должен всегда."}],"c":1,"e":{"uk":"Білий автомобіль повертає ліворуч, а за {p:16.2} водій, повертаючи, повинен дати дорогу пішоходам, які переходять проїзну частину, на яку він повертає, навіть якщо сам рухається головною дорогою.","ru":"Белый автомобиль поворачивает налево, а по {p:16.2} водитель при повороте должен уступить дорогу пешеходам, переходящим проезжую часть, на которую он поворачивает, даже если сам движется по главной дороге."},"ref":["16.2"],"pic":["img/hsc/16.2-70-1.jpg"]},{"id":"h16.2-71","t":"h16.2","num":"16.2.71","q":{"uk":"На якому з місць водій повинен зупинити свій транспортний засіб у разі зупинки для виконання вимоги дати дорогу?","ru":"В каком из мест водитель должен остановить своё транспортное средство в случае остановки для выполнения требования уступить дорогу?"},"a":[{"uk":"На місці А.","ru":"На месте А."},{"uk":"На місці Б.","ru":"На месте Б.","w":{"uk":"Місце Б розташоване за лінією {m:1.13}, а зупинятися треба перед нею.","ru":"Место Б расположено за линией {m:1.13}, а останавливаться нужно перед ней."}},{"uk":"На місці А чи Б.","ru":"На месте А или Б.","w":{"uk":"Правила визначають одне місце зупинки — перед розміткою {m:1.13}; зупинка за нею, на місці Б, порушує {p:16.3}.","ru":"Правила определяют одно место остановки — перед разметкой {m:1.13}; остановка за ней, на месте Б, нарушает {p:16.3}."}}],"c":0,"e":{"uk":"За {p:16.3}, коли треба надати перевагу транспортним засобам на перехрещуваній дорозі, водій зупиняється перед розміткою {m:1.13}, а якщо її немає — перед краєм перехрещуваної проїзної частини. Місце А розташоване перед лінією {m:1.13}, тож зупинятися слід саме там.","ru":"По {p:16.3}, когда нужно предоставить преимущество транспортным средствам на пересекаемой дороге, водитель останавливается перед разметкой {m:1.13}, а если её нет — перед краем пересекаемой проезжей части. Место А расположено перед линией {m:1.13}, поэтому останавливаться нужно именно там."},"ref":["16.3"],"pic":["img/hsc/16.2-71-1.jpg"]},{"id":"h16.2-72","t":"h16.2","num":"16.2.72","q":{"uk":"Чи може водій білого автомобіля виїхати на перехрестя в даній ситуації?","ru":"Может ли водитель белого автомобиля выехать на перекрёсток в данной ситуации?"},"a":[{"uk":"Може, тому що перебуває на головній дорозі.","ru":"Может, так как находится на главной дороге.","w":{"uk":"Перевага головної дороги не скасовує заборони {p:16.4} виїжджати на перехрестя, коли за ним затор.","ru":"Преимущество главной дороги не отменяет запрета {p:16.4} выезжать на перекрёсток, когда за ним затор."}},{"uk":"Не може, тому що, зупинившись, створить перешкоду для руху іншим транспортним засобам.","ru":"Не может, так как, остановившись, создаст помеху для движения другим транспортным средствам."},{"uk":"Може, тому що рухається прямо.","ru":"Может, так как движется прямо.","w":{"uk":"Заборона {p:16.4} стосується всіх напрямків руху, зокрема й руху прямо.","ru":"Запрет {p:16.4} касается всех направлений движения, в том числе и движения прямо."}}],"c":1,"e":{"uk":"За {p:16.4} забороняється виїжджати на будь-яке перехрестя, якщо утворився затор, який змусить водія зупинитися на ньому й створити перешкоду іншим транспортним засобам. За перехрестям у напрямку руху білого автомобіля стоїть колона, тож виїжджати не можна.","ru":"По {p:16.4} запрещается выезжать на любой перекрёсток, если образовался затор, который вынудит водителя остановиться на нём и создать помеху другим транспортным средствам. За перекрёстком в направлении движения белого автомобиля стоит колонна, поэтому выезжать нельзя."},"ref":["16.4"],"pic":["img/hsc/16.2-72-1.jpg"]},{"id":"h16.2-73","t":"h16.2","num":"16.2.73","q":{"uk":"Яка черговість проїзду транспортних засобів на даному перехресті?","ru":"Какова очерёдность проезда транспортных средств на данном перекрёстке?"},"a":[{"uk":"Трамвай, автомобіль.","ru":"Трамвай, автомобиль.","w":{"uk":"Трамвай має перевагу лише перед транспортом на рівнозначній дорозі; виїжджаючи з другорядної, він поступається автомобілю на головній.","ru":"Трамвай имеет преимущество только перед транспортом на равнозначной дороге; выезжая со второстепенной, он уступает автомобилю на главной."}},{"uk":"Автомобіль, трамвай.","ru":"Автомобиль, трамвай."}],"c":1,"e":{"uk":"Автомобіль рухається головною дорогою (знак {s:2.3}), а трамвай — другорядною (знак {s:2.1}). Перевага трамвая за {p:16.12} діє лише щодо транспорту на рівнозначній дорозі, тому тут він за {p:16.11} пропускає автомобіль.","ru":"Автомобиль движется по главной дороге (знак {s:2.3}), а трамвай — по второстепенной (знак {s:2.1}). Преимущество трамвая по {p:16.12} действует только по отношению к транспорту на равнозначной дороге, поэтому здесь он по {p:16.11} пропускает автомобиль."},"ref":["16.11","16.12","33.2"],"pic":["img/hsc/16.2-73-1.jpg"]},{"id":"h16.2-74","t":"h16.2","num":"16.2.74","q":{"uk":"Яка черговість проїзду на даному перехресті?","ru":"Какова очерёдность проезда на данном перекрёстке?"},"a":[{"uk":"Велосипедист, трамвай.","ru":"Велосипедист, трамвай."},{"uk":"Трамвай, велосипедист.","ru":"Трамвай, велосипедист.","w":{"uk":"Трамвай на другорядній дорозі не має переваги перед велосипедистом, який рухається головною.","ru":"Трамвай на второстепенной дороге не имеет преимущества перед велосипедистом, движущимся по главной."}},{"uk":"Залежить від швидкості транспортних засобів.","ru":"Зависит от скорости транспортных средств.","w":{"uk":"Черговість на нерегульованому перехресті визначають знаки пріоритету й Правила, а не швидкість транспортних засобів.","ru":"Очерёдность на нерегулируемом перекрёстке определяют знаки приоритета и Правила, а не скорость транспортных средств."}}],"c":0,"e":{"uk":"Велосипедист рухається головною дорогою (знак {s:2.3}), а трамвай — другорядною (знак {s:2.1}), тож за {p:16.11} трамвай має дати дорогу велосипедисту. Перевага трамвая за {p:16.12} діє лише щодо транспорту на рівнозначній дорозі.","ru":"Велосипедист движется по главной дороге (знак {s:2.3}), а трамвай — по второстепенной (знак {s:2.1}), поэтому по {p:16.11} трамвай должен уступить дорогу велосипедисту. Преимущество трамвая по {p:16.12} действует только по отношению к транспорту на равнозначной дороге."},"ref":["16.11","16.12","33.2"],"pic":["img/hsc/16.2-74-1.jpg"]},{"id":"h16.2-75","t":"h16.2","num":"16.2.75","q":{"uk":"Черговість проїзду даного перехрестя:","ru":"Очерёдность проезда данного перекрёстка:"},"a":[{"uk":"Синій автомобіль, зелений автомобіль, трамвай.","ru":"Синий автомобиль, зелёный автомобиль, трамвай.","w":{"uk":"Зелений автомобіль і трамвай на одній, другорядній дорозі, а трамвай має перевагу перед нерейковими транспортними засобами, тож зелений їде після нього.","ru":"Зелёный автомобиль и трамвай на одной, второстепенной дороге, а трамвай имеет преимущество перед нерельсовыми транспортными средствами, поэтому зелёный едет после него."}},{"uk":"Трамвай, синій автомобіль, зелений автомобіль.","ru":"Трамвай, синий автомобиль, зелёный автомобиль.","w":{"uk":"Трамвай на другорядній дорозі мусить пропустити синій автомобіль, що на головній.","ru":"Трамвай на второстепенной дороге обязан пропустить синий автомобиль, который на главной."}},{"uk":"Трамвай і зелений автомобіль, синій автомобіль.","ru":"Трамвай и зелёный автомобиль, синий автомобиль.","w":{"uk":"Синій автомобіль на головній дорозі має перевагу і перед трамваєм, і перед зеленим автомобілем, тому проїжджає першим.","ru":"Синий автомобиль на главной дороге имеет преимущество и перед трамваем, и перед зелёным автомобилем, поэтому проезжает первым."}},{"uk":"Синій автомобіль, трамвай, зелений автомобіль.","ru":"Синий автомобиль, трамвай, зелёный автомобиль."}],"c":3,"e":{"uk":"Синій автомобіль рухається головною дорогою (знак {s:2.3}), тож проїжджає першим ({p:16.11}). Трамвай і зелений автомобіль — на другорядній дорозі, і між ними перевагу має трамвай як рейковий транспортний засіб ({p:16.12}), тому далі їде трамвай, а потім зелений.","ru":"Синий автомобиль движется по главной дороге (знак {s:2.3}), поэтому проезжает первым ({p:16.11}). Трамвай и зелёный автомобиль — на второстепенной дороге, и между ними преимущество у трамвая как рельсового транспортного средства ({p:16.12}), поэтому далее едет трамвай, а затем зелёный."},"ref":["16.11","16.12","33.2"],"pic":["img/hsc/16.2-75-1.jpg"]},{"id":"h16.2-76","t":"h16.2","num":"16.2.76","q":{"uk":"Яка черговість проїзду автомобілів на даному перехресті?","ru":"Какова очерёдность проезда автомобилей на данном перекрёстке?"},"a":[{"uk":"Синій, білий, жовтий, зелений.","ru":"Синий, белый, жёлтый, зелёный.","w":{"uk":"Синій автомобіль повертає ліворуч, тому має пропустити зустрічний білий, що їде прямо.","ru":"Синий автомобиль поворачивает налево, поэтому должен пропустить встречный белый, едущий прямо."}},{"uk":"Жовтий, зелений, білий, синій.","ru":"Жёлтый, зелёный, белый, синий.","w":{"uk":"Жовтий і зелений автомобілі стоять перед знаками {s:2.1} на другорядній дорозі й мусять пропустити білий і синій, які рухаються головною.","ru":"Жёлтый и зелёный автомобили стоят перед знаками {s:2.1} на второстепенной дороге и обязаны пропустить белый и синий, движущиеся по главной."}},{"uk":"Білий, синій, жовтий, зелений.","ru":"Белый, синий, жёлтый, зелёный."},{"uk":"Білий, зелений, синій, жовтий.","ru":"Белый, зелёный, синий, жёлтый.","w":{"uk":"Зелений автомобіль на другорядній дорозі має пропустити синій, що на головній, а також жовтий, бо повертає ліворуч йому назустріч.","ru":"Зелёный автомобиль на второстепенной дороге должен пропустить синий, который на главной, а также жёлтый, так как поворачивает налево ему навстречу."}}],"c":2,"e":{"uk":"Головна дорога (знаки {s:2.3}) йде знизу вгору, тож першими їдуть білий і синій автомобілі; синій повертає ліворуч і за {p:16.13} пропускає зустрічний білий. Потім другорядною дорогою ({p:16.11}): зелений, повертаючи ліворуч, пропускає зустрічний жовтий, що повертає праворуч.","ru":"Главная дорога (знаки {s:2.3}) идёт снизу вверх, поэтому первыми едут белый и синий автомобили; синий поворачивает налево и по {p:16.13} пропускает встречный белый. Затем по второстепенной дороге ({p:16.11}): зелёный, поворачивая налево, пропускает встречный жёлтый, поворачивающий направо."},"ref":["16.11","16.13","33.2"],"pic":["img/hsc/16.2-76-1.jpg"]},{"id":"h16.2-77","t":"h16.2","num":"16.2.77","q":{"uk":"На даному перехресті, повертаючи ліворуч, необхідно:","ru":"На данном перекрёстке, поворачивая налево, необходимо:"},"a":[{"uk":"Дати дорогу всім автомобілям.","ru":"Уступить дорогу всем автомобилям.","w":{"uk":"Червоний і темний автомобілі ліворуч і праворуч рухаються другорядними дорогами, тому мають пропустити Вас.","ru":"Красный и тёмный автомобили слева и справа движутся по второстепенным дорогам, поэтому должны пропустить Вас."}},{"uk":"Дати дорогу тільки зустрічному автомобілю.","ru":"Уступить дорогу только встречному автомобилю."},{"uk":"Проїхати перехрестя першим.","ru":"Проехать перекрёсток первым.","w":{"uk":"Зустрічний автомобіль на тій самій головній дорозі їде прямо, і під час повороту ліворуч Ви мусите його пропустити.","ru":"Встречный автомобиль на той же главной дороге едет прямо, и при повороте налево Вы обязаны его пропустить."}}],"c":1,"e":{"uk":"Ви на головній дорозі (знак {s:2.3}), тож автомобілі ліворуч і праворуч на другорядних дорогах поступаються Вам ({p:16.11}). Але зустрічний автомобіль теж рухається головною дорогою, і, повертаючи ліворуч, Ви за {p:16.13} повинні дати йому дорогу.","ru":"Вы на главной дороге (знак {s:2.3}), поэтому автомобили слева и справа на второстепенных дорогах уступают Вам ({p:16.11}). Но встречный автомобиль тоже движется по главной дороге, и, поворачивая налево, Вы по {p:16.13} должны уступить ему дорогу."},"ref":["16.11","16.13","33.2"],"pic":["img/hsc/16.2-77-1.jpg"]},{"id":"h16.2-78","t":"h16.2","num":"16.2.78","q":{"uk":"Проїжджаючи дане перехрестя, Ви повинні:","ru":"Проезжая данный перекрёсток, Вы должны:"},"a":[{"uk":"Маючи перевагу, проїхати перехрестя першим.","ru":"Имея преимущество, проехать перекрёсток первым.","w":{"uk":"Знак {s:2.3} дає перевагу лише перед транспортом на другорядних дорогах; синій автомобіль на тій самій головній дорозі праворуч від Вас, тому перевага в нього.","ru":"Знак {s:2.3} даёт преимущество только перед транспортом на второстепенных дорогах; синий автомобиль на той же главной дороге справа от Вас, поэтому преимущество у него."}},{"uk":"Давши дорогу, проїхати перехрестя другим.","ru":"Уступив дорогу, проехать перекрёсток вторым."}],"c":1,"e":{"uk":"За табличкою {s:7.8} головна дорога повертає праворуч, а Ви повертаєте ліворуч, залишаючи її. Синій автомобіль праворуч теж на головній дорозі, тож між вами за {p:16.14} діють правила рівнозначних доріг, і Ви поступаєтеся йому як транспортному засобу праворуч ({p:16.12}).","ru":"По табличке {s:7.8} главная дорога поворачивает направо, а Вы поворачиваете налево, покидая её. Синий автомобиль справа тоже на главной дороге, поэтому между вами по {p:16.14} действуют правила равнозначных дорог, и Вы уступаете ему как транспортному средству справа ({p:16.12})."},"ref":["16.12","16.14","33.2","33.7"],"pic":["img/hsc/16.2-78-1.jpg"]},{"id":"h16.2-79","t":"h16.2","num":"16.2.79","q":{"uk":"Проїжджаючи дане перехрестя прямо, Ви повинні:","ru":"Проезжая данный перекрёсток прямо, Вы должны:"},"a":[{"uk":"Дати дорогу велосипедистові.","ru":"Уступить дорогу велосипедисту."},{"uk":"Не давати дорогу велосипедистові.","ru":"Не уступать дорогу велосипедисту.","w":{"uk":"Велосипедист рухається тією самою головною дорогою і наближається праворуч, тому має перевагу перед Вами.","ru":"Велосипедист движется по той же главной дороге и приближается справа, поэтому имеет преимущество перед Вами."}}],"c":0,"e":{"uk":"Головна дорога (табличка {s:7.8}) повертає праворуч, а велосипедист рухається нею праворуч від Вас. Між водіями на головній дорозі за {p:16.14} діють правила рівнозначних доріг, тож Ви, їдучи прямо, поступаєтеся велосипедистові праворуч ({p:16.12}).","ru":"Главная дорога (табличка {s:7.8}) поворачивает направо, а велосипедист движется по ней справа от Вас. Между водителями на главной дороге по {p:16.14} действуют правила равнозначных дорог, поэтому Вы, двигаясь прямо, уступаете велосипедисту справа ({p:16.12})."},"ref":["1.10","16.12","16.14","33.7"],"pic":["img/hsc/16.2-79-1.jpg"]},{"id":"h16.2-80","t":"h16.2","num":"16.2.80","q":{"uk":"Повертаючи ліворуч на даному перехресті, Ви повинні:","ru":"Поворачивая налево на данном перекрёстке, Вы должны:"},"a":[{"uk":"Дати дорогу тільки вантажному і білому автомобілям.","ru":"Уступить дорогу только грузовому и белому автомобилям.","w":{"uk":"Вантажний і білий автомобілі рухаються другорядними дорогами, тож мають пропустити Вас.","ru":"Грузовой и белый автомобили движутся по второстепенным дорогам, поэтому должны пропустить Вас."}},{"uk":"Дати дорогу тільки червоному автомобілю.","ru":"Уступить дорогу только красному автомобилю.","w":{"uk":"Червоний автомобіль на головній дорозі ліворуч від Вас, тож за правилами рівнозначних доріг поступається він.","ru":"Красный автомобиль на главной дороге слева от Вас, поэтому по правилам равнозначных дорог уступает он."}},{"uk":"Проїхати перехрестя першим.","ru":"Проехать перекрёсток первым."}],"c":2,"e":{"uk":"За табличкою {s:7.8} головна дорога повертає ліворуч, і Ви рухаєтеся саме нею, тож білий і вантажний автомобілі на другорядних дорогах поступаються Вам ({p:16.11}). Червоний автомобіль ліворуч теж на головній, але між вами діють правила рівнозначних доріг ({p:16.14}), і для нього Ви праворуч.","ru":"По табличке {s:7.8} главная дорога поворачивает налево, и Вы движетесь именно по ней, поэтому белый и грузовой автомобили на второстепенных дорогах уступают Вам ({p:16.11}). Красный автомобиль слева тоже на главной, но между вами действуют правила равнозначных дорог ({p:16.14}), и для него Вы справа."},"ref":["16.11","16.14","33.2","33.7"],"pic":["img/hsc/16.2-80-1.jpg"]},{"id":"h16.2-81","t":"h16.2","num":"16.2.81","q":{"uk":"Яка черговість проїзду транспортних засобів на даному перехресті?","ru":"Какова очерёдность проезда транспортных средств на данном перекрёстке?"},"a":[{"uk":"Трамвай, автомобіль.","ru":"Трамвай, автомобиль.","w":{"uk":"Трамвай на другорядній дорозі не має переваги перед автомобілем на головній.","ru":"Трамвай на второстепенной дороге не имеет преимущества перед автомобилем на главной."}},{"uk":"Автомобіль, трамвай.","ru":"Автомобиль, трамвай."},{"uk":"Залежить від швидкості руху транспортних засобів.","ru":"Зависит от скорости движения транспортных средств.","w":{"uk":"Черговість визначають знаки пріоритету й Правила, а не швидкість транспортних засобів.","ru":"Очерёдность определяют знаки приоритета и Правила, а не скорость транспортных средств."}}],"c":1,"e":{"uk":"За табличками {s:7.8} головна дорога йде знизу ліворуч: синій автомобіль, повертаючи ліворуч, рухається нею, а трамвай стоїть перед знаком {s:2.1} на другорядній. Перевага трамвая за {p:16.12} діє лише на рівнозначних дорогах, тож тут він за {p:16.11} пропускає автомобіль.","ru":"По табличкам {s:7.8} главная дорога идёт снизу налево: синий автомобиль, поворачивая налево, движется по ней, а трамвай стоит перед знаком {s:2.1} на второстепенной. Преимущество трамвая по {p:16.12} действует только на равнозначных дорогах, поэтому здесь он по {p:16.11} пропускает автомобиль."},"ref":["16.11","16.12","33.2","33.7"],"pic":["img/hsc/16.2-81-1.jpg"]},{"id":"h16.2-82","t":"h16.2","num":"16.2.82","q":{"uk":"Повертаючи ліворуч на даному перехресті, Ви повинні:","ru":"Поворачивая налево на данном перекрёстке, Вы должны:"},"a":[{"uk":"Дати дорогу трамваю.","ru":"Уступить дорогу трамваю.","w":{"uk":"Трамвай праворуч рухається другорядною дорогою, а Ви — головною, тож поступається він.","ru":"Трамвай справа движется по второстепенной дороге, а Вы — по главной, поэтому уступает он."}},{"uk":"Проїхати перехрестя першим.","ru":"Проехать перекрёсток первым."}],"c":1,"e":{"uk":"Табличка {s:7.8} показує, що головна дорога повертає ліворуч, і Ви рухаєтеся саме нею, а трамвай праворуч — на другорядній дорозі. Тому за {p:16.11} трамвай має пропустити Вас: його перевага за {p:16.12} діє лише на рівнозначних дорогах.","ru":"Табличка {s:7.8} показывает, что главная дорога поворачивает налево, и Вы движетесь именно по ней, а трамвай справа — на второстепенной дороге. Поэтому по {p:16.11} трамвай должен пропустить Вас: его преимущество по {p:16.12} действует только на равнозначных дорогах."},"ref":["16.11","16.12","33.2","33.7"],"pic":["img/hsc/16.2-82-1.jpg"]},{"id":"h16.2-83","t":"h16.2","num":"16.2.83","q":{"uk":"Повертаючи ліворуч на даному перехресті, Ви повинні:","ru":"Поворачивая налево на данном перекрёстке, Вы должны:"},"a":[{"uk":"Дати дорогу тільки транспортному засобу з увімкненим проблисковим маячком синього кольору.","ru":"Уступить дорогу только транспортному средству с включённым проблесковым маячком синего цвета.","w":{"uk":"Сірий автомобіль рухається тією самою головною дорогою і наближається праворуч, тому йому теж треба дати дорогу.","ru":"Серый автомобиль движется по той же главной дороге и приближается справа, поэтому ему тоже нужно уступить дорогу."}},{"uk":"Дати дорогу транспортному засобу з увімкненим проблисковим маячком синього кольору та сірому автомобілю.","ru":"Уступить дорогу транспортному средству с включённым проблесковым маячком синего цвета и серому автомобилю."}],"c":1,"e":{"uk":"Автомобілю швидкої допомоги з увімкненими синім маячком і спеціальним звуковим сигналом треба дати дорогу за {p:3.2}. Крім того, головна дорога (табличка {s:7.8}) повертає праворуч, а Ви з неї повертаєте ліворуч, тож із сірим автомобілем праворуч, який теж на головній, ви роз'їжджаєтеся за правилами рівнозначних доріг ({p:16.14}), і перевага в нього.","ru":"Автомобилю скорой помощи с включёнными синим маячком и специальным звуковым сигналом нужно уступить дорогу по {p:3.2}. Кроме того, главная дорога (табличка {s:7.8}) поворачивает направо, а Вы с неё поворачиваете налево, поэтому с серым автомобилем справа, который тоже на главной, вы разъезжаетесь по правилам равнозначных дорог ({p:16.14}), и преимущество у него."},"ref":["3.2","16.12","16.14","33.2","33.7"],"pic":["img/hsc/16.2-83-1.jpg"]},{"id":"h16.2-84","t":"h16.2","num":"16.2.84","q":{"uk":"Проїжджаючи дане перехрестя, водій сірого автомобіля повинен:","ru":"Проезжая данный перекрёсток, водитель серого автомобиля должен:"},"a":[{"uk":"Дати дорогу обом автомобілям.","ru":"Уступить дорогу обоим автомобилям.","w":{"uk":"Обидва автомобілі мають пропустити сірий: зелений — бо на другорядній дорозі, чорний — бо сірий для нього праворуч.","ru":"Оба автомобиля должны пропустить серый: зелёный — так как на второстепенной дороге, чёрный — так как серый для него справа."}},{"uk":"Дати дорогу тільки зеленому автомобілю.","ru":"Уступить дорогу только зелёному автомобилю.","w":{"uk":"Зелений автомобіль стоїть перед знаком {s:2.1} на другорядній дорозі, тож має пропустити сірий.","ru":"Зелёный автомобиль стоит перед знаком {s:2.1} на второстепенной дороге, поэтому должен пропустить серый."}},{"uk":"Проїхати перехрестя першим.","ru":"Проехать перекрёсток первым."}],"c":2,"e":{"uk":"За табличкою {s:7.8} головна дорога йде знизу ліворуч, і сірий автомобіль, повертаючи ліворуч, рухається нею. Зелений автомобіль на другорядній дорозі (знак {s:2.1}) поступається йому ({p:16.11}), а чорний, теж на головній, за {p:16.14} пропускає сірий, бо той для нього праворуч.","ru":"По табличке {s:7.8} главная дорога идёт снизу налево, и серый автомобиль, поворачивая налево, движется по ней. Зелёный автомобиль на второстепенной дороге (знак {s:2.1}) уступает ему ({p:16.11}), а чёрный, тоже на главной, по {p:16.14} пропускает серый, так как тот для него справа."},"ref":["16.11","16.14","33.2","33.7"],"pic":["img/hsc/16.2-84-1.jpg"]},{"id":"h16.2-85","t":"h16.2","num":"16.2.85","q":{"uk":"Яка черговість проїзду транспортних засобів на даному перехресті?","ru":"Какова очерёдность проезда транспортных средств на данном перекрёстке?"},"a":[{"uk":"Сірий, зелений, червоний автомобілі.","ru":"Серый, зелёный, красный автомобили.","w":{"uk":"Червоний автомобіль на головній дорозі не може їхати після зеленого, що на другорядній; до того ж сірий має пропустити червоний.","ru":"Красный автомобиль на главной дороге не может ехать после зелёного, который на второстепенной; к тому же серый должен пропустить красный."}},{"uk":"Червоний, сірий, зелений автомобілі.","ru":"Красный, серый, зелёный автомобили."},{"uk":"Сірий, червоний, зелений автомобілі.","ru":"Серый, красный, зелёный автомобили.","w":{"uk":"Сірий і червоний обидва на головній дорозі, і червоний для сірого праворуч, тому сірий має його пропустити.","ru":"Серый и красный оба на главной дороге, и красный для серого справа, поэтому серый должен его пропустить."}}],"c":1,"e":{"uk":"За табличками {s:7.8} головна дорога йде знизу ліворуч: червоний автомобіль рухається нею, повертаючи ліворуч, а сірий наближається нею ж зліва. Між ними за {p:16.14} діють правила рівнозначних доріг, тож сірий пропускає червоний, який для нього праворуч; зелений на другорядній дорозі (знак {s:2.1}) проїжджає останнім ({p:16.11}).","ru":"По табличкам {s:7.8} главная дорога идёт снизу налево: красный автомобиль движется по ней, поворачивая налево, а серый приближается по ней же слева. Между ними по {p:16.14} действуют правила равнозначных дорог, поэтому серый пропускает красный, который для него справа; зелёный на второстепенной дороге (знак {s:2.1}) проезжает последним ({p:16.11})."},"ref":["16.11","16.14","33.2","33.7"],"pic":["img/hsc/16.2-85-1.jpg"]},{"id":"h16.2-86","t":"h16.2","num":"16.2.86","q":{"uk":"Рухаючись прямо на цьому перехресті, Ви повинні:","ru":"Двигаясь прямо на этом перекрёстке, Вы должны:"},"a":[{"uk":"Проїхати перехрестя першим.","ru":"Проехать перекрёсток первым.","w":{"uk":"Чорний автомобіль на головній дорозі праворуч від Вас, тож має перевагу.","ru":"Чёрный автомобиль на главной дороге справа от Вас, поэтому имеет преимущество."}},{"uk":"Проїхати перехрестя останнім, давши дорогу обом автомобілям.","ru":"Проехать перекрёсток последним, уступив дорогу обоим автомобилям.","w":{"uk":"Синій зустрічний автомобіль рухається другорядною дорогою, тому поступається Вам.","ru":"Синий встречный автомобиль движется по второстепенной дороге, поэтому уступает Вам."}},{"uk":"Проїхати перехрестя другим, давши дорогу тільки чорному автомобілю.","ru":"Проехать перекрёсток вторым, уступив дорогу только чёрному автомобилю."}],"c":2,"e":{"uk":"Головна дорога (табличка {s:7.8}) повертає праворуч, а Ви їдете прямо, залишаючи її. Чорний автомобіль праворуч теж на головній, тож за {p:16.14} Ви поступаєтеся йому як транспортному засобу праворуч, а синій зустрічний на другорядній дорозі сам пропускає Вас ({p:16.11}).","ru":"Главная дорога (табличка {s:7.8}) поворачивает направо, а Вы едете прямо, покидая её. Чёрный автомобиль справа тоже на главной, поэтому по {p:16.14} Вы уступаете ему как транспортному средству справа, а синий встречный на второстепенной дороге сам пропускает Вас ({p:16.11})."},"ref":["16.11","16.14","33.2","33.7"],"pic":["img/hsc/16.2-86-1.jpg"]},{"id":"h16.2-87","t":"h16.2","num":"16.2.87","q":{"uk":"Повертаючи ліворуч на даному перехресті, Ви повинні:","ru":"Поворачивая налево на данном перекрёстке, Вы должны:"},"a":[{"uk":"Дати дорогу автомобілю з увімкненими проблисковими маячками.","ru":"Уступить дорогу автомобилю с включёнными проблесковыми маячками.","w":{"uk":"Синій автомобіль рухається тією самою головною дорогою праворуч від Вас, тому йому теж треба дати дорогу.","ru":"Синий автомобиль движется по той же главной дороге справа от Вас, поэтому ему тоже нужно уступить дорогу."}},{"uk":"Дати дорогу обом транспортним засобам.","ru":"Уступить дорогу обоим транспортным средствам."}],"c":1,"e":{"uk":"Поліцейському автомобілю з увімкненими проблисковими маячками і спеціальним звуковим сигналом треба дати дорогу за {p:3.2}. Головна дорога (табличка {s:7.8}) повертає праворуч, а Ви з неї повертаєте ліворуч, тож синій автомобіль праворуч, теж на головній, має перед Вами перевагу за {p:16.14}.","ru":"Полицейскому автомобилю с включёнными проблесковыми маячками и специальным звуковым сигналом нужно уступить дорогу по {p:3.2}. Главная дорога (табличка {s:7.8}) поворачивает направо, а Вы с неё поворачиваете налево, поэтому синий автомобиль справа, тоже на главной, имеет перед Вами преимущество по {p:16.14}."},"ref":["3.2","16.12","16.14","33.2","33.7"],"pic":["img/hsc/16.2-87-1.jpg"]},{"id":"h16.2-88","t":"h16.2","num":"16.2.88","q":{"uk":"Яка черговість проїзду автомобілів на даному перехресті?","ru":"Какова очерёдность проезда автомобилей на данном перекрёстке?"},"a":[{"uk":"Зелений, синій, червоний автомобілі.","ru":"Зелёный, синий, красный автомобили.","w":{"uk":"Синій автомобіль для зеленого праворуч, тож зелений має його пропустити.","ru":"Синий автомобиль для зелёного справа, поэтому зелёный должен его пропустить."}},{"uk":"Червоний, зелений, синій автомобілі.","ru":"Красный, зелёный, синий автомобили.","w":{"uk":"Червоний автомобіль на другорядній дорозі мусить пропустити обидва автомобілі на головній.","ru":"Красный автомобиль на второстепенной дороге обязан пропустить оба автомобиля на главной."}},{"uk":"Синій, зелений, червоний автомобілі.","ru":"Синий, зелёный, красный автомобили."}],"c":2,"e":{"uk":"Головна дорога (знаки {s:2.3} з табличками {s:7.8}) йде знизу праворуч, тож першими їдуть зелений і синій, а червоний перед знаком {s:2.1} чекає ({p:16.11}). Між собою зелений і синій за {p:16.14} керуються правилами рівнозначних доріг: синій для зеленого праворуч, тому проїжджає першим.","ru":"Главная дорога (знаки {s:2.3} с табличками {s:7.8}) идёт снизу направо, поэтому первыми едут зелёный и синий, а красный перед знаком {s:2.1} ждёт ({p:16.11}). Между собой зелёный и синий по {p:16.14} руководствуются правилами равнозначных дорог: синий для зелёного справа, поэтому проезжает первым."},"ref":["16.11","16.14","33.2","33.7"],"pic":["img/hsc/16.2-88-1.jpg"]},{"id":"h16.2-89","t":"h16.2","num":"16.2.89","q":{"uk":"Яка черговість проїзду автомобілями даного перехрестя?","ru":"Какова очерёдность проезда автомобилями данного перекрёстка?"},"a":[{"uk":"Синій, червоний, білий автомобілі.","ru":"Синий, красный, белый автомобили.","w":{"uk":"Синій автомобіль на другорядній дорозі мусить пропустити обидва автомобілі на головній.","ru":"Синий автомобиль на второстепенной дороге обязан пропустить оба автомобиля на главной."}},{"uk":"Білий, червоний, синій автомобілі.","ru":"Белый, красный, синий автомобили."},{"uk":"Червоний, білий, синій автомобілі.","ru":"Красный, белый, синий автомобили.","w":{"uk":"Білий автомобіль для червоного праворуч, тож червоний має його пропустити.","ru":"Белый автомобиль для красного справа, поэтому красный должен его пропустить."}}],"c":1,"e":{"uk":"Головна дорога (знаки {s:2.3} з табличками {s:7.8}) йде знизу ліворуч, тож першими їдуть білий і червоний, а синій перед знаком {s:2.1} чекає ({p:16.11}). Між собою вони за {p:16.14} керуються правилами рівнозначних доріг: білий для червоного праворуч, тому проїжджає першим.","ru":"Главная дорога (знаки {s:2.3} с табличками {s:7.8}) идёт снизу налево, поэтому первыми едут белый и красный, а синий перед знаком {s:2.1} ждёт ({p:16.11}). Между собой они по {p:16.14} руководствуются правилами равнозначных дорог: белый для красного справа, поэтому проезжает первым."},"ref":["16.11","16.14","33.2","33.7"],"pic":["img/hsc/16.2-89-1.jpg"]},{"id":"h16.2-90","t":"h16.2","num":"16.2.90","q":{"uk":"Водій синього автомобіля проїде дане перехрестя:","ru":"Водитель синего автомобиля проедет данный перекрёсток:"},"a":[{"uk":"Першим.","ru":"Первым.","w":{"uk":"Синій автомобіль стоїть перед знаком {s:2.1} на другорядній дорозі, тому першим проїхати не може.","ru":"Синий автомобиль стоит перед знаком {s:2.1} на второстепенной дороге, поэтому первым проехать не может."}},{"uk":"Другим.","ru":"Вторым.","w":{"uk":"Перед синім автомобілем проїжджають усі три транспортні засоби на головній дорозі.","ru":"Перед синим автомобилем проезжают все три транспортных средства на главной дороге."}},{"uk":"Третім.","ru":"Третьим.","w":{"uk":"Крім транспорту на головній дорозі, синій має пропустити трамвай на своїй дорозі, що має перевагу перед нерейковими транспортними засобами.","ru":"Кроме транспорта на главной дороге, синий должен пропустить трамвай на своей дороге, имеющий преимущество перед нерельсовыми транспортными средствами."}},{"uk":"Четвертим.","ru":"Четвёртым.","w":{"uk":"Повертаючи ліворуч, синій поступається ще й зустрічному темному автомобілю, тож проїжджає не четвертим, а останнім.","ru":"Поворачивая налево, синий уступает ещё и встречному тёмному автомобилю, поэтому проезжает не четвёртым, а последним."}},{"uk":"Останнім.","ru":"Последним."}],"c":4,"e":{"uk":"Головна дорога (знаки {s:2.3}) йде зліва направо, тож спершу проїжджають трамвай, мотоцикл і зелений автомобіль ({p:16.11}). На другорядній дорозі трамвай має перевагу перед нерейковими транспортними засобами ({p:16.12}), а синій автомобіль, повертаючи ліворуч, за {p:16.13} пропускає ще й зустрічний темний автомобіль, тому проїжджає останнім.","ru":"Главная дорога (знаки {s:2.3}) идёт слева направо, поэтому сначала проезжают трамвай, мотоцикл и зелёный автомобиль ({p:16.11}). На второстепенной дороге трамвай имеет преимущество перед нерельсовыми транспортными средствами ({p:16.12}), а синий автомобиль, поворачивая налево, по {p:16.13} пропускает ещё и встречный тёмный автомобиль, поэтому проезжает последним."},"ref":["16.11","16.12","16.13","33.2"],"pic":["img/hsc/16.2-90-1.jpg"]},{"id":"h16.2-91","t":"h16.2","num":"16.2.91","q":{"uk":"Повертаючи ліворуч на даному перехресті, Ви повинні:","ru":"Поворачивая налево на данном перекрёстке, Вы должны:"},"a":[{"uk":"Проїхати перехрестя першим.","ru":"Проехать перекрёсток первым.","w":{"uk":"Зустрічний велосипедист їде прямо, тож, повертаючи ліворуч, Ви мусите його пропустити.","ru":"Встречный велосипедист едет прямо, поэтому, поворачивая налево, Вы обязаны его пропустить."}},{"uk":"Дати дорогу тільки велосипедистові і проїхати перехрестя другим.","ru":"Уступить дорогу только велосипедисту и проехать перекрёсток вторым."},{"uk":"Проїхати перехрестя останнім.","ru":"Проехать перекрёсток последним.","w":{"uk":"Фіолетовий автомобіль на другорядній дорозі має пропустити Вас, тож останнім Ви не будете.","ru":"Фиолетовый автомобиль на второстепенной дороге должен пропустить Вас, поэтому последним Вы не будете."}}],"c":1,"e":{"uk":"Ви на головній дорозі (знак {s:2.3}), тож фіолетовий автомобіль праворуч, що на другорядній, поступається Вам ({p:16.11}). Зустрічний велосипедист їде тією самою головною дорогою прямо, і під час повороту ліворуч Ви за {p:16.13} повинні його пропустити, тому проїжджаєте другим.","ru":"Вы на главной дороге (знак {s:2.3}), поэтому фиолетовый автомобиль справа, находящийся на второстепенной, уступает Вам ({p:16.11}). Встречный велосипедист едет по той же главной дороге прямо, и при повороте налево Вы по {p:16.13} должны его пропустить, поэтому проезжаете вторым."},"ref":["16.11","16.13","33.2"],"pic":["img/hsc/16.2-91-1.jpg"]},{"id":"h16.2-92","t":"h16.2","num":"16.2.92","q":{"uk":"Яка черговість проїзду транспортних засобів на даному перехресті?","ru":"Какова очерёдность проезда транспортных средств на данном перекрёстке?"},"a":[{"uk":"Білий, синій автомобілі, велосипед, червоний автомобілі.","ru":"Белый, синий автомобили, велосипед, красный автомобиль.","w":{"uk":"Синій автомобіль на другорядній дорозі мусить пропустити червоний, що на головній, а також зустрічного велосипедиста.","ru":"Синий автомобиль на второстепенной дороге обязан пропустить красный, который на главной, а также встречного велосипедиста."}},{"uk":"Білий, червоний автомобілі, велосипед, синій автомобілі.","ru":"Белый, красный автомобили, велосипед, синий автомобиль."},{"uk":"Білий, червоний, синій автомобілі, велосипед.","ru":"Белый, красный, синий автомобили, велосипед.","w":{"uk":"Синій автомобіль повертає ліворуч і має пропустити зустрічного велосипедиста, який їде прямо, тож велосипедист проїжджає раніше.","ru":"Синий автомобиль поворачивает налево и должен пропустить встречного велосипедиста, едущего прямо, поэтому велосипедист проезжает раньше."}}],"c":1,"e":{"uk":"Головна дорога (знаки {s:2.3}) йде знизу вгору: білий автомобіль їде прямо і проїжджає першим, а червоний, повертаючи ліворуч, за {p:16.13} пропускає його. Потім другорядною дорогою ({p:16.11}): синій, повертаючи ліворуч, пропускає зустрічного велосипедиста, що їде прямо.","ru":"Главная дорога (знаки {s:2.3}) идёт снизу вверх: белый автомобиль едет прямо и проезжает первым, а красный, поворачивая налево, по {p:16.13} пропускает его. Затем по второстепенной дороге ({p:16.11}): синий, поворачивая налево, пропускает встречного велосипедиста, едущего прямо."},"ref":["1.10","16.11","16.13","33.2"],"pic":["img/hsc/16.2-92-1.jpg"]},{"id":"h16.2-93","t":"h16.2","num":"16.2.93","q":{"uk":"Яка черговість проїзду транспортних засобів на даному перехресті?","ru":"Какова очерёдность проезда транспортных средств на данном перекрёстке?"},"a":[{"uk":"Легковий автомобіль, трамвай, мотоцикл.","ru":"Легковой автомобиль, трамвай, мотоцикл.","w":{"uk":"Легковий автомобіль на другорядній дорозі має пропустити трамвай і мотоцикл, що рухаються головною.","ru":"Легковой автомобиль на второстепенной дороге должен пропустить трамвай и мотоцикл, движущиеся по главной."}},{"uk":"Мотоцикл, трамвай, легковий автомобіль.","ru":"Мотоцикл, трамвай, легковой автомобиль.","w":{"uk":"Повертаючи ліворуч, мотоцикліст за {p:16.13} зобов'язаний пропустити трамвай попутного напрямку.","ru":"Поворачивая налево, мотоциклист по {p:16.13} обязан пропустить трамвай попутного направления."}},{"uk":"Трамвай, мотоцикл, легковий автомобіль.","ru":"Трамвай, мотоцикл, легковой автомобиль."},{"uk":"Трамвай, легковий автомобіль, мотоцикл.","ru":"Трамвай, легковой автомобиль, мотоцикл.","w":{"uk":"Легковий автомобіль на другорядній дорозі поступається й мотоциклу, що рухається головною дорогою.","ru":"Легковой автомобиль на второстепенной дороге уступает и мотоциклу, движущемуся по главной дороге."}}],"c":2,"e":{"uk":"Трамвай і мотоцикл рухаються головною дорогою (знак {s:2.3}), а легковий автомобіль — другорядною (знак {s:2.1}), тож він проїжджає останнім ({p:16.11}). Мотоцикл повертає ліворуч і за {p:16.13} має дати дорогу трамваю попутного напрямку, тому першим проїжджає трамвай.","ru":"Трамвай и мотоцикл движутся по главной дороге (знак {s:2.3}), а легковой автомобиль — по второстепенной (знак {s:2.1}), поэтому он проезжает последним ({p:16.11}). Мотоцикл поворачивает налево и по {p:16.13} должен уступить дорогу трамваю попутного направления, поэтому первым проезжает трамвай."},"ref":["16.11","16.13","33.2"],"pic":["img/hsc/16.2-93-1.jpg"]},{"id":"h16.2-94","t":"h16.2","num":"16.2.94","q":{"uk":"Як Ви проїдете дане перехрестя?","ru":"Как Вы проедете данный перекрёсток?"},"a":[{"uk":"Першим, нікому не даючи дорогу.","ru":"Первым, никому не уступая дорогу.","w":{"uk":"Повертаючи ліворуч, Ви мусите пропустити зустрічний червоний автомобіль, що рухається тією самою головною дорогою прямо.","ru":"Поворачивая налево, Вы обязаны пропустить встречный красный автомобиль, движущийся по той же главной дороге прямо."}},{"uk":"Останнім, давши дорогу червоному і синьому автомобілям.","ru":"Последним, уступив дорогу красному и синему автомобилям.","w":{"uk":"Синій автомобіль ліворуч на другорядній дорозі, тому поступається він, а не Ви.","ru":"Синий автомобиль слева на второстепенной дороге, поэтому уступает он, а не Вы."}},{"uk":"Другим, давши дорогу тільки червоному автомобілю.","ru":"Вторым, уступив дорогу только красному автомобилю."}],"c":2,"e":{"uk":"Ви на головній дорозі (знак {s:2.3}), тож синій автомобіль ліворуч, що на другорядній, пропускає Вас ({p:16.11}). Червоний зустрічний автомобіль теж на головній дорозі й їде прямо, тому, повертаючи ліворуч, Ви за {p:16.13} поступаєтеся йому.","ru":"Вы на главной дороге (знак {s:2.3}), поэтому синий автомобиль слева, находящийся на второстепенной, пропускает Вас ({p:16.11}). Красный встречный автомобиль тоже на главной дороге и едет прямо, поэтому, поворачивая налево, Вы по {p:16.13} уступаете ему."},"ref":["16.11","16.13","33.2"],"pic":["img/hsc/16.2-94-1.jpg"]},{"id":"h16.2-95","t":"h16.2","num":"16.2.95","q":{"uk":"Яка черговість проїзду транспортних засобів на даному перехресті?","ru":"Какова очерёдность проезда транспортных средств на данном перекрёстке?"},"a":[{"uk":"Синій, жовтий, фіолетовий.","ru":"Синий, жёлтый, фиолетовый.","w":{"uk":"Синій автомобіль повертає ліворуч і має пропустити зустрічний жовтий.","ru":"Синий автомобиль поворачивает налево и должен пропустить встречный жёлтый."}},{"uk":"Жовтий, синій, фіолетовий.","ru":"Жёлтый, синий, фиолетовый."},{"uk":"Жовтий, фіолетовий, синій.","ru":"Жёлтый, фиолетовый, синий.","w":{"uk":"Фіолетовий автомобіль на другорядній дорозі мусить пропустити й синій, що на головній.","ru":"Фиолетовый автомобиль на второстепенной дороге обязан пропустить и синий, который на главной."}},{"uk":"Фіолетовий, жовтий, синій.","ru":"Фиолетовый, жёлтый, синий.","w":{"uk":"Фіолетовий автомобіль на другорядній дорозі не може проїхати раніше за автомобілі на головній.","ru":"Фиолетовый автомобиль на второстепенной дороге не может проехать раньше автомобилей на главной."}}],"c":1,"e":{"uk":"Жовтий і синій автомобілі рухаються головною дорогою (знаки {s:2.3}), а фіолетовий стоїть перед знаком {s:2.1} і проїжджає останнім ({p:16.11}). Синій повертає ліворуч, тому за {p:16.13} пропускає зустрічний жовтий.","ru":"Жёлтый и синий автомобили движутся по главной дороге (знаки {s:2.3}), а фиолетовый стоит перед знаком {s:2.1} и проезжает последним ({p:16.11}). Синий поворачивает налево, поэтому по {p:16.13} пропускает встречный жёлтый."},"ref":["16.11","16.13","33.2"],"pic":["img/hsc/16.2-95-1.jpg"]},{"id":"h16.2-96","t":"h16.2","num":"16.2.96","q":{"uk":"Як велосипедист, що повертає ліворуч, проїде дане перехрестя?","ru":"Как велосипедист, поворачивающий налево, проедет данный перекрёсток?"},"a":[{"uk":"Проїде першим.","ru":"Проедет первым.","w":{"uk":"Повертаючи ліворуч, велосипедист перетинає шлях зустрічного автомобіля, тому має його пропустити.","ru":"Поворачивая налево, велосипедист пересекает путь встречного автомобиля, поэтому должен его пропустить."}},{"uk":"Проїде, давши дорогу автомобілю.","ru":"Проедет, уступив дорогу автомобилю."},{"uk":"Велосипедисту заборонено повертати наліво в даній ситуації.","ru":"Велосипедисту запрещено поворачивать налево в данной ситуации.","w":{"uk":"Правила не забороняють велосипедисту повертати ліворуч у такій ситуації — він лише має пропустити зустрічний транспорт.","ru":"Правила не запрещают велосипедисту поворачивать налево в такой ситуации — он лишь должен пропустить встречный транспорт."}}],"c":1,"e":{"uk":"Велосипедист і білий автомобіль рухаються однією головною дорогою (знаки {s:2.3}) назустріч один одному. Велосипедист виконує вимоги Правил, що стосуються водіїв ({p:6.6}), тож, повертаючи ліворуч, за {p:16.13} має пропустити зустрічний автомобіль, що їде прямо.","ru":"Велосипедист и белый автомобиль движутся по одной главной дороге (знаки {s:2.3}) навстречу друг другу. Велосипедист выполняет требования Правил, касающиеся водителей ({p:6.6}), поэтому, поворачивая налево, по {p:16.13} должен пропустить встречный автомобиль, едущий прямо."},"ref":["6.6","16.13"],"pic":["img/hsc/16.2-96-1.jpg"]},{"id":"h16.2-97","t":"h16.2","num":"16.2.97","q":{"uk":"Повертаючи ліворуч на даному перехресті, Ви повинні:","ru":"Поворачивая налево на данном перекрёстке, Вы должны:"},"a":[{"uk":"Проїхати перехрестя першим.","ru":"Проехать перекрёсток первым.","w":{"uk":"Головна дорога не дає Вам переваги перед зустрічними транспортними засобами на ній самій: трамвай і червоний автомобіль треба пропустити.","ru":"Главная дорога не даёт Вам преимущества перед встречными транспортными средствами на ней же: трамвай и красный автомобиль нужно пропустить."}},{"uk":"Дати дорогу трамваю і після нього повернути ліворуч.","ru":"Уступить дорогу трамваю и после него повернуть налево.","w":{"uk":"Крім трамвая, Ви повинні пропустити зустрічний червоний автомобіль, що їде прямо.","ru":"Кроме трамвая, Вы должны пропустить встречный красный автомобиль, едущий прямо."}},{"uk":"Дати дорогу трамваю і червоному автомобілю, а після цього повернути ліворуч.","ru":"Уступить дорогу трамваю и красному автомобилю, а после этого повернуть налево."}],"c":2,"e":{"uk":"Ви, зустрічні трамвай і червоний автомобіль рухаєтеся однією головною дорогою (знак {s:2.3}). Трамвай має перевагу перед нерейковими транспортними засобами незалежно від напрямку руху ({p:16.12}), а червоний автомобіль їде назустріч прямо, і, повертаючи ліворуч, Ви за {p:16.13} повинні пропустити й його.","ru":"Вы, встречные трамвай и красный автомобиль движетесь по одной главной дороге (знак {s:2.3}). Трамвай имеет преимущество перед нерельсовыми транспортными средствами независимо от направления движения ({p:16.12}), а красный автомобиль едет навстречу прямо, и, поворачивая налево, Вы по {p:16.13} должны пропустить и его."},"ref":["16.12","16.13","33.2"],"pic":["img/hsc/16.2-97-1.jpg"]},{"id":"h16.2-98","t":"h16.2","num":"16.2.98","q":{"uk":"Проїжджаючи дане перехрестя, Ви повинні:","ru":"Проезжая данный перекрёсток, Вы должны:"},"a":[{"uk":"Маючи перевагу в русі, проїхати перехрестя першим.","ru":"Имея преимущество в движении, проехать перекрёсток первым.","w":{"uk":"Знак {s:2.3} дає перевагу лише перед транспортом на другорядній дорозі, а трамвай на тій самій головній має перевагу перед Вами.","ru":"Знак {s:2.3} даёт преимущество только перед транспортом на второстепенной дороге, а трамвай на той же главной имеет преимущество перед Вами."}},{"uk":"Дати дорогу тільки трамваю.","ru":"Уступить дорогу только трамваю."},{"uk":"Дати дорогу трамваю й автомобілю.","ru":"Уступить дорогу трамваю и автомобилю.","w":{"uk":"Білий автомобіль виїжджає з другорядної дороги, тож має пропустити Вас.","ru":"Белый автомобиль выезжает со второстепенной дороги, поэтому должен пропустить Вас."}}],"c":1,"e":{"uk":"Трамвай ліворуч рухається тією самою головною дорогою (знак {s:2.3}) і повертає праворуч, перетинаючи Ваш шлях; за {p:16.12} він має перевагу перед нерейковими транспортними засобами незалежно від напрямку руху. Білий автомобіль праворуч на другорядній дорозі сам поступається Вам ({p:16.11}).","ru":"Трамвай слева движется по той же главной дороге (знак {s:2.3}) и поворачивает направо, пересекая Ваш путь; по {p:16.12} он имеет преимущество перед нерельсовыми транспортными средствами независимо от направления движения. Белый автомобиль справа на второстепенной дороге сам уступает Вам ({p:16.11})."},"ref":["16.11","16.12","33.2"],"pic":["img/hsc/16.2-98-1.jpg"]},{"id":"h16.2-99","t":"h16.2","num":"16.2.99","q":{"uk":"Ви повинні проїхати дане перехрестя:","ru":"Вы должны проехать данный перекрёсток:"},"a":[{"uk":"Першим.","ru":"Первым.","w":{"uk":"Перевага головної дороги не звільняє від обов'язку пропустити швидку зі спеціальними сигналами, а повертаючи ліворуч, Ви ще й поступаєтеся зустрічному сірому автомобілю.","ru":"Преимущество главной дороги не освобождает от обязанности пропустить скорую со специальными сигналами, а поворачивая налево, Вы ещё и уступаете встречному серому автомобилю."}},{"uk":"Проїхати після транспортного засобу з увімкненим проблисковим маячком синього кольору та сірого автомобіля.","ru":"Проехать после транспортного средства с включённым проблесковым маячком синего цвета и серого автомобиля."},{"uk":"Проїхати перехрестя останнім.","ru":"Проехать перекрёсток последним.","w":{"uk":"Автомобіль праворуч стоїть на другорядній дорозі, тож він має пропустити Вас, і останнім Ви не будете.","ru":"Автомобиль справа стоит на второстепенной дороге, поэтому он должен пропустить Вас, и последним Вы не будете."}}],"c":1,"e":{"uk":"Автомобілю швидкої допомоги з увімкненими синім маячком і спеціальним звуковим сигналом треба дати дорогу за {p:3.2}, а зустрічному сірому автомобілю, що їде головною дорогою прямо, Ви поступаєтеся під час повороту ліворуч ({p:16.13}). Темний автомобіль праворуч на другорядній дорозі пропускає Вас ({p:16.11}).","ru":"Автомобилю скорой помощи с включёнными синим маячком и специальным звуковым сигналом нужно уступить дорогу по {p:3.2}, а встречному серому автомобилю, едущему по главной дороге прямо, Вы уступаете при повороте налево ({p:16.13}). Тёмный автомобиль справа на второстепенной дороге пропускает Вас ({p:16.11})."},"ref":["3.2","16.11","16.13","33.2"],"pic":["img/hsc/16.2-99-1.jpg"]},{"id":"h16.2-100","t":"h16.2","num":"16.2.100","q":{"uk":"Повертаючи ліворуч на даному перехресті, Ви повинні:","ru":"Поворачивая налево на данном перекрёстке, Вы должны:"},"a":[{"uk":"Проїхати перехрестя першим.","ru":"Проехать перекрёсток первым.","w":{"uk":"Велосипедист рухається головною дорогою праворуч від Вас, тож має перевагу.","ru":"Велосипедист движется по главной дороге справа от Вас, поэтому имеет преимущество."}},{"uk":"Проїхати перехрестя після велосипедиста.","ru":"Проехать перекрёсток после велосипедиста."},{"uk":"Проїхати після велосипедиста і червоного автомобіля.","ru":"Проехать после велосипедиста и красного автомобиля.","w":{"uk":"Червоний автомобіль на другорядній дорозі (знак {s:2.1}) має пропустити Вас.","ru":"Красный автомобиль на второстепенной дороге (знак {s:2.1}) должен пропустить Вас."}}],"c":1,"e":{"uk":"Табличка {s:7.8} показує, що головна дорога повертає праворуч, а Ви повертаєте ліворуч, залишаючи її. Велосипедист праворуч теж на головній дорозі, тож за {p:16.14} Ви поступаєтеся йому як транспортному засобу праворуч, а червоний автомобіль перед знаком {s:2.1} на другорядній дорозі пропускає Вас ({p:16.11}).","ru":"Табличка {s:7.8} показывает, что главная дорога поворачивает направо, а Вы поворачиваете налево, покидая её. Велосипедист справа тоже на главной дороге, поэтому по {p:16.14} Вы уступаете ему как транспортному средству справа, а красный автомобиль перед знаком {s:2.1} на второстепенной дороге пропускает Вас ({p:16.11})."},"ref":["16.11","16.14","33.2","33.7"],"pic":["img/hsc/16.2-100-1.jpg"]},{"id":"h16.2-101","t":"h16.2","num":"16.2.101","q":{"uk":"Яке перехрестя вважається нерегульованим?","ru":"Какой перекрёсток считается нерегулируемым?"},"a":[{"uk":"Перехрестя, де світлофор вимкнений або працює в режимі миготіння жовтого сигналу.","ru":"Перекрёсток, где светофор выключен или работает в режиме мигания жёлтого сигнала.","w":{"uk":"Це лише один із випадків: нерегульованими є й перехрестя без світлофорів і регулювальника, і ті, де черговість визначають знаки пріоритету.","ru":"Это лишь один из случаев: нерегулируемыми являются и перекрёстки без светофоров и регулировщика, и те, где очерёдность определяют знаки приоритета."}},{"uk":"Перехрестя, де немає світлофорів і відсутній регулювальник.","ru":"Перекрёсток, где нет светофоров и отсутствует регулировщик.","w":{"uk":"Це лише один із випадків: нерегульованим є й перехрестя з вимкненим або миготливим жовтим світлофором.","ru":"Это лишь один из случаев: нерегулируемым является и перекрёсток с выключенным или мигающим жёлтым светофором."}},{"uk":"Перехрестя, де черговість проїзду регулюється тільки дорожніми знаками пріоритету.","ru":"Перекрёсток, где очерёдность проезда регулируется только дорожными знаками приоритета.","w":{"uk":"Це лише один із випадків: нерегульованими є й перехрестя з вимкненим або миготливим жовтим світлофором, і ті, де немає ні світлофора, ні регулювальника.","ru":"Это лишь один из случаев: нерегулируемыми являются и перекрёстки с выключенным или мигающим жёлтым светофором, и те, где нет ни светофора, ни регулировщика."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2.","w":{"uk":"Відповідь неповна: перехрестя, де черговість визначають лише знаки пріоритету, теж нерегульоване.","ru":"Ответ неполный: перекрёсток, где очерёдность определяют только знаки приоритета, тоже нерегулируемый."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3."}],"c":4,"e":{"uk":"Регульованим за {p:16.1} є лише перехрестя, де черговість визначають сигнали світлофора чи регулювальника. Отже, нерегульованим є кожне з перелічених: де світлофор вимкнений або мигає жовтим (і немає регулювальника), де немає ні світлофорів, ні регулювальника, і де черговість визначають лише знаки пріоритету.","ru":"Регулируемым по {p:16.1} является только перекрёсток, где очерёдность определяют сигналы светофора или регулировщика. Значит, нерегулируемым является каждый из перечисленных: где светофор выключен или мигает жёлтым (и нет регулировщика), где нет ни светофоров, ни регулировщика, и где очерёдность определяют только знаки приоритета."},"ref":["16.1"]},{"id":"h16.2-102","t":"h16.2","num":"16.2.102","q":{"uk":"Якщо Ви рухаєтесь прямо, чи повинні Ви пропустити транспортні засоби, що наближатимуться ліворуч?","ru":"Если Вы движетесь прямо, должны ли Вы пропустить транспортные средства, которые будут приближаться слева?"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"Правило «перешкоди праворуч» діє лише на рівнозначних дорогах; перед знаком {s:2.1} треба пропустити транспорт на головній дорозі з обох боків.","ru":"Правило «помехи справа» действует только на равнозначных дорогах; перед знаком {s:2.1} нужно пропустить транспорт на главной дороге с обеих сторон."}}],"c":0,"e":{"uk":"Перед перехрестям установлено знак {s:2.1}, тобто Ви на другорядній дорозі. За {p:16.11} водій на другорядній дорозі дає дорогу всім транспортним засобам, що наближаються головною, — і праворуч, і ліворуч, незалежно від напрямку їхнього руху.","ru":"Перед перекрёстком установлен знак {s:2.1}, то есть Вы на второстепенной дороге. По {p:16.11} водитель на второстепенной дороге уступает дорогу всем транспортным средствам, приближающимся по главной, — и справа, и слева, независимо от направления их движения."},"ref":["16.11","33.2"],"pic":["img/hsc/16.2-102-1.jpg"]},{"id":"h16.2-103","t":"h16.2","num":"16.2.103","q":{"uk":"В наведеній ситуації, за відсутності знаків пріоритету, який транспортний засіб проїде перехрестя останнім?","ru":"В приведённой ситуации, при отсутствии знаков приоритета, какое транспортное средство проедет перекрёсток последним?"},"a":[{"uk":"Сірий автомобіль.","ru":"Серый автомобиль.","w":{"uk":"Сірий автомобіль для Вас праворуч, тож проїжджає раніше за Вас, одразу після синього.","ru":"Серый автомобиль для Вас справа, поэтому проезжает раньше Вас, сразу после синего."}},{"uk":"Синій автомобіль.","ru":"Синий автомобиль.","w":{"uk":"Синьому автомобілю праворуч ніхто не заважає, тому він проїжджає першим.","ru":"Синему автомобилю справа никто не мешает, поэтому он проезжает первым."}},{"uk":"Ваш автомобіль.","ru":"Ваш автомобиль."}],"c":2,"e":{"uk":"Без знаків пріоритету дороги рівнозначні ({p:16.12}): Ви поступаєтеся сірому автомобілю, що праворуч, а сірий — синьому зустрічному, бо той для нього праворуч. Синьому праворуч ніхто не заважає, тож черговість така: синій, сірий, Ви — останнім.","ru":"Без знаков приоритета дороги равнозначные ({p:16.12}): Вы уступаете серому автомобилю, который справа, а серый — синему встречному, так как тот для него справа. Синему справа никто не мешает, поэтому очерёдность такая: синий, серый, Вы — последним."},"ref":["16.12"],"pic":["img/hsc/16.2-103-1.jpg"]},{"id":"h16.2-104","t":"h16.2","num":"16.2.104","q":{"uk":"В наведеній ситуації, за відсутності знаків пріоритету, який транспортний засіб проїде перехрестя першим?","ru":"В приведённой ситуации, при отсутствии знаков приоритета, какое транспортное средство проедет перекрёсток первым?"},"a":[{"uk":"Сірий автомобіль.","ru":"Серый автомобиль.","w":{"uk":"Сірий автомобіль має пропустити синій, який для нього праворуч.","ru":"Серый автомобиль должен пропустить синий, который для него справа."}},{"uk":"Синій автомобіль.","ru":"Синий автомобиль."},{"uk":"Ваш автомобіль.","ru":"Ваш автомобиль.","w":{"uk":"Ви повинні пропустити сірий автомобіль праворуч, тож першим проїхати не можете.","ru":"Вы должны пропустить серый автомобиль справа, поэтому первым проехать не можете."}}],"c":1,"e":{"uk":"Без знаків пріоритету дороги рівнозначні ({p:16.12}): сірий автомобіль має пропустити синій зустрічний, бо той для нього праворуч, а Ви — сірий, що праворуч від Вас. Синьому праворуч ніхто не заважає, тож він проїжджає першим.","ru":"Без знаков приоритета дороги равнозначные ({p:16.12}): серый автомобиль должен пропустить синий встречный, так как тот для него справа, а Вы — серый, который справа от Вас. Синему справа никто не мешает, поэтому он проезжает первым."},"ref":["16.12"],"pic":["img/hsc/16.2-104-1.jpg"]},{"id":"h16.2-105","t":"h16.2","num":"16.2.105","q":{"uk":"Ви повинні керуватись правилом проїзду нерегульованих перехресть та установленими на перехресті відповідними дорожніми знаками, якщо наближаєтесь до світлофора, який працює в режимі миготіння жовтого сигналу?","ru":"Должны ли Вы руководствоваться правилами проезда нерегулируемых перекрёстков и установленными на перекрёстке соответствующими дорожными знаками, если приближаетесь к светофору, работающему в режиме мигания жёлтого сигнала?"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"Миготливий жовтий сигнал не регулює черговість проїзду, тому діють правила нерегульованих перехресть і знаки пріоритету.","ru":"Мигающий жёлтый сигнал не регулирует очерёдность проезда, поэтому действуют правила нерегулируемых перекрёстков и знаки приоритета."}}],"c":0,"e":{"uk":"За {p:16.1}, коли світлофор працює в режимі миготіння жовтого сигналу і регулювальника немає, перехрестя вважається нерегульованим, тож водії керуються правилами проїзду нерегульованих перехресть і встановленими там знаками пріоритету.","ru":"По {p:16.1}, когда светофор работает в режиме мигания жёлтого сигнала и регулировщика нет, перекрёсток считается нерегулируемым, поэтому водители руководствуются правилами проезда нерегулируемых перекрёстков и установленными там знаками приоритета."},"ref":["16.1"],"pic":["img/hsc/16.2-105-1.jpg"]},{"id":"h16.2-106","t":"h16.2","num":"16.2.106","q":{"uk":"Чи дозволено Вам повернути праворуч у даному випадку?","ru":"Разрешено ли Вам повернуть направо в данном случае?"},"a":[{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"Знак {s:3.21} на дорозі праворуч забороняє туди в'їжджати.","ru":"Знак {s:3.21} на дороге справа запрещает туда въезжать."}},{"uk":"Дозволено, пропустивши пішохода.","ru":"Разрешено, пропустив пешехода.","w":{"uk":"Пропуск пішохода не скасовує заборони знака {s:3.21}: повертати праворуч не можна взагалі.","ru":"Пропуск пешехода не отменяет запрета знака {s:3.21}: поворачивать направо нельзя вообще."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":2,"e":{"uk":"На в'їзді на дорогу праворуч установлено знак {s:3.21}, який забороняє в'їзд усіх транспортних засобів ({p:33.3}), тож повертати праворуч не можна.","ru":"На въезде на дорогу справа установлен знак {s:3.21}, который запрещает въезд всех транспортных средств ({p:33.3}), поэтому поворачивать направо нельзя."},"ref":["33.3"],"pic":["img/hsc/16.2-106-1.jpg"]},{"id":"h16.2-107","t":"h16.2","num":"16.2.107","q":{"uk":"Чи дозволено Вам повернути ліворуч у даному випадку?","ru":"Разрешено ли Вам повернуть налево в данном случае?"},"a":[{"uk":"Дозволено","ru":"Разрешено.","w":{"uk":"Знак {s:4.2} дозволяє рух тільки в напрямку, показаному стрілкою, — праворуч.","ru":"Знак {s:4.2} разрешает движение только в направлении, указанном стрелкой, — направо."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":1,"e":{"uk":"Під знаком {s:2.1} установлено знак {s:4.2}, який дозволяє рух лише праворуч ({p:33.4}), тож повертати ліворуч заборонено.","ru":"Под знаком {s:2.1} установлен знак {s:4.2}, который разрешает движение только направо ({p:33.4}), поэтому поворачивать налево запрещено."},"ref":["33.4"],"pic":["img/hsc/16.2-107-1.jpg"]},{"id":"h16.2-108","t":"h16.2","num":"16.2.108","q":{"uk":"В даному випадку Вам дозволено повернути лише праворуч?","ru":"В данном случае Вам разрешено повернуть только направо?"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"Знак {s:4.2} забороняє будь-який інший напрямок руху, крім показаного стрілкою праворуч.","ru":"Знак {s:4.2} запрещает любое другое направление движения, кроме указанного стрелкой направо."}}],"c":0,"e":{"uk":"Знак {s:4.2} дозволяє рух лише в напрямку стрілки — праворуч ({p:33.4}), а знак {s:2.1} над ним вимагає ще й дати дорогу транспорту на головній дорозі ({p:16.11}).","ru":"Знак {s:4.2} разрешает движение только в направлении стрелки — направо ({p:33.4}), а знак {s:2.1} над ним требует ещё и уступить дорогу транспорту на главной дороге ({p:16.11})."},"ref":["16.11","33.4"],"pic":["img/hsc/16.2-108-1.jpg"]},{"id":"h16.2-109","t":"h16.2","num":"16.2.109","q":{"uk":"Ви плануєте повернути праворуч. Чи повинні Ви дати дорогу автомобілю, що наближається з лівого боку?","ru":"Вы планируете повернуть направо. Должны ли Вы уступить дорогу автомобилю, приближающемуся с левой стороны?"},"a":[{"uk":"Повинні.","ru":"Должны.","w":{"uk":"Автомобіль ліворуч рухається другорядною дорогою, а Ви — головною, тож поступається він.","ru":"Автомобиль слева движется по второстепенной дороге, а Вы — по главной, поэтому уступает он."}},{"uk":"Не повинні.","ru":"Не должны."}],"c":1,"e":{"uk":"Знак {s:2.3} з табличкою {s:7.8} показує, що головна дорога повертає праворуч, тож, повертаючи праворуч, Ви рухаєтеся саме нею. Автомобіль ліворуч наближається другорядною дорогою, тому за {p:16.11} він має дати дорогу Вам.","ru":"Знак {s:2.3} с табличкой {s:7.8} показывает, что главная дорога поворачивает направо, поэтому, поворачивая направо, Вы движетесь именно по ней. Автомобиль слева приближается по второстепенной дороге, поэтому по {p:16.11} он должен уступить дорогу Вам."},"ref":["16.11","33.2","33.7"],"pic":["img/hsc/16.2-109-1.jpg"]},{"id":"h17-1","t":"h17","num":"17.1","q":{"uk":"Яким транспортним засобам дозволено рух по смузі для маршрутних транспортних засобів у даній ситуації?","ru":"Каким транспортным средствам разрешено движение по полосе для маршрутных транспортных средств в данной ситуации?"},"a":[{"uk":"Автомобілям таксі.","ru":"Автомобилям такси.","w":{"uk":"Неповна відповідь: таксі — лише одне з виключень, крім нього смугою рухаються маршрутні транспортні засоби, мопеди, мотоцикли й велосипедисти {p:17.1}.","ru":"Неполный ответ: такси — лишь одно из исключений, кроме него по полосе движутся маршрутные транспортные средства, мопеды, мотоциклы и велосипедисты {p:17.1}."}},{"uk":"Усім транспортним засобам.","ru":"Всем транспортным средствам.","w":{"uk":"Рух інших транспортних засобів цією смугою заборонено {p:17.1}.","ru":"Движение других транспортных средств по этой полосе запрещено {p:17.1}."}},{"uk":"Автобусам і мікроавтобусам.","ru":"Автобусам и микроавтобусам.","w":{"uk":"Неповна відповідь і неточна: смуга призначена для маршрутних транспортних засобів, що рухаються за маршрутом, а також для таксі, мопедів, мотоциклів і велосипедистів {p:17.1}.","ru":"Неполный и неточный ответ: полоса предназначена для маршрутных транспортных средств, движущихся по маршруту, а также для такси, мопедов, мотоциклов и велосипедистов {p:17.1}."}},{"uk":"Маршрутним транспортним засобам, які рухаються за встановленим маршрутом, таксі, мопедам, мотоциклам (за винятком мотоциклів з боковим причепом, мотоколясок, триколісних транспортних засобів) та велосипедистам.","ru":"Маршрутным транспортным средствам, движущимся по установленному маршруту, такси, мопедам, мотоциклам (за исключением мотоциклов с боковым прицепом, мотоколясок, трёхколёсных транспортных средств) и велосипедистам."}],"c":3,"e":{"uk":"Знак {s:5.11} і розмітка {m:1.27} позначають смугу для маршрутних транспортних засобів. Крім них, нею можуть рухатися лише таксі, мопеди, мотоцикли (без бокового причепа, крім мотоколясок і триколісних) та велосипедисти {p:17.1}.","ru":"Знак {s:5.11} и разметка {m:1.27} обозначают полосу для маршрутных транспортных средств. Кроме них, по ней могут двигаться только такси, мопеды, мотоциклы (без бокового прицепа, кроме мотоколясок и трёхколёсных) и велосипедисты {p:17.1}."},"ref":["17.1"],"pic":["img/hsc/17-1-1.jpg"]},{"id":"h17-2","t":"h17","num":"17.2","q":{"uk":"По якій траєкторії водієві синього автомобіля дозволено поворот праворуч?","ru":"По какой траектории водителю синего автомобиля разрешён поворот направо?"},"a":[{"uk":"По траєкторії А.","ru":"По траектории А.","w":{"uk":"За траєкторією А автомобіль повертає не з крайнього правого положення і перетинає смугу, по якій може рухатися маршрутний транспорт {p:10.4}.","ru":"По траектории А автомобиль поворачивает не из крайнего правого положения и пересекает полосу, по которой может двигаться маршрутный транспорт {p:10.4}."}},{"uk":"По траєкторії Б.","ru":"По траектории Б."},{"uk":"По траєкторіях А і Б.","ru":"По траекториям А и Б.","w":{"uk":"Траєкторія А неправильна: поворот праворуч треба виконувати з крайнього правого положення, тобто зі смуги для маршрутних транспортних засобів {p:17.2}.","ru":"Траектория А неправильна: поворот направо нужно выполнять из крайнего правого положения, то есть с полосы для маршрутных транспортных средств {p:17.2}."}}],"c":1,"e":{"uk":"Перед перехрестям смугу для маршрутних транспортних засобів відокремлено переривчастою лінією, тож водій, що повертає праворуч, може заїхати на неї й повертати з неї {p:17.2}. Це і є крайнє праве положення, якого вимагає {p:10.4}, — траєкторія Б.","ru":"Перед перекрёстком полоса для маршрутных транспортных средств отделена прерывистой линией, поэтому водитель, поворачивающий направо, может заехать на неё и поворачивать с неё {p:17.2}. Это и есть крайнее правое положение, которого требует {p:10.4}, — траектория Б."},"ref":["17.2","10.4"],"pic":["img/hsc/17-2-1.jpg"]},{"id":"h17-3","t":"h17","num":"17.3","q":{"uk":"По якій траєкторії повинен рухатися водій білого автомобіля?","ru":"По какой траектории должен двигаться водитель белого автомобиля?"},"a":[{"uk":"По траєкторії А.","ru":"По траектории А.","w":{"uk":"Траєкторія А — поворот не з крайнього правого положення через смугу маршрутного транспорту, що суперечить {p:10.4}.","ru":"Траектория А — поворот не из крайнего правого положения через полосу маршрутного транспорта, что противоречит {p:10.4}."}},{"uk":"По траєкторії Б.","ru":"По траектории Б."},{"uk":"По траєкторіях А і Б.","ru":"По траекториям А и Б.","w":{"uk":"Правильна лише траєкторія Б: якщо смугу відокремлено переривчастою лінією, повертати праворуч треба з неї {p:17.2}.","ru":"Правильна только траектория Б: если полоса отделена прерывистой линией, поворачивать направо нужно с неё {p:17.2}."}}],"c":1,"e":{"uk":"Смугу для маршрутних транспортних засобів перед перехрестям відокремлено переривчастою лінією, тож для повороту праворуч треба заздалегідь заїхати на неї й повертати з неї {p:17.2}: це крайнє праве положення, якого вимагає {p:10.4}, — траєкторія Б.","ru":"Полоса для маршрутных транспортных средств перед перекрёстком отделена прерывистой линией, поэтому для поворота направо нужно заранее заехать на неё и поворачивать с неё {p:17.2}: это крайнее правое положение, которого требует {p:10.4}, — траектория Б."},"ref":["17.2","10.4"],"pic":["img/hsc/17-3-1.jpg"]},{"id":"h17-4","t":"h17","num":"17.4","q":{"uk":"Чи має право водій білого автомобіля в даній ситуації виїхати і зупинитися на смузі для маршрутних транспортних засобів для посадки пасажира?","ru":"Имеет ли право водитель белого автомобиля в данной ситуации выехать и остановиться на полосе для маршрутных транспортных средств для посадки пассажира?"},"a":[{"uk":"Має право.","ru":"Имеет право."},{"uk":"Не має права: виїзд на смугу йому заборонено.","ru":"Не имеет права: выезд на полосу ему запрещён.","w":{"uk":"Заборона {p:17.1} має виняток: через переривчасту лінію заїжджати на смугу для посадки пасажирів дозволено {p:17.2}.","ru":"Запрет {p:17.1} имеет исключение: через прерывистую линию заезжать на полосу для посадки пассажиров разрешено {p:17.2}."}}],"c":0,"e":{"uk":"Смугу для маршрутних транспортних засобів тут відокремлено переривчастою лінією, а в таких місцях на неї дозволено заїжджати для посадки чи висадки пасажирів біля правого краю проїзної частини {p:17.2}.","ru":"Полоса для маршрутных транспортных средств здесь отделена прерывистой линией, а в таких местах на неё разрешено заезжать для посадки или высадки пассажиров у правого края проезжей части {p:17.2}."},"ref":["17.2"],"pic":["img/hsc/17-4-1.jpg"]},{"id":"h17-5","t":"h17","num":"17.5","q":{"uk":"У якому випадку водієві білого автомобіля дозволено виїзд на смугу для маршрутних транспортних засобів у даній ситуації?","ru":"В каком случае водителю белого автомобиля разрешён выезд на полосу для маршрутных транспортных средств в данной ситуации?"},"a":[{"uk":"Виїзд на смугу заборонено.","ru":"Выезд на полосу запрещён.","w":{"uk":"Через переривчасту лінію заїжджати на смугу в окремих випадках дозволено {p:17.2}.","ru":"Через прерывистую линию заезжать на полосу в отдельных случаях разрешено {p:17.2}."}},{"uk":"Тільки для посадки або висадки пасажирів.","ru":"Только для посадки или высадки пассажиров.","w":{"uk":"Неповна відповідь: заїжджати на смугу можна й для повороту праворуч {p:17.2}.","ru":"Неполный ответ: заезжать на полосу можно и для поворота направо {p:17.2}."}},{"uk":"Тільки для виконання повороту праворуч.","ru":"Только для выполнения поворота направо.","w":{"uk":"Неповна відповідь: заїжджати на смугу можна й для посадки чи висадки пасажирів {p:17.2}.","ru":"Неполный ответ: заезжать на полосу можно и для посадки или высадки пассажиров {p:17.2}."}},{"uk":"Для посадки або висадки пасажирів або для виконання повороту праворуч.","ru":"Для посадки или высадки пассажиров или для выполнения поворота направо."}],"c":3,"e":{"uk":"Смугу відокремлено переривчастою лінією, тож на неї можна заїжджати і для повороту праворуч, і для посадки чи висадки пасажирів біля правого краю проїзної частини {p:17.2}.","ru":"Полоса отделена прерывистой линией, поэтому на неё можно заезжать и для поворота направо, и для посадки или высадки пассажиров у правого края проезжей части {p:17.2}."},"ref":["17.2"],"pic":["img/hsc/17-5-1.jpg"]},{"id":"h17-6","t":"h17","num":"17.6","q":{"uk":"Хто з водіїв повинен дати дорогу в даній ситуації?","ru":"Кто из водителей должен уступить дорогу в данной ситуации?"},"a":[{"uk":"Водій автомобіля.","ru":"Водитель автомобиля."},{"uk":"Водій трамвая.","ru":"Водитель трамвая.","w":{"uk":"Поза перехрестям, де колія перетинає смугу руху, перевагу має трамвай (крім виїзду з депо), тож поступатися йому не потрібно {p:17.3}.","ru":"Вне перекрёстка, где пути пересекают полосу движения, преимущество имеет трамвай (кроме выезда из депо), поэтому уступать ему не нужно {p:17.3}."}}],"c":0,"e":{"uk":"Трамвайна колія перетинає смугу руху поза перехрестям (знак {s:1.20}), а в таких місцях перевага надається трамваю {p:17.3}. Тож автомобіль пропускає трамвай.","ru":"Трамвайные пути пересекают полосу движения вне перекрёстка (знак {s:1.20}), а в таких местах преимущество предоставляется трамваю {p:17.3}. Поэтому автомобиль пропускает трамвай."},"ref":["17.3"],"pic":["img/hsc/17-6-1.jpg"]},{"id":"h17-7","t":"h17","num":"17.7","q":{"uk":"Ви як водій автомобіля, під’їжджаючи до автобуса в населеному пункті, що розпочинає рух від позначеної зупинки, розташованої в заїзному «кармані», повинні:","ru":"Вы как водитель автомобиля, подъезжая в населённом пункте к автобусу, начинающему движение от обозначенной остановки, расположенной в заездном «кармане», должны:"},"a":[{"uk":"Зменшити швидкість, а в разі потреби зупинитися, щоб дати можливість маршрутному транспортному засобу розпочати рух.","ru":"Снизить скорость, а при необходимости остановиться, чтобы дать возможность маршрутному транспортному средству начать движение."},{"uk":"Обов’язково перестроїтись на ліву смугу.","ru":"Обязательно перестроиться на левую полосу.","w":{"uk":"Перестроюватися ліворуч Правила не вимагають, достатньо зменшити швидкість чи зупинитися {p:17.4}.","ru":"Перестраиваться налево Правила не требуют, достаточно снизить скорость или остановиться {p:17.4}."}},{"uk":"Проїхати повз автобус не зменшуючи швидкості, бо водій автобусу перед початком руху повинен надати дорогу.","ru":"Проехать мимо автобуса, не снижая скорости, так как водитель автобуса перед началом движения должен уступить дорогу.","w":{"uk":"У населеному пункті перевагу має автобус, що виїжджає з «кармана», а не транспорт, який рухається повз нього {p:17.4}.","ru":"В населённом пункте преимущество имеет автобус, выезжающий из «кармана», а не транспорт, движущийся мимо него {p:17.4}."}}],"c":0,"e":{"uk":"Це дослівна вимога {p:17.4}: у населених пунктах водії мають зменшити швидкість, а в разі потреби зупинитися, щоб автобус міг виїхати із заїзного «кармана».","ru":"Это дословное требование {p:17.4}: в населённых пунктах водители должны снизить скорость, а при необходимости остановиться, чтобы автобус мог выехать из заездного «кармана»."},"ref":["17.4"]},{"id":"h17-8","t":"h17","num":"17.8","q":{"uk":"Як повинен діяти водій білого автомобіля в зображеній на малюнку ситуації, під’їжджаючи до автобуса, що розпочинає рух від позначеної зупинки, розташованої в заїзному «кармані», поза населеним пунктом?","ru":"Как должен действовать водитель белого автомобиля в изображённой на рисунке ситуации, подъезжая вне населённого пункта к автобусу, начинающему движение от обозначенной остановки, расположенной в заездном «кармане»?"},"a":[{"uk":"Він повинен зменшити швидкість, а в разі потреби зупинитися, щоб дати можливість маршрутному транспортному засобу розпочати рух.","ru":"Он должен снизить скорость, а при необходимости остановиться, чтобы дать возможность маршрутному транспортному средству начать движение.","w":{"uk":"Обов'язок пропустити автобус, що рушає з «кармана», встановлено лише для населених пунктів, а тут ситуація поза ними {p:17.4}.","ru":"Обязанность пропустить автобус, трогающийся из «кармана», установлена только для населённых пунктов, а здесь ситуация вне их {p:17.4}."}},{"uk":"Водій білого автомобіля має перевагу у русі.","ru":"Водитель белого автомобиля имеет преимущество в движении."}],"c":1,"e":{"uk":"Перевага автобусів, що виїжджають із заїзного «кармана», діє лише **в населених пунктах** {p:17.4}. Поза ними автобус перед початком руху сам повинен дати дорогу транспорту, що рухається дорогою {p:10.1}.","ru":"Преимущество автобусов, выезжающих из заездного «кармана», действует только **в населённых пунктах** {p:17.4}. Вне их автобус перед началом движения сам должен уступить дорогу транспорту, движущемуся по дороге {p:10.1}."},"ref":["17.4","10.1"],"pic":["img/hsc/17-8-1.jpg"]},{"id":"h17-9","t":"h17","num":"17.9","q":{"uk":"Чи має право водій таксі рухатися на дорозі із смугою для маршрутних транспортних засобів?","ru":"Имеет ли право водитель такси двигаться по дороге с полосой для маршрутных транспортных средств?"},"a":[{"uk":"Має право рухатися.","ru":"Имеет право двигаться."},{"uk":"Не має права рухатися.","ru":"Не имеет права двигаться.","w":{"uk":"Таксі — виняток із заборони, тож рухатися такою дорогою і навіть смугою для маршрутних транспортних засобів воно може {p:17.1}.","ru":"Такси — исключение из запрета, поэтому двигаться по такой дороге и даже по полосе для маршрутных транспортных средств оно может {p:17.1}."}}],"c":0,"e":{"uk":"Таксі прямо названо серед транспортних засобів, яким дозволено рух смугою для маршрутних транспортних засобів {p:17.1}, а іншими смугами такої дороги може рухатися будь-хто.","ru":"Такси прямо названо среди транспортных средств, которым разрешено движение по полосе для маршрутных транспортных средств {p:17.1}, а по другим полосам такой дороги может двигаться кто угодно."},"ref":["17.1"]},{"id":"h17-10","t":"h17","num":"17.10","q":{"uk":"Чи має право водій таксі здійснювати посадку та висадку пасажирів у межах смуги для маршрутних транспортних засобів?","ru":"Имеет ли право водитель такси осуществлять посадку и высадку пассажиров в пределах полосы для маршрутных транспортных средств?"},"a":[{"uk":"Має право здійснювати посадку та висадку пасажирів.","ru":"Имеет право осуществлять посадку и высадку пассажиров."},{"uk":"Не має права здійснювати посадку та висадку пасажирів.","ru":"Не имеет права осуществлять посадку и высадку пассажиров.","w":{"uk":"Таксі — виняток із заборони руху й зупинки на цій смузі {p:17.1}.","ru":"Такси — исключение из запрета движения и остановки на этой полосе {p:17.1}."}}],"c":0,"e":{"uk":"Заборона руху **і зупинки** на смузі для маршрутних транспортних засобів не поширюється на таксі {p:17.1}, тож зупинитися на ній для посадки чи висадки пасажирів таксі може.","ru":"Запрет движения **и остановки** на полосе для маршрутных транспортных средств не распространяется на такси {p:17.1}, поэтому остановиться на ней для посадки или высадки пассажиров такси может."},"ref":["17.1"]},{"id":"h17-11","t":"h17","num":"17.11","q":{"uk":"Чи забороняється на дорозі із смугою для маршрутних транспортних засобів, позначеної дорожнім знаком 5.8 або 5.11, рух і зупинка інших транспортних засобів?","ru":"Запрещается ли на дороге с полосой для маршрутных транспортных средств, обозначенной дорожным знаком 5.8 или 5.11, движение и остановка других транспортных средств?"},"a":[{"uk":"Забороняються рух і зупинка інших транспортних засобів.","ru":"Запрещаются движение и остановка других транспортных средств.","w":{"uk":"Неповна відповідь: заборона має винятки — таксі, мопеди, мотоцикли й велосипедисти {p:17.1}.","ru":"Неполный ответ: запрет имеет исключения — такси, мопеды, мотоциклы и велосипедисты {p:17.1}."}},{"uk":"Дозволяється рух і зупинка інших транспортних засобів.","ru":"Разрешаются движение и остановка других транспортных средств.","w":{"uk":"Рух і зупинка інших транспортних засобів на цій смузі заборонені, за винятком переліченого у {p:17.1}.","ru":"Движение и остановка других транспортных средств на этой полосе запрещены, за исключением перечисленных в {p:17.1}."}},{"uk":"Дозволяється рух і зупинка тільки для таксі, мопедам, мотоциклам (за винятком мотоциклів з боковим причепом, мотоколясок, триколісних транспортних засобів) та велосипедистам.","ru":"Движение и остановка разрешены только такси, мопедам, мотоциклам (за исключением мотоциклов с боковым прицепом, мотоколясок, трёхколёсных транспортных средств) и велосипедистам."}],"c":2,"e":{"uk":"{p:17.1} забороняє на смузі, позначеній {s:5.8} або {s:5.11}, рух і зупинку інших транспортних засобів, **крім** таксі, мопедів, мотоциклів (за винятком мотоциклів з боковим причепом, мотоколясок, триколісних) та велосипедистів.","ru":"{p:17.1} запрещает на полосе, обозначенной {s:5.8} или {s:5.11}, движение и остановку других транспортных средств, **кроме** такси, мопедов, мотоциклов (за исключением мотоциклов с боковым прицепом, мотоколясок, трёхколёсных) и велосипедистов."},"ref":["17.1"],"pic":["img/hsc/17-11-1.jpg"]},{"id":"h18-1","t":"h18","num":"18.1","q":{"uk":"Яке значення мають два миготливі сигнали світлофора в даній ситуації?","ru":"Какое значение имеют два мигающих сигнала светофора в данной ситуации?"},"a":[{"uk":"Забороняють рух.","ru":"Запрещают движение.","w":{"uk":"Жовті миготливі сигнали рух дозволяють; забороняють його червоні сигнали {p:8.7}.","ru":"Жёлтые мигающие сигналы движение разрешают; запрещают его красные сигналы {p:8.7}."}},{"uk":"Інформують про наявність пішоходів на пішохідному переході.","ru":"Информируют о наличии пешеходов на пешеходном переходе.","w":{"uk":"Сигнали миготять постійно, незалежно від того, чи є пішоходи на переході, — вони попереджають про сам перехід {p:8.7}.","ru":"Сигналы мигают постоянно, независимо от того, есть ли пешеходы на переходе, — они предупреждают о самом переходе {p:8.7}."}},{"uk":"Інформують про наявність небезпечного нерегульованого пішохідного переходу.","ru":"Информируют о наличии опасного нерегулируемого пешеходного перехода."},{"uk":"Інформують про наявність небезпечного регульованого пішохідного переходу.","ru":"Информируют о наличии опасного регулируемого пешеходного перехода.","w":{"uk":"Перехід, де світлофор працює в режимі миготіння жовтого сигналу, вважається нерегульованим {p:1.10}.","ru":"Переход, где светофор работает в режиме мигания жёлтого сигнала, считается нерегулируемым {p:1.10}."}}],"c":2,"e":{"uk":"За {p:8.7} жовтий миготливий сигнал або два жовті миготливі сигнали дозволяють рух і інформують про небезпечний **нерегульований** пішохідний перехід; перехід зі світлофором у такому режимі вважається нерегульованим {p:1.10}.","ru":"По {p:8.7} жёлтый мигающий сигнал или два жёлтых мигающих сигнала разрешают движение и информируют об опасном **нерегулируемом** пешеходном переходе; переход со светофором в таком режиме считается нерегулируемым {p:1.10}."},"ref":["8.7","1.10"],"pic":["img/hsc/18-1-1.jpg"]},{"id":"h18-2","t":"h18","num":"18.2","q":{"uk":"Як повинні вчинити водії, наближаючись до транспортного засобу з розпізнавальним знаком «Діти», що стоїть з увімкненою аварійною сигналізацією та проблисковим маячком оранжевого кольору?","ru":"Как должны поступить водители, приближаясь к транспортному средству с опознавательным знаком «Дети», стоящему с включённой аварийной сигнализацией и проблесковым маячком оранжевого цвета?"},"a":[{"uk":"Тільки зменшити швидкість.","ru":"Только снизить скорость.","w":{"uk":"Неповна відповідь: якщо діти можуть вибігти на дорогу, треба й зупинитися {p:18.9}.","ru":"Неполный ответ: если дети могут выбежать на дорогу, нужно и остановиться {p:18.9}."}},{"uk":"Обов'язково зупинитися перед цим транспортним засобом.","ru":"Обязательно остановиться перед этим транспортным средством.","w":{"uk":"Зупинка обов'язкова лише в разі потреби, а не завжди {p:18.9}.","ru":"Остановка обязательна только при необходимости, а не всегда {p:18.9}."}},{"uk":"Зменшити швидкість, а в разі потреби зупинитися, щоб уникнути наїзду на дітей.","ru":"Снизить скорость, а при необходимости остановиться, чтобы избежать наезда на детей."}],"c":2,"e":{"uk":"Це дослівна вимога {p:18.9}: водії, що рухаються суміжною смугою, повинні зменшити швидкість, а в разі потреби зупинитися, щоб уникнути наїзду на дітей.","ru":"Это дословное требование {p:18.9}: водители, движущиеся по смежной полосе, должны снизить скорость, а при необходимости остановиться, чтобы избежать наезда на детей."},"ref":["18.9"],"pic":["img/hsc/18-2-1.jpg"]},{"id":"h18-3","t":"h18","num":"18.3","q":{"uk":"Як повинен вчинити в даній ситуації водій сірого автомобіля?","ru":"Как должен поступить в данной ситуации водитель серого автомобиля?"},"a":[{"uk":"Подати звуковий сигнал і, знизивши швидкість, продовжити рух, давши дорогу пішоходам.","ru":"Подать звуковой сигнал и, снизив скорость, продолжить движение, уступив дорогу пешеходам.","w":{"uk":"Звуковий сигнал не дає переваги {p:9.4}; тут потрібно не просто знизити швидкість, а зупинитися {p:18.8}.","ru":"Звуковой сигнал не даёт преимущества {p:9.4}; здесь нужно не просто снизить скорость, а остановиться {p:18.8}."}},{"uk":"Об'їхати трамвай зліва, давши дорогу зустрічним транспортним засобам.","ru":"Объехать трамвай слева, уступив дорогу встречным транспортным средствам.","w":{"uk":"Об'їзд трамвая не звільняє від обов'язку зупинитися й пропустити пішоходів {p:18.8}, а ліворуч до того ж трамвайна колія й зустрічний рух.","ru":"Объезд трамвая не освобождает от обязанности остановиться и пропустить пешеходов {p:18.8}, а слева к тому же трамвайные пути и встречное движение."}},{"uk":"Зупинитися, щоб дати дорогу пішоходам. Продовжувати рух дозволяється лише тоді, коли пішоходи залишать проїзну частину, а двері трамвая зачиняться.","ru":"Остановиться, чтобы уступить дорогу пешеходам. Продолжать движение разрешается лишь тогда, когда пешеходы покинут проезжую часть, а двери трамвая закроются."}],"c":2,"e":{"uk":"Трамвай стоїть на зупинці ({s:5.46.1}), а пасажири йдуть до нього і від нього через проїзну частину. За {p:18.8} водій повинен зупинитися й рушати лише тоді, коли пішоходи залишать проїзну частину і двері трамвая зачиняться.","ru":"Трамвай стоит на остановке ({s:5.46.1}), а пассажиры идут к нему и от него через проезжую часть. По {p:18.8} водитель должен остановиться и трогаться только тогда, когда пешеходы покинут проезжую часть и двери трамвая закроются."},"ref":["18.8"],"pic":["img/hsc/18-3-1.jpg"]},{"id":"h18-4","t":"h18","num":"18.4","q":{"uk":"Яких заходів повинні вживати водії, проїжджаючи повз пішоходів, які очікують увімкнення дозвільного сигналу світлофора на острівцях безпеки або на лінії, що розділяє транспортні потоки?","ru":"Какие меры должны принимать водители, проезжая мимо пешеходов, ожидающих включения разрешающего сигнала светофора на островках безопасности или на линии, разделяющей транспортные потоки?"},"a":[{"uk":"Подавати звуковий сигнал.","ru":"Подавать звуковой сигнал.","w":{"uk":"Звуковий сигнал може налякати пішохода, а в населених пунктах його подавати заборонено, крім випадків запобігання ДТП {p:9.5}.","ru":"Звуковой сигнал может напугать пешехода, а в населённых пунктах его подавать запрещено, кроме случаев предотвращения ДТП {p:9.5}."}},{"uk":"Дотримуватися безпечного інтервалу.","ru":"Соблюдать безопасный интервал."}],"c":1,"e":{"uk":"За {p:18.3}, проїжджаючи повз пішоходів, які вимушено перебувають на острівці безпеки або на лінії, що розділяє транспортні потоки, водії повинні дотримуватися **безпечного інтервалу**.","ru":"По {p:18.3}, проезжая мимо пешеходов, которые вынужденно находятся на островке безопасности или на линии, разделяющей транспортные потоки, водители должны соблюдать **безопасный интервал**."},"ref":["18.3"],"pic":["img/hsc/18-4-1.jpg"]},{"id":"h18-5","t":"h18","num":"18.5","q":{"uk":"Як повинен вчинити водій автомобіля, якщо автомобіль, що їде перед ним, почав зменшувати швидкість перед нерегульованим пішохідним переходом?","ru":"Как должен поступить водитель автомобиля, если автомобиль, едущий перед ним, начал снижать скорость перед нерегулируемым пешеходным переходом?"},"a":[{"uk":"Подати звуковий сигнал і далі продовжити рух, дотримуючись обережності.","ru":"Подать звуковой сигнал и далее продолжить движение, соблюдая осторожность.","w":{"uk":"Звуковий сигнал не дає переваги {p:9.4} і не звільняє від обов'язку переконатися, що на переході немає пішоходів {p:18.4}.","ru":"Звуковой сигнал не даёт преимущества {p:9.4} и не освобождает от обязанности убедиться, что на переходе нет пешеходов {p:18.4}."}},{"uk":"Знизити швидкість і рухатися далі, дотримуючись заходів безпеки.","ru":"Снизить скорость и двигаться дальше, соблюдая меры безопасности.","w":{"uk":"Неповна відповідь: продовжувати рух можна лише переконавшись, що на переході немає пішоходів, а в разі потреби — після зупинки {p:18.4}.","ru":"Неполный ответ: продолжать движение можно только убедившись, что на переходе нет пешеходов, а при необходимости — после остановки {p:18.4}."}},{"uk":"Знизити швидкість (у разі необхідності – зупинитися) і продовжити рух, тільки переконавшись, що на пішохідному переході немає пішоходів, для яких може бути створена перешкода чи небезпека.","ru":"Снизить скорость (при необходимости — остановиться) и продолжить движение, только убедившись, что на пешеходном переходе нет пешеходов, для которых может быть создана помеха или опасность."}],"c":2,"e":{"uk":"Вантажівка перед нерегульованим переходом ({s:5.38.1}) може закривати пішохода, тож за {p:18.4} водій на сусідній смузі повинен зменшити швидкість, у разі потреби зупинитися і продовжити рух, лише переконавшись, що на переході немає пішоходів.","ru":"Грузовик перед нерегулируемым переходом ({s:5.38.1}) может закрывать пешехода, поэтому по {p:18.4} водитель на соседней полосе должен снизить скорость, при необходимости остановиться и продолжить движение, только убедившись, что на переходе нет пешеходов."},"ref":["18.4"],"pic":["img/hsc/18-5-1.jpg"]},{"id":"h18-6","t":"h18","num":"18.6","q":{"uk":"Як повинні вчинити водії в ситуації, коли пішохід, що виходить на проїзну частину, подає сигнал тростиною білого кольору, спрямованою вперед?","ru":"Как должны поступить водители в ситуации, когда пешеход, выходящий на проезжую часть, подаёт сигнал тростью белого цвета, направленной вперёд?"},"a":[{"uk":"Подати звуковий сигнал, тому що в даному місці перехід дороги заборонено.","ru":"Подать звуковой сигнал, так как в данном месте переход дороги запрещён.","w":{"uk":"Незряча людина не бачить, де перехід, а Правила зобов'язують пропустити її в будь-якому місці {p:18.5}.","ru":"Незрячий человек не видит, где переход, а Правила обязывают пропустить его в любом месте {p:18.5}."}},{"uk":"Пропустити пішохода.","ru":"Пропустить пешехода."},{"uk":"Зменшити швидкість і, дотримуючись безпечного інтервалу, проїхати біля пішохода.","ru":"Снизить скорость и, соблюдая безопасный интервал, проехать мимо пешехода.","w":{"uk":"Проїхати повз не можна: пішохода з білою тростиною треба пропустити {p:18.5}.","ru":"Проехать мимо нельзя: пешехода с белой тростью нужно пропустить {p:18.5}."}}],"c":1,"e":{"uk":"Пішохода з порушенням зору, який подає сигнал білою тростиною, спрямованою вперед, водій повинен пропустити **в будь-якому місці**, а не лише на пішохідному переході {p:18.5}.","ru":"Пешехода с нарушением зрения, подающего сигнал белой тростью, направленной вперёд, водитель должен пропустить **в любом месте**, а не только на пешеходном переходе {p:18.5}."},"ref":["18.5"],"pic":["img/hsc/18-6-1.jpg"]},{"id":"h18-7","t":"h18","num":"18.7","q":{"uk":"Ви зупинилися, щоб дати дорогу пішоходам, які виконують посадку в трамвай і висадку з нього. Коли вам дозволено продовжити рух?","ru":"Вы остановились, чтобы уступить дорогу пешеходам, которые садятся в трамвай и выходят из него. Когда вам разрешено продолжить движение?"},"a":[{"uk":"Коли пішоходи залишать проїзну частину.","ru":"Когда пешеходы покинут проезжую часть.","w":{"uk":"Неповна відповідь: поки двері трамвая відчинені, до нього можуть бігти нові пасажири {p:18.8}.","ru":"Неполный ответ: пока двери трамвая открыты, к нему могут бежать новые пассажиры {p:18.8}."}},{"uk":"Коли двері трамвая зачиняться.","ru":"Когда двери трамвая закроются.","w":{"uk":"Неповна відповідь: навіть після зачинення дверей на проїзній частині можуть залишатися пішоходи {p:18.8}.","ru":"Неполный ответ: даже после закрытия дверей на проезжей части могут оставаться пешеходы {p:18.8}."}},{"uk":"Коли пішоходи залишать проїзну частину і двері трамвая зачиняться.","ru":"Когда пешеходы покинут проезжую часть и двери трамвая закроются."}],"c":2,"e":{"uk":"За {p:18.8} продовжувати рух дозволяється лише тоді, коли **одночасно** пішоходи залишили проїзну частину **і** двері трамвая зачинилися.","ru":"По {p:18.8} продолжать движение разрешается только тогда, когда **одновременно** пешеходы покинули проезжую часть **и** двери трамвая закрылись."},"ref":["18.8"]},{"id":"h18-8","t":"h18","num":"18.8","q":{"uk":"Як Ви повинні вчинити в ситуації, коли попереду Вас зупинився трамвай для посадки і висадки пасажирів?","ru":"Как вы должны поступить в ситуации, когда впереди вас остановился трамвай для посадки и высадки пассажиров?"},"a":[{"uk":"Знизити швидкість і проїхати біля трамвая.","ru":"Снизить скорость и проехать мимо трамвая.","w":{"uk":"Знизити швидкість недостатньо: треба зупинитися й пропустити пішоходів {p:18.8}.","ru":"Снизить скорость недостаточно: нужно остановиться и пропустить пешеходов {p:18.8}."}},{"uk":"Об'їхати трамвай з лівого боку.","ru":"Объехать трамвай с левой стороны.","w":{"uk":"Об'їзд трамвая зліва не звільняє від обов'язку зупинитися й пропустити пішоходів {p:18.8}.","ru":"Объезд трамвая слева не освобождает от обязанности остановиться и пропустить пешеходов {p:18.8}."}},{"uk":"Зупинитися, щоб дати дорогу пішоходам. Продовжувати рух дозволяється лише тоді, коли пішоходи залишать проїзну частину, а двері трамвая зачиняться.","ru":"Остановиться, чтобы уступить дорогу пешеходам. Продолжать движение разрешается лишь тогда, когда пешеходы покинут проезжую часть, а двери трамвая закроются."}],"c":2,"e":{"uk":"Якщо посадка й висадка відбуваються з проїзної частини, водій повинен зупинитися, щоб дати дорогу пішоходам, і рушати лише тоді, коли пішоходи залишать проїзну частину, а двері трамвая зачиняться {p:18.8}.","ru":"Если посадка и высадка происходят с проезжей части, водитель должен остановиться, чтобы уступить дорогу пешеходам, и трогаться только тогда, когда пешеходы покинут проезжую часть, а двери трамвая закроются {p:18.8}."},"ref":["18.8"]},{"id":"h18-9","t":"h18","num":"18.9","q":{"uk":"Як ви повинні вчинити в ситуації, коли за пішохідним переходом утворився затор?","ru":"Как вы должны поступить в ситуации, когда за пешеходным переходом образовался затор?"},"a":[{"uk":"Зупинитися перед пішохідним переходом.","ru":"Остановиться перед пешеходным переходом."},{"uk":"Зупинитися на пішохідному переході, залишивши місце для проходу пішоходів.","ru":"Остановиться на пешеходном переходе, оставив место для прохода пешеходов.","w":{"uk":"Зупинятися на пішохідному переході в заторі заборонено, навіть залишивши прохід {p:18.6}.","ru":"Останавливаться на пешеходном переходе в заторе запрещено, даже оставив проход {p:18.6}."}},{"uk":"Зупинитися на пішохідному переході, тільки якщо на ньому немає пішоходів.","ru":"Остановиться на пешеходном переходе, только если на нём нет пешеходов.","w":{"uk":"Заборона не залежить від наявності пішоходів: вони можуть з'явитися будь-якої миті {p:18.6}.","ru":"Запрет не зависит от наличия пешеходов: они могут появиться в любой момент {p:18.6}."}}],"c":0,"e":{"uk":"{p:18.6} забороняє в'їжджати на пішохідний перехід, якщо за ним утворився затор, який змусить зупинитися на переході, — тож чекати треба перед переходом.","ru":"{p:18.6} запрещает въезжать на пешеходный переход, если за ним образовался затор, который вынудит остановиться на переходе, — поэтому ждать нужно перед переходом."},"ref":["18.6"]},{"id":"h18-10","t":"h18","num":"18.10","q":{"uk":"Що повинен зробити водій транспортного засобу, якщо інший транспортний засіб, що рухається по суміжній смузі попереду нього, перед нерегульованим пішохідним переходом почав знижувати швидкість або зовсім зупинився?","ru":"Что должен сделать водитель транспортного средства, если другое транспортное средство, движущееся по смежной полосе впереди него, перед нерегулируемым пешеходным переходом начало снижать скорость или полностью остановилось?"},"a":[{"uk":"Повинен тільки знизити швидкість, щоб переконатися у відсутності пішоходів.","ru":"Должен только снизить скорость, чтобы убедиться в отсутствии пешеходов.","w":{"uk":"Неповна відповідь: у разі потреби треба й зупинитися {p:18.4}.","ru":"Неполный ответ: при необходимости нужно и остановиться {p:18.4}."}},{"uk":"Повинен обов'язково зупинитися, щоб переконатися у відсутності пішоходів.","ru":"Должен обязательно остановиться, чтобы убедиться в отсутствии пешеходов.","w":{"uk":"Зупинка обов'язкова лише в разі потреби, а не завжди {p:18.4}.","ru":"Остановка обязательна только при необходимости, а не всегда {p:18.4}."}},{"uk":"Перед пішохідним переходом повинен зменшити швидкість (у разі необхідності – зупинитися) і продовжити рух, тільки переконавшись, що на пішохідному переході немає пішоходів, для яких може бути створена перешкода чи небезпека.","ru":"Перед пешеходным переходом должен снизить скорость (при необходимости — остановиться) и продолжить движение, только убедившись, что на пешеходном переходе нет пешеходов, для которых может быть создана помеха или опасность."},{"uk":"Подати звуковий сигнал, щоб попередити пішоходів.","ru":"Подать звуковой сигнал, чтобы предупредить пешеходов.","w":{"uk":"Звуковий сигнал не замінює обов'язку зменшити швидкість і пропустити пішоходів {p:18.4}, а в населених пунктах його подавати заборонено {p:9.5}.","ru":"Звуковой сигнал не заменяет обязанности снизить скорость и пропустить пешеходов {p:18.4}, а в населённых пунктах его подавать запрещено {p:9.5}."}}],"c":2,"e":{"uk":"Це дослівна вимога {p:18.4}: зменшити швидкість, у разі потреби зупинитися і продовжувати рух, лише переконавшись, що на переході немає пішоходів, яким можна створити перешкоду чи небезпеку.","ru":"Это дословное требование {p:18.4}: снизить скорость, при необходимости остановиться и продолжать движение, только убедившись, что на переходе нет пешеходов, которым можно создать помеху или опасность."},"ref":["18.4"]},{"id":"h18-11","t":"h18","num":"18.11","q":{"uk":"Як ви повинні вчинити в ситуації, коли мікроавтобус зупинився перед пішохідним переходом на нерегульованому перехресті?","ru":"Как вы должны поступить в ситуации, когда микроавтобус остановился перед пешеходным переходом на нерегулируемом перекрёстке?"},"a":[{"uk":"Рухатися далі, оскільки для вас встановлено знак «Головна дорога».","ru":"Двигаться дальше, так как для вас установлен знак «Главная дорога».","w":{"uk":"Знак {s:2.3} дає перевагу перед транспортом на другорядній дорозі, але не перед пішоходами на переході {p:18.4}.","ru":"Знак {s:2.3} даёт преимущество перед транспортом на второстепенной дороге, но не перед пешеходами на переходе {p:18.4}."}},{"uk":"Зменшити швидкість (у разі необхідності – зупинитися) і продовжити рух, тільки переконавшись, що на пішохідному переході немає пішоходів, для яких може бути створена перешкода чи небезпека.","ru":"Снизить скорость (при необходимости — остановиться) и продолжить движение, только убедившись, что на пешеходном переходе нет пешеходов, для которых может быть создана помеха или опасность."}],"c":1,"e":{"uk":"Мікроавтобус, що зупинився перед нерегульованим переходом, може закривати пішоходів, тож за {p:18.4} треба зменшити швидкість, у разі потреби зупинитися й рушати, лише переконавшись, що на переході нікого немає.","ru":"Микроавтобус, остановившийся перед нерегулируемым переходом, может закрывать пешеходов, поэтому по {p:18.4} нужно снизить скорость, при необходимости остановиться и трогаться, только убедившись, что на переходе никого нет."},"ref":["18.4"]},{"id":"h18-12","t":"h18","num":"18.12","q":{"uk":"Як ви повинні вчинити в ситуації, коли автомобіль, що їде перед вами, спочатку почав знижувати швидкість, а потім і зовсім зупинився перед нерегульованим пішохідним переходом?","ru":"Как вы должны поступить в ситуации, когда автомобиль, едущий перед вами, сначала начал снижать скорость, а затем и вовсе остановился перед нерегулируемым пешеходным переходом?"},"a":[{"uk":"Подати звуковий сигнал і знизити швидкість руху.","ru":"Подать звуковой сигнал и снизить скорость движения.","w":{"uk":"Звуковий сигнал не дає переваги {p:9.4} і не звільняє від обов'язку переконатися, що на переході немає пішоходів {p:18.4}.","ru":"Звуковой сигнал не даёт преимущества {p:9.4} и не освобождает от обязанности убедиться, что на переходе нет пешеходов {p:18.4}."}},{"uk":"Знизити швидкість і обережно проїхати пішохідний перехід.","ru":"Снизить скорость и осторожно проехать пешеходный переход.","w":{"uk":"«Обережно проїхати» недостатньо: рушати можна лише переконавшись, що на переході немає пішоходів {p:18.4}.","ru":"«Осторожно проехать» недостаточно: трогаться можно, только убедившись, что на переходе нет пешеходов {p:18.4}."}},{"uk":"Зменшити швидкість (у разі потреби – зупинитися) і продовжити рух, тільки переконавшись, що на пішохідному переході немає пішоходів, для яких може бути створена перешкода чи небезпека.","ru":"Снизить скорость (при необходимости — остановиться) и продолжить движение, только убедившись, что на пешеходном переходе нет пешеходов, для которых может быть создана помеха или опасность."}],"c":2,"e":{"uk":"Автомобіль, що зупинився перед нерегульованим переходом, найімовірніше пропускає пішоходів і закриває їх від Вас, тож за {p:18.4} треба зменшити швидкість, у разі потреби зупинитися й рушати, лише переконавшись, що на переході нікого немає.","ru":"Автомобиль, остановившийся перед нерегулируемым переходом, скорее всего пропускает пешеходов и закрывает их от вас, поэтому по {p:18.4} нужно снизить скорость, при необходимости остановиться и трогаться, только убедившись, что на переходе никого нет."},"ref":["18.4"]},{"id":"h18-13","t":"h18","num":"18.13","q":{"uk":"Що повинен зробити водій транспортного засобу в разі ввімкнення сигналу світлофора, що дозволяє рух, якщо перед ним перебувають пішоходи, що закінчують перехід проїзної частини?","ru":"Что должен сделать водитель транспортного средства при включении сигнала светофора, разрешающего движение, если перед ним находятся пешеходы, заканчивающие переход проезжей части?"},"a":[{"uk":"Безпечно об'їхати пішоходів.","ru":"Безопасно объехать пешеходов.","w":{"uk":"Об'їжджати пішоходів не можна: треба дати їм дорогу, тобто дочекатися, поки вони завершать перехід {p:18.2}.","ru":"Объезжать пешеходов нельзя: нужно уступить им дорогу, то есть дождаться, пока они завершат переход {p:18.2}."}},{"uk":"Подати звуковий сигнал, щоб пішоходи пришвидшили перехід проїзної частини.","ru":"Подать звуковой сигнал, чтобы пешеходы ускорили переход проезжей части.","w":{"uk":"Квапити пішоходів звуковим сигналом не можна: він не дає переваги {p:9.4}, а пішоходам треба дати дорогу {p:18.2}.","ru":"Торопить пешеходов звуковым сигналом нельзя: он не даёт преимущества {p:9.4}, а пешеходам нужно уступить дорогу {p:18.2}."}},{"uk":"Дати дорогу пішоходам.","ru":"Уступить дорогу пешеходам."}],"c":2,"e":{"uk":"За {p:18.2} на регульованому переході навіть за дозвільного сигналу водій повинен дати дорогу пішоходам, які закінчують перехід проїзної частини.","ru":"По {p:18.2} на регулируемом переходе даже при разрешающем сигнале водитель должен уступить дорогу пешеходам, которые заканчивают переход проезжей части."},"ref":["18.2"]},{"id":"h18-14","t":"h18","num":"18.14","q":{"uk":"Як повинен вчинити водій транспортного засобу, наближаючись до нерегульованого пішохідного переходу, якщо на ньому є пішоходи?","ru":"Как должен поступить водитель транспортного средства, приближаясь к нерегулируемому пешеходному переходу, если на нём есть пешеходы?"},"a":[{"uk":"Знизити швидкість і безпечно об'їхати пішоходів, що переходять.","ru":"Снизить скорость и безопасно объехать переходящих пешеходов.","w":{"uk":"Об'їжджати пішоходів на переході не можна — їм треба дати дорогу {p:18.1}.","ru":"Объезжать пешеходов на переходе нельзя — им нужно уступить дорогу {p:18.1}."}},{"uk":"Обов'язково зупинитися, щоб дати дорогу пішоходам, що переходять.","ru":"Обязательно остановиться, чтобы уступить дорогу переходящим пешеходам.","w":{"uk":"Зупинка обов'язкова лише в разі потреби — наприклад, якщо пішохід уже на Вашому шляху {p:18.1}.","ru":"Остановка обязательна только при необходимости — например, если пешеход уже на вашем пути {p:18.1}."}},{"uk":"Зменшити швидкість, а в разі потреби зупинитися, щоб дати дорогу пішоходам.","ru":"Снизить скорость, а при необходимости остановиться, чтобы уступить дорогу пешеходам."}],"c":2,"e":{"uk":"Це дослівна вимога {p:18.1}: зменшити швидкість, а в разі потреби зупинитися, щоб дати дорогу пішоходам, для яких може бути створена перешкода чи небезпека.","ru":"Это дословное требование {p:18.1}: снизить скорость, а при необходимости остановиться, чтобы уступить дорогу пешеходам, для которых может быть создана помеха или опасность."},"ref":["18.1"]},{"id":"h18-15","t":"h18","num":"18.15","q":{"uk":"Як ви повинні вчинити, якщо світлофор працює в режимі миготіння жовтого сигналу?","ru":"Как вы должны поступить, если светофор работает в режиме мигания жёлтого сигнала?"},"a":[{"uk":"Не повинні давати дорогу пішоходам.","ru":"Не должны уступать дорогу пешеходам.","w":{"uk":"Миготливий жовтий не дає переваги — він попереджає про небезпечний нерегульований перехід, де пішоходів треба пропускати {p:8.7}.","ru":"Мигающий жёлтый не даёт преимущества — он предупреждает об опасном нерегулируемом переходе, где пешеходов нужно пропускать {p:8.7}."}},{"uk":"Повинні знизити швидкість, а в разі потреби зупинитися, щоб дати дорогу пішоходам.","ru":"Должны снизить скорость, а при необходимости остановиться, чтобы уступить дорогу пешеходам."},{"uk":"Повинні тільки зменшити швидкість, щоб дати дорогу пішоходам.","ru":"Должны только снизить скорость, чтобы уступить дорогу пешеходам.","w":{"uk":"Неповна відповідь: у разі потреби треба й зупинитися {p:18.1}.","ru":"Неполный ответ: при необходимости нужно и остановиться {p:18.1}."}}],"c":1,"e":{"uk":"Перехід зі світлофором у режимі миготіння жовтого сигналу вважається нерегульованим {p:1.10}, тож діє {p:18.1}: зменшити швидкість, а в разі потреби зупинитися, щоб дати дорогу пішоходам.","ru":"Переход со светофором в режиме мигания жёлтого сигнала считается нерегулируемым {p:1.10}, поэтому действует {p:18.1}: снизить скорость, а при необходимости остановиться, чтобы уступить дорогу пешеходам."},"ref":["18.1","1.10","8.7"]},{"id":"h18-16","t":"h18","num":"18.16","q":{"uk":"Як ви повинні вчинити, наближаючись до нерегульованого пішохідного переходу?","ru":"Как вы должны поступить, приближаясь к нерегулируемому пешеходному переходу?"},"a":[{"uk":"Повинні об'їхати пішоходів ззаду.","ru":"Должны объехать пешеходов сзади.","w":{"uk":"Об'їзд пішоходів позаду Правила не передбачають — їм треба дати дорогу {p:18.1}.","ru":"Объезд пешеходов сзади Правила не предусматривают — им нужно уступить дорогу {p:18.1}."}},{"uk":"Повинні тільки зупинитися, щоб дати дорогу пішоходам.","ru":"Должны только остановиться, чтобы уступить дорогу пешеходам.","w":{"uk":"Зупинка потрібна лише в разі потреби, а спершу треба зменшити швидкість {p:18.1}.","ru":"Остановка нужна только при необходимости, а сначала нужно снизить скорость {p:18.1}."}},{"uk":"Повинні тільки знизити швидкість, щоб дати дорогу пішоходам.","ru":"Должны только снизить скорость, чтобы уступить дорогу пешеходам.","w":{"uk":"Неповна відповідь: у разі потреби треба й зупинитися {p:18.1}.","ru":"Неполный ответ: при необходимости нужно и остановиться {p:18.1}."}},{"uk":"Повинні знизити швидкість, а в разі потреби зупинитися, щоб дати дорогу пішоходам.","ru":"Должны снизить скорость, а при необходимости остановиться, чтобы уступить дорогу пешеходам."}],"c":3,"e":{"uk":"Це дослівна вимога {p:18.1}: наближаючись до нерегульованого переходу, на якому є пішоходи, водій зменшує швидкість, а в разі потреби зупиняється, щоб дати їм дорогу.","ru":"Это дословное требование {p:18.1}: приближаясь к нерегулируемому переходу, на котором есть пешеходы, водитель снижает скорость, а при необходимости останавливается, чтобы уступить им дорогу."},"ref":["18.1"]},{"id":"h18-17","t":"h18","num":"18.17","q":{"uk":"Як ви повинні вчинити в ситуації, наближаючись до автобуса, який виконує посадку або висадку організованих груп дітей?","ru":"Как вы должны поступить в ситуации, приближаясь к автобусу, который выполняет посадку или высадку организованных групп детей?"},"a":[{"uk":"Знизити швидкість руху і бути обережним.","ru":"Снизить скорость движения и быть осторожным.","w":{"uk":"Неповна відповідь: у разі потреби треба й зупинитися, щоб уникнути наїзду на дітей {p:18.9}.","ru":"Неполный ответ: при необходимости нужно и остановиться, чтобы избежать наезда на детей {p:18.9}."}},{"uk":"Знизити швидкість, а в разі потреби зупинитися, щоб уникнути наїзду на дітей.","ru":"Снизить скорость, а при необходимости остановиться, чтобы избежать наезда на детей."},{"uk":"Подати звуковий сигнал, щоб привернути до себе увагу.","ru":"Подать звуковой сигнал, чтобы привлечь к себе внимание.","w":{"uk":"Звуковий сигнал може налякати дітей і не передбачений для цієї ситуації; Правила вимагають зменшити швидкість чи зупинитися {p:18.9}.","ru":"Звуковой сигнал может напугать детей и не предусмотрен для этой ситуации; Правила требуют снизить скорость или остановиться {p:18.9}."}},{"uk":"Відповіді 2 і 3.","ru":"Ответы 2 и 3.","w":{"uk":"Варіант 3 зайвий: звукового сигналу Правила тут не вимагають, а в населених пунктах він заборонений {p:9.5}.","ru":"Вариант 3 лишний: звукового сигнала Правила здесь не требуют, а в населённых пунктах он запрещён {p:9.5}."}}],"c":1,"e":{"uk":"За {p:18.9}, наближаючись до транспортного засобу зі знаком «Діти», що зупинився з увімкненими маячками чи аварійною сигналізацією, водій повинен зменшити швидкість, а в разі потреби зупинитися, щоб уникнути наїзду на дітей.","ru":"По {p:18.9}, приближаясь к транспортному средству со знаком «Дети», остановившемуся с включёнными маячками или аварийной сигнализацией, водитель должен снизить скорость, а при необходимости остановиться, чтобы избежать наезда на детей."},"ref":["18.9"]},{"id":"h18-18","t":"h18","num":"18.18","q":{"uk":"У цьому випадку водій білого автомобіля може продовжувати рух лише тоді, коли пішоходи залишать проїзну частину і в трамваї зачиняться двері.","ru":"В этом случае водитель белого автомобиля может продолжать движение лишь тогда, когда пешеходы покинут проезжую часть и у трамвая закроются двери."},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"Твердження точно відтворює {p:18.8}: потрібні обидві умови — пішоходи пішли з проїзної частини і двері зачинено.","ru":"Утверждение точно воспроизводит {p:18.8}: нужны оба условия — пешеходы ушли с проезжей части и двери закрыты."}}],"c":0,"e":{"uk":"Трамвай стоїть на зупинці, а посадка й висадка відбуваються з проїзної частини, тож за {p:18.8} водій повинен зупинитися й рушати лише тоді, коли пішоходи залишать проїзну частину і двері трамвая зачиняться.","ru":"Трамвай стоит на остановке, а посадка и высадка происходят с проезжей части, поэтому по {p:18.8} водитель должен остановиться и трогаться только тогда, когда пешеходы покинут проезжую часть и двери трамвая закроются."},"ref":["18.8"],"pic":["img/hsc/18-18-1.jpg"]},{"id":"h18-19","t":"h18","num":"18.19","q":{"uk":"Чи має право в даному випадку водій білого автомобіля об’їхати пішоходів?","ru":"Имеет ли право в данном случае водитель белого автомобиля объехать пешеходов?"},"a":[{"uk":"Так.","ru":"Да.","w":{"uk":"Правила вимагають зупинитися й дочекатися, поки пішоходи залишать проїзну частину, а двері трамвая зачиняться {p:18.8}.","ru":"Правила требуют остановиться и дождаться, пока пешеходы покинут проезжую часть, а двери трамвая закроются {p:18.8}."}},{"uk":"Ні.","ru":"Нет."}],"c":1,"e":{"uk":"Пасажири йдуть до трамвая й від нього проїзною частиною, тож водій повинен **зупинитися** і пропустити їх {p:18.8}; об'їжджати пішоходів не можна.","ru":"Пассажиры идут к трамваю и от него по проезжей части, поэтому водитель должен **остановиться** и пропустить их {p:18.8}; объезжать пешеходов нельзя."},"ref":["18.8"],"pic":["img/hsc/18-19-1.jpg"]},{"id":"h19-1","t":"h19","num":"19.1","q":{"uk":"Темною порою доби вважається:"},"a":[{"uk":"Частина доби від закінчення вечірніх (30 хв. після заходу сонця) до початку ранкових сутінків (30 хв. до сходу сонця)."},{"uk":"Частина доби від заходу до сходу сонця."}],"c":1,"pic":["img/hsc/19-1-1.jpg"]},{"id":"h19-2","t":"h19","num":"19.2","q":{"uk":"Як ви повинні діяти в разі погіршення видимості в напрямку руху, викликаного світлом фар зустрічних транспортних засобів?"},"a":[{"uk":"Збільшити швидкість, щоб швидше роз'їхатися із зустрічними транспортними засобами."},{"uk":"Зменшити швидкість до безпечної."}],"c":1},{"id":"h19-3","t":"h19","num":"19.3","q":{"uk":"Що вмикається на транспортному засобі під час зупинки на дорозі в темну пору доби?"},"a":[{"uk":"Аварійна сигналізація."},{"uk":"Протитуманні фари."},{"uk":"Габаритні або стоянкові ліхтарі."}],"c":2},{"id":"h19-4","t":"h19","num":"19.4","q":{"uk":"Що вмикається на транспортному засобі під час вимушеної зупинки на дорозі в темну пору доби?"},"a":[{"uk":"Аварійна сигналізація."},{"uk":"Протитуманні фари."},{"uk":"Габаритні або стоянкові ліхтарі."},{"uk":"Габаритні або стоянкові ліхтарі спільно з аварійною сигналізацією."}],"c":3},{"id":"h19-5","t":"h19","num":"19.5","q":{"uk":"Що вмикається на транспортному засобі під час зупинки на дорозі в умовах недостатньої видимості?"},"a":[{"uk":"Стоянкові вогні."},{"uk":"Протитуманні фари."},{"uk":"Габаритні або стоянкові ліхтарі, додатково дозволяється увімкнути ближнє світло або протитуманні фари й задні протитуманні ліхтарі."},{"uk":"Габаритні або стоянкові ліхтарі одночасно з аварійною сигналізацією."}],"c":2},{"id":"h19-6","t":"h19","num":"19.6","q":{"uk":"Як необхідно вчинити в разі вимушеної зупинки на дорозі в темну пору доби або в умовах недостатньої видимості, якщо габаритні ліхтарі несправні?"},"a":[{"uk":"Поставити транспортний засіб правіше."},{"uk":"Увімкнути протитуманні фари."},{"uk":"Транспортний засіб слід прибрати за межі дороги. Якщо це неможливо, його необхідно позначити відповідно до вимог Правил дорожнього руху."}],"c":2},{"id":"h19-7","t":"h19","num":"19.7","q":{"uk":"Як дозволено використовувати протитуманні фари в умовах недостатньої видимості?"},"a":[{"uk":"Тільки разом з ближнім або дальнім світлом фар."},{"uk":"Тільки окремо від ближнього світла фар."},{"uk":"Як окремо, так і разом з ближнім або дальнім світлом фар."}],"c":2},{"id":"h19-8","t":"h19","num":"19.8","q":{"uk":"Як дозволено використовувати протитуманні фари в темну пору доби?"},"a":[{"uk":"Тільки разом з ближнім або дальнім світлом фар."},{"uk":"Тільки окремо від ближнього світла фар."},{"uk":"Як окремо, так і разом з ближнім або дальнім світлом фар."}],"c":0},{"id":"h19-9","t":"h19","num":"19.9","q":{"uk":"Чи дозволено водієві в темний час доби рухатися з протитуманними фарами, увімкненими без ближнього або дальнього світла?"},"a":[{"uk":"Заборонено."},{"uk":"Дозволено."}],"c":0},{"id":"h19-10","t":"h19","num":"19.10","q":{"uk":"У яких умовах водіям оперативних транспортних засобів дозволено використовувати фару-прожектор або фару-шукач?"},"a":[{"uk":"Під час виконання службових завдань, вживши заходів для того, щоб не засліплювати інших учасників дорожнього руху."},{"uk":"Завжди в темний час доби або в умовах недостатньої видимості."}],"c":0},{"id":"h19-11","t":"h19","num":"19.11","q":{"uk":"Чи дозволено підключати до задніх протитуманних ліхтарів сигнали гальмування?"},"a":[{"uk":"Дозволено."},{"uk":"Заборонено."}],"c":1},{"id":"h19-12","t":"h19","num":"19.12","q":{"uk":"У яких умовах дозволено використовувати задній протитуманний ліхтар?"},"a":[{"uk":"У темну пору доби на неосвітлених ділянках доріг."},{"uk":"В умовах недостатньої видимості."},{"uk":"У будь-яких умовах."}],"c":1},{"id":"h19-13","t":"h19","num":"19.13","q":{"uk":"Як ви повинні вчинити, якщо в темну пору доби вас засліпив водій зустрічного транспортного засобу?"},"a":[{"uk":"Подаючи звуковий сигнал, зупинитися."},{"uk":"Зупинитися на узбіччі."},{"uk":"Зупинитися, не змінюючи смуги руху, і увімкнути аварійну сигналізацію."}],"c":2},{"id":"h19-14","t":"h19","num":"19.14","q":{"uk":"Як повинен вчинити водій транспортного засобу, який рухається з дальнім світлом фар у темний час доби, якщо водії зустрічних транспортних засобів, що знаходяться на відстані більше ніж 250 м, періодично перемикають світло фар?"},"a":[{"uk":"Негайно переключитися на ближнє світло."},{"uk":"Негайно переключитися на протитуманні фари."},{"uk":"Переключитися на ближнє світло тільки на відстані 250 м."}],"c":0},{"id":"h19-15","t":"h19","num":"19.15","q":{"uk":"Під час руху в умовах недостатньої видимості на механічному транспортному засобі, що рухається, повинні бути ввімкнені такі зовнішні світлові пристрої:"},"a":[{"uk":"Фари ближнього світла."},{"uk":"Протитуманні фари."},{"uk":"Фари ближнього (дальнього) світла. Дозволяється увімкнути протитуманні фари як окремо, так і разом з ближнім або дальнім світлом фар."},{"uk":"Габаритні ліхтарі."}],"c":2},{"id":"h19-16","t":"h19","num":"19.16","q":{"uk":"Які зовнішні світлові пристрої повинні бути обов'язково ввімкнені під час руху на транспортному засобі, що буксирується, у темний час доби і в умовах недостатньої видимості?"},"a":[{"uk":"Задній протитуманний ліхтар та аварійна світлова сигналізація."},{"uk":"Габаритні ліхтарі та аварійна світлова сигналізація."},{"uk":"Аварійна світлова сигналізація."}],"c":1},{"id":"h19-17","t":"h19","num":"19.17","q":{"uk":"Які зовнішні світлові пристрої повинні бути ввімкнені на механічному транспортному засобі, що рухається, у темний час доби, під час сильного дощу або туману?"},"a":[{"uk":"Протитуманні фари."},{"uk":"Фари ближнього або дальнього світла."},{"uk":"Фари ближнього світла."}],"c":1},{"id":"h19-18","t":"h19","num":"19.18","q":{"uk":"Які зовнішні пристрої повинен обов'язково ввімкнути водій механічного транспортного засобу при в'їзді в тунель?"},"a":[{"uk":"Ближнє світло фар."},{"uk":"Протитуманні фари."},{"uk":"Габаритні вогні."},{"uk":"Ближнє або дальнє світло фар."}],"c":3},{"id":"h19-19","t":"h19","num":"19.19","q":{"uk":"Які зовнішні пристрої повинен ввімкнути водій механічного транспортного засобу при в'їзді в освітлений тунель?"},"a":[{"uk":"Габаритні ліхтарі."},{"uk":"Протитуманні фари."},{"uk":"Ближнє або дальнє світло фар."}],"c":2},{"id":"h19-20","t":"h19","num":"19.20","q":{"uk":"Які зовнішні пристрої повинен ввімкнути водій механічного транспортного засобу при в'їзді в будь-який тунель, незалежно від ступеня його освітлення?"},"a":[{"uk":"Габаритні ліхтарі."},{"uk":"Протитуманні фари."},{"uk":"Ближнє або дальнє світло фар."},{"uk":"Ближнє світло фар."}],"c":2},{"id":"h19-21","t":"h19","num":"19.21","q":{"uk":"Які зовнішні світлові пристрої повинні бути ввімкнені на гужових возах (санях) під час руху в темну пору доби незалежно від ступеня освітлення дороги?"},"a":[{"uk":"Досить наявності встановлених світлоповертачів."},{"uk":"Фари або ліхтарі."}],"c":1},{"id":"h19-22","t":"h19","num":"19.22","q":{"uk":"За яких умов водіям механічних транспортних засобів дозволено використовувати дальнє світло фар у темний час доби або в умовах недостатньої видимості?"},"a":[{"uk":"За умови, що дорога, по якій вони рухаються, має роздільну смугу."},{"uk":"За умови, що водій не може засліпити інших водіїв, зокрема тих, які рухаються в попутному напрямку."},{"uk":"Відповіді 1 і 2."}],"c":1},{"id":"h19-23","t":"h19","num":"19.23","q":{"uk":"У якому режимі повинні бути ввімкнені фари транспортного засобу, що рухається позаду іншого транспортного засобу, у темний час доби?"},"a":[{"uk":"У режимі ближнього світла."},{"uk":"У режимі дальнього світла."}],"c":0},{"id":"h19-24","t":"h19","num":"19.24","q":{"uk":"На якій відстані до зустрічного транспортного засобу необхідно переключити дальнє світло на ближнє в темний час доби?"},"a":[{"uk":"На відстані не менше 50 м."},{"uk":"На відстані не менше 150 м."},{"uk":"На відстані не менше 250 м."},{"uk":"На відстані не менше 350 м."}],"c":2},{"id":"h19-25","t":"h19","num":"19.25","q":{"uk":"У якому режимі у вас повинні бути ввімкнені фари при зустрічному роз'їзді вночі?"},"a":[{"uk":"У режимі дальнього світла."},{"uk":"У режимі ближнього світла."},{"uk":"У режимі протитуманних фар."}],"c":1},{"id":"h19-26","t":"h19","num":"19.26","q":{"uk":"Під час руху в темний час доби незалежно від ступеня освітлення дороги на механічному транспортному засобі, що рухається, обов'язково вмикаються такі зовнішні світлові пристрої:"},"a":[{"uk":"Габаритні вогні разом з протитуманними фарами."},{"uk":"Тільки ближнє світло фар."},{"uk":"Фари ближнього або дальнього світла."},{"uk":"Тільки протитуманні фари."}],"c":2},{"id":"h19-27","t":"h19","num":"19.27","q":{"uk":"Вночі, коли Ви наближаєтеся до зустрічного транспортного засобу, Ви увімкнете фари дальнього світла, щоб Ваш автомобіль було краще видно:"},"a":[{"uk":"Так."},{"uk":"Ні."}],"c":1,"pic":["img/hsc/19-27-1.jpg"]},{"id":"h19-28","t":"h19","num":"19.28","q":{"uk":"Дальнє світло фар рекомендовано вмикати при наближенні до зустрічних транспортних засобів:"},"a":[{"uk":"Так."},{"uk":"Ні."}],"c":1},{"id":"h19-29","t":"h19","num":"19.29","q":{"uk":"Рухаючись по не достатньо освітленій вулиці, водій легкового автомобіля повинен ввімкнути такі зовнішні світлові пристрої:"},"a":[{"uk":"Габаритні ліхтарі."},{"uk":"Фари ближнього або дальнього світла."},{"uk":"Протитуманні фари та задній протитуманний ліхтар."},{"uk":"Відповідь 1 та 3."}],"c":1,"pic":["img/hsc/19-29-1.jpg"]},{"id":"h19-30","t":"h19","num":"19.30","q":{"uk":"Чи дозволено зупинитися, змінивши смугу руху у разі засліплення?"},"a":[{"uk":"Дозволено."},{"uk":"Заборонено."}],"c":1,"pic":["img/hsc/19-30-1.jpg"]},{"id":"h19-31","t":"h19","num":"19.31","q":{"uk":"Ви рухаєтесь вночі на транспортному засобі, попереду немає інших транспортних засобів. Чи дозволено Вам увімкнути фари дальнього світла?"},"a":[{"uk":"Дозволено."},{"uk":"Заборонено."}],"c":0},{"id":"h19-32","t":"h19","num":"19.32","q":{"uk":"В темну пору доби, на неосвітлених ділянках доріг, протитуманні фари можна використовувати лише разом з ближнім або дальнім світлом фар?"},"a":[{"uk":"Ні."},{"uk":"Так."}],"c":1,"pic":["img/hsc/19-32-1.jpg"]},{"id":"h19-33","t":"h19","num":"19.33","q":{"uk":"Чи дозволено вночі вмикати задній протитуманний ліхтар при відсутності умов недостатньої видимості?"},"a":[{"uk":"Заборонено."},{"uk":"Дозволено."}],"c":0,"pic":["img/hsc/19-33-1.jpg"]},{"id":"h20-1","t":"h20","num":"20.1","q":{"uk":"Чи дозволено в цій ситуації рух через переїзд у два ряди?"},"a":[{"uk":"Заборонено."},{"uk":"Дозволено."}],"c":1,"pic":["img/hsc/20-1-1.jpg"]},{"id":"h20-2","t":"h20","num":"20.2","q":{"uk":"Як ви повинні вчинити в цій ситуації, коли на залізничному переїзді утворився затор, який змусить вас зупинитися?"},"a":[{"uk":"В'їхати на залізничний переїзд і зупинитися на ньому."},{"uk":"Об'їхати транспортні засоби, які стоять."},{"uk":"Зупинитися перед залізничним переїздом (в'їзд на нього заборонений)."}],"c":2,"pic":["img/hsc/20-2-1.jpg"]},{"id":"h20-3","t":"h20","num":"20.3","q":{"uk":"Чи дозволено в цій ситуації рух через переїзд у два ряди?"},"a":[{"uk":"Заборонено."},{"uk":"Дозволено в будь-якому випадку."},{"uk":"Дозволено, якщо це не створює перешкоди для зустрічних транспортних засобів."}],"c":0,"pic":["img/hsc/20-3-1.jpg"]},{"id":"h20-4","t":"h20","num":"20.4","q":{"uk":"Чи дозволяється самовільно відкривати шлагбаум на залізничному переїзді?"},"a":[{"uk":"Дозволено, якщо вимкнена звукова і світлова сигналізація."},{"uk":"Заборонено."},{"uk":"Дозволено на короткий час для пропуску легкового автомобіля."}],"c":1,"pic":["img/hsc/20-4-1.jpg"]},{"id":"h20-5","t":"h20","num":"20.5","q":{"uk":"Чим повинен керуватися водій транспортного засобу під час проїзду цього залізничного переїзду?"},"a":[{"uk":"Світловою і звуковою сигналізацією."},{"uk":"Вказівками і сигналами чергового по переїзду."},{"uk":"Положенням шлагбаума."},{"uk":"Дорожньої розміткою."},{"uk":"Усім переліченим вище."}],"c":4,"pic":["img/hsc/20-5-1.jpg"]},{"id":"h20-6","t":"h20","num":"20.6","q":{"uk":"Чим повинен керуватися водій транспортного засобу під час проїзду цього залізничного переїзду?"},"a":[{"uk":"Дорожніми знаками."},{"uk":"Дорожньої розміткою."},{"uk":"Світловою і звуковою сигналізацією."},{"uk":"Усім переліченим вище."},{"uk":"Тільки дорожніми знаками і дорожньою розміткою."}],"c":3,"pic":["img/hsc/20-6-1.jpg"]},{"id":"h20-7","t":"h20","num":"20.7","q":{"uk":"Чи дозволено рух через залізничний переїзд у ситуації, зображеній на малюнку?"},"a":[{"uk":"Дозволено."},{"uk":"Заборонено."}],"c":0,"pic":["img/hsc/20-7-1.jpg"]},{"id":"h20-8","t":"h20","num":"20.8","q":{"uk":"Чи дозволено рух через залізничний переїзд у ситуації, зображеній на малюнку?"},"a":[{"uk":"Дозволено."},{"uk":"Заборонено."}],"c":1,"pic":["img/hsc/20-8-1.jpg"]},{"id":"h20-9","t":"h20","num":"20.9","q":{"uk":"Як ви повинні вчинити в цій ситуації, коли на залізничному переїзді увімкнулися світлова та звукова сигналізації, а шлагбауми ще не почали опускатися?"},"a":[{"uk":"Проїхати залізничний переїзд."},{"uk":"Зупинитися в передбаченому місці, оскільки проїзд через переїзд за цих умов заборонений."},{"uk":"Зупинитися, тільки якщо шлагбауми почали опускатися."},{"uk":"Проїхати залізничний переїзд, переконавшись, що до нього не наближається поїзд."}],"c":1,"pic":["img/hsc/20-9-1.jpg"]},{"id":"h20-10","t":"h20","num":"20.10","q":{"uk":"У разі вимушеної зупинки транспортного засобу на залізничному переїзді водій зобов'язаний негайно:"},"a":[{"uk":"Висадити людей."},{"uk":"Вжити заходів для звільнення переїзду."},{"uk":"Виконати обидві дії."}],"c":2},{"id":"h20-11","t":"h20","num":"20.11","q":{"uk":"Яких заходів повинен вжити водій транспортного засобу в разі вимушеної зупинки на залізничному переїзді, якщо йому не вдається звільнити залізничний переїзд?"},"a":[{"uk":"Коли є можливість, послати двох чоловік уздовж колій в обидва боки від переїзду не менш як на 1000 м (якщо одного, то в бік імовірної появи поїзда, а на одноколійних переїздах - у бік гіршої видимості залізничної колії), пояснивши їм правила подавання сигналу зупинки машиністу поїзда (локомотива, дрезини), що наближається."},{"uk":"Залишатися біля транспортного засобу і, подаючи сигнали загальної тривоги, вживати всіх заходів для звільнення переїзду."},{"uk":"У разі появи поїзда бігти йому назустріч, подаючи сигнал зупинки."},{"uk":"Виконати все перераховане."}],"c":3},{"id":"h20-12","t":"h20","num":"20.12","q":{"uk":"Що є сигналом зупинки поїзда, який подається людиною в разі вимушеної зупинки транспортного засобу на залізничному переїзді або іншої небезпеки?"},"a":[{"uk":"Круговий рух руки із шматком яскравої тканини або будь-яким добре помітним предметом у світлий час доби, у темну пору доби і в умовах недостатньої видимості - з факелом або ліхтарем."},{"uk":"Жести руками із шматком яскравої тканини або будь-яким добре помітним предметом у світлий час доби, у темну пору доби і в умовах недостатньої видимості - з факелом або ліхтарем."},{"uk":"Обидві відповіді правильні."}],"c":0},{"id":"h20-13","t":"h20","num":"20.13","q":{"uk":"Як ви повинні вчинити в ситуації, коли при під'їзді до залізничного переїзду ви побачили поїзд, що наближається, але при цьому звукова та світлова сигналізація залізничного переїзду не увімкнена?"},"a":[{"uk":"Продовжити рух через переїзд."},{"uk":"Зупинитися в передбаченому місці, так як проїзд через переїзд заборонений."}],"c":1},{"id":"h20-14","t":"h20","num":"20.14","q":{"uk":"Як ви повинні вчинити в ситуації, якщо ви зупинилися перед залізничним переїздом на заборонний сигнал світлофора, коли поїзд вже проїхав, а світлова та звукова сигналізація ще не вимкнулися?"},"a":[{"uk":"Продовжити рух через переїзд у будь-якому випадку."},{"uk":"Продовжити рух через переїзд, тільки переконавшись у відсутності поїзда, що наближається."},{"uk":"Дочекатися виключення заборонного сигналу світлофора та звукової сигналізації, а також переконатися у відсутності поїзда, що наближається, після чого продовжити рух."}],"c":2},{"id":"h20-15","t":"h20","num":"20.15","q":{"uk":"Як ви повинні вчинити в ситуації, коли на залізничному переїзді увімкнулася світлова та звукова сигналізація, а поїзд ще не з'явився в межах видимості?"},"a":[{"uk":"Проїхати залізничний переїзд."},{"uk":"Зупинитися в передбаченому місці, так як проїзд через переїзд заборонений."}],"c":1},{"id":"h20-16","t":"h20","num":"20.16","q":{"uk":"Як ви повинні вчинити в цій ситуації, коли шлагбауми, які знаходяться перед вами, почали опускатися?"},"a":[{"uk":"Проїхати далі."},{"uk":"Зупинитися в передбаченому місці, так як проїзд через переїзд заборонений."},{"uk":"Зупинитися, тільки якщо увімкнений заборонний сигнал світлофора або увімкнена звукова сигналізація."}],"c":1},{"id":"h20-17","t":"h20","num":"20.17","q":{"uk":"Залізничним переїздом вважається:"},"a":[{"uk":"Перетин дороги з трамвайними коліями на одному рівні."},{"uk":"Перехрещення дороги із залізничними коліями на одному рівні."},{"uk":"Перехрещення дороги із залізничними коліями на різних рівнях."},{"uk":"Відповіді, зазначені в пунктах 1 та 2."}],"c":1},{"id":"h20-18","t":"h20","num":"20.18","q":{"uk":"Де водій автомобіля повинен зупинити свій транспортний засіб для пропуску поїзда, що наближається, за відсутності на переїзді засобів організації дорожнього руху?"},"a":[{"uk":"За 5 м до найближчої рейки."},{"uk":"За 10 м до найближчої рейки."},{"uk":"За 15 м до найближчої рейки."},{"uk":"За 20 м до найближчої рейки."}],"c":1},{"id":"h20-19","t":"h20","num":"20.19","q":{"uk":"У чому повинен переконатися водій при під'їзді до будь-якого залізничного переїзду?"},"a":[{"uk":"У тому, що перед переїздом є дорожня розмітка «Стоп-лінія»."},{"uk":"У тому, що перед переїздом є дорожній знак «Проїзд без зупинки заборонено»."},{"uk":"У тому, що не наближається поїзд (локомотив, дрезина)."}],"c":2},{"id":"h20-20","t":"h20","num":"20.20","q":{"uk":"Чим повинні керуватися водії транспортних засобів під час проїзду будь-яких залізничних переїздів?"},"a":[{"uk":"Сигналами і вказівками чергового по переїзду."},{"uk":"Положенням шлагбаума."},{"uk":"Світловою і звуковою сигналізацією."},{"uk":"Дорожніми знаками і дорожньою розміткою."},{"uk":"Усім переліченим вище."}],"c":4},{"id":"h20-21","t":"h20","num":"20.21","q":{"uk":"Де водіям транспортних засобів дозволено перетинати залізничні колії?"},"a":[{"uk":"Тільки на залізничних переїздах."},{"uk":"Тільки на залізничних переїздах, а якщо їх немає, то в місцях, де дорога добре проглядається в обидва боки."}],"c":0},{"id":"h20-22","t":"h20","num":"20.22","q":{"uk":"Водії транспортних засобів можуть перетинати залізничні колії лише:"},"a":[{"uk":"На залізничних переїздах з шлагбаумом."},{"uk":"На залізничних переїздах без шлагбаума."},{"uk":"У будь-якому місці, де залізничні колії добре проглядаються."},{"uk":"На будь-якому залізничному переїзді."},{"uk":"Відповіді 3 і 4."}],"c":3},{"id":"h20-23","t":"h20","num":"20.23","q":{"uk":"Що є звуковим сигналом загальної тривоги на залізничних переїздах?"},"a":[{"uk":"Серія сигналів, що складається з одного довгого і трьох коротких сигналів."},{"uk":"Серія сигналів, що складається з трьох довгих і одного короткого сигналу."},{"uk":"Серія сигналів, що складається з двох довгих і трьох коротких сигналів."}],"c":0},{"id":"h20-24","t":"h20","num":"20.24","q":{"uk":"У якому випадку Ви можете проїхати під шлагбаумом, який опускається на залізничному переїзді?"},"a":[{"uk":"Якщо потяг, який наближається, ще достатньо далеко."},{"uk":"Якщо Ви встигнете проїхати, не пошкодивши цей шлагбаум."},{"uk":"У жодному. Рух за цих умов заборонено."}],"c":2,"pic":["img/hsc/20-24-1.jpg"]},{"id":"h20-25","t":"h20","num":"20.25","q":{"uk":"Якщо ви наближаєтеся до залізничного переїзду, Ви повинні зупинитися:"},"a":[{"uk":"Перед розміткою «стоп-лінія»."},{"uk":"Перед дорожнім знаком «проїзд без зупинки заборонено»."},{"uk":"Перед світлофором так, щоб бачити сигнали."},{"uk":"В будь-якій із перерахованих вище ситуацій."}],"c":3},{"id":"h20-26","t":"h20","num":"20.26","q":{"uk":"За якої умови дозволено виконати обгін на залізничному переїзді:"},"a":[{"uk":"Якщо залізничний переїзд регульований."},{"uk":"Якщо шлагбаум піднятий."},{"uk":"Обгін на залізничному переїзді заборонено."}],"c":2},{"id":"h20-27","t":"h20","num":"20.27","q":{"uk":"За якої умови дозволено виконати обгін на залізничному переїзді:"},"a":[{"uk":"Якщо швидкість автомобіля, що рухається попереду не перевищує 30 км/год."},{"uk":"Якщо необхідно виконати обгін лише одного транспортного засобу."},{"uk":"У випадках 1 і 2."},{"uk":"Обгін на залізничному переїзді заборонено."}],"c":3},{"id":"h20-28","t":"h20","num":"20.28","q":{"uk":"Чи дозволено Вам проїхати залізничний переїзд, якщо шлагбаум не опустився, а лише увімкнулась світлова та звукова сигналізація?"},"a":[{"uk":"Дозволено."},{"uk":"Заборонено."}],"c":1},{"id":"h20-29","t":"h20","num":"20.29","q":{"uk":"Чи дозволено Вам рух через залізничний переїзд заднім ходом, якщо ви пропустили поворот праворуч?"},"a":[{"uk":"Дозволено."},{"uk":"Заборонено."}],"c":1},{"id":"h20-30","t":"h20","num":"20.30","q":{"uk":"Чи дозволено водієві в даному випадку розпочати рух заднім ходом?"},"a":[{"uk":"Дозволено."},{"uk":"Заборонено."}],"c":1,"pic":["img/hsc/20-30-1.jpg"]},{"id":"h20-31","t":"h20","num":"20.31","q":{"uk":"Чи дозволено водієві в даному випадку виконати розворот, якщо попереду і позаду нього немає транспортних засобів?"},"a":[{"uk":"Дозволено."},{"uk":"Заборонено."}],"c":1,"pic":["img/hsc/20-31-1.jpg"]},{"id":"h21-1","t":"h21","num":"21.1","q":{"uk":"У якій кількості дозволяється перевозити пасажирів в обладнаному для цього транспортному засобі?"},"a":[{"uk":"У кількості, що забезпечує безпеку перевезення пасажирів."},{"uk":"У кількості, що відповідає фактичній кількості місць транспортного засобу."},{"uk":"У кількості, передбаченій технічною характеристикою транспортного засобу."}],"c":2},{"id":"h21-2","t":"h21","num":"21.2","q":{"uk":"У якій кількості дозволено перевозити пасажирів у будь-якому транспортному засобі?"},"a":[{"uk":"Не більше ніж вісім."},{"uk":"У кількості, передбаченій технічною характеристикою транспортного засобу."},{"uk":"У кількості, при якій не перевищуються навантаження на осі, визначені технічною характеристикою транспортного засобу."}],"c":1},{"id":"h21-3","t":"h21","num":"21.3","q":{"uk":"Що забороняється водієві маршрутного транспортного засобу під час перевезення пасажирів?"},"a":[{"uk":"Розмовляти з пасажирами."},{"uk":"Їсти і пити."},{"uk":"Користуватися засобами зв’язку, тримаючи їх у руці."},{"uk":"Палити."},{"uk":"Все вищеперераховане."}],"c":4},{"id":"h21-4","t":"h21","num":"21.4","q":{"uk":"Чи дозволено водієві відчиняти двері транспортного засобу до його зупинки?"},"a":[{"uk":"Заборонено."},{"uk":"Дозволено, якщо на підніжках немає пасажирів."},{"uk":"Дозволено в будь-якому випадку."}],"c":0},{"id":"h21-5","t":"h21","num":"21.5","q":{"uk":"У якому випадку дозволено перевозити пасажирів поза кабіною транспортного засобу?"},"a":[{"uk":"В обладнаному для перевезення пасажирів кузові вантажного автомобіля з бортовою платформою."},{"uk":"В обладнаному для перевезення пасажирів кузові-фургоні вантажного автомобіля."},{"uk":"У кузові трактора."},{"uk":"Відповіді 1 і 2."},{"uk":"Відповіді 1, 2 і 3."}],"c":3},{"id":"h21-6","t":"h21","num":"21.6","q":{"uk":"Чи дозволено перевозити дітей в дитячих утримуючих системах в не пристебнутому положенні?"},"a":[{"uk":"Дозволено."},{"uk":"На розсуд батьків."},{"uk":"Заборонено."}],"c":2},{"id":"h21-7","t":"h21","num":"21.7","q":{"uk":"За яких умов дозволено перевозити дитину в легковому автомобілі без використання дитячих утримуючих систем, що дають змогу пристебнути дитину за допомогою ременів безпеки?"},"a":[{"uk":"Якщо зріст дитини менше 145 см."},{"uk":"Якщо зріст дитини 150 см і більше."},{"uk":"Якщо дитина досягла 12-річного віку.»."}],"c":1,"pic":["img/hsc/21-7-1.jpg"]},{"id":"h21-8","t":"h21","num":"21.8","q":{"uk":"Яке твердження, що стосується дитячих утримуючих систем, невірне?"},"a":[{"uk":"Діти повинні перебувати у дитячих утримуючих системах у пристебнутому положенні."},{"uk":"Дитячі утримуючі системи встановлюють на місцях для сидіння, крім першого ряду."},{"uk":"У разі перевезення дитини віком до трьох років у легковому автомобілі на місці для сидіння першого ряду допускається встановлення дитячих утримуючих систем, які встановлюються проти напрямку руху без відключення фронтальної подушки безпеки цього місця для сидіння."}],"c":2,"pic":["img/hsc/21-8-1.jpg"]},{"id":"h21-9","t":"h21","num":"21.9","q":{"uk":"Яке найбезпечніше місце для розташування дитячої утримуючої системи в автомобілі?"},"a":[{"uk":"Середнє заднє сидіння."},{"uk":"Переднє сидіння."},{"uk":"Сидіння позаду водія."}],"c":0,"pic":["img/hsc/21-9-1.jpg"]},{"id":"h21-10","t":"h21","num":"21.10","q":{"uk":"Чи є обов’язковим відключення фронтальної подушки безпеки цього місця для сидіння при встановленні дитячої утримуючої системи на передньому сидінні?"},"a":[{"uk":"Так."},{"uk":"Ні."}],"c":0,"pic":["img/hsc/21-10-1.jpg"]},{"id":"h21-11","t":"h21","num":"21.11","q":{"uk":"У разі перевезення дитини віком до трьох років у легковому автомобілі на місці для сидіння першого ряду, дитячі утримуючі системи встановлюються:"},"a":[{"uk":"За напрямком руху легкового автомобіля."},{"uk":"Проти напрямку руху легкового автомобіля."}],"c":1,"pic":["img/hsc/21-11-1.jpg"]},{"id":"h21-12","t":"h21","num":"21.12","q":{"uk":"У якому положенні повинні перебувати діти у дитячих утримуючих системах?"},"a":[{"uk":"У пристебнутому положенні."},{"uk":"У положенні, що забезпечує дитині комфортне перебування."}],"c":0,"pic":["img/hsc/21-12-1.jpg"]},{"id":"h22-1","t":"h22","num":"22.1","q":{"uk":"Понад яку мінімальну відстань від зовнішнього краю переднього або заднього габаритного ліхтаря повинен виступати вантаж за шириною, щоб його потрібно було обов'язково позначити сигнальними щитками або прапорцями згідно з Правилами дорожнього руху?"},"a":[{"uk":"На 0,2 м."},{"uk":"На 0,3 м."},{"uk":"На 0,4 м."},{"uk":"На 0,5 м."},{"uk":"На 0,6 м."}],"c":2},{"id":"h22-2","t":"h22","num":"22.2","q":{"uk":"Понад яку мінімальну відстань від зовнішнього краю переднього або заднього габариту транспортного засобу повинен виступати вантаж за довжиною, щоб було обов'язковим його позначення сигнальними щитками або прапорцями згідно з Правилами дорожнього руху?"},"a":[{"uk":"На 0,4 м."},{"uk":"На 0,5 м."},{"uk":"На 1 м."},{"uk":"На 2 м."}],"c":2},{"id":"h22-3","t":"h22","num":"22.3","q":{"uk":"Яких заходів безпеки зобов'язаний вжити водій транспортного засобу, що перевозить вантаж, перед початком руху, а також під час руху?"},"a":[{"uk":"Забезпечити надійність розташування вантажу."},{"uk":"Забезпечити надійність кріплення вантажу."},{"uk":"Усе перелічене вище."}],"c":2},{"id":"h22-4","t":"h22","num":"22.4","q":{"uk":"Щоб запобігти падінню і волочіння вантажу, травмуванню супроводжуючих осіб або створенню перешкод для дорожнього руху, водій, що перевозить вантаж, зобов'язаний:"},"a":[{"uk":"Перед початком руху перевірити надійність розташування і кріплення вантажу."},{"uk":"Під час руху контролювати надійність розташування і кріплення вантажу."},{"uk":"Виконувати обидві дії."}],"c":2},{"id":"h22-5","t":"h22","num":"22.5","q":{"uk":"У разі дотримання яких умов дозволяється перевезення вантажів?"},"a":[{"uk":"За умови, що вантаж не наражає на небезпеку учасників дорожнього руху, не створює шуму, не піднімає пилу та не забруднює проїзну частину і навколишнє середовище."},{"uk":"За умови, що вантаж не порушує стійкості транспортного засобу і не утруднює керування транспортним засобом."},{"uk":"За умови, що вантаж не обмежує водієві оглядовості."},{"uk":"За умови, що вантаж не закриває зовнішніх світлових приладів, світлоповертачів, номерних і розпізнавальних знаків, а також не перешкоджає сприйманню сигналів, що подаються рукою."},{"uk":"У разі дотримання всіх перелічених вище умов."}],"c":4},{"id":"h22-6","t":"h22","num":"22.6","q":{"uk":"Перед початком руху, а також під час руху водій транспортного засобу зобов'язаний перевірити надійність розташування і кріплення вантажу, щоб вантаж:"},"a":[{"uk":"Не наражав на небезпеку учасників дорожнього руху, не створював шуму, не піднімав пилу та не забруднював проїзну частину і навколишнє середовище."},{"uk":"Не обмежував водієві оглядовості."},{"uk":"Не падав, не волочився, не травмував супроводжуючих осіб і не створював перешкод для руху."},{"uk":"Відповіді 1 і 2."},{"uk":"Відповіді 1, 2 і 3."}],"c":4},{"id":"h23-1","t":"h23","num":"23.1","q":{"uk":"При дотриманні яких умов дозволяється буксирування транспортного засобу з несправною гальмовою системою на жорсткому зчепленні?"},"a":[{"uk":"При дотриманні максимальної швидкості руху в 40 км/год."},{"uk":"За умови, що фактична маса буксируваного транспортного засобу не перевищує половини фактичної маси транспортного засобу, що буксирує."}],"c":1},{"id":"h23-2","t":"h23","num":"23.2","q":{"uk":"Жорстке зчеплення повинно забезпечувати відстань між транспортними засобами не більше ніж:"},"a":[{"uk":"1 м."},{"uk":"2 м."},{"uk":"3 м."},{"uk":"4 м."},{"uk":"5 м."}],"c":3,"pic":["img/hsc/23-2-1.jpg"]},{"id":"h23-3","t":"h23","num":"23.3","q":{"uk":"Чи можуть перебувати пасажири в буксируваному легковому автомобілі в разі буксирування на жорсткому або гнучкому зчепленні?"},"a":[{"uk":"Не можуть."},{"uk":"Можуть."}],"c":1},{"id":"h23-4","t":"h23","num":"23.4","q":{"uk":"Де повинні перебувати пасажири у разі буксирування транспортного засобу способом часткового навантаження?"},"a":[{"uk":"В обох транспортних засобах."},{"uk":"Тільки в кузові вантажного автомобіля, що буксирує."},{"uk":"Тільки в кабіні і кузові автомобіля, що буксирує."},{"uk":"Лише в кабіні автомобіля, що буксирує."}],"c":3},{"id":"h23-5","t":"h23","num":"23.5","q":{"uk":"Під час буксирування яким із способів пасажири можуть перебувати в буксируваному транспортному засобі?"},"a":[{"uk":"Під час буксирування на жорсткому зчепленні – у вантажному автомобілі."},{"uk":"Під час буксирування на жорсткому зчепленні в світлу пору доби."},{"uk":"Під час буксирування на жорсткому або гнучкому зчепленні – в легковому автомобілі."},{"uk":"Завжди, під час будь-якого буксирування – в будь-якому буксируваному автомобілі."}],"c":2},{"id":"h23-6","t":"h23","num":"23.6","q":{"uk":"Буксируванням вважається переміщення одним транспортним засобом іншого, яке не належить до експлуатації автопоїздів (транспортних составів):"},"a":[{"uk":"На жорсткому або гнучкому зчепленні."},{"uk":"Способом часткового навантаження на платформу чи на спеціальне опорне пристосування."},{"uk":"Способом повного завантаження на платформу або спеціальний опорний пристрій."},{"uk":"Відповіді, зазначені в пунктах 1, 2."},{"uk":"Відповіді, зазначені в пунктах 1, 2, 3."}],"c":3},{"id":"h23-7","t":"h23","num":"23.7","q":{"uk":"Чи дозволяється буксирування на гнучкому зчепленні під час ожеледиці?"},"a":[{"uk":"Дозволяється зі швидкістю не більше ніж 40 км/год."},{"uk":"Забороняється."},{"uk":"Дозволяється при довжині гнучкого зчеплення понад 5 м."},{"uk":"Дозволяється на дорогах з неінтенсивним рухом."}],"c":1},{"id":"h23-8","t":"h23","num":"23.8","q":{"uk":"Яким способом дозволено виконувати буксирування транспортних засобів під час ожеледиці?"},"a":[{"uk":"Тільки на жорсткому зчепленні."},{"uk":"Тільки способом часткового навантаження."},{"uk":"Тільки на гнучкому зчепленні."},{"uk":"На жорсткому зчепленні або способом часткового навантаження."}],"c":3},{"id":"h23-9","t":"h23","num":"23.9","q":{"uk":"У якому випадку дозволяється буксирування двох і більше транспортних засобів?"},"a":[{"uk":"Буксирування понад одного транспортного засобу заборонене."},{"uk":"Під час руху за межами населеного пункту."},{"uk":"Під час руху по дорогах з неінтенсивним рухом."},{"uk":"За погодженням із уповноваженим підрозділом Національної поліції."}],"c":3},{"id":"h23-10","t":"h23","num":"23.10","q":{"uk":"Яким способом необхідно буксирувати транспортний засіб із рульовим керуванням, що не діє?"},"a":[{"uk":"Тільки на гнучкому зчепленні."},{"uk":"Тільки на жорсткому зчепленні."},{"uk":"На жорсткому зчепленні або способом часткового навантаження."},{"uk":"Лише способом часткового навантаження."}],"c":3},{"id":"h23-11","t":"h23","num":"23.11","q":{"uk":"Яким способом повинне здійснюватися буксирування немеханічних транспортних засобів?"},"a":[{"uk":"На гнучкому або жорсткому зчепленні."},{"uk":"Лише на гнучкому зчепленні."},{"uk":"Лише на жорсткому зчепленні."}],"c":2},{"id":"h23-12","t":"h23","num":"23.12","q":{"uk":"За яких умов повинне здійснюватися буксирування транспортних засобів?"},"a":[{"uk":"За умови наявності технічно справного зчіпного пристрою лише у буксируваного транспортного засобу."},{"uk":"За умови наявності технічно справного зчіпного пристрою тільки у транспортного засобу, що буксирує."},{"uk":"За умови наявності справного зчіпного пристрою у буксируваного транспортного засобу, а також у транспортного засобу, що буксирує."}],"c":2},{"id":"h23-13","t":"h23","num":"23.13","q":{"uk":"Яка відстань має бути забезпечена між транспортними засобами у разі буксирування на гнучкому зчепленні?"},"a":[{"uk":"3–5 м."},{"uk":"4–5 м."},{"uk":"4–6 м."},{"uk":"5–7 м."},{"uk":"4–7 м."}],"c":2},{"id":"h23-14","t":"h23","num":"23.14","q":{"uk":"Як повинно бути позначене гнучке зчеплення?"},"a":[{"uk":"Через кожен метр – сигнальними щитками або прапорцями розміром 200 × 200 мм із нанесеними на них по діагоналі червоними і білими смугами."},{"uk":"З використанням покриття із світлоповертального матеріалу."},{"uk":"Одним із вищевказаних способів."}],"c":2},{"id":"h23-15","t":"h23","num":"23.15","q":{"uk":"У разі буксирування транспортного засобу на гнучкому зчепленні в буксируваному транспортному засобі повинні бути справні такі системи:"},"a":[{"uk":"Тільки рульове керування."},{"uk":"Тільки гальмова система."},{"uk":"Рульове керування і гальмова система."}],"c":2},{"id":"h23-16","t":"h23","num":"23.16","q":{"uk":"З якими із перерахованих несправностей заборонене буксирування транспортних засобів на гнучкому зчепленні?"},"a":[{"uk":"З несправною гальмовою системою."},{"uk":"З несправним рульовим керуванням."},{"uk":"Із несправною паливною системою."},{"uk":"З несправною підвіскою."},{"uk":"Із несправними гальмовою системою і рульовим керуванням."}],"c":4},{"id":"h23-17","t":"h23","num":"23.17","q":{"uk":"Із якими з несправностей заборонене буксирування усіх транспортних засобів на жорсткому зчепленні?"},"a":[{"uk":"Із несправним рульовим керуванням."},{"uk":"З негерметичною гальмовою системою."},{"uk":"З несправною аварійною сигналізацією."},{"uk":"Відповіді 1, 2 і 3."}],"c":0},{"id":"h23-18","t":"h23","num":"23.18","q":{"uk":"Чи дозволене буксирування транспортних засобів на жорсткому або гнучкому зчепленні з несправним рульовим керуванням?"},"a":[{"uk":"Заборонено."},{"uk":"Дозволено."}],"c":0},{"id":"h23-19","t":"h23","num":"23.19","q":{"uk":"За якої умови під час буксирування транспортного засобу на жорсткому зчепленні в буксируваному транспортному засобі може бути відсутній водій?"},"a":[{"uk":"Завжди."},{"uk":"Під час буксирування у населених пунктах."},{"uk":"За умови, що конструкція жорсткого зчеплення забезпечує буксируваному транспортному засобу повторення траєкторії руху транспортного засобу, що буксирує, незалежно від величини поворотів."},{"uk":"Відповіді 1, 2 і 3."}],"c":2},{"id":"h23-20","t":"h23","num":"23.20","q":{"uk":"Чи дозволяється буксирування транспортного засобу з причепом?"},"a":[{"uk":"Забороняється."},{"uk":"Дозволяється."}],"c":1},{"id":"h24-1","t":"h24","num":"24.1","q":{"uk":"Чи дозволено навчання водінню транспортного засобу на дорогах, позначених такими дорожніми знаками?"},"a":[{"uk":"Дозволено."},{"uk":"Заборонено."}],"c":1,"pic":["img/hsc/24-1-1.jpg"]},{"id":"h24-2","t":"h24","num":"24.2","q":{"uk":"Чи дозволена навчальна їзда в житлових зонах?"},"a":[{"uk":"Заборонена."},{"uk":"Дозволена."},{"uk":"Дозволена під час руху по навчальному маршруту."}],"c":0,"pic":["img/hsc/24-2-1.jpg"]},{"id":"h24-3","t":"h24","num":"24.3","q":{"uk":"Яким (-ми) із дорожніх знаків позначається дорога, на якій не заборонена навчальна їзда на легковому автомобілі?"},"a":[{"uk":"Знаками 3, 4 і 5."},{"uk":"Знаками 4 і 5."},{"uk":"Знаками 1, 2, 4 і 5."},{"uk":"Всіма зазначеними знаками."}],"c":1,"pic":["img/hsc/24-3-1.jpg"]},{"id":"h24-4","t":"h24","num":"24.4","q":{"uk":"Яким із дорожніх знаків позначається дорога, на якій заборонена навчальна їзда?"},"a":[{"uk":"Всіма."},{"uk":"Знаками 1, 2, 3 і 5."},{"uk":"Знаками 1, 2 і 3."},{"uk":"Знаками 1, 2, 3 і 4."},{"uk":"Знаками 1, 2 і 5."}],"c":2,"pic":["img/hsc/24-4-1.jpg"]},{"id":"h24-5","t":"h24","num":"24.5","q":{"uk":"Обов’язковою умовою, за якої дозволено навчатися водінню транспортного засобу, є:"},"a":[{"uk":"Наявність мінімальних навичок водіння."},{"uk":"Досягнення 18-річного віку."},{"uk":"Відсутність медичних протипоказань, що підтверджується дійсною медичною довідкою встановленого зразка."},{"uk":"Відповіді 1, 2 і 3."}],"c":2},{"id":"h24-6","t":"h24","num":"24.6","q":{"uk":"Початкове навчання водінню транспортного засобу повинно проводитися:"},"a":[{"uk":"На закритих майданчиках, автодромах або у місцях, де відсутні інші учасники дорожнього руху."},{"uk":"Одразу на вулицях населеного пункту, де є інші учасники дорожнього руху, а в кінці на автодромі."},{"uk":"На складних перехрестях і дорогах з одностороннім рухом."}],"c":0},{"id":"h24-7","t":"h24","num":"24.7","q":{"uk":"Чим із переліченого мають бути обладнані автомобілі з механічною коробкою передач, що систематично використовуються для навчання водіння?"},"a":[{"uk":"Додатковими педалями зчеплення і гальма, а також педаллю акселератора (якщо конструкція транспортного засобу допускає можливість обладнання такою педаллю)."},{"uk":"Дзеркалом або дзеркалами заднього виду для спеціаліста з підготовки водіїв, а також розпізнавальними знаками «Навчальний транспортний засіб», встановленими відповідно до вимог Правил дорожнього руху."},{"uk":"Правильні відповіді 1 і 2."}],"c":2},{"id":"h24-8","t":"h24","num":"24.8","q":{"uk":"Автомобілі, що систематично використовуються для навчання водіння, мають бути обладнані:"},"a":[{"uk":"Розпізнавальними знаками «Навчальний транспортний засіб», встановленими відповідно до вимог Правил дорожнього руху."},{"uk":"Додатковими педалями зчеплення (якщо конструкція транспортного засобу передбачає педаль зчеплення), акселератора (якщо конструкція транспортного засобу допускає можливість обладнання такою педаллю) і гальмування."},{"uk":"Дзеркалом або дзеркалами заднього виду для спеціаліста з підготовки водіїв."},{"uk":"Правильні відповіді 1 і 2."},{"uk":"Правильні відповіді 1, 2 і 3."}],"c":4},{"id":"h24-9","t":"h24","num":"24.9","q":{"uk":"Чи дозволена навчальна їзда на дорогах без присутності спеціаліста з підготовки водіїв?"},"a":[{"uk":"Заборонена."},{"uk":"Дозволена за умови присутності водія зі стажем не менше трьох років."},{"uk":"Дозволена в присутності будь-якого досвідченого водія."}],"c":0},{"id":"h24-10","t":"h24","num":"24.10","q":{"uk":"Де має проводитися початкове навчання водінню транспортного засобу?"},"a":[{"uk":"Тільки на закритих майданчиках і автодромах."},{"uk":"Тільки в місцях, де відсутні інші учасники дорожнього руху."},{"uk":"На дорогах з неінтенсивним рухом."},{"uk":"На закритих майданчиках, автодромах або у місцях, де немає інших учасників дорожнього руху."}],"c":3},{"id":"h24-11","t":"h24","num":"24.11","q":{"uk":"Чи повинна особа, яка навчається водінню транспортного засобу, знати і виконувати вимоги Правил дорожнього руху?"},"a":[{"uk":"Не повинна."},{"uk":"Повинна обов'язково."}],"c":1},{"id":"h24-12","t":"h24","num":"24.12","q":{"uk":"З якого віку дозволено навчатися водінню автомобіля?"},"a":[{"uk":"З 14 років."},{"uk":"З 16 років."},{"uk":"З 17 років."},{"uk":"З 18 років."},{"uk":"З 19 років."}],"c":1},{"id":"h24-13","t":"h24","num":"24.13","q":{"uk":"Особа, яка навчається водінню транспортного засобу:"},"a":[{"uk":"Не зобов’язана знати вимоги Правил дорожнього руху."},{"uk":"Може розпочати навчання водінню до вивчення правил проїзду перехресть."},{"uk":"Зобов’язана знати і виконувати вимоги Правил дорожнього руху."}],"c":2},{"id":"h24-14","t":"h24","num":"24.14","q":{"uk":"Чи дозволено особам, які навчаються водінню, не пристібатись під час руху в населеному пункті?"},"a":[{"uk":"Дозволено."},{"uk":"Заборонено."}],"c":1,"pic":["img/hsc/24-14-1.jpg"]},{"id":"h25-1","t":"h25","num":"25.1","q":{"uk":"Як позначають транспортні засоби, що рухаються в колоні, якщо їх не супроводжують оперативні транспортні засоби?"},"a":[{"uk":"На кожному транспортному засобі спереду і ззаду встановлюють розпізнавальний знак «Колона»."},{"uk":"На кожному транспортному засобі вмикається ближнє світло фар."},{"uk":"На кожному транспортному засобі вмикаються денні ходові вогні або ближнє світло фар."},{"uk":"Відповіді 1 і 2."},{"uk":"Відповіді 1 і 3."}],"c":3},{"id":"h25-2","t":"h25","num":"25.2","q":{"uk":"Як позначають транспортні засоби, що рухаються в колоні, яку супроводжують оперативні транспортні засоби з увімкненими червоним, синім і червоним, зеленим або синім і зеленим проблисковими маячками та (або) спеціальними звуковими сигналами?"},"a":[{"uk":"На кожному транспортному засобі в обов'язковому порядку встановлюється розпізнавальний знак «Колона»."},{"uk":"На кожному транспортному засобі вмикається ближнє світло фар."},{"uk":"На кожному транспортному засобі вмикаються денні ходові вогні або ближнє світло фар."},{"uk":"Відповіді 1 і 2."},{"uk":"Відповіді 1 і 3."}],"c":1},{"id":"h25-3","t":"h25","num":"25.3","q":{"uk":"Як повинні розміщуватися на дорозі транспортні засоби колони?"},"a":[{"uk":"Колона повинна рухатися лише в один ряд якнайближче до правого краю проїзної частини."},{"uk":"Колона може рухатися в будь-якій смузі."},{"uk":"Колона повинна рухатися лише в один ряд якнайближче до правого краю проїзної частини, за винятком випадків, коли її супроводжують оперативні транспортні засоби."}],"c":2},{"id":"h25-4","t":"h25","num":"25.4","q":{"uk":"Швидкість руху колони та дистанція між транспортними засобами встановлюються:"},"a":[{"uk":"Тільки старшим колони відповідно до вимог Правил дорожнього руху на певній ділянці дороги."},{"uk":"Тільки за режимом руху головної машини відповідно до вимог Правил дорожнього руху на певній ділянці дороги."},{"uk":"Старшим колони або за режимом руху головної машини відповідно до вимог Правил дорожнього руху на певній ділянці дороги."}],"c":2},{"id":"h25-5","t":"h25","num":"25.5","q":{"uk":"Як повинна рухатися колона, яку не супроводжують оперативні транспортні засоби, щоб не створювати перешкод транспортним засобам, що обганяють?"},"a":[{"uk":"Рухатися лише в один ряд якнайближче до правого краю проїзної частини."},{"uk":"Рухатися зі швидкістю не більше ніж 50 км/год."},{"uk":"Повинна бути розділена на групи до п'яти транспортних засобів у кожній, дистанція між групами повинна бути достатньою для виконання обгону."},{"uk":"Відповіді 1, 2 і 3."},{"uk":"Відповіді 1 і 3."}],"c":4},{"id":"h25-6","t":"h25","num":"25.6","q":{"uk":"Під час зупинки колони на дорозі на всіх транспортних засобах колони вмикаються:"},"a":[{"uk":"Протитуманні фари."},{"uk":"Ближнє світло фар."},{"uk":"Аварійна світлова сигналізація."},{"uk":"Проблискові маячки оранжевого кольору."},{"uk":"Відповіді 3 і 4."}],"c":2},{"id":"h25-7","t":"h25","num":"25.7","q":{"uk":"Чи можуть сторонні транспортні засоби займати місце для постійного руху в колоні, яку не супроводжують оперативні транспортні засоби?"},"a":[{"uk":"Не можуть."},{"uk":"Можуть."}],"c":0},{"id":"h25-8","t":"h25","num":"25.8","q":{"uk":"У якому випадку стороннім транспортним засобам дозволено прилаштовуватися в колону, яка їде без супроводу оперативних транспортних засобів?"},"a":[{"uk":"Для подальшого руху в ній."},{"uk":"У разі виконання випередження колони."},{"uk":"У разі виконання обгону колони."}],"c":2},{"id":"h26-1","t":"h26","num":"26.1","q":{"uk":"Житловою зоною вважаються: 5.34 5.53"},"a":[{"uk":"Дворові території, а також частини населених пунктів, позначені дорожнім знаком 5.53."},{"uk":"Дворові території, а також частини населених пунктів, позначені дорожнім знаком 5.34."}],"c":1,"pic":["img/hsc/26-1-1.jpg","img/hsc/26-1-2.jpg"]},{"id":"h26-2","t":"h26","num":"26.2","q":{"uk":"Виїжджаючи із житлової зони, водій синього автомобіля повинен дати дорогу:"},"a":[{"uk":"Пішоходу і велосипедисту."},{"uk":"Автомобілю і велосипеду."},{"uk":"Пішоходу і автомобілю."}],"c":2,"pic":["img/hsc/26-2-1.jpg"]},{"id":"h26-3","t":"h26","num":"26.3","q":{"uk":"Кому дозволено в'їзд у пішохідну зону?"},"a":[{"uk":"Транспортним засобам, що обслуговують громадян і підприємства, які розташовані у зазначеній зоні."},{"uk":"Транспортним засобам, що належать громадянам, які проживають або працюють у цій зоні."},{"uk":"Автомобілям (мотоколяскам), позначеним розпізнавальним знаком «Водій з інвалідністю», якими керують водії з інвалідністю або водії, які перевозять пасажирів з інвалідністю."},{"uk":"Відповіді 1, 2 і 3."}],"c":3,"pic":["img/hsc/26-3-1.jpg"]},{"id":"h26-4","t":"h26","num":"26.4","q":{"uk":"Чи дозволяється навчальна їзда в житловій зоні?"},"a":[{"uk":"Дозволяється."},{"uk":"Дозволяється з особливою обережністю."},{"uk":"Забороняється."}],"c":2,"pic":["img/hsc/26-4-1.jpg"]},{"id":"h26-5","t":"h26","num":"26.5","q":{"uk":"Виїжджаючи з пішохідної зони, водій синього автомобіля повинен дати дорогу:"},"a":[{"uk":"Пішоходу."},{"uk":"Автомобілю."},{"uk":"Пішоходу і автомобілю."}],"c":2,"pic":["img/hsc/26-5-1.jpg"]},{"id":"h26-6","t":"h26","num":"26.6","q":{"uk":"Чи повинен водій транспортного засобу, який рухається у житловій або пішохідній зоні, поступатися дорогою пішоходам, які перебувають на проїжджій частині?"},"a":[{"uk":"Повинен завжди."},{"uk":"Не повинен."}],"c":0,"pic":["img/hsc/26-6-1.jpg"]},{"id":"h26-7","t":"h26","num":"26.7","q":{"uk":"Чи дозволений транзитний рух транспортних засобів у житловій зоні?"},"a":[{"uk":"Заборонено."},{"uk":"Дозволено тільки найкоротшим шляхом."},{"uk":"Дозволено."}],"c":0},{"id":"h26-8","t":"h26","num":"26.8","q":{"uk":"Що з перерахованого заборонено в житлових зонах?"},"a":[{"uk":"Стоянка з працюючим двигуном."},{"uk":"Транзитний рух."},{"uk":"Рух пішоходів по проїжджій частині."},{"uk":"Відповіді 1 і 2."},{"uk":"Відповіді 1, 2 і 3."}],"c":3},{"id":"h26-9","t":"h26","num":"26.9","q":{"uk":"Дотримуючись яких з умов, пішоходи можуть рухатися по проїжджій частині житлових і пішохідних зон?"},"a":[{"uk":"Рухатися по проїжджій частині, не створюючи безпідставних перешкод для руху транспортних засобів."},{"uk":"Рухатися по проїжджій частині лише в світлий час доби."},{"uk":"Рухатися по проїжджій частині, поступаючись дорогою транспортним засобам."}],"c":0},{"id":"h26-10","t":"h26","num":"26.10","q":{"uk":"Де дозволено рухатися пішоходам у житлових і пішохідних зонах?"},"a":[{"uk":"Тільки по тротуарах."},{"uk":"По тротуарах і по проїжджій частині."},{"uk":"По тротуарах і по проїжджій частині в разі відсутності тротуарів."}],"c":1},{"id":"h26-11","t":"h26","num":"26.11","q":{"uk":"Де повинні бути поставлені на стоянку транспортні засоби в житлових зонах?"},"a":[{"uk":"У спеціально відведених місцях."},{"uk":"У будь-якому місці за умови, що це не утруднює рух пішоходів."},{"uk":"Відповіді 1 і 2."}],"c":0},{"id":"h26-12","t":"h26","num":"26.12","q":{"uk":"Чи дозволено водієві зеленого автомобіля поставити автомобіль на стоянку так як показано на малюнку?"},"a":[{"uk":"Дозволено."},{"uk":"Заборонено."}],"c":1,"pic":["img/hsc/26-12-1.jpg"]},{"id":"h26-13","t":"h26","num":"26.13","q":{"uk":"Правила щодо руху у житловій зоні поширюються на будь-яку дворову територію, незалежно від того, чи позначена вона відповідним дорожнім знаком:"},"a":[{"uk":"Так."},{"uk":"Ні."}],"c":0},{"id":"h27-1","t":"h27","num":"27.1","q":{"uk":"Яким транспортним засобам дозволено рух по автомагістралі?"},"a":[{"uk":"Автомобілям, якими керують водії зі стажем водіння до двох років."},{"uk":"Вантажним автомобілям з дозволеною максимальною масою понад 3,5 т."},{"uk":"Тракторам, самохідним машинам і механізмам."},{"uk":"Відповіді 1 і 2."}],"c":3,"pic":["img/hsc/27-1-1.jpg"]},{"id":"h27-2","t":"h27","num":"27.2","q":{"uk":"Чи дозволено на автомагістралях рух механічних транспортних засобів, швидкість яких за технічною характеристикою або їхнім станом менше 40 км/год?"},"a":[{"uk":"Дозволено."},{"uk":"Заборонено."}],"c":1,"pic":["img/hsc/27-2-1.jpg"]},{"id":"h27-3","t":"h27","num":"27.3","q":{"uk":"Що з перерахованого заборонено на автомагістралі?"},"a":[{"uk":"Рух із причепами, а також буксирування."},{"uk":"Рух заднім ходом."},{"uk":"Рух тракторів, самохідних машин і механізмів, а також велосипедів."},{"uk":"Відповіді 1, 2 і 3."},{"uk":"Відповіді 2 і 3."}],"c":4,"pic":["img/hsc/27-3-1.jpg"]},{"id":"h27-4","t":"h27","num":"27.4","q":{"uk":"У якому місці дороги для автомобілів дозволена зупинка транспортних засобів?"},"a":[{"uk":"У будь-якому місці, але тільки на узбіччі."},{"uk":"У місцях, позначених знаком «Місце відпочинку»."},{"uk":"У місцях, позначених знаком «Місце для стоянки»."},{"uk":"Відповіді 2 і 3."},{"uk":"Відповіді 1, 2 і 3."}],"c":3,"pic":["img/hsc/27-4-1.jpg"]},{"id":"h27-5","t":"h27","num":"27.5","q":{"uk":"Чи дозволений розворот у технологічних розривах розділювальної смуги на автомагістралі?"},"a":[{"uk":"Дозволений."},{"uk":"Дозволений, якщо дорога добре проглядається в обидві сторони."},{"uk":"Заборонений."}],"c":2,"pic":["img/hsc/27-5-1.jpg"]},{"id":"h27-6","t":"h27","num":"27.6","q":{"uk":"Де пішоходам дозволено переходити проїжджу частину автомагістралі?"},"a":[{"uk":"По наземних пішохідних переходах."},{"uk":"По лініях тротуарів."},{"uk":"По підземних або надземних пішохідних переходах."},{"uk":"Відповіді 1, 2 і 3."}],"c":2},{"id":"h27-7","t":"h27","num":"27.7","q":{"uk":"Що з перерахованого заборонено на дорозі для автомобілів?"},"a":[{"uk":"Рух заднім ходом."},{"uk":"Навчальна їзда."},{"uk":"Зупинка поза спеціальними місцями для стоянки, позначеними дорожніми знаками «Місце відпочинку» і «Місце для стоянки»."},{"uk":"Рух тракторів, самохідних машин і механізмів."},{"uk":"Все перераховане вище."}],"c":4},{"id":"h27-8","t":"h27","num":"27.8","q":{"uk":"Чи повинні водії транспортних засобів, які виїжджають на автомагістраль або дорогу для автомобілів, пропускати транспортні засоби, що рухаються по цих дорогах?"},"a":[{"uk":"Не повинні."},{"uk":"Повинні завжди."},{"uk":"Повинні, тільки якщо встановлений знак «Дати дорогу»."}],"c":1},{"id":"h27-9","t":"h27","num":"27.9","q":{"uk":"Чи дозволяється навчальна їзда на автомагістралі?"},"a":[{"uk":"Дозволяється."},{"uk":"Дозволяється лише у світлу пору доби."},{"uk":"Забороняється."}],"c":2},{"id":"h27-10","t":"h27","num":"27.10","q":{"uk":"Чи дозволено транспортним засобам рух заднім ходом на автомагістралі?"},"a":[{"uk":"Дозволено за умови забезпечення безпеки руху."},{"uk":"Заборонено."},{"uk":"Дозволено, якщо неможливо під'їхати до об'єкта іншим способом."}],"c":1},{"id":"h27-11","t":"h27","num":"27.11","q":{"uk":"Чи дозволяється транспортним засобам виконувати розворот на автомагістралі?"},"a":[{"uk":"Дозволяється, тільки якщо дорога добре проглядається."},{"uk":"Забороняється."},{"uk":"Дозволяється."}],"c":1},{"id":"h27-12","t":"h27","num":"27.12","q":{"uk":"У якому місці автомагістралі дозволена зупинка транспортних засобів?"},"a":[{"uk":"У місцях, позначених знаками «Місце відпочинку» і «Місце для стоянки»."},{"uk":"У місцях, позначених знаком «Пункт зупинки автобуса»."},{"uk":"Відповіді 1 і 2."},{"uk":"У будь-якому місці, але тільки на узбіччі."}],"c":0},{"id":"h27-13","t":"h27","num":"27.13","q":{"uk":"Як повинен діяти водій у разі вимушеної зупинки на автомагістралі чи дорозі для автомобілів?"},"a":[{"uk":"Ввімкнути аварійну сигналізацію або встановити знак аварійної зупинки або миготливий червоний ліхтар."},{"uk":"Вжити заходів для того, щоб прибрати транспортний засіб за межі проїжджої частини праворуч."},{"uk":"Виконати обидві дії."}],"c":2},{"id":"h28-1","t":"h28","num":"28.1","q":{"uk":"Який зі способів буксирування заборонений на гірських дорогах?"},"a":[{"uk":"Буксирування на гнучкому зчепленні."},{"uk":"Буксирування на жорсткому зчепленні."},{"uk":"Буксирування способом часткового навантаження."},{"uk":"Буксирування будь-яким способом."}],"c":0,"pic":["img/hsc/28-1-1.jpg"]},{"id":"h28-2","t":"h28","num":"28.2","q":{"uk":"На гірських дорогах і крутих спусках, де зустрічний роз'їзд утруднено, дати дорогу повинен:"},"a":[{"uk":"Водій транспортного засобу, що рухається на спуск."},{"uk":"Водій транспортного засобу, що рухається на підйом."},{"uk":"Водій транспортного засобу з найбільшими габаритами."}],"c":0},{"id":"h28-3","t":"h28","num":"28.3","q":{"uk":"На гірських дорогах і крутих спусках, де зустрічний роз'їзд утруднено, перевагу в русі має:"},"a":[{"uk":"Водій транспортного засобу, що рухається на спуск."},{"uk":"Водій транспортного засобу, що рухається на підйом."},{"uk":"Водій транспортного засобу з найбільшими габаритами."}],"c":1},{"id":"h28-4","t":"h28","num":"28.4","q":{"uk":"Під час руху на спуск на вашій смузі руху виникла перешкода. Як ви роз'їдетеся із зустрічним транспортним засобом?"},"a":[{"uk":"Поступитеся йому дорогою."},{"uk":"Маючи перевагу в русі, проїдете першим."}],"c":0},{"id":"h28-5","t":"h28","num":"28.5","q":{"uk":"Що з перерахованого забороняється на гірських дорогах?"},"a":[{"uk":"Рухатися з непрацюючим двигуном."},{"uk":"Рухатися з вимкненими зчепленням або передачею."},{"uk":"Заборонені обидві дії, зазначені у відповідях 1 і 2."}],"c":2},{"id":"h28-6","t":"h28","num":"28.6","q":{"uk":"Під час руху по гірських дорогах водій транспортного засобу повинен:"},"a":[{"uk":"Рухатися з працюючим двигуном, ввімкненими зчепленням і передачею."},{"uk":"Рухатися з працюючим двигуном."},{"uk":"Рухатися з ввімкненими зчепленням або передачею."}],"c":0},{"id":"h28-7","t":"h28","num":"28.7","q":{"uk":"Яким способом/способами дозволено буксирування автомобілів на гірських дорогах?"},"a":[{"uk":"На жорсткому зчепленні."},{"uk":"На гнучкому зчепленні."},{"uk":"Способом часткового навантаження."},{"uk":"На жорсткому зчепленні або способом часткового навантаження."}],"c":3},{"id":"h28-8","t":"h28","num":"28.8","q":{"uk":"Чи дозволене буксирування на гірських дорогах під час ожеледиці?"},"a":[{"uk":"Заборонено."},{"uk":"Дозволено на жорсткому зчепленні."},{"uk":"Дозволено способом часткового навантаження."}],"c":0},{"id":"h29-1","t":"h29","num":"29.1","q":{"uk":"Виїжджаючи за кордон на транспортному засобі водій – громадянин України повинен мати:"},"a":[{"uk":"Реєстраційні документи на транспортний засіб, що відповідають вимогам Конвенції про дорожній рух."},{"uk":"Посвідчення водія, що відповідає вимогам Конвенції про дорожній рух."},{"uk":"Відповіді 1 і 2."}],"c":2},{"id":"h30-1","t":"h30","num":"30.1","q":{"uk":"Цим розпізнавальним знаком позначаються транспортні засоби, на яких:"},"a":[{"uk":"Встановлено шини із шипами."},{"uk":"Встановлено зимові шини."},{"uk":"Встановлено всесезонні шини."}],"c":0,"pic":["img/hsc/30-1-1.jpg"]},{"id":"h30-2","t":"h30","num":"30.2","q":{"uk":"Де на транспортному засобі повинен бути розпізнавальний знак «Таксі»?"},"a":[{"uk":"На даху транспортного засобу."},{"uk":"На бічній поверхні транспортного засобу."},{"uk":"На даху або на бічній поверхні транспортного засобу."}],"c":2,"pic":["img/hsc/30-2-1.jpg"]},{"id":"h30-3","t":"h30","num":"30.3","q":{"uk":"На яких транспортних засобах обов'язково встановлюється цей розпізнавальний знак?"},"a":[{"uk":"На всіх механічних транспортних засобах."},{"uk":"На транспортних засобах, які використовуються для дорожніх робіт."},{"uk":"На транспортних засобах, що мають особливу форму."},{"uk":"Відповіді 2 і 3."}],"c":3,"pic":["img/hsc/30-3-1.jpg"]},{"id":"h30-4","t":"h30","num":"30.4","q":{"uk":"Який із розпізнавальних знаків встановлюється на транспортних засобах, якими керують водії зі стажем до двох років?"},"a":[{"uk":"Перший."},{"uk":"Другий."},{"uk":"Третій."}],"c":2,"pic":["img/hsc/30-4-1.jpg"]},{"id":"h30-5","t":"h30","num":"30.5","q":{"uk":"У яких випадках на транспортних засобах встановлюється такий розпізнавальний знак?"},"a":[{"uk":"У разі перевезення небезпечного вантажу."},{"uk":"Коли вантаж виступає за габарити транспортного засобу на відстань більшу, ніж це передбачено Правилами дорожнього руху."},{"uk":"Під час перевезення великовагового вантажу."},{"uk":"Відповіді 1, 2 і 3."}],"c":1,"pic":["img/hsc/30-5-1.jpg"]},{"id":"h30-6","t":"h30","num":"30.6","q":{"uk":"Цей розпізнавальний знак встановлюється на транспортних засобах:"},"a":[{"uk":"Якими керують водії з інвалідністю."},{"uk":"Що належать водіям-лікарям."},{"uk":"Якими керують глухі або глухонімі водії."},{"uk":"Якими керують водії-лікарі."}],"c":1,"pic":["img/hsc/30-6-1.jpg"]},{"id":"h30-7","t":"h30","num":"30.7","q":{"uk":"Цим розпізнавальним знаком позначають транспортні засоби, які:"},"a":[{"uk":"Перевозять великовагові вантажі."},{"uk":"Перевозять небезпечні вантажі."},{"uk":"Перевозять великогабаритні вантажі."}],"c":1,"pic":["img/hsc/30-7-1.jpg"]},{"id":"h30-8","t":"h30","num":"30.8","q":{"uk":"На яких транспортних засобах встановлюється такий розпізнавальний знак?"},"a":[{"uk":"На тих, якими керують водії з інвалідністю."},{"uk":"На тих, якими керують глухі або глухонімі водії."},{"uk":"Відповіді 1 і 2."}],"c":0,"pic":["img/hsc/30-8-1.jpg"]},{"id":"h30-9","t":"h30","num":"30.9","q":{"uk":"Яким із розпізнавальних знаків позначаються транспортні засоби, якими керують водії з інвалідністю?"},"a":[{"uk":"Першим."},{"uk":"Другим."},{"uk":"Третім."},{"uk":"Четвертим."}],"c":0,"pic":["img/hsc/30-9-1.jpg"]},{"id":"h30-10","t":"h30","num":"30.10","q":{"uk":"Такий розпізнавальний знак розміщується на транспортних засобах, які:"},"a":[{"uk":"Перевозять пасажирів з дітьми."},{"uk":"Перевозять організовані групи дітей."},{"uk":"Перевозять пасажирів, велика частина з яких діти."}],"c":1,"pic":["img/hsc/30-10-1.jpg"]},{"id":"h30-11","t":"h30","num":"30.11","q":{"uk":"Який із розпізнавальних знаків встановлюється на транспортних засобах, якими керують глухі або глухонімі водії?"},"a":[{"uk":"Перший."},{"uk":"Другий."},{"uk":"Третій."}],"c":0,"pic":["img/hsc/30-11-1.jpg"]},{"id":"h30-12","t":"h30","num":"30.12","q":{"uk":"На яких транспортних засобах встановлюється цей розпізнавальний знак?"},"a":[{"uk":"На транспортних засобах, якими керують водії з інвалідністю."},{"uk":"На транспортних засобах, якими керують глухі водії."},{"uk":"На транспортних засобах, якими керують глухі або глухонімі водії."}],"c":2,"pic":["img/hsc/30-12-1.jpg"]},{"id":"h30-13","t":"h30","num":"30.13","q":{"uk":"Де на механічних транспортних засобах (за винятком трамваїв і тролейбусів) і причепах встановлюють номерні знаки?"},"a":[{"uk":"З боків."},{"uk":"Спереду і ззаду."},{"uk":"У передбачених для цього місцях."}],"c":2},{"id":"h30-14","t":"h30","num":"30.14","q":{"uk":"Якщо в результаті проведення переобладнання або ремонту транспортного засобу необхідно внести зміни до реєстраційних документів, протягом якого часу з моменту завершення ремонту або переобладнання необхідно перереєструвати його в уповноваженому органі МВС?"},"a":[{"uk":"5 діб."},{"uk":"7 діб."},{"uk":"10 діб."},{"uk":"14 діб."}],"c":2},{"id":"h31-1","t":"h31","num":"31.1","q":{"uk":"Як називаються зовнішні світлові пристрої білого кольору, передбачені конструкцією транспортного засобу, встановлені спереду транспортного засобу і призначені для поліпшення його видимості під час руху в світлий час доби?","ru":"Как называются внешние световые приборы белого цвета, предусмотренные конструкцией транспортного средства, установленные спереди транспортного средства и предназначенные для улучшения его видимости во время движения в светлое время суток?"},"a":[{"uk":"Протитуманні фари.","ru":"Противотуманные фары.","w":{"uk":"Протитуманні фари освітлюють дорогу в умовах недостатньої видимості (туман, снігопад, дощ), а не позначають автомобіль удень.","ru":"Противотуманные фары освещают дорогу в условиях недостаточной видимости (туман, снегопад, дождь), а не обозначают автомобиль днём."}},{"uk":"Габаритні вогні.","ru":"Габаритные огни.","w":{"uk":"Габаритні вогні позначають габарити транспортного засобу в темну пору доби й на стоянці, вони не призначені для денної видимості під час руху.","ru":"Габаритные огни обозначают габариты транспортного средства в тёмное время суток и на стоянке, они не предназначены для дневной видимости во время движения."}},{"uk":"Ближнє світло фар.","ru":"Ближний свет фар.","w":{"uk":"Ближнє світло фар призначене для освітлення дороги; удень його вмикають замість денних ходових вогнів лише тоді, коли їх немає в конструкції ({p:9.8}).","ru":"Ближний свет фар предназначен для освещения дороги; днём его включают вместо дневных ходовых огней лишь тогда, когда их нет в конструкции ({p:9.8})."}},{"uk":"Денні ходові вогні.","ru":"Дневные ходовые огни."},{"uk":"Відповіді 2 і 3.","ru":"Ответы 2 и 3.","w":{"uk":"Габаритні вогні й ближнє світло — інші прилади з іншим призначенням; наведене визначення стосується лише денних ходових вогнів.","ru":"Габаритные огни и ближний свет — другие приборы с другим назначением; приведённое определение относится только к дневным ходовым огням."}}],"c":3,"e":{"uk":"Це дослівне визначення **денних ходових вогнів** з {p:1.10}: білі зовнішні світлові прилади спереду, передбачені конструкцією, для кращої видимості транспортного засобу під час руху у світлу пору доби.","ru":"Это дословное определение **дневных ходовых огней** из {p:1.10}: белые внешние световые приборы спереди, предусмотренные конструкцией, для лучшей видимости транспортного средства во время движения в светлое время суток."},"ref":["1.10"]},{"id":"h31-2","t":"h31","num":"31.2","q":{"uk":"Чи дозволяється вам встановлювати на одну вісь транспортного засобу ошиповану шину разом із неошипованою?","ru":"Разрешается ли вам устанавливать на одну ось транспортного средства ошипованную шину вместе с неошипованной?"},"a":[{"uk":"Дозволяється.","ru":"Разрешается.","w":{"uk":"Шини з різним зчепленням на одній осі спричиняють занесення під час гальмування, тому таке поєднання прямо заборонено {p:31.4}.","ru":"Шины с разным сцеплением на одной оси вызывают занос при торможении, поэтому такое сочетание прямо запрещено {p:31.4}."}},{"uk":"Дозволяється лише на задню вісь.","ru":"Разрешается только на заднюю ось.","w":{"uk":"Заборона стосується будь-якої осі, зокрема й задньої.","ru":"Запрет касается любой оси, в том числе и задней."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":2,"e":{"uk":"За {p:31.4} (п. 31.4.5 «г») експлуатацію заборонено, якщо на одну вісь встановлено **ошиповані та неошиповані** шини — незалежно від того, яка це вісь.","ru":"Согласно {p:31.4} (п. 31.4.5 «г») эксплуатация запрещена, если на одну ось установлены **ошипованные и неошипованные** шины — независимо от того, какая это ось."},"ref":["31.4"]},{"id":"h31-3","t":"h31","num":"31.3","q":{"uk":"Чи дозволяється рух до місця ремонту або стоянки в темний час доби з несправними фарами і задніми габаритними вогнями?","ru":"Разрешается ли движение к месту ремонта или стоянки в тёмное время суток с неисправными фарами и задними габаритными огнями?"},"a":[{"uk":"Забороняється лише на дорогах без штучного освітлення.","ru":"Запрещается только на дорогах без искусственного освещения.","w":{"uk":"Штучне освітлення дороги нічого не змінює: заборона {p:31.6} діє в темну пору доби на будь-якій дорозі.","ru":"Искусственное освещение дороги ничего не меняет: запрет {p:31.6} действует в тёмное время суток на любой дороге."}},{"uk":"Забороняється.","ru":"Запрещается."},{"uk":"Дозволяється.","ru":"Разрешается.","w":{"uk":"Доїхати до місця ремонту {p:31.5} дозволяє лише з іншими несправностями; для фар і задніх габаритних ліхтарів у темряві діє пряма заборона {p:31.6}.","ru":"Доехать до места ремонта {p:31.5} разрешает лишь с другими неисправностями; для фар и задних габаритных фонарей в темноте действует прямой запрет {p:31.6}."}}],"c":1,"e":{"uk":"За {p:31.6} (підпункт «б») подальший рух заборонено, якщо в темну пору доби або в умовах недостатньої видимості не горять лампи фар чи задніх габаритних ліхтарів, — навіть до місця ремонту чи стоянки.","ru":"Согласно {p:31.6} (подпункт «б») дальнейшее движение запрещено, если в тёмное время суток или в условиях недостаточной видимости не горят лампы фар или задних габаритных фонарей, — даже к месту ремонта или стоянки."},"ref":["31.6"]},{"id":"h31-4","t":"h31","num":"31.4","q":{"uk":"Як ви повинні вчинити, якщо під час руху відмовив спідометр?","ru":"Как вы должны поступить, если во время движения отказал спидометр?"},"a":[{"uk":"Продовжити намічену поїздку з особливою обережністю.","ru":"Продолжить намеченную поездку с особой осторожностью.","w":{"uk":"Продовжувати поїздку з несправністю з переліку {p:31.4} не можна — дозволено лише доїхати до місця стоянки чи ремонту.","ru":"Продолжать поездку с неисправностью из перечня {p:31.4} нельзя — разрешено лишь доехать до места стоянки или ремонта."}},{"uk":"Припинити подальший рух.","ru":"Прекратить дальнейшее движение.","w":{"uk":"Відмова спідометра не входить до несправностей {p:31.6}, за яких рух заборонено повністю, тож до місця ремонту чи стоянки доїхати можна.","ru":"Отказ спидометра не входит в неисправности {p:31.6}, при которых движение запрещено полностью, поэтому доехать до места ремонта или стоянки можно."}},{"uk":"Спробувати усунути несправність на місці, а якщо це неможливо, то слідувати до місця стоянки або ремонту, ввімкнувши аварійну світлову сигналізацію або встановивши ззаду на транспортному засобі знак аварійної зупинки.","ru":"Попытаться устранить неисправность на месте, а если это невозможно, то следовать к месту стоянки или ремонта, включив аварийную световую сигнализацию или установив сзади на транспортном средстве знак аварийной остановки."}],"c":2,"e":{"uk":"Несправний спідометр — несправність із {p:31.4} (п. 31.4.7 «г»). За {p:31.5} її треба спробувати усунути, а якщо це неможливо — рухатися найкоротшим шляхом до місця стоянки чи ремонту з увімкненою аварійною сигналізацією ({p:9.9}) або зі знаком аварійної зупинки ззаду, якщо сигналізація несправна чи її немає ({p:9.11}).","ru":"Неисправный спидометр — неисправность из {p:31.4} (п. 31.4.7 «г»). Согласно {p:31.5} её нужно попытаться устранить, а если это невозможно — двигаться кратчайшим путём к месту стоянки или ремонта с включённой аварийной сигнализацией ({p:9.9}) или со знаком аварийной остановки сзади, если сигнализация неисправна или её нет ({p:9.11})."},"ref":["31.4","31.5","9.9","9.11"]},{"id":"h31-5","t":"h31","num":"31.5","q":{"uk":"У якому випадку дозволяється експлуатація транспортного засобу?","ru":"В каком случае разрешается эксплуатация транспортного средства?"},"a":[{"uk":"Порушено регулювання фар.","ru":"Нарушена регулировка фар.","w":{"uk":"Порушене регулювання фар прямо назване в {p:31.4} (п. 31.4.3 «б») серед несправностей, за яких експлуатацію заборонено.","ru":"Нарушенная регулировка фар прямо названа в {p:31.4} (п. 31.4.3 «б») среди неисправностей, при которых эксплуатация запрещена."}},{"uk":"На світлових приладах використовуються розсіювачі, що не відповідають типу конкретного світлового приладу.","ru":"На световых приборах используются рассеиватели, не соответствующие типу конкретного светового прибора.","w":{"uk":"Розсіювачі, що не відповідають типу світлового приладу, забороняє {p:31.4} (п. 31.4.3 «г»).","ru":"Рассеиватели, не соответствующие типу светового прибора, запрещает {p:31.4} (п. 31.4.3 «г»)."}},{"uk":"Відсутні протитуманні фари.","ru":"Отсутствуют противотуманные фары."}],"c":2,"e":{"uk":"Протитуманні фари не обов'язкові: примітки до п. 31.4.3 лише **дозволяють** додатково обладнати ними транспортний засіб, тож їх відсутність не є несправністю з {p:31.4}.","ru":"Противотуманные фары не обязательны: примечания к п. 31.4.3 лишь **разрешают** дополнительно оборудовать ими транспортное средство, поэтому их отсутствие не является неисправностью из {p:31.4}."},"ref":["31.4"]},{"id":"h31-6","t":"h31","num":"31.6","q":{"uk":"Ви маєте право експлуатувати легковий автомобіль за відсутності:","ru":"Вы имеете право эксплуатировать легковой автомобиль при отсутствии:"},"a":[{"uk":"Аптечки.","ru":"Аптечки.","w":{"uk":"Медична аптечка на легковому автомобілі обов'язкова ({p:31.4}, п. 31.4.7 «є»).","ru":"Медицинская аптечка на легковом автомобиле обязательна ({p:31.4}, п. 31.4.7 «є»)."}},{"uk":"Вогнегасника.","ru":"Огнетушителя.","w":{"uk":"Працездатний вогнегасник на легковому автомобілі обов'язковий ({p:31.4}, п. 31.4.7 «є»).","ru":"Работоспособный огнетушитель на легковом автомобиле обязателен ({p:31.4}, п. 31.4.7 «є»)."}},{"uk":"Знака аварійної зупинки.","ru":"Знака аварийной остановки.","w":{"uk":"Знак аварійної зупинки (миготливий червоний ліхтар) на легковому автомобілі обов'язковий ({p:31.4}, п. 31.4.7 «є»).","ru":"Знак аварийной остановки (мигающий красный фонарь) на легковом автомобиле обязателен ({p:31.4}, п. 31.4.7 «є»)."}},{"uk":"Противідкатних упорів.","ru":"Противооткатных упоров."}],"c":3,"e":{"uk":"За {p:31.4} (п. 31.4.7 «є») **противідкотні упори** обов'язкові лише на вантажних автомобілях з дозволеною максимальною масою понад 3,5 т і в автобусах понад 5 т. Аптечка, вогнегасник і знак аварійної зупинки на легковому автомобілі мають бути обов'язково.","ru":"Согласно {p:31.4} (п. 31.4.7 «є») **противооткатные упоры** обязательны лишь на грузовых автомобилях с разрешённой максимальной массой более 3,5 т и в автобусах более 5 т. Аптечка, огнетушитель и знак аварийной остановки на легковом автомобиле должны быть обязательно."},"ref":["31.4"]},{"id":"h31-7","t":"h31","num":"31.7","q":{"uk":"Чи дозволяється встановлювати на одну вісь легкового автомобіля шини з різним малюнком протектора?","ru":"Разрешается ли устанавливать на одну ось легкового автомобиля шины с разным рисунком протектора?"},"a":[{"uk":"Дозволяється на будь-яку вісь.","ru":"Разрешается на любую ось.","w":{"uk":"Шини з різним малюнком протектора по-різному тримають дорогу, тому на одній осі їх поєднувати заборонено.","ru":"Шины с разным рисунком протектора по-разному держат дорогу, поэтому сочетать их на одной оси запрещено."}},{"uk":"Дозволяється лише на задню вісь.","ru":"Разрешается только на заднюю ось.","w":{"uk":"Заборона стосується будь-якої осі, зокрема й задньої.","ru":"Запрет касается любой оси, в том числе и задней."}},{"uk":"Не дозволяється.","ru":"Не разрешается."}],"c":2,"e":{"uk":"{p:31.4} (п. 31.4.5 «г») забороняє експлуатацію, якщо на одну вісь легкового автомобіля встановлено шини різних моделей з **різними малюнками протектора**.","ru":"{p:31.4} (п. 31.4.5 «г») запрещает эксплуатацию, если на одну ось легкового автомобиля установлены шины разных моделей с **разными рисунками протектора**."},"ref":["31.4"]},{"id":"h31-8","t":"h31","num":"31.8","q":{"uk":"За наявності якої несправності дозволяється експлуатація транспортного засобу?","ru":"При наличии какой неисправности разрешается эксплуатация транспортного средства?"},"a":[{"uk":"Не працюють запори горловин паливних баків.","ru":"Не работают запоры горловин топливных баков.","w":{"uk":"Несправні запори горловин паливних баків — несправність із {p:31.4} (п. 31.4.7 «г»), з якою експлуатацію заборонено.","ru":"Неисправные запоры горловин топливных баков — неисправность из {p:31.4} (п. 31.4.7 «г»), при которой эксплуатация запрещена."}},{"uk":"Не працює механізм регулювання сидіння водія.","ru":"Не работает механизм регулировки сиденья водителя.","w":{"uk":"Механізм регулювання положення сидіння водія названо в {p:31.4} (п. 31.4.7 «г»): водій має сидіти так, щоб безпечно керувати.","ru":"Механизм регулировки положения сиденья водителя назван в {p:31.4} (п. 31.4.7 «г»): водитель должен сидеть так, чтобы безопасно управлять."}},{"uk":"Не працює пристрій для обігрівання і обдування скла.","ru":"Не работает устройство для обогрева и обдува стекла.","w":{"uk":"Без обігрівання й обдування скла воно запотіває й обмерзає, тому цю несправність теж названо в {p:31.4} (п. 31.4.7 «г»).","ru":"Без обогрева и обдува стекло запотевает и обмерзает, поэтому эта неисправность тоже названа в {p:31.4} (п. 31.4.7 «г»)."}},{"uk":"Не працює склопідйомник.","ru":"Не работает стеклоподъёмник."}],"c":3,"e":{"uk":"**Склопідйомника** немає в переліку несправностей {p:31.4}, а запори горловин паливних баків, механізм регулювання сидіння водія й пристрій для обігрівання та обдування скла прямо названі в п. 31.4.7 «г».","ru":"**Стеклоподъёмника** нет в перечне неисправностей {p:31.4}, а запоры горловин топливных баков, механизм регулировки сиденья водителя и устройство для обогрева и обдува стекла прямо названы в п. 31.4.7 «г»."},"ref":["31.4"]},{"id":"h31-9","t":"h31","num":"31.9","q":{"uk":"У яких випадках забороняється подальший рух навіть до місця ремонту або стоянки з несправними фарами і задніми габаритними вогнями?","ru":"В каких случаях запрещается дальнейшее движение даже к месту ремонта или стоянки с неисправными фарами и задними габаритными огнями?"},"a":[{"uk":"Тільки в умовах недостатньої видимості.","ru":"Только в условиях недостаточной видимости.","w":{"uk":"Неповна відповідь: заборона діє також у темну пору доби.","ru":"Неполный ответ: запрет действует также в тёмное время суток."}},{"uk":"Тільки в темний час доби.","ru":"Только в тёмное время суток.","w":{"uk":"Неповна відповідь: заборона діє також в умовах недостатньої видимості (туман, дощ, снігопад).","ru":"Неполный ответ: запрет действует также в условиях недостаточной видимости (туман, дождь, снегопад)."}},{"uk":"В обох випадках.","ru":"В обоих случаях."}],"c":2,"e":{"uk":"{p:31.6} (підпункт «б») забороняє подальший рух, якщо не горять лампи фар чи задніх габаритних ліхтарів **у темну пору доби або в умовах недостатньої видимості** — тобто в обох випадках.","ru":"{p:31.6} (подпункт «б») запрещает дальнейшее движение, если не горят лампы фар или задних габаритных фонарей **в тёмное время суток или в условиях недостаточной видимости** — то есть в обоих случаях."},"ref":["31.6"]},{"id":"h31-10","t":"h31","num":"31.10","q":{"uk":"У якому випадку дозволяється експлуатація автомобіля?","ru":"В каком случае разрешается эксплуатация автомобиля?"},"a":[{"uk":"Не працюють передбачені конструкцією транспортного засобу склоочисники.","ru":"Не работают предусмотренные конструкцией транспортного средства стеклоочистители.","w":{"uk":"Непрацюючі склоочисники — несправність із {p:31.4} (п. 31.4.4 «а»), з якою експлуатацію заборонено.","ru":"Неработающие стеклоочистители — неисправность из {p:31.4} (п. 31.4.4 «а»), при которой эксплуатация запрещена."}},{"uk":"Не працюють склообмивачі.","ru":"Не работают стеклоомыватели.","w":{"uk":"Непрацюючі склоомивачі, передбачені конструкцією, — несправність із {p:31.4} (п. 31.4.4 «б»).","ru":"Неработающие стеклоомыватели, предусмотренные конструкцией, — неисправность из {p:31.4} (п. 31.4.4 «б»)."}},{"uk":"Не працює склопідйомник.","ru":"Не работает стеклоподъёмник."}],"c":2,"e":{"uk":"**Склопідйомника** немає в переліку несправностей {p:31.4}, тоді як склоочисники й склоомивачі названо в п. 31.4.4.","ru":"**Стеклоподъёмника** нет в перечне неисправностей {p:31.4}, тогда как стеклоочистители и стеклоомыватели названы в п. 31.4.4."},"ref":["31.4"]},{"id":"h31-11","t":"h31","num":"31.11","q":{"uk":"За наявності якої несправності заборонено подальший рух на транспортному засобі під час дощу або снігопаду?","ru":"При наличии какой неисправности запрещено дальнейшее движение транспортного средства во время дождя или снегопада?"},"a":[{"uk":"Не працюють у встановленому режимі склоочисники.","ru":"Не работают в установленном режиме стеклоочистители.","w":{"uk":"Робота склоочисників не в установленому режимі — несправність із {p:31.4}, з якою можна доїхати до місця ремонту ({p:31.5}); повну заборону руху {p:31.6} пов'язує лише зі склоочисником з боку водія.","ru":"Работа стеклоочистителей не в установленном режиме — неисправность из {p:31.4}, с которой можно доехать до места ремонта ({p:31.5}); полный запрет движения {p:31.6} связывает лишь со стеклоочистителем со стороны водителя."}},{"uk":"Несправний склоочисник з боку розміщення керма.","ru":"Неисправен стеклоочиститель со стороны размещения руля."},{"uk":"Не працюють передбачені конструкцією транспортного засобу склообмивачі.","ru":"Не работают предусмотренные конструкцией транспортного средства стеклоомыватели.","w":{"uk":"Несправні склоомивачі забороняють експлуатацію ({p:31.4}), але не подальший рух: до місця ремонту доїхати можна ({p:31.5}).","ru":"Неисправные стеклоомыватели запрещают эксплуатацию ({p:31.4}), но не дальнейшее движение: до места ремонта доехать можно ({p:31.5})."}}],"c":1,"e":{"uk":"За {p:31.6} (підпункт «в») подальший рух заборонено, якщо під час дощу або снігопаду не працює **склоочисник з боку розміщення керма** — водій тоді просто не бачить дороги.","ru":"Согласно {p:31.6} (подпункт «в») дальнейшее движение запрещено, если во время дождя или снегопада не работает **стеклоочиститель со стороны размещения руля** — водитель тогда просто не видит дороги."},"ref":["31.6"]},{"id":"h31-12","t":"h31","num":"31.12","q":{"uk":"У яких випадках вам дозволяється експлуатація транспортного засобу?","ru":"В каких случаях вам разрешается эксплуатация транспортного средства?"},"a":[{"uk":"Вміст шкідливих речовин у відпрацьованих газах або їх димність перевищує встановлені норми.","ru":"Содержание вредных веществ в отработавших газах или их дымность превышает установленные нормы.","w":{"uk":"Перевищення норм вмісту шкідливих речовин чи димності — несправність із {p:31.4} (п. 31.4.6 «а»).","ru":"Превышение норм содержания вредных веществ или дымности — неисправность из {p:31.4} (п. 31.4.6 «а»)."}},{"uk":"Негерметична паливна система.","ru":"Негерметична топливная система.","w":{"uk":"Негерметична паливна система загрожує пожежею, її названо в {p:31.4} (п. 31.4.6 «б»).","ru":"Негерметичная топливная система грозит пожаром, она названа в {p:31.4} (п. 31.4.6 «б»)."}},{"uk":"Не працює покажчик температури охолоджуючої рідини.","ru":"Не работает указатель температуры охлаждающей жидкости."},{"uk":"Несправна система випускання відпрацьованих газів.","ru":"Неисправна система выпуска отработавших газов.","w":{"uk":"Несправну систему випускання відпрацьованих газів названо в {p:31.4} (п. 31.4.6 «в»).","ru":"Неисправная система выпуска отработавших газов названа в {p:31.4} (п. 31.4.6 «в»)."}}],"c":2,"e":{"uk":"**Покажчика температури охолоджувальної рідини** немає в переліку несправностей {p:31.4}, а три інші несправності прямо названі в п. 31.4.6 («Двигун»).","ru":"**Указателя температуры охлаждающей жидкости** нет в перечне неисправностей {p:31.4}, а три другие неисправности прямо названы в п. 31.4.6 («Двигатель»)."},"ref":["31.4"]},{"id":"h31-13","t":"h31","num":"31.13","q":{"uk":"У разі виникнення якої несправності заборонено подальший рух навіть до місця ремонту або стоянки?","ru":"При возникновении какой неисправности запрещено дальнейшее движение даже к месту ремонта или стоянки?"},"a":[{"uk":"Несправна робоча гальмова система не дає змоги водієві зупинити транспортний засіб при русі навіть з мінімальною швидкістю.","ru":"Неисправная рабочая тормозная система не позволяет водителю остановить транспортное средство при движении даже с минимальной скоростью."},{"uk":"Несправна система випуску відпрацьованих газів.","ru":"Неисправна система выпуска отработавших газов.","w":{"uk":"Несправна система випускання — несправність із {p:31.4}, з якою можна доїхати до місця стоянки чи ремонту ({p:31.5}).","ru":"Неисправная система выпуска — неисправность из {p:31.4}, с которой можно доехать до места стоянки или ремонта ({p:31.5})."}},{"uk":"Не працює склоочисник.","ru":"Не работает стеклоочиститель.","w":{"uk":"З непрацюючим склоочисником до місця ремонту доїхати можна; рух заборонено лише під час дощу чи снігопаду, якщо не працює склоочисник з боку водія ({p:31.6}).","ru":"С неработающим стеклоочистителем до места ремонта доехать можно; движение запрещено лишь во время дождя или снегопада, если не работает стеклоочиститель со стороны водителя ({p:31.6})."}}],"c":0,"e":{"uk":"За {p:31.6} (підпункт «а») подальший рух заборонено, якщо **робоча гальмова система** не дає змоги зупинити транспортний засіб під час руху з мінімальною швидкістю.","ru":"Согласно {p:31.6} (подпункт «а») дальнейшее движение запрещено, если **рабочая тормозная система** не позволяет остановить транспортное средство при движении с минимальной скоростью."},"ref":["31.6"]},{"id":"h31-14","t":"h31","num":"31.14","q":{"uk":"У разі виникнення якої несправності заборонено подальший рух?","ru":"При возникновении какой неисправности запрещено дальнейшее движение?"},"a":[{"uk":"Не працює склопідйомник.","ru":"Не работает стеклоподъёмник.","w":{"uk":"Склопідйомника немає ні в {p:31.4}, ні в {p:31.6}, тож рух із ним дозволено.","ru":"Стеклоподъёмника нет ни в {p:31.4}, ни в {p:31.6}, поэтому движение с ним разрешено."}},{"uk":"Несправне рульове керування не дає можливості здійснити маневр під час руху з мінімальною швидкістю.","ru":"Неисправное рулевое управление не позволяет выполнить манёвр при движении с минимальной скоростью."},{"uk":"Несправний глушник.","ru":"Неисправен глушитель.","w":{"uk":"Глушник — частина системи випускання відпрацьованих газів: це несправність із {p:31.4}, з якою можна доїхати до місця ремонту ({p:31.5}).","ru":"Глушитель — часть системы выпуска отработавших газов: это неисправность из {p:31.4}, с которой можно доехать до места ремонта ({p:31.5})."}}],"c":1,"e":{"uk":"За {p:31.6} (підпункт «а») подальший рух заборонено, якщо **рульове керування** не дає змоги здійснити маневр під час руху з мінімальною швидкістю.","ru":"Согласно {p:31.6} (подпункт «а») дальнейшее движение запрещено, если **рулевое управление** не позволяет выполнить манёвр при движении с минимальной скоростью."},"ref":["31.6"]},{"id":"h31-15","t":"h31","num":"31.15","q":{"uk":"У якому випадку вам забороняється експлуатація транспортного засобу?","ru":"В каком случае вам запрещается эксплуатация транспортного средства?"},"a":[{"uk":"Двигун нестійко працює на холостих обертах.","ru":"Двигатель неустойчиво работает на холостых оборотах.","w":{"uk":"Нестійкої роботи двигуна на холостих обертах немає в переліку {p:31.4}.","ru":"Неустойчивой работы двигателя на холостых оборотах нет в перечне {p:31.4}."}},{"uk":"Двигун не розвиває максимальну потужність.","ru":"Двигатель не развивает максимальную мощность.","w":{"uk":"Те, що двигун не розвиває максимальної потужності, не входить до переліку {p:31.4}.","ru":"То, что двигатель не развивает максимальную мощность, не входит в перечень {p:31.4}."}},{"uk":"Несправна система випускання відпрацьованих газів.","ru":"Неисправна система выпуска отработавших газов."}],"c":2,"e":{"uk":"Несправну **систему випускання відпрацьованих газів** прямо названо в {p:31.4} (п. 31.4.6 «в») серед несправностей, з якими експлуатацію заборонено.","ru":"Неисправная **система выпуска отработавших газов** прямо названа в {p:31.4} (п. 31.4.6 «в») среди неисправностей, при которых эксплуатация запрещена."},"ref":["31.4"]},{"id":"h31-16","t":"h31","num":"31.16","q":{"uk":"У якому випадку вам дозволяється експлуатація легкового автомобіля?","ru":"В каком случае вам разрешается эксплуатация легкового автомобиля?"},"a":[{"uk":"Не працює спідометр.","ru":"Не работает спидометр.","w":{"uk":"Непрацюючий спідометр — несправність із {p:31.4} (п. 31.4.7 «г»): без нього водій не може контролювати швидкість.","ru":"Неработающий спидометр — неисправность из {p:31.4} (п. 31.4.7 «г»): без него водитель не может контролировать скорость."}},{"uk":"Не працює покажчик температури охолоджуючої рідини.","ru":"Не работает указатель температуры охлаждающей жидкости."},{"uk":"Не працюють передбачені конструкцією замки дверей кузова або кабіни.","ru":"Не работают предусмотренные конструкцией замки дверей кузова или кабины.","w":{"uk":"Непрацюючі замки дверей кузова чи кабіни названо в {p:31.4} (п. 31.4.7 «г»): двері можуть відчинитися під час руху.","ru":"Неработающие замки дверей кузова или кабины названы в {p:31.4} (п. 31.4.7 «г»): двери могут открыться во время движения."}}],"c":1,"e":{"uk":"**Покажчика температури охолоджувальної рідини** немає в переліку {p:31.4}, а спідометр і замки дверей кузова прямо названі в п. 31.4.7 «г».","ru":"**Указателя температуры охлаждающей жидкости** нет в перечне {p:31.4}, а спидометр и замки дверей кузова прямо названы в п. 31.4.7 «г»."},"ref":["31.4"]},{"id":"h31-17","t":"h31","num":"31.17","q":{"uk":"У якому випадку вам забороняється експлуатація автомобіля?","ru":"В каком случае вам запрещается эксплуатация автомобиля?"},"a":[{"uk":"Не працює покажчик рівня палива.","ru":"Не работает указатель уровня топлива.","w":{"uk":"Покажчика рівня палива немає в переліку несправностей {p:31.4}.","ru":"Указателя уровня топлива нет в перечне неисправностей {p:31.4}."}},{"uk":"Порушено регулювання кута випередження запалювання.","ru":"Нарушена регулировка угла опережения зажигания.","w":{"uk":"Порушене регулювання кута випередження запалювання погіршує роботу двигуна, але до переліку {p:31.4} не входить.","ru":"Нарушенная регулировка угла опережения зажигания ухудшает работу двигателя, но в перечень {p:31.4} не входит."}},{"uk":"Ускладнений запуск двигуна.","ru":"Затруднён пуск двигателя.","w":{"uk":"Ускладнений запуск двигуна не є несправністю з переліку {p:31.4}.","ru":"Затруднённый пуск двигателя не является неисправностью из перечня {p:31.4}."}},{"uk":"Не працює звуковий сигнал.","ru":"Не работает звуковой сигнал."}],"c":3,"e":{"uk":"Непрацюючий **звуковий сигнал** прямо названо в {p:31.4} (п. 31.4.7 «б») серед несправностей, з якими експлуатацію заборонено.","ru":"Неработающий **звуковой сигнал** прямо назван в {p:31.4} (п. 31.4.7 «б») среди неисправностей, при которых эксплуатация запрещена."},"ref":["31.4"]},{"id":"h31-18","t":"h31","num":"31.18","q":{"uk":"За яких умов заборонено подальший рух транспортного засобу, якщо не працює склоочисник з боку розміщення керма?","ru":"При каких условиях запрещено дальнейшее движение транспортного средства, если не работает стеклоочиститель со стороны размещения руля?"},"a":[{"uk":"За будь-яких обставин.","ru":"При любых обстоятельствах.","w":{"uk":"У суху погоду несправний склоочисник лише забороняє експлуатацію ({p:31.4}), а до місця стоянки чи ремонту доїхати можна ({p:31.5}).","ru":"В сухую погоду неисправный стеклоочиститель лишь запрещает эксплуатацию ({p:31.4}), а до места стоянки или ремонта доехать можно ({p:31.5})."}},{"uk":"Під час дощу або снігопаду.","ru":"Во время дождя или снегопада."},{"uk":"Непрацюючий склоочисник не є перешкодою для руху у будь-якому випадку.","ru":"Неработающий стеклоочиститель ни в каком случае не является препятствием для движения.","w":{"uk":"Несправний склоочисник — несправність із {p:31.4}, а під час дощу чи снігопаду рух із ним заборонено повністю ({p:31.6}).","ru":"Неисправный стеклоочиститель — неисправность из {p:31.4}, а во время дождя или снегопада движение с ним запрещено полностью ({p:31.6})."}}],"c":1,"e":{"uk":"За {p:31.6} (підпункт «в») подальший рух заборонено, якщо **під час дощу або снігопаду** не працює склоочисник з боку розміщення керма — як на малюнку, де скло вкрите краплями.","ru":"Согласно {p:31.6} (подпункт «в») дальнейшее движение запрещено, если **во время дождя или снегопада** не работает стеклоочиститель со стороны размещения руля — как на рисунке, где стекло покрыто каплями."},"ref":["31.6"],"pic":["img/hsc/31-18-1.jpg"]},{"id":"h32-1","t":"h32","num":"32.1","q":{"uk":"У якому випадку з органами Національної поліції варто узгодити умови і порядок руху колони транспортних засобів?","ru":"В каком случае с органами Национальной полиции следует согласовать условия и порядок движения колонны транспортных средств?"},"a":[{"uk":"Під час руху колони за межами населених пунктів.","ru":"При движении колонны вне населённых пунктов.","w":{"uk":"Обов'язок узгодження залежить від кількості транспортних засобів у колоні, а не від того, де вона рухається.","ru":"Обязанность согласования зависит от количества транспортных средств в колонне, а не от того, где она движется."}},{"uk":"Якщо колона складається більш ніж із 5 механічних транспортних засобів.","ru":"Если колонна состоит более чем из 5 механических транспортных средств."},{"uk":"Якщо колона складається більш ніж із 4 механічних транспортних засобів.","ru":"Если колонна состоит более чем из 4 механических транспортных средств.","w":{"uk":"Межу встановлено інакше: узгодження потрібне для колони з більш як п'яти, а не чотирьох механічних транспортних засобів.","ru":"Граница установлена иначе: согласование нужно для колонны из более чем пяти, а не четырёх механических транспортных средств."}},{"uk":"Під час руху колони в населених пунктах.","ru":"При движении колонны в населённых пунктах.","w":{"uk":"Рух колони в населеному пункті сам по собі не вимагає узгодження — важить лише кількість транспортних засобів (понад п'ять).","ru":"Движение колонны в населённом пункте само по себе не требует согласования — значение имеет лишь количество транспортных средств (более пяти)."}}],"c":1,"e":{"uk":"За {p:32.1} (підпункт «б») з Національною поліцією узгоджують умови та порядок руху колон у складі **більш як п'яти** механічних транспортних засобів.","ru":"Согласно {p:32.1} (подпункт «б») с Национальной полицией согласовывают условия и порядок движения колонн в составе **более пяти** механических транспортных средств."},"ref":["32.1"]},{"id":"h32-2","t":"h32","num":"32.2","q":{"uk":"За яких умов з органами Національної поліції узгоджують порядок буксирування?","ru":"При каких условиях с органами Национальной полиции согласовывают порядок буксировки?"},"a":[{"uk":"У разі буксирування по гірських дорогах.","ru":"При буксировке по горным дорогам.","w":{"uk":"Буксирування гірськими дорогами не потребує узгодження з поліцією — його виконують за загальними правилами розділу 23.","ru":"Буксировка по горным дорогам не требует согласования с полицией — её выполняют по общим правилам раздела 23."}},{"uk":"Під час буксирування по автомагістралях і дорогах для автомобілів.","ru":"При буксировке по автомагистралям и дорогам для автомобилей.","w":{"uk":"Узгоджувати буксирування автомагістралями {p:32.1} не вимагає; для таких доріг діють свої обмеження руху, а не процедура узгодження.","ru":"Согласовывать буксировку по автомагистралям {p:32.1} не требует; для таких дорог действуют свои ограничения движения, а не процедура согласования."}},{"uk":"У разі буксирування двох і більше транспортних засобів.","ru":"При буксировке двух и более транспортных средств."},{"uk":"Під час буксирування транспортного засобу з причепом.","ru":"При буксировке транспортного средства с прицепом.","w":{"uk":"{p:32.1} вимагає узгодження лише тоді, коли буксирують два і більше транспортних засоби, а не транспортний засіб із причепом.","ru":"{p:32.1} требует согласования лишь тогда, когда буксируют два и более транспортных средства, а не транспортное средство с прицепом."}}],"c":2,"e":{"uk":"За {p:32.1} (підпункт «в») з Національною поліцією узгоджують порядок буксирування **двох і більше** транспортних засобів.","ru":"Согласно {p:32.1} (подпункт «в») с Национальной полицией согласовывают порядок буксировки **двух и более** транспортных средств."},"ref":["32.1"]},{"id":"h32-3","t":"h32","num":"32.3","q":{"uk":"Що з перерахованого необхідно узгоджувати з органами Національної поліції?","ru":"Что из перечисленного необходимо согласовывать с органами Национальной полиции?"},"a":[{"uk":"Нанесення білих смуг під нахилом на зовнішні бічні поверхні транспортних засобів.","ru":"Нанесение белых полос под наклоном на внешние боковые поверхности транспортных средств.","w":{"uk":"Нанесення смуг на бічні поверхні транспортних засобів не входить до переліку питань {p:32.1}, які узгоджують з Національною поліцією.","ru":"Нанесение полос на боковые поверхности транспортных средств не входит в перечень вопросов {p:32.1}, которые согласовывают с Национальной полицией."}},{"uk":"Розміщення в смугах відведення автомобільних доріг кіосків, павільйонів, рекламоносіїв, пересувних торговельних пунктів.","ru":"Размещение в полосах отвода автомобильных дорог киосков, павильонов, рекламоносителей, передвижных торговых пунктов."},{"uk":"Переобладнання транспортних засобів.","ru":"Переоборудование транспортных средств.","w":{"uk":"Переобладнання транспортних засобів узгоджують не з поліцією, а з територіальними органами з надання сервісних послуг МВС ({p:32.2}).","ru":"Переоборудование транспортных средств согласовывают не с полицией, а с территориальными органами по предоставлению сервисных услуг МВД ({p:32.2})."}}],"c":1,"e":{"uk":"Розміщення в смугах відведення автомобільних доріг кіосків, павільйонів, рекламоносіїв і пересувних торговельних пунктів прямо назване в {p:32.1} (підпункт «а») серед питань, які узгоджують з **Національною поліцією**.","ru":"Размещение в полосах отвода автомобильных дорог киосков, павильонов, рекламоносителей и передвижных торговых пунктов прямо названо в {p:32.1} (подпункт «а») среди вопросов, которые согласовывают с **Национальной полицией**."},"ref":["32.1"]},{"id":"h32-4","t":"h32","num":"32.4","q":{"uk":"За яких умов на транспортних засобах дозволяється встановлення спеціальних звукових і світлових сигнальних пристроїв?","ru":"При каких условиях на транспортных средствах разрешается установка специальных звуковых и световых сигнальных устройств?"},"a":[{"uk":"За умови узгодження з територіальним органом з надання сервісних послуг МВС.","ru":"При условии согласования с территориальным органом по предоставлению сервисных услуг МВД."},{"uk":"За умови узгодження з уповноваженими підрозділами Національної поліції.","ru":"При условии согласования с уполномоченными подразделениями Национальной полиции.","w":{"uk":"З Національною поліцією узгоджують інші питання ({p:32.1}); спеціальні сигнальні пристрої {p:32.2} відносить до сервісних центрів МВС.","ru":"С Национальной полицией согласовывают другие вопросы ({p:32.1}); специальные сигнальные устройства {p:32.2} относит к сервисным центрам МВД."}}],"c":0,"e":{"uk":"За {p:32.2} (підпункт «а») технічні вимоги, конструкцію та встановлення спеціальних звукових і світлових сигнальних пристроїв узгоджують з **територіальними органами з надання сервісних послуг МВС**.","ru":"Согласно {p:32.2} (подпункт «а») технические требования, конструкцию и установку специальных звуковых и световых сигнальных устройств согласовывают с **территориальными органами по предоставлению сервисных услуг МВД**."},"ref":["32.2"]},{"id":"h32-5","t":"h32","num":"32.5","q":{"uk":"За якої умови дозволено вносити зміни в ідентифікаційні номери і номерні таблички кузова чи шасі (рами), двигуна транспортного засобу, а також їхнє знищення (перенесення, закріплення, відновлення)?","ru":"При каком условии разрешено вносить изменения в идентификационные номера и номерные таблички кузова или шасси (рамы), двигателя транспортного средства, а также их уничтожение (перенос, закрепление, восстановление)?"},"a":[{"uk":"При узгодженні з територіальними органами з надання сервісних послуг МВС та з заводом-виробником транспортного засобу.","ru":"При согласовании с территориальными органами по предоставлению сервисных услуг МВД и с заводом-изготовителем транспортного средства.","w":{"uk":"Узгодження із заводом-виробником Правила не вимагають — достатньо попереднього узгодження із сервісним центром МВС.","ru":"Согласования с заводом-изготовителем Правила не требуют — достаточно предварительного согласования с сервисным центром МВД."}},{"uk":"У разі попереднього узгодження з територіальними органами з надання сервісних послуг МВС.","ru":"При предварительном согласовании с территориальными органами по предоставлению сервисных услуг МВД."},{"uk":"За умови дозволу заводу-виробника.","ru":"При условии разрешения завода-изготовителя.","w":{"uk":"Дозволу заводу-виробника недостатньо: {p:32.3} вимагає попереднього узгодження саме з територіальними органами з надання сервісних послуг МВС.","ru":"Разрешения завода-изготовителя недостаточно: {p:32.3} требует предварительного согласования именно с территориальными органами по предоставлению сервисных услуг МВД."}}],"c":1,"e":{"uk":"{p:32.3} забороняє будь-які зміни ідентифікаційних номерів і номерних табличок кузова, шасі чи двигуна **без попереднього узгодження з територіальними органами з надання сервісних послуг МВС** — навіть на спеціалізованих підприємствах.","ru":"{p:32.3} запрещает любые изменения идентификационных номеров и номерных табличек кузова, шасси или двигателя **без предварительного согласования с территориальными органами по предоставлению сервисных услуг МВД** — даже на специализированных предприятиях."},"ref":["32.3"]},{"id":"h33-1","t":"h33","num":"33.1","q":{"uk":"Зображений дорожній знак має таке значення:","ru":"Изображённый дорожный знак имеет следующее значение:"},"a":[{"uk":"Дозволяє виконати поворот ліворуч у зазначеному місці.","ru":"Разрешает выполнить поворот налево в указанном месте.","w":{"uk":"Знак {s:4.8} стосується об'їзду перешкоди, а не повороту; поворот ліворуч задає знак {s:4.3}.","ru":"Знак {s:4.8} касается объезда препятствия, а не поворота; поворот налево задаёт знак {s:4.3}."}},{"uk":"Дозволяє повернути тільки ліворуч.","ru":"Разрешает повернуть только налево.","w":{"uk":"Рух лише ліворуч наказує знак {s:4.3} зі стрілкою, загнутою вліво; похила стрілка {s:4.8} вказує бік об'їзду перешкоди.","ru":"Движение только налево предписывает знак {s:4.3} со стрелкой, загнутой влево; наклонная стрелка {s:4.8} указывает сторону объезда препятствия."}},{"uk":"Дозволяє об'їзд перешкоди тільки з лівого боку.","ru":"Разрешает объезд препятствия только слева."}],"c":2,"e":{"uk":"Це знак {s:4.8} «Об'їзд перешкоди з лівого боку»: згідно з {p:33.4} об'їзд дозволено **лише** з боку, показаного стрілкою, тобто зліва.","ru":"Это знак {s:4.8} «Объезд препятствия слева»: согласно {p:33.4} объезд разрешён **только** со стороны, указанной стрелкой, то есть слева."},"ref":["33.4"],"pic":["img/hsc/33-1-1.jpg"]},{"id":"h33-2","t":"h33","num":"33.2","q":{"uk":"Який із зображених дорожніх знаків скасовує обмеження мінімальної швидкості руху?","ru":"Какой из изображённых дорожных знаков отменяет ограничение минимальной скорости?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:5.4} «Кінець дороги для автомобілів», він не стосується мінімальної швидкості.","ru":"Знак 1 — {s:5.4} «Конец дороги для автомобилей», он не касается минимальной скорости."}},{"uk":"Знак 2.","ru":"Знак 2."},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — {s:3.42} «Кінець усіх заборон і обмежень»: він скасовує дію заборонних знаків, а мінімальну швидкість встановлює наказовий знак {s:4.12}.","ru":"Знак 3 — {s:3.42} «Конец всех запрещений и ограничений»: он отменяет действие запрещающих знаков, а минимальную скорость устанавливает предписывающий знак {s:4.12}."}},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Знак 4 — {s:3.30} «Кінець обмеження максимальної швидкості», а не мінімальної.","ru":"Знак 4 — {s:3.30} «Конец ограничения максимальной скорости», а не минимальной."}}],"c":1,"e":{"uk":"Знак 2 — {s:4.13} «Кінець обмеження мінімальної швидкості»: синє коло з числом, перекресленим червоною смугою; він скасовує дію знака {s:4.12} ({p:33.4}).","ru":"Знак 2 — {s:4.13} «Конец ограничения минимальной скорости»: синий круг с числом, перечёркнутым красной полосой; он отменяет действие знака {s:4.12} ({p:33.4})."},"ref":["33.4"],"pic":["img/hsc/33-2-1.jpg"]},{"id":"h33-3","t":"h33","num":"33.3","q":{"uk":"Зображений дорожній знак позначає:","ru":"Изображённый дорожный знак обозначает:"},"a":[{"uk":"Початок ділянки дороги, на якій встановлено особливий режим руху.","ru":"Начало участка дороги, на котором установлен особый режим движения.","w":{"uk":"Формулювання надто загальне: особливий режим руху мають і дорога для автомобілів, і житлова зона, а цей знак позначає саме автомагістраль.","ru":"Формулировка слишком общая: особый режим движения имеют и дорога для автомобилей, и жилая зона, а этот знак обозначает именно автомагистраль."}},{"uk":"Початок ділянки дороги, що належить до автомагістралі (дороги, на якій діють особливі умови дорожнього руху, передбачені розділом 27 Правил дорожнього руху).","ru":"Начало участка дороги, относящегося к автомагистрали (дороги, на которой действуют особые условия дорожного движения, предусмотренные разделом 27 Правил дорожного движения)."},{"uk":"Початок ділянки дороги, яка за режимом руху належить до доріг для автомобілів.","ru":"Начало участка дороги, которая по режиму движения относится к дорогам для автомобилей.","w":{"uk":"Дорогу для автомобілів позначає інший знак — {s:5.3}.","ru":"Дорогу для автомобилей обозначает другой знак — {s:5.3}."}},{"uk":"Початок ділянки дороги, рух на якій дозволено тільки механічним транспортним засобам.","ru":"Начало участка дороги, движение по которой разрешено только механическим транспортным средствам.","w":{"uk":"Знак не відкриває дорогу для всіх механічних транспортних засобів: на автомагістралі, наприклад, заборонено рух тракторів і самохідних машин ({p:27.2}).","ru":"Знак не открывает дорогу для всех механических транспортных средств: на автомагистрали, например, запрещено движение тракторов и самоходных машин ({p:27.2})."}}],"c":1,"e":{"uk":"Знак {s:5.1} «Автомагістраль» позначає дорогу, на якій діють особливі умови руху, передбачені розділом 27 Правил ({p:33.5}).","ru":"Знак {s:5.1} «Автомагистраль» обозначает дорогу, на которой действуют особые условия движения, предусмотренные разделом 27 Правил ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-3-1.jpg"]},{"id":"h33-4","t":"h33","num":"33.4","q":{"uk":"Який із зображених дорожніх знаків встановлюється на початку автомагістралі?","ru":"Какой из изображённых дорожных знаков устанавливается в начале автомагистрали?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:5.3} «Дорога для автомобілів»: режим подібний, але це не автомагістраль.","ru":"Знак 1 — {s:5.3} «Дорога для автомобилей»: режим похожий, но это не автомагистраль."}},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:5.8} «Дорога зі смугою для руху маршрутних транспортних засобів».","ru":"Знак 2 — {s:5.8} «Дорога с полосой для движения маршрутных транспортных средств»."}},{"uk":"Знак 3.","ru":"Знак 3."},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Знак 4 — наказовий {s:4.11} «Рух легкових автомобілів», він дозволяє рух лише окремих видів транспортних засобів.","ru":"Знак 4 — предписывающий {s:4.11} «Движение легковых автомобилей», он разрешает движение лишь отдельных видов транспортных средств."}},{"uk":"Знак 5.","ru":"Знак 5.","w":{"uk":"Знак 5 — {s:5.51} «Початок населеного пункту» з його назвою.","ru":"Знак 5 — {s:5.51} «Начало населённого пункта» с его названием."}}],"c":2,"e":{"uk":"Знак 3 — {s:5.1} «Автомагістраль» (зелений знак із зображенням багатосмугової дороги під шляхопроводом); з нього починаються особливі умови руху за розділом 27 Правил ({p:33.5}).","ru":"Знак 3 — {s:5.1} «Автомагистраль» (зелёный знак с изображением многополосной дороги под путепроводом); с него начинаются особые условия движения по разделу 27 Правил ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-4-1.jpg"]},{"id":"h33-5","t":"h33","num":"33.5","q":{"uk":"Зображений дорожній знак позначає:","ru":"Изображённый дорожный знак обозначает:"},"a":[{"uk":"Кінець дороги для автомобілів.","ru":"Конец дороги для автомобилей.","w":{"uk":"Кінець дороги для автомобілів позначає інший знак — {s:5.4}.","ru":"Конец дороги для автомобилей обозначает другой знак — {s:5.4}."}},{"uk":"Кінець автомагістралі.","ru":"Конец автомагистрали."},{"uk":"Кінець обмеження мінімальної швидкості руху.","ru":"Конец ограничения минимальной скорости.","w":{"uk":"Кінець обмеження мінімальної швидкості позначає круглий синій знак {s:4.13}.","ru":"Конец ограничения минимальной скорости обозначает круглый синий знак {s:4.13}."}},{"uk":"Кінець дії вимог, що стосуються руху в населених пунктах.","ru":"Конец действия требований, касающихся движения в населённых пунктах.","w":{"uk":"Місце, де перестають діяти вимоги для населених пунктів, позначає знак {s:5.50} «Кінець населеного пункту».","ru":"Место, где перестают действовать требования для населённых пунктов, обозначает знак {s:5.50} «Конец населённого пункта»."}}],"c":1,"e":{"uk":"Це знак {s:5.2} «Кінець автомагістралі»: з цього місця перестають діяти особливі умови руху, встановлені для автомагістралі розділом 27 Правил ({p:33.5}).","ru":"Это знак {s:5.2} «Конец автомагистрали»: с этого места перестают действовать особые условия движения, установленные для автомагистрали разделом 27 Правил ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-5-1.jpg"]},{"id":"h33-6","t":"h33","num":"33.6","q":{"uk":"Чи дозволено водієві синього автомобіля виконати розворот, як показано на малюнку?","ru":"Разрешено ли водителю синего автомобиля выполнить разворот, как показано на рисунке?"},"a":[{"uk":"Заборонено.","ru":"Запрещено."},{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"Після розвороту автомобіль рухався б дорогою з одностороннім рухом у зворотному напрямку, що суперечить знаку {s:5.5}.","ru":"После разворота автомобиль двигался бы по дороге с односторонним движением в обратном направлении, что противоречит знаку {s:5.5}."}}],"c":0,"e":{"uk":"Знаки {s:5.5} «Дорога з одностороннім рухом» показують, що рух по всій ширині дороги здійснюється лише в одному напрямку ({p:33.5}), тому розворот, після якого довелося б їхати назустріч потоку, заборонено.","ru":"Знаки {s:5.5} «Дорога с односторонним движением» показывают, что движение по всей ширине дороги осуществляется только в одном направлении ({p:33.5}), поэтому разворот, после которого пришлось бы ехать навстречу потоку, запрещён."},"ref":["33.5"],"pic":["img/hsc/33-6-1.jpg"]},{"id":"h33-7","t":"h33","num":"33.7","q":{"uk":"Зображеним дорожнім знаком позначається:","ru":"Изображённым дорожным знаком обозначается:"},"a":[{"uk":"Дорога, на якій по одній або кількох смугах напрямок руху може змінюватися на протилежний.","ru":"Дорога, на которой по одной или нескольким полосам направление движения может меняться на противоположное.","w":{"uk":"Так визначено дорогу з реверсивним рухом, яку позначає знак {s:5.13}.","ru":"Так определена дорога с реверсивным движением, которую обозначает знак {s:5.13}."}},{"uk":"Дозволений напрямок руху транспортних засобів по смузі.","ru":"Разрешённое направление движения транспортных средств по полосе.","w":{"uk":"Дозволений напрямок руху по смузі показує знак {s:5.18}, який встановлюють над смугою.","ru":"Разрешённое направление движения по полосе показывает знак {s:5.18}, который устанавливают над полосой."}},{"uk":"Дорога або відокремлена проїзна частина, по якій рух транспортних засобів по всій ширині здійснюється лише в одному напрямку.","ru":"Дорога или отдельная проезжая часть, по которой движение транспортных средств по всей ширине осуществляется только в одном направлении."}],"c":2,"e":{"uk":"Це знак {s:5.5} «Дорога з одностороннім рухом» — дорога або відокремлена проїзна частина, по якій рух за всією шириною здійснюється лише в одному напрямку ({p:33.5}).","ru":"Это знак {s:5.5} «Дорога с односторонним движением» — дорога или отдельная проезжая часть, по которой движение по всей ширине осуществляется только в одном направлении ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-7-1.jpg"]},{"id":"h33-8","t":"h33","num":"33.8","q":{"uk":"Який із зображених дорожніх знаків встановлюється на початку дороги або відокремленої проїзної частини, по всій ширині якої рух транспортних засобів здійснюється тільки в одному напрямку?","ru":"Какой из изображённых дорожных знаков устанавливается в начале дороги или отдельной проезжей части, по всей ширине которой движение транспортных средств осуществляется только в одном направлении?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — наказовий {s:4.1} «Рух прямо»: він визначає напрямок руху на перехресті, а не односторонній рух на дорозі.","ru":"Знак 1 — предписывающий {s:4.1} «Движение прямо»: он определяет направление движения на перекрёстке, а не одностороннее движение на дороге."}},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:5.11} «Смуга для руху маршрутних транспортних засобів».","ru":"Знак 2 — {s:5.11} «Полоса для движения маршрутных транспортных средств»."}},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — {s:5.13} «Дорога з реверсивним рухом».","ru":"Знак 3 — {s:5.13} «Дорога с реверсивным движением»."}},{"uk":"Знак 4.","ru":"Знак 4."},{"uk":"Знак 5.","ru":"Знак 5.","w":{"uk":"Знак 5 показує напрямки руху по смугах, а не позначає дорогу з одностороннім рухом.","ru":"Знак 5 показывает направления движения по полосам, а не обозначает дорогу с односторонним движением."}}],"c":3,"e":{"uk":"Знак 4 — {s:5.5} «Дорога з одностороннім рухом»: широка біла стрілка на синьому прямокутнику ({p:33.5}).","ru":"Знак 4 — {s:5.5} «Дорога с односторонним движением»: широкая белая стрелка на синем прямоугольнике ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-8-1.jpg"]},{"id":"h33-9","t":"h33","num":"33.9","q":{"uk":"Що з переліченого заборонено водіям на зображеній дорозі?","ru":"Что из перечисленного запрещено водителям на изображённой дороге?"},"a":[{"uk":"Розворот.","ru":"Разворот.","w":{"uk":"Розворот справді заборонено, але так само заборонено й рух заднім ходом (крім випадку, коли інакше не під'їхати), тому повна відповідь — 1 і 2.","ru":"Разворот действительно запрещён, но так же запрещено и движение задним ходом (кроме случая, когда иначе не подъехать), поэтому полный ответ — 1 и 2."}},{"uk":"Рух заднім ходом, крім випадків, коли неможливо під'їхати до об'єкта іншим способом.","ru":"Движение задним ходом, кроме случаев, когда невозможно подъехать к объекту иным способом.","w":{"uk":"Це лише одна із заборон: розворот на дорозі з одностороннім рухом теж заборонено.","ru":"Это лишь один из запретов: разворот на дороге с односторонним движением тоже запрещён."}},{"uk":"Зупинка і стоянка біля лівого краю проїзної частини.","ru":"Остановка и стоянка у левого края проезжей части.","w":{"uk":"Зупинка і стоянка біля лівого краю дороги з одностороннім рухом у населених пунктах дозволені ({p:15.3}).","ru":"Остановка и стоянка у левого края дороги с односторонним движением в населённых пунктах разрешены ({p:15.3})."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2."},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3.","w":{"uk":"Варіант помилково включає зупинку і стоянку зліва, які {p:15.3} на дорогах з одностороннім рухом у населених пунктах дозволяє.","ru":"Вариант ошибочно включает остановку и стоянку слева, которые {p:15.3} на дорогах с односторонним движением в населённых пунктах разрешает."}}],"c":3,"e":{"uk":"Дорогу позначено знаками {s:5.5}, тож розворот на ній означав би рух назустріч потоку ({p:33.5}), а заднім ходом тут можна рухатися лише тоді, коли інакше під'їхати до об'єкта неможливо ({p:10.10}). Зупинка і стоянка біля лівого краю дороги з одностороннім рухом у населеному пункті дозволені ({p:15.3}).","ru":"Дорога обозначена знаками {s:5.5}, поэтому разворот на ней означал бы движение навстречу потоку ({p:33.5}), а задним ходом здесь можно двигаться, только когда иначе подъехать к объекту невозможно ({p:10.10}). Остановка и стоянка у левого края дороги с односторонним движением в населённом пункте разрешены ({p:15.3})."},"ref":["33.5","10.10","15.3"],"pic":["img/hsc/33-9-1.jpg"]},{"id":"h33-10","t":"h33","num":"33.10","q":{"uk":"Зображений дорожній знак дозволяє рух:","ru":"Изображённый дорожный знак разрешает движение:"},"a":[{"uk":"Зі швидкістю, що не перевищує зазначену на знакові.","ru":"Со скоростью, не превышающей указанную на знаке.","w":{"uk":"Так діє заборонний знак {s:3.29} «Обмеження максимальної швидкості» (червоне коло), а синій круглий знак встановлює мінімальну швидкість.","ru":"Так действует запрещающий знак {s:3.29} «Ограничение максимальной скорости» (красный круг), а синий круглый знак устанавливает минимальную скорость."}},{"uk":"Зі швидкістю, яка дорівнює тій, що вказана на знаку.","ru":"Со скоростью, равной указанной на знаке.","w":{"uk":"Знак не вимагає їхати саме з указаною швидкістю: можна й швидше, у межах загальних обмежень ({p:12.4}).","ru":"Знак не требует ехать именно с указанной скоростью: можно и быстрее, в пределах общих ограничений ({p:12.4})."}},{"uk":"Зі швидкістю не меншою від тієї, що вказана на знаку.","ru":"Со скоростью не меньше указанной на знаке."}],"c":2,"e":{"uk":"Це знак {s:4.12} «Обмеження мінімальної швидкості»: рух зі швидкістю, **не меншою** за зазначену на знаку, але й не більшою, ніж дозволяють пункти 12.4–12.7 ({p:33.4}).","ru":"Это знак {s:4.12} «Ограничение минимальной скорости»: движение со скоростью **не меньше** указанной на знаке, но и не больше разрешённой пунктами 12.4–12.7 ({p:33.4})."},"ref":["33.4"],"pic":["img/hsc/33-10-1.jpg"]},{"id":"h33-11","t":"h33","num":"33.11","q":{"uk":"Яким із зображених знаків позначається доріжка для вершників?","ru":"Каким из изображённых знаков обозначается дорожка для всадников?"},"a":[{"uk":"Знак 1.","ru":"Знак 1."},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — попереджувальний {s:1.36} «Дикі тварини».","ru":"Знак 2 — предупреждающий {s:1.36} «Дикие животные»."}},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — попереджувальний {s:1.35} «Перегін худоби».","ru":"Знак 3 — предупреждающий {s:1.35} «Перегон скота»."}},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Знак 4 — {s:4.17} «Доріжка для пішоходів і велосипедистів».","ru":"Знак 4 — {s:4.17} «Дорожка для пешеходов и велосипедистов»."}}],"c":0,"e":{"uk":"Знак 1 — {s:4.19} «Доріжка для вершників»: синє коло з вершником на коні; такою доріжкою дозволено рух лише вершників ({p:33.4}).","ru":"Знак 1 — {s:4.19} «Дорожка для всадников»: синий круг со всадником на коне; по такой дорожке разрешено движение только всадников ({p:33.4})."},"ref":["33.4"],"pic":["img/hsc/33-11-1.jpg"]},{"id":"h33-12","t":"h33","num":"33.12","q":{"uk":"Зображений дорожній знак дозволяє рух:","ru":"Изображённый дорожный знак разрешает движение:"},"a":[{"uk":"Пішоходів.","ru":"Пешеходов.","w":{"uk":"Лише для пішоходів призначена доріжка зі знаком {s:4.16}; цей знак дозволяє рух і велосипедистам.","ru":"Только для пешеходов предназначена дорожка со знаком {s:4.16}; этот знак разрешает движение и велосипедистам."}},{"uk":"Велосипедистів.","ru":"Велосипедистов.","w":{"uk":"Лише для велосипедистів призначена доріжка зі знаком {s:4.14}; тут дозволено рух і пішоходам.","ru":"Только для велосипедистов предназначена дорожка со знаком {s:4.14}; здесь разрешено движение и пешеходам."}},{"uk":"На мопедах і пішоходам.","ru":"На мопедах и пешеходам.","w":{"uk":"Рух на мопедах доріжкою для пішоходів і велосипедистів не дозволено.","ru":"Движение на мопедах по дорожке для пешеходов и велосипедистов не разрешено."}},{"uk":"Пішоходів і велосипедистів.","ru":"Пешеходов и велосипедистов."}],"c":3,"e":{"uk":"Це знак {s:4.17} «Доріжка для пішоходів і велосипедистів»: дозволено рух пішоходів і велосипедистів, а також осіб у кріслах колісних зі швидкістю пішохода ({p:33.4}).","ru":"Это знак {s:4.17} «Дорожка для пешеходов и велосипедистов»: разрешено движение пешеходов и велосипедистов, а также лиц в креслах-колясках со скоростью пешехода ({p:33.4})."},"ref":["33.4"],"pic":["img/hsc/33-12-1.jpg"]},{"id":"h33-13","t":"h33","num":"33.13","q":{"uk":"З якого боку ви повинні об'їхати перешкоду в зображеній ситуації?","ru":"С какой стороны вы должны объехать препятствие в изображённой ситуации?"},"a":[{"uk":"З будь-якого боку.","ru":"С любой стороны.","w":{"uk":"Об'їзд з будь-якого боку дозволяє знак {s:4.9} із двома стрілками, а тут стрілка одна — ліворуч.","ru":"Объезд с любой стороны разрешает знак {s:4.9} с двумя стрелками, а здесь стрелка одна — влево."}},{"uk":"З правого боку.","ru":"Справа.","w":{"uk":"Об'їзд справа вимагав би знак {s:4.7}, а стрілка на цьому знаку спрямована ліворуч.","ru":"Объезд справа требовал бы знак {s:4.7}, а стрелка на этом знаке направлена влево."}},{"uk":"З лівого боку.","ru":"Слева."}],"c":2,"e":{"uk":"Перед перешкодою встановлено знак {s:4.8} «Об'їзд перешкоди з лівого боку»: об'їзд дозволено лише з боку, показаного стрілкою, тобто зліва ({p:33.4}).","ru":"Перед препятствием установлен знак {s:4.8} «Объезд препятствия слева»: объезд разрешён только со стороны, указанной стрелкой, то есть слева ({p:33.4})."},"ref":["33.4"],"pic":["img/hsc/33-13-1.jpg"]},{"id":"h33-14","t":"h33","num":"33.14","q":{"uk":"По якій дорозі Вам дозволено рух?","ru":"По какой дороге вам разрешено движение?"},"a":[{"uk":"По дорозі А.","ru":"По дороге А.","w":{"uk":"Знак {s:4.9} не обмежує рух лише правим боком — так діяв би знак {s:4.7}.","ru":"Знак {s:4.9} не ограничивает движение только правой стороной — так действовал бы знак {s:4.7}."}},{"uk":"По дорозі Б.","ru":"По дороге Б.","w":{"uk":"Знак {s:4.9} не обмежує рух лише лівим боком — так діяв би знак {s:4.8}.","ru":"Знак {s:4.9} не ограничивает движение только левой стороной — так действовал бы знак {s:4.8}."}},{"uk":"По будь-якій дорозі.","ru":"По любой дороге."}],"c":2,"e":{"uk":"На острівці встановлено знак {s:4.9} «Об'їзд перешкоди з правого або лівого боку», тож рухатися можна як праворуч, так і ліворуч від нього ({p:33.4}).","ru":"На островке установлен знак {s:4.9} «Объезд препятствия справа или слева», поэтому двигаться можно как справа, так и слева от него ({p:33.4})."},"ref":["33.4"],"pic":["img/hsc/33-14-1.jpg"]},{"id":"h33-15","t":"h33","num":"33.15","q":{"uk":"Зображений дорожній знак встановлюється:","ru":"Изображённый дорожный знак устанавливается:"},"a":[{"uk":"На перехресті, через яке організовано об'їзд.","ru":"На перекрёстке, через который организован объезд.","w":{"uk":"Об'їзд позначають знаками {s:5.63} «Схема об'їзду» та {s:5.64.1} «Напрямок об'їзду», а {s:4.10} визначає порядок руху на перехресті з круговим рухом.","ru":"Объезд обозначают знаками {s:5.63} «Схема объезда» и {s:5.64.1} «Направление объезда», а {s:4.10} определяет порядок движения на перекрёстке с круговым движением."}},{"uk":"На перехресті з круговим рухом; вимагає об'їзду клумби в напрямку, показаному стрілками.","ru":"На перекрёстке с круговым движением; требует объезда клумбы в направлении, указанном стрелками."}],"c":1,"e":{"uk":"Це знак {s:4.10} «Круговий рух»: на перехресті з круговим рухом він вимагає об'їзду клумби (центрального острівця) в напрямку, показаному стрілками ({p:33.4}).","ru":"Это знак {s:4.10} «Круговое движение»: на перекрёстке с круговым движением он требует объезда клумбы (центрального островка) в направлении, указанном стрелками ({p:33.4})."},"ref":["33.4"],"pic":["img/hsc/33-15-1.jpg"]},{"id":"h33-16","t":"h33","num":"33.16","q":{"uk":"Зображений дорожній знак дозволяє рух:","ru":"Изображённый дорожный знак разрешает движение:"},"a":[{"uk":"Легкових автомобілів і мотоциклів.","ru":"Легковых автомобилей и мотоциклов.","w":{"uk":"Перелік неповний: знак дозволяє рух також автобусів, маршрутних транспортних засобів і вантажівок масою до 3,5 т.","ru":"Перечень неполный: знак разрешает движение также автобусов, маршрутных транспортных средств и грузовиков массой до 3,5 т."}},{"uk":"Автобусів і маршрутних транспортних засобів.","ru":"Автобусов и маршрутных транспортных средств.","w":{"uk":"Перелік неповний: знак дозволяє рух також легкових автомобілів, мотоциклів і вантажівок масою до 3,5 т.","ru":"Перечень неполный: знак разрешает движение также легковых автомобилей, мотоциклов и грузовиков массой до 3,5 т."}},{"uk":"Вантажних автомобілів, дозволена максимальна маса яких не перевищує 3,5 т.","ru":"Грузовых автомобилей, разрешённая максимальная масса которых не превышает 3,5 т.","w":{"uk":"Перелік неповний: знак дозволяє рух не лише вантажівок масою до 3,5 т, а й легкових автомобілів, мотоциклів, автобусів і маршрутних транспортних засобів.","ru":"Перечень неполный: знак разрешает движение не только грузовиков массой до 3,5 т, но и легковых автомобилей, мотоциклов, автобусов и маршрутных транспортных средств."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2.","w":{"uk":"Пропущено вантажні автомобілі з дозволеною максимальною масою до 3,5 т, яким цей знак теж дозволяє рух.","ru":"Пропущены грузовые автомобили с разрешённой максимальной массой до 3,5 т, которым этот знак тоже разрешает движение."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3."}],"c":4,"e":{"uk":"Знак {s:4.11} «Рух легкових автомобілів» дозволяє рух легкових автомобілів, автобусів, мотоциклів, маршрутних транспортних засобів і вантажних автомобілів з дозволеною максимальною масою не більше 3,5 т ({p:33.4}).","ru":"Знак {s:4.11} «Движение легковых автомобилей» разрешает движение легковых автомобилей, автобусов, мотоциклов, маршрутных транспортных средств и грузовых автомобилей с разрешённой максимальной массой не более 3,5 т ({p:33.4})."},"ref":["33.4"],"pic":["img/hsc/33-16-1.jpg"]},{"id":"h33-17","t":"h33","num":"33.17","q":{"uk":"Яким транспортним засобам заборонено рух у зону дії зображеного дорожнього знака?","ru":"Каким транспортным средствам запрещено движение в зону действия изображённого дорожного знака?"},"a":[{"uk":"Велосипедам.","ru":"Велосипедам.","w":{"uk":"Відповідь неповна: крім велосипедів, рух заборонено також мопедам і гужовим возам.","ru":"Ответ неполный: кроме велосипедов, движение запрещено также мопедам и гужевым повозкам."}},{"uk":"Мопедам.","ru":"Мопедам.","w":{"uk":"Відповідь неповна: крім мопедів, рух заборонено також велосипедам і гужовим возам.","ru":"Ответ неполный: кроме мопедов, движение запрещено также велосипедам и гужевым повозкам."}},{"uk":"Гужовим возам.","ru":"Гужевым повозкам.","w":{"uk":"Відповідь неповна: крім гужових возів, рух заборонено також велосипедам і мопедам.","ru":"Ответ неполный: кроме гужевых повозок, движение запрещено также велосипедам и мопедам."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2.","w":{"uk":"Пропущено гужові вози — їх теж немає серед дозволених знаком {s:4.11}.","ru":"Пропущены гужевые повозки — их тоже нет среди разрешённых знаком {s:4.11}."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3."}],"c":4,"e":{"uk":"Знак {s:4.11} «Рух легкових автомобілів» дозволяє рух **лише** легкових автомобілів, автобусів, мотоциклів, маршрутних транспортних засобів і вантажівок масою до 3,5 т ({p:33.4}); велосипедів, мопедів і гужових возів у цьому переліку немає, тож їм рух заборонено.","ru":"Знак {s:4.11} «Движение легковых автомобилей» разрешает движение **только** легковых автомобилей, автобусов, мотоциклов, маршрутных транспортных средств и грузовиков массой до 3,5 т ({p:33.4}); велосипедов, мопедов и гужевых повозок в этом перечне нет, поэтому им движение запрещено."},"ref":["33.4"],"pic":["img/hsc/33-17-1.jpg"]},{"id":"h33-18","t":"h33","num":"33.18","q":{"uk":"У якому з напрямків Вам дозволено рух у зображеній ситуації?","ru":"В каком из направлений вам разрешено движение в изображённой ситуации?"},"a":[{"uk":"У напрямку А, В або Г.","ru":"В направлении А, В или Г.","w":{"uk":"Знак {s:4.11} не забороняє рух прямо (Б): він стосується видів транспортних засобів, а не напрямків.","ru":"Знак {s:4.11} не запрещает движение прямо (Б): он касается видов транспортных средств, а не направлений."}},{"uk":"У напрямку А або Г.","ru":"В направлении А или Г.","w":{"uk":"Знак не забороняє рух у напрямках Б і В: легковому автомобілю рух дозволено, а напрямки задають знаки {s:4.1}–{s:4.6}.","ru":"Знак не запрещает движение в направлениях Б и В: легковому автомобилю движение разрешено, а направления задают знаки {s:4.1}–{s:4.6}."}},{"uk":"У напрямку А, Б або В.","ru":"В направлении А, Б или В.","w":{"uk":"Знак не забороняє розворот (Г): {s:4.11} не належить до знаків, що визначають напрямок руху.","ru":"Знак не запрещает разворот (Г): {s:4.11} не относится к знакам, определяющим направление движения."}},{"uk":"У будь-якому напрямку.","ru":"В любом направлении."}],"c":3,"e":{"uk":"Знак {s:4.11} «Рух легкових автомобілів» не визначає напрямку руху — він лише дозволяє рух легкових автомобілів та деяких інших транспортних засобів ({p:33.4}). Ви керуєте легковим автомобілем, тому можете рухатися в будь-якому напрямку.","ru":"Знак {s:4.11} «Движение легковых автомобилей» не определяет направления движения — он лишь разрешает движение легковых автомобилей и некоторых других транспортных средств ({p:33.4}). Вы управляете легковым автомобилем, поэтому можете двигаться в любом направлении."},"ref":["33.4"],"pic":["img/hsc/33-18-1.jpg"]},{"id":"h33-19","t":"h33","num":"33.19","q":{"uk":"Зображений дорожній знак дозволяє рух:","ru":"Изображённый дорожный знак разрешает движение:"},"a":[{"uk":"На велосипедах і мопедах.","ru":"На велосипедах и мопедах.","w":{"uk":"Рух мопедів велосипедною доріжкою знак не дозволяє.","ru":"Движение мопедов по велосипедной дорожке знак не разрешает."}},{"uk":"На мопедах і велосипедах з підвісним мотором.","ru":"На мопедах и велосипедах с подвесным мотором.","w":{"uk":"Мопеди й велосипеди з підвісним двигуном не належать до тих, кому дозволено рух доріжкою для велосипедистів.","ru":"Мопеды и велосипеды с подвесным двигателем не относятся к тем, кому разрешено движение по дорожке для велосипедистов."}},{"uk":"На велосипедах.","ru":"На велосипедах.","w":{"uk":"Відповідь неповна: за відсутності тротуару чи пішохідної доріжки нею можуть рухатися й пішоходи.","ru":"Ответ неполный: при отсутствии тротуара или пешеходной дорожки по ней могут двигаться и пешеходы."}},{"uk":"На велосипедах, а також пішоходам за умови, що поряд немає тротуару або доріжки для руху пішоходів.","ru":"На велосипедах, а также пешеходам при условии, что рядом нет тротуара или дорожки для движения пешеходов."}],"c":3,"e":{"uk":"Це знак {s:4.14} «Доріжка для велосипедистів»: рух на велосипедах, а якщо немає тротуару чи пішохідної доріжки — також пішоходів ({p:33.4}).","ru":"Это знак {s:4.14} «Дорожка для велосипедистов»: движение на велосипедах, а если нет тротуара или пешеходной дорожки — также пешеходов ({p:33.4})."},"ref":["33.4"],"pic":["img/hsc/33-19-1.jpg"]},{"id":"h33-20","t":"h33","num":"33.20","q":{"uk":"Кому заборонено рух у зображеній ситуації?","ru":"Кому запрещено движение в изображённой ситуации?"},"a":[{"uk":"Велосипедистові.","ru":"Велосипедисту.","w":{"uk":"Не лише велосипедистові: водієві мопеда рух пішохідною доріжкою теж заборонено.","ru":"Не только велосипедисту: водителю мопеда движение по пешеходной дорожке тоже запрещено."}},{"uk":"Водієві мопеда.","ru":"Водителю мопеда.","w":{"uk":"Не лише водієві мопеда: велосипедистові рух пішохідною доріжкою теж заборонено.","ru":"Не только водителю мопеда: велосипедисту движение по пешеходной дорожке тоже запрещено."}},{"uk":"Водієві мопеда і велосипедистові.","ru":"Водителю мопеда и велосипедисту."},{"uk":"Усім учасникам руху.","ru":"Всем участникам движения.","w":{"uk":"Пішоходам рух цією доріжкою дозволено — саме для них її призначено.","ru":"Пешеходам движение по этой дорожке разрешено — именно для них она предназначена."}}],"c":2,"e":{"uk":"Знак {s:4.16} «Доріжка для пішоходів» позначає доріжку, призначену **тільки** для руху пішоходів ({p:33.4}), тому велосипедистові й водієві мопеда рух нею заборонено.","ru":"Знак {s:4.16} «Дорожка для пешеходов» обозначает дорожку, предназначенную **только** для движения пешеходов ({p:33.4}), поэтому велосипедисту и водителю мопеда движение по ней запрещено."},"ref":["33.4"],"pic":["img/hsc/33-20-1.jpg"]},{"id":"h33-21","t":"h33","num":"33.21","q":{"uk":"Який із зображених дорожніх знаків позначає кінець дороги з одностороннім рухом?","ru":"Какой из изображённых дорожных знаков обозначает конец дороги с односторонним движением?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:5.32.1} «Тупик».","ru":"Знак 1 — {s:5.32.1} «Тупик»."}},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:5.28} «Смуга руху для аварійної зупинки».","ru":"Знак 2 — {s:5.28} «Полоса движения для аварийной остановки»."}},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — {s:5.29} «Місце для розвороту».","ru":"Знак 3 — {s:5.29} «Место для разворота»."}},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Знак 4 — {s:5.14} «Кінець дороги з реверсивним рухом».","ru":"Знак 4 — {s:5.14} «Конец дороги с реверсивным движением»."}},{"uk":"Знак 5.","ru":"Знак 5."}],"c":4,"e":{"uk":"Знак 5 — {s:5.6} «Кінець дороги з одностороннім рухом»: стрілка знака {s:5.5}, перекреслена червоною смугою ({p:33.5}).","ru":"Знак 5 — {s:5.6} «Конец дороги с односторонним движением»: стрелка знака {s:5.5}, перечёркнутая красной полосой ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-21-1.jpg"]},{"id":"h33-22","t":"h33","num":"33.22","q":{"uk":"Зображений дорожній знак позначає:","ru":"Изображённый дорожный знак обозначает:"},"a":[{"uk":"Кінець ділянки дороги, на одній або кількох смугах якої напрямок руху може змінюватися на протилежний.","ru":"Конец участка дороги, на одной или нескольких полосах которого направление движения может меняться на противоположное.","w":{"uk":"Кінець дороги з реверсивним рухом позначає знак {s:5.14}.","ru":"Конец дороги с реверсивным движением обозначает знак {s:5.14}."}},{"uk":"Кінець смуги для руху маршрутних транспортних засобів.","ru":"Конец полосы для движения маршрутных транспортных средств.","w":{"uk":"Кінець смуги для руху маршрутних транспортних засобів позначає знак {s:5.12}.","ru":"Конец полосы для движения маршрутных транспортных средств обозначает знак {s:5.12}."}},{"uk":"Кінець дороги з розділювальною смугою.","ru":"Конец дороги с разделительной полосой.","w":{"uk":"Знак {s:5.6} стосується одностороннього руху, а не розділювальної смуги.","ru":"Знак {s:5.6} касается одностороннего движения, а не разделительной полосы."}},{"uk":"Кінець дороги або відокремленої проїзної частини, по всій ширині якої рух транспортних засобів здійснюється тільки в одному напрямку.","ru":"Конец дороги или отдельной проезжей части, по всей ширине которой движение транспортных средств осуществляется только в одном направлении."}],"c":3,"e":{"uk":"Це знак {s:5.6} «Кінець дороги з одностороннім рухом»: він завершує дорогу (відокремлену проїзну частину), позначену знаком {s:5.5} ({p:33.5}).","ru":"Это знак {s:5.6} «Конец дороги с односторонним движением»: он завершает дорогу (отдельную проезжую часть), обозначенную знаком {s:5.5} ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-22-1.jpg"]},{"id":"h33-23","t":"h33","num":"33.23","q":{"uk":"Зображений дорожній знак вказує:","ru":"Изображённый дорожный знак указывает:"},"a":[{"uk":"Початок ділянки дороги з двостороннім рухом після одностороннього.","ru":"Начало участка дороги с двусторонним движением после одностороннего.","w":{"uk":"Початок двостороннього руху після одностороннього позначає попереджувальний знак {s:1.26} «Двосторонній рух».","ru":"Начало двустороннего движения после одностороннего обозначает предупреждающий знак {s:1.26} «Двустороннее движение»."}},{"uk":"Початок ділянки дороги з одностороннім рухом.","ru":"Начало участка дороги с односторонним движением.","w":{"uk":"Дорогу з одностороннім рухом позначає знак {s:5.5}.","ru":"Дорогу с односторонним движением обозначает знак {s:5.5}."}},{"uk":"Початок ділянки дороги, де на одній або кількох смугах напрямок руху може змінюватися на протилежний.","ru":"Начало участка дороги, где на одной или нескольких полосах направление движения может меняться на противоположное."},{"uk":"Початок окремої смуги для руху маршрутних транспортних засобів.","ru":"Начало отдельной полосы для движения маршрутных транспортных средств.","w":{"uk":"Смугу для руху маршрутних транспортних засобів позначає знак {s:5.11}.","ru":"Полосу для движения маршрутных транспортных средств обозначает знак {s:5.11}."}}],"c":2,"e":{"uk":"Це знак {s:5.13} «Дорога з реверсивним рухом»: початок ділянки, на якій по одній або кількох смугах напрямок руху може змінюватися на протилежний ({p:33.5}).","ru":"Это знак {s:5.13} «Дорога с реверсивным движением»: начало участка, на котором по одной или нескольким полосам направление движения может меняться на противоположное ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-23-1.jpg"]},{"id":"h33-24","t":"h33","num":"33.24","q":{"uk":"Який із зображених дорожніх знаків інформує про початок ділянки дороги, де на одній або кількох смугах напрямок руху може змінюватися на протилежний?","ru":"Какой из изображённых дорожных знаков информирует о начале участка дороги, где на одной или нескольких полосах направление движения может меняться на противоположное?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — знак пріоритету {s:2.6} «Перевага перед зустрічним рухом».","ru":"Знак 1 — знак приоритета {s:2.6} «Преимущество перед встречным движением»."}},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:5.5} «Дорога з одностороннім рухом».","ru":"Знак 2 — {s:5.5} «Дорога с односторонним движением»."}},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — {s:5.8} «Дорога зі смугою для руху маршрутних транспортних засобів».","ru":"Знак 3 — {s:5.8} «Дорога с полосой для движения маршрутных транспортных средств»."}},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Знак 4 показує смуги руху попутного напрямку, реверсивного руху він не позначає.","ru":"Знак 4 показывает полосы движения попутного направления, реверсивного движения он не обозначает."}},{"uk":"Знак 5.","ru":"Знак 5."}],"c":4,"e":{"uk":"Знак 5 — {s:5.13} «Дорога з реверсивним рухом»: дві протилежно спрямовані стрілки на синьому фоні ({p:33.5}).","ru":"Знак 5 — {s:5.13} «Дорога с реверсивным движением»: две противоположно направленные стрелки на синем фоне ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-24-1.jpg"]},{"id":"h33-25","t":"h33","num":"33.25","q":{"uk":"Який із зображених дорожніх знаків інформує про кінець ділянки дороги, де на одній або кількох смугах напрямок руху може змінюватися на протилежний?","ru":"Какой из изображённых дорожных знаков информирует о конце участка дороги, где на одной или нескольких полосах направление движения может меняться на противоположное?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:5.6} «Кінець дороги з одностороннім рухом».","ru":"Знак 1 — {s:5.6} «Конец дороги с односторонним движением»."}},{"uk":"Знак 2.","ru":"Знак 2."},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — {s:5.21.2} «Кінець додаткової смуги руху».","ru":"Знак 3 — {s:5.21.2} «Конец дополнительной полосы движения»."}},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Знак 4 — {s:5.9} «Кінець дороги зі смугою для руху маршрутних транспортних засобів».","ru":"Знак 4 — {s:5.9} «Конец дороги с полосой для движения маршрутных транспортных средств»."}},{"uk":"Знак 5.","ru":"Знак 5.","w":{"uk":"Знак 5 — знак пріоритету {s:2.5} «Перевага зустрічного руху».","ru":"Знак 5 — знак приоритета {s:2.5} «Преимущество встречного движения»."}}],"c":1,"e":{"uk":"Знак 2 — {s:5.14} «Кінець дороги з реверсивним рухом»: знак {s:5.13}, перекреслений червоною смугою ({p:33.5}).","ru":"Знак 2 — {s:5.14} «Конец дороги с реверсивным движением»: знак {s:5.13}, перечёркнутый красной полосой ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-25-1.jpg"]},{"id":"h33-26","t":"h33","num":"33.26","q":{"uk":"Зображений дорожній знак вказує:","ru":"Изображённый дорожный знак указывает:"},"a":[{"uk":"Дозволені напрямки руху на перехресті.","ru":"Разрешённые направления движения на перекрёстке.","w":{"uk":"Дозволені напрямки руху на перехресті задають наказові знаки {s:4.1}–{s:4.6} або знак {s:5.16}.","ru":"Разрешённые направления движения на перекрёстке задают предписывающие знаки {s:4.1}–{s:4.6} или знак {s:5.16}."}},{"uk":"Те, що на дорозі, яка перетинається, двосторонній рух.","ru":"То, что на пересекаемой дороге двустороннее движение.","w":{"uk":"Знак попереджає не про звичайний двосторонній рух, а про реверсивний, коли напрямок руху на смугах може змінюватися.","ru":"Знак предупреждает не об обычном двустороннем движении, а о реверсивном, когда направление движения на полосах может меняться."}},{"uk":"Напрямок руху по смузі для маршрутних транспортних засобів.","ru":"Направление движения по полосе для маршрутных транспортных средств.","w":{"uk":"Виїзд на дорогу зі смугою для маршрутних транспортних засобів позначають знаки {s:5.10.1}–{s:5.10.4} із зображенням автобуса.","ru":"Выезд на дорогу с полосой для маршрутных транспортных средств обозначают знаки {s:5.10.1}–{s:5.10.4} с изображением автобуса."}},{"uk":"На виїзд на дорогу з реверсивним рухом.","ru":"На выезд на дорогу с реверсивным движением."}],"c":3,"e":{"uk":"Це знак {s:5.15} «Виїзд на дорогу з реверсивним рухом» (горизонтальна двобічна стрілка): він попереджає, що на перехрещуваній дорозі на смугах напрямок руху може змінюватися на протилежний ({p:33.5}).","ru":"Это знак {s:5.15} «Выезд на дорогу с реверсивным движением» (горизонтальная двусторонняя стрелка): он предупреждает, что на пересекаемой дороге на полосах направление движения может меняться на противоположное ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-26-1.jpg"]},{"id":"h33-27","t":"h33","num":"33.27","q":{"uk":"Зображений дорожній знак вказує:","ru":"Изображённый дорожный знак указывает:"},"a":[{"uk":"Те, що смуга використовується для руху тільки певних видів транспортних засобів у зазначених напрямках.","ru":"То, что полоса используется для движения только определённых видов транспортных средств в указанных направлениях.","w":{"uk":"Так визначено знаки {s:5.19.1}–{s:5.19.3} «Використання смуги руху»; на цьому знаку немає символів видів транспортних засобів.","ru":"Так определены знаки {s:5.19.1}–{s:5.19.3} «Использование полосы движения»; на этом знаке нет символов видов транспортных средств."}},{"uk":"Кількість смуг на перехресті і дозволені напрямки руху на кожній з них.","ru":"Количество полос на перекрёстке и разрешённые направления движения по каждой из них."},{"uk":"Обидва варіанти правильні.","ru":"Оба варианта правильны.","w":{"uk":"Правильне лише друге значення: знак не відводить смуги для окремих видів транспортних засобів.","ru":"Верно лишь второе значение: знак не выделяет полосы для отдельных видов транспортных средств."}}],"c":1,"e":{"uk":"Це знак {s:5.16} «Напрямки руху по смугах»: він показує кількість смуг на перехресті та дозволені напрямки руху по кожній з них ({p:33.5}).","ru":"Это знак {s:5.16} «Направления движения по полосам»: он показывает количество полос на перекрёстке и разрешённые направления движения по каждой из них ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-27-1.jpg"]},{"id":"h33-28","t":"h33","num":"33.28","q":{"uk":"Який із зображених дорожніх знаків показує кількість смуг на перехресті й дозволені напрямки руху на кожній з них?","ru":"Какой из изображённых дорожных знаков показывает количество полос на перекрёстке и разрешённые направления движения по каждой из них?"},"a":[{"uk":"Знак 1.","ru":"Знак 1."},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:5.17.1} «Напрямок руху по смугах»: він показує кількість смуг у кожному напрямку на дорозі, а не напрямки руху на перехресті.","ru":"Знак 2 — {s:5.17.1} «Направление движения по полосам»: он показывает количество полос в каждом направлении на дороге, а не направления движения на перекрёстке."}},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — {s:5.17.2} «Напрямок руху по смугах»: так само показує кількість смуг зустрічного й попутного напрямків, а не напрямки руху на перехресті.","ru":"Знак 3 — {s:5.17.2} «Направление движения по полосам»: так же показывает количество полос встречного и попутного направлений, а не направления движения на перекрёстке."}},{"uk":"Знаки 1, 2 і 3.","ru":"Знаки 1, 2 и 3.","w":{"uk":"Знаки {s:5.17.1} і {s:5.17.2} не вказують напрямків руху на перехресті, тому підходить лише знак 1.","ru":"Знаки {s:5.17.1} и {s:5.17.2} не указывают направлений движения на перекрёстке, поэтому подходит только знак 1."}}],"c":0,"e":{"uk":"Знак 1 — {s:5.16} «Напрямки руху по смугах»: стрілки на ньому показують кількість смуг на перехресті та дозволені напрямки руху по кожній з них ({p:33.5}).","ru":"Знак 1 — {s:5.16} «Направления движения по полосам»: стрелки на нём показывают количество полос на перекрёстке и разрешённые направления движения по каждой из них ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-28-1.jpg"]},{"id":"h33-29","t":"h33","num":"33.29","q":{"uk":"Зображений дорожній знак вказує:","ru":"Изображённый дорожный знак указывает:"},"a":[{"uk":"Початок дороги, по всій ширині якої рух транспортних засобів здійснюється тільки в одному напрямку.","ru":"Начало дороги, по всей ширине которой движение транспортных средств осуществляется только в одном направлении.","w":{"uk":"Початок дороги з одностороннім рухом позначає знак {s:5.5}.","ru":"Начало дороги с односторонним движением обозначает знак {s:5.5}."}},{"uk":"Дозволений напрямок руху транспортних засобів на перехресті, дія знака поширюється на всю ширину проїзної частини.","ru":"Разрешённое направление движения транспортных средств на перекрёстке, действие знака распространяется на всю ширину проезжей части.","w":{"uk":"Знак {s:5.18} діє лише на свою смугу, а не на всю ширину проїзної частини; для всієї проїзної частини застосовують наказові знаки {s:4.1}–{s:4.6}.","ru":"Знак {s:5.18} действует только на свою полосу, а не на всю ширину проезжей части; для всей проезжей части применяют предписывающие знаки {s:4.1}–{s:4.6}."}},{"uk":"Дозволений напрямок руху по смузі, над якою його встановлено.","ru":"Разрешённое направление движения по полосе, над которой он установлен."}],"c":2,"e":{"uk":"Це знак {s:5.18} «Напрямок руху по смузі»: він показує дозволений напрямок руху по смузі, над якою встановлений ({p:33.5}).","ru":"Это знак {s:5.18} «Направление движения по полосе»: он показывает разрешённое направление движения по полосе, над которой установлен ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-29-1.jpg"]},{"id":"h33-30","t":"h33","num":"33.30","q":{"uk":"Зображений дорожній знак вказує:","ru":"Изображённый дорожный знак указывает:"},"a":[{"uk":"Дозволені напрямки руху транспортних засобів по смугах на перехресті.","ru":"Разрешённые направления движения транспортных средств по полосам на перекрёстке.","w":{"uk":"Напрямки руху по смугах на перехресті показує знак {s:5.16}, а тут на смузі зображено заборонний знак для певного виду транспортних засобів.","ru":"Направления движения по полосам на перекрёстке показывает знак {s:5.16}, а здесь на полосе изображён запрещающий знак для определённого вида транспортных средств."}},{"uk":"Дозволені напрямки руху транспортних засобів по реверсивній смузі.","ru":"Разрешённые направления движения транспортных средств по реверсивной полосе.","w":{"uk":"Знак не позначає реверсивну смугу — реверсивний рух позначають знаки {s:5.13} і {s:5.15}.","ru":"Знак не обозначает реверсивную полосу — реверсивное движение обозначают знаки {s:5.13} и {s:5.15}."}},{"uk":"Те, що смуга використовується для руху тільки певних видів транспортних засобів у зазначених напрямках.","ru":"То, что полоса используется для движения только определённых видов транспортных средств в указанных направлениях."}],"c":2,"e":{"uk":"Це знак {s:5.19.2} «Використання смуги руху»: він інформує, що смугу використовують для руху лише певних видів транспортних засобів у зазначених напрямках; зображений на середній смузі знак {s:3.3} забороняє рух нею вантажівкам ({p:33.5}).","ru":"Это знак {s:5.19.2} «Использование полосы движения»: он информирует, что полоса используется для движения только определённых видов транспортных средств в указанных направлениях; изображённый на средней полосе знак {s:3.3} запрещает движение по ней грузовикам ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-30-1.jpg"]},{"id":"h33-31","t":"h33","num":"33.31","q":{"uk":"Який із зображених дорожніх знаків встановлюється в кінці смуги, призначеної тільки для транспортних засобів, що рухаються за встановленими маршрутами попутно із загальним потоком транспортних засобів?","ru":"Какой из изображённых дорожных знаков устанавливается в конце полосы, предназначенной только для транспортных средств, движущихся по установленным маршрутам попутно с общим потоком транспортных средств?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:5.14} «Кінець дороги з реверсивним рухом».","ru":"Знак 1 — {s:5.14} «Конец дороги с реверсивным движением»."}},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:5.4} «Кінець дороги для автомобілів».","ru":"Знак 2 — {s:5.4} «Конец дороги для автомобилей»."}},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — {s:5.6} «Кінець дороги з одностороннім рухом».","ru":"Знак 3 — {s:5.6} «Конец дороги с односторонним движением»."}},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Знак 4 — {s:5.9} «Кінець дороги зі смугою для руху маршрутних транспортних засобів»: він завершує дорогу, позначену знаком {s:5.8}, а не окрему смугу попутного напрямку.","ru":"Знак 4 — {s:5.9} «Конец дороги с полосой для движения маршрутных транспортных средств»: он завершает дорогу, обозначенную знаком {s:5.8}, а не отдельную полосу попутного направления."}},{"uk":"Знак 5.","ru":"Знак 5."}],"c":4,"e":{"uk":"Знак 5 — {s:5.12} «Кінець смуги для руху маршрутних транспортних засобів»: перекреслений знак {s:5.11}, яким позначають смугу для маршрутних транспортних засобів, що рухаються попутно загальному потоку ({p:33.5}).","ru":"Знак 5 — {s:5.12} «Конец полосы для движения маршрутных транспортных средств»: перечёркнутый знак {s:5.11}, которым обозначают полосу для маршрутных транспортных средств, движущихся попутно общему потоку ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-31-1.jpg"]},{"id":"h33-32","t":"h33","num":"33.32","q":{"uk":"Дія зображеного дорожнього знака поширюється:","ru":"Действие изображённого дорожного знака распространяется:"},"a":[{"uk":"Тільки на праву смугу, коли знак встановлено по центру над дорогою.","ru":"Только на правую полосу, когда знак установлен по центру над дорогой.","w":{"uk":"Знак, установлений над дорогою, діє на ту смугу, над якою його розміщено, а не автоматично на праву.","ru":"Знак, установленный над дорогой, действует на ту полосу, над которой он размещён, а не автоматически на правую."}},{"uk":"Тільки на ту смугу, над якою його встановлено.","ru":"Только на ту полосу, над которой он установлен.","w":{"uk":"Це лише одне з двох правил: знак, установлений праворуч від дороги, діє на праву смугу.","ru":"Это лишь одно из двух правил: знак, установленный справа от дороги, действует на правую полосу."}},{"uk":"Тільки на праву смугу, коли знак встановлено праворуч від дороги.","ru":"Только на правую полосу, когда знак установлен справа от дороги.","w":{"uk":"Це лише одне з двох правил: знак, установлений над смугою, діє саме на цю смугу.","ru":"Это лишь одно из двух правил: знак, установленный над полосой, действует именно на эту полосу."}},{"uk":"Усі наведені вище відповіді.","ru":"Все приведённые выше ответы.","w":{"uk":"Варіант 1 неправильний, тому «усі відповіді» не підходять.","ru":"Вариант 1 неверен, поэтому «все ответы» не подходят."}},{"uk":"Відповіді 2 і 3.","ru":"Ответы 2 и 3."}],"c":4,"e":{"uk":"Для знака {s:5.11} «Смуга для руху маршрутних транспортних засобів» {p:33.5} встановлює: дія поширюється на смугу, над якою його встановлено, а якщо знак стоїть праворуч від дороги — на праву смугу.","ru":"Для знака {s:5.11} «Полоса для движения маршрутных транспортных средств» {p:33.5} устанавливает: действие распространяется на полосу, над которой он установлен, а если знак стоит справа от дороги — на правую полосу."},"ref":["33.5"],"pic":["img/hsc/33-32-1.jpg"]},{"id":"h33-33","t":"h33","num":"33.33","q":{"uk":"Який із зображених дорожніх знаків позначає смугу призначену для руху транспортних засобів, що рухаються за встановленими маршрутами, та велосипедистів, якщо рух такою смугою здійснюється попутно загальному потоку транспортних засобів?","ru":"Какой из изображённых дорожных знаков обозначает полосу, предназначенную для движения транспортных средств, движущихся по установленным маршрутам, и велосипедистов, если движение по такой полосе осуществляется попутно общему потоку транспортных средств?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:5.8} «Дорога зі смугою для руху маршрутних транспортних засобів»: на ньому смуга для маршрутних транспортних засобів спрямована назустріч загальному потоку.","ru":"Знак 1 — {s:5.8} «Дорога с полосой для движения маршрутных транспортных средств»: на нём полоса для маршрутных транспортных средств направлена навстречу общему потоку."}},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:5.13} «Дорога з реверсивним рухом».","ru":"Знак 2 — {s:5.13} «Дорога с реверсивным движением»."}},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — {s:5.19.2} «Використання смуги руху»: він інформує про обмеження руху смугою для певних видів транспортних засобів.","ru":"Знак 3 — {s:5.19.2} «Использование полосы движения»: он информирует об ограничении движения по полосе для определённых видов транспортных средств."}},{"uk":"Знак 4.","ru":"Знак 4."},{"uk":"Знак 5.","ru":"Знак 5.","w":{"uk":"Знак 5 — {s:5.45.1} «Пункт зупинки автобуса».","ru":"Знак 5 — {s:5.45.1} «Пункт остановки автобуса»."}}],"c":3,"e":{"uk":"Знак 4 — {s:5.11} «Смуга для руху маршрутних транспортних засобів» (стрілка й автобус на одній смузі): смуга для маршрутних транспортних засобів, мопедів, мотоциклів без бокового причепа і велосипедистів, якщо рух нею попутний загальному потоку ({p:33.5}).","ru":"Знак 4 — {s:5.11} «Полоса для движения маршрутных транспортных средств» (стрелка и автобус на одной полосе): полоса для маршрутных транспортных средств, мопедов, мотоциклов без бокового прицепа и велосипедистов, если движение по ней попутное общему потоку ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-33-1.jpg"]},{"id":"h33-34","t":"h33","num":"33.34","q":{"uk":"Чи дозволено Вам повернути ліворуч у зображеній ситуації?","ru":"Разрешено ли вам повернуть налево в изображённой ситуации?"},"a":[{"uk":"Заборонено.","ru":"Запрещено.","w":{"uk":"Поворот ліворуч заборонено не повністю: у другий проїзд повертати ліворуч можна.","ru":"Поворот налево запрещён не полностью: во второй проезд поворачивать налево можно."}},{"uk":"Дозволено тільки в другий проїзд.","ru":"Разрешено только во второй проезд."},{"uk":"Дозволено тільки в обидва проїзди.","ru":"Разрешено в оба проезда.","w":{"uk":"У перший проїзд повертати ліворуч не можна: знак {s:5.7.1} дозволяє рух ним лише праворуч.","ru":"В первый проезд поворачивать налево нельзя: знак {s:5.7.1} разрешает движение по нему только направо."}}],"c":1,"e":{"uk":"Знак {s:5.7.1} «Виїзд на дорогу з одностороннім рухом» над знаком {s:2.1} показує, що першою (ближньою) проїзною частиною перехрещуваної дороги рух дозволено лише праворуч ({p:33.5}). Тому ліворуч можна повернути тільки в другий проїзд.","ru":"Знак {s:5.7.1} «Выезд на дорогу с односторонним движением» над знаком {s:2.1} показывает, что по первой (ближней) проезжей части пересекаемой дороги движение разрешено только направо ({p:33.5}). Поэтому налево можно повернуть только во второй проезд."},"ref":["33.5"],"pic":["img/hsc/33-34-1.jpg"]},{"id":"h33-35","t":"h33","num":"33.35","q":{"uk":"Чи дозволено Вам виконати розворот у зображеній ситуації?","ru":"Разрешено ли вам выполнить разворот в изображённой ситуации?"},"a":[{"uk":"Дозволено.","ru":"Разрешено."},{"uk":"Заборонено.","ru":"Запрещено.","w":{"uk":"Жоден знак тут розвороту не забороняє: {s:5.7.1} стосується руху перехрещуваною дорогою, а розворот забороняє знак {s:3.24}.","ru":"Ни один знак здесь разворот не запрещает: {s:5.7.1} касается движения по пересекаемой дороге, а разворот запрещает знак {s:3.24}."}}],"c":0,"e":{"uk":"Знак {s:5.7.1} визначає лише напрямок руху на перехрещуваній дорозі ({p:33.5}) і не забороняє розвороту на перехресті; дорога, якою ви рухаєтеся, двостороння, тож розвернутися на ній можна.","ru":"Знак {s:5.7.1} определяет лишь направление движения на пересекаемой дороге ({p:33.5}) и не запрещает разворота на перекрёстке; дорога, по которой вы движетесь, двусторонняя, поэтому развернуться на ней можно."},"ref":["33.5"],"pic":["img/hsc/33-35-1.jpg"]},{"id":"h33-36","t":"h33","num":"33.36","q":{"uk":"У яких напрямках Вам дозволено рух у зображеній ситуації?","ru":"В каких направлениях вам разрешено движение в изображённой ситуации?"},"a":[{"uk":"Ліворуч або у зворотному напрямку.","ru":"Налево или в обратном направлении.","w":{"uk":"Рух прямо не заборонено: знак {s:5.7.2} стосується лише перехрещуваної дороги.","ru":"Движение прямо не запрещено: знак {s:5.7.2} касается только пересекаемой дороги."}},{"uk":"Тільки ліворуч.","ru":"Только налево.","w":{"uk":"Знак не забороняє ні руху прямо, ні розвороту — він показує лише напрямок руху перехрещуваною дорогою.","ru":"Знак не запрещает ни движения прямо, ни разворота — он показывает лишь направление движения по пересекаемой дороге."}},{"uk":"Прямо, ліворуч або у зворотному напрямку.","ru":"Прямо, налево или в обратном направлении."},{"uk":"Прямо або ліворуч.","ru":"Прямо или налево.","w":{"uk":"Розворот теж дозволено: знак {s:5.7.2} його не забороняє.","ru":"Разворот тоже разрешён: знак {s:5.7.2} его не запрещает."}}],"c":2,"e":{"uk":"Знак {s:5.7.2} показує, що перехрещуваною дорогою рух дозволено лише ліворуч ({p:33.5}), тому заборонено тільки поворот праворуч; рух прямо, поворот ліворуч і розворот на перехресті дозволені.","ru":"Знак {s:5.7.2} показывает, что по пересекаемой дороге движение разрешено только налево ({p:33.5}), поэтому запрещён только поворот направо; движение прямо, поворот налево и разворот на перекрёстке разрешены."},"ref":["33.5"],"pic":["img/hsc/33-36-1.jpg"]},{"id":"h33-37","t":"h33","num":"33.37","q":{"uk":"Зображений дорожній знак вказує:","ru":"Изображённый дорожный знак указывает:"},"a":[{"uk":"Дозволений напрямок руху – тільки ліворуч.","ru":"Разрешённое направление движения – только налево.","w":{"uk":"Знак не наказує рух лише ліворуч — так діяв би наказовий знак {s:4.3}; він інформує про напрямок руху перехрещуваною дорогою.","ru":"Знак не предписывает движение только налево — так действовал бы предписывающий знак {s:4.3}; он информирует о направлении движения по пересекаемой дороге."}},{"uk":"Напрямок головної дороги на перехресті.","ru":"Направление главной дороги на перекрёстке.","w":{"uk":"Напрямок головної дороги на перехресті показує табличка {s:7.8}, яку застосовують зі знаками пріоритету.","ru":"Направление главной дороги на перекрёстке показывает табличка {s:7.8}, которую применяют со знаками приоритета."}},{"uk":"Напрямок руху на дорозі, що перетинається, якщо на ній організовано односторонній рух.","ru":"Направление движения на пересекаемой дороге, если на ней организовано одностороннее движение."}],"c":2,"e":{"uk":"Це знак {s:5.7.2} «Виїзд на дорогу з одностороннім рухом» (стрілка ліворуч): він показує напрямок руху на перехрещуваній дорозі з одностороннім рухом, і рух нею дозволено лише в напрямку стрілки ({p:33.5}).","ru":"Это знак {s:5.7.2} «Выезд на дорогу с односторонним движением» (стрелка влево): он показывает направление движения на пересекаемой дороге с односторонним движением, и движение по ней разрешено только в направлении стрелки ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-37-1.jpg"]},{"id":"h33-38","t":"h33","num":"33.38","q":{"uk":"Зображений дорожній знак позначає:","ru":"Изображённый дорожный знак обозначает:"},"a":[{"uk":"Дорогу, на якій рух транспортних засобів здійснюється по двох зустрічних смугах.","ru":"Дорогу, на которой движение транспортных средств осуществляется по двум встречным полосам.","w":{"uk":"Знак позначає не звичайну дорогу з двома зустрічними смугами, а дорогу, де одну смугу відведено для маршрутних транспортних засобів.","ru":"Знак обозначает не обычную дорогу с двумя встречными полосами, а дорогу, где одна полоса выделена для маршрутных транспортных средств."}},{"uk":"Дорогу, на якій рух транспортних засобів здійснюється за встановленим маршрутом по спеціально відведеній смузі, розташованій з правого боку проїзної частини.","ru":"Дорогу, на которой движение транспортных средств осуществляется по установленному маршруту по специально выделенной полосе, расположенной с правой стороны проезжей части.","w":{"uk":"Визначення неповне: відведеною смугою можуть рухатися також мопеди, мотоцикли без бокового причепа й велосипедисти, а розташування смуги праворуч Правила не встановлюють.","ru":"Определение неполное: по выделенной полосе могут двигаться также мопеды, мотоциклы без бокового прицепа и велосипедисты, а расположение полосы справа Правила не устанавливают."}},{"uk":"Дорогу, на якій по спеціально відведеній смузі здійснюється рух транспортних засобів за встановленим маршрутом, мопедів, мотоциклів (за винятком мотоциклів з боковим причепом, мотоколясок, триколісних транспортних засобів) та велосипедистів.","ru":"Дорогу, на которой по специально выделенной полосе осуществляется движение транспортных средств по установленному маршруту, мопедов, мотоциклов (за исключением мотоциклов с боковым прицепом, мотоколясок, трёхколёсных транспортных средств) и велосипедистов."}],"c":2,"e":{"uk":"Це знак {s:5.8} «Дорога зі смугою для руху маршрутних транспортних засобів», і варіант 3 дослівно повторює його визначення з {p:33.5}.","ru":"Это знак {s:5.8} «Дорога с полосой для движения маршрутных транспортных средств», и вариант 3 дословно повторяет его определение из {p:33.5}."},"ref":["33.5"],"pic":["img/hsc/33-38-1.jpg"]},{"id":"h33-39","t":"h33","num":"33.39","q":{"uk":"Зображений дорожній знак позначає:","ru":"Изображённый дорожный знак обозначает:"},"a":[{"uk":"Кінець дороги, на якій по спеціально відведеній смузі здійснюється рух транспортних засобів за встановленим маршрутом, мопедів, мотоциклів (за винятком мотоциклів з боковим причепом, мотоколясок, триколісних транспортних засобів) та велосипедистів.","ru":"Конец дороги, на которой по специально выделенной полосе осуществляется движение транспортных средств по установленному маршруту, мопедов, мотоциклов (за исключением мотоциклов с боковым прицепом, мотоколясок, трёхколёсных транспортных средств) и велосипедистов."},{"uk":"Кінець дороги, на якій рух транспортних засобів здійснюється за встановленим маршрутом по спеціально відведеній смузі, розташованій з правого боку проїзної частини.","ru":"Конец дороги, на которой движение транспортных средств осуществляется по установленному маршруту по специально выделенной полосе, расположенной с правой стороны проезжей части.","w":{"uk":"Визначення неповне: смугою рухаються також мопеди, мотоцикли й велосипедисти, а розташування смуги праворуч Правила не встановлюють.","ru":"Определение неполное: по полосе движутся также мопеды, мотоциклы и велосипедисты, а расположение полосы справа Правила не устанавливают."}},{"uk":"Кінець дороги, на якій рух транспортних засобів здійснюється по двох зустрічних смугах.","ru":"Конец дороги, на которой движение транспортных средств осуществляется по двум встречным полосам.","w":{"uk":"Знак завершує не звичайну дорогу з двома зустрічними смугами, а дорогу з відведеною смугою для маршрутних транспортних засобів.","ru":"Знак завершает не обычную дорогу с двумя встречными полосами, а дорогу с выделенной полосой для маршрутных транспортных средств."}}],"c":0,"e":{"uk":"Це знак {s:5.9} «Кінець дороги зі смугою для руху маршрутних транспортних засобів»: він завершує дорогу, позначену знаком {s:5.8}, визначення якої й наведено у варіанті 1 ({p:33.5}).","ru":"Это знак {s:5.9} «Конец дороги с полосой для движения маршрутных транспортных средств»: он завершает дорогу, обозначенную знаком {s:5.8}, определение которой и приведено в варианте 1 ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-39-1.jpg"]},{"id":"h33-40","t":"h33","num":"33.40","q":{"uk":"У якому з напрямків дозволено рух водієві білого автомобіля в зображеній ситуації?","ru":"В каком из направлений разрешено движение водителю белого автомобиля в изображённой ситуации?"},"a":[{"uk":"У напрямку А.","ru":"В направлении А.","w":{"uk":"Рух прямо (Б) і розворот (Г) теж дозволено: знак стосується лише руху перехрещуваною дорогою.","ru":"Движение прямо (Б) и разворот (Г) тоже разрешены: знак касается только движения по пересекаемой дороге."}},{"uk":"У напрямку А, Б або В.","ru":"В направлении А, Б или В.","w":{"uk":"Ліворуч (В) перехрещуваною дорогою можуть рухатися тільки маршрутні транспортні засоби.","ru":"Налево (В) по пересекаемой дороге могут двигаться только маршрутные транспортные средства."}},{"uk":"У напрямку А, Б, або Г.","ru":"В направлении А, Б или Г."},{"uk":"У напрямку А або Г.","ru":"В направлении А или Г.","w":{"uk":"Рух прямо (Б) знак {s:5.10.1} не забороняє.","ru":"Движение прямо (Б) знак {s:5.10.1} не запрещает."}},{"uk":"У будь-якому з напрямків.","ru":"В любом из направлений.","w":{"uk":"Поворот ліворуч (В) заборонено: у цьому напрямку перехрещуваною дорогою рухаються лише маршрутні транспортні засоби.","ru":"Поворот налево (В) запрещён: в этом направлении по пересекаемой дороге движутся только маршрутные транспортные средства."}}],"c":2,"e":{"uk":"Знак {s:5.10.1} позначає виїзд на дорогу, де загальний потік рухається праворуч, а ліворуч — лише маршрутні транспортні засоби спеціально відведеною смугою ({p:33.5}). Тому поворот ліворуч (В) заборонено, а праворуч (А), прямо (Б) і розворот (Г) дозволено.","ru":"Знак {s:5.10.1} обозначает выезд на дорогу, где общий поток движется направо, а налево — только маршрутные транспортные средства по специально выделенной полосе ({p:33.5}). Поэтому поворот налево (В) запрещён, а направо (А), прямо (Б) и разворот (Г) разрешены."},"ref":["33.5"],"pic":["img/hsc/33-40-1.jpg"]},{"id":"h33-41","t":"h33","num":"33.41","q":{"uk":"У якому з напрямків дозволено рух водієві білого автомобіля в зображеній ситуації?","ru":"В каком из направлений разрешено движение водителю белого автомобиля в изображённой ситуации?"},"a":[{"uk":"У напрямку Б або В.","ru":"В направлении Б или В.","w":{"uk":"Розворот (Г) теж дозволено: знак {s:5.10.2} його не забороняє.","ru":"Разворот (Г) тоже разрешён: знак {s:5.10.2} его не запрещает."}},{"uk":"У напрямку Б, В або Г.","ru":"В направлении Б, В или Г."},{"uk":"У напрямку А, Б, або Г.","ru":"В направлении А, Б или Г.","w":{"uk":"Праворуч (А) рухаються лише маршрутні транспортні засоби, а поворот ліворуч (В) якраз дозволено.","ru":"Направо (А) движутся только маршрутные транспортные средства, а поворот налево (В) как раз разрешён."}},{"uk":"У напрямку В або Г.","ru":"В направлении В или Г.","w":{"uk":"Рух прямо (Б) знак {s:5.10.2} не забороняє.","ru":"Движение прямо (Б) знак {s:5.10.2} не запрещает."}},{"uk":"У будь-якому з напрямків.","ru":"В любом из направлений.","w":{"uk":"Поворот праворуч (А) заборонено: у цьому напрямку перехрещуваною дорогою рухаються лише маршрутні транспортні засоби.","ru":"Поворот направо (А) запрещён: в этом направлении по пересекаемой дороге движутся только маршрутные транспортные средства."}}],"c":1,"e":{"uk":"Знак {s:5.10.2} показує, що загальний потік на перехрещуваній дорозі рухається ліворуч, а праворуч — лише маршрутні транспортні засоби спеціально відведеною смугою ({p:33.5}). Тому поворот праворуч (А) заборонено, а прямо (Б), ліворуч (В) і розворот (Г) дозволено.","ru":"Знак {s:5.10.2} показывает, что общий поток на пересекаемой дороге движется налево, а направо — только маршрутные транспортные средства по специально выделенной полосе ({p:33.5}). Поэтому поворот направо (А) запрещён, а прямо (Б), налево (В) и разворот (Г) разрешены."},"ref":["33.5"],"pic":["img/hsc/33-41-1.jpg"]},{"id":"h33-42","t":"h33","num":"33.42","q":{"uk":"Зображений дорожній знак інформує:","ru":"Изображённый дорожный знак информирует:"},"a":[{"uk":"Про початок смуги гальмування з правого боку.","ru":"О начале полосы торможения справа.","w":{"uk":"Відповідь неповна: знак позначає також початок додаткової смуги на підйом.","ru":"Ответ неполный: знак обозначает также начало дополнительной полосы на подъём."}},{"uk":"Про початок додаткової смуги руху на підйомі.","ru":"О начале дополнительной полосы движения на подъёме.","w":{"uk":"Відповідь неповна: знак позначає також початок смуги гальмування.","ru":"Ответ неполный: знак обозначает также начало полосы торможения."}},{"uk":"Про дозволені напрямки руху транспортних засобів на перехресті.","ru":"О разрешённых направлениях движения транспортных средств на перекрёстке.","w":{"uk":"Дозволені напрямки руху по смугах на перехресті показує знак {s:5.16}.","ru":"Разрешённые направления движения по полосам на перекрёстке показывает знак {s:5.16}."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2."}],"c":3,"e":{"uk":"Це знак {s:5.20.1} «Початок додаткової смуги руху»: він позначає початок додаткової смуги на підйом або смуги гальмування ({p:33.5}), тому правильні обидва перші варіанти.","ru":"Это знак {s:5.20.1} «Начало дополнительной полосы движения»: он обозначает начало дополнительной полосы на подъём или полосы торможения ({p:33.5}), поэтому верны оба первых варианта."},"ref":["33.5"],"pic":["img/hsc/33-42-1.jpg"]},{"id":"h33-43","t":"h33","num":"33.43","q":{"uk":"На кого (які транспортні засоби) не поширюється дія зображеного дорожнього знака?","ru":"На кого (какие транспортные средства) не распространяется действие изображённого дорожного знака?"},"a":[{"uk":"На таксі, що здійснюють посадку або висадку пасажирів (розвантаження чи завантаження вантажу).","ru":"На такси, осуществляющие посадку или высадку пассажиров (разгрузку или погрузку груза).","w":{"uk":"Відповідь неповна: знак не поширюється також на маршрутні транспортні засоби.","ru":"Ответ неполный: знак не распространяется также на маршрутные транспортные средства."}},{"uk":"На транспортні засоби, що рухаються за встановленими маршрутами.","ru":"На транспортные средства, движущиеся по установленным маршрутам.","w":{"uk":"Відповідь неповна: таксі теж може зупинитися для посадки чи висадки пасажирів.","ru":"Ответ неполный: такси тоже может остановиться для посадки или высадки пассажиров."}},{"uk":"На водіїв з інвалідністю, що керують мотоколяскою або автомобілем, позначеними розпізнавальним знаком «Водій з інвалідністю».","ru":"На водителей с инвалидностью, управляющих мотоколяской или автомобилем, обозначенными опознавательным знаком «Водитель с инвалидностью».","w":{"uk":"На водіїв з інвалідністю дія знака {s:3.34} не поширюється лише за наявності під ним таблички {s:7.18}.","ru":"На водителей с инвалидностью действие знака {s:3.34} не распространяется только при наличии под ним таблички {s:7.18}."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2."},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3.","w":{"uk":"Водіїв з інвалідністю звільняє від дії знака {s:3.34} лише табличка {s:7.18}, а без неї знак діє і на них.","ru":"Водителей с инвалидностью освобождает от действия знака {s:3.34} только табличка {s:7.18}, а без неё знак действует и на них."}}],"c":3,"e":{"uk":"Це знак {s:3.34} «Зупинку заборонено»: він не забороняє зупинку таксі для посадки чи висадки пасажирів (розвантаження чи завантаження вантажу) і не поширюється на транспортні засоби, що рухаються за встановленими маршрутами ({p:33.3}).","ru":"Это знак {s:3.34} «Остановка запрещена»: он не запрещает остановку такси для посадки или высадки пассажиров (разгрузки или погрузки груза) и не распространяется на транспортные средства, движущиеся по установленным маршрутам ({p:33.3})."},"ref":["33.3"],"pic":["img/hsc/33-43-1.jpg"]},{"id":"h33-44","t":"h33","num":"33.44","q":{"uk":"На кого (які транспортні засоби) не поширюється дія зображеного дорожнього знака?","ru":"На кого (какие транспортные средства) не распространяется действие изображённого дорожного знака?"},"a":[{"uk":"На таксі з увімкненим таксометром.","ru":"На такси с включённым таксометром.","w":{"uk":"Відповідь неповна: знак не поширюється також на водіїв з інвалідністю.","ru":"Ответ неполный: знак не распространяется также на водителей с инвалидностью."}},{"uk":"На автомобілі, що належать громадянам, які проживають у зоні дії знака.","ru":"На автомобили, принадлежащие гражданам, проживающим в зоне действия знака.","w":{"uk":"Виняток для мешканців зони стосується знаків {s:3.1}–{s:3.8} і {s:3.11}, які забороняють рух, а не стоянку.","ru":"Исключение для жителей зоны касается знаков {s:3.1}–{s:3.8} и {s:3.11}, которые запрещают движение, а не стоянку."}},{"uk":"На водії з інвалідністю, що керують мотоколясками або автомобілями, позначеними розпізнавальним знаком «Водій з інвалідністю».","ru":"На водителей с инвалидностью, управляющих мотоколясками или автомобилями, обозначенными опознавательным знаком «Водитель с инвалидностью».","w":{"uk":"Відповідь неповна: знак не поширюється також на таксі з увімкненим таксометром.","ru":"Ответ неполный: знак не распространяется также на такси с включённым таксометром."}},{"uk":"Відповіді 1 і 3.","ru":"Ответы 1 и 3."},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3.","w":{"uk":"Мешканці зони не мають винятку із заборони стоянки — їх звільнено лише від знаків, що забороняють рух.","ru":"Жители зоны не имеют исключения из запрета стоянки — они освобождены только от знаков, запрещающих движение."}}],"c":3,"e":{"uk":"Це знак {s:3.35} «Стоянку заборонено»: його дія не поширюється на таксі з увімкненим таксометром і на водіїв з інвалідністю, які керують мотоколяскою чи автомобілем з розпізнавальним знаком «Водій з інвалідністю» ({p:33.3}).","ru":"Это знак {s:3.35} «Стоянка запрещена»: его действие не распространяется на такси с включённым таксометром и на водителей с инвалидностью, управляющих мотоколяской или автомобилем с опознавательным знаком «Водитель с инвалидностью» ({p:33.3})."},"ref":["33.3"],"pic":["img/hsc/33-44-1.jpg"]},{"id":"h33-45","t":"h33","num":"33.45","q":{"uk":"У якому з місць Ви можете виконати зупинку в зображеній ситуації?","ru":"В каком из мест вы можете выполнить остановку в изображённой ситуации?"},"a":[{"uk":"У місці В або Г.","ru":"В месте В или Г.","w":{"uk":"Місця А і Б праворуч теж підходять: знак {s:3.35} не забороняє зупинку.","ru":"Места А и Б справа тоже подходят: знак {s:3.35} не запрещает остановку."}},{"uk":"У місці А, В або Г.","ru":"В месте А, В или Г.","w":{"uk":"Місце Б теж підходить: знак {s:3.35} забороняє стоянку, а не зупинку.","ru":"Место Б тоже подходит: знак {s:3.35} запрещает стоянку, а не остановку."}},{"uk":"У місці Б або В.","ru":"В месте Б или В.","w":{"uk":"Місця А і Г теж підходять: зупинку тут нічого не забороняє.","ru":"Места А и Г тоже подходят: остановку здесь ничто не запрещает."}},{"uk":"У місці А або Г.","ru":"В месте А или Г.","w":{"uk":"Місця Б і В теж підходять: знак {s:3.35} не забороняє зупинку.","ru":"Места Б и В тоже подходят: знак {s:3.35} не запрещает остановку."}},{"uk":"У будь-якому місці.","ru":"В любом месте."}],"c":4,"e":{"uk":"Знак {s:3.35} «Стоянку заборонено» з табличкою {s:7.2.4} (ви в зоні дії знака) забороняє лише стоянку, а не зупинку ({p:33.3}). На лівому боці цієї дороги з однією смугою в кожному напрямку зупинка в населеному пункті теж дозволена ({p:15.3}), тож зупинитися можна в будь-якому місці.","ru":"Знак {s:3.35} «Стоянка запрещена» с табличкой {s:7.2.4} (вы в зоне действия знака) запрещает только стоянку, а не остановку ({p:33.3}). На левой стороне этой дороги с одной полосой в каждом направлении остановка в населённом пункте тоже разрешена ({p:15.3}), поэтому остановиться можно в любом месте."},"ref":["33.3","33.7","15.3"],"pic":["img/hsc/33-45-1.jpg"]},{"id":"h33-46","t":"h33","num":"33.46","q":{"uk":"Чи дозволено водіям транспортних засобів виконувати посадку або висадку пасажирів у зоні дії зображеного знака?","ru":"Разрешено ли водителям транспортных средств осуществлять посадку или высадку пассажиров в зоне действия изображённого знака?"},"a":[{"uk":"Заборонено.","ru":"Запрещено.","w":{"uk":"Посадка й висадка пасажирів — це зупинка, а знак {s:3.35} забороняє лише стоянку.","ru":"Посадка и высадка пассажиров — это остановка, а знак {s:3.35} запрещает только стоянку."}},{"uk":"Дозволено.","ru":"Разрешено."},{"uk":"Дозволено на час до 5 хвилин.","ru":"Разрешено на время до 5 минут.","w":{"uk":"Посадку чи висадку пасажирів не обмежено 5 хвилинами: за {p:1.10} це зупинка, навіть якщо вона триває довше.","ru":"Посадка или высадка пассажиров не ограничена 5 минутами: по {p:1.10} это остановка, даже если она длится дольше."}}],"c":1,"e":{"uk":"Знак {s:3.35} «Стоянку заборонено» забороняє лише стоянку ({p:33.3}); посадка чи висадка пасажирів — це зупинка, навіть якщо вона триває понад 5 хвилин ({p:1.10}), тож її дозволено.","ru":"Знак {s:3.35} «Стоянка запрещена» запрещает только стоянку ({p:33.3}); посадка или высадка пассажиров — это остановка, даже если она длится более 5 минут ({p:1.10}), поэтому она разрешена."},"ref":["33.3","1.10"],"pic":["img/hsc/33-46-1.jpg"]},{"id":"h33-47","t":"h33","num":"33.47","q":{"uk":"У якому з місць Ви можете зупинити транспортний засіб для стоянки в зображеній ситуації?","ru":"В каком из мест вы можете поставить транспортное средство на стоянку в изображённой ситуации?"},"a":[{"uk":"У місці А або Б.","ru":"В месте А или Б.","w":{"uk":"Місце Г теж підходить: воно розташоване перед знаком, а зона дії {s:3.35} починається від місця його встановлення.","ru":"Место Г тоже подходит: оно расположено перед знаком, а зона действия {s:3.35} начинается от места его установки."}},{"uk":"У місці А, Б або Г.","ru":"В месте А, Б или Г."},{"uk":"У місці А або Г.","ru":"В месте А или Г.","w":{"uk":"Місце Б на правому боці теж підходить: знак, установлений на лівому боці, на правий бік не поширюється.","ru":"Место Б на правой стороне тоже подходит: знак, установленный на левой стороне, на правую сторону не распространяется."}},{"uk":"У місці А, В або Г.","ru":"В месте А, В или Г.","w":{"uk":"Місце В — у зоні дії знака {s:3.35} (200 м за ним на тому самому боці), стоянку там заборонено.","ru":"Место В — в зоне действия знака {s:3.35} (200 м за ним на той же стороне), стоянка там запрещена."}},{"uk":"У будь-якому місці.","ru":"В любом месте.","w":{"uk":"У місці В стоянку заборонено знаком {s:3.35} з табличкою {s:7.2.2}.","ru":"В месте В стоянка запрещена знаком {s:3.35} с табличкой {s:7.2.2}."}}],"c":1,"e":{"uk":"Знак {s:3.35} установлено на лівому боці дороги, а діє він лише на тому боці, де встановлений ({p:33.3}); табличка {s:7.2.2} показує, що зона його дії — 200 м від знака вперед ({p:33.7}). Тому стоянку заборонено лише в місці В, а в місцях А, Б (правий бік) і Г (перед знаком) вона дозволена.","ru":"Знак {s:3.35} установлен на левой стороне дороги, а действует он только на той стороне, где установлен ({p:33.3}); табличка {s:7.2.2} показывает, что зона его действия — 200 м от знака вперёд ({p:33.7}). Поэтому стоянка запрещена только в месте В, а в местах А, Б (правая сторона) и Г (перед знаком) она разрешена."},"ref":["33.3","33.7","15.3"],"pic":["img/hsc/33-47-1.jpg"]},{"id":"h33-48","t":"h33","num":"33.48","q":{"uk":"У якому з місць Вам дозволено виконати стоянку в зображеній ситуації?","ru":"В каком из мест вам разрешено выполнить стоянку в изображённой ситуации?"},"a":[{"uk":"У місці А.","ru":"В месте А.","w":{"uk":"Місце А розташоване перед знаком, тобто ще в зоні заборони стоянки.","ru":"Место А расположено перед знаком, то есть ещё в зоне запрета стоянки."}},{"uk":"У місці А чи Г.","ru":"В месте А или Г.","w":{"uk":"Місця А і Г ще в зоні дії знаків {s:3.35}: табличка {s:7.2.3} показує, що заборона закінчується лише біля знаків.","ru":"Места А и Г ещё в зоне действия знаков {s:3.35}: табличка {s:7.2.3} показывает, что запрет заканчивается только у знаков."}},{"uk":"У місці Б.","ru":"В месте Б.","w":{"uk":"Місце В теж підходить: на лівому боці за знаком заборона стоянки так само закінчилася.","ru":"Место В тоже подходит: на левой стороне за знаком запрет стоянки так же закончился."}},{"uk":"У місці Б або В.","ru":"В месте Б или В."},{"uk":"У місці В або Г.","ru":"В месте В или Г.","w":{"uk":"Місце Г розташоване перед знаком на лівому боці, тобто ще в зоні заборони.","ru":"Место Г расположено перед знаком на левой стороне, то есть ещё в зоне запрета."}}],"c":3,"e":{"uk":"Знаки {s:3.35} з табличкою {s:7.2.3} на обох боках дороги позначають кінець зони заборони стоянки ({p:33.7}): до знаків (місця А і Г) стоянку заборонено, а за ними (Б і В) — дозволено.","ru":"Знаки {s:3.35} с табличкой {s:7.2.3} на обеих сторонах дороги обозначают конец зоны запрета стоянки ({p:33.7}): до знаков (места А и Г) стоянка запрещена, а за ними (Б и В) — разрешена."},"ref":["33.3","33.7"],"pic":["img/hsc/33-48-1.jpg"]},{"id":"h33-49","t":"h33","num":"33.49","q":{"uk":"Який із зображених знаків забороняє стоянку тільки в непарні числа місяця?","ru":"Какой из изображённых знаков запрещает стоянку только по нечётным числам месяца?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:3.34} «Зупинку заборонено»: діє щодня і забороняє також зупинку.","ru":"Знак 1 — {s:3.34} «Остановка запрещена»: действует ежедневно и запрещает также остановку."}},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:3.35} «Стоянку заборонено»: діє незалежно від числа місяця.","ru":"Знак 2 — {s:3.35} «Стоянка запрещена»: действует независимо от числа месяца."}},{"uk":"Знак 3.","ru":"Знак 3."},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Знак 4 — {s:3.37} «Стоянку заборонено в парні числа місяця» (дві риски).","ru":"Знак 4 — {s:3.37} «Стоянка запрещена по чётным числам месяца» (две черты)."}}],"c":2,"e":{"uk":"Знак 3 — {s:3.36} «Стоянку заборонено в непарні числа місяця»: на синьому полі одна вертикальна риска ({p:33.3}).","ru":"Знак 3 — {s:3.36} «Стоянка запрещена по нечётным числам месяца»: на синем поле одна вертикальная черта ({p:33.3})."},"ref":["33.3"],"pic":["img/hsc/33-49-1.jpg"]},{"id":"h33-50","t":"h33","num":"33.50","q":{"uk":"Який із зображених знаків забороняє стоянку тільки в парні числа місяця?","ru":"Какой из изображённых знаков запрещает стоянку только по чётным числам месяца?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:3.34} «Зупинку заборонено»: діє щодня і забороняє також зупинку.","ru":"Знак 1 — {s:3.34} «Остановка запрещена»: действует ежедневно и запрещает также остановку."}},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:3.35} «Стоянку заборонено»: діє незалежно від числа місяця.","ru":"Знак 2 — {s:3.35} «Стоянка запрещена»: действует независимо от числа месяца."}},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — {s:3.36} «Стоянку заборонено в непарні числа місяця» (одна риска).","ru":"Знак 3 — {s:3.36} «Стоянка запрещена по нечётным числам месяца» (одна черта)."}},{"uk":"Знак 4.","ru":"Знак 4."}],"c":3,"e":{"uk":"Знак 4 — {s:3.37} «Стоянку заборонено в парні числа місяця»: на синьому полі дві вертикальні риски ({p:33.3}).","ru":"Знак 4 — {s:3.37} «Стоянка запрещена по чётным числам месяца»: на синем поле две вертикальные черты ({p:33.3})."},"ref":["33.3"],"pic":["img/hsc/33-50-1.jpg"]},{"id":"h33-51","t":"h33","num":"33.51","q":{"uk":"Який час дається водіям для перестановки транспортних засобів з одного боку дороги на другий у разі одночасного встановлення зображених дорожніх знаків?","ru":"Какое время даётся водителям для перестановки транспортных средств с одной стороны дороги на другую в случае одновременной установки изображённых дорожных знаков?"},"a":[{"uk":"З 17:00 до 23:00.","ru":"С 17:00 до 23:00.","w":{"uk":"Правила встановлюють інший проміжок — з 19 до 24 год.","ru":"Правила устанавливают другой промежуток — с 19 до 24 ч."}},{"uk":"З 19:00 до 24:00.","ru":"С 19:00 до 24:00."},{"uk":"З 7:00 до 24:00.","ru":"С 7:00 до 24:00.","w":{"uk":"Перестановка з 7:00 тривала б майже всю добу, а Правила відводять на неї лише час з 19 до 24 год.","ru":"Перестановка с 7:00 длилась бы почти сутки, а Правила отводят на неё лишь время с 19 до 24 ч."}}],"c":1,"e":{"uk":"У разі одночасного застосування знаків {s:3.36} і {s:3.37} час перестановки транспортних засобів з одного боку дороги на інший — з 19 до 24 год ({p:33.3}).","ru":"При одновременном применении знаков {s:3.36} и {s:3.37} время перестановки транспортных средств с одной стороны дороги на другую — с 19 до 24 ч ({p:33.3})."},"ref":["33.3"],"pic":["img/hsc/33-51-1.jpg"]},{"id":"h33-52","t":"h33","num":"33.52","q":{"uk":"Чи дозволено Вам виконати посадку пасажира в зображеній ситуації?","ru":"Разрешено ли вам осуществить посадку пассажира в изображённой ситуации?"},"a":[{"uk":"Дозволено.","ru":"Разрешено."},{"uk":"Заборонено.","ru":"Запрещено.","w":{"uk":"Посадка пасажира — це зупинка, а знак {s:3.35} її не забороняє.","ru":"Посадка пассажира — это остановка, а знак {s:3.35} её не запрещает."}}],"c":0,"e":{"uk":"Знак {s:3.35} «Стоянку заборонено» з табличкою {s:7.2.2} (150 м) забороняє лише стоянку ({p:33.3}), а зупинка для посадки пасажира стоянкою не є ({p:1.10}), тож її дозволено.","ru":"Знак {s:3.35} «Стоянка запрещена» с табличкой {s:7.2.2} (150 м) запрещает только стоянку ({p:33.3}), а остановка для посадки пассажира стоянкой не является ({p:1.10}), поэтому она разрешена."},"ref":["33.3","1.10"],"pic":["img/hsc/33-52-1.jpg"]},{"id":"h33-53","t":"h33","num":"33.53","q":{"uk":"Зображений дорожній знак забороняє:","ru":"Изображённый дорожный знак запрещает:"},"a":[{"uk":"Зупинку і стоянку всіх транспортних засобів.","ru":"Остановку и стоянку всех транспортных средств.","w":{"uk":"Зупинку і стоянку забороняє знак {s:3.34} «Зупинку заборонено» (червоний хрест на синьому полі).","ru":"Остановку и стоянку запрещает знак {s:3.34} «Остановка запрещена» (красный крест на синем поле)."}},{"uk":"Зупинку транспортних засобів.","ru":"Остановку транспортных средств.","w":{"uk":"Знак {s:3.35} не забороняє зупинку — лише стоянку.","ru":"Знак {s:3.35} не запрещает остановку — только стоянку."}},{"uk":"Стоянку транспортних засобів.","ru":"Стоянку транспортных средств."}],"c":2,"e":{"uk":"Це знак {s:3.35} «Стоянку заборонено»: забороняється стоянка всіх транспортних засобів, а зупинка дозволена ({p:33.3}).","ru":"Это знак {s:3.35} «Стоянка запрещена»: запрещается стоянка всех транспортных средств, а остановка разрешена ({p:33.3})."},"ref":["33.3"],"pic":["img/hsc/33-53-1.jpg"]},{"id":"h33-54","t":"h33","num":"33.54","q":{"uk":"Який з автомобілів поставлено на стоянку в населеному пункті з порушенням Правил дорожнього руху в зображеній ситуації?","ru":"Какой из автомобилей поставлен на стоянку в населённом пункте с нарушением Правил дорожного движения в изображённой ситуации?"},"a":[{"uk":"Червоний автомобіль.","ru":"Красный автомобиль.","w":{"uk":"Червоний автомобіль має розпізнавальний знак «Водій з інвалідністю», а табличка {s:7.18} звільняє такі автомобілі від дії знака {s:3.34}.","ru":"Красный автомобиль имеет опознавательный знак «Водитель с инвалидностью», а табличка {s:7.18} освобождает такие автомобили от действия знака {s:3.34}."}},{"uk":"Чорний автомобіль.","ru":"Чёрный автомобиль.","w":{"uk":"Знак {s:3.34} діє лише на тому боці дороги, де його встановлено ({p:33.3}), а стоянка на лівому боці такої дороги в населеному пункті дозволена.","ru":"Знак {s:3.34} действует только на той стороне дороги, где он установлен ({p:33.3}), а стоянка на левой стороне такой дороги в населённом пункте разрешена."}},{"uk":"Обидва поставлені правильно.","ru":"Оба поставлены правильно."}],"c":2,"e":{"uk":"Табличка {s:7.18} «Крім осіб з інвалідністю» знімає дію знака {s:3.34} з автомобілів із розпізнавальним знаком «Водій з інвалідністю» ({p:33.7}), тож червоний автомобіль стоїть правильно. Чорний стоїть на лівому боці, на який знак не поширюється, а в населеному пункті на дорозі з однією смугою в кожному напрямку стоянка зліва дозволена ({p:15.3}).","ru":"Табличка {s:7.18} «Кроме лиц с инвалидностью» снимает действие знака {s:3.34} с автомобилей с опознавательным знаком «Водитель с инвалидностью» ({p:33.7}), поэтому красный автомобиль стоит правильно. Чёрный стоит на левой стороне, на которую знак не распространяется, а в населённом пункте на дороге с одной полосой в каждом направлении стоянка слева разрешена ({p:15.3})."},"ref":["33.3","33.7","15.3"],"pic":["img/hsc/33-54-1.jpg"]},{"id":"h33-55","t":"h33","num":"33.55","q":{"uk":"З якою дорожньою розміткою може застосовуватися дорожній знак «Зупинка заборонена»?","ru":"С какой дорожной разметкой может применяться дорожный знак «Остановка запрещена»?"},"a":[{"uk":"З жовтою переривчастою лінією розмітки, яка наноситься біля краю проїзної частини або по верху бордюру.","ru":"С жёлтой прерывистой линией разметки, которая наносится у края проезжей части или по верху бордюра.","w":{"uk":"Жовта переривчаста лінія {m:1.10.1} позначає заборону стоянки й застосовується зі знаком {s:3.35}.","ru":"Жёлтая прерывистая линия {m:1.10.1} обозначает запрет стоянки и применяется со знаком {s:3.35}."}},{"uk":"З жовтою суцільною лінією розмітки, яка наноситься біля краю проїзної частини або по верху бордюру.","ru":"С жёлтой сплошной линией разметки, которая наносится у края проезжей части или по верху бордюра."},{"uk":"З білою переривчастою лінією розмітки, яка наноситься біля краю проїзної частини або по верху бордюру.","ru":"С белой прерывистой линией разметки, которая наносится у края проезжей части или по верху бордюра.","w":{"uk":"Біла переривчаста лінія не позначає заборони зупинки: лінії, що забороняють зупинку чи стоянку, жовті.","ru":"Белая прерывистая линия не обозначает запрета остановки: линии, запрещающие остановку или стоянку, жёлтые."}},{"uk":"З білою суцільною лінією розмітки, яка наноситься біля краю проїзної частини або по верху бордюру.","ru":"С белой сплошной линией разметки, которая наносится у края проезжей части или по верху бордюра.","w":{"uk":"Біла суцільна лінія біля краю ({m:1.2}) позначає край проїзної частини, а не заборону зупинки.","ru":"Белая сплошная линия у края ({m:1.2}) обозначает край проезжей части, а не запрет остановки."}}],"c":1,"e":{"uk":"Знак {s:3.34} може застосовуватися разом із розміткою {m:1.4} — жовтою суцільною лінією біля краю проїзної частини або по верху бордюру ({p:33.3}, {p:34.1}).","ru":"Знак {s:3.34} может применяться вместе с разметкой {m:1.4} — жёлтой сплошной линией у края проезжей части или по верху бордюра ({p:33.3}, {p:34.1})."},"ref":["33.3","34.1"],"pic":["img/hsc/33-55-1.jpg"]},{"id":"h33-56","t":"h33","num":"33.56","q":{"uk":"Який з автомобілів поставлено на стоянку в населеному пункті з порушенням Правил дорожнього руху в зображеній ситуації?","ru":"Какой из автомобилей поставлен на стоянку в населённом пункте с нарушением Правил дорожного движения в изображённой ситуации?"},"a":[{"uk":"Зелений і жовтий.","ru":"Зелёный и жёлтый.","w":{"uk":"Зелений автомобіль стоїть на лівому боці дороги, на який дія знака не поширюється.","ru":"Зелёный автомобиль стоит на левой стороне дороги, на которую действие знака не распространяется."}},{"uk":"Чорний і жовтий.","ru":"Чёрный и жёлтый.","w":{"uk":"Чорний автомобіль стоїть перед знаком, тобто поза зоною його дії.","ru":"Чёрный автомобиль стоит перед знаком, то есть вне зоны его действия."}},{"uk":"Жовтий.","ru":"Жёлтый."},{"uk":"Зелений.","ru":"Зелёный.","w":{"uk":"Зелений автомобіль на лівому боці стоїть правильно, а порушник — жовтий, що стоїть у зоні дії знака.","ru":"Зелёный автомобиль на левой стороне стоит правильно, а нарушитель — жёлтый, стоящий в зоне действия знака."}}],"c":2,"e":{"uk":"Знак {s:3.34} з табличкою {s:7.2.2} забороняє зупинку і стоянку на 200 м за знаком лише на правому боці дороги ({p:33.3}, {p:33.7}). Жовтий автомобіль стоїть саме в цій зоні, чорний — перед знаком, а зелений — на лівому боці, де стоянка в населеному пункті дозволена ({p:15.3}).","ru":"Знак {s:3.34} с табличкой {s:7.2.2} запрещает остановку и стоянку на 200 м за знаком только на правой стороне дороги ({p:33.3}, {p:33.7}). Жёлтый автомобиль стоит именно в этой зоне, чёрный — перед знаком, а зелёный — на левой стороне, где стоянка в населённом пункте разрешена ({p:15.3})."},"ref":["33.3","33.7","15.3"],"pic":["img/hsc/33-56-1.jpg"]},{"id":"h33-57","t":"h33","num":"33.57","q":{"uk":"Який з автомобілів поставлено на стоянку в населеному пункті з порушенням Правил дорожнього руху в зображеній ситуації?","ru":"Какой из автомобилей поставлен на стоянку в населённом пункте с нарушением Правил дорожного движения в изображённой ситуации?"},"a":[{"uk":"Сірий і чорний.","ru":"Серый и чёрный.","w":{"uk":"Сірий автомобіль стоїть на лівому боці, а чорний — за знаком, де зона заборони вже закінчилася.","ru":"Серый автомобиль стоит на левой стороне, а чёрный — за знаком, где зона запрета уже закончилась."}},{"uk":"Чорний.","ru":"Чёрный.","w":{"uk":"Чорний автомобіль стоїть за знаком із табличкою {s:7.2.3}, тобто поза зоною заборони.","ru":"Чёрный автомобиль стоит за знаком с табличкой {s:7.2.3}, то есть вне зоны запрета."}},{"uk":"Червоний і жовтий.","ru":"Красный и жёлтый.","w":{"uk":"Жовтий автомобіль стоїть на лівому боці дороги, на який знак не поширюється.","ru":"Жёлтый автомобиль стоит на левой стороне дороги, на которую знак не распространяется."}},{"uk":"Червоний.","ru":"Красный."},{"uk":"Червоний, жовтий і сірий.","ru":"Красный, жёлтый и серый.","w":{"uk":"Жовтий і сірий автомобілі стоять на лівому боці, де знак {s:3.34} не діє.","ru":"Жёлтый и серый автомобили стоят на левой стороне, где знак {s:3.34} не действует."}}],"c":3,"e":{"uk":"Знак {s:3.34} з табличкою {s:7.2.3} позначає кінець зони заборони зупинки на правому боці ({p:33.7}): червоний автомобіль стоїть перед знаком, тобто ще в зоні заборони, а чорний — уже за нею. Жовтий і сірий стоять на лівому боці, де знак не діє, а стоянку в населеному пункті дозволено ({p:15.3}).","ru":"Знак {s:3.34} с табличкой {s:7.2.3} обозначает конец зоны запрета остановки на правой стороне ({p:33.7}): красный автомобиль стоит перед знаком, то есть ещё в зоне запрета, а чёрный — уже за ней. Жёлтый и серый стоят на левой стороне, где знак не действует, а стоянка в населённом пункте разрешена ({p:15.3})."},"ref":["33.3","33.7","15.3"],"pic":["img/hsc/33-57-1.jpg"]},{"id":"h33-58","t":"h33","num":"33.58","q":{"uk":"Який водій неправильно зупинив свій транспортний засіб на дорозі за межами населеного пункту?","ru":"Какой водитель неправильно остановил своё транспортное средство на дороге вне населённого пункта?"},"a":[{"uk":"Водій синього автомобіля.","ru":"Водитель синего автомобиля.","w":{"uk":"Порушник не лише синій: білий автомобіль зупинився на лівому боці дороги поза населеним пунктом.","ru":"Нарушитель не только синий: белый автомобиль остановился на левой стороне дороги вне населённого пункта."}},{"uk":"Водії білого і синього автомобілів.","ru":"Водители белого и синего автомобилей."},{"uk":"Водії синього і фіолетового автомобілів.","ru":"Водители синего и фиолетового автомобилей.","w":{"uk":"Фіолетовий автомобіль стоїть перед знаком, тобто поза зоною його дії.","ru":"Фиолетовый автомобиль стоит перед знаком, то есть вне зоны его действия."}},{"uk":"Водії білого і фіолетового автомобілів.","ru":"Водители белого и фиолетового автомобилей.","w":{"uk":"Фіолетовий автомобіль стоїть перед знаком правильно, а порушує ще й синій, що стоїть у зоні дії знака.","ru":"Фиолетовый автомобиль стоит перед знаком правильно, а нарушает ещё и синий, стоящий в зоне действия знака."}}],"c":1,"e":{"uk":"Синій автомобіль стоїть у зоні дії знака {s:3.34} з табличкою {s:7.2.2} (300 м за знаком), де зупинку заборонено ({p:33.3}). Білий стоїть на лівому боці дороги, а поза населеним пунктом зупинка зліва не дозволена: {p:15.3} допускає її лише в населених пунктах.","ru":"Синий автомобиль стоит в зоне действия знака {s:3.34} с табличкой {s:7.2.2} (300 м за знаком), где остановка запрещена ({p:33.3}). Белый стоит на левой стороне дороги, а вне населённого пункта остановка слева не разрешена: {p:15.3} допускает её только в населённых пунктах."},"ref":["33.3","33.7","15.3"],"pic":["img/hsc/33-58-1.jpg"]},{"id":"h33-59","t":"h33","num":"33.59","q":{"uk":"Водій якого автомобіля виконує стоянку з порушенням Правил дорожнього руху?","ru":"Водитель какого автомобиля выполняет стоянку с нарушением Правил дорожного движения?"},"a":[{"uk":"Водій білого автомобіля.","ru":"Водитель белого автомобиля.","w":{"uk":"Синій автомобіль теж стоїть у зоні дії знака {s:3.34}.","ru":"Синий автомобиль тоже стоит в зоне действия знака {s:3.34}."}},{"uk":"Водій синього автомобіля.","ru":"Водитель синего автомобиля.","w":{"uk":"Білий автомобіль теж порушує: без таблички {s:7.18} знак {s:3.34} поширюється і на водіїв з інвалідністю.","ru":"Белый автомобиль тоже нарушает: без таблички {s:7.18} знак {s:3.34} распространяется и на водителей с инвалидностью."}},{"uk":"Обидва водії.","ru":"Оба водителя."}],"c":2,"e":{"uk":"Обидва автомобілі стоять у зоні дії знака {s:3.34} з табличкою {s:7.2.2} (150 м). Розпізнавальний знак «Водій з інвалідністю» на білому автомобілі не допомагає: від дії знака {s:3.34} такі автомобілі звільняє лише табличка {s:7.18}, якої тут немає ({p:33.3}).","ru":"Оба автомобиля стоят в зоне действия знака {s:3.34} с табличкой {s:7.2.2} (150 м). Опознавательный знак «Водитель с инвалидностью» на белом автомобиле не помогает: от действия знака {s:3.34} такие автомобили освобождает только табличка {s:7.18}, которой здесь нет ({p:33.3})."},"ref":["33.3","33.7"],"pic":["img/hsc/33-59-1.jpg"]},{"id":"h33-60","t":"h33","num":"33.60","q":{"uk":"Який з автомобілів поставлено на стоянку в населеному пункті з порушенням Правил дорожнього руху в зображеній ситуації?","ru":"Какой из автомобилей поставлен на стоянку в населённом пункте с нарушением Правил дорожного движения в изображённой ситуации?"},"a":[{"uk":"Жовтий і зелений.","ru":"Жёлтый и зелёный."},{"uk":"Жовтий.","ru":"Жёлтый.","w":{"uk":"Зелений автомобіль теж стоїть у зоні дії знака на правому боці.","ru":"Зелёный автомобиль тоже стоит в зоне действия знака на правой стороне."}},{"uk":"Чорний і червоний.","ru":"Чёрный и красный.","w":{"uk":"Чорний і червоний стоять на лівому боці, де знак не діє.","ru":"Чёрный и красный стоят на левой стороне, где знак не действует."}},{"uk":"Усі автомобілі.","ru":"Все автомобили.","w":{"uk":"Чорний і червоний автомобілі на лівому боці стоять правильно.","ru":"Чёрный и красный автомобили на левой стороне стоят правильно."}}],"c":0,"e":{"uk":"Табличка {s:7.2.4} під знаком {s:3.34} інформує, що ви перебуваєте в зоні його дії ({p:33.7}), тож заборона діє на правому боці і перед знаком, і за ним — жовтий і зелений автомобілі стоять із порушенням. Чорний і червоний стоять на лівому боці, на який знак не поширюється ({p:33.3}), а стоянку зліва в населеному пункті тут дозволено ({p:15.3}).","ru":"Табличка {s:7.2.4} под знаком {s:3.34} информирует, что вы находитесь в зоне его действия ({p:33.7}), поэтому запрет действует на правой стороне и перед знаком, и за ним — жёлтый и зелёный автомобили стоят с нарушением. Чёрный и красный стоят на левой стороне, на которую знак не распространяется ({p:33.3}), а стоянка слева в населённом пункте здесь разрешена ({p:15.3})."},"ref":["33.3","33.7","15.3"],"pic":["img/hsc/33-60-1.jpg"]},{"id":"h33-61","t":"h33","num":"33.61","q":{"uk":"Який з автомобілів поставлено на стоянку в населеному пункті з порушенням Правил дорожнього руху в зображеній ситуації?","ru":"Какой из автомобилей поставлен на стоянку в населённом пункте с нарушением Правил дорожного движения в изображённой ситуации?"},"a":[{"uk":"Жовтий, чорний і сірий.","ru":"Жёлтый, чёрный и серый.","w":{"uk":"Жовтий і чорний автомобілі стоять перед знаками, тобто поза зоною їхньої дії.","ru":"Жёлтый и чёрный автомобили стоят перед знаками, то есть вне зоны их действия."}},{"uk":"Жовтий, червоний і сірий.","ru":"Жёлтый, красный и серый.","w":{"uk":"Жовтий автомобіль стоїть перед знаком, поза зоною його дії.","ru":"Жёлтый автомобиль стоит перед знаком, вне зоны его действия."}},{"uk":"Чорний і сірий.","ru":"Чёрный и серый.","w":{"uk":"Чорний автомобіль стоїть перед знаком, а порушує, крім сірого, ще й червоний.","ru":"Чёрный автомобиль стоит перед знаком, а нарушает, кроме серого, ещё и красный."}},{"uk":"Чорний, сірий і червоний.","ru":"Чёрный, серый и красный.","w":{"uk":"Чорний автомобіль стоїть перед знаком, тобто поза зоною заборони.","ru":"Чёрный автомобиль стоит перед знаком, то есть вне зоны запрета."}},{"uk":"Сірий і червоний.","ru":"Серый и красный."}],"c":4,"e":{"uk":"Знаки {s:3.34} з табличкою {s:7.2.2} (200 м) встановлено на обох боках дороги, і кожен діє на своєму боці від місця встановлення вперед ({p:33.3}, {p:33.7}). За знаками стоять сірий (ліворуч) і червоний (праворуч) автомобілі — вони порушують, а чорний і жовтий стоять перед знаками.","ru":"Знаки {s:3.34} с табличкой {s:7.2.2} (200 м) установлены на обеих сторонах дороги, и каждый действует на своей стороне от места установки вперёд ({p:33.3}, {p:33.7}). За знаками стоят серый (слева) и красный (справа) автомобили — они нарушают, а чёрный и жёлтый стоят перед знаками."},"ref":["33.3","33.7"],"pic":["img/hsc/33-61-1.jpg"]},{"id":"h33-62","t":"h33","num":"33.62","q":{"uk":"У якому із зазначених місць Ви можете зупинити свій транспортний засіб?","ru":"В каком из указанных мест вы можете остановить своё транспортное средство?"},"a":[{"uk":"У місці А або Б.","ru":"В месте А или Б.","w":{"uk":"Місце Б — у зоні дії знака {s:3.34}, зупинку там заборонено.","ru":"Место Б — в зоне действия знака {s:3.34}, остановка там запрещена."}},{"uk":"У місці А, В або Г.","ru":"В месте А, В или Г."},{"uk":"У місці В або Г.","ru":"В месте В или Г.","w":{"uk":"Місце А теж підходить: воно розташоване перед знаком.","ru":"Место А тоже подходит: оно расположено перед знаком."}},{"uk":"У місці А або Г.","ru":"В месте А или Г.","w":{"uk":"Місце В на лівому боці теж підходить: знак, установлений праворуч, на лівий бік не поширюється.","ru":"Место В на левой стороне тоже подходит: знак, установленный справа, на левую сторону не распространяется."}},{"uk":"У місці Б або В.","ru":"В месте Б или В.","w":{"uk":"У місці Б зупинку заборонено знаком {s:3.34} з табличкою {s:7.2.2}.","ru":"В месте Б остановка запрещена знаком {s:3.34} с табличкой {s:7.2.2}."}}],"c":1,"e":{"uk":"Знак {s:3.34} з табличкою {s:7.2.2} забороняє зупинку на 200 м за знаком лише на правому боці ({p:33.3}), тому в місці Б зупинятися не можна. Місце А — перед знаком, а на лівому боці (В, Г) знак не діє, і зупинка там у населеному пункті дозволена ({p:15.3}).","ru":"Знак {s:3.34} с табличкой {s:7.2.2} запрещает остановку на 200 м за знаком только на правой стороне ({p:33.3}), поэтому в месте Б останавливаться нельзя. Место А — перед знаком, а на левой стороне (В, Г) знак не действует, и остановка там в населённом пункте разрешена ({p:15.3})."},"ref":["33.3","33.7","15.3"],"pic":["img/hsc/33-62-1.jpg"]},{"id":"h33-63","t":"h33","num":"33.63","q":{"uk":"Дія якого із зображених дорожніх знаків поширюється тільки на той бік дороги, над яким він встановлений?","ru":"Действие какого из изображённых дорожных знаков распространяется только на ту сторону дороги, над которой он установлен?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Не лише знак 1 ({s:3.34}): так само діють і решта трьох знаків.","ru":"Не только знак 1 ({s:3.34}): так же действуют и остальные три знака."}},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Не лише знак 2 ({s:3.35}): так само діють і решта трьох знаків.","ru":"Не только знак 2 ({s:3.35}): так же действуют и остальные три знака."}},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Не лише знак 3 ({s:3.36}): так само діють і решта трьох знаків.","ru":"Не только знак 3 ({s:3.36}): так же действуют и остальные три знака."}},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Не лише знак 4 ({s:3.37}): так само діють і решта трьох знаків.","ru":"Не только знак 4 ({s:3.37}): так же действуют и остальные три знака."}},{"uk":"Усі перелічені вище знаки.","ru":"Все перечисленные выше знаки."}],"c":4,"e":{"uk":"На зображенні — знаки {s:3.34}, {s:3.35}, {s:3.36} і {s:3.37}; за {p:33.3} дія кожного з них поширюється лише на той бік дороги, на якому його встановлено.","ru":"На изображении — знаки {s:3.34}, {s:3.35}, {s:3.36} и {s:3.37}; согласно {p:33.3} действие каждого из них распространяется только на ту сторону дороги, на которой он установлен."},"ref":["33.3"],"pic":["img/hsc/33-63-1.jpg"]},{"id":"h33-64","t":"h33","num":"33.64","q":{"uk":"Зображений дорожній знак:","ru":"Изображённый дорожный знак:"},"a":[{"uk":"Забороняє стоянку всіх транспортних засобів на тому боці дороги, на якому він встановлений.","ru":"Запрещает стоянку всех транспортных средств на той стороне дороги, на которой он установлен.","w":{"uk":"Так діє знак {s:3.35}; знак {s:3.38} не забороняє стоянку, а обмежує її тривалість у всій зоні.","ru":"Так действует знак {s:3.35}; знак {s:3.38} не запрещает стоянку, а ограничивает её продолжительность во всей зоне."}},{"uk":"Не дозволяє зупинку всіх транспортних засобів на тому боці дороги, на якому він встановлений.","ru":"Не разрешает остановку всех транспортных средств на той стороне дороги, на которой он установлен.","w":{"uk":"Зупинку забороняє знак {s:3.34}, а {s:3.38} стосується лише тривалості стоянки.","ru":"Остановку запрещает знак {s:3.34}, а {s:3.38} касается только продолжительности стоянки."}},{"uk":"Визначає територію в населеному пункті, на якій тривалість стоянки обмежена незалежно від того, чи справляється за це плата.","ru":"Определяет территорию в населённом пункте, на которой продолжительность стоянки ограничена независимо от того, взимается ли за это плата."},{"uk":"Визначає територію в населеному пункті, на якій заборонено зупинку всіх транспортних засобів.","ru":"Определяет территорию в населённом пункте, на которой запрещена остановка всех транспортных средств.","w":{"uk":"Знак {s:3.38} не забороняє зупинку, а лише обмежує тривалість стоянки.","ru":"Знак {s:3.38} не запрещает остановку, а лишь ограничивает продолжительность стоянки."}}],"c":2,"e":{"uk":"Це знак {s:3.38} «Зона обмеженої стоянки»: він визначає територію в населеному пункті, на якій тривалість стоянки обмежена незалежно від того, чи справляється за це плата, і діє на всю позначену зону ({p:33.3}).","ru":"Это знак {s:3.38} «Зона ограниченной стоянки»: он определяет территорию в населённом пункте, на которой продолжительность стоянки ограничена независимо от того, взимается ли за это плата, и действует на всю обозначенную зону ({p:33.3})."},"ref":["33.3"],"pic":["img/hsc/33-64-1.jpg"]},{"id":"h33-65","t":"h33","num":"33.65","q":{"uk":"У якому з напрямків дозволено рух автомобілю в зображеній ситуації?","ru":"В каком из направлений разрешено движение автомобилю в изображённой ситуации?"},"a":[{"uk":"Тільки праворуч.","ru":"Только направо."},{"uk":"Праворуч або на розворот.","ru":"Направо или на разворот.","w":{"uk":"Знак {s:4.2} розвороту не дозволяє — його дозволяють лише {s:4.3}, {s:4.5} і {s:4.6}.","ru":"Знак {s:4.2} разворота не разрешает — его разрешают только {s:4.3}, {s:4.5} и {s:4.6}."}},{"uk":"Ліворуч або на розворот.","ru":"Налево или на разворот.","w":{"uk":"Ні ліворуч, ні на розворот знак {s:4.2} рух не дозволяє.","ru":"Ни налево, ни на разворот знак {s:4.2} движение не разрешает."}},{"uk":"Праворуч або ліворуч.","ru":"Направо или налево.","w":{"uk":"Поворот ліворуч знак {s:4.2} забороняє.","ru":"Поворот налево знак {s:4.2} запрещает."}}],"c":0,"e":{"uk":"Під знаком {s:2.1} встановлено знак {s:4.2} «Рух праворуч»: рух дозволено лише праворуч ({p:33.4}), а розворот дозволяють тільки знаки {s:4.3}, {s:4.5} і {s:4.6}.","ru":"Под знаком {s:2.1} установлен знак {s:4.2} «Движение направо»: движение разрешено только направо ({p:33.4}), а разворот разрешают только знаки {s:4.3}, {s:4.5} и {s:4.6}."},"ref":["33.4"],"pic":["img/hsc/33-65-1.jpg"]},{"id":"h33-66","t":"h33","num":"33.66","q":{"uk":"У яких напрямках Вам дозволено рух у зображеній ситуації?","ru":"В каких направлениях вам разрешено движение в изображённой ситуации?"},"a":[{"uk":"Тільки ліворуч.","ru":"Только налево.","w":{"uk":"Знак {s:4.3} дозволяє не лише поворот ліворуч, а й розворот ({p:33.4}).","ru":"Знак {s:4.3} разрешает не только поворот налево, но и разворот ({p:33.4})."}},{"uk":"Ліворуч або на розворот.","ru":"Налево или на разворот."},{"uk":"Прямо або ліворуч.","ru":"Прямо или налево.","w":{"uk":"Рух прямо знак {s:4.3} не дозволяє — так діяв би знак {s:4.5}.","ru":"Движение прямо знак {s:4.3} не разрешает — так действовал бы знак {s:4.5}."}}],"c":1,"e":{"uk":"Знак {s:4.3} «Рух ліворуч» дозволяє рух ліворуч, а за {p:33.4} знаки {s:4.3}, {s:4.5} і {s:4.6} дозволяють також розворот.","ru":"Знак {s:4.3} «Движение налево» разрешает движение налево, а согласно {p:33.4} знаки {s:4.3}, {s:4.5} и {s:4.6} разрешают также разворот."},"ref":["33.4"],"pic":["img/hsc/33-66-1.jpg"]},{"id":"h33-67","t":"h33","num":"33.67","q":{"uk":"Зображений дорожній знак дозволяє рух:","ru":"Изображённый дорожный знак разрешает движение:"},"a":[{"uk":"Тільки ліворуч.","ru":"Только налево.","w":{"uk":"Знак {s:4.3} дозволяє не лише поворот ліворуч, а й розворот ({p:33.4}).","ru":"Знак {s:4.3} разрешает не только поворот налево, но и разворот ({p:33.4})."}},{"uk":"Ліворуч або на розворот.","ru":"Налево или на разворот."},{"uk":"Тільки на розворот.","ru":"Только на разворот.","w":{"uk":"Знак {s:4.3} дозволяє й поворот ліворуч, а не лише розворот.","ru":"Знак {s:4.3} разрешает и поворот налево, а не только разворот."}}],"c":1,"e":{"uk":"Це знак {s:4.3} «Рух ліворуч»: він дозволяє рух ліворуч, а також розворот ({p:33.4}).","ru":"Это знак {s:4.3} «Движение налево»: он разрешает движение налево, а также разворот ({p:33.4})."},"ref":["33.4"],"pic":["img/hsc/33-67-1.jpg"]},{"id":"h33-68","t":"h33","num":"33.68","q":{"uk":"У якому з напрямків Вам дозволено рух у зображеній ситуації?","ru":"В каком из направлений вам разрешено движение в изображённой ситуации?"},"a":[{"uk":"У напрямку А або Б.","ru":"В направлении А или Б.","w":{"uk":"Поворот ліворуч (В) і розворот (Г) на цьому перехресті не заборонено: знак стосується наступного перехрещення.","ru":"Поворот налево (В) и разворот (Г) на этом перекрёстке не запрещены: знак касается следующего пересечения."}},{"uk":"У напрямку А, Б або В.","ru":"В направлении А, Б или В.","w":{"uk":"Розворот (Г) теж дозволено: знак {s:4.4}, установлений за перехрестям, тут не діє.","ru":"Разворот (Г) тоже разрешён: знак {s:4.4}, установленный за перекрёстком, здесь не действует."}},{"uk":"У напрямку А, Б, В або Г.","ru":"В направлении А, Б, В или Г."},{"uk":"У напрямку Б, В або Г.","ru":"В направлении Б, В или Г.","w":{"uk":"Поворот праворуч (А) теж дозволено: знак на цьому перехресті не діє.","ru":"Поворот направо (А) тоже разрешён: знак на этом перекрёстке не действует."}}],"c":2,"e":{"uk":"Знак {s:4.4} «Рух прямо або праворуч» установлено за перехрестям, а дія знаків {s:4.1}–{s:4.6} поширюється лише на перехрещення проїзних частин, перед яким їх установлено ({p:33.4}). На цьому перехресті знак не діє, тож рух дозволено в будь-якому з напрямків.","ru":"Знак {s:4.4} «Движение прямо или направо» установлен за перекрёстком, а действие знаков {s:4.1}–{s:4.6} распространяется только на пересечение проезжих частей, перед которым они установлены ({p:33.4}). На этом перекрёстке знак не действует, поэтому движение разрешено в любом из направлений."},"ref":["33.4"],"pic":["img/hsc/33-68-1.jpg"]},{"id":"h33-69","t":"h33","num":"33.69","q":{"uk":"На які з перелічених транспортних засобів не поширюється дія зображеного дорожнього знака?","ru":"На какие из перечисленных транспортных средств не распространяется действие изображённого дорожного знака?"},"a":[{"uk":"На транспортні засоби осіб, які працюють або проживають у зоні, куди заборонено поворот.","ru":"На транспортные средства лиц, которые работают или проживают в зоне, куда запрещён поворот.","w":{"uk":"Пільга для тих, хто проживає чи працює в зоні, стосується знаків {s:3.1}–{s:3.8}, {s:3.11} і {s:4.11}, а не знаків напрямку руху {s:4.1}–{s:4.6}.","ru":"Льгота для тех, кто проживает или работает в зоне, касается знаков {s:3.1}–{s:3.8}, {s:3.11} и {s:4.11}, а не знаков направления движения {s:4.1}–{s:4.6}."}},{"uk":"На транспортні засоби, що рухаються з увімкненим проблисковим маячком оранжевого кольору.","ru":"На транспортные средства, движущиеся с включённым проблесковым маячком оранжевого цвета.","w":{"uk":"Оранжевий маячок переваги в русі не дає ({p:3.6}); відступати під час роботи від вимог знаків можуть лише машини дорожньо-експлуатаційної служби, а не всі транспортні засоби з таким маячком.","ru":"Оранжевый маячок преимущества в движении не даёт ({p:3.6}); отступать во время работы от требований знаков могут только машины дорожно-эксплуатационной службы, а не все транспортные средства с таким маячком."}},{"uk":"На маршрутні транспортні засоби, що рухаються за встановленим маршрутом.","ru":"На маршрутные транспортные средства, движущиеся по установленному маршруту."},{"uk":"На транспортні засоби, позначені розпізнавальним знаком «Водій з інвалідністю», якими керують водії з інвалідністю.","ru":"На транспортные средства, обозначенные опознавательным знаком «Водитель с инвалидностью», которыми управляют водители с инвалидностью.","w":{"uk":"Водіїв з інвалідністю звільнено від дії інших знаків ({s:3.1}, {s:3.2}, {s:3.35}–{s:3.38}), а не від знака {s:4.5}.","ru":"Водители с инвалидностью освобождены от действия других знаков ({s:3.1}, {s:3.2}, {s:3.35}–{s:3.38}), а не от знака {s:4.5}."}},{"uk":"Відповіді 1, 2, 3 і 4.","ru":"Ответы 1, 2, 3 и 4.","w":{"uk":"Із перелічених винятків для знака {s:4.5} Правила передбачають лише маршрутні транспортні засоби.","ru":"Из перечисленных исключений для знака {s:4.5} Правила предусматривают только маршрутные транспортные средства."}}],"c":2,"e":{"uk":"Це знак {s:4.5} «Рух прямо або ліворуч», а за {p:33.4} дія знаків {s:4.1}–{s:4.6} не поширюється на транспортні засоби, що рухаються за встановленими маршрутами.","ru":"Это знак {s:4.5} «Движение прямо или налево», а согласно {p:33.4} действие знаков {s:4.1}–{s:4.6} не распространяется на транспортные средства, движущиеся по установленным маршрутам."},"ref":["33.4","3.6"],"pic":["img/hsc/33-69-1.jpg"]},{"id":"h33-70","t":"h33","num":"33.70","q":{"uk":"Якому транспортному засобу дозволено рух прямо в зображеній ситуації?","ru":"Какому транспортному средству разрешено движение прямо в изображённой ситуации?"},"a":[{"uk":"Легковому автомобілю й автобусу, який рухається за встановленим маршрутом.","ru":"Легковому автомобилю и автобусу, который движется по установленному маршруту.","w":{"uk":"Легковий автомобіль повинен виконувати вимогу знака {s:4.6}, тож прямо йому їхати не можна.","ru":"Легковой автомобиль должен выполнять требование знака {s:4.6}, поэтому прямо ему ехать нельзя."}},{"uk":"Тільки автобусу, який рухається за встановленим маршрутом.","ru":"Только автобусу, который движется по установленному маршруту."},{"uk":"Нікому.","ru":"Никому.","w":{"uk":"Маршрутний автобус не зобов'язаний виконувати вимогу знака {s:4.6} і може їхати прямо.","ru":"Маршрутный автобус не обязан выполнять требование знака {s:4.6} и может ехать прямо."}}],"c":1,"e":{"uk":"Знак {s:4.6} «Рух праворуч або ліворуч» дозволяє рух лише в напрямках стрілок, але за {p:33.4} дія знаків {s:4.1}–{s:4.6} не поширюється на транспортні засоби, що рухаються за встановленими маршрутами. Тому прямо може їхати лише маршрутний автобус.","ru":"Знак {s:4.6} «Движение направо или налево» разрешает движение только в направлениях стрелок, но согласно {p:33.4} действие знаков {s:4.1}–{s:4.6} не распространяется на транспортные средства, движущиеся по установленным маршрутам. Поэтому прямо может ехать только маршрутный автобус."},"ref":["33.4"],"pic":["img/hsc/33-70-1.jpg"]},{"id":"h33-71","t":"h33","num":"33.71","q":{"uk":"У якому з напрямків дозволено рух легкового автомобіля в зображеній ситуації?","ru":"В каком из направлений разрешено движение легкового автомобиля в изображённой ситуации?"},"a":[{"uk":"У напрямках А і Б.","ru":"В направлениях А и Б.","w":{"uk":"Знак {s:4.6} дозволяє також розворот (В).","ru":"Знак {s:4.6} разрешает также разворот (В)."}},{"uk":"У напрямках А і В.","ru":"В направлениях А и В.","w":{"uk":"Поворот ліворуч (Б) знак {s:4.6} теж дозволяє.","ru":"Поворот налево (Б) знак {s:4.6} тоже разрешает."}},{"uk":"У напрямках Б і В.","ru":"В направлениях Б и В.","w":{"uk":"Поворот праворуч (А) знак {s:4.6} теж дозволяє.","ru":"Поворот направо (А) знак {s:4.6} тоже разрешает."}},{"uk":"У напрямках А, Б і В.","ru":"В направлениях А, Б и В."}],"c":3,"e":{"uk":"Знак {s:4.6} «Рух праворуч або ліворуч» дозволяє поворот праворуч (А) і ліворуч (Б), а за {p:33.4} — ще й розворот (В).","ru":"Знак {s:4.6} «Движение направо или налево» разрешает поворот направо (А) и налево (Б), а согласно {p:33.4} — ещё и разворот (В)."},"ref":["33.4"],"pic":["img/hsc/33-71-1.jpg"]},{"id":"h33-72","t":"h33","num":"33.72","q":{"uk":"Зображений дорожній знак має таке значення:","ru":"Изображённый дорожный знак имеет следующее значение:"},"a":[{"uk":"Дозволяє виконати поворот праворуч у зазначеному місці.","ru":"Разрешает выполнить поворот направо в указанном месте.","w":{"uk":"Знак {s:4.7} стосується об'їзду перешкоди, а не повороту; поворот праворуч задає знак {s:4.2}.","ru":"Знак {s:4.7} касается объезда препятствия, а не поворота; поворот направо задаёт знак {s:4.2}."}},{"uk":"Дозволяє повернути тільки праворуч.","ru":"Разрешает повернуть только направо.","w":{"uk":"Рух лише праворуч наказує знак {s:4.2} зі стрілкою, загнутою вправо; похила стрілка {s:4.7} вказує бік об'їзду перешкоди.","ru":"Движение только направо предписывает знак {s:4.2} со стрелкой, загнутой вправо; наклонная стрелка {s:4.7} указывает сторону объезда препятствия."}},{"uk":"Дозволяє об'їзд перешкоди тільки з правого боку.","ru":"Разрешает объезд препятствия только справа."}],"c":2,"e":{"uk":"Це знак {s:4.7} «Об'їзд перешкоди з правого боку»: об'їзд дозволено **лише** з боку, показаного стрілкою, тобто справа ({p:33.4}).","ru":"Это знак {s:4.7} «Объезд препятствия справа»: объезд разрешён **только** со стороны, указанной стрелкой, то есть справа ({p:33.4})."},"ref":["33.4"],"pic":["img/hsc/33-72-1.jpg"]},{"id":"h33-73","t":"h33","num":"33.73","q":{"uk":"На які з перелічених транспортних засобів не поширюється дія зображеного дорожнього знака?","ru":"На какие из перечисленных транспортных средств не распространяется действие изображённого дорожного знака?"},"a":[{"uk":"На транспортні засоби осіб, які працюють або проживають у зоні, куди заборонено поворот.","ru":"На транспортные средства лиц, которые работают или проживают в зоне, куда запрещён поворот.","w":{"uk":"Пільга для тих, хто проживає чи працює в зоні, стосується знаків {s:3.1}–{s:3.8}, {s:3.11} і {s:4.11}, а не знаків напрямку руху {s:4.1}–{s:4.6}.","ru":"Льгота для тех, кто проживает или работает в зоне, касается знаков {s:3.1}–{s:3.8}, {s:3.11} и {s:4.11}, а не знаков направления движения {s:4.1}–{s:4.6}."}},{"uk":"На транспортні засоби, що рухаються з увімкненим проблисковим маячком оранжевого кольору.","ru":"На транспортные средства, движущиеся с включённым проблесковым маячком оранжевого цвета.","w":{"uk":"Оранжевий маячок переваги в русі не дає ({p:3.6}); відступати під час роботи від вимог знаків можуть лише машини дорожньо-експлуатаційної служби, а не всі транспортні засоби з таким маячком.","ru":"Оранжевый маячок преимущества в движении не даёт ({p:3.6}); отступать во время работы от требований знаков могут только машины дорожно-эксплуатационной службы, а не все транспортные средства с таким маячком."}},{"uk":"На маршрутні транспортні засоби, що рухаються за встановленим маршрутом.","ru":"На маршрутные транспортные средства, движущиеся по установленному маршруту."},{"uk":"На транспортні засоби, позначені розпізнавальним знаком «Водій з інвалідністю», якими керують водії з інвалідністю.","ru":"На транспортные средства, обозначенные опознавательным знаком «Водитель с инвалидностью», которыми управляют водители с инвалидностью.","w":{"uk":"Водіїв з інвалідністю звільнено від дії інших знаків ({s:3.1}, {s:3.2}, {s:3.35}–{s:3.38}), а не від знака {s:4.1}.","ru":"Водители с инвалидностью освобождены от действия других знаков ({s:3.1}, {s:3.2}, {s:3.35}–{s:3.38}), а не от знака {s:4.1}."}},{"uk":"Відповіді 1, 2, 3 і 4.","ru":"Ответы 1, 2, 3 и 4.","w":{"uk":"Із перелічених винятків для знака {s:4.1} Правила передбачають лише маршрутні транспортні засоби.","ru":"Из перечисленных исключений для знака {s:4.1} Правила предусматривают только маршрутные транспортные средства."}}],"c":2,"e":{"uk":"Це знак {s:4.1} «Рух прямо», а за {p:33.4} дія знаків {s:4.1}–{s:4.6} не поширюється на транспортні засоби, що рухаються за встановленими маршрутами.","ru":"Это знак {s:4.1} «Движение прямо», а согласно {p:33.4} действие знаков {s:4.1}–{s:4.6} не распространяется на транспортные средства, движущиеся по установленным маршрутам."},"ref":["33.4","3.6"],"pic":["img/hsc/33-73-1.jpg"]},{"id":"h33-74","t":"h33","num":"33.74","q":{"uk":"У якому напрямку водієві зеленого автомобіля дозволено рух у зображеній ситуації?","ru":"В каком направлении водителю зелёного автомобиля разрешено движение в изображённой ситуации?"},"a":[{"uk":"У напрямку Б.","ru":"В направлении Б.","w":{"uk":"Поворот праворуч на прилеглу територію (А) знак {s:4.1} не забороняє.","ru":"Поворот направо на прилегающую территорию (А) знак {s:4.1} не запрещает."}},{"uk":"У напрямках А і Б.","ru":"В направлениях А и Б."},{"uk":"У напрямку Б, В або Г.","ru":"В направлении Б, В или Г.","w":{"uk":"Повороти ліворуч (В, Г) на цій ділянці знак {s:4.1} забороняє, а праворуч (А) — дозволяє.","ru":"Повороты налево (В, Г) на этом участке знак {s:4.1} запрещает, а направо (А) — разрешает."}},{"uk":"У напрямках В і Г.","ru":"В направлениях В и Г.","w":{"uk":"Повороти ліворуч (В і Г) заборонено знаком {s:4.1}.","ru":"Повороты налево (В и Г) запрещены знаком {s:4.1}."}}],"c":1,"e":{"uk":"Знак {s:4.1} «Рух прямо», установлений за перехрестям, діє на ділянці дороги до найближчого перехрестя і не забороняє поворот праворуч у двори та на інші прилеглі території ({p:33.4}). Тому можна рухатися прямо (Б) або праворуч (А), а повороти ліворуч (В, Г) заборонено.","ru":"Знак {s:4.1} «Движение прямо», установленный за перекрёстком, действует на участке дороги до ближайшего перекрёстка и не запрещает поворот направо во дворы и на другие прилегающие территории ({p:33.4}). Поэтому можно двигаться прямо (Б) или направо (А), а повороты налево (В, Г) запрещены."},"ref":["33.4"],"pic":["img/hsc/33-74-1.jpg"]},{"id":"h33-75","t":"h33","num":"33.75","q":{"uk":"Чи дозволено Вам виконати розворот у зображеній ситуації?","ru":"Разрешено ли вам выполнить разворот в изображённой ситуации?"},"a":[{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"Знак {s:4.1} розвороту не дозволяє: розворот дозволяють лише знаки {s:4.3}, {s:4.5} і {s:4.6}.","ru":"Знак {s:4.1} разворота не разрешает: разворот разрешают только знаки {s:4.3}, {s:4.5} и {s:4.6}."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":1,"e":{"uk":"Знаки {s:4.1} «Рух прямо» встановлено перед розривом розділювальної смуги — перехрещенням проїзних частин, на яке поширюється їхня дія ({p:33.4}). Тут дозволено рух лише прямо, тож розворот у розриві заборонено.","ru":"Знаки {s:4.1} «Движение прямо» установлены перед разрывом разделительной полосы — пересечением проезжих частей, на которое распространяется их действие ({p:33.4}). Здесь разрешено движение только прямо, поэтому разворот в разрыве запрещён."},"ref":["33.4"],"pic":["img/hsc/33-75-1.jpg"]},{"id":"h33-76","t":"h33","num":"33.76","q":{"uk":"Який із зображених дорожніх знаків позначає кінець зони обмеженої стоянки, початок якої позначено відповідним дорожнім знаком?","ru":"Какой из изображённых дорожных знаков обозначает конец зоны ограниченной стоянки, начало которой обозначено соответствующим дорожным знаком?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:3.36} «Стоянку заборонено в непарні числа місяця».","ru":"Знак 1 — {s:3.36} «Стоянка запрещена по нечётным числам месяца»."}},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:3.37} «Стоянку заборонено в парні числа місяця».","ru":"Знак 2 — {s:3.37} «Стоянка запрещена по чётным числам месяца»."}},{"uk":"Знак 3.","ru":"Знак 3."},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Знак 4 — {s:3.35} «Стоянку заборонено».","ru":"Знак 4 — {s:3.35} «Стоянка запрещена»."}}],"c":2,"e":{"uk":"Знак 3 — {s:3.39} «Кінець зони обмеженої стоянки»: перекреслений знак {s:3.38}; він завершує зону, позначену знаком {s:3.38} ({p:33.3}).","ru":"Знак 3 — {s:3.39} «Конец зоны ограниченной стоянки»: перечёркнутый знак {s:3.38}; он завершает зону, обозначенную знаком {s:3.38} ({p:33.3})."},"ref":["33.3"],"pic":["img/hsc/33-76-1.jpg"]},{"id":"h33-77","t":"h33","num":"33.77","q":{"uk":"Зображений дорожній знак встановлюється:","ru":"Изображённый дорожный знак устанавливается:"},"a":[{"uk":"Перед митними пунктами, біля яких зупинка не обов'язкова.","ru":"Перед таможенными пунктами, у которых остановка не обязательна.","w":{"uk":"Знак {s:3.40} якраз забороняє проїзд митниці без зупинки.","ru":"Знак {s:3.40} как раз запрещает проезд таможни без остановки."}},{"uk":"Перед митними пунктами, біля яких зупинка обов'язкова.","ru":"Перед таможенными пунктами, у которых остановка обязательна."},{"uk":"Перед контрольними пунктами пропуску, біля яких зупинка обов'язкова.","ru":"Перед контрольными пунктами пропуска, у которых остановка обязательна.","w":{"uk":"Проїзд без зупинки перед контрольними пунктами забороняє інший знак — {s:3.41} «Контроль».","ru":"Проезд без остановки перед контрольными пунктами запрещает другой знак — {s:3.41} «Контроль»."}}],"c":1,"e":{"uk":"Це знак {s:3.40} «Митниця»: забороняється проїзд без зупинки біля митниці ({p:33.3}), тобто зупинка тут обов'язкова.","ru":"Это знак {s:3.40} «Таможня»: запрещается проезд без остановки у таможни ({p:33.3}), то есть остановка здесь обязательна."},"ref":["33.3"],"pic":["img/hsc/33-77-1.jpg"]},{"id":"h33-78","t":"h33","num":"33.78","q":{"uk":"Який із зображених дорожніх знаків забороняє проїзд без обов'язкової зупинки перед контрольними пунктами?","ru":"Какой из изображённых дорожных знаков запрещает проезд без обязательной остановки перед контрольными пунктами?"},"a":[{"uk":"Знак 1.","ru":"Знак 1."},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — попереджувальний {s:1.28} «Залізничний переїзд без шлагбаума».","ru":"Знак 2 — предупреждающий {s:1.28} «Железнодорожный переезд без шлагбаума»."}},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Зображення 3 — лише напис «STOP» без знака; обов'язок зупинитися перед контрольним пунктом встановлює знак {s:3.41}.","ru":"Изображение 3 — лишь надпись «STOP» без знака; обязанность остановиться перед контрольным пунктом устанавливает знак {s:3.41}."}},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Знак 4 — {s:3.21} «В'їзд заборонено».","ru":"Знак 4 — {s:3.21} «Въезд запрещён»."}},{"uk":"Знак 5.","ru":"Знак 5.","w":{"uk":"Знак 5 — знак пріоритету {s:2.5} «Перевага зустрічного руху».","ru":"Знак 5 — знак приоритета {s:2.5} «Преимущество встречного движения»."}}],"c":0,"e":{"uk":"Знак 1 — {s:3.41} «Контроль»: забороняється проїзд без зупинки перед контрольними пунктами (дорожня станція патрульної поліції, карантинний пост, пункт оплати проїзду тощо) ({p:33.3}).","ru":"Знак 1 — {s:3.41} «Контроль»: запрещается проезд без остановки перед контрольными пунктами (дорожная станция патрульной полиции, карантинный пост, пункт оплаты проезда и т. п.) ({p:33.3})."},"ref":["33.3"],"pic":["img/hsc/33-78-1.jpg"]},{"id":"h33-79","t":"h33","num":"33.79","q":{"uk":"Як повинен вчинити водій, проїжджаючи місце, позначене зазначеним дорожнім знаком?","ru":"Как должен поступить водитель, проезжая место, обозначенное указанным дорожным знаком?"},"a":[{"uk":"Знизити швидкість і проїхати позначене місце без зупинки.","ru":"Снизить скорость и проехать обозначенное место без остановки.","w":{"uk":"Проїзд без зупинки якраз і заборонено знаком {s:3.41}.","ru":"Проезд без остановки как раз и запрещён знаком {s:3.41}."}},{"uk":"Знизити швидкість і проїхати позначене місце, зупинившись тільки на вимогу регулювальника.","ru":"Снизить скорость и проехать обозначенное место, остановившись только по требованию регулировщика.","w":{"uk":"Зупинка обов'язкова незалежно від вимоги регулювальника.","ru":"Остановка обязательна независимо от требования регулировщика."}},{"uk":"Обов'язково зупинитися перед позначеним місцем.","ru":"Обязательно остановиться перед обозначенным местом."}],"c":2,"e":{"uk":"Це знак {s:3.41} «Контроль»: він забороняє проїзд без зупинки перед контрольним пунктом (дорожня станція патрульної поліції, карантинний пост, пункт оплати проїзду тощо) ({p:33.3}), тому водій повинен обов'язково зупинитися.","ru":"Это знак {s:3.41} «Контроль»: он запрещает проезд без остановки перед контрольным пунктом (дорожная станция патрульной полиции, карантинный пост, пункт оплаты проезда и т. п.) ({p:33.3}), поэтому водитель должен обязательно остановиться."},"ref":["33.3"],"pic":["img/hsc/33-79-1.jpg"]},{"id":"h33-80","t":"h33","num":"33.80","q":{"uk":"Зображений дорожній знак позначає:","ru":"Изображённый дорожный знак обозначает:"},"a":[{"uk":"Кінець дії всіх раніше встановлених дорожніх знаків.","ru":"Конец действия всех ранее установленных дорожных знаков.","w":{"uk":"Знак не скасовує всіх знаків: попереджувальні, наказові, інформаційні знаки й частина заборонних і далі діють.","ru":"Знак не отменяет всех знаков: предупреждающие, предписывающие, информационные знаки и часть запрещающих продолжают действовать."}},{"uk":"Кінець дії всіх заборон і обмежень, запроваджених Правилами дорожнього руху.","ru":"Конец действия всех запрещений и ограничений, введённых Правилами дорожного движения.","w":{"uk":"Вимог самих Правил (наприклад, загальних обмежень швидкості) знак {s:3.42} не скасовує.","ru":"Требований самих Правил (например, общих ограничений скорости) знак {s:3.42} не отменяет."}},{"uk":"Кінець дії всіх заборон і обмежень, запроваджених деякими заборонними дорожніми знаками.","ru":"Конец действия всех запрещений и ограничений, введённых некоторыми запрещающими дорожными знаками."}],"c":2,"e":{"uk":"Знак {s:3.42} «Кінець усіх заборон і обмежень» одночасно скасовує заборони й обмеження, запроваджені лише певними заборонними знаками ({s:3.20}, {s:3.25}, {s:3.27}, {s:3.29}, {s:3.31}, {s:3.33}–{s:3.38}, {s:3.44}, {s:3.45}) ({p:33.3}).","ru":"Знак {s:3.42} «Конец всех запрещений и ограничений» одновременно отменяет запрещения и ограничения, введённые лишь определёнными запрещающими знаками ({s:3.20}, {s:3.25}, {s:3.27}, {s:3.29}, {s:3.31}, {s:3.33}–{s:3.38}, {s:3.44}, {s:3.45}) ({p:33.3})."},"ref":["33.3"],"pic":["img/hsc/33-80-1.jpg"]},{"id":"h33-81","t":"h33","num":"33.81","q":{"uk":"Чи дозволено рух водієві в зону дії даного дорожнього знака, якщо водій там проживає або обслуговує підприємства, які розташовані в цій зоні?","ru":"Разрешено ли водителю движение в зону действия данного дорожного знака, если водитель там проживает или обслуживает предприятия, которые расположены в этой зоне?"},"a":[{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"Знак {s:3.43} не має винятків: він забороняє рух усім, зокрема й мешканцям та працівникам зони.","ru":"Знак {s:3.43} не имеет исключений: он запрещает движение всем, в том числе жителям и работникам зоны."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":1,"e":{"uk":"Це знак {s:3.43} «Небезпека»: він забороняє рух **усіх без винятку** користувачів доріг через ДТП, аварію, стихійне лихо чи іншу небезпеку ({p:33.3}). Пільга для тих, хто проживає чи працює в зоні, передбачена лише для знаків {s:3.1}–{s:3.8} і {s:3.11}, тож рух заборонено.","ru":"Это знак {s:3.43} «Опасность»: он запрещает движение **всех без исключения** пользователей дорог из-за ДТП, аварии, стихийного бедствия или другой опасности ({p:33.3}). Льгота для тех, кто проживает или работает в зоне, предусмотрена только для знаков {s:3.1}–{s:3.8} и {s:3.11}, поэтому движение запрещено."},"ref":["33.3"],"pic":["img/hsc/33-81-1.jpg"]},{"id":"h33-82","t":"h33","num":"33.82","q":{"uk":"Чи дозволено Вам повернути ліворуч у зображеній ситуації на перехресті?","ru":"Разрешено ли вам повернуть налево в изображённой ситуации на перекрёстке?"},"a":[{"uk":"Заборонено.","ru":"Запрещено.","w":{"uk":"Знак {s:4.1} діє лише на перше перехрещення проїзних частин, тож поворот у другий проїзд дозволено.","ru":"Знак {s:4.1} действует только на первое пересечение проезжих частей, поэтому поворот во второй проезд разрешён."}},{"uk":"Дозволено в будь-який із проїздів.","ru":"Разрешено в любой из проездов.","w":{"uk":"У перший проїзд повертати ліворуч заборонено знаком {s:4.1}.","ru":"В первый проезд поворачивать налево запрещено знаком {s:4.1}."}},{"uk":"Дозволено тільки в перший проїзд.","ru":"Разрешено только в первый проезд.","w":{"uk":"Саме на перше перехрещення проїзних частин поширюється дія знака {s:4.1}, тому поворот у перший проїзд заборонено.","ru":"Именно на первое пересечение проезжих частей распространяется действие знака {s:4.1}, поэтому поворот в первый проезд запрещён."}},{"uk":"Дозволено тільки в другий проїзд.","ru":"Разрешено только во второй проезд."}],"c":3,"e":{"uk":"Знак {s:4.1} «Рух прямо» діє лише на те перехрещення проїзних частин, перед яким його встановлено ({p:33.4}), — тут на перехрещення з першою проїзною частиною дороги з розділювальною смугою. На перехрещення з другою проїзною частиною його дія не поширюється, тому ліворуч можна повернути лише в другий проїзд.","ru":"Знак {s:4.1} «Движение прямо» действует только на то пересечение проезжих частей, перед которым он установлен ({p:33.4}), — здесь на пересечение с первой проезжей частью дороги с разделительной полосой. На пересечение со второй проезжей частью его действие не распространяется, поэтому налево можно повернуть только во второй проезд."},"ref":["33.4"],"pic":["img/hsc/33-82-1.jpg"]},{"id":"h33-83","t":"h33","num":"33.83","q":{"uk":"У якому напрямку Вам дозволено рух у зображеній ситуації?","ru":"В каком направлении вам разрешено движение в изображённой ситуации?"},"a":[{"uk":"Прямо або праворуч.","ru":"Прямо или направо.","w":{"uk":"Поворот праворуч на перехресті знак {s:4.1} забороняє; виняток для повороту праворуч у двори стосується лише знака, установленого за перехрестям або на початку дороги.","ru":"Поворот направо на перекрёстке знак {s:4.1} запрещает; исключение для поворота направо во дворы касается только знака, установленного за перекрёстком или в начале дороги."}},{"uk":"Тільки прямо.","ru":"Только прямо."}],"c":1,"e":{"uk":"Знак {s:4.1} «Рух прямо», установлений перед перехрестям, дозволяє на ньому рух лише прямо ({p:33.4}).","ru":"Знак {s:4.1} «Движение прямо», установленный перед перекрёстком, разрешает на нём движение только прямо ({p:33.4})."},"ref":["33.4"],"pic":["img/hsc/33-83-1.jpg"]},{"id":"h33-84","t":"h33","num":"33.84","q":{"uk":"Як Ви повинні вчинити в зображеній ситуації?","ru":"Как вы должны поступить в изображённой ситуации?"},"a":[{"uk":"Продовжити рух прямо, не змінюючи смуги руху.","ru":"Продолжить движение прямо, не меняя полосы движения.","w":{"uk":"Ліву смугу перекрито, а знак {s:4.7} вимагає об'їжджати перешкоду справа.","ru":"Левая полоса перекрыта, а знак {s:4.7} требует объезжать препятствие справа."}},{"uk":"Перестроїтися на праву смугу.","ru":"Перестроиться на правую полосу."},{"uk":"Перестроїтися на праву смугу лише в тому разі, якщо є перешкода.","ru":"Перестроиться на правую полосу лишь в том случае, если есть препятствие.","w":{"uk":"Перешкода вже є — смугу перекрито через дорожні роботи, тож перестроїтися потрібно.","ru":"Препятствие уже есть — полоса перекрыта из-за дорожных работ, поэтому перестроиться нужно."}}],"c":1,"e":{"uk":"Перед місцем дорожніх робіт ({s:1.37}) встановлено знак {s:4.7} «Об'їзд перешкоди з правого боку»: об'їзд дозволено лише справа ({p:33.4}), тому слід перестроїтися на праву смугу.","ru":"Перед местом дорожных работ ({s:1.37}) установлен знак {s:4.7} «Объезд препятствия справа»: объезд разрешён только справа ({p:33.4}), поэтому следует перестроиться на правую полосу."},"ref":["33.4"],"pic":["img/hsc/33-84-1.jpg"]},{"id":"h33-85","t":"h33","num":"33.85","q":{"uk":"Який із зображених дорожніх знаків інформує про напрямок руху до зазначених на ньому пам'яток?","ru":"Какой из изображённых дорожных знаков информирует о направлении движения к указанным на нём достопримечательностям?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:5.59} на синьому фоні: він показує напрямок до населеного пункту, а не до визначного місця.","ru":"Знак 1 — {s:5.59} на синем фоне: он показывает направление к населённому пункту, а не к достопримечательности."}},{"uk":"Знак 2.","ru":"Знак 2."},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — покажчик напрямків до населених пунктів (Харків, Суми) з номерами доріг.","ru":"Знак 3 — указатель направлений к населённым пунктам (Харьков, Сумы) с номерами дорог."}},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Знак 4 — {s:5.53} «Початок забудови населеного пункту».","ru":"Знак 4 — {s:5.53} «Начало застройки населённого пункта»."}}],"c":1,"e":{"uk":"Знак 2 — {s:5.59} «Покажчик напрямку» на коричневому фоні: за {p:33.5} такий знак інформує про напрямок руху до визначних місць.","ru":"Знак 2 — {s:5.59} «Указатель направления» на коричневом фоне: согласно {p:33.5} такой знак информирует о направлении движения к достопримечательностям."},"ref":["33.5"],"pic":["img/hsc/33-85-1.jpg"]},{"id":"h33-86","t":"h33","num":"33.86","q":{"uk":"Зображена табличка вказує:","ru":"Изображённая табличка указывает:"},"a":[{"uk":"Відстань до небезпечної ділянки або визначеного об'єкта.","ru":"Расстояние до опасного участка или определённого объекта.","w":{"uk":"Відстань до небезпечної ділянки чи об'єкта показує табличка {s:7.1.1} «Відстань до об'єкта».","ru":"Расстояние до опасного участка или объекта показывает табличка {s:7.1.1} «Расстояние до объекта»."}},{"uk":"Відстань до місця запровадження відповідного обмеження.","ru":"Расстояние до места введения соответствующего ограничения.","w":{"uk":"Відстань до місця запровадження обмеження теж показує табличка {s:7.1.1}, а не {s:7.2.1}.","ru":"Расстояние до места введения ограничения тоже показывает табличка {s:7.1.1}, а не {s:7.2.1}."}},{"uk":"Протяжність небезпечної ділянки або зону дії заборонних та інформаційно-вказівних знаків.","ru":"Протяжённость опасного участка или зону действия запрещающих и информационно-указательных знаков."},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2.","w":{"uk":"Обидва ці значення належать табличці {s:7.1.1}, а не зображеній.","ru":"Оба эти значения относятся к табличке {s:7.1.1}, а не к изображённой."}}],"c":2,"e":{"uk":"Це табличка {s:7.2.1} «Зона дії»: вона позначає протяжність небезпечної ділянки, позначеної попереджувальними знаками, або зону дії заборонних та інформаційно-вказівних знаків ({p:33.7}).","ru":"Это табличка {s:7.2.1} «Зона действия»: она обозначает протяжённость опасного участка, обозначенного предупреждающими знаками, или зону действия запрещающих и информационно-указательных знаков ({p:33.7})."},"ref":["33.7"],"pic":["img/hsc/33-86-1.jpg"]},{"id":"h33-87","t":"h33","num":"33.87","q":{"uk":"З яким дорожнім знаком встановлюється зображена табличка?","ru":"С каким дорожным знаком устанавливается изображённая табличка?"},"a":[{"uk":"Зі знаком 1.","ru":"Со знаком 1.","w":{"uk":"Не лише зі знаком 1 ({s:3.34}): табличку застосовують з усіма чотирма знаками.","ru":"Не только со знаком 1 ({s:3.34}): табличку применяют со всеми четырьмя знаками."}},{"uk":"Зі знаком 2.","ru":"Со знаком 2.","w":{"uk":"Не лише зі знаком 2 ({s:3.35}): табличку застосовують з усіма чотирма знаками.","ru":"Не только со знаком 2 ({s:3.35}): табличку применяют со всеми четырьмя знаками."}},{"uk":"Зі знаком 3.","ru":"Со знаком 3.","w":{"uk":"Не лише зі знаком 3 ({s:3.36}): табличку застосовують з усіма чотирма знаками.","ru":"Не только со знаком 3 ({s:3.36}): табличку применяют со всеми четырьмя знаками."}},{"uk":"Зі знаком 4.","ru":"Со знаком 4.","w":{"uk":"Не лише зі знаком 4 ({s:3.37}): табличку застосовують з усіма чотирма знаками.","ru":"Не только со знаком 4 ({s:3.37}): табличку применяют со всеми четырьмя знаками."}},{"uk":"З будь-яким із перелічених вище знаків.","ru":"С любым из перечисленных выше знаков."}],"c":4,"e":{"uk":"Табличка {s:7.2.2} «Зона дії» (стрілка вгору з відстанню) застосовується зі знаками {s:3.34}, {s:3.35}, {s:3.36} і {s:3.37} ({p:33.7}), тобто з усіма зображеними.","ru":"Табличка {s:7.2.2} «Зона действия» (стрелка вверх с расстоянием) применяется со знаками {s:3.34}, {s:3.35}, {s:3.36} и {s:3.37} ({p:33.7}), то есть со всеми изображёнными."},"ref":["33.7"],"pic":["img/hsc/33-87-1.jpg"]},{"id":"h33-88","t":"h33","num":"33.88","q":{"uk":"Зображена табличка вказує:","ru":"Изображённая табличка указывает:"},"a":[{"uk":"Напрямок дії дорожніх знаків, розташованих перед перехрестям.","ru":"Направление действия дорожных знаков, расположенных перед перекрёстком.","w":{"uk":"Відповідь неповна: табличка показує також напрямок руху до об'єктів біля дороги.","ru":"Ответ неполный: табличка показывает также направление движения к объектам у дороги."}},{"uk":"Напрямок руху до позначених об'єктів, що розташовані безпосередньо біля дороги.","ru":"Направление движения к обозначенным объектам, расположенным непосредственно у дороги.","w":{"uk":"Відповідь неповна: табличка показує також напрямок дії знаків, розташованих перед перехрестям.","ru":"Ответ неполный: табличка показывает также направление действия знаков, расположенных перед перекрёстком."}},{"uk":"Правильні обидві відповіді.","ru":"Правильны оба ответа."}],"c":2,"e":{"uk":"Це табличка {s:7.3.2} «Напрямок дії» (стрілка ліворуч): такі таблички зазначають напрямок дії знаків, розташованих безпосередньо перед перехрестям, або напрямок руху до позначених об'єктів, що розташовані безпосередньо біля дороги ({p:33.7}).","ru":"Это табличка {s:7.3.2} «Направление действия» (стрелка влево): такие таблички указывают направление действия знаков, расположенных непосредственно перед перекрёстком, или направление движения к обозначенным объектам, расположенным непосредственно у дороги ({p:33.7})."},"ref":["33.7"],"pic":["img/hsc/33-88-1.jpg"]},{"id":"h33-89","t":"h33","num":"33.89","q":{"uk":"Зображена табличка вказує:","ru":"Изображённая табличка указывает:"},"a":[{"uk":"Табличка до дорожнього знаку діє протягом суботніх, недільних і святкових днів.","ru":"Табличка к дорожному знаку действует в течение субботних, воскресных и праздничных дней."},{"uk":"Табличка до дорожнього знаку діє протягом робочих днів.","ru":"Табличка к дорожному знаку действует в течение рабочих дней.","w":{"uk":"Робочі дні позначає табличка {s:7.4.2} із символом схрещених молотків.","ru":"Рабочие дни обозначает табличка {s:7.4.2} с символом скрещённых молотков."}}],"c":0,"e":{"uk":"Це табличка {s:7.4.1} «Час дії» (червона зірочка): знак, з яким її встановлено, діє в суботні, недільні та святкові дні ({p:33.7}).","ru":"Это табличка {s:7.4.1} «Время действия» (красная звёздочка): знак, с которым она установлена, действует в субботние, воскресные и праздничные дни ({p:33.7})."},"ref":["33.7"],"pic":["img/hsc/33-89-1.jpg"]},{"id":"h33-90","t":"h33","num":"33.90","q":{"uk":"Встановлений з якою із зображених табличок дорожній знак діє в усі робочі дні?","ru":"Установленный с какой из изображённых табличек дорожный знак действует во все рабочие дни?"},"a":[{"uk":"З табличкою 1.","ru":"С табличкой 1.","w":{"uk":"Табличка 1 — {s:7.4.1}: знак діє в суботні, недільні та святкові дні.","ru":"Табличка 1 — {s:7.4.1}: знак действует в субботние, воскресные и праздничные дни."}},{"uk":"З табличкою 2.","ru":"С табличкой 2."},{"uk":"З табличкою 3.","ru":"С табличкой 3.","w":{"uk":"Табличка 3 зазначає лише час доби (8.00–17.30), а не робочі дні.","ru":"Табличка 3 указывает лишь время суток (8.00–17.30), а не рабочие дни."}},{"uk":"З табличкою 4.","ru":"С табличкой 4.","w":{"uk":"Табличка 4 обмежує дію знака лише днями з понеділка по середу.","ru":"Табличка 4 ограничивает действие знака лишь днями с понедельника по среду."}},{"uk":"З табличкою 5.","ru":"С табличкой 5.","w":{"uk":"Табличка 5 обмежує дію знака середою з 8.30 до 9.30.","ru":"Табличка 5 ограничивает действие знака средой с 8.30 до 9.30."}}],"c":1,"e":{"uk":"Табличка 2 — {s:7.4.2} «Час дії» із символом схрещених молотків: знак діє в робочі дні ({p:33.7}).","ru":"Табличка 2 — {s:7.4.2} «Время действия» с символом скрещённых молотков: знак действует в рабочие дни ({p:33.7})."},"ref":["33.7"],"pic":["img/hsc/33-90-1.jpg"]},{"id":"h33-91","t":"h33","num":"33.91","q":{"uk":"Дія зображеної таблички поширюється:","ru":"Действие изображённой таблички распространяется:"},"a":[{"uk":"На всі вантажні автомобілі.","ru":"На все грузовые автомобили.","w":{"uk":"На вантажівки з дозволеною максимальною масою до 3,5 т табличка {s:7.5.1} не поширюється.","ru":"На грузовики с разрешённой максимальной массой до 3,5 т табличка {s:7.5.1} не распространяется."}},{"uk":"На вантажні автомобілі, в тому числі з причепами, дозволеною максимальною масою до 3,5 т.","ru":"На грузовые автомобили, в том числе с прицепами, разрешённой максимальной массой до 3,5 т.","w":{"uk":"Навпаки: табличка стосується вантажівок масою понад 3,5 т, а легші вантажівки разом із легковими автомобілями охоплює табличка {s:7.5.3}.","ru":"Наоборот: табличка касается грузовиков массой свыше 3,5 т, а более лёгкие грузовики вместе с легковыми автомобилями охватывает табличка {s:7.5.3}."}},{"uk":"На вантажні автомобілі, в тому числі з причепами, дозволеною максимальною масою понад 3,5 т.","ru":"На грузовые автомобили, в том числе с прицепами, разрешённой максимальной массой свыше 3,5 т."},{"uk":"На вантажні автомобілі, що перевозять небезпечні вантажі.","ru":"На грузовые автомобили, перевозящие опасные грузы.","w":{"uk":"Транспортні засоби з небезпечними вантажами позначає табличка {s:7.5.8}.","ru":"Транспортные средства с опасными грузами обозначает табличка {s:7.5.8}."}}],"c":2,"e":{"uk":"Табличка {s:7.5.1} «Вид транспортного засобу» поширює дію знака на вантажні автомобілі (у тому числі з причепом) з дозволеною максимальною масою понад 3,5 т ({p:33.7}).","ru":"Табличка {s:7.5.1} «Вид транспортного средства» распространяет действие знака на грузовые автомобили (в том числе с прицепом) с разрешённой максимальной массой свыше 3,5 т ({p:33.7})."},"ref":["33.7"],"pic":["img/hsc/33-91-1.jpg"]},{"id":"h33-92","t":"h33","num":"33.92","q":{"uk":"У якому з напрямків дозволено рух водієві легкового автомобіля в зображеній ситуації?","ru":"В каком из направлений разрешено движение водителю легкового автомобиля в изображённой ситуации?"},"a":[{"uk":"У напрямку А або Б.","ru":"В направлении А или Б.","w":{"uk":"Рух прямо (В) легковому автомобілю теж дозволено: знак з табличкою {s:7.5.1} на нього не поширюється.","ru":"Движение прямо (В) легковому автомобилю тоже разрешено: знак с табличкой {s:7.5.1} на него не распространяется."}},{"uk":"У напрямку Б.","ru":"В направлении Б.","w":{"uk":"Розворот (А) і рух прямо (В) легковому автомобілю теж дозволено.","ru":"Разворот (А) и движение прямо (В) легковому автомобилю тоже разрешены."}},{"uk":"У напрямках А, Б і В.","ru":"В направлениях А, Б и В."},{"uk":"У напрямку Б або В.","ru":"В направлении Б или В.","w":{"uk":"Розворот (А) теж дозволено: вимога знака стосується лише вантажівок.","ru":"Разворот (А) тоже разрешён: требование знака касается только грузовиков."}}],"c":2,"e":{"uk":"Знак {s:4.3} «Рух ліворуч» з табличкою {s:7.5.1} діє лише на вантажні автомобілі з дозволеною максимальною масою понад 3,5 т ({p:33.7}), тож водій легкового автомобіля може рухатися в будь-якому з показаних напрямків.","ru":"Знак {s:4.3} «Движение налево» с табличкой {s:7.5.1} действует только на грузовые автомобили с разрешённой максимальной массой свыше 3,5 т ({p:33.7}), поэтому водитель легкового автомобиля может двигаться в любом из показанных направлений."},"ref":["33.4","33.7"],"pic":["img/hsc/33-92-1.jpg"]},{"id":"h33-93","t":"h33","num":"33.93","q":{"uk":"Дія зображеної таблички поширюється:","ru":"Действие изображённой таблички распространяется:"},"a":[{"uk":"На транспортні засоби з причепами.","ru":"На транспортные средства с прицепами."},{"uk":"На транспортні засоби, що виконують буксирування.","ru":"На транспортные средства, выполняющие буксировку.","w":{"uk":"Табличка показує вид транспортного засобу — з причепом, а буксирування нею не охоплюється.","ru":"Табличка показывает вид транспортного средства — с прицепом, а буксировка ею не охватывается."}},{"uk":"Правильні обидві відповіді.","ru":"Правильны оба ответа.","w":{"uk":"Правильна лише перша відповідь: табличка стосується транспортних засобів з причепами.","ru":"Верен только первый ответ: табличка касается транспортных средств с прицепами."}}],"c":0,"e":{"uk":"Табличка {s:7.5.2} «Вид транспортного засобу» із зображенням автомобіля з причепом поширює дію знака на транспортні засоби з причепами ({p:33.7}).","ru":"Табличка {s:7.5.2} «Вид транспортного средства» с изображением автомобиля с прицепом распространяет действие знака на транспортные средства с прицепами ({p:33.7})."},"ref":["33.7"],"pic":["img/hsc/33-93-1.jpg"]},{"id":"h33-94","t":"h33","num":"33.94","q":{"uk":"З яким дорожнім знаком встановлюється зображена табличка?","ru":"С каким дорожным знаком устанавливается изображённая табличка?"},"a":[{"uk":"Зі знаком 1.","ru":"Со знаком 1.","w":{"uk":"Табличку застосовують не лише зі знаком {s:2.2}, а й зі знаком {s:2.1}.","ru":"Табличку применяют не только со знаком {s:2.2}, но и со знаком {s:2.1}."}},{"uk":"Зі знаком 2.","ru":"Со знаком 2.","w":{"uk":"Табличку застосовують не лише зі знаком {s:2.1}, а й зі знаком {s:2.2}.","ru":"Табличку применяют не только со знаком {s:2.1}, но и со знаком {s:2.2}."}},{"uk":"Зі знаком 3.","ru":"Со знаком 3.","w":{"uk":"Знак 3 — {s:2.3} «Головна дорога», табличку {s:7.1.2} з ним не застосовують.","ru":"Знак 3 — {s:2.3} «Главная дорога», табличку {s:7.1.2} с ним не применяют."}},{"uk":"З знаками 1 і 2.","ru":"Со знаками 1 и 2."}],"c":3,"e":{"uk":"Табличку {s:7.1.2} («STOP» з відстанню) застосовують зі знаком {s:2.1} «Дати дорогу», а також зі знаком {s:2.2} «Проїзд без зупинки заборонено» ({p:33.7}) — тобто зі знаками 2 і 1.","ru":"Табличку {s:7.1.2} («STOP» с расстоянием) применяют со знаком {s:2.1} «Уступить дорогу», а также со знаком {s:2.2} «Проезд без остановки запрещён» ({p:33.7}) — то есть со знаками 2 и 1."},"ref":["33.7"],"pic":["img/hsc/33-94-1.jpg"]},{"id":"h33-95","t":"h33","num":"33.95","q":{"uk":"Зображена табличка позначає:","ru":"Изображённая табличка обозначает:"},"a":[{"uk":"Відстань до небезпечної ділянки або визначеного об'єкта.","ru":"Расстояние до опасного участка или определённого объекта.","w":{"uk":"Відповідь неповна: табличка показує також відстань до місця запровадження обмеження.","ru":"Ответ неполный: табличка показывает также расстояние до места введения ограничения."}},{"uk":"Відстань до місця запровадження відповідного обмеження.","ru":"Расстояние до места введения соответствующего ограничения.","w":{"uk":"Відповідь неповна: табличка показує також відстань до небезпечної ділянки чи об'єкта.","ru":"Ответ неполный: табличка показывает также расстояние до опасного участка или объекта."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2."},{"uk":"Протяжність небезпечної ділянки або зону дії заборонних та інформаційно-вказівних знаків.","ru":"Протяжённость опасного участка или зону действия запрещающих и информационно-указательных знаков.","w":{"uk":"Протяжність ділянки чи зону дії знаків позначає інша табличка — {s:7.2.1}.","ru":"Протяжённость участка или зону действия знаков обозначает другая табличка — {s:7.2.1}."}}],"c":2,"e":{"uk":"Це табличка {s:7.1.1} «Відстань до об'єкта»: вона позначає відстань від знака до початку небезпечної ділянки, місця запровадження відповідного обмеження або певного об'єкта попереду ({p:33.7}).","ru":"Это табличка {s:7.1.1} «Расстояние до объекта»: она обозначает расстояние от знака до начала опасного участка, места введения соответствующего ограничения или определённого объекта впереди ({p:33.7})."},"ref":["33.7"],"pic":["img/hsc/33-95-1.jpg"]},{"id":"h33-96","t":"h33","num":"33.96","q":{"uk":"Який із зображених дорожніх знаків інформує про наявність на дорозі обладнаного місця відпочинку?","ru":"Какой из изображённых дорожных знаков информирует о наличии на дороге оборудованного места отдыха?"},"a":[{"uk":"Знак 1.","ru":"Знак 1."},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:6.12} «Питна вода».","ru":"Знак 2 — {s:6.12} «Питьевая вода»."}},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — {s:6.9} «Пункт довідкової служби».","ru":"Знак 3 — {s:6.9} «Пункт справочной службы»."}},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Знак 4 — {s:6.8} «Телефон».","ru":"Знак 4 — {s:6.8} «Телефон»."}}],"c":0,"e":{"uk":"Знак 1 — знак сервісу {s:6.15} «Місце відпочинку» ({p:33.6}).","ru":"Знак 1 — знак сервиса {s:6.15} «Место отдыха» ({p:33.6})."},"ref":["33.6"],"pic":["img/hsc/33-96-1.jpg"]},{"id":"h33-97","t":"h33","num":"33.97","q":{"uk":"Зображений дорожній знак інформує:","ru":"Изображённый дорожный знак информирует:"},"a":[{"uk":"Про місце розташування залізничного вокзалу.","ru":"О месте расположения железнодорожного вокзала.","w":{"uk":"Відповідь неповна: знак позначає також пункт зупинки поїздів.","ru":"Ответ неполный: знак обозначает также пункт остановки поездов."}},{"uk":"Про місце розташування пункту зупинки поїздів.","ru":"О месте расположения пункта остановки поездов.","w":{"uk":"Відповідь неповна: знак позначає також залізничний вокзал.","ru":"Ответ неполный: знак обозначает также железнодорожный вокзал."}},{"uk":"Про місце розташування метро.","ru":"О месте расположения метро.","w":{"uk":"Метро цей знак не позначає — він стосується залізниці.","ru":"Метро этот знак не обозначает — он касается железной дороги."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2."}],"c":3,"e":{"uk":"Це знак {s:5.72} «Залізничний вокзал чи пункт зупинки поїздів» ({p:33.5}) — він позначає обидва ці об'єкти.","ru":"Это знак {s:5.72} «Железнодорожный вокзал или пункт остановки поездов» ({p:33.5}) — он обозначает оба этих объекта."},"ref":["33.5"],"pic":["img/hsc/33-97-1.jpg"]},{"id":"h33-98","t":"h33","num":"33.98","q":{"uk":"Зображений дорожній знак інформує:","ru":"Изображённый дорожный знак информирует:"},"a":[{"uk":"Про початок місця зупинки автобусів.","ru":"О начале места остановки автобусов.","w":{"uk":"Початок посадкового майданчика автобуса позначає знак {s:5.45.1} «Пункт зупинки автобуса».","ru":"Начало посадочной площадки автобуса обозначает знак {s:5.45.1} «Пункт остановки автобуса»."}},{"uk":"Про місце розташування автовокзалу або автостанції.","ru":"О месте расположения автовокзала или автостанции."},{"uk":"Обидві відповіді правильні.","ru":"Оба ответа правильны.","w":{"uk":"Правильна лише друга відповідь: зупинку автобуса позначає інший знак.","ru":"Верен только второй ответ: остановку автобуса обозначает другой знак."}}],"c":1,"e":{"uk":"Це знак {s:5.73} «Автовокзал чи автостанція»: його встановлюють безпосередньо біля автовокзалу (автостанції) або біля повороту до нього ({p:33.5}).","ru":"Это знак {s:5.73} «Автовокзал или автостанция»: его устанавливают непосредственно у автовокзала (автостанции) или у поворота к нему ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-98-1.jpg"]},{"id":"h33-99","t":"h33","num":"33.99","q":{"uk":"Зображений дорожній знак позначає:","ru":"Изображённый дорожный знак обозначает:"},"a":[{"uk":"Пункт технічного обслуговування.","ru":"Пункт технического обслуживания.","w":{"uk":"Пункт технічного обслуговування позначає знак {s:6.5} із гайковим ключем.","ru":"Пункт технического обслуживания обозначает знак {s:6.5} с гаечным ключом."}},{"uk":"Електрозарядні станції.","ru":"Электрозарядные станции."},{"uk":"Автозаправні та електрозарядні станції.","ru":"Автозаправочные и электрозарядные станции.","w":{"uk":"Автозаправні та електрозарядні станції разом позначають знаки {s:6.7.5}–{s:6.7.7} із символами кількох кольорів.","ru":"Автозаправочные и электрозарядные станции вместе обозначают знаки {s:6.7.5}–{s:6.7.7} с символами нескольких цветов."}}],"c":1,"e":{"uk":"Це знак {s:6.7.3} «Електрозарядні станції»: зарядка для електромобілів, символ на знаку зеленого кольору ({p:33.6}).","ru":"Это знак {s:6.7.3} «Электрозарядные станции»: зарядка для электромобилей, символ на знаке зелёного цвета ({p:33.6})."},"ref":["33.6"],"pic":["img/hsc/33-99-1.jpg"]},{"id":"h33-100","t":"h33","num":"33.100","q":{"uk":"Зображений дорожній знак позначає:","ru":"Изображённый дорожный знак обозначает:"},"a":[{"uk":"Пункт технічного обслуговування.","ru":"Пункт технического обслуживания.","w":{"uk":"Пункт технічного обслуговування позначає знак {s:6.5} із гайковим ключем.","ru":"Пункт технического обслуживания обозначает знак {s:6.5} с гаечным ключом."}},{"uk":"Електрозарядні станції.","ru":"Электрозарядные станции.","w":{"uk":"Лише електрозарядні станції позначає знак {s:6.7.3} з одним зеленим символом.","ru":"Только электрозарядные станции обозначает знак {s:6.7.3} с одним зелёным символом."}},{"uk":"Автозаправні та електрозарядні станції.","ru":"Автозаправочные и электрозарядные станции."}],"c":2,"e":{"uk":"Це знак {s:6.7.6} «Автозаправні та електрозарядні станції»: символи блакитного (газ) і зеленого (зарядка для електромобілів) кольорів означають, що тут є і заправка, і зарядка ({p:33.6}).","ru":"Это знак {s:6.7.6} «Автозаправочные и электрозарядные станции»: символы голубого (газ) и зелёного (зарядка для электромобилей) цветов означают, что здесь есть и заправка, и зарядка ({p:33.6})."},"ref":["33.6"],"pic":["img/hsc/33-100-1.jpg"]},{"id":"h33-101","t":"h33","num":"33.101","q":{"uk":"Зображений дорожній знак інформує:","ru":"Изображённый дорожный знак информирует:"},"a":[{"uk":"Про наближення до поста Національної поліції.","ru":"О приближении к посту Национальной полиции.","w":{"uk":"Дорожню станцію патрульної поліції позначає знак сервісу {s:6.10}.","ru":"Дорожную станцию патрульной полиции обозначает знак сервиса {s:6.10}."}},{"uk":"Про можливе здійснення контролю за порушенням Правил дорожнього руху за допомогою спеціальних технічних засобів.","ru":"О возможном осуществлении контроля за нарушением Правил дорожного движения с помощью специальных технических средств."},{"uk":"Про наближення до місця фіксації швидкості руху.","ru":"О приближении к месту фиксации скорости движения.","w":{"uk":"Знак стосується контролю за будь-якими порушеннями Правил, а не лише фіксації швидкості.","ru":"Знак касается контроля за любыми нарушениями Правил, а не только фиксации скорости."}}],"c":1,"e":{"uk":"Це знак {s:5.76} «Автоматична відеофіксація порушень Правил дорожнього руху»: він позначає ділянки доріг, де можливий контроль за порушенням Правил за допомогою спеціальних технічних та/або електронних засобів ({p:33.5}).","ru":"Это знак {s:5.76} «Автоматическая видеофиксация нарушений Правил дорожного движения»: он обозначает участки дорог, где возможен контроль за нарушением Правил с помощью специальных технических и/или электронных средств ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-101-1.jpg"]},{"id":"h33-102","t":"h33","num":"33.102","q":{"uk":"Зображений дорожній знак інформує:","ru":"Изображённый дорожный знак информирует:"},"a":[{"uk":"Про місце розташування телефону громадського користування.","ru":"О месте расположения телефона общего пользования.","w":{"uk":"Звичайний телефон позначає знак {s:6.8} «Телефон» — без напису SOS.","ru":"Обычный телефон обозначает знак {s:6.8} «Телефон» — без надписи SOS."}},{"uk":"Про місце розташування телефону для виклику аварійних служб.","ru":"О месте расположения телефона для вызова аварийных служб."},{"uk":"Про місце розташування відділення зв'язку.","ru":"О месте расположения отделения связи.","w":{"uk":"Знак позначає телефон для виклику аварійних служб, а не відділення зв'язку.","ru":"Знак обозначает телефон для вызова аварийных служб, а не отделение связи."}}],"c":1,"e":{"uk":"Це знак сервісу {s:6.3} «Телефон для виклику аварійної служби» — телефонна слухавка з написом SOS ({p:33.6}).","ru":"Это знак сервиса {s:6.3} «Телефон для вызова аварийной службы» — телефонная трубка с надписью SOS ({p:33.6})."},"ref":["33.6"],"pic":["img/hsc/33-102-1.jpg"]},{"id":"h33-103","t":"h33","num":"33.103","q":{"uk":"Зображений дорожній знак інформує:","ru":"Изображённый дорожный знак информирует:"},"a":[{"uk":"Про місце розташування газозаправної станції.","ru":"О месте расположения газозаправочной станции."},{"uk":"Про місце розташування спільної автозаправної станції.","ru":"О месте расположения совмещённой автозаправочной станции.","w":{"uk":"Станцію з кількома видами пального позначають символи кількох кольорів, а тут символ лише блакитний — газ.","ru":"Станцию с несколькими видами топлива обозначают символы нескольких цветов, а здесь символ только голубой — газ."}},{"uk":"Про місце розташування автозаправної станції одного виду пального.","ru":"О месте расположения автозаправочной станции одного вида топлива.","w":{"uk":"Колір символу вказує конкретний вид пального: блакитний означає газ, тож це саме газозаправна станція.","ru":"Цвет символа указывает конкретный вид топлива: голубой означает газ, поэтому это именно газозаправочная станция."}}],"c":0,"e":{"uk":"Це знак {s:6.7.2} «Автозаправні станції» із символом блакитного кольору: за {p:33.6} блакитний колір символу означає газ, тобто це газозаправна станція.","ru":"Это знак {s:6.7.2} «Автозаправочные станции» с символом голубого цвета: согласно {p:33.6} голубой цвет символа означает газ, то есть это газозаправочная станция."},"ref":["33.6"],"pic":["img/hsc/33-103-1.jpg"]},{"id":"h33-104","t":"h33","num":"33.104","q":{"uk":"Табличка до дорожнього знаку діє:","ru":"Табличка к дорожному знаку действует:"},"a":[{"uk":"Протягом суботніх, недільних і святкових днів.","ru":"В течение субботних, воскресных и праздничных дней."},{"uk":"Протягом робочих днів.","ru":"В течение рабочих дней.","w":{"uk":"Робочі дні позначає табличка {s:7.4.2} із символом схрещених молотків.","ru":"Рабочие дни обозначает табличка {s:7.4.2} с символом скрещённых молотков."}}],"c":0,"e":{"uk":"Це табличка {s:7.4.1} «Час дії» (червона зірочка): знак з нею діє в суботні, недільні та святкові дні ({p:33.7}).","ru":"Это табличка {s:7.4.1} «Время действия» (красная звёздочка): знак с ней действует в субботние, воскресные и праздничные дни ({p:33.7})."},"ref":["33.7"],"pic":["img/hsc/33-104-1.jpg"]},{"id":"h33-105","t":"h33","num":"33.105","q":{"uk":"Дія зображеної таблички поширюється:","ru":"Действие изображённой таблички распространяется:"},"a":[{"uk":"На всі вантажні автомобілі.","ru":"На все грузовые автомобили.","w":{"uk":"Табличка стосується не всіх вантажівок, а лише транспортних засобів з небезпечним вантажем.","ru":"Табличка касается не всех грузовиков, а только транспортных средств с опасным грузом."}},{"uk":"На вантажні автомобілі дозволеною максимальною масою понад 3,5 т.","ru":"На грузовые автомобили разрешённой максимальной массой свыше 3,5 т.","w":{"uk":"Вантажівки масою понад 3,5 т позначає табличка {s:7.5.1}.","ru":"Грузовики массой свыше 3,5 т обозначает табличка {s:7.5.1}."}},{"uk":"На вантажні автомобілі, що перевозять небезпечний вантаж.","ru":"На грузовые автомобили, перевозящие опасный груз.","w":{"uk":"Дія поширюється на всі транспортні засоби з небезпечним вантажем, а не лише на вантажні автомобілі.","ru":"Действие распространяется на все транспортные средства с опасным грузом, а не только на грузовые автомобили."}},{"uk":"На всі транспортні засоби, що перевозять небезпечний вантаж.","ru":"На все транспортные средства, перевозящие опасный груз."}],"c":3,"e":{"uk":"Табличка {s:7.5.8} поширює дію знака на транспортні засоби з розпізнавальним знаком «Табличка оранжевого кольору», що перевозять небезпечні вантажі ({p:33.7}), — незалежно від того, вантажівка це чи інший транспортний засіб.","ru":"Табличка {s:7.5.8} распространяет действие знака на транспортные средства с опознавательным знаком «Табличка оранжевого цвета», перевозящие опасные грузы ({p:33.7}), — независимо от того, грузовик это или другое транспортное средство."},"ref":["33.7"],"pic":["img/hsc/33-105-1.jpg"]},{"id":"h33-106","t":"h33","num":"33.106","q":{"uk":"Який транспортний засіб поставлено на стоянку неправильно?","ru":"Какое транспортное средство поставлено на стоянку неправильно?"},"a":[{"uk":"Вантажний автомобіль.","ru":"Грузовой автомобиль."},{"uk":"Усі правильно.","ru":"Все правильно.","w":{"uk":"Вантажний автомобіль не належить до транспортних засобів, яким табличка дозволяє такий спосіб стоянки.","ru":"Грузовой автомобиль не относится к транспортным средствам, которым табличка разрешает такой способ стоянки."}},{"uk":"Мотоцикл з боковим причепом.","ru":"Мотоцикл с боковым прицепом.","w":{"uk":"Мотоцикл з боковим причепом — це мотоцикл, а таблички {s:7.6.2}–{s:7.6.6} дозволяють такий спосіб стоянки легковим автомобілям і мотоциклам.","ru":"Мотоцикл с боковым прицепом — это мотоцикл, а таблички {s:7.6.2}–{s:7.6.6} разрешают такой способ стоянки легковым автомобилям и мотоциклам."}}],"c":0,"e":{"uk":"Під знаком {s:5.42.1} «Місце для стоянки» встановлено табличку зі способом поставлення з використанням тротуару, а такі таблички ({s:7.6.2}–{s:7.6.6}) визначають спосіб поставлення лише легкових автомобілів і мотоциклів ({p:33.7}). Тому вантажний автомобіль поставлено неправильно.","ru":"Под знаком {s:5.42.1} «Место стоянки» установлена табличка со способом постановки с использованием тротуара, а такие таблички ({s:7.6.2}–{s:7.6.6}) определяют способ постановки только легковых автомобилей и мотоциклов ({p:33.7}). Поэтому грузовой автомобиль поставлен неправильно."},"ref":["33.5","33.7"],"pic":["img/hsc/33-106-1.jpg"]},{"id":"h33-107","t":"h33","num":"33.107","q":{"uk":"Який із зображених дорожніх знаків забороняє в’їзд усіх транспортних засобів (крім транспортних засобів, що рухаються за встановленими маршрутами)?","ru":"Какой из изображённых дорожных знаков запрещает въезд всех транспортных средств (кроме транспортных средств, движущихся по установленным маршрутам)?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:3.41} «Контроль»: забороняє проїзд без зупинки, а не в'їзд.","ru":"Знак 1 — {s:3.41} «Контроль»: запрещает проезд без остановки, а не въезд."}},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — попереджувальний {s:1.28} «Залізничний переїзд без шлагбаума».","ru":"Знак 2 — предупреждающий {s:1.28} «Железнодорожный переезд без шлагбаума»."}},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Зображення 3 — лише напис «STOP», в'їзду він не забороняє.","ru":"Изображение 3 — лишь надпись «STOP», въезда она не запрещает."}},{"uk":"Знак 4.","ru":"Знак 4."},{"uk":"Знак 5.","ru":"Знак 5.","w":{"uk":"Знак 5 — знак пріоритету {s:2.5} «Перевага зустрічного руху»: він вимагає дати дорогу зустрічним, а не забороняє в'їзд.","ru":"Знак 5 — знак приоритета {s:2.5} «Преимущество встречного движения»: он требует уступить дорогу встречным, а не запрещает въезд."}}],"c":3,"e":{"uk":"Знак 4 — {s:3.21} «В'їзд заборонено»: він забороняє в'їзд усіх транспортних засобів, а на ті, що рухаються за встановленими маршрутами, його дія не поширюється ({p:33.3}).","ru":"Знак 4 — {s:3.21} «Въезд запрещён»: он запрещает въезд всех транспортных средств, а на движущиеся по установленным маршрутам его действие не распространяется ({p:33.3})."},"ref":["33.3"],"pic":["img/hsc/33-107-1.jpg"]},{"id":"h33-108","t":"h33","num":"33.108","q":{"uk":"Що спільного у цих двох дорожніх знаків?","ru":"Что общего у этих двух дорожных знаков?"},"a":[{"uk":"Застосовуються тільки як тимчасові знаки.","ru":"Применяются только как временные знаки.","w":{"uk":"Знак {s:1.33} «Діти» зазвичай встановлюють постійно біля дитячих закладів, тож лише тимчасовими ці знаки не є.","ru":"Знак {s:1.33} «Дети» обычно устанавливают постоянно у детских учреждений, поэтому только временными эти знаки не являются."}},{"uk":"Повторюються в населеному пункті при довгостроковій установці.","ru":"Повторяются в населённом пункте при долгосрочной установке."},{"uk":"Повинні встановлюватися з двох сторін проїжджої частини.","ru":"Должны устанавливаться с двух сторон проезжей части.","w":{"uk":"Обов'язкового встановлення з обох боків проїзної частини Правила для цих знаків не передбачають.","ru":"Обязательной установки с обеих сторон проезжей части Правила для этих знаков не предусматривают."}},{"uk":"Застосовуються тільки зі знаком обмеження швидкості.","ru":"Применяются только со знаком ограничения скорости.","w":{"uk":"Ці знаки застосовують самостійно, без обов'язкового знака обмеження швидкості.","ru":"Эти знаки применяют самостоятельно, без обязательного знака ограничения скорости."}}],"c":1,"e":{"uk":"Це знаки {s:1.33} «Діти» і {s:1.37} «Дорожні роботи»: за {p:33.1} саме їх, на відміну від інших попереджувальних знаків, повторюють і в населених пунктах (наступний знак — щонайменше за 50 м до початку небезпечної ділянки).","ru":"Это знаки {s:1.33} «Дети» и {s:1.37} «Дорожные работы»: согласно {p:33.1} именно их, в отличие от других предупреждающих знаков, повторяют и в населённых пунктах (следующий знак — не менее чем за 50 м до начала опасного участка)."},"ref":["33.1"],"pic":["img/hsc/33-108-1.jpg"]},{"id":"h33-109","t":"h33","num":"33.109","q":{"uk":"Що спільного у цих двох дорожніх знаків?","ru":"Что общего у этих двух дорожных знаков?"},"a":[{"uk":"Забороняють зупинку.","ru":"Запрещают остановку.","w":{"uk":"Зупинку забороняє лише знак {s:3.34}, а {s:3.35} її дозволяє.","ru":"Остановку запрещает только знак {s:3.34}, а {s:3.35} её разрешает."}},{"uk":"Забороняють поворот наліво.","ru":"Запрещают поворот налево.","w":{"uk":"Повороти ці знаки не регулюють.","ru":"Повороты эти знаки не регулируют."}},{"uk":"Забороняють рух прямо.","ru":"Запрещают движение прямо.","w":{"uk":"Рух ці знаки не забороняють — лише зупинку чи стоянку.","ru":"Движение эти знаки не запрещают — только остановку или стоянку."}},{"uk":"Забороняють стоянку.","ru":"Запрещают стоянку."}],"c":3,"e":{"uk":"Знак {s:3.34} «Зупинку заборонено» забороняє зупинку і стоянку, а {s:3.35} «Стоянку заборонено» — стоянку ({p:33.3}); отже, спільне в них — заборона стоянки.","ru":"Знак {s:3.34} «Остановка запрещена» запрещает остановку и стоянку, а {s:3.35} «Стоянка запрещена» — стоянку ({p:33.3}); значит, общее у них — запрет стоянки."},"ref":["33.3"],"pic":["img/hsc/33-109-1.jpg"]},{"id":"h33-110","t":"h33","num":"33.110","q":{"uk":"Що спільного у цих двох дорожніх знаків?","ru":"Что общего у этих двух дорожных знаков?"},"a":[{"uk":"Інформують про дорогу з одностороннім рухом.","ru":"Информируют о дороге с односторонним движением."},{"uk":"Інформують про дозволені напрямки руху.","ru":"Информируют о разрешённых направлениях движения.","w":{"uk":"Дозволені напрямки руху наказують знаки {s:4.1}–{s:4.6}, а ці інформаційні знаки стосуються одностороннього руху.","ru":"Разрешённые направления движения предписывают знаки {s:4.1}–{s:4.6}, а эти информационные знаки касаются одностороннего движения."}},{"uk":"Інформують про заборонені напрямки руху.","ru":"Информируют о запрещённых направлениях движения.","w":{"uk":"Заборонені напрямки встановлюють заборонні знаки {s:3.22}–{s:3.24}, а не ці.","ru":"Запрещённые направления устанавливают запрещающие знаки {s:3.22}–{s:3.24}, а не эти."}},{"uk":"Інформують про рух по одній смузі.","ru":"Информируют о движении по одной полосе.","w":{"uk":"Знак {s:5.5} стосується всієї ширини дороги, а не однієї смуги.","ru":"Знак {s:5.5} касается всей ширины дороги, а не одной полосы."}}],"c":0,"e":{"uk":"Знак {s:5.5} позначає дорогу з одностороннім рухом, а {s:5.7.1} — виїзд на таку дорогу й напрямок руху нею ({p:33.5}); обидва інформують про односторонній рух.","ru":"Знак {s:5.5} обозначает дорогу с односторонним движением, а {s:5.7.1} — выезд на такую дорогу и направление движения по ней ({p:33.5}); оба информируют об одностороннем движении."},"ref":["33.5"],"pic":["img/hsc/33-110-1.jpg"]},{"id":"h33-111","t":"h33","num":"33.111","q":{"uk":"Що спільного у цих двох дорожніх знаків?","ru":"Что общего у этих двух дорожных знаков?"},"a":[{"uk":"Дозволяють розворот.","ru":"Разрешают разворот."},{"uk":"Забороняють розворот.","ru":"Запрещают разворот.","w":{"uk":"Обидва знаки, навпаки, розворот дозволяють.","ru":"Оба знака, наоборот, разворот разрешают."}},{"uk":"Дозволяють поворот праворуч.","ru":"Разрешают поворот направо.","w":{"uk":"Знак {s:4.5} поворот праворуч забороняє.","ru":"Знак {s:4.5} поворот направо запрещает."}},{"uk":"Забороняють поворот праворуч.","ru":"Запрещают поворот направо.","w":{"uk":"Знак {s:3.23} поворот праворуч не забороняє.","ru":"Знак {s:3.23} поворот направо не запрещает."}}],"c":0,"e":{"uk":"Знак {s:4.5} «Рух прямо або ліворуч» дозволяє також розворот ({p:33.4}), а знак {s:3.23} «Поворот ліворуч заборонено» забороняє лише поворот ліворуч, дозволяючи розворот ({p:33.3}).","ru":"Знак {s:4.5} «Движение прямо или налево» разрешает также разворот ({p:33.4}), а знак {s:3.23} «Поворот налево запрещён» запрещает только поворот налево, разрешая разворот ({p:33.3})."},"ref":["33.3","33.4"],"pic":["img/hsc/33-111-1.jpg"]},{"id":"h33-112","t":"h33","num":"33.112","q":{"uk":"Що спільного у цих двох дорожніх знаків?","ru":"Что общего у этих двух дорожных знаков?"},"a":[{"uk":"Інформують про зустрічну смугу руху для маршрутних транспортних засобів.","ru":"Информируют о встречной полосе движения для маршрутных транспортных средств.","w":{"uk":"Зустрічну смугу показує лише знак {s:5.8}, а {s:5.11} позначає смугу, рух якою попутний загальному потоку.","ru":"Встречную полосу показывает только знак {s:5.8}, а {s:5.11} обозначает полосу, движение по которой попутное общему потоку."}},{"uk":"Інформують про попутну смугу руху для маршрутних транспортних засобів.","ru":"Информируют о попутной полосе движения для маршрутных транспортных средств.","w":{"uk":"Попутну смугу позначає лише {s:5.11}, а на знаку {s:5.8} смуга для маршрутних транспортних засобів зустрічна.","ru":"Попутную полосу обозначает только {s:5.11}, а на знаке {s:5.8} полоса для маршрутных транспортных средств встречная."}},{"uk":"Інформують про смугу руху для маршрутних транспортних засобів.","ru":"Информируют о полосе движения для маршрутных транспортных средств."},{"uk":"Інформують про дорогу з одностороннім рухом.","ru":"Информируют о дороге с односторонним движением.","w":{"uk":"Дорогу з одностороннім рухом позначає знак {s:5.5}.","ru":"Дорогу с односторонним движением обозначает знак {s:5.5}."}}],"c":2,"e":{"uk":"Знак {s:5.8} позначає дорогу зі смугою для руху маршрутних транспортних засобів, а {s:5.11} — саму таку смугу ({p:33.5}); спільне в них — смуга для маршрутних транспортних засобів.","ru":"Знак {s:5.8} обозначает дорогу с полосой для движения маршрутных транспортных средств, а {s:5.11} — саму такую полосу ({p:33.5}); общее у них — полоса для маршрутных транспортных средств."},"ref":["33.5"],"pic":["img/hsc/33-112-1.jpg"]},{"id":"h33-113","t":"h33","num":"33.113","q":{"uk":"Що спільного у цих двох дорожніх знаків?","ru":"Что общего у этих двух дорожных знаков?"},"a":[{"uk":"Встановлюються перед перехрестями.","ru":"Устанавливаются перед перекрёстками.","w":{"uk":"Перед перехрестям встановлюють знак {s:5.16}, а {s:5.17.1} застосовують на дорогах з неоднаковою кількістю смуг у різних напрямках.","ru":"Перед перекрёстком устанавливают знак {s:5.16}, а {s:5.17.1} применяют на дорогах с неодинаковым количеством полос в разных направлениях."}},{"uk":"Інформують про кількість смуг попутного напрямку.","ru":"Информируют о количестве полос попутного направления.","w":{"uk":"Знак {s:5.17.1} показує смуги обох напрямків, а не лише попутного.","ru":"Знак {s:5.17.1} показывает полосы обоих направлений, а не только попутного."}},{"uk":"Інформують про кількість смуг на проїзній частині.","ru":"Информируют о количестве полос на проезжей части.","w":{"uk":"Знак {s:5.16} показує лише смуги свого напрямку на перехресті, а не всю проїзну частину.","ru":"Знак {s:5.16} показывает только полосы своего направления на перекрёстке, а не всю проезжую часть."}},{"uk":"Вказують дозволений рух по смугах.","ru":"Указывают разрешённое движение по полосам."}],"c":3,"e":{"uk":"Знак {s:5.16} показує дозволені напрямки руху по смугах на перехресті, а {s:5.17.1} — напрямок руху по смугах на дорозі ({p:33.5}); спільне — обидва вказують дозволений рух по смугах.","ru":"Знак {s:5.16} показывает разрешённые направления движения по полосам на перекрёстке, а {s:5.17.1} — направление движения по полосам на дороге ({p:33.5}); общее — оба указывают разрешённое движение по полосам."},"ref":["33.5"],"pic":["img/hsc/33-113-1.jpg"]},{"id":"h33-114","t":"h33","num":"33.114","q":{"uk":"Який із зображених дорожніх знаків позначає кінець зони стоянки?","ru":"Какой из изображённых дорожных знаков обозначает конец зоны стоянки?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 позначає кінець зони дії заборонного знака (перекреслене сіре коло з написом «ЗОНА»), а не кінець зони стоянки.","ru":"Знак 1 обозначает конец зоны действия запрещающего знака (перечёркнутый серый круг с надписью «ЗОНА»), а не конец зоны стоянки."}},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:5.35} «Кінець житлової зони».","ru":"Знак 2 — {s:5.35} «Конец жилой зоны»."}},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — {s:5.50} «Кінець населеного пункту».","ru":"Знак 3 — {s:5.50} «Конец населённого пункта»."}},{"uk":"Знак 4.","ru":"Знак 4."},{"uk":"Знак 5.","ru":"Знак 5.","w":{"uk":"Знак 5 — {s:3.9} «Рух пішоходів заборонено».","ru":"Знак 5 — {s:3.9} «Движение пешеходов запрещено»."}}],"c":3,"e":{"uk":"Знак 4 — {s:5.44} «Кінець зони стоянки»: перекреслений знак {s:5.43} «Зона стоянки» ({p:33.5}).","ru":"Знак 4 — {s:5.44} «Конец зоны стоянки»: перечёркнутый знак {s:5.43} «Зона стоянки» ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-114-1.jpg"]},{"id":"h33-115","t":"h33","num":"33.115","q":{"uk":"З яким із дорожніх знаків можуть бути встановлені зображені таблички?","ru":"С каким из дорожных знаков могут быть установлены изображённые таблички?"},"a":[{"uk":"Зі знаком 1.","ru":"Со знаком 1.","w":{"uk":"Знак 1 — {s:1.13} «Слизька дорога»; таблички «Вид небезпеки» з ним не застосовують.","ru":"Знак 1 — {s:1.13} «Скользкая дорога»; таблички «Вид опасности» с ним не применяют."}},{"uk":"Зі знаком 2.","ru":"Со знаком 2.","w":{"uk":"Знак 2 — {s:1.16} «Падіння каміння»; таблички «Вид небезпеки» з ним не застосовують.","ru":"Знак 2 — {s:1.16} «Падение камней»; таблички «Вид опасности» с ним не применяют."}},{"uk":"Зі знаком 3.","ru":"Со знаком 3.","w":{"uk":"Знак 3 — {s:1.37} «Дорожні роботи»; таблички «Вид небезпеки» з ним не застосовують.","ru":"Знак 3 — {s:1.37} «Дорожные работы»; таблички «Вид опасности» с ним не применяют."}},{"uk":"Зі знаком 4.","ru":"Со знаком 4."},{"uk":"Зі знаком 5.","ru":"Со знаком 5.","w":{"uk":"Знак 5 — {s:1.38} «Затори в дорожньому русі»; таблички «Вид небезпеки» з ним не застосовують.","ru":"Знак 5 — {s:1.38} «Заторы в дорожном движении»; таблички «Вид опасности» с ним не применяют."}}],"c":3,"e":{"uk":"Це таблички «Вид небезпеки» ({s:7.21.1}–{s:7.21.4}): їх застосовують зі знаком {s:1.41}, а також дозволено зі знаком {s:1.39} «Інша небезпека» ({p:33.7}), який зображено під номером 4.","ru":"Это таблички «Вид опасности» ({s:7.21.1}–{s:7.21.4}): их применяют со знаком {s:1.41}, а также разрешено со знаком {s:1.39} «Иная опасность» ({p:33.7}), который изображён под номером 4."},"ref":["33.7"],"pic":["img/hsc/33-115-1.jpg"]},{"id":"h33-116","t":"h33","num":"33.116","q":{"uk":"Яка з табличок встановлюється із зображеним дорожнім знаком?","ru":"Какая из табличек устанавливается с изображённым дорожным знаком?"},"a":[{"uk":"Табличка 1.","ru":"Табличка 1.","w":{"uk":"Не лише табличка 1: зі знаком {s:1.39} дозволено застосовувати всі таблички «Вид небезпеки».","ru":"Не только табличка 1: со знаком {s:1.39} разрешено применять все таблички «Вид опасности»."}},{"uk":"Табличка 2.","ru":"Табличка 2.","w":{"uk":"Не лише табличка 2: зі знаком {s:1.39} дозволено застосовувати всі таблички «Вид небезпеки».","ru":"Не только табличка 2: со знаком {s:1.39} разрешено применять все таблички «Вид опасности»."}},{"uk":"Табличка 3.","ru":"Табличка 3.","w":{"uk":"Не лише табличка 3: зі знаком {s:1.39} дозволено застосовувати всі таблички «Вид небезпеки».","ru":"Не только табличка 3: со знаком {s:1.39} разрешено применять все таблички «Вид опасности»."}},{"uk":"Табличка 4.","ru":"Табличка 4.","w":{"uk":"Не лише табличка 4: зі знаком {s:1.39} дозволено застосовувати всі таблички «Вид небезпеки».","ru":"Не только табличка 4: со знаком {s:1.39} разрешено применять все таблички «Вид опасности»."}},{"uk":"Усі перелічені вище таблички.","ru":"Все перечисленные выше таблички."}],"c":4,"e":{"uk":"Зі знаком {s:1.39} «Інша небезпека» дозволено застосовувати таблички {s:7.21.1}–{s:7.21.5} «Вид небезпеки» ({p:33.7}), тож підходять усі зображені таблички.","ru":"Со знаком {s:1.39} «Иная опасность» разрешено применять таблички {s:7.21.1}–{s:7.21.5} «Вид опасности» ({p:33.7}), поэтому подходят все изображённые таблички."},"ref":["33.7"],"pic":["img/hsc/33-116-1.jpg"]},{"id":"h33-117","t":"h33","num":"33.117","q":{"uk":"Зображена табличка вказує:","ru":"Изображённая табличка указывает:"},"a":[{"uk":"Час дії дорожнього знака.","ru":"Время действия дорожного знака."},{"uk":"Час обмеження дії дорожнього знака.","ru":"Время ограничения действия дорожного знака.","w":{"uk":"Табличка вказує дні, коли знак діє (з понеділка по середу), а не коли його дію обмежено.","ru":"Табличка указывает дни, когда знак действует (с понедельника по среду), а не когда его действие ограничено."}}],"c":0,"e":{"uk":"Це табличка {s:7.4.3} «Час дії» з написом «Понеділок – середа»: вона зазначає дні тижня, протягом яких діє знак ({p:33.7}).","ru":"Это табличка {s:7.4.3} «Время действия» с надписью «Понедельник – среда»: она указывает дни недели, в течение которых действует знак ({p:33.7})."},"ref":["33.7"],"pic":["img/hsc/33-117-1.jpg"]},{"id":"h33-118","t":"h33","num":"33.118","q":{"uk":"Яка із зображених табличок дозволяє стоянку всіх транспортних засобів способом, вказаним на ній?","ru":"Какая из изображённых табличек разрешает стоянку всех транспортных средств указанным на ней способом?"},"a":[{"uk":"Табличка 1.","ru":"Табличка 1.","w":{"uk":"Табличка 1 визначає спосіб поставлення з використанням тротуару лише для легкових автомобілів і мотоциклів.","ru":"Табличка 1 определяет способ постановки с использованием тротуара только для легковых автомобилей и мотоциклов."}},{"uk":"Табличка 2.","ru":"Табличка 2.","w":{"uk":"Табличка 2 визначає спосіб поставлення біля тротуару лише для легкових автомобілів і мотоциклів.","ru":"Табличка 2 определяет способ постановки у тротуара только для легковых автомобилей и мотоциклов."}},{"uk":"Табличка 3.","ru":"Табличка 3."},{"uk":"Табличка 4.","ru":"Табличка 4.","w":{"uk":"Табличка 4 визначає спосіб поставлення з використанням тротуару лише для легкових автомобілів і мотоциклів.","ru":"Табличка 4 определяет способ постановки с использованием тротуара только для легковых автомобилей и мотоциклов."}},{"uk":"Табличка 5.","ru":"Табличка 5.","w":{"uk":"Табличка 5 визначає спосіб поставлення з використанням тротуару лише для легкових автомобілів і мотоциклів.","ru":"Табличка 5 определяет способ постановки с использованием тротуара только для легковых автомобилей и мотоциклов."}}],"c":2,"e":{"uk":"Табличка 3 — {s:7.6.1}: за {p:33.7} вона означає, що **всі** транспортні засоби ставлять на стоянку на проїзній частині вздовж тротуару.","ru":"Табличка 3 — {s:7.6.1}: согласно {p:33.7} она означает, что **все** транспортные средства ставят на стоянку на проезжей части вдоль тротуара."},"ref":["33.7"],"pic":["img/hsc/33-118-1.jpg"]},{"id":"h33-119","t":"h33","num":"33.119","q":{"uk":"Зображені таблички, що встановлюються з відповідними дорожніми знаками, вказують:","ru":"Изображённые таблички, которые устанавливаются с соответствующими дорожными знаками, указывают:"},"a":[{"uk":"Спосіб поставлення, а також вид транспортного засобу, який може бути поставлено на стоянку.","ru":"Способ постановки, а также вид транспортного средства, который может быть поставлен на стоянку."},{"uk":"Вид транспортного засобу, який може бути поставлено на стоянку.","ru":"Вид транспортного средства, который может быть поставлен на стоянку.","w":{"uk":"Відповідь неповна: таблички вказують також спосіб поставлення транспортного засобу.","ru":"Ответ неполный: таблички указывают также способ постановки транспортного средства."}},{"uk":"Спосіб поставлення транспортного засобу на стоянку.","ru":"Способ постановки транспортного средства на стоянку.","w":{"uk":"Відповідь неповна: таблички вказують також вид транспортного засобу, який можна так поставити.","ru":"Ответ неполный: таблички указывают также вид транспортного средства, которое можно так поставить."}}],"c":0,"e":{"uk":"На зображених табличках {s:7.6.2}–{s:7.6.6} показано легковий автомобіль і його положення відносно тротуару: вони визначають спосіб поставлення легкових автомобілів і мотоциклів на стоянці біля тротуару та з його використанням ({p:33.7}), тобто вказують і спосіб поставлення, і вид транспортного засобу.","ru":"На изображённых табличках {s:7.6.2}–{s:7.6.6} показан легковой автомобиль и его положение относительно тротуара: они определяют способ постановки легковых автомобилей и мотоциклов на стоянке у тротуара и с его использованием ({p:33.7}), то есть указывают и способ постановки, и вид транспортного средства."},"ref":["33.7"],"pic":["img/hsc/33-119-1.jpg"]},{"id":"h33-120","t":"h33","num":"33.120","q":{"uk":"Зображена табличка, яка встановлюється зі знаками «Місце стоянки» або «Зона стоянки», вказує:","ru":"Изображённая табличка, которая устанавливается со знаками «Место стоянки» или «Зона стоянки», указывает:"},"a":[{"uk":"Те, що стоянку транспортних засобів дозволено лише передньою частиною до бордюру.","ru":"То, что стоянка транспортных средств разрешена лишь передней частью к бордюру.","w":{"uk":"Спосіб поставлення транспортного засобу визначають таблички {s:7.6.1}–{s:7.6.7}.","ru":"Способ постановки транспортного средства определяют таблички {s:7.6.1}–{s:7.6.7}."}},{"uk":"Те, що залишати на стоянку транспортні засоби дозволено лише з непрацюючим двигуном.","ru":"То, что оставлять на стоянке транспортные средства разрешено лишь с неработающим двигателем."},{"uk":"Те, що заборонено стоянку транспортних засобів з підвищеною димністю відпрацьованих газів.","ru":"То, что запрещена стоянка транспортных средств с повышенной дымностью отработавших газов.","w":{"uk":"Перекреслений вихлоп на табличці {s:7.7} означає вимогу вимкнути двигун на стоянці, а не заборону для автомобілів з підвищеною димністю.","ru":"Перечёркнутый выхлоп на табличке {s:7.7} означает требование выключить двигатель на стоянке, а не запрет для автомобилей с повышенной дымностью."}}],"c":1,"e":{"uk":"Це табличка {s:7.7} «Стоянка з непрацюючим двигуном»: на стоянці, позначеній знаками {s:5.42.1}–{s:5.42.3} або {s:5.43}, дозволяється залишати транспортні засоби лише з непрацюючим двигуном ({p:33.7}).","ru":"Это табличка {s:7.7} «Стоянка с неработающим двигателем»: на стоянке, обозначенной знаками {s:5.42.1}–{s:5.42.3} или {s:5.43}, разрешается оставлять транспортные средства только с неработающим двигателем ({p:33.7})."},"ref":["33.7"],"pic":["img/hsc/33-120-1.jpg"]},{"id":"h33-121","t":"h33","num":"33.121","q":{"uk":"Яка із зображених табличок вказує, що дозволено залишати транспортні засоби лише з непрацюючим двигуном?","ru":"Какая из изображённых табличек указывает, что разрешается оставлять транспортные средства только с неработающим двигателем?"},"a":[{"uk":"Табличка 1.","ru":"Табличка 1.","w":{"uk":"Табличка 1 — одна з табличок «Спосіб поставлення транспортного засобу на стоянку» ({s:7.6.1}–{s:7.6.7}): вона визначає, як ставити автомобіль відносно тротуару, а не вимагає вимикати двигун.","ru":"Табличка 1 — одна из табличек «Способ постановки транспортного средства на стоянку» ({s:7.6.1}–{s:7.6.7}): она определяет, как ставить автомобиль относительно тротуара, а не требует выключать двигатель."}},{"uk":"Табличка 2.","ru":"Табличка 2.","w":{"uk":"Табличка 2 теж належить до табличок «Спосіб поставлення транспортного засобу на стоянку» і стосується лише способу поставлення.","ru":"Табличка 2 тоже относится к табличкам «Способ постановки транспортного средства на стоянку» и касается только способа постановки."}},{"uk":"Табличка 3.","ru":"Табличка 3."},{"uk":"Табличка 4.","ru":"Табличка 4.","w":{"uk":"Табличка 4 — {s:7.5.3} «Вид транспортного засобу»: поширює дію знака на легкові автомобілі та вантажні автомобілі з дозволеною максимальною масою до 3,5 т.","ru":"Табличка 4 — {s:7.5.3} «Вид транспортного средства»: распространяет действие знака на легковые автомобили и грузовые автомобили с разрешённой максимальной массой до 3,5 т."}},{"uk":"Табличка 5.","ru":"Табличка 5.","w":{"uk":"Табличка 5 — {s:7.5.1} «Вид транспортного засобу»: поширює дію знака на вантажні автомобілі з дозволеною максимальною масою понад 3,5 т.","ru":"Табличка 5 — {s:7.5.1} «Вид транспортного средства»: распространяет действие знака на грузовые автомобили с разрешённой максимальной массой более 3,5 т."}}],"c":2,"e":{"uk":"Табличка 3 — {s:7.7} «Стоянка з непрацюючим двигуном» (перекреслений автомобіль із хмаркою вихлопних газів): на стоянці, позначеній знаками {s:5.42.1}–{s:5.42.3} або {s:5.43}, дозволяється залишати транспортні засоби **лише** з непрацюючим двигуном ({p:33.7}).","ru":"Табличка 3 — {s:7.7} «Стоянка с неработающим двигателем» (перечёркнутый автомобиль с облачком выхлопных газов): на стоянке, обозначенной знаками {s:5.42.1}–{s:5.42.3} или {s:5.43}, разрешается оставлять транспортные средства **только** с неработающим двигателем ({p:33.7})."},"ref":["33.7"],"pic":["img/hsc/33-121-1.jpg"]},{"id":"h33-122","t":"h33","num":"33.122","q":{"uk":"Зображена табличка визначає:","ru":"Изображённая табличка определяет:"},"a":[{"uk":"Кінець зони дії дорожнього знака, з яким вона встановлена.","ru":"Конец зоны действия дорожного знака, с которым она установлена.","w":{"uk":"Кінець зони дії знака зазначає інша табличка — {s:7.2.3} «Зона дії» з вертикальною стрілкою.","ru":"Конец зоны действия знака указывает другая табличка — {s:7.2.3} «Зона действия» с вертикальной стрелкой."}},{"uk":"Смугу руху, на яку поширюється дія знака або світлофора, з яким вона встановлена.","ru":"Полосу движения, на которую распространяется действие знака или светофора, с которым она установлена."},{"uk":"Початок зони дії дорожнього знака, з яким вона встановлена.","ru":"Начало зоны действия дорожного знака, с которым она установлена.","w":{"uk":"Зону дії знака позначають таблички «Зона дії» ({s:7.2.1}–{s:7.2.7}), а табличка {s:7.9} вказує смугу руху.","ru":"Зону действия знака обозначают таблички «Зона действия» ({s:7.2.1}–{s:7.2.7}), а табличка {s:7.9} указывает полосу движения."}}],"c":1,"e":{"uk":"Це табличка {s:7.9} «Смуга руху» (широка стрілка, спрямована вниз): вона визначає смугу руху, на яку поширюється дія знака або світлофора ({p:33.7}).","ru":"Это табличка {s:7.9} «Полоса движения» (широкая стрелка, направленная вниз): она определяет полосу движения, на которую распространяется действие знака или светофора ({p:33.7})."},"ref":["33.7"],"pic":["img/hsc/33-122-1.jpg"]},{"id":"h33-123","t":"h33","num":"33.123","q":{"uk":"З яким із дорожніх знаків може бути встановлена зображена табличка?","ru":"С каким из дорожных знаков может быть установлена изображённая табличка?"},"a":[{"uk":"Зі знаком 1.","ru":"Со знаком 1.","w":{"uk":"Знак 1 — {s:1.1} «Небезпечний поворот праворуч» попереджає про один поворот, тому табличку з кількістю поворотів з ним не застосовують.","ru":"Знак 1 — {s:1.1} «Опасный поворот направо» предупреждает об одном повороте, поэтому табличку с количеством поворотов с ним не применяют."}},{"uk":"Зі знаком 2.","ru":"Со знаком 2.","w":{"uk":"Знак 2 — {s:1.13} «Слизька дорога»; табличка {s:7.10} з ним не застосовується.","ru":"Знак 2 — {s:1.13} «Скользкая дорога»; табличка {s:7.10} с ним не применяется."}},{"uk":"Зі знаком 3.","ru":"Со знаком 3."},{"uk":"Зі знаком 4.","ru":"Со знаком 4.","w":{"uk":"Знак 4 — {s:1.5.1} «Звуження дороги»; табличка {s:7.10} з ним не застосовується.","ru":"Знак 4 — {s:1.5.1} «Сужение дороги»; табличка {s:7.10} с ним не применяется."}}],"c":2,"e":{"uk":"Це табличка {s:7.10} «Кількість поворотів»: її застосовують зі знаками {s:1.3.1} і {s:1.3.2} «Декілька поворотів», якщо поворотів три й більше ({p:33.7}). Знак 3 — саме {s:1.3.1}.","ru":"Это табличка {s:7.10} «Количество поворотов»: её применяют со знаками {s:1.3.1} и {s:1.3.2} «Несколько поворотов», если поворотов три и более ({p:33.7}). Знак 3 — именно {s:1.3.1}."},"ref":["33.7"],"pic":["img/hsc/33-123-1.jpg"]},{"id":"h33-124","t":"h33","num":"33.124","q":{"uk":"Зображена табличка вказує:","ru":"Изображённая табличка указывает:"},"a":[{"uk":"Час дії дорожнього знака, з яким вона встановлена.","ru":"Время действия дорожного знака, с которым она установлена.","w":{"uk":"Час дії знака вказують таблички «Час дії» ({s:7.4.1}–{s:7.4.7}) з днями тижня або годинами.","ru":"Время действия знака указывают таблички «Время действия» ({s:7.4.1}–{s:7.4.7}) с днями недели или часами."}},{"uk":"Те, що послуги надаються лише за плату.","ru":"То, что услуги предоставляются только за плату."},{"uk":"Зону дії дорожнього знака, з яким вона встановлена.","ru":"Зону действия дорожного знака, с которым она установлена.","w":{"uk":"Зону дії знака вказують таблички «Зона дії» ({s:7.2.1}–{s:7.2.7}).","ru":"Зону действия знака указывают таблички «Зона действия» ({s:7.2.1}–{s:7.2.7})."}}],"c":1,"e":{"uk":"Це табличка {s:7.14} «Платні послуги» (зображення монет): її застосовують зі знаками місць і зон стоянки, де беруть плату за паркування, а також зі знаками {s:6.6}, {s:6.11} і {s:6.21}, де послуги надаються тільки на платній основі ({p:33.7}).","ru":"Это табличка {s:7.14} «Платные услуги» (изображение монет): её применяют со знаками мест и зон стоянки, где взимается плата за парковку, а также со знаками {s:6.6}, {s:6.11} и {s:6.21}, где услуги предоставляются только на платной основе ({p:33.7})."},"ref":["33.7"],"pic":["img/hsc/33-124-1.jpg"]},{"id":"h33-125","t":"h33","num":"33.125","q":{"uk":"З яким із дорожніх знаків може бути встановлена зображена табличка?","ru":"С каким из дорожных знаков может быть установлена изображённая табличка?"},"a":[{"uk":"Зі знаком 1.","ru":"Со знаком 1.","w":{"uk":"Знак 1 — {s:5.38.1} «Пішохідний перехід»; з ним застосовують табличку {s:7.16} «Пішоходи з порушенням зору», а не {s:7.17}.","ru":"Знак 1 — {s:5.38.1} «Пешеходный переход»; с ним применяют табличку {s:7.16} «Пешеходы с нарушением зрения», а не {s:7.17}."}},{"uk":"Зі знаком 2.","ru":"Со знаком 2.","w":{"uk":"Знак 2 — {s:3.34} «Зупинку заборонено»; щоб його дія не поширювалася на водіїв з інвалідністю, застосовують іншу табличку — {s:7.18} «Крім осіб з інвалідністю».","ru":"Знак 2 — {s:3.34} «Остановка запрещена»; чтобы его действие не распространялось на водителей с инвалидностью, применяют другую табличку — {s:7.18} «Кроме лиц с инвалидностью»."}},{"uk":"Зі знаком 3.","ru":"Со знаком 3.","w":{"uk":"Знак 3 — {s:3.35} «Стоянку заборонено»; з ним застосовують табличку {s:7.18}, а не {s:7.17}.","ru":"Знак 3 — {s:3.35} «Стоянка запрещена»; с ним применяют табличку {s:7.18}, а не {s:7.17}."}},{"uk":"Зі знаком 4.","ru":"Со знаком 4."},{"uk":"Зі знаком 5.","ru":"Со знаком 5.","w":{"uk":"Знак 5 — {s:3.38} «Зона обмеженої стоянки»; табличку {s:7.17} з ним не застосовують, можлива лише {s:7.18}.","ru":"Знак 5 — {s:3.38} «Зона ограниченной стоянки»; табличку {s:7.17} с ним не применяют, возможна лишь {s:7.18}."}}],"c":3,"e":{"uk":"Це табличка {s:7.17} «Особи з інвалідністю»: її застосовують зі знаками {s:5.42.1}, {s:5.42.2} і {s:5.43}, щоб позначити місце для стоянки транспортних засобів з розпізнавальним знаком «Водій з інвалідністю» ({p:33.7}). Знак 4 — {s:5.42.1} «Місце для стоянки».","ru":"Это табличка {s:7.17} «Лица с инвалидностью»: её применяют со знаками {s:5.42.1}, {s:5.42.2} и {s:5.43}, чтобы обозначить место для стоянки транспортных средств с опознавательным знаком «Водитель с инвалидностью» ({p:33.7}). Знак 4 — {s:5.42.1} «Место стоянки»."},"ref":["33.7"],"pic":["img/hsc/33-125-1.jpg"]},{"id":"h33-126","t":"h33","num":"33.126","q":{"uk":"Що спільного у цих двох дорожніх знаків?","ru":"Что общего у этих двух дорожных знаков?"},"a":[{"uk":"Встановлюються тільки на Т-подібних перехрестях.","ru":"Устанавливаются только на Т-образных перекрёстках.","w":{"uk":"Знак {s:1.4.3} установлюють на Т-подібних перехрестях, розгалуженнях доріг або для об'їзду ділянки, що ремонтується, а {s:4.6} — перед будь-яким перехрещенням проїзних частин.","ru":"Знак {s:1.4.3} устанавливают на Т-образных перекрёстках, разветвлениях дорог или для объезда ремонтируемого участка, а {s:4.6} — перед любым пересечением проезжих частей."}},{"uk":"Не забороняють поворот направо.","ru":"Не запрещают поворот направо."},{"uk":"Завжди дозволяють розворот.","ru":"Всегда разрешают разворот.","w":{"uk":"Розворот дозволяє лише знак {s:4.6}, і то не завжди — його можуть заборонити інші знаки або вимоги Правил; попереджувальний знак {s:1.4.3} розвороту не стосується.","ru":"Разворот разрешает только знак {s:4.6}, да и то не всегда — его могут запретить другие знаки или требования Правил; предупреждающий знак {s:1.4.3} разворота не касается."}},{"uk":"Дозволяють рух прямо для маршрутних транспортних засобів.","ru":"Разрешают движение прямо для маршрутных транспортных средств.","w":{"uk":"Виняток для маршрутних транспортних засобів стосується лише наказового знака {s:4.6}, а знак {s:1.4.3} показує, що прямо проїзду немає.","ru":"Исключение для маршрутных транспортных средств касается только предписывающего знака {s:4.6}, а знак {s:1.4.3} показывает, что прямо проезда нет."}}],"c":1,"e":{"uk":"Знак {s:1.4.3} «Напрямок повороту» показує, що далі можна рухатися праворуч або ліворуч ({p:33.1}), а знак {s:4.6} «Рух праворуч або ліворуч» дозволяє рух лише в цих напрямках ({p:33.4}); отже, жоден із них поворот праворуч **не забороняє**.","ru":"Знак {s:1.4.3} «Направление поворота» показывает, что дальше можно двигаться направо или налево ({p:33.1}), а знак {s:4.6} «Движение направо или налево» разрешает движение только в этих направлениях ({p:33.4}); следовательно, ни один из них поворот направо **не запрещает**."},"ref":["33.1","33.4"],"pic":["img/hsc/33-126-1.jpg"]},{"id":"h33-127","t":"h33","num":"33.127","q":{"uk":"Зображений дорожній знак інформує:","ru":"Изображённый дорожный знак информирует:"},"a":[{"uk":"Про початок смуги гальмування.","ru":"О начале полосы торможения.","w":{"uk":"Початок смуги гальмування позначає знак {s:5.20.1} «Початок додаткової смуги руху».","ru":"Начало полосы торможения обозначает знак {s:5.20.1} «Начало дополнительной полосы движения»."}},{"uk":"Про мінімально допустиму швидкість на лівій смузі, що веде на підйом.","ru":"О минимально допустимой скорости на левой полосе, ведущей на подъём."},{"uk":"Про наявність смуги призначеної для руху транспортних засобів, що рухаються за встановленими маршрутами.","ru":"О наличии полосы, предназначенной для движения транспортных средств, движущихся по установленным маршрутам.","w":{"uk":"Смугу для руху маршрутних транспортних засобів позначає знак {s:5.11}.","ru":"Полосу для движения маршрутных транспортных средств обозначает знак {s:5.11}."}}],"c":1,"e":{"uk":"Це знак {s:5.25} «Мінімальна швидкість на смузі руху» із зображенням знака {s:4.12}: він установлює мінімально допустиму швидкість на лівій смузі, що веде на підйом, — так виокремлюють смугу для тихохідного транспорту ({p:33.5}).","ru":"Это знак {s:5.25} «Минимальная скорость на полосе движения» с изображением знака {s:4.12}: он устанавливает минимально допустимую скорость на левой полосе, ведущей на подъём, — так выделяют полосу для тихоходного транспорта ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-127-1.jpg"]},{"id":"h33-128","t":"h33","num":"33.128","q":{"uk":"Зображений дорожній знак вказує:","ru":"Изображённый дорожный знак указывает:"},"a":[{"uk":"Дозволені напрямки руху на перехресті.","ru":"Разрешённые направления движения на перекрёстке.","w":{"uk":"Дозволені напрямки руху на перехресті показують знак {s:5.16} або наказові знаки {s:4.1}–{s:4.6}.","ru":"Разрешённые направления движения на перекрёстке показывают знак {s:5.16} или предписывающие знаки {s:4.1}–{s:4.6}."}},{"uk":"Дороги, які не мають наскрізного проїзду.","ru":"Дороги, не имеющие сквозного проезда."},{"uk":"Дороги, рух по яких заборонено.","ru":"Дороги, движение по которым запрещено.","w":{"uk":"Знак не забороняє рух: тупиковою дорогою їздити можна, вона лише не має наскрізного проїзду; рух забороняють, наприклад, знаки {s:3.1} чи {s:3.21}.","ru":"Знак не запрещает движение: по тупиковой дороге ездить можно, она лишь не имеет сквозного проезда; движение запрещают, например, знаки {s:3.1} или {s:3.21}."}}],"c":1,"e":{"uk":"Це знак {s:5.32.2} «Тупик»: так позначають дорогу, що не має наскрізного проїзду ({p:33.5}); червоний прямокутник показує, що тупиковою є дорога ліворуч.","ru":"Это знак {s:5.32.2} «Тупик»: так обозначают дорогу, не имеющую сквозного проезда ({p:33.5}); красный прямоугольник показывает, что тупиковой является дорога налево."},"ref":["33.5"],"pic":["img/hsc/33-128-1.jpg"]},{"id":"h33-129","t":"h33","num":"33.129","q":{"uk":"Чи повинні Ви під час руху прямо дати дорогу мотоциклу?","ru":"Должны ли вы при движении прямо уступить дорогу мотоциклу?"},"a":[{"uk":"Не повинні.","ru":"Не должны.","w":{"uk":"Тупикова дорога — це все одно дорога, а не прилегла територія, і знаків пріоритету тут немає, тож діє правило «перешкоди праворуч».","ru":"Тупиковая дорога — это всё равно дорога, а не прилегающая территория, и знаков приоритета здесь нет, поэтому действует правило «помехи справа»."}},{"uk":"Повинні.","ru":"Должны."}],"c":1,"e":{"uk":"Знак {s:5.32.3} «Тупик» лише інформує, що дорога праворуч не має наскрізного проїзду ({p:33.5}), і черговості проїзду не встановлює. Перехрестя рівнозначне, тому треба дати дорогу мотоциклу, що наближається праворуч ({p:16.12}).","ru":"Знак {s:5.32.3} «Тупик» лишь информирует, что дорога справа не имеет сквозного проезда ({p:33.5}), и очерёдности проезда не устанавливает. Перекрёсток равнозначный, поэтому нужно уступить дорогу мотоциклу, приближающемуся справа ({p:16.12})."},"ref":["16.12","33.5"],"pic":["img/hsc/33-129-1.jpg"]},{"id":"h33-130","t":"h33","num":"33.130","q":{"uk":"Який із зображених дорожніх знаків вказує рекомендовану швидкість руху?","ru":"Какой из изображённых дорожных знаков указывает рекомендуемую скорость движения?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:4.12} «Обмеження мінімальної швидкості» (синє коло): рухатися повільніше за вказану швидкість не можна.","ru":"Знак 1 — {s:4.12} «Ограничение минимальной скорости» (синий круг): двигаться медленнее указанной скорости нельзя."}},{"uk":"Знак 2.","ru":"Знак 2."},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — {s:3.29} «Обмеження максимальної швидкості»: забороняє рух зі швидкістю, що перевищує вказану.","ru":"Знак 3 — {s:3.29} «Ограничение максимальной скорости»: запрещает движение со скоростью, превышающей указанную."}},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Знак 4 — {s:3.31} «Зона обмеження максимальної швидкості»: забороняє перевищувати вказану швидкість у межах усієї зони.","ru":"Знак 4 — {s:3.31} «Зона ограничения максимальной скорости»: запрещает превышать указанную скорость в пределах всей зоны."}},{"uk":"Знак 5.","ru":"Знак 5.","w":{"uk":"Знак 5 — {s:3.15}: забороняє рух транспортних засобів, загальна фактична маса яких перевищує 7 т; до швидкості він не стосується.","ru":"Знак 5 — {s:3.15}: запрещает движение транспортных средств, общая фактическая масса которых превышает 7 т; к скорости он не относится."}}],"c":1,"e":{"uk":"Знак 2 — {s:5.33} «Рекомендована швидкість» (синій квадрат із числом); його дія поширюється до найближчого перехрестя ({p:33.5}).","ru":"Знак 2 — {s:5.33} «Рекомендуемая скорость» (синий квадрат с числом); его действие распространяется до ближайшего перекрёстка ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-130-1.jpg"]},{"id":"h33-131","t":"h33","num":"33.131","q":{"uk":"Зображений дорожній знак застосовується для:","ru":"Изображённый дорожный знак применяется для:"},"a":[{"uk":"Зазначення швидкості, з якою рекомендується рух на даній ділянці дороги.","ru":"Указания скорости, с которой рекомендуется движение на данном участке дороги."},{"uk":"Зазначення обмеження максимальної швидкості на даній ділянці дороги.","ru":"Указания ограничения максимальной скорости на данном участке дороги.","w":{"uk":"Максимальну швидкість обмежує заборонний знак {s:3.29} — червоне коло з числом, а інформаційно-вказівний знак {s:5.33} швидкість лише рекомендує.","ru":"Максимальную скорость ограничивает запрещающий знак {s:3.29} — красный круг с числом, а информационно-указательный знак {s:5.33} скорость лишь рекомендует."}}],"c":0,"e":{"uk":"Синій квадратний знак із числом — {s:5.33} «Рекомендована швидкість»: він повідомляє швидкість, з якою рекомендується рухатися на цій ділянці, і діє до найближчого перехрестя ({p:33.5}).","ru":"Синий квадратный знак с числом — {s:5.33} «Рекомендуемая скорость»: он сообщает скорость, с которой рекомендуется двигаться на этом участке, и действует до ближайшего перекрёстка ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-131-1.jpg"]},{"id":"h33-132","t":"h33","num":"33.132","q":{"uk":"Який із зображених дорожніх знаків інформує про початок житлової зони?","ru":"Какой из изображённых дорожных знаков информирует о начале жилой зоны?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:3.1} «Рух заборонено».","ru":"Знак 1 — {s:3.1} «Движение запрещено»."}},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:3.9} «Рух пішоходів заборонено».","ru":"Знак 2 — {s:3.9} «Движение пешеходов запрещено»."}},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — {s:5.36} «Пішохідна зона», а не житлова.","ru":"Знак 3 — {s:5.36} «Пешеходная зона», а не жилая."}},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Знак 4 — {s:4.16} «Доріжка для пішоходів».","ru":"Знак 4 — {s:4.16} «Дорожка для пешеходов»."}},{"uk":"Знак 5.","ru":"Знак 5."}],"c":4,"e":{"uk":"Знак 5 — {s:5.34} «Житлова зона» (автомобіль, будинок, пішохід і дитина з м'ячем): він інформує про в'їзд на територію, де діють особливі умови руху, передбачені розділом 26 Правил ({p:33.5}).","ru":"Знак 5 — {s:5.34} «Жилая зона» (автомобиль, дом, пешеход и ребёнок с мячом): он информирует о въезде на территорию, где действуют особые условия движения, предусмотренные разделом 26 Правил ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-132-1.jpg"]},{"id":"h33-133","t":"h33","num":"33.133","q":{"uk":"Про що інформує зображений дорожній знак?","ru":"О чём информирует изображённый дорожный знак?"},"a":[{"uk":"Про в'їзд на територію, яка є пішохідною зоною.","ru":"О въезде на территорию, которая является пешеходной зоной.","w":{"uk":"Пішохідну зону позначає інший знак — {s:5.36} (пішоходи в синьому колі з написом «ЗОНА»).","ru":"Пешеходную зону обозначает другой знак — {s:5.36} (пешеходы в синем круге с надписью «ЗОНА»)."}},{"uk":"Про в'їзд на прилеглу територію.","ru":"О въезде на прилегающую территорию.","w":{"uk":"Окремі дворові території знаком {s:5.34} не позначають, хоча вимоги розділу 26 на них діють ({p:33.5}).","ru":"Отдельные дворовые территории знаком {s:5.34} не обозначают, хотя требования раздела 26 на них действуют ({p:33.5})."}},{"uk":"Про в'їзд на територію, що є житловою зоною.","ru":"О въезде на территорию, являющуюся жилой зоной."},{"uk":"Відповіді 1 і 3.","ru":"Ответы 1 и 3.","w":{"uk":"Знак позначає лише житлову зону; пішохідну зону позначає знак {s:5.36}.","ru":"Знак обозначает только жилую зону; пешеходную зону обозначает знак {s:5.36}."}}],"c":2,"e":{"uk":"Це знак {s:5.34} «Житлова зона»: він інформує про в'їзд на територію з особливими умовами руху ({p:33.5}); там, зокрема, заборонено транзитний рух, навчальну їзду і стоянку з працюючим двигуном ({p:26.2}).","ru":"Это знак {s:5.34} «Жилая зона»: он информирует о въезде на территорию с особыми условиями движения ({p:33.5}); там, в частности, запрещены сквозное движение, учебная езда и стоянка с работающим двигателем ({p:26.2})."},"ref":["33.5","26.2"],"pic":["img/hsc/33-133-1.jpg"]},{"id":"h33-134","t":"h33","num":"33.134","q":{"uk":"Який із зображених дорожніх знаків позначає кінець житлової зони?","ru":"Какой из изображённых дорожных знаков обозначает конец жилой зоны?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:5.37} «Кінець пішохідної зони».","ru":"Знак 1 — {s:5.37} «Конец пешеходной зоны»."}},{"uk":"Знак 2.","ru":"Знак 2."},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — {s:5.50} «Кінець населеного пункту».","ru":"Знак 3 — {s:5.50} «Конец населённого пункта»."}},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Знак 4 — {s:5.44} «Кінець зони стоянки».","ru":"Знак 4 — {s:5.44} «Конец зоны стоянки»."}},{"uk":"Знак 5.","ru":"Знак 5.","w":{"uk":"Знак 5 — {s:3.9} «Рух пішоходів заборонено».","ru":"Знак 5 — {s:3.9} «Движение пешеходов запрещено»."}}],"c":1,"e":{"uk":"Знак 2 — {s:5.35} «Кінець житлової зони»: перекреслений знак {s:5.34} «Житлова зона» ({p:33.5}).","ru":"Знак 2 — {s:5.35} «Конец жилой зоны»: перечёркнутый знак {s:5.34} «Жилая зона» ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-134-1.jpg"]},{"id":"h33-135","t":"h33","num":"33.135","q":{"uk":"Про що інформує зображений дорожній знак?","ru":"О чём информирует изображённый дорожный знак?"},"a":[{"uk":"Про в'їзд на територію, яка є пішохідною зоною.","ru":"О въезде на территорию, которая является пешеходной зоной."},{"uk":"Про в'їзд на прилеглу територію.","ru":"О въезде на прилегающую территорию.","w":{"uk":"Прилеглі території спеціальними знаками не позначають, а знак {s:5.36} позначає саме пішохідну зону.","ru":"Прилегающие территории специальными знаками не обозначают, а знак {s:5.36} обозначает именно пешеходную зону."}},{"uk":"Про в'їзд на територію, що є житловою зоною.","ru":"О въезде на территорию, являющуюся жилой зоной.","w":{"uk":"Житлову зону позначає знак {s:5.34} із зображенням будинку, автомобіля та пішоходів.","ru":"Жилую зону обозначает знак {s:5.34} с изображением дома, автомобиля и пешеходов."}},{"uk":"Відповіді 1 і 3.","ru":"Ответы 1 и 3.","w":{"uk":"Знак позначає лише пішохідну зону, а житлову зону позначають іншим знаком — {s:5.34}.","ru":"Знак обозначает только пешеходную зону, а жилую зону обозначают другим знаком — {s:5.34}."}}],"c":0,"e":{"uk":"Це знак {s:5.36} «Пішохідна зона»: він інформує про в'їзд на територію з особливими умовами руху ({p:33.5}); в'їзд туди дозволено лише транспортним засобам, що обслуговують розташовані в зоні громадян і підприємства, належать її мешканцям чи працівникам, а також автомобілям зі знаком «Водій з інвалідністю» ({p:26.3}).","ru":"Это знак {s:5.36} «Пешеходная зона»: он информирует о въезде на территорию с особыми условиями движения ({p:33.5}); въезд туда разрешён только транспортным средствам, обслуживающим расположенных в зоне граждан и предприятия, принадлежащим её жителям или работникам, а также автомобилям со знаком «Водитель с инвалидностью» ({p:26.3})."},"ref":["33.5","26.3"],"pic":["img/hsc/33-135-1.jpg"]},{"id":"h33-136","t":"h33","num":"33.136","q":{"uk":"Чи дозволено Вам рух прямо в зображеній ситуації?","ru":"Разрешено ли вам движение прямо в изображённой ситуации?"},"a":[{"uk":"Дозволено.","ru":"Разрешено."},{"uk":"Заборонено.","ru":"Запрещено.","w":{"uk":"Знак «Тупик» інформаційно-вказівний, а не заборонний: він повідомляє, що далі немає наскрізного проїзду, але в'їзд не забороняє.","ru":"Знак «Тупик» информационно-указательный, а не запрещающий: он сообщает, что дальше нет сквозного проезда, но въезд не запрещает."}}],"c":0,"e":{"uk":"Знак {s:5.32.1} «Тупик» лише інформує, що дорога попереду не має наскрізного проїзду ({p:33.5}); рух нею не заборонено, тож їхати прямо можна.","ru":"Знак {s:5.32.1} «Тупик» лишь информирует, что дорога впереди не имеет сквозного проезда ({p:33.5}); движение по ней не запрещено, поэтому ехать прямо можно."},"ref":["33.5"],"pic":["img/hsc/33-136-1.jpg"]},{"id":"h33-137","t":"h33","num":"33.137","q":{"uk":"Зображені дорожні знаки вказують:","ru":"Изображённые дорожные знаки указывают:"},"a":[{"uk":"Рекомендований напрямок руху для вантажних автомобілів.","ru":"Рекомендуемое направление движения для грузовых автомобилей.","w":{"uk":"Відповідь неповна: ці знаки рекомендують напрямок руху й самохідним машинам.","ru":"Ответ неполный: эти знаки рекомендуют направление движения и самоходным машинам."}},{"uk":"Рекомендований напрямок руху для самохідних машин.","ru":"Рекомендуемое направление движения для самоходных машин.","w":{"uk":"Відповідь неповна: ці знаки рекомендують напрямок руху насамперед вантажним автомобілям.","ru":"Ответ неполный: эти знаки рекомендуют направление движения прежде всего грузовым автомобилям."}},{"uk":"Обов'язкові напрямки руху для вантажних автомобілів і самохідних машин.","ru":"Обязательные направления движения для грузовых автомобилей и самоходных машин.","w":{"uk":"Інформаційно-вказівні знаки {s:5.31.1}–{s:5.31.3} напрямок лише рекомендують, а обов'язкові напрямки руху встановлюють наказові знаки.","ru":"Информационно-указательные знаки {s:5.31.1}–{s:5.31.3} направление лишь рекомендуют, а обязательные направления движения устанавливают предписывающие знаки."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2."}],"c":3,"e":{"uk":"Це знаки {s:5.31.1}, {s:5.31.2}, {s:5.31.3} «Напрямок руху для вантажних автомобілів»: вони показують **рекомендований** напрямок руху для вантажних автомобілів і самохідних машин ({p:33.5}).","ru":"Это знаки {s:5.31.1}, {s:5.31.2}, {s:5.31.3} «Направление движения для грузовых автомобилей»: они показывают **рекомендуемое** направление движения для грузовых автомобилей и самоходных машин ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-137-1.jpg"]},{"id":"h33-138","t":"h33","num":"33.138","q":{"uk":"Зображений дорожній знак позначає:","ru":"Изображённый дорожный знак обозначает:"},"a":[{"uk":"Зону за довжиною для розвороту транспортних засобів; поворот ліворуч у такому місці дозволено.","ru":"Зону по длине для разворота транспортных средств; поворот налево в таком месте разрешён.","w":{"uk":"Поворот ліворуч у зоні для розвороту, позначеній знаком {s:5.30}, заборонено.","ru":"Поворот налево в зоне для разворота, обозначенной знаком {s:5.30}, запрещён."}},{"uk":"Зону за довжиною для розвороту тільки вантажних транспортних засобів; поворот ліворуч у такому місці заборонено.","ru":"Зону по длине для разворота только грузовых транспортных средств; поворот налево в таком месте запрещён.","w":{"uk":"Зона для розвороту призначена для всіх транспортних засобів, а не лише для вантажних.","ru":"Зона для разворота предназначена для всех транспортных средств, а не только для грузовых."}},{"uk":"Зону за довжиною для розвороту транспортних засобів; поворот ліворуч у такому місці заборонено.","ru":"Зону по длине для разворота транспортных средств; поворот налево в таком месте запрещён."}],"c":2,"e":{"uk":"Це знак {s:5.30} «Зона для розвороту» (на знаку вказано її довжину — 15 м): він позначає зону за довжиною для розвороту транспортних засобів, а поворот ліворуч тут **забороняється** ({p:33.5}).","ru":"Это знак {s:5.30} «Зона для разворота» (на знаке указана её длина — 15 м): он обозначает зону по длине для разворота транспортных средств, а поворот налево здесь **запрещается** ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-138-1.jpg"]},{"id":"h33-139","t":"h33","num":"33.139","q":{"uk":"Зображений дорожній знак інформує:","ru":"Изображённый дорожный знак информирует:"},"a":[{"uk":"Про початок додаткової смуги зліва або початок смуги гальмування перед перехрестям для повороту ліворуч або розвороту.","ru":"О начале дополнительной полосы слева или начале полосы торможения перед перекрёстком для поворота налево или разворота."},{"uk":"Про дозволені напрямки руху транспортних засобів на перехресті.","ru":"О разрешённых направлениях движения транспортных средств на перекрёстке.","w":{"uk":"Дозволені напрямки руху на перехресті показує знак {s:5.16} «Напрямки руху по смугах».","ru":"Разрешённые направления движения на перекрёстке показывает знак {s:5.16} «Направления движения по полосам»."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2.","w":{"uk":"Знак {s:5.20.2} не визначає дозволених напрямків руху на перехресті, тож відповідь 2 сюди не належить.","ru":"Знак {s:5.20.2} не определяет разрешённых направлений движения на перекрёстке, поэтому ответ 2 сюда не относится."}}],"c":0,"e":{"uk":"Це знак {s:5.20.2} «Початок додаткової смуги руху»: він позначає додаткову смугу зліва або початок смуги гальмування перед перехрестям, призначеної для повороту ліворуч або розвороту ({p:33.5}).","ru":"Это знак {s:5.20.2} «Начало дополнительной полосы движения»: он обозначает дополнительную полосу слева или начало полосы торможения перед перекрёстком, предназначенной для поворота налево или разворота ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-139-1.jpg"]},{"id":"h33-140","t":"h33","num":"33.140","q":{"uk":"Зображений дорожній знак інформує:","ru":"Изображённый дорожный знак информирует:"},"a":[{"uk":"Про наявність смуги для розгону транспортних засобів, яка прилягає з правого боку до проїзної частини.","ru":"О наличии полосы для разгона транспортных средств, примыкающей справа к проезжей части.","w":{"uk":"Прилягання смуги для розгону позначає знак {s:5.22}.","ru":"Примыкание полосы для разгона обозначает знак {s:5.22}."}},{"uk":"Про прилягання справа до проїзної частини смуги, по якій здійснюється рух транспортних засобів у тому ж напрямку.","ru":"О примыкании справа к проезжей части полосы, по которой осуществляется движение транспортных средств в том же направлении.","w":{"uk":"Прилягання додаткової смуги руху з правого боку позначає знак {s:5.23}.","ru":"Примыкание дополнительной полосы движения справа обозначает знак {s:5.23}."}},{"uk":"Про закінчення додаткової смуги або смуги розгону справа.","ru":"Об окончании дополнительной полосы или полосы разгона справа."}],"c":2,"e":{"uk":"Це знак {s:5.21.1} «Кінець додаткової смуги руху»: права смуга закінчується, і її стрілка відхиляється ліворуч; знак показує кінець додаткової смуги або смуги для розгону ({p:33.5}).","ru":"Это знак {s:5.21.1} «Конец дополнительной полосы движения»: правая полоса заканчивается, и её стрелка отклоняется влево; знак указывает на конец дополнительной полосы или полосы для разгона ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-140-1.jpg"]},{"id":"h33-141","t":"h33","num":"33.141","q":{"uk":"Зображений дорожній знак інформує:","ru":"Изображённый дорожный знак информирует:"},"a":[{"uk":"Про прилягання справа до проїзної частини смуги, по якій здійснюється рух транспортних засобів у тому ж напрямку.","ru":"О примыкании справа к проезжей части полосы, по которой осуществляется движение транспортных средств в том же направлении.","w":{"uk":"Прилягання додаткової смуги руху з правого боку позначає знак {s:5.23}.","ru":"Примыкание дополнительной полосы движения справа обозначает знак {s:5.23}."}},{"uk":"Про закінчення смуги для розгону.","ru":"Об окончании полосы для разгона.","w":{"uk":"Кінець смуги для розгону (праворуч) показує знак {s:5.21.1}, а тут закінчується ліва смуга.","ru":"Конец полосы для разгона (справа) показывает знак {s:5.21.1}, а здесь заканчивается левая полоса."}},{"uk":"Про закінчення смуги, призначеної для руху в даному напрямку.","ru":"Об окончании полосы, предназначенной для движения в данном направлении."},{"uk":"Відповіді 2 і 3.","ru":"Ответы 2 и 3.","w":{"uk":"Відповідь 2 неправильна: кінець смуги для розгону позначає інший знак — {s:5.21.1}.","ru":"Ответ 2 неверен: конец полосы для разгона обозначает другой знак — {s:5.21.1}."}}],"c":2,"e":{"uk":"Це знак {s:5.21.2} «Кінець додаткової смуги руху»: закінчується ліва смуга, і її стрілка відхиляється праворуч; знак показує кінець смуги, призначеної для руху в даному напрямку ({p:33.5}).","ru":"Это знак {s:5.21.2} «Конец дополнительной полосы движения»: заканчивается левая полоса, и её стрелка отклоняется вправо; знак указывает на конец полосы, предназначенной для движения в данном направлении ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-141-1.jpg"]},{"id":"h33-142","t":"h33","num":"33.142","q":{"uk":"Який із зображених дорожніх знаків інформує водіїв про місце, де смуга для розгону прилягає до основної смуги руху на одному рівні з правого боку?","ru":"Какой из изображённых дорожных знаков информирует водителей о месте, где полоса для разгона примыкает к основной полосе движения на одном уровне справа?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:5.20.1} «Початок додаткової смуги руху»: позначає початок додаткової смуги на підйом або смуги гальмування.","ru":"Знак 1 — {s:5.20.1} «Начало дополнительной полосы движения»: обозначает начало дополнительной полосы на подъём или полосы торможения."}},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:5.21.1} «Кінець додаткової смуги руху».","ru":"Знак 2 — {s:5.21.1} «Конец дополнительной полосы движения»."}},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — {s:5.27.1} «Зміна напрямку руху на дорозі з розділювальною смугою»: показує об'їзд закритої ділянки проїзної частини.","ru":"Знак 3 — {s:5.27.1} «Изменение направления движения на дороге с разделительной полосой»: показывает объезд закрытого участка проезжей части."}},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Знак 4 — {s:5.20.2} «Початок додаткової смуги руху»: позначає додаткову смугу зліва.","ru":"Знак 4 — {s:5.20.2} «Начало дополнительной полосы движения»: обозначает дополнительную полосу слева."}},{"uk":"Знак 5.","ru":"Знак 5."}],"c":4,"e":{"uk":"Знак 5 — {s:5.22} «Прилягання смуги для розгону транспортних засобів»: позначає місце, де смуга для розгону прилягає до основної смуги руху на одному рівні з правого боку ({p:33.5}).","ru":"Знак 5 — {s:5.22} «Примыкание полосы для разгона транспортных средств»: обозначает место, где полоса для разгона примыкает к основной полосе движения на одном уровне справа ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-142-1.jpg"]},{"id":"h33-143","t":"h33","num":"33.143","q":{"uk":"Який із зображених дорожніх знаків інформує про те, що додаткова смуга руху прилягає до основної смуги руху на одному рівні з правого боку?","ru":"Какой из изображённых дорожных знаков информирует о том, что дополнительная полоса движения примыкает к основной полосе движения на одном уровне справа?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:5.22}: так позначають прилягання смуги для розгону, а не додаткової смуги руху.","ru":"Знак 1 — {s:5.22}: так обозначают примыкание полосы для разгона, а не дополнительной полосы движения."}},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:5.21.1} «Кінець додаткової смуги руху».","ru":"Знак 2 — {s:5.21.1} «Конец дополнительной полосы движения»."}},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — {s:5.20.1} «Початок додаткової смуги руху»: позначає початок додаткової смуги на підйом або смуги гальмування.","ru":"Знак 3 — {s:5.20.1} «Начало дополнительной полосы движения»: обозначает начало дополнительной полосы на подъём или полосы торможения."}},{"uk":"Знак 4.","ru":"Знак 4."},{"uk":"Знак 5.","ru":"Знак 5.","w":{"uk":"Знак 5 — {s:5.28} «Смуга руху для аварійної зупинки».","ru":"Знак 5 — {s:5.28} «Полоса движения для аварийной остановки»."}}],"c":3,"e":{"uk":"Знак 4 — {s:5.23} «Прилягання додаткової смуги руху з правого боку»: інформує, що додаткова смуга руху прилягає до основної смуги руху з правого боку ({p:33.5}).","ru":"Знак 4 — {s:5.23} «Примыкание дополнительной полосы движения справа»: информирует, что дополнительная полоса движения примыкает к основной полосе движения справа ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-143-1.jpg"]},{"id":"h33-144","t":"h33","num":"33.144","q":{"uk":"Який із зображених дорожніх знаків показує напрямок об'їзду закритої для руху ділянки проїзної частини на дорозі з розділювальною смугою?","ru":"Какой из изображённых дорожных знаков показывает направление объезда закрытого для движения участка проезжей части на дороге с разделительной полосой?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — наказовий {s:4.8} «Об'їзд перешкоди з лівого боку»: він визначає бік об'їзду перешкоди, а не перехід через розділювальну смугу.","ru":"Знак 1 — предписывающий {s:4.8} «Объезд препятствия слева»: он определяет сторону объезда препятствия, а не переход через разделительную полосу."}},{"uk":"Знак 2.","ru":"Знак 2."},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — {s:5.63} «Схема об'їзду»: маршрут об'їзду ділянки дороги, тимчасово закритої для руху.","ru":"Знак 3 — {s:5.63} «Схема объезда»: маршрут объезда участка дороги, временно закрытого для движения."}},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Знак 4 — {s:5.64.3} «Напрямок об'їзду»: показує напрямок об'їзду тимчасово закритої ділянки дороги, а не зміну проїзної частини на дорозі з розділювальною смугою.","ru":"Знак 4 — {s:5.64.3} «Направление объезда»: показывает направление объезда временно закрытого участка дороги, а не смену проезжей части на дороге с разделительной полосой."}}],"c":1,"e":{"uk":"Знак 2 — {s:5.27.1} «Зміна напрямку руху на дорозі з розділювальною смугою»: він показує напрямок об'їзду закритої для руху ділянки проїзної частини на дорозі з розділювальною смугою ({p:33.5}).","ru":"Знак 2 — {s:5.27.1} «Изменение направления движения на дороге с разделительной полосой»: он показывает направление объезда закрытого для движения участка проезжей части на дороге с разделительной полосой ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-144-1.jpg"]},{"id":"h33-145","t":"h33","num":"33.145","q":{"uk":"Зображений дорожній знак інформує:","ru":"Изображённый дорожный знак информирует:"},"a":[{"uk":"Про напрямок руху для повернення на проїзну частину праворуч після об'їзду закритої для руху ділянки проїзної частини дороги з розділювальною смугою.","ru":"О направлении движения для возвращения на проезжую часть справа после объезда закрытого для движения участка проезжей части дороги с разделительной полосой."},{"uk":"Про маршрут руху на перехресті в разі заборони окремих маневрів або про дозволені напрямки руху на складному перехресті.","ru":"О маршруте движения на перекрёстке в случае запрещения отдельных манёвров или о разрешённых направлениях движения на сложном перекрёстке.","w":{"uk":"Так описано знак {s:5.62} «Схема руху».","ru":"Так описан знак {s:5.62} «Схема движения»."}},{"uk":"Про маршрут об'їзду ділянки дороги, яка тимчасово закрита для руху.","ru":"О маршруте объезда участка дороги, временно закрытого для движения.","w":{"uk":"Маршрут об'їзду тимчасово закритої ділянки дороги показує знак {s:5.63} «Схема об'їзду».","ru":"Маршрут объезда временно закрытого участка дороги показывает знак {s:5.63} «Схема объезда»."}}],"c":0,"e":{"uk":"Це знак {s:5.27.2} «Зміна напрямку руху на дорозі з розділювальною смугою»: після об'їзду закритої ділянки він показує напрямок руху для повернення на проїзну частину праворуч ({p:33.5}).","ru":"Это знак {s:5.27.2} «Изменение направления движения на дороге с разделительной полосой»: после объезда закрытого участка он показывает направление движения для возвращения на проезжую часть справа ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-145-1.jpg"]},{"id":"h33-146","t":"h33","num":"33.146","q":{"uk":"Зображений дорожній знак інформує:","ru":"Изображённый дорожный знак информирует:"},"a":[{"uk":"Про наближення до повороту дороги, на якому є в’їзд на прилеглу територію.","ru":"О приближении к повороту дороги, на котором есть въезд на прилегающую территорию.","w":{"uk":"Знак показує не поворот дороги з в'їздом на прилеглу територію, а відгалуження смуги для аварійної зупинки.","ru":"Знак показывает не поворот дороги с въездом на прилегающую территорию, а ответвление полосы для аварийной остановки."}},{"uk":"Про початок смуги гальмування.","ru":"О начале полосы торможения.","w":{"uk":"Початок смуги гальмування позначає знак {s:5.20.1} «Початок додаткової смуги руху».","ru":"Начало полосы торможения обозначает знак {s:5.20.1} «Начало дополнительной полосы движения»."}},{"uk":"Про розташування смуги, спеціально підготовленої для аварійної зупинки транспортних засобів у разі відмови гальмівної системи.","ru":"О расположении полосы, специально подготовленной для аварийной остановки транспортных средств при отказе тормозной системы."}],"c":2,"e":{"uk":"Це знак {s:5.28} «Смуга руху для аварійної зупинки»: він інформує про розташування смуги, спеціально підготовленої для аварійної зупинки транспортних засобів у разі відмови гальмової системи ({p:33.5}).","ru":"Это знак {s:5.28} «Полоса движения для аварийной остановки»: он информирует о расположении полосы, специально подготовленной для аварийной остановки транспортных средств при отказе тормозной системы ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-146-1.jpg"]},{"id":"h33-147","t":"h33","num":"33.147","q":{"uk":"Який із зображених дорожніх знаків позначає кінець пішохідної зони?","ru":"Какой из изображённых дорожных знаков обозначает конец пешеходной зоны?"},"a":[{"uk":"Знак 1.","ru":"Знак 1."},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:5.35} «Кінець житлової зони».","ru":"Знак 2 — {s:5.35} «Конец жилой зоны»."}},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — {s:5.50} «Кінець населеного пункту».","ru":"Знак 3 — {s:5.50} «Конец населённого пункта»."}},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Знак 4 — {s:5.44} «Кінець зони стоянки».","ru":"Знак 4 — {s:5.44} «Конец зоны стоянки»."}},{"uk":"Знак 5.","ru":"Знак 5.","w":{"uk":"Знак 5 — {s:3.9} «Рух пішоходів заборонено».","ru":"Знак 5 — {s:3.9} «Движение пешеходов запрещено»."}}],"c":0,"e":{"uk":"Знак 1 — {s:5.37} «Кінець пішохідної зони»: перекреслений знак {s:5.36} «Пішохідна зона» ({p:33.5}).","ru":"Знак 1 — {s:5.37} «Конец пешеходной зоны»: перечёркнутый знак {s:5.36} «Пешеходная зона» ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-147-1.jpg"]},{"id":"h33-148","t":"h33","num":"33.148","q":{"uk":"Зображеними дорожніми знаками позначаються:","ru":"Изображёнными дорожными знаками обозначаются:"},"a":[{"uk":"Місця, призначені для руху пішоходів по проїзній частині.","ru":"Места, предназначенные для движения пешеходов по проезжей части."},{"uk":"Підземні пішохідні переходи.","ru":"Подземные пешеходные переходы.","w":{"uk":"Підземні пішохідні переходи позначають знаки {s:5.40.1} і {s:5.40.2}.","ru":"Подземные пешеходные переходы обозначают знаки {s:5.40.1} и {s:5.40.2}."}},{"uk":"Надземні пішохідні переходи.","ru":"Надземные пешеходные переходы.","w":{"uk":"Надземні пішохідні переходи позначають знаки {s:5.41.1} і {s:5.41.2}.","ru":"Надземные пешеходные переходы обозначают знаки {s:5.41.1} и {s:5.41.2}."}},{"uk":"Пішохідні доріжки.","ru":"Пешеходные дорожки.","w":{"uk":"Пішохідну доріжку позначає круглий наказовий знак {s:4.16} «Доріжка для пішоходів».","ru":"Пешеходную дорожку обозначает круглый предписывающий знак {s:4.16} «Дорожка для пешеходов»."}}],"c":0,"e":{"uk":"Це знаки {s:5.38.1} і {s:5.38.2} «Пішохідний перехід»: ними позначають ділянку проїзної частини, призначену для руху пішоходів через дорогу ({p:1.10}); знак {s:5.38.1} установлюють праворуч від дороги на ближній межі переходу, а {s:5.38.2} — ліворуч на дальній межі ({p:33.5}).","ru":"Это знаки {s:5.38.1} и {s:5.38.2} «Пешеходный переход»: ими обозначают участок проезжей части, предназначенный для движения пешеходов через дорогу ({p:1.10}); знак {s:5.38.1} устанавливают справа от дороги на ближней границе перехода, а {s:5.38.2} — слева на дальней границе ({p:33.5})."},"ref":["33.5","1.10"],"pic":["img/hsc/33-148-1.jpg"]},{"id":"h33-149","t":"h33","num":"33.149","q":{"uk":"Зображений дорожній знак інформує:","ru":"Изображённый дорожный знак информирует:"},"a":[{"uk":"Про можливість використання дороги.","ru":"О возможности использования дороги.","w":{"uk":"Про можливість руху гірською дорогою (через перевал) інформує знак {s:5.56} «Можливість використання дороги».","ru":"О возможности движения по горной дороге (через перевал) информирует знак {s:5.56} «Возможность использования дороги»."}},{"uk":"Про відстань до населених пунктів.","ru":"О расстоянии до населённых пунктов.","w":{"uk":"Відстані до населених пунктів зазначає знак {s:5.61} «Покажчик відстаней».","ru":"Расстояния до населённых пунктов указывает знак {s:5.61} «Указатель расстояний»."}},{"uk":"Про швидкісні обмеження, що запроваджують на даній дорозі.","ru":"О скоростных ограничениях, которые вводятся на данной дороге.","w":{"uk":"Знак повідомляє не обмеження на конкретній дорозі, а загальні обмеження швидкості, що діють на всій території України, і до того ж — строки ввімкнення денних ходових вогнів.","ru":"Знак сообщает не ограничения на конкретной дороге, а общие ограничения скорости, действующие на всей территории Украины, и к тому же — сроки включения дневных ходовых огней."}},{"uk":"Про загальні обмеження швидкості та строк застосування денних ходових вогнів (ближнього світла фар).","ru":"Об общих ограничениях скорости и сроках применения дневных ходовых огней (ближнего света фар)."}],"c":3,"e":{"uk":"Це знак {s:5.55} «Загальні обмеження швидкості та строк застосування денних ходових вогнів (ближнього світла фар)»: він інформує про загальні обмеження швидкості на території України (у населених пунктах, поза ними й на автомагістралях) і про строки обов'язкового ввімкнення денних ходових вогнів (ближнього світла фар) поза населеними пунктами ({p:33.5}).","ru":"Это знак {s:5.55} «Общие ограничения скорости и сроки применения дневных ходовых огней (ближнего света фар)»: он информирует об общих ограничениях скорости на территории Украины (в населённых пунктах, вне их и на автомагистралях) и о сроках обязательного включения дневных ходовых огней (ближнего света фар) вне населённых пунктов ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-149-1.jpg"]},{"id":"h33-150","t":"h33","num":"33.150","q":{"uk":"На якому із зображених дорожніх знаків може змінюватися інформація?","ru":"На каком из изображённых дорожных знаков может изменяться информация?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:5.55}: загальні обмеження швидкості та строки ввімкнення денних ходових вогнів на ньому постійні.","ru":"Знак 1 — {s:5.55}: общие ограничения скорости и сроки включения дневных ходовых огней на нём постоянные."}},{"uk":"Знак 2.","ru":"Знак 2."},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — {s:5.51} «Початок населеного пункту»: назва населеного пункту на ньому не змінюється.","ru":"Знак 3 — {s:5.51} «Начало населённого пункта»: название населённого пункта на нём не меняется."}},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Знак 4 — {s:5.57} «Попередній покажчик напрямків» з постійною інформацією про напрямки руху.","ru":"Знак 4 — {s:5.57} «Предварительный указатель направлений» с постоянной информацией о направлениях движения."}},{"uk":"Знак 5.","ru":"Знак 5.","w":{"uk":"Знак 5 — {s:5.59} «Покажчик напрямку» з постійною інформацією.","ru":"Знак 5 — {s:5.59} «Указатель направления» с постоянной информацией."}}],"c":1,"e":{"uk":"Знак 2 — {s:5.56} «Можливість використання дороги»: таблички 1–3 на ньому **змінні** — табличка 1 зеленого кольору з написом «Відкрито» дозволяє рух гірською дорогою (через перевал), а червоного з написом «Закрито» — забороняє ({p:33.5}).","ru":"Знак 2 — {s:5.56} «Возможность использования дороги»: таблички 1–3 на нём **сменные** — табличка 1 зелёного цвета с надписью «Открыто» разрешает движение по горной дороге (через перевал), а красного с надписью «Закрыто» — запрещает ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-150-1.jpg"]},{"id":"h33-151","t":"h33","num":"33.151","q":{"uk":"Зображений дорожній знак встановлюється:","ru":"Изображённый дорожный знак устанавливается:"},"a":[{"uk":"В населеному пункті.","ru":"В населённом пункте.","w":{"uk":"У населеному пункті знаки {s:5.57}–{s:5.60} повинні мати білий фон; синіми чи зеленими там можуть бути лише вставки.","ru":"В населённом пункте знаки {s:5.57}–{s:5.60} должны иметь белый фон; синими или зелёными там могут быть только вставки."}},{"uk":"Поза населеним пунктом.","ru":"Вне населённого пункта."}],"c":1,"e":{"uk":"Це знак {s:5.57} «Попередній покажчик напрямків» на зеленому фоні. Знаки {s:5.57}–{s:5.60} поза населеним пунктом мають зелений фон на автомагістралі або синій на іншій дорозі, а в населеному пункті — білий ({p:33.5}); отже, цей знак установлено поза населеним пунктом.","ru":"Это знак {s:5.57} «Предварительный указатель направлений» на зелёном фоне. Знаки {s:5.57}–{s:5.60} вне населённого пункта имеют зелёный фон на автомагистрали или синий на другой дороге, а в населённом пункте — белый ({p:33.5}); следовательно, этот знак установлен вне населённого пункта."},"ref":["33.5"],"pic":["img/hsc/33-151-1.jpg"]},{"id":"h33-152","t":"h33","num":"33.152","q":{"uk":"Який із дорожніх знаків інформує про номер і напрямок маршруту (дороги)?","ru":"Какой из дорожных знаков информирует о номере и направлении маршрута (дороги)?"},"a":[{"uk":"Знак 1.","ru":"Знак 1."},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:5.68} «Кілометровий знак»: показує відстань від початку дороги до місця встановлення знака.","ru":"Знак 2 — {s:5.68} «Километровый знак»: показывает расстояние от начала дороги до места установки знака."}},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — {s:5.51} «Початок населеного пункту» з його назвою.","ru":"Знак 3 — {s:5.51} «Начало населённого пункта» с его названием."}}],"c":0,"e":{"uk":"Знак 1 — «Номер і напрямок маршруту (дороги)» ({s:5.67.1}–{s:5.67.3}): номер дороги Т-25-01 зі стрілкою, що показує її напрямок; такі знаки застосовують перед перехрестям ({p:33.5}).","ru":"Знак 1 — «Номер и направление маршрута (дороги)» ({s:5.67.1}–{s:5.67.3}): номер дороги Т-25-01 со стрелкой, показывающей её направление; такие знаки применяют перед перекрёстком ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-152-1.jpg"]},{"id":"h33-153","t":"h33","num":"33.153","q":{"uk":"Зображений дорожній знак позначає:","ru":"Изображённый дорожный знак обозначает:"},"a":[{"uk":"Початок населеного пункту, в якому діють вимоги Правил дорожнього руху, що визначають порядок руху в населених пунктах.","ru":"Начало населённого пункта, в котором действуют требования Правил дорожного движения, определяющие порядок движения в населённых пунктах.","w":{"uk":"Такий населений пункт позначає знак {s:5.49} — білий знак з назвою населеного пункту.","ru":"Такой населённый пункт обозначает знак {s:5.49} — белый знак с названием населённого пункта."}},{"uk":"Початок населеного пункту, в якому на даній дорозі не діють вимоги Правил дорожнього руху, що визначають порядок руху в населених пунктах.","ru":"Начало населённого пункта, в котором на данной дороге не действуют требования Правил дорожного движения, определяющие порядок движения в населённых пунктах.","w":{"uk":"Такий населений пункт позначає синій знак {s:5.51} з назвою населеного пункту.","ru":"Такой населённый пункт обозначает синий знак {s:5.51} с названием населённого пункта."}},{"uk":"Межу, де починається забудова безпосередньо поблизу проїзної частини (за умови наявності такої забудови). Означає обмеження максимальної дозволеної швидкості до 50 км/год.","ru":"Границу, где начинается застройка непосредственно вблизи проезжей части (при наличии такой застройки). Означает ограничение максимальной разрешённой скорости до 50 км/ч."}],"c":2,"e":{"uk":"Це знак {s:5.53} «Початок щільної забудови» (силует забудови): його застосовують у населених пунктах, позначених знаком {s:5.51}, на межі, де починається забудова безпосередньо поблизу проїзної частини; він означає обмеження максимальної швидкості до 50 км/год ({p:33.5}).","ru":"Это знак {s:5.53} «Начало плотной застройки» (силуэт застройки): его применяют в населённых пунктах, обозначенных знаком {s:5.51}, на границе, где начинается застройка непосредственно вблизи проезжей части; он означает ограничение максимальной скорости до 50 км/ч ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-153-1.jpg"]},{"id":"h33-154","t":"h33","num":"33.154","q":{"uk":"Який із зображених дорожніх знаків застосовується в населених пунктах, для виділення межі закінчення забудови населеного пункту, розташованої безпосередньо поблизу проїзної частини (за умови подальшої відсутності такої забудови)?","ru":"Какой из изображённых дорожных знаков применяется в населённых пунктах для выделения границы окончания застройки населённого пункта, расположенной непосредственно вблизи проезжей части (при дальнейшем отсутствии такой застройки)?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:5.35} «Кінець житлової зони».","ru":"Знак 1 — {s:5.35} «Конец жилой зоны»."}},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:5.4} «Кінець дороги для автомобілів».","ru":"Знак 2 — {s:5.4} «Конец дороги для автомобилей»."}},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — {s:3.32} «Кінець зони обмеження максимальної швидкості».","ru":"Знак 3 — {s:3.32} «Конец зоны ограничения максимальной скорости»."}},{"uk":"Знак 4.","ru":"Знак 4."},{"uk":"Знак 5.","ru":"Знак 5.","w":{"uk":"Знак 5 — {s:5.52} «Кінець населеного пункту»: позначає кінець усього населеного пункту, позначеного знаком {s:5.51}, а не лише забудови біля дороги.","ru":"Знак 5 — {s:5.52} «Конец населённого пункта»: обозначает конец всего населённого пункта, обозначенного знаком {s:5.51}, а не только застройки у дороги."}}],"c":3,"e":{"uk":"Знак 4 — {s:5.54} «Кінець щільної забудови» (перекреслений силует забудови): його застосовують у населених пунктах, позначених знаком {s:5.51}, щоб виділити межу закінчення забудови поблизу проїзної частини ({p:33.5}).","ru":"Знак 4 — {s:5.54} «Конец плотной застройки» (перечёркнутый силуэт застройки): его применяют в населённых пунктах, обозначенных знаком {s:5.51}, чтобы выделить границу окончания застройки вблизи проезжей части ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-154-1.jpg"]},{"id":"h33-155","t":"h33","num":"33.155","q":{"uk":"Зображений дорожній знак позначає:","ru":"Изображённый дорожный знак обозначает:"},"a":[{"uk":"Те, що за цим знаком тимчасово змінено схему руху і (або) встановлено нові дорожні знаки.","ru":"То, что за этим знаком временно изменена схема движения и (или) установлены новые дорожные знаки.","w":{"uk":"Відповідь неповна: знак застосовують і в разі постійної зміни схеми руху — протягом не менш як трьох місяців.","ru":"Ответ неполный: знак применяют и при постоянном изменении схемы движения — в течение не менее трёх месяцев."}},{"uk":"Те, що за цим знаком на постійній основі змінено схему руху і (або) встановлено нові дорожні знаки.","ru":"То, что за этим знаком на постоянной основе изменена схема движения и (или) установлены новые дорожные знаки.","w":{"uk":"Відповідь неповна: знак застосовують і в разі тимчасової зміни схеми руху.","ru":"Ответ неполный: знак применяют и при временном изменении схемы движения."}},{"uk":"Обидві відповіді правильні.","ru":"Оба ответа правильные."}],"c":2,"e":{"uk":"Це знак {s:5.70} «Зміна схеми руху»: він позначає, що за ним **тимчасово або постійно** змінено схему руху та (або) встановлено нові дорожні знаки ({p:33.5}).","ru":"Это знак {s:5.70} «Изменение схемы движения»: он обозначает, что за ним **временно или постоянно** изменена схема движения и (или) установлены новые дорожные знаки ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-155-1.jpg"]},{"id":"h33-156","t":"h33","num":"33.156","q":{"uk":"Який із зображених дорожніх знаків інформує про місце розташування аеропорту?","ru":"Какой из изображённых дорожных знаков информирует о месте расположения аэропорта?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — попереджувальний {s:1.18} «Низьколітаючі літаки»: попереджає про ділянку поблизу аеродрому, над якою низько пролітають літаки, а не вказує на аеропорт.","ru":"Знак 1 — предупреждающий {s:1.18} «Низколетящие самолёты»: предупреждает об участке вблизи аэродрома, над которым низко пролетают самолёты, а не указывает на аэропорт."}},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:5.43} «Зона стоянки».","ru":"Знак 2 — {s:5.43} «Зона стоянки»."}},{"uk":"Знак 3","ru":"Знак 3.","w":{"uk":"Знак 3 — {s:5.42.2} «Місце для стоянки»: позначає криті (підземні та надземні) стоянки.","ru":"Знак 3 — {s:5.42.2} «Место стоянки»: обозначает крытые (подземные и надземные) стоянки."}},{"uk":"Знак 4.","ru":"Знак 4."}],"c":3,"e":{"uk":"Знак 4 — {s:5.71} «Аеропорт»: його встановлюють безпосередньо біля аеропорту, а якщо той розташований осторонь дороги, — біля повороту до нього ({p:33.5}).","ru":"Знак 4 — {s:5.71} «Аэропорт»: его устанавливают непосредственно у аэропорта, а если тот расположен в стороне от дороги — у поворота к нему ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-156-1.jpg"]},{"id":"h33-157","t":"h33","num":"33.157","q":{"uk":"Зображений дорожній знак позначає:","ru":"Изображённый дорожный знак обозначает:"},"a":[{"uk":"Початок населеного пункту, в якому діють вимоги даних Правил дорожнього руху, що визначають порядок руху в населених пунктах.","ru":"Начало населённого пункта, в котором действуют требования данных Правил дорожного движения, определяющие порядок движения в населённых пунктах.","w":{"uk":"Такий населений пункт позначає знак {s:5.49} на білому фоні.","ru":"Такой населённый пункт обозначает знак {s:5.49} на белом фоне."}},{"uk":"Початок населеного пункту, в якому на даній дорозі не діють вимоги Правил дорожнього руху, що визначають порядок руху в населених пунктах.","ru":"Начало населённого пункта, в котором на данной дороге не действуют требования Правил дорожного движения, определяющие порядок движения в населённых пунктах."},{"uk":"Початок забудови населеного пункту безпосередньо біля проїзної частини.","ru":"Начало застройки населённого пункта непосредственно у проезжей части.","w":{"uk":"Початок забудови поблизу проїзної частини позначає знак {s:5.53} із силуетом забудови.","ru":"Начало застройки вблизи проезжей части обозначает знак {s:5.53} с силуэтом застройки."}}],"c":1,"e":{"uk":"Синій знак із назвою — {s:5.51} «Початок населеного пункту»: позначає найменування і початок населеного пункту, в якому на даній дорозі **не діють** вимоги Правил щодо руху в населених пунктах ({p:33.5}); швидкість тут визначає {p:12.6}.","ru":"Синий знак с названием — {s:5.51} «Начало населённого пункта»: обозначает наименование и начало населённого пункта, в котором на данной дороге **не действуют** требования Правил о движении в населённых пунктах ({p:33.5}); скорость здесь определяет {p:12.6}."},"ref":["33.5","12.6"],"pic":["img/hsc/33-157-1.jpg"]},{"id":"h33-158","t":"h33","num":"33.158","q":{"uk":"Зображений дорожній знак позначає:","ru":"Изображённый дорожный знак обозначает:"},"a":[{"uk":"Початок населеного пункту, в якому діють вимоги Правил дорожнього руху, що визначають порядок руху в населених пунктах.","ru":"Начало населённого пункта, в котором действуют требования Правил дорожного движения, определяющие порядок движения в населённых пунктах."},{"uk":"Початок населеного пункту, в якому не діють вимоги Правил дорожнього руху, що визначають порядок руху в населених пунктах.","ru":"Начало населённого пункта, в котором не действуют требования Правил дорожного движения, определяющие порядок движения в населённых пунктах.","w":{"uk":"Такий населений пункт позначає синій знак {s:5.51}.","ru":"Такой населённый пункт обозначает синий знак {s:5.51}."}},{"uk":"Початок щільної забудови безпосередньо біля проїзної частини.","ru":"Начало плотной застройки непосредственно у проезжей части.","w":{"uk":"Початок щільної забудови позначає знак {s:5.53} із силуетом забудови.","ru":"Начало плотной застройки обозначает знак {s:5.53} с силуэтом застройки."}}],"c":0,"e":{"uk":"Білий знак із назвою — {s:5.49} «Початок населеного пункту»: позначає найменування і початок забудови населеного пункту, в якому діють вимоги Правил щодо руху в населених пунктах ({p:33.5}), зокрема обмеження швидкості до 50 км/год ({p:12.4}).","ru":"Белый знак с названием — {s:5.49} «Начало населённого пункта»: обозначает наименование и начало застройки населённого пункта, в котором действуют требования Правил о движении в населённых пунктах ({p:33.5}), в частности ограничение скорости до 50 км/ч ({p:12.4})."},"ref":["33.5","12.4"],"pic":["img/hsc/33-158-1.jpg"]},{"id":"h33-159","t":"h33","num":"33.159","q":{"uk":"Зображений дорожній знак позначає:","ru":"Изображённый дорожный знак обозначает:"},"a":[{"uk":"Початок посадкового майданчика автобуса.","ru":"Начало посадочной площадки автобуса."},{"uk":"Початок смуги для руху маршрутних транспортних засобів.","ru":"Начало полосы для движения маршрутных транспортных средств.","w":{"uk":"Смугу для руху маршрутних транспортних засобів позначає знак {s:5.11}.","ru":"Полосу для движения маршрутных транспортных средств обозначает знак {s:5.11}."}},{"uk":"Початок смуги для руху тільки автобусів.","ru":"Начало полосы для движения только автобусов.","w":{"uk":"Знак позначає пункт зупинки, а не смугу руху; смугу для маршрутних транспортних засобів позначає знак {s:5.11}.","ru":"Знак обозначает пункт остановки, а не полосу движения; полосу для маршрутных транспортных средств обозначает знак {s:5.11}."}}],"c":0,"e":{"uk":"Це знак {s:5.45.1} «Пункт зупинки автобуса»: позначає початок посадкового майданчика автобуса, що рухається за встановленим маршрутом ({p:33.5}).","ru":"Это знак {s:5.45.1} «Пункт остановки автобуса»: обозначает начало посадочной площадки автобуса, движущегося по установленному маршруту ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-159-1.jpg"]},{"id":"h33-160","t":"h33","num":"33.160","q":{"uk":"Якими із зображених дорожніх знаків позначаються місця, призначені для переходу пішоходами по проїзній частині?","ru":"Какими из изображённых дорожных знаков обозначаются места, предназначенные для перехода пешеходами по проезжей части?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знаки 1 зі сходами позначають пішохідний перехід в іншому рівні (підземний чи надземний), а не перехід по проїзній частині.","ru":"Знаки 1 с лестницей обозначают пешеходный переход в другом уровне (подземный или надземный), а не переход по проезжей части."}},{"uk":"Знак 2.","ru":"Знак 2."},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знаки 3 зі сходами теж позначають підземний чи надземний пішохідний перехід, де пішоходи не виходять на проїзну частину.","ru":"Знаки 3 с лестницей тоже обозначают подземный или надземный пешеходный переход, где пешеходы не выходят на проезжую часть."}},{"uk":"Знаки 1, 2, 3.","ru":"Знаки 1, 2, 3.","w":{"uk":"Знаки зі сходами (1 і 3) позначають переходи в іншому рівні — підземні ({s:5.40.1}, {s:5.40.2}) і надземні ({s:5.41.1}, {s:5.41.2}).","ru":"Знаки с лестницей (1 и 3) обозначают переходы в другом уровне — подземные ({s:5.40.1}, {s:5.40.2}) и надземные ({s:5.41.1}, {s:5.41.2})."}}],"c":1,"e":{"uk":"Знаки 2 — {s:5.38.1} і {s:5.38.2} «Пішохідний перехід»: ними позначають ділянку проїзної частини, призначену для руху пішоходів через дорогу ({p:1.10}, {p:33.5}).","ru":"Знаки 2 — {s:5.38.1} и {s:5.38.2} «Пешеходный переход»: ими обозначают участок проезжей части, предназначенный для движения пешеходов через дорогу ({p:1.10}, {p:33.5})."},"ref":["33.5","1.10"],"pic":["img/hsc/33-160-1.jpg"]},{"id":"h33-161","t":"h33","num":"33.161","q":{"uk":"Зображеним дорожнім знаком позначаються:","ru":"Изображённым дорожным знаком обозначаются:"},"a":[{"uk":"Місця, призначені для руху пішоходів по проїзній частині.","ru":"Места, предназначенные для движения пешеходов по проезжей части.","w":{"uk":"Перехід по проїзній частині позначають знаки {s:5.38.1} і {s:5.38.2} із «зеброю» в білому трикутнику.","ru":"Переход по проезжей части обозначают знаки {s:5.38.1} и {s:5.38.2} с «зеброй» в белом треугольнике."}},{"uk":"Підземні пішохідні переходи.","ru":"Подземные пешеходные переходы."},{"uk":"Надземні пішохідні переходи.","ru":"Надземные пешеходные переходы.","w":{"uk":"Надземний пішохідний перехід позначають знаки {s:5.41.1} і {s:5.41.2}.","ru":"Надземный пешеходный переход обозначают знаки {s:5.41.1} и {s:5.41.2}."}},{"uk":"Пішохідні доріжки.","ru":"Пешеходные дорожки.","w":{"uk":"Пішохідну доріжку позначає круглий наказовий знак {s:4.16}.","ru":"Пешеходную дорожку обозначает круглый предписывающий знак {s:4.16}."}}],"c":1,"e":{"uk":"Це знак «Підземний пішохідний перехід» ({s:5.40.1}, {s:5.40.2}): пішохід спускається сходами ({p:33.5}).","ru":"Это знак «Подземный пешеходный переход» ({s:5.40.1}, {s:5.40.2}): пешеход спускается по лестнице ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-161-1.jpg"]},{"id":"h33-162","t":"h33","num":"33.162","q":{"uk":"Зображеним дорожнім знаком позначаються:","ru":"Изображённым дорожным знаком обозначаются:"},"a":[{"uk":"Місця, призначені для руху пішоходів по проїзній частині.","ru":"Места, предназначенные для движения пешеходов по проезжей части.","w":{"uk":"Перехід по проїзній частині позначають знаки {s:5.38.1} і {s:5.38.2} із «зеброю» в білому трикутнику.","ru":"Переход по проезжей части обозначают знаки {s:5.38.1} и {s:5.38.2} с «зеброй» в белом треугольнике."}},{"uk":"Підземні пішохідні переходи.","ru":"Подземные пешеходные переходы.","w":{"uk":"Підземний пішохідний перехід позначають знаки {s:5.40.1} і {s:5.40.2}.","ru":"Подземный пешеходный переход обозначают знаки {s:5.40.1} и {s:5.40.2}."}},{"uk":"Надземні пішохідні переходи.","ru":"Надземные пешеходные переходы."},{"uk":"Пішохідні доріжки.","ru":"Пешеходные дорожки.","w":{"uk":"Пішохідну доріжку позначає круглий наказовий знак {s:4.16}.","ru":"Пешеходную дорожку обозначает круглый предписывающий знак {s:4.16}."}}],"c":2,"e":{"uk":"Це знак «Надземний пішохідний перехід» ({s:5.41.1}, {s:5.41.2}): пішохід піднімається сходами ({p:33.5}).","ru":"Это знак «Надземный пешеходный переход» ({s:5.41.1}, {s:5.41.2}): пешеход поднимается по лестнице ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-162-1.jpg"]},{"id":"h33-163","t":"h33","num":"33.163","q":{"uk":"Зображений дорожній знак застосовується:","ru":"Изображённый дорожный знак применяется:"},"a":[{"uk":"Для позначення місць і майданчиків під накриттям для стоянки транспортних засобів.","ru":"Для обозначения мест и площадок под навесом для стоянки транспортных средств.","w":{"uk":"Криті стоянки позначає інший знак — {s:5.42.2} (дах над літерою «P»).","ru":"Крытые стоянки обозначает другой знак — {s:5.42.2} (крыша над буквой «P»)."}},{"uk":"Для позначення місць і майданчиків для стоянки транспортних засобів.","ru":"Для обозначения мест и площадок для стоянки транспортных средств."},{"uk":"Для позначення місць і майданчиків з дахом для стоянки транспортних засобів, де є можливість пересадки на маршрутні транспортні засоби.","ru":"Для обозначения мест и площадок с крышей для стоянки транспортных средств, где есть возможность пересадки на маршрутные транспортные средства.","w":{"uk":"Стоянки поблизу зупинок маршрутних транспортних засобів позначають знаками {s:5.42.1} або {s:5.42.2} з табличками {s:7.28.1}–{s:7.28.4}, а тут табличок немає.","ru":"Стоянки вблизи остановок маршрутных транспортных средств обозначают знаками {s:5.42.1} или {s:5.42.2} с табличками {s:7.28.1}–{s:7.28.4}, а здесь табличек нет."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3.","w":{"uk":"Знак без даху й без табличок позначає звичайне місце для стоянки, тож відповіді 1 і 3 не підходять.","ru":"Знак без крыши и без табличек обозначает обычное место стоянки, поэтому ответы 1 и 3 не подходят."}}],"c":1,"e":{"uk":"Це знак {s:5.42.1} «Місце для стоянки»: ним позначають місця та майданчики для стоянки транспортних засобів ({p:33.5}).","ru":"Это знак {s:5.42.1} «Место стоянки»: им обозначают места и площадки для стоянки транспортных средств ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-163-1.jpg"]},{"id":"h33-164","t":"h33","num":"33.164","q":{"uk":"Зображений дорожній знак застосовується:","ru":"Изображённый дорожный знак применяется:"},"a":[{"uk":"Для позначення критих (підземних та надземних) стоянок.","ru":"Для обозначения крытых (подземных и надземных) стоянок."},{"uk":"Для позначення місць і майданчиків для стоянки транспортних засобів.","ru":"Для обозначения мест и площадок для стоянки транспортных средств.","w":{"uk":"Звичайні місця й майданчики для стоянки позначає знак {s:5.42.1} без даху.","ru":"Обычные места и площадки для стоянки обозначает знак {s:5.42.1} без крыши."}},{"uk":"Для позначення місць і майданчиків під накриттям для стоянки транспортних засобів, де є можливість пересадки на маршрутні транспортні засоби.","ru":"Для обозначения мест и площадок под навесом для стоянки транспортных средств, где есть возможность пересадки на маршрутные транспортные средства.","w":{"uk":"Можливість пересадки на маршрутний транспорт показують таблички {s:7.28.1}–{s:7.28.4}, яких тут немає.","ru":"Возможность пересадки на маршрутный транспорт показывают таблички {s:7.28.1}–{s:7.28.4}, которых здесь нет."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3.","w":{"uk":"Знак позначає саме криті стоянки; відповіді 2 і 3 стосуються інших знаків і табличок.","ru":"Знак обозначает именно крытые стоянки; ответы 2 и 3 относятся к другим знакам и табличкам."}}],"c":0,"e":{"uk":"Це знак {s:5.42.2} «Місце для стоянки» з дахом над літерою «P»: він позначає криті (підземні та надземні) стоянки ({p:33.5}).","ru":"Это знак {s:5.42.2} «Место стоянки» с крышей над буквой «P»: он обозначает крытые (подземные и надземные) стоянки ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-164-1.jpg"]},{"id":"h33-165","t":"h33","num":"33.165","q":{"uk":"Зображений дорожній знак в поєднанні з табличкою 7.28.2 застосовується:","ru":"Изображённый дорожный знак в сочетании с табличкой 7.28.2 применяется:"},"a":[{"uk":"Для позначення місць і майданчиків з дахом для стоянки транспортних засобів.","ru":"Для обозначения мест и площадок с крышей для стоянки транспортных средств.","w":{"uk":"Криті стоянки позначає знак {s:5.42.2}, а тут зображено {s:5.42.1} без даху.","ru":"Крытые стоянки обозначает знак {s:5.42.2}, а здесь изображён {s:5.42.1} без крыши."}},{"uk":"Для позначення місць і майданчиків для стоянки транспортних засобів.","ru":"Для обозначения мест и площадок для стоянки транспортных средств.","w":{"uk":"Без таблички знак {s:5.42.1} позначав би просто місце для стоянки, але табличка {s:7.28.2} уточнює, що це стоянка біля зупинки маршрутного транспорту.","ru":"Без таблички знак {s:5.42.1} обозначал бы просто место стоянки, но табличка {s:7.28.2} уточняет, что это стоянка у остановки маршрутного транспорта."}},{"uk":"Для позначення стоянки поблизу зупинки маршрутних транспортних засобів.","ru":"Для обозначения стоянки вблизи остановки маршрутных транспортных средств."},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3.","w":{"uk":"Відповідь 1 не підходить (стоянка не крита), а відповідь 2 неточна — табличка визначає спеціалізацію стоянки.","ru":"Ответ 1 не подходит (стоянка не крытая), а ответ 2 неточен — табличка определяет специализацию стоянки."}}],"c":2,"e":{"uk":"Знаки {s:5.42.1} і {s:5.42.2} з табличками {s:7.28.1}–{s:7.28.4} «Вид громадського транспорту» позначають стоянки поблизу станцій метро та зупинок маршрутних транспортних засобів ({p:33.5}); табличка {s:7.28.2} (знак «+» і автобус) інформує про можливість пересісти на маршрутний транспорт ({p:33.7}).","ru":"Знаки {s:5.42.1} и {s:5.42.2} с табличками {s:7.28.1}–{s:7.28.4} «Вид общественного транспорта» обозначают стоянки вблизи станций метро и остановок маршрутных транспортных средств ({p:33.5}); табличка {s:7.28.2} (знак «+» и автобус) информирует о возможности пересесть на маршрутный транспорт ({p:33.7})."},"ref":["33.5","33.7"],"pic":["img/hsc/33-165-1.jpg"]},{"id":"h33-166","t":"h33","num":"33.166","q":{"uk":"Зображений дорожній знак позначає:","ru":"Изображённый дорожный знак обозначает:"},"a":[{"uk":"Місце для стоянки транспортних засобів.","ru":"Место для стоянки транспортных средств.","w":{"uk":"Окреме місце для стоянки позначає знак {s:5.42.1} — без напису «ЗОНА».","ru":"Отдельное место стоянки обозначает знак {s:5.42.1} — без надписи «ЗОНА»."}},{"uk":"Зону, де дозволено стоянку транспортних засобів.","ru":"Зону, где разрешена стоянка транспортных средств."},{"uk":"Місце для посадки і висадки пасажирів.","ru":"Место для посадки и высадки пассажиров.","w":{"uk":"Знак не стосується посадки й висадки пасажирів; посадкові майданчики маршрутних транспортних засобів позначають знаки {s:5.45.1}, {s:5.46.1}, {s:5.47.1}.","ru":"Знак не касается посадки и высадки пассажиров; посадочные площадки маршрутных транспортных средств обозначают знаки {s:5.45.1}, {s:5.46.1}, {s:5.47.1}."}}],"c":1,"e":{"uk":"Це знак {s:5.43} «Зона стоянки»: позначає початок зони, де дозволено стоянку на проїзній частині або вздовж неї на умовах, зазначених на знаку чи табличках; його дія поширюється на всю позначену територію ({p:33.5}).","ru":"Это знак {s:5.43} «Зона стоянки»: обозначает начало зоны, где разрешена стоянка на проезжей части или вдоль неё на условиях, указанных на знаке или табличках; его действие распространяется на всю обозначенную территорию ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-166-1.jpg"]},{"id":"h33-167","t":"h33","num":"33.167","q":{"uk":"Зображений дорожній знак позначає:","ru":"Изображённый дорожный знак обозначает:"},"a":[{"uk":"Кінець зони обмеженої стоянки транспортних засобів.","ru":"Конец зоны ограниченной стоянки транспортных средств.","w":{"uk":"Кінець зони обмеженої стоянки позначає заборонний знак {s:3.39} — перекреслений знак {s:3.38} з червоним колом.","ru":"Конец зоны ограниченной стоянки обозначает запрещающий знак {s:3.39} — перечёркнутый знак {s:3.38} с красным кругом."}},{"uk":"Кінець зони стоянки транспортних засобів.","ru":"Конец зоны стоянки транспортных средств."},{"uk":"Місце виїзду з майданчика для стоянки транспортних засобів.","ru":"Место выезда с площадки для стоянки транспортных средств.","w":{"uk":"Окремого знака для виїзду з майданчика для стоянки немає; перекреслений знак «Зона стоянки» означає кінець зони.","ru":"Отдельного знака для выезда с площадки для стоянки нет; перечёркнутый знак «Зона стоянки» означает конец зоны."}}],"c":1,"e":{"uk":"Це знак {s:5.44} «Кінець зони стоянки» (перекреслений знак {s:5.43}): позначає кінець зони, де дозволено стоянку ({p:33.5}).","ru":"Это знак {s:5.44} «Конец зоны стоянки» (перечёркнутый знак {s:5.43}): обозначает конец зоны, где разрешена стоянка ({p:33.5})."},"ref":["33.5"],"pic":["img/hsc/33-167-1.jpg"]},{"id":"h33-168","t":"h33","num":"33.168","q":{"uk":"Який із зображених дорожніх знаків не обмежує швидкість руху транспортних засобів на ділянці дороги, на якій його встановлено?","ru":"Какой из изображённых дорожных знаков не ограничивает скорость движения транспортных средств на участке дороги, на котором он установлен?"},"a":[{"uk":"Знак 1.","ru":"Знак 1."},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:4.12} «Обмеження мінімальної швидкості»: забороняє рухатися повільніше за вказану швидкість ({p:33.4}).","ru":"Знак 2 — {s:4.12} «Ограничение минимальной скорости»: запрещает двигаться медленнее указанной скорости ({p:33.4})."}},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — {s:3.29} «Обмеження максимальної швидкості»: забороняє перевищувати вказану швидкість ({p:33.3}).","ru":"Знак 3 — {s:3.29} «Ограничение максимальной скорости»: запрещает превышать указанную скорость ({p:33.3})."}},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Знак 4 — {s:3.31} «Зона обмеження максимальної швидкості»: обмежує швидкість у межах усієї зони ({p:33.3}).","ru":"Знак 4 — {s:3.31} «Зона ограничения максимальной скорости»: ограничивает скорость в пределах всей зоны ({p:33.3})."}}],"c":0,"e":{"uk":"Знак 1 — {s:5.33} «Рекомендована швидкість»: інформаційно-вказівний знак лише рекомендує швидкість до найближчого перехрестя ({p:33.5}) і нічого не забороняє.","ru":"Знак 1 — {s:5.33} «Рекомендуемая скорость»: информационно-указательный знак лишь рекомендует скорость до ближайшего перекрёстка ({p:33.5}) и ничего не запрещает."},"ref":["33.5"],"pic":["img/hsc/33-168-1.jpg"]},{"id":"h33-169","t":"h33","num":"33.169","q":{"uk":"Зазначений дорожній знак попереджає:","ru":"Указанный дорожный знак предупреждает:"},"a":[{"uk":"Про наближення до двох рівнозначних перехресть.","ru":"О приближении к двум равнозначным перекрёсткам.","w":{"uk":"Перехрещення рівнозначних доріг позначає інший знак — {s:1.21}.","ru":"Пересечение равнозначных дорог обозначает другой знак — {s:1.21}."}},{"uk":"Про наближення до двох перехресть, де водій, перед яким встановлено цей знак, перебуває на головній дорозі.","ru":"О приближении к двум перекрёсткам, где водитель, перед которым установлен этот знак, находится на главной дороге."},{"uk":"Про наближення до двох перехресть, на першому з яких водій має перевагу в русі.","ru":"О приближении к двум перекрёсткам, на первом из которых водитель имеет преимущество в движении.","w":{"uk":"Водій перебуває на головній дорозі на **обох** перехрестях, а не лише на першому.","ru":"Водитель находится на главной дороге на **обоих** перекрёстках, а не только на первом."}}],"c":1,"e":{"uk":"Це знак {s:1.23.4} «Прилягання другорядної дороги» (спочатку ліворуч, потім праворуч): широка лінія зображує дорогу, якою рухається водій, а другорядні дороги прилягають до неї ({p:33.1}). Отже, на обох перехрестях водій перебуває на головній дорозі.","ru":"Это знак {s:1.23.4} «Примыкание второстепенной дороги» (сначала слева, затем справа): широкая линия изображает дорогу, по которой движется водитель, а второстепенные дороги примыкают к ней ({p:33.1}). Следовательно, на обоих перекрёстках водитель находится на главной дороге."},"ref":["33.1"],"pic":["img/hsc/33-169-1.jpg"]},{"id":"h33-170","t":"h33","num":"33.170","q":{"uk":"Зображений дорожній знак встановлюється:","ru":"Изображённый дорожный знак устанавливается:"},"a":[{"uk":"Безпосередньо перед залізничним переїздом без шлагбаума з однією колією.","ru":"Непосредственно перед железнодорожным переездом без шлагбаума с одним путём.","w":{"uk":"Перед переїздом без шлагбаума з однією колією встановлюють знак {s:1.29} «Одноколійна залізниця» — хрест без додаткового елемента внизу.","ru":"Перед переездом без шлагбаума с одним путём устанавливают знак {s:1.29} «Однопутная железная дорога» — крест без дополнительного элемента внизу."}},{"uk":"Безпосередньо перед залізничним переїздом без шлагбаума з двома і більше коліями.","ru":"Непосредственно перед железнодорожным переездом без шлагбаума с двумя и более путями."},{"uk":"На залізничному переїзді зі шлагбаумом з однією колією.","ru":"На железнодорожном переезде со шлагбаумом с одним путём.","w":{"uk":"Знаки {s:1.29} і {s:1.30} позначають лише переїзди без шлагбаума; про переїзд зі шлагбаумом попереджає знак {s:1.27}.","ru":"Знаки {s:1.29} и {s:1.30} обозначают только переезды без шлагбаума; о переезде со шлагбаумом предупреждает знак {s:1.27}."}},{"uk":"На залізничному переїзді зі шлагбаумом з двома і більше коліями.","ru":"На железнодорожном переезде со шлагбаумом с двумя и более путями.","w":{"uk":"Знак {s:1.30} не встановлюють на переїздах зі шлагбаумом — він позначає саме переїзд без шлагбаума.","ru":"Знак {s:1.30} не устанавливают на переездах со шлагбаумом — он обозначает именно переезд без шлагбаума."}}],"c":1,"e":{"uk":"Це знак {s:1.30} «Багатоколійна залізниця» (подвійний хрест): позначає не обладнаний шлагбаумом переїзд через залізницю з двома і більше коліями, і його встановлюють безпосередньо перед переїздом ({p:33.1}).","ru":"Это знак {s:1.30} «Многопутная железная дорога» (двойной крест): обозначает не оборудованный шлагбаумом переезд через железную дорогу с двумя и более путями, и его устанавливают непосредственно перед переездом ({p:33.1})."},"ref":["33.1"],"pic":["img/hsc/33-170-1.jpg"]},{"id":"h33-171","t":"h33","num":"33.171","q":{"uk":"Який із зображених дорожніх знаків встановлюється безпосередньо перед залізничним переїздом без шлагбаума з двома і більше коліями?","ru":"Какой из изображённых дорожных знаков устанавливается непосредственно перед железнодорожным переездом без шлагбаума с двумя и более путями?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:1.21} «Перехрещення рівнозначних доріг».","ru":"Знак 1 — {s:1.21} «Пересечение равнозначных дорог»."}},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:1.29} «Одноколійна залізниця»: його встановлюють перед переїздом без шлагбаума з однією колією.","ru":"Знак 2 — {s:1.29} «Однопутная железная дорога»: его устанавливают перед переездом без шлагбаума с одним путём."}},{"uk":"Знак 3.","ru":"Знак 3."},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Знак 4 — {s:1.28} «Залізничний переїзд без шлагбаума»: він попереджає про переїзд заздалегідь, а не встановлюється безпосередньо перед ним.","ru":"Знак 4 — {s:1.28} «Железнодорожный переезд без шлагбаума»: он предупреждает о переезде заранее, а не устанавливается непосредственно перед ним."}}],"c":2,"e":{"uk":"Знак 3 — {s:1.30} «Багатоколійна залізниця» (подвійний хрест): позначає не обладнаний шлагбаумом переїзд через залізницю з двома і більше коліями й установлюється безпосередньо перед переїздом ({p:33.1}).","ru":"Знак 3 — {s:1.30} «Многопутная железная дорога» (двойной крест): обозначает не оборудованный шлагбаумом переезд через железную дорогу с двумя и более путями и устанавливается непосредственно перед переездом ({p:33.1})."},"ref":["33.1"],"pic":["img/hsc/33-171-1.jpg"]},{"id":"h33-172","t":"h33","num":"33.172","q":{"uk":"Який із зображених дорожніх знаків встановлюється першим у разі наближення до залізничного переїзду?","ru":"Какой из изображённых дорожных знаков устанавливается первым при приближении к железнодорожному переезду?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:1.31.3} з однією смугою: його встановлюють з другим знаком {s:1.27} або {s:1.28}, тобто останнім.","ru":"Знак 1 — {s:1.31.3} с одной полосой: его устанавливают со вторым знаком {s:1.27} или {s:1.28}, то есть последним."}},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:1.31.2} з двома смугами: його встановлюють самостійно, посередині між першим і другим знаками {s:1.27} або {s:1.28}.","ru":"Знак 2 — {s:1.31.2} с двумя полосами: его устанавливают самостоятельно, посередине между первым и вторым знаками {s:1.27} или {s:1.28}."}},{"uk":"Знак 3.","ru":"Знак 3."}],"c":2,"e":{"uk":"Знак 3 — {s:1.31.1} «Наближення до залізничного переїзду» з трьома смугами: його встановлюють разом із першим (головним) по ходу руху знаком {s:1.27} або {s:1.28} ({p:33.1}).","ru":"Знак 3 — {s:1.31.1} «Приближение к железнодорожному переезду» с тремя полосами: его устанавливают вместе с первым (основным) по ходу движения знаком {s:1.27} или {s:1.28} ({p:33.1})."},"ref":["33.1"],"pic":["img/hsc/33-172-1.jpg"]},{"id":"h33-173","t":"h33","num":"33.173","q":{"uk":"Як встановлюють дані дорожні знаки перед залізничним переїздом?","ru":"Как устанавливают данные дорожные знаки перед железнодорожным переездом?"},"a":[{"uk":"Самостійно, на рівномірній відстані між знаками «Залізничний переїзд із шлагбаумом» або «Залізничний переїзд без шлагбаума».","ru":"Самостоятельно, на равном расстоянии между знаками «Железнодорожный переезд со шлагбаумом» или «Железнодорожный переезд без шлагбаума»."},{"uk":"Спільно з першим із знаків «Залізничний переїзд із шлагбаумом» або «Залізничний переїзд без шлагбаума».","ru":"Совместно с первым из знаков «Железнодорожный переезд со шлагбаумом» или «Железнодорожный переезд без шлагбаума».","w":{"uk":"З першим знаком {s:1.27} або {s:1.28} встановлюють знак {s:1.31.1} з трьома смугами (дублюючий ліворуч — {s:1.31.4}).","ru":"С первым знаком {s:1.27} или {s:1.28} устанавливают знак {s:1.31.1} с тремя полосами (дублирующий слева — {s:1.31.4})."}},{"uk":"Спільно з другим із знаків «Залізничний переїзд із шлагбаумом» або «Залізничний переїзд без шлагбаума».","ru":"Совместно со вторым из знаков «Железнодорожный переезд со шлагбаумом» или «Железнодорожный переезд без шлагбаума».","w":{"uk":"З другим знаком {s:1.27} або {s:1.28} встановлюють знаки з однією смугою — {s:1.31.3} і {s:1.31.6}.","ru":"Со вторым знаком {s:1.27} или {s:1.28} устанавливают знаки с одной полосой — {s:1.31.3} и {s:1.31.6}."}}],"c":0,"e":{"uk":"Це знаки {s:1.31.2} і {s:1.31.5} з двома смугами: їх встановлюють самостійно, на рівномірній відстані між першим і другим знаками {s:1.27} або {s:1.28} ({p:33.1}).","ru":"Это знаки {s:1.31.2} и {s:1.31.5} с двумя полосами: их устанавливают самостоятельно, на равном расстоянии между первым и вторым знаками {s:1.27} или {s:1.28} ({p:33.1})."},"ref":["33.1"],"pic":["img/hsc/33-173-1.jpg"]},{"id":"h33-174","t":"h33","num":"33.174","q":{"uk":"Який із зображених дорожніх знаків встановлюється останнім у разі наближення до залізничного переїзду?","ru":"Какой из изображённых дорожных знаков устанавливается последним при приближении к железнодорожному переезду?"},"a":[{"uk":"Знак 1.","ru":"Знак 1."},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:1.31.2} з двома смугами: його встановлюють посередині між першим і другим знаками {s:1.27} або {s:1.28}.","ru":"Знак 2 — {s:1.31.2} с двумя полосами: его устанавливают посередине между первым и вторым знаками {s:1.27} или {s:1.28}."}},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — {s:1.31.1} з трьома смугами: його встановлюють першим, разом із першим знаком {s:1.27} або {s:1.28}.","ru":"Знак 3 — {s:1.31.1} с тремя полосами: его устанавливают первым, вместе с первым знаком {s:1.27} или {s:1.28}."}}],"c":0,"e":{"uk":"Знак 1 — {s:1.31.3} з однією смугою: його встановлюють разом із другим знаком {s:1.27} або {s:1.28}, тобто найближче до переїзду ({p:33.1}).","ru":"Знак 1 — {s:1.31.3} с одной полосой: его устанавливают вместе со вторым знаком {s:1.27} или {s:1.28}, то есть ближе всего к переезду ({p:33.1})."},"ref":["33.1"],"pic":["img/hsc/33-174-1.jpg"]},{"id":"h33-175","t":"h33","num":"33.175","q":{"uk":"Який із зображених дорожніх знаків попереджає про наближення до нерегульованого пішохідного переходу?","ru":"Какой из изображённых дорожных знаков предупреждает о приближении к нерегулируемому пешеходному переходу?"},"a":[{"uk":"Знак 1.","ru":"Знак 1."},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:1.33} «Діти»: ділянка, де можлива поява дітей з території дитячого закладу.","ru":"Знак 2 — {s:1.33} «Дети»: участок, где возможно появление детей с территории детского учреждения."}},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — інформаційно-вказівний {s:5.38.1} «Пішохідний перехід»: він позначає сам перехід, а не попереджає про наближення до нього.","ru":"Знак 3 — информационно-указательный {s:5.38.1} «Пешеходный переход»: он обозначает сам переход, а не предупреждает о приближении к нему."}},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Знак 4 — {s:1.34} «Виїзд велосипедистів»: попереджає про можливу появу велосипедистів або перехрещення з велосипедною доріжкою.","ru":"Знак 4 — {s:1.34} «Выезд велосипедистов»: предупреждает о возможном появлении велосипедистов или пересечении с велосипедной дорожкой."}},{"uk":"Знак 5.","ru":"Знак 5.","w":{"uk":"Знак 5 — {s:1.24} «Світлофорне регулювання»: попереджає про перехрестя, перехід чи ділянку, рух на яких регулюється світлофором, тобто про **регульований** перехід.","ru":"Знак 5 — {s:1.24} «Светофорное регулирование»: предупреждает о перекрёстке, переходе или участке, движение на которых регулируется светофором, то есть о **регулируемом** переходе."}}],"c":0,"e":{"uk":"Знак 1 — попереджувальний {s:1.32} «Пішохідний перехід»: попереджає про наближення до нерегульованого пішохідного переходу, позначеного відповідними знаками або розміткою ({p:33.1}).","ru":"Знак 1 — предупреждающий {s:1.32} «Пешеходный переход»: предупреждает о приближении к нерегулируемому пешеходному переходу, обозначенному соответствующими знаками или разметкой ({p:33.1})."},"ref":["33.1"],"pic":["img/hsc/33-175-1.jpg"]},{"id":"h33-176","t":"h33","num":"33.176","q":{"uk":"Зображений дорожній знак попереджає про наближення до:","ru":"Изображённый дорожный знак предупреждает о приближении к:"},"a":[{"uk":"Нерегульованого пішохідного переходу.","ru":"Нерегулируемому пешеходному переходу."},{"uk":"Будь-якого пішохідного переходу.","ru":"Любому пешеходному переходу.","w":{"uk":"Про регульований пішохідний перехід попереджає інший знак — {s:1.24} «Світлофорне регулювання».","ru":"О регулируемом пешеходном переходе предупреждает другой знак — {s:1.24} «Светофорное регулирование»."}},{"uk":"Місця перетину велосипедної доріжки.","ru":"Месту пересечения велосипедной дорожки.","w":{"uk":"Про перехрещення з велосипедною доріжкою попереджає знак {s:1.34} «Виїзд велосипедистів».","ru":"О пересечении с велосипедной дорожкой предупреждает знак {s:1.34} «Выезд велосипедистов»."}},{"uk":"Місця, на якому можлива поява дітей.","ru":"Месту, где возможно появление детей.","w":{"uk":"Про можливу появу дітей попереджає знак {s:1.33} «Діти».","ru":"О возможном появлении детей предупреждает знак {s:1.33} «Дети»."}}],"c":0,"e":{"uk":"Це знак {s:1.32} «Пішохідний перехід»: він попереджає саме про **нерегульований** пішохідний перехід, позначений знаками або розміткою ({p:33.1}).","ru":"Это знак {s:1.32} «Пешеходный переход»: он предупреждает именно о **нерегулируемом** пешеходном переходе, обозначенном знаками или разметкой ({p:33.1})."},"ref":["33.1"],"pic":["img/hsc/33-176-1.jpg"]},{"id":"h33-177","t":"h33","num":"33.177","q":{"uk":"Який із зображених дорожніх знаків встановлюється перед ділянкою дороги, на якій можлива поява дітей з території дитячого закладу, прилеглого безпосередньо до дороги?","ru":"Какой из изображённых дорожных знаков устанавливается перед участком дороги, на котором возможно появление детей с территории детского учреждения, непосредственно прилегающей к дороге?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:1.27} «Залізничний переїзд зі шлагбаумом».","ru":"Знак 1 — {s:1.27} «Железнодорожный переезд со шлагбаумом»."}},{"uk":"Знак 2.","ru":"Знак 2."},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — {s:1.32} «Пішохідний перехід»: попереджає про нерегульований пішохідний перехід.","ru":"Знак 3 — {s:1.32} «Пешеходный переход»: предупреждает о нерегулируемом пешеходном переходе."}}],"c":1,"e":{"uk":"Знак 2 — {s:1.33} «Діти»: позначає ділянку дороги, на якій можлива поява дітей з території дитячого закладу, що прилягає безпосередньо до дороги ({p:33.1}).","ru":"Знак 2 — {s:1.33} «Дети»: обозначает участок дороги, на котором возможно появление детей с территории детского учреждения, прилегающей непосредственно к дороге ({p:33.1})."},"ref":["33.1"],"pic":["img/hsc/33-177-1.jpg"]},{"id":"h33-178","t":"h33","num":"33.178","q":{"uk":"Зображений дорожній знак встановлюється:","ru":"Изображённый дорожный знак устанавливается:"},"a":[{"uk":"Безпосередньо перед залізничним переїздом без шлагбаума з однією колією.","ru":"Непосредственно перед железнодорожным переездом без шлагбаума с одним путём."},{"uk":"Безпосередньо перед залізничним переїздом без шлагбаума з двома і більше коліями.","ru":"Непосредственно перед железнодорожным переездом без шлагбаума с двумя и более путями.","w":{"uk":"Перед переїздом без шлагбаума з двома і більше коліями встановлюють знак {s:1.30} «Багатоколійна залізниця» — подвійний хрест.","ru":"Перед переездом без шлагбаума с двумя и более путями устанавливают знак {s:1.30} «Многопутная железная дорога» — двойной крест."}},{"uk":"На залізничному переїзді зі шлагбаумом з однією колією.","ru":"На железнодорожном переезде со шлагбаумом с одним путём.","w":{"uk":"Знаки {s:1.29} і {s:1.30} позначають лише переїзди без шлагбаума; про переїзд зі шлагбаумом попереджає знак {s:1.27}.","ru":"Знаки {s:1.29} и {s:1.30} обозначают только переезды без шлагбаума; о переезде со шлагбаумом предупреждает знак {s:1.27}."}},{"uk":"На залізничному переїзді зі шлагбаумом з двома і більше коліями.","ru":"На железнодорожном переезде со шлагбаумом с двумя и более путями.","w":{"uk":"Знак {s:1.29} не встановлюють на переїздах зі шлагбаумом — до того ж він стосується лише однієї колії.","ru":"Знак {s:1.29} не устанавливают на переездах со шлагбаумом — к тому же он касается только одного пути."}}],"c":0,"e":{"uk":"Це знак {s:1.29} «Одноколійна залізниця» (одинарний хрест): позначає не обладнаний шлагбаумом переїзд через залізницю з однією колією, і його встановлюють безпосередньо перед переїздом ({p:33.1}).","ru":"Это знак {s:1.29} «Однопутная железная дорога» (одинарный крест): обозначает не оборудованный шлагбаумом переезд через железную дорогу с одним путём, и его устанавливают непосредственно перед переездом ({p:33.1})."},"ref":["33.1"],"pic":["img/hsc/33-178-1.jpg"]},{"id":"h33-179","t":"h33","num":"33.179","q":{"uk":"Який із зображених дорожніх знаків встановлюється безпосередньо перед залізничним переїздом без шлагбаума з однією колією?","ru":"Какой из изображённых дорожных знаков устанавливается непосредственно перед железнодорожным переездом без шлагбаума с одним путём?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:1.21} «Перехрещення рівнозначних доріг».","ru":"Знак 1 — {s:1.21} «Пересечение равнозначных дорог»."}},{"uk":"Знак 2.","ru":"Знак 2."},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — {s:1.30} «Багатоколійна залізниця»: його встановлюють перед переїздом з двома і більше коліями.","ru":"Знак 3 — {s:1.30} «Многопутная железная дорога»: его устанавливают перед переездом с двумя и более путями."}},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Знак 4 — {s:1.28} «Залізничний переїзд без шлагбаума»: він попереджає про переїзд заздалегідь, а не встановлюється безпосередньо перед ним.","ru":"Знак 4 — {s:1.28} «Железнодорожный переезд без шлагбаума»: он предупреждает о переезде заранее, а не устанавливается непосредственно перед ним."}}],"c":1,"e":{"uk":"Знак 2 — {s:1.29} «Одноколійна залізниця» (одинарний хрест): позначає не обладнаний шлагбаумом переїзд через залізницю з однією колією й установлюється безпосередньо перед переїздом ({p:33.1}).","ru":"Знак 2 — {s:1.29} «Однопутная железная дорога» (одинарный крест): обозначает не оборудованный шлагбаумом переезд через железную дорогу с одним путём и устанавливается непосредственно перед переездом ({p:33.1})."},"ref":["33.1"],"pic":["img/hsc/33-179-1.jpg"]},{"id":"h33-180","t":"h33","num":"33.180","q":{"uk":"Про що інформує даний дорожній знак?","ru":"О чём информирует данный дорожный знак?"},"a":[{"uk":"Про наближення до перехрестя, рух на якому, регулюється світлофором.","ru":"О приближении к перекрёстку, движение на котором регулируется светофором.","w":{"uk":"Відповідь неповна: знак попереджає також про регульований пішохідний перехід і ділянку дороги.","ru":"Ответ неполный: знак предупреждает также о регулируемом пешеходном переходе и участке дороги."}},{"uk":"Про наближення до пішохідного переходу, рух на якому, регулюється світлофором.","ru":"О приближении к пешеходному переходу, движение на котором регулируется светофором.","w":{"uk":"Відповідь неповна: знак попереджає також про регульоване перехрестя і ділянку дороги.","ru":"Ответ неполный: знак предупреждает также о регулируемом перекрёстке и участке дороги."}},{"uk":"Про наближення до ділянки дороги, рух на якій, регулюється світлофором.","ru":"О приближении к участку дороги, движение на котором регулируется светофором.","w":{"uk":"Відповідь неповна: знак попереджає також про регульоване перехрестя і пішохідний перехід.","ru":"Ответ неполный: знак предупреждает также о регулируемом перекрёстке и пешеходном переходе."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2.","w":{"uk":"Відповідь неповна: знак застосовують і перед ділянкою дороги, рух на якій регулюється світлофором.","ru":"Ответ неполный: знак применяют и перед участком дороги, движение на котором регулируется светофором."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3."}],"c":4,"e":{"uk":"Це знак {s:1.24} «Світлофорне регулювання»: він попереджає про перехрестя, пішохідний перехід **або** ділянку дороги, рух на яких регулюється світлофором ({p:33.1}).","ru":"Это знак {s:1.24} «Светофорное регулирование»: он предупреждает о перекрёстке, пешеходном переходе **или** участке дороги, движение на которых регулируется светофором ({p:33.1})."},"ref":["33.1"],"pic":["img/hsc/33-180-1.jpg"]},{"id":"h33-181","t":"h33","num":"33.181","q":{"uk":"Зазначений дорожній знак попереджає:","ru":"Указанный дорожный знак предупреждает:"},"a":[{"uk":"Про наближення до набережної.","ru":"О приближении к набережной.","w":{"uk":"Про виїзд на набережну або берег попереджає знак {s:1.8} «Виїзд на набережну або берег».","ru":"О выезде на набережную или берег предупреждает знак {s:1.8} «Выезд на набережную или берег»."}},{"uk":"Про наближення до поромної переправи.","ru":"О приближении к паромной переправе.","w":{"uk":"Про поромну переправу попереджає знак {s:1.8} разом із табличкою {s:7.11} «Поромна переправа».","ru":"О паромной переправе предупреждает знак {s:1.8} вместе с табличкой {s:7.11} «Паромная переправа»."}},{"uk":"Про наближення до порту.","ru":"О приближении к порту.","w":{"uk":"Попереджувального знака про порт немає; морський (річковий) порт позначає інформаційно-вказівний знак {s:5.77}.","ru":"Предупреждающего знака о порте нет; морской (речной) порт обозначает информационно-указательный знак {s:5.77}."}},{"uk":"Про наближення до розвідного моста.","ru":"О приближении к разводному мосту."}],"c":3,"e":{"uk":"Це знак {s:1.25} «Розвідний міст»: попереджає про наближення до розвідного моста ({p:33.1}).","ru":"Это знак {s:1.25} «Разводной мост»: предупреждает о приближении к разводному мосту ({p:33.1})."},"ref":["33.1"],"pic":["img/hsc/33-181-1.jpg"]},{"id":"h33-182","t":"h33","num":"33.182","q":{"uk":"Який з наведених дорожніх знаків попереджає про початок ділянки дороги із зустрічним рухом після одностороннього?","ru":"Какой из приведённых дорожных знаков предупреждает о начале участка дороги со встречным движением после одностороннего?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:5.14} «Кінець дороги з реверсивним рухом».","ru":"Знак 1 — {s:5.14} «Конец дороги с реверсивным движением»."}},{"uk":"Знак 2.","ru":"Знак 2."},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — {s:2.6} «Перевага перед зустрічним рухом»: позначає вузьку ділянку, де водій має перевагу перед зустрічними транспортними засобами ({p:33.2}).","ru":"Знак 3 — {s:2.6} «Преимущество перед встречным движением»: обозначает узкий участок, где водитель имеет преимущество перед встречными транспортными средствами ({p:33.2})."}},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Знак 4 — {s:5.6} «Кінець дороги з одностороннім рухом»: інформаційно-вказівний знак позначає саме місце закінчення одностороннього руху, а попереджає заздалегідь про зустрічний рух знак {s:1.26}.","ru":"Знак 4 — {s:5.6} «Конец дороги с односторонним движением»: информационно-указательный знак обозначает само место окончания одностороннего движения, а заранее предупреждает о встречном движении знак {s:1.26}."}},{"uk":"Знак 5.","ru":"Знак 5.","w":{"uk":"Знак 5 — {s:1.5.1} «Звуження дороги».","ru":"Знак 5 — {s:1.5.1} «Сужение дороги»."}}],"c":1,"e":{"uk":"Знак 2 — {s:1.26} «Двосторонній рух»: попереджає про початок ділянки дороги (проїзної частини) із зустрічним рухом після одностороннього ({p:33.1}).","ru":"Знак 2 — {s:1.26} «Двустороннее движение»: предупреждает о начале участка дороги (проезжей части) со встречным движением после одностороннего ({p:33.1})."},"ref":["33.1"],"pic":["img/hsc/33-182-1.jpg"]},{"id":"h33-183","t":"h33","num":"33.183","q":{"uk":"Даний дорожній знак попереджає:","ru":"Данный дорожный знак предупреждает:"},"a":[{"uk":"Про наближення до ділянки дороги зі смугою для реверсивного руху.","ru":"О приближении к участку дороги с полосой для реверсивного движения.","w":{"uk":"Дорогу з реверсивним рухом позначає інформаційно-вказівний знак {s:5.13}.","ru":"Дорогу с реверсивным движением обозначает информационно-указательный знак {s:5.13}."}},{"uk":"Про наближення до ділянки дороги з інтенсивним рухом.","ru":"О приближении к участку дороги с интенсивным движением.","w":{"uk":"Знака про інтенсивний рух Правила не передбачають; про затори через звуження проїзної частини попереджає знак {s:1.38}.","ru":"Знака об интенсивном движении Правила не предусматривают; о заторах из-за сужения проезжей части предупреждает знак {s:1.38}."}},{"uk":"Про наближення до ділянки дороги із зустрічним рухом після одностороннього.","ru":"О приближении к участку дороги со встречным движением после одностороннего."},{"uk":"Про наближення до ділянки дороги, на якій починається багатосмугова дорога.","ru":"О приближении к участку дороги, на котором начинается многополосная дорога.","w":{"uk":"Стрілки на знаку показують протилежні напрямки руху, а не додаткові смуги.","ru":"Стрелки на знаке показывают противоположные направления движения, а не дополнительные полосы."}}],"c":2,"e":{"uk":"Це знак {s:1.26} «Двосторонній рух»: попереджає про початок ділянки дороги (проїзної частини) із зустрічним рухом після одностороннього ({p:33.1}).","ru":"Это знак {s:1.26} «Двустороннее движение»: предупреждает о начале участка дороги (проезжей части) со встречным движением после одностороннего ({p:33.1})."},"ref":["33.1"],"pic":["img/hsc/33-183-1.jpg"]},{"id":"h33-184","t":"h33","num":"33.184","q":{"uk":"Даний дорожній знак встановлюється перед:","ru":"Данный дорожный знак устанавливается перед:"},"a":[{"uk":"Місцем виконання дорожніх робіт.","ru":"Местом проведения дорожных работ.","w":{"uk":"Про дорожні роботи попереджає знак {s:1.37} «Дорожні роботи».","ru":"О дорожных работах предупреждает знак {s:1.37} «Дорожные работы»."}},{"uk":"Залізничним переїздом без шлагбаума.","ru":"Железнодорожным переездом без шлагбаума.","w":{"uk":"Про переїзд без шлагбаума попереджає знак {s:1.28} із зображенням паровоза.","ru":"О переезде без шлагбаума предупреждает знак {s:1.28} с изображением паровоза."}},{"uk":"Залізничним переїздом із шлагбаумом.","ru":"Железнодорожным переездом со шлагбаумом."},{"uk":"Місцем перетину дороги з трамвайною колією.","ru":"Местом пересечения дороги с трамвайной линией.","w":{"uk":"Про перехрещення з трамвайною колією попереджає знак {s:1.20}.","ru":"О пересечении с трамвайной линией предупреждает знак {s:1.20}."}}],"c":2,"e":{"uk":"Це знак {s:1.27} «Залізничний переїзд зі шлагбаумом» (зображення огорожі); поза населеними пунктами його повторюють, і повторний знак встановлюють щонайменше за 50 м до переїзду ({p:33.1}).","ru":"Это знак {s:1.27} «Железнодорожный переезд со шлагбаумом» (изображение ограждения); вне населённых пунктов его повторяют, и повторный знак устанавливают не менее чем за 50 м до переезда ({p:33.1})."},"ref":["33.1"],"pic":["img/hsc/33-184-1.jpg"]},{"id":"h33-185","t":"h33","num":"33.185","q":{"uk":"Який із зображених дорожніх знаків встановлюється перед залізничним переїздом зі шлагбаумом?","ru":"Какой из изображённых дорожных знаков устанавливается перед железнодорожным переездом со шлагбаумом?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:1.20} «Перехрещення з трамвайною колією».","ru":"Знак 1 — {s:1.20} «Пересечение с трамвайной линией»."}},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:1.9} «Тунель».","ru":"Знак 2 — {s:1.9} «Тоннель»."}},{"uk":"Знак 3.","ru":"Знак 3."},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Знак 4 — {s:1.28} «Залізничний переїзд без шлагбаума».","ru":"Знак 4 — {s:1.28} «Железнодорожный переезд без шлагбаума»."}}],"c":2,"e":{"uk":"Знак 3 — {s:1.27} «Залізничний переїзд зі шлагбаумом» (зображення огорожі) ({p:33.1}).","ru":"Знак 3 — {s:1.27} «Железнодорожный переезд со шлагбаумом» (изображение ограждения) ({p:33.1})."},"ref":["33.1"],"pic":["img/hsc/33-185-1.jpg"]},{"id":"h33-186","t":"h33","num":"33.186","q":{"uk":"Який із зображених дорожніх знаків встановлюється перед залізничним переїздом без шлагбаума?"},"a":[{"uk":"Знак 1."},{"uk":"Знак 2."},{"uk":"Знак 3."},{"uk":"Знак 4."}],"c":3,"pic":["img/hsc/33-186-1.jpg"]},{"id":"h33-187","t":"h33","num":"33.187","q":{"uk":"У якому місці встановлюється даний дорожній знак?"},"a":[{"uk":"Перед місцем перетину дороги з трамвайною колією на перехресті з обмеженою оглядовістю."},{"uk":"Перед залізничним переїздом без шлагбаума."},{"uk":"Перед залізничним переїздом зі шлагбаумом."},{"uk":"Перед залізничним переїздом без шлагбаума, розташованим за межами населеного пункту."}],"c":1,"pic":["img/hsc/33-187-1.jpg"]},{"id":"h33-188","t":"h33","num":"33.188","q":{"uk":"Зображений дорожній знак встановлюється перед:"},"a":[{"uk":"Нерегульованим пішохідним переходом."},{"uk":"Місцем масового скупчення людей."},{"uk":"Ділянкою дороги, на якій можлива поява дітей з території дитячого закладу, прилеглого безпосередньо до дороги."},{"uk":"Ділянкою дороги, на якій можливий вихід людей на проїзну частину."}],"c":2,"pic":["img/hsc/33-188-1.jpg"]},{"id":"h33-189","t":"h33","num":"33.189","q":{"uk":"Зображений дорожній знак встановлюється перед:"},"a":[{"uk":"Місцем перехрещення з велосипедною доріжкою поза перехрестям."},{"uk":"Місцем, поблизу якого проходить велосипедна доріжка."},{"uk":"Ділянкою дороги, на якій можлива поява велосипедистів."},{"uk":"Відповіді 1 і 3."}],"c":3,"pic":["img/hsc/33-189-1.jpg"]},{"id":"h33-190","t":"h33","num":"33.190","q":{"uk":"Який із зображених знаків встановлюється перед місцем перетину дороги з велосипедною доріжкою поза перехрестям?"},"a":[{"uk":"Знак 1."},{"uk":"Знак 2."},{"uk":"Знак 3."},{"uk":"Знак 4."}],"c":1,"pic":["img/hsc/33-190-1.jpg"]},{"id":"h33-191","t":"h33","num":"33.191","q":{"uk":"Зображеними дорожніми знаками позначають:"},"a":[{"uk":"Ділянку дороги з двома і більше розташованими один за одним небезпечними поворотами."},{"uk":"Звуження дороги."},{"uk":"Напрямок повороту."}],"c":2,"pic":["img/hsc/33-191-1.jpg"]},{"id":"h33-192","t":"h33","num":"33.192","q":{"uk":"Який із зображених дорожніх знаків повторюється перед небезпечною ділянкою дороги за межами населених пунктів?"},"a":[{"uk":"Знак 1."},{"uk":"Знак 2."},{"uk":"Знак 3."},{"uk":"Знак 4."},{"uk":"Усі зображені дорожні знаки."}],"c":4,"pic":["img/hsc/33-192-1.jpg"]},{"id":"h33-193","t":"h33","num":"33.193","q":{"uk":"Який із зображених дорожніх знаків повторюється перед небезпечною ділянкою дороги за межами населених пунктів?"},"a":[{"uk":"Знак 1."},{"uk":"Знак 2."},{"uk":"Знак 3."},{"uk":"Знак 4."},{"uk":"Усі зображені дорожні знаки."}],"c":0,"pic":["img/hsc/33-193-1.jpg"]},{"id":"h33-194","t":"h33","num":"33.194","q":{"uk":"Який із зображених дорожніх знаків повторюється перед небезпечними ділянками дороги в населених пунктах?"},"a":[{"uk":"Знак 1."},{"uk":"Знак 2."},{"uk":"Знак 3."},{"uk":"Знаки 1 і 2."},{"uk":"Знаки 1, 2 і 3."}],"c":3,"pic":["img/hsc/33-194-1.jpg"]},{"id":"h33-195","t":"h33","num":"33.195","q":{"uk":"Які із зображених дорожніх знаків є тимчасовими?"},"a":[{"uk":"Знак 1."},{"uk":"Знак 2."},{"uk":"Знак 3."},{"uk":"Знак 4."}],"c":0,"pic":["img/hsc/33-195-1.jpg"]},{"id":"h33-196","t":"h33","num":"33.196","q":{"uk":"Зображений дорожній знак діє:"},"a":[{"uk":"На регульованому перехресті."},{"uk":"На нерегульованому перехресті."},{"uk":"На регульованому і нерегульованому перехрестях."}],"c":1,"pic":["img/hsc/33-196-1.jpg"]},{"id":"h33-197","t":"h33","num":"33.197","q":{"uk":"Водій правильно виконав вимогу даного дорожнього знака, встановленого на нерегульованому перехресті, якщо:"},"a":[{"uk":"Обов'язково зупинився перед розміткою «Стоп-лінія» і дав дорогу транспортним засобам, що рухаються по головній дорозі."},{"uk":"Знизив швидкість або зупинився, щоб дати дорогу транспортним засобам, що рухаються по головній дорозі."},{"uk":"Проїхав, не зупинившись, не даючи дорогу іншим транспортним засобам."}],"c":1,"pic":["img/hsc/33-197-1.jpg"]},{"id":"h33-198","t":"h33","num":"33.198","q":{"uk":"Чи є обов'язковою зупинка для виконання вимоги даного дорожнього знака?"},"a":[{"uk":"Обов’язкова."},{"uk":"Необов’язкова."}],"c":1,"pic":["img/hsc/33-198-1.jpg"]},{"id":"h33-199","t":"h33","num":"33.199","q":{"uk":"Який з перелічених знаків встановлюється безпосередньо перед небезпечною ділянкою дороги?"},"a":[{"uk":"Знак 1."},{"uk":"Знак 2."},{"uk":"Знак 3."},{"uk":"Знак 4."},{"uk":"Знаки 1 і 2."}],"c":4,"pic":["img/hsc/33-199-1.jpg"]},{"id":"h33-200","t":"h33","num":"33.200","q":{"uk":"Який із зображених знаків може бути встановлено безпосередньо перед небезпечною ділянкою дороги?"},"a":[{"uk":"Знак 1."},{"uk":"Знак 2."},{"uk":"Знак 3."},{"uk":"Знак 4."},{"uk":"Знак 5."}],"c":0,"pic":["img/hsc/33-200-1.jpg"]},{"id":"h33-201","t":"h33","num":"33.201","q":{"uk":"Зображений дорожній знак встановлюється перед:"},"a":[{"uk":"Ділянкою дороги, на якій можлива поява диких тварин."},{"uk":"Ділянкою дороги, на якій можлива поява будь-яких тварин."},{"uk":"Ділянкою дороги, на якій можлива поява худоби."}],"c":2,"pic":["img/hsc/33-201-1.jpg"]},{"id":"h33-202","t":"h33","num":"33.202","q":{"uk":"Зображений дорожній знак встановлюється перед:"},"a":[{"uk":"Ділянкою дороги, на якій можлива поява худоби."},{"uk":"Ділянкою дороги, на якій можлива поява будь-яких тварин."},{"uk":"Ділянкою дороги, на якій можлива поява диких тварин."}],"c":2,"pic":["img/hsc/33-202-1.jpg"]},{"id":"h33-203","t":"h33","num":"33.203","q":{"uk":"Зображений дорожній знак встановлюється перед:"},"a":[{"uk":"Ділянкою дороги, на якій є нерівності проїзної частини."},{"uk":"Ділянкою дороги, на якій обмежено дорожній рух."},{"uk":"Ділянкою дороги, на якій виконують дорожні роботи."},{"uk":"Відповіді 1 і 3."},{"uk":"Відповіді 1, 2 і 3."}],"c":2,"pic":["img/hsc/33-203-1.jpg"]},{"id":"h33-204","t":"h33","num":"33.204","q":{"uk":"На якій відстані від місця виконання короткотермінових дорожніх робіт на проїзній частині в населеному пункті може бути встановлено знак «Дорожні роботи»?"},"a":[{"uk":"50—100 м."},{"uk":"150—300 м."},{"uk":"10—15 м."},{"uk":"Безпосередньо перед таким місцем."}],"c":2,"pic":["img/hsc/33-204-1.jpg"]},{"id":"h33-205","t":"h33","num":"33.205","q":{"uk":"Зображений дорожній знак встановлюється перед:"},"a":[{"uk":"Ділянкою дороги, на якій проходять ремонтні роботи."},{"uk":"Ділянкою дороги, де звуження проїзної частини спричиняє затори в дорожньому русі."},{"uk":"Ділянкою дороги з інтенсивним рухом."},{"uk":"Ділянкою дороги з багатосмуговим рухом."}],"c":1,"pic":["img/hsc/33-205-1.jpg"]},{"id":"h33-206","t":"h33","num":"33.206","q":{"uk":"Який із зображених дорожніх знаків попереджає про наближення до ділянки (місця) концентрації дорожньо-транспортних пригод?"},"a":[{"uk":"Знак 1."},{"uk":"Знак 2."},{"uk":"Знак 3."},{"uk":"Знак 4."}],"c":1,"pic":["img/hsc/33-206-1.jpg"]},{"id":"h33-207","t":"h33","num":"33.207","q":{"uk":"Зображений дорожній знак попереджає водіїв:"},"a":[{"uk":"Про наближення до ділянки дороги у місці, де геометричні параметри проїзної частини, радіуси вертикальних і горизонтальних кривих тощо не відповідають вимогам будівельних норм."},{"uk":"Про наближення до місця, де звуження проїзної частини спричиняє затори в дорожньому русі."},{"uk":"Правильні обидва варіанти."}],"c":0,"pic":["img/hsc/33-207-1.jpg"]},{"id":"h33-208","t":"h33","num":"33.208","q":{"uk":"Даний дорожній знак встановлюється перед:"},"a":[{"uk":"Місцем проведення дорожніх робіт."},{"uk":"Місцем звуження дороги з обох боків."},{"uk":"Місцем, де звуження проїзної частини спричиняє затори в дорожньому русі."},{"uk":"Місцем, де дорога з удосконаленим покриттям переходить у гравійну або ґрунтову дорогу."}],"c":3,"pic":["img/hsc/33-208-1.jpg"]},{"id":"h33-209","t":"h33","num":"33.209","q":{"uk":"Який дорожній знак встановлено на дорозі, що перетинається, якщо для вас встановлено даний знак?"},"a":[{"uk":"Знак 1."},{"uk":"Знак 2."},{"uk":"Знак 3."},{"uk":"Знак 4."}],"c":1,"pic":["img/hsc/33-209-1.jpg"]},{"id":"h33-210","t":"h33","num":"33.210","q":{"uk":"У даній ситуації ви маєте перевагу:"},"a":[{"uk":"Тільки на першому перехресті."},{"uk":"Тільки на другому перехресті."},{"uk":"На обох перехрестях."},{"uk":"На обох перехрестях ви взагалі не маєте переваги."}],"c":2,"pic":["img/hsc/33-210-1.jpg"]},{"id":"h33-211","t":"h33","num":"33.211","q":{"uk":"Дорожні роботи – це:"},"a":[{"uk":"Роботи, пов'язані з інженерним облаштуванням, установкою (ремонтом, заміною) технічних засобів організації дорожнього руху."},{"uk":"Роботи, пов'язані з будівництвом, реконструкцією, ремонтом чи утриманням автомобільної дороги (вулиці), штучних споруд, споруд дорожнього водовідводу."},{"uk":"Відповіді, зазначені в пунктах 1, 2."}],"c":2,"pic":["img/hsc/33-211-1.jpg"]},{"id":"h33-212","t":"h33","num":"33.212","q":{"uk":"На що вказує даний дорожній знак?"},"a":[{"uk":"На напрямок звуження проїзної частини."},{"uk":"На напрямок руху на Т-подібних перехрестях."},{"uk":"На напрямок руху на розгалуженнях доріг."},{"uk":"На напрямок об'їзду ділянки дороги, що ремонтується."},{"uk":"Відповіді 2, 3 і 4."}],"c":4,"pic":["img/hsc/33-212-1.jpg"]},{"id":"h33-213","t":"h33","num":"33.213","q":{"uk":"Який з наведених дорожніх знаків вказує напрямок повороту?"},"a":[{"uk":"Знак 1."},{"uk":"Знак 2."},{"uk":"Знак 3."},{"uk":"Знак 4."}],"c":2,"pic":["img/hsc/33-213-1.jpg"]},{"id":"h33-214","t":"h33","num":"33.214","q":{"uk":"Де встановлюється даний дорожній знак?"},"a":[{"uk":"Перед ділянкою дороги з підвищеною слизькістю проїзної частини."},{"uk":"Перед небезпечним поворотом дороги."},{"uk":"Перед звуженням дороги з обох боків."}],"c":2,"pic":["img/hsc/33-214-1.jpg"]},{"id":"h33-215","t":"h33","num":"33.215","q":{"uk":"Який з наведених дорожніх знаків попереджає про звуження дороги з правого боку?"},"a":[{"uk":"Знак 1."},{"uk":"Знак 2."},{"uk":"Знак 3."},{"uk":"Знак 4."}],"c":1,"pic":["img/hsc/33-215-1.jpg"]},{"id":"h33-216","t":"h33","num":"33.216","q":{"uk":"Про що попереджає даний дорожній знак?"},"a":[{"uk":"Про звуження дороги праворуч."},{"uk":"Про звуження дороги ліворуч."},{"uk":"Про закінчення дороги з розділювальною смугою."}],"c":1,"pic":["img/hsc/33-216-1.jpg"]},{"id":"h33-217","t":"h33","num":"33.217","q":{"uk":"Який з наведених дорожніх знаків встановлюється перед крутим підйомом?"},"a":[{"uk":"Знак 1."},{"uk":"Знак 2."},{"uk":"Знак 3."},{"uk":"Знак 4."}],"c":0,"pic":["img/hsc/33-217-1.jpg"]},{"id":"h33-218","t":"h33","num":"33.218","q":{"uk":"Який з наведених дорожніх знаків встановлюється перед крутим спуском?"},"a":[{"uk":"Знак 1."},{"uk":"Знак 2."},{"uk":"Знак 3."}],"c":1,"pic":["img/hsc/33-218-1.jpg"]},{"id":"h33-219","t":"h33","num":"33.219","q":{"uk":"Про що попереджає даний дорожній знак?"},"a":[{"uk":"Про наближення до крутого спуску."},{"uk":"Про наближення до крутого підйому."},{"uk":"Про наближення до аварійно небезпечної ділянки дороги."}],"c":1,"pic":["img/hsc/33-219-1.jpg"]},{"id":"h33-220","t":"h33","num":"33.220","q":{"uk":"У якому з місць встановлюється даний дорожній знак?"},"a":[{"uk":"У місцях дороги з небезпечним узбіччям."},{"uk":"У місцях дороги, де можливі сильний вітер або раптові його пориви."},{"uk":"У місцях напрямку повороту дороги."}],"c":2,"pic":["img/hsc/33-220-1.jpg"]},{"id":"h33-221","t":"h33","num":"33.221","q":{"uk":"Де встановлюється даний дорожній знак?"},"a":[{"uk":"У місцях звуження дороги."},{"uk":"На затяжних підйомах."},{"uk":"У місцях напрямку повороту дороги з обмеженою оглядовістю."},{"uk":"У місцях об’їзду центра перехрестя з круговим рухом."},{"uk":"Відповіді 3 і 4."}],"c":4,"pic":["img/hsc/33-221-1.jpg"]},{"id":"h33-222","t":"h33","num":"33.222","q":{"uk":"Про що попереджає даний дорожній знак?"},"a":[{"uk":"Про наближення до небезпечного повороту праворуч."},{"uk":"Про наближення до небезпечного повороту ліворуч."},{"uk":"Про наявність в'їзду з прилеглої території."},{"uk":"Про наявність двох поворотів, що йдуть один за одним."}],"c":0,"pic":["img/hsc/33-222-1.jpg"]},{"id":"h33-223","t":"h33","num":"33.223","q":{"uk":"Про що попереджає даний дорожній знак?"},"a":[{"uk":"Про наближення до небезпечного повороту праворуч."},{"uk":"Про наближення до небезпечного повороту ліворуч."},{"uk":"Про наявність в'їзду з прилеглої території."},{"uk":"Про наявність двох поворотів, що йдуть один за одним."}],"c":1,"pic":["img/hsc/33-223-1.jpg"]},{"id":"h33-224","t":"h33","num":"33.224","q":{"uk":"Який із зображених дорожніх знаків попереджає про заокруглення з обмеженою оглядовістю?"},"a":[{"uk":"Знак 1."},{"uk":"Знак 2."},{"uk":"Знак 3."},{"uk":"Знак 4."}],"c":3,"pic":["img/hsc/33-224-1.jpg"]},{"id":"h33-225","t":"h33","num":"33.225","q":{"uk":"Який із перелічених дорожніх знаків вказує водію про наближення до небезпечного повороту дороги?"},"a":[{"uk":"Знак 1."},{"uk":"Знак 2."},{"uk":"Знак 3."},{"uk":"Знак 4."}],"c":2,"pic":["img/hsc/33-225-1.jpg"]},{"id":"h33-226","t":"h33","num":"33.226","q":{"uk":"Про що попереджає даний дорожній знак?"},"a":[{"uk":"Про наявність з'їзду в прилеглу територію."},{"uk":"Про наближення до ділянки дороги з небезпечним поворотом."},{"uk":"Про наближення до ділянки дороги з двома небезпечними поворотами – з першим праворуч."},{"uk":"Про наближення до ділянки дороги з двома небезпечними поворотами – з першим ліворуч."}],"c":2,"pic":["img/hsc/33-226-1.jpg"]},{"id":"h33-227","t":"h33","num":"33.227","q":{"uk":"Про що попереджає даний дорожній знак?"},"a":[{"uk":"Про наближення до ділянки дороги з двома і більше небезпечними поворотами – з першим ліворуч."},{"uk":"Про наближення до слизької ділянки дороги."},{"uk":"Про наближення до небезпечного повороту дороги."}],"c":0,"pic":["img/hsc/33-227-1.jpg"]},{"id":"h33-228","t":"h33","num":"33.228","q":{"uk":"Про що попереджає даний дорожній знак, встановлений з табличкою?"},"a":[{"uk":"Про наближення до небезпечного повороту дороги."},{"uk":"Про наближення до ділянки дороги з двома небезпечними поворотами – з першим ліворуч."},{"uk":"Про наближення до ділянки дороги з дев'ятьма небезпечними поворотами – з першим ліворуч."},{"uk":"Про наближення до ділянки дороги з дев'ятьма небезпечними поворотами – з першим праворуч."}],"c":3,"pic":["img/hsc/33-228-1.jpg"]},{"id":"h33-229","t":"h33","num":"33.229","q":{"uk":"Який із вказаних дорожніх знаків встановлюється перед ділянкою дороги з двома небезпечними поворотами, розташованими один за одним?"},"a":[{"uk":"Знак 1."},{"uk":"Знак 2."},{"uk":"Знак 3."},{"uk":"Знак 4."}],"c":1,"pic":["img/hsc/33-229-1.jpg"]},{"id":"h33-230","t":"h33","num":"33.230","q":{"uk":"Про що попереджає даний дорожній знак?"},"a":[{"uk":"Про те, що дорога виходить на берег водойми або набережну."},{"uk":"Про те, що дорога виходить на поромну переправу."},{"uk":"Про те, що дорога проходить через розвідний міст."}],"c":0,"pic":["img/hsc/33-230-1.jpg"]},{"id":"h33-231","t":"h33","num":"33.231","q":{"uk":"Про що попереджає даний дорожній знак у поєднанні з табличкою?"},"a":[{"uk":"Про те, що дорога проходить поблизу поромної переправи."},{"uk":"Про те, що дорога виходить на берег водойми або набережну."},{"uk":"Про те, що дорога виходить на поромну переправу."}],"c":2,"pic":["img/hsc/33-231-1.jpg"]},{"id":"h33-232","t":"h33","num":"33.232","q":{"uk":"Про що попереджає даний дорожній знак?"},"a":[{"uk":"Про наближення до споруди, що не має штучного освітлення, оглядовість в'їзного порталу якої обмежена або на під'їзді до якої звужена проїзна частина."},{"uk":"Про наближення до мосту."},{"uk":"Про наближення до шляхопроводу."},{"uk":"Про наближення до залізничного переїзду."}],"c":0,"pic":["img/hsc/33-232-1.jpg"]},{"id":"h33-233","t":"h33","num":"33.233","q":{"uk":"Який із зображених дорожніх знаків попереджає про наближення до перехрестя з круговим рухом?"},"a":[{"uk":"Знак 1."},{"uk":"Знак 2."},{"uk":"Знак 3."},{"uk":"Знак 4."}],"c":1,"pic":["img/hsc/33-233-1.jpg"]},{"id":"h33-234","t":"h33","num":"33.234","q":{"uk":"Який із зображених дорожніх знаків встановлюється перед перетином дороги з трамвайною колією на перехресті з обмеженою оглядовістю?"},"a":[{"uk":"Знак 1."},{"uk":"Знак 2."},{"uk":"Знак 3."},{"uk":"Знак 4."}],"c":1,"pic":["img/hsc/33-234-1.jpg"]},{"id":"h33-235","t":"h33","num":"33.235","q":{"uk":"Про що попереджає даний дорожній знак?"},"a":[{"uk":"Про наближення до перехрестя нерівнозначних доріг."},{"uk":"Про наближення до перехрестя, на якому необхідно дати дорогу."},{"uk":"Про наближення до перехрестя, на якому водій має перевагу в русі."},{"uk":"Про наближення до перехрестя рівнозначних доріг."}],"c":3,"pic":["img/hsc/33-235-1.jpg"]},{"id":"h33-236","t":"h33","num":"33.236","q":{"uk":"Який із зображених дорожніх знаків встановлюється перед перехрестям рівнозначних доріг?"},"a":[{"uk":"Знак 1."},{"uk":"Знак 2."},{"uk":"Знак 3."},{"uk":"Знак 4."}],"c":1,"pic":["img/hsc/33-236-1.jpg"]},{"id":"h33-237","t":"h33","num":"33.237","q":{"uk":"Про що попереджає даний дорожній знак?"},"a":[{"uk":"Про наближення до перехрестя рівнозначних доріг."},{"uk":"Про наближення до перехрестя нерівнозначних доріг."},{"uk":"Про наближення до місця перетину з прилеглою територією."},{"uk":"Про наближення до залізничного переїзду."}],"c":1,"pic":["img/hsc/33-237-1.jpg"]},{"id":"h33-238","t":"h33","num":"33.238","q":{"uk":"Який із зображених дорожніх знаків встановлюється при наближенні до перехрестя із другорядною дорогою?"},"a":[{"uk":"Знак 1."},{"uk":"Знак 2."},{"uk":"Знак 3."},{"uk":"Знак 4."}],"c":1,"pic":["img/hsc/33-238-1.jpg"]},{"id":"h33-239","t":"h33","num":"33.239","q":{"uk":"Чи маєте ви перевагу в русі на найближчому перехресті?"},"a":[{"uk":"Не маєте."},{"uk":"Маєте, тільки якщо встановлено знак «Головна дорога»."},{"uk":"Маєте в будь-якому разі."}],"c":2,"pic":["img/hsc/33-239-1.jpg"]},{"id":"h33-240","t":"h33","num":"33.240","q":{"uk":"Даний дорожній знак попереджає:"},"a":[{"uk":"Про наближення до перехрестя з обмеженою оглядовістю."},{"uk":"Про наближення до перехрестя рівнозначних доріг."},{"uk":"Про наближення до перехрестя, на якому другорядна дорога прилягає з правого боку."}],"c":2,"pic":["img/hsc/33-240-1.jpg"]},{"id":"h33-241","t":"h33","num":"33.241","q":{"uk":"Даний дорожній знак встановлюється перед ділянками дороги:","ru":"Данный дорожный знак устанавливается перед участками дороги:"},"a":[{"uk":"Які проходять поблизу аеропорту.","ru":"Которые проходят вблизи аэропорта.","w":{"uk":"Знак пов'язаний не з аеропортом, а з аеродромами й низькими польотами; про аеропорт інформує знак {s:5.71} «Аеропорт».","ru":"Знак связан не с аэропортом, а с аэродромами и низкими полётами; об аэропорте информирует знак {s:5.71} «Аэропорт»."}},{"uk":"Які проходять поблизу аеродромів.","ru":"Которые проходят вблизи аэродромов.","w":{"uk":"Відповідь неповна: знак ставлять і там, де літаки чи вертольоти пролітають над дорогою на невеликій висоті, навіть далеко від аеродрому.","ru":"Ответ неполный: знак ставят и там, где самолёты или вертолёты пролетают над дорогой на небольшой высоте, даже далеко от аэродрома."}},{"uk":"Які проходять поблизу аеродромів або над якими літаки чи вертольоти пролітають на невеликій висоті.","ru":"Которые проходят вблизи аэродромов или над которыми самолёты или вертолёты пролетают на небольшой высоте."}],"c":2,"e":{"uk":"Це знак {s:1.18} «Низьколітаючі літаки»: він попереджає про ділянку дороги, яка проходить поблизу аеродрому **або** над якою літаки чи вертольоти пролітають на невеликій висоті ({p:33.1}).","ru":"Это знак {s:1.18} «Низколетящие самолёты»: он предупреждает об участке дороги, проходящем вблизи аэродрома **или** над которым самолёты или вертолёты пролетают на небольшой высоте ({p:33.1})."},"ref":["33.1"],"pic":["img/hsc/33-241-1.jpg"]},{"id":"h33-242","t":"h33","num":"33.242","q":{"uk":"Про що попереджає даний дорожній знак?","ru":"О чём предупреждает данный дорожный знак?"},"a":[{"uk":"Попереду ділянка дороги, яка проходить поблизу злітно-посадкових смуг.","ru":"Впереди участок дороги, проходящий вблизи взлётно-посадочных полос.","w":{"uk":"Про ділянку поблизу аеродрому попереджає знак {s:1.18} «Низьколітаючі літаки» із зображенням літака.","ru":"Об участке вблизи аэродрома предупреждает знак {s:1.18} «Низколетящие самолёты» с изображением самолёта."}},{"uk":"Попереду ділянка дороги, на якій можливі сильний боковий вітер або його раптові пориви.","ru":"Впереди участок дороги, на котором возможны сильный боковой ветер или его внезапные порывы."},{"uk":"Попереду ділянка дороги, яка проходить поблизу набережної.","ru":"Впереди участок дороги, проходящий вблизи набережной.","w":{"uk":"Про виїзд на набережну чи берег попереджає знак {s:1.8} «Виїзд на набережну або берег».","ru":"О выезде на набережную или берег предупреждает знак {s:1.8} «Выезд на набережную или берег»."}}],"c":1,"e":{"uk":"Знак {s:1.17} «Боковий вітер» (на ньому зображено вітровказівний конус) попереджає про ділянку дороги, на якій можливі сильний боковий вітер або його раптові пориви ({p:33.1}).","ru":"Знак {s:1.17} «Боковой ветер» (на нём изображён ветроуказательный конус) предупреждает об участке дороги, на котором возможны сильный боковой ветер или его внезапные порывы ({p:33.1})."},"ref":["33.1"],"pic":["img/hsc/33-242-1.jpg"]},{"id":"h33-243","t":"h33","num":"33.243","q":{"uk":"Де встановлюється даний дорожній знак?","ru":"Где устанавливается данный дорожный знак?"},"a":[{"uk":"Перед ділянкою дороги з вибоїнами.","ru":"Перед участком дороги с выбоинами.","w":{"uk":"Про вибоїни попереджає знак {s:1.12} «Вибоїна», на якому зображено заглиблення в покритті.","ru":"О выбоинах предупреждает знак {s:1.12} «Выбоина», на котором изображено углубление в покрытии."}},{"uk":"Перед ділянкою дороги зі штучно створюваними буграми в місцях, де необхідно примусово обмежити швидкість руху транспортних засобів.","ru":"Перед участком дороги с искусственно создаваемыми буграми в местах, где необходимо принудительно ограничить скорость движения транспортных средств.","w":{"uk":"Штучні бугри для примусового обмеження швидкості позначають знаком {s:1.11} «Пагорб».","ru":"Искусственные бугры для принудительного ограничения скорости обозначают знаком {s:1.11} «Бугор»."}},{"uk":"Перед ділянкою дороги з нерівністю проїзної частини – хвилястості, напливи, спучування.","ru":"Перед участком дороги с неровностями проезжей части — волнистостью, наплывами, вспучиваниями."},{"uk":"Перед ділянкою дороги, на якій узбіччя підвищене, занижене, зруйноване, а також якщо на узбіччі виконують ремонтні роботи.","ru":"Перед участком дороги, на котором обочина повышенная, пониженная, разрушенная, а также если на обочине выполняются ремонтные работы.","w":{"uk":"Про таке узбіччя попереджає знак {s:1.15} «Небезпечне узбіччя».","ru":"О такой обочине предупреждает знак {s:1.15} «Опасная обочина»."}}],"c":2,"e":{"uk":"Це знак {s:1.10} «Нерівна дорога»: ділянка дороги, що має нерівності проїзної частини — хвилястості, напливи, спучування ({p:33.1}). Знак тимчасовий, тому він на жовтому фоні.","ru":"Это знак {s:1.10} «Неровная дорога»: участок дороги, имеющий неровности проезжей части — волнистость, наплывы, вспучивания ({p:33.1}). Знак временный, поэтому он на жёлтом фоне."},"ref":["33.1"],"pic":["img/hsc/33-243-1.jpg"]},{"id":"h33-244","t":"h33","num":"33.244","q":{"uk":"Даний дорожній знак встановлюється перед:","ru":"Данный дорожный знак устанавливается перед:"},"a":[{"uk":"Ділянкою дороги, що має нерівності проїзної частини – хвилястості, напливи, спучування.","ru":"Участком дороги, имеющим неровности проезжей части — волнистость, наплывы, вспучивания.","w":{"uk":"Хвилястості, напливи й спучування проїзної частини позначає знак {s:1.10} «Нерівна дорога».","ru":"Волнистость, наплывы и вспучивания проезжей части обозначает знак {s:1.10} «Неровная дорога»."}},{"uk":"Ділянкою дороги з вибоїнами чи просіданням дорожнього покриття на проїзній частині.","ru":"Участком дороги с выбоинами или просадками дорожного покрытия на проезжей части.","w":{"uk":"Вибоїни та просідання покриття позначає знак {s:1.12} «Вибоїна».","ru":"Выбоины и просадки покрытия обозначает знак {s:1.12} «Выбоина»."}},{"uk":"Штучно створюваними буграми в місцях, де необхідно примусово обмежити швидкість руху транспортних засобів.","ru":"Искусственно создаваемыми буграми в местах, где необходимо принудительно ограничить скорость движения транспортных средств.","w":{"uk":"Відповідь неповна: знак {s:1.11} ставлять і перед природними буграми, напливами чи неплавним стикуванням конструкцій мостів.","ru":"Ответ неполный: знак {s:1.11} ставят и перед естественными буграми, наплывами или неплавным стыком конструкций мостов."}},{"uk":"Ділянкою дороги з буграми, напливами чи неплавним стикуванням конструкцій мостів.","ru":"Участком дороги с буграми, наплывами или неплавным стыком конструкций мостов.","w":{"uk":"Відповідь неповна: знак {s:1.11} застосовують і перед штучними буграми для примусового обмеження швидкості.","ru":"Ответ неполный: знак {s:1.11} применяют и перед искусственными буграми для принудительного ограничения скорости."}},{"uk":"Відповіді 3 і 4.","ru":"Ответы 3 и 4."}],"c":4,"e":{"uk":"Це знак {s:1.11} «Пагорб»: його ставлять перед ділянкою дороги з буграми, напливами чи неплавним стикуванням конструкцій мостів, а також перед штучно створюваними буграми там, де треба примусово обмежити швидкість ({p:33.1}).","ru":"Это знак {s:1.11} «Бугор»: его ставят перед участком дороги с буграми, наплывами или неплавным стыком конструкций мостов, а также перед искусственно создаваемыми буграми там, где нужно принудительно ограничить скорость ({p:33.1})."},"ref":["33.1"],"pic":["img/hsc/33-244-1.jpg"]},{"id":"h33-245","t":"h33","num":"33.245","q":{"uk":"Даний дорожній знак встановлюється перед:","ru":"Данный дорожный знак устанавливается перед:"},"a":[{"uk":"Штучно створюваними буграми в місцях, де необхідно примусово обмежити швидкість руху транспортних засобів.","ru":"Искусственно создаваемыми буграми в местах, где необходимо принудительно ограничить скорость движения транспортных средств.","w":{"uk":"Штучні бугри позначають знаком {s:1.11} «Пагорб», на якому зображено опуклість, а не заглиблення.","ru":"Искусственные бугры обозначают знаком {s:1.11} «Бугор», на котором изображена выпуклость, а не углубление."}},{"uk":"Ділянками доріг з вибоїнами чи просіданням дорожнього покриття на проїзній частині.","ru":"Участками дорог с выбоинами или просадками дорожного покрытия на проезжей части."},{"uk":"Ділянками доріг з буграми, напливами чи неплавним стикуванням конструкцій мостів.","ru":"Участками дорог с буграми, наплывами или неплавным стыком конструкций мостов.","w":{"uk":"Бугри, напливи й неплавне стикування конструкцій мостів позначає знак {s:1.11} «Пагорб».","ru":"Бугры, наплывы и неплавный стык конструкций мостов обозначает знак {s:1.11} «Бугор»."}},{"uk":"Ділянками доріг, на яких можливе викидання гравію, щебеню і т. д. з-під коліс транспортних засобів.","ru":"Участками дорог, на которых возможен выброс гравия, щебня и т. п. из-под колёс транспортных средств.","w":{"uk":"Про можливе викидання гравію та щебеню попереджає знак {s:1.14} «Викидання кам'яних матеріалів».","ru":"О возможном выбросе гравия и щебня предупреждает знак {s:1.14} «Выброс каменных материалов»."}}],"c":1,"e":{"uk":"Знак {s:1.12} «Вибоїна» (на ньому зображено заглиблення в покритті) встановлюють перед ділянкою дороги з вибоїнами чи просіданнями дорожнього покриття на проїзній частині ({p:33.1}).","ru":"Знак {s:1.12} «Выбоина» (на нём изображено углубление в покрытии) устанавливают перед участком дороги с выбоинами или просадками дорожного покрытия на проезжей части ({p:33.1})."},"ref":["33.1"],"pic":["img/hsc/33-245-1.jpg"]},{"id":"h33-246","t":"h33","num":"33.246","q":{"uk":"Який з наведених дорожніх знаків встановлюється перед ділянками доріг з вибоїнами чи просіданням дорожнього покриття?","ru":"Какой из приведённых дорожных знаков устанавливается перед участками дорог с выбоинами или просадками дорожного покрытия?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:1.11} «Пагорб»: він попереджає про бугри, напливи чи штучні нерівності, а не про вибоїни.","ru":"Знак 1 — {s:1.11} «Бугор»: он предупреждает о буграх, наплывах или искусственных неровностях, а не о выбоинах."}},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:1.10} «Нерівна дорога»: хвилястості, напливи, спучування проїзної частини.","ru":"Знак 2 — {s:1.10} «Неровная дорога»: волнистость, наплывы, вспучивания проезжей части."}},{"uk":"Знак 3.","ru":"Знак 3."},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Знак 4 — {s:1.37} «Дорожні роботи».","ru":"Знак 4 — {s:1.37} «Дорожные работы»."}}],"c":2,"e":{"uk":"Знак 3 — {s:1.12} «Вибоїна»: на ньому зображено заглиблення в покритті; його ставлять перед ділянкою з вибоїнами чи просіданнями покриття ({p:33.1}).","ru":"Знак 3 — {s:1.12} «Выбоина»: на нём изображено углубление в покрытии; его ставят перед участком с выбоинами или просадками покрытия ({p:33.1})."},"ref":["33.1"],"pic":["img/hsc/33-246-1.jpg"]},{"id":"h33-247","t":"h33","num":"33.247","q":{"uk":"Який з наведених дорожніх знаків попереджає, що попереду ділянка дороги з підвищеною слизькістю проїзної частини?","ru":"Какой из приведённых дорожных знаков предупреждает, что впереди участок дороги с повышенной скользкостью проезжей части?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:1.5.2} «Звуження дороги» з правого боку.","ru":"Знак 1 — {s:1.5.2} «Сужение дороги» справа."}},{"uk":"Знак 2.","ru":"Знак 2."},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — {s:1.3.1} «Декілька поворотів» (перший поворот праворуч).","ru":"Знак 3 — {s:1.3.1} «Несколько поворотов» (первый поворот направо)."}},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Знак 4 — {s:1.7} «Крутий спуск».","ru":"Знак 4 — {s:1.7} «Крутой спуск»."}}],"c":1,"e":{"uk":"Знак 2 — {s:1.13} «Слизька дорога» (автомобіль зі слідами заносу): ділянка дороги з підвищеною слизькістю проїзної частини ({p:33.1}).","ru":"Знак 2 — {s:1.13} «Скользкая дорога» (автомобиль со следами заноса): участок дороги с повышенной скользкостью проезжей части ({p:33.1})."},"ref":["33.1"],"pic":["img/hsc/33-247-1.jpg"]},{"id":"h33-248","t":"h33","num":"33.248","q":{"uk":"Про що попереджає даний дорожній знак?","ru":"О чём предупреждает данный дорожный знак?"},"a":[{"uk":"Про те, що попереду ділянка дороги з мокрим покриттям.","ru":"О том, что впереди участок дороги с мокрым покрытием.","w":{"uk":"Окремого знака про мокре покриття немає: для цього до знака {s:1.13} «Слизька дорога» додають табличку {s:7.13} «Вологе покриття».","ru":"Отдельного знака о мокром покрытии нет: для этого к знаку {s:1.13} «Скользкая дорога» добавляют табличку {s:7.13} «Влажное покрытие»."}},{"uk":"Про те, що попереду ділянка дороги, заметена снігом.","ru":"О том, что впереди участок дороги, занесённый снегом.","w":{"uk":"На знаку зображено камінці, що вилітають з-під коліс автомобіля, а не сніг.","ru":"На знаке изображены камешки, вылетающие из-под колёс автомобиля, а не снег."}},{"uk":"Про те, що попереду ділянка дороги, що має нерівності проїзної частини.","ru":"О том, что впереди участок дороги, имеющий неровности проезжей части.","w":{"uk":"Нерівності проїзної частини позначає знак {s:1.10} «Нерівна дорога».","ru":"Неровности проезжей части обозначает знак {s:1.10} «Неровная дорога»."}},{"uk":"Попереду ділянка дороги, на якій можливе викидання гравію, щебеню тощо з-під коліс транспортних засобів.","ru":"Впереди участок дороги, на котором возможен выброс гравия, щебня и т. п. из-под колёс транспортных средств."}],"c":3,"e":{"uk":"Знак {s:1.14} «Викидання кам'яних матеріалів» попереджає про ділянку дороги, на якій можливе викидання гравію, щебеню тощо з-під коліс транспортних засобів ({p:33.1}).","ru":"Знак {s:1.14} «Выброс каменных материалов» предупреждает об участке дороги, на котором возможен выброс гравия, щебня и т. п. из-под колёс транспортных средств ({p:33.1})."},"ref":["33.1"],"pic":["img/hsc/33-248-1.jpg"]},{"id":"h33-249","t":"h33","num":"33.249","q":{"uk":"Даний дорожній знак встановлюється перед ділянками дороги, на яких:","ru":"Данный дорожный знак устанавливается перед участками дороги, на которых:"},"a":[{"uk":"Підвищене, занижене, зруйноване узбіччя або на узбіччі виконують ремонтні роботи.","ru":"Повышенная, пониженная, разрушенная обочина или на обочине выполняются ремонтные работы."},{"uk":"Можливе викидання гравію, щебеню тощо з-під коліс транспортних засобів.","ru":"Возможен выброс гравия, щебня и т. п. из-под колёс транспортных средств.","w":{"uk":"Про викидання гравію та щебеню попереджає знак {s:1.14} «Викидання кам'яних матеріалів».","ru":"О выбросе гравия и щебня предупреждает знак {s:1.14} «Выброс каменных материалов»."}},{"uk":"Виконуються дорожні роботи.","ru":"Выполняются дорожные работы.","w":{"uk":"Про дорожні роботи попереджає знак {s:1.37} «Дорожні роботи» із зображенням робітника з лопатою.","ru":"О дорожных работах предупреждает знак {s:1.37} «Дорожные работы» с изображением рабочего с лопатой."}},{"uk":"Є нерівності проїзної частини – хвилястості, напливи, спучування.","ru":"Имеются неровности проезжей части — волнистость, наплывы, вспучивания.","w":{"uk":"Нерівності проїзної частини позначає знак {s:1.10} «Нерівна дорога».","ru":"Неровности проезжей части обозначает знак {s:1.10} «Неровная дорога»."}}],"c":0,"e":{"uk":"Це знак {s:1.15} «Небезпечне узбіччя»: підвищене, занижене, зруйноване узбіччя або узбіччя, на якому виконуються ремонтні роботи ({p:33.1}).","ru":"Это знак {s:1.15} «Опасная обочина»: повышенная, пониженная, разрушенная обочина или обочина, на которой выполняются ремонтные работы ({p:33.1})."},"ref":["33.1"],"pic":["img/hsc/33-249-1.jpg"]},{"id":"h33-250","t":"h33","num":"33.250","q":{"uk":"Даний дорожній знак встановлюється перед ділянкою дороги, на якій:","ru":"Данный дорожный знак устанавливается перед участком дороги, на котором:"},"a":[{"uk":"Можливі сильний боковий вітер або його раптові пориви.","ru":"Возможны сильный боковой ветер или его внезапные порывы.","w":{"uk":"Про боковий вітер попереджає знак {s:1.17} «Боковий вітер».","ru":"О боковом ветре предупреждает знак {s:1.17} «Боковой ветер»."}},{"uk":"Можуть бути падіння каміння, обвали, зсуви.","ru":"Возможны падение камней, обвалы, оползни."},{"uk":"Можливе викидання гравію, щебеню тощо з-під коліс транспортних засобів.","ru":"Возможен выброс гравия, щебня и т. п. из-под колёс транспортных средств.","w":{"uk":"Про викидання гравію з-під коліс попереджає знак {s:1.14} «Викидання кам'яних матеріалів».","ru":"О выбросе гравия из-под колёс предупреждает знак {s:1.14} «Выброс каменных материалов»."}},{"uk":"Крутий підйом.","ru":"Крутой подъём.","w":{"uk":"Крутий підйом позначає знак {s:1.6} «Крутий підйом» із зазначенням ухилу у відсотках.","ru":"Крутой подъём обозначает знак {s:1.6} «Крутой подъём» с указанием уклона в процентах."}}],"c":1,"e":{"uk":"Це знак {s:1.16} «Падіння каміння»: ділянка дороги, на якій можуть бути падіння каміння, обвали, зсуви ({p:33.1}).","ru":"Это знак {s:1.16} «Падение камней»: участок дороги, на котором возможны падение камней, обвалы, оползни ({p:33.1})."},"ref":["33.1"],"pic":["img/hsc/33-250-1.jpg"]},{"id":"h33-251","t":"h33","num":"33.251","q":{"uk":"Даний дорожній знак попереджає:","ru":"Данный дорожный знак предупреждает:"},"a":[{"uk":"Про наближення до перехрестя з обмеженою оглядовістю.","ru":"О приближении к перекрёстку с ограниченной обзорностью.","w":{"uk":"Знак показує не обмежену оглядовість, а конфігурацію перехрестя: зліва прилягає другорядна дорога.","ru":"Знак показывает не ограниченную обзорность, а конфигурацию перекрёстка: слева примыкает второстепенная дорога."}},{"uk":"Про наближення до перехрестя рівнозначних доріг.","ru":"О приближении к перекрёстку равнозначных дорог.","w":{"uk":"Перехрещення рівнозначних доріг позначає знак {s:1.21} із зображенням косого хреста.","ru":"Пересечение равнозначных дорог обозначает знак {s:1.21} с изображением косого креста."}},{"uk":"Про наближення до прилягання другорядної дороги з лівого боку.","ru":"О приближении к примыканию второстепенной дороги слева."},{"uk":"Про наближення до місця, де дорога звужується зліва.","ru":"О приближении к месту, где дорога сужается слева.","w":{"uk":"Звуження дороги з лівого боку позначає знак {s:1.5.3} «Звуження дороги».","ru":"Сужение дороги слева обозначает знак {s:1.5.3} «Сужение дороги»."}}],"c":2,"e":{"uk":"Це знак {s:1.23.2} «Прилягання другорядної дороги» з лівого боку; зображення прилягання на знаку відповідає реальній конфігурації перехрестя ({p:33.1}).","ru":"Это знак {s:1.23.2} «Примыкание второстепенной дороги» слева; изображение примыкания на знаке соответствует реальной конфигурации перекрёстка ({p:33.1})."},"ref":["33.1"],"pic":["img/hsc/33-251-1.jpg"]},{"id":"h33-252","t":"h33","num":"33.252","q":{"uk":"Який дорожній знак встановлено на найближчому перехресті після знаку дати дорогу з зазначеною табличкою?","ru":"Какой дорожный знак установлен на ближайшем перекрёстке после знака «Уступить дорогу» с указанной табличкой?"},"a":[{"uk":"Знак 1.","ru":"Знак 1."},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Перед знаком {s:2.2} «Проїзд без зупинки заборонено» попередній знак {s:2.1} мав би табличку {s:7.1.2} з написом «STOP» і відстанню ({p:33.7}), а тут лише відстань.","ru":"Перед знаком {s:2.2} «Проезд без остановки запрещён» предварительный знак {s:2.1} имел бы табличку {s:7.1.2} с надписью «STOP» и расстоянием ({p:33.7}), а здесь только расстояние."}},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — попереджувальний {s:1.39} «Інша небезпека»: він не є знаком пріоритету і не може бути тим знаком, який повторює {s:2.1}.","ru":"Знак 3 — предупреждающий {s:1.39} «Иная опасность»: он не является знаком приоритета и не может быть тем знаком, который повторяет {s:2.1}."}}],"c":0,"e":{"uk":"Поза населеними пунктами на дорогах з твердим покриттям знак {s:2.1} «Дати дорогу» повторюється заздалегідь з табличкою {s:7.1.1} «Відстань до об'єкта» ({p:33.2}), тож через 300 м, на перехресті, стоїть такий самий знак {s:2.1} (знак 1).","ru":"Вне населённых пунктов на дорогах с твёрдым покрытием знак {s:2.1} «Уступить дорогу» повторяется заранее с табличкой {s:7.1.1} «Расстояние до объекта» ({p:33.2}), поэтому через 300 м, на перекрёстке, стоит такой же знак {s:2.1} (знак 1)."},"ref":["33.2","33.7"],"pic":["img/hsc/33-252-1.jpg"]},{"id":"h33-253","t":"h33","num":"33.253","q":{"uk":"Представлений дорожній знак забороняє рух:","ru":"Представленный дорожный знак запрещает движение:"},"a":[{"uk":"Гужових возів (саней).","ru":"Гужевых повозок (саней).","w":{"uk":"Відповідь неповна: знак забороняє також рух тварин під сідлом або в'юком і прогін худоби.","ru":"Ответ неполный: знак запрещает также движение животных под седлом или вьюком и прогон скота."}},{"uk":"Тварин під сідлом або в'юком і прогін худоби.","ru":"Животных под седлом или вьюком и прогон скота.","w":{"uk":"Відповідь неповна: знак забороняє передусім рух гужових возів (саней).","ru":"Ответ неполный: знак запрещает прежде всего движение гужевых повозок (саней)."}},{"uk":"Рух пішоходів.","ru":"Движение пешеходов.","w":{"uk":"Рух пішоходів забороняє інший знак — {s:3.9} «Рух пішоходів заборонено».","ru":"Движение пешеходов запрещает другой знак — {s:3.9} «Движение пешеходов запрещено»."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3.","w":{"uk":"Пішоходів знак {s:3.11} не стосується: для них є окремий знак {s:3.9}.","ru":"Пешеходов знак {s:3.11} не касается: для них есть отдельный знак {s:3.9}."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2."}],"c":4,"e":{"uk":"Знак {s:3.11} «Рух гужових возів (саней) заборонено» забороняє рух гужових возів (саней), тварин під сідлом або в'юком, а також прогін худоби ({p:33.3}).","ru":"Знак {s:3.11} «Движение гужевых повозок (саней) запрещено» запрещает движение гужевых повозок (саней), животных под седлом или вьюком, а также прогон скота ({p:33.3})."},"ref":["33.3"],"pic":["img/hsc/33-253-1.jpg"]},{"id":"h33-254","t":"h33","num":"33.254","q":{"uk":"У якому із зазначених напрямків Вам дозволено рух у зображеній ситуації?","ru":"В каком из указанных направлений вам разрешено движение в изображённой ситуации?"},"a":[{"uk":"У напрямку А.","ru":"В направлении А.","w":{"uk":"Відповідь неповна: поворот праворуч у напрямку Б, розташований далі, знак {s:3.22} не забороняє.","ru":"Ответ неполный: поворот направо в направлении Б, расположенный дальше, знак {s:3.22} не запрещает."}},{"uk":"У напрямках В і Б.","ru":"В направлениях В и Б.","w":{"uk":"Поворот у напрямку В — саме те місце, перед яким установлено знак {s:3.22}, тому він заборонений.","ru":"Поворот в направлении В — именно то место, перед которым установлен знак {s:3.22}, поэтому он запрещён."}},{"uk":"У напрямках А і Б.","ru":"В направлениях А и Б."},{"uk":"У напрямках А і В.","ru":"В направлениях А и В.","w":{"uk":"Поворот у напрямку В заборонено знаком {s:3.22}, а дозволений напрямок Б у цій відповіді пропущено.","ru":"Поворот в направлении В запрещён знаком {s:3.22}, а разрешённое направление Б в этом ответе пропущено."}}],"c":2,"e":{"uk":"Дія знака {s:3.22} «Поворот праворуч заборонено» поширюється лише на перехрещення проїзних частин чи інше місце, перед яким його встановлено ({p:33.3}), — тут це найближчий поворот праворуч у напрямку В. Рух прямо (А) і поворот праворуч далі, у напрямку Б, знак не забороняє.","ru":"Действие знака {s:3.22} «Поворот направо запрещён» распространяется только на пересечение проезжих частей или другое место, перед которым он установлен ({p:33.3}), — здесь это ближайший поворот направо в направлении В. Движение прямо (А) и поворот направо дальше, в направлении Б, знак не запрещает."},"ref":["33.3"],"pic":["img/hsc/33-254-1.jpg"]},{"id":"h33-255","t":"h33","num":"33.255","q":{"uk":"По якій із зображених траєкторій Вам дозволено повернути праворуч?","ru":"По какой из изображённых траекторий вам разрешено повернуть направо?"},"a":[{"uk":"У напрямку А.","ru":"В направлении А."},{"uk":"У напрямку Б.","ru":"В направлении Б.","w":{"uk":"Траєкторія Б веде на поворот, перед яким установлено знак {s:3.22}, тож там повертати праворуч заборонено.","ru":"Траектория Б ведёт на поворот, перед которым установлен знак {s:3.22}, поэтому там поворачивать направо запрещено."}},{"uk":"У будь-якому із зазначених напрямків.","ru":"В любом из указанных направлений.","w":{"uk":"Поворот праворуч у напрямку Б заборонено знаком {s:3.22}.","ru":"Поворот направо в направлении Б запрещён знаком {s:3.22}."}}],"c":0,"e":{"uk":"Знак {s:3.22} «Поворот праворуч заборонено» стоїть за першим поворотом, перед місцем повороту Б, а діє він лише на місце, перед яким установлений ({p:33.3}). Тому поворот праворуч по траєкторії А, розташований до знака, дозволено.","ru":"Знак {s:3.22} «Поворот направо запрещён» стоит за первым поворотом, перед местом поворота Б, а действует он только на место, перед которым установлен ({p:33.3}). Поэтому поворот направо по траектории А, расположенный до знака, разрешён."},"ref":["33.3"],"pic":["img/hsc/33-255-1.jpg"]},{"id":"h33-256","t":"h33","num":"33.256","q":{"uk":"Чи дозволено Вам виконати розворот на зображеному перехресті?","ru":"Разрешено ли вам выполнить разворот на изображённом перекрёстке?"},"a":[{"uk":"Заборонено.","ru":"Запрещено.","w":{"uk":"Розворот заборонив би знак {s:3.24} «Розворот заборонено»; знак {s:3.23} забороняє тільки поворот ліворуч.","ru":"Разворот запретил бы знак {s:3.24} «Разворот запрещён»; знак {s:3.23} запрещает только поворот налево."}},{"uk":"Дозволено.","ru":"Разрешено."}],"c":1,"e":{"uk":"Знак {s:3.23} «Поворот ліворуч заборонено» забороняє лише поворот ліворуч, а розворот при цьому **дозволяється** ({p:33.3}).","ru":"Знак {s:3.23} «Поворот налево запрещён» запрещает только поворот налево, а разворот при этом **разрешается** ({p:33.3})."},"ref":["33.3"],"pic":["img/hsc/33-256-1.jpg"]},{"id":"h33-257","t":"h33","num":"33.257","q":{"uk":"По якій з траєкторій Вам дозволено повернути ліворуч?","ru":"По какой из траекторий вам разрешено повернуть налево?"},"a":[{"uk":"По траєкторії А.","ru":"По траектории А.","w":{"uk":"Траєкторія А — поворот ліворуч саме на тому перехресті, перед яким стоїть знак {s:3.23}.","ru":"Траектория А — поворот налево именно на том перекрёстке, перед которым стоит знак {s:3.23}."}},{"uk":"По траєкторії Б.","ru":"По траектории Б."},{"uk":"По траєкторіях А і Б.","ru":"По траекториям А и Б.","w":{"uk":"Поворот ліворуч по траєкторії А заборонено знаком {s:3.23}.","ru":"Поворот налево по траектории А запрещён знаком {s:3.23}."}}],"c":1,"e":{"uk":"Дія знака {s:3.23} «Поворот ліворуч заборонено» поширюється лише на перехрещення проїзних частин, перед яким його встановлено ({p:33.3}): на цьому перехресті повертати ліворуч (А) не можна, а поворот ліворуч за перехрестям (Б) знак не забороняє.","ru":"Действие знака {s:3.23} «Поворот налево запрещён» распространяется только на пересечение проезжих частей, перед которым он установлен ({p:33.3}): на этом перекрёстке поворачивать налево (А) нельзя, а поворот налево за перекрёстком (Б) знак не запрещает."},"ref":["33.3"],"pic":["img/hsc/33-257-1.jpg"]},{"id":"h33-258","t":"h33","num":"33.258","q":{"uk":"По якій з траєкторій Вам дозволено рух у зображеній ситуації?","ru":"По какой из траекторий вам разрешено движение в изображённой ситуации?"},"a":[{"uk":"По траєкторії В.","ru":"По траектории В.","w":{"uk":"Відповідь неповна: поворот ліворуч за перехрестям (Б) знак {s:3.23} не забороняє.","ru":"Ответ неполный: поворот налево за перекрёстком (Б) знак {s:3.23} не запрещает."}},{"uk":"По траєкторіях А, Б і В.","ru":"По траекториям А, Б и В.","w":{"uk":"Траєкторія А — поворот ліворуч на перехресті, перед яким стоїть знак {s:3.23}, тому вона заборонена.","ru":"Траектория А — поворот налево на перекрёстке, перед которым стоит знак {s:3.23}, поэтому она запрещена."}},{"uk":"По траєкторіях Б і В.","ru":"По траекториям Б и В."},{"uk":"По траєкторіях А і В.","ru":"По траекториям А и В.","w":{"uk":"Поворот ліворуч по траєкторії А заборонено, а дозволену траєкторію Б у цій відповіді пропущено.","ru":"Поворот налево по траектории А запрещён, а разрешённая траектория Б в этом ответе пропущена."}}],"c":2,"e":{"uk":"Знак {s:3.23} «Поворот ліворуч заборонено» забороняє поворот ліворуч лише на перехресті, перед яким його встановлено ({p:33.3}), — це траєкторія А. Рух прямо (В) і поворот ліворуч за перехрестям (Б) дозволено.","ru":"Знак {s:3.23} «Поворот налево запрещён» запрещает поворот налево только на перекрёстке, перед которым он установлен ({p:33.3}), — это траектория А. Движение прямо (В) и поворот налево за перекрёстком (Б) разрешены."},"ref":["33.3"],"pic":["img/hsc/33-258-1.jpg"]},{"id":"h33-259","t":"h33","num":"33.259","q":{"uk":"Чи дозволено Вам повернути ліворуч у зображеній ситуації?","ru":"Разрешено ли вам повернуть налево в изображённой ситуации?"},"a":[{"uk":"Дозволено.","ru":"Разрешено."},{"uk":"Заборонено.","ru":"Запрещено.","w":{"uk":"Поворот ліворуч заборонив би знак {s:3.23}; знак {s:3.24} поворот ліворуч прямо дозволяє.","ru":"Поворот налево запретил бы знак {s:3.23}; знак {s:3.24} поворот налево прямо разрешает."}}],"c":0,"e":{"uk":"Знаки {s:3.24} «Розворот заборонено» забороняють лише розворот, а поворот ліворуч при цьому **дозволяється** ({p:33.3}).","ru":"Знаки {s:3.24} «Разворот запрещён» запрещают только разворот, а поворот налево при этом **разрешается** ({p:33.3})."},"ref":["33.3"],"pic":["img/hsc/33-259-1.jpg"]},{"id":"h33-260","t":"h33","num":"33.260","q":{"uk":"По якій з траєкторій Вам дозволено виконати розворот у зображеній ситуації?","ru":"По какой из траекторий вам разрешено выполнить разворот в изображённой ситуации?"},"a":[{"uk":"По траєкторії А.","ru":"По траектории А.","w":{"uk":"Траєкторія А — розворот саме на перехресті, перед яким стоїть знак {s:3.24}.","ru":"Траектория А — разворот именно на перекрёстке, перед которым стоит знак {s:3.24}."}},{"uk":"По траєкторії Б.","ru":"По траектории Б."},{"uk":"По будь-якій траєкторії.","ru":"По любой траектории.","w":{"uk":"Розворот по траєкторії А заборонено знаком {s:3.24}.","ru":"Разворот по траектории А запрещён знаком {s:3.24}."}}],"c":1,"e":{"uk":"Знак {s:3.24} «Розворот заборонено» діє на перехрещення проїзних частин, перед яким його встановлено ({p:33.3}), тому розвернутися на самому перехресті (А) не можна, а за перехрестям (Б) — можна.","ru":"Знак {s:3.24} «Разворот запрещён» действует на пересечение проезжих частей, перед которым он установлен ({p:33.3}), поэтому развернуться на самом перекрёстке (А) нельзя, а за перекрёстком (Б) — можно."},"ref":["33.3"],"pic":["img/hsc/33-260-1.jpg"]},{"id":"h33-261","t":"h33","num":"33.261","q":{"uk":"Який із зображених дорожніх знаків забороняє розворот?","ru":"Какой из изображённых дорожных знаков запрещает разворот?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:3.22} «Поворот праворуч заборонено».","ru":"Знак 1 — {s:3.22} «Поворот направо запрещён»."}},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:3.23} «Поворот ліворуч заборонено»: за цим знаком розворот дозволяється.","ru":"Знак 2 — {s:3.23} «Поворот налево запрещён»: при этом знаке разворот разрешается."}},{"uk":"Знак 3.","ru":"Знак 3."},{"uk":"Знаки 2 і 3.","ru":"Знаки 2 и 3.","w":{"uk":"Знак 2 ({s:3.23}) розворот не забороняє — Правила прямо дозволяють розворот у зоні його дії.","ru":"Знак 2 ({s:3.23}) разворот не запрещает — Правила прямо разрешают разворот в зоне его действия."}}],"c":2,"e":{"uk":"Знак 3 — {s:3.24} «Розворот заборонено»: він забороняє розворот, а поворот ліворуч при цьому дозволяє ({p:33.3}).","ru":"Знак 3 — {s:3.24} «Разворот запрещён»: он запрещает разворот, а поворот налево при этом разрешает ({p:33.3})."},"ref":["33.3"],"pic":["img/hsc/33-261-1.jpg"]},{"id":"h33-262","t":"h33","num":"33.262","q":{"uk":"З якою метою може бути встановлений даний дорожній знак?","ru":"С какой целью может быть установлен данный дорожный знак?"},"a":[{"uk":"З метою запобігання зустрічному руху транспортних засобів на ділянках доріг з одностороннім рухом.","ru":"С целью предотвращения встречного движения транспортных средств на участках дорог с односторонним движением.","w":{"uk":"Це лише одна з цілей: знак також застосовують на дорогах зі смугою для маршрутних транспортних засобів, на стоянках і АЗС та перед окремою смугою руху.","ru":"Это лишь одна из целей: знак также применяют на дорогах с полосой для маршрутных транспортных средств, на стоянках и АЗС и перед отдельной полосой движения."}},{"uk":"З метою запобігання виїзду транспортних засобів назустріч загальному потоку на двосмуговій дорозі зі смугою руху для маршрутного транспорту.","ru":"С целью предотвращения выезда транспортных средств навстречу общему потоку на двухполосной дороге с полосой движения для маршрутного транспорта.","w":{"uk":"Це лише одна з цілей: знак також запобігає зустрічному руху на дорогах з одностороннім рухом, відокремлює в'їзд і виїзд на стоянках і АЗС та забороняє в'їзд на окрему смугу.","ru":"Это лишь одна из целей: знак также предотвращает встречное движение на дорогах с односторонним движением, обособляет въезд и выезд на стоянках и АЗС и запрещает въезд на отдельную полосу."}},{"uk":"З метою організації відокремленого в'їзду і виїзду на майданчиках, що використовуються для стоянки транспортних засобів, автозаправних станціях і т. д.","ru":"С целью организации обособленного въезда и выезда на площадках, используемых для стоянки транспортных средств, автозаправочных станциях и т. д.","w":{"uk":"Це лише одна з цілей: знак також ставлять на дорогах з одностороннім рухом, на дорогах зі смугою для маршрутних транспортних засобів і перед окремою смугою руху.","ru":"Это лишь одна из целей: знак также ставят на дорогах с односторонним движением, на дорогах с полосой для маршрутных транспортных средств и перед отдельной полосой движения."}},{"uk":"З метою запобігання в'їзду на окрему смугу руху.","ru":"С целью предотвращения въезда на отдельную полосу движения.","w":{"uk":"Це лише одна з цілей (у такому разі знак застосовують з табличкою {s:7.9}); решту перелічених цілей Правила теж передбачають.","ru":"Это лишь одна из целей (в таком случае знак применяют с табличкой {s:7.9}); остальные перечисленные цели Правила тоже предусматривают."}},{"uk":"Відповіді 1, 2, 3 і 4.","ru":"Ответы 1, 2, 3 и 4."}],"c":4,"e":{"uk":"Знак {s:3.21} «В'їзд заборонено» застосовують, щоб запобігти зустрічному руху на дорогах з одностороннім рухом і виїзду назустріч загальному потоку на дорогах зі смугою для маршрутних транспортних засобів, щоб організувати відокремлений в'їзд і виїзд на стоянках, АЗС тощо, а також (з табличкою {s:7.9}) щоб заборонити в'їзд на окрему смугу ({p:33.3}).","ru":"Знак {s:3.21} «Въезд запрещён» применяют, чтобы предотвратить встречное движение на дорогах с односторонним движением и выезд навстречу общему потоку на дорогах с полосой для маршрутных транспортных средств, чтобы организовать обособленный въезд и выезд на стоянках, АЗС и т. п., а также (с табличкой {s:7.9}) чтобы запретить въезд на отдельную полосу ({p:33.3})."},"ref":["33.3"],"pic":["img/hsc/33-262-1.jpg"]},{"id":"h33-263","t":"h33","num":"33.263","q":{"uk":"У якому напрямку Вам дозволено рух у даній ситуації?","ru":"В каком направлении вам разрешено движение в данной ситуации?"},"a":[{"uk":"У напрямках Б і В.","ru":"В направлениях Б и В.","w":{"uk":"Рух прямо (А) теж дозволено: ця траєкторія веде не на смугу, позначену знаком {s:3.21} з табличкою {s:7.9}.","ru":"Движение прямо (А) тоже разрешено: эта траектория ведёт не на полосу, обозначенную знаком {s:3.21} с табличкой {s:7.9}."}},{"uk":"У напрямках А і Б.","ru":"В направлениях А и Б.","w":{"uk":"Відповідь неповна: напрямок В теж дозволено, бо знак стосується лише однієї смуги.","ru":"Ответ неполный: направление В тоже разрешено, поскольку знак касается только одной полосы."}},{"uk":"У напрямках А і В.","ru":"В направлениях А и В.","w":{"uk":"Відповідь неповна: напрямок Б теж дозволено, бо знак стосується лише однієї смуги.","ru":"Ответ неполный: направление Б тоже разрешено, поскольку знак касается только одной полосы."}},{"uk":"У напрямках А, Б і В.","ru":"В направлениях А, Б и В."}],"c":3,"e":{"uk":"Знак {s:3.21} «В'їзд заборонено» з табличкою {s:7.9} «Смуга руху» забороняє в'їзд лише на ту смугу, над якою його встановлено ({p:33.3}, {p:33.7}); жодна з траєкторій А, Б і В на цю смугу не веде, тож рух дозволено в усіх трьох напрямках.","ru":"Знак {s:3.21} «Въезд запрещён» с табличкой {s:7.9} «Полоса движения» запрещает въезд только на ту полосу, над которой он установлен ({p:33.3}, {p:33.7}); ни одна из траекторий А, Б и В на эту полосу не ведёт, поэтому движение разрешено во всех трёх направлениях."},"ref":["33.3","33.7"],"pic":["img/hsc/33-263-1.jpg"]},{"id":"h33-264","t":"h33","num":"33.264","q":{"uk":"Який із зображених дорожніх знаків забороняє рух транспортних засобів, що перевозять вибухові та легкозаймисті вантажі?","ru":"Какой из изображённых дорожных знаков запрещает движение транспортных средств, перевозящих взрывчатые и легковоспламеняющиеся грузы?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:3.2} «Рух механічних транспортних засобів заборонено».","ru":"Знак 1 — {s:3.2} «Движение механических транспортных средств запрещено»."}},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:3.14}: він забороняє рух транспортних засобів, що перевозять речовини, які забруднюють воду.","ru":"Знак 2 — {s:3.14}: он запрещает движение транспортных средств, перевозящих вещества, загрязняющие воду."}},{"uk":"Знак 3.","ru":"Знак 3."},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Знак 4 — {s:3.15}: він забороняє рух транспортних засобів, фактична маса яких перевищує 7 т.","ru":"Знак 4 — {s:3.15}: он запрещает движение транспортных средств, фактическая масса которых превышает 7 т."}},{"uk":"Знаки 2 і 3.","ru":"Знаки 2 и 3.","w":{"uk":"Знак 2 ({s:3.14}) стосується речовин, які забруднюють воду, а не вибухових і легкозаймистих вантажів.","ru":"Знак 2 ({s:3.14}) касается веществ, загрязняющих воду, а не взрывчатых и легковоспламеняющихся грузов."}}],"c":2,"e":{"uk":"Знак 3 — {s:3.13} (автомобіль на тлі вибуху): заборонено рух транспортних засобів з розпізнавальним знаком «Табличка оранжевого кольору», що перевозять вибухові та легкозаймисті вантажі ({p:33.3}).","ru":"Знак 3 — {s:3.13} (автомобиль на фоне взрыва): запрещено движение транспортных средств с опознавательным знаком «Табличка оранжевого цвета», перевозящих взрывчатые и легковоспламеняющиеся грузы ({p:33.3})."},"ref":["33.3"],"pic":["img/hsc/33-264-1.jpg"]},{"id":"h33-265","t":"h33","num":"33.265","q":{"uk":"Зображений дорожній знак забороняє рух:","ru":"Изображённый дорожный знак запрещает движение:"},"a":[{"uk":"Транспортних засобів, що перевозять речовини, які забруднюють навколишнє середовище.","ru":"Транспортных средств, перевозящих вещества, загрязняющие окружающую среду.","w":{"uk":"Рух транспортних засобів із речовинами, які забруднюють воду, забороняє інший знак — {s:3.14}.","ru":"Движение транспортных средств с веществами, загрязняющими воду, запрещает другой знак — {s:3.14}."}},{"uk":"Транспортних засобів, що перевозять великовагові вантажі.","ru":"Транспортных средств, перевозящих тяжеловесные грузы.","w":{"uk":"Обмеження за масою встановлює знак {s:3.15}, за навантаженням на вісь — {s:3.16}; знак {s:3.13} стосується характеру вантажу, а не його ваги.","ru":"Ограничение по массе устанавливает знак {s:3.15}, по нагрузке на ось — {s:3.16}; знак {s:3.13} касается характера груза, а не его веса."}},{"uk":"Транспортних засобів, що перевозять небезпечні вантажі.","ru":"Транспортных средств, перевозящих опасные грузы.","w":{"uk":"Рух транспортних засобів з будь-якими небезпечними вантажами забороняє знак {s:3.12}; знак {s:3.13} стосується лише вибухових і легкозаймистих вантажів.","ru":"Движение транспортных средств с любыми опасными грузами запрещает знак {s:3.12}; знак {s:3.13} касается только взрывчатых и легковоспламеняющихся грузов."}},{"uk":"Транспортних засобів, що перевозять вибухові та легкозаймисті вантажі.","ru":"Транспортных средств, перевозящих взрывчатые и легковоспламеняющиеся грузы."}],"c":3,"e":{"uk":"Це знак {s:3.13}: заборонено рух транспортних засобів з розпізнавальним знаком «Табличка оранжевого кольору», що перевозять вибухові та легкозаймисті вантажі ({p:33.3}).","ru":"Это знак {s:3.13}: запрещено движение транспортных средств с опознавательным знаком «Табличка оранжевого цвета», перевозящих взрывчатые и легковоспламеняющиеся грузы ({p:33.3})."},"ref":["33.3"],"pic":["img/hsc/33-265-1.jpg"]},{"id":"h33-266","t":"h33","num":"33.266","q":{"uk":"Який із зображених дорожніх знаків забороняє рух транспортних засобів, маса яких перевищує 7 т?","ru":"Какой из изображённых дорожных знаков запрещает движение транспортных средств, масса которых превышает 7 т?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:3.12}: він забороняє рух транспортних засобів, що перевозять небезпечні вантажі.","ru":"Знак 1 — {s:3.12}: он запрещает движение транспортных средств, перевозящих опасные грузы."}},{"uk":"Знак 2.","ru":"Знак 2."},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — {s:3.17}: він обмежує габаритну ширину (2,7 м), а не масу.","ru":"Знак 3 — {s:3.17}: он ограничивает габаритную ширину (2,7 м), а не массу."}},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Знак 4 — {s:3.20}: він забороняє рух із дистанцією, меншою за 70 м.","ru":"Знак 4 — {s:3.20}: он запрещает движение с дистанцией меньше 70 м."}}],"c":1,"e":{"uk":"Знак 2 — {s:3.15} з написом «7 т»: заборонено рух транспортних засобів, у тому числі їх составів, загальна фактична маса яких перевищує 7 т ({p:33.3}).","ru":"Знак 2 — {s:3.15} с надписью «7 т»: запрещено движение транспортных средств, в том числе их составов, общая фактическая масса которых превышает 7 т ({p:33.3})."},"ref":["33.3"],"pic":["img/hsc/33-266-1.jpg"]},{"id":"h33-267","t":"h33","num":"33.267","q":{"uk":"Чи дозволено в зображеній ситуації рух автопоїзду, маса якого понад 18 т?","ru":"Разрешено ли в изображённой ситуации движение автопоезда, масса которого более 18 т?"},"a":[{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"Обмеження знака {s:3.15} стосується загальної фактичної маси всього состава, тож автопоїзд масою понад 18 т під заборону підпадає.","ru":"Ограничение знака {s:3.15} касается общей фактической массы всего состава, поэтому автопоезд массой более 18 т под запрет попадает."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":1,"e":{"uk":"Знак {s:3.15} забороняє рух транспортних засобів, **у тому числі їх составів**, загальна фактична маса яких перевищує зазначену на знаку ({p:33.3}); автопоїзду масою понад 18 т на міст в'їжджати не можна.","ru":"Знак {s:3.15} запрещает движение транспортных средств, **в том числе их составов**, общая фактическая масса которых превышает указанную на знаке ({p:33.3}); автопоезду массой более 18 т въезжать на мост нельзя."},"ref":["33.3"],"pic":["img/hsc/33-267-1.jpg"]},{"id":"h33-268","t":"h33","num":"33.268","q":{"uk":"Зображений дорожній знак забороняє рух:","ru":"Изображённый дорожный знак запрещает движение:"},"a":[{"uk":"Вантажних автомобілів, габаритна ширина яких (з вантажем чи без нього) більша від зазначеної на знакові.","ru":"Грузовых автомобилей, габаритная ширина которых (с грузом или без него) больше указанной на знаке.","w":{"uk":"Заборона не обмежується вантажними автомобілями: вона стосується будь-якого транспортного засобу, ширшого за зазначене значення.","ru":"Запрет не ограничивается грузовыми автомобилями: он касается любого транспортного средства шире указанного значения."}},{"uk":"Автобусів, ширина яких більша від зазначеної на знакові.","ru":"Автобусов, ширина которых больше указанной на знаке.","w":{"uk":"Заборона не обмежується автобусами: вона стосується будь-якого транспортного засобу, ширшого за зазначене значення.","ru":"Запрет не ограничивается автобусами: он касается любого транспортного средства шире указанного значения."}},{"uk":"Тракторів і самохідних машин та механізмів, габаритна ширина яких (з вантажем чи без нього) більша від зазначеної на знакові.","ru":"Тракторов и самоходных машин и механизмов, габаритная ширина которых (с грузом или без него) больше указанной на знаке.","w":{"uk":"Заборона не обмежується тракторами й самохідними машинами: вона стосується будь-якого транспортного засобу, ширшого за зазначене значення.","ru":"Запрет не ограничивается тракторами и самоходными машинами: он касается любого транспортного средства шире указанного значения."}},{"uk":"Усіх транспортних засобів, габаритна ширина яких (з вантажем чи без нього) більша від зазначеної на знакові.","ru":"Всех транспортных средств, габаритная ширина которых (с грузом или без него) больше указанной на знаке."}],"c":3,"e":{"uk":"Знак {s:3.17} забороняє рух **усіх** транспортних засобів, габаритна ширина яких (з вантажем чи без нього) більша за зазначену на знаку ({p:33.3}).","ru":"Знак {s:3.17} запрещает движение **всех** транспортных средств, габаритная ширина которых (с грузом или без него) больше указанной на знаке ({p:33.3})."},"ref":["33.3"],"pic":["img/hsc/33-268-1.jpg"]},{"id":"h33-269","t":"h33","num":"33.269","q":{"uk":"Чи дозволено Вам у зображеній ситуації рух прямо?","ru":"Разрешено ли вам в изображённой ситуации движение прямо?"},"a":[{"uk":"Дозволено, якщо Ви там проживаєте.","ru":"Разрешено, если вы там проживаете.","w":{"uk":"Виняток для мешканців зони діє для знаків {s:3.1}–{s:3.8} і {s:3.11}, але не для знака {s:3.21}.","ru":"Исключение для жителей зоны действует для знаков {s:3.1}–{s:3.8} и {s:3.11}, но не для знака {s:3.21}."}},{"uk":"Дозволено, якщо Ви обслуговуєте підприємства, що там розташовані.","ru":"Разрешено, если вы обслуживаете предприятия, которые там расположены.","w":{"uk":"Виняток для транспорту, що обслуговує підприємства в зоні, на знак {s:3.21} не поширюється.","ru":"Исключение для транспорта, обслуживающего предприятия в зоне, на знак {s:3.21} не распространяется."}},{"uk":"Заборонено.","ru":"Запрещено."},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2.","w":{"uk":"Жоден із цих винятків не стосується знака {s:3.21}: в'їзд заборонено всім, крім маршрутних транспортних засобів.","ru":"Ни одно из этих исключений не касается знака {s:3.21}: въезд запрещён всем, кроме маршрутных транспортных средств."}}],"c":2,"e":{"uk":"Знак {s:3.21} «В'їзд заборонено» забороняє в'їзд усіх транспортних засобів ({p:33.3}). Виняток для тих, хто проживає, працює в зоні чи обслуговує розташовані в ній підприємства, Правила встановлюють лише для знаків {s:3.1}–{s:3.8} і {s:3.11}, а дія знака {s:3.21} не поширюється тільки на маршрутні транспортні засоби.","ru":"Знак {s:3.21} «Въезд запрещён» запрещает въезд всех транспортных средств ({p:33.3}). Исключение для тех, кто проживает, работает в зоне или обслуживает расположенные в ней предприятия, Правила устанавливают только для знаков {s:3.1}–{s:3.8} и {s:3.11}, а действие знака {s:3.21} не распространяется только на маршрутные транспортные средства."},"ref":["33.3"],"pic":["img/hsc/33-269-1.jpg"]},{"id":"h33-270","t":"h33","num":"33.270","q":{"uk":"Чи дозволено Вам рух прямо в зображеній ситуації?","ru":"Разрешено ли вам движение прямо в изображённой ситуации?"},"a":[{"uk":"Заборонено.","ru":"Запрещено.","w":{"uk":"Знак {s:3.21} з табличкою {s:7.9} забороняє в'їзд лише на позначену смугу для зустрічного руху маршрутних транспортних засобів, а не на всю дорогу.","ru":"Знак {s:3.21} с табличкой {s:7.9} запрещает въезд только на обозначенную полосу для встречного движения маршрутных транспортных средств, а не на всю дорогу."}},{"uk":"Дозволено.","ru":"Разрешено."}],"c":1,"e":{"uk":"Знак {s:5.8} показує дорогу зі смугою, якою маршрутні транспортні засоби рухаються назустріч загальному потоку, а знак {s:3.21} з табличкою {s:7.9} забороняє в'їзд лише на цю смугу ({p:33.3}, {p:33.5}). Рух прямо іншою смугою дозволено.","ru":"Знак {s:5.8} обозначает дорогу с полосой, по которой маршрутные транспортные средства движутся навстречу общему потоку, а знак {s:3.21} с табличкой {s:7.9} запрещает въезд только на эту полосу ({p:33.3}, {p:33.5}). Движение прямо по другой полосе разрешено."},"ref":["33.3","33.5","33.7"],"pic":["img/hsc/33-270-1.jpg"]},{"id":"h33-271","t":"h33","num":"33.271","q":{"uk":"У якому напрямку Вам дозволено рух у даній ситуації?","ru":"В каком направлении вам разрешено движение в данной ситуации?"},"a":[{"uk":"У напрямках Б і В.","ru":"В направлениях Б и В.","w":{"uk":"Рух прямо (А) теж дозволено: в'їзд заборонено лише через 300 м, а цей знак лише попереджає про це заздалегідь.","ru":"Движение прямо (А) тоже разрешено: въезд запрещён только через 300 м, а этот знак лишь заранее предупреждает об этом."}},{"uk":"У напрямках А і Б.","ru":"В направлениях А и Б.","w":{"uk":"Відповідь неповна: у напрямку В рух теж дозволено, бо на цьому перехресті знак ще не діє.","ru":"Ответ неполный: в направлении В движение тоже разрешено, поскольку на этом перекрёстке знак ещё не действует."}},{"uk":"У напрямках А і В.","ru":"В направлениях А и В.","w":{"uk":"Відповідь неповна: у напрямку Б рух теж дозволено, бо на цьому перехресті знак ще не діє.","ru":"Ответ неполный: в направлении Б движение тоже разрешено, поскольку на этом перекрёстке знак ещё не действует."}},{"uk":"У напрямках А, Б і В.","ru":"В направлениях А, Б и В."}],"c":3,"e":{"uk":"Знак {s:3.21} «В'їзд заборонено» встановлено з табличкою {s:7.1.1} «Відстань до об'єкта» (300 м): вона показує відстань до місця, де починає діяти заборона ({p:33.7}). На цьому перехресті в'їзд не заборонено, тож рух можливий у всіх напрямках — А, Б і В.","ru":"Знак {s:3.21} «Въезд запрещён» установлен с табличкой {s:7.1.1} «Расстояние до объекта» (300 м): она показывает расстояние до места, где начинает действовать запрет ({p:33.7}). На этом перекрёстке въезд не запрещён, поэтому движение возможно во всех направлениях — А, Б и В."},"ref":["33.3","33.7"],"pic":["img/hsc/33-271-1.jpg"]},{"id":"h33-272","t":"h33","num":"33.272","q":{"uk":"Дія зображених дорожніх знаків поширюється:","ru":"Действие изображённых дорожных знаков распространяется:"},"a":[{"uk":"На ділянку дороги від місця встановлення до найближчого перехрестя за ним.","ru":"На участок дороги от места установки до ближайшего перекрёстка за ним.","w":{"uk":"Зону дії «до найближчого перехрестя» мають інші заборонні знаки (наприклад {s:3.25}, {s:3.29}); знаків {s:3.22}–{s:3.24} у цьому переліку немає.","ru":"Зону действия «до ближайшего перекрёстка» имеют другие запрещающие знаки (например {s:3.25}, {s:3.29}); знаков {s:3.22}–{s:3.24} в этом перечне нет."}},{"uk":"На перехрещення проїзних частин та інші місця, перед якими встановлено один із цих знаків.","ru":"На пересечение проезжих частей и другие места, перед которыми установлен один из этих знаков."},{"uk":"У населених пунктах, де немає перехресть, – до кінця населеного пункту.","ru":"В населённых пунктах, где нет перекрёстков, — до конца населённого пункта.","w":{"uk":"Правило «до кінця населеного пункту» стосується знаків, що діють до найближчого перехрестя, а не знаків заборони повороту й розвороту.","ru":"Правило «до конца населённого пункта» касается знаков, действующих до ближайшего перекрёстка, а не знаков запрещения поворота и разворота."}},{"uk":"Відповіді 1 і 3.","ru":"Ответы 1 и 3.","w":{"uk":"Обидва ці правила визначають зону дії інших заборонних знаків, а не {s:3.22}, {s:3.23} і {s:3.24}.","ru":"Оба эти правила определяют зону действия других запрещающих знаков, а не {s:3.22}, {s:3.23} и {s:3.24}."}}],"c":1,"e":{"uk":"Це знаки {s:3.22}, {s:3.23} і {s:3.24}; їхня дія поширюється на перехрещення проїзних частин та інші місця, перед якими встановлено один із цих знаків ({p:33.3}).","ru":"Это знаки {s:3.22}, {s:3.23} и {s:3.24}; их действие распространяется на пересечение проезжих частей и другие места, перед которыми установлен один из этих знаков ({p:33.3})."},"ref":["33.3"],"pic":["img/hsc/33-272-1.jpg"]},{"id":"h33-273","t":"h33","num":"33.273","q":{"uk":"Зображений дорожній знак забороняє:","ru":"Изображённый дорожный знак запрещает:"},"a":[{"uk":"Обгін усіх транспортних засобів, крім поодиноких, що рухаються зі швидкістю менш ніж 30 км/год.","ru":"Обгон всех транспортных средств, кроме одиночных, движущихся со скоростью менее 30 км/ч."},{"uk":"Обгін усіх транспортних засобів, крім поодиноких, що рухаються зі швидкістю менш ніж 40 км/год.","ru":"Обгон всех транспортных средств, кроме одиночных, движущихся со скоростью менее 40 км/ч.","w":{"uk":"Межа швидкості для винятку — 30 км/год, а не 40.","ru":"Порог скорости для исключения — 30 км/ч, а не 40."}},{"uk":"Обгін усіх транспортних засобів, крім велосипедів і гужових возів.","ru":"Обгон всех транспортных средств, кроме велосипедов и гужевых повозок.","w":{"uk":"Виняток «крім поодиноких велосипедів і гужових возів» стосується тракторів у зоні дії знака {s:3.27}, а не знака {s:3.25}.","ru":"Исключение «кроме одиночных велосипедов и гужевых повозок» касается тракторов в зоне действия знака {s:3.27}, а не знака {s:3.25}."}},{"uk":"Обгін усіх вантажних автомобілів і тракторів.","ru":"Обгон всех грузовых автомобилей и тракторов.","w":{"uk":"Знак забороняє обганяти будь-які транспортні засоби, а не лише вантажні автомобілі й трактори.","ru":"Знак запрещает обгонять любые транспортные средства, а не только грузовые автомобили и тракторы."}}],"c":0,"e":{"uk":"Знак {s:3.25} «Обгін заборонено» забороняє обгін усіх транспортних засобів, крім поодиноких, що рухаються зі швидкістю менше ніж 30 км/год ({p:33.3}).","ru":"Знак {s:3.25} «Обгон запрещён» запрещает обгон всех транспортных средств, кроме одиночных, движущихся со скоростью менее 30 км/ч ({p:33.3})."},"ref":["33.3"],"pic":["img/hsc/33-273-1.jpg"]},{"id":"h33-274","t":"h33","num":"33.274","q":{"uk":"Чи дозволено водієві синього автомобіля виконати обгін вантажного автомобіля, що рухається зі швидкістю 50 км/год.?","ru":"Разрешено ли водителю синего автомобиля выполнить обгон грузового автомобиля, движущегося со скоростью 50 км/ч?"},"a":[{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"Швидкість вантажівки (50 км/год) більша за 30 км/год, тож виняток зі знака {s:3.25} не діє.","ru":"Скорость грузовика (50 км/ч) больше 30 км/ч, поэтому исключение из знака {s:3.25} не действует."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":1,"e":{"uk":"У зоні дії знака {s:3.25} «Обгін заборонено» можна обганяти лише поодинокі транспортні засоби, що рухаються зі швидкістю менше ніж 30 км/год ({p:33.3}); вантажівка їде 50 км/год, тому обгін заборонено.","ru":"В зоне действия знака {s:3.25} «Обгон запрещён» можно обгонять только одиночные транспортные средства, движущиеся со скоростью менее 30 км/ч ({p:33.3}); грузовик едет 50 км/ч, поэтому обгон запрещён."},"ref":["33.3"],"pic":["img/hsc/33-274-1.jpg"]},{"id":"h33-275","t":"h33","num":"33.275","q":{"uk":"Який із зображених дорожніх знаків забороняє рух з більшою швидкістю, ніж зазначено на знакові?","ru":"Какой из изображённых дорожных знаков запрещает движение со скоростью большей, чем указано на знаке?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:4.13} «Кінець обмеження мінімальної швидкості».","ru":"Знак 1 — {s:4.13} «Конец ограничения минимальной скорости»."}},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:4.12} «Обмеження мінімальної швидкості»: він вимагає їхати не повільніше від зазначеної швидкості.","ru":"Знак 2 — {s:4.12} «Ограничение минимальной скорости»: он требует ехать не медленнее указанной скорости."}},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — {s:5.33} «Рекомендована швидкість»: він лише рекомендує швидкість, а не забороняє її перевищувати.","ru":"Знак 3 — {s:5.33} «Рекомендуемая скорость»: он лишь рекомендует скорость, а не запрещает её превышать."}},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Знак 4 — {s:5.51} «Початок населеного пункту» на синьому фоні: на цій дорозі вимоги щодо руху в населених пунктах, зокрема обмеження швидкості, не діють ({p:33.5}).","ru":"Знак 4 — {s:5.51} «Начало населённого пункта» на синем фоне: на этой дороге требования к движению в населённых пунктах, в том числе ограничение скорости, не действуют ({p:33.5})."}},{"uk":"Знак 5.","ru":"Знак 5."}],"c":4,"e":{"uk":"Знак 5 — {s:3.29} «Обмеження максимальної швидкості»: забороняється рух зі швидкістю, що перевищує зазначену на знаку ({p:33.3}).","ru":"Знак 5 — {s:3.29} «Ограничение максимальной скорости»: запрещается движение со скоростью, превышающей указанную на знаке ({p:33.3})."},"ref":["33.3"],"pic":["img/hsc/33-275-1.jpg"]},{"id":"h33-276","t":"h33","num":"33.276","q":{"uk":"Який із зображених дорожніх знаків запроваджує обмеження максимальної швидкості руху?","ru":"Какой из изображённых дорожных знаков вводит ограничение максимальной скорости движения?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:4.12} «Обмеження мінімальної швидкості»: він обмежує швидкість знизу, а не зверху.","ru":"Знак 1 — {s:4.12} «Ограничение минимальной скорости»: он ограничивает скорость снизу, а не сверху."}},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:4.13} «Кінець обмеження мінімальної швидкості».","ru":"Знак 2 — {s:4.13} «Конец ограничения минимальной скорости»."}},{"uk":"Знак 3.","ru":"Знак 3."},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Знак 4 — {s:3.30} «Кінець обмеження максимальної швидкості»: він знімає обмеження, а не запроваджує його.","ru":"Знак 4 — {s:3.30} «Конец ограничения максимальной скорости»: он снимает ограничение, а не вводит его."}}],"c":2,"e":{"uk":"Знак 3 — {s:3.29} «Обмеження максимальної швидкості»: червоне коло з числом забороняє рух зі швидкістю, що перевищує зазначену ({p:33.3}).","ru":"Знак 3 — {s:3.29} «Ограничение максимальной скорости»: красный круг с числом запрещает движение со скоростью, превышающей указанную ({p:33.3})."},"ref":["33.3"],"pic":["img/hsc/33-276-1.jpg"]},{"id":"h33-277","t":"h33","num":"33.277","q":{"uk":"Зображений дорожній знак має таке значення:","ru":"Изображённый дорожный знак имеет следующее значение:"},"a":[{"uk":"Заборонено рух транспортних засобів зі швидкістю не меншою, ніж зазначено на знакові.","ru":"Запрещено движение транспортных средств со скоростью не меньше указанной на знаке.","w":{"uk":"Їхати рівно 50 км/год знак не забороняє — заборонено лише перевищувати цю швидкість; мінімальну швидкість задає синій знак {s:4.12}.","ru":"Ехать ровно 50 км/ч знак не запрещает — запрещено лишь превышать эту скорость; минимальную скорость задаёт синий знак {s:4.12}."}},{"uk":"Заборонено рух транспортних засобів зі швидкістю, що перевищує зазначену на знакові.","ru":"Запрещено движение транспортных средств со скоростью, превышающей указанную на знаке."},{"uk":"Заборонено рух транспортних засобів, загальна фактична маса яких перевищує зазначену на знакові.","ru":"Запрещено движение транспортных средств, общая фактическая масса которых превышает указанную на знаке.","w":{"uk":"Обмеження маси позначає знак {s:3.15}, на якому після числа стоїть літера «т».","ru":"Ограничение массы обозначает знак {s:3.15}, на котором после числа стоит буква «т»."}},{"uk":"Заборонено рух транспортних засобів, довжина яких (з вантажем чи без нього) перевищує зазначену на знакові.","ru":"Запрещено движение транспортных средств, длина которых (с грузом или без него) превышает указанную на знаке.","w":{"uk":"Обмеження довжини позначає знак {s:3.19}, на якому довжину вказано в метрах.","ru":"Ограничение длины обозначает знак {s:3.19}, на котором длина указана в метрах."}}],"c":1,"e":{"uk":"Це знак {s:3.29} «Обмеження максимальної швидкості»: забороняється рух зі швидкістю, що **перевищує** зазначену на знаку ({p:33.3}).","ru":"Это знак {s:3.29} «Ограничение максимальной скорости»: запрещается движение со скоростью, **превышающей** указанную на знаке ({p:33.3})."},"ref":["33.3"],"pic":["img/hsc/33-277-1.jpg"]},{"id":"h33-278","t":"h33","num":"33.278","q":{"uk":"Який із зображених дорожніх знаків позначає кінець зони дії знака «Обмеження максимальної швидкості»?","ru":"Какой из изображённых дорожных знаков обозначает конец зоны действия знака «Ограничение максимальной скорости»?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:5.1} «Автомагістраль».","ru":"Знак 1 — {s:5.1} «Автомагистраль»."}},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:3.26} «Кінець заборони обгону».","ru":"Знак 2 — {s:3.26} «Конец запрещения обгона»."}},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — {s:4.13} «Кінець обмеження мінімальної швидкості»: він скасовує знак {s:4.12}, а не {s:3.29}.","ru":"Знак 3 — {s:4.13} «Конец ограничения минимальной скорости»: он отменяет знак {s:4.12}, а не {s:3.29}."}},{"uk":"Знак 4.","ru":"Знак 4."}],"c":3,"e":{"uk":"Знак 4 — {s:3.30} «Кінець обмеження максимальної швидкості»: ним закінчується зона дії знака {s:3.29} ({p:33.3}).","ru":"Знак 4 — {s:3.30} «Конец ограничения максимальной скорости»: им заканчивается зона действия знака {s:3.29} ({p:33.3})."},"ref":["33.3"],"pic":["img/hsc/33-278-1.jpg"]},{"id":"h33-279","t":"h33","num":"33.279","q":{"uk":"Який із зображених дорожніх знаків позначає кінець дії обмеження максимальної швидкості руху, встановленого відповідним дорожнім знаком?","ru":"Какой из изображённых дорожных знаков обозначает конец действия ограничения максимальной скорости движения, установленного соответствующим дорожным знаком?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:5.12} «Кінець смуги для руху маршрутних транспортних засобів».","ru":"Знак 1 — {s:5.12} «Конец полосы для движения маршрутных транспортных средств»."}},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:4.13} «Кінець обмеження мінімальної швидкості».","ru":"Знак 2 — {s:4.13} «Конец ограничения минимальной скорости»."}},{"uk":"Знак 3.","ru":"Знак 3."},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Знак 4 — {s:3.39} «Кінець зони обмеженої стоянки».","ru":"Знак 4 — {s:3.39} «Конец зоны ограниченной стоянки»."}}],"c":2,"e":{"uk":"Знак 3 — {s:3.30} «Кінець обмеження максимальної швидкості»: ним закінчується зона дії знака {s:3.29} ({p:33.3}).","ru":"Знак 3 — {s:3.30} «Конец ограничения максимальной скорости»: им заканчивается зона действия знака {s:3.29} ({p:33.3})."},"ref":["33.3"],"pic":["img/hsc/33-279-1.jpg"]},{"id":"h33-280","t":"h33","num":"33.280","q":{"uk":"Зображений дорожній знак має таке значення:","ru":"Изображённый дорожный знак имеет следующее значение:"},"a":[{"uk":"На ділянці дороги, перед якою встановлений, забороняє рух зі швидкістю, що перевищує зазначену на знакові.","ru":"На участке дороги, перед которым установлен, запрещает движение со скоростью, превышающей указанную на знаке.","w":{"uk":"Так діє знак {s:3.29} — до найближчого перехрестя; знак {s:3.31} з написом «ЗОНА» поширює дію на всю зону.","ru":"Так действует знак {s:3.29} — до ближайшего перекрёстка; знак {s:3.31} с надписью «ЗОНА» распространяет действие на всю зону."}},{"uk":"У зоні, на в'їзді в яку встановлений, забороняє рух зі швидкістю, що перевищує зазначену на знакові.","ru":"В зоне, на въезде в которую установлен, запрещает движение со скоростью, превышающей указанную на знаке."}],"c":1,"e":{"uk":"Це знак {s:3.31} «Зона обмеження максимальної швидкості»: у зоні (населений пункт, мікрорайон, зона відпочинку тощо) забороняється рух зі швидкістю, що перевищує зазначену на знаку, і його дія поширюється на всю зону ({p:33.3}).","ru":"Это знак {s:3.31} «Зона ограничения максимальной скорости»: в зоне (населённый пункт, микрорайон, зона отдыха и т. п.) запрещается движение со скоростью, превышающей указанную на знаке, и его действие распространяется на всю зону ({p:33.3})."},"ref":["33.3"],"pic":["img/hsc/33-280-1.jpg"]},{"id":"h33-281","t":"h33","num":"33.281","q":{"uk":"Який із зображених дорожніх знаків позначає кінець зони дії знака «Зона обмеження максимальної швидкості»?","ru":"Какой из изображённых дорожных знаков обозначает конец зоны действия знака «Зона ограничения максимальной скорости»?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:4.13} «Кінець обмеження мінімальної швидкості».","ru":"Знак 1 — {s:4.13} «Конец ограничения минимальной скорости»."}},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:3.26} «Кінець заборони обгону».","ru":"Знак 2 — {s:3.26} «Конец запрещения обгона»."}},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — {s:3.30}: він закінчує дію знака {s:3.29}, а не зону, позначену знаком {s:3.31}.","ru":"Знак 3 — {s:3.30}: он заканчивает действие знака {s:3.29}, а не зону, обозначенную знаком {s:3.31}."}},{"uk":"Знак 4.","ru":"Знак 4."},{"uk":"Знак 5.","ru":"Знак 5.","w":{"uk":"Знак 5 — {s:3.20}: він забороняє рух із дистанцією, меншою за 70 м.","ru":"Знак 5 — {s:3.20}: он запрещает движение с дистанцией меньше 70 м."}}],"c":3,"e":{"uk":"Знак 4 — {s:3.32} «Кінець зони обмеження максимальної швидкості»: ним закінчується зона дії знака {s:3.31} ({p:33.3}).","ru":"Знак 4 — {s:3.32} «Конец зоны ограничения максимальной скорости»: им заканчивается зона действия знака {s:3.31} ({p:33.3})."},"ref":["33.3"],"pic":["img/hsc/33-281-1.jpg"]},{"id":"h33-282","t":"h33","num":"33.282","q":{"uk":"Чи дозволено в зоні дії зображеного дорожнього знака користуватися звуковим сигналом?","ru":"Разрешено ли в зоне действия изображённого дорожного знака пользоваться звуковым сигналом?"},"a":[{"uk":"Заборонено.","ru":"Запрещено.","w":{"uk":"Заборона не абсолютна: щоб запобігти ДТП, звуковий сигнал подати можна.","ru":"Запрет не абсолютный: чтобы предотвратить ДТП, звуковой сигнал подать можно."}},{"uk":"Дозволено тільки для привернення уваги водія під час обгону транспортного засобу.","ru":"Разрешено только для привлечения внимания водителя во время обгона транспортного средства.","w":{"uk":"Привернення уваги під час обгону під виняток знака {s:3.33} не підпадає — дозволено лише запобігти ДТП.","ru":"Привлечение внимания при обгоне под исключение знака {s:3.33} не подпадает — разрешено лишь предотвратить ДТП."}},{"uk":"Дозволено тільки в тому разі, коли без цього неможливо запобігти дорожньо-транспортній пригоді.","ru":"Разрешено только в том случае, когда без этого невозможно предотвратить дорожно-транспортное происшествие."}],"c":2,"e":{"uk":"Знак {s:3.33} «Подачу звукового сигналу заборонено» забороняє користуватися звуковими сигналами, **крім** випадків, коли без цього неможливо запобігти дорожньо-транспортній пригоді ({p:33.3}).","ru":"Знак {s:3.33} «Подача звукового сигнала запрещена» запрещает пользоваться звуковыми сигналами, **кроме** случаев, когда без этого невозможно предотвратить дорожно-транспортное происшествие ({p:33.3})."},"ref":["33.3"],"pic":["img/hsc/33-282-1.jpg"]},{"id":"h33-283","t":"h33","num":"33.283","q":{"uk":"Чи дозволено водієві трактора виконати обгін у зображеній ситуації, якщо автомобіль, що їде попереду, рухається зі швидкістю менш ніж 30 км/год.?","ru":"Разрешено ли водителю трактора выполнить обгон в изображённой ситуации, если автомобиль, едущий впереди, движется со скоростью менее 30 км/ч?"},"a":[{"uk":"Заборонено.","ru":"Запрещено."},{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"Виняток для поодиноких транспортних засобів, що їдуть повільніше за 30 км/год, знак {s:3.27} робить для вантажних автомобілів, а трактор може обганяти лише велосипеди й гужові вози.","ru":"Исключение для одиночных транспортных средств, едущих медленнее 30 км/ч, знак {s:3.27} делает для грузовых автомобилей, а трактор может обгонять только велосипеды и гужевые повозки."}}],"c":0,"e":{"uk":"У зоні дії знака {s:3.27} «Обгін вантажним автомобілям заборонено» тракторам забороняється обгін усіх транспортних засобів, крім поодиноких велосипедів і гужових возів (саней) ({p:33.3}); легковий автомобіль трактору обганяти не можна навіть за швидкості менше 30 км/год.","ru":"В зоне действия знака {s:3.27} «Обгон грузовым автомобилям запрещён» тракторам запрещается обгон всех транспортных средств, кроме одиночных велосипедов и гужевых повозок (саней) ({p:33.3}); легковой автомобиль трактору обгонять нельзя даже при скорости менее 30 км/ч."},"ref":["33.3"],"pic":["img/hsc/33-283-1.jpg"]},{"id":"h33-284","t":"h33","num":"33.284","q":{"uk":"На які транспортні засоби поширюється дія зображеного дорожнього знака?","ru":"На какие транспортные средства распространяется действие изображённого дорожного знака?"},"a":[{"uk":"На всі вантажні автомобілі та трактори.","ru":"На все грузовые автомобили и тракторы.","w":{"uk":"Вантажних автомобілів з дозволеною максимальною масою до 3,5 т ця заборона не стосується.","ru":"Грузовых автомобилей с разрешённой максимальной массой до 3,5 т этот запрет не касается."}},{"uk":"На вантажні автомобілі з дозволеною максимальною масою понад 3,5 т, а також на трактори.","ru":"На грузовые автомобили с разрешённой максимальной массой более 3,5 т, а также на тракторы."},{"uk":"На всі транспортні засоби.","ru":"На все транспортные средства.","w":{"uk":"Легковим автомобілям, автобусам, мотоциклам знак {s:3.27} обганяти не забороняє; обгін усім забороняє інший знак — {s:3.25}.","ru":"Легковым автомобилям, автобусам, мотоциклам знак {s:3.27} обгонять не запрещает; обгон всем запрещает другой знак — {s:3.25}."}},{"uk":"На трактори.","ru":"На тракторы.","w":{"uk":"Відповідь неповна: заборона стосується також вантажних автомобілів масою понад 3,5 т.","ru":"Ответ неполный: запрет касается также грузовых автомобилей массой более 3,5 т."}}],"c":1,"e":{"uk":"Знак {s:3.27} «Обгін вантажним автомобілям заборонено» забороняє обгін вантажним автомобілям з дозволеною максимальною масою понад 3,5 т, а також тракторам ({p:33.3}).","ru":"Знак {s:3.27} «Обгон грузовым автомобилям запрещён» запрещает обгон грузовым автомобилям с разрешённой максимальной массой более 3,5 т, а также тракторам ({p:33.3})."},"ref":["33.3"],"pic":["img/hsc/33-284-1.jpg"]},{"id":"h33-285","t":"h33","num":"33.285","q":{"uk":"Чи дозволено Вам у даній ситуації виконати обгін вантажного автомобіля з причепом, що рухається зі швидкістю менш ніж 30 км/год.?","ru":"Разрешено ли вам в данной ситуации выполнить обгон грузового автомобиля с прицепом, движущегося со скоростью менее 30 км/ч?"},"a":[{"uk":"Дозволено.","ru":"Разрешено."},{"uk":"Заборонено.","ru":"Запрещено.","w":{"uk":"Вантажівка з причепом вважається поодиноким транспортним засобом, тож за швидкості менше 30 км/год її обгін у зоні знака {s:3.25} дозволено.","ru":"Грузовик с прицепом считается одиночным транспортным средством, поэтому при скорости менее 30 км/ч его обгон в зоне знака {s:3.25} разрешён."}}],"c":0,"e":{"uk":"Знак {s:3.25} «Обгін заборонено» дозволяє обганяти поодинокі транспортні засоби, що рухаються зі швидкістю менше ніж 30 км/год, а автопоїзд (вантажівку з причепом) Правила прямо відносять до поодиноких ({p:33.3}).","ru":"Знак {s:3.25} «Обгон запрещён» разрешает обгонять одиночные транспортные средства, движущиеся со скоростью менее 30 км/ч, а автопоезд (грузовик с прицепом) Правила прямо относят к одиночным ({p:33.3})."},"ref":["33.3"],"pic":["img/hsc/33-285-1.jpg"]},{"id":"h33-286","t":"h33","num":"33.286","q":{"uk":"За якої з умов Вам буде дозволено виконати обгін вантажного автомобіля в зображеній ситуації?","ru":"При каком из условий вам будет разрешено выполнить обгон грузового автомобиля в изображённой ситуации?"},"a":[{"uk":"Якщо вантажний автомобіль рухається зі швидкістю менш ніж 40 км/год.","ru":"Если грузовой автомобиль движется со скоростью менее 40 км/ч.","w":{"uk":"Межа швидкості для винятку — 30 км/год, а не 40.","ru":"Порог скорости для исключения — 30 км/ч, а не 40."}},{"uk":"Обгін у зображеній ситуації суворо заборонений.","ru":"Обгон в изображённой ситуации строго запрещён.","w":{"uk":"Заборона не абсолютна: поодинокий транспортний засіб, що їде повільніше за 30 км/год, обганяти можна.","ru":"Запрет не абсолютный: одиночное транспортное средство, едущее медленнее 30 км/ч, обгонять можно."}},{"uk":"Якщо вантажний автомобіль рухається зі швидкістю менш ніж 30 км/год.","ru":"Если грузовой автомобиль движется со скоростью менее 30 км/ч."}],"c":2,"e":{"uk":"У зоні дії знака {s:3.25} «Обгін заборонено» дозволено обганяти поодинокі транспортні засоби, що рухаються зі швидкістю менше ніж 30 км/год ({p:33.3}); попереду якраз поодинока вантажівка.","ru":"В зоне действия знака {s:3.25} «Обгон запрещён» разрешено обгонять одиночные транспортные средства, движущиеся со скоростью менее 30 км/ч ({p:33.3}); впереди как раз одиночный грузовик."},"ref":["33.3"],"pic":["img/hsc/33-286-1.jpg"]},{"id":"h33-287","t":"h33","num":"33.287","q":{"uk":"За якої з умов дозволено виконати обгін транспортного засобу після проїзду зображеного дорожнього знака, встановленого з табличкою?","ru":"При каком из условий разрешено выполнить обгон транспортного средства после проезда изображённого дорожного знака, установленного с табличкой?"},"a":[{"uk":"Якщо поодинокий транспортний засіб рухається зі швидкістю 40 км/год.","ru":"Если одиночное транспортное средство движется со скоростью 40 км/ч.","w":{"uk":"Швидкість 40 км/год не дає права на обгін у зоні дії знака {s:3.25}: виняток діє лише для поодиноких транспортних засобів, що їдуть повільніше за 30 км/год.","ru":"Скорость 40 км/ч не даёт права на обгон в зоне действия знака {s:3.25}: исключение действует только для одиночных транспортных средств, едущих медленнее 30 км/ч."}},{"uk":"Якщо обгін закінчиться не більш ніж через 500 м після проїзду даних дорожніх знаків.","ru":"Если обгон закончится не более чем через 500 м после проезда данных дорожных знаков."},{"uk":"Обидві відповіді правильні.","ru":"Оба ответа правильные.","w":{"uk":"Перша відповідь неправильна, тому варіант «обидві відповіді» теж неправильний.","ru":"Первый ответ неверен, поэтому вариант «оба ответа» тоже неверен."}}],"c":1,"e":{"uk":"Табличка {s:7.1.1} «Відстань до об'єкта» (число без стрілок) показує відстань від знака до місця, де починає діяти заборона ({p:33.7}): заборона обгону {s:3.25} запроваджується лише через 500 м, тож обгін, завершений у межах цих 500 м, дозволено.","ru":"Табличка {s:7.1.1} «Расстояние до объекта» (число без стрелок) показывает расстояние от знака до места, где начинает действовать запрет ({p:33.7}): запрещение обгона {s:3.25} вводится только через 500 м, поэтому обгон, завершённый в пределах этих 500 м, разрешён."},"ref":["33.3","33.7"],"pic":["img/hsc/33-287-1.jpg"]},{"id":"h33-288","t":"h33","num":"33.288","q":{"uk":"Чи дозволено водієві сірого автомобіля виконати обгін у зображеній ситуації?","ru":"Разрешено ли водителю серого автомобиля выполнить обгон в изображённой ситуации?"},"a":[{"uk":"Дозволено, якщо швидкість транспорту, який обганяють, менш ніж 40 км/год.","ru":"Разрешено, если скорость обгоняемого транспорта менее 40 км/ч.","w":{"uk":"Межа швидкості для винятку — 30 км/год, а не 40.","ru":"Порог скорости для исключения — 30 км/ч, а не 40."}},{"uk":"Обгін у зображеній ситуації заборонено.","ru":"Обгон в изображённой ситуации запрещён.","w":{"uk":"Буксирувальний состав є поодиноким транспортним засобом, тож за швидкості менше 30 км/год його обгін дозволено.","ru":"Буксировочный состав является одиночным транспортным средством, поэтому при скорости менее 30 км/ч его обгон разрешён."}},{"uk":"Дозволено, якщо швидкість транспорту, який обганяють, менш ніж 30 км/год.","ru":"Разрешено, если скорость обгоняемого транспорта менее 30 км/ч."}],"c":2,"e":{"uk":"Попереду — буксируючий автомобіль у зчепленні з буксированим, а такий состав Правила вважають поодиноким транспортним засобом; у зоні дії знака {s:3.25} поодинокі транспортні засоби, що рухаються зі швидкістю менше ніж 30 км/год, обганяти дозволено ({p:33.3}).","ru":"Впереди — буксирующий автомобиль в сцепке с буксируемым, а такой состав Правила считают одиночным транспортным средством; в зоне действия знака {s:3.25} одиночные транспортные средства, движущиеся со скоростью менее 30 км/ч, обгонять разрешено ({p:33.3})."},"ref":["33.3"],"pic":["img/hsc/33-288-1.jpg"]},{"id":"h33-289","t":"h33","num":"33.289","q":{"uk":"Зображений на малюнку дорожній знак забороняє:","ru":"Изображённый на рисунке дорожный знак запрещает:"},"a":[{"uk":"Обгін усіх транспортних засобів.","ru":"Обгон всех транспортных средств.","w":{"uk":"Знак має виняток: поодинокі транспортні засоби, що їдуть повільніше за 30 км/год, обганяти дозволено.","ru":"У знака есть исключение: одиночные транспортные средства, едущие медленнее 30 км/ч, обгонять разрешено."}},{"uk":"Обгін усіх транспортних засобів, крім поодиноких, що рухаються із швидкістю менше 30 км/год.","ru":"Обгон всех транспортных средств, кроме одиночных, движущихся со скоростью менее 30 км/ч."},{"uk":"Випередження усіх транспортних засобів, крім поодиноких, що рухаються із швидкістю менше 30 км/год.","ru":"Опережение всех транспортных средств, кроме одиночных, движущихся со скоростью менее 30 км/ч.","w":{"uk":"Знак забороняє саме обгін — випередження з виїздом на смугу зустрічного руху ({p:1.10}); випередження без виїзду на зустрічну смугу він не забороняє.","ru":"Знак запрещает именно обгон — опережение с выездом на полосу встречного движения ({p:1.10}); опережение без выезда на встречную полосу он не запрещает."}}],"c":1,"e":{"uk":"Знак {s:3.25} «Обгін заборонено» забороняє обгін усіх транспортних засобів, крім поодиноких, що рухаються зі швидкістю менше ніж 30 км/год ({p:33.3}).","ru":"Знак {s:3.25} «Обгон запрещён» запрещает обгон всех транспортных средств, кроме одиночных, движущихся со скоростью менее 30 км/ч ({p:33.3})."},"ref":["33.3","1.10"],"pic":["img/hsc/33-289-1.jpg"]},{"id":"h33-290","t":"h33","num":"33.290","q":{"uk":"На які види транспортних засобів не поширюється дія зображеного дорожнього знака?","ru":"На какие виды транспортных средств не распространяется действие изображённого дорожного знака?"},"a":[{"uk":"На механічні транспортні засоби.","ru":"На механические транспортные средства.","w":{"uk":"Механічні транспортні засоби з-під дії знака {s:3.25} не виведено — обганяти в його зоні їм заборонено.","ru":"Механические транспортные средства из-под действия знака {s:3.25} не выведены — обгонять в его зоне им запрещено."}},{"uk":"На немеханічні транспортні засоби.","ru":"На немеханические транспортные средства.","w":{"uk":"Для немеханічних транспортних засобів (велосипедів, гужових возів) Правила теж не роблять винятку зі знака {s:3.25}.","ru":"Для немеханических транспортных средств (велосипедов, гужевых повозок) Правила тоже не делают исключения из знака {s:3.25}."}},{"uk":"Дія зображеного дорожнього знака поширюється на всі без винятку транспортні засоби.","ru":"Действие изображённого дорожного знака распространяется на все без исключения транспортные средства."}],"c":2,"e":{"uk":"Знак {s:3.25} «Обгін заборонено» забороняє обгін **усім** транспортним засобам, і Правила не роблять винятків щодо того, хто обганяє ({p:33.3}); виняток стосується лише тих, кого обганяють, — поодиноких, що їдуть повільніше за 30 км/год.","ru":"Знак {s:3.25} «Обгон запрещён» запрещает обгон **всем** транспортным средствам, и Правила не делают исключений в отношении того, кто обгоняет ({p:33.3}); исключение касается лишь тех, кого обгоняют, — одиночных, едущих медленнее 30 км/ч."},"ref":["33.3"],"pic":["img/hsc/33-290-1.jpg"]},{"id":"h33-291","t":"h33","num":"33.291","q":{"uk":"Який із зображених дорожніх знаків забороняє обгін усім транспортним засобам?","ru":"Какой из изображённых дорожных знаков запрещает обгон всем транспортным средствам?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:3.27}: він забороняє обгін лише вантажним автомобілям масою понад 3,5 т і тракторам.","ru":"Знак 1 — {s:3.27}: он запрещает обгон только грузовым автомобилям массой более 3,5 т и тракторам."}},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:3.1} «Рух заборонено».","ru":"Знак 2 — {s:3.1} «Движение запрещено»."}},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — {s:3.34} «Зупинку заборонено».","ru":"Знак 3 — {s:3.34} «Остановка запрещена»."}},{"uk":"Знак 4.","ru":"Знак 4."},{"uk":"Знак 5.","ru":"Знак 5.","w":{"uk":"Знак 5 — {s:3.2} «Рух механічних транспортних засобів заборонено».","ru":"Знак 5 — {s:3.2} «Движение механических транспортных средств запрещено»."}}],"c":3,"e":{"uk":"Знак 4 — {s:3.25} «Обгін заборонено» (червоний і чорний легкові автомобілі): він забороняє обгін усіх транспортних засобів, крім поодиноких, що рухаються зі швидкістю менше ніж 30 км/год ({p:33.3}).","ru":"Знак 4 — {s:3.25} «Обгон запрещён» (красный и чёрный легковые автомобили): он запрещает обгон всех транспортных средств, кроме одиночных, движущихся со скоростью менее 30 км/ч ({p:33.3})."},"ref":["33.3"],"pic":["img/hsc/33-291-1.jpg"]},{"id":"h33-292","t":"h33","num":"33.292","q":{"uk":"Зображений дорожній знак позначає:","ru":"Изображённый дорожный знак обозначает:"},"a":[{"uk":"Кінець зони дії знака «Обгін вантажним автомобілям заборонено».","ru":"Конец зоны действия знака «Обгон грузовым автомобилям запрещён».","w":{"uk":"Кінець заборони обгону вантажним автомобілям позначає знак {s:3.28}, на якому зображено вантажівку.","ru":"Конец запрещения обгона грузовым автомобилям обозначает знак {s:3.28}, на котором изображён грузовик."}},{"uk":"Кінець дії всіх заборон і обмежень, запроваджених заборонними дорожніми знаками.","ru":"Конец действия всех запрещений и ограничений, введённых запрещающими дорожными знаками.","w":{"uk":"Кінець усіх заборон і обмежень позначає знак {s:3.42} — без зображень, лише з перекресленням.","ru":"Конец всех запрещений и ограничений обозначает знак {s:3.42} — без изображений, только с перечёркиванием."}},{"uk":"Кінець зони дії знака «Обгін заборонено».","ru":"Конец зоны действия знака «Обгон запрещён»."}],"c":2,"e":{"uk":"Це знак {s:3.26} «Кінець заборони обгону» (сірі легкові автомобілі, перекреслені смугами): ним закінчується зона дії знака {s:3.25} ({p:33.3}).","ru":"Это знак {s:3.26} «Конец запрещения обгона» (серые легковые автомобили, перечёркнутые полосами): им заканчивается зона действия знака {s:3.25} ({p:33.3})."},"ref":["33.3"],"pic":["img/hsc/33-292-1.jpg"]},{"id":"h33-293","t":"h33","num":"33.293","q":{"uk":"Який із зображених дорожніх знаків забороняє зупинку транспортних засобів?","ru":"Какой из изображённых дорожных знаков запрещает остановку транспортных средств?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:3.2} «Рух механічних транспортних засобів заборонено».","ru":"Знак 1 — {s:3.2} «Движение механических транспортных средств запрещено»."}},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:3.38} «Зона обмеженої стоянки»: він обмежує тривалість стоянки, але не забороняє зупинку.","ru":"Знак 2 — {s:3.38} «Зона ограниченной стоянки»: он ограничивает продолжительность стоянки, но не запрещает остановку."}},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — {s:3.37} «Стоянку заборонено в парні числа місяця»: зупинку він не забороняє.","ru":"Знак 3 — {s:3.37} «Стоянка запрещена по чётным числам месяца»: остановку он не запрещает."}},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Знак 4 — {s:3.35} «Стоянку заборонено»: він забороняє лише стоянку, а зупинку дозволяє.","ru":"Знак 4 — {s:3.35} «Стоянка запрещена»: он запрещает только стоянку, а остановку разрешает."}},{"uk":"Знак 5.","ru":"Знак 5."}],"c":4,"e":{"uk":"Знак 5 — {s:3.34} «Зупинку заборонено» (синє коло з червоним хрестом): забороняються зупинка і стоянка, крім таксі під час посадки чи висадки пасажирів ({p:33.3}).","ru":"Знак 5 — {s:3.34} «Остановка запрещена» (синий круг с красным крестом): запрещаются остановка и стоянка, кроме такси при посадке или высадке пассажиров ({p:33.3})."},"ref":["33.3"],"pic":["img/hsc/33-293-1.jpg"]},{"id":"h33-294","t":"h33","num":"33.294","q":{"uk":"Вимога якого із зображених знаків зобов'язує водія транспортного засобу обов'язково зупинитися на нерегульованому перехресті або залізничному переїзді?","ru":"Требование какого из изображённых знаков обязывает водителя транспортного средства обязательно остановиться на нерегулируемом перекрёстке или железнодорожном переезде?"},"a":[{"uk":"Знак 1.","ru":"Знак 1."},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Напис «STOP» на прямокутній табличці (як на табличці {s:7.1.2}) лише попереджає разом зі знаком {s:2.1}, що попереду знак {s:2.2} ({p:33.7}); сам він зупинки не вимагає.","ru":"Надпись «STOP» на прямоугольной табличке (как на табличке {s:7.1.2}) лишь предупреждает вместе со знаком {s:2.1}, что впереди знак {s:2.2} ({p:33.7}); сама она остановки не требует."}},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — {s:2.1} «Дати дорогу»: він вимагає дати дорогу, але не зобов'язує зупинятися, якщо перешкод немає.","ru":"Знак 3 — {s:2.1} «Уступить дорогу»: он требует уступить дорогу, но не обязывает останавливаться, если помех нет."}},{"uk":"Усі зображені дорожні знаки.","ru":"Все изображённые дорожные знаки.","w":{"uk":"Обов'язкової зупинки вимагає лише знак {s:2.2}; знак {s:2.1} і табличка «STOP» такої вимоги не містять.","ru":"Обязательной остановки требует только знак {s:2.2}; знак {s:2.1} и табличка «STOP» такого требования не содержат."}},{"uk":"Знаки 1 і 2.","ru":"Знаки 1 и 2.","w":{"uk":"Табличка з написом «STOP» (знак 2) окремо зупинки не вимагає — це робить тільки знак {s:2.2}.","ru":"Табличка с надписью «STOP» (знак 2) отдельно остановки не требует — это делает только знак {s:2.2}."}}],"c":0,"e":{"uk":"Знак 1 — {s:2.2} «Проїзд без зупинки заборонено»: він забороняє проїзд без зупинки перед стоп-лінією, а за її відсутності — перед знаком, у тому числі перед залізничним переїздом, що не охороняється й не обладнаний світлофорною сигналізацією ({p:33.2}).","ru":"Знак 1 — {s:2.2} «Проезд без остановки запрещён»: он запрещает проезд без остановки перед стоп-линией, а при её отсутствии — перед знаком, в том числе перед железнодорожным переездом, который не охраняется и не оборудован светофорной сигнализацией ({p:33.2})."},"ref":["33.2","33.7"],"pic":["img/hsc/33-294-1.jpg"]},{"id":"h33-295","t":"h33","num":"33.295","q":{"uk":"Який із зображених дорожніх знаків надає переважне право проїзду вузької ділянки дороги водієві зустрічного транспортного засобу?","ru":"Какой из изображённых дорожных знаков предоставляет преимущественное право проезда узкого участка дороги водителю встречного транспортного средства?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:2.6} «Перевага перед зустрічним рухом»: навпаки, перевагу на вузькій ділянці має той, для кого його встановлено.","ru":"Знак 1 — {s:2.6} «Преимущество перед встречным движением»: наоборот, преимущество на узком участке имеет тот, для кого он установлен."}},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:2.3} «Головна дорога»: він стосується проїзду нерегульованих перехресть.","ru":"Знак 2 — {s:2.3} «Главная дорога»: он касается проезда нерегулируемых перекрёстков."}},{"uk":"Знак 3.","ru":"Знак 3."},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Знак 4 — табличка {s:7.8} «Напрямок головної дороги».","ru":"Знак 4 — табличка {s:7.8} «Направление главной дороги»."}},{"uk":"Знак 5.","ru":"Знак 5.","w":{"uk":"Знак 5 — {s:2.1} «Дати дорогу»: він стосується перехресть, а не вузьких ділянок.","ru":"Знак 5 — {s:2.1} «Уступить дорогу»: он касается перекрёстков, а не узких участков."}}],"c":2,"e":{"uk":"Знак 3 — {s:2.5} «Перевага зустрічного руху»: забороняється в'їзд на вузьку ділянку, якщо це утруднить зустрічний рух, і треба дати дорогу зустрічним транспортним засобам, що перебувають на ній ({p:33.2}).","ru":"Знак 3 — {s:2.5} «Преимущество встречного движения»: запрещается въезд на узкий участок, если это затруднит встречное движение, и нужно уступить дорогу встречным транспортным средствам, находящимся на нём ({p:33.2})."},"ref":["33.2"],"pic":["img/hsc/33-295-1.jpg"]},{"id":"h33-296","t":"h33","num":"33.296","q":{"uk":"Зображений дорожній знак встановлюється:","ru":"Изображённый дорожный знак устанавливается:"},"a":[{"uk":"На перехресті з обмеженою оглядовістю дороги.","ru":"На перекрёстке с ограниченной обзорностью дороги.","w":{"uk":"Перед перехрестями ставлять інші знаки пріоритету ({s:2.1}, {s:2.2}, {s:2.3}); знак {s:2.5} стосується вузьких ділянок.","ru":"Перед перекрёстками ставят другие знаки приоритета ({s:2.1}, {s:2.2}, {s:2.3}); знак {s:2.5} касается узких участков."}},{"uk":"На нерегульованих перехрестях.","ru":"На нерегулируемых перекрёстках.","w":{"uk":"Знак {s:2.5} визначає черговість проїзду вузької ділянки, а не перехрестя.","ru":"Знак {s:2.5} определяет очерёдность проезда узкого участка, а не перекрёстка."}},{"uk":"На вузьких ділянках дороги, в місцях, де обмежено зустрічний роз'їзд транспортних засобів.","ru":"На узких участках дороги, в местах, где ограничен встречный разъезд транспортных средств."},{"uk":"На підйомах і спусках.","ru":"На подъёмах и спусках.","w":{"uk":"Про підйоми й спуски попереджають знаки {s:1.6} і {s:1.7}; знак {s:2.5} ставлять лише там, де дорога звужена.","ru":"О подъёмах и спусках предупреждают знаки {s:1.6} и {s:1.7}; знак {s:2.5} ставят только там, где дорога сужена."}}],"c":2,"e":{"uk":"Це знак {s:2.5} «Перевага зустрічного руху»; його встановлюють безпосередньо перед вузькою ділянкою дороги, де ускладнено зустрічний роз'їзд ({p:33.2}).","ru":"Это знак {s:2.5} «Преимущество встречного движения»; его устанавливают непосредственно перед узким участком дороги, где затруднён встречный разъезд ({p:33.2})."},"ref":["33.2"],"pic":["img/hsc/33-296-1.jpg"]},{"id":"h33-297","t":"h33","num":"33.297","q":{"uk":"Як ви роз'їдетеся із зустрічним транспортним засобом у даній ситуації?","ru":"Как вы разъедетесь со встречным транспортным средством в данной ситуации?"},"a":[{"uk":"Проїдете першим, маючи перевагу.","ru":"Проедете первым, имея преимущество.","w":{"uk":"Перевагу на вузькій ділянці дав би знак {s:2.6} (синій прямокутний), а у вас круглий знак {s:2.5}.","ru":"Преимущество на узком участке дал бы знак {s:2.6} (синий прямоугольный), а у вас круглый знак {s:2.5}."}},{"uk":"Проїдете другим, не маючи переваги.","ru":"Проедете вторым, не имея преимущества."}],"c":1,"e":{"uk":"Перед вами тимчасовий знак {s:2.5} «Перевага зустрічного руху»: на вузьку ділянку не можна в'їжджати, якщо це утруднить зустрічний рух, і треба дати дорогу зустрічному автомобілю ({p:33.2}).","ru":"Перед вами временный знак {s:2.5} «Преимущество встречного движения»: на узкий участок нельзя въезжать, если это затруднит встречное движение, и нужно уступить дорогу встречному автомобилю ({p:33.2})."},"ref":["33.2"],"pic":["img/hsc/33-297-1.jpg"]},{"id":"h33-298","t":"h33","num":"33.298","q":{"uk":"Хто з водіїв має перевагу під час зустрічного роз'їзду в даній ситуації?","ru":"Кто из водителей имеет преимущество при встречном разъезде в данной ситуации?"},"a":[{"uk":"Водій легкового автомобіля.","ru":"Водитель легкового автомобиля."},{"uk":"Водій вантажного автомобіля.","ru":"Водитель грузового автомобиля.","w":{"uk":"Водій вантажівки бачить знак {s:2.5} і повинен дати дорогу зустрічному транспорту на вузькій ділянці.","ru":"Водитель грузовика видит знак {s:2.5} и должен уступить дорогу встречному транспорту на узком участке."}}],"c":0,"e":{"uk":"Перед мостом для вантажівки встановлено знак {s:2.5} «Перевага зустрічного руху», а для легкового автомобіля — {s:2.6} «Перевага перед зустрічним рухом» ({p:33.2}), тож перевагу має водій легкового автомобіля.","ru":"Перед мостом для грузовика установлен знак {s:2.5} «Преимущество встречного движения», а для легкового автомобиля — {s:2.6} «Преимущество перед встречным движением» ({p:33.2}), поэтому преимущество имеет водитель легкового автомобиля."},"ref":["33.2"],"pic":["img/hsc/33-298-1.jpg"]},{"id":"h33-299","t":"h33","num":"33.299","q":{"uk":"Який дорожній знак встановлюється зустрічним транспортним засобам, якщо для вас встановлено даний дорожній знак?","ru":"Какой дорожный знак устанавливается для встречных транспортных средств, если для вас установлен данный дорожный знак?"},"a":[{"uk":"Знак 1.","ru":"Знак 1."},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:2.3} «Головна дорога»: він стосується перехресть, а не вузьких ділянок.","ru":"Знак 2 — {s:2.3} «Главная дорога»: он касается перекрёстков, а не узких участков."}},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — {s:2.4} «Кінець головної дороги».","ru":"Знак 3 — {s:2.4} «Конец главной дороги»."}},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Знак 4 — табличка {s:7.8} «Напрямок головної дороги».","ru":"Знак 4 — табличка {s:7.8} «Направление главной дороги»."}},{"uk":"Знак 5.","ru":"Знак 5.","w":{"uk":"Знак 5 — {s:2.1} «Дати дорогу»: він стосується перехресть і не визначає черговості на вузькій ділянці.","ru":"Знак 5 — {s:2.1} «Уступить дорогу»: он касается перекрёстков и не определяет очерёдность на узком участке."}}],"c":0,"e":{"uk":"Знаки {s:2.5} і {s:2.6} парні: якщо з вашого боку вузької ділянки стоїть {s:2.5} «Перевага зустрічного руху», то з протилежного — {s:2.6} «Перевага перед зустрічним рухом», тобто знак 1 ({p:33.2}).","ru":"Знаки {s:2.5} и {s:2.6} парные: если с вашей стороны узкого участка стоит {s:2.5} «Преимущество встречного движения», то с противоположной — {s:2.6} «Преимущество перед встречным движением», то есть знак 1 ({p:33.2})."},"ref":["33.2"],"pic":["img/hsc/33-299-1.jpg"]},{"id":"h33-300","t":"h33","num":"33.300","q":{"uk":"Який із зображених дорожніх знаків надає перевагу стосовно зустрічних транспортних засобів на вузькій ділянці дороги?","ru":"Какой из изображённых дорожных знаков даёт преимущество по отношению к встречным транспортным средствам на узком участке дороги?"},"a":[{"uk":"Знак 1.","ru":"Знак 1."},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:2.3} «Головна дорога»: він дає перевагу на нерегульованих перехрестях, а не на вузькій ділянці.","ru":"Знак 2 — {s:2.3} «Главная дорога»: он даёт преимущество на нерегулируемых перекрёстках, а не на узком участке."}},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — {s:2.5} «Перевага зустрічного руху»: навпаки, зобов'язує дати дорогу зустрічним.","ru":"Знак 3 — {s:2.5} «Преимущество встречного движения»: наоборот, обязывает уступить дорогу встречным."}},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Знак 4 — табличка {s:7.8} «Напрямок головної дороги».","ru":"Знак 4 — табличка {s:7.8} «Направление главной дороги»."}},{"uk":"Знак 5.","ru":"Знак 5.","w":{"uk":"Знак 5 — {s:2.1} «Дати дорогу».","ru":"Знак 5 — {s:2.1} «Уступить дорогу»."}}],"c":0,"e":{"uk":"Знак 1 — {s:2.6} «Перевага перед зустрічним рухом»: вузька ділянка дороги, під час руху якою водій має перевагу стосовно зустрічних транспортних засобів ({p:33.2}).","ru":"Знак 1 — {s:2.6} «Преимущество перед встречным движением»: узкий участок дороги, при движении по которому водитель имеет преимущество по отношению к встречным транспортным средствам ({p:33.2})."},"ref":["33.2"],"pic":["img/hsc/33-300-1.jpg"]},{"id":"h33-301","t":"h33","num":"33.301","q":{"uk":"Зображений дорожній знак встановлюється:","ru":"Изображённый дорожный знак устанавливается:"},"a":[{"uk":"На перехресті з обмеженою оглядовістю дороги.","ru":"На перекрёстке с ограниченной обзорностью дороги.","w":{"uk":"Перед перехрестями ставлять інші знаки пріоритету ({s:2.1}, {s:2.2}, {s:2.3}); знак {s:2.6} стосується вузьких ділянок.","ru":"Перед перекрёстками ставят другие знаки приоритета ({s:2.1}, {s:2.2}, {s:2.3}); знак {s:2.6} касается узких участков."}},{"uk":"На нерегульованих перехрестях.","ru":"На нерегулируемых перекрёстках.","w":{"uk":"Знак {s:2.6} визначає черговість проїзду вузької ділянки, а не перехрестя.","ru":"Знак {s:2.6} определяет очерёдность проезда узкого участка, а не перекрёстка."}},{"uk":"На вузьких ділянках дороги, в місцях, де ускладнено зустрічний роз'їзд транспортних засобів.","ru":"На узких участках дороги, в местах, где затруднён встречный разъезд транспортных средств."},{"uk":"На підйомах і спусках.","ru":"На подъёмах и спусках.","w":{"uk":"Про підйоми й спуски попереджають знаки {s:1.6} і {s:1.7}.","ru":"О подъёмах и спусках предупреждают знаки {s:1.6} и {s:1.7}."}},{"uk":"У місцях, де закінчується односторонній рух.","ru":"В местах, где заканчивается одностороннее движение.","w":{"uk":"Про початок двостороннього руху після одностороннього попереджає знак {s:1.26} «Двосторонній рух».","ru":"О начале двустороннего движения после одностороннего предупреждает знак {s:1.26} «Двустороннее движение»."}}],"c":2,"e":{"uk":"Це знак {s:2.6} «Перевага перед зустрічним рухом»; його встановлюють безпосередньо перед вузькою ділянкою дороги, де ускладнено зустрічний роз'їзд ({p:33.2}).","ru":"Это знак {s:2.6} «Преимущество перед встречным движением»; его устанавливают непосредственно перед узким участком дороги, где затруднён встречный разъезд ({p:33.2})."},"ref":["33.2"],"pic":["img/hsc/33-301-1.jpg"]},{"id":"h33-302","t":"h33","num":"33.302","q":{"uk":"Як ви повинні діяти в даній ситуації при обмеженому зустрічному роз'їзді?","ru":"Как вы должны действовать в данной ситуации при ограниченном встречном разъезде?"},"a":[{"uk":"Дати дорогу зустрічному автомобілю, проїхати другим.","ru":"Уступить дорогу встречному автомобилю, проехать вторым.","w":{"uk":"Дати дорогу зустрічному вимагав би знак {s:2.5}; синій прямокутний знак {s:2.6} дає перевагу вам.","ru":"Уступить дорогу встречному требовал бы знак {s:2.5}; синий прямоугольный знак {s:2.6} даёт преимущество вам."}},{"uk":"Маючи перевагу, проїхати першим.","ru":"Имея преимущество, проехать первым."}],"c":1,"e":{"uk":"Перед ділянкою дорожніх робіт для вас встановлено тимчасовий знак {s:2.6} «Перевага перед зустрічним рухом», тож на звуженій ділянці ви маєте перевагу і проїжджаєте першим ({p:33.2}); знак {s:4.8} показує, що перешкоду треба об'їхати зліва ({p:33.4}).","ru":"Перед участком дорожных работ для вас установлен временный знак {s:2.6} «Преимущество перед встречным движением», поэтому на суженном участке вы имеете преимущество и проезжаете первым ({p:33.2}); знак {s:4.8} показывает, что препятствие нужно объехать слева ({p:33.4})."},"ref":["33.2","33.4"],"pic":["img/hsc/33-302-1.jpg"]},{"id":"h33-303","t":"h33","num":"33.303","q":{"uk":"Зображений дорожній знак встановлюється:","ru":"Изображённый дорожный знак устанавливается:"},"a":[{"uk":"Перед перехрестями, на яких скасовується право першочергового проїзду нерегульованих перехресть.","ru":"Перед перекрёстками, на которых отменяется право первоочередного проезда нерегулируемых перекрёстков."},{"uk":"Перед перехрестями, на яких водієві транспортного засобу надається право першочергового проїзду нерегульованих перехресть.","ru":"Перед перекрёстками, на которых водителю транспортного средства предоставляется право первоочередного проезда нерегулируемых перекрёстков.","w":{"uk":"Право першочергового проїзду надає знак {s:2.3} «Головна дорога» — без чорних смуг.","ru":"Право первоочередного проезда предоставляет знак {s:2.3} «Главная дорога» — без чёрных полос."}}],"c":0,"e":{"uk":"Це знак {s:2.4} «Кінець головної дороги»: він скасовує право першочергового проїзду нерегульованих перехресть і встановлюється в кінці головної дороги ({p:33.2}).","ru":"Это знак {s:2.4} «Конец главной дороги»: он отменяет право первоочередного проезда нерегулируемых перекрёстков и устанавливается в конце главной дороги ({p:33.2})."},"ref":["33.2"],"pic":["img/hsc/33-303-1.jpg"]},{"id":"h33-304","t":"h33","num":"33.304","q":{"uk":"Який із зображених дорожніх знаків скасовує право першочергового проїзду нерегульованих перехресть?","ru":"Какой из изображённых дорожных знаков отменяет право первоочередного проезда нерегулируемых перекрёстков?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:2.3} «Головна дорога»: він, навпаки, надає право першочергового проїзду.","ru":"Знак 1 — {s:2.3} «Главная дорога»: он, наоборот, предоставляет право первоочередного проезда."}},{"uk":"Знак 2.","ru":"Знак 2."},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — {s:2.5} «Перевага зустрічного руху»: стосується вузької ділянки дороги.","ru":"Знак 3 — {s:2.5} «Преимущество встречного движения»: касается узкого участка дороги."}},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Знак 4 — {s:2.6} «Перевага перед зустрічним рухом»: стосується вузької ділянки дороги.","ru":"Знак 4 — {s:2.6} «Преимущество перед встречным движением»: касается узкого участка дороги."}}],"c":1,"e":{"uk":"Знак 2 — {s:2.4} «Кінець головної дороги» (перекреслений жовтий ромб): він скасовує право першочергового проїзду нерегульованих перехресть ({p:33.2}).","ru":"Знак 2 — {s:2.4} «Конец главной дороги» (перечёркнутый жёлтый ромб): он отменяет право первоочередного проезда нерегулируемых перекрёстков ({p:33.2})."},"ref":["33.2"],"pic":["img/hsc/33-304-1.jpg"]},{"id":"h33-305","t":"h33","num":"33.305","q":{"uk":"Який дорожній знак встановлено на найближчому перехресті після знаків дати дорогу разом з табличкою?","ru":"Какой дорожный знак установлен на ближайшем перекрёстке после знака «Уступить дорогу» вместе с табличкой?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Повторний знак {s:2.1} анонсують табличкою {s:7.1.1} лише з відстанню, без напису «STOP».","ru":"Повторный знак {s:2.1} анонсируют табличкой {s:7.1.1} только с расстоянием, без надписи «STOP»."}},{"uk":"Знак 2.","ru":"Знак 2."},{"uk":"Знак 3.","ru":"Знак 3.","w":{"uk":"Знак 3 — попереджувальний {s:1.39} «Інша небезпека»: він не є знаком пріоритету.","ru":"Знак 3 — предупреждающий {s:1.39} «Иная опасность»: он не является знаком приоритета."}}],"c":1,"e":{"uk":"Табличку {s:7.1.2} з написом «STOP» і відстанню ставлять зі знаком {s:2.1}, якщо безпосередньо перед перехрестям встановлено знак {s:2.2} ({p:33.2}, {p:33.7}); отже, через 250 м стоїть знак {s:2.2} «Проїзд без зупинки заборонено».","ru":"Табличку {s:7.1.2} с надписью «STOP» и расстоянием ставят со знаком {s:2.1}, если непосредственно перед перекрёстком установлен знак {s:2.2} ({p:33.2}, {p:33.7}); значит, через 250 м стоит знак {s:2.2} «Проезд без остановки запрещён»."},"ref":["33.2","33.7"],"pic":["img/hsc/33-305-1.jpg"]},{"id":"h33-306","t":"h33","num":"33.306","q":{"uk":"Чи є обов'язковою зупинка для виконання вимог даного знака?","ru":"Является ли обязательной остановка для выполнения требований данного знака?"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"Зупинитися потрібно навіть тоді, коли дорогою, що перетинається, ніхто не їде.","ru":"Остановиться нужно даже тогда, когда по пересекаемой дороге никто не едет."}}],"c":0,"e":{"uk":"Знак {s:2.2} «Проїзд без зупинки заборонено» забороняє проїзд без зупинки перед стоп-лінією {m:1.12}, а за її відсутності — перед знаком ({p:33.2}): зупинка обов'язкова завжди, навіть якщо перехрестя вільне.","ru":"Знак {s:2.2} «Проезд без остановки запрещён» запрещает проезд без остановки перед стоп-линией {m:1.12}, а при её отсутствии — перед знаком ({p:33.2}): остановка обязательна всегда, даже если перекрёсток свободен."},"ref":["33.2"],"pic":["img/hsc/33-306-1.jpg"]},{"id":"h33-307","t":"h33","num":"33.307","q":{"uk":"У якій з відповідей водій правильно виконав вимогу даного дорожнього знака, проїхавши через перехрестя?","ru":"В каком из ответов водитель правильно выполнил требование данного дорожного знака, проехав через перекрёсток?"},"a":[{"uk":"Водій тільки знизив швидкість і дав дорогу транспортним засобам, що рухаються по головній дорозі.","ru":"Водитель только снизил скорость и уступил дорогу транспортным средствам, движущимся по главной дороге.","w":{"uk":"Самого зниження швидкості недостатньо: знак {s:2.2} вимагає повної зупинки.","ru":"Одного снижения скорости недостаточно: знак {s:2.2} требует полной остановки."}},{"uk":"Водій зупинився перед знаком «Проїзд без зупинки заборонено» і дав дорогу транспортним засобам, що рухаються по головній дорозі.","ru":"Водитель остановился перед знаком «Проезд без остановки запрещён» и уступил дорогу транспортным средствам, движущимся по главной дороге."},{"uk":"Водій зупинився перед знаком «Проїзд без зупинки заборонено» і не дав нікому дорогу.","ru":"Водитель остановился перед знаком «Проезд без остановки запрещён» и никому не уступил дорогу.","w":{"uk":"Після зупинки водій ще повинен дати дорогу транспортним засобам на дорозі, яка перетинається.","ru":"После остановки водитель ещё должен уступить дорогу транспортным средствам на пересекаемой дороге."}}],"c":1,"e":{"uk":"Знак {s:2.2} вимагає двох дій: обов'язково зупинитися перед стоп-лінією (а за її відсутності — перед знаком) **і** дати дорогу транспортним засобам, що рухаються дорогою, яка перетинається ({p:33.2}).","ru":"Знак {s:2.2} требует двух действий: обязательно остановиться перед стоп-линией (а при её отсутствии — перед знаком) **и** уступить дорогу транспортным средствам, движущимся по пересекаемой дороге ({p:33.2})."},"ref":["33.2"],"pic":["img/hsc/33-307-1.jpg"]},{"id":"h33-308","t":"h33","num":"33.308","q":{"uk":"Чи повинен водій жовтого автомобіля зупинитися перед стоп-лінією, якщо він вже зупинявся за попутним автомобілем?","ru":"Должен ли водитель жёлтого автомобиля остановиться перед стоп-линией, если он уже останавливался за попутным автомобилем?"},"a":[{"uk":"Не повинен.","ru":"Не должен.","w":{"uk":"Зупинка в черзі за іншим автомобілем не замінює обов'язкової зупинки перед стоп-лінією.","ru":"Остановка в очереди за другим автомобилем не заменяет обязательной остановки перед стоп-линией."}},{"uk":"Повинен.","ru":"Должен."}],"c":1,"e":{"uk":"Знак {s:2.2} забороняє проїзд без зупинки саме перед стоп-лінією ({p:33.2}); зупинка позаду іншого автомобіля цієї вимоги не виконує, тож, під'їхавши до стоп-лінії, треба зупинитися ще раз.","ru":"Знак {s:2.2} запрещает проезд без остановки именно перед стоп-линией ({p:33.2}); остановка позади другого автомобиля этого требования не выполняет, поэтому, подъехав к стоп-линии, нужно остановиться ещё раз."},"ref":["33.2"],"pic":["img/hsc/33-308-1.jpg"]},{"id":"h33-309","t":"h33","num":"33.309","q":{"uk":"У якій із зображених ситуацій водій повинен виконати вимогу знака «Проїзд без зупинки заборонено» (у другій ситуації світлофор працює в режимі миготіння жовтого сигналу)?","ru":"В какой из изображённых ситуаций водитель должен выполнить требование знака «Проезд без остановки запрещён» (во второй ситуации светофор работает в режиме мигания жёлтого сигнала)?"},"a":[{"uk":"У першій ситуації.","ru":"В первой ситуации.","w":{"uk":"За зеленого сигналу перехрестя регульоване, і знаки пріоритету, зокрема {s:2.2}, на ньому не діють.","ru":"При зелёном сигнале перекрёсток регулируемый, и знаки приоритета, в том числе {s:2.2}, на нём не действуют."}},{"uk":"У другій ситуації.","ru":"Во второй ситуации."},{"uk":"В обох ситуаціях.","ru":"В обеих ситуациях.","w":{"uk":"У першій ситуації знак не діє, бо працює світлофор із зеленим сигналом.","ru":"В первой ситуации знак не действует, поскольку работает светофор с зелёным сигналом."}}],"c":1,"e":{"uk":"Сигнали світлофора, крім жовтого миготливого, мають перевагу перед знаками пріоритету ({p:8.3}). У першій ситуації горить зелений, перехрестя регульоване, і знак {s:2.2} не діє ({p:16.1}); у другій жовтий миготливий сигнал робить перехрестя нерегульованим, тож вимогу знака треба виконати.","ru":"Сигналы светофора, кроме жёлтого мигающего, имеют преимущество перед знаками приоритета ({p:8.3}). В первой ситуации горит зелёный, перекрёсток регулируемый, и знак {s:2.2} не действует ({p:16.1}); во второй жёлтый мигающий сигнал делает перекрёсток нерегулируемым, поэтому требование знака нужно выполнить."},"ref":["8.3","16.1","33.2"],"pic":["img/hsc/33-309-1.jpg"]},{"id":"h33-310","t":"h33","num":"33.310","q":{"uk":"Який із зображених знаків зобов'язує дати дорогу транспортним засобам, що рухаються по дорозі, яка перетинається, на нерегульованих перехрестях?","ru":"Какой из изображённых знаков обязывает уступить дорогу транспортным средствам, движущимся по пересекаемой дороге, на нерегулируемых перекрёстках?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак {s:2.2} теж зобов'язує дати дорогу — і ще вимагає обов'язкової зупинки.","ru":"Знак {s:2.2} тоже обязывает уступить дорогу — и ещё требует обязательной остановки."}},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак {s:2.1} теж зобов'язує дати дорогу, лише без обов'язкової зупинки.","ru":"Знак {s:2.1} тоже обязывает уступить дорогу, только без обязательной остановки."}},{"uk":"Обидва знаки.","ru":"Оба знака."}],"c":2,"e":{"uk":"І знак {s:2.1} «Дати дорогу», і знак {s:2.2} «Проїзд без зупинки заборонено» зобов'язують дати дорогу транспортним засобам на дорозі, що перетинається; знак {s:2.2} додатково вимагає зупинитися ({p:33.2}).","ru":"И знак {s:2.1} «Уступить дорогу», и знак {s:2.2} «Проезд без остановки запрещён» обязывают уступить дорогу транспортным средствам на пересекаемой дороге; знак {s:2.2} дополнительно требует остановиться ({p:33.2})."},"ref":["33.2"],"pic":["img/hsc/33-310-1.jpg"]},{"id":"h33-311","t":"h33","num":"33.311","q":{"uk":"Який із зображених дорожніх знаків надає першочергове право проїзду перед транспортними засобами, що рухаються по дорозі, яка перетинається, на нерегульованих перехрестях?","ru":"Какой из изображённых дорожных знаков даёт право первоочередного проезда перед транспортными средствами, движущимися по пересекаемой дороге, на нерегулируемых перекрёстках?"},"a":[{"uk":"Знак 1.","ru":"Знак 1.","w":{"uk":"Знак 1 — {s:2.1} «Дати дорогу»: він зобов'язує поступитися, а не дає перевагу.","ru":"Знак 1 — {s:2.1} «Уступить дорогу»: он обязывает уступить, а не даёт преимущество."}},{"uk":"Знак 2.","ru":"Знак 2.","w":{"uk":"Знак 2 — {s:2.2} «Проїзд без зупинки заборонено»: він зобов'язує зупинитися й дати дорогу.","ru":"Знак 2 — {s:2.2} «Проезд без остановки запрещён»: он обязывает остановиться и уступить дорогу."}},{"uk":"Знак 3.","ru":"Знак 3."},{"uk":"Знак 4.","ru":"Знак 4.","w":{"uk":"Знак 4 — {s:2.4} «Кінець головної дороги»: він скасовує право першочергового проїзду.","ru":"Знак 4 — {s:2.4} «Конец главной дороги»: он отменяет право первоочередного проезда."}},{"uk":"Знаки 1 і 2.","ru":"Знаки 1 и 2.","w":{"uk":"Знаки 1 і 2 зобов'язують поступитися дорогою, а не дають переваги.","ru":"Знаки 1 и 2 обязывают уступить дорогу, а не дают преимущества."}}],"c":2,"e":{"uk":"Знак 3 — {s:2.3} «Головна дорога»: він надає право першочергового проїзду нерегульованих перехресть ({p:33.2}).","ru":"Знак 3 — {s:2.3} «Главная дорога»: он предоставляет право первоочередного проезда нерегулируемых перекрёстков ({p:33.2})."},"ref":["33.2"],"pic":["img/hsc/33-311-1.jpg"]},{"id":"h33-312","t":"h33","num":"33.312","q":{"uk":"Зображений дорожній знак, встановлений на нерегульованому перехресті:","ru":"Изображённый дорожный знак, установленный на нерегулируемом перекрёстке:"},"a":[{"uk":"Зобов'язує водія дати дорогу транспортним засобам, які під'їжджають до нерегульованого перехрестя по дорозі, що перетинається.","ru":"Обязывает водителя уступить дорогу транспортным средствам, подъезжающим к нерегулируемому перекрёстку по пересекаемой дороге.","w":{"uk":"Так діє знак {s:2.1} «Дати дорогу» (перевернутий трикутник).","ru":"Так действует знак {s:2.1} «Уступить дорогу» (перевёрнутый треугольник)."}},{"uk":"Зобов'язує водія дати дорогу транспортним засобам, які під'їжджають до нерегульованого перехрестя по дорозі, що перетинається, з обов'язковою зупинкою перед розміткою «Стоп-лінія».","ru":"Обязывает водителя уступить дорогу транспортным средствам, подъезжающим к нерегулируемому перекрёстку по пересекаемой дороге, с обязательной остановкой перед разметкой «Стоп-линия».","w":{"uk":"Так діє знак {s:2.2} «Проїзд без зупинки заборонено» (восьмикутник «STOP»).","ru":"Так действует знак {s:2.2} «Проезд без остановки запрещён» (восьмиугольник «STOP»)."}},{"uk":"Надає водієві право на першочерговий проїзд перехрестя.","ru":"Предоставляет водителю право на первоочередной проезд перекрёстка."}],"c":2,"e":{"uk":"Це знак {s:2.3} «Головна дорога»: він надає право першочергового проїзду нерегульованих перехресть ({p:33.2}).","ru":"Это знак {s:2.3} «Главная дорога»: он предоставляет право первоочередного проезда нерегулируемых перекрёстков ({p:33.2})."},"ref":["33.2"],"pic":["img/hsc/33-312-1.jpg"]},{"id":"h33-313","t":"h33","num":"33.313","q":{"uk":"Як Ви повинні вчинити в даній ситуації?","ru":"Как вы должны поступить в данной ситуации?"},"a":[{"uk":"Проїхати першим.","ru":"Проехать первым."},{"uk":"Дати дорогу зустрічному автомобілю.","ru":"Уступить дорогу встречному автомобилю.","w":{"uk":"Дати дорогу зустрічному мав би той, перед ким стоїть знак {s:2.5}; синій знак {s:2.6} дає перевагу вам.","ru":"Уступить дорогу встречному должен был бы тот, перед кем стоит знак {s:2.5}; синий знак {s:2.6} даёт преимущество вам."}}],"c":0,"e":{"uk":"Перед мостом для вас установлено знак {s:2.6} «Перевага перед зустрічним рухом»: на вузькій ділянці ви маєте перевагу стосовно зустрічних транспортних засобів ({p:33.2}), тож проїжджаєте першим.","ru":"Перед мостом для вас установлен знак {s:2.6} «Преимущество перед встречным движением»: на узком участке вы имеете преимущество по отношению к встречным транспортным средствам ({p:33.2}), поэтому проезжаете первым."},"ref":["33.2"],"pic":["img/hsc/33-313-1.jpg"]},{"id":"h33-314","t":"h33","num":"33.314","q":{"uk":"У якому з випадків водіям транспортних засобів дозволено в'їзд у зону, позначену даними дорожніми знаками?"},"a":[{"uk":"Якщо транспортний засіб належить громадянину, який проживає в зазначеній зоні."},{"uk":"Якщо транспортний засіб належить громадянину, який працює в зазначеній зоні."},{"uk":"Якщо транспортний засіб належить громадянину, який обслуговує підприємства або громадян у зазначеній зоні."},{"uk":"Відповіді 1 і 2."},{"uk":"Відповіді 1, 2 і 3."}],"c":4,"pic":["img/hsc/33-314-1.jpg"]},{"id":"h33-315","t":"h33","num":"33.315","q":{"uk":"Чи дозволено Вам транзитний рух прямо через позначену зону?"},"a":[{"uk":"Дозволено."},{"uk":"Заборонено."}],"c":1,"pic":["img/hsc/33-315-1.jpg"]},{"id":"h33-316","t":"h33","num":"33.316","q":{"uk":"Яким транспортним засобам заборонено рух у зоні дії даного дорожнього знака?"},"a":[{"uk":"Усім автомобілям і тракторам із причепами."},{"uk":"Вантажним автомобілям і тракторам із причепами будь-якого типу."},{"uk":"Транспортним засобам, які виконують буксирування механічних транспортних засобів."},{"uk":"Відповіді 1 і 3."},{"uk":"Відповіді 2 і 3."}],"c":4,"pic":["img/hsc/33-316-1.jpg"]},{"id":"h33-317","t":"h33","num":"33.317","q":{"uk":"Чи дозволено рух легкового автомобіля прямо в даній ситуації?"},"a":[{"uk":"Дозволено."},{"uk":"Заборонено."}],"c":0,"pic":["img/hsc/33-317-1.jpg"]},{"id":"h33-318","t":"h33","num":"33.318","q":{"uk":"Чи дозволено буксирування прямо?"},"a":[{"uk":"Заборонено."},{"uk":"Дозволено."}],"c":0,"pic":["img/hsc/33-318-1.jpg"]},{"id":"h33-319","t":"h33","num":"33.319","q":{"uk":"Зображений дорожній знак забороняє рух:"},"a":[{"uk":"Тракторів."},{"uk":"Самохідних машин і механізмів."},{"uk":"Вантажних автомобілів і транспортних составів з дозволеною максимальною масою понад 3,5 т."},{"uk":"Відповіді 1 і 2."},{"uk":"Відповіді 1, 2 і 3."}],"c":3,"pic":["img/hsc/33-319-1.jpg"]},{"id":"h33-320","t":"h33","num":"33.320","q":{"uk":"Дія зображеного дорожнього знака поширюється на:"},"a":[{"uk":"Мотоцикли та мопеди."},{"uk":"Мотоцикли, мопеди і велосипеди з підвісними двигунами."},{"uk":"Мопеди."},{"uk":"Мопеди і велосипеди з підвісними двигунами."},{"uk":"Мопеди і велосипеди."}],"c":3,"pic":["img/hsc/33-320-1.jpg"]},{"id":"h33-321","t":"h33","num":"33.321","q":{"uk":"Зображений дорожній знак забороняє рух:"},"a":[{"uk":"Велосипедів, мопедів і мотоциклів."},{"uk":"Велосипедів і мопедів."},{"uk":"Велосипедів."}],"c":2,"pic":["img/hsc/33-321-1.jpg"]},{"id":"h33-322","t":"h33","num":"33.322","q":{"uk":"Чи дозволено велосипедистові повернути праворуч, якщо він обслуговує громадян, які там проживають?"},"a":[{"uk":"Дозволено."},{"uk":"Заборонено."}],"c":0,"pic":["img/hsc/33-322-1.jpg"]},{"id":"h33-323","t":"h33","num":"33.323","q":{"uk":"Який із знаків забороняє рух пішоходів?"},"a":[{"uk":"Знак 1."},{"uk":"Знак 2."},{"uk":"Знак 3."},{"uk":"Знак 4."},{"uk":"Знаки 1 і 2."}],"c":0,"pic":["img/hsc/33-323-1.jpg"]},{"id":"h33-324","t":"h33","num":"33.324","q":{"uk":"У якому напрямку дозволено рух трактора в даній ситуації?"},"a":[{"uk":"Тільки Б."},{"uk":"Б і Г."},{"uk":"А і В."},{"uk":"А, В і Г."},{"uk":"У всіх напрямках."}],"c":1,"pic":["img/hsc/33-324-1.jpg"]},{"id":"h33-325","t":"h33","num":"33.325","q":{"uk":"У якому напрямку дозволено рух велосипедистові на даному перехресті?"},"a":[{"uk":"Б."},{"uk":"Б і Г."},{"uk":"А і В."},{"uk":"В і Г."},{"uk":"У всіх напрямках."}],"c":4,"pic":["img/hsc/33-325-1.jpg"]},{"id":"h33-326","t":"h33","num":"33.326","q":{"uk":"Чи дозволено Вам рух прямо до місця роботи, яке знаходиться відразу за знаком?"},"a":[{"uk":"Заборонено."},{"uk":"Дозволено."}],"c":1,"pic":["img/hsc/33-326-1.jpg"]},{"id":"h33-327","t":"h33","num":"33.327","q":{"uk":"Чи дозволено водію з інвалідністю в даній ситуації в'їзд у позначену дорожніми знаками зону за відсутності інших під'їздів?"},"a":[{"uk":"Дозволено."},{"uk":"Заборонено."}],"c":0,"pic":["img/hsc/33-327-1.jpg"]},{"id":"h33-328","t":"h33","num":"33.328","q":{"uk":"Чи дозволено Вам рух у позначену дорожніми знаками зону за умови, що Ви працюєте в позначеній зоні?"},"a":[{"uk":"Дозволено."},{"uk":"Заборонено."}],"c":1,"pic":["img/hsc/33-328-1.jpg"]},{"id":"h33-329","t":"h33","num":"33.329","q":{"uk":"Чи дозволено Вам в'їзд у позначену дорожніми знаками зону, якщо Ви обслуговуєте підприємство, розташоване в ній, за умови, що відсутні інші під'їзди?"},"a":[{"uk":"Дозволено."},{"uk":"Заборонено."}],"c":0,"pic":["img/hsc/33-329-1.jpg"]},{"id":"h33-330","t":"h33","num":"33.330","q":{"uk":"На які з перелічених транспортних засобів не поширює свою дію даний дорожній знак?"},"a":[{"uk":"На мопеди."},{"uk":"На велосипеди."},{"uk":"На мотоцикли."},{"uk":"На квадроцикли."},{"uk":"Відповіді 1 і 2."}],"c":1,"pic":["img/hsc/33-330-1.jpg"]},{"id":"h33-331","t":"h33","num":"33.331","q":{"uk":"На які з перелічених транспортних засобів поширює дію цей дорожній знак?"},"a":[{"uk":"На автомобілі."},{"uk":"На мотоцикли."},{"uk":"На мопеди."},{"uk":"На автобуси."},{"uk":"Відповіді 1, 2, 3 і 4."}],"c":4,"pic":["img/hsc/33-331-1.jpg"]},{"id":"h33-332","t":"h33","num":"33.332","q":{"uk":"Хто з учасників дорожнього руху порушує Правила дорожнього руху в даній ситуації за умови, що водій таксі везе пасажира, який проживає в зазначеній зоні?"},"a":[{"uk":"Людина, що керує гужовим возом."},{"uk":"Велосипедист."},{"uk":"Водій мопеда."},{"uk":"Водій таксі, що везе пасажира, який проживає в цій зоні."},{"uk":"Ніхто не порушує."}],"c":2,"pic":["img/hsc/33-332-1.jpg"]},{"id":"h33-333","t":"h33","num":"33.333","q":{"uk":"Даний дорожній знак не поширює свою дію:"},"a":[{"uk":"На транспортні засоби, що обслуговують громадян чи належать громадянам, які проживають або працюють у позначеній зоні."},{"uk":"На транспортні засоби, що обслуговують підприємства, які розташовані в позначеній зоні."},{"uk":"На транспортні засоби, що рухаються за встановленими маршрутами."},{"uk":"Відповіді 1 і 2."},{"uk":"Відповіді 1, 2 і 3."}],"c":4,"pic":["img/hsc/33-333-1.jpg"]},{"id":"h33-334","t":"h33","num":"33.334","q":{"uk":"Який із зображених дорожніх знаків забороняє рух пішоходів з ручними візками?"},"a":[{"uk":"Знак 1."},{"uk":"Знак 2."},{"uk":"Знак 3."},{"uk":"Знак 4."},{"uk":"Знак 5."}],"c":2,"pic":["img/hsc/33-334-1.jpg"]},{"id":"h33-335","t":"h33","num":"33.335","q":{"uk":"З якою дорожньою розміткою може застосовуватися дорожній знак «Стоянку заборонено»?"},"a":[{"uk":"З жовтою переривчастою лінією розмітки, яка наноситься біля краю проїзної частини або по верху бордюру."},{"uk":"З жовтою суцільною лінією розмітки, яка наноситься біля краю проїзної частини або по верху бордюру."},{"uk":"З білою переривчастою лінією розмітки, яка наноситься біля краю проїзної частини або по верху бордюру."},{"uk":"З білою суцільною лінією розмітки, яка наноситься біля краю проїзної частини або по верху бордюру."}],"c":0},{"id":"h33-336","t":"h33","num":"33.336","q":{"uk":"Попереджувальні знаки встановлюють до початку небезпечної ділянки поза населеними пунктами на відстані:"},"a":[{"uk":"150 – 200 м."},{"uk":"100 – 300 м."},{"uk":"150 – 300 м."},{"uk":"50 – 100 м."}],"c":2},{"id":"h33-337","t":"h33","num":"33.337","q":{"uk":"Попереджувальні знаки встановлюють до початку небезпечної ділянки в населених пунктах на відстані:"},"a":[{"uk":"10 – 50 м."},{"uk":"50 – 100 м."},{"uk":"150 – 300 м."},{"uk":"20 – 50 м."}],"c":1},{"id":"h33-338","t":"h33","num":"33.338","q":{"uk":"Зображений дорожній знак позначає:"},"a":[{"uk":"Велосипедну смугу."},{"uk":"Велосипедну доріжку."},{"uk":"Велосипедний переїзд."}],"c":0,"pic":["img/hsc/33-338-1.jpg"]},{"id":"h33-339","t":"h33","num":"33.339","q":{"uk":"Вказаний дорожній знак позначає:"},"a":[{"uk":"Діагональний пішохідний перехід."},{"uk":"Підземний пішохідний перехід."},{"uk":"Пішохідну доріжку."}],"c":0,"pic":["img/hsc/33-339-1.jpg"]},{"id":"h33-340","t":"h33","num":"33.340","q":{"uk":"Вказаний дорожній знак позначає:"},"a":[{"uk":"Початок населеного пункту."},{"uk":"Початок ділянки дороги, що проходить через тунель довжиною 1000 м і більше."},{"uk":"Початок населеного пункту, де відсутня забудова."}],"c":1,"pic":["img/hsc/33-340-1.jpg"]},{"id":"h33-341","t":"h33","num":"33.341","q":{"uk":"Вказаний дорожній знак попереджає про наближення до:"},"a":[{"uk":"Місця (ділянки) концентрації дорожньо-транспортних пригод."},{"uk":"Залізничного переїзду."},{"uk":"Ділянки, де можливе падіння каміння."}],"c":0,"pic":["img/hsc/33-341-1.jpg"]},{"id":"h33-342","t":"h33","num":"33.342","q":{"uk":"Зображений дорожній знак:"},"a":[{"uk":"Забороняє рух зазначених на ньому транспортних засобів."},{"uk":"Забороняє обгін зазначених на ньому транспортних засобів."},{"uk":"Забороняє рух усіх транспортних засобів."}],"c":0,"pic":["img/hsc/33-342-1.jpg"]},{"id":"h33-343","t":"h33","num":"33.343","q":{"uk":"Зображений дорожній знак інформує про:"},"a":[{"uk":"Суміжні пішохідний перехід та велосипедний переїзд."},{"uk":"Доріжку для пішоходів та велосипедистів."},{"uk":"Суміжну пішохідну та велосипедну доріжки."}],"c":2,"pic":["img/hsc/33-343-1.jpg"]},{"id":"h33-344","t":"h33","num":"33.344","q":{"uk":"Зображений дорожній знак позначає:"},"a":[{"uk":"Рух із застосуванням ланцюгів проти ковзання."},{"uk":"Рух лише вантажних автомобілів із застосуванням ланцюгів проти ковзання."},{"uk":"Місця розташування шиномонтажу."}],"c":0,"pic":["img/hsc/33-344-1.jpg"]},{"id":"h33-345","t":"h33","num":"33.345","q":{"uk":"Зображений дорожній знак інформує про дорогу:"},"a":[{"uk":"Із зустрічною велосипедною смугою."},{"uk":"Для суміщеного руху легкових автомобілів та велосипедистів."},{"uk":"Де велосипедна доріжка перетинає проїзну частину."}],"c":1,"pic":["img/hsc/33-345-1.jpg"]},{"id":"h33-346","t":"h33","num":"33.346","q":{"uk":"Зображений дорожній знак позначає виїзд на дорогу, де рух транспортних засобів, що рухаються за встановленими маршрутами, здійснюється спеціально відведеною смугою, позначеною знаком 5.11:"},"a":[{"uk":"Попутно загальному потоку."},{"uk":"Назустріч загальному потоку."}],"c":0,"pic":["img/hsc/33-346-1.jpg"]},{"id":"h33-347","t":"h33","num":"33.347","q":{"uk":"Зображений дорожній знак позначає:"},"a":[{"uk":"Мінімальну швидкість на різних смугах руху."},{"uk":"Обмеження максимальної швидкості на різних смугах руху."},{"uk":"Початок додаткової смуги руху."}],"c":0,"pic":["img/hsc/33-347-1.jpg"]},{"id":"h33-348","t":"h33","num":"33.348","q":{"uk":"Вказаний дорожній знак позначає:"},"a":[{"uk":"Мінімальну швидкість на різних смугах руху."},{"uk":"Обмеження максимальної швидкості на різних смугах руху."},{"uk":"Початок додаткової смуги руху."}],"c":1,"pic":["img/hsc/33-348-1.jpg"]},{"id":"h33-349","t":"h33","num":"33.349","q":{"uk":"Вказаний дорожній знак позначає:"},"a":[{"uk":"Місця, де може зупинитися вантажний автомобіль, фургон тощо, виключно на час, необхідний для розвантаження/завантаження."},{"uk":"Місця, призначені для стоянки виключно вантажних транспортних засобів."},{"uk":"Місця для стоянки транспортних засобів, що здійснюють міжнародні автомобільні перевезення вантажів."}],"c":0,"pic":["img/hsc/33-349-1.jpg"]},{"id":"h33-350","t":"h33","num":"33.350","q":{"uk":"Зображений дорожній знак позначає:"},"a":[{"uk":"Місце розташування автовокзалу чи автостанції."},{"uk":"Місце розташування морського (річкового) порту чи вокзалу."}],"c":1,"pic":["img/hsc/33-350-1.jpg"]},{"id":"h33-351","t":"h33","num":"33.351","q":{"uk":"Вказаний дорожній знак позначає:"},"a":[{"uk":"Платну дорогу."},{"uk":"Номер і напрямок дороги."},{"uk":"Загальні обмеження швидкості."}],"c":0,"pic":["img/hsc/33-351-1.jpg"]},{"id":"h33-352","t":"h33","num":"33.352","q":{"uk":"Вказаний дорожній знак інформує про:"},"a":[{"uk":"Зону для пішоходів."},{"uk":"Зону для велосипедистів."},{"uk":"Зону для пішоходів і велосипедистів."}],"c":0,"pic":["img/hsc/33-352-1.jpg"]},{"id":"h33-353","t":"h33","num":"33.353","q":{"uk":"Зображений дорожній знак позначає:"},"a":[{"uk":"Дорогу, на якій по спеціально виділеній і відокремленій розміткою смузі, організовано рух велосипедистів у зустрічному до загального потоку транспортних засобів напрямку."},{"uk":"Велосипедну смугу."},{"uk":"Місця, де велосипедна доріжка перетинає проїзну частину."}],"c":0,"pic":["img/hsc/33-353-1.jpg"]},{"id":"h33-354","t":"h33","num":"33.354","q":{"uk":"Зображена табличка застосовується для:"},"a":[{"uk":"Інформування водіїв про наявність попереду острівця безпеки і звуження ширини проїзної частини."},{"uk":"Позначення смуги руху, на яку поширюється дія знака або світлофора."},{"uk":"Зазначення розташування майданчиків для стоянки відносно дороги."}],"c":0,"pic":["img/hsc/33-354-1.jpg"]},{"id":"h33-355","t":"h33","num":"33.355","q":{"uk":"Зображена табличка застосовується для:"},"a":[{"uk":"Позначення майданчиків для стоянки та місць, на яких є естакада або оглядова канава."},{"uk":"Попередження про можливу евакуацію автомобіля без відома власника."},{"uk":"Позначення місць розташування шиномонтажу."}],"c":1,"pic":["img/hsc/33-355-1.jpg"]},{"id":"h33-356","t":"h33","num":"33.356","q":{"uk":"Зображений дорожній знак позначає:"},"a":[{"uk":"Виїзд на дорогу з одностороннім рухом і зустрічною велосипедною смугою."},{"uk":"Велосипедний переїзд."},{"uk":"Велосипедну смугу."}],"c":0,"pic":["img/hsc/33-356-1.jpg"]},{"id":"h33-357","t":"h33","num":"33.357","q":{"uk":"Дія даного дорожнього знаку поширюється на:"},"a":[{"uk":"Всі вантажні автомобілі."},{"uk":"Вантажні автомобілі з дозволеною максимальною масою більше 3,5 т."},{"uk":"Транспортні засоби, що перевозять небезпечні вантажі.»."}],"c":2,"pic":["img/hsc/33-357-1.jpg"]},{"id":"h34-1","t":"h34","num":"34.1","q":{"uk":"Дана дорожня розмітка у вигляді стрілок, нанесена на смузі руху:"},"a":[{"uk":"Надає Вам перевагу в разі перестроювання на праву смугу."},{"uk":"Інформує про те, що дорога повертає праворуч."},{"uk":"Попереджає про наближення до звуження проїзної частини."}],"c":2,"pic":["img/hsc/34-1-1.jpg"]},{"id":"h34-2","t":"h34","num":"34.2","q":{"uk":"Дана вертикальна дорожня розмітка:"},"a":[{"uk":"Забороняє стоянку транспортних засобів."},{"uk":"Не дозволяє зупинку транспортних засобів."},{"uk":"Означає бордюри на небезпечних ділянках доріг."}],"c":2,"pic":["img/hsc/34-2-1.jpg"]},{"id":"h34-3","t":"h34","num":"34.3","q":{"uk":"Чи дозволено Вам поставити автомобіль на стоянку в даному місці?"},"a":[{"uk":"Дозволено."},{"uk":"Дозволено тільки з частковим заїздом на тротуар."},{"uk":"Заборонено."}],"c":2,"pic":["img/hsc/34-3-1.jpg"]},{"id":"h34-4","t":"h34","num":"34.4","q":{"uk":"Дана дорожня розмітка позначає:"},"a":[{"uk":"Місце, де починається або закінчується житлова зона."},{"uk":"Попереджає про наближення до пристрою примусового зниження швидкості руху транспортних засобів."},{"uk":"Місце, де починається заборона на подальший рух."}],"c":1,"pic":["img/hsc/34-4-1.jpg"]},{"id":"h34-5","t":"h34","num":"34.5","q":{"uk":"Який маневр забороняє Вам зображена лінія дорожньої розмітки?"},"a":[{"uk":"Тільки обгін."},{"uk":"Тільки об'їзд."},{"uk":"Тільки розворот."},{"uk":"Жоден з вищеперерахованих маневрів не заборонено.."}],"c":3,"pic":["img/hsc/34-5-1.jpg"]},{"id":"h34-6","t":"h34","num":"34.6","q":{"uk":"Дана дорожня розмітка позначає:"},"a":[{"uk":"Номер дороги або маршруту."},{"uk":"Рекомендовану швидкість руху на цій ділянці дороги."},{"uk":"Дозволену максимальну швидкість руху на цій ділянці дороги, дублюючи дорожній знак «Обмеження максимальної швидкості»."}],"c":2,"pic":["img/hsc/34-6-1.jpg"]},{"id":"h34-7","t":"h34","num":"34.7","q":{"uk":"Даною вертикальною дорожньою розміткою позначають:"},"a":[{"uk":"Нижній край прогону штучної споруди, конструкції тунелів, якщо відстань від нього до поверхні дорожнього покриття становить 5 м або менше."},{"uk":"Тільки в'їзд у неосвітлені тунелі."},{"uk":"Будь-які елементи дорожніх споруд, які становлять небезпеку."}],"c":0,"pic":["img/hsc/34-7-1.jpg"]},{"id":"h34-8","t":"h34","num":"34.8","q":{"uk":"Що означає напис на проїзній частині дороги?"},"a":[{"uk":"Відстань до найближчого перехрестя."},{"uk":"Відстань до найближчого населеного пункту."},{"uk":"Номер дороги або маршруту."}],"c":2,"pic":["img/hsc/34-8-1.jpg"]},{"id":"h34-9","t":"h34","num":"34.9","q":{"uk":"Даною дорожньою розміткою у вигляді букви «А» позначають:"},"a":[{"uk":"Спеціальну смугу для маршрутних транспортних засобів."},{"uk":"Смугу призначену для руху транспортних засобів, що рухаються за встановленими маршрутами, мопедів, мотоциклів (за винятком мотоциклів з боковим причепом, мотоколясок, триколісних транспортних засобів), таксі та велосипедистів."},{"uk":"Місце зупинки і стоянки будь-яких автобусів."}],"c":1,"pic":["img/hsc/34-9-1.jpg"]},{"id":"h34-10","t":"h34","num":"34.10","q":{"uk":"Даною лінією дорожньої розмітки позначають:"},"a":[{"uk":"Ділянку дороги, де заборонено рух поблизу тротуару."},{"uk":"Місця, де заборонено будь-яку зупинку."},{"uk":"Місця зупинки маршрутних транспортних засобів."}],"c":2,"pic":["img/hsc/34-10-1.jpg"]},{"id":"h34-11","t":"h34","num":"34.11","q":{"uk":"Як Ви повинні вчинити, якщо реверсивні світлофори вимкнулися:"},"a":[{"uk":"Негайно перестроїтися на праву смугу."},{"uk":"Можете продовжити рух по смузі тільки до перехрестя."},{"uk":"За відсутності зустрічних транспортних засобів продовжити рух по смузі."}],"c":0,"pic":["img/hsc/34-11-1.jpg"]},{"id":"h34-12","t":"h34","num":"34.12","q":{"uk":"По якій траєкторії ви можете об'їхати перешкоду?"},"a":[{"uk":"Тільки по траєкторії А."},{"uk":"Тільки по траєкторії Б."},{"uk":"По будь-якій."}],"c":1,"pic":["img/hsc/34-12-1.jpg"]},{"id":"h34-13","t":"h34","num":"34.13","q":{"uk":"Які з перелічених транспортних засобів мають право рухатися по смузі, позначеній розміткою «А», на яку поширюється дія дорожнього знака, розміщеного праворуч від дороги?"},"a":[{"uk":"Маршрутні транспортні засоби, велосипеди, таксі, мопеди та мотоцикли (за винятком мотоциклів з боковим причепом, мотоколясок, триколісних транспортних засобів)."},{"uk":"Маршрутні транспортні засоби та таксі."},{"uk":"Будь-які автобуси."}],"c":0,"pic":["img/hsc/34-13-1.jpg"]},{"id":"h34-14","t":"h34","num":"34.14","q":{"uk":"Чи дозволено велосипедисту рухатись смугою для маршрутних транспортних засобів позначеній вказаним дорожнім знаком?"},"a":[{"uk":"Дозволено."},{"uk":"Заборонено."}],"c":0,"pic":["img/hsc/34-14-1.jpg"]},{"id":"h34-15","t":"h34","num":"34.15","q":{"uk":"Чи дозволено Вам зупинку в зазначеному місці для висадки пасажира?"},"a":[{"uk":"Дозволено."},{"uk":"Дозволено тільки із заїздом на тротуар."},{"uk":"Дозволено, якщо не буде створено перешкод маршрутним транспортним засобам."},{"uk":"Заборонено."}],"c":0,"pic":["img/hsc/34-15-1.jpg"]},{"id":"h34-16","t":"h34","num":"34.16","q":{"uk":"Дана дорожня розмітка у вигляді стрілки, нанесена на смузі руху:"},"a":[{"uk":"Дозволяє Вам тільки поворот ліворуч."},{"uk":"Дозволяє Вам тільки розворот."},{"uk":"Дозволяє Вам поворот ліворуч і розворот."}],"c":2,"pic":["img/hsc/34-16-1.jpg"]},{"id":"h34-17","t":"h34","num":"34.17","q":{"uk":"Чи дозволено Вам (не водію маршрутного ТЗ) зупинитися в цьому місці для посадки або висадки пасажирів?"},"a":[{"uk":"Так."},{"uk":"Так, якщо Ви не створите перешкод руху маршрутних транспортних засобів."},{"uk":"Ні."}],"c":2,"pic":["img/hsc/34-17-1.jpg"]},{"id":"h34-18","t":"h34","num":"34.18","q":{"uk":"Дана вертикальна дорожня розмітка на огородженні дороги попереджає:"},"a":[{"uk":"Про наближення до залізничного переїзду."},{"uk":"Про наближення до небезпечного перетину."},{"uk":"Про рух по небезпечній ділянці дороги."}],"c":2,"pic":["img/hsc/34-18-1.jpg"]},{"id":"h34-19","t":"h34","num":"34.19","q":{"uk":"Що означає дорожня розмітка у вигляді трикутника на смузі руху?"},"a":[{"uk":"Ви в'їжджаєте на небезпечну ділянку дороги."},{"uk":"Попереджає про наближення до дорожньої розмітки, перед якою водій повинен у разі потреби зупинитися і дати дорогу транспортним засобам, які рухаються по дорозі, що перетинається."},{"uk":"Показує місце, де потрібно зупинитися."}],"c":1,"pic":["img/hsc/34-19-1.jpg"]},{"id":"h34-20","t":"h34","num":"34.20","q":{"uk":"Чи дозволяє Вам дана дорожня розмітка виконати обгін трактора в такій ситуації?"},"a":[{"uk":"Так."},{"uk":"Так, але тільки якщо швидкість трактора менш ніж 30 км/год."},{"uk":"Ні."}],"c":0,"pic":["img/hsc/34-20-1.jpg"]},{"id":"h34-21","t":"h34","num":"34.21","q":{"uk":"Такою вертикальною дорожньою розміткою позначають:"},"a":[{"uk":"Усі вертикальні елементи дорожніх споруд."},{"uk":"Торцеві частини штучних споруд."}],"c":1,"pic":["img/hsc/34-21-1.jpg"]},{"id":"h34-22","t":"h34","num":"34.22","q":{"uk":"Чи дозволено вам випередження по реверсивній смузі, якщо реверсивний світлофор вимкнений?"},"a":[{"uk":"Дозволено."},{"uk":"Заборонено."}],"c":1,"pic":["img/hsc/34-22-1.jpg"]},{"id":"h34-23","t":"h34","num":"34.23","q":{"uk":"У якому місці Ви повинні зупинитися, щоб дати дорогу транспортним засобам на перехрещуванній дорозі, повертаючи ліворуч у даній ситуації?"},"a":[{"uk":"Перед знаком."},{"uk":"Перед перехрестям біля лінії розмітки 1.13."},{"uk":"На перехресті перед переривчастою лінією розмітки."},{"uk":"У будь-якому місці на розсуд водія."}],"c":1,"pic":["img/hsc/34-23-1.jpg"]},{"id":"h34-24","t":"h34","num":"34.24","q":{"uk":"Водій якого автомобіля не порушує Правила дорожнього руху в даній ситуації?"},"a":[{"uk":"Білого автомобіля."},{"uk":"Синього автомобіля."},{"uk":"Обидва порушують."},{"uk":"Обидва не порушують."}],"c":1,"pic":["img/hsc/34-24-1.jpg"]},{"id":"h34-25","t":"h34","num":"34.25","q":{"uk":"У якому із зазначених місць Ви можете перетнути суцільну лінію дорожньої розмітки та зупинитися?"},"a":[{"uk":"Тільки Б."},{"uk":"У будь-якому."},{"uk":"У жодному."}],"c":0,"pic":["img/hsc/34-25-1.jpg"]},{"id":"h34-26","t":"h34","num":"34.26","q":{"uk":"Чи дозволено Вам у легковому автомобілі продовжити рух по правій смузі?"},"a":[{"uk":"Дозволено, якщо швидкість вантажного автомобіля менш ніж 30 км/год."},{"uk":"Дозволено, якщо при цьому не буде створено перешкод руху маршрутних транспортних засобів."},{"uk":"Заборонено."}],"c":2,"pic":["img/hsc/34-26-1.jpg"]},{"id":"h34-27","t":"h34","num":"34.27","q":{"uk":"Що означають переривчасті лінії розмітки, які знаходяться з правого боку від водія?"},"a":[{"uk":"Місця, де дозволено з'їзд на узбіччя тільки для зупинки."},{"uk":"Край проїзної частини."},{"uk":"Межу між основною смугою руху і смугою гальмування."}],"c":2,"pic":["img/hsc/34-27-1.jpg"]},{"id":"h34-28","t":"h34","num":"34.28","q":{"uk":"Чи дозволено Вам стоянку в зазначеному місці?"},"a":[{"uk":"Дозволено."},{"uk":"Дозволено без заїзду на тротуар."},{"uk":"Заборонено."}],"c":2,"pic":["img/hsc/34-28-1.jpg"]},{"id":"h34-29","t":"h34","num":"34.29","q":{"uk":"Чи дозволяє Вам дана дорожня розмітка виконати обгін?"},"a":[{"uk":"Дозволяє в будь-якому випадку."},{"uk":"Дозволяє, якщо швидкість трактора менш ніж 30 км/год."},{"uk":"Забороняє."}],"c":2,"pic":["img/hsc/34-29-1.jpg"]},{"id":"h34-30","t":"h34","num":"34.30","q":{"uk":"У даній ситуації Ви повинні:"},"a":[{"uk":"Зупинитися біля знака."},{"uk":"Зупинитися перед дорожньою розміткою «Стоп-лінія»."},{"uk":"За відсутності інших транспортних засобів проїхати перехрестя без зупинки."}],"c":1,"pic":["img/hsc/34-30-1.jpg"]},{"id":"h34-31","t":"h34","num":"34.31","q":{"uk":"Чим Ви повинні керуватися, якщо значення дорожніх знаків і ліній горизонтальної розмітки суперечать одне одному?"},"a":[{"uk":"Вимогами ліній розмітки."},{"uk":"Вимогами дорожніх знаків."},{"uk":"Правила цю ситуацію не регламентують."}],"c":1},{"id":"h34-32","t":"h34","num":"34.32","q":{"uk":"Що позначає горизонтальна дорожня розмітка у вигляді напису «STOP» на проїзній частині?"},"a":[{"uk":"Наближення до регульованого перехрестя."},{"uk":"Наближення до поперечної розмітки 1.12 (стоп-лінія)."},{"uk":"Наближення до дорожнього знаку «Дати дорогу»."}],"c":1},{"id":"h34-33","t":"h34","num":"34.33","q":{"uk":"Чи дозволено Вам перетинати подвійну суцільну лінію дорожньої розмітки?"},"a":[{"uk":"Дозволено тільки в разі виїзду з дворів та інших прилеглих територій."},{"uk":"Дозволено тільки в разі обгону."},{"uk":"Дозволено тільки в разі інтенсивного руху."},{"uk":"Заборонено."}],"c":3},{"id":"h34-34","t":"h34","num":"34.34","q":{"uk":"Ця горизонтальна дорожня розмітка позначає ділянки, на які забороняється виїжджати на перехресті, якщо попереду утворився затор?"},"a":[{"uk":"Так."},{"uk":"Ні."}],"c":0,"pic":["img/hsc/34-34-1.jpg"]},{"id":"h34-35","t":"h34","num":"34.35","q":{"uk":"Чи дозволено виїжджати на цю горизонтальну розмітку на перехрестях під час заторів?"},"a":[{"uk":"Дозволено."},{"uk":"Заборонено."}],"c":1,"pic":["img/hsc/34-35-1.jpg"]},{"id":"h35-1","t":"h35","num":"35.1","q":{"uk":"В очікуванні сигналу світлофора, що дозволяє рух, необхідно:","ru":"В ожидании сигнала светофора, разрешающего движение, необходимо:"},"a":[{"uk":"Включити завчасно першу передачу, вимкнувши зчеплення в очікуванні дозволяючого сигналу.","ru":"Заранее включить первую передачу, выключив сцепление в ожидании разрешающего сигнала.","w":{"uk":"Вижате під час усього очікування зчеплення зношує вижимний підшипник, а нога може зісковзнути з педалі — і автомобіль рушить на заборонний сигнал.","ru":"Выжатое во время всего ожидания сцепление изнашивает выжимной подшипник, а нога может соскользнуть с педали — и автомобиль тронется на запрещающий сигнал."}},{"uk":"Встановити важіль перемикання передач в нейтральне положення, першу передачу включити тільки при включенні жовтого сигналу світлофора.","ru":"Установить рычаг переключения передач в нейтральное положение, первую передачу включить только при включении жёлтого сигнала светофора."}],"c":1,"e":{"uk":"Довго тримати педаль зчеплення вижатою шкідливо для механізму й стомлює ногу, а якщо нога зісковзне, автомобіль смикнеться вперед на червоний. Тому стоять на нейтралі, а першу передачу вмикають, коли загоряється жовтий, що попереджає про зміну сигналів ({p:8.7}), — і рушають одразу на зелений.","ru":"Долго держать педаль сцепления выжатой вредно для механизма и утомляет ногу, а если нога соскользнёт, автомобиль дёрнется вперёд на красный. Поэтому стоят на нейтрали, а первую передачу включают, когда загорается жёлтый, предупреждающий о смене сигналов ({p:8.7}), — и трогаются сразу на зелёный."},"ref":["8.7"]},{"id":"h35-2","t":"h35","num":"35.2","q":{"uk":"Безпечною дистанцією під час руху сухою дорогою на легковому автомобілі можна вважати відстань, яку автомобіль пройде не менше ніж за:","ru":"Безопасной дистанцией при движении по сухой дороге на легковом автомобиле можно считать расстояние, которое автомобиль проедет не менее чем за:"},"a":[{"uk":"1 секунду.","ru":"1 секунду.","w":{"uk":"Однієї секунди вистачає лише на реакцію водія — на саме гальмування запасу відстані вже не лишається.","ru":"Одной секунды хватает лишь на реакцию водителя — на само торможение запаса расстояния уже не остаётся."}},{"uk":"2 секунди.","ru":"2 секунды."},{"uk":"3 секунди.","ru":"3 секунды.","w":{"uk":"Три секунди й більше радять на мокрій чи слизькій дорозі; для сухої дороги мінімальною безпечною дистанцією вважають дві секунди.","ru":"Три секунды и больше советуют на мокрой или скользкой дороге; для сухой дороги минимальной безопасной дистанцией считают две секунды."}}],"c":1,"e":{"uk":"Для легкового автомобіля на сухому покритті діє «правило двох секунд»: цього часу вистачає, щоб помітити гальмування автомобіля попереду, зреагувати (близько 1 с) і загальмувати так само ефективно. Безпечну дистанцію водій зобов'язаний дотримувати за {p:13.1}.","ru":"Для легкового автомобиля на сухом покрытии действует «правило двух секунд»: этого времени хватает, чтобы заметить торможение впереди идущего автомобиля, среагировать (около 1 с) и затормозить так же эффективно. Соблюдать безопасную дистанцию водитель обязан по {p:13.1}."},"ref":["13.1"]},{"id":"h35-3","t":"h35","num":"35.3","q":{"uk":"Зменшення гальмового шляху транспортного засобу досягається:","ru":"Уменьшение тормозного пути транспортного средства достигается:"},"a":[{"uk":"Гальмуванням з блокуванням коліс (юзом).","ru":"Торможением с блокировкой колёс (юзом).","w":{"uk":"Заблоковане колесо ковзає, а тертя ковзання менше за зчеплення колеса, що котиться, — гальмовий шлях подовжується, автомобіль втрачає керованість і може піти в занос.","ru":"Заблокированное колесо скользит, а трение скольжения меньше сцепления катящегося колеса — тормозной путь удлиняется, автомобиль теряет управляемость и может уйти в занос."}},{"uk":"Гальмуванням на межі блокування способом переривчастого натискання на педаль гальма.","ru":"Торможением на грани блокировки способом прерывистого нажатия на педаль тормоза."}],"c":1,"e":{"uk":"Колесо, що котиться на межі блокування, має краще зчеплення з дорогою, ніж колесо, що ковзає юзом. Переривчасте натискання на педаль не дає колесам заблокуватися, скорочує гальмовий шлях і зберігає керованість — за тим самим принципом працює АБС.","ru":"Колесо, катящееся на грани блокировки, имеет лучшее сцепление с дорогой, чем колесо, скользящее юзом. Прерывистое нажатие на педаль не даёт колёсам заблокироваться, сокращает тормозной путь и сохраняет управляемость — по тому же принципу работает АБС."}},{"id":"h35-4","t":"h35","num":"35.4","q":{"uk":"Під час руху в умовах поганої видимості потрібно вибирати швидкість, виходячи з того, що зупинний шлях має бути:","ru":"При движении в условиях плохой видимости нужно выбирать скорость, исходя из того, что остановочный путь должен быть:"},"a":[{"uk":"Більше відстані видимості.","ru":"Больше расстояния видимости.","w":{"uk":"Тоді перед перешкодою, що з'явилася на межі видимості, зупинитися вже не вдасться — наїзд стане неминучим.","ru":"Тогда перед препятствием, появившимся на границе видимости, остановиться уже не удастся — наезд станет неизбежным."}},{"uk":"Менше відстані видимості.","ru":"Меньше расстояния видимости."}],"c":1,"e":{"uk":"За {p:12.2} у темну пору доби та за недостатньої видимості швидкість має бути такою, щоб водій міг зупинитися **в межах видимості дороги** — тобто зупинний шлях має бути меншим за відстань, яку він бачить.","ru":"По {p:12.2} в тёмное время суток и при недостаточной видимости скорость должна быть такой, чтобы водитель мог остановиться **в пределах видимости дороги** — то есть остановочный путь должен быть меньше расстояния, которое он видит."},"ref":["12.2"]},{"id":"h35-5","t":"h35","num":"35.5","q":{"uk":"Що мається на увазі під часом реакції водія?","ru":"Что подразумевается под временем реакции водителя?"},"a":[{"uk":"Час з моменту виявлення водієм небезпеки до повної зупинки транспортного засобу.","ru":"Время с момента обнаружения водителем опасности до полной остановки транспортного средства.","w":{"uk":"Це час проходження всього зупинного шляху: до реакції додаються ще спрацювання гальм і саме гальмування.","ru":"Это время прохождения всего остановочного пути: к реакции добавляются ещё срабатывание тормозов и само торможение."}},{"uk":"Час з моменту виявлення водієм небезпеки чи перешкоди для руху до початку вжиття ним заходів задля запобігання контакту з ними.","ru":"Время с момента обнаружения водителем опасности или препятствия для движения до начала принятия им мер для предотвращения контакта с ними."},{"uk":"Час, необхідний для перенесення ноги з педалі подачі акселератора на педаль гальмування.","ru":"Время, необходимое для переноса ноги с педали акселератора на педаль тормоза.","w":{"uk":"Перенесення ноги на гальмо — лише завершальна частина реакції; до неї входить ще час, щоб помітити небезпеку й ухвалити рішення.","ru":"Перенос ноги на тормоз — лишь завершающая часть реакции; в неё входит ещё время, чтобы заметить опасность и принять решение."}}],"c":1,"e":{"uk":"Час реакції — це проміжок від моменту, коли водій помітив небезпеку, до початку його дій (натискання на гальмо, поворот керма). Зазвичай він становить 0,8–1,5 с і зростає від утоми, відволікання, алкоголю.","ru":"Время реакции — это промежуток от момента, когда водитель заметил опасность, до начала его действий (нажатие на тормоз, поворот руля). Обычно оно составляет 0,8–1,5 с и растёт от усталости, отвлечения, алкоголя."}},{"id":"h35-6","t":"h35","num":"35.6","q":{"uk":"У яких випадках слід збільшити боковий інтервал?","ru":"В каких случаях следует увеличить боковой интервал?"},"a":[{"uk":"При зустрічному роз'їзді з великою швидкістю.","ru":"При встречном разъезде с большой скоростью.","w":{"uk":"Велика швидкість справді вимагає більшого інтервалу, але це лише один із трьох наведених випадків.","ru":"Большая скорость действительно требует большего интервала, но это лишь один из трёх приведённых случаев."}},{"uk":"Під час роз'їзду з довгомірним транспортним засобом.","ru":"При разъезде с длинномерным транспортным средством.","w":{"uk":"Роз'їзд із довгомірним транспортним засобом справді вимагає більшого інтервалу, але так само слід діяти й в інших наведених випадках.","ru":"Разъезд с длинномерным транспортным средством действительно требует большего интервала, но так же следует поступать и в других приведённых случаях."}},{"uk":"Під час руху мокрим, слизьким або нерівним покриттям.","ru":"При движении по мокрому, скользкому или неровному покрытию.","w":{"uk":"Мокре чи нерівне покриття справді вимагає більшого інтервалу, але це не єдиний такий випадок серед наведених.","ru":"Мокрое или неровное покрытие действительно требует большего интервала, но это не единственный такой случай среди приведённых."}},{"uk":"У всіх наведених випадках.","ru":"Во всех приведённых случаях."}],"c":3,"e":{"uk":"Безпечний інтервал обирають залежно від швидкості й дорожньої обстановки ({p:13.1}, {p:13.3}): на великій швидкості та на слизькому чи нерівному покритті автомобіль легко зміщується вбік, а довгомірний транспортний засіб може «вильнути» причепом і створює сильний потік повітря. Тому в усіх цих випадках інтервал збільшують.","ru":"Безопасный интервал выбирают в зависимости от скорости и дорожной обстановки ({p:13.1}, {p:13.3}): на большой скорости и на скользком или неровном покрытии автомобиль легко смещается в сторону, а длинномерное транспортное средство может «вильнуть» прицепом и создаёт сильный поток воздуха. Поэтому во всех этих случаях интервал увеличивают."},"ref":["13.1","13.3"]},{"id":"h35-7","t":"h35","num":"35.7","q":{"uk":"Рухатися по глибокому снігу на ґрунтовій дорозі слід:","ru":"Двигаться по глубокому снегу на грунтовой дороге следует:"},"a":[{"uk":"Змінюючи швидкість руху і передачу залежно від стану дороги.","ru":"Изменяя скорость движения и передачу в зависимости от состояния дороги.","w":{"uk":"Під час перемикання передачі тягове зусилля зникає, і в глибокому снігу автомобіль може зупинитися й застрягти.","ru":"При переключении передачи тяговое усилие пропадает, и в глубоком снегу автомобиль может остановиться и застрять."}},{"uk":"На заздалегідь обраній зниженій передачі, без різких поворотів і зупинок.","ru":"На заранее выбранной пониженной передаче, без резких поворотов и остановок."}],"c":1,"e":{"uk":"Глибокий сніг чинить великий опір руху: під час перемикання передачі тяга на мить зникає, і автомобіль швидко зупиняється й застрягає, а рушити з місця в снігу важко. Тому їдуть рівномірно на заздалегідь обраній зниженій передачі, без різких поворотів і зупинок.","ru":"Глубокий снег оказывает большое сопротивление движению: при переключении передачи тяга на мгновение пропадает, и автомобиль быстро останавливается и застревает, а тронуться с места в снегу трудно. Поэтому едут равномерно на заранее выбранной пониженной передаче, без резких поворотов и остановок."}},{"id":"h35-8","t":"h35","num":"35.8","q":{"uk":"Чи виключає антиблокувальна гальмівна система можливість виникнення занесення або знесення під час проходження повороту?","ru":"Исключает ли антиблокировочная тормозная система возможность возникновения заноса или сноса при прохождении поворота?"},"a":[{"uk":"Повністю виключає можливість виникнення тільки занесення.","ru":"Полностью исключает возможность возникновения только заноса.","w":{"uk":"АБС не запобігає занесенню, спричиненому завеликою швидкістю в повороті чи різкими діями кермом або педаллю газу.","ru":"АБС не предотвращает занос, вызванный слишком высокой скоростью в повороте или резкими действиями рулём или педалью газа."}},{"uk":"Повністю виключає можливість виникнення тільки знесення.","ru":"Полностью исключает возможность возникновения только сноса.","w":{"uk":"Знесення передньої осі через завелику швидкість у повороті АБС так само не виключає.","ru":"Снос передней оси из-за слишком высокой скорости в повороте АБС точно так же не исключает."}},{"uk":"Не виключає можливість виникнення знесення або занесення.","ru":"Не исключает возможность возникновения сноса или заноса."}],"c":2,"e":{"uk":"АБС лише не дає колесам заблокуватися під час гальмування й зберігає керованість, але не скасовує законів фізики: якщо швидкість у повороті завелика для наявного зчеплення, можливе і знесення (ковзання передньої осі), і занесення (ковзання задньої осі).","ru":"АБС лишь не даёт колёсам заблокироваться при торможении и сохраняет управляемость, но не отменяет законов физики: если скорость в повороте слишком велика для имеющегося сцепления, возможен и снос (скольжение передней оси), и занос (скольжение задней оси)."}},{"id":"h35-9","t":"h35","num":"35.9","q":{"uk":"Рухаючись прямо зі швидкістю 50 км/год., ви раптово потрапили на невелику слизьку ділянку дороги. Що слід зробити?","ru":"Двигаясь прямо со скоростью 50 км/ч, вы внезапно попали на небольшой скользкий участок дороги. Что следует сделать?"},"a":[{"uk":"Плавно загальмувати.","ru":"Плавно затормозить.","w":{"uk":"Навіть плавне гальмування на льоду може заблокувати колеса (нерідко нерівномірно) і спричинити занесення, а на короткій ділянці воно все одно майже не зменшить швидкість.","ru":"Даже плавное торможение на льду может заблокировать колёса (нередко неравномерно) и вызвать занос, а на коротком участке оно всё равно почти не снизит скорость."}},{"uk":"Не змінювати траєкторії та швидкості руху.","ru":"Не изменять траекторию и скорость движения."}],"c":1,"e":{"uk":"На слизькій ділянці зчеплення різко падає, і будь-яке гальмування чи поворот керма може зірвати колеса в ковзання та спричинити занос. Ділянка невелика, тож безпечніше проїхати її прямо за інерцією, не змінюючи швидкості й траєкторії.","ru":"На скользком участке сцепление резко падает, и любое торможение или поворот руля может сорвать колёса в скольжение и вызвать занос. Участок небольшой, поэтому безопаснее проехать его прямо по инерции, не меняя скорости и траектории."}},{"id":"h35-10","t":"h35","num":"35.10","q":{"uk":"Увімкнення яких зовнішніх світлових приладів забезпечить вам найкращу видимість дороги під час руху вночі за сильної хуртовини?","ru":"Включение каких внешних световых приборов обеспечит вам наилучшую видимость дороги при движении ночью в сильную метель?"},"a":[{"uk":"Протитуманних фар спільно з дальнім світлом фар.","ru":"Противотуманных фар совместно с дальним светом фар.","w":{"uk":"У хуртовину дальнє світло відбивається від снігу й засліплює водія — видимість не покращується, а погіршується.","ru":"В метель дальний свет отражается от снега и ослепляет водителя — видимость не улучшается, а ухудшается."}},{"uk":"Протитуманних фар спільно з ближнім світлом фар.","ru":"Противотуманных фар совместно с ближним светом фар."}],"c":1,"e":{"uk":"Дальнє світло відбивається від сніжинок і створює перед автомобілем «світлову завісу», яка засліплює самого водія. Ближнє світло й низько розташовані протитуманні фари світять під сніговою пеленою й краще освітлюють дорогу; вночі протитуманні фари вмикають лише разом із фарами ближнього чи дальнього світла ({p:19.5}), і в хуртовину це має бути ближнє.","ru":"Дальний свет отражается от снежинок и создаёт перед автомобилем «световую завесу», которая ослепляет самого водителя. Ближний свет и низко расположенные противотуманные фары светят под снежной пеленой и лучше освещают дорогу; ночью противотуманные фары включают только вместе с фарами ближнего или дальнего света ({p:19.5}), и в метель это должен быть ближний."},"ref":["19.5"]},{"id":"h35-11","t":"h35","num":"35.11","q":{"uk":"У якому з перелічених випадків водієві слід оцінювати обстановку позаду?","ru":"В каком из перечисленных случаев водителю следует оценивать обстановку сзади?"},"a":[{"uk":"Тільки у випадку різкого гальмування.","ru":"Только в случае резкого торможения.","w":{"uk":"Навіть плавне гальмування може застати зненацька неуважного водія позаду, тож стежити за ним треба завжди.","ru":"Даже плавное торможение может застать врасплох невнимательного водителя сзади, поэтому следить за ним нужно всегда."}},{"uk":"Тільки у випадку гальмування на дорозі з мокрим або слизьким покриттям.","ru":"Только в случае торможения на дороге с мокрым или скользким покрытием.","w":{"uk":"На сухій дорозі водій позаду теж може не встигнути загальмувати, тому обстановку позаду оцінюють за будь-якого гальмування.","ru":"На сухой дороге водитель сзади тоже может не успеть затормозить, поэтому обстановку сзади оценивают при любом торможении."}},{"uk":"У випадку будь-якого гальмування.","ru":"В случае любого торможения."}],"c":2,"e":{"uk":"Будь-яке гальмування може виявитися несподіваним для водія, що їде позаду, особливо якщо він тримає замалу дистанцію або відволікся. Тому, гальмуючи, слід стежити в дзеркала за обстановкою позаду — це частина обов'язку стежити за дорожньою обстановкою ({p:2.3}).","ru":"Любое торможение может оказаться неожиданным для водителя, едущего сзади, особенно если он держит слишком малую дистанцию или отвлёкся. Поэтому, тормозя, следует следить в зеркала за обстановкой сзади — это часть обязанности следить за дорожной обстановкой ({p:2.3})."},"ref":["2.3"]},{"id":"h35-12","t":"h35","num":"35.12","q":{"uk":"Де повинна бути розташована ступня лівої ноги водія при керуванні автомобілем з механічною коробкою передач (з увімкненим зчепленням)?","ru":"Где должна располагаться ступня левой ноги водителя при управлении автомобилем с механической коробкой передач (при включённом сцеплении)?"},"a":[{"uk":"На підлозі перед педаллю зчеплення.","ru":"На полу перед педалью сцепления.","w":{"uk":"Ступня перед педаллю може опинитися під нею й завадити повністю вимкнути зчеплення, коли це знадобиться.","ru":"Ступня перед педалью может оказаться под ней и помешать полностью выключить сцепление, когда это понадобится."}},{"uk":"Над педаллю зчеплення, не торкаючись педалі.","ru":"Над педалью сцепления, не касаясь педали.","w":{"uk":"Тримати ногу на вазі втомливо, а випадковий дотик до педалі частково вимикає зчеплення й прискорює його знос.","ru":"Держать ногу на весу утомительно, а случайное касание педали частично выключает сцепление и ускоряет его износ."}},{"uk":"Зліва від педалі на підлозі або спеціальному майданчику.","ru":"Слева от педали на полу или специальной площадке."}],"c":2,"e":{"uk":"Коли зчеплення увімкнене, ліва нога має відпочивати ліворуч від педалі — на підлозі чи спеціальному майданчику. Так вона не натискає педаль випадково, не заважає її ходу й слугує опорою для тіла в поворотах.","ru":"Когда сцепление включено, левая нога должна отдыхать слева от педали — на полу или специальной площадке. Так она не нажимает педаль случайно, не мешает её ходу и служит опорой для тела в поворотах."}},{"id":"h35-13","t":"h35","num":"35.13","q":{"uk":"Якщо Ви сідаєте за кермо автомобіля після іншого водія, яка повинна бути послідовність Ваших дій?","ru":"Если вы садитесь за руль автомобиля после другого водителя, какой должна быть последовательность ваших действий?"},"a":[{"uk":"Пристебнути пасок безпеки, відрегулювати положення рульової колонки, відрегулювати положення дзеркал заднього виду, відрегулювати положення сидіння.","ru":"Пристегнуть ремень безопасности, отрегулировать положение рулевой колонки, отрегулировать положение зеркал заднего вида, отрегулировать положение сиденья.","w":{"uk":"Після регулювання сидіння положення голови й рук зміниться, і кермо та дзеркала доведеться налаштовувати знову; ремінь пристібають наостанок.","ru":"После регулировки сиденья положение головы и рук изменится, и руль и зеркала придётся настраивать заново; ремень пристёгивают в последнюю очередь."}},{"uk":"Відрегулювати положення дзеркал заднього виду, відрегулювати положення сидіння, відрегулювати положення рульової колонки.","ru":"Отрегулировать положение зеркал заднего вида, отрегулировать положение сиденья, отрегулировать положение рулевой колонки.","w":{"uk":"Дзеркала налаштовують після сидіння, а не до нього; до того ж у цьому переліку взагалі немає пристібання ременя безпеки.","ru":"Зеркала настраивают после сиденья, а не до него; к тому же в этом перечне вообще нет пристёгивания ремня безопасности."}},{"uk":"Відрегулювати положення сидіння, відрегулювати положення рульової колонки, відрегулювати положення дзеркал заднього виду, пристебнути пасок безпеки.","ru":"Отрегулировать положение сиденья, отрегулировать положение рулевой колонки, отрегулировать положение зеркал заднего вида, пристегнуть ремень безопасности."}],"c":2,"e":{"uk":"Спершу налаштовують сидіння — від нього залежить положення тіла й очей; потім кермову колонку під руки; потім дзеркала, бо огляд у них залежить від остаточного положення голови; і наостанок пристібають ремінь безпеки ({p:2.3}).","ru":"Сначала настраивают сиденье — от него зависит положение тела и глаз; затем рулевую колонку под руки; затем зеркала, потому что обзор в них зависит от окончательного положения головы; и напоследок пристёгивают ремень безопасности ({p:2.3})."},"ref":["2.3"]},{"id":"h35-14","t":"h35","num":"35.14","q":{"uk":"Де Ви знайдете дані про допустиму масу причепа, обладнаного гальмами, для Вашого легкового автомобіля?","ru":"Где вы найдёте данные о допустимой массе прицепа, оборудованного тормозами, для вашего легкового автомобиля?"},"a":[{"uk":"У Правилах дорожнього руху.","ru":"В Правилах дорожного движения.","w":{"uk":"Правила встановлюють загальні вимоги до буксирування й автопоїздів, але не технічні параметри кожної моделі автомобіля.","ru":"Правила устанавливают общие требования к буксировке и автопоездам, но не технические параметры каждой модели автомобиля."}},{"uk":"У страховому полісі.","ru":"В страховом полисе.","w":{"uk":"Страховий поліс засвідчує страхування цивільно-правової відповідальності й не містить технічних характеристик автомобіля.","ru":"Страховой полис удостоверяет страхование гражданско-правовой ответственности и не содержит технических характеристик автомобиля."}},{"uk":"В технічному паспорті.","ru":"В техническом паспорте."}],"c":2,"e":{"uk":"Допустима маса причепа (з гальмами й без них) — технічна характеристика конкретного автомобіля, яку встановлює виробник; її вказують у реєстраційному документі (техпаспорті) та в інструкції з експлуатації.","ru":"Допустимая масса прицепа (с тормозами и без них) — техническая характеристика конкретного автомобиля, которую устанавливает производитель; её указывают в регистрационном документе (техпаспорте) и в инструкции по эксплуатации."}},{"id":"h35-15","t":"h35","num":"35.15","q":{"uk":"При проїзді через тунель ви наближаєтеся до кінця затору. Як Вам вести себе?","ru":"При проезде через тоннель вы приближаетесь к концу затора. Как вам себя вести?"},"a":[{"uk":"Розвернути транспортний засіб і залишити тунель.","ru":"Развернуть транспортное средство и покинуть тоннель.","w":{"uk":"Розворот у тунелі заборонений ({p:10.7}) і дуже небезпечний у тісному просторі серед інших автомобілів.","ru":"Разворот в тоннеле запрещён ({p:10.7}) и очень опасен в тесном пространстве среди других автомобилей."}},{"uk":"В кінці затору вимкнути двигун і залишити транспортний засіб.","ru":"В конце затора выключить двигатель и покинуть транспортное средство.","w":{"uk":"Покинутий автомобіль заблокує рух, коли затор рушить; залишати його слід лише в разі пожежі чи іншої надзвичайної ситуації.","ru":"Брошенный автомобиль заблокирует движение, когда затор тронется; покидать его следует только при пожаре или иной чрезвычайной ситуации."}},{"uk":"Включити аварійну світлову сигналізацію.","ru":"Включить аварийную световую сигнализацию."},{"uk":"Всі відповіді вірні.","ru":"Все ответы верны.","w":{"uk":"Правильна лише відповідь 3: розворот у тунелі й залишення автомобіля в заторі неприпустимі.","ru":"Верен только ответ 3: разворот в тоннеле и оставление автомобиля в заторе недопустимы."}}],"c":2,"e":{"uk":"Аварійна сигналізація — попереджувальний сигнал ({p:9.1}): вона показує водіям позаду, що попереду нерухомий затор. У тунелі з обмеженою оглядовістю й без можливості об'їзду це запобігає наїздам ззаду.","ru":"Аварийная сигнализация — предупреждающий сигнал ({p:9.1}): она показывает водителям сзади, что впереди неподвижный затор. В тоннеле с ограниченной обзорностью и без возможности объезда это предотвращает наезды сзади."},"ref":["9.1"]},{"id":"h35-16","t":"h35","num":"35.16","q":{"uk":"Ви хочете обігнати велосипедистів. Що Ви повинні врахувати при оцінці бокового інтервалу?","ru":"Вы хотите обогнать велосипедистов. Что вы должны учесть при оценке бокового интервала?"},"a":[{"uk":"Бокова відстань в 1,0 м є завжди достатньою.","ru":"Боковое расстояние в 1,0 м всегда является достаточным.","w":{"uk":"Фіксованого «завжди достатнього» інтервалу немає: на великій швидкості чи коли велосипедист хитається, 1 м може виявитися замало.","ru":"Фиксированного «всегда достаточного» интервала нет: на большой скорости или когда велосипедист виляет, 1 м может оказаться мало."}},{"uk":"Поведінка велосипедистів.","ru":"Поведение велосипедистов.","w":{"uk":"Поведінку велосипедистів враховувати треба, але інтервал залежить і від власної швидкості.","ru":"Поведение велосипедистов учитывать нужно, но интервал зависит и от собственной скорости."}},{"uk":"Швидкість свого транспортного засобу.","ru":"Скорость своего транспортного средства.","w":{"uk":"Власну швидкість враховувати треба, але не менш важлива й поведінка велосипедистів.","ru":"Собственную скорость учитывать нужно, но не менее важно и поведение велосипедистов."}},{"uk":"Відповіді 2 і 3.","ru":"Ответы 2 и 3."}],"c":3,"e":{"uk":"Безпечний інтервал залежить від швидкості та дорожньої обстановки ({p:13.1}, {p:13.3}). Велосипедист може раптово відхилитися, об'їжджаючи вибоїну, чи похитнутися від потоку повітря, а що вища швидкість обгону, то сильніший цей потік і менше часу на реакцію — тому враховують і поведінку велосипедистів, і власну швидкість.","ru":"Безопасный интервал зависит от скорости и дорожной обстановки ({p:13.1}, {p:13.3}). Велосипедист может внезапно отклониться, объезжая выбоину, или покачнуться от потока воздуха, а чем выше скорость обгона, тем сильнее этот поток и меньше времени на реакцию — поэтому учитывают и поведение велосипедистов, и собственную скорость."},"ref":["13.1","13.3"]},{"id":"h35-17","t":"h35","num":"35.17","q":{"uk":"Ви хочете перетнути головну дорогу. Видимість в обох напрямках сильно обмежена через припарковані транспортні засоби. Як Ви будете діяти?","ru":"Вы хотите пересечь главную дорогу. Видимость в обоих направлениях сильно ограничена из-за припаркованных транспортных средств. Как вы будете действовать?"},"a":[{"uk":"Швидко перетну перехрестя.","ru":"Быстро пересеку перекрёсток.","w":{"uk":"На швидкості ви не встигнете зупинитися, якщо з-за припаркованих автомобілів з'явиться транспорт на головній дорозі, якому ви зобов'язані дати дорогу.","ru":"На скорости вы не успеете остановиться, если из-за припаркованных автомобилей появится транспорт на главной дороге, которому вы обязаны уступить дорогу."}},{"uk":"З особливою обережністю виїду на перехрестя.","ru":"С особой осторожностью выеду на перекрёсток."}],"c":1,"e":{"uk":"Через припарковані автомобілі ні ви не бачите транспорт на головній дорозі, ні його водії не бачать вас, а дати йому дорогу ви зобов'язані ({p:16.11}). Тому виїжджають повільно, поступово відкриваючи собі огляд і будучи готовими негайно зупинитися ({p:10.1}).","ru":"Из-за припаркованных автомобилей ни вы не видите транспорт на главной дороге, ни его водители не видят вас, а уступить ему дорогу вы обязаны ({p:16.11}). Поэтому выезжают медленно, постепенно открывая себе обзор и будучи готовыми немедленно остановиться ({p:10.1})."},"ref":["16.11","10.1"]},{"id":"h35-18","t":"h35","num":"35.18","q":{"uk":"Безпечною дистанцією між легковими автомобілями, які рухаються зі швидкістю 50 км на годину на сухому асфальті, можна вважати:","ru":"Безопасной дистанцией между легковыми автомобилями, движущимися со скоростью 50 км в час по сухому асфальту, можно считать:"},"a":[{"uk":"2 метри.","ru":"2 метра.","w":{"uk":"Два метри на 50 км/год автомобіль проїжджає менш ніж за 0,2 с — водій навіть не встигне зреагувати на гальмування автомобіля попереду.","ru":"Два метра на 50 км/ч автомобиль проезжает менее чем за 0,2 с — водитель даже не успеет среагировать на торможение впереди идущего автомобиля."}},{"uk":"Довжина легкового автомобіля.","ru":"Длину легкового автомобиля.","w":{"uk":"Довжину автомобіля (4–5 м) на 50 км/год проїжджають приблизно за третину секунди — це набагато менше за час реакції водія.","ru":"Длину автомобиля (4–5 м) на 50 км/ч проезжают примерно за треть секунды — это намного меньше времени реакции водителя."}},{"uk":"Не менше 25 метрів або 2 секунди.","ru":"Не менее 25 метров или 2 секунды."}],"c":2,"e":{"uk":"На швидкості 50 км/год автомобіль проїжджає майже 14 м за секунду, тобто за дві секунди — близько 28 м. Цього вистачає на реакцію водія й гальмування, тому на сухому асфальті дистанцію не менше 25 м (2 с) вважають безпечною ({p:13.1}).","ru":"На скорости 50 км/ч автомобиль проезжает почти 14 м в секунду, то есть за две секунды — около 28 м. Этого хватает на реакцию водителя и торможение, поэтому на сухом асфальте дистанцию не менее 25 м (2 с) считают безопасной ({p:13.1})."},"ref":["13.1"]},{"id":"h35-19","t":"h35","num":"35.19","q":{"uk":"Як сприймається водієм швидкість його автомобіля у випадку тривалого руху рівнинною дорогою з великою швидкістю?","ru":"Как воспринимается водителем скорость его автомобиля при длительном движении по равнинной дороге с большой скоростью?"},"a":[{"uk":"Здається менше, ніж насправді.","ru":"Кажется меньше, чем на самом деле."},{"uk":"Здається більшою, ніж насправді.","ru":"Кажется больше, чем на самом деле.","w":{"uk":"Ефект протилежний: звикання до великої швидкості змушує її недооцінювати, а не переоцінювати.","ru":"Эффект обратный: привыкание к большой скорости заставляет её недооценивать, а не переоценивать."}},{"uk":"Сприйняття швидкості не змінюється.","ru":"Восприятие скорости не меняется.","w":{"uk":"Сприйняття змінюється: мозок пристосовується до тривалої швидкості, і вона починає здаватися меншою.","ru":"Восприятие меняется: мозг приспосабливается к длительной скорости, и она начинает казаться меньше."}}],"c":0,"e":{"uk":"Під час тривалого руху з великою швидкістю водій звикає до неї: одноманітна рівна дорога створює враження, що автомобіль їде повільніше, ніж насправді. Тому варто частіше поглядати на спідометр, особливо після з'їзду із заміської траси.","ru":"При длительном движении с большой скоростью водитель привыкает к ней: однообразная ровная дорога создаёт впечатление, что автомобиль едет медленнее, чем на самом деле. Поэтому стоит чаще поглядывать на спидометр, особенно после съезда с загородной трассы."}},{"id":"h35-20","t":"h35","num":"35.20","q":{"uk":"Під час руху на якому автомобілі збільшення швидкості може сприяти усуненню занесення задньої осі?","ru":"При движении на каком автомобиле увеличение скорости может способствовать устранению заноса задней оси?"},"a":[{"uk":"На передньопривідному.","ru":"На переднеприводном."},{"uk":"На задньопривідному.","ru":"На заднеприводном.","w":{"uk":"На задньопривідному автомобілі газ збільшує тягове зусилля на задніх колесах, які й так ковзають, — занесення посилиться.","ru":"На заднеприводном автомобиле газ увеличивает тяговое усилие на задних колёсах, которые и так скользят, — занос усилится."}}],"c":0,"e":{"uk":"На передньопривідному автомобілі плавне додавання газу змушує ведучі передні колеса «тягнути» машину вперед і вирівнювати її, а задні колеса вільно котяться й відновлюють зчеплення. На задньопривідному додавання газу, навпаки, ще сильніше зриває задні ведучі колеса в ковзання.","ru":"На переднеприводном автомобиле плавное добавление газа заставляет ведущие передние колёса «тянуть» машину вперёд и выравнивать её, а задние колёса свободно катятся и восстанавливают сцепление. На заднеприводном добавление газа, наоборот, ещё сильнее срывает задние ведущие колёса в скольжение."}},{"id":"h35-21","t":"h35","num":"35.21","q":{"uk":"Що має зробити водій, щоб швидко відновити ефективність гальм після проїзду через водну перешкоду?","ru":"Что должен сделать водитель, чтобы быстро восстановить эффективность тормозов после проезда через водную преграду?"},"a":[{"uk":"Продовжити рух, трохи натягнувши важіль ручного гальма.","ru":"Продолжить движение, немного натянув рычаг ручного тормоза.","w":{"uk":"Стоянкове гальмо зазвичай діє лише на задні колеса, тож передні гальмівні механізми лишаються мокрими, а рух із затягнутим ручним гальмом перегріває й зношує колодки.","ru":"Стояночный тормоз обычно действует только на задние колёса, поэтому передние тормозные механизмы остаются мокрыми, а движение с затянутым ручным тормозом перегревает и изнашивает колодки."}},{"uk":"Продовжити рух і просушити гальмівні колодки багаторазовими нетривалими натисканнями на педаль гальма.","ru":"Продолжить движение и просушить тормозные колодки многократными кратковременными нажатиями на педаль тормоза."},{"uk":"Продовжити рух із малою швидкістю без пригальмовування.","ru":"Продолжить движение с малой скоростью без притормаживания.","w":{"uk":"Без пригальмовування колодки сохнуть довго, і весь цей час гальма працюватимуть гірше, ніж зазвичай.","ru":"Без притормаживания колодки сохнут долго, и всё это время тормоза будут работать хуже обычного."}}],"c":1,"e":{"uk":"Мокрі колодки мають знижене тертя, тому гальма діють слабше. Кілька коротких натискань на педаль на ходу нагрівають колодки й диски (барабани) та випаровують воду — ефективність гальм швидко відновлюється.","ru":"Мокрые колодки имеют пониженное трение, поэтому тормоза действуют слабее. Несколько коротких нажатий на педаль на ходу нагревают колодки и диски (барабаны) и испаряют воду — эффективность тормозов быстро восстанавливается."}},{"id":"h35-22","t":"h35","num":"35.22","q":{"uk":"Під час гальмування двигуном на крутому спуску водій має вибирати передачу, виходячи з умов:","ru":"При торможении двигателем на крутом спуске водитель должен выбирать передачу, исходя из условия:"},"a":[{"uk":"Чим крутіше спуск, тим вище передача.","ru":"Чем круче спуск, тем выше передача.","w":{"uk":"На вищій передачі гальмування двигуном слабке, і на крутому спуску автомобіль розганятиметься, змушуючи постійно гальмувати робочими гальмами.","ru":"На высокой передаче торможение двигателем слабое, и на крутом спуске автомобиль будет разгоняться, вынуждая постоянно тормозить рабочими тормозами."}},{"uk":"Чим крутіше спуск, тим нижче передача.","ru":"Чем круче спуск, тем ниже передача."},{"uk":"Вибір передачі не залежить від крутизни спуску.","ru":"Выбор передачи не зависит от крутизны спуска.","w":{"uk":"Що крутіший спуск, то більша сила, яка розганяє автомобіль, — і то нижча передача потрібна, щоб її стримати.","ru":"Чем круче спуск, тем больше сила, разгоняющая автомобиль, — и тем ниже передача нужна, чтобы её сдержать."}}],"c":1,"e":{"uk":"Що нижча передача, то сильніше двигун опирається обертанню коліс і то ефективніше гальмування двигуном. На крутому спуску сила тяжіння розганяє автомобіль сильніше, тому потрібна нижча передача.","ru":"Чем ниже передача, тем сильнее двигатель сопротивляется вращению колёс и тем эффективнее торможение двигателем. На крутом спуске сила тяжести разгоняет автомобиль сильнее, поэтому нужна более низкая передача."}},{"id":"h35-23","t":"h35","num":"35.23","q":{"uk":"Як має діяти водій у разі втрати зчеплення коліс з дорогою через утворення «водяного клина»?","ru":"Как должен действовать водитель в случае потери сцепления колёс с дорогой из-за образования «водяного клина»?"},"a":[{"uk":"Збільшити швидкість.","ru":"Увеличить скорость.","w":{"uk":"Що вища швидкість, то товщий водяний клин: шини повністю відриваються від дороги, і автомобіль стає некерованим.","ru":"Чем выше скорость, тем толще водяной клин: шины полностью отрываются от дороги, и автомобиль становится неуправляемым."}},{"uk":"Знизити швидкість різким натисканням на педаль гальма.","ru":"Снизить скорость резким нажатием на педаль тормоза.","w":{"uk":"Колеса без зчеплення від різкого гальмування заблокуються, і щойно зчеплення відновиться, автомобіль може піти в занос.","ru":"Колёса без сцепления от резкого торможения заблокируются, и как только сцепление восстановится, автомобиль может уйти в занос."}},{"uk":"Знизити швидкість, застосовуючи гальмування двигуном.","ru":"Снизить скорость, применяя торможение двигателем."}],"c":2,"e":{"uk":"Під час аквапланування шини «спливають» на водяному клині й втрачають контакт з дорогою. Треба плавно відпустити педаль газу й зменшити швидкість гальмуванням двигуном, тримаючи кермо прямо: зі зниженням швидкості шини продавлюють воду, і зчеплення відновлюється.","ru":"При аквапланировании шины «всплывают» на водяном клине и теряют контакт с дорогой. Нужно плавно отпустить педаль газа и снизить скорость торможением двигателем, держа руль прямо: со снижением скорости шины продавливают воду, и сцепление восстанавливается."}},{"id":"h35-24","t":"h35","num":"35.24","q":{"uk":"Чим небезпечне тривале гальмування з вимкненим зчепленням (передачею) на крутому спуску?","ru":"Чем опасно длительное торможение с выключенным сцеплением (передачей) на крутом спуске?"},"a":[{"uk":"Значно збільшується знос протектора шин.","ru":"Значительно увеличивается износ протектора шин.","w":{"uk":"Під час гальмування без блокування коліс шини зношуються незначно — головна небезпека не в цьому.","ru":"При торможении без блокировки колёс шины изнашиваются незначительно — главная опасность не в этом."}},{"uk":"Підвищується знос деталей гальмівних механізмів.","ru":"Повышается износ деталей тормозных механизмов.","w":{"uk":"Знос гальм справді зростає, але найнебезпечніше інше — перегрів і втрата ефективності гальмування просто на спуску.","ru":"Износ тормозов действительно растёт, но опаснее другое — перегрев и потеря эффективности торможения прямо на спуске."}},{"uk":"Перегріваються гальмівні механізми і зменшується ефективність гальмування.","ru":"Перегреваются тормозные механизмы и уменьшается эффективность торможения."}],"c":2,"e":{"uk":"Без гальмування двигуном уся енергія спуску перетворюється на тепло в гальмах. Колодки й диски перегріваються, тертя між ними падає, гальмівна рідина може закипіти — гальма слабшають аж до повної відмови просто на спуску.","ru":"Без торможения двигателем вся энергия спуска превращается в тепло в тормозах. Колодки и диски перегреваются, трение между ними падает, тормозная жидкость может закипеть — тормоза слабеют вплоть до полного отказа прямо на спуске."}},{"id":"h35-25","t":"h35","num":"35.25","q":{"uk":"Під час руху в умовах туману відстань до предметів видається:","ru":"При движении в условиях тумана расстояние до предметов кажется:"},"a":[{"uk":"Більшою, ніж насправді.","ru":"Больше, чем на самом деле."},{"uk":"Меншою, ніж насправді.","ru":"Меньше, чем на самом деле.","w":{"uk":"Ефект протилежний: розмиті контури в тумані «віддаляють» предмети, а не наближають їх.","ru":"Эффект обратный: размытые контуры в тумане «отдаляют» предметы, а не приближают их."}},{"uk":"Такою, що відповідає дійсності.","ru":"Соответствующим действительности.","w":{"uk":"Туман спотворює сприйняття відстані: через нечіткі обриси вона здається більшою.","ru":"Туман искажает восприятие расстояния: из-за нечётких очертаний оно кажется больше."}}],"c":0,"e":{"uk":"У тумані предмети виглядають розмитими й тьмяними, а мозок сприймає нечіткі обриси як віддалені. Тому відстань здається більшою, ніж насправді, і водій ризикує запізнитися з гальмуванням.","ru":"В тумане предметы выглядят размытыми и тусклыми, а мозг воспринимает нечёткие очертания как удалённые. Поэтому расстояние кажется больше, чем на самом деле, и водитель рискует опоздать с торможением."}},{"id":"h35-26","t":"h35","num":"35.26","q":{"uk":"Що мається на увазі під зупинним шляхом?","ru":"Что подразумевается под остановочным путём?"},"a":[{"uk":"Відстань, пройдена транспортним засобом з моменту виявлення водієм небезпеки до повної зупинки.","ru":"Расстояние, пройденное транспортным средством с момента обнаружения водителем опасности до полной остановки."},{"uk":"Відстань, пройдена транспортним засобом з моменту початку спрацьовування гальмівного приводу до повної зупинки.","ru":"Расстояние, пройденное транспортным средством с момента начала срабатывания тормозного привода до полной остановки.","w":{"uk":"Тут не враховано відстань, пройдену за час реакції водія, а вона становить чималу частину зупинного шляху.","ru":"Здесь не учтено расстояние, пройденное за время реакции водителя, а оно составляет немалую часть остановочного пути."}},{"uk":"Відстань, що відповідає гальмівному шляху, визначеному технічною характеристикою даного транспортного засобу.","ru":"Расстояние, соответствующее тормозному пути, определённому технической характеристикой данного транспортного средства.","w":{"uk":"Гальмовий шлях ({p:1.10}) — лише частина зупинного, до того ж він залежить не тільки від автомобіля, а й від покриття, шин і завантаження.","ru":"Тормозной путь ({p:1.10}) — лишь часть остановочного, к тому же он зависит не только от автомобиля, но и от покрытия, шин и загрузки."}}],"c":0,"e":{"uk":"Зупинний шлях — це вся відстань від моменту, коли водій помітив небезпеку, до повної зупинки: шлях за час реакції водія, за час спрацювання гальмівного приводу і власне гальмовий шлях.","ru":"Остановочный путь — это всё расстояние от момента, когда водитель заметил опасность, до полной остановки: путь за время реакции водителя, за время срабатывания тормозного привода и собственно тормозной путь."}},{"id":"h35-27","t":"h35","num":"35.27","q":{"uk":"Якими критеріями мають керуватися водії, обираючи швидкість у відповідності до видимості за напрямком руху?","ru":"Какими критериями должны руководствоваться водители, выбирая скорость в соответствии с видимостью в направлении движения?"},"a":[{"uk":"Швидкість руху і видимість дороги між собою не пов’язані.","ru":"Скорость движения и видимость дороги между собой не связаны.","w":{"uk":"Видимість у напрямку руху — один із головних чинників, які водій ураховує, обираючи безпечну швидкість ({p:12.1}).","ru":"Видимость в направлении движения — один из главных факторов, которые водитель учитывает, выбирая безопасную скорость ({p:12.1})."}},{"uk":"У населеному пункті, при виборі швидкості руху, на видимість можна не зважати.","ru":"В населённом пункте при выборе скорости движения на видимость можно не обращать внимания.","w":{"uk":"Вимога {p:12.2} діє і в населених пунктах; дозволені там 50 км/год ({p:12.4}) — лише верхня межа, а не безпечна швидкість за будь-якої видимості.","ru":"Требование {p:12.2} действует и в населённых пунктах; разрешённые там 50 км/ч ({p:12.4}) — лишь верхний предел, а не безопасная скорость при любой видимости."}},{"uk":"Чим гірша видимість, тим меншою має бути швидкість руху.","ru":"Чем хуже видимость, тем меньше должна быть скорость движения."}],"c":2,"e":{"uk":"Водій має встигнути зупинитися в межах видимої ділянки дороги ({p:12.1}, {p:12.2}), тож що гірша видимість, то коротшим має бути зупинний шлях, а отже — нижчою швидкість.","ru":"Водитель должен успеть остановиться в пределах видимого участка дороги ({p:12.1}, {p:12.2}), поэтому чем хуже видимость, тем короче должен быть остановочный путь, а значит — ниже скорость."},"ref":["12.1","12.2"]},{"id":"h35-28","t":"h35","num":"35.28","q":{"uk":"У якому випадку легковий автомобіль більш стійкий проти перекидання на повороті?","ru":"В каком случае легковой автомобиль более устойчив против опрокидывания на повороте?"},"a":[{"uk":"Без вантажу і пасажирів.","ru":"Без груза и пассажиров."},{"uk":"З пасажирами, але без вантажу.","ru":"С пассажирами, но без груза.","w":{"uk":"Пасажири сидять вище за центр ваги автомобіля, тож піднімають його й зменшують стійкість.","ru":"Пассажиры сидят выше центра тяжести автомобиля, поэтому поднимают его и уменьшают устойчивость."}},{"uk":"Без пасажирів, але з вантажем на верхньому багажнику.","ru":"Без пассажиров, но с грузом на верхнем багажнике.","w":{"uk":"Вантаж на даху найсильніше піднімає центр ваги — це найменш стійкий варіант.","ru":"Груз на крыше сильнее всего поднимает центр тяжести — это наименее устойчивый вариант."}}],"c":0,"e":{"uk":"Стійкість проти перекидання залежить від висоти центру ваги: що він нижчий, то стійкіший автомобіль. Пасажири й особливо вантаж на даху піднімають центр ваги, тому найстійкіший порожній автомобіль.","ru":"Устойчивость против опрокидывания зависит от высоты центра тяжести: чем он ниже, тем устойчивее автомобиль. Пассажиры и особенно груз на крыше поднимают центр тяжести, поэтому самый устойчивый — пустой автомобиль."}},{"id":"h35-29","t":"h35","num":"35.29","q":{"uk":"Що слід зробити водієві, щоб запобігти виникненню заносу під час проїзду крутого повороту?","ru":"Что следует сделать водителю, чтобы предотвратить возникновение заноса при проезде крутого поворота?"},"a":[{"uk":"Перед поворотом знизити швидкість і натиснути на педаль зчеплення, щоб дати можливість автомобілю рухатися накатом на повороті.","ru":"Перед поворотом снизить скорость и нажать на педаль сцепления, чтобы дать возможность автомобилю двигаться накатом на повороте.","w":{"uk":"Накатом із вимкненим зчепленням водій втрачає змогу гальмувати двигуном і плавно керувати тягою, тож автомобіль гірше тримає траєкторію.","ru":"Накатом с выключенным сцеплением водитель теряет возможность тормозить двигателем и плавно управлять тягой, поэтому автомобиль хуже держит траекторию."}},{"uk":"Перед поворотом знизити швидкість, за необхідності ввімкнути знижену передачу, а під час проїзду повороту не збільшувати різко швидкість і не гальмувати.","ru":"Перед поворотом снизить скорость, при необходимости включить пониженную передачу, а при проезде поворота не увеличивать резко скорость и не тормозить."},{"uk":"Допускається будь-яка з наведених дій.","ru":"Допускается любое из приведённых действий.","w":{"uk":"Рух накатом із вимкненим зчепленням у повороті небезпечний, тому придатний лише варіант 2.","ru":"Движение накатом с выключенным сцеплением в повороте опасно, поэтому годится только вариант 2."}}],"c":1,"e":{"uk":"Швидкість знижують до повороту, поки колеса ще йдуть прямо. У самому повороті зчеплення шин майже повністю витрачається на утримання траєкторії, тож різкий газ чи гальмування можуть зірвати колеса в занос; знижена передача дає змогу пройти поворот на рівній тязі.","ru":"Скорость снижают до поворота, пока колёса ещё идут прямо. В самом повороте сцепление шин почти полностью расходуется на удержание траектории, поэтому резкий газ или торможение могут сорвать колёса в занос; пониженная передача позволяет пройти поворот на ровной тяге."}},{"id":"h35-30","t":"h35","num":"35.30","q":{"uk":"У який момент слід поступово відпускати стоянкове гальмо, починаючи рух на підйомі?","ru":"В какой момент следует постепенно отпускать стояночный тормоз, начиная движение на подъёме?"},"a":[{"uk":"До початку руху.","ru":"До начала движения.","w":{"uk":"Якщо відпустити гальмо, поки двигун ще не тягне, автомобіль відкотиться назад і може вдарити транспортний засіб позаду.","ru":"Если отпустить тормоз, пока двигатель ещё не тянет, автомобиль откатится назад и может ударить транспортное средство сзади."}},{"uk":"Після початку руху.","ru":"После начала движения.","w":{"uk":"Рушати із затягнутим стоянковим гальмом — це перевантажувати двигун і зчеплення та перегрівати колодки; двигун може заглохнути.","ru":"Трогаться с затянутым стояночным тормозом — значит перегружать двигатель и сцепление и перегревать колодки; двигатель может заглохнуть."}},{"uk":"Одночасно з початком руху.","ru":"Одновременно с началом движения."}],"c":2,"e":{"uk":"Стоянкове гальмо відпускають саме тоді, коли зчеплення «схопило» і двигун уже тягне автомобіль угору: так він не відкотиться назад і не рушить із затягнутим гальмом.","ru":"Стояночный тормоз отпускают именно тогда, когда сцепление «схватило» и двигатель уже тянет автомобиль вверх: так он не откатится назад и не тронется с затянутым тормозом."}},{"id":"h35-31","t":"h35","num":"35.31","q":{"uk":"Під час руху якою ділянкою дороги дія сильного бокового вітру найбільш небезпечна?","ru":"При движении по какому участку дороги действие сильного бокового ветра наиболее опасно?"},"a":[{"uk":"Відкритою.","ru":"По открытому.","w":{"uk":"На відкритій ділянці вітер дме постійно, і водій уже вносить поправку кермом; найнебезпечніший саме несподіваний порив.","ru":"На открытом участке ветер дует постоянно, и водитель уже делает поправку рулём; опаснее всего именно неожиданный порыв."}},{"uk":"Закритою деревами.","ru":"Закрытому деревьями.","w":{"uk":"Дерева захищають від вітру — небезпека виникає саме тоді, коли цей захист раптово закінчується.","ru":"Деревья защищают от ветра — опасность возникает именно тогда, когда эта защита внезапно заканчивается."}},{"uk":"Під час виїзду з закритої ділянки на відкриту.","ru":"При выезде с закрытого участка на открытый."}],"c":2,"e":{"uk":"Найнебезпечніший **раптовий** порив: на закритій ділянці вітер майже не відчувається, а на виїзді на відкриту автомобіль несподівано отримує сильний бічний поштовх і може зміститися на сусідню смугу чи узбіччя.","ru":"Опаснее всего **внезапный** порыв: на закрытом участке ветер почти не ощущается, а при выезде на открытый автомобиль неожиданно получает сильный боковой толчок и может сместиться на соседнюю полосу или обочину."}},{"id":"h35-32","t":"h35","num":"35.32","q":{"uk":"Чи залежить вибір бокового інтервалу від швидкості руху?","ru":"Зависит ли выбор бокового интервала от скорости движения?"},"a":[{"uk":"Вибір бокового інтервалу від швидкості руху не залежить.","ru":"Выбор бокового интервала от скорости движения не зависит.","w":{"uk":"{p:13.1} прямо вимагає обирати безпечний інтервал з урахуванням швидкості руху.","ru":"{p:13.1} прямо требует выбирать безопасный интервал с учётом скорости движения."}},{"uk":"Збільшуючи швидкість руху, бічний інтервал необхідно збільшити.","ru":"Увеличивая скорость движения, боковой интервал необходимо увеличить."}],"c":1,"e":{"uk":"Безпечний інтервал водій обирає залежно від швидкості ({p:13.1}): на більшій швидкості автомобіль сильніше відхиляється від прямої через нерівності й вітер, потоки повітря між транспортними засобами сильніші, а на виправлення помилки лишається менше часу.","ru":"Безопасный интервал водитель выбирает в зависимости от скорости ({p:13.1}): на большей скорости автомобиль сильнее отклоняется от прямой из-за неровностей и ветра, потоки воздуха между транспортными средствами сильнее, а на исправление ошибки остаётся меньше времени."},"ref":["13.1"]},{"id":"h35-33","t":"h35","num":"35.33","q":{"uk":"Як змінюється поле зору водія зі збільшенням швидкості руху?","ru":"Как изменяется поле зрения водителя с увеличением скорости движения?"},"a":[{"uk":"Не змінюється.","ru":"Не изменяется.","w":{"uk":"Поле зору залежить від швидкості: що вона вища, то вужча зона, яку водій чітко сприймає.","ru":"Поле зрения зависит от скорости: чем она выше, тем уже зона, которую водитель чётко воспринимает."}},{"uk":"Розширюється.","ru":"Расширяется.","w":{"uk":"Ефект протилежний: на швидкості погляд зосереджується вдалині, а бокове сприйняття погіршується.","ru":"Эффект обратный: на скорости взгляд сосредоточивается вдали, а боковое восприятие ухудшается."}},{"uk":"Звужується.","ru":"Сужается."}],"c":2,"e":{"uk":"Зі зростанням швидкості погляд водія переміщується вдалину, а увага зосереджується на дорозі попереду — виникає так званий «тунельний зір». Об'єкти збоку (пішоходів, автомобілі з другорядних доріг) водій помічає гірше й пізніше.","ru":"С ростом скорости взгляд водителя перемещается вдаль, а внимание сосредоточивается на дороге впереди — возникает так называемое «туннельное зрение». Объекты сбоку (пешеходов, автомобили со второстепенных дорог) водитель замечает хуже и позже."}},{"id":"h35-34","t":"h35","num":"35.34","q":{"uk":"Який стиль водіння забезпечить найменшу витрату палива?","ru":"Какой стиль вождения обеспечит наименьший расход топлива?"},"a":[{"uk":"Часте і різке прискорення при плавному уповільненні.","ru":"Частое и резкое ускорение при плавном замедлении.","w":{"uk":"Часті різкі прискорення — головна причина перевитрати пального, і плавне уповільнення цього не компенсує.","ru":"Частые резкие ускорения — главная причина перерасхода топлива, и плавное замедление этого не компенсирует."}},{"uk":"Плавне прискорення при різкому уповільненні.","ru":"Плавное ускорение при резком замедлении.","w":{"uk":"Різке гальмування марно «спалює» в гальмах енергію, на яку вже витрачено пальне; завчасне плавне уповільнення дало б змогу проїхати цю відстань майже без витрати пального.","ru":"Резкое торможение впустую «сжигает» в тормозах энергию, на которую уже потрачено топливо; заблаговременное плавное замедление позволило бы проехать это расстояние почти без расхода топлива."}},{"uk":"Плавне прискорення при плавному уповільненні.","ru":"Плавное ускорение при плавном замедлении."}],"c":2,"e":{"uk":"Різкий розгін потребує високих обертів і збагаченої суміші, а різке гальмування марно перетворює набрану швидкість на тепло в гальмах. Плавний розгін і завчасне плавне уповільнення з гальмуванням двигуном дають найменшу витрату пального.","ru":"Резкий разгон требует высоких оборотов и обогащённой смеси, а резкое торможение впустую превращает набранную скорость в тепло в тормозах. Плавный разгон и заблаговременное плавное замедление с торможением двигателем дают наименьший расход топлива."}},{"id":"h35-35","t":"h35","num":"35.35","q":{"uk":"Як змінюється довжина гальмівного шляху легкового автомобіля під час руху з причепом, не оснащеним гальмівною системою?","ru":"Как изменяется длина тормозного пути легкового автомобиля при движении с прицепом, не оснащённым тормозной системой?"},"a":[{"uk":"Зменшується, оскільки причіп чинить додатковий опір руху.","ru":"Уменьшается, поскольку прицеп оказывает дополнительное сопротивление движению.","w":{"uk":"Опір коченню причепа мізерний порівняно з його інерцією, яка під час гальмування штовхає автомобіль уперед.","ru":"Сопротивление качению прицепа ничтожно по сравнению с его инерцией, которая при торможении толкает автомобиль вперёд."}},{"uk":"Збільшується.","ru":"Увеличивается."},{"uk":"Не змінюється.","ru":"Не изменяется.","w":{"uk":"Маса, яку треба зупинити, зростає, а гальма лишаються тими самими — тож гальмовий шлях подовжується.","ru":"Масса, которую нужно остановить, растёт, а тормоза остаются теми же — поэтому тормозной путь удлиняется."}}],"c":1,"e":{"uk":"Причіп без гальм збільшує масу, яку треба зупинити, але не додає гальмівного зусилля: за інерцією він штовхає автомобіль уперед, тож гальмовий шлях зростає. Крім того, виникає ризик «складання» автопоїзда.","ru":"Прицеп без тормозов увеличивает массу, которую нужно остановить, но не добавляет тормозного усилия: по инерции он толкает автомобиль вперёд, поэтому тормозной путь растёт. Кроме того, возникает риск «складывания» автопоезда."}},{"id":"h35-36","t":"h35","num":"35.36","q":{"uk":"Як слід вчинити водієві, якщо під час руху сухою дорогою з асфальтобетонним покриттям почав накрапати дощ?","ru":"Как следует поступить водителю, если при движении по сухой дороге с асфальтобетонным покрытием начал накрапывать дождь?"},"a":[{"uk":"Зменшити швидкість і бути особливо обережним.","ru":"Снизить скорость и быть особенно осторожным."},{"uk":"Не змінюючи швидкості, продовжити рух.","ru":"Не меняя скорости, продолжить движение.","w":{"uk":"Зчеплення на щойно намоклому асфальті значно гірше, ніж на сухому, тож колишня швидкість уже не є безпечною.","ru":"Сцепление на только что намокшем асфальте значительно хуже, чем на сухом, поэтому прежняя скорость уже не является безопасной."}},{"uk":"Збільшити швидкість і спробувати проїхати якомога більшу відстань, поки не почався сильний дощ.","ru":"Увеличить скорость и попытаться проехать как можно большее расстояние, пока не начался сильный дождь.","w":{"uk":"Збільшувати швидкість на щойно намоклій, найбільш слизькій дорозі — пряма загроза заносу й ДТП.","ru":"Увеличивать скорость на только что намокшей, самой скользкой дороге — прямая угроза заноса и ДТП."}}],"c":0,"e":{"uk":"Перші краплі дощу змішуються з пилом, гумою й мастилом на асфальті й утворюють слизьку плівку, тож на початку дощу дорога особливо слизька. Тому швидкість зменшують відповідно до нових дорожніх умов ({p:12.1}).","ru":"Первые капли дождя смешиваются с пылью, резиной и маслом на асфальте и образуют скользкую плёнку, поэтому в начале дождя дорога особенно скользкая. Поэтому скорость снижают в соответствии с новыми дорожными условиями ({p:12.1})."},"ref":["12.1"]},{"id":"h35-37","t":"h35","num":"35.37","q":{"uk":"Для припинення занесення, викликаного гальмуванням, водій у першу чергу має:","ru":"Для прекращения заноса, вызванного торможением, водитель в первую очередь должен:"},"a":[{"uk":"Припинити розпочате гальмування.","ru":"Прекратить начатое торможение."},{"uk":"Вимкнути зчеплення.","ru":"Выключить сцепление.","w":{"uk":"Вимкнення зчеплення не усуває причини заносу — колеса лишаються загальмованими й ковзають далі.","ru":"Выключение сцепления не устраняет причину заноса — колёса остаются заторможенными и продолжают скользить."}},{"uk":"Продовжити гальмування, не змінюючи зусилля на педаль гальма.","ru":"Продолжить торможение, не изменяя усилия на педаль тормоза.","w":{"uk":"Поки гальмування триває, колеса ковзають, і занесення лише посилюватиметься.","ru":"Пока торможение продолжается, колёса скользят, и занос будет только усиливаться."}}],"c":0,"e":{"uk":"Занос виник тому, що гальмування заблокувало колеса й вони втратили бокове зчеплення. Щойно гальмування припинено, колеса знову котяться, відновлюють зчеплення, і водій може вирівняти автомобіль кермом.","ru":"Занос возник потому, что торможение заблокировало колёса и они потеряли боковое сцепление. Как только торможение прекращено, колёса снова катятся, восстанавливают сцепление, и водитель может выровнять автомобиль рулём."}},{"id":"h35-38","t":"h35","num":"35.38","q":{"uk":"У темну пору доби та в похмуру погоду швидкість зустрічного автомобіля видається:","ru":"В тёмное время суток и в пасмурную погоду скорость встречного автомобиля кажется:"},"a":[{"uk":"Нижчою, ніж насправді.","ru":"Ниже, чем на самом деле."},{"uk":"Вищою, ніж насправді.","ru":"Выше, чем на самом деле.","w":{"uk":"Ефект протилежний: через нестачу орієнтирів швидкість зустрічного автомобіля недооцінюють, а не переоцінюють.","ru":"Эффект обратный: из-за нехватки ориентиров скорость встречного автомобиля недооценивают, а не переоценивают."}},{"uk":"Сприйняття швидкості не змінюється.","ru":"Восприятие скорости не меняется.","w":{"uk":"За поганого освітлення сприйняття змінюється: швидкість зустрічного автомобіля здається нижчою, ніж насправді.","ru":"При плохом освещении восприятие меняется: скорость встречного автомобиля кажется ниже, чем на самом деле."}}],"c":0,"e":{"uk":"У темряві та в похмуру погоду водій бачить менше орієнтирів — лише фари чи нечіткі обриси, — і оцінити, як швидко наближається зустрічний автомобіль, важче: його швидкість зазвичай недооцінюють. Тому під час обгону чи повороту ліворуч у таких умовах потрібен більший запас відстані.","ru":"В темноте и в пасмурную погоду водитель видит меньше ориентиров — лишь фары или нечёткие очертания, — и оценить, как быстро приближается встречный автомобиль, труднее: его скорость обычно недооценивают. Поэтому при обгоне или повороте налево в таких условиях нужен больший запас расстояния."}},{"id":"h35-39","t":"h35","num":"35.39","q":{"uk":"Гальмовим шляхом вважається:","ru":"Тормозным путём считается:"},"a":[{"uk":"Відстань, що проходить транспортний засіб, з місця, де починаються чітко виражені сліди гальмування до повної зупинки.","ru":"Расстояние, которое проходит транспортное средство с места, где начинаются чётко выраженные следы торможения, до полной остановки.","w":{"uk":"Сліди гальмування з'являються не одразу, а лише після спрацювання гальм і блокування коліс (з АБС їх може й не бути), тож ця відстань коротша за гальмовий шлях.","ru":"Следы торможения появляются не сразу, а лишь после срабатывания тормозов и блокировки колёс (с АБС их может и не быть), поэтому это расстояние короче тормозного пути."}},{"uk":"Відстань, що проходить транспортний засіб під час екстреного гальмування з початку впливу на органи керування гальмовою системою до повної зупинки.","ru":"Расстояние, которое проходит транспортное средство при экстренном торможении с начала воздействия на органы управления тормозной системой до полной остановки."}],"c":1,"e":{"uk":"Саме так гальмовий шлях визначено в {p:1.10}: від початку дії на орган керування гальмовою системою (педаль, рукоятку) до місця зупинки під час екстреного гальмування.","ru":"Именно так тормозной путь определён в {p:1.10}: от начала воздействия на орган управления тормозной системой (педаль, рукоятку) до места остановки при экстренном торможении."},"ref":["1.10"]},{"id":"h35-40","t":"h35","num":"35.40","q":{"uk":"Різке гальмування під час ожеледиці може підвищити ризик потрапляння у ДТП?","ru":"Может ли резкое торможение во время гололёда повысить риск попадания в ДТП?"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"Саме різке гальмування на льоду найчастіше призводить до заносу й втрати керованості.","ru":"Именно резкое торможение на льду чаще всего приводит к заносу и потере управляемости."}}],"c":0,"e":{"uk":"На ожеледиці зчеплення шин з дорогою в кілька разів гірше, ніж на сухому асфальті. Різке гальмування блокує колеса — автомобіль втрачає керованість, іде в занос, а гальмовий шлях зростає; гальмувати слід плавно й завчасно.","ru":"На гололёде сцепление шин с дорогой в несколько раз хуже, чем на сухом асфальте. Резкое торможение блокирует колёса — автомобиль теряет управляемость, уходит в занос, а тормозной путь растёт; тормозить следует плавно и заблаговременно."},"pic":["img/hsc/35-40-1.jpg"]},{"id":"h35-41","t":"h35","num":"35.41","q":{"uk":"Чи потрібно зчистити сніг із даху авто перед початком руху взимку?","ru":"Нужно ли очистить снег с крыши автомобиля перед началом движения зимой?"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"Сніг на даху під час гальмування закриє лобове скло, а на швидкості може злетіти на автомобіль позаду й закрити огляд його водієві.","ru":"Снег на крыше при торможении закроет лобовое стекло, а на скорости может слететь на автомобиль сзади и закрыть обзор его водителю."}}],"c":0,"e":{"uk":"Під час гальмування сніг із даху з'їжджає на лобове скло й закриває огляд, а на ходу зривається на автомобілі позаду. Водій зобов'язаний перед виїздом подбати про стан автомобіля й не створювати загрози безпеці руху ({p:2.3}).","ru":"При торможении снег с крыши сползает на лобовое стекло и закрывает обзор, а на ходу срывается на автомобили сзади. Водитель обязан перед выездом позаботиться о состоянии автомобиля и не создавать угрозы безопасности движения ({p:2.3})."},"ref":["2.3"],"pic":["img/hsc/35-41-1.jpg"]},{"id":"h35-42","t":"h35","num":"35.42","q":{"uk":"Якщо виникла нагальна необхідність здійснити поїздку під час снігопаду, що рекомендовано мати з собою водієві?","ru":"Если возникла насущная необходимость совершить поездку во время снегопада, что рекомендуется иметь с собой водителю?"},"a":[{"uk":"Лопату.","ru":"Лопату.","w":{"uk":"Лопата знадобиться, щоб відкопати автомобіль, але решта перелічених речей у зимовій поїздці теж потрібна.","ru":"Лопата понадобится, чтобы откопать автомобиль, но остальные перечисленные вещи в зимней поездке тоже нужны."}},{"uk":"Теплу ковдру.","ru":"Тёплое одеяло.","w":{"uk":"Тепла ковдра допоможе не замерзнути, але без лопати, щітки й запасу пального можна так само опинитися в скрутному становищі.","ru":"Тёплое одеяло поможет не замёрзнуть, но без лопаты, щётки и запаса топлива можно так же оказаться в затруднительном положении."}},{"uk":"Щітку зі скребком.","ru":"Щётку со скребком.","w":{"uk":"Щітка зі скребком потрібна, щоб очистити скло й фари, але це лише одна з рекомендованих речей.","ru":"Щётка со скребком нужна, чтобы очистить стёкла и фары, но это лишь одна из рекомендуемых вещей."}},{"uk":"Повний бак пального.","ru":"Полный бак топлива.","w":{"uk":"Повний бак дасть змогу довше гріти салон у заторі, але інші перелічені речі теж рекомендовано мати із собою.","ru":"Полный бак позволит дольше греть салон в заторе, но остальные перечисленные вещи тоже рекомендуется иметь с собой."}},{"uk":"Все перераховане вище.","ru":"Всё перечисленное выше."}],"c":4,"e":{"uk":"У снігопад автомобіль може застрягти або надовго стати в заторі: лопата допоможе відкопатися, щітка зі скребком — очистити скло, фари й дах, повний бак дасть змогу довше гріти салон, а ковдра допоможе не замерзнути, якщо двигун доведеться заглушити.","ru":"В снегопад автомобиль может застрять или надолго встать в заторе: лопата поможет откопаться, щётка со скребком — очистить стёкла, фары и крышу, полный бак позволит дольше греть салон, а одеяло поможет не замёрзнуть, если двигатель придётся заглушить."}},{"id":"h35-43","t":"h35","num":"35.43","q":{"uk":"Водіння вночі вимагає від водія більшої зосередженості та концентрації уваги, ніж водіння в денний час?","ru":"Требует ли вождение ночью от водителя большей сосредоточенности и концентрации внимания, чем вождение в дневное время?"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"Обмежена видимість, засліплення й утома роблять нічне водіння складнішим, тож уваги потрібно більше, ніж удень.","ru":"Ограниченная видимость, ослепление и усталость делают ночное вождение сложнее, поэтому внимания нужно больше, чем днём."}}],"c":0,"e":{"uk":"Уночі видимість обмежена зоною світла фар, пішоходів і перешкоди видно пізніше, зустрічні фари засліплюють, а організм схильний до втоми й сонливості. Щоб вчасно помітити небезпеку, водій має бути особливо уважним ({p:2.3}) і обирати швидкість, за якої зупиниться в межах видимості ({p:12.2}).","ru":"Ночью видимость ограничена зоной света фар, пешеходов и препятствия видно позже, встречные фары ослепляют, а организм склонен к усталости и сонливости. Чтобы вовремя заметить опасность, водитель должен быть особенно внимательным ({p:2.3}) и выбирать скорость, при которой остановится в пределах видимости ({p:12.2})."},"ref":["2.3","12.2"]},{"id":"h35-44","t":"h35","num":"35.44","q":{"uk":"Для водіїв із досвідом водіння понад 2 роки максимально допустима доза алкоголю у крові становить 0,3 проміле?","ru":"Для водителей со стажем вождения более 2 лет максимально допустимая доза алкоголя в крови составляет 0,3 промилле?"},"a":[{"uk":"Так.","ru":"Да.","w":{"uk":"Граничний рівень становить 0,2 проміле, а не 0,3, і від водійського стажу він не залежить.","ru":"Предельный уровень составляет 0,2 промилле, а не 0,3, и от водительского стажа он не зависит."}},{"uk":"Ні.","ru":"Нет."}],"c":1,"e":{"uk":"Керувати в стані сп'яніння заборонено ({p:2.9}), а в Україні алкогольним сп'янінням вважається вміст алкоголю в крові понад **0,2** проміле — для всіх водіїв однаково, незалежно від стажу.","ru":"Управлять в состоянии опьянения запрещено ({p:2.9}), а в Украине алкогольным опьянением считается содержание алкоголя в крови более **0,2** промилле — для всех водителей одинаково, независимо от стажа."},"ref":["2.9"]},{"id":"h35-45","t":"h35","num":"35.45","q":{"uk":"Чи безпечно рухатись водієві автомобіля в даному випадку?","ru":"Безопасно ли двигаться водителю автомобиля в данном случае?"},"a":[{"uk":"Так.","ru":"Да.","w":{"uk":"Неочищений автомобіль небезпечний: сніг може раптово закрити огляд і самому водієві, і водіям позаду, на чиє скло він злетить.","ru":"Неочищенный автомобиль опасен: снег может внезапно закрыть обзор и самому водителю, и водителям сзади, на чьё стекло он слетит."}},{"uk":"Ні.","ru":"Нет."}],"c":1,"e":{"uk":"На даху й капоті автомобіля лежить шар снігу: під час гальмування він з'їде на лобове скло й закриє огляд, а на ходу злітатиме на автомобілі позаду. Перед виїздом автомобіль треба повністю очистити від снігу ({p:2.3}).","ru":"На крыше и капоте автомобиля лежит слой снега: при торможении он сползёт на лобовое стекло и закроет обзор, а на ходу будет слетать на автомобили сзади. Перед выездом автомобиль нужно полностью очистить от снега ({p:2.3})."},"ref":["2.3"],"pic":["img/hsc/35-45-1.jpg"]},{"id":"h35-46","t":"h35","num":"35.46","q":{"uk":"Водіння вночі є безпечнішим, ніж водіння в денний час, оскільки на дорозі відносно невелика кількість автомобілів?","ru":"Вождение ночью безопаснее, чем вождение в дневное время, поскольку на дороге относительно небольшое количество автомобилей?"},"a":[{"uk":"Так.","ru":"Да.","w":{"uk":"Порожня дорога вночі оманлива: через погану видимість, засліплення й утому ризик ДТП, особливо тяжкої, вищий, ніж удень.","ru":"Пустая дорога ночью обманчива: из-за плохой видимости, ослепления и усталости риск ДТП, особенно тяжёлого, выше, чем днём."}},{"uk":"Ні.","ru":"Нет."}],"c":1,"e":{"uk":"Менша кількість автомобілів не компенсує нічних ризиків: видимість обмежена світлом фар, пішоходів у темному одязі видно надто пізно, зустрічні фари засліплюють, водій швидше втомлюється, а дехто на порожній дорозі перевищує швидкість. Тому вночі швидкість обирають так, щоб зупинитися в межах видимості ({p:12.2}).","ru":"Меньшее количество автомобилей не компенсирует ночных рисков: видимость ограничена светом фар, пешеходов в тёмной одежде видно слишком поздно, встречные фары ослепляют, водитель быстрее устаёт, а некоторые на пустой дороге превышают скорость. Поэтому ночью скорость выбирают так, чтобы остановиться в пределах видимости ({p:12.2})."},"ref":["12.2"],"pic":["img/hsc/35-46-1.jpg"]},{"id":"h35-47","t":"h35","num":"35.47","q":{"uk":"Дистанція до зустрічного автомобіля в тумані завжди здається більшою, а швидкість меншою, ніж насправді:","ru":"Дистанция до встречного автомобиля в тумане всегда кажется больше, а скорость меньше, чем на самом деле:"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"Туман справді спотворює сприйняття: розмиті й тьмяні об'єкти здаються далі й повільнішими, ніж є насправді.","ru":"Туман действительно искажает восприятие: размытые и тусклые объекты кажутся дальше и медленнее, чем есть на самом деле."}}],"c":0,"e":{"uk":"У тумані обриси й вогні зустрічного автомобіля розмиті й тьмяні, тому мозок сприймає його як віддаленіший і повільніший, ніж насправді. Через це водій запізнюється з реакцією — у тумані треба знизити швидкість ({p:12.2}) і залишати більший запас відстані.","ru":"В тумане очертания и огни встречного автомобиля размыты и тусклы, поэтому мозг воспринимает его как более удалённый и медленный, чем на самом деле. Из-за этого водитель запаздывает с реакцией — в тумане нужно снизить скорость ({p:12.2}) и оставлять больший запас расстояния."},"ref":["12.2"],"pic":["img/hsc/35-47-1.jpg"]},{"id":"h35-48","t":"h35","num":"35.48","q":{"uk":"Перед тим, як вирушати у поїздку вночі, особливу увагу слід приділити:","ru":"Перед тем как отправляться в поездку ночью, особое внимание следует уделить:"},"a":[{"uk":"Освітлювальним приладам.","ru":"Осветительным приборам."},{"uk":"Справності кондиціонера.","ru":"Исправности кондиционера.","w":{"uk":"Кондиціонер впливає на комфорт, а не на видимість, тож для нічної поїздки він не має особливого значення.","ru":"Кондиционер влияет на комфорт, а не на видимость, поэтому для ночной поездки он не имеет особого значения."}},{"uk":"Справності склоочисників.","ru":"Исправности стеклоочистителей.","w":{"uk":"Справні склоочисники потрібні за будь-якої погоди, удень і вночі; саме для нічної поїздки найважливіші освітлювальні прилади.","ru":"Исправные стеклоочистители нужны в любую погоду, днём и ночью; именно для ночной поездки важнее всего осветительные приборы."}}],"c":0,"e":{"uk":"Уночі безпека залежить насамперед від того, як водій бачить дорогу і як його бачать інші, — тобто від справності фар, габаритних ліхтарів, сигналів гальмування й покажчиків поворотів. Технічний стан водій перевіряє перед виїздом ({p:2.3}), а в темну пору доби фари мають бути ввімкнені ({p:19.1}).","ru":"Ночью безопасность зависит прежде всего от того, как водитель видит дорогу и как его видят другие, — то есть от исправности фар, габаритных огней, сигналов торможения и указателей поворотов. Техническое состояние водитель проверяет перед выездом ({p:2.3}), а в тёмное время суток фары должны быть включены ({p:19.1})."},"ref":["2.3","19.1"],"pic":["img/hsc/35-48-1.jpg"]},{"id":"h35-49","t":"h35","num":"35.49","q":{"uk":"Для того щоб розпочати рух взимку достатньо очистити лобове скло автомобіля:","ru":"Для того чтобы начать движение зимой, достаточно очистить лобовое стекло автомобиля:"},"a":[{"uk":"Так.","ru":"Да.","w":{"uk":"З одним лише очищеним лобовим склом водій не бачить обстановки збоку й позаду, а засніжені фари й ліхтарі роблять автомобіль малопомітним.","ru":"С одним лишь очищенным лобовым стеклом водитель не видит обстановку сбоку и сзади, а заснеженные фары и фонари делают автомобиль малозаметным."}},{"uk":"Ні.","ru":"Нет."}],"c":1,"e":{"uk":"Перед виїздом від снігу й льоду очищають усі вікна, бічні дзеркала, фари й ліхтарі, а також дах і капот: інакше водій не бачить обстановки збоку й позаду, інші не бачать його світлових сигналів, а сніг із даху під час гальмування з'їде на лобове скло ({p:2.3}).","ru":"Перед выездом от снега и льда очищают все окна, боковые зеркала, фары и фонари, а также крышу и капот: иначе водитель не видит обстановку сбоку и сзади, другие не видят его световых сигналов, а снег с крыши при торможении сползёт на лобовое стекло ({p:2.3})."},"ref":["2.3"],"pic":["img/hsc/35-49-1.jpg"]},{"id":"h35-50","t":"h35","num":"35.50","q":{"uk":"Під час руху взимку всі рухи водія мають бути якомога плавнішими:","ru":"Во время движения зимой все действия водителя должны быть как можно более плавными:"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"Різкі дії кермом, газом чи гальмом на слизькій дорозі — найчастіша причина зимових заносів.","ru":"Резкие действия рулём, газом или тормозом на скользкой дороге — самая частая причина зимних заносов."}}],"c":0,"e":{"uk":"На снігу й льоду зчеплення шин з дорогою мале, і будь-яка різка дія — газ, гальмування чи поворот керма — може зірвати колеса в ковзання й спричинити занос. Плавні рухи дають змогу втримати автомобіль у межах наявного зчеплення.","ru":"На снегу и льду сцепление шин с дорогой мало, и любое резкое действие — газ, торможение или поворот руля — может сорвать колёса в скольжение и вызвать занос. Плавные движения позволяют удержать автомобиль в пределах имеющегося сцепления."}},{"id":"h35-51","t":"h35","num":"35.51","q":{"uk":"Ви можете подавати звукові сигнали в населеному пункті будь-коли, якщо вважаєте це необхідним:","ru":"Вы можете подавать звуковые сигналы в населённом пункте в любое время, если считаете это необходимым:"},"a":[{"uk":"Так.","ru":"Да.","w":{"uk":"Звуковий сигнал у населеному пункті дозволений лише для запобігання ДТП ({p:9.5}), а не будь-коли на розсуд водія.","ru":"Звуковой сигнал в населённом пункте разрешён только для предотвращения ДТП ({p:9.5}), а не когда угодно на усмотрение водителя."}},{"uk":"Ні.","ru":"Нет."}],"c":1,"e":{"uk":"За {p:9.5} у населених пунктах подавати звукові сигнали заборонено, крім випадків, коли без цього неможливо запобігти ДТП. Отже, підставою є лише загроза пригоди, а не будь-яке бажання водія привернути увагу.","ru":"По {p:9.5} в населённых пунктах подавать звуковые сигналы запрещено, кроме случаев, когда без этого невозможно предотвратить ДТП. Значит, основанием служит только угроза происшествия, а не любое желание водителя привлечь внимание."},"ref":["9.5"],"pic":["img/hsc/35-51-1.jpg"]},{"id":"h35-52","t":"h35","num":"35.52","q":{"uk":"Ви повинні закінчити подавання сигналу світловим покажчиком повороту безпосередньо під час виконання маневру повороту?","ru":"Вы должны прекратить подачу сигнала световым указателем поворота непосредственно во время выполнения манёвра поворота?"},"a":[{"uk":"Так.","ru":"Да.","w":{"uk":"Вимкнути сигнал посеред повороту — означає позбавити інших учасників руху інформації про маневр, що триває; припиняють його лише після завершення маневру ({p:9.4}).","ru":"Выключить сигнал посреди поворота — значит лишить других участников движения информации о продолжающемся манёвре; прекращают его только после завершения манёвра ({p:9.4})."}},{"uk":"Ні.","ru":"Нет."}],"c":1,"e":{"uk":"За {p:9.4} сигнал покажчиком повороту подають завчасно до початку маневру й припиняють **негайно після його завершення**. Тобто протягом усього повороту сигнал має працювати, щоб інші учасники руху розуміли ваші наміри.","ru":"По {p:9.4} сигнал указателем поворота подают заблаговременно до начала манёвра и прекращают **немедленно после его завершения**. То есть на протяжении всего поворота сигнал должен работать, чтобы другие участники движения понимали ваши намерения."},"ref":["9.4"],"pic":["img/hsc/35-52-1.jpg"]},{"id":"h35-53","t":"h35","num":"35.53","q":{"uk":"Чому небезпечно залишати дах автомобіля не очищеним від снігу взимку?","ru":"Почему опасно оставлять крышу автомобиля не очищенной от снега зимой?"},"a":[{"uk":"Сніг може потрапити на лобове скло Вашого автомобіля під час руху.","ru":"Снег может попасть на лобовое стекло вашего автомобиля во время движения.","w":{"uk":"Це справжня небезпека, але сніг із даху загрожує й іншим автомобілям, на які він може злетіти.","ru":"Это реальная опасность, но снег с крыши угрожает и другим автомобилям, на которые он может слететь."}},{"uk":"Сніг може потрапити на інші автомобілі під час руху.","ru":"Снег может попасть на другие автомобили во время движения.","w":{"uk":"Це справжня небезпека, але сніг може з'їхати й на ваше власне лобове скло під час гальмування.","ru":"Это реальная опасность, но снег может сползти и на ваше собственное лобовое стекло при торможении."}},{"uk":"Усе вищенаведене.","ru":"Всё вышеприведённое."}],"c":2,"e":{"uk":"Сніг на даху створює подвійну небезпеку: під час гальмування він з'їжджає на ваше лобове скло й закриває огляд, а на ходу зривається й летить на автомобілі позаду, закриваючи огляд їхнім водіям. Тому дах очищають перед виїздом ({p:2.3}).","ru":"Снег на крыше создаёт двойную опасность: при торможении он сползает на ваше лобовое стекло и закрывает обзор, а на ходу срывается и летит на автомобили сзади, закрывая обзор их водителям. Поэтому крышу очищают перед выездом ({p:2.3})."},"ref":["2.3"],"pic":["img/hsc/35-53-1.jpg"]},{"id":"h35-54","t":"h35","num":"35.54","q":{"uk":"Чим вищою є швидкість руху, тим більшою повинна бути дистанція до транспортного засобу, що рухається попереду?","ru":"Чем выше скорость движения, тем больше должна быть дистанция до транспортного средства, движущегося впереди?"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"Що вища швидкість, то довший зупинний шлях, тож за тієї самої дистанції запасу на зупинку вже не вистачить.","ru":"Чем выше скорость, тем длиннее остановочный путь, поэтому при той же дистанции запаса на остановку уже не хватит."}}],"c":0,"e":{"uk":"Зі зростанням швидкості збільшуються і відстань, яку автомобіль проходить за час реакції водія, і гальмовий шлях. Тому безпечну дистанцію обирають залежно від швидкості ({p:13.1}), і зручно відміряти її в секундах, а не в метрах.","ru":"С ростом скорости увеличиваются и расстояние, которое автомобиль проходит за время реакции водителя, и тормозной путь. Поэтому безопасную дистанцию выбирают в зависимости от скорости ({p:13.1}), и удобно отмерять её в секундах, а не в метрах."},"ref":["13.1"]},{"id":"h35-55","t":"h35","num":"35.55","q":{"uk":"Чи погоджуєтесь Ви з тим, що при збільшенні швидкості у два рази, гальмовий шлях збільшується приблизно у чотири рази:","ru":"Согласны ли вы с тем, что при увеличении скорости в два раза тормозной путь увеличивается примерно в четыре раза:"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"Гальмовий шлях зростає не пропорційно швидкості, а пропорційно її квадрату, тобто за подвоєння швидкості — приблизно вчетверо.","ru":"Тормозной путь растёт не пропорционально скорости, а пропорционально её квадрату, то есть при удвоении скорости — примерно вчетверо."}}],"c":0,"e":{"uk":"Кінетична енергія автомобіля пропорційна **квадрату** швидкості, а гальма гасять її з приблизно сталою силою. Тому гальмовий шлях зростає пропорційно квадрату швидкості: удвічі більша швидкість — приблизно вчетверо довший гальмовий шлях.","ru":"Кинетическая энергия автомобиля пропорциональна **квадрату** скорости, а тормоза гасят её с примерно постоянной силой. Поэтому тормозной путь растёт пропорционально квадрату скорости: вдвое большая скорость — примерно вчетверо более длинный тормозной путь."}},{"id":"h35-56","t":"h35","num":"35.56","q":{"uk":"З метою безпечного керування транспортним засобом водій повинен прогнозувати зміни дорожньої обстановки:","ru":"С целью безопасного управления транспортным средством водитель должен прогнозировать изменения дорожной обстановки:"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні, оскільки дорожня обстановка ніяк не залежить від водія.","ru":"Нет, поскольку дорожная обстановка никак не зависит от водителя.","w":{"uk":"Водій не керує діями інших, але може передбачити їх і заздалегідь підготуватися — саме від цього залежить, чи встигне він уникнути небезпеки.","ru":"Водитель не управляет действиями других, но может предвидеть их и заранее подготовиться — именно от этого зависит, успеет ли он избежать опасности."}}],"c":0,"e":{"uk":"Водій зобов'язаний стежити за дорожньою обстановкою й відповідно реагувати на її зміну ({p:2.3}). Прогнозування — наприклад, що м'яч на дорозі означає дитину поруч, — дає змогу заздалегідь знизити швидкість і не потрапити в аварійну ситуацію.","ru":"Водитель обязан следить за дорожной обстановкой и соответственно реагировать на её изменение ({p:2.3}). Прогнозирование — например, что мяч на дороге означает ребёнка поблизости, — позволяет заранее снизить скорость и не попасть в аварийную ситуацию."},"ref":["2.3"]},{"id":"h35-57","t":"h35","num":"35.57","q":{"uk":"Дозволений рівень алкоголю в крові водія в Україні не повинен перевищувати:","ru":"Разрешённый уровень алкоголя в крови водителя в Украине не должен превышать:"},"a":[{"uk":"0,3 проміле.","ru":"0,3 промилле.","w":{"uk":"0,3 проміле перевищує встановлену межу 0,2 проміле — це вже стан алкогольного сп'яніння.","ru":"0,3 промилле превышает установленный предел 0,2 промилле — это уже состояние алкогольного опьянения."}},{"uk":"0,2 проміле.","ru":"0,2 промилле."},{"uk":"0,4 проміле.","ru":"0,4 промилле.","w":{"uk":"0,4 проміле вдвічі перевищує встановлену межу 0,2 проміле.","ru":"0,4 промилле вдвое превышает установленный предел 0,2 промилле."}}],"c":1,"e":{"uk":"Керувати в стані сп'яніння заборонено ({p:2.9}), а за українським законодавством алкогольним сп'янінням вважається вміст алкоголю в крові понад **0,2** проміле. Будь-яка доза алкоголю погіршує реакцію, тож найбезпечніше взагалі не вживати його перед поїздкою.","ru":"Управлять в состоянии опьянения запрещено ({p:2.9}), а по украинскому законодательству алкогольным опьянением считается содержание алкоголя в крови более **0,2** промилле. Любая доза алкоголя ухудшает реакцию, поэтому безопаснее всего вообще не употреблять его перед поездкой."},"ref":["2.9"]},{"id":"h35-58","t":"h35","num":"35.58","q":{"uk":"Водії із досвідом водіння понад 10 років можуть під час руху користуватись телефоном, тримаючи його в руці:","ru":"Водители со стажем вождения более 10 лет могут во время движения пользоваться телефоном, держа его в руке:"},"a":[{"uk":"Так.","ru":"Да.","w":{"uk":"Заборона з {p:2.9} діє для всіх водіїв: досвід не повертає уваги, яку забирає розмова, і не звільняє зайняту телефоном руку.","ru":"Запрет из {p:2.9} действует для всех водителей: опыт не возвращает внимание, которое отнимает разговор, и не освобождает занятую телефоном руку."}},{"uk":"Ні.","ru":"Нет."}],"c":1,"e":{"uk":"{p:2.9} забороняє під час руху користуватися засобами зв'язку, тримаючи їх у руці, — незалежно від стажу; виняток зроблено лише для водіїв оперативних транспортних засобів під час невідкладного службового завдання. Розмовляти можна через гарнітуру або систему «вільні руки».","ru":"{p:2.9} запрещает во время движения пользоваться средствами связи, держа их в руке, — независимо от стажа; исключение сделано только для водителей оперативных транспортных средств при выполнении неотложного служебного задания. Разговаривать можно через гарнитуру или систему «свободные руки»."},"ref":["2.9"],"pic":["img/hsc/35-58-1.jpg"]},{"id":"h35-59","t":"h35","num":"35.59","q":{"uk":"Як Ви повинні вчинити, якщо зіштовхнулися з агресивною манерою водіння водіїв, що рухаються попереду?","ru":"Как вы должны поступить, если столкнулись с агрессивной манерой вождения водителей, движущихся впереди?"},"a":[{"uk":"Зберігати спокій, максимально уважно стежити за дорожньою обстановкою.","ru":"Сохранять спокойствие, максимально внимательно следить за дорожной обстановкой.","w":{"uk":"Спокій і уважність потрібні, але їх замало без готовності знизити швидкість чи зупинитися.","ru":"Спокойствие и внимательность нужны, но их мало без готовности снизить скорость или остановиться."}},{"uk":"Бути готовим зменшити швидкість.","ru":"Быть готовым снизить скорость.","w":{"uk":"Бути готовим знизити швидкість треба, але так само потрібні спокій і готовність зупинитися.","ru":"Быть готовым снизить скорость нужно, но так же нужны спокойствие и готовность остановиться."}},{"uk":"Бути готовим зупинитись.","ru":"Быть готовым остановиться.","w":{"uk":"Бути готовим зупинитися треба, але це лише одна з правильних дій — решта варіантів також вірні.","ru":"Быть готовым остановиться нужно, но это лишь одно из правильных действий — остальные варианты тоже верны."}},{"uk":"Усе вищеперераховане.","ru":"Всё вышеперечисленное."}],"c":3,"e":{"uk":"Агресивний водій може різко перестроїтися, «підрізати» чи раптово загальмувати. Найкращий захист — не піддаватися на провокації, зберігати спокій, тримати більшу дистанцію ({p:13.1}) і бути готовим знизити швидкість аж до зупинки ({p:12.3}).","ru":"Агрессивный водитель может резко перестроиться, «подрезать» или внезапно затормозить. Лучшая защита — не поддаваться на провокации, сохранять спокойствие, держать увеличенную дистанцию ({p:13.1}) и быть готовым снизить скорость вплоть до остановки ({p:12.3})."},"ref":["12.3","13.1"],"pic":["img/hsc/35-59-1.jpg"]},{"id":"h35-60","t":"h35","num":"35.60","q":{"uk":"Цей автомобіль здійснює рух заднім ходом?","ru":"Этот автомобиль движется задним ходом?"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"Білі вогні позаду автомобіля — це ліхтарі заднього ходу, які горять лише з увімкненою задньою передачею.","ru":"Белые огни сзади автомобиля — это фонари заднего хода, которые горят только с включённой задней передачей."}}],"c":0,"e":{"uk":"На фото ввімкнені білі ліхтарі заднього ходу — вони світяться, лише коли ввімкнено задню передачу. Ліхтар заднього ходу є попереджувальним сигналом ({p:9.1}), який повідомляє інших про рух назад.","ru":"На фото включены белые фонари заднего хода — они светятся, только когда включена задняя передача. Фонарь заднего хода является предупреждающим сигналом ({p:9.1}), который сообщает другим о движении назад."},"ref":["9.1"],"pic":["img/hsc/35-60-1.jpg"]},{"id":"h35-61","t":"h35","num":"35.61","q":{"uk":"На дорозі раптово з'явилася дика тварина, Ваші дії:","ru":"На дороге внезапно появилось дикое животное, ваши действия:"},"a":[{"uk":"Гальмувати та бути готовим до повної зупинки.","ru":"Тормозить и быть готовым к полной остановке."},{"uk":"Одразу виконати різкий рух кермом.","ru":"Сразу выполнить резкое движение рулём.","w":{"uk":"Різкий поворот керма на швидкості може спричинити занос, перекидання чи зіткнення із зустрічним транспортом, а тварина однаково може метнутися в той самий бік.","ru":"Резкий поворот руля на скорости может вызвать занос, опрокидывание или столкновение со встречным транспортом, а животное всё равно может метнуться в ту же сторону."}}],"c":0,"e":{"uk":"Поява тварини — небезпека для руху, і {p:12.3} вимагає негайно знижувати швидкість аж до зупинки. Різкий маневр кермом на швидкості загрожує заносом, виїздом на зустрічну смугу чи в кювет — це часто тяжче, ніж зіткнення з твариною, яка до того ж може раптово змінити напрямок.","ru":"Появление животного — опасность для движения, и {p:12.3} требует немедленно снижать скорость вплоть до остановки. Резкий манёвр рулём на скорости грозит заносом, выездом на встречную полосу или в кювет — это часто тяжелее, чем столкновение с животным, которое к тому же может внезапно изменить направление."},"ref":["12.3"],"pic":["img/hsc/35-61-1.jpg"]},{"id":"h35-62","t":"h35","num":"35.62","q":{"uk":"Якщо через сильну зливу в межах населеного пункту, Ви не можете продовжувати рух, необхідно:","ru":"Если из-за сильного ливня в пределах населённого пункта вы не можете продолжать движение, необходимо:"},"a":[{"uk":"Зупинитись біля краю проїзної частини та увімкнути аварійну світлову сигналізацію.","ru":"Остановиться у края проезжей части и включить аварийную световую сигнализацию."},{"uk":"Зупинитись на проїзній частині та увімкнути дальнє світло фар.","ru":"Остановиться на проезжей части и включить дальний свет фар.","w":{"uk":"Автомобіль посеред проїзної частини в зливу — загроза наїзду ззаду, а дальнє світло засліплює зустрічних водіїв і відбивається від стіни дощу; позначають таку зупинку аварійною сигналізацією.","ru":"Автомобиль посреди проезжей части в ливень — угроза наезда сзади, а дальний свет ослепляет встречных водителей и отражается от стены дождя; обозначают такую остановку аварийной сигнализацией."}}],"c":0,"e":{"uk":"Якщо через зливу рух неможливий, слід зупинитися на узбіччі або якомога правіше біля краю проїзної частини ({p:15.1}, {p:15.2}) і ввімкнути аварійну сигналізацію ({p:9.9}): у дощ інші водії погано бачать нерухомий автомобіль. За недостатньої видимості мають горіти й габаритні ліхтарі ({p:19.4}).","ru":"Если из-за ливня движение невозможно, следует остановиться на обочине или как можно правее у края проезжей части ({p:15.1}, {p:15.2}) и включить аварийную сигнализацию ({p:9.9}): в дождь другие водители плохо видят неподвижный автомобиль. При недостаточной видимости должны гореть и габаритные огни ({p:19.4})."},"ref":["15.1","15.2","9.9","19.4"],"pic":["img/hsc/35-62-1.jpg"]},{"id":"h35-63","t":"h35","num":"35.63","q":{"uk":"Чи можна різко збільшувати швидкість під час руху в дощову погоду?","ru":"Можно ли резко увеличивать скорость во время движения в дождливую погоду?"},"a":[{"uk":"Так.","ru":"Да.","w":{"uk":"Різкий розгін на мокрій дорозі зриває ведучі колеса в пробуксовування й загрожує заносом.","ru":"Резкий разгон на мокрой дороге срывает ведущие колёса в пробуксовку и грозит заносом."}},{"uk":"Ні.","ru":"Нет."}],"c":1,"e":{"uk":"На мокрому покритті зчеплення шин з дорогою значно гірше: різке натискання на газ спричиняє пробуксовування ведучих коліс і може зірвати автомобіль у занос, а на калюжах — призвести до аквапланування. Тому в дощ розганяються плавно.","ru":"На мокром покрытии сцепление шин с дорогой значительно хуже: резкое нажатие на газ вызывает пробуксовку ведущих колёс и может сорвать автомобиль в занос, а на лужах — привести к аквапланированию. Поэтому в дождь разгоняются плавно."},"pic":["img/hsc/35-63-1.jpg"]},{"id":"h35-64","t":"h35","num":"35.64","q":{"uk":"Чи потрібно зменшити швидкість до та після проїзду цього дорожнього знаку?","ru":"Нужно ли снижать скорость до и после проезда этого дорожного знака?"},"a":[{"uk":"Лише перед початком.","ru":"Только перед началом.","w":{"uk":"Небезпека — сама ділянка робіт за знаком, тож знижену швидкість зберігають і після нього, поки роботи не закінчаться.","ru":"Опасность — сам участок работ за знаком, поэтому сниженную скорость сохраняют и после него, пока работы не закончатся."}},{"uk":"Після проїзду.","ru":"После проезда.","w":{"uk":"Знижувати швидкість треба вже на підході до знака, щоб в'їхати на ділянку робіт без різкого гальмування.","ru":"Снижать скорость нужно уже на подходе к знаку, чтобы въехать на участок работ без резкого торможения."}},{"uk":"В обох випадках.","ru":"В обоих случаях."}],"c":2,"e":{"uk":"Знак {s:1.37} попереджає про ділянку дорожніх робіт ({p:33.1}). Швидкість знижують заздалегідь, наближаючись до неї, і тримають низькою на всій ділянці за знаком — там можуть бути звуження, нерівне покриття, техніка й робітники ({p:12.1}).","ru":"Знак {s:1.37} предупреждает об участке дорожных работ ({p:33.1}). Скорость снижают заранее, приближаясь к нему, и держат низкой на всём участке за знаком — там могут быть сужения, неровное покрытие, техника и рабочие ({p:12.1})."},"ref":["33.1","12.1"],"pic":["img/hsc/35-64-1.jpg"]},{"id":"h35-65","t":"h35","num":"35.65","q":{"uk":"Ви наближаєтесь до перехрестя, Ваші дії:","ru":"Вы приближаетесь к перекрёстку, ваши действия:"},"a":[{"uk":"Бути готовим до зміни сигналів світлофору.","ru":"Быть готовым к смене сигналов светофора.","w":{"uk":"Готовність до зміни сигналу потрібна, але слід пам'ятати й про можливі помилки інших водіїв.","ru":"Готовность к смене сигнала нужна, но следует помнить и о возможных ошибках других водителей."}},{"uk":"Бути готовим до того, що водій зустрічного автомобіля може помилитися та продовжити свій маневр перед Вами.","ru":"Быть готовым к тому, что водитель встречного автомобиля может ошибиться и продолжить свой манёвр перед вами.","w":{"uk":"Помилки інших водіїв варто передбачати, але так само треба бути готовим до зміни сигналів світлофора.","ru":"Ошибки других водителей стоит предвидеть, но так же нужно быть готовым к смене сигналов светофора."}},{"uk":"Бути готовим до вищеперерахованого.","ru":"Быть готовым к вышеперечисленному."}],"c":2,"e":{"uk":"Перехрестя — одне з найнебезпечніших місць на дорозі. Зелений може змінитися на жовтий у будь-яку мить ({p:8.7}), а зустрічний водій, що повертає ліворуч, може неправильно оцінити вашу швидкість і не дати дороги. Тому до перехрестя наближаються уважно ({p:2.3}) і з такою швидкістю, щоб устигнути зреагувати в обох випадках.","ru":"Перекрёсток — одно из самых опасных мест на дороге. Зелёный может смениться жёлтым в любой момент ({p:8.7}), а встречный водитель, поворачивающий налево, может неверно оценить вашу скорость и не уступить дорогу. Поэтому к перекрёстку приближаются внимательно ({p:2.3}) и с такой скоростью, чтобы успеть среагировать в обоих случаях."},"ref":["8.7","2.3"],"pic":["img/hsc/35-65-1.jpg"]},{"id":"h35-66","t":"h35","num":"35.66","q":{"uk":"Ви вирушили в доволі далеку поїздку. Через деякий час ви починаєте відчувати втому. Що Вам слід зробити?","ru":"Вы отправились в довольно дальнюю поездку. Через некоторое время вы начинаете чувствовать усталость. Что вам следует сделать?"},"a":[{"uk":"З’їхати з дороги, зупинитися та відпочити, поки не перестанете відчувати втому.","ru":"Съехать с дороги, остановиться и отдохнуть, пока не перестанете чувствовать усталость."},{"uk":"Достатньо відчинити вікно, щоб в салоні автомобіля циркулювало багато свіжого повітря.","ru":"Достаточно открыть окно, чтобы в салоне автомобиля циркулировало много свежего воздуха.","w":{"uk":"Свіже повітря бадьорить лише на кілька хвилин і не усуває втоми — ризик заснути за кермом лишається.","ru":"Свежий воздух бодрит лишь на несколько минут и не устраняет усталость — риск уснуть за рулём остаётся."}}],"c":0,"e":{"uk":"Керувати транспортним засобом у стані стомлення заборонено ({p:2.9}): утома сповільнює реакцію й може призвести до мікросну за кермом. Єдиний надійний засіб — зупинитися в безпечному місці й відпочити.","ru":"Управлять транспортным средством в состоянии утомления запрещено ({p:2.9}): усталость замедляет реакцию и может привести к микросну за рулём. Единственное надёжное средство — остановиться в безопасном месте и отдохнуть."},"ref":["2.9"],"pic":["img/hsc/35-66-1.jpg"]},{"id":"h35-67","t":"h35","num":"35.67","q":{"uk":"Якщо Ви відчуваєте сильну втому за кермом, Ви:","ru":"Если вы чувствуете сильную усталость за рулём, вы:"},"a":[{"uk":"Зупинитесь, відпочините та по можливості поміняєте водія.","ru":"Остановитесь, отдохнёте и по возможности поменяете водителя."},{"uk":"Голосно ввімкнете радіо.","ru":"Громко включите радио.","w":{"uk":"Гучне радіо не знімає втоми, а лише відволікає; сонливість однаково візьме своє.","ru":"Громкое радио не снимает усталость, а лишь отвлекает; сонливость всё равно возьмёт своё."}},{"uk":"Увімкнете кондиціонер або відкриєте вікна.","ru":"Включите кондиционер или откроете окна.","w":{"uk":"Прохолода бадьорить лише на короткий час, а втома й ризик заснути за кермом лишаються.","ru":"Прохлада бодрит лишь на короткое время, а усталость и риск уснуть за рулём остаются."}}],"c":0,"e":{"uk":"Керувати в стані стомлення заборонено ({p:2.9}). Гучна музика чи прохолодне повітря лише ненадовго маскують утому, а сонливість повертається раптово; допомагає тільки відпочинок або заміна водія.","ru":"Управлять в состоянии утомления запрещено ({p:2.9}). Громкая музыка или прохладный воздух лишь ненадолго маскируют усталость, а сонливость возвращается внезапно; помогает только отдых или смена водителя."},"ref":["2.9"],"pic":["img/hsc/35-67-1.jpg"]},{"id":"h35-68","t":"h35","num":"35.68","q":{"uk":"Який найкращий спосіб уникнути наїзду на інші транспортні засоби, людей чи тварин під час виїзду на проїзну частину з узбіччя?","ru":"Какой лучший способ избежать наезда на другие транспортные средства, людей или животных при выезде на проезжую часть с обочины?"},"a":[{"uk":"Подати звуковий сигнал перед початком руху.","ru":"Подать звуковой сигнал перед началом движения.","w":{"uk":"Звуковий сигнал не дає переваги ({p:9.4}), у населених пунктах заборонений ({p:9.5}) і не показує, чи вільна дорога, — переконатися в цьому можна лише оглядом.","ru":"Звуковой сигнал не даёт преимущества ({p:9.4}), в населённых пунктах запрещён ({p:9.5}) и не показывает, свободна ли дорога, — убедиться в этом можно только осмотром."}},{"uk":"Подивитися у свої дзеркала та зробити поворот голови через плече, перш ніж виїжджати з узбіччя.","ru":"Посмотреть в свои зеркала и повернуть голову через плечо, прежде чем выезжать с обочины."}],"c":1,"e":{"uk":"Перед початком руху водій зобов'язаний переконатися, що це безпечно ({p:10.1}). Дзеркала показують не все — частина простору збоку позаду потрапляє в «сліпу зону», тому, крім дзеркал, обов'язково повертають голову й дивляться через плече.","ru":"Перед началом движения водитель обязан убедиться, что это безопасно ({p:10.1}). Зеркала показывают не всё — часть пространства сбоку сзади попадает в «слепую зону», поэтому, кроме зеркал, обязательно поворачивают голову и смотрят через плечо."},"ref":["10.1"]},{"id":"h35-69","t":"h35","num":"35.69","q":{"uk":"Якщо ви нещодавно отримали право на керування транспортним засобом і поїздки за кермом вночі викликають у Вас страх або невпевненість, найкраще:","ru":"Если вы недавно получили право на управление транспортным средством и поездки за рулём ночью вызывают у вас страх или неуверенность, лучше всего:"},"a":[{"uk":"Їздити на великі відстані, щоб покращити концентрацію.","ru":"Ездить на большие расстояния, чтобы улучшить концентрацию.","w":{"uk":"Тривалі поїздки, особливо вночі, втомлюють і погіршують концентрацію, а не покращують її.","ru":"Длительные поездки, особенно ночью, утомляют и ухудшают концентрацию, а не улучшают её."}},{"uk":"Їздити переважно незнайомими вулицями.","ru":"Ездить преимущественно по незнакомым улицам.","w":{"uk":"Незнайомі вулиці вночі додають невпевненому водієві стресу й підвищують ризик помилки.","ru":"Незнакомые улицы ночью добавляют неуверенному водителю стресса и повышают риск ошибки."}},{"uk":"Проїхати незнайомі вулиці спочатку вдень, а потім їздити такими вулицями вночі.","ru":"Проехать незнакомые улицы сначала днём, а потом ездить по таким улицам ночью."}],"c":2,"e":{"uk":"Уночі видимість гірша, а незнайома дорога додає стресу. Якщо спершу проїхати маршрут удень, ви запам'ятаєте повороти, знаки, перехрестя й небезпечні місця, а вночі зможете зосередитися на керуванні.","ru":"Ночью видимость хуже, а незнакомая дорога добавляет стресса. Если сначала проехать маршрут днём, вы запомните повороты, знаки, перекрёстки и опасные места, а ночью сможете сосредоточиться на управлении."}},{"id":"h35-70","t":"h35","num":"35.70","q":{"uk":"Під час тривалих поїздок найкращий спосіб запобігти сонливості це:","ru":"Во время длительных поездок лучший способ предотвратить сонливость — это:"},"a":[{"uk":"Увімкнення автомобільного радіо.","ru":"Включение автомобильного радио.","w":{"uk":"Радіо лише ненадовго відволікає від одноманітності, але не знімає втоми.","ru":"Радио лишь ненадолго отвлекает от однообразия, но не снимает усталость."}},{"uk":"Зменшення швидкості руху, щоб ви могли краще реагувати.","ru":"Снижение скорости движения, чтобы вы могли лучше реагировать.","w":{"uk":"Зниження швидкості не усуває сонливості: утомлений водій може задрімати й на малій швидкості.","ru":"Снижение скорости не устраняет сонливость: уставший водитель может задремать и на малой скорости."}},{"uk":"Регулярні зупинки для відпочинку та вживання питної води (за наявності).","ru":"Регулярные остановки для отдыха и употребления питьевой воды (при наличии)."}],"c":2,"e":{"uk":"Сонливість у дорозі — наслідок утоми й одноманітності, тож запобігають їй регулярні перерви (щонайменше кожні 2 години), під час яких можна розім'ятися й попити води. Керувати в стані стомлення заборонено ({p:2.9}).","ru":"Сонливость в дороге — следствие усталости и однообразия, поэтому предотвращают её регулярные перерывы (как минимум каждые 2 часа), во время которых можно размяться и попить воды. Управлять в состоянии утомления запрещено ({p:2.9})."},"ref":["2.9"],"pic":["img/hsc/35-70-1.jpg"]},{"id":"h35-71","t":"h35","num":"35.71","q":{"uk":"Ремені безпеки є найефективнішим засобом попередження травмування для водія та пасажирів:","ru":"Ремни безопасности являются самым эффективным средством предупреждения травмирования водителя и пассажиров:"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"Саме ремені безпеки найбільше знижують ризик загибелі й тяжких травм у ДТП; без них як слід не захищають навіть подушки безпеки.","ru":"Именно ремни безопасности сильнее всего снижают риск гибели и тяжёлых травм в ДТП; без них как следует не защищают даже подушки безопасности."}}],"c":0,"e":{"uk":"Під час зіткнення ремінь утримує тіло на сидінні, не дає вдаритися об кермо, панель і скло чи вилетіти з автомобіля, а навантаження розподіляє на міцні кістки таза й грудної клітки. Тому ними обов'язково користуються ({p:2.3}); подушки безпеки ефективні лише разом із пристебнутим ременем.","ru":"При столкновении ремень удерживает тело на сиденье, не даёт удариться о руль, панель и стекло или вылететь из автомобиля, а нагрузку распределяет на прочные кости таза и грудной клетки. Поэтому ими обязательно пользуются ({p:2.3}); подушки безопасности эффективны только вместе с пристёгнутым ремнём."},"ref":["2.3"],"pic":["img/hsc/35-71-1.jpg"]},{"id":"h35-72","t":"h35","num":"35.72","q":{"uk":"У якому випадку подання звукового сигналу під час руху в населеному пункті є доречним:","ru":"В каком случае подача звукового сигнала во время движения в населённом пункте уместна:"},"a":[{"uk":"Ви вирішили розпочати обгін двох транспортних засобів.","ru":"Вы решили начать обгон двух транспортных средств.","w":{"uk":"Привертати увагу водія, якого обганяють, у населеному пункті можна лише перемиканням світла фар ({p:9.6}).","ru":"Привлекать внимание обгоняемого водителя в населённом пункте можно только переключением света фар ({p:9.6})."}},{"uk":"Водій, що рухається попереду починає пригальмовувати.","ru":"Водитель, движущийся впереди, начинает притормаживать.","w":{"uk":"Гальмування автомобіля попереду — привід збільшити дистанцію чи загальмувати самому, а не сигналити ({p:9.5}).","ru":"Торможение впереди идущего автомобиля — повод увеличить дистанцию или затормозить самому, а не сигналить ({p:9.5})."}},{"uk":"Ви бачите дитину, яка збирається вибігти на проїзну частину.","ru":"Вы видите ребёнка, который собирается выбежать на проезжую часть."}],"c":2,"e":{"uk":"У населених пунктах звуковий сигнал дозволено лише тоді, коли без нього неможливо запобігти ДТП ({p:9.5}). Дитина, що от-от вибіжить на дорогу, — саме така ситуація; водночас слід знижувати швидкість аж до зупинки ({p:12.3}).","ru":"В населённых пунктах звуковой сигнал разрешён только тогда, когда без него невозможно предотвратить ДТП ({p:9.5}). Ребёнок, который вот-вот выбежит на дорогу, — именно такая ситуация; одновременно следует снижать скорость вплоть до остановки ({p:12.3})."},"ref":["9.5","12.3"],"pic":["img/hsc/35-72-1.jpg"]},{"id":"h35-73","t":"h35","num":"35.73","q":{"uk":"Якщо назустріч вам наближається транспортний засіб з увімкненим дальнім світлом фар, Ви повинні:","ru":"Если навстречу вам приближается транспортное средство с включённым дальним светом фар, вы должны:"},"a":[{"uk":"Відвести погляд на будь-яку сторону дороги.","ru":"Отвести взгляд на любую сторону дороги.","w":{"uk":"Погляд ліворуч спрямований на зустрічний транспорт і його фари — засліплення посилиться, а свою смугу ви не бачитимете.","ru":"Взгляд влево направлен на встречный транспорт и его фары — ослепление усилится, а свою полосу вы видеть не будете."}},{"uk":"Відвести погляд на праву сторону дороги.","ru":"Отвести взгляд на правую сторону дороги."},{"uk":"Відвести погляд на ліву сторону дороги.","ru":"Отвести взгляд на левую сторону дороги.","w":{"uk":"Ліворуч — зустрічна смуга з тими самими засліплювальними фарами; орієнтуватися треба на правий край дороги.","ru":"Слева — встречная полоса с теми же ослепляющими фарами; ориентироваться нужно на правый край дороги."}}],"c":1,"e":{"uk":"Дивлячись на правий край дороги, ви не дивитеся прямо у фари й водночас бачите межу своєї смуги та можливі перешкоди на узбіччі — це допомагає не збитися з напрямку. Швидкість при цьому знижують до безпечної за фактичною видимістю, а в разі засліплення зупиняються, не змінюючи смуги ({p:19.3}).","ru":"Глядя на правый край дороги, вы не смотрите прямо в фары и при этом видите границу своей полосы и возможные препятствия на обочине — это помогает не сбиться с направления. Скорость при этом снижают до безопасной по фактической видимости, а при ослеплении останавливаются, не меняя полосы ({p:19.3})."},"ref":["19.3"]},{"id":"h35-74","t":"h35","num":"35.74","q":{"uk":"Правильне налаштування підголівників може значно зменшити ризик травмування:","ru":"Правильная регулировка подголовников может значительно уменьшить риск травмирования:"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"Неправильно встановлений (занизький чи віддалений від голови) підголовник не втримає голову під час удару ззаду, і ризик травми шиї зросте.","ru":"Неправильно установленный (слишком низкий или удалённый от головы) подголовник не удержит голову при ударе сзади, и риск травмы шеи возрастёт."}}],"c":0,"e":{"uk":"Під час удару ззаду голова різко відкидається назад, і без опори травмується шия («хлистова травма»). Підголовник, верх якого на рівні верхівки голови й близько до потилиці, зупиняє цей рух; водій зобов'язаний користуватися підголовниками ({p:2.3}).","ru":"При ударе сзади голова резко запрокидывается назад, и без опоры травмируется шея («хлыстовая травма»). Подголовник, верх которого на уровне макушки и близко к затылку, останавливает это движение; водитель обязан пользоваться подголовниками ({p:2.3})."},"ref":["2.3"],"pic":["img/hsc/35-74-1.jpg"]},{"id":"h35-75","t":"h35","num":"35.75","q":{"uk":"Що означають білі або прозорі вогні в задній частині автомобіля:","ru":"Что означают белые или прозрачные огни в задней части автомобиля:"},"a":[{"uk":"Транспортний засіб рухається заднім ходом.","ru":"Транспортное средство движется задним ходом."},{"uk":"Транспортний засіб зупинився.","ru":"Транспортное средство остановилось.","w":{"uk":"Про зупинку чи гальмування сигналізують червоні сигнали гальмування, а не білі вогні.","ru":"Об остановке или торможении сигнализируют красные сигналы торможения, а не белые огни."}},{"uk":"Свідчать про несправність транспортного засобу.","ru":"Свидетельствуют о неисправности транспортного средства.","w":{"uk":"Білі задні вогні — штатний сигнал заднього ходу, а не ознака несправності.","ru":"Белые задние огни — штатный сигнал заднего хода, а не признак неисправности."}}],"c":0,"e":{"uk":"Білі вогні позаду — це ліхтарі заднього ходу: вони світяться, коли ввімкнено задню передачу, і є попереджувальним сигналом ({p:9.1}). Побачивши їх, слід бути готовим, що автомобіль рушить назад.","ru":"Белые огни сзади — это фонари заднего хода: они светятся, когда включена задняя передача, и являются предупреждающим сигналом ({p:9.1}). Увидев их, следует быть готовым, что автомобиль тронется назад."},"ref":["9.1"],"pic":["img/hsc/35-75-1.jpg"]},{"id":"h35-76","t":"h35","num":"35.76","q":{"uk":"Недостатній тиск в шинах збільшує гальмівний шлях автомобіля:","ru":"Недостаточное давление в шинах увеличивает тормозной путь автомобиля:"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"За недостатнього тиску шина гірше тримає дорогу, особливо мокру, тож гальмовий шлях зростає.","ru":"При недостаточном давлении шина хуже держит дорогу, особенно мокрую, поэтому тормозной путь растёт."}}],"c":0,"e":{"uk":"Недокачана шина деформується, пляма контакту стає нерівномірною (навантаження переходить на краї протектора), а на мокрій дорозі вода гірше відводиться з-під неї. Зчеплення погіршується, тож гальмовий шлях подовжується, а автомобіль гірше тримає траєкторію.","ru":"Недокачанная шина деформируется, пятно контакта становится неравномерным (нагрузка переходит на края протектора), а на мокрой дороге вода хуже отводится из-под неё. Сцепление ухудшается, поэтому тормозной путь удлиняется, а автомобиль хуже держит траекторию."},"pic":["img/hsc/35-76-1.jpg"]},{"id":"h35-77","t":"h35","num":"35.77","q":{"uk":"Недостатній тиск в шинах сприяє економії пального:","ru":"Недостаточное давление в шинах способствует экономии топлива:"},"a":[{"uk":"Так.","ru":"Да.","w":{"uk":"Ефект протилежний: зі зниженням тиску зростає опір коченню, і автомобіль споживає більше пального.","ru":"Эффект обратный: со снижением давления растёт сопротивление качению, и автомобиль потребляет больше топлива."}},{"uk":"Ні.","ru":"Нет."}],"c":1,"e":{"uk":"Недокачана шина сильніше деформується під час кочення, і на цю деформацію двигун витрачає додаткову енергію — опір коченню зростає, а з ним і витрата пального. До того ж шина перегрівається й швидше зношується.","ru":"Недокачанная шина сильнее деформируется при качении, и на эту деформацию двигатель тратит дополнительную энергию — сопротивление качению растёт, а с ним и расход топлива. К тому же шина перегревается и быстрее изнашивается."},"pic":["img/hsc/35-77-1.jpg"]},{"id":"h35-78","t":"h35","num":"35.78","q":{"uk":"Найбільша небезпека великогабаритних транспортних засобів у тому, що вони:","ru":"Наибольшая опасность крупногабаритных транспортных средств в том, что они:"},"a":[{"uk":"Не обладнані боковими дзеркалами.","ru":"Не оборудованы боковыми зеркалами.","w":{"uk":"Великогабаритні транспортні засоби обладнані боковими дзеркалами, часто кількома, — але й вони не охоплюють усього простору навколо.","ru":"Крупногабаритные транспортные средства оборудованы боковыми зеркалами, часто несколькими, — но и они не охватывают всё пространство вокруг."}},{"uk":"Не обладнані дзеркалами заднього виду.","ru":"Не оборудованы зеркалами заднего вида.","w":{"uk":"Дзеркала заднього виду в них є; проблема в тому, що вони не показують усього простору довкола великого кузова.","ru":"Зеркала заднего вида у них есть; проблема в том, что они не показывают всё пространство вокруг большого кузова."}},{"uk":"Мають великі «сліпі зони».","ru":"Имеют большие «слепые зоны»."},{"uk":"Не мають ефективних гальм.","ru":"Не имеют эффективных тормозов.","w":{"uk":"Гальма в них ефективні, хоча через велику масу гальмовий шлях довший; головна небезпека для інших учасників руху — «сліпі зони».","ru":"Тормоза у них эффективные, хотя из-за большой массы тормозной путь длиннее; главная опасность для других участников движения — «слепые зоны»."}}],"c":2,"e":{"uk":"Через великі розміри кабіни й кузова водій вантажівки чи автобуса не бачить значної частини простору поруч: одразу перед кабіною, уздовж бортів (особливо праворуч) і позаду. Автомобіль у такій «сліпій зоні» він може не помітити під час перестроювання чи повороту, тож довго в ній не залишаються.","ru":"Из-за больших размеров кабины и кузова водитель грузовика или автобуса не видит значительной части пространства рядом: непосредственно перед кабиной, вдоль бортов (особенно справа) и сзади. Автомобиль в такой «слепой зоне» он может не заметить при перестроении или повороте, поэтому долго в ней не задерживаются."}},{"id":"h35-79","t":"h35","num":"35.79","q":{"uk":"Коли інший автомобіль розпочав маневр перестроювання у вашу смугу зі смуги праворуч, Ваші дії:","ru":"Когда другой автомобиль начал манёвр перестроения в вашу полосу из полосы справа, ваши действия:"},"a":[{"uk":"Збільшити швидкість.","ru":"Увеличить скорость.","w":{"uk":"Розгін «наперекір» скорочує проміжок між автомобілями й робить бокове зіткнення ймовірнішим.","ru":"Разгон «наперекор» сокращает промежуток между автомобилями и делает боковое столкновение более вероятным."}},{"uk":"Подати звуковий сигнал.","ru":"Подать звуковой сигнал.","w":{"uk":"Сигнал не зупинить маневр, що вже почався, а в населеному пункті звуковий сигнал дозволено лише тоді, коли інакше ДТП не запобігти ({p:9.5}), — тут досить знизити швидкість.","ru":"Сигнал не остановит уже начатый манёвр, а в населённом пункте звуковой сигнал разрешён только тогда, когда иначе ДТП не предотвратить ({p:9.5}), — здесь достаточно снизить скорость."}},{"uk":"Зменшити швидкість та дозволити йому здійснити маневр перестроювання.","ru":"Уменьшить скорость и позволить ему выполнить манёвр перестроения."}],"c":2,"e":{"uk":"Хоча за {p:10.3} водій, що перестроюється, мав би дати вам дорогу, маневр уже розпочато — і наполягати на своїй перевазі означає ризикувати зіткненням. Безпечніше знизити швидкість ({p:12.3}), збільшити проміжок і дати йому завершити перестроювання.","ru":"Хотя по {p:10.3} перестраивающийся водитель должен был бы уступить вам дорогу, манёвр уже начат — и настаивать на своём преимуществе значит рисковать столкновением. Безопаснее снизить скорость ({p:12.3}), увеличить промежуток и дать ему завершить перестроение."},"ref":["10.3","12.3"],"pic":["img/hsc/35-79-1.jpg"]},{"id":"h35-80","t":"h35","num":"35.80","q":{"uk":"Якщо водій білого автомобіля різко розпочав маневр перестроювання у вашу смугу зі смуги ліворуч, Ваші дії:","ru":"Если водитель белого автомобиля резко начал манёвр перестроения в вашу полосу из полосы слева, ваши действия:"},"a":[{"uk":"Збільшити швидкість.","ru":"Увеличить скорость.","w":{"uk":"Розгін, коли інший автомобіль уже зміщується у вашу смугу, майже гарантує бокове зіткнення.","ru":"Разгон, когда другой автомобиль уже смещается в вашу полосу, почти гарантирует боковое столкновение."}},{"uk":"Подати звуковий сигнал.","ru":"Подать звуковой сигнал.","w":{"uk":"Звуковий сигнал не зупинить різкий маневр, а лише відволіче вас від головного — вчасно загальмувати; у населеному пункті він до того ж обмежений {p:9.5}.","ru":"Звуковой сигнал не остановит резкий манёвр, а лишь отвлечёт вас от главного — вовремя затормозить; в населённом пункте он к тому же ограничен {p:9.5}."}},{"uk":"Зменшити швидкість та дозволити йому здійснити маневр перестроювання.","ru":"Уменьшить скорость и позволить ему выполнить манёвр перестроения."}],"c":2,"e":{"uk":"Водій білого автомобіля мав дати вам дорогу ({p:10.3}), але його різкий маневр уже створив небезпеку, а бокове зіткнення зашкодить обом. Тому слід знизити швидкість ({p:12.3}), дати йому завершити перестроювання й відновити безпечну дистанцію.","ru":"Водитель белого автомобиля должен был уступить вам дорогу ({p:10.3}), но его резкий манёвр уже создал опасность, а боковое столкновение навредит обоим. Поэтому следует снизить скорость ({p:12.3}), дать ему завершить перестроение и восстановить безопасную дистанцию."},"ref":["10.3","12.3"],"pic":["img/hsc/35-80-1.jpg"]},{"id":"h35-81","t":"h35","num":"35.81","q":{"uk":"Який найкращий спосіб переконатися, що у вашій сліпій зоні немає транспортних засобів чи велосипедистів?","ru":"Какой лучший способ убедиться, что в вашей слепой зоне нет транспортных средств или велосипедистов?"},"a":[{"uk":"Повернути голову через плече.","ru":"Повернуть голову через плечо.","w":{"uk":"Погляд через плече охоплює «сліпу зону», але не показує, що відбувається далі позаду, — це видно в дзеркалах.","ru":"Взгляд через плечо охватывает «слепую зону», но не показывает, что происходит дальше сзади, — это видно в зеркалах."}},{"uk":"Перевірити дзеркало заднього виду.","ru":"Проверить зеркало заднего вида.","w":{"uk":"Дзеркало не показує «сліпої зони» — тому її так і називають; потрібен ще й погляд через плече.","ru":"Зеркало не показывает «слепую зону» — поэтому её так и называют; нужен ещё и взгляд через плечо."}},{"uk":"Все вищеперераховане.","ru":"Всё вышеперечисленное."}],"c":2,"e":{"uk":"Дзеркала показують простір позаду, але частина простору збоку лишається в «сліпій зоні», яку закриває саме поворот голови через плече. Лише поєднання обох способів дає повну картину й дає змогу переконатися в безпеці маневру ({p:10.1}).","ru":"Зеркала показывают пространство сзади, но часть пространства сбоку остаётся в «слепой зоне», которую закрывает именно поворот головы через плечо. Только сочетание обоих способов даёт полную картину и позволяет убедиться в безопасности манёвра ({p:10.1})."},"ref":["10.1"]},{"id":"h35-82","t":"h35","num":"35.82","q":{"uk":"Вашу голову та груди від удару об приладову панель або лобове скло під час зіткнення тримає:","ru":"Вашу голову и грудь от удара о приборную панель или лобовое стекло при столкновении удерживает:"},"a":[{"uk":"Ремінь безпеки.","ru":"Ремень безопасности."},{"uk":"Підголівник.","ru":"Подголовник.","w":{"uk":"Підголовник розташований позаду голови й захищає шию під час удару ззаду, а від руху вперед не утримує.","ru":"Подголовник расположен позади головы и защищает шею при ударе сзади, а от движения вперёд не удерживает."}}],"c":0,"e":{"uk":"Під час фронтального зіткнення тіло за інерцією рухається вперед, і саме ремінь безпеки утримує його на сидінні, не даючи вдаритися об кермо, панель чи скло ({p:2.3}).","ru":"При фронтальном столкновении тело по инерции движется вперёд, и именно ремень безопасности удерживает его на сиденье, не давая удариться о руль, панель или стекло ({p:2.3})."},"ref":["2.3"]},{"id":"h35-83","t":"h35","num":"35.83","q":{"uk":"Перевірка Ваших «сліпих зон» особливо важлива:","ru":"Проверка ваших «слепых зон» особенно важна:"},"a":[{"uk":"Перед тим, як виконати маневр перестроювання.","ru":"Перед тем как выполнить манёвр перестроения.","w":{"uk":"Перед перестроюванням перевірка справді потрібна, але так само важлива вона під час з'їзду на узбіччя й виїзду з нього.","ru":"Перед перестроением проверка действительно нужна, но так же важна она при съезде на обочину и выезде с неё."}},{"uk":"Перед тим, як з’їхати з проїзної частини на узбіччя.","ru":"Перед тем как съехать с проезжей части на обочину.","w":{"uk":"З'їжджаючи на узбіччя, можна зачепити велосипедиста чи мотоцикліста праворуч, але це лише одна з наведених ситуацій.","ru":"Съезжая на обочину, можно задеть велосипедиста или мотоциклиста справа, но это лишь одна из приведённых ситуаций."}},{"uk":"Перед виїздом з узбіччя на проїзну частину.","ru":"Перед выездом с обочины на проезжую часть.","w":{"uk":"Виїзд з узбіччя справді вимагає перевірки «сліпої зони», але не менш важлива вона й в інших наведених випадках.","ru":"Выезд с обочины действительно требует проверки «слепой зоны», но не менее важна она и в других приведённых случаях."}},{"uk":"У всіх перерахованих вище ситуаціях.","ru":"Во всех перечисленных выше ситуациях."}],"c":3,"e":{"uk":"Будь-яке бокове зміщення — перестроювання, з'їзд на узбіччя чи виїзд з нього — може перетнути траєкторію автомобіля, мотоцикліста чи велосипедиста, якого не видно в дзеркалах. Перед кожним таким маневром водій зобов'язаний переконатися в його безпеці ({p:10.1}), тому «сліпі зони» перевіряють у всіх цих випадках.","ru":"Любое боковое смещение — перестроение, съезд на обочину или выезд с неё — может пересечь траекторию автомобиля, мотоциклиста или велосипедиста, которого не видно в зеркалах. Перед каждым таким манёвром водитель обязан убедиться в его безопасности ({p:10.1}), поэтому «слепые зоны» проверяют во всех этих случаях."},"ref":["10.1"]},{"id":"h35-84","t":"h35","num":"35.84","q":{"uk":"Пішоходи повинні утриматись від переходу проїзної частини, якщо наближається транспортний засіб з проблисковими маячками:","ru":"Пешеходы должны воздержаться от перехода проезжей части, если приближается транспортное средство с проблесковыми маячками:"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"{p:4.13} прямо зобов'язує пішоходів утриматися від переходу: оперативний транспорт може не зупинитися навіть перед пішохідним переходом.","ru":"{p:4.13} прямо обязывает пешеходов воздержаться от перехода: оперативный транспорт может не остановиться даже перед пешеходным переходом."}}],"c":0,"e":{"uk":"За {p:4.13} у разі наближення транспортного засобу з увімкненим проблисковим маячком червоного та (або) синього кольору і (або) спеціальним звуковим сигналом пішоходи повинні утриматися від переходу проїзної частини або негайно залишити її. Такий транспорт виконує невідкладне завдання й може відступати від низки вимог Правил ({p:3.1}).","ru":"По {p:4.13} при приближении транспортного средства с включённым проблесковым маячком красного и (или) синего цвета и (или) специальным звуковым сигналом пешеходы должны воздержаться от перехода проезжей части или немедленно покинуть её. Такой транспорт выполняет неотложное задание и может отступать от ряда требований Правил ({p:3.1})."},"ref":["4.13","3.1"],"pic":["img/hsc/35-84-1.jpg"]},{"id":"h35-85","t":"h35","num":"35.85","q":{"uk":"Що робити, якщо під час руху вночі зустрічний автомобіль рухається із увімкненим дальнім світлом фар та засліплює Вас?","ru":"Что делать, если во время движения ночью встречный автомобиль движется с включённым дальним светом фар и ослепляет вас?"},"a":[{"uk":"Декілька разів швидко розплющити і заплющити очі.","ru":"Несколько раз быстро открыть и закрыть глаза.","w":{"uk":"Заплющуючи очі, ви на ці миті взагалі не бачите дороги, а засліплення від цього не минає.","ru":"Закрывая глаза, вы в эти мгновения вообще не видите дороги, а ослепление от этого не проходит."}},{"uk":"Подивитися на правий край проїжджої частини.","ru":"Посмотреть на правый край проезжей части."},{"uk":"Увімкніть дальнє світло фар.","ru":"Включите дальний свет фар.","w":{"uk":"Дальнє світло у відповідь засліпить зустрічного водія ({p:9.7}, {p:19.2}) — обидва водії майже нічого не бачитимуть, і ризик зіткнення зросте.","ru":"Дальний свет в ответ ослепит встречного водителя ({p:9.7}, {p:19.2}) — оба водителя почти ничего не будут видеть, и риск столкновения возрастёт."}}],"c":1,"e":{"uk":"Погляд на правий край проїзної частини виводить яскраві фари з центру поля зору й водночас дає змогу бачити межу своєї смуги. Швидкість знижують до безпечної, а в разі засліплення зупиняються, не змінюючи смуги, і вмикають аварійну сигналізацію ({p:19.3}).","ru":"Взгляд на правый край проезжей части выводит яркие фары из центра поля зрения и одновременно позволяет видеть границу своей полосы. Скорость снижают до безопасной, а при ослеплении останавливаются, не меняя полосы, и включают аварийную сигнализацию ({p:19.3})."},"ref":["19.3"],"pic":["img/hsc/35-85-1.jpg"]},{"id":"h35-86","t":"h35","num":"35.86","q":{"uk":"Якщо на вашій смузі є зустрічний транспортний засіб чи дозволено подати звуковий сигнал в населеному пункті?","ru":"Если на вашей полосе находится встречное транспортное средство, разрешено ли подать звуковой сигнал в населённом пункте?"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"{p:9.5} дозволяє звуковий сигнал у населеному пункті саме тоді, коли без нього неможливо запобігти ДТП, — а зустрічний автомобіль на вашій смузі створює таку загрозу.","ru":"{p:9.5} разрешает звуковой сигнал в населённом пункте именно тогда, когда без него невозможно предотвратить ДТП, — а встречный автомобиль на вашей полосе создаёт такую угрозу."}}],"c":0,"e":{"uk":"У населених пунктах звуковий сигнал заборонений, крім випадків, коли без нього неможливо запобігти ДТП ({p:9.5}). Зустрічний транспортний засіб на вашій смузі — загроза лобового зіткнення, тож сигнал доречний; водночас слід знижувати швидкість аж до зупинки ({p:12.3}).","ru":"В населённых пунктах звуковой сигнал запрещён, кроме случаев, когда без него невозможно предотвратить ДТП ({p:9.5}). Встречное транспортное средство на вашей полосе — угроза лобового столкновения, поэтому сигнал уместен; одновременно следует снижать скорость вплоть до остановки ({p:12.3})."},"ref":["9.5","12.3"],"pic":["img/hsc/35-86-1.jpg"]},{"id":"h35-87","t":"h35","num":"35.87","q":{"uk":"Використання кондиціонера під час руху впливає на роботу автомобіля, а саме на:","ru":"Использование кондиционера во время движения влияет на работу автомобиля, а именно на:"},"a":[{"uk":"Швидкість автомобіля.","ru":"Скорость автомобиля.","w":{"uk":"Швидкість обирає водій: потрібну швидкість зберігають, трохи сильніше натискаючи на педаль акселератора, тобто ціною більшої витрати палива.","ru":"Скорость выбирает водитель: нужную скорость сохраняют, чуть сильнее нажимая на педаль акселератора, то есть ценой большего расхода топлива."}},{"uk":"Витрату палива.","ru":"Расход топлива."},{"uk":"Стійкість автомобіля під час руху.","ru":"Устойчивость автомобиля во время движения.","w":{"uk":"Стійкість залежить від шин, підвіски, розподілу маси й швидкості, а кондиціонер на них не впливає.","ru":"Устойчивость зависит от шин, подвески, распределения массы и скорости, а кондиционер на них не влияет."}}],"c":1,"e":{"uk":"Компресор кондиціонера обертає двигун, тож частина його потужності витрачається не на рух, а на охолодження салону. Щоб утримувати ту саму швидкість, двигун спалює більше палива — особливо в місті, на малих швидкостях.","ru":"Компрессор кондиционера вращает двигатель, поэтому часть его мощности расходуется не на движение, а на охлаждение салона. Чтобы поддерживать ту же скорость, двигатель сжигает больше топлива — особенно в городе, на малых скоростях."},"pic":["img/hsc/35-87-1.jpg"]},{"id":"h35-88","t":"h35","num":"35.88","q":{"uk":"Чи впливає використання кондиціонера під час руху авто на витрату палива?","ru":"Влияет ли использование кондиционера во время движения автомобиля на расход топлива?"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"Увімкнений кондиціонер — додаткове навантаження на двигун, і витрата палива помітно зростає, особливо в міському русі.","ru":"Включённый кондиционер — дополнительная нагрузка на двигатель, и расход топлива заметно растёт, особенно в городском движении."}}],"c":0,"e":{"uk":"Компресор кондиціонера приводиться від двигуна й відбирає частину його потужності. Щоб їхати з тією самою швидкістю, двигун мусить спалювати більше палива.","ru":"Компрессор кондиционера приводится от двигателя и отбирает часть его мощности. Чтобы ехать с той же скоростью, двигатель вынужден сжигать больше топлива."},"pic":["img/hsc/35-88-1.jpg"]},{"id":"h35-89","t":"h35","num":"35.89","q":{"uk":"З метою належного прогнозування дорожньої обстановки і безпечного подальшого руху, Ви повинні більше розподілити увагу погляд на:","ru":"Для правильного прогнозирования дорожной обстановки и безопасного дальнейшего движения вы должны больше направлять внимание (взгляд) на:"},"a":[{"uk":"Точці А.","ru":"Точку A."},{"uk":"Точці В.","ru":"Точку B.","w":{"uk":"Дивлячись на узбіччя просто перед автомобілем (точка B), водій помічатиме небезпеку надто пізно — коли до неї лишаться лічені метри.","ru":"Глядя на обочину прямо перед автомобилем (точка B), водитель будет замечать опасность слишком поздно — когда до неё останутся считаные метры."}}],"c":0,"e":{"uk":"Погляд, спрямований далеко вперед (точка A), дає змогу завчасно помітити транспорт, пішоходів, перешкоди й зміну напрямку дороги та мати запас часу на реакцію. Близьку ділянку біля капота водій і так охоплює периферійним зором; стежити за обстановкою на дорозі він зобов'язаний за {p:2.3}.","ru":"Взгляд, направленный далеко вперёд (точка A), позволяет заблаговременно заметить транспорт, пешеходов, препятствия и изменение направления дороги и иметь запас времени на реакцию. Близкий участок у капота водитель и так охватывает периферийным зрением; следить за обстановкой на дороге он обязан по {p:2.3}."},"ref":["2.3"],"pic":["img/hsc/35-89-1.jpg"]},{"id":"h35-90","t":"h35","num":"35.90","q":{"uk":"Чи дозволено Вам здійснити обгін у даній дорожній ситуації?","ru":"Разрешено ли вам выполнить обгон в данной дорожной ситуации?"},"a":[{"uk":"Заборонено.","ru":"Запрещено."},{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"До пішохідного переходу лишається менше ніж 50 м, далі — перехрестя, а зустрічна смуга зайнята, тож обгін тут заборонений ({p:14.6}) і небезпечний.","ru":"До пешеходного перехода остаётся меньше 50 м, дальше — перекрёсток, а встречная полоса занята, поэтому обгон здесь запрещён ({p:14.6}) и опасен."}}],"c":0,"e":{"uk":"Попереду — пішохідний перехід і перехрестя зі світлофором, а зустрічною смугою рухаються автомобілі. Обгін заборонено на перехресті та ближче ніж за 50 м перед пішохідним переходом у населеному пункті ({p:14.6}).","ru":"Впереди — пешеходный переход и перекрёсток со светофором, а по встречной полосе движутся автомобили. Обгон запрещён на перекрёстке и ближе чем за 50 м перед пешеходным переходом в населённом пункте ({p:14.6})."},"ref":["14.6"],"pic":["img/hsc/35-90-1.jpg"]},{"id":"h35-91","t":"h35","num":"35.91","q":{"uk":"Садити дитину в авто потрібно з боку:","ru":"Сажать ребёнка в автомобиль нужно со стороны:"},"a":[{"uk":"Проїзної частини.","ru":"Проезжей части.","w":{"uk":"З боку проїзної частини дорослий стоїть спиною до транспорту, а дитина може вирватися на дорогу; відчинені двері перекривають смугу.","ru":"Со стороны проезжей части взрослый стоит спиной к транспорту, а ребёнок может вырваться на дорогу; открытые двери перекрывают полосу."}},{"uk":"Тротуару.","ru":"Тротуара."},{"uk":"Не має значення.","ru":"Не имеет значения.","w":{"uk":"Це має значення: лише посадка з тротуару не виводить дитину й дорослого на проїзну частину під колеса автомобілів.","ru":"Это имеет значение: только посадка с тротуара не выводит ребёнка и взрослого на проезжую часть под колёса автомобилей."}}],"c":1,"e":{"uk":"З боку тротуару дорослий і дитина не опиняються на проїзній частині поруч із транспортом, що проїжджає, а відчинені двері не заважають рухові. Пасажирам дозволено сідати й виходити саме з тротуару чи узбіччя ({p:5.1}).","ru":"Со стороны тротуара взрослый и ребёнок не оказываются на проезжей части рядом с проезжающим транспортом, а открытые двери не мешают движению. Пассажирам разрешено садиться и выходить именно с тротуара или обочины ({p:5.1})."},"ref":["5.1"],"pic":["img/hsc/35-91-1.jpg"]},{"id":"h35-92","t":"h35","num":"35.92","q":{"uk":"Чи потрібно у даному випадку зменшити швидкість?","ru":"Нужно ли в данном случае снизить скорость?"},"a":[{"uk":"Потрібно.","ru":"Нужно."},{"uk":"Не потрібно.","ru":"Не нужно.","w":{"uk":"На звичайній швидкості водій не встигне зупинитися перед автомобілем чи перешкодою, що раптово з'явиться з туману.","ru":"На обычной скорости водитель не успеет остановиться перед автомобилем или препятствием, внезапно появившимся из тумана."}},{"uk":"Не потрібно, якщо водії, що рухаються попереду не зменшують.","ru":"Не нужно, если водители, движущиеся впереди, не снижают её.","w":{"uk":"Безпечну швидкість кожен водій обирає сам за фактичною видимістю ({p:12.2}); те, що інші не пригальмовують, не робить їхню швидкість безпечною.","ru":"Безопасную скорость каждый водитель выбирает сам по фактической видимости ({p:12.2}); то, что другие не притормаживают, не делает их скорость безопасной."}}],"c":0,"e":{"uk":"Туман різко зменшує видимість, тож швидкість має бути такою, щоб зупинитися в межах видимої ділянки дороги ({p:12.2}). До того ж у тумані відстані до інших автомобілів здаються більшими, ніж насправді, тому потрібна й більша дистанція.","ru":"Туман резко уменьшает видимость, поэтому скорость должна быть такой, чтобы остановиться в пределах видимого участка дороги ({p:12.2}). К тому же в тумане расстояния до других автомобилей кажутся больше, чем на самом деле, поэтому нужна и большая дистанция."},"ref":["12.2"],"pic":["img/hsc/35-92-1.jpg"]},{"id":"h35-93","t":"h35","num":"35.93","q":{"uk":"Чи правильно в даному випадку водій відрегулював положення сидіння та рульового колеса перед початком руху?","ru":"Правильно ли в данном случае водитель отрегулировал положение сиденья и рулевого колеса перед началом движения?"},"a":[{"uk":"Правильно.","ru":"Правильно.","w":{"uk":"Сидіння присунуте надто близько: лікті зігнуті майже під прямим кутом, а груди майже біля керма — це небезпечно в разі спрацювання подушки безпеки.","ru":"Сиденье придвинуто слишком близко: локти согнуты почти под прямым углом, а грудь почти у руля — это опасно при срабатывании подушки безопасности."}},{"uk":"Неправильно.","ru":"Неправильно."}],"c":1,"e":{"uk":"Водій сидить надто близько до керма: руки сильно зігнуті, корпус нахилений уперед, спина не спирається на спинку сидіння. Так важко швидко й точно повертати кермо, а подушка безпеки, що розкривається, може травмувати груди й обличчя; правильно — спина на спинці, а зап'ястя витягнутих рук лежать на верхній частині керма.","ru":"Водитель сидит слишком близко к рулю: руки сильно согнуты, корпус наклонён вперёд, спина не опирается на спинку сиденья. Так трудно быстро и точно поворачивать руль, а раскрывающаяся подушка безопасности может травмировать грудь и лицо; правильно — спина на спинке, а запястья вытянутых рук лежат на верхней части руля."},"pic":["img/hsc/35-93-1.jpg"]},{"id":"h35-94","t":"h35","num":"35.94","q":{"uk":"Чи комфортна та правильна посадка водія?","ru":"Удобна и правильна ли посадка водителя?"},"a":[{"uk":"Так.","ru":"Да.","w":{"uk":"Посадка напружена й неправильна: спина має спиратися на спинку сидіння, а руки — бути злегка зігнутими й лежати на кермі без напруження.","ru":"Посадка напряжённая и неправильная: спина должна опираться на спинку сиденья, а руки — быть слегка согнутыми и лежать на руле без напряжения."}},{"uk":"Ні.","ru":"Нет."}],"c":1,"e":{"uk":"Водій «навис» над кермом: спина відірвана від спинки, руки зігнуті майже під прямим кутом. У такій позі швидко втомлюються плечі й спина, важко точно керувати, а подушка безпеки, що розкривається, може травмувати водія.","ru":"Водитель «навис» над рулём: спина оторвана от спинки, руки согнуты почти под прямым углом. В такой позе быстро устают плечи и спина, трудно точно управлять, а раскрывающаяся подушка безопасности может травмировать водителя."},"pic":["img/hsc/35-94-1.jpg"]},{"id":"h35-95","t":"h35","num":"35.95","q":{"uk":"Чи необхідно збільшити потужність склоочисника у разі випередження вантажного автомобіля під час невеликого дощу?","ru":"Нужно ли увеличить скорость работы стеклоочистителя при опережении грузового автомобиля во время небольшого дождя?"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"На звичайній швидкості склоочисник не встигатиме прибирати бризки з-під коліс вантажівки, і на кілька секунд скло стане майже непрозорим.","ru":"На обычной скорости стеклоочиститель не будет успевать убирать брызги из-под колёс грузовика, и на несколько секунд стекло станет почти непрозрачным."}},{"uk":"Склоочисник краще вимкнути під час випередження.","ru":"Стеклоочиститель лучше выключить во время опережения.","w":{"uk":"Вимкнений склоочисник залишить скло залитим брудною водою саме тоді, коли ви поруч із вантажівкою й маєте бачити дорогу якнайкраще.","ru":"Выключенный стеклоочиститель оставит стекло залитым грязной водой именно тогда, когда вы рядом с грузовиком и должны видеть дорогу как можно лучше."}}],"c":0,"e":{"uk":"Колеса вантажівки здіймають з мокрої дороги хмару бризок, яка під час випередження вмить заливає лобове скло. Щоб не втратити огляду в найнебезпечніший момент — поруч із великим автомобілем, — швидкість роботи склоочисника збільшують завчасно, ще до початку маневру.","ru":"Колёса грузовика поднимают с мокрой дороги облако брызг, которое при опережении мгновенно заливает лобовое стекло. Чтобы не потерять обзор в самый опасный момент — рядом с большим автомобилем, — скорость работы стеклоочистителя увеличивают заранее, ещё до начала манёвра."},"pic":["img/hsc/35-95-1.jpg"]},{"id":"h35-96","t":"h35","num":"35.96","q":{"uk":"Зоною потенційної небезпеки для Вас, як водія даного транспортного засобу, є:","ru":"Зоной потенциальной опасности для вас как водителя данного транспортного средства является:"},"a":[{"uk":"Зона А.","ru":"Зона A.","w":{"uk":"Зона A — ліве зовнішнє дзеркало: у нього стежать за обстановкою позаду, але на вашій траєкторії попереду небезпека виникне не там.","ru":"Зона A — левое наружное зеркало: в него следят за обстановкой сзади, но на вашей траектории впереди опасность возникнет не там."}},{"uk":"Зона В.","ru":"Зона B.","w":{"uk":"Сам автобус у зоні B добре видно, і його рух передбачуваний; небезпечне те, що він закриває, — ділянка поруч із ним (зона C).","ru":"Сам автобус в зоне B хорошо виден, и его движение предсказуемо; опасно то, что он закрывает, — участок рядом с ним (зона C)."}},{"uk":"Зона C.","ru":"Зона C."}],"c":2,"e":{"uk":"Автобус закриває огляд, і з-за нього в зоні C просто на вашу смугу може раптово вийти пішохід, що перетинає дорогу перед автобусом. Цю ділянку треба тримати в полі зору й бути готовим знизити швидкість аж до зупинки ({p:12.3}).","ru":"Автобус закрывает обзор, и из-за него в зоне C прямо на вашу полосу может внезапно выйти пешеход, переходящий дорогу перед автобусом. Этот участок нужно держать в поле зрения и быть готовым снизить скорость вплоть до остановки ({p:12.3})."},"ref":["12.3"],"pic":["img/hsc/35-96-1.jpg"]},{"id":"h35-97","t":"h35","num":"35.97","q":{"uk":"Ремінь безпеки є обов’язковим для вагітних?","ru":"Является ли ремень безопасности обязательным для беременных?"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"Вагітність не звільняє від обов'язку пристібатися: без ременя жінка в разі зіткнення вдариться об кермо чи панель, а це для плоду значно небезпечніше, ніж правильно прокладений ремінь.","ru":"Беременность не освобождает от обязанности пристёгиваться: без ремня женщина при столкновении ударится о руль или панель, а это для плода значительно опаснее, чем правильно проложенный ремень."}}],"c":0,"e":{"uk":"Ремінь безпеки захищає в разі зіткнення і жінку, і майбутню дитину, тому вагітні пристібаються обов'язково ({p:2.3}). Поясну лямку прокладають якомога нижче — під животом, по стегнах, а діагональну — між грудьми й збоку від живота.","ru":"Ремень безопасности защищает при столкновении и женщину, и будущего ребёнка, поэтому беременные пристёгиваются обязательно ({p:2.3}). Поясную лямку прокладывают как можно ниже — под животом, по бёдрам, а диагональную — между грудью и сбоку от живота."},"ref":["2.3"],"pic":["img/hsc/35-97-1.jpg"]},{"id":"h35-98","t":"h35","num":"35.98","q":{"uk":"Водій транспортного засобу, наближаючись до пішоходів, які перетинають автомобільну дорогу за межами наземного пішохідного переходу, повинен:","ru":"Водитель транспортного средства, приближаясь к пешеходам, пересекающим автомобильную дорогу вне наземного пешеходного перехода, должен:"},"a":[{"uk":"Негайно зменшити швидкість і бути готовим до повної зупинки.","ru":"Немедленно снизить скорость и быть готовым к полной остановке."},{"uk":"Подати звуковий сигнал.","ru":"Подать звуковой сигнал.","w":{"uk":"Звуковий сигнал у населеному пункті дозволений лише для запобігання ДТП ({p:9.5}), а наляканий пішохід може завмерти чи кинутися вперед — і стати ще непередбачуванішим.","ru":"Звуковой сигнал в населённом пункте разрешён только для предотвращения ДТП ({p:9.5}), а испуганный пешеход может замереть или броситься вперёд — и стать ещё непредсказуемее."}},{"uk":"Повідомити уповноважений підрозділ Національної поліції.","ru":"Сообщить в уполномоченное подразделение Национальной полиции.","w":{"uk":"Повідомлення поліції не усуває небезпеки наїзду; обов'язок водія тут — знизити швидкість і не допустити ДТП.","ru":"Сообщение в полицию не устраняет опасности наезда; обязанность водителя здесь — снизить скорость и не допустить ДТП."}},{"uk":"Відповідь 1 та 3.","ru":"Ответы 1 и 3.","w":{"uk":"Знижувати швидкість справді треба, але повідомляти поліцію в цій ситуації водій не зобов'язаний.","ru":"Снижать скорость действительно нужно, но сообщать в полицию в этой ситуации водитель не обязан."}}],"c":0,"e":{"uk":"Пішоходи, що переходять дорогу в недозволеному місці, — це небезпека для руху, і водій зобов'язаний негайно знижувати швидкість аж до зупинки ({p:12.3}). Водії мають бути особливо уважними до пішоходів ({p:1.7}), навіть якщо ті порушують Правила.","ru":"Пешеходы, переходящие дорогу в неположенном месте, — это опасность для движения, и водитель обязан немедленно снижать скорость вплоть до остановки ({p:12.3}). Водители должны быть особенно внимательны к пешеходам ({p:1.7}), даже если те нарушают Правила."},"ref":["12.3","1.7"],"pic":["img/hsc/35-98-1.jpg"]},{"id":"h35-99","t":"h35","num":"35.99","q":{"uk":"У мокру погоду або в дощ гальмовий шлях транспортного засобу збільшується:","ru":"В сырую погоду или в дождь тормозной путь транспортного средства увеличивается:"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"Мокре покриття має гірше зчеплення з шинами, тож автомобіль гальмує повільніше, і гальмовий шлях подовжується.","ru":"Мокрое покрытие имеет худшее сцепление с шинами, поэтому автомобиль тормозит медленнее, и тормозной путь удлиняется."}}],"c":0,"e":{"uk":"Вода між шиною й дорогою діє як мастило й погіршує зчеплення, тому на мокрому покритті гальмовий шлях помітно довший, ніж на сухому. Тож у дощ знижують швидкість і збільшують дистанцію.","ru":"Вода между шиной и дорогой действует как смазка и ухудшает сцепление, поэтому на мокром покрытии тормозной путь заметно длиннее, чем на сухом. Поэтому в дождь снижают скорость и увеличивают дистанцию."},"pic":["img/hsc/35-99-1.jpg"]},{"id":"h35-100","t":"h35","num":"35.100","q":{"uk":"Водій вантажного автомобіля, не враховуючи дорожньої обстановки почав рух, Ви повинні:","ru":"Водитель грузового автомобиля, не учитывая дорожную обстановку, начал движение. Вы должны:"},"a":[{"uk":"Подати звуковий сигнал та пришвидшитись.","ru":"Подать звуковой сигнал и ускориться.","w":{"uk":"Пришвидшившись, ви скоротите собі час і відстань для реакції, а звуковий сигнал не змусить вантажівку, що вже виїхала, миттєво зупинитися.","ru":"Ускорившись, вы сократите себе время и расстояние для реакции, а звуковой сигнал не заставит уже выехавший грузовик мгновенно остановиться."}},{"uk":"Продовжувати рух, тому що маєте перевагу в русі.","ru":"Продолжать движение, так как имеете преимущество в движении.","w":{"uk":"Перевага в русі не звільняє від обов'язку запобігти ДТП: {p:12.3} вимагає знижувати швидкість аж до зупинки, щойно виникла небезпека.","ru":"Преимущество в движении не освобождает от обязанности предотвратить ДТП: {p:12.3} требует снижать скорость вплоть до остановки, как только возникла опасность."}},{"uk":"Зменшити швидкість або зупинитися.","ru":"Снизить скорость или остановиться."}],"c":2,"e":{"uk":"Вантажівка виїжджає на дорогу й створює небезпеку для руху. Навіть маючи перевагу, водій за {p:12.3} зобов'язаний негайно знижувати швидкість аж до зупинки: важкий автомобіль не може швидко звільнити смугу, а на мокрій дорозі ваш гальмовий шлях довший.","ru":"Грузовик выезжает на дорогу и создаёт опасность для движения. Даже имея преимущество, водитель по {p:12.3} обязан немедленно снижать скорость вплоть до остановки: тяжёлый автомобиль не может быстро освободить полосу, а на мокрой дороге ваш тормозной путь длиннее."},"ref":["12.3"],"pic":["img/hsc/35-100-1.jpg"]},{"id":"h35-101","t":"h35","num":"35.101","q":{"uk":"Чи потрібно в даному випадку зменшити швидкість або зупинитися, якщо Ви рухаєтесь прямо по головній дорозі:","ru":"Нужно ли в данном случае снизить скорость или остановиться, если вы движетесь прямо по главной дороге:"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"Розраховувати, що вантажівка встигне зупинитися чи звільнити смугу, не можна: вона вже на вашій траєкторії, а дорога мокра й гальмовий шлях довший.","ru":"Рассчитывать, что грузовик успеет остановиться или освободить полосу, нельзя: он уже на вашей траектории, а дорога мокрая и тормозной путь длиннее."}}],"c":0,"e":{"uk":"Вантажівка вже виїжджає на дорогу, не пропускаючи вас, — це небезпека для руху. Перевага на головній дорозі не звільняє від обов'язку запобігти ДТП: за {p:12.3} треба негайно знижувати швидкість аж до зупинки.","ru":"Грузовик уже выезжает на дорогу, не пропуская вас, — это опасность для движения. Преимущество на главной дороге не освобождает от обязанности предотвратить ДТП: по {p:12.3} нужно немедленно снижать скорость вплоть до остановки."},"ref":["12.3"],"pic":["img/hsc/35-101-1.jpg"]},{"id":"h35-102","t":"h35","num":"35.102","q":{"uk":"Під час руху водію транспортного засобу дозволяється використовувати свій смартфон для використання навігації (GPS):","ru":"Во время движения водителю транспортного средства разрешается использовать свой смартфон для навигации (GPS):"},"a":[{"uk":"Тримаючи у руці (за винятком водіїв оперативних транспортних засобів під час виконання ними невідкладного службового завдання).","ru":"Держа в руке (за исключением водителей оперативных транспортных средств во время выполнения ими неотложного служебного задания).","w":{"uk":"Тримати телефон у руці під час руху заборонено ({p:2.9}): одна рука зайнята, а погляд відривається від дороги.","ru":"Держать телефон в руке во время движения запрещено ({p:2.9}): одна рука занята, а взгляд отрывается от дороги."}},{"uk":"Закріпивши на приладовій панелі (за винятком водіїв оперативних транспортних засобів під час виконання ними невідкладного службового завдання).","ru":"Закрепив на приборной панели (за исключением водителей оперативных транспортных средств во время выполнения ими неотложного служебного задания)."}],"c":1,"e":{"uk":"{p:2.9} забороняє під час руху користуватися засобами зв'язку, **тримаючи їх у руці**. Смартфон-навігатор закріплюють у тримачі на приладовій панелі так, щоб він не закривав огляду, — тоді обидві руки лишаються на кермі.","ru":"{p:2.9} запрещает во время движения пользоваться средствами связи, **держа их в руке**. Смартфон-навигатор закрепляют в держателе на приборной панели так, чтобы он не закрывал обзор, — тогда обе руки остаются на руле."},"ref":["2.9"],"pic":["img/hsc/35-102-1.jpg"]},{"id":"h35-103","t":"h35","num":"35.103","q":{"uk":"Водій транспортного засобу для здійснення посадки (висадки) пасажирів повинен:","ru":"Водитель транспортного средства для осуществления посадки (высадки) пассажиров должен:"},"a":[{"uk":"Користуватися краєм проїзної частини, але не з боку суміжної смуги для руху.","ru":"Пользоваться краем проезжей части, но не со стороны смежной полосы для движения.","w":{"uk":"Посадка з краю проїзної частини — лише частина вимог: ще треба переконатися в дзеркалах, що відчинені двері нікому не загрожують.","ru":"Посадка с края проезжей части — лишь часть требований: ещё нужно убедиться в зеркалах, что открытые двери никому не угрожают."}},{"uk":"Переконатись у безпеці пасажирів перед виходом з транспортного засобу, скориставшись дзеркалами заднього виду.","ru":"Убедиться в безопасности пассажиров перед выходом из транспортного средства, воспользовавшись зеркалами заднего вида.","w":{"uk":"Перевірка в дзеркалах потрібна, але й місце посадки має бути безпечним — з краю проїзної частини, а не з боку суміжної смуги.","ru":"Проверка в зеркалах нужна, но и место посадки должно быть безопасным — с края проезжей части, а не со стороны смежной полосы."}},{"uk":"Відповідь 1 і 2.","ru":"Ответ 1 и 2."}],"c":2,"e":{"uk":"Пасажири сідають і виходять з тротуару, узбіччя чи краю проїзної частини, але не з боку суміжної смуги, де рухається транспорт ({p:5.1}). Перед тим як вони відчинять двері, водій перевіряє в дзеркалах, чи не наближається велосипедист або автомобіль: відчиняти двері, якщо це загрожує безпеці, заборонено ({p:15.13}).","ru":"Пассажиры садятся и выходят с тротуара, обочины или края проезжей части, но не со стороны смежной полосы, где движется транспорт ({p:5.1}). Прежде чем они откроют двери, водитель проверяет в зеркалах, не приближается ли велосипедист или автомобиль: открывать двери, если это угрожает безопасности, запрещено ({p:15.13})."},"ref":["5.1","15.13"],"pic":["img/hsc/35-103-1.jpg"]},{"id":"h35-104","t":"h35","num":"35.104","q":{"uk":"Чи правильно в даному випадку водій транспортного засобу закріпив ремінь безпеки?","ru":"Правильно ли в данном случае водитель транспортного средства закрепил ремень безопасности?"},"a":[{"uk":"Так, ремінь закріплений правильно.","ru":"Да, ремень закреплён правильно.","w":{"uk":"Лямка не лежить на плечі й грудях, тож у разі зіткнення ремінь не втримає тулуб і голову від удару об кермо.","ru":"Лямка не лежит на плече и груди, поэтому при столкновении ремень не удержит туловище и голову от удара о руль."}},{"uk":"Ні, ремінь закріплений неправильно.","ru":"Нет, ремень закреплён неправильно."}],"c":1,"e":{"uk":"Діагональна лямка має проходити через середину плеча й груди, а поясна — низько по стегнах. Якщо лямка проходить збоку, під рукою, то під час зіткнення верхня частина тіла не утримується й рухається вперед, а ремінь тисне на ребра й органи черевної порожнини.","ru":"Диагональная лямка должна проходить через середину плеча и грудь, а поясная — низко по бёдрам. Если лямка проходит сбоку, под рукой, то при столкновении верхняя часть тела не удерживается и движется вперёд, а ремень давит на рёбра и органы брюшной полости."},"ref":["2.3"],"pic":["img/hsc/35-104-1.jpg"]},{"id":"h35-105","t":"h35","num":"35.105","q":{"uk":"У наведеній ситуації Ви, наближаючись до перехрестя, повинні:","ru":"В приведённой ситуации вы, приближаясь к перекрёстку, должны:"},"a":[{"uk":"Подати звуковий сигнал, щоб водій транспортного засобу, який знаходиться позаду пригальмував.","ru":"Подать звуковой сигнал, чтобы водитель транспортного средства, находящегося сзади, притормозил.","w":{"uk":"Звуковий сигнал у населеному пункті дозволений лише для запобігання ДТП ({p:9.5}); водієві позаду він нічого не підкаже, а велосипедиста може налякати.","ru":"Звуковой сигнал в населённом пункте разрешён только для предотвращения ДТП ({p:9.5}); водителю сзади он ничего не подскажет, а велосипедиста может напугать."}},{"uk":"Безпечно об'їхати велосипедиста.","ru":"Безопасно объехать велосипедиста.","w":{"uk":"Об'їжджаючи велосипедиста, ви не даєте йому дороги, хоча {p:16.5} цього вимагає, а його раптовий маневр може закінчитися наїздом.","ru":"Объезжая велосипедиста, вы не уступаете ему дорогу, хотя {p:16.5} этого требует, а его внезапный манёвр может закончиться наездом."}},{"uk":"Пригальмувати та дати можливість велосипедисту безпечно закінчити перетин перехрестя.","ru":"Притормозить и дать велосипедисту возможность безопасно закончить пересечение перекрёстка."}],"c":2,"e":{"uk":"Велосипедист завершує рух через перехрестя, і навіть на зелений сигнал водій зобов'язаний дати йому дорогу ({p:16.5}). До велосипедистів водії мають бути особливо уважними ({p:1.7}): він може похитнутися чи змінити траєкторію, тож безпечніше пригальмувати й дочекатися, поки він проїде.","ru":"Велосипедист завершает движение через перекрёсток, и даже на зелёный сигнал водитель обязан уступить ему дорогу ({p:16.5}). К велосипедистам водители должны быть особенно внимательны ({p:1.7}): он может покачнуться или изменить траекторию, поэтому безопаснее притормозить и дождаться, пока он проедет."},"ref":["16.5","1.7"],"pic":["img/hsc/35-105-1.jpg"]},{"id":"h35-106","t":"h35","num":"35.106","q":{"uk":"Чи може ремінь безпеки ефективно спрацювати захистити лежачого пасажира?","ru":"Может ли ремень безопасности эффективно сработать и защитить лежащего пассажира?"},"a":[{"uk":"Так, може.","ru":"Да, может.","w":{"uk":"Ремінь розрахований на людину, що сидить: у лежачому положенні тіло «пірнає» під поясну лямку, а діагональна опиняється біля шиї.","ru":"Ремень рассчитан на сидящего человека: в лежачем положении тело «ныряет» под поясную лямку, а диагональная оказывается у шеи."}},{"uk":"Ні.","ru":"Нет."}],"c":1,"e":{"uk":"Коли спинку сидіння відкинуто, діагональна лямка відходить від грудей, а тіло під час зіткнення ковзає вперед під поясною лямкою. Ремінь тоді тисне на шию й живіт і може сам спричинити тяжкі травми, тому в дорозі спинку тримають майже вертикально.","ru":"Когда спинка сиденья откинута, диагональная лямка отходит от груди, а тело при столкновении скользит вперёд под поясной лямкой. Ремень тогда давит на шею и живот и может сам причинить тяжёлые травмы, поэтому в дороге спинку держат почти вертикально."},"pic":["img/hsc/35-106-1.jpg"]},{"id":"h35-107","t":"h35","num":"35.107","q":{"uk":"Якщо під час тривалої подорожі виникла необхідність змінити водія, необхідно налаштувати, у тому числі:","ru":"Если во время длительной поездки возникла необходимость сменить водителя, необходимо настроить, в том числе:"},"a":[{"uk":"Сидіння та дзеркала.","ru":"Сиденье и зеркала."},{"uk":"Тільки сидіння.","ru":"Только сиденье.","w":{"uk":"Після регулювання сидіння положення очей нового водія інше, і дзеркала, налаштовані попереднім водієм, показуватимуть не те, що потрібно.","ru":"После регулировки сиденья положение глаз нового водителя другое, и зеркала, настроенные предыдущим водителем, будут показывать не то, что нужно."}},{"uk":"Тільки дзеркала.","ru":"Только зеркала.","w":{"uk":"Самих дзеркал мало: якщо не налаштувати сидіння, новий водій не зможе зручно дотягуватися до педалей і керма.","ru":"Одних зеркал мало: если не настроить сиденье, новый водитель не сможет удобно дотягиваться до педалей и руля."}}],"c":0,"e":{"uk":"У кожного водія свій зріст і будова тіла. Спершу під себе налаштовують сидіння (а також кермову колонку й підголівник), а вже потім дзеркала, бо огляд у них залежить від положення голови.","ru":"У каждого водителя свой рост и телосложение. Сначала под себя настраивают сиденье (а также рулевую колонку и подголовник), а уже потом зеркала, потому что обзор в них зависит от положения головы."},"pic":["img/hsc/35-107-1.jpg"]},{"id":"h35-108","t":"h35","num":"35.108","q":{"uk":"Як має діяти водій транспортного засобу у разі сонячного засліплення?","ru":"Как должен действовать водитель транспортного средства при ослеплении солнцем?"},"a":[{"uk":"Ввімкнути аварійну сигналізацію і, не змінюючи смуги руху, зменшити швидкість і зупинитися.","ru":"Включить аварийную сигнализацию и, не меняя полосы движения, снизить скорость и остановиться."},{"uk":"Подаючи звуковий сигнал, зупинитися на узбіччі.","ru":"Подавая звуковой сигнал, остановиться на обочине.","w":{"uk":"З'їжджаючи наосліп на узбіччя, можна наїхати на пішохода, велосипедиста чи автомобіль, що стоїть; звуковий сигнал не замінить огляду.","ru":"Съезжая вслепую на обочину, можно наехать на пешехода, велосипедиста или стоящий автомобиль; звуковой сигнал не заменит обзора."}}],"c":0,"e":{"uk":"Засліплений водій не бачить дороги, тож будь-яке бокове зміщення може закінчитися зіткненням з тим, кого він не помітив. Діють так само, як у разі засліплення фарами: зупиняються, не змінюючи смуги, і вмикають аварійну сигналізацію, щоб попередити водіїв позаду ({p:19.3}, {p:9.9}).","ru":"Ослеплённый водитель не видит дороги, поэтому любое боковое смещение может закончиться столкновением с тем, кого он не заметил. Действуют так же, как при ослеплении фарами: останавливаются, не меняя полосы, и включают аварийную сигнализацию, чтобы предупредить водителей сзади ({p:19.3}, {p:9.9})."},"ref":["19.3","9.9"],"pic":["img/hsc/35-108-1.jpg"]},{"id":"h35-109","t":"h35","num":"35.109","q":{"uk":"У разі аварії цей водій буде захищений ременем безпеки?","ru":"В случае аварии будет ли этот водитель защищён ремнём безопасности?"},"a":[{"uk":"Так.","ru":"Да.","w":{"uk":"Застебнутий так ремінь не втримає тулуб і голову: водій ударяється об кермо, а лямка травмує живіт.","ru":"Застёгнутый так ремень не удержит туловище и голову: водитель ударяется о руль, а лямка травмирует живот."}},{"uk":"Ні.","ru":"Нет."}],"c":1,"e":{"uk":"Діагональна лямка проходить не через плече й груди, а під рукою, поперек живота. Під час зіткнення верхня частина тіла не утримується й летить уперед на кермо, а ремінь тисне на ребра й органи черевної порожнини; правильно — лямка через середину плеча й груди, поясна — низько по стегнах.","ru":"Диагональная лямка проходит не через плечо и грудь, а под рукой, поперёк живота. При столкновении верхняя часть тела не удерживается и летит вперёд на руль, а ремень давит на рёбра и органы брюшной полости; правильно — лямка через середину плеча и груди, поясная — низко по бёдрам."},"ref":["2.3"],"pic":["img/hsc/35-109-1.jpg"]},{"id":"h35-110","t":"h35","num":"35.110","q":{"uk":"Чи буде тривала розмова пасажира з водієм заважати водієві керувати транспортним засобом?","ru":"Будет ли длительный разговор пассажира с водителем мешать водителю управлять транспортным средством?"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні, оскільки розмова ніяк не обмежує оглядовість водієві.","ru":"Нет, поскольку разговор никак не ограничивает обзор водителя.","w":{"uk":"Розмова справді не закриває огляду, але відволікає увагу: водій дивиться, та не завжди помічає небезпеку.","ru":"Разговор действительно не закрывает обзор, но отвлекает внимание: водитель смотрит, но не всегда замечает опасность."}}],"c":0,"e":{"uk":"Розмова забирає частину уваги: водій повертається до співрозмовника, гірше стежить за дорогою й пізніше реагує на небезпеку. Водій не повинен відволікатися від керування ({p:2.3}), а пасажирам заборонено відвертати його увагу ({p:5.3}).","ru":"Разговор забирает часть внимания: водитель поворачивается к собеседнику, хуже следит за дорогой и позже реагирует на опасность. Водитель не должен отвлекаться от управления ({p:2.3}), а пассажирам запрещено отвлекать его внимание ({p:5.3})."},"ref":["2.3","5.3"],"pic":["img/hsc/35-110-1.jpg"]},{"id":"h35-111","t":"h35","num":"35.111","q":{"uk":"Наближаючись до перехрестя, де світлофор працює в режимі миготіння жовтого сигналу водій легкового автомобіля повинен:","ru":"Приближаясь к перекрёстку, где светофор работает в режиме мигания жёлтого сигнала, водитель легкового автомобиля должен:"},"a":[{"uk":"Знизити швидкість та бути готовим до повної зупинки.","ru":"Снизить скорость и быть готовым к полной остановке."},{"uk":"Перетнути перехрестя не зменшуючи швидкості.","ru":"Пересечь перекрёсток, не снижая скорости.","w":{"uk":"Миготливий жовтий не дає переваги: перехрестя нерегульоване, і без зниження швидкості ви не встигнете пропустити тих, кому мусите дати дорогу.","ru":"Мигающий жёлтый не даёт преимущества: перекрёсток нерегулируемый, и без снижения скорости вы не успеете пропустить тех, кому обязаны уступить дорогу."}},{"uk":"Збільшити швидкість для швидкого перетину перехрестя.","ru":"Увеличить скорость для быстрого пересечения перекрёстка.","w":{"uk":"Збільшуючи швидкість на небезпечному перехресті, ви скорочуєте собі час на реакцію й подовжуєте гальмовий шлях.","ru":"Увеличивая скорость на опасном перекрёстке, вы сокращаете себе время на реакцию и удлиняете тормозной путь."}}],"c":0,"e":{"uk":"Жовтий миготливий сигнал дозволяє рух, але попереджає про небезпечне нерегульоване перехрестя ({p:8.7}). Черговість проїзду тут визначають знаки пріоритету та правила проїзду нерегульованих перехресть ({p:16.1}), тож, можливо, доведеться дати дорогу, — під'їжджати слід на зниженій швидкості.","ru":"Жёлтый мигающий сигнал разрешает движение, но предупреждает об опасном нерегулируемом перекрёстке ({p:8.7}). Очерёдность проезда здесь определяют знаки приоритета и правила проезда нерегулируемых перекрёстков ({p:16.1}), поэтому, возможно, придётся уступить дорогу, — подъезжать следует на сниженной скорости."},"ref":["8.7","16.1"],"pic":["img/hsc/35-111-1.jpg"]},{"id":"h35-112","t":"h35","num":"35.112","q":{"uk":"Гальмівний шлях змінюється в залежності від:","ru":"Тормозной путь изменяется в зависимости от:"},"a":[{"uk":"Швидкості руху.","ru":"Скорости движения.","w":{"uk":"Від швидкості гальмовий шлях справді залежить, але не менше на нього впливають погодні умови.","ru":"От скорости тормозной путь действительно зависит, но не меньше на него влияют погодные условия."}},{"uk":"Погодних умов.","ru":"Погодных условий.","w":{"uk":"Погода справді змінює гальмовий шлях, але й швидкість впливає на нього дуже сильно.","ru":"Погода действительно меняет тормозной путь, но и скорость влияет на него очень сильно."}},{"uk":"Всі відповіді вірні.","ru":"Все ответы верны."}],"c":2,"e":{"uk":"Гальмовий шлях зростає пропорційно квадрату швидкості: удвічі вища швидкість — приблизно вчетверо довший шлях. Погода змінює зчеплення шин з дорогою: на мокрому, засніженому чи обмерзлому покритті шлях у рази довший, ніж на сухому.","ru":"Тормозной путь растёт пропорционально квадрату скорости: вдвое большая скорость — примерно вчетверо более длинный путь. Погода меняет сцепление шин с дорогой: на мокром, заснеженном или обледенелом покрытии путь в разы длиннее, чем на сухом."},"pic":["img/hsc/35-112-1.jpg"]},{"id":"h35-113","t":"h35","num":"35.113","q":{"uk":"Витрата палива залежить від:","ru":"Расход топлива зависит от:"},"a":[{"uk":"Швидкості руху.","ru":"Скорости движения.","w":{"uk":"Швидкість справді впливає на витрату, але так само впливають маса автомобіля і його завантаження.","ru":"Скорость действительно влияет на расход, но так же влияют масса автомобиля и его загрузка."}},{"uk":"Ваги транспортного засобу.","ru":"Массы транспортного средства.","w":{"uk":"Маса автомобіля — лише один із чинників; швидкість і завантаження впливають на витрату не менше.","ru":"Масса автомобиля — лишь один из факторов; скорость и загрузка влияют на расход не меньше."}},{"uk":"Завантаження транспортного засобу.","ru":"Загрузки транспортного средства.","w":{"uk":"Завантаження — лише один із чинників; швидкість і власна маса автомобіля також змінюють витрату.","ru":"Загрузка — лишь один из факторов; скорость и собственная масса автомобиля также меняют расход."}},{"uk":"Всі відповіді правильні.","ru":"Все ответы правильные."}],"c":3,"e":{"uk":"З ростом швидкості різко зростає опір повітря, а важчий автомобіль потребує більше енергії на розгін і кочення. Завантаження додає масу, а вантаж на даху ще й погіршує аеродинаміку — усе це збільшує витрату палива.","ru":"С ростом скорости резко растёт сопротивление воздуха, а более тяжёлый автомобиль требует больше энергии на разгон и качение. Загрузка добавляет массу, а груз на крыше ещё и ухудшает аэродинамику — всё это увеличивает расход топлива."},"pic":["img/hsc/35-113-1.jpg"]},{"id":"h35-114","t":"h35","num":"35.114","q":{"uk":"Дотримання безпечної дистанції може допомогти запобігти зіткненню без здійснення будь-яких маневрів?","ru":"Может ли соблюдение безопасной дистанции помочь предотвратить столкновение без выполнения каких-либо манёвров?"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"Саме безпечна дистанція дає змогу просто загальмувати у своїй смузі; без неї водієві лишається хіба різкий об'їзд.","ru":"Именно безопасная дистанция позволяет просто затормозить в своей полосе; без неё водителю остаётся разве что резкий объезд."}}],"c":0,"e":{"uk":"Безпечна дистанція ({p:13.1}) дає запас часу й відстані: якщо автомобіль попереду різко загальмує, ви встигнете зреагувати й зупинитися на своїй смузі. Не доведеться різко об'їжджати перешкоду, ризикуючи зіткнутися із сусідами чи вилетіти з дороги.","ru":"Безопасная дистанция ({p:13.1}) даёт запас времени и расстояния: если впереди идущий автомобиль резко затормозит, вы успеете среагировать и остановиться на своей полосе. Не придётся резко объезжать препятствие, рискуя столкнуться с соседями или вылететь с дороги."},"ref":["13.1"]},{"id":"h35-115","t":"h35","num":"35.115","q":{"uk":"Ви зупинились на вимогу поліцейського. Ви увімкнете аварійну світлову сигналізацію?","ru":"Вы остановились по требованию полицейского. Включите ли вы аварийную световую сигнализацию?"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"{p:9.9} прямо вимагає вмикати аварійну сигналізацію в разі зупинки на вимогу поліцейського.","ru":"{p:9.9} прямо требует включать аварийную сигнализацию при остановке по требованию полицейского."}}],"c":0,"e":{"uk":"За {p:9.9} аварійну світлову сигналізацію вмикають, зокрема, у разі зупинки на вимогу поліцейського. Вона попереджає інших водіїв, що автомобіль стоїть на дорозі, і біля нього можуть бути люди.","ru":"По {p:9.9} аварийную световую сигнализацию включают, в частности, при остановке по требованию полицейского. Она предупреждает других водителей, что автомобиль стоит на дороге и возле него могут находиться люди."},"ref":["9.9"],"pic":["img/hsc/35-115-1.jpg"]},{"id":"h35-116","t":"h35","num":"35.116","q":{"uk":"Водій, який має намір Вас обігнати, раніше перешкоджав Вам виконати обгін. У цьому випадку Ви:","ru":"Водитель, который намерен вас обогнать, ранее мешал вам выполнить обгон. В этом случае вы:"},"a":[{"uk":"Збільшите швидкість, щоб унеможливити обгін.","ru":"Увеличите скорость, чтобы сделать обгон невозможным.","w":{"uk":"Помста на дорозі заборонена й небезпечна: розганяючись, ви порушуєте {p:14.3} і залишаєте автомобіль, що обганяє, на зустрічній смузі.","ru":"Месть на дороге запрещена и опасна: разгоняясь, вы нарушаете {p:14.3} и оставляете обгоняющий автомобиль на встречной полосе."}},{"uk":"Не будете перешкоджати обгону.","ru":"Не будете препятствовать обгону."}],"c":1,"e":{"uk":"Водієві, якого обганяють, заборонено перешкоджати обгону підвищенням швидкості чи іншими діями ({p:14.3}), хоч би як поводився інший водій раніше. Якщо не дати обгону завершитися, автомобіль, що обганяє, застрягне на зустрічній смузі — це прямий шлях до лобового зіткнення.","ru":"Водителю, которого обгоняют, запрещено препятствовать обгону повышением скорости или другими действиями ({p:14.3}), как бы ни вёл себя другой водитель раньше. Если не дать обгону завершиться, обгоняющий автомобиль застрянет на встречной полосе — это прямой путь к лобовому столкновению."},"ref":["14.3"],"pic":["img/hsc/35-116-1.jpg"]},{"id":"h35-117","t":"h35","num":"35.117","q":{"uk":"Особа, яка навчається водінню, повинна мати при собі медичну довідку встановленого зразка?","ru":"Должно ли лицо, обучающееся вождению, иметь при себе медицинскую справку установленного образца?"},"a":[{"uk":"Так.","ru":"Да.","w":{"uk":"Довідка лише підтверджує, що медичних протипоказань немає ({p:24.1}); при собі учень має тримати документ, що засвідчує вік ({p:24.2}), а не довідку.","ru":"Справка лишь подтверждает отсутствие медицинских противопоказаний ({p:24.1}); при себе ученик должен иметь документ, удостоверяющий возраст ({p:24.2}), а не справку."}},{"uk":"Ні.","ru":"Нет."}],"c":1,"e":{"uk":"Медична довідка потрібна, щоб допустити особу до навчання водінню ({p:24.1}), але мати її при собі Правила не вимагають. Учень зобов'язаний мати при собі лише документ, що засвідчує його вік ({p:24.2}).","ru":"Медицинская справка нужна, чтобы допустить человека к обучению вождению ({p:24.1}), но иметь её при себе Правила не требуют. Ученик обязан иметь при себе лишь документ, удостоверяющий его возраст ({p:24.2})."},"ref":["24.1","24.2"]},{"id":"h35-118","t":"h35","num":"35.118","q":{"uk":"Рухаючись у населеному пункті, Ви бачите як водій, що рухається попереду, створив аварійну ситуацію. Для того, щоб запобігти ДТП Ви можете подати звуковий сигнал:","ru":"Двигаясь в населённом пункте, вы видите, как водитель, движущийся впереди, создал аварийную ситуацию. Чтобы предотвратить ДТП, вы можете подать звуковой сигнал:"},"a":[{"uk":"Ні.","ru":"Нет.","w":{"uk":"{p:9.5} забороняє сигнал у населеному пункті не повністю — його дозволено, коли без нього неможливо запобігти ДТП.","ru":"{p:9.5} запрещает сигнал в населённом пункте не полностью — его разрешено подавать, когда без него невозможно предотвратить ДТП."}},{"uk":"Так.","ru":"Да."}],"c":1,"e":{"uk":"У населених пунктах звуковий сигнал заборонений, крім випадків, коли без нього неможливо запобігти ДТП ({p:9.5}). Аварійна ситуація — саме такий випадок; водночас слід знижувати швидкість аж до зупинки ({p:12.3}).","ru":"В населённых пунктах звуковой сигнал запрещён, кроме случаев, когда без него невозможно предотвратить ДТП ({p:9.5}). Аварийная ситуация — именно такой случай; одновременно следует снижать скорость вплоть до остановки ({p:12.3})."},"ref":["9.5","12.3"],"pic":["img/hsc/35-118-1.jpg"]},{"id":"h35-119","t":"h35","num":"35.119","q":{"uk":"Сідаючи в автомобіль, Ви раптом відчули запаморочення та сильну втому. Дорога до місця призначення займе не більше 10 хв. Ви:","ru":"Садясь в автомобиль, вы вдруг почувствовали головокружение и сильную усталость. Дорога до места назначения займёт не более 10 минут. Вы:"},"a":[{"uk":"Розпочинаєте рух.","ru":"Начинаете движение.","w":{"uk":"Тривалість поїздки не має значення: аварія може статися в першу ж хвилину, а заборона {p:2.9} не залежить від відстані.","ru":"Продолжительность поездки не имеет значения: авария может произойти в первую же минуту, а запрет {p:2.9} не зависит от расстояния."}},{"uk":"Не розпочнете рух.","ru":"Не начнёте движение."}],"c":1,"e":{"uk":"Керувати транспортним засобом у хворобливому стані чи в стані стомлення заборонено ({p:2.9}), хоч би якою короткою була поїздка. Запаморочення може перейти в непритомність просто за кермом, а втома сповільнює реакцію.","ru":"Управлять транспортным средством в болезненном состоянии или в состоянии утомления запрещено ({p:2.9}), какой бы короткой ни была поездка. Головокружение может перейти в обморок прямо за рулём, а усталость замедляет реакцию."},"ref":["2.9"],"pic":["img/hsc/35-119-1.jpg"]},{"id":"h35-120","t":"h35","num":"35.120","q":{"uk":"Після приймання заспокійливого лікарського засобу, Ви відчули запаморочення та зниження уваги. У такому випадку дозволено керувати транспортним засобом за умови:","ru":"После приёма успокоительного лекарственного средства вы почувствовали головокружение и снижение внимания. В таком случае управлять транспортным средством разрешено при условии:"},"a":[{"uk":"Невеликої кількості транспортних засобів на дорозі.","ru":"Небольшого количества транспортных средств на дороге.","w":{"uk":"Навіть на порожній дорозі загальмований водій може не помітити пішохода, перешкоду чи поворот; заборона {p:2.9} від інтенсивності руху не залежить.","ru":"Даже на пустой дороге заторможенный водитель может не заметить пешехода, препятствие или поворот; запрет {p:2.9} от интенсивности движения не зависит."}},{"uk":"Присутності в автомобілі пасажирів.","ru":"Присутствия в автомобиле пассажиров.","w":{"uk":"Пасажири не керують автомобілем і не можуть замінити увагу й реакцію водія; заборона {p:2.9} діє й за їх присутності.","ru":"Пассажиры не управляют автомобилем и не могут заменить внимание и реакцию водителя; запрет {p:2.9} действует и в их присутствии."}},{"uk":"Керувати транспортним засобом заборонено.","ru":"Управлять транспортным средством запрещено."}],"c":2,"e":{"uk":"{p:2.9} забороняє керувати транспортним засобом під впливом лікарських препаратів, що знижують увагу та швидкість реакції, а також у хворобливому стані. Запаморочення й неуважність роблять водія небезпечним за будь-якої інтенсивності руху.","ru":"{p:2.9} запрещает управлять транспортным средством под влиянием лекарственных препаратов, снижающих внимание и скорость реакции, а также в болезненном состоянии. Головокружение и невнимательность делают водителя опасным при любой интенсивности движения."},"ref":["2.9"],"pic":["img/hsc/35-120-1.jpg"]},{"id":"h35-121","t":"h35","num":"35.121","q":{"uk":"Особа, яка не досягла 18-річного віку може отримати право на керування транспортним засобом категорії В за умови:","ru":"Лицо, не достигшее 18-летнего возраста, может получить право на управление транспортным средством категории B при условии:"},"a":[{"uk":"Наявності достатнього практичного досвіду керування транспортним засобом.","ru":"Наличия достаточного практического опыта управления транспортным средством.","w":{"uk":"Практичний досвід не замінює встановленого віку: до 18 років посвідчення категорії B не видають ({p:2.13}).","ru":"Практический опыт не заменяет установленного возраста: до 18 лет удостоверение категории B не выдают ({p:2.13})."}},{"uk":"Отримання транспортного засобу у спадок.","ru":"Получения транспортного средства в наследство.","w":{"uk":"Спадщина дає право власності на автомобіль, але не право ним керувати — для цього потрібні 18 років і посвідчення водія ({p:2.13}).","ru":"Наследство даёт право собственности на автомобиль, но не право им управлять — для этого нужны 18 лет и водительское удостоверение ({p:2.13})."}},{"uk":"В жодному випадку.","ru":"Ни в коем случае."}],"c":2,"e":{"uk":"Право керувати автомобілями категорій B1, B, C1, C надають лише з 18-річного віку ({p:2.13}). Жодні обставини — досвід чи власність на автомобіль — цього віку не знижують.","ru":"Право управлять автомобилями категорий B1, B, C1, C предоставляют только с 18-летнего возраста ({p:2.13}). Никакие обстоятельства — опыт или собственность на автомобиль — этот возраст не снижают."},"ref":["2.13"]},{"id":"h35-122","t":"h35","num":"35.122","q":{"uk":"З якого з цих транспортних засобів пасажир може вийти до моменту повної зупинки?","ru":"Из какого из этих транспортных средств пассажир может выйти до момента полной остановки?"},"a":[{"uk":"Громадського транспорту.","ru":"Общественного транспорта.","w":{"uk":"З громадського транспорту теж виходять лише після повної зупинки ({p:5.1}): на ходу легко впасти на сходинках чи під колеса.","ru":"Из общественного транспорта тоже выходят только после полной остановки ({p:5.1}): на ходу легко упасть на ступеньках или под колёса."}},{"uk":"Легкового автомобіля.","ru":"Легкового автомобиля.","w":{"uk":"Вистрибуючи з легкового автомобіля на ходу, людина падає за інерцією й може потрапити під колеса; {p:5.1} цього не дозволяє.","ru":"Выпрыгивая из легкового автомобиля на ходу, человек падает по инерции и может попасть под колёса; {p:5.1} этого не разрешает."}},{"uk":"Мотоцикла.","ru":"Мотоцикла.","w":{"uk":"Зіскочити з мотоцикла на ходу — означає впасти на дорогу, а ще й порушити рівновагу мотоцикла; висаджуються лише після зупинки ({p:5.1}).","ru":"Соскочить с мотоцикла на ходу — значит упасть на дорогу и ещё нарушить равновесие мотоцикла; высаживаются только после остановки ({p:5.1})."}},{"uk":"Жодного з них.","ru":"Ни из одного из них."}],"c":3,"e":{"uk":"Пасажирам дозволено сідати й виходити лише після зупинки транспортного засобу ({p:5.1}). На ходу людину за інерцією кидає вперед: вона може впасти, потрапити під колеса цього чи іншого транспортного засобу.","ru":"Пассажирам разрешено садиться и выходить только после остановки транспортного средства ({p:5.1}). На ходу человека по инерции бросает вперёд: он может упасть, попасть под колёса этого или другого транспортного средства."},"ref":["5.1"]},{"id":"h35-123","t":"h35","num":"35.123","q":{"uk":"Проїжджаючи повз школу, що в першу чергу необхідно зробити?","ru":"Проезжая мимо школы, что в первую очередь необходимо сделать?"},"a":[{"uk":"Увімкнути ближнє світло фар.","ru":"Включить ближний свет фар.","w":{"uk":"Ближнє світло робить автомобіль помітнішим, але гальмового шляху не скорочує; найважливіше біля школи — знизити швидкість.","ru":"Ближний свет делает автомобиль заметнее, но тормозного пути не сокращает; самое важное у школы — снизить скорость."}},{"uk":"Періодично сигналити для привертання уваги.","ru":"Периодически сигналить для привлечения внимания.","w":{"uk":"Звуковий сигнал у населеному пункті дозволений лише для запобігання ДТП ({p:9.5}), а налякана дитина може кинутися просто під колеса.","ru":"Звуковой сигнал в населённом пункте разрешён только для предотвращения ДТП ({p:9.5}), а испуганный ребёнок может броситься прямо под колёса."}},{"uk":"Зменшити швидкість.","ru":"Снизить скорость."},{"uk":"Збільшити швидкість.","ru":"Увеличить скорость.","w":{"uk":"Що вища швидкість, то довший гальмовий шлях і менше шансів зупинитися перед дитиною, яка вибігла на дорогу.","ru":"Чем выше скорость, тем длиннее тормозной путь и меньше шансов остановиться перед ребёнком, выбежавшим на дорогу."}}],"c":2,"e":{"uk":"Біля школи діти можуть раптово вибігти на дорогу, не дивлячись на транспорт, тому до них треба бути особливо обережним ({p:1.7}). Знижена швидкість скорочує гальмовий шлях і дає змогу вчасно зупинитися; про таку ділянку часто попереджає знак {s:1.33}.","ru":"У школы дети могут внезапно выбежать на дорогу, не глядя на транспорт, поэтому по отношению к ним нужно быть особенно осторожным ({p:1.7}). Сниженная скорость сокращает тормозной путь и позволяет вовремя остановиться; о таком участке часто предупреждает знак {s:1.33}."},"ref":["1.7"]},{"id":"h35-124","t":"h35","num":"35.124","q":{"uk":"Вживання навіть невеликої дози алкоголю:","ru":"Употребление даже небольшой дозы алкоголя:"},"a":[{"uk":"Жодним чином не впливає на водія.","ru":"Никак не влияет на водителя.","w":{"uk":"Алкоголь діє на нервову систему вже в малих дозах: водій реагує повільніше, хоча сам цього може не відчувати.","ru":"Алкоголь действует на нервную систему уже в малых дозах: водитель реагирует медленнее, хотя сам этого может не ощущать."}},{"uk":"Покращує водійські навички.","ru":"Улучшает водительские навыки.","w":{"uk":"Алкоголь лише створює ілюзію впевненості, а насправді погіршує реакцію, координацію й оцінку обстановки.","ru":"Алкоголь лишь создаёт иллюзию уверенности, а на самом деле ухудшает реакцию, координацию и оценку обстановки."}},{"uk":"Впливає на час реакції водія.","ru":"Влияет на время реакции водителя."}],"c":2,"e":{"uk":"Навіть невелика доза алкоголю сповільнює реакцію, погіршує координацію рухів, оцінку відстаней і швидкості, звужує поле зору й додає хибної впевненості. Тому керувати в будь-якому стані алкогольного сп'яніння заборонено ({p:2.9}).","ru":"Даже небольшая доза алкоголя замедляет реакцию, ухудшает координацию движений, оценку расстояний и скорости, сужает поле зрения и добавляет ложной уверенности. Поэтому управлять в любом состоянии алкогольного опьянения запрещено ({p:2.9})."},"ref":["2.9"],"pic":["img/hsc/35-124-1.jpg"]},{"id":"h35-125","t":"h35","num":"35.125","q":{"uk":"Аварії, вчинені водіями у стані алкогольного сп’яніння, як правило мають:","ru":"Аварии, совершённые водителями в состоянии алкогольного опьянения, как правило, имеют:"},"a":[{"uk":"Легші наслідки.","ru":"Более лёгкие последствия.","w":{"uk":"Розслабленість п'яного не пом'якшує удару: швидкість зіткнення в таких аваріях зазвичай більша, а травми важчі.","ru":"Расслабленность пьяного не смягчает удара: скорость столкновения в таких авариях обычно выше, а травмы тяжелее."}},{"uk":"Більш важкі наслідки.","ru":"Более тяжёлые последствия."}],"c":1,"e":{"uk":"Нетверезий водій частіше перевищує швидкість, не пристібається й гальмує із запізненням, тож зіткнення відбувається на більшій швидкості. Тому такі ДТП, як правило, мають важчі наслідки; керувати в стані сп'яніння заборонено ({p:2.9}).","ru":"Нетрезвый водитель чаще превышает скорость, не пристёгивается и тормозит с опозданием, поэтому столкновение происходит на большей скорости. Поэтому такие ДТП, как правило, имеют более тяжёлые последствия; управлять в состоянии опьянения запрещено ({p:2.9})."},"ref":["2.9"]},{"id":"h35-126","t":"h35","num":"35.126","q":{"uk":"Щоб керувати транспортним засобом безпечно, потрібно зосередитися і вміти стежити за всім, що відбувається на дорозі. Для цього вам потрібно:","ru":"Чтобы управлять транспортным средством безопасно, нужно сосредоточиться и уметь следить за всем, что происходит на дороге. Для этого вам нужно:"},"a":[{"uk":"За можливості попросити пасажирів стежити за дорожніми небезпеками.","ru":"По возможности попросить пассажиров следить за дорожными опасностями.","w":{"uk":"Пасажири не відповідають за безпеку руху, а їхні підказки лише відволікають; стежити за дорогою — обов'язок водія ({p:2.3}).","ru":"Пассажиры не отвечают за безопасность движения, а их подсказки лишь отвлекают; следить за дорогой — обязанность водителя ({p:2.3})."}},{"uk":"Дивитися і оцінювати небезпеки лише попереду.","ru":"Смотреть и оценивать опасности только впереди.","w":{"uk":"Небезпека може виникнути позаду й збоку — від автомобіля в «сліпій зоні», мотоцикліста чи пішохода, тому стежать за всією обстановкою.","ru":"Опасность может возникнуть сзади и сбоку — от автомобиля в «слепой зоне», мотоциклиста или пешехода, поэтому следят за всей обстановкой."}},{"uk":"Постійно оцінювати дорожню обстановку, контролювати безпечну дистанцію та інтервал.","ru":"Постоянно оценивать дорожную обстановку, контролировать безопасную дистанцию и интервал."}],"c":2,"e":{"uk":"Водій зобов'язаний сам бути уважним і стежити за дорожньою обстановкою ({p:2.3}): дивитися вперед, у дзеркала й на боки та тримати безпечну дистанцію й інтервал ({p:13.1}). Тоді в разі небезпеки є запас часу й простору, щоб зреагувати.","ru":"Водитель обязан сам быть внимательным и следить за дорожной обстановкой ({p:2.3}): смотреть вперёд, в зеркала и по сторонам и держать безопасную дистанцию и интервал ({p:13.1}). Тогда при опасности есть запас времени и пространства, чтобы среагировать."},"ref":["2.3","13.1"],"pic":["img/hsc/35-126-1.jpg"]},{"id":"h35-127","t":"h35","num":"35.127","q":{"uk":"При під’їзді до крутого повороту Ви помітили сліди гравію на дорозі. Вам слід:","ru":"При подъезде к крутому повороту вы заметили следы гравия на дороге. Вам следует:"},"a":[{"uk":"Продовжити рух з тією ж швидкістю.","ru":"Продолжить движение с той же скоростью.","w":{"uk":"На гравії зчеплення гірше, тож швидкість, безпечна на чистому асфальті, у крутому повороті може винести автомобіль з дороги.","ru":"На гравии сцепление хуже, поэтому скорость, безопасная на чистом асфальте, в крутом повороте может вынести автомобиль с дороги."}},{"uk":"Збільшити швидкість.","ru":"Увеличить скорость.","w":{"uk":"Що вища швидкість у повороті, то більша відцентрова сила; на гравії шини її не втримають, і автомобіль занесе.","ru":"Чем выше скорость в повороте, тем больше центробежная сила; на гравии шины её не удержат, и автомобиль занесёт."}},{"uk":"Зменшити швидкість.","ru":"Снизить скорость."}],"c":2,"e":{"uk":"Гравій під колесами діє як кульки й різко зменшує зчеплення шин з дорогою, а в повороті саме зчеплення утримує автомобіль на траєкторії. Швидкість знижують ще до повороту, щоб пройти його без різкого гальмування й ривків кермом ({p:12.1}).","ru":"Гравий под колёсами действует как шарики и резко уменьшает сцепление шин с дорогой, а в повороте именно сцепление удерживает автомобиль на траектории. Скорость снижают ещё до поворота, чтобы пройти его без резкого торможения и рывков рулём ({p:12.1})."},"ref":["12.1"],"pic":["img/hsc/35-127-1.jpg"]},{"id":"h35-128","t":"h35","num":"35.128","q":{"uk":"Якщо Ви помітили вершника на дорозі, Вам слід:","ru":"Если вы заметили всадника на дороге, вам следует:"},"a":[{"uk":"Подати звуковий сигнал.","ru":"Подать звуковой сигнал.","w":{"uk":"Різкий звук лякає коня, і він може кинутися просто під колеса чи скинути вершника.","ru":"Резкий звук пугает лошадь, и она может броситься прямо под колёса или сбросить всадника."}},{"uk":"Зменшити швидкість та збільшити безпечний інтервал до вершника.","ru":"Снизить скорость и увеличить безопасный интервал до всадника."},{"uk":"Збільшити швидкість.","ru":"Увеличить скорость.","w":{"uk":"Що швидше й гучніше проїжджає автомобіль, то сильніше лякається тварина, а часу зреагувати на її стрибок у вас менше.","ru":"Чем быстрее и громче проезжает автомобиль, тем сильнее пугается животное, а времени среагировать на его прыжок у вас меньше."}}],"c":1,"e":{"uk":"Кінь може злякатися шуму чи автомобіля, що проїжджає впритул, — стати дибки, шарахнутися вбік або скинути вершника. Тому швидкість знижують і проїжджають тихо, з великим безпечним інтервалом ({p:13.3}).","ru":"Лошадь может испугаться шума или автомобиля, проезжающего вплотную, — встать на дыбы, шарахнуться в сторону или сбросить всадника. Поэтому скорость снижают и проезжают тихо, с большим безопасным интервалом ({p:13.3})."},"ref":["13.3"],"pic":["img/hsc/35-128-1.jpg"]},{"id":"h35-129","t":"h35","num":"35.129","q":{"uk":"Друг позичає вам транспортний засіб, який вміщує десять осіб разом з водієм. Чи достатньо Вам посвідчення на право керування транспортним засобом категорії B, щоб керувати таким транспортним засобом?","ru":"Друг одалживает вам транспортное средство, которое вмещает десять человек вместе с водителем. Достаточно ли вам удостоверения на право управления транспортным средством категории B, чтобы управлять таким транспортным средством?"},"a":[{"uk":"Достатньо.","ru":"Достаточно.","w":{"uk":"Категорія B обмежена вісьмома місцями, крім водійського ({p:2.13}), а тут їх дев'ять — потрібна категорія D1.","ru":"Категория B ограничена восемью местами, кроме водительского ({p:2.13}), а здесь их девять — нужна категория D1."}},{"uk":"Недостатньо.","ru":"Недостаточно."}],"c":1,"e":{"uk":"До категорії B належать автомобілі, у яких, крім сидіння водія, не більше восьми сидячих місць ({p:2.13}). Десять осіб разом з водієм — це дев'ять пасажирських місць, тобто вже автобус категорії D1.","ru":"К категории B относятся автомобили, в которых, кроме сиденья водителя, не более восьми сидячих мест ({p:2.13}). Десять человек вместе с водителем — это девять пассажирских мест, то есть уже автобус категории D1."},"ref":["2.13"],"pic":["img/hsc/35-129-1.jpg"]},{"id":"h35-130","t":"h35","num":"35.130","q":{"uk":"Рухаючись у заторі Ви сповільнюєте рух, наближаючись до велосипедиста. Водії позаду сигналять, вимагаючи від Вас рухатись швидше та обігнати велосипедиста. Ваші дії:","ru":"Двигаясь в заторе, вы замедляете движение, приближаясь к велосипедисту. Водители сзади сигналят, требуя от вас двигаться быстрее и обогнать велосипедиста. Ваши действия:"},"a":[{"uk":"Збільшите швидкість та виконаєте обгін велосипедиста.","ru":"Увеличите скорость и выполните обгон велосипедиста.","w":{"uk":"Поспіх під тиском інших у заторі закінчується обгоном з замалим інтервалом — велосипедиста можна зачепити чи збити.","ru":"Спешка под давлением других в заторе заканчивается обгоном с недостаточным интервалом — велосипедиста можно задеть или сбить."}},{"uk":"Зупините транспортний засіб, даючи можливість велосипедисту проїхати вперед на достатню відстань.","ru":"Остановите транспортное средство, давая возможность велосипедисту проехать вперёд на достаточное расстояние.","w":{"uk":"Зупинятися без потреби не слід: це створює перешкоду й ризик удару ззаду; досить їхати за велосипедистом на безпечній дистанції, доки не з'явиться змога обігнати.","ru":"Останавливаться без необходимости не следует: это создаёт помеху и риск удара сзади; достаточно ехать за велосипедистом на безопасной дистанции, пока не появится возможность обогнать."}},{"uk":"Зберігаєте спокій і виконаєте обгін велосипедиста тоді, коли це буде безпечно.","ru":"Сохраняете спокойствие и выполните обгон велосипедиста тогда, когда это будет безопасно."}],"c":2,"e":{"uk":"За безпеку маневру відповідаєте ви, а не водії позаду. Обганяють лише тоді, коли можна дотримати безпечного інтервалу до велосипедиста ({p:13.3}) і маневр нікому не загрожує ({p:14.2}); до велосипедистів водії мають бути особливо уважними ({p:1.7}).","ru":"За безопасность манёвра отвечаете вы, а не водители сзади. Обгоняют только тогда, когда можно соблюсти безопасный интервал до велосипедиста ({p:13.3}) и манёвр никому не угрожает ({p:14.2}); к велосипедистам водители должны быть особенно внимательны ({p:1.7})."},"ref":["13.3","14.2","1.7"],"pic":["img/hsc/35-130-1.jpg"]},{"id":"h35-131","t":"h35","num":"35.131","q":{"uk":"Відкриваючи двері транспортного засобу зі сторони проїжджої частини, на що слід звернути увагу?","ru":"Открывая двери транспортного средства со стороны проезжей части, на что следует обратить внимание?"},"a":[{"uk":"Відкривати двері необхідно різко.","ru":"Открывать двери необходимо резко.","w":{"uk":"Різко відчинені двері не дають велосипедистові чи водієві, що наближається, часу зреагувати — він урізається в них.","ru":"Резко открытая дверь не даёт велосипедисту или приближающемуся водителю времени среагировать — он врезается в неё."}},{"uk":"Переконатися, що всі водії, що рухаються позаду, зрозуміли Ваші наміри.","ru":"Убедиться, что все водители, движущиеся сзади, поняли ваши намерения.","w":{"uk":"Сигналу про відчинення дверей не існує, і переконатися, що всі «зрозуміли наміри», неможливо; треба дочекатися, коли поруч ніхто не їде.","ru":"Сигнала об открывании дверей не существует, и убедиться, что все «поняли намерения», невозможно; нужно дождаться, когда рядом никто не едет."}},{"uk":"Відкривати двері лише, коли впевнились в тому, що це не загрожує іншим учасникам дорожнього руху.","ru":"Открывать двери только тогда, когда убедились в том, что это не угрожает другим участникам дорожного движения."}],"c":2,"e":{"uk":"Відчиняти двері заборонено, якщо це загрожує безпеці чи створює перешкоди іншим учасникам руху ({p:15.13}). Перед цим дивляться в дзеркало й через плече, чи не наближаються велосипедист, мотоцикліст або автомобіль, і відчиняють двері повільно.","ru":"Открывать двери запрещено, если это угрожает безопасности или создаёт помехи другим участникам движения ({p:15.13}). Перед этим смотрят в зеркало и через плечо, не приближаются ли велосипедист, мотоциклист или автомобиль, и открывают двери медленно."},"ref":["15.13"],"pic":["img/hsc/35-131-1.jpg"]},{"id":"h35-132","t":"h35","num":"35.132","q":{"uk":"Проїжджаючи поруч з дітьми, які граються біля краю дороги, Вам слід:","ru":"Проезжая рядом с детьми, которые играют у края дороги, вам следует:"},"a":[{"uk":"Посигналити їм.","ru":"Посигналить им.","w":{"uk":"Звуковий сигнал може налякати дитину, і вона кинеться просто на дорогу; у населеному пункті сигнал дозволений лише для запобігання ДТП ({p:9.5}).","ru":"Звуковой сигнал может напугать ребёнка, и он бросится прямо на дорогу; в населённом пункте сигнал разрешён только для предотвращения ДТП ({p:9.5})."}},{"uk":"Збільшити швидкість.","ru":"Увеличить скорость.","w":{"uk":"З більшою швидкістю гальмовий шлях довший, і зупинитися перед дитиною, що вибігла, ви вже не встигнете.","ru":"С большей скоростью тормозной путь длиннее, и остановиться перед выбежавшим ребёнком вы уже не успеете."}},{"uk":"Зменшити швидкість і бути готовим повністю зупинити транспортний засіб.","ru":"Снизить скорость и быть готовым полностью остановить транспортное средство."}],"c":2,"e":{"uk":"Захоплені грою діти не стежать за дорогою й можуть раптово вибігти на проїзну частину, наприклад за м'ячем. До дітей усі учасники руху мають бути особливо обережними ({p:1.7}), тож швидкість знижують так, щоб устигнути зупинитися ({p:12.3}).","ru":"Увлечённые игрой дети не следят за дорогой и могут внезапно выбежать на проезжую часть, например за мячом. По отношению к детям все участники движения должны быть особенно осторожны ({p:1.7}), поэтому скорость снижают так, чтобы успеть остановиться ({p:12.3})."},"ref":["1.7","12.3"]},{"id":"h35-133","t":"h35","num":"35.133","q":{"uk":"Коли Ви бачите дітей на дорозі або поруч з нею:","ru":"Когда вы видите детей на дороге или рядом с ней:"},"a":[{"uk":"Необхідно зменшити швидкість на 5-10 км/год.","ru":"Необходимо снизить скорость на 5–10 км/ч.","w":{"uk":"Швидкість знижують не на «умовні» 5–10 км/год, а до такої, за якої можна зупинитися перед дитиною, що раптово вибігла.","ru":"Скорость снижают не на «условные» 5–10 км/ч, а до такой, при которой можно остановиться перед внезапно выбежавшим ребёнком."}},{"uk":"Не слід звертати на них увагу.","ru":"Не следует обращать на них внимание.","w":{"uk":"Діти — найнепередбачуваніші учасники руху, і Правила вимагають бути до них особливо обережними ({p:1.7}).","ru":"Дети — самые непредсказуемые участники движения, и Правила требуют быть особенно осторожными по отношению к ним ({p:1.7})."}},{"uk":"Потрібно бути обережним, зменшити швидкість і бути готовим повністю зупинити транспортний засіб.","ru":"Нужно быть осторожным, снизить скорость и быть готовым полностью остановить транспортное средство."}],"c":2,"e":{"uk":"Поведінка дітей непередбачувана: вони можуть раптово вибігти на дорогу, не дивлячись на транспорт. Тому водій знижує швидкість так, щоб устигнути зупинитися ({p:12.3}): до дітей треба бути особливо обережним ({p:1.7}).","ru":"Поведение детей непредсказуемо: они могут внезапно выбежать на дорогу, не глядя на транспорт. Поэтому водитель снижает скорость так, чтобы успеть остановиться ({p:12.3}): по отношению к детям нужно быть особенно осторожным ({p:1.7})."},"ref":["1.7","12.3"]},{"id":"h35-134","t":"h35","num":"35.134","q":{"uk":"Рухаючись ділянками, де велика кількість пішоходів, водію необхідно:","ru":"Двигаясь по участкам, где большое количество пешеходов, водителю необходимо:"},"a":[{"uk":"Увімкнути дальнє світло фар.","ru":"Включить дальний свет фар.","w":{"uk":"Дальнє світло засліплює пішоходів і зустрічних водіїв ({p:19.2}), а гальмового шляху не скорочує.","ru":"Дальний свет ослепляет пешеходов и встречных водителей ({p:19.2}), а тормозного пути не сокращает."}},{"uk":"Бути особливо уважним та обережним, зменшити швидкість і бути готовим до повної зупинки.","ru":"Быть особенно внимательным и осторожным, снизить скорость и быть готовым к полной остановке."},{"uk":"Проїхати ділянку максимально швидко, увімкнувши аварійну світлову сигналізацію.","ru":"Проехать участок максимально быстро, включив аварийную световую сигнализацию.","w":{"uk":"Аварійну сигналізацію для цього не вмикають ({p:9.9}), а висока швидкість серед пішоходів не залишає шансів зупинитися.","ru":"Аварийную сигнализацию для этого не включают ({p:9.9}), а высокая скорость среди пешеходов не оставляет шансов остановиться."}}],"c":1,"e":{"uk":"Що більше пішоходів, то вища ймовірність, що хтось несподівано ступить на проїзну частину. Водії мають бути особливо уважними до пішоходів ({p:1.7}) і тримати таку швидкість, щоб устигнути зупинитися ({p:12.3}).","ru":"Чем больше пешеходов, тем выше вероятность, что кто-то неожиданно ступит на проезжую часть. Водители должны быть особенно внимательны к пешеходам ({p:1.7}) и держать такую скорость, чтобы успеть остановиться ({p:12.3})."},"ref":["1.7","12.3"],"pic":["img/hsc/35-134-1.jpg"]},{"id":"h35-135","t":"h35","num":"35.135","q":{"uk":"Коли Ви бачите людей похилого віку на дорозі або біля неї, Вам необхідно:","ru":"Когда вы видите людей пожилого возраста на дороге или возле неё, вам необходимо:"},"a":[{"uk":"Зменшити швидкість на 5-10 км/год.","ru":"Снизить скорость на 5–10 км/ч.","w":{"uk":"Фіксоване зниження на 5–10 км/год може виявитися замалим; швидкість має давати змогу зупинитися, якщо людина раптово вийде на дорогу.","ru":"Фиксированное снижение на 5–10 км/ч может оказаться недостаточным; скорость должна позволять остановиться, если человек внезапно выйдет на дорогу."}},{"uk":"Не слід звертати на них увагу.","ru":"Не следует обращать на них внимание.","w":{"uk":"Правила прямо вимагають бути особливо обережними до людей похилого віку ({p:1.7}).","ru":"Правила прямо требуют быть особенно осторожными по отношению к людям пожилого возраста ({p:1.7})."}},{"uk":"Потрібно бути обережним, зменшити швидкість і бути готовим повністю зупинити транспортний засіб.","ru":"Нужно быть осторожным, снизить скорость и быть готовым полностью остановить транспортное средство."}],"c":2,"e":{"uk":"Літні люди рухаються повільніше, гірше бачать і чують, можуть неправильно оцінити швидкість автомобіля чи зупинитися посеред дороги. До них усі учасники руху мають бути особливо обережними ({p:1.7}), тож швидкість знижують так, щоб устигнути зупинитися ({p:12.3}).","ru":"Пожилые люди двигаются медленнее, хуже видят и слышат, могут неверно оценить скорость автомобиля или остановиться посреди дороги. По отношению к ним все участники движения должны быть особенно осторожны ({p:1.7}), поэтому скорость снижают так, чтобы успеть остановиться ({p:12.3})."},"ref":["1.7","12.3"],"pic":["img/hsc/35-135-1.jpg"]},{"id":"h35-136","t":"h35","num":"35.136","q":{"uk":"Якщо Ви помітили пішохода з ознаками алкогольного сп’яніння, який рухається по краю проїзної частини, необхідно:","ru":"Если вы заметили пешехода с признаками алкогольного опьянения, который движется по краю проезжей части, необходимо:"},"a":[{"uk":"Бути максимально уважним та обережним, зменшити швидкість та бути готовим зупинити транспортний засіб.","ru":"Быть максимально внимательным и осторожным, снизить скорость и быть готовым остановить транспортное средство."},{"uk":"Проїхати повз, не зменшуючи швидкість.","ru":"Проехать мимо, не снижая скорости.","w":{"uk":"Якщо пішохід хитнеться на дорогу, на незниженій швидкості ви не встигнете ні загальмувати, ні об'їхати його.","ru":"Если пешеход качнётся на дорогу, на неснижённой скорости вы не успеете ни затормозить, ни объехать его."}},{"uk":"Посигналити двічі, попередивши його про наближення транспортного засобу.","ru":"Посигналить дважды, предупредив его о приближении транспортного средства.","w":{"uk":"Сигнал може налякати нетверезого пішохода, і він рвоне просто під колеса; у населеному пункті сигнал дозволений лише для запобігання ДТП ({p:9.5}).","ru":"Сигнал может напугать нетрезвого пешехода, и он рванётся прямо под колёса; в населённом пункте сигнал разрешён только для предотвращения ДТП ({p:9.5})."}}],"c":0,"e":{"uk":"Нетверезий пішохід рухається непередбачувано: може похитнутися, спіткнутися чи раптово вийти на дорогу, не оцінивши небезпеки. Така ситуація вимагає знизити швидкість аж до зупинки ({p:12.3}) і проїжджати з великим інтервалом ({p:13.1}).","ru":"Нетрезвый пешеход движется непредсказуемо: может пошатнуться, споткнуться или внезапно выйти на дорогу, не оценив опасности. Такая ситуация требует снизить скорость вплоть до остановки ({p:12.3}) и проезжать с большим интервалом ({p:13.1})."},"ref":["12.3","13.1"],"pic":["img/hsc/35-136-1.jpg"]},{"id":"h35-137","t":"h35","num":"35.137","q":{"uk":"Наближаючись до пішохідного переходу, на якому немає пішоходів, Ви:","ru":"Приближаясь к пешеходному переходу, на котором нет пешеходов, вы:"},"a":[{"uk":"Будете обережним і готовим зменшити швидкість, а у разі необхідності зупинити транспортний засіб.","ru":"Будете осторожны и готовы снизить скорость, а при необходимости остановить транспортное средство."},{"uk":"Проїдете перехід, збільшивши швидкість перед його початком.","ru":"Проедете переход, увеличив скорость перед его началом.","w":{"uk":"Пришвидшившись перед переходом, ви не встигнете зупинитися, якщо на нього раптово вийде пішохід.","ru":"Ускорившись перед переходом, вы не успеете остановиться, если на него внезапно выйдет пешеход."}},{"uk":"Все одно зупините транспортний засіб перед початком переходу і зачекаєте, поки з’являться пішоходи.","ru":"Всё равно остановите транспортное средство перед началом перехода и подождёте, пока появятся пешеходы.","w":{"uk":"Зупинка без потреби створює перешкоду для руху й ризик удару ззаду; пропускати немає кого, а чекати появи пішоходів немає сенсу.","ru":"Остановка без необходимости создаёт помеху для движения и риск удара сзади; пропускать некого, а ждать появления пешеходов нет смысла."}}],"c":0,"e":{"uk":"Пішохід може раптово з'явитися на переході з-за автомобіля, що стоїть, кіоску чи дерева, або вибігти, сподіваючись устигнути. Тому біля переходу водій готовий знизити швидкість і зупинитися, щоб дати дорогу пішоходам ({p:18.1}).","ru":"Пешеход может внезапно появиться на переходе из-за стоящего автомобиля, киоска или дерева либо выбежать, надеясь успеть. Поэтому у перехода водитель готов снизить скорость и остановиться, чтобы уступить дорогу пешеходам ({p:18.1})."},"ref":["18.1"],"pic":["img/hsc/35-137-1.jpg"]},{"id":"h35-138","t":"h35","num":"35.138","q":{"uk":"Проїжджаючи повз припарковані транспортні засоби необхідно:","ru":"Проезжая мимо припаркованных транспортных средств, необходимо:"},"a":[{"uk":"Бути максимально обережним, бо можлива раптова поява людей чи тварин з-за автомобілів, а також відкриття дверей.","ru":"Быть максимально осторожным, так как возможно внезапное появление людей или животных из-за автомобилей, а также открывание дверей."},{"uk":"Якомога швидше проїхати повз автомобілі, щоб не перешкоджати іншим учасникам дорожнього руху.","ru":"Как можно быстрее проехать мимо автомобилей, чтобы не мешать другим участникам дорожного движения.","w":{"uk":"Поспіх повз ряд автомобілів, що стоять, не залишає часу зреагувати на пішохода, що вийде з-за них, чи на відчинені двері.","ru":"Спешка мимо ряда стоящих автомобилей не оставляет времени среагировать на пешехода, вышедшего из-за них, или на открытую дверь."}},{"uk":"Рухатись повз припарковані транспортні засоби увімкнувши аварійну світлову сигналізацію.","ru":"Двигаться мимо припаркованных транспортных средств, включив аварийную световую сигнализацию.","w":{"uk":"Аварійну сигналізацію в такій ситуації не вмикають ({p:9.9}): вона вводить інших в оману й нічим не допомагає.","ru":"Аварийную сигнализацию в такой ситуации не включают ({p:9.9}): она вводит других в заблуждение и ничем не помогает."}}],"c":0,"e":{"uk":"Припарковані автомобілі закривають огляд: з-за них може вийти пішохід, вибігти дитина чи тварина, а водій або пасажир — відчинити двері. Тому повз них їдуть на зниженій швидкості й з достатнім боковим інтервалом ({p:13.1}).","ru":"Припаркованные автомобили закрывают обзор: из-за них может выйти пешеход, выбежать ребёнок или животное, а водитель или пассажир — открыть дверь. Поэтому мимо них едут на сниженной скорости и с достаточным боковым интервалом ({p:13.1})."},"ref":["13.1"],"pic":["img/hsc/35-138-1.jpg"]},{"id":"h35-139","t":"h35","num":"35.139","q":{"uk":"Під час руху ви зіткнулись із агресивною манерою водіння транспортного засобу, що їде попереду. Ви повинні:","ru":"Во время движения вы столкнулись с агрессивной манерой вождения транспортного средства, едущего впереди. Вы должны:"},"a":[{"uk":"Якомога швидше обігнати цей транспортний засіб.","ru":"Как можно быстрее обогнать это транспортное средство.","w":{"uk":"Поспішний обгін агресивного водія може його спровокувати: він пришвидшиться чи підріже вас, а сам маневр, зроблений нашвидкуруч, небезпечний.","ru":"Поспешный обгон агрессивного водителя может его спровоцировать: он ускорится или подрежет вас, а сам манёвр, выполненный наспех, опасен."}},{"uk":"Попередити водія, що рухається попереду тривалим звуковим сигналом.","ru":"Предупредить водителя, движущегося впереди, длительным звуковым сигналом.","w":{"uk":"Тривалий сигнал не заспокоїть агресивного водія, а розізлить його; у населеному пункті сигнал дозволений лише для запобігання ДТП ({p:9.5}).","ru":"Длительный сигнал не успокоит агрессивного водителя, а разозлит его; в населённом пункте сигнал разрешён только для предотвращения ДТП ({p:9.5})."}},{"uk":"Зберігати спокій, за необхідності зменшити швидкість і уважно слідкувати за дорожньою обстановкою.","ru":"Сохранять спокойствие, при необходимости снизить скорость и внимательно следить за дорожной обстановкой."}],"c":2,"e":{"uk":"Агресивний водій діє непередбачувано: різко гальмує, перестроюється, підрізає. Найбезпечніше — не вступати в конфлікт, збільшити дистанцію ({p:13.1}) і уважно стежити за його діями та обстановкою ({p:2.3}).","ru":"Агрессивный водитель действует непредсказуемо: резко тормозит, перестраивается, подрезает. Безопаснее всего — не вступать в конфликт, увеличить дистанцию ({p:13.1}) и внимательно следить за его действиями и обстановкой ({p:2.3})."},"ref":["13.1","2.3"],"pic":["img/hsc/35-139-1.jpg"]},{"id":"h35-140","t":"h35","num":"35.140","q":{"uk":"Під час руху вночі необхідно:","ru":"Во время движения ночью необходимо:"},"a":[{"uk":"Рухатись на найменшій відстані до транспортних засобів, що попереду, щоб інші водії розуміли, що Ви рухаєтесь позаду.","ru":"Двигаться на наименьшем расстоянии от транспортных средств, находящихся впереди, чтобы другие водители понимали, что вы движетесь сзади.","w":{"uk":"На малій дистанції не залишається часу зреагувати на гальмування попереду, а ваші фари засліплюють водія через його дзеркала.","ru":"На малой дистанции не остаётся времени среагировать на торможение впереди, а ваши фары ослепляют водителя через его зеркала."}},{"uk":"Рухатись на безпечній дистанції до транспортних засобів, що попереду, оскільки вночі складніше оцінювати дорожню обстановку.","ru":"Двигаться на безопасной дистанции до транспортных средств, находящихся впереди, поскольку ночью сложнее оценивать дорожную обстановку."}],"c":1,"e":{"uk":"Уночі видно лише те, що освітлюють фари, відстані й швидкість оцінювати важче, а втома сповільнює реакцію. Тому безпечна дистанція ({p:13.1}) вночі особливо важлива, а швидкість має давати змогу зупинитися в межах видимості ({p:12.2}).","ru":"Ночью видно только то, что освещают фары, расстояния и скорость оценивать труднее, а усталость замедляет реакцию. Поэтому безопасная дистанция ({p:13.1}) ночью особенно важна, а скорость должна позволять остановиться в пределах видимости ({p:12.2})."},"ref":["13.1","12.2"],"pic":["img/hsc/35-140-1.jpg"]},{"id":"h35-141","t":"h35","num":"35.141","q":{"uk":"Яке з наведених тверджень найбільш вдало описує Вас як безпечного водія?","ru":"Какое из приведённых утверждений наиболее удачно описывает вас как безопасного водителя?"},"a":[{"uk":"Коли я керую транспортним засобом, я несу відповідальність за власну безпеку та безпеку інших учасників дорожнього руху.","ru":"Когда я управляю транспортным средством, я несу ответственность за собственную безопасность и безопасность других участников дорожного движения."},{"uk":"Інші водії повинні рухатись так, щоб уникнути зіткнення зі мною.","ru":"Другие водители должны двигаться так, чтобы избежать столкновения со мной.","w":{"uk":"Перекладати відповідальність на інших небезпечно: інші теж помиляються, і безпеку кожен водій зобов'язаний забезпечувати сам ({p:2.3}).","ru":"Перекладывать ответственность на других опасно: другие тоже ошибаются, и безопасность каждый водитель обязан обеспечивать сам ({p:2.3})."}},{"uk":"Потрапити чи не потрапити в ДТП – справа випадку.","ru":"Попасть или не попасть в ДТП — дело случая.","w":{"uk":"Більшість ДТП спричиняють помилки водіїв — перевищення швидкості, неуважність, сп'яніння, — тож аварії можна відвернути, а не покладатися на випадок.","ru":"Большинство ДТП вызывают ошибки водителей — превышение скорости, невнимательность, опьянение, — поэтому аварии можно предотвратить, а не полагаться на случай."}}],"c":0,"e":{"uk":"Безпечний водій розуміє, що від його дій залежить життя не лише його самого, а й пасажирів, пішоходів та інших водіїв. Тому він не створює своїми діями загрози безпеці руху ({p:2.3}), передбачає можливі помилки інших і залишає собі запас часу та простору.","ru":"Безопасный водитель понимает, что от его действий зависит жизнь не только его самого, но и пассажиров, пешеходов и других водителей. Поэтому он не создаёт своими действиями угрозы безопасности движения ({p:2.3}), предвидит возможные ошибки других и оставляет себе запас времени и пространства."},"ref":["2.3"]},{"id":"h35-142","t":"h35","num":"35.142","q":{"uk":"Якщо під час сильного дощу видимість раптово погіршується, Вам слід:","ru":"Если во время сильного дождя видимость внезапно ухудшается, вам следует:"},"a":[{"uk":"Зменшити швидкість та збільшити відстань до транспортного засобу, що рухається попереду.","ru":"Снизить скорость и увеличить расстояние до транспортного средства, движущегося впереди."},{"uk":"Зупинити автомобіль.","ru":"Остановить автомобиль.","w":{"uk":"Раптова зупинка на проїзній частині в зливу небезпечна: водії позаду можуть пізно помітити ваш автомобіль і врізатися в нього; досить знизити швидкість.","ru":"Внезапная остановка на проезжей части в ливень опасна: водители сзади могут поздно заметить ваш автомобиль и врезаться в него; достаточно снизить скорость."}},{"uk":"Увімкнути дальнє світло фар.","ru":"Включить дальний свет фар.","w":{"uk":"Дальнє світло відбивається від крапель дощу світловою завісою й погіршує видимість, а ще засліплює інших водіїв.","ru":"Дальний свет отражается от капель дождя световой завесой и ухудшает видимость, а ещё ослепляет других водителей."}}],"c":0,"e":{"uk":"У зливу видимість падає, а гальмовий шлях на мокрій дорозі довшає. Швидкість знижують так, щоб зупинитися в межах видимості ({p:12.2}), а дистанцію збільшують, щоб устигнути загальмувати за автомобілем попереду ({p:13.1}).","ru":"В ливень видимость падает, а тормозной путь на мокрой дороге удлиняется. Скорость снижают так, чтобы остановиться в пределах видимости ({p:12.2}), а дистанцию увеличивают, чтобы успеть затормозить за впереди идущим автомобилем ({p:13.1})."},"ref":["12.2","13.1"],"pic":["img/hsc/35-142-1.jpg"]},{"id":"h35-143","t":"h35","num":"35.143","q":{"uk":"Що необхідно пам’ятати, якщо Ви плануєте тривалу поїздку:","ru":"Что необходимо помнить, если вы планируете длительную поездку:"},"a":[{"uk":"Краще їхати уночі, оскільки менше транспортних засобів.","ru":"Лучше ехать ночью, поскольку меньше транспортных средств.","w":{"uk":"Уночі організм налаштований на сон, видимість обмежена світлом фар, а зустрічні фари засліплюють — ризик заснути за кермом найвищий.","ru":"Ночью организм настроен на сон, видимость ограничена светом фар, а встречные фары ослепляют — риск уснуть за рулём самый высокий."}},{"uk":"Краще їхати без зупинок, щоб менше відчувати втому.","ru":"Лучше ехать без остановок, чтобы меньше ощущать усталость.","w":{"uk":"Без зупинок утома накопичується непомітно: реакція сповільнюється, увага розсіюється, і водій може задрімати.","ru":"Без остановок усталость накапливается незаметно: реакция замедляется, внимание рассеивается, и водитель может задремать."}},{"uk":"Краще їхати протягом дня і робити багато перерв для відпочинку.","ru":"Лучше ехать в течение дня и делать много перерывов для отдыха."}],"c":2,"e":{"uk":"Удень краща видимість, а організм бадьорий. Регулярні перерви (приблизно кожні 2 години) знімають утому й відновлюють увагу, а керувати в стані стомлення заборонено ({p:2.9}).","ru":"Днём лучше видимость, а организм бодр. Регулярные перерывы (примерно каждые 2 часа) снимают усталость и восстанавливают внимание, а управлять в состоянии утомления запрещено ({p:2.9})."},"ref":["2.9"],"pic":["img/hsc/35-143-1.jpg"]},{"id":"h35-144","t":"h35","num":"35.144","q":{"uk":"Ви хочете обігнати велосипедиста. Що Ви повинні врахувати при оцінці бокового інтервалу?","ru":"Вы хотите обогнать велосипедиста. Что вы должны учесть при оценке бокового интервала?"},"a":[{"uk":"Бокова відстань в 1,0 м є завжди достатньою.","ru":"Боковое расстояние 1,0 м всегда является достаточным.","w":{"uk":"Фіксованого «завжди достатнього» інтервалу немає: на більшій швидкості, за вітру чи біля невпевненого велосипедиста одного метра замало.","ru":"Фиксированного «всегда достаточного» интервала нет: на большей скорости, при ветре или рядом с неуверенным велосипедистом одного метра мало."}},{"uk":"Поведінку велосипедиста.","ru":"Поведение велосипедиста.","w":{"uk":"Поведінку велосипедиста враховують, але інтервал залежить і від вашої швидкості.","ru":"Поведение велосипедиста учитывают, но интервал зависит и от вашей скорости."}},{"uk":"Швидкість свого транспортного засобу.","ru":"Скорость своего транспортного средства.","w":{"uk":"Швидкість важлива, але так само важливо, як поводиться велосипедист: хитається він чи їде впевнено.","ru":"Скорость важна, но так же важно, как ведёт себя велосипедист: шатается он или едет уверенно."}},{"uk":"Відповіді 2 і 3.","ru":"Ответы 2 и 3."}],"c":3,"e":{"uk":"Безпечний інтервал залежить від швидкості та дорожньої обстановки ({p:13.1}, {p:13.3}). Велосипедист може похитнутися чи відхилитися, об'їжджаючи вибоїну, а що вища ваша швидкість, то сильніший потік повітря, який його розгойдує, тож інтервал має бути більшим.","ru":"Безопасный интервал зависит от скорости и дорожной обстановки ({p:13.1}, {p:13.3}). Велосипедист может покачнуться или отклониться, объезжая выбоину, а чем выше ваша скорость, тем сильнее поток воздуха, который его раскачивает, поэтому интервал должен быть больше."},"ref":["13.1","13.3"]},{"id":"h35-145","t":"h35","num":"35.145","q":{"uk":"Як сприймається водієм швидкість його автомобіля у випадку тривалого руху рівнинною дорогою з великою швидкістю?","ru":"Как воспринимается водителем скорость его автомобиля в случае длительного движения по равнинной дороге с большой скоростью?"},"a":[{"uk":"Здається меншою, ніж насправді.","ru":"Кажется меньше, чем на самом деле."},{"uk":"Здається більшою, ніж насправді.","ru":"Кажется больше, чем на самом деле.","w":{"uk":"Відчуття швидкості з часом притуплюється, а не загострюється: звична швидкість здається меншою.","ru":"Ощущение скорости со временем притупляется, а не обостряется: привычная скорость кажется меньше."}},{"uk":"Сприйняття швидкості не змінюється.","ru":"Восприятие скорости не меняется.","w":{"uk":"Сприйняття змінюється: організм адаптується до швидкості, і водій недооцінює її.","ru":"Восприятие меняется: организм адаптируется к скорости, и водитель недооценивает её."}}],"c":0,"e":{"uk":"За тривалого руху з великою швидкістю водій звикає до неї, і вона починає здаватися меншою, ніж є. Особливо небезпечно це після з'їзду з траси, у населеному пункті чи перед поворотом, тому швидкість контролюють за спідометром.","ru":"При длительном движении с большой скоростью водитель привыкает к ней, и она начинает казаться меньше, чем есть. Особенно опасно это после съезда с трассы, в населённом пункте или перед поворотом, поэтому скорость контролируют по спидометру."},"pic":["img/hsc/35-145-1.jpg"]},{"id":"h35-146","t":"h35","num":"35.146","q":{"uk":"Який стиль водіння забезпечить найменшу витрату палива?","ru":"Какой стиль вождения обеспечит наименьший расход топлива?"},"a":[{"uk":"Часте і різке прискорення при плавному уповільненні.","ru":"Частое и резкое ускорение при плавном замедлении.","w":{"uk":"Часті різкі прискорення найбільше збільшують витрату: двигун працює на високих обертах із збагаченою сумішшю.","ru":"Частые резкие ускорения сильнее всего увеличивают расход: двигатель работает на высоких оборотах с обогащённой смесью."}},{"uk":"Плавне прискорення при різкому уповільненні.","ru":"Плавное ускорение при резком замедлении.","w":{"uk":"Різке гальмування марно «спалює» в гальмах енергію, на яку вже витрачено паливо; плавне уповільнення дало б змогу проїхати накатом.","ru":"Резкое торможение впустую «сжигает» в тормозах энергию, на которую уже потрачено топливо; плавное замедление позволило бы проехать накатом."}},{"uk":"Плавне прискорення при плавному уповільненні.","ru":"Плавное ускорение при плавном замедлении."}],"c":2,"e":{"uk":"Різкий розгін потребує високих обертів і збагаченої суміші, а різке гальмування марно перетворює набрану швидкість на тепло в гальмах. Плавний розгін і завчасне плавне уповільнення з гальмуванням двигуном дають найменшу витрату палива.","ru":"Резкий разгон требует высоких оборотов и обогащённой смеси, а резкое торможение впустую превращает набранную скорость в тепло в тормозах. Плавный разгон и заблаговременное плавное замедление с торможением двигателем дают наименьший расход топлива."}},{"id":"h35-147","t":"h35","num":"35.147","q":{"uk":"У темну пору доби та в похмуру погоду швидкість зустрічного автомобіля видається:","ru":"В тёмное время суток и в пасмурную погоду скорость встречного автомобиля кажется:"},"a":[{"uk":"Нижчою, ніж насправді.","ru":"Ниже, чем на самом деле."},{"uk":"Вищою, ніж насправді.","ru":"Выше, чем на самом деле.","w":{"uk":"Погана видимість не перебільшує, а занижує швидкість: тьмяні вогні сприймаються як віддалені й повільні.","ru":"Плохая видимость не преувеличивает, а занижает скорость: тусклые огни воспринимаются как удалённые и медленные."}},{"uk":"Сприйняття швидкості не змінюється.","ru":"Восприятие скорости не меняется.","w":{"uk":"Сприйняття змінюється: без чітких обрисів і орієнтирів мозок недооцінює швидкість зустрічного автомобіля.","ru":"Восприятие меняется: без чётких очертаний и ориентиров мозг недооценивает скорость встречного автомобиля."}}],"c":0,"e":{"uk":"У темряві та в похмуру погоду видно лише вогні чи розмиті обриси автомобіля, а орієнтирів довкола мало, тож відстань і швидкість оцінити важко. Зустрічний автомобіль здається віддаленішим і повільнішим, ніж насправді, тому треба залишати більший запас.","ru":"В темноте и в пасмурную погоду видны лишь огни или размытые очертания автомобиля, а ориентиров вокруг мало, поэтому расстояние и скорость оценить трудно. Встречный автомобиль кажется более удалённым и медленным, чем на самом деле, поэтому нужно оставлять больший запас."},"pic":["img/hsc/35-147-1.jpg"]},{"id":"h35-148","t":"h35","num":"35.148","q":{"uk":"Відносно якої лінії дорожньої розмітки найбільш безпечно контролювати положення свого автомобіля при зустрічному роз’їзді в темний час доби?","ru":"Относительно какой линии дорожной разметки наиболее безопасно контролировать положение своего автомобиля при встречном разъезде в тёмное время суток?"},"a":[{"uk":"Відносно лінії, що позначає лівий край проїжджої частини дороги.","ru":"Относительно линии, обозначающей левый край проезжей части дороги.","w":{"uk":"Лівий край проїзної частини — за зустрічною смугою: дивлячись туди, водій дивиться просто крізь світло зустрічних фар.","ru":"Левый край проезжей части — за встречной полосой: глядя туда, водитель смотрит прямо сквозь свет встречных фар."}},{"uk":"Відносно лінії, що позначає правий край проїжджої частини дороги.","ru":"Относительно линии, обозначающей правый край проезжей части дороги."},{"uk":"Відносно лінії, що розділяє транспортні потоки протилежних напрямків","ru":"Относительно линии, разделяющей транспортные потоки противоположных направлений.","w":{"uk":"Осьова лінія поруч із зустрічними фарами: орієнтуючись на неї, водій дивиться в осліплювальне світло й мимоволі зміщується до зустрічного автомобіля.","ru":"Осевая линия рядом со встречными фарами: ориентируясь на неё, водитель смотрит в ослепляющий свет и невольно смещается к встречному автомобилю."}}],"c":1,"e":{"uk":"Дивлячись на лінію правого краю проїзної частини ({m:1.2}), водій виводить фари зустрічного автомобіля з центру поля зору й водночас точно тримає своє положення на смузі. Швидкість при цьому знижують до безпечної за фактичною видимістю ({p:19.3}).","ru":"Глядя на линию правого края проезжей части ({m:1.2}), водитель выводит фары встречного автомобиля из центра поля зрения и одновременно точно держит своё положение на полосе. Скорость при этом снижают до безопасной по фактической видимости ({p:19.3})."},"ref":["19.3"],"pic":["img/hsc/35-148-1.jpg"]},{"id":"h35-149","t":"h35","num":"35.149","q":{"uk":"Гальмівний шлях на дорозі одразу після дощу:","ru":"Тормозной путь на дороге сразу после дождя:"},"a":[{"uk":"Збільшується.","ru":"Увеличивается."},{"uk":"Зменшується.","ru":"Уменьшается.","w":{"uk":"Дощ не покращує зчеплення: на мокрому покритті шини тримають гірше, ніж на сухому.","ru":"Дождь не улучшает сцепление: на мокром покрытии шины держат хуже, чем на сухом."}},{"uk":"Не змінюється.","ru":"Не изменяется.","w":{"uk":"Доки покриття мокре, зчеплення гірше, тож гальмовий шлях довший, ніж на сухій дорозі.","ru":"Пока покрытие мокрое, сцепление хуже, поэтому тормозной путь длиннее, чем на сухой дороге."}}],"c":0,"e":{"uk":"Вода на покритті погіршує зчеплення шин з дорогою, а в перші хвилини дощу вона ще й змішується з пилом, мастилом і гумовим нальотом у слизьку плівку. Тому гальмовий шлях на мокрій дорозі довший, ніж на сухій.","ru":"Вода на покрытии ухудшает сцепление шин с дорогой, а в первые минуты дождя она ещё и смешивается с пылью, маслом и резиновым налётом в скользкую плёнку. Поэтому тормозной путь на мокрой дороге длиннее, чем на сухой."},"pic":["img/hsc/35-149-1.jpg"]},{"id":"h35-150","t":"h35","num":"35.150","q":{"uk":"Під час руху в транспортному потоці водій, що рухався по сусідній смузі, різко перелаштувався на Вашу смугу руху, змусивши Вас загальмувати. Що необхідно Вам зробити в даній ситуації?","ru":"Во время движения в транспортном потоке водитель, двигавшийся по соседней полосе, резко перестроился на вашу полосу движения, вынудив вас затормозить. Что необходимо вам сделать в данной ситуации?"},"a":[{"uk":"Подати світловий сигнал фарами.","ru":"Подать световой сигнал фарами.","w":{"uk":"Миготіння фарами після того, як маневр завершено, нічого не виправляє, лише провокує конфлікт і відволікає обох водіїв.","ru":"Мигание фарами после того, как манёвр завершён, ничего не исправляет, лишь провоцирует конфликт и отвлекает обоих водителей."}},{"uk":"Випередити порушника, перестроїтись перед ним на його смугу і різко загальмувати.","ru":"Опередить нарушителя, перестроиться перед ним на его полосу и резко затормозить.","w":{"uk":"Різке гальмування перед іншим автомобілем заборонене ({p:12.9}) і може спричинити зіткнення — це помста, яка створює аварійну ситуацію.","ru":"Резкое торможение перед другим автомобилем запрещено ({p:12.9}) и может привести к столкновению — это месть, которая создаёт аварийную ситуацию."}},{"uk":"На найближчому світлофорі при сигналі, що забороняє рух, підійти до його автомобілю і зробити зауваження порушнику.","ru":"На ближайшем светофоре при сигнале, запрещающем движение, подойти к его автомобилю и сделать замечание нарушителю.","w":{"uk":"Виходити з автомобіля на проїзну частину посеред потоку небезпечно й заборонено, якщо це створює загрозу чи перешкоди ({p:15.13}), а суперечка може перерости в бійку.","ru":"Выходить из автомобиля на проезжую часть посреди потока опасно и запрещено, если это создаёт угрозу или помехи ({p:15.13}), а спор может перерасти в драку."}},{"uk":"Неприпустима жодна з перерахованих дій.","ru":"Недопустимо ни одно из перечисленных действий."}],"c":3,"e":{"uk":"Небезпека вже минула, і будь-яка «відповідь» лише розпалює конфлікт та створює нову загрозу. Слід зберігати спокій, відновити безпечну дистанцію ({p:13.1}) і продовжувати рух, не створюючи своїми діями загрози безпеці ({p:2.3}).","ru":"Опасность уже миновала, и любой «ответ» лишь разжигает конфликт и создаёт новую угрозу. Следует сохранять спокойствие, восстановить безопасную дистанцию ({p:13.1}) и продолжать движение, не создавая своими действиями угрозы безопасности ({p:2.3})."},"ref":["2.3","13.1"],"pic":["img/hsc/35-150-1.jpg"]},{"id":"h35-151","t":"h35","num":"35.151","q":{"uk":"Чим гірша видимість, тим меншою має бути швидкість руху:","ru":"Чем хуже видимость, тем меньше должна быть скорость движения:"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"Якщо видимість зменшилася, а швидкість ні, перешкода з'явиться ближче, ніж гальмовий шлях, і зупинитися перед нею не вдасться.","ru":"Если видимость уменьшилась, а скорость нет, препятствие появится ближе, чем тормозной путь, и остановиться перед ним не удастся."}}],"c":0,"e":{"uk":"Швидкість має бути такою, щоб водій міг зупинитися в межах видимості дороги ({p:12.2}). Що менша видима ділянка, то менше місця для гальмування, отже, тим нижчою має бути швидкість.","ru":"Скорость должна быть такой, чтобы водитель мог остановиться в пределах видимости дороги ({p:12.2}). Чем меньше видимый участок, тем меньше места для торможения, следовательно, тем ниже должна быть скорость."},"ref":["12.2"],"pic":["img/hsc/35-151-1.jpg"]},{"id":"h35-152","t":"h35","num":"35.152","q":{"uk":"Чим гірша видимість, тим більшою має бути швидкість руху:","ru":"Чем хуже видимость, тем больше должна быть скорость движения:"},"a":[{"uk":"Так.","ru":"Да.","w":{"uk":"З більшою швидкістю гальмовий шлях довший, і за поганої видимості водій не встигне зупинитися перед перешкодою, яку помітить надто пізно.","ru":"С большей скоростью тормозной путь длиннее, и при плохой видимости водитель не успеет остановиться перед препятствием, которое заметит слишком поздно."}},{"uk":"Ні.","ru":"Нет."}],"c":1,"e":{"uk":"Навпаки: швидкість має дозволяти зупинитися в межах видимості дороги ({p:12.2}), тож за гіршої видимості її знижують.","ru":"Наоборот: скорость должна позволять остановиться в пределах видимости дороги ({p:12.2}), поэтому при худшей видимости её снижают."},"ref":["12.2"],"pic":["img/hsc/35-152-1.jpg"]},{"id":"h35-153","t":"h35","num":"35.153","q":{"uk":"Чи дозволено водієві відчиняти двері транспортного засобу до його повної зупинки?","ru":"Разрешено ли водителю открывать двери транспортного средства до его полной остановки?"},"a":[{"uk":"Заборонено.","ru":"Запрещено."},{"uk":"Дозволено, якщо поруч немає пішоходів або інших транспортних засобів.","ru":"Разрешено, если рядом нет пешеходов или других транспортных средств.","w":{"uk":"Навіть коли поруч нікого не видно, відчинені на ходу двері відволікають водія, можуть зачепитися за перешкоду, а велосипедист може з'явитися зі «сліпої зони».","ru":"Даже когда рядом никого не видно, открытая на ходу дверь отвлекает водителя, может зацепиться за препятствие, а велосипедист может появиться из «слепой зоны»."}},{"uk":"Дозволено в будь-якому випадку.","ru":"Разрешено в любом случае.","w":{"uk":"Відчиняти двері на ходу небезпечно за будь-яких умов: можна травмувати інших учасників руху або випасти самому.","ru":"Открывать двери на ходу опасно при любых условиях: можно травмировать других участников движения или выпасть самому."}}],"c":0,"e":{"uk":"Відчинені на ходу двері можуть зачепити пішохода, велосипедиста чи інший транспортний засіб, а людина може випасти з автомобіля. Відчиняти двері можна лише після зупинки й лише тоді, коли це нікому не загрожує ({p:15.13}); пасажирам відчиняти двері до зупинки прямо заборонено ({p:5.3}).","ru":"Открытая на ходу дверь может задеть пешехода, велосипедиста или другое транспортное средство, а человек может выпасть из автомобиля. Открывать двери можно только после остановки и только тогда, когда это никому не угрожает ({p:15.13}); пассажирам открывать двери до остановки прямо запрещено ({p:5.3})."},"ref":["15.13","5.3"],"pic":["img/hsc/35-153-1.jpg"]},{"id":"h35-154","t":"h35","num":"35.154","q":{"uk":"Чи дозволено пасажирам відчиняти двері транспортного засобу до його зупинки?","ru":"Разрешено ли пассажирам открывать двери транспортного средства до его остановки?"},"a":[{"uk":"Заборонено.","ru":"Запрещено."},{"uk":"Дозволено, якщо поруч немає інших транспортних засобів.","ru":"Разрешено, если рядом нет других транспортных средств.","w":{"uk":"{p:5.3} забороняє відчиняти двері до зупинки незалежно від того, чи є поруч транспорт: ризикують і пішоходи, і сам пасажир.","ru":"{p:5.3} запрещает открывать двери до остановки независимо от того, есть ли рядом транспорт: рискуют и пешеходы, и сам пассажир."}},{"uk":"Дозволено в будь-якому випадку.","ru":"Разрешено в любом случае.","w":{"uk":"Такого дозволу немає: {p:5.3} прямо забороняє пасажирам відчиняти двері, доки транспортний засіб не зупинився.","ru":"Такого разрешения нет: {p:5.3} прямо запрещает пассажирам открывать двери, пока транспортное средство не остановилось."}}],"c":0,"e":{"uk":"Пасажирам заборонено відчиняти двері, не переконавшись, що транспортний засіб зупинився біля тротуару, посадкового майданчика, краю проїзної частини чи на узбіччі ({p:5.3}). Двері, відчинені на ходу, можуть зачепити пішохода чи велосипедиста, а пасажир — випасти.","ru":"Пассажирам запрещено открывать двери, не убедившись, что транспортное средство остановилось у тротуара, посадочной площадки, края проезжей части или на обочине ({p:5.3}). Двери, открытые на ходу, могут задеть пешехода или велосипедиста, а пассажир — выпасть."},"ref":["5.3"],"pic":["img/hsc/35-154-1.jpg"]},{"id":"h35-155","t":"h35","num":"35.155","q":{"uk":"Як ви повинні вчинити в ситуації, наближаючись до автобуса, який виконує посадку або висадку організованих груп дітей?","ru":"Как вы должны поступить в ситуации, приближаясь к автобусу, который выполняет посадку или высадку организованных групп детей?"},"a":[{"uk":"Проїхати, не знижуючи швидкість, але забезпечивши достатній боковий інтервал.","ru":"Проехать, не снижая скорости, но обеспечив достаточный боковой интервал.","w":{"uk":"Боковий інтервал не врятує, якщо дитина вибіжить з-за автобуса просто перед вами: швидкість потрібно знизити ({p:18.9}).","ru":"Боковой интервал не спасёт, если ребёнок выбежит из-за автобуса прямо перед вами: скорость нужно снизить ({p:18.9})."}},{"uk":"Знизити швидкість, а в разі потреби зупинитися, бути максимально обережним.","ru":"Снизить скорость, а при необходимости остановиться, быть максимально осторожным."},{"uk":"Подати звуковий сигнал, щоб привернути до себе увагу.","ru":"Подать звуковой сигнал, чтобы привлечь к себе внимание.","w":{"uk":"Звуковий сигнал може налякати дітей, і вони кинуться врізнобіч, зокрема на дорогу; безпеку забезпечує лише знижена швидкість.","ru":"Звуковой сигнал может напугать детей, и они бросятся врассыпную, в том числе на дорогу; безопасность обеспечивает только сниженная скорость."}},{"uk":"Відповіді 1 і 3.","ru":"Ответы 1 и 3.","w":{"uk":"Обидва варіанти хибні: проїжджати, не знижуючи швидкості, і сигналити біля дітей небезпечно.","ru":"Оба варианта ошибочны: проезжать, не снижая скорости, и сигналить возле детей опасно."}}],"c":1,"e":{"uk":"Під час посадки чи висадки діти можуть раптово вибігти з-за автобуса на дорогу. Наближаючись до автобуса зі знаком «Діти», водії зобов'язані знизити швидкість, а в разі потреби зупинитися ({p:18.9}); до дітей треба бути особливо обережним ({p:1.7}).","ru":"Во время посадки или высадки дети могут внезапно выбежать из-за автобуса на дорогу. Приближаясь к автобусу со знаком «Дети», водители обязаны снизить скорость, а при необходимости остановиться ({p:18.9}); по отношению к детям нужно быть особенно осторожным ({p:1.7})."},"ref":["18.9","1.7"],"pic":["img/hsc/35-155-1.jpg"]},{"id":"h35-156","t":"h35","num":"35.156","q":{"uk":"У даній ситуації найбільшу увагу слід зосередити на зоні:","ru":"В данной ситуации наибольшее внимание следует сосредоточить на:"},"a":[{"uk":"Зоні А.","ru":"Зоне A.","w":{"uk":"Зона A — автомобілі, припарковані за зустрічною смугою: вони далеко від вашої траєкторії, і раптова небезпека звідти менш імовірна, ніж з-за автобуса.","ru":"Зона A — автомобили, припаркованные за встречной полосой: они далеко от вашей траектории, и внезапная опасность оттуда менее вероятна, чем из-за автобуса."}},{"uk":"Зоні В.","ru":"Зоне B."}],"c":1,"e":{"uk":"Справа на зупинці стоїть автобус: пішоходи, які з нього вийшли, можуть переходити дорогу перед ним і з'явитися на вашій смузі просто з-за його передньої частини, а сам автобус може рушити. Тому зона B потребує найбільшої уваги й готовності знизити швидкість аж до зупинки ({p:12.3}).","ru":"Справа на остановке стоит автобус: пешеходы, которые из него вышли, могут переходить дорогу перед ним и появиться на вашей полосе прямо из-за его передней части, а сам автобус может тронуться. Поэтому зона B требует наибольшего внимания и готовности снизить скорость вплоть до остановки ({p:12.3})."},"ref":["12.3","1.7"],"pic":["img/hsc/35-156-1.jpg"]},{"id":"h35-157","t":"h35","num":"35.157","q":{"uk":"Найбільша небезпека у даному випадку зосереджена у:","ru":"Наибольшая опасность в данном случае сосредоточена в:"},"a":[{"uk":"Зоні А.","ru":"Зоне A.","w":{"uk":"У зоні A — автомобіль ліворуч, на віддалі від вашої смуги; його рух видно й легко передбачити.","ru":"В зоне A — автомобиль слева, на удалении от вашей полосы; его движение видно и легко предсказать."}},{"uk":"Зоні В.","ru":"Зоне B.","w":{"uk":"У зоні B автомобіль їде попереду в тому самому напрямку: досить тримати безпечну дистанцію ({p:13.1}).","ru":"В зоне B автомобиль едет впереди в том же направлении: достаточно держать безопасную дистанцию ({p:13.1})."}},{"uk":"Зоні С.","ru":"Зоне C."},{"uk":"Зоні D.","ru":"Зоне D.","w":{"uk":"Зона D — дзеркало заднього виду: обстановку позаду контролюють, але ви рухаєтеся прямо, і безпосередня загроза — попереду праворуч.","ru":"Зона D — зеркало заднего вида: обстановку сзади контролируют, но вы движетесь прямо, и непосредственная угроза — впереди справа."}}],"c":2,"e":{"uk":"У зоні C між припаркованими автомобілями біля самого краю проїзної частини стоїть пішохід: він може будь-якої миті ступити на дорогу або відчинити двері автомобіля просто перед вами. Тому тут готуються знизити швидкість аж до зупинки ({p:12.3}) і тримають більший боковий інтервал.","ru":"В зоне C между припаркованными автомобилями у самого края проезжей части стоит пешеход: он может в любой момент ступить на дорогу или открыть дверь автомобиля прямо перед вами. Поэтому здесь готовятся снизить скорость вплоть до остановки ({p:12.3}) и держат больший боковой интервал."},"ref":["12.3"],"pic":["img/hsc/35-157-1.jpg"]},{"id":"h35-158","t":"h35","num":"35.158","q":{"uk":"У цьому випадку за появи зустрічного автомобіля водій білого повинен:","ru":"В этом случае при появлении встречного автомобиля водитель белого автомобиля должен:"},"a":[{"uk":"Переключитись на ближнє світло фар.","ru":"Переключиться на ближний свет фар."},{"uk":"Продовжити рух із увімкненим дальнім світлом фар.","ru":"Продолжить движение с включённым дальним светом фар.","w":{"uk":"З дальнім світлом засліплений зустрічний водій може виїхати на вашу смугу; {p:19.2} вимагає перемкнути світло на ближнє.","ru":"С дальним светом ослеплённый встречный водитель может выехать на вашу полосу; {p:19.2} требует переключить свет на ближний."}}],"c":0,"e":{"uk":"Дальнє світло засліплює зустрічного водія, і той на кілька секунд перестає бачити дорогу. Тому його перемикають на ближнє не менш як за 250 м до зустрічного транспортного засобу ({p:19.2}).","ru":"Дальний свет ослепляет встречного водителя, и тот на несколько секунд перестаёт видеть дорогу. Поэтому его переключают на ближний не менее чем за 250 м до встречного транспортного средства ({p:19.2})."},"ref":["19.2"],"pic":["img/hsc/35-158-1.jpg"]},{"id":"h35-159","t":"h35","num":"35.159","q":{"uk":"Чому швидкість водіїв-початківців має бути нижчою, ніж в інших водіїв?","ru":"Почему скорость водителей-новичков должна быть ниже, чем у других водителей?"},"a":[{"uk":"Час реакції у таких водіїв-початківців більше.","ru":"Время реакции у таких водителей-новичков больше.","w":{"uk":"Більший час реакції — лише одна причина; не менш важливо, що початківцеві бракує досвіду оцінювати дорожню обстановку.","ru":"Большее время реакции — лишь одна причина; не менее важно, что новичку не хватает опыта оценивать дорожную обстановку."}},{"uk":"Здатність повноцінно орієнтуватись у дорожній обстановці приходить після багаторазових повторень та аналізу прийнятих рішень та дій.","ru":"Способность полноценно ориентироваться в дорожной обстановке приходит после многократных повторений и анализа принятых решений и действий.","w":{"uk":"Брак досвіду справді важливий, але й час реакції в початківця більший — правильні обидві відповіді.","ru":"Недостаток опыта действительно важен, но и время реакции у новичка больше — верны оба ответа."}},{"uk":"Відповіді 1 та 2.","ru":"Ответы 1 и 2."}],"c":2,"e":{"uk":"Початківець ще свідомо обдумує кожну дію, тому реагує повільніше, а вміння швидко оцінювати обстановку й передбачати дії інших приходить лише з досвідом. Тому Правила обмежують швидкість водіїв зі стажем до 2 років поза населеними пунктами 70 км/год ({p:12.6}).","ru":"Новичок ещё сознательно обдумывает каждое действие, поэтому реагирует медленнее, а умение быстро оценивать обстановку и предвидеть действия других приходит только с опытом. Поэтому Правила ограничивают скорость водителей со стажем до 2 лет вне населённых пунктов 70 км/ч ({p:12.6})."},"ref":["12.6"],"pic":["img/hsc/35-159-1.jpg"]},{"id":"h35-160","t":"h35","num":"35.160","q":{"uk":"Дивлячись на зону С в даному випадку я повинен враховувати, що:","ru":"Глядя на зону C в данном случае, я должен учитывать, что:"},"a":[{"uk":"Пішохід у будь-який момент може розпочати рух.","ru":"Пешеход в любой момент может начать движение."},{"uk":"Пішохід обов’язково пропустить мене.","ru":"Пешеход обязательно пропустит меня.","w":{"uk":"Розраховувати на те, що пішохід вас пропустить, не можна: він може вас не побачити чи неправильно оцінити відстань.","ru":"Рассчитывать на то, что пешеход вас пропустит, нельзя: он может вас не увидеть или неверно оценить расстояние."}}],"c":0,"e":{"uk":"Пішохід стоїть між припаркованими автомобілями біля самого краю проїзної частини й будь-якої миті може ступити на дорогу, не помітивши вас. Тому водій готовий знизити швидкість аж до зупинки ({p:12.3}) і особливо уважний до пішоходів ({p:1.7}).","ru":"Пешеход стоит между припаркованными автомобилями у самого края проезжей части и в любой момент может ступить на дорогу, не заметив вас. Поэтому водитель готов снизить скорость вплоть до остановки ({p:12.3}) и особенно внимателен к пешеходам ({p:1.7})."},"ref":["12.3","1.7"],"pic":["img/hsc/35-160-1.jpg"]},{"id":"h35-161","t":"h35","num":"35.161","q":{"uk":"Попереду Вас рухається велосипедист, який постійно різко пригальмовує. Ви:","ru":"Впереди вас движется велосипедист, который постоянно резко притормаживает. Вы:"},"a":[{"uk":"Попереджу велосипедиста, що рухається попереду тривалим звуковим сигналом.","ru":"Предупрежу велосипедиста, движущегося впереди, длительным звуковым сигналом.","w":{"uk":"Різкий тривалий сигнал може налякати велосипедиста, і він впаде чи вильне просто перед вами; у населеному пункті сигнал дозволений лише для запобігання ДТП ({p:9.5}).","ru":"Резкий длительный сигнал может напугать велосипедиста, и он упадёт или вильнёт прямо перед вами; в населённом пункте сигнал разрешён только для предотвращения ДТП ({p:9.5})."}},{"uk":"Буду зберігати спокій, за необхідності зменшу швидкість, буду готовим зупинитись та продовжу уважно слідкувати за дорожньою обстановкою.","ru":"Буду сохранять спокойствие, при необходимости снижу скорость, буду готов остановиться и продолжу внимательно следить за дорожной обстановкой."}],"c":1,"e":{"uk":"Велосипедист, що постійно різко пригальмовує, поводиться непередбачувано, тож безпечніше збільшити дистанцію ({p:13.1}), бути готовим зупинитися й не нервувати. До велосипедистів водії мають бути особливо уважними ({p:1.7}).","ru":"Велосипедист, постоянно резко притормаживающий, ведёт себя непредсказуемо, поэтому безопаснее увеличить дистанцию ({p:13.1}), быть готовым остановиться и не нервничать. К велосипедистам водители должны быть особенно внимательны ({p:1.7})."},"ref":["13.1","1.7"]},{"id":"h35-162","t":"h35","num":"35.162","q":{"uk":"Відкриваючи двері транспортного засобу зі сторони проїжджої частини, на що слід звернути увагу?","ru":"Открывая двери транспортного средства со стороны проезжей части, на что следует обратить внимание?"},"a":[{"uk":"Відкривати двері необхідно різко.","ru":"Открывать двери необходимо резко.","w":{"uk":"Різко відчинені двері не дають велосипедистові чи водієві, що наближається, часу зреагувати — він урізається в них.","ru":"Резко открытая дверь не даёт велосипедисту или приближающемуся водителю времени среагировать — он врезается в неё."}},{"uk":"Переконатися, що всі водії, що рухаються позаду, зрозуміли Ваші наміри.","ru":"Убедиться, что все водители, движущиеся сзади, поняли ваши намерения.","w":{"uk":"Немає способу переконатися, що всі «зрозуміли наміри»; відчиняти двері можна лише тоді, коли поруч ніхто не їде.","ru":"Нет способа убедиться, что все «поняли намерения»; открывать дверь можно только тогда, когда рядом никто не едет."}},{"uk":"Відкривати двері лише, коли впевнились в тому, що це не загрожує іншим учасникам дорожнього руху.","ru":"Открывать двери только тогда, когда убедились в том, что это не угрожает другим участникам дорожного движения."}],"c":2,"e":{"uk":"Відчиняти двері заборонено, якщо це загрожує безпеці чи створює перешкоди іншим учасникам руху ({p:15.13}). Перед цим перевіряють у дзеркалі й через плече, чи не наближаються велосипедист або автомобіль; зручно відчиняти двері дальньою від них рукою — так тіло саме повертається назад.","ru":"Открывать двери запрещено, если это угрожает безопасности или создаёт помехи другим участникам движения ({p:15.13}). Перед этим проверяют в зеркале и через плечо, не приближаются ли велосипедист или автомобиль; удобно открывать дверь дальней от неё рукой — так тело само поворачивается назад."},"ref":["15.13"],"pic":["img/hsc/35-162-1.jpg"]},{"id":"h35-163","t":"h35","num":"35.163","q":{"uk":"Чи обов'язково водієві, стаж водіння якого менше двох років, вішати відповідний розпізнавальний знак на автомобіль?","ru":"Обязательно ли водителю, стаж вождения которого меньше двух лет, вешать соответствующий опознавательный знак на автомобиль?"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"{p:30.3} прямо вимагає розміщувати знак «Обмеження максимальної швидкості» на транспортних засобах, якими керують водії зі стажем до 2 років.","ru":"{p:30.3} прямо требует размещать знак «Ограничение максимальной скорости» на транспортных средствах, которыми управляют водители со стажем до 2 лет."}}],"c":0,"e":{"uk":"Водії зі стажем до 2 років поза населеними пунктами можуть їхати не швидше 70 км/год ({p:12.6}), тому ззаду ліворуч на їхньому автомобілі розміщують розпізнавальний знак «Обмеження максимальної швидкості» — зображення знака {s:3.29} з числом 70 ({p:30.3}). Він попереджає інших водіїв, що цей автомобіль рухатиметься повільніше.","ru":"Водители со стажем до 2 лет вне населённых пунктов могут ехать не быстрее 70 км/ч ({p:12.6}), поэтому сзади слева на их автомобиле размещают опознавательный знак «Ограничение максимальной скорости» — изображение знака {s:3.29} с числом 70 ({p:30.3}). Он предупреждает других водителей, что этот автомобиль будет двигаться медленнее."},"ref":["30.3","12.6"],"pic":["img/hsc/35-163-1.jpg"]},{"id":"h35-164","t":"h35","num":"35.164","q":{"uk":"Якщо Ви рухаєтесь прямо на зелений сигнал світлофора, чи потрібно Вам зменшити швидкість у даному випадку?","ru":"Если вы движетесь прямо на зелёный сигнал светофора, нужно ли вам снизить скорость в данном случае?"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"Зелений сигнал не гарантує вільного перехрестя: {p:16.5} вимагає пропустити тих, хто завершує рух чи перехід, а білий автомобіль ще перетинає вашу траєкторію.","ru":"Зелёный сигнал не гарантирует свободного перекрёстка: {p:16.5} требует пропустить тех, кто завершает движение или переход, а белый автомобиль ещё пересекает вашу траекторию."}}],"c":0,"e":{"uk":"Хоча для вас горить зелений, перехрестям ще рухається білий автомобіль, а біля пішохідного переходу є люди. На дозвільний сигнал водій зобов'язаний дати дорогу транспортним засобам, що завершують рух через перехрестя, і пішоходам, які закінчують перехід ({p:16.5}), тож швидкість слід знизити ({p:12.3}).","ru":"Хотя для вас горит зелёный, по перекрёстку ещё движется белый автомобиль, а у пешеходного перехода есть люди. На разрешающий сигнал водитель обязан уступить дорогу транспортным средствам, завершающим движение через перекрёсток, и пешеходам, заканчивающим переход ({p:16.5}), поэтому скорость следует снизить ({p:12.3})."},"ref":["16.5","12.3"],"pic":["img/hsc/35-164-1.jpg"]},{"id":"h35-165","t":"h35","num":"35.165","q":{"uk":"Ви наближаєтесь до пішохідного переходу, на підходах до якого та безпосередньо на ньому немає пішоходів. Чи можете Ви проїхати, не зменшуючи швидкість?","ru":"Вы приближаетесь к пешеходному переходу, на подходах к которому и непосредственно на нём нет пешеходов. Можете ли вы проехать, не снижая скорости?"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"Правила не вимагають знижувати швидкість перед кожним переходом: такий обов'язок виникає, коли на ньому є пішоходи ({p:18.1}) або перед ним зупинився транспорт на сусідній смузі ({p:18.4}).","ru":"Правила не требуют снижать скорость перед каждым переходом: такая обязанность возникает, когда на нём есть пешеходы ({p:18.1}) или перед ним остановился транспорт на соседней полосе ({p:18.4})."}}],"c":0,"e":{"uk":"Знизити швидкість, а в разі потреби зупинитися водій зобов'язаний, коли на нерегульованому переході є пішоходи ({p:18.1}). Коли ні на переході, ні біля нього нікого немає, огляд відкритий і перед переходом ніхто не зупинився, можна проїхати з дозволеною швидкістю, залишаючись уважним.","ru":"Снизить скорость, а при необходимости остановиться водитель обязан, когда на нерегулируемом переходе есть пешеходы ({p:18.1}). Когда ни на переходе, ни возле него никого нет, обзор открыт и перед переходом никто не остановился, можно проехать с разрешённой скоростью, оставаясь внимательным."},"ref":["18.1"],"pic":["img/hsc/35-165-1.jpg"]},{"id":"h35-166","t":"h35","num":"35.166","q":{"uk":"Чи дозволено водієві сірого автомобіля виконати зупинку у цьому місці?","ru":"Разрешено ли водителю серого автомобиля выполнить остановку в этом месте?"},"a":[{"uk":"Дозволено.","ru":"Разрешено.","w":{"uk":"До переходу менше 10 м, тож зупинка тут заборонена ({p:15.9}): пішохід, що виходить з-за автомобіля, стає невидимим для інших водіїв.","ru":"До перехода меньше 10 м, поэтому остановка здесь запрещена ({p:15.9}): пешеход, выходящий из-за автомобиля, становится невидимым для других водителей."}},{"uk":"Заборонено.","ru":"Запрещено."}],"c":1,"e":{"uk":"Сірий автомобіль стоїть просто перед пішохідним переходом, а зупинка заборонена на переходах і ближче 10 м від них з обох боків ({p:15.9}). Такий автомобіль закриває пішоходів від водіїв, що наближаються, а пішоходам — огляд дороги.","ru":"Серый автомобиль стоит прямо перед пешеходным переходом, а остановка запрещена на переходах и ближе 10 м от них с обеих сторон ({p:15.9}). Такой автомобиль закрывает пешеходов от приближающихся водителей, а пешеходам — обзор дороги."},"ref":["15.9"],"pic":["img/hsc/35-166-1.jpg"]},{"id":"h35-167","t":"h35","num":"35.167","q":{"uk":"Чи повинні Ви зупинитись у даному випадку, якщо водій зустрічного автомобіля, не переконавшись у безпечності маневру, виконує поворот ліворуч?","ru":"Должны ли вы остановиться в данном случае, если водитель встречного автомобиля, не убедившись в безопасности манёвра, выполняет поворот налево?"},"a":[{"uk":"Повинні.","ru":"Должны."},{"uk":"Ні, тому, що маєте перевагу в русі.","ru":"Нет, потому что имеете преимущество в движении.","w":{"uk":"Перевага в русі не захищає від зіткнення: якщо інший водій помилився, {p:12.3} вимагає гальмувати аж до зупинки.","ru":"Преимущество в движении не защищает от столкновения: если другой водитель ошибся, {p:12.3} требует тормозить вплоть до остановки."}}],"c":0,"e":{"uk":"Зустрічний водій порушує {p:10.1} і вже перетинає вашу траєкторію — це небезпека для руху. Незалежно від того, хто має перевагу, водій зобов'язаний негайно знижувати швидкість аж до зупинки, щоб відвернути зіткнення ({p:12.3}).","ru":"Встречный водитель нарушает {p:10.1} и уже пересекает вашу траекторию — это опасность для движения. Независимо от того, у кого преимущество, водитель обязан немедленно снижать скорость вплоть до остановки, чтобы предотвратить столкновение ({p:12.3})."},"ref":["12.3","10.1"],"pic":["img/hsc/35-167-1.jpg"]},{"id":"h35-168","t":"h35","num":"35.168","q":{"uk":"Чи потрібно збільшувати боковий інтервал, коли Ви наближаєтесь до вантажного автомобіля?","ru":"Нужно ли увеличивать боковой интервал, когда вы приближаетесь к грузовому автомобилю?"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"Інтервал, достатній біля легкового автомобіля, біля вантажівки замалий: великі габарити, потоки повітря й «сліпі зони» її водія вимагають більшого запасу.","ru":"Интервал, достаточный возле легкового автомобиля, возле грузовика мал: большие габариты, потоки воздуха и «слепые зоны» его водителя требуют большего запаса."}}],"c":0,"e":{"uk":"Біля вантажівки виникають сильні потоки повітря, які можуть відкинути чи підтягнути легковий автомобіль, а сама вантажівка може хитнутися, з кузова може впасти вантаж, а з-під коліс — вилетіти камінці й бризки. Безпечний інтервал залежить від дорожньої обстановки ({p:13.1}, {p:13.3}), тож поруч із вантажівкою його збільшують.","ru":"Возле грузовика возникают сильные потоки воздуха, которые могут отбросить или подтянуть легковой автомобиль, а сам грузовик может качнуться, из кузова может упасть груз, а из-под колёс — вылететь камешки и брызги. Безопасный интервал зависит от дорожной обстановки ({p:13.1}, {p:13.3}), поэтому рядом с грузовиком его увеличивают."},"ref":["13.1","13.3"]},{"id":"h35-169","t":"h35","num":"35.169","q":{"uk":"Чи повинні Ви під час руху прямо в даному випадку враховувати те, що велосипедист у будь-який момент може розпочати рух?","ru":"Должны ли вы при движении прямо в данном случае учитывать то, что велосипедист в любой момент может начать движение?"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"Нерухомий велосипедист може рушити раптово, і якщо цього не передбачити, ви не встигнете загальмувати чи об'їхати його.","ru":"Неподвижный велосипедист может тронуться внезапно, и если этого не предвидеть, вы не успеете затормозить или объехать его."}}],"c":0,"e":{"uk":"Велосипедист стоїть біля самого краю проїзної частини серед натовпу й будь-якої миті може виїхати на дорогу, не озирнувшись. До велосипедистів водії мають бути особливо уважними ({p:1.7}) і готовими знизити швидкість аж до зупинки ({p:12.3}).","ru":"Велосипедист стоит у самого края проезжей части среди толпы и в любой момент может выехать на дорогу, не оглянувшись. К велосипедистам водители должны быть особенно внимательны ({p:1.7}) и готовы снизить скорость вплоть до остановки ({p:12.3})."},"ref":["1.7","12.3"],"pic":["img/hsc/35-169-1.jpg"]},{"id":"h35-170","t":"h35","num":"35.170","q":{"uk":"Чи потрібно зменшити швидкість, проїжджаючи повз пішохода у даному випадку?","ru":"Нужно ли снизить скорость, проезжая мимо пешехода в данном случае?"},"a":[{"uk":"Так.","ru":"Да."},{"uk":"Ні.","ru":"Нет.","w":{"uk":"Пішохід стоїть упритул до проїзної частини, і його рух важко передбачити; на незниженій швидкості ви не встигнете зреагувати, якщо він ступить на дорогу.","ru":"Пешеход стоит вплотную к проезжей части, и его движение трудно предсказать; на неснижённой скорости вы не успеете среагировать, если он ступит на дорогу."}}],"c":0,"e":{"uk":"Літній пішохід із сумкою стоїть на краю проїзної частини, де немає тротуару: він може оступитися, ступити на дорогу чи почати переходити її, неправильно оцінивши швидкість автомобіля. До людей похилого віку слід бути особливо обережним ({p:1.7}), тож швидкість знижують і проїжджають з більшим інтервалом ({p:12.3}, {p:13.1}).","ru":"Пожилой пешеход с сумкой стоит на краю проезжей части, где нет тротуара: он может оступиться, ступить на дорогу или начать переходить её, неверно оценив скорость автомобиля. По отношению к пожилым людям следует быть особенно осторожным ({p:1.7}), поэтому скорость снижают и проезжают с большим интервалом ({p:12.3}, {p:13.1})."},"ref":["1.7","12.3","13.1"],"pic":["img/hsc/35-170-1.jpg"]},{"id":"h35-171","t":"h35","num":"35.171","q":{"uk":"Які фактори можуть призвести до засліплення водія?","ru":"Какие факторы могут привести к ослеплению водителя?"},"a":[{"uk":"Мокрий сніг.","ru":"Мокрый снег.","w":{"uk":"Мокрий сніг налипає на скло й погіршує видимість, але засліплює водія не він, а яскраве світло.","ru":"Мокрый снег налипает на стекло и ухудшает видимость, но ослепляет водителя не он, а яркий свет."}},{"uk":"Сильна злива.","ru":"Сильный ливень.","w":{"uk":"Злива погіршує видимість водяною завісою на склі, але не засліплює — засліплення спричиняє світло.","ru":"Ливень ухудшает видимость водяной завесой на стекле, но не ослепляет — ослепление вызывает свет."}},{"uk":"Інтенсивний снігопад.","ru":"Интенсивный снегопад.","w":{"uk":"Снігопад обмежує видимість, але сам по собі не засліплює; засліплення — це дія яскравого світла на очі.","ru":"Снегопад ограничивает видимость, но сам по себе не ослепляет; ослепление — это действие яркого света на глаза."}},{"uk":"Світло.","ru":"Свет."}],"c":3,"e":{"uk":"Засліплення спричиняє яскраве світло — фари зустрічних автомобілів, низьке сонце, відблиски від мокрої дороги чи снігу. Засліплений водій на кілька секунд майже не бачить дороги, тому знижує швидкість, а в разі засліплення зупиняється, не змінюючи смуги, і вмикає аварійну сигналізацію ({p:19.3}).","ru":"Ослепление вызывает яркий свет — фары встречных автомобилей, низкое солнце, отблески от мокрой дороги или снега. Ослеплённый водитель на несколько секунд почти не видит дороги, поэтому снижает скорость, а при ослеплении останавливается, не меняя полосы, и включает аварийную сигнализацию ({p:19.3})."},"ref":["19.3"]},{"id":"h36-1","t":"h36","num":"36.1","q":{"uk":"Який орган має право розглядати оскарження адміністративного затримання, особистого огляду, огляду речей, огляду, а також вилучення речей і документів, у тому числі посвідчення водія?"},"a":[{"uk":"Тільки суд."},{"uk":"Тільки вищестоящий орган (вища посадова особа) щодо органу, який застосував ці заходи."},{"uk":"Органи, зазначені у відповідях 1 і 2."}],"c":2},{"id":"h36-2","t":"h36","num":"36.2","q":{"uk":"Результати особистого огляду або огляду речей офіційно повинні бути зафіксовані:"},"a":[{"uk":"Складанням протоколу."},{"uk":"Відповідним записом у протоколі про адміністративне правопорушення або в протоколі про адміністративне затримання."},{"uk":"Робиться так, як зазначено у відповідях 1 або 2."}],"c":2},{"id":"h36-3","t":"h36","num":"36.3","q":{"uk":"В'їзд водіїв на залізничний переїзд на заборонний сигнал світлофора при закритому шлагбаумі тягне за собою:"},"a":[{"uk":"Накладення штрафу або позбавлення права керування транспортним засобом."},{"uk":"Безкоштовне вилучення транспортного засобу."},{"uk":"Усне попередження від чергового по переїзду."}],"c":0},{"id":"h36-4","t":"h36","num":"36.4","q":{"uk":"Чи мають право посадові особи правоохоронних органів вилучати речі і документи під час затримання, особистого огляду або огляду речей?"},"a":[{"uk":"Мають право вилучати будь-які речі і документи на розсуд посадової особи."},{"uk":"Мають право вилучати тільки ті речі і документи, які є знаряддям або безпосереднім об'єктом правопорушення."},{"uk":"Мають право вилучати речі і документи, зазначені у відповідях 1 або 2."}],"c":1},{"id":"h36-5","t":"h36","num":"36.5","q":{"uk":"Водії, які керують транспортними засобами і щодо яких є достатні підстави вважати, що вони перебувають у стані сп'яніння:"},"a":[{"uk":"Підлягають відстороненню від керування цими транспортними засобами та огляду на стан сп'яніння."},{"uk":"Підлягають тільки огляду на стан сп'яніння."}],"c":0},{"id":"h36-6","t":"h36","num":"36.6","q":{"uk":"Чи дозволено органам внутрішніх справ (Національною поліцією) провести адміністративне затримання, якщо водій порушив Правила дорожнього руху?"},"a":[{"uk":"Дозволено."},{"uk":"Заборонено."}],"c":0},{"id":"h36-7","t":"h36","num":"36.7","q":{"uk":"Адміністративне затримання особи, яка вчинила адміністративне правопорушення, може тривати не більше ніж:"},"a":[{"uk":"П'ять годин."},{"uk":"Чотири години."},{"uk":"Три години."}],"c":2},{"id":"h36-8","t":"h36","num":"36.8","q":{"uk":"Залишення водіями місця ДТП, до якої вони причетні, тягне за собою:"},"a":[{"uk":"Накладення штрафу або громадські роботи, або адміністративний арешт."},{"uk":"Тільки накладення штрафу."},{"uk":"Особа не несе відповідальність за «втечу» з місця ДТП."}],"c":0},{"id":"h37-1","t":"h37","num":"37.1","q":{"uk":"Унаслідок ДТП у мотоцикліста на правій гомілці видима рана, з якої виступає уламок кістки. Яка перша домедична допомога?","ru":"В результате ДТП у мотоциклиста на правой голени видна рана, из которой выступает обломок кости. Какова первая домедицинская помощь?"},"a":[{"uk":"На рану накласти стерильну пов'язку, провести фіксацію суглобів вище і нижче місця перелому, транспортувати потерпілого в зручному для нього положенні.","ru":"На рану наложить стерильную повязку, провести фиксацию суставов выше и ниже места перелома, транспортировать пострадавшего в удобном для него положении."},{"uk":"Потерпілого покласти на спину, підклавши під ногу валик, дати випити таблетку анальгіну.","ru":"Пострадавшего уложить на спину, подложив под ногу валик, дать выпить таблетку анальгина.","w":{"uk":"Валик без шини не знерухомлює перелом, рана лишається відкритою, а давати ліки не входить до домедичної допомоги.","ru":"Валик без шины не обездвиживает перелом, рана остаётся открытой, а давать лекарства не входит в домедицинскую помощь."}}],"c":0,"e":{"uk":"Це **відкритий перелом**: рану закривають стерильною пов'язкою, щоб не допустити інфікування, а кінцівку знерухомлюють із фіксацією двох суглобів — вище й нижче перелому, щоб уламки не зміщувалися й не травмували судини та нерви.","ru":"Это **открытый перелом**: рану закрывают стерильной повязкой, чтобы не допустить инфицирования, а конечность обездвиживают с фиксацией двух суставов — выше и ниже перелома, чтобы обломки не смещались и не травмировали сосуды и нервы."},"pic":["img/hsc/37-1-1.jpg"]},{"id":"h37-2","t":"h37","num":"37.2","q":{"uk":"Що слід зробити в разі перелому ключиці в потерпілого?","ru":"Что следует сделать при переломе ключицы у пострадавшего?"},"a":[{"uk":"Накласти холодний компрес на місце перелому і туго забинтувати.","ru":"Наложить холодный компресс на место перелома и туго забинтовать.","w":{"uk":"Холод і тугий бинт на місці перелому не знерухомлюють уламки, а тугий бинт може ще й здавити судини.","ru":"Холод и тугой бинт на месте перелома не обездвиживают обломки, а тугой бинт может ещё и сдавить сосуды."}},{"uk":"Підвісити руку на косинку або прибинтувати випрямлену руку до тулуба.","ru":"Подвесить руку на косынку или прибинтовать выпрямленную руку к туловищу.","w":{"uk":"Випрямлена рука своєю вагою тягне плече донизу й зміщує уламки ключиці — руку треба зігнути в лікті.","ru":"Выпрямленная рука своим весом тянет плечо вниз и смещает обломки ключицы — руку нужно согнуть в локте."}},{"uk":"Підкласти валик з бинта або вати в пахвову ділянку і прибинтувати зігнуту в лікті руку до тулуба.","ru":"Подложить валик из бинта или ваты в подмышечную область и прибинтовать согнутую в локте руку к туловищу."}],"c":2,"e":{"uk":"Під час перелому ключиці треба знерухомити плечовий пояс: валик у пахві відводить плече й утримує уламки, а **зігнута в лікті** рука, прибинтована до тулуба, не тягне їх донизу.","ru":"При переломе ключицы нужно обездвижить плечевой пояс: валик в подмышке отводит плечо и удерживает обломки, а **согнутая в локте** рука, прибинтованная к туловищу, не тянет их вниз."}},{"id":"h37-3","t":"h37","num":"37.3","q":{"uk":"В якій послідовності слід надавати допомогу постраждалому:","ru":"В какой последовательности следует оказывать помощь пострадавшему:"},"a":[{"uk":"Зупинка масивної кровотечі – відновлення прохідності дихальних шляхів – забезпечення адекватного дихання.","ru":"Остановка массивного кровотечения – восстановление проходимости дыхательных путей – обеспечение адекватного дыхания."},{"uk":"Відновлення прохідності дихальних шляхів – зупинка масивної кровотечі – забезпечення адекватного дихання.","ru":"Восстановление проходимости дыхательных путей – остановка массивного кровотечения – обеспечение адекватного дыхания.","w":{"uk":"Поки рятувальник займається дихальними шляхами, постраждалий втрачає кров — масивну кровотечу зупиняють першою.","ru":"Пока спасатель занимается дыхательными путями, пострадавший теряет кровь — массивное кровотечение останавливают первым."}},{"uk":"Забезпечення адекватного дихання – відновлення прохідності дихальних шляхів – зупинка масивної кровотечі.","ru":"Обеспечение адекватного дыхания – восстановление проходимости дыхательных путей – остановка массивного кровотечения.","w":{"uk":"Порядок перевернутий: забезпечити дихання без прохідних дихальних шляхів неможливо, а кровотеча за цей час стає смертельною.","ru":"Порядок перевёрнут: обеспечить дыхание без проходимых дыхательных путей невозможно, а кровотечение за это время становится смертельным."}}],"c":0,"e":{"uk":"Від масивної кровотечі людина може загинути за кілька хвилин, тому її зупиняють **першою**; далі відновлюють прохідність дихальних шляхів, а вже потім забезпечують дихання — без прохідних шляхів дихання неможливе.","ru":"От массивного кровотечения человек может погибнуть за несколько минут, поэтому его останавливают **первым**; затем восстанавливают проходимость дыхательных путей, а уже потом обеспечивают дыхание — без проходимых путей дыхание невозможно."}},{"id":"h37-4","t":"h37","num":"37.4","q":{"uk":"Яка ознака зупинки серця у постраждалих враховується в базовому алгоритмі серцево-легеневої реанімації:","ru":"Какой признак остановки сердца у пострадавших учитывается в базовом алгоритме сердечно-лёгочной реанимации:"},"a":[{"uk":"Розширення зіниць.","ru":"Расширение зрачков.","w":{"uk":"Зіниці розширюються не відразу й не завжди, тож чекати цієї ознаки — втрачати час.","ru":"Зрачки расширяются не сразу и не всегда, поэтому ждать этого признака — терять время."}},{"uk":"Відсутність дихання.","ru":"Отсутствие дыхания."},{"uk":"Відсутність пульсу на сонних артеріях.","ru":"Отсутствие пульса на сонных артериях.","w":{"uk":"Неспеціалісти часто помиляються, шукаючи пульс, і гають час, тому в базовому алгоритмі пульс не перевіряють.","ru":"Неспециалисты часто ошибаются, ища пульс, и теряют время, поэтому в базовом алгоритме пульс не проверяют."}}],"c":1,"e":{"uk":"За базовим алгоритмом людину без свідомості, яка **не дихає** (або дихає ненормально), вважають такою, що має зупинку серця, і одразу починають серцево-легеневу реанімацію.","ru":"По базовому алгоритму человека без сознания, который **не дышит** (или дышит ненормально), считают находящимся в состоянии остановки сердца и сразу начинают сердечно-лёгочную реанимацию."}},{"id":"h37-5","t":"h37","num":"37.5","q":{"uk":"Яка частота натискань на грудну клітку при проведенні серцево-легеневої реанімації у постраждалих:","ru":"Какова частота надавливаний на грудную клетку при проведении сердечно-лёгочной реанимации у пострадавших:"},"a":[{"uk":"80 в хв.","ru":"80 в мин.","w":{"uk":"80 натискань на хвилину — замало: кровообіг, який вони створюють, недостатній.","ru":"80 надавливаний в минуту — слишком мало: кровообращение, которое они создают, недостаточно."}},{"uk":"100 в хв.","ru":"100 в мин."},{"uk":"Немає різниці, головне тиснути без зупинки.","ru":"Нет разницы, главное давить без остановки.","w":{"uk":"Частота має значення: за надто повільних натискань кровотік слабкий, а за надто швидких серце не встигає наповнитися кров'ю.","ru":"Частота имеет значение: при слишком медленных надавливаниях кровоток слабый, а при слишком быстрых сердце не успевает наполниться кровью."}}],"c":1,"e":{"uk":"Натискати на грудну клітку треба з частотою **100** (до 120) разів на хвилину — так створюється достатній кровотік до мозку й серця.","ru":"Надавливать на грудную клетку нужно с частотой **100** (до 120) раз в минуту — так создаётся достаточный кровоток к мозгу и сердцу."}},{"id":"h37-6","t":"h37","num":"37.6","q":{"uk":"Яке співвідношення проведення частоти натискань на грудну клітку та штучного дихання є правильним при проведенні серцево-легеневої реанімації?","ru":"Какое соотношение надавливаний на грудную клетку и искусственного дыхания является правильным при проведении сердечно-лёгочной реанимации?"},"a":[{"uk":"5 до 1.","ru":"5 к 1.","w":{"uk":"Співвідношення 5:1 застаріле: часті паузи на вдихи переривають кровообіг.","ru":"Соотношение 5:1 устарело: частые паузы на вдохи прерывают кровообращение."}},{"uk":"15 до 1.","ru":"15 к 1.","w":{"uk":"Співвідношення 15:1 не відповідає жодному чинному алгоритму реанімації дорослих.","ru":"Соотношение 15:1 не соответствует ни одному действующему алгоритму реанимации взрослых."}},{"uk":"30 до 2.","ru":"30 к 2."}],"c":2,"e":{"uk":"Сучасний алгоритм реанімації дорослого — **30 натискань** на грудну клітку, потім **2 вдихи**, і так циклами без перерв.","ru":"Современный алгоритм реанимации взрослого — **30 надавливаний** на грудную клетку, затем **2 вдоха**, и так циклами без перерывов."}},{"id":"h37-7","t":"h37","num":"37.7","q":{"uk":"У постраждалого внаслідок опіку на шкірі утворилися пухирі. Які дії є правильними?","ru":"У пострадавшего в результате ожога на коже образовались пузыри. Какие действия являются правильными?"},"a":[{"uk":"Накласти на місце опіку чисту пов’язку. Обережно зафіксувати без створення додаткового тиску.","ru":"Наложить на место ожога чистую повязку. Осторожно зафиксировать без создания дополнительного давления."},{"uk":"Проколоти пухирі гострим предметом після чого накласти чисту пов’язку.","ru":"Проколоть пузыри острым предметом, после чего наложить чистую повязку.","w":{"uk":"Проколюючи пухирі, відкривають рану й заносять інфекцію.","ru":"Прокалывая пузыри, открывают рану и заносят инфекцию."}},{"uk":"Накласти на місце опіку тугу бинтову пов’язку.","ru":"Наложить на место ожога тугую бинтовую повязку.","w":{"uk":"Туга пов'язка тисне на опечені тканини, що набрякають, травмує їх і може зірвати пухирі.","ru":"Тугая повязка давит на обожжённые ткани, которые отекают, травмирует их и может сорвать пузыри."}}],"c":0,"e":{"uk":"Пухирі захищають рану від інфекції, тому їх не чіпають, а опік накривають чистою пов'язкою і закріплюють її **без тиску** на пошкоджені тканини.","ru":"Пузыри защищают рану от инфекции, поэтому их не трогают, а ожог накрывают чистой повязкой и закрепляют её **без давления** на повреждённые ткани."}},{"id":"h37-8","t":"h37","num":"37.8","q":{"uk":"Яка допомога при опіку є найбільш правильною?","ru":"Какая помощь при ожоге является наиболее правильной?"},"a":[{"uk":"Накласти на місце опіку пакет з льодом як мінімум на 30 хв.","ru":"Наложить на место ожога пакет со льдом как минимум на 30 мин.","w":{"uk":"Лід на ушкодженій шкірі спричиняє ще й холодову травму, а горіння цей варіант не зупиняє.","ru":"Лёд на повреждённой коже вызывает ещё и холодовую травму, а горение этот вариант не останавливает."}},{"uk":"Припинити горіння. Охолодити місце опіку прохолодною водою. Накласти чисту марлеву пов’язку.","ru":"Прекратить горение. Охладить место ожога прохладной водой. Наложить чистую марлевую повязку."},{"uk":"Припинити горіння. Обробити місце опіку антисептиком (спирт, йод, зеленка). Накласти чисту марлеву пов’язку.","ru":"Прекратить горение. Обработать место ожога антисептиком (спирт, йод, зелёнка). Наложить чистую марлевую повязку.","w":{"uk":"Спирт, йод і зеленка додатково обпікають уражені тканини й посилюють біль.","ru":"Спирт, йод и зелёнка дополнительно обжигают поражённые ткани и усиливают боль."}}],"c":1,"e":{"uk":"Спочатку припиняють дію високої температури, потім охолоджують опік **прохолодною водою** (це зменшує глибину ураження й біль) і накривають чистою марлевою пов'язкою.","ru":"Сначала прекращают действие высокой температуры, затем охлаждают ожог **прохладной водой** (это уменьшает глубину поражения и боль) и накрывают чистой марлевой повязкой."}},{"id":"h37-9","t":"h37","num":"37.9","q":{"uk":"В якому випадку слід припинити проведення серцево-легеневої реанімації у постраждалих?","ru":"В каком случае следует прекратить проведение сердечно-лёгочной реанимации у пострадавших?"},"a":[{"uk":"Через 15 хвилин проведення серцево-легеневої реанімації.","ru":"Через 15 минут проведения сердечно-лёгочной реанимации.","w":{"uk":"Строк у 15 хвилин не є підставою зупинитися: без реанімації шансів у постраждалого немає.","ru":"Срок в 15 минут не является основанием остановиться: без реанимации шансов у пострадавшего нет."}},{"uk":"Через 30 хвилин проведення серцево-легеневої реанімації.","ru":"Через 30 минут проведения сердечно-лёгочной реанимации.","w":{"uk":"Для того, хто надає домедичну допомогу, тривалість реанімації не є підставою її припинити — до появи ознак життя чи приїзду медиків.","ru":"Для того, кто оказывает домедицинскую помощь, длительность реанимации не является основанием её прекратить — до появления признаков жизни или приезда медиков."}},{"uk":"Поява ознак життя (дихання, свідомість).","ru":"Появление признаков жизни (дыхание, сознание)."}],"c":2,"e":{"uk":"Реанімацію продовжують, доки в постраждалого не з'являться **ознаки життя** — самостійне дихання, свідомість: тоді серце запрацювало і натискання вже не потрібні.","ru":"Реанимацию продолжают, пока у пострадавшего не появятся **признаки жизни** — самостоятельное дыхание, сознание: тогда сердце заработало и надавливания уже не нужны."}},{"id":"h37-10","t":"h37","num":"37.10","q":{"uk":"В якому випадку слід припинити проведення серцево-легеневої реанімації у постраждалих?","ru":"В каком случае следует прекратить проведение сердечно-лёгочной реанимации у пострадавших?"},"a":[{"uk":"Прибуття бригади ЕМД, після чого вони продовжать проведення реанімаційних заходів.","ru":"Прибытие бригады ЭМП, после чего они продолжат проведение реанимационных мероприятий."},{"uk":"Через 15 хвилин проведення серцево-легеневої реанімації.","ru":"Через 15 минут проведения сердечно-лёгочной реанимации.","w":{"uk":"Тривалість у 15 хвилин не є підставою зупинитися — реанімацію продовжують до передачі медикам.","ru":"Длительность в 15 минут не является основанием остановиться — реанимацию продолжают до передачи медикам."}},{"uk":"Через 30 хвилин проведення серцево-легеневої реанімації.","ru":"Через 30 минут проведения сердечно-лёгочной реанимации.","w":{"uk":"Тривалість у 30 хвилин не є підставою зупинитися — реанімацію продовжують до передачі медикам.","ru":"Длительность в 30 минут не является основанием остановиться — реанимацию продолжают до передачи медикам."}}],"c":0,"e":{"uk":"Реанімацію припиняють, коли прибула бригада **екстреної медичної допомоги** й перебрала її на себе, — так натискання не перериваються.","ru":"Реанимацию прекращают, когда прибыла бригада **экстренной медицинской помощи** и взяла её на себя, — так надавливания не прерываются."}},{"id":"h37-11","t":"h37","num":"37.11","q":{"uk":"У випадку коли Вам чітко відоме джерело масивної кровотечі, джгут слід накласти:","ru":"В случае, когда вам точно известен источник массивного кровотечения, жгут следует наложить:"},"a":[{"uk":"На 2-3 см вище рани.","ru":"На 2-3 см выше раны.","w":{"uk":"На відстані 2–3 см джгут може зісковзнути в рану або лягти на пошкоджену ділянку судини.","ru":"На расстоянии 2–3 см жгут может соскользнуть в рану или лечь на повреждённый участок сосуда."}},{"uk":"На 5-7 см вище рани.","ru":"На 5-7 см выше раны."},{"uk":"На 10-12 см вище рани.","ru":"На 10-12 см выше раны.","w":{"uk":"10–12 см — зайва відстань: без кровопостачання лишається більша частина кінцівки, ніж потрібно.","ru":"10–12 см — лишнее расстояние: без кровоснабжения остаётся большая часть конечности, чем нужно."}}],"c":1,"e":{"uk":"Якщо рану видно, джгут накладають на **5–7 см вище** від неї: так він надійно перетискає судину й не потрапляє на краї рани.","ru":"Если рана видна, жгут накладывают на **5–7 см выше** неё: так он надёжно пережимает сосуд и не попадает на края раны."}},{"id":"h37-12","t":"h37","num":"37.12","q":{"uk":"При наявності стороннього тіла в рані необхідно:","ru":"При наличии инородного тела в ране необходимо:"},"a":[{"uk":"Накласти пов’язку, не виймаючи стороннього тіла.","ru":"Наложить повязку, не извлекая инородного тела."},{"uk":"Вийняти стороннє тіло після чого накласти пов’язку.","ru":"Извлечь инородное тело, после чего наложить повязку.","w":{"uk":"Якщо витягти стороннє тіло, може відкритися сильна кровотеча й додатково пошкодитися тканини.","ru":"Если извлечь инородное тело, может открыться сильное кровотечение и дополнительно повредиться ткани."}},{"uk":"Зафіксувати стороннє тіло тільки якщо воно виступає над раною не менше ніж на 5 см.","ru":"Зафиксировать инородное тело, только если оно выступает над раной не менее чем на 5 см.","w":{"uk":"Стороннє тіло фіксують незалежно від того, наскільки воно виступає над раною.","ru":"Инородное тело фиксируют независимо от того, насколько оно выступает над раной."}}],"c":0,"e":{"uk":"Стороннє тіло часто саме перекриває пошкоджені судини, тому його **не виймають**, а фіксують пов'язкою навколо — витягти його можуть лише медики.","ru":"Инородное тело часто само перекрывает повреждённые сосуды, поэтому его **не извлекают**, а фиксируют повязкой вокруг — извлечь его могут только медики."}},{"id":"h37-13","t":"h37","num":"37.13","q":{"uk":"У мотоцикліста при перелітанні через перепону перш за все слід підозрювати травму:","ru":"У мотоциклиста при перелёте через препятствие прежде всего следует подозревать травму:"},"a":[{"uk":"Шийного відділу хребта.","ru":"Шейного отдела позвоночника."},{"uk":"Перелом кістки правого плеча.","ru":"Перелом кости правого плеча.","w":{"uk":"Перелом плеча можливий, але він не є найнебезпечнішою й найхарактернішою травмою під час такого падіння.","ru":"Перелом плеча возможен, но он не является самой опасной и характерной травмой при таком падении."}},{"uk":"Перелом кісток тазу.","ru":"Перелом костей таза.","w":{"uk":"Перелом таза частіше буває під час удару об кермо чи бак, а падіння через перешкоду головою вперед насамперед загрожує шиї.","ru":"Перелом таза чаще бывает при ударе о руль или бак, а падение через препятствие головой вперёд прежде всего угрожает шее."}}],"c":0,"e":{"uk":"Перелітаючи через перешкоду, мотоцикліст зазвичай падає вперед на голову, і шия зазнає різкого згинання — тому насамперед підозрюють травму **шийного відділу хребта** й обмежують рухи шиї.","ru":"Перелетая через препятствие, мотоциклист обычно падает вперёд на голову, и шея подвергается резкому сгибанию — поэтому прежде всего подозревают травму **шейного отдела позвоночника** и ограничивают движения шеи."}},{"id":"h37-14","t":"h37","num":"37.14","q":{"uk":"Кровоспинний джгут треба затягувати на кінцівці:","ru":"Кровоостанавливающий жгут нужно затягивать на конечности:"},"a":[{"uk":"До появи болю.","ru":"До появления боли.","w":{"uk":"Біль з'являється задовго до того, як артерію перетиснуто, тож кровотеча може тривати.","ru":"Боль появляется задолго до того, как артерия пережата, поэтому кровотечение может продолжаться."}},{"uk":"До зупинки кровотечі.","ru":"До остановки кровотечения."},{"uk":"Скільки є сили.","ru":"Изо всех сил.","w":{"uk":"Надмірне затягування понад потрібне травмує нерви, м'язи й шкіру.","ru":"Чрезмерное затягивание сверх нужного травмирует нервы, мышцы и кожу."}}],"c":1,"e":{"uk":"Джгут затягують саме **до зупинки кровотечі** — це означає, що артерію перетиснуто достатньо.","ru":"Жгут затягивают именно **до остановки кровотечения** — это значит, что артерия пережата достаточно."}},{"id":"h37-15","t":"h37","num":"37.15","q":{"uk":"Якщо людина знаходиться без свідомості і не має травм, її треба:","ru":"Если человек находится без сознания и не имеет травм, его нужно:"},"a":[{"uk":"Посадити, щоб голова була в припіднятому положенні.","ru":"Усадить, чтобы голова была в приподнятом положении.","w":{"uk":"Людина без свідомості не втримає тіло сидячи: голова звисає, і дихальні шляхи можуть перекритися.","ru":"Человек без сознания не удержит тело сидя: голова свисает, и дыхательные пути могут перекрыться."}},{"uk":"Не чіпати.","ru":"Не трогать.","w":{"uk":"Якщо людину без свідомості залишити на спині, язик може запасти й перекрити дихальні шляхи.","ru":"Если человека без сознания оставить на спине, язык может запасть и перекрыть дыхательные пути."}},{"uk":"Перевести в стабільне положення.","ru":"Перевести в устойчивое положение."}],"c":2,"e":{"uk":"Людину без свідомості, яка дихає й не має травм, кладуть у **стабільне бокове положення**: язик не западає, а блювотні маси чи кров не потрапляють у дихальні шляхи.","ru":"Человека без сознания, который дышит и не имеет травм, укладывают в **устойчивое боковое положение**: язык не западает, а рвотные массы или кровь не попадают в дыхательные пути."}},{"id":"h37-16","t":"h37","num":"37.16","q":{"uk":"Порядок дій при масивній артеріальній кровотечі:","ru":"Порядок действий при массивном артериальном кровотечении:"},"a":[{"uk":"Викликати 103 і накласти пов'язку, що тисне.","ru":"Вызвать 103 и наложить давящую повязку.","w":{"uk":"Пов'язка, що тисне, не зупиняє масивну артеріальну кровотечу, а дзвінок перед цим забирає дорогоцінний час.","ru":"Давящая повязка не останавливает массивное артериальное кровотечение, а звонок перед этим отнимает драгоценное время."}},{"uk":"Викликати 103, накласти джгут, вказати час накладання.","ru":"Вызвать 103, наложить жгут, указать время наложения.","w":{"uk":"Поки триває дзвінок, постраждалий втрачає кров — джгут накладають перед викликом.","ru":"Пока длится звонок, пострадавший теряет кровь — жгут накладывают до вызова."}},{"uk":"Накласти джгут, вказати час накладання, викликати 103.","ru":"Наложить жгут, указать время наложения, вызвать 103."}],"c":2,"e":{"uk":"Масивна артеріальна кровотеча вбиває за лічені хвилини, тому **спершу** накладають джгут і записують час накладання, а вже потім викликають екстрену допомогу (103).","ru":"Массивное артериальное кровотечение убивает за считаные минуты, поэтому **сначала** накладывают жгут и записывают время наложения, а уже потом вызывают экстренную помощь (103)."}},{"id":"h37-17","t":"h37","num":"37.17","q":{"uk":"Що першочергово потрібно зробити при наданні домедичної допомоги постраждалому при ДТП?","ru":"Что в первую очередь нужно сделать при оказании домедицинской помощи пострадавшему при ДТП?"},"a":[{"uk":"Переконатися у відсутності небезпеки.","ru":"Убедиться в отсутствии опасности."},{"uk":"Спочатку треба відновити прохідність дихальних шляхів.","ru":"Сначала нужно восстановить проходимость дыхательных путей.","w":{"uk":"Дихальні шляхи відновлюють лише після того, як переконалися, що на місці немає небезпеки.","ru":"Дыхательные пути восстанавливают только после того, как убедились, что на месте нет опасности."}},{"uk":"Спочатку необхідно впевнитись в наявності дихання у постраждалого.","ru":"Сначала необходимо убедиться в наличии дыхания у пострадавшего.","w":{"uk":"Перевіряти дихання можна тільки тоді, коли місце події безпечне для рятувальника.","ru":"Проверять дыхание можно только тогда, когда место происшествия безопасно для спасателя."}}],"c":0,"e":{"uk":"Першим кроком завжди є оцінка **безпеки**: рух транспорту, пожежа, витік пального можуть зробити постраждалим і того, хто допомагає.","ru":"Первым шагом всегда является оценка **безопасности**: движение транспорта, пожар, утечка топлива могут сделать пострадавшим и того, кто помогает."}},{"id":"h37-18","t":"h37","num":"37.18","q":{"uk":"У постраждалого кровотеча з рани в області шиї. Який метод зупинки кровотечі буде найбільш правильний:","ru":"У пострадавшего кровотечение из раны в области шеи. Какой метод остановки кровотечения будет наиболее правильным:"},"a":[{"uk":"Накладання кровоспинного джгута.","ru":"Наложение кровоостанавливающего жгута.","w":{"uk":"Джгут на шиї перетисне дихальні шляхи й судини, що живлять мозок.","ru":"Жгут на шее пережмёт дыхательные пути и сосуды, питающие мозг."}},{"uk":"Накладання тугої бинтової пов’язки.","ru":"Наложение тугой бинтовой повязки.","w":{"uk":"Тугий бинт навколо шиї здавлює трахею та сонні артерії — це небезпечно для життя.","ru":"Тугой бинт вокруг шеи сдавливает трахею и сонные артерии — это опасно для жизни."}},{"uk":"Пальцеве притискання рани.","ru":"Пальцевое прижатие раны."}],"c":2,"e":{"uk":"На шиї джгут чи тугу пов'язку не накладають, тому кровотечу зупиняють **притисканням рани пальцями** (рукою) й утримують тиск до приїзду медиків.","ru":"На шее жгут или тугую повязку не накладывают, поэтому кровотечение останавливают **прижатием раны пальцами** (рукой) и удерживают давление до приезда медиков."}},{"id":"h37-19","t":"h37","num":"37.19","q":{"uk":"Ви не бачите джерело кровотечі з кінцівки у постраждалого, однак визначили що вона масивна. Де Ви накладете джгут:","ru":"Вы не видите источник кровотечения из конечности у пострадавшего, однако определили, что оно массивное. Где вы наложите жгут:"},"a":[{"uk":"Максимально високо на кінцівку.","ru":"Максимально высоко на конечность."},{"uk":"Посередині кінцівки.","ru":"Посередине конечности.","w":{"uk":"Рана може бути вище від середини кінцівки, і тоді джгут кровотечу не зупинить.","ru":"Рана может быть выше середины конечности, и тогда жгут кровотечение не остановит."}},{"uk":"Джгут в будь-якому випадку слід накласти тільки після виявлення рани.","ru":"Жгут в любом случае следует накладывать только после обнаружения раны.","w":{"uk":"Пошук рани за масивної кровотечі забирає час, за який людина може загинути від крововтрати.","ru":"Поиск раны при массивном кровотечении отнимает время, за которое человек может погибнуть от кровопотери."}}],"c":0,"e":{"uk":"Якщо рану не видно, джгут накладають **якомога вище** на кінцівку — тоді він гарантовано опиниться вище від місця кровотечі.","ru":"Если рана не видна, жгут накладывают **как можно выше** на конечность — тогда он гарантированно окажется выше места кровотечения."}},{"id":"h37-20","t":"h37","num":"37.20","q":{"uk":"Як надати домедичну допомогу в разі отруєння випарами бензину?","ru":"Как оказать домедицинскую помощь при отравлении парами бензина?"},"a":[{"uk":"Винести пацієнта на свіже повітря, зігріти, зробити штучне дихання.","ru":"Вынести пациента на свежий воздух, согреть, сделать искусственное дыхание."},{"uk":"Промити шлунок великою кількістю рідини.","ru":"Промыть желудок большим количеством жидкости.","w":{"uk":"Промивання шлунка допомагає, коли отруту проковтнули, а пари бензину вдихають.","ru":"Промывание желудка помогает, когда яд проглотили, а пары бензина вдыхают."}},{"uk":"Винести пацієнта на свіже повітря і дати йому гарячого чаю.","ru":"Вынести пациента на свежий воздух и дать ему горячего чая.","w":{"uk":"Гарячий чай не відновлює дихання, а людина з порушеною свідомістю може ним захлинутися.","ru":"Горячий чай не восстанавливает дыхание, а человек с нарушенным сознанием может им захлебнуться."}}],"c":0,"e":{"uk":"Пари бензину потрапляють в організм через легені, тому постраждалого виносять на **свіже повітря**, зігрівають, а якщо дихання порушене чи зупинилося — роблять штучне дихання.","ru":"Пары бензина попадают в организм через лёгкие, поэтому пострадавшего выносят на **свежий воздух**, согревают, а если дыхание нарушено или остановилось — делают искусственное дыхание."}},{"id":"h37-21","t":"h37","num":"37.21","q":{"uk":"Як потрібно обробити уражені електролітом ділянки шкіри?","ru":"Как нужно обработать поражённые электролитом участки кожи?"},"a":[{"uk":"Тільки промити великою кількістю води.","ru":"Только промыть большим количеством воды."},{"uk":"Тільки обробити розчином йоду.","ru":"Только обработать раствором йода.","w":{"uk":"Йод не нейтралізує електроліт, а сам додатково обпікає ушкоджену шкіру.","ru":"Йод не нейтрализует электролит, а сам дополнительно обжигает повреждённую кожу."}},{"uk":"Тільки протерти розчином перекису водню.","ru":"Только протереть раствором перекиси водорода.","w":{"uk":"Пероксид водню не видаляє електроліт і подразнює вже уражені тканини.","ru":"Перекись водорода не удаляет электролит и раздражает уже поражённые ткани."}},{"uk":"Виконати всі перелічені вище дії.","ru":"Выполнить все перечисленные выше действия.","w":{"uk":"Йод і пероксид водню на хімічному опіку лише шкодять — потрібна тільки вода.","ru":"Йод и перекись водорода на химическом ожоге только вредят — нужна только вода."}}],"c":0,"e":{"uk":"Електроліт (кислота чи луг) спричиняє хімічний опік, тому його **змивають великою кількістю проточної води** — вода розбавляє й видаляє речовину зі шкіри.","ru":"Электролит (кислота или щёлочь) вызывает химический ожог, поэтому его **смывают большим количеством проточной воды** — вода разбавляет и удаляет вещество с кожи."}},{"id":"h37-22","t":"h37","num":"37.22","q":{"uk":"Як надати домедичну допомогу в разі харчового отруєння в дорозі?","ru":"Как оказать домедицинскую помощь при пищевом отравлении в дороге?"},"a":[{"uk":"Зупинитися. Вийти на свіже повітря, вжити валеріанові краплі і по змозі випити гарячого чаю або кави.","ru":"Остановиться. Выйти на свежий воздух, принять валериановые капли и по возможности выпить горячего чая или кофе.","w":{"uk":"Валеріанові краплі, чай чи кава не виводять отруту з організму.","ru":"Валериановые капли, чай или кофе не выводят яд из организма."}},{"uk":"Зупинитися. Спожити багато рідини, викликати штучно блювоту, вжити активоване вугілля.","ru":"Остановиться. Выпить много жидкости, искусственно вызвать рвоту, принять активированный уголь."},{"uk":"Виконати дії, зазначені у відповіді 1 або 2.","ru":"Выполнить действия, указанные в ответе 1 или 2.","w":{"uk":"Дії з відповіді 1 не допомагають при отруєнні, тому «1 або 2» — неправильно.","ru":"Действия из ответа 1 не помогают при отравлении, поэтому «1 или 2» — неверно."}}],"c":1,"e":{"uk":"При харчовому отруєнні треба видалити отруту зі шлунка: випити багато рідини, **викликати блювання**, а залишки токсинів зв'язати **активованим вугіллям**.","ru":"При пищевом отравлении нужно удалить яд из желудка: выпить много жидкости, **вызвать рвоту**, а остатки токсинов связать **активированным углём**."}},{"id":"h37-23","t":"h37","num":"37.23","q":{"uk":"Як надати домедичну допомогу в разі забою живота?","ru":"Как оказать домедицинскую помощь при ушибе живота?"},"a":[{"uk":"Розтерти забите місце жорстким матеріалом, накласти пов'язку, дати багато пити.","ru":"Растереть ушибленное место жёстким материалом, наложить повязку, дать много пить.","w":{"uk":"Розтирання посилює крововилив, а пиття при можливій травмі органів черевної порожнини протипоказане.","ru":"Растирание усиливает кровоизлияние, а питьё при возможной травме органов брюшной полости противопоказано."}},{"uk":"Масажувати забите місце, а потім прогріти його грілкою.","ru":"Массировать ушибленное место, а затем прогреть его грелкой.","w":{"uk":"Масаж і тепло розширюють судини та посилюють внутрішню кровотечу.","ru":"Массаж и тепло расширяют сосуды и усиливают внутреннее кровотечение."}},{"uk":"Забезпечити потерпілому повний спокій, забите місце охолодити.","ru":"Обеспечить пострадавшему полный покой, ушибленное место охладить."}],"c":2,"e":{"uk":"Забій живота може супроводжуватися пошкодженням органів і внутрішньою кровотечею, тому потрібні **спокій і холод** — холод звужує судини й зменшує крововилив.","ru":"Ушиб живота может сопровождаться повреждением органов и внутренним кровотечением, поэтому нужны **покой и холод** — холод сужает сосуды и уменьшает кровоизлияние."}},{"id":"h37-24","t":"h37","num":"37.24","q":{"uk":"За відсутності дихання в потерпілого потрібно:","ru":"При отсутствии дыхания у пострадавшего нужно:"},"a":[{"uk":"Зробити масаж серця.","ru":"Сделать массаж сердца.","w":{"uk":"Натискання на грудну клітку підтримують кровообіг, але не подають у легені свіже повітря; в цьому питанні правильною вважається відповідь про штучне дихання.","ru":"Надавливания на грудную клетку поддерживают кровообращение, но не подают в лёгкие свежий воздух; в этом вопросе правильным считается ответ об искусственном дыхании."}},{"uk":"Зробити штучне дихання","ru":"Сделать искусственное дыхание."},{"uk":"Покласти потерпілого на спину і дати йому понюхати нашатирний спирт.","ru":"Уложить пострадавшего на спину и дать ему понюхать нашатырный спирт.","w":{"uk":"Нашатирний спирт не відновлює дихання, а час на нього може коштувати життя.","ru":"Нашатырный спирт не восстанавливает дыхание, а время на него может стоить жизни."}}],"c":1,"e":{"uk":"Якщо людина не дихає, кисень не надходить у легені, тому за цим питанням правильна відповідь — **штучне дихання**; за сучасним алгоритмом його поєднують із натисканнями на грудну клітку (30:2).","ru":"Если человек не дышит, кислород не поступает в лёгкие, поэтому в этом вопросе правильный ответ — **искусственное дыхание**; по современному алгоритму его сочетают с надавливаниями на грудную клетку (30:2)."}},{"id":"h37-25","t":"h37","num":"37.25","q":{"uk":"Як надати домедичну допомогу в разі термічного опіку в дорозі?","ru":"Как оказать домедицинскую помощь при термическом ожоге в дороге?"},"a":[{"uk":"Винести потерпілого із зони високої температури, проколоти пухирі, обробити уражену поверхню вазеліном або олією і присипати порошком.","ru":"Вынести пострадавшего из зоны высокой температуры, проколоть пузыри, обработать поражённую поверхность вазелином или маслом и присыпать порошком.","w":{"uk":"Проколоті пухирі інфікуються, а олія, вазелін і порошок утримують тепло й забруднюють рану.","ru":"Проколотые пузыри инфицируются, а масло, вазелин и порошок удерживают тепло и загрязняют рану."}},{"uk":"Винести потерпілого із зони високої температури, накласти суху асептичну пов'язку або чисту бавовняну тканину.","ru":"Вынести пострадавшего из зоны высокой температуры, наложить сухую асептическую повязку или чистую хлопчатобумажную ткань."},{"uk":"Виконати дії, зазначені у відповіді 1 або 2.","ru":"Выполнить действия, указанные в ответе 1 или 2.","w":{"uk":"Дії з відповіді 1 шкодять постраждалому, тому «1 або 2» — неправильно.","ru":"Действия из ответа 1 вредят пострадавшему, поэтому «1 или 2» — неверно."}}],"c":1,"e":{"uk":"Постраждалого виводять із зони дії високої температури, а опік накривають **сухою асептичною пов'язкою** або чистою бавовняною тканиною, щоб захистити його від забруднення.","ru":"Пострадавшего выводят из зоны действия высокой температуры, а ожог накрывают **сухой асептической повязкой** или чистой хлопчатобумажной тканью, чтобы защитить его от загрязнения."}},{"id":"h37-26","t":"h37","num":"37.26","q":{"uk":"Як надати домедичну допомогу при стенокардії (біль у серці) в дорозі?","ru":"Как оказать домедицинскую помощь при стенокардии (боль в сердце) в дороге?"},"a":[{"uk":"Обличчя і груди хворого змочити холодною водою, дати йому понюхати ватку, змочену нашатирним спиртом.","ru":"Лицо и грудь больного смочить холодной водой, дать ему понюхать ватку, смоченную нашатырным спиртом.","w":{"uk":"Холодна вода й нашатирний спирт не покращують кровопостачання серця і можуть спричинити спазм судин.","ru":"Холодная вода и нашатырный спирт не улучшают кровоснабжение сердца и могут вызвать спазм сосудов."}},{"uk":"Забезпечити доступ повітря до хворого, дати йому таблетку нітрогліцерину (валідолу) під язик.","ru":"Обеспечить доступ воздуха к больному, дать ему таблетку нитроглицерина (валидола) под язык."},{"uk":"Виконати дії, зазначені у відповідях 1 і 2.","ru":"Выполнить действия, указанные в ответах 1 и 2.","w":{"uk":"Дії з відповіді 1 не допомагають при стенокардії, тому поєднувати їх із відповіддю 2 не слід.","ru":"Действия из ответа 1 не помогают при стенокардии, поэтому сочетать их с ответом 2 не следует."}}],"c":1,"e":{"uk":"Біль у серці виникає через нестачу кисню серцевому м'язу, тому хворому забезпечують **доступ свіжого повітря** й дають під язик нітрогліцерин (валідол), що розширює судини серця.","ru":"Боль в сердце возникает из-за нехватки кислорода сердечной мышце, поэтому больному обеспечивают **доступ свежего воздуха** и дают под язык нитроглицерин (валидол), расширяющий сосуды сердца."}},{"id":"h37-27","t":"h37","num":"37.27","q":{"uk":"У разі перелому кінцівки слід:","ru":"При переломе конечности следует:"},"a":[{"uk":"Перев'язати місце перелому.","ru":"Перевязать место перелома.","w":{"uk":"Пов'язка без шини не знерухомлює уламки кістки.","ru":"Повязка без шины не обездвиживает обломки кости."}},{"uk":"Зафіксувати кінцівку за допомогою шини або предмета, що замінює її.","ru":"Зафиксировать конечность с помощью шины или предмета, её заменяющего."},{"uk":"Вкласти кінцівку в будь-якому зручному для потерпілого положенні.","ru":"Уложить конечность в любом удобном для пострадавшего положении.","w":{"uk":"Без фіксації уламки зміщуватимуться під час будь-якого руху, хоч би яким зручним було положення.","ru":"Без фиксации обломки будут смещаться при любом движении, каким бы удобным ни было положение."}}],"c":1,"e":{"uk":"Головне при переломі — **знерухомити** кінцівку шиною або підручним предметом, щоб уламки не зміщувалися й не пошкоджували судини та нерви.","ru":"Главное при переломе — **обездвижить** конечность шиной или подручным предметом, чтобы обломки не смещались и не повреждали сосуды и нервы."}},{"id":"h37-28","t":"h37","num":"37.28","q":{"uk":"Як впливає алкоголь на час реакції водія?","ru":"Как влияет алкоголь на время реакции водителя?"},"a":[{"uk":"Не впливає на реакцію водія.","ru":"Не влияет на реакцию водителя.","w":{"uk":"Навіть невелика доза алкоголю погіршує увагу й уповільнює реакцію.","ru":"Даже небольшая доза алкоголя ухудшает внимание и замедляет реакцию."}},{"uk":"Час реакції збільшується.","ru":"Время реакции увеличивается."},{"uk":"Час реакції зменшується.","ru":"Время реакции уменьшается.","w":{"uk":"Алкоголь не прискорює, а сповільнює реакцію; відчуття «бадьорості» оманливе.","ru":"Алкоголь не ускоряет, а замедляет реакцию; ощущение «бодрости» обманчиво."}}],"c":1,"e":{"uk":"Алкоголь гальмує нервову систему, тому водій пізніше помічає небезпеку й повільніше реагує — **час реакції збільшується**; саме тому керування в стані сп'яніння заборонене ({p:2.9}).","ru":"Алкоголь тормозит нервную систему, поэтому водитель позже замечает опасность и медленнее реагирует — **время реакции увеличивается**; именно поэтому управление в состоянии опьянения запрещено ({p:2.9})."},"ref":["2.9"]},{"id":"h37-29","t":"h37","num":"37.29","q":{"uk":"Найбільш небезпечною кровотечею у постраждалих є:","ru":"Наиболее опасным кровотечением у пострадавших является:"},"a":[{"uk":"Артеріальна.","ru":"Артериальное."},{"uk":"Венозна.","ru":"Венозное.","w":{"uk":"У венах тиск нижчий, кров витікає повільніше, і таку кровотечу зазвичай зупиняє пов'язка, що тисне.","ru":"В венах давление ниже, кровь вытекает медленнее, и такое кровотечение обычно останавливает давящая повязка."}},{"uk":"Капілярна.","ru":"Капиллярное.","w":{"uk":"Капілярна кровотеча слабка, кров виступає краплями й зазвичай зупиняється сама.","ru":"Капиллярное кровотечение слабое, кровь выступает каплями и обычно останавливается само."}}],"c":0,"e":{"uk":"В артеріях кров тече під високим тиском, тому з пошкодженої артерії вона витікає дуже швидко, і людина може загинути від **крововтрати** за кілька хвилин.","ru":"В артериях кровь течёт под высоким давлением, поэтому из повреждённой артерии она вытекает очень быстро, и человек может погибнуть от **кровопотери** за несколько минут."}},{"id":"h37-30","t":"h37","num":"37.30","q":{"uk":"Зупинка масивної артеріальної кровотечі, як правило, проводиться:","ru":"Остановка массивного артериального кровотечения, как правило, проводится:"},"a":[{"uk":"Накладанням бинтової пов’язки.","ru":"Наложением бинтовой повязки.","w":{"uk":"Звичайна бинтова пов'язка не витримує тиску артеріальної крові.","ru":"Обычная бинтовая повязка не выдерживает давления артериальной крови."}},{"uk":"За допомогою кровоспинного джгута.","ru":"С помощью кровоостанавливающего жгута."},{"uk":"Як правило, зупиняється самостійно.","ru":"Как правило, останавливается самостоятельно.","w":{"uk":"Масивна артеріальна кровотеча сама не зупиняється — без допомоги людина гине від крововтрати.","ru":"Массивное артериальное кровотечение само не останавливается — без помощи человек погибает от кровопотери."}}],"c":1,"e":{"uk":"Масивну артеріальну кровотечу на кінцівці зупиняють **кровоспинним джгутом**, який перетискає артерію вище від рани.","ru":"Массивное артериальное кровотечение на конечности останавливают **кровоостанавливающим жгутом**, который пережимает артерию выше раны."}},{"id":"h37-31","t":"h37","num":"37.31","q":{"uk":"Зупинка венозної кровотечі як правило проводиться:","ru":"Остановка венозного кровотечения, как правило, проводится:"},"a":[{"uk":"Накладанням пов’язки, що тисне.","ru":"Наложением давящей повязки."},{"uk":"За допомогою кровоспинного джгута.","ru":"С помощью кровоостанавливающего жгута.","w":{"uk":"Джгут потрібен для масивної (артеріальної) кровотечі; при венозній він зайвий і лише порушує кровопостачання кінцівки.","ru":"Жгут нужен при массивном (артериальном) кровотечении; при венозном он излишен и только нарушает кровоснабжение конечности."}},{"uk":"Як правило, зупиняється самостійно.","ru":"Как правило, останавливается самостоятельно.","w":{"uk":"Сама зазвичай зупиняється капілярна кровотеча, а венозна без пов'язки триває й призводить до крововтрати.","ru":"Само обычно останавливается капиллярное кровотечение, а венозное без повязки продолжается и приводит к кровопотере."}}],"c":0,"e":{"uk":"У венах тиск невисокий, тому венозну кровотечу зазвичай надійно зупиняє **пов'язка, що тисне**.","ru":"В венах давление невысокое, поэтому венозное кровотечение обычно надёжно останавливает **давящая повязка**."}},{"id":"h37-32","t":"h37","num":"37.32","q":{"uk":"Ознаки артеріальної кровотечі:","ru":"Признаки артериального кровотечения:"},"a":[{"uk":"Повільно витікає з рани, темного кольору.","ru":"Медленно вытекает из раны, тёмного цвета.","w":{"uk":"Темна кров, що повільно витікає, — ознака венозної кровотечі.","ru":"Тёмная кровь, медленно вытекающая из раны, — признак венозного кровотечения."}},{"uk":"Витікає з рани краплями.","ru":"Вытекает из раны каплями.","w":{"uk":"Кров, що виступає краплями, — ознака капілярної кровотечі.","ru":"Кровь, выступающая каплями, — признак капиллярного кровотечения."}},{"uk":"Пульсує, швидко витікає, яскравого кольору.","ru":"Пульсирует, быстро вытекает, яркого цвета."}],"c":2,"e":{"uk":"Артеріальна кров насичена киснем, тому **яскраво-червона**, і під тиском серця **б'є пульсуючим струменем**.","ru":"Артериальная кровь насыщена кислородом, поэтому **ярко-алая**, и под давлением сердца **бьёт пульсирующей струёй**."}},{"id":"h37-33","t":"h37","num":"37.33","q":{"uk":"Ознаки венозної кровотечі:","ru":"Признаки венозного кровотечения:"},"a":[{"uk":"Повільно витікає з рани, темного кольору.","ru":"Медленно вытекает из раны, тёмного цвета."},{"uk":"Пульсує, швидко витікає, яскравого кольору.","ru":"Пульсирует, быстро вытекает, яркого цвета.","w":{"uk":"Яскрава кров, що б'є пульсуючим струменем, — ознака артеріальної кровотечі.","ru":"Яркая кровь, бьющая пульсирующей струёй, — признак артериального кровотечения."}},{"uk":"Витікає з рани краплями.","ru":"Вытекает из раны каплями.","w":{"uk":"Кров, що виступає краплями, — ознака капілярної кровотечі.","ru":"Кровь, выступающая каплями, — признак капиллярного кровотечения."}}],"c":0,"e":{"uk":"Венозна кров містить мало кисню, тому вона **темна**, а через низький тиск у венах **витікає повільно**, без пульсації.","ru":"Венозная кровь содержит мало кислорода, поэтому она **тёмная**, а из-за низкого давления в венах **вытекает медленно**, без пульсации."}},{"id":"h37-34","t":"h37","num":"37.34","q":{"uk":"Ви не бачите джерело кровотечі з кінцівки у постраждалого, однак визначили що вона масивна. Де Ви накладете джгут:","ru":"Вы не видите источник кровотечения из конечности у пострадавшего, однако определили, что оно массивное. Где вы наложите жгут:"},"a":[{"uk":"Максимально високо на кінцівку.","ru":"Максимально высоко на конечность."},{"uk":"Посередині кінцівки.","ru":"Посередине конечности.","w":{"uk":"Рана може бути вище від середини кінцівки, і тоді джгут кровотечу не зупинить.","ru":"Рана может быть выше середины конечности, и тогда жгут кровотечение не остановит."}},{"uk":"Джгут в будь-якому випадку слід накласти тільки після виявлення рани.","ru":"Жгут в любом случае следует накладывать только после обнаружения раны.","w":{"uk":"Пошук рани за масивної кровотечі забирає час, за який людина може загинути від крововтрати.","ru":"Поиск раны при массивном кровотечении отнимает время, за которое человек может погибнуть от кровопотери."}}],"c":0,"e":{"uk":"Якщо рану не видно, джгут накладають **якомога вище** на кінцівку — тоді він гарантовано опиниться вище від місця кровотечі.","ru":"Если рана не видна, жгут накладывают **как можно выше** на конечность — тогда он гарантированно окажется выше места кровотечения."}},{"id":"h37-35","t":"h37","num":"37.35","q":{"uk":"Яке положення треба надати постраждалому з травмою грудної клітки?","ru":"Какое положение нужно придать пострадавшему с травмой грудной клетки?"},"a":[{"uk":"Зручне положення, при якому йому найлегше дихати.","ru":"Удобное положение, при котором ему легче всего дышать."},{"uk":"Стабільне бокове положення.","ru":"Устойчивое боковое положение.","w":{"uk":"Стабільне бокове положення призначене для людей без свідомості, а при травмі грудей може утруднити дихання.","ru":"Устойчивое боковое положение предназначено для людей без сознания, а при травме груди может затруднить дыхание."}},{"uk":"Положення лежачи з піднятими ногами.","ru":"Положение лёжа с поднятыми ногами.","w":{"uk":"Положення з піднятими ногами — протишокове; при травмі грудей воно посилює задишку.","ru":"Положение с поднятыми ногами — противошоковое; при травме груди оно усиливает одышку."}}],"c":0,"e":{"uk":"При травмі грудної клітки людині важко дихати, тому їй дозволяють прийняти **зручне положення** (найчастіше напівсидячи), у якому дихати найлегше.","ru":"При травме грудной клетки человеку трудно дышать, поэтому ему позволяют принять **удобное положение** (чаще всего полусидя), в котором дышать легче всего."}},{"id":"h37-36","t":"h37","num":"37.36","q":{"uk":"Які ваші першочергові дії при наданні домедичної допомоги дорослому в разі раптової зупинки кровообігу та відсутності дихання?","ru":"Каковы ваши первоочередные действия при оказании домедицинской помощи взрослому в случае внезапной остановки кровообращения и отсутствия дыхания?"},"a":[{"uk":"Розпочати серцево-легеневу реанімацію, тільки після появи дихання викликати екстрену медичну допомогу.","ru":"Начать сердечно-лёгочную реанимацию, только после появления дыхания вызвать экстренную медицинскую помощь.","w":{"uk":"Дихання саме по собі відновлюється рідко, тож відкладений виклик позбавляє постраждалого вчасної допомоги медиків.","ru":"Дыхание само по себе восстанавливается редко, поэтому отложенный вызов лишает пострадавшего своевременной помощи медиков."}},{"uk":"Викликати екстрену (швидку) медичну допомогу та дотримуватись указівок диспетчера, розпочати серцево-легеневу реанімацію.","ru":"Вызвать экстренную (скорую) медицинскую помощь и выполнять указания диспетчера, начать сердечно-лёгочную реанимацию."},{"uk":"Перевести дорослого у стабільне бокове положення, при цьому кожні 5 хвилин перевіряти наявність дихання.","ru":"Перевести взрослого в устойчивое боковое положение, при этом каждые 5 минут проверять наличие дыхания.","w":{"uk":"Стабільне бокове положення — для тих, хто дихає; людині без дихання потрібна реанімація, а не очікування.","ru":"Устойчивое боковое положение — для тех, кто дышит; человеку без дыхания нужна реанимация, а не ожидание."}}],"c":1,"e":{"uk":"Без дефібрилятора та медиків шанси людини із зупинкою серця малі, тому **одразу викликають** екстрену допомогу (диспетчер підкаже, що робити) і починають серцево-легеневу реанімацію.","ru":"Без дефибриллятора и медиков шансы человека с остановкой сердца малы, поэтому **сразу вызывают** экстренную помощь (диспетчер подскажет, что делать) и начинают сердечно-лёгочную реанимацию."}},{"id":"h37-37","t":"h37","num":"37.37","q":{"uk":"У постраждалого внаслідок термічного опіку на шкірі утворилися пухирі. Які дії будуть правильними?","ru":"У пострадавшего в результате термического ожога на коже образовались пузыри. Какие действия будут правильными?"},"a":[{"uk":"Не пошкоджуючи пухирі, охолодити місце опіку та накласти чисту, стерильну суху марлеву пов’язку, яка не тиснутиме на м’які тканини.","ru":"Не повреждая пузыри, охладить место ожога и наложить чистую стерильную сухую марлевую повязку, которая не будет давить на мягкие ткани."},{"uk":"Проколоти пухирі гострим предметом, після чого накласти на місце опіку чисту, стерильну суху марлеву пов’язку, яка не тиснутиме на м’які тканини.","ru":"Проколоть пузыри острым предметом, после чего наложить на место ожога чистую стерильную сухую марлевую повязку, которая не будет давить на мягкие ткани.","w":{"uk":"Проколюючи пухирі, відкривають рану й заносять у неї інфекцію.","ru":"Прокалывая пузыри, открывают рану и заносят в неё инфекцию."}}],"c":0,"e":{"uk":"Цілі пухирі захищають рану від інфекції, тому їх **не пошкоджують**: опік охолоджують і накривають чистою стерильною сухою пов'язкою без тиску.","ru":"Целые пузыри защищают рану от инфекции, поэтому их **не повреждают**: ожог охлаждают и накрывают чистой стерильной сухой повязкой без давления."}},{"id":"h37-38","t":"h37","num":"37.38","q":{"uk":"Що насамперед необхідно враховувати під час надання домедичної допомоги постраждалим із термічними опіками?","ru":"Что прежде всего необходимо учитывать при оказании домедицинской помощи пострадавшим с термическими ожогами?"},"a":[{"uk":"Ступінь пошкодження шкіри та м’яких тканин.","ru":"Степень повреждения кожи и мягких тканей."},{"uk":"Місцезнаходження потерпілого під час отримання термічного опіку.","ru":"Местонахождение пострадавшего во время получения термического ожога.","w":{"uk":"Де саме людина обпеклася, на порядок допомоги не впливає — важливий стан ураженої ділянки.","ru":"Где именно человек обжёгся, на порядок помощи не влияет — важно состояние поражённого участка."}},{"uk":"Вік, зріст і стать потерпілого.","ru":"Возраст, рост и пол пострадавшего.","w":{"uk":"Вік, зріст і стать не визначають порядку дій — його визначає ступінь опіку.","ru":"Возраст, рост и пол не определяют порядок действий — его определяет степень ожога."}}],"c":0,"e":{"uk":"Від **ступеня пошкодження** шкіри та м'яких тканин (почервоніння, пухирі, глибоке ураження) залежать дії: чи можна охолоджувати, яку пов'язку накладати, наскільки терміново потрібні медики.","ru":"От **степени повреждения** кожи и мягких тканей (покраснение, пузыри, глубокое поражение) зависят действия: можно ли охлаждать, какую повязку накладывать, насколько срочно нужны медики."}},{"id":"h37-39","t":"h37","num":"37.39","q":{"uk":"Невідкладний стан, спричинений дією високих температур, у результаті чого виникає пошкодження шкіри та м’яких тканин, – це:","ru":"Неотложное состояние, вызванное действием высоких температур, в результате которого возникает повреждение кожи и мягких тканей, – это:"},"a":[{"uk":"Тепловий удар.","ru":"Тепловой удар.","w":{"uk":"Тепловий удар — це перегрівання всього організму, а не пошкодження шкіри й тканин.","ru":"Тепловой удар — это перегревание всего организма, а не повреждение кожи и тканей."}},{"uk":"Термічний опік.","ru":"Термический ожог."},{"uk":"Порушення прохідності дихальних шляхів.","ru":"Нарушение проходимости дыхательных путей.","w":{"uk":"Порушення прохідності дихальних шляхів — інший невідкладний стан, не пов'язаний з ушкодженням шкіри.","ru":"Нарушение проходимости дыхательных путей — другое неотложное состояние, не связанное с повреждением кожи."}}],"c":1,"e":{"uk":"Місцеве пошкодження шкіри та м'яких тканин високою температурою (полум'ям, окропом, гарячим предметом) називають **термічним опіком**.","ru":"Местное повреждение кожи и мягких тканей высокой температурой (пламенем, кипятком, горячим предметом) называют **термическим ожогом**."}},{"id":"h37-40","t":"h37","num":"37.40","q":{"uk":"Що слід зробити, якщо при наданні домедичної допомоги постраждалому з ознаками термічного опіку було випадково пошкоджено пухирі?","ru":"Что следует сделать, если при оказании домедицинской помощи пострадавшему с признаками термического ожога были случайно повреждены пузыри?"},"a":[{"uk":"Накласти на місце опіку чисту, стерильну суху марлеву пов’язку, яка не тиснутиме на м’які тканини.","ru":"Наложить на место ожога чистую стерильную сухую марлевую повязку, которая не будет давить на мягкие ткани."},{"uk":"Охолодити місце опіку шляхом промивання протягом щонайменше 20 хвилин холодною водою.","ru":"Охладить место ожога промыванием холодной водой в течение не менее 20 минут.","w":{"uk":"Тривале промивання відкритої опікової рани нестерильною водою загрожує інфікуванням і переохолодженням.","ru":"Длительное промывание открытой ожоговой раны нестерильной водой грозит инфицированием и переохлаждением."}},{"uk":"Обробити місце опіку дезінфікувальним засобом.","ru":"Обработать место ожога дезинфицирующим средством.","w":{"uk":"Дезінфікувальні засоби додатково ушкоджують відкриті опечені тканини й посилюють біль.","ru":"Дезинфицирующие средства дополнительно повреждают открытые обожжённые ткани и усиливают боль."}}],"c":0,"e":{"uk":"Пошкоджені пухирі означають відкриту рану, тому опік **більше не охолоджують**, а одразу накривають чистою стерильною сухою пов'язкою без тиску, щоб не допустити інфікування.","ru":"Повреждённые пузыри означают открытую рану, поэтому ожог **больше не охлаждают**, а сразу накрывают чистой стерильной сухой повязкой без давления, чтобы не допустить инфицирования."}},{"id":"h37-41","t":"h37","num":"37.41","q":{"uk":"Якщо під час огляду постраждалого виявлено проникну травму черевної порожнини з фіксованим стороннім предметом у ній, Ви:","ru":"Если при осмотре пострадавшего обнаружена проникающая травма брюшной полости с фиксированным инородным предметом в ней, вы:"},"a":[{"uk":"Обережно витягнете сторонній предмет та накладете стерильну пов’язку.","ru":"Осторожно извлечёте инородный предмет и наложите стерильную повязку.","w":{"uk":"Якщо витягти предмет, може відкритися сильна внутрішня кровотеча й додатково пошкодитися органи.","ru":"Если извлечь предмет, может открыться сильное внутреннее кровотечение и дополнительно повредиться органы."}},{"uk":"Надійно зафіксуєте сторонній предмет у рані та наглядатимете за постраждалим до приїзду бригади екстреної (швидкої) медичної допомоги.","ru":"Надёжно зафиксируете инородный предмет в ране и будете наблюдать за пострадавшим до приезда бригады экстренной (скорой) медицинской помощи."}],"c":1,"e":{"uk":"Предмет у рані перекриває пошкоджені судини й органи, тому його **не виймають**, а надійно фіксують і стежать за станом постраждалого до приїзду медиків.","ru":"Предмет в ране перекрывает повреждённые сосуды и органы, поэтому его **не извлекают**, а надёжно фиксируют и следят за состоянием пострадавшего до приезда медиков."}},{"id":"h37-42","t":"h37","num":"37.42","q":{"uk":"Швидке, інтенсивне витікання крові з рани постраждалого є основною ознакою:","ru":"Быстрое, интенсивное вытекание крови из раны пострадавшего является основным признаком:"},"a":[{"uk":"Масивної зовнішньої кровотечі.","ru":"Массивного наружного кровотечения."},{"uk":"Внутрішньої кровотечі.","ru":"Внутреннего кровотечения.","w":{"uk":"Внутрішня кровотеча відбувається всередині тіла, і кров з рани назовні не витікає.","ru":"Внутреннее кровотечение происходит внутри тела, и кровь из раны наружу не вытекает."}}],"c":0,"e":{"uk":"Якщо кров швидко й інтенсивно витікає **з рани назовні**, це масивна зовнішня кровотеча, яку треба негайно зупиняти.","ru":"Если кровь быстро и интенсивно вытекает **из раны наружу**, это массивное наружное кровотечение, которое нужно немедленно останавливать."}},{"id":"h37-43","t":"h37","num":"37.43","q":{"uk":"Основні ознаки відкритого перелому кінцівки:","ru":"Основные признаки открытого перелома конечности:"},"a":[{"uk":"Наявність рани в місці перелому, кровотеча з рани, наявність уламків кістки в рані.","ru":"Наличие раны в месте перелома, кровотечение из раны, наличие обломков кости в ране."},{"uk":"Неприродне положення кінцівки, біль у ділянці рани / деформації кінцівки, гематома в ділянці перелому (збільшення кінцівки в об’ємі).","ru":"Неестественное положение конечности, боль в области раны / деформации конечности, гематома в области перелома (увеличение конечности в объёме).","w":{"uk":"Неприродне положення, біль і гематома бувають і при закритому переломі, тож відкритий перелом за ними не відрізнити.","ru":"Неестественное положение, боль и гематома бывают и при закрытом переломе, поэтому открытый перелом по ним не отличить."}}],"c":0,"e":{"uk":"Відкритий перелом відрізняється тим, що в місці перелому є **рана**: з неї тече кров, а в ній можуть бути видні **уламки кістки**.","ru":"Открытый перелом отличается тем, что в месте перелома есть **рана**: из неё течёт кровь, а в ней могут быть видны **обломки кости**."}},{"id":"h37-44","t":"h37","num":"37.44","q":{"uk":"За наявності ран у ділянці голови у жодному разі не можна:","ru":"При наличии ран в области головы ни в коем случае нельзя:"},"a":[{"uk":"Проводити пальпацію рани.","ru":"Проводить пальпацию раны.","w":{"uk":"Прощупування рани справді заборонене, але воно лише одна з трьох заборонених дій.","ru":"Прощупывание раны действительно запрещено, но это лишь одно из трёх запрещённых действий."}},{"uk":"Натискати на рану.","ru":"Надавливать на рану.","w":{"uk":"Натискання на рану справді заборонене, але не можна також прощупувати рану й обробляти її антисептиками.","ru":"Надавливание на рану действительно запрещено, но нельзя также прощупывать рану и обрабатывать её антисептиками."}},{"uk":"Використовувати антисептики під час обробки ран.","ru":"Использовать антисептики при обработке ран.","w":{"uk":"Антисептики справді не застосовують, але не можна також прощупувати рану й тиснути на неї.","ru":"Антисептики действительно не применяют, но нельзя также прощупывать рану и давить на неё."}},{"uk":"Усі відповіді правильні.","ru":"Все ответы правильные."}],"c":3,"e":{"uk":"Під раною на голові може бути **перелом черепа**: прощупування й натискання можуть вдавити уламки кісток у мозок, а антисептики — потрапити в мозкові тканини, тому заборонено все перелічене.","ru":"Под раной на голове может быть **перелом черепа**: прощупывание и надавливание могут вдавить обломки костей в мозг, а антисептики — попасть в мозговые ткани, поэтому запрещено всё перечисленное."}},{"id":"h37-45","t":"h37","num":"37.45","q":{"uk":"Часткове або повне порушення цілісності кістки без пошкодження шкірних покривів у проєкції перелому – це:","ru":"Частичное или полное нарушение целостности кости без повреждения кожных покровов в проекции перелома – это:"},"a":[{"uk":"Відкритий перелом.","ru":"Открытый перелом.","w":{"uk":"При відкритому переломі шкіру в місці перелому пошкоджено — є рана.","ru":"При открытом переломе кожа в месте перелома повреждена — есть рана."}},{"uk":"Закритий перелом.","ru":"Закрытый перелом."}],"c":1,"e":{"uk":"Якщо кістку зламано, а **шкіра над переломом ціла**, перелом називають закритим.","ru":"Если кость сломана, а **кожа над переломом цела**, перелом называют закрытым."}},{"id":"h37-46","t":"h37","num":"37.46","q":{"uk":"Часткове або повне порушення цілісності кістки з одночасним пошкодженням шкірного покриву в проєкції перелому – це:","ru":"Частичное или полное нарушение целостности кости с одновременным повреждением кожного покрова в проекции перелома – это:"},"a":[{"uk":"Відкритий перелом.","ru":"Открытый перелом."},{"uk":"Закритий перелом.","ru":"Закрытый перелом.","w":{"uk":"При закритому переломі шкіра над місцем перелому ціла.","ru":"При закрытом переломе кожа над местом перелома цела."}}],"c":0,"e":{"uk":"Якщо разом із кісткою пошкоджено **шкіру над переломом** (є рана), перелом називають відкритим.","ru":"Если вместе с костью повреждена **кожа над переломом** (есть рана), перелом называют открытым."}},{"id":"h37-47","t":"h37","num":"37.47","q":{"uk":"Якщо у постраждалого є ознаки закритого перелому, потрібно:","ru":"Если у пострадавшего есть признаки закрытого перелома, нужно:"},"a":[{"uk":"Допомогти постраждалому прийняти зручне положення (таке, яке завдає найменше болю).","ru":"Помочь пострадавшему принять удобное положение (такое, которое причиняет наименьшую боль).","w":{"uk":"Зручне положення без знерухомлення не утримає уламки від зміщення.","ru":"Удобное положение без обездвиживания не удержит обломки от смещения."}},{"uk":"Іммобілізувати (знерухомити) пошкоджену кінцівку за допомогою стандартного обладнання (шин) чи підручних засобів.","ru":"Иммобилизовать (обездвижить) повреждённую конечность с помощью стандартного оборудования (шин) или подручных средств.","w":{"uk":"Знерухомлення потрібне, але й положення постраждалого має завдавати якомога менше болю — правильні обидві відповіді.","ru":"Обездвиживание нужно, но и положение пострадавшего должно причинять как можно меньше боли — верны оба ответа."}},{"uk":"Усі відповіді правильні.","ru":"Все ответы правильные."}],"c":2,"e":{"uk":"При закритому переломі постраждалому допомагають прийняти положення з найменшим болем і **знерухомлюють** кінцівку шиною чи підручними засобами — потрібні обидві дії.","ru":"При закрытом переломе пострадавшему помогают принять положение с наименьшей болью и **обездвиживают** конечность шиной или подручными средствами — нужны оба действия."}},{"id":"h37-48","t":"h37","num":"37.48","q":{"uk":"Якими будуть Ваші першочергові дії при наданні домедичної допомоги постраждалому у випадку ДТП?","ru":"Каковы будут ваши первоочередные действия при оказании домедицинской помощи пострадавшему в случае ДТП?"},"a":[{"uk":"Переконатися у відсутності небезпеки для себе, оточення, постраждалого і тільки за її відсутності перейти до надання допомоги.","ru":"Убедиться в отсутствии опасности для себя, окружающих, пострадавшего и только при её отсутствии перейти к оказанию помощи."},{"uk":"Незалежно від наявності небезпеки почати надавати домедичну допомогу постраждалому.","ru":"Независимо от наличия опасности начать оказывать домедицинскую помощь пострадавшему.","w":{"uk":"Допомога в небезпечному місці (рух транспорту, пожежа) може призвести до нових жертв, зокрема й серед рятувальників.","ru":"Помощь в опасном месте (движение транспорта, пожар) может привести к новым жертвам, в том числе среди спасателей."}}],"c":0,"e":{"uk":"Спершу оцінюють **безпеку** для себя, оточення й постраждалого: рятувальник, який сам постраждав, уже нікому не допоможе.","ru":"Сначала оценивают **безопасность** для себя, окружающих и пострадавшего: спасатель, который сам пострадал, уже никому не поможет."}},{"id":"h37-49","t":"h37","num":"37.49","q":{"uk":"Причинами виникнення шоку в постраждалого можуть бути:","ru":"Причинами возникновения шока у пострадавшего могут быть:"},"a":[{"uk":"Масивна зовнішня кровотеча.","ru":"Массивное наружное кровотечение.","w":{"uk":"Масивна зовнішня кровотеча справді спричиняє шок, але вона не єдина причина.","ru":"Массивное наружное кровотечение действительно вызывает шок, но это не единственная причина."}},{"uk":"Внутрішня кровотеча.","ru":"Внутреннее кровотечение.","w":{"uk":"Внутрішня кровотеча справді спричиняє шок, але не лише вона.","ru":"Внутреннее кровотечение действительно вызывает шок, но не только оно."}},{"uk":"Серцевий напад.","ru":"Сердечный приступ.","w":{"uk":"Серцевий напад може спричинити шок, але причиною буває й крововтрата.","ru":"Сердечный приступ может вызвать шок, но причиной бывает и кровопотеря."}},{"uk":"Усі відповіді правильні.","ru":"Все ответы правильные."}],"c":3,"e":{"uk":"Шок — це гостра нестача кровопостачання органів; її спричиняє і **крововтрата** (зовнішня чи внутрішня), і **слабкість серця** під час серцевого нападу, тож правильні всі варіанти.","ru":"Шок — это острая нехватка кровоснабжения органов; её вызывает и **кровопотеря** (наружная или внутренняя), и **слабость сердца** при сердечном приступе, поэтому верны все варианты."}},{"id":"h37-50","t":"h37","num":"37.50","q":{"uk":"Першочергові дії при наданні домедичної допомоги постраждалим за підозри шоку:","ru":"Первоочередные действия при оказании домедицинской помощи пострадавшим при подозрении на шок:"},"a":[{"uk":"Здійснити виклик екстреної медичної допомоги та дотримуватись указівок диспетчера прийому виклику, за можливості виявити та усунути причину виникнення шоку, надати постраждалому протишокове положення.","ru":"Осуществить вызов экстренной медицинской помощи и выполнять указания диспетчера приёма вызова, по возможности выявить и устранить причину возникновения шока, придать пострадавшему противошоковое положение."},{"uk":"Дати постраждалому заспокійливе, за можливості виявити й усунути причину виникнення шоку, здійснити виклик екстреної медичної допомоги та дотримуватись указівок диспетчера прийому виклику.","ru":"Дать пострадавшему успокоительное, по возможности выявить и устранить причину возникновения шока, осуществить вызов экстренной медицинской помощи и выполнять указания диспетчера приёма вызова.","w":{"uk":"Давати ліки (зокрема заспокійливі) не входить до домедичної допомоги, а виклик медиків тут відкладено на кінець.","ru":"Давать лекарства (в том числе успокоительные) не входит в домедицинскую помощь, а вызов медиков здесь отложен на конец."}}],"c":0,"e":{"uk":"Шок загрожує життю, тому **першим** викликають екстрену допомогу й діють за вказівками диспетчера, за можливості усувають причину (наприклад, зупиняють кровотечу) і надають протишокове положення.","ru":"Шок угрожает жизни, поэтому **первым** вызывают экстренную помощь и действуют по указаниям диспетчера, по возможности устраняют причину (например, останавливают кровотечение) и придают противошоковое положение."}},{"id":"h37-51","t":"h37","num":"37.51","q":{"uk":"Що з наведеного насамперед зобов’язаний зробити причетний до дорожньо-транспортної пригоди водій, якщо в результаті події є потерпілі особи?","ru":"Что из приведённого прежде всего обязан сделать причастный к дорожно-транспортному происшествию водитель, если в результате происшествия есть пострадавшие?"},"a":[{"uk":"Ужити можливих заходів для надання домедичної допомоги потерпілим, викликати бригаду екстреної (швидкої) медичної допомоги, а в разі відсутності можливості вжити зазначених заходів звернутися по допомогу до присутніх і відправити потерпілих до закладу охорони здоров’я.","ru":"Принять возможные меры для оказания домедицинской помощи пострадавшим, вызвать бригаду экстренной (скорой) медицинской помощи, а при отсутствии возможности принять указанные меры обратиться за помощью к присутствующим и отправить пострадавших в учреждение здравоохранения."},{"uk":"Повідомити про дорожньо-транспортну пригоду орган чи уповноважений підрозділ Національної поліції, записати прізвища та адреси очевидців, чекати прибуття поліцейських.","ru":"Сообщить о дорожно-транспортном происшествии в орган или уполномоченное подразделение Национальной полиции, записать фамилии и адреса очевидцев, ждать прибытия полицейских.","w":{"uk":"Повідомити поліцію й записати очевидців теж треба ({p:2.10}), але не раніше, ніж потерпілим надано допомогу.","ru":"Сообщить в полицию и записать очевидцев тоже нужно ({p:2.10}), но не раньше, чем пострадавшим оказана помощь."}},{"uk":"Вжити всіх можливих заходів для збереження слідів пригоди, їх огородження та організувати об’їзд місця пригоди.","ru":"Принять все возможные меры для сохранения следов происшествия, их ограждения и организовать объезд места происшествия.","w":{"uk":"Збереження слідів пригоди — теж обов'язок водія, але допомога потерпілим важливіша й надається насамперед.","ru":"Сохранение следов происшествия — тоже обязанность водителя, но помощь пострадавшим важнее и оказывается в первую очередь."}}],"c":0,"e":{"uk":"Серед обов'язків водія, причетного до ДТП ({p:2.10}), **порятунок життя** — найважливіший: надати домедичну допомогу й викликати екстрену медичну допомогу, а якщо це неможливо — залучити присутніх і відправити потерпілих до закладу охорони здоров'я.","ru":"Среди обязанностей водителя, причастного к ДТП ({p:2.10}), **спасение жизни** — самое важное: оказать домедицинскую помощь и вызвать экстренную медицинскую помощь, а если это невозможно — привлечь присутствующих и отправить пострадавших в учреждение здравоохранения."},"ref":["2.10"]},{"id":"h37-52","t":"h37","num":"37.52","q":{"uk":"Ви бачите джерело масивної зовнішньої кровотечі з рани на кінцівці постраждалого. Що Ви повинні зробити насамперед?","ru":"Вы видите источник массивного наружного кровотечения из раны на конечности пострадавшего. Что вы должны сделать в первую очередь?"},"a":[{"uk":"Якнайсильніше натиснути на рану руками та накласти пов’язку, що тисне.","ru":"Как можно сильнее надавить на рану руками и наложить давящую повязку."},{"uk":"Промити рану великою кількістю води.","ru":"Промыть рану большим количеством воды.","w":{"uk":"Промивання рани забирає час і не зупиняє масивну кровотечу — людина продовжує втрачати кров.","ru":"Промывание раны отнимает время и не останавливает массивное кровотечение — человек продолжает терять кровь."}}],"c":0,"e":{"uk":"Найшвидший спосіб зупинити видиму кровотечу — **сильно притиснути рану руками**, а потім закріпити тиск пов'язкою, що тисне.","ru":"Самый быстрый способ остановить видимое кровотечение — **сильно прижать рану руками**, а затем закрепить давление давящей повязкой."}},{"id":"h37-53","t":"h37","num":"37.53","q":{"uk":"Що слід зробити, якщо після накладання кровоспинного джгута кровотеча з рани на кінцівці постраждалого не спинилася?","ru":"Что следует сделать, если после наложения кровоостанавливающего жгута кровотечение из раны на конечности пострадавшего не остановилось?"},"a":[{"uk":"Збільшити тиск кровоспинного джгута та/або накласти ще один кровоспинний джгут вище від першого.","ru":"Увеличить давление кровоостанавливающего жгута и/или наложить ещё один кровоостанавливающий жгут выше первого.","w":{"uk":"Це правильна дія, але так само допустимо притиснути рану руками або затампонувати її.","ru":"Это правильное действие, но так же допустимо прижать рану руками или затампонировать её."}},{"uk":"Затиснути рану руками і тримати до приїзду бригади екстреної (швидкої) медичної допомоги або виконати тампонування рани.","ru":"Зажать рану руками и держать до приезда бригады экстренной (скорой) медицинской помощи или выполнить тампонирование раны.","w":{"uk":"Це правильна дія, але можна також посилити тиск джгута чи накласти другий джгут.","ru":"Это правильное действие, но можно также усилить давление жгута или наложить второй жгут."}},{"uk":"Обидва варіанти правильні.","ru":"Оба варианта правильные."}],"c":2,"e":{"uk":"Якщо кровотеча триває, джгут **дотягують** або накладають ще один вище, а якщо й це не допомагає — притискають рану руками чи тампонують її; припустимі обидва способи.","ru":"Если кровотечение продолжается, жгут **дотягивают** или накладывают ещё один выше, а если и это не помогает — прижимают рану руками или тампонируют её; допустимы оба способа."}},{"id":"h37-54","t":"h37","num":"37.54","q":{"uk":"Що Ви повинні насамперед зробити у разі виявлення в потерпілого у ДТП масивної зовнішньої кровотечі з рани, яка локалізована в основі шиї?","ru":"Что вы должны прежде всего сделать при обнаружении у пострадавшего в ДТП массивного наружного кровотечения из раны, локализованной у основания шеи?"},"a":[{"uk":"Здійснити максимально можливий тиск на рану.","ru":"Осуществить максимально возможное давление на рану."},{"uk":"Заспокоїти постраждалого та пояснити подальші дії.","ru":"Успокоить пострадавшего и объяснить дальнейшие действия.","w":{"uk":"Заспокоювати й пояснювати можна, але вже після того, як кровотечу зупинено.","ru":"Успокаивать и объяснять можно, но уже после того, как кровотечение остановлено."}},{"uk":"Допомогти постраждалому прийняти зручне положення.","ru":"Помочь пострадавшему принять удобное положение.","w":{"uk":"Поки постраждалий влаштовується зручніше, він втрачає кров — спершу треба зупинити кровотечу.","ru":"Пока пострадавший устраивается удобнее, он теряет кровь — сначала нужно остановить кровотечение."}}],"c":0,"e":{"uk":"На основі шиї джгут накласти неможливо, тому масивну кровотечу зупиняють **максимально сильним тиском на рану** й утримують його до приїзду медиків.","ru":"У основания шеи жгут наложить невозможно, поэтому массивное кровотечение останавливают **максимально сильным давлением на рану** и удерживают его до приезда медиков."}},{"id":"h37-55","t":"h37","num":"37.55","q":{"uk":"Що Ви повинні насамперед зробити у разі виявлення в потерпілого у ДТП масивної зовнішньої кровотечі з рани, яка локалізована в пахвових ділянках?","ru":"Что вы должны прежде всего сделать при обнаружении у пострадавшего в ДТП массивного наружного кровотечения из раны, локализованной в подмышечных областях?"},"a":[{"uk":"Допомогти постраждалому прийняти зручне положення.","ru":"Помочь пострадавшему принять удобное положение.","w":{"uk":"Поки постраждалий влаштовується зручніше, він втрачає кров — спершу треба зупинити кровотечу.","ru":"Пока пострадавший устраивается удобнее, он теряет кровь — сначала нужно остановить кровотечение."}},{"uk":"Заспокоїти постраждалого та пояснити подальші дії.","ru":"Успокоить пострадавшего и объяснить дальнейшие действия.","w":{"uk":"Заспокоювати й пояснювати можна, але вже після того, як кровотечу зупинено.","ru":"Успокаивать и объяснять можно, но уже после того, как кровотечение остановлено."}},{"uk":"Здійснити максимально можливий тиск на рану.","ru":"Осуществить максимально возможное давление на рану."}],"c":2,"e":{"uk":"У пахвовій ділянці джгут накласти неможливо, тому масивну кровотечу зупиняють **максимально сильним тиском на рану**.","ru":"В подмышечной области жгут наложить невозможно, поэтому массивное кровотечение останавливают **максимально сильным давлением на рану**."}},{"id":"h37-56","t":"h37","num":"37.56","q":{"uk":"За яких умов Ви повинні припинити проведення серцево-легеневої реанімації постраждалого в ДТП до прибуття бригади екстреної (швидкої) медичної допомоги?","ru":"При каких условиях вы должны прекратить проведение сердечно-лёгочной реанимации пострадавшего в ДТП до прибытия бригады экстренной (скорой) медицинской помощи?"},"a":[{"uk":"За появи у постраждалого явних ознак життя: відновлення самостійного дихання, координованої рухової активності.","ru":"При появлении у пострадавшего явных признаков жизни: восстановления самостоятельного дыхания, координированной двигательной активности.","w":{"uk":"Ознаки життя — підстава припинити реанімацію, але не єдина.","ru":"Признаки жизни — основание прекратить реанимацию, но не единственное."}},{"uk":"У разі виникнення загрози життю, Вашому та / або постраждалого.","ru":"При возникновении угрозы жизни, вашей и/или пострадавшего.","w":{"uk":"Загроза життю — підстава припинити реанімацію, але не єдина.","ru":"Угроза жизни — основание прекратить реанимацию, но не единственное."}},{"uk":"Якщо проводити серцево-легеневу реанімацію неможливо внаслідок Вашого значного фізичного виснаження.","ru":"Если проводить сердечно-лёгочную реанимацию невозможно вследствие вашего значительного физического истощения.","w":{"uk":"Виснаження рятувальника — підстава припинити реанімацію, але не єдина.","ru":"Истощение спасателя — основание прекратить реанимацию, но не единственное."}},{"uk":"За будь-якої з вищевказаних умов.","ru":"При любом из вышеуказанных условий."}],"c":3,"e":{"uk":"Реанімацію припиняють, коли в постраждалого з'явилися **ознаки життя**, коли виникла небезпека для рятувальника чи постраждалого або коли рятувальник фізично більше не може її проводити — тобто за будь-якої з цих умов.","ru":"Реанимацию прекращают, когда у пострадавшего появились **признаки жизни**, когда возникла опасность для спасателя или пострадавшего или когда спасатель физически больше не может её проводить — то есть при любом из этих условий."}},{"id":"h37-57","t":"h37","num":"37.57","q":{"uk":"Що потрібно насамперед зробити під час надання домедичної допомоги постраждалому в ДТП у разі підозри в нього травми голови до приїзду бригади екстреної (швидкої) медичної допомоги?","ru":"Что нужно прежде всего сделать при оказании домедицинской помощи пострадавшему в ДТП при подозрении на травму головы до приезда бригады экстренной (скорой) медицинской помощи?"},"a":[{"uk":"Обмежити рухи постраждалого в ділянці шийного відділу хребта.","ru":"Ограничить движения пострадавшего в области шейного отдела позвоночника."},{"uk":"Вкрити постраждалого термопокривалом / ковдрою.","ru":"Укрыть пострадавшего термоодеялом / одеялом.","w":{"uk":"Вкрити постраждалого корисно, але це не першочергова дія при травмі голови.","ru":"Укрыть пострадавшего полезно, но это не первоочередное действие при травме головы."}},{"uk":"Здійснювати фіксацію шийного відділу хребта за допомогою шийного коміра.","ru":"Осуществлять фиксацию шейного отдела позвоночника с помощью шейного воротника.","w":{"uk":"Шийний комір накладають медики; невміле накладання може зашкодити, тож до приїзду бригади рухи шиї обмежують руками.","ru":"Шейный воротник накладывают медики; неумелое наложение может навредить, поэтому до приезда бригады движения шеи ограничивают руками."}}],"c":0,"e":{"uk":"Травма голови часто поєднується з травмою шиї, тому насамперед **обмежують рухи шийного відділу хребта** — утримують голову руками в нерухомому положенні.","ru":"Травма головы часто сочетается с травмой шеи, поэтому прежде всего **ограничивают движения шейного отдела позвоночника** — удерживают голову руками в неподвижном положении."}},{"id":"h37-58","t":"h37","num":"37.58","q":{"uk":"За наявності у постраждалого в ДТП ран у ділянці голови необхідно:","ru":"При наличии у пострадавшего в ДТП ран в области головы необходимо:"},"a":[{"uk":"Накласти марлеву пов’язку та зафіксувати її без створення надмірного тиску.","ru":"Наложить марлевую повязку и зафиксировать её без создания чрезмерного давления."},{"uk":"Обробити рани з використанням антисептиків та накласти тугу марлеву пов’язку.","ru":"Обработать раны с использованием антисептиков и наложить тугую марлевую повязку.","w":{"uk":"Антисептики можуть потрапити в мозкові тканини, а туга пов'язка тисне на можливий перелом черепа.","ru":"Антисептики могут попасть в мозговые ткани, а тугая повязка давит на возможный перелом черепа."}},{"uk":"Здійснювати тиск на рани до повної зупинки кровотечі.","ru":"Осуществлять давление на раны до полной остановки кровотечения.","w":{"uk":"Тиск на рану голови може вдавити уламки кісток черепа в мозок.","ru":"Давление на рану головы может вдавить обломки костей черепа в мозг."}}],"c":0,"e":{"uk":"Під раною на голові може бути перелом черепа, тому рану накривають марлевою пов'язкою і фіксують її **без надмірного тиску**.","ru":"Под раной на голове может быть перелом черепа, поэтому рану накрывают марлевой повязкой и фиксируют её **без чрезмерного давления**."}},{"id":"h37-59","t":"h37","num":"37.59","q":{"uk":"Які ознаки тупої травми органів черевної порожнини?","ru":"Каковы признаки тупой травмы органов брюшной полости?"},"a":[{"uk":"Наявність забоїв та гематоми передньої та / або бокової стінки живота.","ru":"Наличие ушибов и гематомы передней и/или боковой стенки живота.","w":{"uk":"Забої та гематоми — ознака тупої травми, але не єдина: характерний і біль у животі.","ru":"Ушибы и гематомы — признак тупой травмы, но не единственный: характерна и боль в животе."}},{"uk":"Біль у ділянці живота.","ru":"Боль в области живота.","w":{"uk":"Біль — ознака тупої травми, але не єдина: на стінці живота бувають і забої та гематоми.","ru":"Боль — признак тупой травмы, но не единственный: на стенке живота бывают и ушибы и гематомы."}},{"uk":"Правильні відповіді 1 і 2.","ru":"Правильные ответы 1 и 2."}],"c":2,"e":{"uk":"На тупу травму живота вказують і **забої та гематоми** на його стінці, і **біль у животі** — тож правильні обидві відповіді.","ru":"На тупую травму живота указывают и **ушибы и гематомы** на его стенке, и **боль в животе** — поэтому верны оба ответа."}},{"id":"h37-60","t":"h37","num":"37.60","q":{"uk":"Що із переліченого належить до ознак гострого мозкового інсульту?","ru":"Что из перечисленного относится к признакам острого мозгового инсульта?"},"a":[{"uk":"Раптова зміна виразу обличчя, порушення його симетрії.","ru":"Внезапное изменение выражения лица, нарушение его симметрии.","w":{"uk":"Асиметрія обличчя — ознака інсульту, але не єдина.","ru":"Асимметрия лица — признак инсульта, но не единственный."}},{"uk":"Раптова слабкість та / або оніміння в руці чи нозі з одного боку.","ru":"Внезапная слабость и/или онемение в руке или ноге с одной стороны.","w":{"uk":"Однобічна слабкість чи оніміння — ознака інсульту, але не єдина.","ru":"Односторонняя слабость или онемение — признак инсульта, но не единственный."}},{"uk":"Раптове порушення мовлення / розуміння простих команд / запитань.","ru":"Внезапное нарушение речи / понимания простых команд / вопросов.","w":{"uk":"Порушення мовлення — ознака інсульту, але не єдина.","ru":"Нарушение речи — признак инсульта, но не единственный."}},{"uk":"Усе вищеперелічене.","ru":"Всё вышеперечисленное."}],"c":3,"e":{"uk":"Інсульт розпізнають за **раптовими** ознаками: асиметрія обличчя, слабкість чи оніміння руки або ноги з одного боку, порушення мовлення чи розуміння — будь-яка з них є приводом негайно викликати екстрену допомогу.","ru":"Инсульт распознают по **внезапным** признакам: асимметрия лица, слабость или онемение руки или ноги с одной стороны, нарушение речи или понимания — любой из них является поводом немедленно вызвать экстренную помощь."}},{"id":"h38-1","t":"h38","num":"38.1","q":{"uk":"Як у цій ситуації ви визначаєте порядок руху?"},"a":[{"uk":"Не гальмуєте, тому що вантажівка повинна вас пропустити."},{"uk":"Гальмуєте, тому що ви зобов’язані пропустити вантажівку."},{"uk":"Керуєтеся ПДР та діями іншого водія."}],"c":2,"pic":["img/hsc/38-1-1.jpg"]},{"id":"h38-2","t":"h38","num":"38.2","q":{"uk":"Якими будуть ваші дії, якщо вантажний автомобіль не зменшує швидкість, виїжджаючи на міст?"},"a":[{"uk":"Продовжувати рух, бо у вас перевага в русі."},{"uk":"Почати гальмування, щоб не створювати аварійну ситуацію."},{"uk":"Ввімкнути дальнє світло, щоб водій зупинився від засліплення."}],"c":1,"pic":["img/hsc/38-2-1.jpg"]},{"id":"h38-3","t":"h38","num":"38.3","q":{"uk":"Якими будуть ваші дії, якщо вантажний автомобіль декілька разів увімкнув дальнє світло?"},"a":[{"uk":"Теж ввімкнути декілька разів дальнє світло, не припиняючи рух."},{"uk":"Подати звуковий сигнал, попереджаючи іншого водія, що у вас перевага в русі."},{"uk":"Почати гальмування, щоб визначити подальші дії іншого водія."}],"c":2,"pic":["img/hsc/38-3-1.jpg"]},{"id":"h38-4","t":"h38","num":"38.4","q":{"uk":"Що може означати короткочасне ввімкнення стоп-сигналів автомобіля, що рухається попереду в щільному транспортному потоці?"},"a":[{"uk":"Прохання про збільшення дистанції."},{"uk":"Попередження про наступне гальмування (зупинку)."},{"uk":"Усе перелічене."}],"c":2},{"id":"h38-5","t":"h38","num":"38.5","q":{"uk":"Як повинен діяти водій автомобіля, який обганяють, що рухається з дальнім світлом фар у темний час доби?"},"a":[{"uk":"Переключитися на ближнє світло фар у момент, коли автомобілі порівнялися, рухаючись сусідніми смугами руху."},{"uk":"Відразу переключитися на ближнє світло, як тільки водій наступного за ним автомобіля почав виїжджати на зустрічну смугу руху."},{"uk":"Включити світло фар, як тільки автомобіль, що обганяє, виявився попереду, та рухатися з ввімкненими габаритними вогнями до моменту, поки автомобіль, що рухається попереду, не віддалився на значну відстань."}],"c":0},{"id":"h38-6","t":"h38","num":"38.6","q":{"uk":"Що необхідно зробити перед тим, як вийти з автомобіля після зупинки на дорозі?"},"a":[{"uk":"Вжити заходів, які виключають мимовільний рух транспортного засобу."},{"uk":"Через дзеркало заднього виду або поворотом голови назад переконатися в безпеці виходу і потім лише виходити."},{"uk":"У темну пору доби на неосвітленій ділянці дороги (крім житлових зон) ввімкнути габаритні чи стоянкові ліхтарі."},{"uk":"Виконати все, перелічене вище."}],"c":3},{"id":"h38-7","t":"h38","num":"38.7","q":{"uk":"Які з перерахованих дій учасників дорожнього руху можуть призвести до виникнення аварійної ситуації під час перестоювання в транспортному потоці?"},"a":[{"uk":"Перестроювання автомобіля в «сліпій» (мертвій) зоні."},{"uk":"Різке гальмування автомобіля, що рухається попереду."},{"uk":"Різке прискорення автомобіля, що рухається позаду сусідньою смугою руху."},{"uk":"Усі, перелічені вище."}],"c":3},{"id":"h38-8","t":"h38","num":"38.8","q":{"uk":"Під час руху по дорозі поза населеним пунктом Ви зібралися зробити обгін вантажного автомобіля. Після ввімкнення Вами лівого покажчика повороту водій вантажного автомобіля ввімкнув та вимкнув сигнал лівого повороту. Що це може означати?"},"a":[{"uk":"Водій вантажного автомобіля, порушуючи Правила дорожнього руху, перешкоджає виконанню обгону."},{"uk":"Водій вантажного автомобіля попереджає Вас про небезпеку під час здійснення обгону, яку Ви не в змозі виявити."},{"uk":"Водій вантажного автомобіля зібрався сам виконати обгін, але, побачивши Ваші дії, відмовився від запланованого."}],"c":1},{"id":"h38-9","t":"h38","num":"38.9","q":{"uk":"Під час руху в темний час доби автомобіль, що рухався перед Вами, різко загальмував на смузі руху. Які Ваші дії в ситуації, що склалася, будуть найбезпечнішими?"},"a":[{"uk":"Подати звуковий сигнал та об’їхати автомобіль, що зупинився, узбіччям."},{"uk":"Ввімкнути лівий покажчик повороту та об’їхати автомобіль, що зупинився, зустрічною смугою руху."},{"uk":"Зупинитися у полосі руху, ввімкнувши аварійну світлову сигналізацію, та не об’їжджати автомобіль, що зупинився, не переконавшись у безпеці такого маневру."}],"c":2},{"id":"h38-10","t":"h38","num":"38.10","q":{"uk":"В який бік необхідно дивитися водію при зустрічному роз’їзді в темний час доби для того, щоб зменшити вірогідність засліплення?"},"a":[{"uk":"У бік лівого узбіччя, контролюючи край проїжджої частини дороги."},{"uk":"У бік правого узбіччя, контролюючи край проїжджої частини дороги."},{"uk":"По центру проїжджої частини дороги, контролюючи лінію, що розділяє транспортні потоки протилежних напрямків."}],"c":1},{"id":"h38-11","t":"h38","num":"38.11","q":{"uk":"Відносно якої лінії дорожньої розмітки найбільш безпечно контролювати положення свого автомобіля при зустрічному роз’їзді в темний час доби?"},"a":[{"uk":"Відносно лінії, що позначає лівий край проїжджої частини дороги."},{"uk":"Відносно лінії, що позначає правий край проїжджої частини дороги."},{"uk":"Відносно лінії, що розділяє транспортні потоки протилежних напрямків."}],"c":1},{"id":"h38-12","t":"h38","num":"38.12","q":{"uk":"Чи змінюється поле зору водія при збільшенні швидкості руху?"},"a":[{"uk":"Звужується."},{"uk":"Розширюється."},{"uk":"Не змінюється."}],"c":0},{"id":"h38-13","t":"h38","num":"38.13","q":{"uk":"Гальмівний шлях на дорозі одразу після дощу:"},"a":[{"uk":"Збільшується."},{"uk":"Зменшується."},{"uk":"Не змінюється."}],"c":0},{"id":"h38-14","t":"h38","num":"38.14","q":{"uk":"При русі в транспортному потоці водій, що рухався по сусідній смузі, різко перелаштувався на Вашу смугу руху, змусивши Вас загальмувати. Що необхідно Вам зробити в даній ситуації?"},"a":[{"uk":"Подати світловий сигнал фарами."},{"uk":"Випередити порушника, перестроїтись перед ним на його смугу і різко загальмувати."},{"uk":"На найближчому світлофорі при заборонному сигналі підійти до його автомобілю і зробити зауваження порушнику."},{"uk":"Неприпустима жодна з перерахованих дій."}],"c":3},{"id":"h39-1","t":"h39","num":"39.1","q":{"uk":"Оберіть правильне твердження однієї з умов використання спільного повідомлення про дорожньо-транспортну пригоду (Європротоколу):"},"a":[{"uk":"Наявність у одного з водіїв чинного страхового полісу (страховий сертифікат «Зелена картка») про укладання договору обов’язкового страхування цивільно- правової відповідальності власників наземних транспортних засобів."},{"uk":"Наявність у обох водіїв транспортних засобів чинних страхових полісів (страхових сертифікатів «Зелена картка») про укладання договорів обов’язкового страхування цивільно-правової відповідальності."},{"uk":"Наявність у водіїв транспортних засобів чинних страхових полісів (страхових сертифікатів «Зелена картка») про укладання договорів обов’язкового страхування цивільно-правової відповідальності або посвідчення учасника бойових дій, особи з інвалідністю внаслідок війни або особи з інвалідністю І групи."},{"uk":"Всі твердження вірні."}],"c":1},{"id":"h39-2","t":"h39","num":"39.2","q":{"uk":"Чи можна скласти спільне повідомлення про дорожньо-транспортну пригоду (Європротокол) у разі завдання шкоди об’єктам крім ТЗ?"},"a":[{"uk":"Так."},{"uk":"Ні."},{"uk":"Так, якщо власник пошкодженого майна не має претензій до учасників події."},{"uk":"Жодне з тверджень не вірне."}],"c":1},{"id":"h39-3","t":"h39","num":"39.3","q":{"uk":"Чи складається спільне повідомлення про дорожньо-транспортну пригоду (Європротокол) якщо шкода завдана третьому ТЗ, крім двох учасників ДТП?"},"a":[{"uk":"Так."},{"uk":"Ні."},{"uk":"Так, якщо шкода завдана третьому ТЗ незначна."},{"uk":"Так, якщо пошкоджено не більше 5 ТЗ."}],"c":1},{"id":"h39-4","t":"h39","num":"39.4","q":{"uk":"Ким складається спільне повідомлення про дорожньо-транспортну пригоду (Європротокол)?"},"a":[{"uk":"Поліцейськими."},{"uk":"Водіями транспортних засобів, що є учасниками ДТП."},{"uk":"Водієм транспортного засобу винного у ДТП та потерпілими."},{"uk":"Всі відповіді вірні."}],"c":1},{"id":"h39-5","t":"h39","num":"39.5","q":{"uk":"Хто з водіїв, учасників ДТП, заповнює пункт «Транспортний засіб А» при оформленні спільного повідомлення про дорожньо-транспортну пригоду (Європротоколу)?)"},"a":[{"uk":"Це вирішують поліцейські."},{"uk":"Винуватець ДТП."},{"uk":"Потерпілий в ДТП."},{"uk":"Будь-хто з водіїв транспортних засобів — учасників ДТП."}],"c":3},{"id":"h39-6","t":"h39","num":"39.6","q":{"uk":"В разі завдання шкоди життю та здоров’ю учаснику (учасникам) ДТП чи складається спільне повідомлення про дорожньо-транспортну пригоду (Європротокол)?"},"a":[{"uk":"Так."},{"uk":"Ні."},{"uk":"Ні, якщо є загиблі."},{"uk":"Так, якщо шкода є незначною."}],"c":1},{"id":"h44-1","t":"h44","num":"44.1","q":{"uk":"Ви, як водій автомобіля, маєте право використовувати узбіччя:","ru":"Вы, как водитель автомобиля, имеете право использовать обочину:"},"a":[{"uk":"Для руху.","ru":"Для движения.","w":{"uk":"Рух автомобілів узбіччям заборонений: воно призначене для пішоходів, велосипедистів, мопедів і для зупинки та стоянки.","ru":"Движение автомобилей по обочине запрещено: она предназначена для пешеходов, велосипедистов, мопедов и для остановки и стоянки."}},{"uk":"Для зупинки та стоянки.","ru":"Для остановки и стоянки."},{"uk":"Відповіді, зазначені в пунктах 1, 2.","ru":"Ответы, указанные в пунктах 1, 2.","w":{"uk":"Варіант містить рух узбіччям, а автомобілю він не дозволений.","ru":"Вариант включает движение по обочине, а автомобилю оно не разрешено."}}],"c":1,"e":{"uk":"За визначенням ({p:1.10}), узбіччя **не призначене для руху** транспортних засобів, але його можна використовувати для **зупинки та стоянки** — саме там їх і належить здійснювати ({p:15.1}).","ru":"По определению ({p:1.10}), обочина **не предназначена для движения** транспортных средств, но её можно использовать для **остановки и стоянки** — именно там их и следует осуществлять ({p:15.1})."},"ref":["1.10","15.1"],"pic":["img/hsc/44-1-1.jpg"]},{"id":"h44-2","t":"h44","num":"44.2","q":{"uk":"З якого віку надається право на керування транспортними засобами категорії В?","ru":"С какого возраста предоставляется право на управление транспортными средствами категории B?"},"a":[{"uk":"З 16 років.","ru":"С 16 лет.","w":{"uk":"З 16 років можна отримати лише категорії A1 і A (мотоцикли, мопеди).","ru":"С 16 лет можно получить только категории A1 и A (мотоциклы, мопеды)."}},{"uk":"З 18 років.","ru":"С 18 лет."},{"uk":"З 19 років.","ru":"С 19 лет.","w":{"uk":"З 19 років надаються категорії BE, C1E, CE — составів із причепами.","ru":"С 19 лет предоставляются категории BE, C1E, CE — составов с прицепами."}},{"uk":"З 21 року.","ru":"С 21 года.","w":{"uk":"З 21 року надаються категорії D1, D, D1E, DE, T — автобуси, трамваї, тролейбуси.","ru":"С 21 года предоставляются категории D1, D, D1E, DE, T — автобусы, трамваи, троллейбусы."}}],"c":1,"e":{"uk":"Право керувати автомобілями категорій B1, B, C1, C надається **з 18 років** ({p:2.13}).","ru":"Право управлять автомобилями категорий B1, B, C1, C предоставляется **с 18 лет** ({p:2.13})."},"ref":["2.13"],"pic":["img/hsc/44-2-1.jpg"]},{"id":"h44-3","t":"h44","num":"44.3","q":{"uk":"Яку максимальну швидкість руху встановлено в населених пунктах, позначених даним дорожнім знаком?","ru":"Какая максимальная скорость движения установлена в населённых пунктах, обозначенных данным дорожным знаком?"},"a":[{"uk":"50 км/год.","ru":"50 км/ч."},{"uk":"60 км/год.","ru":"60 км/ч.","w":{"uk":"60 км/год — колишнє обмеження; нині в населених пунктах дозволено не більше 50 км/год.","ru":"60 км/ч — прежнее ограничение; сейчас в населённых пунктах разрешено не более 50 км/ч."}},{"uk":"70 км/год.","ru":"70 км/ч.","w":{"uk":"70 км/год у населеному пункті, позначеному білим знаком, перевищує загальне обмеження в 50 км/год.","ru":"70 км/ч в населённом пункте, обозначенном белым знаком, превышает общее ограничение в 50 км/ч."}},{"uk":"80 км/год.","ru":"80 км/ч.","w":{"uk":"80 км/год — обмеження для окремих транспортних засобів поза населеними пунктами ({p:12.6}), а не в місті.","ru":"80 км/ч — ограничение для отдельных транспортных средств вне населённых пунктов ({p:12.6}), а не в городе."}}],"c":0,"e":{"uk":"Білий знак {s:5.49} позначає населений пункт, у якому діють правила руху в населених пунктах, тобто швидкість — **не більше 50 км/год** ({p:12.4}).","ru":"Белый знак {s:5.49} обозначает населённый пункт, в котором действуют правила движения в населённых пунктах, то есть скорость — **не более 50 км/ч** ({p:12.4})."},"ref":["12.4"],"pic":["img/hsc/44-3-1.jpg"]},{"id":"h44-4","t":"h44","num":"44.4","q":{"uk":"Кожна особа, під час проходження навчання практичному водінню на легковому автомобілі (категорія В), зобов'язана отримати:","ru":"Каждое лицо во время прохождения обучения практическому вождению на легковом автомобиле (категория B) обязано получить:"},"a":[{"uk":"Практичне керування автомобілем на майданчику.","ru":"Практическое управление автомобилем на площадке.","w":{"uk":"Керування на майданчику обов'язкове, але це лише частина програми.","ru":"Управление на площадке обязательно, но это лишь часть программы."}},{"uk":"Практичне керування автомобілем на майданчику в темну пору доби.","ru":"Практическое управление автомобилем на площадке в тёмное время суток.","w":{"uk":"Керування в темну пору доби обов'язкове, але це лише частина програми.","ru":"Управление в тёмное время суток обязательно, но это лишь часть программы."}},{"uk":"Навички руху заднім ходом за допомогою дзеркал заднього виду.","ru":"Навыки движения задним ходом с помощью зеркал заднего вида.","w":{"uk":"Навички руху заднім ходом обов'язкові, але це лише частина програми.","ru":"Навыки движения задним ходом обязательны, но это лишь часть программы."}},{"uk":"Відповіді 1, 2 і 3 правильні.","ru":"Ответы 1, 2 и 3 правильные."}],"c":3,"e":{"uk":"Програма практичного навчання водінню на категорію B передбачає **усі три** елементи: керування на майданчику (з нього починається навчання — {p:24.4}), керування в темну пору доби та рух заднім ходом за дзеркалами.","ru":"Программа практического обучения вождению на категорию B предусматривает **все три** элемента: управление на площадке (с него начинается обучение — {p:24.4}), управление в тёмное время суток и движение задним ходом по зеркалам."},"ref":["24.4"]},{"id":"h44-5","t":"h44","num":"44.5","q":{"uk":"Рухаючись у темну пору доби, водій механічного транспортного засобу незалежно від ступеня освітлення дороги повинен ввімкнути такі зовнішні світлові пристрої:","ru":"Двигаясь в тёмное время суток, водитель механического транспортного средства независимо от степени освещения дороги должен включить следующие внешние световые приборы:"},"a":[{"uk":"Габаритні ліхтарі.","ru":"Габаритные огни.","w":{"uk":"Самих габаритних ліхтарів у русі недостатньо: їх вмикають під час зупинки ({p:19.4}) або на причепах.","ru":"Одних габаритных огней в движении недостаточно: их включают во время остановки ({p:19.4}) или на прицепах."}},{"uk":"Фари ближнього або дальнього світла.","ru":"Фары ближнего или дальнего света."},{"uk":"Протитуманні фари і задній протитуманний ліхтар.","ru":"Противотуманные фары и задний противотуманный фонарь.","w":{"uk":"Протитуманні фари й задній протитуманний ліхтар дозволено вмикати лише в умовах недостатньої видимості ({p:19.9}).","ru":"Противотуманные фары и задний противотуманный фонарь разрешено включать только в условиях недостаточной видимости ({p:19.9})."}}],"c":1,"e":{"uk":"У темну пору доби незалежно від освітлення дороги на механічному транспортному засобі мають бути ввімкнені **фари ближнього (дальнього) світла** ({p:19.1}).","ru":"В тёмное время суток независимо от освещения дороги на механическом транспортном средстве должны быть включены **фары ближнего (дальнего) света** ({p:19.1})."},"ref":["19.1"]},{"id":"h44-6","t":"h44","num":"44.6","q":{"uk":"У якому місці повинні здійснюватися зупинка і стоянка транспортного засобу на дорозі?","ru":"В каком месте должны осуществляться остановка и стоянка транспортного средства на дороге?"},"a":[{"uk":"У спеціально відведених місцях.","ru":"В специально отведённых местах.","w":{"uk":"Спеціально відведені місця — лише одне з двох місць, названих у {p:15.1}; можна й на узбіччі.","ru":"Специально отведённые места — лишь одно из двух мест, названных в {p:15.1}; можно и на обочине."}},{"uk":"На узбіччі.","ru":"На обочине.","w":{"uk":"Узбіччя — лише одне з двох місць, названих у {p:15.1}; можна й у спеціально відведених місцях.","ru":"Обочина — лишь одно из двух мест, названных в {p:15.1}; можно и в специально отведённых местах."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2."}],"c":2,"e":{"uk":"Зупинка і стоянка на дорозі мають здійснюватися **у спеціально відведених місцях чи на узбіччі** ({p:15.1}) — тож правильні обидва варіанти.","ru":"Остановка и стоянка на дороге должны осуществляться **в специально отведённых местах или на обочине** ({p:15.1}) — поэтому верны оба варианта."},"ref":["15.1"]},{"id":"h44-7","t":"h44","num":"44.7","q":{"uk":"Що повинен враховувати водій під час вибору безпечної дистанції та інтервалу?","ru":"Что должен учитывать водитель при выборе безопасной дистанции и интервала?"},"a":[{"uk":"Швидкість руху.","ru":"Скорость движения.","w":{"uk":"Швидкість — лише один із чотирьох чинників, названих у {p:13.1}.","ru":"Скорость — лишь один из четырёх факторов, названных в {p:13.1}."}},{"uk":"Дорожню обстановку.","ru":"Дорожную обстановку.","w":{"uk":"Дорожня обстановка — лише один із чотирьох чинників, названих у {p:13.1}.","ru":"Дорожная обстановка — лишь один из четырёх факторов, названных в {p:13.1}."}},{"uk":"Особливості вантажу, що перевозиться.","ru":"Особенности перевозимого груза.","w":{"uk":"Особливості вантажу — лише один із чотирьох чинників, названих у {p:13.1}.","ru":"Особенности груза — лишь один из четырёх факторов, названных в {p:13.1}."}},{"uk":"Стан транспортного засобу.","ru":"Состояние транспортного средства.","w":{"uk":"Стан транспортного засобу — лише один із чотирьох чинників, названих у {p:13.1}.","ru":"Состояние транспортного средства — лишь один из четырёх факторов, названных в {p:13.1}."}},{"uk":"Відповіді 1, 2, 3 і 4.","ru":"Ответы 1, 2, 3 и 4."}],"c":4,"e":{"uk":"Безпечну дистанцію та інтервал водій обирає залежно від **швидкості, дорожньої обстановки, особливостей вантажу і стану транспортного засобу** ({p:13.1}) — тобто з урахуванням усіх чотирьох чинників.","ru":"Безопасную дистанцию и интервал водитель выбирает в зависимости от **скорости, дорожной обстановки, особенностей груза и состояния транспортного средства** ({p:13.1}) — то есть с учётом всех четырёх факторов."},"ref":["13.1"]},{"id":"h44-8","t":"h44","num":"44.8","q":{"uk":"Як має рухатися нерейковий транспортний засіб на дорозі, яка має по дві й більше смуг для руху в кожному напрямку, вільній від інших транспортних засобів, якщо немає необхідності виконувати маневри?","ru":"Как должно двигаться нерельсовое транспортное средство на дороге, имеющей по две и более полосы для движения в каждом направлении, свободной от других транспортных средств, если нет необходимости выполнять манёвры?"},"a":[{"uk":"Якнайближче до правого краю проїзної частини.","ru":"Как можно ближе к правому краю проезжей части."},{"uk":"У будь-якій смузі – на розсуд водія.","ru":"В любой полосе – на усмотрение водителя.","w":{"uk":"Вибір смуги «на розсуд водія» суперечить вимозі триматися правого краю ({p:11.2}).","ru":"Выбор полосы «на усмотрение водителя» противоречит требованию держаться правого края ({p:11.2})."}},{"uk":"Продовжувати рух по тій самій смузі де і їхав.","ru":"Продолжать движение по той же полосе, где и ехал.","w":{"uk":"Якщо водій їхав не крайньою правою смугою, а маневрів не потрібно, він має повернутися праворуч ({p:11.2}).","ru":"Если водитель ехал не по крайней правой полосе, а манёвров не нужно, он должен вернуться вправо ({p:11.2})."}}],"c":0,"e":{"uk":"На дорогах із двома й більше смугами в одному напрямку нерейкові транспортні засоби мають рухатися **якнайближче до правого краю** проїзної частини, якщо не виконують випередження, об'їзд чи перестроювання для повороту ліворуч або розвороту ({p:11.2}).","ru":"На дорогах с двумя и более полосами в одном направлении нерельсовые транспортные средства должны двигаться **как можно ближе к правому краю** проезжей части, если не выполняют опережение, объезд или перестроение для поворота налево или разворота ({p:11.2})."},"ref":["11.2"]},{"id":"h44-9","t":"h44","num":"44.9","q":{"uk":"Водій, який рухається по перехрестю, де організовано круговий рух, не маючи наміру змінювати своєї смуги, зобов'язаний:","ru":"Водитель, который движется по перекрёстку с круговым движением, не имея намерения менять свою полосу, обязан:"},"a":[{"uk":"Включити лівий поворот, щоб показати всім свій рух по колу.","ru":"Включить левый поворот, чтобы показать всем своё движение по кругу.","w":{"uk":"Лівий покажчик на кільці сприймуть як намір перестроїтися ліворуч — такий сигнал незрозумілий для інших і заборонений ({p:9.4}).","ru":"Левый указатель на кольце воспримут как намерение перестроиться налево — такой сигнал непонятен для других и запрещён ({p:9.4})."}},{"uk":"Включити правий поворот, щоб попередити всіх, що він скоро поїде праворуч.","ru":"Включить правый поворот, чтобы предупредить всех, что он скоро поедет направо.","w":{"uk":"Правий покажчик вмикають безпосередньо перед з'їздом чи перестроюванням, а не «заздалегідь» під час руху по колу ({p:9.4}).","ru":"Правый указатель включают непосредственно перед съездом или перестроением, а не «заранее» во время движения по кругу ({p:9.4})."}},{"uk":"Не вмикати покажчики поворотів, поки він рухається по одній смузі.","ru":"Не включать указатели поворота, пока он движется по одной полосе."}],"c":2,"e":{"uk":"Покажчики повороту вмикають перед перестроюванням, поворотом чи розворотом ({p:9.2}); рух по колу в тій самій смузі маневром не є, а зайвий сигнал може ввести інших в оману, що заборонено ({p:9.4}).","ru":"Указатели поворота включают перед перестроением, поворотом или разворотом ({p:9.2}); движение по кругу в той же полосе манёвром не является, а лишний сигнал может ввести других в заблуждение, что запрещено ({p:9.4})."},"ref":["9.2","9.4"]},{"id":"h44-10","t":"h44","num":"44.10","q":{"uk":"Рухаючись поза населеним пунктом у світлу пору доби, водій механічного транспортного засобу повинен увімкнути:","ru":"Двигаясь вне населённого пункта в светлое время суток, водитель механического транспортного средства должен включить:"},"a":[{"uk":"Аварійну світлову сигналізацію.","ru":"Аварийную световую сигнализацию.","w":{"uk":"Аварійну сигналізацію вмикають у разі вимушеної зупинки, ДТП чи засліплення ({p:9.9}), а не для звичайного руху.","ru":"Аварийную сигнализацию включают при вынужденной остановке, ДТП или ослеплении ({p:9.9}), а не для обычного движения."}},{"uk":"Денні ходові вогні, а в разі їх відсутності у конструкції транспортного засобу – дальнє світло фар.","ru":"Дневные ходовые огни, а при их отсутствии в конструкции транспортного средства – дальний свет фар.","w":{"uk":"Замість денних ходових вогнів вмикають ближнє світло, а не дальнє, яке може засліпити інших водіїв.","ru":"Вместо дневных ходовых огней включают ближний свет, а не дальний, который может ослепить других водителей."}},{"uk":"Денні ходові вогні, а в разі їх відсутності у конструкції транспортного засобу – ближнє світло фар.","ru":"Дневные ходовые огни, а при их отсутствии в конструкции транспортного средства – ближний свет фар."}],"c":2,"e":{"uk":"Поза населеними пунктами на всіх механічних транспортних засобах мають бути ввімкнені **денні ходові вогні**, а якщо їх немає — **ближнє світло** фар ({p:9.8}).","ru":"Вне населённых пунктов на всех механических транспортных средствах должны быть включены **дневные ходовые огни**, а если их нет — **ближний свет** фар ({p:9.8})."},"ref":["9.8"]},{"id":"h44-11","t":"h44","num":"44.11","q":{"uk":"Де заборонене подавання звукового сигналу?","ru":"Где запрещена подача звукового сигнала?"},"a":[{"uk":"У населених пунктах, окрім випадків, коли без цього неможливо запобігти дорожньо-транспортній пригоді.","ru":"В населённых пунктах, кроме случаев, когда без этого невозможно предотвратить дорожно-транспортное происшествие.","w":{"uk":"Заборона діє не лише в населених пунктах, а й поза ними в зоні дії знака {s:3.33}.","ru":"Запрет действует не только в населённых пунктах, но и вне их в зоне действия знака {s:3.33}."}},{"uk":"Поза населеними пунктами, в місцях, де встановлений знак «Подавання звукового сигналу заборонено», крім випадків, коли без цього неможливо запобігти дорожньо-транспортній пригоді.","ru":"Вне населённых пунктов, в местах, где установлен знак «Подача звукового сигнала запрещена», кроме случаев, когда без этого невозможно предотвратить дорожно-транспортное происшествие.","w":{"uk":"Поза населеними пунктами сигнал заборонено лише в зоні знака {s:3.33}, але в населених пунктах заборона діє завжди ({p:9.5}).","ru":"Вне населённых пунктов сигнал запрещён только в зоне знака {s:3.33}, но в населённых пунктах запрет действует всегда ({p:9.5})."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2."}],"c":2,"e":{"uk":"Звуковий сигнал заборонено подавати **в населених пунктах** ({p:9.5}) і **в зоні дії знака** {s:3.33} поза ними; в обох випадках виняток — коли без сигналу неможливо запобігти ДТП.","ru":"Звуковой сигнал запрещено подавать **в населённых пунктах** ({p:9.5}) и **в зоне действия знака** {s:3.33} вне их; в обоих случаях исключение — когда без сигнала невозможно предотвратить ДТП."},"ref":["9.5"]},{"id":"h44-12","t":"h44","num":"44.12","q":{"uk":"Ви рухаєтесь на автомобілі, у якого несправні світлові покажчики поворотів, але Вам необхідно повернути праворуч. Ваші дії:","ru":"Вы движетесь на автомобиле, у которого неисправны световые указатели поворота, но вам необходимо повернуть направо. Ваши действия:"},"a":[{"uk":"Витягнете праву руку в праву сторону і зігнете під прямим кутом вгору.","ru":"Вытянете правую руку в правую сторону и согнёте под прямым углом вверх.","w":{"uk":"Права рука, зігнута під прямим кутом угору, означає поворот ліворуч ({p:9.3}).","ru":"Правая рука, согнутая под прямым углом вверх, означает поворот налево ({p:9.3})."}},{"uk":"Витягнете ліву руку в ліву сторону.","ru":"Вытянете левую руку в левую сторону.","w":{"uk":"Ліва рука, витягнута вбік, — сигнал повороту ліворуч ({p:9.3}).","ru":"Левая рука, вытянутая в сторону, — сигнал поворота налево ({p:9.3})."}},{"uk":"Витягнете ліву руку в ліву сторону у вікно і зігнете під прямим кутом вгору.","ru":"Вытянете левую руку в левую сторону в окно и согнёте под прямым углом вверх."}],"c":2,"e":{"uk":"Сигнал повороту праворуч подають правою рукою, витягнутою вбік, або **лівою рукою, витягнутою вбік і зігнутою в лікті під прямим кутом угору** ({p:9.3}); водій легкового авто зручно показує його лівою рукою у вікно.","ru":"Сигнал поворота направо подают правой рукой, вытянутой в сторону, или **левой рукой, вытянутой в сторону и согнутой в локте под прямым углом вверх** ({p:9.3}); водитель легкового авто удобно показывает его левой рукой в окно."},"ref":["9.3"]},{"id":"h44-13","t":"h44","num":"44.13","q":{"uk":"Що з переліченого нижче входить в обов'язки учасників дорожнього руху?","ru":"Что из перечисленного ниже входит в обязанности участников дорожного движения?"},"a":[{"uk":"Бути уважним, стежити за дорожньою обстановкою.","ru":"Быть внимательным, следить за дорожной обстановкой.","w":{"uk":"Уважність — обов'язок, але не єдиний: решта варіантів теж входять до {p:2.3}.","ru":"Внимательность — обязанность, но не единственная: остальные варианты тоже входят в {p:2.3}."}},{"uk":"Не забруднювати проїзну частину та смугу відведення автомобільних доріг.","ru":"Не загрязнять проезжую часть и полосу отвода автомобильных дорог.","w":{"uk":"Не забруднювати дорогу — обов'язок, але не єдиний: решта варіантів теж входять до {p:2.3}.","ru":"Не загрязнять дорогу — обязанность, но не единственная: остальные варианты тоже входят в {p:2.3}."}},{"uk":"Не створювати своїми діями загрози безпеці дорожнього руху.","ru":"Не создавать своими действиями угрозы безопасности дорожного движения.","w":{"uk":"Не створювати загроз — обов'язок, але не єдиний: решта варіантів теж входять до {p:2.3}.","ru":"Не создавать угроз — обязанность, но не единственная: остальные варианты тоже входят в {p:2.3}."}},{"uk":"Повідомляти дорожньо-експлуатаційним організаціям про виявлені факти створення перешкод для дорожнього руху.","ru":"Сообщать дорожно-эксплуатационным организациям о выявленных фактах создания помех для дорожного движения.","w":{"uk":"Повідомляти про перешкоди — обов'язок, але не єдиний: решта варіантів теж входять до {p:2.3}.","ru":"Сообщать о помехах — обязанность, но не единственная: остальные варианты тоже входят в {p:2.3}."}},{"uk":"Відповіді 1,2,3,4 входять в обов’язки.","ru":"Ответы 1, 2, 3, 4 входят в обязанности."}],"c":4,"e":{"uk":"Усі чотири вимоги прямо названі серед обов'язків водія для забезпечення безпеки руху ({p:2.3}) — тож правильна відповідь «1, 2, 3, 4».","ru":"Все четыре требования прямо названы среди обязанностей водителя для обеспечения безопасности движения ({p:2.3}) — поэтому правильный ответ «1, 2, 3, 4»."},"ref":["2.3"]},{"id":"h44-14","t":"h44","num":"44.14","q":{"uk":"Які документи повинен мати при собі водій механічного транспортного засобу?","ru":"Какие документы должен иметь при себе водитель механического транспортного средства?"},"a":[{"uk":"Реєстраційний документ на транспортний засіб.","ru":"Регистрационный документ на транспортное средство.","w":{"uk":"Реєстраційного документа недостатньо: потрібні ще посвідчення водія і страховий поліс.","ru":"Регистрационного документа недостаточно: нужны ещё водительское удостоверение и страховой полис."}},{"uk":"Посвідчення водія на право керування транспортним засобом відповідної категорії і поліс (сертифікат) обов'язкового страхування цивільно-правової відповідальності власників наземних транспортних засобів (крім водіїв, які відповідно до законодавства звільняються від обов’язкового страхування цивільно-правової відповідальності власників наземних транспортних засобів на території України).","ru":"Водительское удостоверение на право управления транспортным средством соответствующей категории и полис (сертификат) обязательного страхования гражданско-правовой ответственности владельцев наземных транспортных средств (кроме водителей, которые в соответствии с законодательством освобождаются от обязательного страхования гражданско-правовой ответственности владельцев наземных транспортных средств на территории Украины).","w":{"uk":"Посвідчення водія й поліс обов'язкові, але потрібен ще й реєстраційний документ на транспортний засіб.","ru":"Водительское удостоверение и полис обязательны, но нужен ещё и регистрационный документ на транспортное средство."}},{"uk":"Генеральна довіреність на транспортний засіб або тимчасовий реєстраційний талон.","ru":"Генеральная доверенность на транспортное средство или временный регистрационный талон.","w":{"uk":"Довіреність і тимчасовий реєстраційний талон не входять до переліку {p:2.1}: щоб передати авто іншій особі, власнику досить передати їй реєстраційний документ ({p:2.2}).","ru":"Доверенность и временный регистрационный талон не входят в перечень {p:2.1}: чтобы передать авто другому лицу, владельцу достаточно передать ему регистрационный документ ({p:2.2})."}},{"uk":"Усе перелічене вище.","ru":"Всё перечисленное выше.","w":{"uk":"Варіант включає довіреність або тимчасовий талон, яких Правила не вимагають.","ru":"Вариант включает доверенность или временный талон, которых Правила не требуют."}},{"uk":"Відповіді 1 і 2.","ru":"Ответы 1 и 2."}],"c":4,"e":{"uk":"Згідно з {p:2.1}, водій повинен мати при собі **посвідчення водія** відповідної категорії, **реєстраційний документ** на транспортний засіб і **поліс** обов'язкового страхування цивільно-правової відповідальності — тобто документи з відповідей 1 і 2.","ru":"Согласно {p:2.1}, водитель должен иметь при себе **водительское удостоверение** соответствующей категории, **регистрационный документ** на транспортное средство и **полис** обязательного страхования гражданско-правовой ответственности — то есть документы из ответов 1 и 2."},"ref":["2.1","2.2"]},{"id":"h44-15","t":"h44","num":"44.15","q":{"uk":"Яку максимальну кількість пасажирів має право перевозити водій з категорією “В”?","ru":"Какое максимальное количество пассажиров имеет право перевозить водитель с категорией «B»?"},"a":[{"uk":"Менше дев'яти.","ru":"Меньше девяти."},{"uk":"Більше сімнадцяти.","ru":"Больше семнадцати.","w":{"uk":"Понад 16 пасажирських місць мають автобуси категорії D — для них потрібна відповідна категорія.","ru":"Более 16 пассажирских мест имеют автобусы категории D — для них нужна соответствующая категория."}},{"uk":"Більше дев'яти.","ru":"Больше девяти.","w":{"uk":"Транспортні засоби з дев'ятьма й більше пасажирськими місцями належать до категорій D1 або D, а не B.","ru":"Транспортные средства с девятью и более пассажирскими местами относятся к категориям D1 или D, а не B."}}],"c":0,"e":{"uk":"До категорії B належать автомобілі, у яких **не більше восьми** місць для сидіння, крім місця водія ({p:2.13}), тож пасажирів може бути менше дев'яти.","ru":"К категории B относятся автомобили, у которых **не более восьми** мест для сидения, кроме места водителя ({p:2.13}), поэтому пассажиров может быть меньше девяти."},"ref":["2.13"]},{"id":"h44-16","t":"h44","num":"44.16","q":{"uk":"Зміст навчального матеріалу та кількість практичних годин для проходження навчання практичному водінню на легковому автомобілі (категорія В), визначається:","ru":"Содержание учебного материала и количество практических часов для прохождения обучения практическому вождению на легковом автомобиле (категория B) определяется:"},"a":[{"uk":"Кожним навчальним закладом самостійно, в залежності від рівня вмінь особи, що навчається.","ru":"Каждым учебным заведением самостоятельно, в зависимости от уровня умений обучающегося.","w":{"uk":"Навчальний заклад не може сам визначати зміст і обсяг навчання — він зобов'язаний дотримуватися типової програми.","ru":"Учебное заведение не может само определять содержание и объём обучения — оно обязано соблюдать типовую программу."}},{"uk":"Кожним спеціалістом з практичного навчання самостійно, в залежності від рівня вмінь особи, що навчається.","ru":"Каждым специалистом по практическому обучению самостоятельно, в зависимости от уровня умений обучающегося.","w":{"uk":"Інструктор працює за затвердженою програмою і не вирішує сам, чого й скільки навчати.","ru":"Инструктор работает по утверждённой программе и не решает сам, чему и сколько обучать."}},{"uk":"Типовою навчальною програмою підготовки та перепідготовки водіїв транспортних засобів.","ru":"Типовой учебной программой подготовки и переподготовки водителей транспортных средств."}],"c":2,"e":{"uk":"Зміст навчання та мінімальна кількість годин практичного водіння встановлюються **Типовою навчальною програмою** підготовки й перепідготовки водіїв — вона єдина для всіх навчальних закладів.","ru":"Содержание обучения и минимальное количество часов практического вождения устанавливаются **Типовой учебной программой** подготовки и переподготовки водителей — она единая для всех учебных заведений."}},{"id":"h45-1","t":"h45","num":"45.1","q":{"uk":"Недостатньою видимістю вважається:"},"a":[{"uk":"Видимість дороги в напрямку руху менше 300 метрів, обмежена поворотом дороги."},{"uk":"Видимість дороги в напрямку руху менше 300 м у сутінках, в умовах туману, дощу, снігопаду тощо."},{"uk":"Небезпечний поворот, небезпечний підйом, небезпечний спуск."}],"c":1,"pic":["img/hsc/45-1-1.jpg"]},{"id":"h45-2","t":"h45","num":"45.2","q":{"uk":"Що означає вимога дати дорогу?"},"a":[{"uk":"Вимога до учасника дорожнього руху не продовжувати або не відновлювати рух, не здійснювати будь-яких маневрів (за винятком вимоги звільнити займану смугу руху), якщо це може примусити інших учасників дорожнього руху, які мають перевагу, змінити напрямок руху або швидкість."},{"uk":"Вимога обов'язкової зупинки, щоб дати дорогу всім учасникам дорожнього руху."},{"uk":"Вимога обов'язкової зупинки перед дорожнім знаком «Дати дорогу»."}],"c":0,"pic":["img/hsc/45-2-1.jpg"]},{"id":"h45-3","t":"h45","num":"45.3","q":{"uk":"Перехрестям вважається:"},"a":[{"uk":"Перехрещення, прилягання або розгалуження доріг на одному рівні, межею якого є уявні лінії між початком заокруглень країв проїзної частини кожної з доріг та яке не є виїздом з прилеглих територій."},{"uk":"Місце перетину дороги над іншою дорогою (залізницею) на різних рівнях за допомогою шляхопроводу."},{"uk":"Місце прилягання до дороги виїзду з прилеглої території."},{"uk":"Відповіді, зазначені в пунктах 2, 3."}],"c":0,"pic":["img/hsc/45-3-1.jpg"]},{"id":"h45-4","t":"h45","num":"45.4","q":{"uk":"Що з переліченого нижче відповідає терміну «видимість у напрямку руху»?"},"a":[{"uk":"Мінімальна відстань, на якій з місця водія можна побачити «стоп-лінію»."},{"uk":"Максимальна відстань вправо від напрямку руху, на якому можна розпізнати транспортні засоби, що наближаються до перехрестя по головній дорозі."},{"uk":"Максимальна відстань, на якій з місця водія можна чітко розпізнати межі елементів дороги та розміщення учасників руху, що дає змогу водієві орієнтуватися під час керування транспортним засобом."}],"c":2},{"id":"h45-5","t":"h45","num":"45.5","q":{"uk":"За наявності якої несправності дозволяється експлуатація транспортного засобу?"},"a":[{"uk":"Не працюють запори горловин паливних баків."},{"uk":"Не працює механізм регулювання сидіння водія."},{"uk":"Не працює пристрій для обігрівання та обдування скла."},{"uk":"Не працює склопідйомник."}],"c":3},{"id":"h45-6","t":"h45","num":"45.6","q":{"uk":"Яку максимальну кількість пасажирів Ви, як водій з категорією В, маєте право перевозити?"},"a":[{"uk":"Не більше 9, не враховуючи місце водія."},{"uk":"Не більше 9 з урахуванням місця водія."},{"uk":"Не більше 7."},{"uk":"Не більше 5."}],"c":1},{"id":"h45-7","t":"h45","num":"45.7","q":{"uk":"У якому випадку дозволяється експлуатація транспортного засобу?"},"a":[{"uk":"Порушено регулювання фар."},{"uk":"На світлових приладах використовуються розсіювачі, що не відповідають типу конкретного світлового приладу."},{"uk":"Відсутні протитуманні фари."}],"c":2},{"id":"h45-8","t":"h45","num":"45.8","q":{"uk":"Ви маєте право експлуатувати легковий автомобіль за відсутності:"},"a":[{"uk":"Аптечки."},{"uk":"Вогнегасника."},{"uk":"Знака аварійної зупинки."},{"uk":"Противідкатних упорів."}],"c":3},{"id":"h45-9","t":"h45","num":"45.9","q":{"uk":"У разі виникнення якої несправності заборонено подальший рух навіть до місця ремонту або стоянки?"},"a":[{"uk":"Несправна робоча гальмова система не дає змоги водієві зупинити транспортний засіб при русі навіть з мінімальною швидкістю."},{"uk":"Несправна система випуску відпрацьованих газів."},{"uk":"Не працює склоочисник."}],"c":0},{"id":"h45-10","t":"h45","num":"45.10","q":{"uk":"Для чого здійснюють балансування коліс?"},"a":[{"uk":"Для запобігання биттю колеса під час руху."},{"uk":"Для зменшення витрати палива."},{"uk":"Для покращення аеродинамічних показників автомобіля."}],"c":0},{"id":"h45-11","t":"h45","num":"45.11","q":{"uk":"На автомобілі з автоматичною коробкою передач щоб зняти автомобіль з позиції P необхідно натиснути педаль гальма:"},"a":[{"uk":"Так, неможливо зняти не натиснувши на педаль гальма."},{"uk":"Не потрібно натискати, достатньо переключити у необхідне положення."}],"c":0,"pic":["img/hsc/45-11-1.jpg"]},{"id":"h45-12","t":"h45","num":"45.12","q":{"uk":"Під час руху на автомобілі загорівся попереджувальний індикатор № 4, це означає:"},"a":[{"uk":"Несправність акумулятора."},{"uk":"Падіння рівня моторного масла."},{"uk":"Несправність гальмової системи."},{"uk":"Високу температуру теплоносія."}],"c":0,"pic":["img/hsc/45-12-1.jpg"]},{"id":"h45-13","t":"h45","num":"45.13","q":{"uk":"Під час руху на автомобілі загорівся попереджувальний індикатор № 1, це означає:"},"a":[{"uk":"Несправність акумулятора."},{"uk":"Падіння тиску в системі змащування або низький рівень масла."},{"uk":"Несправність гальмової системи."},{"uk":"Високу температуру теплоносія."}],"c":1,"pic":["img/hsc/45-13-1.jpg"]},{"id":"h45-14","t":"h45","num":"45.14","q":{"uk":"Виберіть індикатор, що відображає увімкнення ближнього світла фар:"},"a":[{"uk":"А."},{"uk":"В."},{"uk":"С."},{"uk":"D."}],"c":3,"pic":["img/hsc/45-14-1.jpg"]},{"id":"h45-15","t":"h45","num":"45.15","q":{"uk":"Що означає наведений індикатор червоного кольору:"},"a":[{"uk":"Падіння тиску в системі змащування або низький рівень масла."},{"uk":"Індикатор стоянкового гальма."},{"uk":"Відсутність палива у паливному баку."}],"c":0,"pic":["img/hsc/45-15-1.jpg"]},{"id":"h45-16","t":"h45","num":"45.16","q":{"uk":"Наведений індикатор червоного кольору інформує про:"},"a":[{"uk":"Відчинені двері автомобіля."},{"uk":"Блокування дверей автомобіля."},{"uk":"Відчинені двері багажника."}],"c":0,"pic":["img/hsc/45-16-1.jpg"]},{"id":"h45-17","t":"h45","num":"45.17","q":{"uk":"Спалах зображеного індикатора жовтого кольору інформує водія транспортного засобу про:"},"a":[{"uk":"Низький рівень палива у паливному баку."},{"uk":"Повний паливний бак."},{"uk":"Непрацюючий ремінь безпеки."}],"c":0,"pic":["img/hsc/45-17-1.jpg"]},{"id":"h45-18","t":"h45","num":"45.18","q":{"uk":"Індикатор у вигляді двох миготливих стрілок зеленого кольору відображає:"},"a":[{"uk":"Увімкнену аварійну світлову сигналізацію."},{"uk":"Незакриті передні двері автомобіля."},{"uk":"Увімкнені склоочисники."}],"c":0,"pic":["img/hsc/45-18-1.jpg"]},{"id":"h45-19","t":"h45","num":"45.19","q":{"uk":"Який з наведених індикаторів стає активним при запуску двигуна автомобіля та горить до тих пір, поки ремінь безпеки не буде пристебнутий?"},"a":[{"uk":"1."},{"uk":"2."},{"uk":"3."},{"uk":"4."}],"c":2,"pic":["img/hsc/45-19-1.jpg"]},{"id":"h45-20","t":"h45","num":"45.20","q":{"uk":"Про що може інформувати водія транспортного засобу спалах зображеного індикатора червоного кольору?"},"a":[{"uk":"Про можливі проблеми з гальмовою системою або увімкнута стоянкова гальмова система."},{"uk":"Увімкнена аварійна сигналізація."},{"uk":"Низький рівень палива у паливному баку."}],"c":0,"pic":["img/hsc/45-20-1.jpg"]},{"id":"h45-21","t":"h45","num":"45.21","q":{"uk":"Цей індикатор вказує що в автомобілі ввімкнені:"},"a":[{"uk":"Протитуманні фари."},{"uk":"Ближнє світло фар."},{"uk":"Аварійна світлова сигналізація."}],"c":0,"pic":["img/hsc/45-21-1.jpg"]},{"id":"h45-22","t":"h45","num":"45.22","q":{"uk":"Цей індикатор жовтого кольору вказує на низький рівень тиску в шинах?"},"a":[{"uk":"Так."},{"uk":"Ні."}],"c":0,"pic":["img/hsc/45-22-1.jpg"]},{"id":"h45-23","t":"h45","num":"45.23","q":{"uk":"Про що інформує водія вказаний індикатор червоного кольору?"},"a":[{"uk":"Про необхідність пристебнутися."},{"uk":"Про неправильно відрегульоване сидіння водія."},{"uk":"Про несправність гальмової системи."}],"c":0,"pic":["img/hsc/45-23-1.jpg"]},{"id":"h45-24","t":"h45","num":"45.24","q":{"uk":"Вказаний індикатор червоного кольору інформує водія про:"},"a":[{"uk":"Відчинені двері автомобіля."},{"uk":"Відчинений багажник автомобіля."}],"c":1,"pic":["img/hsc/45-24-1.jpg"]},{"id":"h45-25","t":"h45","num":"45.25","q":{"uk":"Вказаний індикатор жовтого кольору інформує Вас про:"},"a":[{"uk":"Несправність антиблокувальної системи автомобіля."},{"uk":"Несправність гальмівної системи."},{"uk":"Несправність керма."}],"c":0,"pic":["img/hsc/45-25-1.jpg"]},{"id":"h45-26","t":"h45","num":"45.26","q":{"uk":"Виберіть індикатор, що інформує водія про увімкнене дальнє світло фар:"},"a":[{"uk":"Індикатор блакитного кольору."},{"uk":"Індикатор зеленого кольору."}],"c":0,"pic":["img/hsc/45-26-1.jpg"]},{"id":"h45-27","t":"h45","num":"45.27","q":{"uk":"Виберіть індикатор, що інформує водія про увімкнене ближнє світло фар:"},"a":[{"uk":"Індикатор блакитного кольору."},{"uk":"Індикатор зеленого кольору."}],"c":1,"pic":["img/hsc/45-27-1.jpg"]},{"id":"h45-28","t":"h45","num":"45.28","q":{"uk":"Наведений індикатор червоного кольору може інформувати водія про:"},"a":[{"uk":"Перегрів двигуна."},{"uk":"Низький рівень гальмової рідини."},{"uk":"Низький рівень палива у паливному баку."}],"c":0,"pic":["img/hsc/45-28-1.jpg"]},{"id":"h45-29","t":"h45","num":"45.29","q":{"uk":"Який із наведених індикаторів інформує водія транспортного засобу про можливі проблеми з гальмовою системою?"},"a":[{"uk":"1."},{"uk":"1 і 4."},{"uk":"2."},{"uk":"3."},{"uk":"4."}],"c":0,"pic":["img/hsc/45-29-1.jpg"]},{"id":"h45-30","t":"h45","num":"45.30","q":{"uk":"Який із наведених індикаторів інформує водія транспортного засобу про низький рівень палива у паливному баку?"},"a":[{"uk":"1."},{"uk":"2."},{"uk":"3."},{"uk":"4."}],"c":1,"pic":["img/hsc/45-30-1.jpg"]},{"id":"h45-31","t":"h45","num":"45.31","q":{"uk":"Який із наведених індикаторів вмикається при запуску двигуна та інформує водія транспортного засобу про неправильно зачинені двері?"},"a":[{"uk":"1."},{"uk":"2."},{"uk":"3."},{"uk":"4."}],"c":2,"pic":["img/hsc/45-31-1.jpg"]},{"id":"h45-32","t":"h45","num":"45.32","q":{"uk":"Який із наведених індикаторів попереджає водія транспортного засобу про перегрів двигуна?"},"a":[{"uk":"1."},{"uk":"2."},{"uk":"3."},{"uk":"4."}],"c":3,"pic":["img/hsc/45-32-1.jpg"]},{"id":"h45-33","t":"h45","num":"45.33","q":{"uk":"Цей індикатор вказує, що в автомобілі увімкнено:"},"a":[{"uk":"Протитуманні фари."},{"uk":"Ближнє світло фар."},{"uk":"Дальнє світло фар."}],"c":2,"pic":["img/hsc/45-33-1.jpg"]},{"id":"h46-1","t":"h46","num":"46.1","q":{"uk":"В яких випадках водій має право відступати від вимог законодавства?","ru":"В каких случаях водитель имеет право отступать от требований законодательства?"},"a":[{"uk":"В умовах дії непереборної сили.","ru":"В условиях действия непреодолимой силы.","w":{"uk":"Непереборна сила — лише одна з двох підстав, названих у {p:2.14}.","ru":"Непреодолимая сила — лишь одно из двух оснований, названных в {p:2.14}."}},{"uk":"Коли іншими засобами неможливо запобігти власній загибелі чи каліцтву громадян.","ru":"Когда другими средствами невозможно предотвратить собственную гибель или увечье граждан.","w":{"uk":"Загроза загибелі чи каліцтва — лише одна з двох підстав, названих у {p:2.14}.","ru":"Угроза гибели или увечья — лишь одно из двух оснований, названных в {p:2.14}."}},{"uk":"У випадках, зазначених в пунктах 1 та/або 2.","ru":"В случаях, указанных в пунктах 1 и/или 2."}],"c":2,"e":{"uk":"Водій має право відступати від вимог законодавства **в умовах дії непереборної сили** або **коли іншими засобами неможливо запобігти власній загибелі чи каліцтву громадян** ({p:2.14}) — тобто в обох названих випадках.","ru":"Водитель имеет право отступать от требований законодательства **в условиях действия непреодолимой силы** или **когда другими средствами невозможно предотвратить собственную гибель или увечье граждан** ({p:2.14}) — то есть в обоих названных случаях."},"ref":["2.14"]},{"id":"h46-2","t":"h46","num":"46.2","q":{"uk":"Яка необхідна умова при огляді на предмет алкогольного сп’яніння водія на місці зупинки транспортного засобу?","ru":"Какое необходимое условие при осмотре на предмет алкогольного опьянения водителя на месте остановки транспортного средства?"},"a":[{"uk":"Присутність двох свідків та поліцейського.","ru":"Присутствие двух свидетелей и полицейского.","w":{"uk":"Поліцейський сам проводить огляд, тож його присутність не є окремою умовою — закон вимагає саме двох свідків.","ru":"Полицейский сам проводит осмотр, поэтому его присутствие не является отдельным условием — закон требует именно двух свидетелей."}},{"uk":"Присутність двох свідків.","ru":"Присутствие двух свидетелей."},{"uk":"Присутність одного понятого.","ru":"Присутствие одного понятого.","w":{"uk":"Поняті потрібні для огляду речей чи транспортного засобу, а для огляду на стан сп'яніння — двоє свідків.","ru":"Понятые нужны для осмотра вещей или транспортного средства, а для осмотра на состояние опьянения — двое свидетелей."}},{"uk":"Присутність щонайменше двох поліцейських.","ru":"Присутствие как минимум двух полицейских.","w":{"uk":"Кількість поліцейських не має значення: умовою є присутність двох свідків.","ru":"Количество полицейских значения не имеет: условием является присутствие двух свидетелей."}}],"c":1,"e":{"uk":"Водій зобов'язаний пройти огляд на стан сп'яніння на вимогу поліцейського ({p:2.5}); на місці зупинки його проводить поліцейський за допомогою спеціальних технічних засобів **у присутності двох свідків** (ст. 266 КУпАП та інструкція МВС і МОЗ щодо огляду на стан сп'яніння).","ru":"Водитель обязан пройти осмотр на состояние опьянения по требованию полицейского ({p:2.5}); на месте остановки его проводит полицейский с помощью специальных технических средств **в присутствии двух свидетелей** (ст. 266 КУоАП и инструкция МВД и Минздрава об осмотре на состояние опьянения)."},"ref":["2.5"]},{"id":"h46-3","t":"h46","num":"46.3","q":{"uk":"При огляді Вашого автомобіля необхідною умовою є:","ru":"При осмотре вашего автомобиля необходимым условием является:"},"a":[{"uk":"Присутність щонайменше двох свідків та двох поліцейських.","ru":"Присутствие как минимум двух свидетелей и двух полицейских.","w":{"uk":"Свідки залучаються до огляду на стан сп'яніння, а для огляду автомобіля потрібні двоє понятих.","ru":"Свидетели привлекаются к осмотру на состояние опьянения, а для осмотра автомобиля нужны двое понятых."}},{"uk":"Присутність одного понятого та двох поліцейських.","ru":"Присутствие одного понятого и двух полицейских.","w":{"uk":"Одного понятого недостатньо: закон вимагає двох.","ru":"Одного понятого недостаточно: закон требует двух."}},{"uk":"Присутність двох понятих.","ru":"Присутствие двух понятых."},{"uk":"Присутність щонайменше двох поліцейських.","ru":"Присутствие как минимум двух полицейских.","w":{"uk":"Присутність поліцейських не замінює понятих: огляд проводять за участі двох понятих.","ru":"Присутствие полицейских не заменяет понятых: осмотр проводят с участием двух понятых."}}],"c":2,"e":{"uk":"Водій повинен дати можливість оглянути транспортний засіб відповідно до законодавства ({p:2.4}), а за КУпАП такий огляд проводять **у присутності двох понятих**.","ru":"Водитель должен дать возможность осмотреть транспортное средство в соответствии с законодательством ({p:2.4}), а по КУоАП такой осмотр проводят **в присутствии двух понятых**."},"ref":["2.4"]},{"id":"h46-4","t":"h46","num":"46.4","q":{"uk":"При особистому огляді і огляді речей необхідною умовою є:","ru":"При личном досмотре и досмотре вещей необходимым условием является:"},"a":[{"uk":"Присутність двох понятих.","ru":"Присутствие двух понятых."},{"uk":"Присутність щонайменше двох свідків.","ru":"Присутствие как минимум двух свидетелей.","w":{"uk":"Свідки залучаються до огляду на стан сп'яніння, а під час особистого огляду потрібні саме поняті.","ru":"Свидетели привлекаются к осмотру на состояние опьянения, а при личном досмотре нужны именно понятые."}},{"uk":"Присутність одного понятого.","ru":"Присутствие одного понятого.","w":{"uk":"Одного понятого недостатньо: закон вимагає двох.","ru":"Одного понятого недостаточно: закон требует двух."}},{"uk":"Присутність щонайменше двох поліцейських.","ru":"Присутствие как минимум двух полицейских.","w":{"uk":"Присутність поліцейських не замінює понятих.","ru":"Присутствие полицейских не заменяет понятых."}}],"c":0,"e":{"uk":"Особистий огляд і огляд речей проводять **у присутності двох понятих** (ст. 264 КУпАП); особистий огляд — до того ж особою й понятими однієї статі з оглядуваним.","ru":"Личный досмотр и досмотр вещей проводят **в присутствии двух понятых** (ст. 264 КУоАП); личный досмотр — к тому же лицом и понятыми одного пола с досматриваемым."}},{"id":"h46-5","t":"h46","num":"46.5","q":{"uk":"За які правопорушення Вас може бути позбавлено права керування транспортним засобом?","ru":"За какие правонарушения вас могут лишить права управления транспортным средством?"},"a":[{"uk":"За керування транспортним засобом в стані алкогольного, наркотичного чи іншого сп'яніння.","ru":"За управление транспортным средством в состоянии алкогольного, наркотического или иного опьянения.","w":{"uk":"Керування в стані сп'яніння — підстава для позбавлення права, але не єдина з перелічених.","ru":"Управление в состоянии опьянения — основание для лишения права, но не единственное из перечисленных."}},{"uk":"За в'їзд на залізничний переїзд у випадках, коли рух через переїзд заборонений.","ru":"За въезд на железнодорожный переезд в случаях, когда движение через переезд запрещено.","w":{"uk":"В'їзд на закритий переїзд — підстава для позбавлення права, але не єдина з перелічених.","ru":"Въезд на закрытый переезд — основание для лишения права, но не единственное из перечисленных."}},{"uk":"За порушення правил дорожнього руху, що спричинило пошкодження транспортних засобів, вантажу, автомобільних доріг, вулиць, залізничних переїздів, дорожніх споруд чи іншого майна.","ru":"За нарушение правил дорожного движения, повлёкшее повреждение транспортных средств, груза, автомобильных дорог, улиц, железнодорожных переездов, дорожных сооружений или иного имущества.","w":{"uk":"Порушення, що спричинило пошкодження майна, — підстава для позбавлення права, але не єдина з перелічених.","ru":"Нарушение, повлёкшее повреждение имущества, — основание для лишения права, но не единственное из перечисленных."}},{"uk":"За керування транспортним засобом, не зареєстрованим або не перереєстрованим в установленому порядку.","ru":"За управление транспортным средством, не зарегистрированным или не перерегистрированным в установленном порядке.","w":{"uk":"За керування незареєстрованим транспортним засобом передбачено штраф, а не позбавлення права керування.","ru":"За управление незарегистрированным транспортным средством предусмотрен штраф, а не лишение права управления."}},{"uk":"Відповіді 1,2,3.","ru":"Ответы 1, 2, 3."}],"c":4,"e":{"uk":"Позбавлення права керування КУпАП передбачає, зокрема, за **керування в стані сп'яніння** (ст. 130), **в'їзд на переїзд, коли рух через нього заборонений** (ст. 123) і **порушення ПДР, що спричинило пошкодження майна** (ст. 124) — тобто за порушення з відповідей 1, 2, 3.","ru":"Лишение права управления КУоАП предусматривает, в частности, за **управление в состоянии опьянения** (ст. 130), **въезд на переезд, когда движение через него запрещено** (ст. 123) и **нарушение ПДД, повлёкшее повреждение имущества** (ст. 124) — то есть за нарушения из ответов 1, 2, 3."},"ref":["1.9"]},{"id":"h46-6","t":"h46","num":"46.6","q":{"uk":"За які правопорушення Вас можуть позбавити права керування:","ru":"За какие правонарушения вас могут лишить права управления:"},"a":[{"uk":"За перевищення швидкості більш ніж на 20 км/год.","ru":"За превышение скорости более чем на 20 км/ч.","w":{"uk":"За перевищення швидкості понад 20 км/год накладається штраф (ст. 122 КУпАП), а не позбавлення права керування.","ru":"За превышение скорости более чем на 20 км/ч налагается штраф (ст. 122 КУоАП), а не лишение права управления."}},{"uk":"За керування транспортним засобом, не зареєстрованим або не перереєстрованим в установленому порядку.","ru":"За управление транспортным средством, не зарегистрированным или не перерегистрированным в установленном порядке.","w":{"uk":"За керування незареєстрованим транспортним засобом передбачено штраф, а не позбавлення права керування.","ru":"За управление незарегистрированным транспортным средством предусмотрен штраф, а не лишение права управления."}},{"uk":"За порушення вимог дорожніх знаків та розмітки.","ru":"За нарушение требований дорожных знаков и разметки.","w":{"uk":"За порушення вимог знаків і розмітки накладається штраф (ст. 122 КУпАП), а не позбавлення права керування.","ru":"За нарушение требований знаков и разметки налагается штраф (ст. 122 КУоАП), а не лишение права управления."}},{"uk":"За в'їзд на залізничний переїзд у випадках, коли рух через переїзд заборонений.","ru":"За въезд на железнодорожный переезд в случаях, когда движение через переезд запрещено."}],"c":3,"e":{"uk":"Серед перелічених порушень позбавлення права керування КУпАП передбачає лише за **в'їзд на залізничний переїзд, коли рух через нього заборонено** (ст. 123); за решту накладається штраф.","ru":"Среди перечисленных нарушений лишение права управления КУоАП предусматривает только за **въезд на железнодорожный переезд, когда движение через него запрещено** (ст. 123); за остальные налагается штраф."},"ref":["1.9"]},{"id":"h46-7","t":"h46","num":"46.7","q":{"uk":"Адміністративне затримання Національною поліцією проводиться:","ru":"Административное задержание Национальной полицией проводится:"},"a":[{"uk":"Тільки в разі вчинення дрібного хуліганства.","ru":"Только в случае совершения мелкого хулиганства.","w":{"uk":"Слово «тільки» хибне: затримання можливе й за деякі порушення у сфері дорожнього руху.","ru":"Слово «только» ошибочно: задержание возможно и за некоторые нарушения в сфере дорожного движения."}},{"uk":"Тільки в разі порушення Правил дорожнього руху.","ru":"Только в случае нарушения Правил дорожного движения.","w":{"uk":"Слово «тільки» хибне: затримання можливе й за дрібне хуліганство.","ru":"Слово «только» ошибочно: задержание возможно и за мелкое хулиганство."}},{"uk":"Проводиться в разі вчинення правопорушень, зазначених у відповідях 1 і 2 з обов'язковим складанням протоколу про затримання.","ru":"Проводится в случае совершения правонарушений, указанных в ответах 1 и 2, с обязательным составлением протокола о задержании."}],"c":2,"e":{"uk":"КУпАП дозволяє Національній поліції адміністративне затримання як за дрібне хуліганство, так і за окремі порушення у сфері дорожнього руху, а про затримання **обов'язково складається протокол** (ст. 261 КУпАП).","ru":"КУоАП разрешает Национальной полиции административное задержание как за мелкое хулиганство, так и за отдельные нарушения в сфере дорожного движения, а о задержании **обязательно составляется протокол** (ст. 261 КУоАП)."}},{"id":"h46-8","t":"h46","num":"46.8","q":{"uk":"Передача керування транспортним засобом особі, яка не має права керування даним транспортним засобом, тягне за собою:","ru":"Передача управления транспортным средством лицу, которое не имеет права управления данным транспортным средством, влечёт за собой:"},"a":[{"uk":"Адміністративну відповідальність.","ru":"Административную ответственность."},{"uk":"Кримінальну відповідальність.","ru":"Уголовную ответственность.","w":{"uk":"Саме по собі це порушення не є злочином, тому кримінальна відповідальність за нього не настає.","ru":"Само по себе это нарушение не является преступлением, поэтому уголовная ответственность за него не наступает."}},{"uk":"Безоплатне вилучення транспортного засобу.","ru":"Безвозмездное изъятие транспортного средства.","w":{"uk":"Безоплатного вилучення транспортного засобу за це порушення закон не передбачає.","ru":"Безвозмездного изъятия транспортного средства за это нарушение закон не предусматривает."}},{"uk":"Повторний медичний огляд.","ru":"Повторный медицинский осмотр.","w":{"uk":"Повторний медичний огляд — не вид відповідальності й не є наслідком цього порушення.","ru":"Повторный медицинский осмотр — не вид ответственности и не является последствием этого нарушения."}}],"c":0,"e":{"uk":"Передавати керування особі, яка не має посвідчення на право керування, заборонено ({p:2.9}); за це настає **адміністративна відповідальність** (ст. 126 КУпАП).","ru":"Передавать управление лицу, не имеющему удостоверения на право управления, запрещено ({p:2.9}); за это наступает **административная ответственность** (ст. 126 КУоАП)."},"ref":["2.9"]},{"id":"h46-9","t":"h46","num":"46.9","q":{"uk":"Ким проводиться огляд на стан сп’яніння?","ru":"Кем проводится осмотр на состояние опьянения?"},"a":[{"uk":"Будь-яким лікарем.","ru":"Любым врачом.","w":{"uk":"Проводити такий огляд може не будь-який лікар, а лише лікар закладу охорони здоров'я, який має на це право.","ru":"Проводить такой осмотр может не любой врач, а лишь врач учреждения здравоохранения, имеющий на это право."}},{"uk":"Поліцейським на місці зупинки транспортного засобу в присутності двох свідків.","ru":"Полицейским на месте остановки транспортного средства в присутствии двух свидетелей.","w":{"uk":"Поліцейський справді може провести огляд, але його також проводить лікар закладу охорони здоров'я.","ru":"Полицейский действительно может провести осмотр, но его также проводит врач учреждения здравоохранения."}},{"uk":"Лікарем закладу охорони здоров’я, який має право на проведення такого огляду.","ru":"Врачом учреждения здравоохранения, который имеет право на проведение такого осмотра.","w":{"uk":"Лікар закладу охорони здоров'я справді проводить огляд, але й поліцейський на місці зупинки — теж.","ru":"Врач учреждения здравоохранения действительно проводит осмотр, но и полицейский на месте остановки — тоже."}},{"uk":"Відповіді 1,2,3.","ru":"Ответы 1, 2, 3.","w":{"uk":"Варіант включає «будь-якого лікаря», а це неправильно.","ru":"Вариант включает «любого врача», а это неверно."}},{"uk":"Відповіді 2 і 3.","ru":"Ответы 2 и 3."}],"c":4,"e":{"uk":"Огляд на стан сп'яніння ({p:2.5}) проводить **поліцейський** на місці зупинки за допомогою спеціальних технічних засобів у присутності двох свідків або — у разі незгоди водія чи за потреби — **лікар закладу охорони здоров'я**, який має право на такий огляд.","ru":"Осмотр на состояние опьянения ({p:2.5}) проводит **полицейский** на месте остановки с помощью специальных технических средств в присутствии двух свидетелей или — при несогласии водителя либо при необходимости — **врач учреждения здравоохранения**, имеющий право на такой осмотр."},"ref":["2.5"]},{"id":"h47-1","t":"h47","num":"47.1","q":{"uk":"Щоб мати змогу постійно контролювати рух транспортного засобу та безпечно керувати ним, водій повинен:","ru":"Чтобы иметь возможность постоянно контролировать движение транспортного средства и безопасно управлять им, водитель должен:"},"a":[{"uk":"Дотримуватися безпечної дистанції та інтервалу.","ru":"Соблюдать безопасную дистанцию и интервал.","w":{"uk":"Безпечна дистанція потрібна, але не менш важливі швидкість і ремені безпеки.","ru":"Безопасная дистанция нужна, но не менее важны скорость и ремни безопасности."}},{"uk":"Бути пристебнутим і не перевозити пасажирів, не пристебнутих ременями безпеки.","ru":"Быть пристёгнутым и не перевозить пассажиров, не пристёгнутых ремнями безопасности.","w":{"uk":"Ремені безпеки обов'язкові ({p:2.3}), але без безпечної швидкості й дистанції цього недостатньо.","ru":"Ремни безопасности обязательны ({p:2.3}), но без безопасной скорости и дистанции этого недостаточно."}},{"uk":"Дотримуватися безпечної швидкості руху.","ru":"Соблюдать безопасную скорость движения.","w":{"uk":"Безпечна швидкість потрібна, але не менш важливі дистанція й ремені безпеки.","ru":"Безопасная скорость нужна, но не менее важны дистанция и ремни безопасности."}},{"uk":"Відповіді 1, 2 і 3.","ru":"Ответы 1, 2 и 3."},{"uk":"Відповіді 1 і 3.","ru":"Ответы 1 и 3.","w":{"uk":"Варіант пропускає обов'язок бути пристебнутим і не перевозити непристебнутих пасажирів ({p:2.3}).","ru":"Вариант пропускает обязанность быть пристёгнутым и не перевозить непристёгнутых пассажиров ({p:2.3})."}}],"c":3,"e":{"uk":"Контроль над рухом і безпеку забезпечують **безпечна швидкість** ({p:12.1}), **безпечні дистанція та інтервал** ({p:13.1}) і **пристебнуті ремені безпеки** водія й пасажирів ({p:2.3}) — тож потрібне все перелічене.","ru":"Контроль над движением и безопасность обеспечивают **безопасная скорость** ({p:12.1}), **безопасные дистанция и интервал** ({p:13.1}) и **пристёгнутые ремни безопасности** водителя и пассажиров ({p:2.3}) — поэтому нужно всё перечисленное."},"ref":["12.1","13.1","2.3"]},{"id":"h47-2","t":"h47","num":"47.2","q":{"uk":"При русі в щільному потоці Ви помітили ззаду транспортний засіб, що рухається на занадто малій дистанції. Як слід вчинити, щоб забезпечити безпеку руху?","ru":"При движении в плотном потоке вы заметили сзади транспортное средство, движущееся на слишком малой дистанции. Как следует поступить, чтобы обеспечить безопасность движения?"},"a":[{"uk":"Збільшити швидкість руху, зменшивши дистанцію до транспортного засобу, що рухається попереду Вас.","ru":"Увеличить скорость движения, сократив дистанцию до транспортного средства, движущегося впереди вас.","w":{"uk":"Скорочуючи дистанцію попереду, водій порушує вимогу безпечної дистанції ({p:13.1}) і ризикує зіткнутися з обома сусідами.","ru":"Сокращая дистанцию впереди, водитель нарушает требование безопасной дистанции ({p:13.1}) и рискует столкнуться с обоими соседями."}},{"uk":"Попередити наступного ззаду водія різким короткочасним гальмуванням.","ru":"Предупредить следующего сзади водителя резким кратковременным торможением.","w":{"uk":"Різке гальмування заборонене, якщо воно не потрібне для запобігання ДТП ({p:12.9}), — тут воно саме спровокує зіткнення.","ru":"Резкое торможение запрещено, если оно не нужно для предотвращения ДТП ({p:12.9}), — здесь оно само спровоцирует столкновение."}},{"uk":"Скорегувати швидкість руху, послабивши натискання на педаль газу, щоб збільшити дистанцію до транспортного засобу, що рухається попереду.","ru":"Скорректировать скорость движения, ослабив нажатие на педаль газа, чтобы увеличить дистанцию до транспортного средства, движущегося впереди."},{"uk":"Допускається будь-яка з перерахованих вище дій.","ru":"Допускается любое из перечисленных выше действий.","w":{"uk":"Дії 1 і 2 небезпечні, тож прийнятна лише відповідь 3.","ru":"Действия 1 и 2 опасны, поэтому приемлем только ответ 3."}}],"c":2,"e":{"uk":"Якщо ззаду їдуть надто близько, треба **збільшити дистанцію попереду**, плавно відпустивши педаль газу: тоді за потреби можна гальмувати м'якше, і водієві позаду вистачить часу зреагувати.","ru":"Если сзади едут слишком близко, нужно **увеличить дистанцию впереди**, плавно отпустив педаль газа: тогда при необходимости можно тормозить мягче, и водителю сзади хватит времени отреагировать."},"ref":["13.1","12.9"]},{"id":"h47-3","t":"h47","num":"47.3","q":{"uk":"Що необхідно зробити перед відкриттям капота, якщо з-під нього йде дим?","ru":"Что необходимо сделать перед открытием капота, если из-под него идёт дым?"},"a":[{"uk":"Вимкнути двигун і дистанційний вимикач «маси» (при його наявності).","ru":"Выключить двигатель и дистанционный выключатель «массы» (при его наличии).","w":{"uk":"Вимкнути двигун і «масу» потрібно, але це лише одна з трьох необхідних дій.","ru":"Выключить двигатель и «массу» нужно, но это лишь одно из трёх необходимых действий."}},{"uk":"Дістати вогнегасник і підготувати його до використання.","ru":"Достать огнетушитель и подготовить его к использованию.","w":{"uk":"Вогнегасник потрібно підготувати, але це лише одна з трьох необхідних дій.","ru":"Огнетушитель нужно подготовить, но это лишь одно из трёх необходимых действий."}},{"uk":"Захистити руки від опіку, надівши рукавички або обернувши пальці ганчір'ям.","ru":"Защитить руки от ожога, надев перчатки или обернув пальцы ветошью.","w":{"uk":"Захистити руки потрібно, але це лише одна з трьох необхідних дій.","ru":"Защитить руки нужно, но это лишь одно из трёх необходимых действий."}},{"uk":"Все перераховане.","ru":"Всё перечисленное."}],"c":3,"e":{"uk":"Перед тим як відкрити капот, з-під якого йде дим, треба **знеструмити** авто (вимкнути двигун і «масу»), **підготувати вогнегасник** — з припливом повітря полум'я може спалахнути — і **захистити руки** від гарячих деталей.","ru":"Прежде чем открыть капот, из-под которого идёт дым, нужно **обесточить** авто (выключить двигатель и «массу»), **подготовить огнетушитель** — с притоком воздуха пламя может вспыхнуть — и **защитить руки** от горячих деталей."}},{"id":"h47-4","t":"h47","num":"47.4","q":{"uk":"У транспортному потоці найбезпечніше рухатися зі швидкістю:","ru":"В транспортном потоке безопаснее всего двигаться со скоростью:"},"a":[{"uk":"Нижче швидкості транспортного потоку.","ru":"Ниже скорости транспортного потока.","w":{"uk":"Повільніший автомобіль змушує інших гальмувати й обганяти його, а без потреби рухатися надто повільно заборонено ({p:12.9}).","ru":"Более медленный автомобиль заставляет других тормозить и обгонять его, а без необходимости двигаться слишком медленно запрещено ({p:12.9})."}},{"uk":"Вище швидкості транспортного потоку.","ru":"Выше скорости транспортного потока.","w":{"uk":"Рух швидше за потік вимагає частих перестроювань і обгонів, а це збільшує ризик ДТП.","ru":"Движение быстрее потока требует частых перестроений и обгонов, а это увеличивает риск ДТП."}},{"uk":"Рівній швидкості транспортного потоку.","ru":"Равной скорости транспортного потока."}],"c":2,"e":{"uk":"Коли рухаєшся **зі швидкістю потоку**, інші транспортні засоби не наздоганяють тебе і не доводиться їх постійно обганяти, тож менше маневрів і конфліктних ситуацій.","ru":"Когда движешься **со скоростью потока**, другие транспортные средства не догоняют тебя и не приходится постоянно их обгонять, поэтому меньше манёвров и конфликтных ситуаций."}},{"id":"h47-5","t":"h47","num":"47.5","q":{"uk":"Як найбезпечніше проїхати перехрестя, якщо при наближенні до нього Ви бачите зелений миготливий сигнал світлофора?","ru":"Как безопаснее всего проехать перекрёсток, если при приближении к нему вы видите зелёный мигающий сигнал светофора?"},"a":[{"uk":"Збільшити швидкість, щоб встигнути проїхати перехрестя до ввімкнення заборонного сигналу світлофора.","ru":"Увеличить скорость, чтобы успеть проехать перекрёсток до включения запрещающего сигнала светофора.","w":{"uk":"Розганяючись, водій ризикує виїхати на перехрестя на жовтий чи червоний сигнал і зіткнутися з транспортом, що почав рух.","ru":"Разгоняясь, водитель рискует выехать на перекрёсток на жёлтый или красный сигнал и столкнуться с транспортом, начавшим движение."}},{"uk":"Не змінювати швидкість руху, а якщо до ввімкнення червоного сигналу проїхати перехрестя не вдасться - загальмувати перед «стоп-лінією».","ru":"Не менять скорость движения, а если до включения красного сигнала проехать перекрёсток не удастся — затормозить перед «стоп-линией».","w":{"uk":"Без завчасного зниження швидкості зупинитися перед стоп-лінією можна буде лише різким гальмуванням, а це небезпечно ({p:12.9}).","ru":"Без заблаговременного снижения скорости остановиться перед стоп-линией можно будет лишь резким торможением, а это опасно ({p:12.9})."}},{"uk":"Завчасно знизити швидкість, щоб у разі потреби зупинитися перед «стоп-лінією» при ввімкненні заборонного сигналу світлофора, не вдаючись до екстреного гальмування.","ru":"Заблаговременно снизить скорость, чтобы при необходимости остановиться перед «стоп-линией» при включении запрещающего сигнала светофора, не прибегая к экстренному торможению."}],"c":2,"e":{"uk":"Зелений миготливий сигнал попереджає, що незабаром увімкнеться заборонний ({p:8.7}), тому найбезпечніше **завчасно знизити швидкість**, щоб за потреби спокійно зупинитися перед стоп-лінією без різкого гальмування.","ru":"Зелёный мигающий сигнал предупреждает, что скоро включится запрещающий ({p:8.7}), поэтому безопаснее всего **заблаговременно снизить скорость**, чтобы при необходимости спокойно остановиться перед стоп-линией без резкого торможения."},"ref":["8.7","12.9"]},{"id":"h47-6","t":"h47","num":"47.6","q":{"uk":"Який з перерахованих нижче факторів не впливає на час реакції водія?","ru":"Какой из перечисленных ниже факторов не влияет на время реакции водителя?"},"a":[{"uk":"Вік.","ru":"Возраст.","w":{"uk":"З віком швидкість реакції змінюється — у літніх водіїв вона зазвичай повільніша.","ru":"С возрастом скорость реакции меняется — у пожилых водителей она обычно медленнее."}},{"uk":"Час доби.","ru":"Время суток.","w":{"uk":"Уночі й рано-вранці людина втомлена й сонлива, тож реагує повільніше.","ru":"Ночью и рано утром человек утомлён и сонлив, поэтому реагирует медленнее."}},{"uk":"Освіта.","ru":"Образование."},{"uk":"Час перебування за кермом.","ru":"Время пребывания за рулём.","w":{"uk":"Чим довше водій за кермом, тим більша втома і тим повільніша реакція.","ru":"Чем дольше водитель за рулём, тем больше утомление и тем медленнее реакция."}},{"uk":"Температура в салоні автомобіля.","ru":"Температура в салоне автомобиля.","w":{"uk":"Спека чи задуха в салоні спричиняють сонливість і погіршують реакцію.","ru":"Жара или духота в салоне вызывают сонливость и ухудшают реакцию."}}],"c":2,"e":{"uk":"Швидкість реакції залежить від фізичного стану водія та умов, а **освіта** на неї не впливає.","ru":"Скорость реакции зависит от физического состояния водителя и условий, а **образование** на неё не влияет."}},{"id":"h47-7","t":"h47","num":"47.7","q":{"uk":"Де найбезпечніше встановлювати дитяче автокрісло в салоні автомобіля?","ru":"Где безопаснее всего устанавливать детское автокресло в салоне автомобиля?"},"a":[{"uk":"На передньому сидінні.","ru":"На переднем сиденье.","w":{"uk":"Переднє сидіння ближче до зони фронтального удару, а подушка безпеки, що спрацювала, може травмувати дитину в автокріслі.","ru":"Переднее сиденье ближе к зоне фронтального удара, а сработавшая подушка безопасности может травмировать ребёнка в автокресле."}},{"uk":"На задньому сидінні.","ru":"На заднем сиденье."}],"c":1,"e":{"uk":"**Заднє сидіння** розташоване далі від зони фронтального удару й від передньої подушки безпеки, тому дитяче автокрісло там найбезпечніше.","ru":"**Заднее сиденье** расположено дальше от зоны фронтального удара и от передней подушки безопасности, поэтому детское автокресло там безопаснее всего."}}]};
